import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { COVERED, FLAG } from './index';
import type { MinesState, MinesUI } from './index';

const border = (t: number) => Math.round(t * 0.35);

const at = (s: MinesState, x: number, y: number) => s.grid[y * s.w + x];
const cell = (x: number, y: number, t: number): TutorialRect => cellRect(x, y, t, border(t));
const centre = (x: number, y: number, t: number) => cellCentre(x, y, t, border(t));

export const tutorial: Tutorial<MinesState, MinesUI> = {
  steps: [
    {
      gameId: '5x5n2:0,0,me2d9bc8',
      text: 'Every number counts the mines in the eight squares touching it. Two mines hide under the covered block; uncover everything else without treading on one.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'This **1** touches only one covered square, so that square is a mine. **Right-click** it to plant a flag.',
      highlight: ({ tileSize }) => [cell(2, 2, tileSize), cell(3, 3, tileSize)],
      pointer: ({ tileSize }) => ({ ...centre(3, 3, tileSize), button: 'right' }),
      waitFor: ({ state }) => at(state, 3, 3) === FLAG,
      placement: 'above',
    },
    {
      text: 'The **1** below it now has its one mine flagged, so the rest of its neighbours are safe. **Left-click that 1** to open them in one go.',
      highlight: ({ tileSize }) => [cell(2, 3, tileSize), cell(3, 4, tileSize)],
      pointer: ({ tileSize }) => centre(2, 3, tileSize),
      waitFor: ({ state }) => at(state, 3, 4) >= 0,
    },
    {
      text: 'The **2** above the block counts one flag already and has a single covered square left. **Right-click** that square.',
      highlight: ({ tileSize }) => [cell(3, 2, tileSize), cell(4, 3, tileSize)],
      pointer: ({ tileSize }) => ({ ...centre(4, 3, tileSize), button: 'right' }),
      waitFor: ({ state }) => at(state, 4, 3) === FLAG,
      placement: 'above',
    },
    {
      text: 'Both mines are flagged, so the last covered square has to be safe. **Left-click** it to finish the grid.',
      highlight: ({ state, tileSize }) => {
        // Whatever is still covered and unflagged — normally just the bottom-right corner.
        const rects: TutorialRect[] = [];
        state.grid.forEach((v, i) => {
          if (v === COVERED) rects.push(cell(i % state.w, Math.floor(i / state.w), tileSize));
        });
        return rects.length ? rects : cell(4, 4, tileSize);
      },
      pointer: ({ tileSize }) => centre(4, 4, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Cleared. A second right-click takes a flag off again, and **Undo** rescues you if you ever tread on a mine.',
      target: '[data-cmd="undo"]',
    },
  ],
};
