import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_UP,
  LEFT_BUTTON,
  stripMods,
} from '../../framework/input';
import { clamp, flashOn, parseWxH } from '../../framework/grid';
import { drawZiggy, ziggyEnabled } from '../../framework/ziggy';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  BLANK,
  DX,
  DY,
  GEM,
  MINE,
  START,
  STOP,
  WALL,
  cellAt,
  generate,
  slide,
  solveRoute,
} from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export interface InertiaParams {
  w: number;
  h: number;
}

export interface InertiaState {
  w: number;
  h: number;
  /** One character per cell: `w` wall, `s` stop, `g` gem, `m` mine, `b` blank. */
  grid: string;
  px: number;
  py: number;
  /** Gems still to collect. */
  gems: number;
  /** The ball has run into a mine; only Undo can help. */
  dead: boolean;
  /** Solve has been used on the way to this state. */
  cheated: boolean;
  /**
   * Every square the ball occupied during the move that produced this state, from the
   * square it set off from to the one it came to rest on. Drives the slide animation.
   */
  trail: number[];
}

export interface InertiaUI {
  /** Fatal moves made by the player (redoing one does not count again). */
  deaths: number;
  justMadeMove: boolean;
  justDied: boolean;
}

/** Seconds per square of travel, plus a little so a one-square hop is visible. */
const ANIM_PER_CELL = 0.028;
const ANIM_BASE = 0.05;
/**
 * Longest a slide may take. A single roll never gets near it (a 40-square run is just over
 * a second), but Solve rolls the ball along its whole route as one move, and on a big board
 * that route is hundreds of squares: at the per-square pace it took the better part of a
 * minute to watch, and as long again to undo.
 */
export const MAX_SLIDE_TIME = 3;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_DIM = 40;

/** Keypad digits and the direction each one means (5 is the centre and does nothing). */
const KEYPAD_DIRS: Record<string, number> = {
  '8': 0,
  '9': 1,
  '6': 2,
  '3': 3,
  '2': 4,
  '1': 5,
  '4': 6,
  '7': 7,
};

function slideTime(steps: number): number {
  return steps <= 0 ? 0 : Math.min(MAX_SLIDE_TIME, ANIM_BASE + ANIM_PER_CELL * steps);
}

/** Octant of a displacement, clockwise from up, matching the direction table. */
export function octant(dx: number, dy: number): number {
  const angle = Math.atan2(dx, -dy) / (Math.PI / 4);
  return ((Math.round(angle) % 8) + 8) % 8;
}

/**
 * Roll the ball through a sequence of directions. Returns null when any step is illegal
 * (a wall straight ahead, or continuing after a fatal step).
 */
function applyRoute(state: InertiaState, dirs: number[]): InertiaState | null {
  if (state.dead || dirs.length === 0) return null;
  const { w, h } = state;
  const cells = state.grid.split('');
  let grid = state.grid;
  let { px, py, gems } = state;
  const trail = [py * w + px];
  let dead = false;
  for (const d of dirs) {
    if (dead) return null;
    const s = slide(w, h, grid, px, py, d);
    if (!s) return null;
    for (const c of s.cells) {
      trail.push(c);
      if (cells[c] === GEM) {
        cells[c] = BLANK;
        gems--;
      }
    }
    grid = cells.join('');
    const last = s.cells[s.cells.length - 1];
    px = last % w;
    py = (last - px) / w;
    dead = s.dead;
  }
  return { ...state, grid, px, py, gems, dead, trail };
}

function layout(ds: DrawState) {
  const t = ds.tileSize;
  const border = Math.round(t * 0.5);
  return { t, border };
}

// --------------------------------------------------------------------- drawing

function drawWall(dr: Drawing, x: number, y: number, t: number, seed: number): void {
  const pad = Math.max(1, t * 0.05);
  dr.rect(x + pad, y + pad, t - 2 * pad, t - 2 * pad, 'shade');
  dr.hatch(
    x + pad,
    y + pad,
    t - 2 * pad,
    t - 2 * pad,
    'pencil',
    Math.max(3.5, t * 0.19),
    Math.PI / 4,
    1,
    {
      seed,
    },
  );
  dr.rectOutline(x + pad, y + pad, t - 2 * pad, t - 2 * pad, 'ink', { width: 1.6, seed });
}

/** A stop: a pencil ring broken into four arcs, like the original's marker. */
function drawStop(dr: Drawing, cx: number, cy: number, t: number, seed: number): void {
  const r = t * 0.3;
  const gap = Math.PI / 12;
  for (let q = 0; q < 4; q++) {
    const a0 = (q * Math.PI) / 2 + gap;
    const a1 = ((q + 1) * Math.PI) / 2 - gap;
    const pts: number[] = [];
    const n = 5;
    for (let i = 0; i <= n; i++) {
      const a = a0 + ((a1 - a0) * i) / n;
      pts.push(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
    dr.polyline(pts, 'pencil', Math.max(1.2, t * 0.035), { seed: seed + q });
  }
}

function drawGem(dr: Drawing, cx: number, cy: number, t: number, seed: number): void {
  const ry = t * 0.36;
  const rx = t * 0.3;
  const fill = dr.mix('blue', 'paper', 0.35);
  dr.polygon([cx, cy - ry, cx + rx, cy, cx, cy + ry, cx - rx, cy], fill, 'blue', {
    width: Math.max(1.3, t * 0.04),
    seed,
  });
  if (t >= 18) {
    // A facet line and a glint so it reads as a cut stone.
    dr.line(cx - rx * 0.55, cy - ry * 0.05, cx + rx * 0.55, cy - ry * 0.05, 'blue', 1, {
      seed: seed + 1,
      alpha: 0.6,
    });
    dr.dot(cx - rx * 0.2, cy - ry * 0.45, Math.max(1, t * 0.04), 'paper', { seed });
  }
}

function drawMine(dr: Drawing, cx: number, cy: number, t: number, seed: number): void {
  const r = t * 0.24;
  const spikes = 8;
  for (let i = 0; i < spikes; i++) {
    const a = (i * Math.PI * 2) / spikes + Math.PI / 8;
    dr.line(
      cx + Math.cos(a) * r * 0.7,
      cy + Math.sin(a) * r * 0.7,
      cx + Math.cos(a) * r * 1.75,
      cy + Math.sin(a) * r * 1.75,
      'ink',
      Math.max(1.2, t * 0.045),
      { seed: seed + i },
    );
  }
  dr.circle(cx, cy, r, 'ink', 'ink', { width: 1, seed });
  if (t >= 16) dr.dot(cx - r * 0.35, cy - r * 0.35, Math.max(1, r * 0.22), 'paper', { seed });
}

function drawBall(dr: Drawing, cx: number, cy: number, t: number, moving: boolean): void {
  // With the mascot on, the thing being rolled around the grid is Ziggy himself. It is the
  // one token in this game the player identifies *as* themselves, so it is where a mascot
  // earns its place rather than merely decorating.
  if (ziggyEnabled()) {
    drawZiggy(dr, cx, cy, t * 0.92, 7);
    return;
  }
  dr.circle(cx, cy, t * 0.33, 'accent', 'ink', {
    width: Math.max(1.4, t * 0.045),
    seed: 7,
    rough: moving ? 0 : undefined,
  });
  if (t >= 16) dr.dot(cx - t * 0.11, cy - t * 0.12, t * 0.06, 'paper', { rough: 0 });
}

/** The ball after hitting a mine: a burst, in the error colour. */
function drawDeadBall(dr: Drawing, cx: number, cy: number, t: number): void {
  const pts: number[] = [];
  const n = 8;
  for (let i = 0; i < n; i++) {
    const a0 = (i * Math.PI * 2) / n;
    const a1 = a0 + Math.PI / n;
    pts.push(cx + Math.cos(a0) * t * 0.44, cy + Math.sin(a0) * t * 0.44);
    pts.push(cx + Math.cos(a1) * t * 0.2, cy + Math.sin(a1) * t * 0.2);
  }
  dr.polygon(pts, 'error', 'ink', { width: Math.max(1.4, t * 0.045), seed: 9 });
}

const game = defineGame<InertiaParams, InertiaState, InertiaUI>({
  id: 'inertia',
  name: 'Inertia',
  description: 'Slide a ball around a grid to collect every gem without hitting a mine.',
  help,
  tutorial,
  achievements,
  presets: [
    { name: '10×8', params: { w: 10, h: 8 } },
    { name: '15×12', params: { w: 15, h: 12 } },
    { name: '20×16', params: { w: 20, h: 16 } },
  ],
  defaultParams: () => ({ w: 10, h: 8 }),
  encodeParams: (p) => `${p.w}x${p.h}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    return { w: r.w, h: r.h };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w * p.h < 6) return tx`Grid area must be at least six squares`;
    if (p.w > MAX_DIM || p.h > MAX_DIM) return tx`Width and height must be at most ${MAX_DIM}`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
    ];
  },
  customParams(items) {
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      // A minus sign is still a whole number: let validation say it is too small.
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return { w: int(0), h: int(1) };
  },

  newDesc(p, rng: Random) {
    return { desc: generate(p.w, p.h, rng) };
  },

  validateDesc(p, desc) {
    const wh = p.w * p.h;
    if (desc.length < wh) return tx`Not enough data to fill grid`;
    if (desc.length > wh) return tx`Too much data to fill grid`;
    let starts = 0;
    let gems = 0;
    for (const c of desc) {
      if (c === START) starts++;
      else if (c === GEM) gems++;
      else if (c !== WALL && c !== STOP && c !== MINE && c !== BLANK)
        return tx`Unrecognised character in game description`;
    }
    if (starts < 1) return tx`No starting square specified`;
    if (starts > 1) return tx`More than one starting square specified`;
    if (gems < 1) return tx`No gems specified`;
    return null;
  },

  newGame(p, desc) {
    const start = desc.indexOf(START);
    const px = start % p.w;
    const py = (start - px) / p.w;
    // The ball's own square acts as a stop once it has left it.
    const grid = desc.replace(START, STOP);
    let gems = 0;
    for (const c of grid) if (c === GEM) gems++;
    return { w: p.w, h: p.h, grid, px, py, gems, dead: false, cheated: false, trail: [start] };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (curr.dead) throw new Error(tx`The ball has hit a mine; undo that move first`);
    if (curr.gems === 0) throw new Error(tx`Game is already solved`);
    const route = solveRoute(curr.w, curr.h, curr.grid, curr.px, curr.py);
    if (!route || route.length === 0)
      throw new Error(tx`Unable to find a solution from this position`);
    return `S${route.join('')}`;
  },

  newUI: () => ({ deaths: 0, justMadeMove: false, justDied: false }),
  changedState(ui, oldState, newState) {
    // Count a death only for a move the player just made (not for redoing an old one),
    // and only while there was still something to play for.
    if (!oldState.dead && newState.dead && ui.justMadeMove && oldState.gems > 0) {
      ui.deaths++;
      ui.justDied = true;
    } else {
      ui.justDied = false;
    }
    ui.justMadeMove = false;
  },
  encodeUI: (ui) => `D${ui.deaths}`,
  decodeUI(ui, enc) {
    const m = /^D(\d+)/.exec(enc);
    if (m) ui.deaths = parseInt(m[1], 10);
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const c = stripMods(button);
    let dir: number;
    if (c === LEFT_BUTTON) {
      // The move goes in the general direction of the clicked square: whichever of the
      // eight compass points its offset from the ball is nearest to.
      const { t, border } = layout(ds);
      const cx = Math.floor((mx - border) / t);
      const cy = Math.floor((my - border) / t);
      if (cx === state.px && cy === state.py) return null;
      dir = octant(cx - state.px, cy - state.py);
    } else if (c === CURSOR_UP) dir = 0;
    else if (c === CURSOR_RIGHT) dir = 2;
    else if (c === CURSOR_DOWN) dir = 4;
    else if (c === CURSOR_LEFT) dir = 6;
    else if (c >= 48 && c < 58) {
      // Keypad digits (Home/End/PgUp/PgDn arrive as keypad 7/1/9/3); the number row works too.
      const d = KEYPAD_DIRS[String.fromCharCode(c)];
      if (d === undefined) return null;
      dir = d;
    } else {
      return null;
    }
    // A finished board stays finished: rolling on after the last gem could only end on a
    // mine, which turned a solved puzzle into a lost one.
    if (state.dead || state.gems === 0) return null;
    if (cellAt(state.w, state.h, state.grid, state.px + DX[dir], state.py + DY[dir]) === WALL)
      return null;
    ui.justMadeMove = true;
    return String(dir);
  },

  executeMove(state, move) {
    if (/^[0-7]$/.test(move)) return applyRoute(state, [parseInt(move, 10)]);
    if (/^S[0-7]+$/.test(move)) {
      const next = applyRoute(state, Array.from(move.slice(1), Number));
      if (!next || next.dead) return null;
      return { ...next, cheated: true };
    }
    return null;
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const border = Math.round(t * 0.5);
    return { w: p.w * t + 2 * border, h: p.h * t + 2 * border };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h } = state;
    const { t, border } = layout(ds);
    const X = (x: number) => border + x * t;
    const Y = (y: number) => border + y * t;

    // Work out how far along its trail the ball is. `earlier`/`later` are the two states
    // in play order regardless of whether this is a move or an undo.
    let earlier = state;
    let later = state;
    let animating = false;
    let progress = 0;
    if (oldState) {
      earlier = dir > 0 ? oldState : state;
      later = dir > 0 ? state : oldState;
      const steps = later.trail.length - 1;
      const total = slideTime(steps);
      if (steps > 0 && later.trail[0] === earlier.py * w + earlier.px) {
        animating = true;
        const frac = clamp(animTime / total, 0, 1);
        progress = (dir > 0 ? frac : 1 - frac) * steps;
      }
    }
    const firstVisit = new Map<number, number>();
    if (animating) {
      later.trail.forEach((c, i) => {
        if (!firstVisit.has(c)) firstVisit.set(c, i);
      });
    }
    // The picture shows the earlier grid, minus gems the ball has already rolled over.
    const shown = (c: number): string => {
      const v = earlier.grid[c];
      if (animating && v === GEM && later.grid[c] !== GEM) {
        const at = firstVisit.get(c);
        if (at !== undefined && progress >= at) return BLANK;
      }
      return v;
    };
    const restingDead = state.dead && !animating;
    const ballCell = state.py * w + state.px;

    // Flash: a red wash for a death, a shaded board for a win.
    if (flashOn(flashTime, FLASH_FRAME)) {
      if (state.dead) dr.rect(X(0), Y(0), w * t, h * t, 'error', null, { alpha: 0.28 });
      else dr.rect(X(0), Y(0), w * t, h * t, 'shade');
    }

    for (let x = 1; x < w; x++) dr.line(X(x), Y(0), X(x), Y(h), 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(X(0), Y(y), X(w), Y(y), 'faint', 1.2);

    let gemsShown = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const c = y * w + x;
        const v = shown(c);
        const seed = c + 1;
        const cx = X(x) + t / 2;
        const cy = Y(y) + t / 2;
        if (v === WALL) drawWall(dr, X(x), Y(y), t, seed);
        else if (v === STOP) drawStop(dr, cx, cy, t, seed);
        else if (v === GEM) {
          gemsShown++;
          drawGem(dr, cx, cy, t, seed);
        } else if (v === MINE && !(restingDead && c === ballCell)) drawMine(dr, cx, cy, t, seed);
      }
    }
    dr.rectOutline(X(0), Y(0), w * t, h * t, 'ink', { width: 2.4 });

    // The route so far, when Solve is doing the driving.
    if (animating && later.cheated && !earlier.cheated) {
      const pts: number[] = [];
      const upto = Math.floor(progress);
      for (let i = 0; i <= upto; i++) {
        const c = later.trail[i];
        pts.push(X(c % w) + t / 2, Y(Math.floor(c / w)) + t / 2);
      }
      if (pts.length >= 4)
        dr.polyline(pts, 'accent', Math.max(2, t * 0.08), { alpha: 0.3, rough: 0 });
    }

    // The ball, interpolated between the two trail squares it is passing between.
    let bx = X(state.px) + t / 2;
    let by = Y(state.py) + t / 2;
    if (animating) {
      const i0 = Math.floor(progress);
      const i1 = Math.min(later.trail.length - 1, i0 + 1);
      const f = progress - i0;
      const a = later.trail[i0];
      const b = later.trail[i1];
      bx = X((a % w) * (1 - f) + (b % w) * f) + t / 2;
      by = Y(Math.floor(a / w) * (1 - f) + Math.floor(b / w) * f) + t / 2;
    }
    if (restingDead) drawDeadBall(dr, bx, by, t);
    else drawBall(dr, bx, by, t, animating);

    const prev = animating && oldState ? oldState : state;
    let text: string;
    if (state.dead && prev.dead) text = tr('status.dead');
    else if (state.gems > 0 || prev.gems > 0)
      text =
        (state.cheated ? tr('status.autoSolverUsedPrefix') : '') +
        tr('games.inertia.status.gems', { n: gemsShown });
    else if (state.cheated) text = tr('status.autoSolved');
    else text = tr('status.completed');
    // Do not count a death until the ball has actually arrived on the mine.
    let deaths = ui.deaths;
    if (animating && ui.justDied && deaths > 0) deaths--;
    if (deaths > 0) text += tr('games.inertia.status.deaths', { n: deaths });
    dr.statusBar(text);
  },

  animLength(oldState, newState, dir) {
    const earlier = dir > 0 ? oldState : newState;
    const later = dir > 0 ? newState : oldState;
    const steps = later.trail.length - 1;
    if (steps <= 0 || later.trail[0] !== earlier.py * earlier.w + earlier.px) return 0;
    return slideTime(steps);
  },
  flashLength(oldState, newState) {
    if (!oldState.dead && newState.dead) return FLASH;
    if (oldState.gems > 0 && newState.gems === 0 && !newState.dead) return FLASH;
    return 0;
  },
  status: (s) => (s.dead ? -1 : s.gems === 0 ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  flags: { solveAnimates: true, oneButton: true, undoAfterLoss: true },
});

export default game;
