/**
 * Deductive Magnets solver.
 *
 * The solver works on a `Work`: for every cell a polarity (meaningful once the cell is
 * *set*) plus flags recording which polarities have been ruled out. Ruling a polarity
 * out for one half of a domino rules the opposite polarity out for the other half, and
 * setting a pole rules that pole out of the four neighbouring cells. On top of that
 * bookkeeping sit two tiers of reasoning:
 *
 *  - **Easy**: a cell with only one polarity left takes it; a domino neither half of
 *    which can be `+` (or `-`) is neutral; a line whose `+`, `-` or neutral count is
 *    already met rules that polarity out of its other cells, and a line that needs
 *    every remaining candidate for a polarity sets them all; and when a line needs no
 *    more neutrals and one more `+` than `-` (or vice versa), the only odd-length run of
 *    empty cells must start with the extra pole.
 *  - **Tricky** adds arguments about whole dominoes lying within a line: a domino that
 *    must be a magnet contributes one `+` and one `-` however it is turned, which may fill
 *    a count; a line with one neutral still to place cannot have a neutral domino lying
 *    along it; a line whose remaining `+` (or `-`) count equals its number of empty
 *    dominoes has no neutral left; and when the number of dominoes that could still
 *    supply a pole equals the poles still needed, a domino with only one candidate half
 *    for that pole gets it.
 *
 * `solve` returns 1 when the grid is complete, 0 when it got stuck and -1 when the
 * puzzle is contradictory. Every deduction is sound, so a complete grid is the unique
 * solution.
 */
import {
  CELL_NEUTRAL,
  CELL_NOT_NEUTRAL,
  Layout,
  NEGATIVE,
  NEUTRAL,
  POSITIVE,
  checkCompletion,
  opposite,
  polarityOf,
} from './board';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFF_COUNT = 2;
export const DIFFICULTY_NAMES = ['Easy', 'Hard'];
export const DIFFICULTY_LETTERS = 'et';

const SET = 1;
const NOT_POSITIVE = 2;
const NOT_NEGATIVE = 4;
const NOT_NEUTRAL = 8;
const MARK = 16;
const NOT_MASK = NOT_POSITIVE | NOT_NEGATIVE | NOT_NEUTRAL;
const NOT_FLAG = [NOT_NEUTRAL, NOT_POSITIVE, NOT_NEGATIVE];

/** Mutable solving state over a layout. */
export class Work {
  grid: Uint8Array;
  flags: Uint8Array;

  constructor(readonly L: Layout) {
    this.grid = new Uint8Array(L.n);
    this.flags = new Uint8Array(L.n);
    for (let i = 0; i < L.n; i++) if (L.partner[i] === i) this.flags[i] = SET;
  }

  /** A work with every magnet and neutral the player has placed held fixed. */
  static fromCells(L: Layout, cells: Uint8Array): Work | null {
    const w = new Work(L);
    for (let i = 0; i < L.n; i++) {
      if (L.partner[i] === i || cells[i] === CELL_NOT_NEUTRAL) continue;
      const p = polarityOf(cells[i]);
      if (p >= 0 && w.set(i, p) < 0) return null;
    }
    return w;
  }

  isSet(i: number): boolean {
    return (this.flags[i] & SET) !== 0;
  }

  possible(i: number, which: number): boolean {
    return (this.flags[i] & NOT_FLAG[which]) === 0;
  }

  /** The grid as player cells, for judging completion. */
  toCells(): Uint8Array {
    const cells = new Uint8Array(this.L.n);
    for (let i = 0; i < this.L.n; i++)
      if (this.isSet(i)) cells[i] = this.grid[i] === NEUTRAL ? CELL_NEUTRAL : this.grid[i];
    return cells;
  }

  /**
   * Rule `which` out for cell `i` (and its opposite for the other half). Returns the
   * number of new flags, or -1 when the cell is already set that way.
   */
  unflag(i: number, which: number): number {
    const ii = this.L.partner[i];
    if (ii === i) return 0;
    if (this.isSet(i) && this.grid[i] === which) return -1;
    if (this.isSet(ii) && this.grid[ii] === opposite(which)) return -1;
    let ret = 0;
    if (this.possible(i, which)) {
      this.flags[i] |= NOT_FLAG[which];
      ret++;
    }
    if (this.possible(ii, opposite(which))) {
      this.flags[ii] |= NOT_FLAG[opposite(which)];
      ret++;
    }
    return ret;
  }

  /** A pole repels its like: rule `which` out of the four neighbours of `i`. */
  private unflagSurrounds(i: number, which: number): number {
    const { w, h } = this.L;
    const x = i % w;
    const y = Math.floor(i / w);
    if (x > 0 && this.unflag(i - 1, which) < 0) return -1;
    if (x + 1 < w && this.unflag(i + 1, which) < 0) return -1;
    if (y > 0 && this.unflag(i - w, which) < 0) return -1;
    if (y + 1 < h && this.unflag(i + w, which) < 0) return -1;
    return 0;
  }

  /**
   * Set cell `i` to `which` and the other half of its domino to the opposite. Returns 1
   * on success, 0 when it was already so, -1 when that contradicts what is known.
   */
  set(i: number, which: number): number {
    const ii = this.L.partner[i];
    if (this.isSet(i)) return this.grid[i] === which ? 0 : -1;
    if (this.isSet(ii) && this.grid[ii] !== opposite(which)) return -1;
    if (!this.possible(i, which) || !this.possible(ii, opposite(which))) return -1;
    if (which !== NEUTRAL) {
      if (this.unflagSurrounds(i, which) < 0) return -1;
      if (this.unflagSurrounds(ii, opposite(which)) < 0) return -1;
    }
    this.grid[i] = which;
    this.grid[ii] = opposite(which);
    this.flags[i] |= SET;
    this.flags[ii] |= SET;
    return 1;
  }
}

/** A row or column being reasoned about. */
interface Line {
  l: number;
  start: number;
  step: number;
  len: number;
}

type LineRule = (work: Work, rc: Line, counts: number[]) => number;

function lineOf(L: Layout, l: number): Line {
  return { l, ...L.line(l) };
}

/** Count set cells of each polarity in a line, and optionally the unset candidates. */
function lineCounts(work: Work, rc: Line, counts: number[], unset?: number[]): void {
  counts[0] = counts[1] = counts[2] = 0;
  if (unset) unset[0] = unset[1] = unset[2] = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i)) counts[work.grid[i]]++;
    else if (unset)
      for (let which = 0; which <= 2; which++) if (work.possible(i, which)) unset[which]++;
  }
}

/** Every cell with a single polarity left takes it. */
function force(work: Work): number {
  let did = 0;
  for (let i = 0; i < work.L.n; i++) {
    if (work.isSet(i) || work.L.partner[i] === i) continue;
    const f = work.flags[i] & NOT_MASK;
    const which =
      f === (NOT_POSITIVE | NOT_NEGATIVE)
        ? NEUTRAL
        : f === (NOT_POSITIVE | NOT_NEUTRAL)
          ? NEGATIVE
          : f === (NOT_NEGATIVE | NOT_NEUTRAL)
            ? POSITIVE
            : -1;
    if (which < 0) continue;
    if (work.set(i, which) < 0) return -1;
    did = 1;
  }
  return did;
}

/** A domino neither half of which can be `+` (or neither `-`) is neutral. */
function neither(work: Work): number {
  let did = 0;
  const { flags } = work;
  for (let i = 0; i < work.L.n; i++) {
    if (work.isSet(i)) continue;
    const j = work.L.partner[i];
    if (j === i) continue;
    if (
      (flags[i] & NOT_POSITIVE && flags[j] & NOT_POSITIVE) ||
      (flags[i] & NOT_NEGATIVE && flags[j] & NOT_NEGATIVE)
    ) {
      if (work.set(i, NEUTRAL) < 0) return -1;
      did = 1;
    }
  }
  return did;
}

/** A line whose count for a polarity is met, or that needs every candidate for it. */
const checkFull: LineRule = (work, rc, counts) => {
  const unset = [0, 0, 0];
  lineCounts(work, rc, counts, unset);
  let did = 0;
  for (let which = 0; which <= 2; which++) {
    const target = work.L.target(rc.l, which);
    if (target < 0) continue;
    if (target < counts[which] || target - counts[which] > unset[which]) return -1;
    if (target === counts[which]) {
      for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
        if (work.isSet(i) || !work.possible(i, which)) continue;
        if (work.unflag(i, which) < 0) return -1;
        did = 1;
      }
    } else if (target - counts[which] === unset[which]) {
      for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
        if (work.isSet(i) || !work.possible(i, which)) continue;
        if (work.set(i, which) < 0) return -1;
        did = 1;
      }
    }
  }
  return did;
};

/**
 * A line needing no more neutrals and one more of one pole than the other: its only
 * odd-length run of empty cells must begin (and end) with the extra pole.
 */
const oddLength: LineRule = (work, rc, counts) => {
  const { L } = work;
  if (L.target(rc.l, NEUTRAL) !== counts[NEUTRAL]) return 0;
  const tpos = L.target(rc.l, POSITIVE) - counts[POSITIVE];
  const tneg = L.target(rc.l, NEGATIVE) - counts[NEGATIVE];
  let extra: number;
  if (tpos === tneg + 1) extra = POSITIVE;
  else if (tneg === tpos + 1) extra = NEGATIVE;
  else return 0;

  let start = -1;
  let length = 0;
  let startOdd = -1;
  for (let k = 0, i = rc.start; k <= rc.len; k++, i += rc.step) {
    if (k < rc.len && !work.isSet(i)) {
      if (start < 0) start = i;
      length++;
      continue;
    }
    if (start >= 0 && length % 2) {
      if (startOdd >= 0) return 0; // two odd runs: nothing to conclude
      startOdd = start;
    }
    start = -1;
    length = 0;
  }
  if (startOdd < 0) return 0;
  return work.set(startOdd, extra);
};

/**
 * Dominoes lying along the line that must be magnets each supply one `+` and one `-`.
 * If that brings a pole's count up to its target, the pole is ruled out elsewhere.
 */
const advancedFull: LineRule = (work, rc, counts) => {
  const { L, flags } = work;
  const tpos = L.target(rc.l, POSITIVE);
  const tneg = L.target(rc.l, NEGATIVE);
  if (tpos < 0 && tneg < 0) return 0;
  if (tpos >= 0 && counts[POSITIVE] === tpos && tneg >= 0 && counts[NEGATIVE] === tneg) return 0;

  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) flags[i] &= ~MARK;
  let found = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i) || L.partner[i] !== i + rc.step) continue;
    if ((flags[i] & NOT_MASK) !== NOT_NEUTRAL || (flags[i + rc.step] & NOT_MASK) !== NOT_NEUTRAL)
      continue;
    flags[i] |= MARK;
    flags[i + rc.step] |= MARK;
    found++;
  }
  if (!found) return 0;
  const clearPos = tpos >= 0 && counts[POSITIVE] + found === tpos;
  const clearNeg = tneg >= 0 && counts[NEGATIVE] + found === tneg;
  if (!clearPos && !clearNeg) return 0;

  let did = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i) || flags[i] & MARK) continue;
    if (clearPos && work.possible(i, POSITIVE)) {
      if (work.unflag(i, POSITIVE) < 0) return -1;
      did++;
    }
    if (clearNeg && work.possible(i, NEGATIVE)) {
      if (work.unflag(i, NEGATIVE) < 0) return -1;
      did++;
    }
  }
  return did;
};

/** With one neutral left to place, no domino lying along the line can be neutral. */
const nonNeutral: LineRule = (work, rc, counts) => {
  const { L } = work;
  if (L.target(rc.l, NEUTRAL) !== counts[NEUTRAL] + 1) return 0;
  let did = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i) || L.partner[i] !== i + rc.step) continue;
    if (!work.possible(i, NEUTRAL)) continue;
    if (work.unflag(i, NEUTRAL) < 0) return -1;
    did++;
  }
  return did;
};

/** The number of dominoes with an unset cell in the line (each counted once). */
function countEmptyDominoes(work: Work, rc: Line): number {
  const { L } = work;
  let n = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i) || L.partner[i] === i || L.partner[i] === i - rc.step) continue;
    n++;
  }
  return n;
}

/** If a pole's remaining count equals the number of empty dominoes, nothing is neutral. */
const countDominoesNeutral: LineRule = (work, rc, counts) => {
  const { L } = work;
  const tpos = L.target(rc.l, POSITIVE);
  const tneg = L.target(rc.l, NEGATIVE);
  if (tpos < 0 && tneg < 0) return 0;
  const ndom = countEmptyDominoes(work, rc);
  const nonn =
    (tpos >= 0 && tpos - counts[POSITIVE] === ndom) ||
    (tneg >= 0 && tneg - counts[NEGATIVE] === ndom);
  if (!nonn) return 0;
  let did = 0;
  for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
    if (work.isSet(i) || !work.possible(i, NEUTRAL)) continue;
    if (work.unflag(i, NEUTRAL) < 0) return -1;
    did++;
  }
  return did;
};

/** How many cells of the domino starting at `i` (within the line) could hold `which`. */
function dominoCandidates(work: Work, rc: Line, i: number, which: number): number {
  const { L } = work;
  if (L.partner[i] === i || L.partner[i] === i - rc.step || work.isSet(i)) return 0;
  let n = work.possible(i, which) ? 1 : 0;
  if (L.partner[i] === i + rc.step && work.possible(i + rc.step, which)) n++;
  return n;
}

/**
 * When exactly as many dominoes could supply a pole as poles are still needed, every
 * such domino must, so one with a single candidate half gets the pole there.
 */
const countDominoesNonNeutral: LineRule = (work, rc, counts) => {
  const { L } = work;
  let did = 0;
  for (const which of [POSITIVE, NEGATIVE]) {
    const target = L.target(rc.l, which);
    if (target < 0) continue;
    let ndom = 0;
    for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step)
      if (dominoCandidates(work, rc, i, which) > 0) ndom++;
    if (target - counts[which] !== ndom) continue;
    for (let k = 0, i = rc.start; k < rc.len; k++, i += rc.step) {
      if (dominoCandidates(work, rc, i, which) !== 1) continue;
      const toSet = work.possible(i, which) ? i : i + rc.step;
      if (work.set(toSet, which) < 0) return -1;
      did++;
    }
  }
  return did;
};

/** Apply a line rule to every column and row. */
function forLines(work: Work, rule: LineRule): number {
  const counts = [0, 0, 0];
  let did = 0;
  for (let l = 0; l < work.L.lines; l++) {
    const rc = lineOf(work.L, l);
    lineCounts(work, rc, counts);
    const r = rule(work, rc, counts);
    if (r < 0) return -1;
    did += r;
  }
  return did;
}

/** Only the domino-level bookkeeping: used while laying out a random solution. */
export function solveUnnumbered(work: Work): number {
  for (;;) {
    let r = force(work);
    if (r < 0) return -1;
    if (r > 0) continue;
    r = neither(work);
    if (r < 0) return -1;
    if (r > 0) continue;
    break;
  }
  for (let i = 0; i < work.L.n; i++) if (!work.isSet(i)) return 0;
  return 1;
}

const EASY_RULES: LineRule[] = [checkFull, oddLength];
const TRICKY_RULES: LineRule[] = [
  advancedFull,
  nonNeutral,
  countDominoesNeutral,
  countDominoesNonNeutral,
];

/**
 * Solve `work` in place as far as the deductions allowed at `diff` go. Returns 1 for a
 * complete grid, 0 when stuck and -1 when the puzzle is impossible.
 */
export function solve(work: Work, diff: number): -1 | 0 | 1 {
  const rules = diff >= DIFF_TRICKY ? [...EASY_RULES, ...TRICKY_RULES] : EASY_RULES;
  outer: for (;;) {
    let r = force(work);
    if (r < 0) return -1;
    if (r > 0) continue;
    r = neither(work);
    if (r < 0) return -1;
    if (r > 0) continue;
    for (const rule of rules) {
      r = forLines(work, rule);
      if (r < 0) return -1;
      if (r > 0) continue outer;
    }
    break;
  }
  return checkCompletion(work.L, work.toCells()).status;
}

/** Solve a layout from scratch at a difficulty; the work holds whatever was deduced. */
export function solveFresh(L: Layout, diff: number): { status: -1 | 0 | 1; work: Work } {
  const work = new Work(L);
  return { status: solve(work, diff), work };
}
