/**
 * Solo generator.
 *
 * 1. Build the region structure: regular blocks, or a random division of the grid into
 *    equal connected pieces for jigsaw mode, plus random cages for killer mode.
 * 2. Fill a complete grid with a randomised backtracking search that always works on the
 *    most constrained empty square.
 * 3. For ordinary puzzles, visit the squares (in symmetric groups) in random order and
 *    blank each group whose removal leaves the puzzle solvable at the requested
 *    difficulty. For killer puzzles, keep merging neighbouring cages while the empty grid
 *    stays solvable, remembering the last cage set that hit the requested difficulty.
 * 4. Grade the result; if it turned out easier than asked for, start again.
 */
import type { Random } from '../../framework/rng';
import { BlockStructure, encodeDesc } from './blocks';
import {
  DIFF_BLOCK,
  DIFF_INTERSECT,
  DIFF_RECURSIVE,
  KDIFF_INTERSECT,
  KDIFF_SINGLE,
  onDiag0,
  onDiag1,
  solveGrid,
} from './solver';

export const SYMM_NONE = 0;
export const SYMM_ROT2 = 1;
export const SYMM_ROT4 = 2;
export const SYMM_REF2 = 3;
export const SYMM_REF2D = 4;
export const SYMM_REF4 = 5;
export const SYMM_REF4D = 6;
export const SYMM_REF8 = 7;

export interface GenParams {
  c: number;
  r: number;
  symm: number;
  diff: number;
  xtype: boolean;
  killer: boolean;
}

// ------------------------------------------------------------------ grid filler

/**
 * Fill an empty grid with a valid solution, or return null if the step budget runs out.
 * The top row is a random permutation (it only names the digits), then the remaining
 * squares are filled most-constrained first with digits tried in random order.
 *
 * With `singles`, each step also looks at every row, column, block (and diagonal) for a
 * digit that has lost its last possible square — a dead end, abandoned at once — or has
 * only one left, which is then placed first. Irregular jigsaw blocks need this: without it
 * the search wanders into dead ends it cannot see, and a 12×12 jigsaw failed hundreds of
 * times over before one grid came out (the reference generator has the same weakness).
 */
export function fillGrid(
  cr: number,
  blocks: BlockStructure,
  kblocks: BlockStructure | null,
  xtype: boolean,
  rng: Random,
  maxSteps: number,
  singles = false,
): Uint8Array | null {
  const area = cr * cr;
  const grid = new Uint8Array(area);
  const row = new Int32Array(cr);
  const col = new Int32Array(cr);
  const blk = new Int32Array(cr);
  const cge = kblocks ? new Int32Array(kblocks.nrBlocks) : null;
  const diag = xtype ? new Int32Array(2) : null;

  const setBit = (xy: number, n: number, on: boolean) => {
    const bit = 1 << n;
    const x = xy % cr;
    const y = Math.floor(xy / cr);
    const b = blocks.whichblock[xy];
    if (on) {
      row[y] |= bit;
      col[x] |= bit;
      blk[b] |= bit;
      if (cge) cge[kblocks!.whichblock[xy]] |= bit;
      if (diag) {
        if (onDiag0(xy, cr)) diag[0] |= bit;
        if (onDiag1(xy, cr)) diag[1] |= bit;
      }
      grid[xy] = n;
    } else {
      row[y] &= ~bit;
      col[x] &= ~bit;
      blk[b] &= ~bit;
      if (cge) cge[kblocks!.whichblock[xy]] &= ~bit;
      if (diag) {
        if (onDiag0(xy, cr)) diag[0] &= ~bit;
        if (onDiag1(xy, cr)) diag[1] &= ~bit;
      }
      grid[xy] = 0;
    }
  };
  const usedAt = (xy: number): number => {
    let used = row[Math.floor(xy / cr)] | col[xy % cr] | blk[blocks.whichblock[xy]];
    if (cge) used |= cge[kblocks!.whichblock[xy]];
    if (diag) {
      if (onDiag0(xy, cr)) used |= diag[0];
      if (onDiag1(xy, cr)) used |= diag[1];
    }
    return used;
  };

  const top: number[] = [];
  for (let x = 0; x < cr; x++) top.push(x + 1);
  rng.shuffle(top);
  for (let x = 0; x < cr; x++) setBit(x, top[x], true);

  // Remaining spaces with a random tie-break priority.
  const spaces: number[] = [];
  const prio: number[] = [];
  for (let xy = cr; xy < area; xy++) {
    spaces.push(xy);
    prio.push(rng.bits(31));
  }
  let nspaces = spaces.length;
  let steps = maxSteps;

  // For `singles`: every row, column, block and diagonal as a list of squares, and each
  // empty square's candidates (bit n for digit n), refreshed by every step's scan.
  const full = ((1 << (cr + 1)) - 1) & ~1;
  const cand = singles ? new Int32Array(area) : null;
  const units: number[][] = [];
  const unitUsed: Int32Array[] = [];
  if (singles) {
    for (let y = 0; y < cr; y++) units.push(Array.from({ length: cr }, (_, x) => y * cr + x));
    unitUsed.push(row);
    for (let x = 0; x < cr; x++) units.push(Array.from({ length: cr }, (_, y) => y * cr + x));
    unitUsed.push(col);
    for (const b of blocks.blocks) units.push(b.slice());
    unitUsed.push(blk);
    if (diag) {
      units.push(Array.from({ length: cr }, (_, i) => i * (cr + 1)));
      units.push(Array.from({ length: cr }, (_, i) => (i + 1) * (cr - 1)));
      unitUsed.push(diag);
    }
  }
  const usedOfUnit = (k: number): number => {
    let t = k;
    for (const arr of unitUsed) {
      if (t < arr.length) return arr[t];
      t -= arr.length;
    }
    return 0;
  };
  /**
   * -1 if some unit has a digit with nowhere left to go; otherwise the first forced
   * placement found as (square << 5 | digit), or 0 for none.
   */
  const unitSingle = (): number => {
    for (let k = 0; k < units.length; k++) {
      let once = 0;
      let twice = 0;
      for (const xy of units[k]) {
        if (grid[xy]) continue;
        const c = cand![xy];
        twice |= once & c;
        once |= c;
      }
      const missing = full & ~usedOfUnit(k);
      if (missing & ~once) return -1;
      const one = missing & once & ~twice;
      if (one) {
        const n = 31 - Math.clz32(one & -one);
        const xy = units[k].find((q) => !grid[q] && cand![q] & (1 << n))!;
        return (xy << 5) | n;
      }
    }
    return 0;
  };

  const recurse = (): boolean => {
    if (nspaces === 0) return true;
    if (steps <= 0) return false;
    steps--;
    let bestm = cr + 1;
    let bestr = 0;
    let bi = -1;
    let used = 0;
    for (let j = 0; j < nspaces; j++) {
      const u = usedAt(spaces[j]);
      if (cand) cand[spaces[j]] = full & ~u;
      let m = 0;
      for (let n = 1; n <= cr; n++) if (!(u & (1 << n))) m++;
      if (m < bestm || (m === bestm && prio[j] < bestr)) {
        bestm = m;
        bestr = prio[j];
        bi = j;
        used = u;
      }
    }
    if (cand && bestm > 1) {
      const single = unitSingle();
      if (single < 0) return false;
      if (single > 0) {
        const xy = single >> 5;
        const n = single & 31;
        bi = spaces.indexOf(xy, 0);
        used = full & ~(1 << n);
      }
    }
    const last = nspaces - 1;
    if (bi !== last) {
      [spaces[bi], spaces[last]] = [spaces[last], spaces[bi]];
      [prio[bi], prio[last]] = [prio[last], prio[bi]];
    }
    const xy = spaces[last];
    const digits: number[] = [];
    for (let n = 1; n <= cr; n++) if (!(used & (1 << n))) digits.push(n);
    rng.shuffle(digits);
    for (const n of digits) {
      setBit(xy, n, true);
      nspaces--;
      if (recurse()) return true;
      setBit(xy, n, false);
      nspaces++;
    }
    return false;
  };

  return recurse() ? grid : null;
}

// ---------------------------------------------------------------- jigsaw blocks

/**
 * Whether square (x, y) can be added to (or removed from) the piece labelled `val`
 * without breaking simple connectivity: it must touch the piece orthogonally and the
 * piece must occupy exactly one contiguous arc of its eight neighbours.
 */
function addRemCommon(w: number, h: number, x: number, y: number, own: Int32Array, val: number) {
  const nb = new Int32Array(8);
  for (let dir = 0; dir < 8; dir++) {
    const dx = (dir & 3) === 2 ? 0 : dir > 2 && dir < 6 ? 1 : -1;
    const dy = (dir & 3) === 0 ? 0 : dir < 4 ? -1 : 1;
    const sx = x + dx;
    const sy = y + dy;
    nb[dir] = sx < 0 || sx >= w || sy < 0 || sy >= h ? -1 : own[sy * w + sx];
  }
  if (nb[0] !== val && nb[2] !== val && nb[4] !== val && nb[6] !== val) return false;
  let count = 0;
  for (let dir = 0; dir < 8; dir++) {
    const next = (dir + 1) & 7;
    if ((nb[dir] === val) !== (nb[next] === val)) count++;
  }
  return count === 2;
}

/** One attempt at dividing a w × h rectangle into pieces of k squares. */
function divvyOnce(w: number, h: number, k: number, rng: Random): Int32Array | null {
  const wh = w * h;
  const n = wh / k;
  const order: number[] = [];
  for (let i = 0; i < wh; i++) order.push(i);
  rng.shuffle(order);
  const own = new Int32Array(wh).fill(-1);
  const sizes = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    own[order[i]] = i;
    sizes[i] = 1;
  }
  const addable = new Int32Array(wh * 4);
  const removable = new Uint8Array(wh);
  const from = new Int32Array(n);
  const stole = new Int32Array(n);
  const queue = new Int32Array(n);

  for (;;) {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const yx = y * w + x;
        const curr = own[yx];
        removable[yx] =
          curr < 0 ? 0 : sizes[curr] === 1 ? 1 : addRemCommon(w, h, x, y, own, curr) ? 1 : 0;
        for (let dir = 0; dir < 4; dir++) {
          const dx = dir === 0 ? -1 : dir === 1 ? 1 : 0;
          const dy = dir === 2 ? -1 : dir === 3 ? 1 : 0;
          const sx = x + dx;
          const sy = y + dy;
          addable[yx * 4 + dir] = -1;
          if (sx < 0 || sx >= w || sy < 0 || sy >= h) continue;
          const o = own[sy * w + sx];
          if (o < 0 || o === curr) continue;
          if (!addRemCommon(w, h, x, y, own, o)) continue;
          addable[yx * 4 + dir] = o;
        }
      }
    }

    const incomplete: number[] = [];
    for (let i = 0; i < n; i++) if (sizes[i] < k) incomplete.push(i);
    if (incomplete.length === 0) break;
    let j = incomplete[rng.upto(incomplete.length)];

    // Breadth-first search over pieces: expand j into a free square, possibly by stealing
    // a square from a neighbouring piece that then expands in turn.
    from.fill(-1);
    stole.fill(-1);
    let qhead = 0;
    let qtail = 0;
    queue[qtail++] = j;
    from[j] = stole[j] = -2;
    let done = false;
    while (qhead < qtail && !done) {
      j = queue[qhead];
      const tmpsq = stole[j];
      if (tmpsq >= 0) own[tmpsq] = -3;

      let found = -1;
      for (let i = 0; i < wh && found < 0; i++) {
        const sq = order[i];
        if (own[sq] !== -1) continue;
        if (sizes[j] === 1 && tmpsq >= 0) {
          found = sq;
          break;
        }
        for (let dir = 0; dir < 4; dir++) {
          if (addable[sq * 4 + dir] !== j) continue;
          if (!addRemCommon(w, h, sq % w, Math.floor(sq / w), own, j)) continue;
          found = sq;
          break;
        }
      }
      if (found >= 0) {
        if (tmpsq >= 0) own[tmpsq] = j;
        let sq = found;
        for (;;) {
          own[sq] = j;
          if (from[j] === -2) break;
          sq = stole[j];
          j = from[j];
        }
        sizes[j]++;
        done = true;
        break;
      }

      for (let i = 0; i < wh; i++) {
        const sq = order[i];
        const nj = own[sq];
        if (nj < 0 || from[nj] !== -1) continue;
        if (!removable[sq]) continue;
        for (let dir = 0; dir < 4; dir++) {
          if (addable[sq * 4 + dir] !== j) continue;
          if (!addRemCommon(w, h, sq % w, Math.floor(sq / w), own, j)) continue;
          queue[qtail++] = nj;
          from[nj] = j;
          stole[nj] = sq;
          break;
        }
      }
      if (tmpsq >= 0) own[tmpsq] = j;
      qhead++;
    }
    if (!done) return null;
  }
  return own;
}

/** Divide a w × h rectangle into connected pieces of k squares (k must divide w·h). */
export function divvyRectangle(w: number, h: number, k: number, rng: Random): Int32Array {
  for (;;) {
    const own = divvyOnce(w, h, k, rng);
    if (own) return own;
  }
}

// ---------------------------------------------------------------- killer cages

/** Random cages of one or two squares (singletons merged away when `removeSingletons`). */
export function genKillerCages(cr: number, rng: Random, removeSingletons: boolean): BlockStructure {
  const area = cr * cr;
  const own = new Int32Array(area).fill(-1);
  let nr = 0;
  for (let y = 0; y < cr; y++) {
    for (let x = 0; x < cr; x++) {
      const xy = y * cr + x;
      if (own[xy] !== -1) continue;
      own[xy] = nr;
      const rnd = rng.bits(4);
      if (xy + 1 < area && (rnd >= 4 || (!removeSingletons && rnd >= 1))) {
        let xy2 = xy + 1;
        if (x + 1 === cr || own[xy2] !== -1 || (xy + cr < area && rng.bits(1) === 0)) xy2 = xy + cr;
        if (xy2 < area) own[xy2] = nr;
      }
      nr++;
    }
  }
  const b = BlockStructure.fromOwners(cr, own, cr);
  if (removeSingletons) {
    for (let n = 0; n < b.nrBlocks;) {
      if (b.blocks[n].length > 1) {
        n++;
        continue;
      }
      const xy = b.blocks[n][0];
      const x = xy % cr;
      const y = Math.floor(xy / cr);
      let xy2: number;
      if (xy + 1 === area) xy2 = xy - 1;
      else if (x + 1 < cr && (y + 1 === cr || rng.bits(1) === 0)) xy2 = xy + 1;
      else xy2 = xy + cr;
      const other = b.whichblock[xy2];
      b.merge(n, other);
      if (n < other) n++;
    }
  }
  return b;
}

/**
 * Merge a random pair of adjacent cages whose digits stay distinct and whose combined
 * size fits. Returns false when no merge is possible.
 */
export function mergeSomeCages(b: BlockStructure, grid: Uint8Array, rng: Random): boolean {
  const cr = b.cr;
  const pairs: [number, number][] = [];
  for (let i = 0; i < b.nrBlocks; i++) {
    for (let j = i + 1; j < b.nrBlocks; j++) {
      if (b.blocks[i].length + b.blocks[j].length > b.maxSquares) continue;
      for (const xy of b.blocks[i]) {
        const x = xy % cr;
        const y = Math.floor(xy / cr);
        if (
          (y > 0 && b.whichblock[xy - cr] === j) ||
          (y + 1 < cr && b.whichblock[xy + cr] === j) ||
          (x > 0 && b.whichblock[xy - 1] === j) ||
          (x + 1 < cr && b.whichblock[xy + 1] === j)
        ) {
          pairs.push([i, j]);
          break;
        }
      }
    }
  }
  while (pairs.length) {
    const i = rng.upto(pairs.length);
    const [n1, n2] = pairs[i];
    pairs[i] = pairs[pairs.length - 1];
    pairs.pop();
    let digits = 0;
    for (const s of b.blocks[n1]) digits |= 1 << grid[s];
    if (b.blocks[n2].some((s) => digits & (1 << grid[s]))) continue;
    b.merge(n1, n2);
    return true;
  }
  return false;
}

/** The sum of each cage, written into its first square. */
export function computeKclues(cages: BlockStructure, grid: Uint8Array): Uint8Array {
  const kgrid = new Uint8Array(grid.length);
  for (const squares of cages.blocks) {
    let sum = 0;
    for (const s of squares) sum += grid[s];
    kgrid[Math.min(...squares)] = sum;
  }
  return kgrid;
}

// ------------------------------------------------------------------ symmetry

/** The squares equivalent to (x, y) under the symmetry, including itself. */
export function symmetries(cr: number, x: number, y: number, s: number): [number, number][] {
  const out: [number, number][] = [[x, y]];
  const m = cr - 1;
  switch (s) {
    case SYMM_ROT2:
      out.push([m - x, m - y]);
      break;
    case SYMM_ROT4:
      out.push([m - y, x], [y, m - x], [m - x, m - y]);
      break;
    case SYMM_REF2:
      out.push([m - x, y]);
      break;
    case SYMM_REF2D:
      out.push([y, x]);
      break;
    case SYMM_REF4:
      out.push([m - x, y], [x, m - y], [m - x, m - y]);
      break;
    case SYMM_REF4D:
      out.push([y, x], [m - x, m - y], [m - y, m - x]);
      break;
    case SYMM_REF8:
      out.push(
        [m - x, y],
        [x, m - y],
        [m - x, m - y],
        [y, x],
        [y, m - x],
        [m - y, x],
        [m - y, m - x],
      );
      break;
  }
  return out;
}

// ------------------------------------------------------------------ generation

/**
 * Guesses one Unreasonable grading may make. Proving uniqueness by trial and error is
 * exponential, and on a 12×12 X or jigsaw grid a single check could run to tens of
 * thousands of guesses, freezing the page for a minute. A check that runs out counts as
 * "not unique", so the clue in question simply stays; the 9×9 presets need a few dozen.
 */
const GUESS_BUDGET = 200;
/**
 * Killer cage sets graded, or grids that failed to fill, before an exact difficulty match
 * is no longer insisted on. Expert is a narrow target: merging one more pair of cages usually
 * jumps straight from Hard to beyond Expert, and a 9×9 Killer Expert took up to half a
 * minute of retries; an X-diagonal jigsaw Killer mostly fails to fill at all. Past either
 * limit the level just below is accepted too, as Map does in the original, and so is a
 * puzzle whose cages need less than the full range of sum reasoning.
 */
const KILLER_GRADINGS = 500;
const KILLER_FILL_FAILS = 25;

/**
 * Killer: merge cages until the empty grid is exactly as hard as requested. `counter`
 * tallies the gradings and failed grids of the whole deal (see KILLER_GRADINGS).
 */
function refineKillerCages(
  cr: number,
  blocks: BlockStructure,
  cages: BlockStructure,
  xtype: boolean,
  solution: Uint8Array,
  maxdiff: number,
  maxkdiff: number,
  rng: Random,
  counter: { gradings: number; fillFails: number },
): { kblocks: BlockStructure; kgrid: Uint8Array } | null {
  let kblocks = cages;
  let good: BlockStructure | null = null;
  let last: BlockStructure | null = null;
  let tries = 0;
  const grid = new Uint8Array(cr * cr);
  // Grading a big-caged empty grid by trial and error is exponential, and an Unreasonable
  // target keeps the solver guessing on every merge — one puzzle could take minutes. So
  // at that level the starting cages are graded as they are and a miss means a fresh grid,
  // which is all the reference generator ever does (its merge step never fires).
  const merge =
    maxdiff >= DIFF_RECURSIVE ? () => false : () => mergeSomeCages(kblocks, solution, rng);
  for (;;) {
    counter.gradings++;
    const kgrid = computeKclues(kblocks, solution);
    grid.fill(0);
    const res = solveGrid(cr, blocks, kblocks, xtype, grid, kgrid, maxdiff, maxkdiff, {
      left: GUESS_BUDGET,
    });
    const relaxed = counter.gradings > KILLER_GRADINGS || counter.fillFails > KILLER_FILL_FAILS;
    const target = relaxed
      ? (res.diff === maxdiff || res.diff === maxdiff - 1) && res.kdiff <= maxkdiff
      : res.diff === maxdiff && res.kdiff === maxkdiff;
    if (target) {
      tries = 0;
      good = kblocks.clone();
      if (!merge()) break;
    } else if (res.diff > maxdiff || res.kdiff > maxkdiff) {
      if (++tries > 50) break;
      if (good) {
        kblocks = good.clone();
        if (!merge()) break;
      } else {
        if (!last) break;
        kblocks = last;
        last = null;
      }
    } else {
      last = kblocks.clone();
      if (!merge()) break;
    }
  }
  if (!good) return null;
  return { kblocks: good, kgrid: computeKclues(good, solution) };
}

/** Generate a puzzle description and its solution (as a Solve move) from the RNG. */
export function generateSolo(p: GenParams, rng: Random): { desc: string; aux: string } {
  const { c, r } = p;
  const cr = c * r;
  const area = cr * cr;
  const jigsaw = r === 1;
  // Every 2×2 puzzle is Trivial, and so is every jigsaw of fewer than four digits; a
  // four-digit jigsaw never needs more than Intermediate. Holding out for anything harder
  // would loop for ever, since there is nothing harder to find.
  const maxdiff =
    (c === 2 && r === 2) || (jigsaw && cr < 4)
      ? DIFF_BLOCK
      : jigsaw && cr === 4
        ? Math.min(p.diff, DIFF_INTERSECT)
        : p.diff;
  const maxkdiff = KDIFF_INTERSECT;
  const counter = { gradings: 0, fillFails: 0 };

  for (;;) {
    const blocks = jigsaw
      ? BlockStructure.fromOwners(cr, divvyRectangle(cr, cr, cr, rng), cr)
      : BlockStructure.regular(c, r);
    const cages = p.killer ? genKillerCages(cr, rng, maxkdiff > KDIFF_SINGLE) : null;
    const grid = fillGrid(cr, blocks, cages, p.xtype, rng, area * area, jigsaw);
    if (!grid) {
      counter.fillFails++;
      continue;
    }
    const aux = 'S' + Array.from(grid).join(',');

    if (p.killer) {
      const refined = refineKillerCages(
        cr,
        blocks,
        cages!,
        p.xtype,
        grid,
        maxdiff,
        maxkdiff,
        rng,
        counter,
      );
      if (!refined) continue;
      const empty = new Uint8Array(area);
      return { desc: encodeDesc(empty, blocks, jigsaw, refined.kblocks, refined.kgrid), aux };
    }

    // Representatives of the symmetry classes, in random order.
    const locs: [number, number][] = [];
    for (let y = 0; y < cr; y++) {
      for (let x = 0; x < cr; x++) {
        const i = y * cr + x;
        const coords = symmetries(cr, x, y, p.symm);
        if (coords.every(([cx, cy]) => cy * cr + cx >= i)) locs.push([x, y]);
      }
    }
    rng.shuffle(locs);

    const grid2 = new Uint8Array(area);
    for (const [x, y] of locs) {
      grid2.set(grid);
      const coords = symmetries(cr, x, y, p.symm);
      for (const [cx, cy] of coords) grid2[cy * cr + cx] = 0;
      const res = solveGrid(cr, blocks, null, p.xtype, grid2, null, maxdiff, maxkdiff, {
        left: GUESS_BUDGET,
      });
      if (res.diff <= maxdiff) for (const [cx, cy] of coords) grid[cy * cr + cx] = 0;
    }

    grid2.set(grid);
    const res = solveGrid(cr, blocks, null, p.xtype, grid2, null, maxdiff, maxkdiff, {
      left: GUESS_BUDGET,
    });
    if (res.diff === maxdiff) return { desc: encodeDesc(grid, blocks, jigsaw, null, null), aux };
  }
}

/** Grade a puzzle: the difficulty its solution requires (or AMBIGUOUS / IMPOSSIBLE). */
export function gradePuzzle(
  cr: number,
  blocks: BlockStructure,
  kblocks: BlockStructure | null,
  xtype: boolean,
  grid: Uint8Array,
  kgrid: Uint8Array | null,
): { diff: number; kdiff: number; solution: Uint8Array } {
  const solution = grid.slice();
  const res = solveGrid(
    cr,
    blocks,
    kblocks,
    xtype,
    solution,
    kgrid,
    DIFF_RECURSIVE,
    KDIFF_INTERSECT,
  );
  return { ...res, solution };
}
