/**
 * Disjoint-set forest (union–find) with path compression and union by size.
 * Also supports the "inverse" flag flavour used by parity puzzles: two elements can be
 * merged as opposites, and `canonify` reports whether an element is inverted relative
 * to its root.
 */
export class DSF {
  private parent: Int32Array;
  private sizes: Int32Array;
  private inv: Uint8Array;

  constructor(public readonly size: number) {
    this.parent = new Int32Array(size);
    this.sizes = new Int32Array(size).fill(1);
    this.inv = new Uint8Array(size);
    for (let i = 0; i < size; i++) this.parent[i] = i;
  }

  /** Root of the set containing `v`. */
  find(v: number): number {
    return this.canonify(v).root;
  }

  /** Root of the set containing `v` plus whether `v` is inverse to that root. */
  canonify(v: number): { root: number; inverse: boolean } {
    let inverse = 0;
    const start = v;
    // Find the root, accumulating inversions.
    while (this.parent[v] !== v) {
      inverse ^= this.inv[v];
      v = this.parent[v];
    }
    const root = v;
    // Path compression, keeping inversion flags consistent.
    let acc = inverse;
    v = start;
    while (this.parent[v] !== root && this.parent[v] !== v) {
      const next = this.parent[v];
      const myInv = this.inv[v];
      this.parent[v] = root;
      this.inv[v] = acc;
      acc ^= myInv;
      v = next;
    }
    return { root, inverse: inverse === 1 };
  }

  /** Merge the sets containing `a` and `b`. With `inverse` they are opposites. */
  merge(a: number, b: number, inverse = false): void {
    const ca = this.canonify(a);
    const cb = this.canonify(b);
    const wantInverse = inverse !== (ca.inverse !== cb.inverse);
    if (ca.root === cb.root) {
      if (wantInverse) throw new Error('DSF.merge: inconsistent inverse merge');
      return;
    }
    let ra = ca.root;
    let rb = cb.root;
    if (this.sizes[ra] < this.sizes[rb]) {
      const t = ra;
      ra = rb;
      rb = t;
    }
    this.parent[rb] = ra;
    this.inv[rb] = wantInverse ? 1 : 0;
    this.sizes[ra] += this.sizes[rb];
  }

  /** Whether `a` and `b` are in the same set. */
  same(a: number, b: number): boolean {
    return this.find(a) === this.find(b);
  }

  /** Number of elements in the set containing `v`. */
  sizeOf(v: number): number {
    return this.sizes[this.find(v)];
  }

  /** Number of distinct sets. */
  count(): number {
    let n = 0;
    for (let i = 0; i < this.size; i++) if (this.parent[i] === i) n++;
    return n;
  }

  clone(): DSF {
    const d = new DSF(this.size);
    d.parent.set(this.parent);
    d.sizes.set(this.sizes);
    d.inv.set(this.inv);
    return d;
  }
}
