import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { CELL_NEGATIVE, CELL_POSITIVE } from './board';
import type { MagnetsParams, MagnetsState } from './index';
import { DIFF_TRICKY } from './solver';

type C = typeof PALETTE;

function plus(c: C, cx: number, cy: number, r: number, w: number): string {
  return `<path d="M${cx - r} ${cy} H${cx + r} M${cx} ${cy - r} V${cy + r}" stroke="${c.red}" stroke-width="${w}" stroke-linecap="round"/>`;
}

function minus(c: C, cx: number, cy: number, r: number, w: number): string {
  return `<path d="M${cx - r} ${cy} H${cx + r}" stroke="${c.blue}" stroke-width="${w}" stroke-linecap="round"/>`;
}

/** A lying domino filled in as a magnet, `+` on the left. */
function magnet(c: C, x: number, y: number, s: number): string {
  return (
    `<rect x="${x}" y="${y}" width="${2 * s}" height="${s}" rx="${s / 6}" fill="${c.paper}" stroke="${c.ink}" stroke-width="5"/>` +
    `<path d="M${x + s} ${y + s * 0.18} V${y + s * 0.82}" stroke="${c.pencil}" stroke-width="2.5" stroke-dasharray="3 3"/>` +
    plus(c, x + s / 2, y + s / 2, s * 0.24, 6) +
    minus(c, x + 1.5 * s, y + s / 2, s * 0.24, 6)
  );
}

/** Some cell went straight from `+` to `−` or back: a magnet was turned round. */
function flipped(history: readonly MagnetsState[]): boolean {
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].cells;
    const b = history[k].cells;
    for (let i = 0; i < a.length; i++) {
      if (
        (a[i] === CELL_POSITIVE && b[i] === CELL_NEGATIVE) ||
        (a[i] === CELL_NEGATIVE && b[i] === CELL_POSITIVE)
      )
        return true;
    }
  }
  return false;
}

export const achievements = defineAchievements<MagnetsParams, MagnetsState>([
  {
    id: 'no-flips',
    name: 'Right Way Round',
    description: 'Solve an 8×7 Magnets or larger without ever flipping a magnet round.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      magnet(c, 18, 50, 32) +
      // The turn-it-round arrow, struck out.
      `<path d="M66 40 Q50 16 34 40" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round"/>` +
      `<path d="M43 37 L34 40.5 L33.5 31" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>` +
      `<path d="M38 18 L62 42" stroke="${c.red}" stroke-width="6" stroke-linecap="round"/>`,
    test: (ctx) => ctx.params.w * ctx.params.h >= 56 && !flipped(ctx.history),
  },
  {
    id: 'stripped',
    name: 'Bare Wires',
    description: 'Solve a 10×9 Hard Magnets with stripped clues in under ten minutes.',
    tier: 'gold',
    hue: 'red',
    art: (c) =>
      // A horseshoe magnet: ink edge, red body, paper poles marked + and −.
      `<path d="M34 34 V58 A16 16 0 0 0 66 58 V34" fill="none" stroke="${c.ink}" stroke-width="19"/>` +
      `<path d="M34 34 V58 A16 16 0 0 0 66 58 V34" fill="none" stroke="${c.red}" stroke-width="10"/>` +
      `<path d="M34 20 V40 M66 20 V40" stroke="${c.ink}" stroke-width="19"/>` +
      `<path d="M34 24 V35 M66 24 V35" stroke="${c.paper}" stroke-width="10"/>` +
      plus(c, 34, 29.5, 3.2, 3) +
      minus(c, 66, 29.5, 3.2, 3) +
      // Fizzing with pull.
      `<path d="M44 22 L48 30 M56 22 L52 30 M50 18 V28" stroke="${c.ink}" stroke-width="3.5" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 10 &&
      ctx.params.h >= 9 &&
      ctx.params.strip &&
      ctx.params.diff >= DIFF_TRICKY &&
      ctx.secs < 600,
  },
]);
