import { touchPhraseMap } from '../i18n';

/**
 * Mouse wording rewritten for touch screens. The pairs come from the active locale's
 * `touchPhrases` list (see `docs/I18N.md`); English is the list the collection was written
 * against. Order matters: longer phrases first, so "right-click" never gets mangled by
 * the plain "click" rule.
 *
 * Deliberately conservative — whole words only, and never inside a `code span`. A locale
 * that supplies no list leaves the text exactly as its translator wrote it, which is far
 * better than applying English word rules to another language.
 */
const cache = new Map<string, [RegExp, string][]>();

/** Scripts that do not separate words with spaces. Korean does, so Hangul is not here. */
const UNSPACED = /[\p{sc=Han}\p{sc=Hiragana}\p{sc=Katakana}\p{sc=Thai}]/u;

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function phraseRules(
  pairs: readonly (readonly [string, string])[] | null | undefined,
): [RegExp, string][] {
  if (!pairs?.length) return [];
  const sig = JSON.stringify(pairs);
  let rules = cache.get(sig);
  if (!rules) {
    // Plain `\b` is ASCII-only, so it never matches at the edge of a phrase that starts
    // or ends on an Arabic, Thai, Japanese, Korean, etc. character. Unicode-aware
    // lookaround (letter/number/underscore on either side) works for every script; the
    // `u` flag is required for `\p{...}` classes. Scripts written without spaces between
    // words (Japanese, Thai) have no word edge to find — "クリックして" is one run of
    // letters — so a phrase edge in one of them is matched without the lookaround.
    rules = pairs.map(([from, to]) => {
      const before = UNSPACED.test(from[0]) ? '' : '(?<![\\p{L}\\p{N}_])';
      const after = UNSPACED.test(from[from.length - 1]) ? '' : '(?![\\p{L}\\p{N}_])';
      return [new RegExp(`${before}${escapeRe(from)}${after}`, 'giu'), to];
    });
    cache.set(sig, rules);
  }
  return rules;
}

/** Copy the capitalisation of `from` onto `to` (first letter only). */
function matchCase(from: string, to: string): string {
  if (!from || !to) return to;
  const first = from[0];
  if (first === first.toLowerCase()) return to;
  return to[0].toUpperCase() + to.slice(1);
}

/** Run `fn` over the parts of `md` that are not inside a `code span`. */
function outsideCode(md: string, fn: (s: string) => string): string {
  return md
    .split(/(`[^`\n]*`)/g)
    .map((part, i) => (i % 2 === 1 ? part : fn(part)))
    .join('');
}

/**
 * Rewrite mouse wording for touch devices ("right-click" → "long-press", "click" → "tap").
 * Case is preserved and `code spans` are left alone, so key names survive.
 */
export function touchPhrasing(md: string): string {
  return touchPhrasingWith(md, touchPhraseMap());
}

/**
 * `touchPhrasing` with an explicit phrase list instead of the active locale's, so a test
 * can see what every language's text turns into on a phone without switching locale.
 */
export function touchPhrasingWith(
  md: string,
  pairs: readonly (readonly [string, string])[] | null | undefined,
): string {
  const rules = phraseRules(pairs);
  if (!rules.length) return md;
  return outsideCode(md, (text) => {
    let out = text;
    for (const [re, to] of rules) {
      out = out.replace(re, (m) => matchCase(m, to));
    }
    return out;
  });
}

const KEYBOARD_HEADING = /\bkeyboards?\b/i;

/**
 * Drop every section whose heading mentions the keyboard: the heading itself plus
 * everything up to the next heading of the same or a higher level. Used on touch devices,
 * where a keyboard section is noise.
 */
export function stripKeyboardSections(md: string): string {
  const lines = md.replace(/\r\n?/g, '\n').split('\n');
  const out: string[] = [];
  let dropUntilLevel = 0; // 0 = not dropping
  let fence = false;
  for (const line of lines) {
    if (/^\s*```/.test(line)) fence = !fence;
    const h = !fence && /^(#{1,6})\s+(.*)$/.exec(line);
    if (h) {
      const level = h[1].length;
      if (dropUntilLevel && level <= dropUntilLevel) dropUntilLevel = 0;
      if (!dropUntilLevel && KEYBOARD_HEADING.test(h[2])) {
        dropUntilLevel = level;
        continue;
      }
    }
    if (!dropUntilLevel) out.push(line);
  }
  return (
    out
      .join('\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim() + '\n'
  );
}

/**
 * A translated help page marks its keyboard section as `### Toetsenbord (Keyboard)`, so
 * {@link stripKeyboardSections} finds it in any language. The marker is for the stripper,
 * not the reader: once a section has survived (on a desktop), the English in brackets is
 * taken off the heading it would otherwise be printed in.
 */
export function hideKeyboardMarker(md: string): string {
  return md.replace(/^(#{1,6}[ \t]+\S.*?)[ \t]*\(keyboards?\)[ \t]*$/gim, '$1');
}

export interface MarkdownOptions {
  /** Remove sections under a heading that mentions "Keyboard" (see `stripKeyboardSections`). */
  dropKeyboard?: boolean;
  /** Rewrite mouse wording for fingers (see `touchPhrasing`). */
  touch?: boolean;
}

/** A deliberately tiny markdown renderer for help text (headings, lists, emphasis). */
export function renderMarkdown(md: string, opts: MarkdownOptions = {}): string {
  if (opts.dropKeyboard) md = stripKeyboardSections(md);
  md = hideKeyboardMarker(md);
  if (opts.touch) md = touchPhrasing(md);
  const esc = (s: string) =>
    s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const inline = (s: string) =>
    esc(s)
      .replace(/`([^`]+)`/g, '<kbd>$1</kbd>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*]+)\*/g, '<em>$1</em>')
      .replace(/(^|[\s(])_([^_\n]+)_(?=[\s).,;:!?\-–—'’/]|$)/g, '$1<em>$2</em>');

  const lines = md.replace(/\r\n?/g, '\n').split('\n');
  const out: string[] = [];
  let para: string[] = [];
  let list: string[] | null = null;
  let listType: 'ul' | 'ol' = 'ul';

  const flushPara = () => {
    if (para.length) {
      out.push(`<p>${inline(para.join(' '))}</p>`);
      para = [];
    }
  };
  const flushList = () => {
    if (list) {
      out.push(`<${listType}>${list.map((li) => `<li>${inline(li)}</li>`).join('')}</${listType}>`);
      list = null;
    }
  };

  for (const raw of lines) {
    const line = raw.trimEnd();
    const h = /^(#{1,4})\s+(.*)$/.exec(line);
    const li = /^\s*[-*]\s+(.*)$/.exec(line);
    const oli = /^\s*\d+[.)]\s+(.*)$/.exec(line);
    if (!line.trim()) {
      flushPara();
      flushList();
    } else if (h) {
      flushPara();
      flushList();
      const level = Math.min(4, h[1].length + 1);
      out.push(`<h${level}>${inline(h[2])}</h${level}>`);
    } else if (li || oli) {
      flushPara();
      const type = li ? 'ul' : 'ol';
      if (list && listType !== type) flushList();
      if (!list) {
        list = [];
        listType = type;
      }
      list.push((li ?? oli)![1]);
    } else if (list && /^\s{2,}/.test(raw)) {
      list[list.length - 1] += ' ' + line.trim();
    } else {
      flushList();
      para.push(line.trim());
    }
  }
  flushPara();
  flushList();
  return out.join('\n');
}
