import type { Tutorial, TutorialCtx } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { LineMove, NetslideState, NetslideUI } from './index';

type Ctx = TutorialCtx<NetslideState, NetslideUI>;
type Cell = { x: number; y: number };

/** The arrow strip is one tile wide all the way round, so the border *is* the tile size. */
const border = (t: number) => t;

/**
 * Spotlight one cell of the arrow ring and point at it. `cell` is in grid coordinates, so
 * -1 and w/h pick out the arrows, and it is read from the state so "the bottom row" stays
 * the bottom row.
 */
function arrow(cell: (s: NetslideState) => Cell, button?: 'right') {
  return {
    highlight: ({ state, tileSize }: Ctx) => {
      const c = cell(state);
      return cellRect(c.x, c.y, tileSize, border(tileSize));
    },
    pointer: ({ state, tileSize }: Ctx) => {
      const c = cell(state);
      return {
        ...cellCentre(c.x, c.y, tileSize, border(tileSize)),
        ...(button ? { button } : {}),
      };
    },
  };
}

/** True once the last completed move was exactly the slide we asked for. */
function slid(state: NetslideState, want: LineMove): boolean {
  const l = state.last;
  return !!l && l.row === want.row && l.index === want.index && l.dir === want.dir;
}

export const tutorial: Tutorial<NetslideState, NetslideUI> = {
  steps: [
    {
      gameId: '3x3:1dc176415',
      text: 'Every piece of wire has to end up joined to the power source. Blue wires are live, grey pencil ones are not.',
      highlight: ({ state, tileSize }) =>
        cellRect(-1, -1, tileSize, border(tileSize), state.w + 2, state.h + 2),
    },
    {
      text: 'The source sits on the middle tile. That tile never moves, so the middle row and column have no arrows — everything else slides round.',
      highlight: ({ state, tileSize }) => cellRect(state.cx, state.cy, tileSize, border(tileSize)),
    },
    {
      text: 'Click the arrow to the **left of the bottom row** to slide that row one step left; the wire that falls off reappears on the right.',
      ...arrow((s) => ({ x: -1, y: s.h - 1 })),
      waitFor: ({ state }) => slid(state, { row: true, index: state.h - 1, dir: -1 }),
    },
    {
      text: 'The bottom row joins up now, but it is still grey: nothing links it upwards to the source yet.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, state.h - 1, tileSize, border(tileSize), state.w, 1),
    },
    {
      text: '**Right-click** the arrow **above the third column**. A right-click reverses an arrow, so that column slides down and the last wires light up.',
      ...arrow((s) => ({ x: s.w - 1, y: -1 }), 'right'),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'All live! **Solve** shows an answer if you get stuck, and the **Type** menu has wrapping grids where wires run off one edge onto the other.',
      target: '[data-cmd="solve"]',
    },
  ],
};
