import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { WHITE } from './board';
import type { RangeParams, RangeState } from './index';

type C = typeof PALETTE;

/** Hand-lettered digits, as strokes in a box about 10 wide and 14 high round (0, 0). */
const DIGITS: Record<number, string> = {
  2: 'M-4.5 -4 Q-4 -7.5 0 -7.5 Q4.5 -7.5 4.5 -3.5 Q4.5 -0.5 -4.5 7 H5',
  3: 'M-4.5 -6 Q0 -9.5 4 -5.5 Q5 -1.5 0 -0.5 Q5 0 4.8 3.8 Q3.5 8.5 -4.5 6',
  4: 'M2.5 7.5 V-7.5 L-5 3 H5.5',
  5: 'M4.5 -7 H-3 L-4 -0.8 Q0 -3 3.6 -0.8 Q5.5 2.5 3.4 5.6 Q0 8.8 -4.5 6',
};

function digit(c: C, n: number, cx: number, cy: number, s: number, colour: string = c.ink): string {
  return `<path d="${DIGITS[n]}" transform="translate(${cx} ${cy}) scale(${s})" fill="none" stroke="${colour}" stroke-width="${(2.6 / s).toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>`;
}

/** An `n`×`n` Range grid of cell size `s` from (x, y), with the given squares black. */
function grid(c: C, x: number, y: number, n: number, s: number, black: [number, number][]): string {
  let lines = '';
  for (let i = 1; i < n; i++)
    lines += `M${x + i * s} ${y} V${y + n * s} M${x} ${y + i * s} H${x + n * s} `;
  return (
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" fill="${c.paper}"/>` +
    black
      .map(
        ([bx, by]) =>
          `<rect x="${x + bx * s}" y="${y + by * s}" width="${s}" height="${s}" fill="${c.ink}"/>`,
      )
      .join('') +
    `<path d="${lines}" stroke="${c.ink}" stroke-width="2"/>` +
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>`
  );
}

export const achievements = defineAchievements<RangeParams, RangeState>([
  {
    id: 'no-dots',
    name: 'Pure Contrast',
    description: 'Solve a 13×9 Range or larger without placing a single dot.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      grid(c, 17, 17, 4, 14, [
        [1, 0],
        [3, 1],
        [0, 2],
        [2, 3],
      ]) +
      digit(c, 3, 24, 24, 0.8) +
      digit(c, 5, 38, 52, 0.8) +
      // The dot nobody needed, on a sticker in the corner.
      `<circle cx="72" cy="72" r="12" fill="${c.paper}" stroke="${c.red}" stroke-width="4.5"/>` +
      `<circle cx="72" cy="72" r="4" fill="${c.pencil}"/>` +
      `<path d="M63.5 80.5 L80.5 63.5" stroke="${c.red}" stroke-width="4.5" stroke-linecap="round"/>`,
    // A dot never finishes a grid, so the last board (Solve dots every white square) is
    // left out, as the winning move in Mines is.
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 13 * 9 &&
      ctx.history.slice(0, -1).every((s) => !s.grid.includes(WHITE)),
  },
  {
    id: 'quick-sight',
    name: 'Quick Sight',
    description: 'Solve a 16×11 Range in under five minutes.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) =>
      grid(c, 18, 18, 5, 12.8, [
        [2, 0],
        [0, 2],
        [4, 2],
        [2, 4],
      ]) +
      // The number and the lines of sight it counts, running out until a black square.
      `<path d="M50 42 V33 M50 58 V67 M42 50 H33 M58 50 H67" stroke="${c.accent}" stroke-width="4.5" stroke-linecap="round"/>` +
      `<path d="M45 36 L50 31 L55 36 M45 64 L50 69 L55 64 M36 45 L31 50 L36 55 M64 45 L69 50 L64 55" fill="none" stroke="${c.accent}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>` +
      digit(c, 5, 50, 50, 0.72),
    test: (ctx) => ctx.params.w >= 16 && ctx.params.h >= 11 && ctx.secs < 300,
  },
]);
