/**
 * Maximum bipartite matching by augmenting paths (Kuhn's algorithm). The graphs here are
 * tiny (a few hundred vertices of degree at most four), so the simple O(V·E) method is
 * plenty and easy to reason about.
 */

export interface Matching {
  /** Number of matched pairs. */
  size: number;
  /** Right vertex matched to each left vertex, or -1. */
  matchL: Int32Array;
  /** Left vertex matched to each right vertex, or -1. */
  matchR: Int32Array;
}

/**
 * Try to match left vertex `l` by finding an augmenting path. Right vertices with
 * `forbidden[r]` set are skipped. Returns true and updates the matching on success.
 */
export function augment(
  l: number,
  adj: number[][],
  matchL: Int32Array,
  matchR: Int32Array,
  seen: Uint8Array,
  forbidden?: Uint8Array,
): boolean {
  for (const r of adj[l]) {
    if (seen[r] || (forbidden && forbidden[r])) continue;
    seen[r] = 1;
    if (matchR[r] < 0 || augment(matchR[r], adj, matchL, matchR, seen, forbidden)) {
      matchL[l] = r;
      matchR[r] = l;
      return true;
    }
  }
  return false;
}

/** A maximum matching. `adj[l]` lists the right vertices adjacent to left vertex `l`. */
export function maxMatching(nLeft: number, nRight: number, adj: number[][]): Matching {
  const matchL = new Int32Array(nLeft).fill(-1);
  const matchR = new Int32Array(nRight).fill(-1);
  const seen = new Uint8Array(nRight);
  let size = 0;
  for (let l = 0; l < nLeft; l++) {
    seen.fill(0);
    if (augment(l, adj, matchL, matchR, seen)) size++;
  }
  return { size, matchL, matchR };
}
