import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { LINE_NO, LINE_YES } from './board';
import type { LoopyParams } from './generator';
import { GRID_PENROSE_P2, GRID_PENROSE_P3, GRID_SQUARE } from './grid';
import type { LoopyState } from './index';

type C = typeof PALETTE;

const f = (v: number) => v.toFixed(1);

function dots(c: C, pts: [number, number][], r: number): string {
  return pts
    .map(([x, y]) => `<circle cx="${f(x)}" cy="${f(y)}" r="${r}" fill="${c.ink}"/>`)
    .join('');
}

function loop(c: C, pts: [number, number][], colour: string, w: number): string {
  const d = pts.map(([x, y], i) => `${i ? 'L' : 'M'}${f(x)} ${f(y)}`).join(' ') + ' Z';
  return `<path d="${d}" fill="none" stroke="${colour}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`;
}

/** Three hexagons of a honeycomb, with the loop running round the outside of all three. */
function honeycomb(c: C): string {
  const R = 15;
  const dx = (R * Math.sqrt(3)) / 2;
  const centres: [number, number][] = [
    [50 - dx, 39],
    [50 + dx, 39],
    [50, 39 + 1.5 * R],
  ];
  const hex = ([cx, cy]: [number, number]): [number, number][] =>
    [-90, -30, 30, 90, 150, 210].map((a) => {
      const r = (a * Math.PI) / 180;
      return [cx + Math.cos(r) * R, cy + Math.sin(r) * R];
    });
  const [a, b, h] = centres.map(hex);
  // Vertices 0..5 run top, upper right, lower right, bottom, lower left, upper left.
  const outline = [a[0], a[1], b[0], b[1], b[2], b[3], h[2], h[3], h[4], h[5], a[4], a[5]];
  const inner = `M${f(a[1][0])} ${f(a[1][1])} V${f(a[2][1])} L${f(a[3][0])} ${f(a[3][1])} M${f(a[2][0])} ${f(a[2][1])} L${f(b[3][0])} ${f(b[3][1])}`;
  return (
    `<path d="${inner}" fill="none" stroke="${c.pencil}" stroke-width="2.5"/>` +
    loop(c, outline, c.ink, 6) +
    dots(c, [...a, ...b, ...h], 4.2)
  );
}

/** Five fat rhombs round a point, the Penrose "sun", and the loop round its star. */
function penrose(c: C): string {
  const s = 19;
  const cx = 50;
  const cy = 51;
  const at = (deg: number, r: number): [number, number] => {
    const a = ((deg - 90) * Math.PI) / 180;
    return [cx + Math.cos(a) * r, cy + Math.sin(a) * r];
  };
  const tip = 2 * s * Math.cos(Math.PI / 5);
  let rhombs = '';
  const star: [number, number][] = [];
  for (let k = 0; k < 5; k++) {
    const t = k * 72;
    const p = [[cx, cy] as [number, number], at(t - 36, s), at(t, tip), at(t + 36, s)];
    const d = p.map(([x, y], i) => `${i ? 'L' : 'M'}${f(x)} ${f(y)}`).join(' ') + ' Z';
    rhombs += `<path d="${d}" fill="${k % 2 ? c.paper : c.shade}" stroke="${c.pencil}" stroke-width="2.5" stroke-linejoin="round"/>`;
    star.push(at(t - 36, s), at(t, tip));
  }
  return rhombs + loop(c, star, c.ink, 5.5) + dots(c, [[cx, cy], ...star], 2.8);
}

/** A pencilled "no line here" cross inside a red no-entry ring. */
function noCross(c: C, cx: number, cy: number, r: number): string {
  const k = r * 0.42;
  const q = r * 0.7;
  return (
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.paper}" stroke="${c.red}" stroke-width="4"/>` +
    `<path d="M${cx - k} ${cy - k} L${cx + k} ${cy + k} M${cx + k} ${cy - k} L${cx - k} ${cy + k}" stroke="${c.pencil}" stroke-width="3" stroke-linecap="round"/>` +
    `<path d="M${cx - q} ${cy + q} L${cx + q} ${cy - q}" stroke="${c.red}" stroke-width="4" stroke-linecap="round"/>`
  );
}

/** Whether some line, once drawn, was ever taken off again (or crossed out over). */
function removedALine(history: readonly LoopyState[]): boolean {
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].lines;
    const b = history[k].lines;
    for (let e = 0; e < a.length; e++) if (a[e] === LINE_YES && b[e] !== LINE_YES) return true;
  }
  return false;
}

export const achievements = defineAchievements<LoopyParams, LoopyState>([
  {
    id: 'off-grid',
    name: 'Off the Grid',
    description: 'Solve a Loopy on any tiling other than squares.',
    tier: 'bronze',
    hue: 'teal',
    art: (c) => honeycomb(c),
    test: (ctx) => ctx.params.type !== GRID_SQUARE,
  },
  {
    id: 'no-crosses',
    name: 'Just the Loop',
    description: 'Solve a 10×10 Loopy without crossing out a single edge.',
    tier: 'silver',
    hue: 'blue',
    art: (c) => {
      const grid: [number, number][] = [];
      for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) grid.push([20 + x * 20, 20 + y * 20]);
      const path: [number, number][] = [
        [20, 20],
        [60, 20],
        [60, 40],
        [80, 40],
        [80, 80],
        [40, 80],
        [40, 60],
        [20, 60],
      ];
      return loop(c, path, c.ink, 6) + dots(c, grid, 4.4) + noCross(c, 29, 71, 8.5);
    },
    test: (ctx) =>
      ctx.params.w >= 10 &&
      ctx.params.h >= 10 &&
      ctx.history.every((s) => !s.lines.includes(LINE_NO)),
  },
  {
    id: 'aperiodic',
    name: 'Aperiodic',
    description: 'Solve a Penrose Loopy without ever removing a line you drew.',
    tier: 'gold',
    hue: 'purple',
    art: (c) => penrose(c),
    test: (ctx) =>
      (ctx.params.type === GRID_PENROSE_P2 || ctx.params.type === GRID_PENROSE_P3) &&
      !removedALine(ctx.history),
  },
]);
