/**
 * Mine layout generation.
 *
 * Mines are scattered at random, keeping the 3×3 block around the first click clear so
 * that click always opens an empty region. When the puzzle must be solvable without
 * guessing, the solver is then run from that opening square; whenever it gets stuck it
 * asks `perturb` to shuffle mines between the set it is stuck on and squares elsewhere
 * (preferring unexplored territory) so that the set becomes decidable. The whole thing
 * is repeated from scratch until the solver finishes a pass with no help at all.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { MINE, UNKNOWN, solveMines } from './solver';
import type { Perturbation } from './solver';

interface GenContext {
  w: number;
  h: number;
  mines: Uint8Array;
  sx: number;
  sy: number;
  rng: Random;
  /** Allow perturbing the whole unexplored area (only after many failed attempts). */
  allowBig: boolean;
}

/** Number of mines around (x, y). */
export function countAround(mines: Uint8Array, w: number, h: number, x: number, y: number): number {
  let n = 0;
  for (let dy = -1; dy <= 1; dy++) {
    const ny = y + dy;
    if (ny < 0 || ny >= h) continue;
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx;
      if (nx < 0 || nx >= w || (dx === 0 && dy === 0)) continue;
      if (mines[ny * w + nx]) n++;
    }
  }
  return n;
}

function openAt(ctx: GenContext, x: number, y: number): number {
  if (ctx.mines[y * ctx.w + x]) return -1;
  return countAround(ctx.mines, ctx.w, ctx.h, x, y);
}

/**
 * Move mines so that the given set (mask 0 = every unknown square) becomes all-mine or
 * all-clear without changing the total. Squares are taken from, in order of preference,
 * unknown squares bordering explored space, unknown squares further out, and finally
 * known squares (never within one square of the start). Updates the solver's `grid`
 * so its knowledge stays truthful, and returns the list of changed squares.
 */
function perturb(
  ctx: GenContext,
  grid: Int8Array,
  setX: number,
  setY: number,
  mask: number,
): Perturbation[] | null {
  const { w, h, mines, rng } = ctx;
  if (!mask && !ctx.allowBig) return null;

  const inSet = (x: number, y: number) =>
    mask === 0
      ? grid[y * w + x] === UNKNOWN
      : x >= setX &&
        x < setX + 3 &&
        y >= setY &&
        y < setY + 3 &&
        (mask & (1 << ((y - setY) * 3 + (x - setX)))) !== 0;

  // Candidate squares outside the set, grouped by preference and shuffled within groups
  // (a random key each, in reading order). Only as many groups are sorted as the walk
  // below needs: usually the frontier alone, which on a big grid is a small part of it.
  const groups: number[][] = [[], [], []];
  const keys = new Float64Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (Math.abs(y - ctx.sy) <= 1 && Math.abs(x - ctx.sx) <= 1) continue;
      if (inSet(x, y)) continue;
      let type = 3;
      if (grid[y * w + x] === UNKNOWN) {
        type = 2;
        outer: for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h && grid[ny * w + nx] !== UNKNOWN) {
              type = 1;
              break outer;
            }
          }
        }
      }
      keys[y * w + x] = rng.next();
      groups[type - 1].push(y * w + x);
    }
  }

  // Squares of the set itself, and how many of them hold mines.
  const setSquares: number[] = [];
  if (mask) {
    for (let dy = 0; dy < 3; dy++)
      for (let dx = 0; dx < 3; dx++)
        if (mask & (1 << (dy * 3 + dx))) setSquares.push((setY + dy) * w + (setX + dx));
  } else {
    for (let i = 0; i < w * h; i++) if (grid[i] === UNKNOWN) setSquares.push(i);
  }
  let nFull = 0;
  for (const i of setSquares) if (mines[i]) nFull++;
  const nEmpty = setSquares.length - nFull;

  // Walk the candidates until we have either enough empty squares to take all the set's
  // mines, or enough mines to fill all the set's empty squares.
  const toFill: number[] = [];
  const toEmpty: number[] = [];
  walk: for (const group of groups) {
    group.sort((a, b) => keys[a] - keys[b]);
    for (const i of group) {
      if (mines[i]) toEmpty.push(i);
      else toFill.push(i);
      if (toFill.length === nFull || toEmpty.length === nEmpty) break walk;
    }
  }

  const changes: Perturbation[] = [];
  const at = (i: number, delta: 1 | -1): Perturbation => ({
    x: i % w,
    y: Math.floor(i / w),
    delta,
  });
  if (toFill.length === nFull) {
    // Empty the set: its mines move out to the chosen empty squares.
    for (const i of toFill) changes.push(at(i, 1));
    for (const i of setSquares) if (mines[i]) changes.push(at(i, -1));
  } else if (toEmpty.length === nEmpty) {
    // Fill the set: the chosen outside mines move into its empty squares.
    for (const i of toEmpty) changes.push(at(i, -1));
    for (const i of setSquares) if (!mines[i]) changes.push(at(i, 1));
  } else {
    // Not enough room either way (very dense grids): fill as much of the set as the
    // available outside mines allow, choosing which of its empty squares at random.
    if (toEmpty.length === 0) return null;
    const empties = setSquares.filter((i) => !mines[i]);
    for (let k = 0; k < toEmpty.length; k++) {
      const j = k + rng.upto(empties.length - k);
      const t = empties[k];
      empties[k] = empties[j];
      empties[j] = t;
    }
    for (const i of toEmpty) changes.push(at(i, -1));
    for (let k = 0; k < toEmpty.length; k++) changes.push(at(empties[k], 1));
  }
  if (changes.length === 0) return null;

  // Apply to the hidden grid, and keep every known number in the solver's grid right.
  for (const c of changes) {
    const i = c.y * w + c.x;
    mines[i] = c.delta > 0 ? 1 : 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        const nx = c.x + dx;
        const ny = c.y + dy;
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        const j = ny * w + nx;
        if (grid[j] === UNKNOWN) continue;
        if (dx === 0 && dy === 0) grid[j] = c.delta > 0 ? MINE : countAround(mines, w, h, nx, ny);
        else if (grid[j] >= 0) grid[j] += c.delta;
      }
    }
  }
  return changes;
}

/** Attempts from scratch before we settle for whatever random layout comes next. */
const MAX_TRIES = 3000;
/**
 * Squares tried (layouts times grid size) before big perturbations are allowed. The
 * original allows them after 100 layouts; that is this much work on a 30×16 grid, and
 * the same work on a bigger grid lets them in sooner. On 50×50 at 35–45% mines almost no
 * layout comes out without them, and 100 failures of a tenth of a second each froze
 * the first click for 12–19 seconds.
 */
const BIG_PERTURB_WORK = 100 * 30 * 16;
/** Solver passes over one candidate layout before starting afresh. */
const MAX_PASSES = 60;
/**
 * Solver passes times grid size, in all, before we settle for the layout in hand. Strips
 * three or four squares wide at 25–40% mines hardly ever settle: each pass needs big
 * perturbations, which move mines into squares already opened, so the next pass goes
 * differently again, and 40 000 passes (10 seconds) were seen on 3×50. Every other grid
 * stays well below this; a slow 50×50 at 40% takes about a third of it.
 */
const MAX_WORK = 1_000_000;

/**
 * Generate a layout of `n` mines for a `w`×`h` grid whose first click at (sx, sy) opens
 * an empty square. With `unique`, the layout is also fully deducible from that opening
 * without guessing. Deterministic in `rng`.
 */
export function generateLayout(
  w: number,
  h: number,
  n: number,
  sx: number,
  sy: number,
  unique: boolean,
  rng: Random,
): Uint8Array {
  const wh = w * h;
  const mines = new Uint8Array(wh);
  const spots: number[] = [];
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++)
      if (Math.abs(y - sy) > 1 || Math.abs(x - sx) > 1) spots.push(y * w + x);
  if (n > spots.length) throw new Error(tx`Too many mines for grid size`);

  let work = 0;
  for (let tries = 1; ; tries++) {
    // Pick n distinct admissible squares.
    mines.fill(0);
    const pool = spots.slice();
    let k = pool.length;
    for (let left = n; left > 0; left--) {
      const i = rng.upto(k);
      mines[pool[i]] = 1;
      pool[i] = pool[--k];
    }
    if (!unique || tries > MAX_TRIES) return mines;

    const allowBig = tries > 100 || tries * wh > BIG_PERTURB_WORK;
    const ctx: GenContext = { w, h, mines, sx, sy, rng, allowBig };
    const knowledge = new Int8Array(wh);
    const open = (x: number, y: number) => openAt(ctx, x, y);
    const perturbFn = (grid: Int8Array, x: number, y: number, mask: number) =>
      perturb(ctx, grid, x, y, mask);
    for (let pass = 0; pass < MAX_PASSES; pass++) {
      knowledge.fill(UNKNOWN);
      knowledge[sy * w + sx] = openAt(ctx, sx, sy);
      work += wh;
      const ret = solveMines(w, h, n, knowledge, open, perturbFn, rng);
      if (ret === 0) return mines;
      if (ret < 0) break;
    }
    // Out of time: the perturbed layout has had the most straightening, so it is the one
    // nearest to solvable.
    if (work > MAX_WORK) return mines;
  }
}

/** True if the layout can be solved from (sx, sy) by deduction alone. */
export function isSolvableFrom(
  mines: Uint8Array,
  w: number,
  h: number,
  sx: number,
  sy: number,
): boolean {
  if (mines[sy * w + sx]) return false;
  const knowledge = new Int8Array(w * h).fill(UNKNOWN);
  knowledge[sy * w + sx] = countAround(mines, w, h, sx, sy);
  let n = 0;
  for (let i = 0; i < mines.length; i++) if (mines[i]) n++;
  const open = (x: number, y: number) => (mines[y * w + x] ? -1 : countAround(mines, w, h, x, y));
  return solveMines(w, h, n, knowledge, open) === 0;
}
