import '@fontsource/patrick-hand';
import '@fontsource/patrick-hand-sc';
import './ui/styles.css';
import './ui/toolbar.css';
import './ui/endgame.css';
// The desk and the sheet the board lies on; after the shared sheets it restyles.
import './ui/play.css';
import './ui/celebrate.css';
import './ui/achievements.css';
import './ui/welcome.css';
// After `styles.css`, which it deliberately overrides on the menu's phone layout.
import './ui/menu-mobile.css';
// The play page's HUD and pause menu; last, since it restyles the toolbar in every layout.
import './ui/hud.css';
// The collection and the achievements as fixed screens that turn pages.
import './ui/shelf.css';
// The desk under every screen and the box the collection lies in; last, it restyles both.
import './ui/desk.css';
// The menu's resource bar, Continue and the round back buttons; then the Settings card.
import './ui/resource-bar.css';
import './ui/settings.css';
// The browser's own cursors, tooltips, dropdowns and selection, drawn in the game's hand.
import './ui/feel.css';
// The selector the arrow keys and a controller move around the menus.
import './ui/nav.css';
import { initAnalytics } from './analytics';
import { loadingStart, loadingStop, platformLocale } from './crazygames';
import { injectPaletteCSS } from './framework/palette';
import { setZiggyEnabled, setZiggyEyes, setZiggyShape } from './framework/ziggy';
import type { EyeId, ShapeId } from './framework/ziggy';
import { adoptPlatformLocale, applyLocaleToDocument, loadLocaleCatalog } from './i18n';
import { applyBrandToDocument } from './ui/brand';
import { installAdPause } from './ui/adPause';
import { installAchievementToasts } from './ui/achievementToast';
import { reportVisit, watchProgressForAchievements } from './achievements';
import { parseHash, startApp } from './ui/app';
import { startSketchVariety } from './ui/sketchVariety';
import { installGameFeel } from './ui/gameFeel';
import { installNav } from './ui/nav';
import { installGamepad } from './ui/gamepad';
import { installPress } from './ui/press';
import { markDeviceOnRoot } from './ui/device';
import { showSplash } from './ui/splash';
import { liftBootScreenWhenReady } from './ui/boot';

// Bracket the whole boot sequence: on CrazyGames this measures the game's loading
// footprint and tells the platform when to hand off from its own loader. A no-op
// everywhere else (see src/crazygames/index.ts).
loadingStart();
injectPaletteCSS();
// The tab icon and the browser chrome's colour come from the same mark and the same
// palette as everything else on the page (see src/ui/brand.ts).
applyBrandToDocument();
// The mascot, on or off, decided once for the whole page. `?ziggy=1` / `?ziggy=0` beats the
// stored preference, so the same build can be loaded side by side for comparison.
setZiggyEnabled(
  (() => {
    try {
      const q = new URLSearchParams(location.search).get('ziggy');
      if (q !== null) return q !== '0' && q !== 'false';
      // On unless somebody has deliberately turned him off.
      return localStorage.getItem('puzzlebox:ziggy') !== '0';
    } catch {
      return true;
    }
  })(),
);
// Which drawing of him. Shape and eyes are separate choices, so they are separate
// parameters: `?ziggyShape=s1…s4` and `?ziggyEyes=e1…e6`.
try {
  const q = new URLSearchParams(location.search);
  const shape = q.get('ziggyShape');
  const eyes = q.get('ziggyEyes');
  if (shape) setZiggyShape(shape as ShapeId);
  if (eyes) setZiggyEyes(eyes as EyeId);
} catch {
  /* no URL to read: leave the defaults */
}
// `<html lang>`/`<html dir>` first, so an Arabic page is laid out right to left from the
// very first frame, before there is anything in it to mirror.
applyLocaleToDocument();
markDeviceOnRoot();

/**
 * Only the active language's strings are downloaded: English is in this bundle and every
 * other catalogue is a chunk of its own, so a Dutch player fetches Dutch and not the 23
 * languages they cannot read. Awaited before the app mounts, so the first paint is already
 * in the right language rather than flashing English and then correcting itself — the one
 * thing in the boot sequence that waits on the network, which is exactly what the
 * loadingStart()/loadingStop() bracket is for (see docs/CRAZYGAMES.md). For an English
 * player it resolves in the same tick and nothing has changed.
 */
async function boot(): Promise<void> {
  await loadLocaleCatalog();
  // Before mounting, not after: mounting routes, and routing reports gameplay. The SDK's
  // lifecycle is a sequence — loading, then play — and a gameplayStart() that overtakes
  // loadingStop() describes a game the platform still thinks is loading. Nothing is shown
  // any earlier for it: these calls are queued behind the SDK's own readiness, so the DOM
  // below is built and painted long before the platform hears about either.
  loadingStop();
  // Player analytics: a no-op unless the build is configured for it, and never able to
  // throw or wait on anything (see src/analytics).
  initAnalytics({ loadMs: Math.round(performance.now()) });
  const root = document.getElementById('app')!;
  // Read before the router runs: a link to a locked game is bounced to the menu with a
  // toast saying why, and the hash it leaves behind is the menu's — so asking afterwards
  // put the splash up over the one explanation the player was being given.
  const arrivedOnPuzzle = !!parseHash().slug;
  // Every sketched box gets its own wobble and pen weight (ui/sketchVariety.ts).
  startSketchVariety();
  // No URL previews, system tooltips, cursors, dropdowns or browser menus (ui/gameFeel.ts).
  installGameFeel();
  // Arrow keys move a selector around the menus like a console's; a pad drives the same.
  installNav();
  installGamepad();
  // Every control goes down when pressed, by a finger, a key or a mouse (ui/press.ts).
  installPress();
  startApp(root);
  // Ads arrive on top of the game with the page still live underneath; hold input back for
  // as long as one is up. A no-op anywhere no ad can play.
  installAdPause(root);
  // Achievements: the unlock card, the totals watched for unlocks, and today counted as a
  // day played. After the router, so the first page is up before any card comes down.
  installAchievementToasts();
  watchProgressForAchievements();
  reportVisit();
  // The splash belongs to the front door. Arriving straight into a puzzle — a shared game
  // ID, a bookmark, or the collection embedded one game at a time — means the player has
  // already chosen; two seconds of wordmark over the board is a second loading screen
  // after the portal's own.
  //
  // Nor inside someone else's page. An embedding portal has already shown its own loader,
  // and CrazyGames asks that a new player reach gameplay at once, or within one click: in
  // its frame the collection opens straight on the menu, where every starter puzzle is
  // that one click away.
  //
  // Without a splash, the loading screen (index.html, ui/boot.ts) stays up until the first
  // screen is drawn, and fades.
  if (arrivedOnPuzzle || embedded() || !showSplash()) liftBootScreenWhenReady();
  // On the platform, the player's language is the portal's to say (`systemInfo.locale`),
  // ahead of the browser's guess — but never over a language they picked themselves.
  void platformLocale().then(adoptPlatformLocale);
}

/** Whether the page is framed by another (a portal), rather than being the top window. */
function embedded(): boolean {
  try {
    return window.self !== window.top;
  } catch {
    // Reading `top` across origins can throw in older browsers, which is itself an answer.
    return true;
  }
}

void boot();
