/**
 * Range (Kurodoko) board model shared by the game, the solver and the generator.
 *
 * A puzzle is a `w × h` grid in which some cells carry a number. The player paints cells
 * black or dots them to record that they are white; an undecided cell counts as white.
 * A finished grid must satisfy four rules: numbered cells are white, no two black cells
 * touch orthogonally, the white cells form one connected region, and every number equals
 * the count of white cells its cell can see in a straight line in the four directions,
 * itself included once.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

/** Cell value: undecided (counts as white). */
export const EMPTY = 0;
/** Cell value: dotted, asserted white. */
export const WHITE = 1;
/** Cell value: painted black. */
export const BLACK = 2;

// ------------------------------------------------------------- description format

/**
 * Encode the clue grid (0 = no number) the way the original does: a run of `k` empty
 * cells is the letter `a + k - 1` (`z` for 26, repeated for longer runs), a number is
 * written in decimal, and `_` separates two numbers that are not parted by a run.
 */
export function encodeDesc(clues: ArrayLike<number>): string {
  let desc = '';
  let run = 0;
  const n = clues.length;
  for (let i = 0; i <= n; i++) {
    const v = i < n ? clues[i] : -1;
    if (v === 0) {
      run++;
      continue;
    }
    if (run > 0) {
      while (run > 0) {
        const k = Math.min(run, 26);
        desc += String.fromCharCode(96 + k);
        run -= k;
      }
    } else if (desc.length > 0 && v > 0) {
      desc += '_';
    }
    if (v > 0) desc += String(v);
  }
  return desc;
}

/** Parse a description into a clue grid (0 = no number), or return an error message. */
export function parseDesc(desc: string, w: number, h: number): Uint8Array | string {
  const n = w * h;
  const max = w + h - 1;
  const clues = new Uint8Array(n);
  let i = 0;
  let p = 0;
  while (p < desc.length) {
    const c = desc[p++];
    if (c >= 'a' && c <= 'z') {
      const k = c.charCodeAt(0) - 96;
      if (i + k > n) return tx`Too much data to fit in grid`;
      i += k;
    } else if (c === '_') {
      // Separator between two adjacent numbers.
    } else if (c >= '1' && c <= '9') {
      let q = p;
      while (q < desc.length && desc[q] >= '0' && desc[q] <= '9') q++;
      const val = parseInt(desc.slice(p - 1, q), 10);
      p = q;
      if (val < 1 || val > max) return tx`Out-of-range number in game description`;
      if (i >= n) return tx`Too much data to fit in grid`;
      clues[i++] = val;
    } else {
      return tx`Invalid character in game description`;
    }
  }
  if (i < n) return tx`Not enough data to fill grid`;
  return clues;
}

/** Encode a solution as one `0`/`1` per cell (`1` = black), for `aux`. */
export function encodeSolution(grid: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < grid.length; i++) s += grid[i] === BLACK ? '1' : '0';
  return s;
}

/** Decode `encodeSolution` output into a grid of `BLACK`/`WHITE`, or null when malformed. */
export function decodeSolution(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n || !/^[01]*$/.test(aux)) return null;
  const grid = new Uint8Array(n);
  for (let i = 0; i < n; i++) grid[i] = aux[i] === '1' ? BLACK : WHITE;
  return grid;
}

// ------------------------------------------------------------- visibility

/**
 * How many cells `i` can see, itself included: the run of cells accepted by `ok` in each
 * of the four directions, stopping at the first cell that is not.
 */
export function countVisible(w: number, h: number, i: number, ok: (j: number) => boolean): number {
  const x = i % w;
  const y = (i - x) / w;
  let count = 1;
  for (let xx = x - 1; xx >= 0 && ok(y * w + xx); xx--) count++;
  for (let xx = x + 1; xx < w && ok(y * w + xx); xx++) count++;
  for (let yy = y - 1; yy >= 0 && ok(yy * w + x); yy--) count++;
  for (let yy = y + 1; yy < h && ok(yy * w + x); yy++) count++;
  return count;
}

// ------------------------------------------------------------- rule checking

export interface GridCheck {
  /** Every rule holds with undecided cells taken as white. */
  complete: boolean;
  /** 1 for black cells that touch another black cell (or sit on a number). */
  badBlack: Uint8Array;
  /** 1 for non-black cells outside the largest white region. */
  cutOff: Uint8Array;
  /** 1 for numbers that see too few possible whites, or too many definite ones. */
  badClue: Uint8Array;
}

/**
 * Check the rules and work out what to highlight. A number is only flagged when it is
 * already beyond repair: the cells it could still see (undecided ones included) are too
 * few, or the cells it definitely sees (dots and other numbers) are too many.
 */
export function checkGrid(clues: Uint8Array, grid: Uint8Array, w: number, h: number): GridCheck {
  const n = w * h;
  const badBlack = new Uint8Array(n);
  const cutOff = new Uint8Array(n);
  const badClue = new Uint8Array(n);
  let complete = true;
  const notBlack = (j: number) => grid[j] !== BLACK;
  const known = (j: number) => grid[j] === WHITE || clues[j] > 0;

  const dsf = new DSF(n);
  let nwhite = 0;
  for (let i = 0; i < n; i++) {
    const x = i % w;
    const y = (i - x) / w;
    if (grid[i] === BLACK) {
      if (
        clues[i] > 0 ||
        (x > 0 && grid[i - 1] === BLACK) ||
        (x < w - 1 && grid[i + 1] === BLACK) ||
        (y > 0 && grid[i - w] === BLACK) ||
        (y < h - 1 && grid[i + w] === BLACK)
      ) {
        badBlack[i] = 1;
        complete = false;
      }
      continue;
    }
    nwhite++;
    if (x < w - 1 && grid[i + 1] !== BLACK) dsf.merge(i, i + 1);
    if (y < h - 1 && grid[i + w] !== BLACK) dsf.merge(i, i + w);
    if (clues[i] > 0) {
      const seen = countVisible(w, h, i, notBlack);
      if (seen !== clues[i]) complete = false;
      if (seen < clues[i]) badClue[i] = 1;
      else if (seen > clues[i] && countVisible(w, h, i, known) > clues[i]) badClue[i] = 1;
    }
  }

  // Several white regions: the largest one (lowest index on a tie) is the real one.
  let largest = 0;
  let canonical = -1;
  for (let i = 0; i < n; i++) {
    if (grid[i] === BLACK) continue;
    const size = dsf.sizeOf(i);
    if (size > largest) {
      largest = size;
      canonical = dsf.find(i);
    }
  }
  if (largest < nwhite) {
    complete = false;
    for (let i = 0; i < n; i++) {
      if (grid[i] !== BLACK && dsf.find(i) !== canonical) cutOff[i] = 1;
    }
  }
  if (nwhite === 0) complete = false;
  return { complete, badBlack, cutOff, badClue };
}

/** Whether a black/white assignment is a valid finished grid for these clues. */
export function isValidSolution(clues: Uint8Array, grid: Uint8Array, w: number, h: number) {
  return checkGrid(clues, grid, w, h).complete;
}
