import { Drawing } from '../framework/drawing';
import { Random } from '../framework/rng';
import type { Game } from '../framework/types';
import { handFontLoaded } from './fonts';

/**
 * Painted previews, kept for the life of the page and keyed by game and size.
 *
 * The menu rebuilds its whole grid whenever the lock set changes — spending a credit is
 * the common case — and a rebuilt card gets a brand new 1×1 canvas. Repainting all
 * thirty-eight from scratch takes the best part of two seconds (one per animation frame),
 * during which every card in the collection sits blank. Painting once and copying the
 * bitmap afterwards makes a rebuild instant, and a copy of a 180px bitmap costs nothing
 * next to generating a puzzle and drawing it.
 */
const painted = new Map<string, HTMLCanvasElement>();

function cacheKey(game: Game, size: number): string {
  return `${game.id}:${size}`;
}

/** Copy a cached preview into `canvas`. False when this game has not been painted yet. */
export function paintCachedThumbnail(game: Game, canvas: HTMLCanvasElement, size = 180): boolean {
  const src = painted.get(cacheKey(game, size));
  if (!src) return false;
  copyInto(src, canvas);
  return true;
}

function copyInto(src: HTMLCanvasElement, canvas: HTMLCanvasElement): void {
  canvas.width = src.width;
  canvas.height = src.height;
  canvas.style.width = src.style.width;
  canvas.style.height = src.style.height;
  canvas.getContext('2d')?.drawImage(src, 0, 0);
}

/**
 * Render a deterministic preview of `game` into `canvas`, fitting inside `size` px.
 * Uses the game's thumbnail parameters (or the first preset) and a fixed seed.
 */
export function renderThumbnail(game: Game, canvas: HTMLCanvasElement, size = 180): void {
  if (paintCachedThumbnail(game, canvas, size)) return;
  const params = game.thumbnailParams ?? game.presets[0]?.params ?? game.defaultParams();
  const rng = new Random(`thumbnail:${game.id}`);
  const { desc } = game.newDesc(params, rng, false);
  let state = game.newGame(params, desc);
  for (const mv of game.thumbnailMoves ?? []) {
    const next = game.executeMove(state, mv);
    if (next) state = next;
  }
  let t = game.preferredTileSize;
  const fits = (ts: number) => {
    const s = game.computeSize(params, ts);
    return s.w <= size && s.h <= size;
  };
  while (t > 2 && !fits(t)) t--;
  const sz = game.computeSize(params, t);
  const dr = new Drawing(canvas);
  dr.resize(sz.w, sz.h);
  const ui = game.newUI(state);
  const ds = { ...(game.newDrawState?.(state, params) ?? {}), tileSize: t };
  dr.begin();
  game.redraw(dr, ds as any, null, state, 1, ui, 0, 0);
  dr.end();
  // Keep a copy rather than the card's own canvas, which the next rebuild throws away —
  // but not one painted in a stand-in face: the next rebuild paints it again, properly.
  if (!handFontLoaded()) return;
  const keep = document.createElement('canvas');
  copyInto(canvas, keep);
  painted.set(cacheKey(game, size), keep);
}

/**
 * The board each game was left on, this session, and whether it was solved.
 *
 * A card the player has just come back from shows the puzzle as they left it rather than
 * the stock preview: the sheet flies back into the box and turns over into the card (see
 * flight.ts), and a card that then showed a different puzzle would have swapped the
 * player's board for somebody else's on the way in. In memory only — the next visit opens
 * on the collection's own pictures again.
 */
const left = new Map<string, { canvas: HTMLCanvasElement; won: boolean }>();

/** Keep a small copy of `board`, the live canvas of `gameId`'s play page. */
export function rememberBoard(
  gameId: string,
  board: HTMLCanvasElement,
  won: boolean,
  size = 180,
): void {
  const w = parseFloat(board.style.width) || board.width;
  const h = parseFloat(board.style.height) || board.height;
  if (!w || !h || board.width <= 1 || board.height <= 1) return;
  const k = Math.min(size / w, size / h, 1);
  const cw = Math.max(1, Math.round(w * k));
  const ch = Math.max(1, Math.round(h * k));
  const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));
  const keep = document.createElement('canvas');
  keep.width = Math.round(cw * dpr);
  keep.height = Math.round(ch * dpr);
  keep.style.width = `${cw}px`;
  keep.style.height = `${ch}px`;
  const ctx = keep.getContext('2d');
  if (!ctx) return;
  ctx.drawImage(board, 0, 0, keep.width, keep.height);
  left.set(gameId, { canvas: keep, won });
}

/** Paint the board `game` was left on into `canvas`. False when there is none. */
export function paintLeftBoard(game: Game, canvas: HTMLCanvasElement): boolean {
  const kept = left.get(game.id);
  if (!kept) return false;
  copyInto(kept.canvas, canvas);
  return true;
}

/** Whether the board `gameId` was left on this session is one the player solved. */
export function leftSolved(gameId: string): boolean {
  return left.get(gameId)?.won ?? false;
}
