/**
 * Device capabilities, in one place so the rest of the UI never sniffs user agents.
 *
 * The media queries are created once and only their `matches` flag is read, so calling
 * these on every layout pass is cheap while still reflecting the current state (a window
 * resize, a phone rotating, a mouse plugged into a tablet).
 */

/** Widths at or below this are treated as "one column, bottom sheets" screens. */
export const SMALL_WIDTH = 640;
/** Heights at or below this are treated as landscape-phone height. */
export const SHORT_HEIGHT = 560;

const mq = (q: string): MediaQueryList | null =>
  typeof matchMedia === 'function' ? matchMedia(q) : null;

const coarse = mq('(pointer: coarse)');
const anyCoarse = mq('(any-pointer: coarse)');
const noHover = mq('(hover: none)');
const narrow = mq(`(max-width: ${SMALL_WIDTH}px)`);
const short = mq(`(max-height: ${SHORT_HEIGHT}px)`);
/**
 * The exact query `toolbar.css` gates the side rails on, so the stylesheet and the script
 * can never disagree about which layout is on screen.
 *
 * Two shapes, one rule. The first clause is every touch screen on its side, phone or
 * tablet. The second is the same trade made on a mouse: a window wider than it is tall by
 * a fifth, which is every laptop, every desktop and — the reason it is here — every game
 * frame a portal embeds this in. The arithmetic is the whole argument. A band layout
 * gives the board `min(H - 112, W - 32)`; rails give it `min(H - 22, W - 190)`. Rails win
 * whenever `W > H + 80`, and by the full height of both bands once the board is bounded
 * by the height, which it is on every 16:9 screen. 6/5 sits clear of that crossover.
 *
 * `min-width` keeps the smallest windows on bands: below it the board is bounded by the
 * width instead, and a rail would take the dimension that binds it.
 */
export const SIDE_RAIL_QUERY =
  '(pointer: coarse) and (orientation: landscape), (min-width: 760px) and (min-aspect-ratio: 6 / 5)';
const sideRail = mq(SIDE_RAIL_QUERY);

/** True when the primary pointer is a finger (phones, tablets, touch laptops in tablet mode). */
export function isTouch(): boolean {
  if (coarse) return coarse.matches || (!!noHover?.matches && !!anyCoarse?.matches);
  return typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0;
}

/** True on phone-width viewports: single-column menu, bottom sheets, full-screen drawer. */
export function isSmallScreen(): boolean {
  if (narrow) return narrow.matches;
  return typeof window !== 'undefined' && window.innerWidth <= SMALL_WIDTH;
}

/** True on short viewports, whatever is pointing at them: a phone on its side. */
export function isShortScreen(): boolean {
  if (short) return short.matches;
  return typeof window !== 'undefined' && window.innerHeight <= SHORT_HEIGHT;
}

/**
 * True where the play page stands its chrome up into rails either side of the board: any
 * screen meaningfully wider than it is tall. That is every phone and tablet on its side,
 * and every mouse window of the usual shape — the shape where a square board is bounded
 * by the height while half the width sits empty either side of it.
 *
 * A tablet held upright is excluded for the opposite reason: there the board already fills
 * the width, so a rail would take the one dimension that binds it. So is a narrow window,
 * for the same reason. See `SIDE_RAIL_QUERY` for the arithmetic.
 */
export function isSideRail(): boolean {
  if (sideRail) return sideRail.matches;
  if (typeof window === 'undefined') return false;
  const { innerWidth: w, innerHeight: h } = window;
  return (isTouch() && w > h) || (w >= 760 && w >= h * 1.2);
}

/** True when the viewport is narrow *or* short, i.e. every phone including landscape. */
export function isCompactLayout(): boolean {
  if (narrow && short) return narrow.matches || short.matches;
  return (
    typeof window !== 'undefined' &&
    (window.innerWidth <= SMALL_WIDTH || window.innerHeight <= SHORT_HEIGHT)
  );
}

/**
 * Reflect the pointer type on `<html>` so CSS can key off it without duplicating the
 * query, and so tests can see which mode the shell believes it is in.
 */
export function markDeviceOnRoot(): void {
  if (typeof document === 'undefined') return;
  const root = document.documentElement;
  const apply = () => root.classList.toggle('touch', isTouch());
  apply();
  coarse?.addEventListener?.('change', apply);
  noHover?.addEventListener?.('change', apply);
}
