/**
 * Deductive Undead solver.
 *
 * The solver works on a `Work`: one candidate byte per slot (bits for ghost, vampire and
 * zombie) over a fixed `Layout`. It knows three tiers of reasoning, one per difficulty:
 *
 *  - **Easy** counts along each path from one end at a time. Every step is either surely
 *    visible (all its candidates are seen from that end), surely hidden, or undecided;
 *    when the clue equals the number of surely-visible steps the undecided ones must all
 *    be hidden, and when it equals the number of possibly-visible steps they must all be
 *    seen. The monster totals are used the same way: a type that is used up is struck
 *    from every open slot, and a type with exactly as many possible homes as it needs
 *    takes them all.
 *  - **Normal** adds combination reasoning: for one path at a time, every assignment of
 *    its monsters consistent with both clues and the totals is enumerated, and a
 *    candidate that occurs in no valid assignment is dropped.
 *  - **Tricky** allows guessing: when stuck, the slot with the fewest candidates is tried
 *    each way, with Normal deductions after every guess, and the solutions are counted.
 *
 * Deductions are sound, so a puzzle that a tier finishes has exactly one solution; only
 * the Tricky tier can tell an ambiguous puzzle from a unique one that needs a guess.
 */
import { ALL_TYPES, Layout, Path, TYPES, TYPE_INDEX } from './board';

export const DIFF_EASY = 0;
export const DIFF_NORMAL = 1;
export const DIFF_TRICKY = 2;
export const DIFFICULTY_NAMES = ['Easy', 'Normal', 'Tricky'];
export const DIFFICULTY_CODES = ['e', 'n', 't'];

/** Mutable solving state over a layout. */
export class Work {
  /** Candidate types of every slot; a single bit is a decided slot, 0 a contradiction. */
  cand: Uint8Array;
  dead = false;

  constructor(readonly L: Layout) {
    this.cand = new Uint8Array(L.numSlots).fill(ALL_TYPES);
    for (let i = 0; i < L.numSlots; i++) if (L.fixed[i]) this.cand[i] = L.fixed[i];
  }

  clone(): Work {
    const w = new Work(this.L);
    w.cand.set(this.cand);
    w.dead = this.dead;
    return w;
  }

  /** Every slot is decided. */
  solved(): boolean {
    for (const c of this.cand) if (c !== 1 && c !== 2 && c !== 4) return false;
    return true;
  }

  /** Narrow a slot's candidates; marks the work dead on a contradiction. */
  restrict(i: number, mask: number): boolean {
    const next = this.cand[i] & mask;
    if (next === this.cand[i]) return false;
    this.cand[i] = next;
    if (next === 0) this.dead = true;
    return true;
  }
}

/** One round of Easy deductions over every path end and every total. */
function countingPass(work: Work): boolean {
  const { L, cand } = work;
  let changed = false;
  for (const p of L.paths) {
    for (const fromStart of [true, false]) {
      const clue = L.clues[fromStart ? p.start : p.end];
      const vis = fromStart ? p.visStart : p.visEnd;
      let lo = 0;
      let hi = 0;
      for (let k = 0; k < p.slots.length; k++) {
        const s = p.slots[k];
        if (s < 0) continue;
        const c = cand[s];
        if (c & vis[k]) {
          hi++;
          if (!(c & ~vis[k] & ALL_TYPES)) lo++;
        }
      }
      if (clue < lo || clue > hi) {
        work.dead = true;
        return false;
      }
      if (clue === lo || clue === hi) {
        // Every undecided step must be hidden (clue == lo) or seen (clue == hi).
        for (let k = 0; k < p.slots.length; k++) {
          const s = p.slots[k];
          if (s < 0) continue;
          const c = cand[s];
          if (c & vis[k] && c & ~vis[k] & ALL_TYPES) {
            if (work.restrict(s, clue === lo ? ~vis[k] : vis[k])) changed = true;
            if (work.dead) return false;
          }
        }
      }
    }
  }
  for (const t of TYPES) {
    const need = L.total[TYPE_INDEX[t]];
    let decided = 0;
    let possible = 0;
    for (const c of cand) {
      if (c === t) decided++;
      if (c & t) possible++;
    }
    if (decided > need || possible < need) {
      work.dead = true;
      return false;
    }
    if (decided === need && possible > need) {
      for (let i = 0; i < cand.length; i++)
        if (cand[i] !== t && work.restrict(i, ~t)) changed = true;
    } else if (possible === need && possible > decided) {
      for (let i = 0; i < cand.length; i++) if (cand[i] & t && work.restrict(i, t)) changed = true;
    }
    if (work.dead) return false;
  }
  return changed;
}

/**
 * Normal deduction for one path: enumerate every assignment of its monsters that meets
 * both clues without exceeding any total (given what is decided elsewhere), and keep
 * only the candidates that occur in some valid assignment.
 */
function enumeratePath(work: Work, p: Path): boolean {
  const { L, cand } = work;
  const m = p.monsters.length;
  if (m === 0) return false;
  const clueS = L.clues[p.start];
  const clueE = L.clues[p.end];
  // Decided monsters outside this path count against the totals.
  const onPath = new Uint8Array(L.numSlots);
  for (const s of p.monsters) onPath[s] = 1;
  const used = [0, 0, 0];
  for (let i = 0; i < L.numSlots; i++) {
    const c = cand[i];
    if (!onPath[i] && (c === 1 || c === 2 || c === 4)) used[TYPE_INDEX[c]]++;
  }
  // Per monster: how many steps it occupies, and the visibility masks of those steps.
  const occ: number[][] = p.monsters.map(() => []);
  for (let k = 0; k < p.slots.length; k++) {
    const s = p.slots[k];
    if (s >= 0) occ[p.monsters.indexOf(s)].push(k);
  }
  // Most sightings the monsters from index k onward could still add.
  const restMax = new Array<number>(m + 1).fill(0);
  for (let k = m - 1; k >= 0; k--) restMax[k] = restMax[k + 1] + occ[k].length;

  const possible = new Uint8Array(m);
  const assign = new Uint8Array(m);
  let open = m; // monsters whose candidates are not all confirmed possible yet
  const rec = (k: number, seenS: number, seenE: number): void => {
    if (open === 0) return;
    if (seenS > clueS || seenE > clueE) return;
    if (seenS + restMax[k] < clueS || seenE + restMax[k] < clueE) return;
    if (k === m) {
      if (seenS !== clueS || seenE !== clueE) return;
      for (let j = 0; j < m; j++) {
        const before = possible[j];
        possible[j] |= assign[j];
        if (before !== possible[j] && possible[j] === cand[p.monsters[j]]) open--;
      }
      return;
    }
    const c = cand[p.monsters[k]];
    for (const t of TYPES) {
      if (!(c & t)) continue;
      const ti = TYPE_INDEX[t];
      if (used[ti] >= L.total[ti]) continue;
      let addS = 0;
      let addE = 0;
      for (const step of occ[k]) {
        if (p.visStart[step] & t) addS++;
        if (p.visEnd[step] & t) addE++;
      }
      assign[k] = t;
      used[ti]++;
      rec(k + 1, seenS + addS, seenE + addE);
      used[ti]--;
    }
  };
  rec(0, 0, 0);

  let changed = false;
  for (let j = 0; j < m; j++) {
    if (work.restrict(p.monsters[j], possible[j])) changed = true;
    if (work.dead) return false;
  }
  return changed;
}

/** Run every deduction the tier allows until nothing changes or a contradiction appears. */
export function deduce(work: Work, difficulty: number): void {
  for (;;) {
    if (work.dead) return;
    let changed = countingPass(work);
    if (work.dead) return;
    if (difficulty >= DIFF_NORMAL) {
      for (const p of work.L.paths) {
        if (enumeratePath(work, p)) changed = true;
        if (work.dead) return;
      }
    }
    if (!changed) return;
  }
}

export interface SearchResult {
  /** Solutions found, capped at `cap`. */
  count: number;
  /** The first solution found, as one type bit per slot. */
  first: Uint8Array | null;
}

/**
 * Tricky solving: Normal deductions, then guess the most constrained slot and recurse,
 * counting solutions up to `cap`.
 */
export function search(work: Work, cap: number): SearchResult {
  const result: SearchResult = { count: 0, first: null };
  const rec = (w: Work): void => {
    deduce(w, DIFF_NORMAL);
    if (w.dead) return;
    if (w.solved()) {
      result.count++;
      if (!result.first) result.first = w.cand.slice();
      return;
    }
    let pick = -1;
    let bestBits = 4;
    for (let i = 0; i < w.cand.length; i++) {
      const c = w.cand[i];
      const bits = (c & 1) + ((c >> 1) & 1) + ((c >> 2) & 1);
      if (bits > 1 && bits < bestBits) {
        bestBits = bits;
        pick = i;
      }
    }
    for (const t of TYPES) {
      if (!(w.cand[pick] & t)) continue;
      const branch = w.clone();
      branch.cand[pick] = t;
      rec(branch);
      if (result.count >= cap) return;
    }
  };
  rec(work);
  return result;
}

/**
 * The easiest tier that solves the puzzle, or -1 when it has no unique solution. Easy
 * and Normal must finish by deduction alone; Tricky must find exactly one solution.
 */
export function gradePuzzle(L: Layout): number {
  const easy = new Work(L);
  deduce(easy, DIFF_EASY);
  if (easy.dead) return -1;
  if (easy.solved()) return DIFF_EASY;
  const normal = new Work(L);
  deduce(normal, DIFF_NORMAL);
  if (normal.dead) return -1;
  if (normal.solved()) return DIFF_NORMAL;
  return search(normal, 2).count === 1 ? DIFF_TRICKY : -1;
}

/** Solve from scratch with the reasoning of one tier; Tricky also confirms uniqueness. */
export function solveFresh(
  L: Layout,
  difficulty: number,
): { solved: boolean; types: Uint8Array | null; work: Work } {
  const work = new Work(L);
  if (difficulty >= DIFF_TRICKY) {
    const r = search(work, 2);
    return { solved: r.count === 1, types: r.count === 1 ? r.first : null, work };
  }
  deduce(work, difficulty);
  const solved = !work.dead && work.solved();
  return { solved, types: solved ? work.cand.slice() : null, work };
}
