import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  KEY_BACKSPACE,
  LEFT_BUTTON,
  MOD_SHFT,
  RIGHT_BUTTON,
  isCursorMove,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { INK_TIME, changedAt, drawGrow, popGrow } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { parseDesc } from './desc';
import type { TowersDesc } from './desc';
import { generateTowers } from './generator';
import {
  DIFF_AMBIGUOUS,
  DIFF_CHARS,
  DIFF_COUNT,
  DIFF_EASY,
  DIFF_EXTREME,
  DIFF_HARD,
  DIFF_IMPOSSIBLE,
  DIFF_UNREASONABLE,
  checkErrors,
  cluePos,
  solveTowers,
} from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';
import { HIGHLIGHT_GLYPH } from '../../framework/glyphs';

export interface TowersParams {
  w: number;
  diff: number;
}

export interface TowersState {
  w: number;
  /** 4w clues: above the columns, below them, left of the rows, right of them; 0 = none. */
  clues: Int32Array;
  /** The given digits (0 where the player fills in). */
  immutable: Uint8Array;
  grid: Uint8Array;
  /** pencil[xy] has bit n set when digit n is pencilled into square xy. */
  pencil: Uint16Array;
  completed: boolean;
  cheated: boolean;
}

export interface TowersUI {
  hx: number;
  hy: number;
  /** The highlight is shown. */
  hshow: boolean;
  /** Typed digits become pencil marks. */
  hpencil: boolean;
  /** The highlight was placed with the keyboard, so it stays after a digit is typed. */
  hcursor: boolean;
  /** A digit just went into the selected square: one click on it keeps it chosen. */
  hkept: boolean;
  /** The Highlight tool: every square holding the digit last pointed at is picked out. */
  spot: boolean;
  /** The square last clicked or moved to, whose digit Highlight picks out; -1 for none. */
  spotAt: number;
}

const FLASH = 0.4;
const DEFAULTS: TowersParams = { w: 5, diff: DIFF_EASY };
const MIN_SIZE = 3;
const MAX_SIZE = 9;

/**
 * Difficulty words for the Type menu and the Custom dialog alike, in the solver's own
 * order. The generator's level names (`DIFF_NAMES`) are one step out of line with this
 * ladder — its "Extreme" is the menu's "Expert" — so showing them in the dialog made the
 * same word mean two different puzzles.
 */
const PRESET_DIFFICULTIES = ['Easy', 'Hard', 'Expert', 'Extreme'];

function preset(w: number, diff: number): { name: string; params: TowersParams } {
  return { name: `${w}×${w} ${PRESET_DIFFICULTIES[diff]}`, params: { w, diff } };
}

/** Room around the grid for the clues plus a small margin. */
function boardBorder(t: number): number {
  return Math.round(t * 1.1);
}

/** Distance of a clue's centre from the grid edge. */
const CLUE_OFFSET = 0.55;

export function makeState(w: number, d: TowersDesc): TowersState {
  return {
    w,
    clues: d.clues,
    immutable: d.grid,
    grid: d.grid.slice(),
    pencil: new Uint16Array(w * w),
    completed: false,
    cheated: false,
  };
}

/** A sketched block whose height grows with the digit, drawn behind the digit itself. */
function drawTower(dr: Drawing, px: number, py: number, t: number, d: number, w: number) {
  const left = px + t * 0.3;
  const right = px + t * 0.7;
  const bottom = py + t * 0.92;
  const top = bottom - t * (0.2 + (0.62 * d) / w);
  const dx = t * 0.08;
  const dy = t * 0.07;
  const opts = { width: 1, rough: 0.5, seed: d, alpha: 0.75 };
  dr.polygon(
    [right, top, right + dx, top - dy, right + dx, bottom - dy, right, bottom],
    'faint',
    'faint',
    opts,
  );
  dr.polygon(
    [left, top, left + dx, top - dy, right + dx, top - dy, right, top],
    'shade',
    'faint',
    opts,
  );
  dr.polygon([left, top, right, top, right, bottom, left, bottom], 'shade', 'faint', opts);
}

function drawPencilMarks(
  dr: Drawing,
  w: number,
  mask: number,
  px: number,
  py: number,
  t: number,
  spot: number,
) {
  const marks: number[] = [];
  for (let n = 1; n <= w; n++) if (mask & (1 << n)) marks.push(n);
  const count = marks.length;
  if (!count) return;
  const pad = t * 0.06;
  const inner = t - 2 * pad;
  // Lay the marks out on a small grid, choosing the column count that lets them be biggest.
  let bestSize = 0;
  let pw = 3;
  for (let cols = 3; cols < Math.max(count, 4); cols++) {
    const rows = Math.max(Math.ceil(count / cols), 2);
    const fs = Math.min(inner / cols, inner / rows);
    if (fs > bestSize) {
      bestSize = fs;
      pw = cols;
    }
  }
  const ph = Math.max(Math.ceil(count / pw), 2);
  const fs = Math.min(inner / pw, inner / ph);
  const left = px + (t - fs * pw) / 2;
  const top = py + (t - fs * ph) / 2;
  for (let j = 0; j < count; j++) {
    const gx = j % pw;
    const gy = Math.floor(j / pw);
    const lit = marks[j] === spot;
    dr.text(left + fs * (gx + 0.5), top + fs * (gy + 0.5), String(marks[j]), {
      size: fs * 0.82,
      colour: lit ? 'teal' : 'pencil',
      bold: lit,
    });
  }
}

/** The digit Highlight is picking out, or 0 when it is off or points at an empty square. */
export function spotDigit(grid: Uint8Array, ui: TowersUI): number {
  return ui.spot && ui.spotAt >= 0 && ui.spotAt < grid.length ? grid[ui.spotAt] : 0;
}

const game = defineGame<TowersParams, TowersState, TowersUI>({
  id: 'towers',
  name: 'Towers',
  description: 'Build towers so that each edge clue counts the towers visible from there.',
  alsoKnownAs: 'Skyscrapers',
  help,
  tutorial,
  achievements,
  presets: [
    preset(4, DIFF_EASY),
    preset(5, DIFF_EASY),
    preset(5, DIFF_HARD),
    preset(6, DIFF_EASY),
    preset(6, DIFF_HARD),
    preset(6, DIFF_EXTREME),
    preset(6, DIFF_UNREASONABLE),
  ],
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams(p, full) {
    return full ? `${p.w}d${DIFF_CHARS[p.diff] ?? ''}` : `${p.w}`;
  },
  decodeParams(str) {
    const m = /^(\d+)(?:d(.?))?/.exec(str);
    if (!m) throw new Error(tx`expected a grid size`);
    const p: TowersParams = { ...DEFAULTS, w: parseInt(m[1], 10) };
    if (m[2] !== undefined) {
      const d = m[2] ? DIFF_CHARS.indexOf(m[2]) : -1;
      p.diff = d >= 0 ? d : DIFF_COUNT;
    }
    return p;
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.diff))
      return tx`All parameters must be whole numbers`;
    if (p.w < MIN_SIZE || p.w > MAX_SIZE)
      return tx`Grid size must be between ${MIN_SIZE} and ${MAX_SIZE}`;
    if (p.diff < 0 || p.diff >= DIFF_COUNT) return tx`Unknown difficulty rating`;
    if (full && p.w >= 9 && p.diff === DIFF_UNREASONABLE)
      return tx`9×9 Extreme puzzles take too long to generate; try 8×8 or Expert`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Grid size', value: String(p.w) },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.diff },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const w = int(0);
    const diff = (items[1] as { selected: number }).selected;
    return { w, diff };
  },

  newDesc(p, rng: Random) {
    return generateTowers(p.w, p.diff, rng);
  },

  validateDesc(p, desc) {
    const d = parseDesc(p.w, desc);
    return typeof d === 'string' ? d : null;
  },

  newGame(p, desc) {
    return makeState(p.w, parseDesc(p.w, desc) as TowersDesc);
  },

  canSolve: true,
  solve(orig, _curr, aux) {
    if (aux) return aux;
    const grid = orig.immutable.slice();
    const res = solveTowers(orig.w, orig.clues, grid, DIFF_UNREASONABLE);
    if (res === DIFF_IMPOSSIBLE) throw new Error(tx`No solution exists for this puzzle`);
    if (res === DIFF_AMBIGUOUS) throw new Error(tx`Multiple solutions exist for this puzzle`);
    return 'S' + Array.from(grid).join('');
  },

  textFormat(s) {
    const { w, clues, grid } = s;
    const ch = (n: number) => (n ? String(n) : ' ');
    const lines: string[] = [];
    let top = '  ';
    let bottom = '  ';
    for (let x = 0; x < w; x++) {
      top += ' ' + ch(clues[x]);
      bottom += ' ' + ch(clues[x + w]);
    }
    lines.push(top, '');
    for (let y = 0; y < w; y++) {
      let line = ch(clues[y + 2 * w]) + ' ';
      for (let x = 0; x < w; x++) line += ' ' + ch(grid[y * w + x]);
      line += '  ' + ch(clues[y + 3 * w]);
      lines.push(line);
    }
    lines.push('', bottom);
    return lines.join('\n');
  },

  newUI: () => ({
    hx: 0,
    hy: 0,
    hshow: false,
    hpencil: false,
    hcursor: false,
    hkept: false,
    spot: false,
    spotAt: -1,
  }),
  changedState(ui, _old, next) {
    // A pencil highlight on a square that has just been filled (by Undo, Redo or Solve)
    // makes no sense, so drop it unless the keyboard cursor is in use; and a puzzle just
    // finished needs no selection at all.
    if (ui.hshow && ui.hpencil && !ui.hcursor && next.grid[ui.hy * next.w + ui.hx] !== 0)
      ui.hshow = false;
    if (next.completed && !_old.completed) ui.hshow = false;
  },

  // One key per digit, a clear key and the pencil-mark latch, so a device without a
  // keyboard can still fill squares in.
  keypad: (p) => ({
    keys: Array.from({ length: p.w }, (_, i) => String(i + 1)),
    clear: true,
    pencil: true,
  }),

  actions: [
    {
      label: 'Marks',
      key: 'M',
      title: 'Pencil every possibility into every empty square (M)',
    },
    {
      label: 'Highlight',
      key: 'L',
      hud: true,
      glyph: HIGHLIGHT_GLYPH,
      pressed: (_s, ui) => ui.spot,
      view: true,
      title: 'Pick out every square holding the digit you last touched (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    // A click straight after a digit re-chooses the square that kept its selection rather
    // than deselecting it, so clicking a square before each digit still types.
    const kept = ui.hkept;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || isCursorMove(b)) ui.hkept = false;
    const { w } = state;
    const t = ds.tileSize;
    const border = boardBorder(t);
    const tx = Math.floor((mx - border) / t);
    const ty = Math.floor((my - border) / t);
    const inside = tx >= 0 && tx < w && ty >= 0 && ty < w;

    if (b === 76 || b === 108) {
      ui.spot = !ui.spot;
      return '';
    }
    if (inside && (b === LEFT_BUTTON || b === RIGHT_BUTTON)) ui.spotAt = ty * w + tx;
    if (inside && b === LEFT_BUTTON) {
      if (state.immutable[ty * w + tx]) {
        ui.hshow = false;
      } else if (tx === ui.hx && ty === ui.hy && ui.hshow && !ui.hpencil && !kept) {
        ui.hshow = false;
      } else {
        ui.hx = tx;
        ui.hy = ty;
        ui.hshow = true;
        ui.hpencil = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (inside && b === RIGHT_BUTTON) {
      if (state.grid[ty * w + tx] === 0) {
        if (tx === ui.hx && ty === ui.hy && ui.hshow && ui.hpencil) {
          ui.hshow = false;
        } else {
          ui.hx = tx;
          ui.hy = ty;
          ui.hshow = true;
          ui.hpencil = true;
        }
      } else {
        ui.hshow = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.hx, ui.hy, w, w);
      ui.hx = p.x;
      ui.hy = p.y;
      ui.spotAt = p.y * w + p.x;
      ui.hshow = true;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow && b === CURSOR_SELECT) {
      ui.hpencil = !ui.hpencil;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow) {
      let n = -1;
      if (b >= 48 && b <= 57 && b - 48 <= w) n = b - 48;
      else if (b === CURSOR_SELECT2 || b === KEY_BACKSPACE) n = 0;
      if (n >= 0) {
        // MOD_SHFT on a digit is the on-screen keypad's pencil latch: pencil this in
        // whatever mode the square was selected in.
        const pencil = ui.hpencil || (button & MOD_SHFT) !== 0;
        const xy = ui.hy * w + ui.hx;
        // Only the keyboard cursor can sit on a clue or pencil-highlight a filled square.
        if (state.immutable[xy]) return null;
        if (pencil && state.grid[xy]) return null;
        const move = `${pencil && n > 0 ? 'P' : 'R'}${ui.hx},${ui.hy},${n}`;
        // The selection stays after a digit, so a keypad user can rub it out or try
        // another without tapping the square again.
        if (!pencil && !ui.hcursor) ui.hkept = true;
        return move;
      }
    }
    if (b === 77 || b === 109) return 'M';
    return null;
  },

  executeMove(state, move) {
    const { w } = state;
    const a = w * w;
    if (move[0] === 'S') {
      if (move.length !== a + 1) return null;
      const grid = new Uint8Array(a);
      for (let i = 0; i < a; i++) {
        const v = move.charCodeAt(i + 1) - 48;
        if (v < 1 || v > w) return null;
        grid[i] = v;
      }
      return { ...state, grid, pencil: new Uint16Array(a), completed: true, cheated: true };
    }
    if (move === 'M') {
      const pencil = state.pencil.slice();
      const all = (1 << (w + 1)) - 2;
      let changed = false;
      for (let xy = 0; xy < a; xy++) {
        if (!state.grid[xy] && pencil[xy] !== all) {
          pencil[xy] = all;
          changed = true;
        }
      }
      // Every empty square already carries every mark: nothing to record.
      return changed ? { ...state, pencil } : state;
    }
    const m = /^([PR])(\d+),(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    const n = parseInt(m[4], 10);
    if (x >= w || y >= w || n > w) return null;
    const xy = y * w + x;
    if (state.immutable[xy]) return null;
    if (m[1] === 'P' && n > 0) {
      if (state.grid[xy]) return null;
      const pencil = state.pencil.slice();
      pencil[xy] ^= 1 << n;
      return { ...state, pencil };
    }
    // Typing the digit already there, or erasing an empty square: no undo step.
    if (state.grid[xy] === n && !state.pencil[xy]) return state;
    const grid = state.grid.slice();
    grid[xy] = n;
    const pencil = state.pencil.slice();
    pencil[xy] = 0;
    const completed = state.completed || !checkErrors(w, state.clues, grid).any;
    return { ...state, grid, pencil, completed };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.w * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, grid, clues } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashTime > 0 && (flashTime <= FLASH / 3 || flashTime >= (2 * FLASH) / 3);
    const errors = checkErrors(w, clues, grid);

    dr.rect(b, b, w * t, w * t, flash ? 'shade' : 'paper');
    // A finished board is shown clean, without the tint.
    const spot = state.completed ? 0 : spotDigit(grid, ui);
    if (spot) {
      for (let xy = 0; xy < w * w; xy++) {
        if (grid[xy] !== spot) continue;
        dr.rect(b + (xy % w) * t, b + Math.floor(xy / w) * t, t, t, 'teal', null, { alpha: 0.18 });
      }
    }
    if (ui.hshow) {
      dr.rect(b + ui.hx * t, b + ui.hy * t, t, t, ui.hpencil ? 'blue' : 'yellow', null, {
        alpha: ui.hpencil ? 0.12 : 0.25,
      });
    }
    for (let i = 1; i < w; i++) {
      dr.line(b + i * t, b, b + i * t, b + w * t, 'faint', 1.2);
      dr.line(b, b + i * t, b + w * t, b + i * t, 'faint', 1.2);
    }

    // A digit the player has just typed is pressed into the square rather than simply
    // being there, and one they have rubbed out shrinks away. This is the most repeated
    // action in the collection, so it is short — and a Solve, which fills the whole grid
    // at once, is left to appear whole.
    const inked = oldState ? changedAt(oldState.grid, grid, 2) : null;
    /** The digit a square is showing mid-change, and how big it is. */
    const inkAt = (i: number, d: number): { d: number; s: number } =>
      !inked?.includes(i)
        ? { d, s: 1 }
        : d
          ? { d, s: popGrow(animTime) }
          : { d: oldState!.grid[i], s: 1 - drawGrow(animTime, INK_TIME) };

    for (let y = 0; y < w; y++) {
      for (let x = 0; x < w; x++) {
        const xy = y * w + x;
        const px = b + x * t;
        const py = b + y * t;
        const ink = inkAt(xy, grid[xy]);
        const d = ink.d;
        if (d && ink.s > 0) {
          drawTower(dr, px, py, t, d, w);
          // Given digits keep their colour; only the player's own clashing digits turn red.
          const colour = state.immutable[xy]
            ? flash
              ? 'ok'
              : 'ink'
            : errors.cells[xy]
              ? 'error'
              : flash
                ? 'ok'
                : 'blue';
          dr.text(px + t / 2, py + t / 2, String(d), { size: t * 0.55 * ink.s, colour });
        } else if (!grid[xy]) {
          drawPencilMarks(dr, w, state.pencil[xy], px, py, t, spot);
        }
      }
    }

    dr.rectOutline(b, b, w * t, w * t, 'ink', { width: 2.6 });

    for (let c = 0; c < 4 * w; c++) {
      if (!clues[c]) continue;
      const [cx, cy] = cluePos(w, c);
      const px =
        cx < 0 ? b - t * CLUE_OFFSET : cx >= w ? b + w * t + t * CLUE_OFFSET : b + cx * t + t / 2;
      const py =
        cy < 0 ? b - t * CLUE_OFFSET : cy >= w ? b + w * t + t * CLUE_OFFSET : b + cy * t + t / 2;
      dr.text(px, py, String(clues[c]), {
        size: t * 0.5,
        colour: errors.clues[c] ? 'error' : 'ink',
      });
    }

    if (ui.hshow) {
      const inset = t * 0.08;
      const hx = b + ui.hx * t + inset;
      const hy = b + ui.hy * t + inset;
      dr.cursor(hx, hy, t - 2 * inset, t - 2 * inset, 'accent', 2.2, {
        dash: ui.hpencil ? [Math.max(3, t * 0.1), Math.max(2, t * 0.08)] : undefined,
      });
      if (ui.hpencil) {
        const s = t * 0.22;
        dr.polygon([hx, hy, hx + s, hy, hx, hy + s], 'accent', null, { seed: 7 });
      }
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.grid, newState.grid, 2) ? INK_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // A few towers of the 4×4 puzzle the menu thumbnail generates (seed `thumbnail:towers`),
  // so the card shows towers rather than an empty grid; the unit tests pin these digits.
  thumbnailMoves: ['R0,0,1', 'R2,0,4', 'R1,1,3', 'R3,1,1', 'R0,2,2', 'R1,3,4'],
});

export default game;
