import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  LEFT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { SERIES } from '../../framework/palette';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { FILL, floodFill, isUniform, joiningSquares, solveGrid, waveDistances } from './solver';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export interface FloodParams {
  w: number;
  h: number;
  colours: number;
  /** Extra moves allowed on top of the solver's own solution length. */
  leniency: number;
}

export interface FloodState {
  w: number;
  h: number;
  colours: number;
  /** Colour index of every square, row-major. Never mutated once built. */
  grid: Uint8Array;
  moves: number;
  moveLimit: number;
  /** The whole grid is one colour. */
  complete: boolean;
  /** The solver was consulted (hint or Solve) at some point. */
  cheated: boolean;
  /** The grid was finished by Solve, so it counts as solved even over the limit. */
  autoSolved: boolean;
  /** Remaining hint path from the solver, and the index of its next move. */
  soln: number[] | null;
  solnPos: number;
}

export interface FloodUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  flashType: 'win' | 'lose';
}

/** Seconds per ring of the fill wave, and the longest a fill may take in total. */
const WAVE_STEP = 0.05;
const WAVE_MAX = 0.5;
/** Seconds per ring of the rainbow victory ripple, and per blink of the defeat flash. */
const WIN_FRAME = 0.03;
const LOSE_FRAME = 0.1;
const MIN_COLOURS = 3;
const MAX_COLOURS = SERIES.length;
const MAX_SIDE = 32;

const DEFAULTS: FloodParams = { w: 12, h: 12, colours: 6, leniency: 5 };

// ------------------------------------------------------------------ descriptions

function colourChar(c: number): string {
  return c < 10 ? String(c) : String.fromCharCode(55 + c); // 10 → 'A'
}

/** Parse one colour character; null if it is not one. */
function charColour(ch: string): number | null {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'A' && ch <= 'Z') return ch.charCodeAt(0) - 55;
  return null;
}

function encodeGrid(grid: Uint8Array): string {
  let s = '';
  for (let i = 0; i < grid.length; i++) s += colourChar(grid[i]);
  return s;
}

/** Parse a comma-separated list of colour indices below `colours`; null if malformed. */
function parseSequence(s: string, colours: number): number[] | null {
  if (!/^\d+(,\d+)*$/.test(s)) return null;
  const seq = s.split(',').map(Number);
  return seq.every((c) => c < colours) ? seq : null;
}

// ------------------------------------------------------------------ geometry

function boardOrigin(t: number): number {
  return Math.round(t * 0.3);
}

function squareAt(ds: DrawState, mx: number, my: number) {
  const t = ds.tileSize;
  const b = boardOrigin(t);
  return { x: Math.floor((mx - b) / t), y: Math.floor((my - b) / t) };
}

// ------------------------------------------------------------------ status

function statusOf(s: FloodState): -1 | 0 | 1 {
  if (s.complete && (s.moves <= s.moveLimit || s.autoSolved)) return 1;
  if (s.moves >= s.moveLimit) return -1;
  return 0;
}

// ------------------------------------------------------------------ the game

const game = defineGame<FloodParams, FloodState, FloodUI>({
  id: 'flood',
  name: 'Flood',
  description: 'Flood the grid from the corner until it is all one colour, within the move limit.',
  alsoKnownAs: 'Flood It',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [12, 12, 6, 5, '12×12 Easy'],
      [12, 12, 6, 2, '12×12 Medium'],
      [12, 12, 6, 0, '12×12 Hard'],
      [16, 16, 6, 2, '16×16 Medium'],
      [16, 16, 6, 0, '16×16 Hard'],
      [12, 12, 3, 0, '12×12, 3 colours'],
      [12, 12, 4, 0, '12×12, 4 colours'],
    ] as [number, number, number, number, string][]
  ).map(([w, h, colours, leniency, name]) => ({ name, params: { w, h, colours, leniency } })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) => `${p.w}x${p.h}c${p.colours}${full ? `m${p.leniency}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const p: FloodParams = { ...DEFAULTS, w: parseInt(m[1], 10), h: parseInt(m[2] ?? m[1], 10) };
    const re = /([cm])(\d+)/g;
    let part: RegExpExecArray | null;
    while ((part = re.exec(str.slice(m[0].length)))) {
      if (part[1] === 'c') p.colours = parseInt(part[2], 10);
      else p.leniency = parseInt(part[2], 10);
    }
    return p;
  },
  validateParams(p) {
    if (![p.w, p.h, p.colours, p.leniency].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 1 || p.h < 1 || p.w * p.h < 2) return tx`Grid must contain at least two squares`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.colours < MIN_COLOURS || p.colours > MAX_COLOURS)
      return tx`Must have between ${MIN_COLOURS} and ${MAX_COLOURS} colours`;
    if (p.leniency < 0) return tx`Extra moves must not be negative`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: 'Colours', value: String(p.colours) },
      { type: 'string', name: 'Extra moves permitted', value: String(p.leniency) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const num = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return { w: num(0), h: num(1), colours: num(2), leniency: num(3) };
  },

  newDesc(p, rng: Random) {
    const { w, h, colours } = p;
    const grid = new Uint8Array(w * h);
    // A grid that starts out finished would be no puzzle at all.
    do {
      for (let i = 0; i < grid.length; i++) grid[i] = rng.upto(colours);
    } while (isUniform(grid));
    const limit = solveGrid(grid, w, h, colours).length + p.leniency;
    return { desc: `${encodeGrid(grid)},${limit}` };
  },

  validateDesc(p, desc) {
    const wh = p.w * p.h;
    if (desc.length < wh) return tx`Not enough data in grid description`;
    for (let i = 0; i < wh; i++) {
      const c = charColour(desc[i]);
      if (c === null) return tx`Bad character in grid description`;
      if (c >= p.colours) return tx`Colour out of range in grid description`;
    }
    if (desc[wh] !== ',') return tx`Expected ',' after grid description`;
    if (!/^\d+$/.test(desc.slice(wh + 1)))
      return tx`Badly formatted move limit after grid description`;
    return null;
  },

  newGame(p, desc) {
    const { w, h, colours } = p;
    const wh = w * h;
    const grid = new Uint8Array(wh);
    for (let i = 0; i < wh; i++) grid[i] = charColour(desc[i])!;
    return {
      w,
      h,
      colours,
      grid,
      moves: 0,
      moveLimit: parseInt(desc.slice(wh + 1), 10),
      complete: isUniform(grid),
      cheated: false,
      autoSolved: false,
      soln: null,
      solnPos: 0,
    };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (curr.complete) throw new Error(tx`Already solved`);
    const seq = solveGrid(curr.grid, curr.w, curr.h, curr.colours);
    if (seq.length === 0) throw new Error(tx`Solver could not finish this grid`);
    return 'S' + seq.join(',');
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) rows.push(encodeGrid(s.grid.subarray(y * s.w, (y + 1) * s.w)));
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false, flashType: 'win' }),

  /**
   * The solver's next colour, played outright. It goes through the midend's hint hook, not
   * a key of the game's own, so every step counts against the hint allowance: a key that
   * made ordinary moves let a player hint the whole grid and still earn the credit.
   */
  hint(_orig, curr) {
    if (curr.complete) return null;
    const seq = solveGrid(curr.grid, curr.w, curr.h, curr.colours);
    return seq.length ? `M${seq[0]}` : null;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    let tx: number;
    let ty: number;
    if (b === LEFT_BUTTON) {
      const wasVisible = ui.cursorVisible;
      ui.cursorVisible = false;
      ({ x: tx, y: ty } = squareAt(ds, mx, my));
      const inside = tx >= 0 && ty >= 0 && tx < state.w && ty < state.h;
      if (!inside || state.complete || state.grid[ty * state.w + tx] === state.grid[FILL])
        return wasVisible ? '' : null;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, state.w, state.h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (isCursorSelect(b)) {
      ui.cursorVisible = true;
      tx = ui.cx;
      ty = ui.cy;
      if (state.complete || state.grid[ty * state.w + tx] === state.grid[FILL]) return null;
    } else {
      return null;
    }
    return `M${state.grid[ty * state.w + tx]}`;
  },

  executeMove(state, move) {
    const { w, h, colours } = state;
    const wh = w * h;
    if (state.complete) return null;
    if (move[0] === 'M') {
      const seq = parseSequence(move.slice(1), colours);
      if (!seq || seq.length !== 1 || seq[0] === state.grid[FILL]) return null;
      const c = seq[0];
      const grid = state.grid.slice();
      floodFill(grid, w, h, c, new Int32Array(wh));
      // Following the hint path advances it; leaving it discards it.
      let soln = state.soln;
      let solnPos = state.solnPos;
      if (soln) {
        if (c === soln[solnPos] && solnPos + 1 < soln.length) solnPos++;
        else {
          soln = null;
          solnPos = 0;
        }
      }
      return { ...state, grid, moves: state.moves + 1, complete: isUniform(grid), soln, solnPos };
    }
    if (move[0] === 'H') {
      const seq = parseSequence(move.slice(1), colours);
      if (!seq) return null;
      return { ...state, cheated: true, soln: seq, solnPos: 0 };
    }
    if (move[0] === 'S') {
      const seq = parseSequence(move.slice(1), colours);
      if (!seq) return null;
      const grid = state.grid.slice();
      const queue = new Int32Array(wh);
      for (const c of seq) {
        if (c === grid[FILL]) return null;
        floodFill(grid, w, h, c, queue);
      }
      return {
        ...state,
        grid,
        moves: state.moves + seq.length,
        complete: isUniform(grid),
        cheated: true,
        autoSolved: true,
        soln: null,
        solnPos: 0,
      };
    }
    return null;
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const b = boardOrigin(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, colours } = state;
    const wh = w * h;
    const t = ds.tileSize;
    const b = boardOrigin(t);
    const status = statusOf(state);

    // The grid as it should look right now: mid-fill, mid-flash, or simply as it is.
    let shown = state.grid;
    if (oldState) {
      const { dist, max } = waveDistances(oldState.grid, state.grid, w, h);
      const length = Math.min(WAVE_MAX, WAVE_STEP * (max + 1));
      const ring = Math.floor((animTime / length) * (max + 1));
      shown = oldState.grid.slice();
      for (let i = 0; i < wh; i++) {
        if (dist[i] < 0) continue;
        // Forwards the new colour spreads out from the corner; undone, it retreats.
        const reached = dir >= 0 ? dist[i] <= ring : dist[i] >= max - ring;
        if (reached) shown[i] = state.grid[i];
      }
    }
    let blackout = false;
    if (flashTime > 0) {
      if (ui.flashType === 'win') {
        const frame = Math.floor(flashTime / WIN_FRAME);
        shown = shown.slice();
        for (let i = 0; i < wh; i++) {
          const pos = frame - ((i % w) + Math.floor(i / w));
          if (pos >= 0 && pos < colours) shown[i] = pos;
        }
      } else {
        blackout = Math.floor(flashTime / LOSE_FRAME) !== 1;
      }
    }

    for (let i = 0; i < wh; i++) {
      const x = b + (i % w) * t;
      const y = b + Math.floor(i / w) * t;
      dr.rect(x, y, t, t, blackout ? 'lowlight' : SERIES[shown[i]]);
    }

    // Ink only where two different colours meet, in long strokes, like leading in a
    // stained-glass window.
    const lw = Math.max(1.6, t * 0.06);
    for (let x = 1; x < w; x++) {
      let y = 0;
      while (y < h) {
        if (shown[y * w + x - 1] === shown[y * w + x]) {
          y++;
          continue;
        }
        const y0 = y;
        while (y < h && shown[y * w + x - 1] !== shown[y * w + x]) y++;
        dr.line(b + x * t, b + y0 * t, b + x * t, b + y * t, 'ink', lw);
      }
    }
    for (let y = 1; y < h; y++) {
      let x = 0;
      while (x < w) {
        if (shown[(y - 1) * w + x] === shown[y * w + x]) {
          x++;
          continue;
        }
        const x0 = x;
        while (x < w && shown[(y - 1) * w + x] !== shown[y * w + x]) x++;
        dr.line(b + x0 * t, b + y * t, b + x * t, b + y * t, 'ink', lw);
      }
    }
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.8 });

    // Hint: dot every square the solver's next colour would bring into the region.
    if (state.soln && !state.complete && !oldState && flashTime === 0) {
      const marks = joiningSquares(state.grid, w, h, state.soln[state.solnPos]);
      for (let i = 0; i < wh; i++) {
        if (!marks[i]) continue;
        const cx = b + ((i % w) + 0.5) * t;
        const cy = b + (Math.floor(i / w) + 0.5) * t;
        dr.circle(cx, cy, t * 0.17, 'paper', 'ink', { width: 1.6 });
      }
    }

    if (ui.cursorVisible) {
      const inset = t * 0.12;
      const args = [
        b + ui.cx * t + inset,
        b + ui.cy * t + inset,
        t - 2 * inset,
        t - 2 * inset,
      ] as const;
      dr.cursor(...args, 'paper', 4.5);
      dr.cursor(...args, 'ink', 2.2);
    }

    const prefix =
      status === 1
        ? state.cheated
          ? tr('status.autoSolvedPrefix')
          : tr('status.completedPrefix')
        : state.moves >= state.moveLimit
          ? tr('status.failedPrefix')
          : state.cheated
            ? tr('status.autoSolverUsedPrefix')
            : '';
    dr.statusBar(
      prefix + tr('games.flood.status.moves', { n: state.moves, limit: state.moveLimit }),
    );
  },

  animLength(oldState, newState) {
    const { max } = waveDistances(oldState.grid, newState.grid, newState.w, newState.h);
    return max < 0 ? 0 : Math.min(WAVE_MAX, WAVE_STEP * (max + 1));
  },
  flashLength(oldState, newState, dir, ui) {
    if (dir <= 0 || statusOf(oldState) !== 0) return 0;
    const after = statusOf(newState);
    if (after === 1) {
      ui.flashType = 'win';
      return WIN_FRAME * (newState.w + newState.h + newState.colours - 2);
    }
    if (after === -1) {
      ui.flashType = 'lose';
      return LOSE_FRAME * 3;
    }
    return 0;
  },
  status: statusOf,
  wantsStatusBar: true,
  isTimed: false,
  flags: { oneButton: true },
  thumbnailParams: { w: 8, h: 8, colours: 6, leniency: 5 },
});

export default game;
