/** An ellipse as a path, so every eye style is one `<path>` and they compose the same way. */
function oval(cx: number, cy: number, rx: number, ry: number): string {
  return `M${cx - rx} ${cy} a${rx} ${ry} 0 1 0 ${rx * 2} 0 a${rx} ${ry} 0 1 0 ${-rx * 2} 0`;
}

interface EyeStyle {
  name: string;
  blurb: string;
  /** The eye, in ink, given its slot. May return several elements. */
  svg(e: EyeSlot, ink: string, face: string): string;
  /** How the canvas renderer approximates it at puzzle-tile size. */
  canvas: { kind: 'dot' | 'ring'; scale: number };
}

