export interface ZiggyOptions {
  size?: number;
  className?: string;
  shape?: ShapeId;
  eyes?: EyeId;
  body?: string;
  ink?: string;
  face?: string;
  /** Degrees. A mascot that is never quite upright looks drawn rather than placed. */
  tilt?: number;
}

/**
 * The three parts of the drawing that can be moved independently, and what each is for.
 *
 * A mascot that holds perfectly still reads as a sticker, so the DOM drawing is cut into
 * nested groups rather than one flat pile of shapes: `ui/mascot.ts` breathes the body,
 * blinks the eyes, and hops the `<svg>` itself, all at once and without any of the three
 * clobbering another's `transform`. The tilt gets a group of its own for the same reason
 * — it is authored on the element, and GSAP writes whole transforms, so anything animated
 * on the same node would wipe it (the splash learned this the hard way with the logo
 * piece). Nothing here changes how a still Ziggy renders.
 */
export const ZIGGY_TILT_CLASS = 'ziggy-tilt';
export const ZIGGY_BODY_CLASS = 'ziggy-body';
export const ZIGGY_EYES_CLASS = 'ziggy-eyes';

/**
 * Where Ziggy touches the ground, in viewBox coordinates — the origin a breath or a
 * squash turns about, because a body that scales around its middle floats rather than
 * settles.
 */
export const ZIGGY_FEET = '50 94';

/** Ziggy as an SVG string, for anywhere in the DOM. */
export function ziggySVG(opts: ZiggyOptions = {}): string {
  const {
    size,
    className = 'ziggy',
    shape = currentShape,
    eyes = currentEyes,
    body = PALETTE.violet,
    ink = PALETTE.ink,
    face = PALETTE.highlight,
    tilt = 0,
  } = opts;
  const s = SHAPES[shape] ?? SHAPES.s1;
  const e = EYES[eyes] ?? EYES.e2;
  const dim = size ? ` width="${size}" height="${size}"` : '';
  const spin = tilt ? ` transform="rotate(${tilt} 50 52)"` : '';
  // The eyeline, so a blink squashes both eyes towards each other rather than sliding
  // them up the face. Carried on the element because only the shape knows where it is.
  const lid = `${(s.eyes[0].cx + s.eyes[1].cx) / 2} ${(s.eyes[0].cy + s.eyes[1].cy) / 2}`;
  return `<svg class="${className}" viewBox="0 0 100 100"${dim} fill="none" aria-hidden="true">
  <g class="${ZIGGY_TILT_CLASS}"${spin}>
    <g class="${ZIGGY_BODY_CLASS}">
      <path d="${s.path}" fill="${body}" stroke="${ink}" stroke-width="5" stroke-linejoin="round"/>
      <ellipse cx="${s.face.cx}" cy="${s.face.cy}" rx="${s.face.rx}" ry="${s.face.ry}" fill="${face}" stroke="${ink}" stroke-width="4"/>
      <g class="${ZIGGY_EYES_CLASS}" data-lid="${lid}">
        ${s.eyes.map((slot) => e.svg(slot, ink, face)).join('\n        ')}
      </g>
    </g>
  </g>
</svg>`;
}

/**
 * Ziggy on the canvas, centred on (cx, cy) and fitting a box of side `s`.
 *
 * Composed from `Drawing` primitives rather than a raw path: it keeps the sketchy stroke,
 * the seeded wobble and the palette that every other mark on the board goes through, and it
 * means no game reaches past `Drawing` to the 2-D context. At puzzle-tile size the body is
 * a circle plus two ears plus a tail nub — the seams are invisible at 30px and the shape is
 * steadier than a shrunken outline would be.
 */
export function drawZiggy(
  dr: Drawing,
  cx: number,
  cy: number,
  s: number,
  seed: number,
  opts: {
    body?: string;
    outline?: string;
    face?: string;
    shape?: ShapeId;
    eyes?: EyeId;
  } = {},
): void {
  const sh = SHAPES[opts.shape ?? currentShape] ?? SHAPES.s1;
  const ey = EYES[opts.eyes ?? currentEyes] ?? EYES.e2;
  const body = opts.body ?? ZIGGY_COLOUR;
  const outline = opts.outline ?? 'ink';
  const faceCol = opts.face ?? 'highlight';
  const lw = Math.max(1.1, s * 0.055);
  const r = s * sh.canvas.r;

  // The tail, behind the body so the two read as one silhouette. Drawn before the ears for
  // the same reason: only the outer edge of each should ever be visible.
  if (sh.canvas.tail > 0.15) {
    const t = sh.canvas.tail;
    dr.polygon(
      [
        cx - r * 0.55,
        cy + r * 0.45,
        cx - r * (0.5 + 0.7 * t),
        cy + r * (0.85 + 0.5 * t),
        cx + r * 0.1,
        cy + r * 0.92,
      ],
      body,
      outline,
      { seed: seed + 9, width: lw, rough: 0.5 },
    );
  }
  for (const dx of [-0.62, 0.62]) {
    dr.polygon(
      [
        cx + r * dx - s * 0.13,
        cy - r * 0.62,
        cx + Math.sign(dx) * s * 0.43,
        cy - s * 0.46,
        cx + r * dx + s * 0.15,
        cy - r * 0.52,
      ],
      body,
      outline,
      { seed: seed + 7, width: lw, rough: 0.5 },
    );
  }
  dr.circle(cx, cy, r, body, outline, { seed, width: lw });

  // The face sits right of centre and a touch low, as it does in the original.
  const fr = r * sh.canvas.face;
  const fx = cx + r * 0.12;
  const fy = cy + r * 0.08;
  dr.circle(fx, fy, fr, faceCol, outline, { seed: seed + 1, width: lw * 0.8 });

  // The eye styles differ mostly in detail that does not survive to this size, so the
  // canvas keeps only what does: how big the dot is.
  const er = Math.max(0.9, fr * ey.canvas.scale);
  dr.dot(fx - fr * 0.42, fy - fr * 0.1, er, outline, { seed: seed + 2 });
  dr.dot(fx + fr * 0.42, fy - fr * 0.1, er, outline, { seed: seed + 3 });
}
