import type { Tutorial, TutorialCtx } from '../../framework/tutorial';
import { cellRect } from '../../framework/tutorial';
import type { TwiddleState, TwiddleUI } from './index';

type Ctx = TutorialCtx<TwiddleState, TwiddleUI>;
type Cell = { x: number; y: number };

const border = (t: number) => Math.round(t * 0.3);

/**
 * Spotlight the n×n block with the given top-left tile and point at its centre — the click
 * that rotates a block is the one nearest the middle of it. The corner is read from the
 * state so "the bottom-left block" stays in the bottom-left.
 */
function block(corner: (s: TwiddleState) => Cell, button?: 'right') {
  return {
    highlight: ({ state, tileSize }: Ctx) => {
      const c = corner(state);
      return cellRect(c.x, c.y, tileSize, border(tileSize), state.n, state.n);
    },
    pointer: ({ state, tileSize }: Ctx) => {
      const c = corner(state);
      return {
        x: border(tileSize) + (c.x + state.n / 2) * tileSize,
        y: border(tileSize) + (c.y + state.n / 2) * tileSize,
        ...(button ? { button } : {}),
      };
    },
  };
}

/** True once the last rotation was exactly the one we asked for. */
function turned(state: TwiddleState, x: number, y: number, dir: number): boolean {
  return state.lastX === x && state.lastY === y && state.lastDir === dir;
}

export const tutorial: Tutorial<TwiddleState, TwiddleUI> = {
  steps: [
    {
      gameId: '3x3n2:7,1,3,6,2,9,8,4,5',
      text: 'Get the numbers back into order, **1 to 9**. One move rotates a square block of four tiles a quarter turn; three turns finish this board.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'Click in the middle of the **top-left four tiles**. A left-click turns that block anticlockwise, which puts 1, 2, 3 along the top.',
      ...block(() => ({ x: 0, y: 0 })),
      waitFor: ({ state }) => turned(state, 0, 0, 1),
    },
    {
      text: '**Right-click** the middle of the **bottom-right four tiles** to turn that block clockwise instead.',
      ...block((s) => ({ x: s.w - s.n, y: s.h - s.n }), 'right'),
      waitFor: ({ state }) => turned(state, state.w - state.n, state.h - state.n, -1),
    },
    {
      text: 'Finish with a left-click in the middle of the **bottom-left four tiles**.',
      ...block((s) => ({ x: 0, y: s.h - s.n })),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Done! The **Type** menu has larger blocks and an *orientable* mode, where every tile also has to end up the right way up.',
      target: '.type-select',
    },
  ],
};
