import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_SELECT2,
  CURSOR_UP,
  LEFT_BUTTON,
  MOD_NUM_KEYPAD,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  stripMods,
} from '../../framework/input';
import { easeInOut, flashOn, parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { ROTATE_CW_GLYPH } from '../../framework/glyphs';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export interface TwiddleParams {
  w: number;
  h: number;
  /** Side length of the square block that rotates in one move. */
  n: number;
  /** Tiles carry their row number instead of a unique number. */
  rowsOnly: boolean;
  /** Tile orientation matters: every tile must end upright. */
  orientable: boolean;
  /** Exact number of shuffling moves, or 0 to shuffle thoroughly. */
  moveTarget: number;
}

/**
 * Each grid cell holds `number * 4 + orientation`. Orientation counts quarter turns
 * anticlockwise from upright: 0 = up, 1 = left, 2 = down, 3 = right. In non-orientable
 * puzzles the orientation bits are always zero.
 */
export interface TwiddleState {
  w: number;
  h: number;
  n: number;
  rowsOnly: boolean;
  orientable: boolean;
  grid: number[];
  moves: number;
  /** Move count at which the grid was first completed, or 0. */
  completed: number;
  usedSolve: boolean;
  moveTarget: number;
  /** Top-left corner and direction (+1 anticlockwise, -1 clockwise) of the last rotation. */
  lastX: number;
  lastY: number;
  lastDir: number;
}

export interface TwiddleUI {
  /** Top-left corner of the keyboard-selected block. */
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /**
   * The Clockwise tool swaps the two buttons over: a left click (a plain tap) turns a
   * block clockwise and the right one (a long-press) anticlockwise, so either way round
   * is one gesture away and a one-button mouse gets both.
   */
  clockwise: boolean;
}

const ANIM_PER_UNIT = 0.13;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const ORIENT_LETTERS = 'uldr';
const ORIENT_TEXT = '^<v>';

// ------------------------------------------------------------------ grid logic

/** The finished grid for these parameters. */
export function solvedGrid(p: { w: number; h: number; rowsOnly: boolean }): number[] {
  const out: number[] = [];
  for (let i = 0; i < p.w * p.h; i++) out.push(((p.rowsOnly ? Math.floor(i / p.w) : i) + 1) * 4);
  return out;
}

/**
 * Rotate the n×n block with top-left corner (x, y) in place. `dir` +1 turns it a quarter
 * anticlockwise, -1 clockwise. In orientable mode each tile turns with the block.
 */
function rotateInPlace(
  grid: number[],
  w: number,
  n: number,
  orientable: boolean,
  x: number,
  y: number,
  dir: number,
): void {
  const src: number[] = [];
  for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) src.push(grid[(y + j) * w + x + i]);
  const turn = dir > 0 ? 1 : 3;
  for (let j = 0; j < n; j++) {
    for (let i = 0; i < n; i++) {
      // Anticlockwise, cell (i, j) receives the tile from (n-1-j, i); clockwise from (j, n-1-i).
      const si = dir > 0 ? n - 1 - j : j;
      const sj = dir > 0 ? i : n - 1 - i;
      let v = src[sj * n + si];
      if (orientable) v = (v & ~3) | ((v + turn) & 3);
      grid[(y + j) * w + x + i] = v;
    }
  }
}

/** Pure version of {@link rotateInPlace}: returns a new grid. */
export function rotateBlock(
  grid: number[],
  w: number,
  n: number,
  orientable: boolean,
  x: number,
  y: number,
  dir: number,
): number[] {
  const out = grid.slice();
  rotateInPlace(out, w, n, orientable, x, y, dir);
  return out;
}

/** Complete when the numbers never decrease and (if it matters) every tile is upright. */
export function gridComplete(grid: number[], orientable: boolean): boolean {
  for (let i = 0; i < grid.length; i++) {
    if (i > 0 && grid[i] >> 2 < grid[i - 1] >> 2) return false;
    if (orientable && (grid[i] & 3) !== 0) return false;
  }
  return true;
}

/** Parity of a permutation of 0..n-1: 0 even, 1 odd. */
function permutationParity(perm: number[]): number {
  const seen = new Uint8Array(perm.length);
  let odd = 0;
  for (let start = 0; start < perm.length; start++) {
    if (seen[start]) continue;
    let len = 0;
    for (let j = start; !seen[j]; j = perm[j]) {
      seen[j] = 1;
      len++;
    }
    odd ^= (len - 1) & 1;
  }
  return odd;
}

function sameGrid(a: number[], b: number[]): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

/**
 * Necessary conditions for a grid to be reachable from the solved one. Every rotation
 * has invariants that a hand-typed description can violate:
 *
 * - When the whole grid is one block, only its four rotations are reachable.
 * - An n×n rotation is a product of ⌊n²/4⌋ four-cycles, which is an even permutation
 *   unless n ≡ 2 (mod 4); with distinct tiles the permutation parity is then invariant.
 * - For even n, n² ≡ 0 (mod 4) tiles turn a quarter each move, so the sum of all
 *   orientations mod 4 never changes.
 */
export function solvable(grid: number[], p: TwiddleParams): boolean {
  const { w, h, n, orientable } = p;
  if (w === n && h === n) {
    let g = solvedGrid(p);
    for (let k = 0; k < 4; k++) {
      if (sameGrid(g, grid)) return true;
      g = rotateBlock(g, w, n, orientable, 0, 0, 1);
    }
    return false;
  }
  if (orientable && n % 2 === 0) {
    let sum = 0;
    for (const v of grid) sum += v & 3;
    if (sum % 4 !== 0) return false;
  }
  if (!p.rowsOnly && n % 4 !== 2) {
    if (permutationParity(grid.map((v) => (v >> 2) - 1)) !== 0) return false;
  }
  return true;
}

// ------------------------------------------------------- description handling

function encodeGrid(grid: number[], orientable: boolean): string {
  if (orientable) return grid.map((v) => `${v >> 2}${ORIENT_LETTERS[v & 3]}`).join('');
  return grid.map((v) => String(v >> 2)).join(',');
}

/** Parse a description into a grid, or return a user-facing error. */
function parseDesc(p: TwiddleParams, desc: string): number[] | string {
  const wh = p.w * p.h;
  const cells: number[] = [];
  if (p.orientable) {
    if (!/^(\d+[uldr])*$/.test(desc))
      return tx`Description must be numbers each followed by an orientation letter (u, l, d or r)`;
    for (const m of desc.matchAll(/(\d+)([uldr])/g))
      cells.push(parseInt(m[1], 10) * 4 + ORIENT_LETTERS.indexOf(m[2]));
  } else {
    if (!/^\d+(,\d+)*$/.test(desc))
      return tx`Description must be a comma-separated list of numbers`;
    for (const s of desc.split(',')) cells.push(parseInt(s, 10) * 4);
  }
  if (cells.length !== wh) return tx`Description must contain ${wh} tiles`;
  const expected = solvedGrid(p).map((v) => v >> 2);
  const actual = cells.map((v) => v >> 2).sort((a, b) => a - b);
  if (!sameGrid(expected, actual)) {
    return p.rowsOnly
      ? tx`Description must contain each row number from 1 to ${p.h} exactly ${p.w} times`
      : tx`Description must contain each number from 1 to ${wh} exactly once`;
  }
  return cells;
}

/**
 * Shuffle the solved grid with a long sequence of random rotations. Rotations that
 * would simply undo (or over-repeat) the previous rotation of an undisturbed block are
 * avoided so the shuffle actually goes somewhere. Because a block rotation can be an odd
 * permutation, the default move count is randomly even or odd so both parities occur.
 */
function shuffledGrid(p: TwiddleParams, rng: Random): number[] {
  const { w, h, n, orientable } = p;
  const grid = solvedGrid(p);
  const total = p.moveTarget || w * h * n * n * 2 + rng.upto(2);
  const rw = w - n + 1;
  const rh = h - n + 1;
  const wholeGrid = rw === 1 && rh === 1;
  do {
    // Net quarter turns applied to each block since it was last disturbed.
    const net = new Int32Array(rw * rh);
    for (let m = 0; m < total; m++) {
      let x: number;
      let y: number;
      let dir: number;
      for (;;) {
        x = rng.upto(rw);
        y = rng.upto(rh);
        dir = rng.upto(2) ? 1 : -1;
        if (wholeGrid) break;
        const before = net[y * rw + x];
        const after = before + dir;
        if (Math.abs(after) >= Math.abs(before) && Math.abs(after) <= 2) break;
      }
      rotateInPlace(grid, w, n, orientable, x, y, dir);
      net[y * rw + x] += dir;
      for (let dy = 1 - n; dy < n; dy++) {
        for (let dx = 1 - n; dx < n; dx++) {
          if (dx === 0 && dy === 0) continue;
          const bx = x + dx;
          const by = y + dy;
          if (bx >= 0 && by >= 0 && bx < rw && by < rh) net[by * rw + bx] = 0;
        }
      }
    }
  } while (gridComplete(grid, orientable));
  return grid;
}

// ---------------------------------------------------------------- geometry

function animLen(n: number): number {
  return ANIM_PER_UNIT * Math.sqrt(n - 1);
}

function borderFor(t: number): number {
  return Math.round(t * 0.3);
}

const game = defineGame<TwiddleParams, TwiddleState, TwiddleUI>({
  id: 'twiddle',
  name: 'Twiddle',
  description: 'Rotate square blocks of tiles to put the numbers back in order.',
  help,
  tutorial,
  achievements,
  presets: [
    { name: '3×3 rows only', params: p(3, 3, 2, { rowsOnly: true }) },
    { name: '3×3 normal', params: p(3, 3, 2) },
    { name: '3×3 orientable', params: p(3, 3, 2, { orientable: true }) },
    { name: '4×4 normal', params: p(4, 4, 2) },
    { name: '4×4 orientable', params: p(4, 4, 2, { orientable: true }) },
    { name: '4×4, rotating 3×3 blocks', params: p(4, 4, 3) },
    { name: '5×5, rotating 3×3 blocks', params: p(5, 5, 3) },
    { name: '6×6, rotating 4×4 blocks', params: p(6, 6, 4) },
  ],
  thumbnailParams: p(3, 3, 2),
  defaultParams: () => p(3, 3, 2),

  encodeParams(params) {
    // The move target is part of every encoding: it appears in the status bar.
    let s = `${params.w}x${params.h}n${params.n}`;
    if (params.rowsOnly) s += 'r';
    if (params.orientable) s += 'o';
    if (params.moveTarget) s += `m${params.moveTarget}`;
    return s;
  },
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    const out = p(r.w, r.h, 2);
    let rest = r.rest;
    const nm = /^n(\d+)/.exec(rest);
    if (nm) {
      out.n = parseInt(nm[1], 10);
      rest = rest.slice(nm[0].length);
    }
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i];
      if (c === 'r') out.rowsOnly = true;
      else if (c === 'o') out.orientable = true;
      else if (c === 'm') {
        const d = /^\d+/.exec(rest.slice(i + 1));
        if (d) {
          out.moveTarget = parseInt(d[0], 10);
          i += d[0].length;
        }
      }
    }
    return out;
  },
  validateParams(params) {
    const { w, h, n, moveTarget } = params;
    if (![w, h, n, moveTarget].every(Number.isInteger))
      return tx`Width, height, block size and move count must be whole numbers`;
    if (n < 2) return tx`Rotating block size must be at least two`;
    if (w < n) return tx`Width must be at least the rotating block size`;
    if (h < n) return tx`Height must be at least the rotating block size`;
    if (w > 12 || h > 12) return tx`Width and height must be at most twelve`;
    if (moveTarget < 0) return tx`Number of shuffling moves cannot be negative`;
    if (moveTarget > 10000) return tx`Number of shuffling moves must be at most 10000`;
    return null;
  },
  configure(params): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(params.w) },
      { type: 'string', name: 'Height', value: String(params.h) },
      { type: 'string', name: 'Rotating block size', value: String(params.n) },
      { type: 'boolean', name: 'One number per row', value: params.rowsOnly },
      { type: 'boolean', name: 'Orientation matters', value: params.orientable },
      { type: 'string', name: 'Number of shuffling moves', value: String(params.moveTarget) },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    const bool = (i: number) => (items[i] as { value: boolean }).value;
    const int = (s: string) => (/^-?\d+$/.test(s) ? parseInt(s, 10) : NaN);
    return {
      w: int(str(0)),
      h: int(str(1)),
      n: int(str(2)),
      rowsOnly: bool(3),
      orientable: bool(4),
      moveTarget: str(5) === '' ? 0 : int(str(5)),
    };
  },

  newDesc(params, rng) {
    return { desc: encodeGrid(shuffledGrid(params, rng), params.orientable) };
  },
  validateDesc(params, desc) {
    const grid = parseDesc(params, desc);
    if (typeof grid === 'string') return grid;
    if (!solvable(grid, params)) return tx`This arrangement cannot be solved`;
    return null;
  },
  newGame(params, desc) {
    const grid = parseDesc(params, desc);
    if (typeof grid === 'string') throw new Error(grid);
    return {
      w: params.w,
      h: params.h,
      n: params.n,
      rowsOnly: params.rowsOnly,
      orientable: params.orientable,
      grid,
      moves: 0,
      completed: 0,
      usedSolve: false,
      moveTarget: params.moveTarget,
      lastX: -1,
      lastY: -1,
      lastDir: 0,
    };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (gridComplete(curr.grid, curr.orientable)) throw new Error(tx`Already solved`);
    return 'S';
  },

  textFormat(s) {
    const width = String(Math.max(...s.grid.map((v) => v >> 2))).length;
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const row: string[] = [];
      for (let x = 0; x < s.w; x++) {
        const v = s.grid[y * s.w + x];
        row.push(String(v >> 2).padStart(width, ' ') + (s.orientable ? ORIENT_TEXT[v & 3] : ''));
      }
      rows.push(row.join(' '));
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false, clockwise: false }),

  actions: [
    {
      label: 'Clockwise',
      key: 'T',
      hud: true,
      glyph: ROTATE_CW_GLYPH,
      pressed: (_s, ui) => ui.clockwise,
      title: 'Swap the directions: clicks turn clockwise, right-clicks anticlockwise (T)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const { w, h, n } = state;
    const c = stripMods(button);
    const keypad = (button & MOD_NUM_KEYPAD) !== 0;
    const kp = (digit: string) => keypad && c === digit.charCodeAt(0);
    const key = (ch: string) => !keypad && c === ch.charCodeAt(0);

    if (key('t') || key('T')) {
      ui.clockwise = !ui.clockwise;
      return '';
    }

    if (isCursorMove(c)) {
      if (c === CURSOR_LEFT && ui.cx > 0) ui.cx--;
      if (c === CURSOR_RIGHT && ui.cx + n < w) ui.cx++;
      if (c === CURSOR_UP && ui.cy > 0) ui.cy--;
      if (c === CURSOR_DOWN && ui.cy + n < h) ui.cy++;
      ui.cursorVisible = true;
      return '';
    }

    let x: number;
    let y: number;
    let dir: number;
    if (c === LEFT_BUTTON || c === RIGHT_BUTTON) {
      // Choose the block whose centre is nearest the click: shift by half the block
      // (minus one tile) and take the tile under the shifted point as the top-left.
      // A click on the outer half of an edge tile has no block centred nearer than the
      // one at that edge, so it turns that block rather than doing nothing: on a 3×3 grid
      // the dead band would otherwise be more than half the board.
      const t = ds.tileSize;
      const border = borderFor(t);
      if (mx < border || my < border || mx >= border + w * t || my >= border + h * t) return null;
      const off = border + ((n - 1) * t) / 2;
      x = Math.min(Math.max(Math.floor((mx - off) / t), 0), w - n);
      y = Math.min(Math.max(Math.floor((my - off) / t), 0), h - n);
      dir = (c === LEFT_BUTTON) !== ui.clockwise ? 1 : -1;
      ui.cursorVisible = false;
    } else if (isCursorSelect(c)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      x = ui.cx;
      y = ui.cy;
      dir = c === CURSOR_SELECT2 ? -1 : 1;
    } else if (key('a') || key('A') || kp('7')) {
      x = 0;
      y = 0;
      dir = key('A') ? -1 : 1;
    } else if (key('b') || key('B') || kp('9')) {
      x = w - n;
      y = 0;
      dir = key('B') ? -1 : 1;
    } else if (key('c') || key('C') || kp('1')) {
      x = 0;
      y = h - n;
      dir = key('C') ? -1 : 1;
    } else if (key('d') || key('D') || kp('3')) {
      x = w - n;
      y = h - n;
      dir = key('D') ? -1 : 1;
    } else if (kp('8') && (w - n) % 2 === 0) {
      x = (w - n) / 2;
      y = 0;
      dir = 1;
    } else if (kp('2') && (w - n) % 2 === 0) {
      x = (w - n) / 2;
      y = h - n;
      dir = 1;
    } else if (kp('4') && (h - n) % 2 === 0) {
      x = 0;
      y = (h - n) / 2;
      dir = 1;
    } else if (kp('6') && (h - n) % 2 === 0) {
      x = w - n;
      y = (h - n) / 2;
      dir = 1;
    } else if (kp('5') && (w - n) % 2 === 0 && (h - n) % 2 === 0) {
      x = (w - n) / 2;
      y = (h - n) / 2;
      dir = 1;
    } else {
      return null;
    }
    return `M${x},${y},${dir}`;
  },

  executeMove(state, move) {
    if (move === 'S') {
      const grid = state.grid.map((v) => v & ~3).sort((a, b) => a - b);
      return {
        ...state,
        grid,
        usedSolve: true,
        completed: state.moves,
        lastX: -1,
        lastY: -1,
        lastDir: 0,
      };
    }
    const m = /^M(\d+),(\d+),(-?1)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[1], 10);
    const y = parseInt(m[2], 10);
    const dir = parseInt(m[3], 10);
    if (x > state.w - state.n || y > state.h - state.n) return null;
    const grid = rotateBlock(state.grid, state.w, state.n, state.orientable, x, y, dir);
    const moves = state.moves + 1;
    // After a Solve, `completed` marks the move count it was used at (possibly 0) and
    // must not move on when the player turns the grid back to finished.
    const completed =
      state.completed || state.usedSolve
        ? state.completed
        : gridComplete(grid, state.orientable)
          ? moves
          : 0;
    return { ...state, grid, moves, completed, lastX: x, lastY: y, lastDir: dir };
  },

  preferredTileSize: 48,
  computeSize(params, t) {
    const border = borderFor(t);
    return { w: params.w * t + 2 * border, h: params.h * t + 2 * border };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, n } = state;
    const t = ds.tileSize;
    const border = borderFor(t);
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const target = solvedGrid(state);

    dr.rect(border - 4, border - 4, w * t + 8, h * t + 8, flashing ? 'shade' : null, 'ink', {
      width: 2.4,
    });

    // A rotation in progress: which block, and how far is it still turned away from
    // its final position? Undo animates the previous rotation backwards.
    let rot: { x: number; y: number; angle: number } | null = null;
    if (oldState) {
      const src = dir > 0 ? state : oldState;
      if (src.lastX >= 0) {
        const rdir = dir > 0 ? src.lastDir : -src.lastDir;
        const progress = easeInOut(animTime / animLen(n));
        rot = { x: src.lastX, y: src.lastY, angle: (Math.PI / 2) * rdir * (1 - progress) };
      }
    }
    const inBlock = (gx: number, gy: number) =>
      !!rot && gx >= rot.x && gx < rot.x + n && gy >= rot.y && gy < rot.y + n;

    const pad = Math.max(2, t * 0.06);
    const drawBody = (gx: number, gy: number) => {
      const i = gy * w + gx;
      const v = state.grid[i];
      const px = border + gx * t;
      const py = border + gy * t;
      const inPlace = v === target[i];
      dr.roundRect(
        px + pad,
        py + pad,
        t - 2 * pad,
        t - 2 * pad,
        t * 0.14,
        inPlace ? 'shade' : 'paper',
        'ink',
        {
          width: 1.8,
          seed: v,
        },
      );
      if (state.orientable) {
        // A triangle pointing the tile's way up: the puzzle is done when they all point up.
        let ux = 0;
        let uy = -1;
        for (let k = v & 3; k > 0; k--) [ux, uy] = [uy, -ux];
        const cx = px + t / 2;
        const cy = py + t / 2;
        const tip = t * 0.36;
        const base = t * 0.2;
        const half = t * 0.3;
        dr.polygon(
          [
            cx + ux * tip,
            cy + uy * tip,
            cx - ux * base - uy * half,
            cy - uy * base + ux * half,
            cx - ux * base + uy * half,
            cy - uy * base - ux * half,
          ],
          'faint',
          'pencil',
          { width: 1.2, seed: v, alpha: 0.75 },
        );
      }
    };
    const drawNumber = (gx: number, gy: number, cx: number, cy: number) => {
      const v = state.grid[gy * w + gx];
      dr.text(cx, cy, String(v >> 2), {
        size: t * (state.orientable ? 0.42 : 0.5),
        colour: flashing ? 'ok' : 'ink',
        maxWidth: t * 0.8,
      });
    };

    for (let gy = 0; gy < h; gy++) {
      for (let gx = 0; gx < w; gx++) {
        if (inBlock(gx, gy)) continue;
        drawBody(gx, gy);
        drawNumber(gx, gy, border + gx * t + t / 2, border + gy * t + t / 2);
      }
    }

    if (rot) {
      // Draw the turning block last so it sits on top of its neighbours, clipped to the
      // inside of the frame so its corners slide under the border rather than poking out.
      // The tiles turn about the block centre; the numbers stay upright, as on the original.
      const ox = border + (rot.x + n / 2) * t;
      const oy = border + (rot.y + n / 2) * t;
      dr.clip(border - 3, border - 3, w * t + 6, h * t + 6);
      const ctx = dr.ctx;
      ctx.save();
      ctx.translate(ox, oy);
      ctx.rotate(rot.angle);
      ctx.translate(-ox, -oy);
      for (let gy = rot.y; gy < rot.y + n; gy++)
        for (let gx = rot.x; gx < rot.x + n; gx++) drawBody(gx, gy);
      ctx.restore();
      const cos = Math.cos(rot.angle);
      const sin = Math.sin(rot.angle);
      for (let gy = rot.y; gy < rot.y + n; gy++) {
        for (let gx = rot.x; gx < rot.x + n; gx++) {
          const dx = border + gx * t + t / 2 - ox;
          const dy = border + gy * t + t / 2 - oy;
          drawNumber(gx, gy, ox + dx * cos - dy * sin, oy + dx * sin + dy * cos);
        }
      }
      dr.unclip();
    }

    if (ui.cursorVisible) {
      dr.cursor(border + ui.cx * t + 1, border + ui.cy * t + 1, n * t - 2, n * t - 2);
    }

    // Report the state being shown: during an animation that is still the old one.
    const s = oldState ? oldState : state;
    let text: string;
    if (s.usedSolve) {
      text = tr('status.movesSinceSolve', { n: s.moves - s.completed });
    } else {
      text =
        (s.completed ? tr('status.completedPrefix') : '') +
        tr('status.moves', { n: s.completed ? s.completed : s.moves });
      if (s.moveTarget) text += tr('status.target', { n: s.moveTarget });
    }
    dr.statusBar(text);
  },

  animLength(oldState, newState, dir) {
    const src = dir > 0 ? newState : oldState;
    return src.lastX >= 0 ? animLen(newState.n) : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (gridComplete(s.grid, s.orientable) ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  // The Clockwise tool is this game's Tap switch: "Tap: mark" made a tap turn a block
  // clockwise, exactly as the lit tool does, so a phone showed two buttons for one thing
  // (and the switch greyed out whenever the tool was on). The long-press still turns the
  // other way, and the tutorial teaches it.
  flags: { oneButton: true },
});

function p(
  w: number,
  h: number,
  n: number,
  extra: Partial<Pick<TwiddleParams, 'rowsOnly' | 'orientable' | 'moveTarget'>> = {},
): TwiddleParams {
  return { w, h, n, rowsOnly: false, orientable: false, moveTarget: 0, ...extra };
}

export default game;
