import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { SignpostParams, SignpostState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A board square with its arrow, pointing `deg` degrees clockwise from north. */
function square(c: C, x: number, y: number, s: number, deg: number, fill = c.paper): string {
  const cx = x + s / 2;
  const cy = y + s / 2;
  const r = s * 0.28;
  const head = s * 0.16;
  return (
    shape(`M${x} ${y} h${s} v${s} h${-s} Z`, fill, c.ink, 3.5) +
    `<g transform="rotate(${deg} ${cx} ${cy})">` +
    line(`M${cx} ${cy + r} V${cy - r}`, c.ink, 4) +
    line(
      `M${cx - head} ${cy - r + head} L${cx} ${cy - r} L${cx + head} ${cy - r + head}`,
      c.ink,
      4,
    ) +
    '</g>'
  );
}

function star(c: C, cx: number, cy: number, r: number, fill: string): string {
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r * 0.45 : r;
    pts.push(`${(cx + rr * Math.cos(a)).toFixed(1)} ${(cy + rr * Math.sin(a)).toFixed(1)}`);
  }
  return shape(`M${pts.join(' L')} Z`, fill, c.ink, 4);
}

/** Square indices whose successor changed between two positions. */
function changedLinks(a: SignpostState, b: SignpostState): number[] {
  const out: number[] = [];
  for (let i = 0; i < b.next.length; i++) if (a.next[i] !== b.next[i]) out.push(i);
  return out;
}

/** The square the puzzle numbers `k`, or -1. */
function given(s: SignpostState, k: number): number {
  for (let i = 0; i < s.nums.length; i++) if (s.immutable[i] && s.nums[i] === k) return i;
  return -1;
}

export const achievements = defineAchievements<SignpostParams, SignpostState>([
  {
    id: 'unbroken',
    name: 'Unbroken Chain',
    description: 'Solve a Signpost without ever removing or replacing a link.',
    tier: 'silver',
    hue: 'blue',
    art: (c) => {
      let links = '';
      for (let i = 0; i < 3; i++) {
        const x = 30 + i * 20;
        links += `<ellipse cx="${x}" cy="66" rx="13" ry="8.5" fill="none" stroke="${i === 1 ? c.blue : c.ink}" stroke-width="5.5"/>`;
      }
      return (
        square(c, 17, 20, 20, 90) + square(c, 40, 20, 20, 90) + square(c, 63, 20, 20, 135) + links
      );
    },
    // Every link, once made, is still there, pointing the same way, in every later board.
    test: (ctx) => {
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1];
        const b = ctx.history[k];
        for (const i of changedLinks(a, b)) if (a.next[i] !== -1) return false;
      }
      return true;
    },
  },
  {
    id: 'in-order',
    name: 'Straight Through',
    description: 'Solve a 6×6 or larger Signpost linking the path in order, from 1 to the star.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) => {
      let grid = '';
      for (let i = 0; i < 9; i++) {
        const x = 20 + (i % 3) * 20;
        const y = 20 + Math.floor(i / 3) * 20;
        grid += shape(`M${x} ${y} h20 v20 h-20 Z`, c.paper, c.ink, 3);
      }
      return (
        grid +
        line('M30 30 H70 V50 H30 V70 H60', c.blue, 7) +
        `<circle cx="30" cy="30" r="6" fill="${c.blue}" stroke="${c.ink}" stroke-width="3"/>` +
        star(c, 70, 70, 13, c.yellow)
      );
    },
    // Every move extends the chain that starts at 1 from its far end, and breaks nothing.
    // (The board joins two consecutive numbers by itself, so a move may add more than one
    // link; those only ever continue the same chain.)
    test: (ctx) => {
      if (ctx.params.w * ctx.params.h < 36) return false;
      const start = given(ctx.initial, 1);
      if (start < 0) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1];
        const b = ctx.history[k];
        for (const i of changedLinks(a, b)) if (a.next[i] !== -1) return false;
        let head = start;
        for (let guard = 0; a.next[head] !== -1 && guard < a.n; guard++) head = a.next[head];
        if (b.next[head] === -1) return false;
      }
      return true;
    },
  },
  {
    id: 'star-first',
    name: 'Wish Upon a Star',
    description: 'Make your very first link into the star, then solve the puzzle.',
    tier: 'bronze',
    hidden: true,
    hue: 'purple',
    art: (c) =>
      square(c, 18, 58, 24, 45) +
      `<path d="M42 58 Q46 40 58 38" fill="none" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round" stroke-dasharray="1 8"/>` +
      star(c, 64, 36, 20, c.yellow),
    test: (ctx) => {
      const end = given(ctx.initial, ctx.initial.n);
      // The first link since the last Restart, which puts the links back as dealt: the
      // attempt it threw away does not count.
      const dealt = (s: SignpostState) => s.next.every((v, i) => v === ctx.initial.next[i]);
      let from = 1;
      for (let k = 1; k < ctx.history.length; k++) if (dealt(ctx.history[k])) from = k + 1;
      for (let k = from; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1];
        const b = ctx.history[k];
        if (changedLinks(a, b).length === 0) continue;
        return end >= 0 && a.prev[end] === -1 && b.prev[end] !== -1;
      }
      return false;
    },
  },
]);
