import type { Tutorial, TutorialCtx } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { LineMove, SixteenState, SixteenUI } from './index';

type Ctx = TutorialCtx<SixteenState, SixteenUI>;
type Cell = { x: number; y: number };

/** The arrow strip is one tile wide all the way round, so the border *is* the tile size. */
const border = (t: number) => t;

/**
 * Spotlight one cell of the arrow ring and point at it. `cell` is in grid coordinates, so
 * -1 and w/h pick out the arrows, and it is read from the state so "the bottom row" stays
 * the bottom row.
 */
function arrow(cell: (s: SixteenState) => Cell, button?: 'right') {
  return {
    highlight: ({ state, tileSize }: Ctx) => {
      const c = cell(state);
      return cellRect(c.x, c.y, tileSize, border(tileSize));
    },
    pointer: ({ state, tileSize }: Ctx) => {
      const c = cell(state);
      return {
        ...cellCentre(c.x, c.y, tileSize, border(tileSize)),
        ...(button ? { button } : {}),
      };
    },
  };
}

/** True once the last completed move was exactly the slide we asked for. */
function slid(state: SixteenState, want: LineMove): boolean {
  const l = state.last;
  return !!l && l.row === want.row && l.index === want.index && l.dir === want.dir;
}

export const tutorial: Tutorial<SixteenState, SixteenUI> = {
  steps: [
    {
      gameId: '3x3:3,9,2,4,1,6,8,5,7',
      text: 'Put the tiles in order, **1 to 9**, reading left to right. The arrows round the edge slide a whole row or column one step, and whatever drops off comes back on the far side.',
      highlight: ({ state, tileSize }) =>
        cellRect(-1, -1, tileSize, border(tileSize), state.w + 2, state.h + 2),
    },
    {
      text: 'Click the arrow **above the second column** to slide that column up one step; that completes the middle row.',
      ...arrow(() => ({ x: 1, y: -1 })),
      waitFor: ({ state }) => slid(state, { row: false, index: 1, dir: -1 }),
    },
    {
      text: 'Now the bottom row needs to shift right. **Right-click** the arrow to the **left of the bottom row**: a right-click sends the line the opposite way.',
      ...arrow((s) => ({ x: -1, y: s.h - 1 }), 'right'),
      waitFor: ({ state }) => slid(state, { row: true, index: state.h - 1, dir: 1 }),
    },
    {
      text: 'Last one: click the arrow to the **left of the top row** to slide it left and finish the grid.',
      ...arrow(() => ({ x: -1, y: 0 })),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'In order! **Type**, in the pause menu, offers bigger grids, and its **Custom…** can scramble one with a set number of shuffling moves for you to undo.',
      target: '.type-select',
    },
  ],
};
