import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { F_BLACK, F_CIRCLE } from './board';
import type { SinglesParams, SinglesState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A piece of the board: `cols`×`rows` squares of side `s`, the listed ones blacked out. */
function grid(c: C, x: number, y: number, s: number, cols: number, rows: number, black: number[]) {
  let out = '';
  for (let i = 0; i < cols * rows; i++) {
    const cx = x + (i % cols) * s;
    const cy = y + Math.floor(i / cols) * s;
    out += shape(
      `M${cx} ${cy} h${s} v${s} h${-s} Z`,
      black.includes(i) ? c.ink : c.paper,
      c.ink,
      3,
    );
  }
  return out;
}

export const achievements = defineAchievements<SinglesParams, SinglesState>([
  {
    id: 'no-circles',
    name: 'No Circles Needed',
    description: 'Solve an 8×8 or larger Singles without circling a single number.',
    tier: 'silver',
    hue: 'teal',
    art: (c) =>
      grid(c, 18, 18, 16, 3, 3, [1, 3, 8]) +
      `<circle cx="64" cy="64" r="16" fill="${c.paper}" stroke="${c.ink}" stroke-width="5"/>` +
      line('M52 76 L76 52', c.red, 7),
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 64 && ctx.history.every((s) => !s.flags.includes(F_CIRCLE)),
  },
  {
    id: 'sure-hand',
    name: 'Sure Hand',
    description: 'Solve a 10×10 or larger Singles without restoring a blacked-out square.',
    tier: 'gold',
    hue: 'red',
    art: (c) =>
      grid(c, 26, 52, 16, 3, 2, [1, 3, 5]) +
      // A rubber stamp that has just come down on the middle square.
      `<circle cx="50" cy="20" r="7" fill="${c.brown}" stroke="${c.ink}" stroke-width="4"/>` +
      shape('M46 26 H54 V38 H46 Z', c.brown, c.ink, 4) +
      shape('M38 38 H62 V47 H38 Z', c.red, c.ink, 4) +
      line('M24 43 H31 M69 43 H76 M27 31 L33 35 M73 31 L67 35', c.ink, 4),
    test: (ctx) => {
      if (ctx.params.w * ctx.params.h < 100) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].flags;
        const b = ctx.history[k].flags;
        for (let i = 0; i < b.length; i++) if (a[i] === F_BLACK && b[i] !== F_BLACK) return false;
      }
      return true;
    },
  },
]);
