import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { EMPTY, FULL } from './clues';
import type { PatternParams, PatternState } from './index';

type C = typeof PALETTE;

/** A small nonogram: '#' a black square, '.' a dot, anything else left blank. */
function grid(c: C, x: number, y: number, s: number, rows: string[]): string {
  const n = rows[0].length;
  let out = `<rect x="${x}" y="${y}" width="${n * s}" height="${rows.length * s}" fill="${c.paper}"/>`;
  let lines = '';
  for (let i = 1; i < n; i++) lines += `M${x + i * s} ${y} V${y + rows.length * s} `;
  for (let j = 1; j < rows.length; j++) lines += `M${x} ${y + j * s} H${x + n * s} `;
  out += `<path d="${lines}" stroke="${c.faint}" stroke-width="1.5"/>`;
  rows.forEach((row, j) => {
    for (let i = 0; i < n; i++) {
      const px = x + i * s;
      const py = y + j * s;
      if (row[i] === '#')
        out += `<rect x="${px + 1}" y="${py + 1}" width="${s - 2}" height="${s - 2}" fill="${c.ink}"/>`;
      else if (row[i] === '.')
        out += `<circle cx="${px + s / 2}" cy="${py + s / 2}" r="${s * 0.14}" fill="${c.ink}"/>`;
    }
  });
  return (
    out +
    `<rect x="${x}" y="${y}" width="${n * s}" height="${rows.length * s}" fill="none" stroke="${c.ink}" stroke-width="3.5"/>`
  );
}

export const achievements = defineAchievements<PatternParams, PatternState>([
  {
    id: 'no-dots',
    name: 'Not a Dot',
    description: 'Solve a Pattern of 15×15 or larger without placing a single dot.',
    tier: 'silver',
    hue: 'blue',
    // A finished picture, and a dot under a "no" sign.
    art: (c) =>
      grid(c, 20, 20, 12, ['##  ', ' #  ', '### ', ' # #']) +
      `<circle cx="66" cy="66" r="14" fill="${c.paper}" stroke="${c.red}" stroke-width="5"/>` +
      `<circle cx="66" cy="66" r="4.5" fill="${c.ink}"/>` +
      `<path d="M56 56 L76 76" stroke="${c.red}" stroke-width="5" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 15 && ctx.params.h >= 15 && ctx.history.every((s) => !s.grid.includes(EMPTY)),
  },
  {
    id: 'inked-in',
    name: 'Inked In',
    description: 'Solve a Pattern of 20×20 or larger without ever clearing a black square.',
    tier: 'gold',
    hue: 'yellow',
    // A pen nib laying down a picture it will never need to rub out.
    art: (c) =>
      grid(c, 20, 42, 12, ['# ##', '####', ' ## ']) +
      `<path d="M74 18 L82 26 L60 48 L48 52 L52 40 Z" fill="${c.dark}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
      `<path d="M52 40 L60 48" stroke="${c.yellow}" stroke-width="3"/>`,
    test: (ctx) => {
      if (ctx.params.w < 20 || ctx.params.h < 20) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].grid;
        const b = ctx.history[k].grid;
        for (let i = 0; i < a.length; i++) if (a[i] === FULL && b[i] !== FULL) return false;
      }
      return true;
    },
  },
]);
