/**
 * Light Up puzzle generation.
 *
 * Black squares are scattered with the requested symmetry, a valid arrangement of lights
 * is placed on the white squares, and every black square is numbered with its adjacent
 * lights. The solver of the chosen difficulty must then find exactly that solution and
 * no other; clues it never needed are dropped, then the rest are removed one at a time
 * while the puzzle stays uniquely solvable. For Tricky and Hard the finished puzzle must
 * also defeat the next easier solver, otherwise a new grid is tried. If a batch of grids
 * yields nothing the proportion of black squares is nudged up, as in the original.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { Layout, NO_CLUE, encodeDesc, encodeLights } from './board';
import { puzzleIsGood } from './solver';

export const SYMM_NONE = 0;
export const SYMM_REF2 = 1;
export const SYMM_ROT2 = 2;
export const SYMM_REF4 = 3;
export const SYMM_ROT4 = 4;
export const SYMMETRY_NAMES = [
  'None',
  '2-way mirror',
  '2-way rotational',
  '4-way mirror',
  '4-way rotational',
];

export interface GenParams {
  w: number;
  h: number;
  /** Rough percentage of black squares. */
  blackpc: number;
  symm: number;
  difficulty: number;
}

/** Grids tried per batch before the black percentage is raised. */
const TRIES_PER_BATCH = 20;
/**
 * Above this many squares a batch gets proportionally fewer tries (but at least
 * `MIN_TRIES_PER_BATCH`): every try on a big, sparse grid costs a lot of solving, and
 * sparse Hard grids are seldom unique, so a 30×30 at 5% black used to take close to a
 * minute before the rising percentage made one work. The presets (up to 14×14) are
 * unaffected.
 */
const FULL_BATCH_SQUARES = 196;
const MIN_TRIES_PER_BATCH = 4;
/** Batches before giving up on the requested difficulty and returning the best so far. */
const MAX_BATCHES = 12;

/** Scatter black squares with the given symmetry. */
export function placeBlacks(
  w: number,
  h: number,
  blackpc: number,
  symm: number,
  rng: Random,
): Uint8Array {
  const black = new Uint8Array(w * h);
  const wodd = w & 1;
  const hodd = h & 1;
  const degree = symm === SYMM_NONE ? 1 : symm === SYMM_REF2 || symm === SYMM_ROT2 ? 2 : 4;
  const rotate = symm === SYMM_ROT2 || symm === SYMM_ROT4;
  // The region that is randomised; the rest of the grid is copied from it.
  let rw = w;
  let rh = h;
  if (degree === 4) {
    rw = (w >> 1) + (rotate ? 0 : wodd);
    rh = (h >> 1) + hodd;
  } else if (degree === 2) {
    rh = (h >> 1) + hodd;
  }
  const cells: number[] = [];
  for (let y = 0; y < rh; y++) for (let x = 0; x < rw; x++) cells.push(y * w + x);
  rng.shuffle(cells);
  // Always leave one square of the region white: at 100% an all-black grid would be no
  // puzzle at all, and the generator would reject every board it tried.
  const nblack = Math.min(cells.length - 1, Math.floor((rw * rh * blackpc) / 100));
  for (let k = 0; k < nblack; k++) black[cells[k]] = 1;

  if (degree > 1) {
    for (let y = 0; y < rh; y++) {
      for (let x = 0; x < rw; x++) {
        const v = black[y * w + x];
        if (degree === 4) {
          if (rotate) {
            black[x * w + (w - 1 - y)] = v;
            black[(h - 1 - y) * w + (w - 1 - x)] = v;
            black[(h - 1 - x) * w + y] = v;
          } else {
            black[y * w + (w - 1 - x)] = v;
            black[(h - 1 - y) * w + x] = v;
            black[(h - 1 - y) * w + (w - 1 - x)] = v;
          }
        } else {
          black[(h - 1 - y) * w + (rotate ? w - 1 - x : x)] = v;
        }
      }
    }
    // Four-way rotation leaves the centre square of an odd grid undecided.
    if (degree === 4 && rotate && wodd && rng.upto(100) < blackpc)
      black[(h >> 1) * w + (w >> 1)] = 1;
  }
  return black;
}

/**
 * A random valid arrangement of lights: visit the white squares in random order and
 * put a light on every one that is still dark. Nothing already lit is ever chosen, so
 * no two lights see each other, and the sweep ends with every square lit.
 */
export function placeLights(L: Layout, rng: Random): Uint8Array {
  const order: number[] = [];
  for (let i = 0; i < L.n; i++) if (!L.black[i]) order.push(i);
  rng.shuffle(order);
  const light = new Uint8Array(L.n);
  const lit = new Uint8Array(L.n);
  for (const i of order) {
    if (lit[i]) continue;
    light[i] = 1;
    lit[i] = 1;
    for (const j of L.rays[i]) lit[j] = 1;
  }
  return light;
}

/** Number every black square with its count of adjacent lights. */
export function numberAll(L: Layout, light: Uint8Array): Int8Array {
  const clue = new Int8Array(L.n).fill(NO_CLUE);
  for (let i = 0; i < L.n; i++) {
    if (!L.black[i]) continue;
    let n = 0;
    for (const j of L.adj[i]) if (light[j]) n++;
    clue[i] = n;
  }
  return clue;
}

/**
 * Remove as many clues as possible while the puzzle stays good at `difficulty`. `order`
 * is the sequence in which removals are attempted.
 */
function reduceClues(L: Layout, difficulty: number, order: number[]): void {
  const first = puzzleIsGood(L, difficulty);
  // First drop every clue the solver never used, if that keeps the puzzle good.
  const saved = L.clue.slice();
  for (let i = 0; i < L.n; i++)
    if (L.clue[i] !== NO_CLUE && !first.work.used[i]) L.clue[i] = NO_CLUE;
  if (!puzzleIsGood(L, difficulty).good) L.clue = saved;
  // Then try the rest one by one.
  for (const i of order) {
    if (L.clue[i] === NO_CLUE) continue;
    const v = L.clue[i];
    L.clue[i] = NO_CLUE;
    if (!puzzleIsGood(L, difficulty).good) L.clue[i] = v;
  }
}

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(params: GenParams, rng: Random): { desc: string; aux: string } {
  const { w, h, symm, difficulty } = params;
  const n = w * h;
  const order: number[] = [];
  for (let i = 0; i < n; i++) order.push(i);
  rng.shuffle(order);
  let blackpc = params.blackpc;
  let fallback: { desc: string; aux: string } | null = null;

  for (let batch = 0; batch < MAX_BATCHES; batch++) {
    const tries = Math.max(
      MIN_TRIES_PER_BATCH,
      Math.min(TRIES_PER_BATCH, Math.round((TRIES_PER_BATCH * FULL_BATCH_SQUARES) / n)),
    );
    for (let t = 0; t < tries; t++) {
      const black = placeBlacks(w, h, blackpc, symm, rng);
      // A grid with no white square is trivially "unique" but leaves nothing to play and
      // nothing that could ever finish it: 100% black, or a tiny symmetric grid.
      if (black.every((b) => b)) continue;
      const L = new Layout(w, h, black, new Int8Array(n).fill(NO_CLUE));
      const light = placeLights(L, rng);
      L.clue = numberAll(L, light);
      if (!puzzleIsGood(L, difficulty).good) continue;
      reduceClues(L, difficulty, order);
      const result = { desc: encodeDesc(L), aux: encodeLights(light) };
      // Tricky and Hard puzzles must actually need their level of reasoning.
      if (difficulty > 0 && puzzleIsGood(L, difficulty - 1).good) {
        fallback ??= result;
        continue;
      }
      return result;
    }
    if (blackpc < 90) blackpc += 5;
  }
  if (fallback) return fallback;
  // Some symmetries leave a tiny grid no unique puzzle at all: a 2×2 with four-way
  // symmetry is either all black or all white. Drop the symmetry rather than fail.
  if (symm !== SYMM_NONE) return generate({ ...params, symm: SYMM_NONE }, rng);
  throw new Error(tx`Unable to generate a puzzle with these parameters`);
}
