import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { SameGameParams, SameGameState } from './index';

type C = typeof PALETTE;

/** Squares on a board: one letter per square (r red, b blue, g green, y yellow), '.' empty. */
function squares(c: C, x: number, y: number, s: number, rows: string[]): string {
  const colour: Record<string, string> = { r: c.red, b: c.blue, g: c.green, y: c.yellow };
  let out = '';
  rows.forEach((row, j) => {
    for (let i = 0; i < row.length; i++) {
      const fill = colour[row[i]];
      if (fill)
        out += `<rect x="${x + i * s + 1.5}" y="${y + j * s + 1.5}" width="${s - 3}" height="${s - 3}" rx="${s * 0.12}" fill="${fill}" stroke="${c.ink}" stroke-width="2.8"/>`;
    }
  });
  return out;
}

/** The heavy outline the board draws round a selected group: every edge it shares with a
 * square outside the group. */
function outline(c: C, x: number, y: number, s: number, rows: string[], group: string): string {
  const inside = (i: number, j: number) => rows[j]?.[i] === group;
  let d = '';
  rows.forEach((row, j) => {
    for (let i = 0; i < row.length; i++) {
      if (!inside(i, j)) continue;
      const px = x + i * s;
      const py = y + j * s;
      if (!inside(i, j - 1)) d += `M${px} ${py} H${px + s} `;
      if (!inside(i, j + 1)) d += `M${px} ${py + s} H${px + s} `;
      if (!inside(i - 1, j)) d += `M${px} ${py} V${py + s} `;
      if (!inside(i + 1, j)) d += `M${px + s} ${py} V${py + s} `;
    }
  });
  return `<path d="${d}" stroke="${c.ink}" stroke-width="4" stroke-linecap="round"/>`;
}

/**
 * Group size of every removal on the kept line since the last Restart: each board lists
 * what the move took. A Restart deals a fresh board, the only kind that took nothing, and
 * the attempt it threw away does not count (a 25-group removed before it earned nothing).
 */
function removals(ctx: { history: readonly SameGameState[] }): number[] {
  const sizes = ctx.history.slice(1).map((s) => s.removed.length);
  return sizes.slice(sizes.lastIndexOf(0) + 1);
}

export const achievements = defineAchievements<SameGameParams, SameGameState>([
  {
    id: 'avalanche',
    name: 'Avalanche',
    description: 'Remove a group of 25 squares or more in one go, then clear the board.',
    tier: 'silver',
    hue: 'blue',
    // One huge blue group picked out with the heavy outline, about to go.
    art: (c) => {
      const rows = ['bbbbr', 'gbbbb', 'bbybb', 'bbbbg'];
      return (
        squares(
          c,
          22,
          32,
          11,
          rows.map((r) => r.replace(/b/g, '.')),
        ) +
        rows
          .map((r, j) =>
            [...r]
              .map((v, i) =>
                v === 'b'
                  ? `<rect x="${22 + i * 11}" y="${32 + j * 11}" width="11" height="11" fill="${c.blue}"/>`
                  : '',
              )
              .join(''),
          )
          .join('') +
        outline(c, 22, 32, 11, rows, 'b') +
        `<path d="M30 25 L26 19 M49.5 24 V17 M69 25 L73 19" stroke="${c.ink}" stroke-width="4" stroke-linecap="round"/>`
      );
    },
    test: (ctx) => removals(ctx).some((n) => n >= 25),
  },
  {
    id: 'no-pairs',
    name: 'No Pairs Allowed',
    description: 'Clear a board of 15×10 or larger without ever removing a pair.',
    tier: 'gold',
    hue: 'yellow',
    // A pair of squares crossed out, above a group of three.
    art: (c) =>
      squares(c, 30, 20, 20, ['rr']) +
      `<path d="M24 16 L76 46 M76 16 L24 46" stroke="${c.ink}" stroke-width="5.5" stroke-linecap="round"/>` +
      squares(c, 20, 56, 20, ['ggg']),
    test: (ctx) => ctx.params.w * ctx.params.h >= 150 && removals(ctx).every((n) => n >= 3),
  },
  {
    id: 'last-one',
    name: 'The Last Square',
    description: 'Get stuck with just one square left on the board.',
    tier: 'bronze',
    hidden: true,
    hue: 'orange',
    on: 'lose',
    // An empty board with one lonely square in the corner.
    art: (c) =>
      `<rect x="22" y="22" width="56" height="56" fill="${c.paper}" stroke="${c.ink}" stroke-width="4"/>` +
      squares(c, 24, 58, 18, ['y']) +
      `<path d="M44 59.5 h15 v15 h-15 Z M25.5 40 h15 v15 h-15 Z M44 40 h15 v15 h-15 Z" fill="none" stroke="${c.lowlight}" stroke-width="2.5" stroke-dasharray="3.5 3"/>`,
    test: (ctx) => ctx.state.tiles.filter((t) => t !== 0).length === 1,
  },
]);
