import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_UP,
  LEFT_BUTTON,
  stripMods,
} from '../../framework/input';
import { easeInOut, parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export interface FifteenParams {
  w: number;
  h: number;
}

export interface FifteenState {
  w: number;
  h: number;
  /** Tile at each cell (row-major); 0 is the gap. */
  tiles: number[];
  gap: number;
  moves: number;
  completed: number; // move count at which it was completed, or 0
  usedSolve: boolean;
}

export type FifteenUI = Record<string, never>;

const ANIM = 0.13;
const FLASH = 0.3;

function isSolved(tiles: number[]): boolean {
  for (let i = 0; i < tiles.length - 1; i++) if (tiles[i] !== i + 1) return false;
  return tiles[tiles.length - 1] === 0;
}

/** Parity of a permutation of 0..n-1 (0 = even). */
function permutationParity(perm: number[]): number {
  const seen = new Uint8Array(perm.length);
  let parity = 0;
  for (let i = 0; i < perm.length; i++) {
    if (seen[i]) continue;
    let len = 0;
    let j = i;
    while (!seen[j]) {
      seen[j] = 1;
      j = perm[j];
      len++;
    }
    parity ^= (len - 1) & 1;
  }
  return parity;
}

/**
 * A grid position is solvable iff the permutation parity of the tiles (treating the gap
 * as tile 0 in the final position) matches the parity of the gap's taxicab distance
 * from the bottom-right corner.
 */
export function solvable(tiles: number[], w: number, h: number): boolean {
  const n = w * h;
  // Map each cell to where its tile belongs: tile t belongs at index t-1; gap at n-1.
  const perm = tiles.map((t) => (t === 0 ? n - 1 : t - 1));
  const gap = tiles.indexOf(0);
  const gx = gap % w;
  const gy = Math.floor(gap / w);
  const dist = w - 1 - gx + (h - 1 - gy);
  return permutationParity(perm) === (dist & 1);
}

function makeState(w: number, h: number, tiles: number[]): FifteenState {
  return { w, h, tiles, gap: tiles.indexOf(0), moves: 0, completed: 0, usedSolve: false };
}

function tileRect(ds: DrawState, x: number, y: number) {
  const t = ds.tileSize;
  const border = Math.round(t * 0.3);
  return { x: border + x * t, y: border + y * t, t, border };
}

const game = defineGame<FifteenParams, FifteenState, FifteenUI>({
  id: 'fifteen',
  name: 'Fifteen',
  description: 'Slide the tiles around to arrange them into order.',
  alsoKnownAs: '15 puzzle, sliding puzzle',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: [
    { name: '3×3', params: { w: 3, h: 3 } },
    { name: '4×4', params: { w: 4, h: 4 } },
    { name: '5×5', params: { w: 5, h: 5 } },
  ],
  defaultParams: () => ({ w: 4, h: 4 }),
  encodeParams: (p) => `${p.w}x${p.h}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    return { w: r.w, h: r.h };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > 12 || p.h > 12) return tx`Width and height must be at most twelve`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const w = int(0);
    const h = int(1);
    return { w, h };
  },

  newDesc(p, rng: Random) {
    const n = p.w * p.h;
    const tiles: number[] = [];
    for (let i = 1; i < n; i++) tiles.push(i);
    tiles.push(0);
    do {
      rng.shuffle(tiles);
    } while (isSolved(tiles) || !solvable(tiles, p.w, p.h));
    return { desc: tiles.join(',') };
  },

  validateDesc(p, desc) {
    const n = p.w * p.h;
    const parts = desc.split(',');
    if (parts.length !== n) return tx`Description must contain ${n} numbers`;
    const seen = new Uint8Array(n);
    for (const part of parts) {
      if (!/^\d+$/.test(part)) return tx`Description must contain only numbers`;
      const v = parseInt(part, 10);
      if (v >= n) return tx`Description contains a number that is too large`;
      if (seen[v]) return tx`Description contains a duplicate number`;
      seen[v] = 1;
    }
    if (!solvable(parts.map(Number), p.w, p.h)) return tx`This arrangement cannot be solved`;
    return null;
  },

  newGame(p, desc) {
    return makeState(p.w, p.h, desc.split(',').map(Number));
  },

  canSolve: true,
  solve(_orig, curr) {
    if (isSolved(curr.tiles)) throw new Error(tx`Already solved`);
    return 'S';
  },

  textFormat(s) {
    const width = String(s.w * s.h - 1).length;
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const row: string[] = [];
      for (let x = 0; x < s.w; x++) {
        const t = s.tiles[y * s.w + x];
        row.push((t === 0 ? '' : String(t)).padStart(width, ' '));
      }
      rows.push(row.join(' '));
    }
    return rows.join('\n');
  },

  newUI: () => ({}),

  interpretMove(state, _ui, ds, mx, my, button) {
    const b = stripMods(button);
    const gx = state.gap % state.w;
    const gy = Math.floor(state.gap / state.w);
    let nx: number;
    let ny: number;
    if (b === LEFT_BUTTON) {
      const { border, t } = tileRect(ds, 0, 0);
      nx = Math.floor((mx - border) / t);
      ny = Math.floor((my - border) / t);
      if (nx < 0 || ny < 0 || nx >= state.w || ny >= state.h) return null;
      if (nx !== gx && ny !== gy) return null;
      if (nx === gx && ny === gy) return null;
    } else if (b === CURSOR_UP && gy + 1 < state.h) {
      nx = gx;
      ny = gy + 1;
    } else if (b === CURSOR_DOWN && gy > 0) {
      nx = gx;
      ny = gy - 1;
    } else if (b === CURSOR_LEFT && gx + 1 < state.w) {
      nx = gx + 1;
      ny = gy;
    } else if (b === CURSOR_RIGHT && gx > 0) {
      nx = gx - 1;
      ny = gy;
    } else {
      return null;
    }
    return `M${nx},${ny}`;
  },

  executeMove(state, move) {
    if (move === 'S') {
      const n = state.w * state.h;
      const tiles: number[] = [];
      for (let i = 1; i < n; i++) tiles.push(i);
      tiles.push(0);
      return { ...state, tiles, gap: n - 1, usedSolve: true, completed: state.moves };
    }
    const m = /^M(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const nx = parseInt(m[1], 10);
    const ny = parseInt(m[2], 10);
    const gx = state.gap % state.w;
    const gy = Math.floor(state.gap / state.w);
    if (nx >= state.w || ny >= state.h) return null;
    if ((nx !== gx && ny !== gy) || (nx === gx && ny === gy)) return null;
    const tiles = state.tiles.slice();
    const dx = Math.sign(nx - gx);
    const dy = Math.sign(ny - gy);
    // Shift every tile between the gap and the clicked tile one step toward the gap.
    let cx = gx;
    let cy = gy;
    while (cx !== nx || cy !== ny) {
      const from = (cy + dy) * state.w + (cx + dx);
      tiles[cy * state.w + cx] = tiles[from];
      cx += dx;
      cy += dy;
    }
    const gap = ny * state.w + nx;
    tiles[gap] = 0;
    const moves = state.moves + 1;
    const done = isSolved(tiles);
    return {
      ...state,
      tiles,
      gap,
      moves,
      completed: state.completed || (done ? moves : 0),
    };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const border = Math.round(t * 0.3);
    return { w: p.w * t + 2 * border, h: p.h * t + 2 * border };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, _ui, animTime, flashTime) {
    const { w, h } = state;
    const t = ds.tileSize;
    const border = Math.round(t * 0.3);
    const boardX = border;
    const boardY = border;
    const flashing = flashTime > 0 && Math.floor(flashTime / (FLASH / 3)) % 2 === 0;

    // Board frame
    dr.rect(boardX - 4, boardY - 4, w * t + 8, h * t + 8, flashing ? 'shade' : null, 'ink', {
      width: 2.4,
    });

    // Which tiles are moving, and how far along?
    const anim = oldState ? easeInOut(animTime / ANIM) : 1;
    // Build the picture from the *new* state; moving tiles are drawn offset from their
    // old position toward their new position.
    const moving = new Map<number, { fx: number; fy: number }>();
    if (oldState) {
      for (let i = 0; i < w * h; i++) {
        const tile = state.tiles[i];
        if (tile === 0) continue;
        const from = oldState.tiles.indexOf(tile);
        if (from !== i) moving.set(tile, { fx: from % w, fy: Math.floor(from / w) });
      }
    }
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const tile = state.tiles[y * w + x];
        if (tile === 0) continue;
        let px = boardX + x * t;
        let py = boardY + y * t;
        const mv = moving.get(tile);
        if (mv) {
          px = boardX + (mv.fx + (x - mv.fx) * anim) * t;
          py = boardY + (mv.fy + (y - mv.fy) * anim) * t;
        }
        const inPlace = tile === y * w + x + 1;
        const pad = Math.max(2, t * 0.06);
        dr.roundRect(
          px + pad,
          py + pad,
          t - 2 * pad,
          t - 2 * pad,
          t * 0.14,
          inPlace ? 'shade' : 'paper',
          'ink',
          {
            width: 1.8,
            seed: tile,
          },
        );
        dr.text(px + t / 2, py + t / 2, String(tile), {
          size: t * 0.5,
          colour: flashing ? 'ok' : 'ink',
          maxWidth: t * 0.8,
        });
      }
    }

    let status = state.usedSolve
      ? tr('status.solvedByComputer')
      : state.completed
        ? tr('status.movesCompleted', { n: state.completed })
        : tr('status.moves', { n: state.moves });
    if (dir < 0 && !state.completed && !state.usedSolve)
      status = tr('status.moves', { n: state.moves });
    dr.statusBar(status);
  },

  animLength: () => ANIM,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !newState.usedSolve ? FLASH : 0;
  },
  status: (s) => (isSolved(s.tiles) ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  flags: { oneButton: true },
});

export default game;
