import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { GHOST, VAMPIRE } from './board';
import { cluePos, geometry } from './index';
import type { UndeadState, UndeadUI } from './index';

/** One grid square, or a run of them, as a canvas rectangle. */
function cells(t: number, x: number, y: number, w = 1, h = 1): TutorialRect {
  const g = geometry(t);
  return { x: g.gridX + x * t, y: g.gridY + y * t, w: w * t, h: h * t };
}

function centre(t: number, x: number, y: number) {
  const g = geometry(t);
  return { x: g.gridX + (x + 0.5) * t, y: g.gridY + (y + 0.5) * t };
}

/** Edge positions of the clues around the grid: above a column, beside a row, and so on. */
const top = (x: number) => x;
const right = (s: UndeadState, y: number) => s.w + y;
const bottom = (s: UndeadState, x: number) => s.w + s.h + (s.w - 1 - x);
const left = (s: UndeadState, y: number) => 2 * s.w + s.h + (s.h - 1 - y);

/** The number written at edge position `r`, as a canvas rectangle. */
function clue(state: UndeadState, t: number, r: number): TutorialRect {
  const g = geometry(t);
  const p = cluePos(g, state.w, state.h, r);
  const s = g.ring * 0.9;
  return { x: p.x - s / 2, y: p.y - s / 2, w: s, h: s };
}

/** Monster slot of square (x, y). */
const slot = (s: UndeadState, x: number, y: number) => s.layout.slot[y * s.w + x];
const typeAt = (s: UndeadState, x: number, y: number) => s.types[slot(s, x, y)];

/**
 * A 3×3 maze with five squares to fill. The walkthrough reads the ghost out of the pair
 * of clues on the line through the top-left square, pins the single vampire down with the
 * 4 in the bottom-left corner, and reads two more ghosts off the middle row.
 */
export const tutorial: Tutorial<UndeadState, UndeadUI> = {
  steps: [
    {
      gameId: '3x3:3,1,1,aRLcRaR,1,1,0,0,1,0,0,3,4,1,1,0',
      text: 'Fill the five empty squares with ghosts, vampires and zombies — the tally at the top says how many of each. Every number counts the monsters seen looking along that line, and the mirrors bend your gaze.',
      highlight: ({ state, tileSize }) => {
        const g = geometry(tileSize);
        return {
          x: g.b,
          y: g.b,
          w: 2 * g.ring + state.w * tileSize,
          h: g.legend + 2 * g.ring + state.h * tileSize,
        };
      },
    },
    {
      text: 'Looking in from the **left of the top row** you see nothing; the mirror bends that same line out at the top, where the **1** sees one monster. Only a ghost hides head-on and shows in a mirror. **Click** that square.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, 0, 0),
        clue(state, tileSize, left(state, 0)),
        clue(state, tileSize, top(1)),
      ],
      pointer: ({ tileSize }) => centre(tileSize, 0, 0),
      waitFor: ({ state }) => typeAt(state, 0, 0) === GHOST,
    },
    {
      text: 'The **4** in the bottom-left corner zig-zags through the mirrors past three squares and sees every one of them. Vampires vanish in a mirror, so the only vampire must be the middle square of the left column. **Click** it.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, 0, 1),
        clue(state, tileSize, bottom(state, 0)),
      ],
      pointer: ({ tileSize }) => centre(tileSize, 0, 1),
      waitFor: ({ state }) => typeAt(state, 0, 1) !== 0,
    },
    {
      text: 'A click only steps through the monsters. **Press V** instead: G, V and Z drop a ghost, vampire or zombie straight into the highlighted square.',
      textTouch:
        'A tap only steps through the monsters one at a time. Tap **Vampire** on the keypad instead: it drops that monster straight into the highlighted square.',
      highlight: ({ tileSize }) => cells(tileSize, 0, 1),
      target: '[data-key="V"]',
      waitFor: ({ state }) => typeAt(state, 0, 1) === VAMPIRE,
    },
    {
      text: 'The **middle row** is a straight, mirror-free view and both **1**s see a single monster — the vampire. So its two neighbours must be ghosts. **Click** the centre square.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, 0, 1, state.w, 1),
        clue(state, tileSize, left(state, 1)),
        clue(state, tileSize, right(state, 1)),
      ],
      pointer: ({ tileSize }) => centre(tileSize, 1, 1),
      waitFor: ({ state }) => typeAt(state, 1, 1) === GHOST,
    },
    {
      text: 'A **right-click** pencils a small note in instead of placing anything. Try it on the right-hand square of that row; each right-click adds the next monster.',
      highlight: ({ state, tileSize }) => cells(tileSize, state.w - 1, 1),
      pointer: ({ state, tileSize }) => {
        const c = centre(tileSize, state.w - 1, 1);
        // Nudged left of centre so the "right-click" tag stays clear of the callout.
        return { x: c.x - tileSize * 0.4, y: c.y, button: 'right' as const };
      },
      waitFor: ({ state }) => state.pencil[slot(state, state.w - 1, 1)] !== 0,
    },
    {
      text: 'Two squares to go: the one you pencilled is the third ghost, and the last is the zombie. Numbers grey out once their line is settled; **Solve** finishes the maze if you would rather watch.',
      target: '[data-cmd="solve"]',
    },
  ],
};
