/**
 * Tracks board model: the fixed layout (given pieces, counts, entrance and exit) and the
 * mutable flags the player and the solver work with.
 *
 * Every square carries two sets of direction bits: `track` (a rail leaves the square
 * through that side) and `notrack` (a rail definitely does not). Both are mirrored on
 * the neighbouring square so an edge can be read from either side. Two square-level
 * marks say "there is track here somewhere" (`sTrack`) and "no track here" (`sNotrack`).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export const R = 1;
export const U = 2;
export const L = 4;
export const D = 8;
export const ALL = 15;
export const DIRS: readonly number[] = [R, U, L, D];
/** Number of set bits in a 4-bit direction mask. */
export const NBITS = [0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4];

export function dx(d: number): number {
  return d === R ? 1 : d === L ? -1 : 0;
}
export function dy(d: number): number {
  return d === D ? 1 : d === U ? -1 : 0;
}
export function opposite(d: number): number {
  return d === R ? L : d === L ? R : d === U ? D : U;
}
export const DIR_CHAR: Record<number, string> = { [R]: 'R', [U]: 'U', [L]: 'L', [D]: 'D' };
export function dirOf(c: string): number {
  return c === 'R' ? R : c === 'U' ? U : c === 'L' ? L : c === 'D' ? D : 0;
}

export interface Layout {
  w: number;
  h: number;
  n: number;
  /** Direction bits of each given piece; 0 where the square is not a clue. */
  clue: Uint8Array;
  /** Required number of track squares: columns 0..w-1, then rows 0..h-1. */
  numbers: number[];
  /** Row of the entrance on the left edge. */
  rowS: number;
  /** Column of the exit on the bottom edge. */
  colS: number;
}

export class Board {
  readonly w: number;
  readonly h: number;
  readonly n: number;
  track: Uint8Array;
  notrack: Uint8Array;
  sTrack: Uint8Array;
  sNotrack: Uint8Array;

  constructor(
    readonly layout: Layout,
    from?: Board,
  ) {
    this.w = layout.w;
    this.h = layout.h;
    this.n = layout.n;
    if (from) {
      this.track = from.track.slice();
      this.notrack = from.notrack.slice();
      this.sTrack = from.sTrack.slice();
      this.sNotrack = from.sNotrack.slice();
    } else {
      this.track = new Uint8Array(this.n);
      this.notrack = new Uint8Array(this.n);
      this.sTrack = new Uint8Array(this.n);
      this.sNotrack = new Uint8Array(this.n);
    }
  }

  clone(): Board {
    return new Board(this.layout, this);
  }

  inGrid(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.w && y < this.h;
  }

  /** Index of the square beyond side `d` of square `i`, or -1 off the grid. */
  neighbour(i: number, d: number): number {
    const x = (i % this.w) + dx(d);
    const y = Math.floor(i / this.w) + dy(d);
    return this.inGrid(x, y) ? y * this.w + x : -1;
  }

  setTrack(i: number, d: number): void {
    this.track[i] |= d;
    const j = this.neighbour(i, d);
    if (j >= 0) this.track[j] |= opposite(d);
  }
  clearTrack(i: number, d: number): void {
    this.track[i] &= ~d;
    const j = this.neighbour(i, d);
    if (j >= 0) this.track[j] &= ~opposite(d);
  }
  setNoTrack(i: number, d: number): void {
    this.notrack[i] |= d;
    const j = this.neighbour(i, d);
    if (j >= 0) this.notrack[j] |= opposite(d);
  }
  clearNoTrack(i: number, d: number): void {
    this.notrack[i] &= ~d;
    const j = this.neighbour(i, d);
    if (j >= 0) this.notrack[j] &= ~opposite(d);
  }

  /** Track passes through this square: marked as such, or a rail already leaves it. */
  hasTrack(i: number): boolean {
    return this.sTrack[i] !== 0 || this.track[i] !== 0;
  }
}

/** A board holding just the given pieces: every clue's two rails and nothing else. */
export function boardFromLayout(layout: Layout): Board {
  const b = new Board(layout);
  for (let i = 0; i < layout.n; i++) {
    const f = layout.clue[i];
    if (!f) continue;
    b.sTrack[i] = 1;
    for (const d of DIRS) if (f & d) b.setTrack(i, d);
  }
  return b;
}

// ------------------------------------------------------------------ descriptions

/**
 * Parse a description: the grid as run-length letters (`a` = 1 empty square … `z` = 26)
 * interleaved with hex digits giving the direction bits of each given piece, then one
 * comma-separated count per column and per row, the exit column and entrance row
 * prefixed with `S`. Returns an error message or the layout.
 */
export function parseDesc(desc: string, w: number, h: number): Layout | string {
  const n = w * h;
  const clue = new Uint8Array(n);
  let i = 0;
  let p = 0;
  while (i < n) {
    if (p >= desc.length) return tx`Description is too short`;
    const c = desc[p++];
    if (c >= 'a' && c <= 'z') {
      i += c.charCodeAt(0) - 96;
    } else if (/[0-9A-F]/.test(c)) {
      const f = parseInt(c, 16);
      if (NBITS[f] !== 2) return tx`Clue did not provide 2 direction flags`;
      clue[i++] = f;
    } else {
      return tx`Game description contained unexpected characters`;
    }
  }
  if (i !== n || (p < desc.length && /[a-zA-F0-9]/.test(desc[p])))
    return tx`Description is too long`;
  const numbers: number[] = [];
  let rowS = -1;
  let colS = -1;
  for (let k = 0; k < w + h; k++) {
    if (desc[p] !== ',') return tx`Not enough numbers given after grid specification`;
    p++;
    if (desc[p] === 'S') {
      if (k < w) {
        if (colS >= 0) return tx`Puzzle must have one entrance and one exit`;
        colS = k;
      } else {
        if (rowS >= 0) return tx`Puzzle must have one entrance and one exit`;
        rowS = k - w;
      }
      p++;
    }
    const m = /^\d+/.exec(desc.slice(p));
    if (!m) return tx`Invalid character in number list`;
    const v = parseInt(m[0], 10);
    if (v > (k < w ? h : w)) return tx`Count is larger than the line it describes`;
    numbers.push(v);
    p += m[0].length;
  }
  if (p !== desc.length) return tx`Unexpected additional character at end of game description`;
  if (rowS < 0 || colS < 0) return tx`Puzzle must have one entrance and one exit`;
  // The entrance and exit must be given pieces leaving the grid; nothing else may.
  const ent = rowS * w;
  const ext = (h - 1) * w + colS;
  if (!(clue[ent] & L)) return tx`Entrance square must contain a piece leaving the left edge`;
  if (!(clue[ext] & D)) return tx`Exit square must contain a piece leaving the bottom edge`;
  for (let k = 0; k < n; k++) {
    const f = clue[k];
    if (!f) continue;
    const x = k % w;
    const y = Math.floor(k / w);
    if (f & U && y === 0) return tx`A given piece leaves the grid`;
    if (f & R && x === w - 1) return tx`A given piece leaves the grid`;
    if (f & L && x === 0 && k !== ent) return tx`A given piece leaves the grid`;
    if (f & D && y === h - 1 && k !== ext) return tx`A given piece leaves the grid`;
  }
  return { w, h, n, clue, numbers, rowS, colS };
}

export function encodeDesc(layout: Layout): string {
  const { w, h, n, clue, numbers, rowS, colS } = layout;
  let s = '';
  let run = 0;
  const flush = () => {
    while (run > 0) {
      const k = Math.min(run, 26);
      s += String.fromCharCode(96 + k);
      run -= k;
    }
  };
  for (let i = 0; i < n; i++) {
    if (clue[i]) {
      flush();
      s += clue[i].toString(16).toUpperCase();
    } else run++;
  }
  flush();
  for (let x = 0; x < w; x++) s += `,${x === colS ? 'S' : ''}${numbers[x]}`;
  for (let y = 0; y < h; y++) s += `,${y === rowS ? 'S' : ''}${numbers[w + y]}`;
  return s;
}

// ------------------------------------------------------------------ analysis

export interface Analysis {
  /** A single track runs from the entrance to the exit meeting every count. */
  completed: boolean;
  /** Squares drawn in the error colour: junctions, loops and track off the main line. */
  cellError: Uint8Array;
  /** Lines (columns then rows) whose count can no longer be met. */
  lineError: Uint8Array;
  /** Lines with exactly the right number of track squares. */
  lineDone: Uint8Array;
}

/** Number of track squares in column `x` / row `y`. */
export function countLine(b: Board, line: number): { track: number; notrack: number } {
  const { w, h } = b;
  let track = 0;
  let notrack = 0;
  if (line < w) {
    for (let y = 0; y < h; y++) {
      const i = y * w + line;
      if (b.hasTrack(i)) track++;
      if (b.sNotrack[i]) notrack++;
    }
  } else {
    const y = line - w;
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (b.hasTrack(i)) track++;
      if (b.sNotrack[i]) notrack++;
    }
  }
  return { track, notrack };
}

/** Connect squares joined by rails; returns the forest plus the root of any loop. */
export function connect(b: Board): { dsf: DSF; loops: Set<number> } {
  const { w, h, n } = b;
  const dsf = new DSF(n);
  const loops = new Set<number>();
  for (let i = 0; i < n; i++) {
    const x = i % w;
    const y = Math.floor(i / w);
    if (x < w - 1 && b.track[i] & R) {
      if (dsf.same(i, i + 1)) loops.add(dsf.find(i));
      else dsf.merge(i, i + 1);
    }
    if (y < h - 1 && b.track[i] & D) {
      if (dsf.same(i, i + w)) loops.add(dsf.find(i));
      else dsf.merge(i, i + w);
    }
  }
  // Roots may have moved while merging; canonicalise the loop classes.
  const canon = new Set<number>();
  for (const r of loops) canon.add(dsf.find(r));
  return { dsf, loops: canon };
}

export function analyse(b: Board): Analysis {
  const { w, h, n, layout } = b;
  const cellError = new Uint8Array(n);
  const lineError = new Uint8Array(w + h);
  const lineDone = new Uint8Array(w + h);
  let completed = true;

  for (let i = 0; i < n; i++) {
    const bits = NBITS[b.track[i]];
    if (bits > 2) cellError[i] = 1;
    if (b.hasTrack(i) && bits !== 2) completed = false;
  }
  for (let line = 0; line < w + h; line++) {
    const target = layout.numbers[line];
    const len = line < w ? h : w;
    const { track, notrack } = countLine(b, line);
    if (track > target || notrack > len - target) lineError[line] = 1;
    if (track === target) lineDone[line] = 1;
    else completed = false;
  }

  const { dsf, loops } = connect(b);
  if (loops.size) {
    completed = false;
    for (let i = 0; i < n; i++) if (loops.has(dsf.find(i))) cellError[i] = 1;
  }
  const ent = layout.rowS * w;
  const ext = (h - 1) * w + layout.colS;
  if (dsf.same(ent, ext)) {
    // The main line is in place: anything not on it is wrong.
    const main = dsf.find(ent);
    for (let i = 0; i < n; i++) {
      if (b.hasTrack(i) && dsf.find(i) !== main) {
        cellError[i] = 1;
        completed = false;
      }
    }
  } else completed = false;
  if (!(b.track[ent] & L) || !(b.track[ext] & D)) completed = false;

  return { completed, cellError, lineError, lineDone };
}
