/**
 * Latin-square solving machinery, shared by the Unequal solver (and reusable by any
 * other latin-square puzzle).
 *
 * The solver keeps a cube of candidates — for every cell, which digits are still
 * possible — and knows four kinds of pure latin-square reasoning:
 *
 *  - **simple**: a digit with one place left in a row or column goes there; a cell
 *    with one candidate left takes it.
 *  - **set** elimination: within a row (or column), if some set of k digits can only
 *    go in k cells, nothing else can go in those cells. Applied to the row-vs-column
 *    positions of a single digit this becomes the much harder "positional" form.
 *  - **forcing chains**: a chain of two-candidate cells whose ends, whichever way the
 *    chain is resolved, put digit N in one of two cells that both see a third cell,
 *    which therefore cannot be N.
 *  - **recursion**: guess in the most constrained cell and solve each branch fully.
 *
 * A puzzle plugs in its own extra deductions as "user solvers", one per difficulty
 * level, and says at which levels the latin techniques kick in. `latinSolve` runs the
 * techniques from easiest to hardest, restarting from the easiest after every step, and
 * reports the hardest level it needed or one of the special outcomes below.
 */

export const DIFF_IMPOSSIBLE = 100;
export const DIFF_AMBIGUOUS = 101;
export const DIFF_UNFINISHED = 102;

/** At which difficulty level each latin technique is allowed. */
export interface LatinLevels {
  simple: number;
  set: number;
  positionalSet: number;
  forcing: number;
  recursive: number;
}

/**
 * A puzzle-specific deduction. Returns the number of candidates eliminated (or 1 for
 * any progress), 0 for none, and a negative number when it found a contradiction.
 */
export type UserSolver = (solver: LatinSolver) => number;

/**
 * A cap on guessing. `nodes` counts down once for every branch recursion tries, and a
 * solve that runs out gives up with DIFF_UNFINISHED — never a wrong answer — so a caller
 * that only acts on a proven result stays correct, just more cautious.
 */
export interface SolveBudget {
  nodes: number;
}

export class LatinSolver {
  readonly o: number;
  /** cube[(x·o + y)·o + n − 1] is non-zero while digit n is possible at (x, y). */
  cube: Uint8Array;
  /** grid[y·o + x] is the placed digit, 0 while unknown. */
  grid: Uint8Array;
  /** row[y·o + n − 1] set once digit n is placed somewhere in row y (col likewise). */
  private row: Uint8Array;
  private col: Uint8Array;
  // Scratch space for set elimination and forcing chains.
  private sGrid: Uint8Array;
  private sRowIdx: Uint8Array;
  private sColIdx: Uint8Array;
  private sSet: Uint8Array;
  private sNumber: Uint8Array;
  private sQueue: Int32Array;

  constructor(grid: Uint8Array, o: number) {
    this.o = o;
    this.grid = grid;
    this.cube = new Uint8Array(o * o * o).fill(1);
    this.row = new Uint8Array(o * o);
    this.col = new Uint8Array(o * o);
    this.sGrid = new Uint8Array(o * o);
    this.sRowIdx = new Uint8Array(o);
    this.sColIdx = new Uint8Array(o);
    this.sSet = new Uint8Array(o);
    this.sNumber = new Uint8Array(o * o);
    this.sQueue = new Int32Array(o * o);
    for (let y = 0; y < o; y++)
      for (let x = 0; x < o; x++) if (grid[y * o + x]) this.place(x, y, grid[y * o + x]);
  }

  /** A copy sharing nothing with this solver, for trying a guess. */
  clone(): LatinSolver {
    const c = Object.create(LatinSolver.prototype) as LatinSolver;
    Object.assign(c, this);
    c.cube = this.cube.slice();
    c.grid = this.grid.slice();
    (c as any).row = this.row.slice();
    (c as any).col = this.col.slice();
    (c as any).sGrid = new Uint8Array(this.o * this.o);
    (c as any).sRowIdx = new Uint8Array(this.o);
    (c as any).sColIdx = new Uint8Array(this.o);
    (c as any).sSet = new Uint8Array(this.o);
    (c as any).sNumber = new Uint8Array(this.o * this.o);
    (c as any).sQueue = new Int32Array(this.o * this.o);
    return c;
  }

  pos(x: number, y: number, n: number): number {
    return (x * this.o + y) * this.o + n - 1;
  }

  has(x: number, y: number, n: number): boolean {
    return this.cube[(x * this.o + y) * this.o + n - 1] !== 0;
  }

  /** Remove a candidate. Returns 1 if it was present. */
  rule(x: number, y: number, n: number): number {
    const i = (x * this.o + y) * this.o + n - 1;
    if (!this.cube[i]) return 0;
    this.cube[i] = 0;
    return 1;
  }

  /** Number of candidates left for a cell. */
  count(x: number, y: number): number {
    const o = this.o;
    const base = (x * o + y) * o;
    let c = 0;
    for (let n = 0; n < o; n++) if (this.cube[base + n]) c++;
    return c;
  }

  /** Smallest and largest remaining candidate for a cell, as 0-based digits. */
  minMax(x: number, y: number): [number, number] {
    const o = this.o;
    const v = this.grid[y * o + x];
    if (v) return [v - 1, v - 1];
    const base = (x * o + y) * o;
    let min = o;
    let max = -1;
    for (let n = 0; n < o; n++) {
      if (this.cube[base + n]) {
        if (n < min) min = n;
        if (n > max) max = n;
      }
    }
    return [min, max];
  }

  /** Commit digit n to (x, y): clears the other candidates there and n elsewhere in line. */
  place(x: number, y: number, n: number): void {
    const o = this.o;
    const base = (x * o + y) * o;
    for (let i = 0; i < o; i++) if (i !== n - 1) this.cube[base + i] = 0;
    for (let i = 0; i < o; i++) {
      if (i !== y) this.cube[(x * o + i) * o + n - 1] = 0;
      if (i !== x) this.cube[(i * o + y) * o + n - 1] = 0;
    }
    this.grid[y * o + x] = n;
    this.row[y * o + n - 1] = 1;
    this.col[x * o + n - 1] = 1;
  }

  /**
   * Look along `o` cube entries from `start` in steps of `step`: if exactly one is set,
   * place it (+1); if none, contradiction (−1); otherwise 0.
   */
  private elim(start: number, step: number): number {
    const o = this.o;
    let m = 0;
    let fpos = -1;
    for (let i = 0; i < o; i++) {
      if (this.cube[start + i * step]) {
        fpos = start + i * step;
        m++;
      }
    }
    if (m === 0) return -1;
    if (m === 1) {
      const n = 1 + (fpos % o);
      const xy = Math.floor(fpos / o);
      const x = Math.floor(xy / o);
      const y = xy % o;
      if (!this.grid[y * o + x]) {
        this.place(x, y, n);
        return 1;
      }
    }
    return 0;
  }

  /** Positional elimination in rows and columns, then numeric elimination per cell. */
  simple(): number {
    const o = this.o;
    for (let y = 0; y < o; y++)
      for (let n = 1; n <= o; n++)
        if (!this.row[y * o + n - 1]) {
          const r = this.elim(this.pos(0, y, n), o * o);
          if (r) return r;
        }
    for (let x = 0; x < o; x++)
      for (let n = 1; n <= o; n++)
        if (!this.col[x * o + n - 1]) {
          const r = this.elim(this.pos(x, 0, n), o);
          if (r) return r;
        }
    for (let x = 0; x < o; x++)
      for (let y = 0; y < o; y++)
        if (!this.grid[y * o + x]) {
          const r = this.elim(this.pos(x, y, 1), 1);
          if (r) return r;
        }
    return 0;
  }

  /**
   * Set elimination over every row and column (digits vs positions), or in the
   * `positional` form over every digit (rows vs columns).
   */
  set(positional: boolean): number {
    const o = this.o;
    if (!positional) {
      for (let y = 0; y < o; y++) {
        const r = this.setElim(this.pos(0, y, 1), o * o, 1);
        if (r) return r;
      }
      for (let x = 0; x < o; x++) {
        const r = this.setElim(this.pos(x, 0, 1), o, 1);
        if (r) return r;
      }
    } else {
      for (let n = 1; n <= o; n++) {
        const r = this.setElim(this.pos(0, 0, n), o * o, o);
        if (r) return r;
      }
    }
    return 0;
  }

  /**
   * Given an o×o boolean matrix (rows stepping by step1, columns by step2) in which
   * every row must end up with exactly one true entry, drop the rows that are already
   * decided, then look for a set of k columns that between them are the only options
   * for k rows: every other row can then be cleared in those columns.
   */
  private setElim(start: number, step1: number, step2: number): number {
    const o = this.o;
    const { cube, sGrid: grid, sRowIdx: rowidx, sColIdx: colidx, sSet: set } = this;
    rowidx.fill(1);
    colidx.fill(1);
    for (let i = 0; i < o; i++) {
      let count = 0;
      let first = -1;
      for (let j = 0; j < o; j++)
        if (cube[start + i * step1 + j * step2]) {
          first = j;
          count++;
        }
      if (count === 0) return -1;
      if (count === 1) {
        rowidx[i] = 0;
        colidx[first] = 0;
      }
    }
    let n = 0;
    for (let i = 0; i < o; i++) if (rowidx[i]) rowidx[n++] = i;
    let nc = 0;
    for (let i = 0; i < o; i++) if (colidx[i]) colidx[nc++] = i;
    if (nc !== n) return -1; // more decided digits than cells or vice versa
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        grid[i * o + j] = cube[start + rowidx[i] * step1 + colidx[j] * step2];

    set.fill(0, 0, n);
    let count = 0;
    for (;;) {
      if (count > 1 && count < n - 1) {
        // Rows with no candidate in any column of `set`.
        let rows = 0;
        for (let i = 0; i < n; i++) {
          let ok = true;
          for (let j = 0; j < n; j++)
            if (set[j] && grid[i * o + j]) {
              ok = false;
              break;
            }
          if (ok) rows++;
        }
        if (rows > n - count) return -1;
        if (rows === n - count) {
          let progress = false;
          for (let i = 0; i < n; i++) {
            let ok = true;
            for (let j = 0; j < n; j++)
              if (set[j] && grid[i * o + j]) {
                ok = false;
                break;
              }
            if (ok) continue;
            for (let j = 0; j < n; j++)
              if (!set[j] && grid[i * o + j]) {
                cube[start + rowidx[i] * step1 + colidx[j] * step2] = 0;
                progress = true;
              }
          }
          if (progress) return 1;
        }
      }
      // Next subset: binary increment over `set`.
      let i = n;
      while (i > 0 && set[i - 1]) {
        set[--i] = 0;
        count--;
      }
      if (i === 0) break;
      set[i - 1] = 1;
      count++;
    }
    return 0;
  }

  /**
   * Forcing chains: from each two-candidate cell, follow chains of two-candidate cells
   * in line with each other that share candidates. If ruling N out at the start would
   * force N at the far end, then any cell in line with both ends cannot be N.
   */
  forcing(): number {
    const o = this.o;
    const { sNumber: number, sQueue: queue } = this;
    for (let y = 0; y < o; y++) {
      for (let x = 0; x < o; x++) {
        let count = 0;
        let t = 0;
        for (let n = 1; n <= o; n++)
          if (this.has(x, y, n)) {
            count++;
            t += n;
          }
        if (count !== 2) continue;
        for (let n = 1; n <= o; n++) {
          if (!this.has(x, y, n)) continue;
          const orign = n;
          number.fill(o + 1);
          let head = 0;
          let tail = 0;
          queue[tail++] = y * o + x;
          number[y * o + x] = t - n;
          while (head < tail) {
            const cur = queue[head++];
            const xx = cur % o;
            const yy = Math.floor(cur / o);
            const currn = number[cur];
            for (let k = 0; k < 2 * o; k++) {
              const xt = k < o ? xx : k - o;
              const yt = k < o ? k : yy;
              if (xt === xx && yt === yy) continue;
              if (number[yt * o + xt] <= o) continue;
              if (!this.has(xt, yt, currn)) continue;
              let cc = 0;
              let tt = 0;
              for (let nn = 1; nn <= o; nn++)
                if (this.has(xt, yt, nn)) {
                  cc++;
                  tt += nn;
                }
              if (cc === 2) {
                queue[tail++] = yt * o + xt;
                number[yt * o + xt] = tt - currn;
              }
              if (currn === orign && (xt === x || yt === y)) {
                this.rule(xt, yt, orign);
                return 1;
              }
            }
          }
        }
      }
    }
    return 0;
  }

  complete(): boolean {
    for (let i = 0; i < this.grid.length; i++) if (!this.grid[i]) return false;
    return true;
  }
}

/**
 * Run every permitted technique until nothing more can be deduced. Returns the hardest
 * level used, or DIFF_IMPOSSIBLE / DIFF_AMBIGUOUS / DIFF_UNFINISHED. On success (or
 * ambiguity) `solver.grid` holds a solution.
 */
export function latinSolve(
  solver: LatinSolver,
  maxdiff: number,
  levels: LatinLevels,
  users: readonly (UserSolver | null)[],
  budget?: SolveBudget,
): number {
  let diff = levels.simple;
  outer: for (;;) {
    for (let i = 0; i <= maxdiff; i++) {
      let ret = users[i] ? users[i]!(solver) : 0;
      if (ret === 0 && i === levels.simple) ret = solver.simple();
      if (ret === 0 && i === levels.set) ret = solver.set(false);
      if (ret === 0 && i === levels.positionalSet) ret = solver.set(true);
      if (ret === 0 && i === levels.forcing) ret = solver.forcing();
      if (ret < 0) return DIFF_IMPOSSIBLE;
      if (ret > 0) {
        if (i > diff) diff = i;
        continue outer;
      }
    }
    break;
  }
  if (maxdiff >= levels.recursive) {
    const nsol = recurse(solver, levels, users, budget);
    if (nsol === OUT_OF_BUDGET) return DIFF_UNFINISHED;
    if (nsol < 0) return DIFF_IMPOSSIBLE;
    if (nsol === 1) return levels.recursive;
    if (nsol > 1) return DIFF_AMBIGUOUS;
    return diff; // nsol 0: the grid was already complete
  }
  return solver.complete() ? diff : DIFF_UNFINISHED;
}

/** What `recurse` returns when the budget ran out before the answer was known. */
const OUT_OF_BUDGET = -2;

/**
 * Guess in the emptiest-but-most-constrained cell and solve each branch. Returns −1 for
 * no solution, 1 for exactly one (left in `solver.grid`), 2 for several, 0 if there
 * was nothing left to guess, or OUT_OF_BUDGET.
 */
function recurse(
  solver: LatinSolver,
  levels: LatinLevels,
  users: readonly (UserSolver | null)[],
  budget?: SolveBudget,
): number {
  const o = solver.o;
  let best = -1;
  let bestcount = o + 1;
  for (let y = 0; y < o; y++)
    for (let x = 0; x < o; x++)
      if (!solver.grid[y * o + x]) {
        const c = solver.count(x, y);
        if (c < 2) return -1;
        if (c < bestcount) {
          bestcount = c;
          best = y * o + x;
        }
      }
  if (best < 0) return 0;
  const x = best % o;
  const y = Math.floor(best / o);
  let found = 0;
  let solution: Uint8Array | null = null;
  for (let n = 1; n <= o && found < 2; n++) {
    if (!solver.has(x, y, n)) continue;
    if (budget && --budget.nodes < 0) return OUT_OF_BUDGET;
    const sub = solver.clone();
    sub.place(x, y, n);
    const ret = latinSolve(sub, levels.recursive, levels, users, budget);
    // At the recursive level only a spent budget leaves a branch unfinished.
    if (ret === DIFF_UNFINISHED) return OUT_OF_BUDGET;
    if (ret === DIFF_IMPOSSIBLE) continue;
    if (!solution) solution = sub.grid;
    found += ret === DIFF_AMBIGUOUS ? 2 : 1;
  }
  if (solution) solver.grid.set(solution);
  return found === 0 ? -1 : found === 1 ? 1 : 2;
}
