/**
 * Keen generator and game-description format.
 *
 * A description is `<cages>,<clues>`. The cage structure lists the internal grid edges
 * in a fixed order — the w·(w−1) vertical edges in reading order, then the horizontal
 * ones column by column, then one virtual terminating edge — and records the number of
 * *non*-dividing edges before each dividing one: `_` for none, `a`…`y` for 1–25 and `z`
 * for 26 with no dividing edge following. Runs of the same letter are shortened to the
 * letter and a count (`_5`). The clues follow, one per cage in order of the cage's first
 * square: an operator letter (`a`dd, `m`ultiply, `s`ubtract, `d`ivide) and the total.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';
import type { Random } from '../../framework/rng';
import { latinGenerate } from './latin';
import {
  DIFF_NORMAL,
  OP_ADD,
  OP_CHARS,
  OP_DIV,
  OP_MUL,
  OP_SUB,
  cageResult,
  solveKeen,
} from './solver';
import type { Cage, Layout } from './solver';

export interface KeenParams {
  w: number;
  diff: number;
  /** Every clue is a multiplication. */
  multOnly: boolean;
}

/** Cages bigger than this are awkward to solve and their products do not fit a square. */
export const MAX_CAGE = 6;

/** Squares either side of internal edge `pos` (see the module comment for the order). */
function edgeCells(w: number, pos: number): [number, number] {
  if (pos < w * (w - 1)) {
    const y = Math.floor(pos / (w - 1));
    const x = pos % (w - 1);
    return [y * w + x, y * w + x + 1];
  }
  const x = Math.floor(pos / (w - 1)) - w;
  const y = pos % (w - 1);
  return [y * w + x, (y + 1) * w + x];
}

/** Group squares into cages (ordered by first square) from a same-cage predicate. */
export function layoutFromDSF(w: number, dsf: DSF): Layout {
  const a = w * w;
  const whichCage = new Int32Array(a).fill(-1);
  const cages: Cage[] = [];
  const byRoot = new Map<number, number>();
  for (let xy = 0; xy < a; xy++) {
    const root = dsf.find(xy);
    let b = byRoot.get(root);
    if (b === undefined) {
      b = cages.length;
      byRoot.set(root, b);
      cages.push({ cells: [], op: OP_ADD, value: 0 });
    }
    cages[b].cells.push(xy);
    whichCage[xy] = b;
  }
  return { w, cages, whichCage };
}

/** Encode the cage structure of a layout. */
export function encodeCages(layout: Layout): string {
  const { w, whichCage } = layout;
  const edges = 2 * w * (w - 1);
  let raw = '';
  let run = 0;
  for (let i = 0; i <= edges; i++) {
    let edge = true;
    if (i < edges) {
      const [p0, p1] = edgeCells(w, i);
      edge = whichCage[p0] !== whichCage[p1];
    }
    if (!edge) {
      run++;
      continue;
    }
    while (run >= 26) {
      raw += 'z';
      run -= 26;
    }
    raw += run ? String.fromCharCode(96 + run) : '_';
    run = 0;
  }
  let out = '';
  for (let i = 0; i < raw.length;) {
    const c = raw[i];
    let j = i;
    while (j < raw.length && raw[j] === c) j++;
    const len = j - i;
    out += len === 2 ? c + c : len > 2 ? c + String(len) : c;
    i = j;
  }
  return out;
}

/**
 * Parse a cage structure starting at `desc[start]`. Returns the layout and the index
 * just past the structure (at the comma or end), or an error message.
 */
export function parseCages(
  w: number,
  desc: string,
  start = 0,
): { layout: Layout; end: number } | string {
  const a = w * w;
  const edges = 2 * w * (w - 1);
  const dsf = new DSF(a);
  let pos = 0;
  let repc = 0;
  let repn = 0;
  let i = start;
  while (repn > 0 || (i < desc.length && desc[i] !== ',')) {
    let c: number;
    if (repn > 0) {
      repn--;
      c = repc;
    } else {
      const ch = desc[i];
      if (ch === '_' || (ch >= 'a' && ch <= 'z')) {
        c = ch === '_' ? 0 : ch.charCodeAt(0) - 96;
        i++;
        const m = /^\d+/.exec(desc.slice(i));
        if (m) {
          repc = c;
          repn = parseInt(m[0], 10) - 1;
          i += m[0].length;
        }
      } else {
        return tx`Invalid character in game description`;
      }
    }
    const advance = c !== 26;
    while (c-- > 0) {
      if (pos >= edges) return tx`Too much data in block structure specification`;
      const [p0, p1] = edgeCells(w, pos);
      dsf.merge(p0, p1);
      pos++;
    }
    if (advance) {
      pos++;
      if (pos > edges + 1) return tx`Too much data in block structure specification`;
    }
  }
  if (pos !== edges + 1) return tx`Not enough data in block structure specification`;
  return { layout: layoutFromDSF(w, dsf), end: i };
}

/** Parse a full description into a layout with clues, or return an error message. */
export function parseDesc(w: number, desc: string): Layout | string {
  const r = parseCages(w, desc);
  if (typeof r === 'string') return r;
  const { layout } = r;
  // The solver enumerates every filling of a cage, so a pasted description with one huge
  // cage (a whole 6×6, say) would freeze Solve for good. Allow what keeps a cage to about
  // a million fillings, and never less than MAX_CAGE, the most any generated puzzle (here
  // or in the original) has: that still takes a whole 3×3 grid as one cage.
  const maxCage = Math.max(MAX_CAGE, Math.floor(6 / Math.log10(w)));
  if (layout.cages.some((c) => c.cells.length > maxCage)) return tx`A killer cage is too big`;
  let i = r.end;
  if (desc[i] !== ',') return tx`Expected ',' after block structure description`;
  i++;
  for (const cage of layout.cages) {
    if (i >= desc.length) return tx`Too few clues for block structure`;
    const op = OP_CHARS.indexOf(desc[i]);
    if (op < 0) return tx`Unrecognised clue type`;
    if ((op === OP_SUB || op === OP_DIV) && cage.cells.length !== 2)
      return tx`Subtraction and division blocks must have area 2`;
    i++;
    const m = /^\d+/.exec(desc.slice(i));
    if (!m) return tx`Clue is missing its number`;
    cage.op = op;
    cage.value = parseInt(m[0], 10);
    i += m[0].length;
  }
  if (i < desc.length) return tx`Too many clues for block structure`;
  return layout;
}

export function encodeDesc(layout: Layout): string {
  let s = encodeCages(layout) + ',';
  for (const c of layout.cages) s += OP_CHARS[c.op] + String(c.value);
  return s;
}

const F_ADD = 1;
const F_SUB = 2;
const F_MUL = 4;
const F_DIV = 8;
const BAD_SHIFT = 4;

/**
 * Divide the grid into cages: first pair squares into dominoes at random (so there are
 * plenty of places for subtraction and division clues), then fold each remaining single
 * square into a neighbouring cage that still has room. Returns null when a square was
 * left over with nowhere to go.
 */
function divideIntoCages(w: number, rng: Random): Layout | null {
  const a = w * w;
  const order: number[] = [];
  for (let i = 0; i < a; i++) order.push(i);
  rng.shuffle(order);
  const rank = new Int32Array(a);
  for (let i = 0; i < a; i++) rank[order[i]] = i;
  const single = new Uint8Array(a).fill(1);
  const dsf = new DSF(a);

  const bestNeighbour = (i: number, ok: (j: number) => boolean): number => {
    const x = i % w;
    const y = Math.floor(i / w);
    let best = -1;
    const consider = (j: number) => {
      if (ok(j) && (best === -1 || rank[j] < rank[best])) best = j;
    };
    if (x > 0) consider(i - 1);
    if (x + 1 < w) consider(i + 1);
    if (y > 0) consider(i - w);
    if (y + 1 < w) consider(i + w);
    return best;
  };

  for (let i = 0; i < a; i++) {
    if (!single[i]) continue;
    const best = bestNeighbour(i, (j) => single[j] === 1);
    // Place a domino three times in four, leaving some singles to grow bigger shapes.
    if (best >= 0 && rng.upto(4) !== 0) {
      single[i] = single[best] = 0;
      dsf.merge(i, best);
    }
  }
  for (let i = 0; i < a; i++) {
    if (!single[i]) continue;
    const best = bestNeighbour(i, (j) => dsf.sizeOf(j) < MAX_CAGE);
    if (best >= 0) {
      single[i] = single[best] = 0;
      dsf.merge(i, best);
    }
  }
  for (let i = 0; i < a; i++) if (single[i]) return null;
  return layoutFromDSF(w, dsf);
}

/** Choose an operator for every cage and fill in the clue totals. */
function chooseClues(
  layout: Layout,
  grid: Uint8Array,
  diff: number,
  multOnly: boolean,
  rng: Random,
) {
  const { w, cages } = layout;
  const flags = new Int32Array(cages.length);
  for (let b = 0; b < cages.length; b++) {
    const cells = cages[b].cells;
    if (multOnly) {
      flags[b] = F_MUL;
    } else if (cells.length > 2) {
      flags[b] = F_ADD | F_MUL;
    } else if (cells.length === 2) {
      const p = Math.max(grid[cells[0]], grid[cells[1]]);
      const q = Math.min(grid[cells[0]], grid[cells[1]]);
      // Sums of 3, 4, 2w−1 and 2w−2 leave only one pair of digits: too easy.
      const sum = p + q;
      flags[b] |= sum > 4 && sum < 2 * w - 2 ? F_ADD : F_ADD << BAD_SHIFT;
      // Above Normal, prefer products with several factorisations.
      const prod = p * q;
      let ways = 0;
      for (let k = 1; k <= w; k++) if (prod % k === 0 && prod / k <= w && prod / k !== k) ways++;
      flags[b] |= ways <= 2 && diff > DIFF_NORMAL ? F_MUL << BAD_SHIFT : F_MUL;
      // A difference of w−1 gives the pair away completely.
      if (p - q < w - 1) flags[b] |= F_SUB;
      // Quotients above w/2 are both too easy and inelegant.
      if (p % q === 0 && 2 * (p / q) <= w) flags[b] |= F_DIV;
    } else {
      flags[b] = F_ADD;
    }
  }

  const order: number[] = [];
  for (let b = 0; b < cages.length; b++) order.push(b);
  rng.shuffle(order);
  const kinds: [number, number][] = [
    [OP_DIV, F_DIV],
    [OP_SUB, F_SUB],
    [OP_MUL, F_MUL],
    [OP_ADD, F_ADD],
  ];
  // Deal the operators out in rotation so the four kinds stay roughly balanced, taking
  // the good candidates for each kind before falling back on the poor ones.
  for (;;) {
    let done = false;
    for (const [op, good] of kinds) {
      let pick = order.find((b) => flags[b] & good);
      if (pick === undefined) pick = order.find((b) => flags[b] & (good << BAD_SHIFT));
      if (pick === undefined) continue;
      cages[pick].op = op;
      flags[pick] = 0;
      done = true;
    }
    if (!done) break;
  }
  for (const c of cages)
    c.value = cageResult(
      c.op,
      c.cells.map((xy) => grid[xy]),
    );
}

/**
 * Squares' worth of attempts (attempts × w²) at one band of difficulty before the
 * generator widens the band by one easier level. Every preset nearly always finds its
 * exact level well inside one budget; some custom combinations — small multiplication-
 * only grids at Hard and up, above all — need hundreds of thousands of attempts, which
 * froze the tab for a minute or more. Widening keeps every deal to a second or two.
 */
const ATTEMPT_BUDGET = 100_000;

/** Generate a puzzle of the requested difficulty; `aux` carries the solution. */
export function generateKeen(p: KeenParams, rng: Random): { desc: string; aux: string } {
  const { w } = p;
  const a = w * w;
  let diff = p.diff;
  // 3×3 grids cannot support Hard or harder puzzles: the generator would spin forever.
  if (w === 3 && diff > DIFF_NORMAL) diff = DIFF_NORMAL;
  const soln = new Uint8Array(a);
  const perBand = Math.ceil(ATTEMPT_BUDGET / a);
  let attempts = 0;
  for (;;) {
    // The easiest level accepted: the requested one at first, one lower per spent budget.
    const lowest = Math.max(0, diff - Math.floor(attempts++ / perBand));
    const grid = latinGenerate(w, rng);
    const layout = divideIntoCages(w, rng);
    if (!layout) continue;
    chooseClues(layout, grid, diff, p.multOnly, rng);
    if (lowest > 0) {
      soln.fill(0);
      if (solveKeen(layout, soln, lowest - 1) <= lowest - 1) continue;
    }
    soln.fill(0);
    if (solveKeen(layout, soln, diff) > diff) continue;
    for (let i = 0; i < a; i++)
      if (soln[i] !== grid[i]) throw new Error(tx`generateKeen: solver disagrees with the square`);
    let aux = 'S';
    for (let i = 0; i < a; i++) aux += String(soln[i]);
    return { desc: encodeDesc(layout), aux };
  }
}
