export type UndeadParams = GenParams;

export interface UndeadState {
  w: number;
  h: number;
  /** The fixed puzzle: mirrors, totals, clues and precomputed lines of sight. */
  layout: Layout;
  /** Monster in every slot (GHOST, VAMPIRE, ZOMBIE) or 0 when empty. */
  types: Uint8Array;
  /** Pencil-mark candidates per slot, as type bits. */
  pencil: Uint8Array;
  check: BoardCheck;
  completed: boolean;
  usedSolve: boolean;
}

export interface UndeadUI {
  hx: number;
  hy: number;
  /** The highlight is shown. */
  hshow: boolean;
  /** Typed letters become pencil marks. */
  hpencil: boolean;
  /** The highlight was placed with the keyboard, so it stays after a letter is typed. */
  hcursor: boolean;
  /**
   * The Sight tool: draw the lines of sight through the highlighted square, and let a
   * click on an edge number trace that number's own line.
   */
  sight: boolean;
  /** The edge number whose line of sight is traced, or -1 to follow the highlight. */
  sightClue: number;
  /**
   * The slot a plain tap has just cycled from empty to a ghost, and the pencil marks it
   * had before, or null. On a touch screen that tap is the only way to highlight a square,
   * so the keypad's pencil latch that follows it means "note this", not "keep the ghost".
   */
  tapped: { s: number; pencil: number } | null;
}

const FLASH_FRAME = 0.13;
const FLASH = 5 * FLASH_FRAME;
const MAX_AREA = 54;
/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it at the gentlest setting the Type menu
 * offers at that size, and goes up the ladder when they want to.
 */
const DEFAULTS: UndeadParams = { w: 4, h: 4, diff: DIFF_EASY };
/** Left-click order: empty → ghost → vampire → zombie → empty. */
const CYCLE = [0, GHOST, VAMPIRE, ZOMBIE];

export interface Geometry {
  t: number;
  /** Outer margin. */
  b: number;
  /** Width of the band of clues around the grid. */
  ring: number;
  /** Height of the legend row above the grid. */
  legend: number;
  gridX: number;
  gridY: number;
}

export function geometry(t: number): Geometry {
  const b = Math.round(t * 0.3);
  const ring = Math.round(t * 0.7);
  const legend = Math.round(t * 0.9);
  return { t, b, ring, legend, gridX: b + ring, gridY: b + legend + ring };
}

function makeState(layout: Layout, types: Uint8Array, pencil: Uint8Array): UndeadState {
  const check = checkBoard(layout, types);
  return {
    w: layout.w,
    h: layout.h,
    layout,
    types,
    pencil,
    check,
    completed: check.complete,
    usedSolve: false,
  };
}

/** The pencil marks after one right-click: add the next candidate, or clear when full. */
export function nextPencil(mask: number): number {
  if (mask === ALL_TYPES) return 0;
  for (const t of TYPES) if (!(mask & t)) return mask | t;
  return 0;
}

/** A solution to the puzzle, from `aux` when it checks out, else from the solver. */
function findSolution(L: Layout, aux: string | undefined): Uint8Array | null {
  if (aux !== undefined) {
    const types = decodeSolution(aux, L.numSlots);
    if (types && checkBoard(L, types).complete) return types;
  }
  return search(new Work(L), 1).first;
}

// ------------------------------------------------------------------ drawing bits

/** Draw a monster icon centred on (cx, cy), fitting in a box of side `s`. */
export function drawMonster(
  dr: Drawing,
  cx: number,
  cy: number,
  s: number,
  type: number,
  seed: number,
  outline: string,
): void {
  const lw = Math.max(1.1, s * 0.055);
  if (type === GHOST && ziggyEnabled()) {
    // The ghost is already a domed body with two eyes; Ziggy is the same silhouette with
    // ears, so this is the one substitution that changes nothing about how the puzzle reads.
    drawZiggy(dr, cx, cy, s, seed, { outline });
  } else if (type === GHOST) {
    // A sheet: domed top, straight sides, three scallops along the hem.
    const r = s * 0.34;
    const top = cy - s * 0.4;
    const hem = cy + s * 0.36;
    const pts: number[] = [];
    for (let k = 0; k <= 8; k++) {
      const a = Math.PI + (k / 8) * Math.PI;
      pts.push(cx + Math.cos(a) * r, top + r + Math.sin(a) * r);
    }
    pts.push(cx + r, hem);
    for (let k = 0; k < 3; k++) {
      const x1 = cx + r - ((k + 0.5) * 2 * r) / 3;
      const x2 = cx + r - ((k + 1) * 2 * r) / 3;
      pts.push(x1, hem - s * 0.13, x2, hem);
    }
    dr.polygon(pts, 'paper', outline, { seed, width: lw });
    const er = Math.max(0.8, s * 0.06);
    dr.dot(cx - s * 0.13, cy - s * 0.1, er, outline, { seed: seed + 1 });
    dr.dot(cx + s * 0.13, cy - s * 0.1, er, outline, { seed: seed + 2 });
  } else if (type === VAMPIRE) {
    // A pale face under a dark, widow's-peaked head of hair, with two fangs.
    const r = s * 0.37;
    dr.circle(cx, cy, r, dr.mix('purple', 'paper', 0.55), outline, { seed, width: lw });
    const hair: number[] = [];
    for (let k = 0; k <= 8; k++) {
      const a = Math.PI + 0.35 + (k / 8) * (Math.PI - 0.7);
      hair.push(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
    hair.push(cx + r * 0.62, cy - r * 0.42, cx, cy - r * 0.1, cx - r * 0.62, cy - r * 0.42);
    dr.polygon(hair, 'ink', null, { seed: seed + 3, rough: 0.5 });
    const er = Math.max(0.8, s * 0.05);
    dr.dot(cx - s * 0.13, cy + s * 0.06, er, outline, { seed: seed + 1 });
    dr.dot(cx + s * 0.13, cy + s * 0.06, er, outline, { seed: seed + 2 });
    const my = cy + s * 0.2;
    dr.line(cx - s * 0.16, my, cx + s * 0.16, my, outline, lw * 0.8, { seed: seed + 4 });
    for (const fx of [cx - s * 0.08, cx + s * 0.08]) {
      dr.polygon(
        [fx - s * 0.045, my, fx + s * 0.045, my, fx, my + s * 0.13],
        'highlight',
        outline,
        { seed: seed + 5, width: lw * 0.7, rough: 0.3 },
      );
    }
  } else if (type === ZOMBIE) {
    // A boxy green head: stitched scar, one crossed-out eye, a flat mouth.
    const half = s * 0.36;
    dr.roundRect(
      cx - half,
      cy - half,
      2 * half,
      2 * half,
      s * 0.1,
      dr.mix('green', 'paper', 0.5),
      outline,
      { seed, width: lw },
    );
    const sx1 = cx - s * 0.3;
    const sy1 = cy - s * 0.16;
    const sx2 = cx + s * 0.1;
    const sy2 = cy - s * 0.24;
    dr.line(sx1, sy1, sx2, sy2, outline, lw * 0.8, { seed: seed + 1 });
    for (let k = 1; k <= 3; k++) {
      const u = k / 4;
      const px = sx1 + (sx2 - sx1) * u;
      const py = sy1 + (sy2 - sy1) * u;
      dr.line(px, py - s * 0.05, px, py + s * 0.05, outline, lw * 0.7, { seed: seed + 10 + k });
    }
    dr.cross(cx - s * 0.14, cy + s * 0.03, s * 0.055, outline, lw * 0.8, { seed: seed + 2 });
    dr.dot(cx + s * 0.15, cy + s * 0.03, Math.max(0.8, s * 0.055), outline, { seed: seed + 3 });
    const my = cy + s * 0.22;
    dr.line(cx - s * 0.17, my, cx + s * 0.17, my, outline, lw * 0.8, { seed: seed + 4 });
    dr.line(cx - s * 0.06, my - s * 0.05, cx - s * 0.06, my + s * 0.05, outline, lw * 0.7, {
      seed: seed + 5,
    });
    dr.line(cx + s * 0.06, my - s * 0.05, cx + s * 0.06, my + s * 0.05, outline, lw * 0.7, {
      seed: seed + 6,
    });
  }
}

/** Canvas position of the clue at edge position `r`. */
export function cluePos(g: Geometry, w: number, h: number, r: number): { x: number; y: number } {
  const { t, ring, gridX, gridY } = g;
  const e = edgeEntry(r, w, h);
  const cx = gridX + e.x * t + t / 2;
  const cy = gridY + e.y * t + t / 2;
  if (e.dy === 1) return { x: cx, y: gridY - ring / 2 };
  if (e.dx === -1) return { x: gridX + w * t + ring / 2, y: cy };
  if (e.dy === -1) return { x: cx, y: gridY + h * t + ring / 2 };
  return { x: gridX - ring / 2, y: cy };
}

/** The edge position under (mx, my) in the band of numbers around the grid, or -1. */
export function clueAt(g: Geometry, w: number, h: number, mx: number, my: number): number {
  const { t, ring, gridX, gridY } = g;
  const tx = Math.floor((mx - gridX) / t);
  const ty = Math.floor((my - gridY) / t);
  const inCols = tx >= 0 && tx < w;
  const inRows = ty >= 0 && ty < h;
  if (inCols && my >= gridY - ring && my < gridY) return tx;
  if (inRows && mx >= gridX + w * t && mx < gridX + w * t + ring) return w + ty;
  if (inCols && my >= gridY + h * t && my < gridY + h * t + ring) return w + h + (w - 1 - tx);
  if (inRows && mx >= gridX - ring && mx < gridX) return 2 * w + h + (h - 1 - ty);
  return -1;
}

/**
 * The lines of sight the Sight tool is showing, as indices into `layout.paths`: the one
 * from the chosen edge number, or every one through the highlighted square.
 */
export function sightPaths(state: UndeadState, ui: UndeadUI): number[] {
  if (!ui.sight) return [];
  const L = state.layout;
  if (ui.sightClue >= 0) return [L.cluePath[ui.sightClue]];
  if (!ui.hshow) return [];
  const i = ui.hy * state.w + ui.hx;
  const out: number[] = [];
  L.paths.forEach((p, k) => {
    if (p.cells.includes(i)) out.push(k);
  });
  return out;
}

// ------------------------------------------------------------------ the game

const game = defineGame<UndeadParams, UndeadState, UndeadUI>({
  id: 'undead',
  name: 'Undead',
  description: 'Place ghosts, vampires and zombies to match what is seen in the mirrors.',
  alsoKnownAs: 'Haunted Mirror Maze',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [4, 4, DIFF_EASY],
      [4, 4, DIFF_NORMAL],
      [4, 4, DIFF_TRICKY],
      [5, 5, DIFF_EASY],
      [5, 5, DIFF_NORMAL],
      [5, 5, DIFF_TRICKY],
      [7, 7, DIFF_EASY],
      [7, 7, DIFF_NORMAL],
    ] as [number, number, number][]
  ).map(([w, h, diff]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[diff]}`,
    params: { w, h, diff },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? `d${DIFFICULTY_CODES[p.diff]}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    const d = m[3] ? DIFFICULTY_CODES.indexOf(m[3]) : -1;
    return { w, h, diff: d >= 0 ? d : DIFF_NORMAL };
  },
  validateParams(p) {
    if (![p.w, p.h, p.diff].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 3) return tx`Width must be at least 3`;
    if (p.h < 3) return tx`Height must be at least 3`;
    if (p.w * p.h > MAX_AREA) return tx`Grid is too big`;
    if (p.diff < 0 || p.diff >= DIFFICULTY_NAMES.length) return tx`Unknown difficulty rating`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.diff },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "5.5" or "5x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      diff: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const d = parseDesc(desc, p.w, p.h);
    if (typeof d === 'string') throw new Error(d);
    const layout = new Layout(p.w, p.h, d.cells, d.total, d.clues);
    const types = new Uint8Array(layout.numSlots);
    for (let i = 0; i < layout.numSlots; i++) types[i] = layout.fixed[i];
    const state = makeState(layout, types, new Uint8Array(layout.numSlots));
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const L = curr.layout;
    const solution = findSolution(L, aux);
    if (!solution) throw new Error(tx`Puzzle is unsolvable`);
    let move = 'S';
    for (let i = 0; i < L.numSlots; i++)
      if (curr.types[i] !== solution[i]) move += `;${TYPE_LETTERS[solution[i]]}${i}`;
    return move;
  },

  textFormat(s) {
    const { w, h, layout: L } = s;
    const cell = (v: string) => v.padStart(2, ' ');
    const clue = (r: number) => cell(String(L.clues[r]));
    const lines = [`G: ${L.total[0]} V: ${L.total[1]} Z: ${L.total[2]}`, ''];
    let top = '  ';
    let bottom = '  ';
    for (let x = 0; x < w; x++) {
      top += clue(x);
      bottom += clue(w + h + (w - 1 - x));
    }
    lines.push(top);
    for (let y = 0; y < h; y++) {
      let row = clue(2 * w + h + (h - 1 - y));
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const m = L.mirror[i];
        row += cell(m ? (m === CELL_L ? '\\' : '/') : (TYPE_LETTERS[s.types[L.slot[i]]] ?? '.'));
      }
      lines.push(row + clue(w + y));
    }
    lines.push(bottom);
    return lines.join('\n');
  },

  newUI: () => ({
    hx: 0,
    hy: 0,
    hshow: false,
    hpencil: false,
    hcursor: false,
    sight: false,
    sightClue: -1,
    tapped: null,
  }),
  changedState(ui, _old, next) {
    if (next.completed) ui.hshow = false;
    // A pencil highlight on a square that has just been filled (Undo, Redo, Solve) makes
    // no sense, so drop it unless the keyboard cursor is in use.
    if (ui.hshow && ui.hpencil && !ui.hcursor) {
      const s = next.layout.slot[ui.hy * next.w + ui.hx];
      if (s < 0 || next.types[s]) ui.hshow = false;
    }
  },

  // Tapping a square cycles through the monsters, but the keypad picks one directly —
  // the same G/V/Z keys the keyboard sends.
  keypad: () => ({
    keys: ['G', 'V', 'Z'],
    labels: { G: 'Ghost', V: 'Vampire', Z: 'Zombie' },
    clear: true,
    pencil: true,
  }),

  actions: [
    {
      label: 'Sight',
      key: 'S',
      hud: true,
      glyph: EYE_GLYPH,
      pressed: (_s, ui) => ui.sight,
      title: 'Trace the lines of sight through a square, or from an edge number (S)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, layout: L } = state;
    const cycle = (s: number): string => {
      const next = CYCLE[(CYCLE.indexOf(state.types[s]) + 1) % CYCLE.length];
      return next ? `${TYPE_LETTERS[next]}${s}` : `E${s}`;
    };
    const pencilCycle = (s: number): string => {
      const next = nextPencil(state.pencil[s]);
      if (next === 0) return `E${s}`;
      return `${TYPE_LETTERS[next & ~state.pencil[s]].toLowerCase()}${s}`;
    };

    const tapped = ui.tapped;
    // The release (and any jitter) that follows the tap keeps it; anything else ends it.
    if (!isMouseDrag(b) && !isMouseRelease(b)) ui.tapped = null;
    const ch0 = keyChar(b);
    if (ch0 === 's' || ch0 === 'S') {
      ui.sight = !ui.sight;
      ui.sightClue = -1;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const g = geometry(ds.tileSize);
      if (ui.sight) {
        // An edge number traces its own line of sight; a second click lets it go.
        const r = clueAt(g, w, h, mx, my);
        if (r >= 0) {
          ui.sightClue = ui.sightClue === r ? -1 : r;
          ui.hshow = false;
          return '';
        }
      }
      const hadClue = ui.sightClue >= 0;
      ui.sightClue = -1;
      const tx = Math.floor((mx - g.gridX) / g.t);
      const ty = Math.floor((my - g.gridY) / g.t);
      const s = tx >= 0 && ty >= 0 && tx < w && ty < h ? L.slot[ty * w + tx] : -1;
      if (s < 0 || L.fixed[s]) {
        // Mirrors, fixed monsters and the surroundings just drop the highlight.
        if (!ui.hshow) return hadClue ? '' : null;
        ui.hshow = false;
        return '';
      }
      const same = ui.hshow && ui.hx === tx && ui.hy === ty;
      ui.hx = tx;
      ui.hy = ty;
      ui.hshow = true;
      ui.hcursor = false;
      if (b === LEFT_BUTTON) {
        ui.hpencil = false;
        // With Sight on, a tap on a new square only moves the highlight and traces its
        // lines — on a touch screen there is no other way to look at an empty square
        // without filling it. Tapping the highlighted square again cycles as usual.
        if (ui.sight && !same) return '';
        if (!state.types[s]) ui.tapped = { s, pencil: state.pencil[s] };
        return cycle(s);
      }
      if (state.types[s]) {
        ui.hpencil = false;
        return '';
      }
      ui.hpencil = true;
      return pencilCycle(s);
    }
    if (isCursorMove(b)) {
      ui.sightClue = -1;
      const p = moveCursor(b, ui.hx, ui.hy, w, h);
      ui.hx = p.x;
      ui.hy = p.y;
      ui.hshow = true;
      ui.hcursor = true;
      return '';
    }
    if (isCursorSelect(b)) {
      const wasShown = ui.hshow;
      ui.hshow = true;
      ui.hcursor = true;
      if (!wasShown) return '';
      const s = L.slot[ui.hy * w + ui.hx];
      if (s < 0 || L.fixed[s]) return '';
      if (b === CURSOR_SELECT) {
        ui.hpencil = false;
        return cycle(s);
      }
      if (state.types[s]) return '';
      ui.hpencil = true;
      return pencilCycle(s);
    }
    if (!ui.hshow) return null;
    let type = 0;
    let clear = b === KEY_BACKSPACE;
    const ch = keyChar(b)?.toLowerCase();
    if (ch === 'g' || ch === '1') type = GHOST;
    else if (ch === 'v' || ch === '2') type = VAMPIRE;
    else if (ch === 'z' || ch === '3') type = ZOMBIE;
    else if (ch === 'e' || ch === '0') clear = true;
    else if (!clear) return null;
    const s = L.slot[ui.hy * w + ui.hx];
    if (s < 0 || L.fixed[s]) return null;
    if (clear) {
      if (!ui.hcursor) ui.hshow = false;
      return state.types[s] || state.pencil[s] ? `E${s}` : '';
    }
    // MOD_SHFT on a letter is the on-screen keypad's pencil latch: note the monster
    // down instead of placing it, whatever mode the square was selected in.
    if (ui.hpencil || (button & MOD_SHFT) !== 0) {
      if (tapped?.s === s && state.types[s] === GHOST) {
        // The ghost is only there because the square was tapped to highlight it: take it
        // back out and note the monster among the marks the square had before.
        const marks = tapped.pencil ^ type;
        return [
          `E${s}`,
          ...[GHOST, VAMPIRE, ZOMBIE]
            .filter((m) => marks & m)
            .map((m) => TYPE_LETTERS[m].toLowerCase() + s),
        ].join(';');
      }
      if (state.types[s]) return '';
      return `${TYPE_LETTERS[type].toLowerCase()}${s}`;
    }
    if (!ui.hcursor) ui.hshow = false;
    return state.types[s] === type ? '' : `${TYPE_LETTERS[type]}${s}`;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { layout: L } = state;
    const types = state.types.slice();
    const pencil = state.pencil.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = /^([GVZEgvz])(\d+)$/.exec(part);
      if (!m) return null;
      const s = parseInt(m[2], 10);
      if (s >= L.numSlots || L.fixed[s]) return null;
      const c = m[1];
      if (c === 'E') {
        types[s] = 0;
        pencil[s] = 0;
      } else if (c === c.toUpperCase()) {
        types[s] = { G: GHOST, V: VAMPIRE, Z: ZOMBIE }[c]!;
        pencil[s] = 0;
      } else {
        if (types[s]) return null;
        pencil[s] ^= { g: GHOST, v: VAMPIRE, z: ZOMBIE }[c]!;
      }
    }
    // Typing the monster already there, or erasing an empty slot: no undo step.
    if (
      usedSolve === state.usedSolve &&
      sameArr(types, state.types) &&
      sameArr(pencil, state.pencil)
    )
      return state;
    return { ...makeState(L, types, pencil), usedSolve };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const g = geometry(t);
    return { w: 2 * g.b + 2 * g.ring + p.w * t, h: 2 * g.b + g.legend + 2 * g.ring + p.h * t };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, layout: L, types, pencil, check } = state;
    const t = ds.tileSize;
    const g = geometry(t);
    const { gridX, gridY, ring } = g;
    const flash = flashOn(flashTime, FLASH_FRAME);
    const inkish = flash ? 'ok' : 'ink';

    // Legend: each monster with how many are still to be placed.
    const placed = [0, 0, 0];
    for (const v of types) if (v) placed[TYPE_INDEX[v]]++;
    const legendY = g.b + g.legend / 2;
    const span = w * t + 2 * ring;
    for (let k = 0; k < 3; k++) {
      const cx = g.b + (span * (k + 0.5)) / 3;
      drawMonster(dr, cx - t * 0.28, legendY, t * 0.62, TYPES[k], 900 + k, inkish);
      dr.text(cx + t * 0.12, legendY, String(L.total[k] - placed[k]), {
        size: t * 0.48,
        colour: check.countBad[k] ? 'error' : inkish,
        align: 'left',
      });
    }

    dr.rect(gridX, gridY, w * t, h * t, flash ? 'shade' : 'paper');
    if (ui.hshow) {
      dr.rect(gridX + ui.hx * t, gridY + ui.hy * t, t, t, ui.hpencil ? 'blue' : 'yellow', null, {
        alpha: ui.hpencil ? 0.12 : 0.25,
      });
    }
    for (let x = 1; x < w; x++)
      dr.line(gridX + x * t, gridY, gridX + x * t, gridY + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++)
      dr.line(gridX, gridY + y * t, gridX + w * t, gridY + y * t, 'faint', 1.2);

    // The Sight tool: each line of sight from one edge number to the other, bending at
    // the mirrors, under the monsters so they stay readable.
    const traced = sightPaths(state, ui);
    const SIGHT_COLOURS = ['accent', 'teal'];
    traced.forEach((k, n) => {
      const p = L.paths[k];
      const a = cluePos(g, w, h, p.start);
      const z = cluePos(g, w, h, p.end);
      const pts = [a.x, a.y];
      for (const c of p.cells)
        pts.push(gridX + (c % w) * t + t / 2, gridY + Math.floor(c / w) * t + t / 2);
      pts.push(z.x, z.y);
      dr.polyline(pts, SIGHT_COLOURS[n % 2], Math.max(2, t * 0.07), { alpha: 0.45, seed: 300 + k });
    });

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = gridX + x * t;
        const py = gridY + y * t;
        const m = L.mirror[i];
        if (m) {
          const inset = t * 0.18;
          const y1 = m === CELL_L ? py + inset : py + t - inset;
          const y2 = m === CELL_L ? py + t - inset : py + inset;
          dr.line(px + inset, y1, px + t - inset, y2, inkish, Math.max(2.4, t * 0.085), {
            seed: i,
          });
          continue;
        }
        const s = L.slot[i];
        if (L.fixed[s]) dr.rect(px + 1, py + 1, t - 2, t - 2, 'shade');
        const v = types[s];
        if (v) {
          const bad = check.countBad[TYPE_INDEX[v]];
          drawMonster(dr, px + t / 2, py + t / 2, t * 0.8, v, i, bad ? 'error' : inkish);
        } else if (pencil[s]) {
          const spots: [number, number][] = [
            [0.28, 0.3],
            [0.72, 0.3],
            [0.28, 0.72],
          ];
          // Small monsters rather than the letters G, V and Z, which only read in English.
          for (let k = 0; k < 3; k++) {
            if (!(pencil[s] & TYPES[k])) continue;
            const [sx, sy] = spots[k];
            drawMonster(dr, px + t * sx, py + t * sy, t * 0.38, TYPES[k], 700 + i, 'pencil');
          }
        }
      }
    }
    dr.rectOutline(gridX, gridY, w * t, h * t, 'ink', { width: 2.6 });

    for (let r = 0; r < 2 * (w + h); r++) {
      const p = cluePos(g, w, h, r);
      const st = check.clueState[r];
      dr.text(p.x, p.y, String(L.clues[r]), {
        size: t * 0.44,
        colour: st < 0 ? 'error' : flash ? 'ok' : st > 0 ? 'pencil' : 'ink',
      });
    }
    traced.forEach((k, n) => {
      const p = L.paths[k];
      for (const r of [p.start, p.end]) {
        const c = cluePos(g, w, h, r);
        dr.circle(c.x, c.y, t * 0.3, null, SIGHT_COLOURS[n % 2], { width: 2, seed: 400 + r });
      }
    });

    if (ui.hshow) {
      const inset = t * 0.08;
      const hx = gridX + ui.hx * t + inset;
      const hy = gridY + ui.hy * t + inset;
      dr.cursor(hx, hy, t - 2 * inset, t - 2 * inset, 'accent', 2.2, {
        dash: ui.hpencil ? [Math.max(3, t * 0.1), Math.max(2, t * 0.08)] : undefined,
      });
      if (ui.hpencil) {
        const sz = t * 0.22;
        dr.polygon([hx, hy, hx + sz, hy, hx, hy + sz], 'accent', null, { seed: 7 });
      }
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  /** Half of the thumbnail puzzle's solution, so the menu shows all three monsters. */
  thumbnailMoves: ['G0', 'Z1', 'G2', 'Z4', 'V5'],
});

export default game;

function sameArr(a: ArrayLike<number>, b: ArrayLike<number>): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}
