import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { CubeParams, CubeState } from './index';

type C = typeof PALETTE;

/** A cube in isometric view, top vertex at (x, y), edge `s`; faces blue with ink shading. */
function cube(c: C, x: number, y: number, s: number, stroke = 4.5): string {
  const h = s / 2;
  const top = `M${x} ${y} L${x + s} ${y + h} L${x} ${y + s} L${x - s} ${y + h} Z`;
  const left = `M${x - s} ${y + h} L${x} ${y + s} L${x} ${y + 2.2 * s} L${x - s} ${y + 1.7 * s} Z`;
  const right = `M${x} ${y + s} L${x + s} ${y + h} L${x + s} ${y + 1.7 * s} L${x} ${y + 2.2 * s} Z`;
  const face = (d: string, shade: number) =>
    `<path d="${d}" fill="${c.blue}"/>` +
    (shade ? `<path d="${d}" fill="${c.ink}" fill-opacity="${shade}"/>` : '') +
    `<path d="${d}" fill="none" stroke="${c.ink}" stroke-width="${stroke}" stroke-linejoin="round"/>`;
  return face(left, 0.15) + face(right, 0.35) + face(top, 0);
}

/** Rolls it took: the game records the move on which every face turned blue. */
const rolls = (s: CubeState) => s.completed || s.moves;

export const achievements = defineAchievements<CubeParams, CubeState>([
  {
    id: 'short-haul',
    name: 'Short Haul',
    description: 'Finish the Cube with every face blue in no more than twenty rolls.',
    tier: 'silver',
    hue: 'yellow',
    // A blue cube mid-journey, one neat roll arrow over its shoulder.
    art: (c) =>
      `<ellipse cx="40" cy="80" rx="22" ry="4" fill="${c.ink}" fill-opacity="0.18"/>` +
      cube(c, 40, 32, 18) +
      `<path d="M52 24 Q74 18 80 42" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round"/>` +
      `<path d="M72 38 L80 46 L86 36" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: (ctx) => ctx.params.solid === 'c' && rolls(ctx.state) <= 20,
  },
  {
    id: 'octahedron-ace',
    name: 'Eight Faces Fast',
    description: 'Finish the Octahedron with every face blue in no more than thirty rolls.',
    tier: 'gold',
    hue: 'violet',
    // The octahedron seen from the front: four faces in view, all blue.
    art: (c) => {
      const T = '50 16';
      const B = '50 84';
      const L = '22 48';
      const R = '78 48';
      const F = '44 56';
      const face = (d: string, shade: number) =>
        `<path d="M${d} Z" fill="${c.blue}"/>` +
        (shade ? `<path d="M${d} Z" fill="${c.ink}" fill-opacity="${shade}"/>` : '');
      return (
        face(`${T} L${L} L${F}`, 0) +
        face(`${T} L${F} L${R}`, 0.2) +
        face(`${B} L${L} L${F}`, 0.3) +
        face(`${B} L${F} L${R}`, 0.45) +
        `<path d="M${T} L${R} L${B} L${L} Z M${T} L${F} L${B} M${L} L${F} L${R}" fill="none" stroke="${c.ink}" stroke-width="4.5" stroke-linejoin="round" stroke-linecap="round"/>`
      );
    },
    test: (ctx) => ctx.params.solid === 'o' && rolls(ctx.state) <= 30,
  },
  {
    id: 'scenic-route',
    name: 'Grand Tour',
    description: 'Roll the solid at least two hundred times before every face is blue.',
    tier: 'bronze',
    hidden: true,
    hue: 'green',
    // A long, looping trail of roll marks behind a small cube that got there eventually.
    art: (c) =>
      `<path d="M18 80 C22 50 50 86 54 62 C58 40 22 52 26 32 C30 16 56 24 62 38" fill="none" stroke="${c.pencil}" stroke-width="4.5" stroke-linecap="round" stroke-dasharray="1 8"/>` +
      cube(c, 70, 38, 12, 4),
    test: (ctx) => rolls(ctx.state) >= 200,
  },
]);
