import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { D, L, R } from './board';
import { geometry } from './index';
import type { TracksState, TracksUI } from './index';

/** One grid square, or a block of them, as a canvas rectangle. */
function cells(t: number, x: number, y: number, w = 1, h = 1): TutorialRect {
  const g = geometry(t);
  return { x: g.gx + x * t, y: g.gy + y * t, w: w * t, h: h * t };
}

function centre(t: number, x: number, y: number) {
  const g = geometry(t);
  return { x: g.gx + (x + 0.5) * t, y: g.gy + (y + 0.5) * t };
}

/** The count written above column `x`, or beside row `y`, as a canvas rectangle. */
function count(state: TracksState, t: number, line: number): TutorialRect {
  const g = geometry(t);
  const cx = line < state.w ? g.gx + line * t + t / 2 : g.gx + state.w * t + g.gutter / 2;
  const cy = line < state.w ? g.gy - g.gutter / 2 : g.gy + (line - state.w) * t + t / 2;
  const s = g.gutter * 0.9;
  return { x: cx - s / 2, y: cy - s / 2, w: s, h: s };
}

const idx = (s: TracksState, x: number, y: number) => y * s.w + x;
const rail = (s: TracksState, x: number, y: number, d: number) =>
  (s.board.track[idx(s, x, y)] & d) !== 0;

/**
 * A 4×4 railway. The entrance piece forces the top-left corner, the left column's count
 * of 2 is already met so its lower half is crossed out, and the right column's count of
 * 4 runs the line straight down it.
 */
export const tutorial: Tutorial<TracksState, TracksUI> = {
  steps: [
    {
      gameId: '4x4:d6dAcAb,2,S4,4,4,4,S4,3,3',
      text: 'One railway runs from the entrance on the left to the exit at the bottom, and every square it visits has exactly two rails. The numbers say how many squares of that column or row the line passes through.',
      highlight: ({ state, tileSize }) => {
        const g = geometry(tileSize);
        return {
          x: g.pad,
          y: g.pad,
          w: state.w * tileSize + 2 * g.gutter,
          h: state.h * tileSize + 2 * g.gutter,
        };
      },
    },
    {
      text: 'The entrance piece already runs up into the **top-left square**, and that square’s top and left sides are the edge of the grid. So its second rail must go right: **click** just right of its middle.',
      highlight: ({ tileSize }) => cells(tileSize, 0, 0),
      pointer: ({ tileSize }) => {
        const c = centre(tileSize, 0, 0);
        return { x: c.x + tileSize * 0.35, y: c.y };
      },
      waitFor: ({ state }) => rail(state, 0, 0, R),
    },
    {
      text: 'The **left column** is counted **2** and the entrance already uses both squares, so nothing runs through the bottom half of it. **Right-click** the middle of a square to cross it out — a right-drag crosses a whole run.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, 0, 2, 1, state.h - 2),
        count(state, tileSize, 0),
      ],
      pointer: ({ tileSize }) => ({ ...centre(tileSize, 0, 2), button: 'right' as const }),
      waitFor: ({ state }) => state.board.sNotrack[idx(state, 0, 2)] !== 0,
    },
    {
      text: 'The **right column** is counted **4**, so the line visits every square of it, and the squares at its top and bottom can only turn inwards. **Drag** from the top-right square all the way down to the bottom-right one.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, state.w - 1, 0, 1, state.h),
        count(state, tileSize, state.w - 1),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(tileSize, state.w - 1, 0),
        to: centre(tileSize, state.w - 1, state.h - 1),
      }),
      waitFor: ({ state }) => {
        for (let y = 0; y < state.h - 1; y++) if (!rail(state, state.w - 1, y, D)) return false;
        return true;
      },
    },
    {
      text: 'The **bottom row** needs three squares and the left column is finished, so the bottom-right corner is on the line. It cannot leave the grid, so it turns left and up: **click** its left side.',
      highlight: ({ state, tileSize }) => [
        cells(tileSize, state.w - 1, state.h - 1),
        count(state, tileSize, state.w + state.h - 1),
      ],
      pointer: ({ state, tileSize }) => {
        const c = centre(tileSize, state.w - 1, state.h - 1);
        return { x: c.x - tileSize * 0.35, y: c.y };
      },
      waitFor: ({ state }) => rail(state, state.w - 1, state.h - 1, L),
    },
    {
      text: 'Counts go grey when their line is right and red when it cannot work out. Carry on around the loose ends, or let **Solve** finish the railway.',
      target: '[data-cmd="solve"]',
    },
  ],
};
