/**
 * The phone's Back gesture closes whatever is lying over the page — a dialog, the More
 * sheet, the help drawer — and leaves the player on the puzzle, as every mobile app does.
 * Before this, Back went straight past the open layer to the menu, taking the half-played
 * board's page with it.
 *
 * One extra history entry (same address, a marker in its state) stands for "something is
 * open", however many layers are stacked: Back pops it and closes the top layer, and if one
 * is still open underneath, the entry is put back for the next Back. A layer closed any
 * other way (its own button, Escape, the dimmer) takes the entry back out with
 * `history.back()` — a tick later, so a layer that hands over to another (More → Custom…)
 * keeps the entry instead of stepping out and straight back in.
 *
 * The router never sees any of this: the marker entry has the page's own address, so no
 * `hashchange` fires going into it or out of it.
 */

interface Layer {
  close: () => void;
}

const MARK = 'puzzleboxLayer';
const layers: Layer[] = [];
/** Our marker entry is (or is about to be) the current one. */
let entry = false;
/** We called `history.back()` to take the entry out and its popstate has not arrived. */
let leaving = false;
let checkQueued = false;
/** Address changes held back until the marker entry is gone (see {@link afterLayers}). */
const waiting: Array<() => void> = [];
let listening = false;

function onMarker(): boolean {
  return (history.state as Record<string, unknown> | null)?.[MARK] === true;
}

function push() {
  try {
    history.pushState({ ...(history.state ?? {}), [MARK]: true }, '', location.href);
    entry = true;
  } catch {
    /* a sandboxed frame may refuse; the layer still closes every other way */
  }
}

function settled() {
  if (entry || leaving || layers.length) return;
  for (const fn of waiting.splice(0)) fn();
}

function onPopState() {
  if (!entry) return;
  if (onMarker()) return; // Forward onto our own entry, or a same-address hop: still in.
  entry = false;
  if (leaving) {
    leaving = false;
    // A layer opened while the entry was on its way out needs one of its own.
    if (layers.length) push();
    settled();
    return;
  }
  // The player's Back: close the top layer (taken off the stack first, so its own close
  // does not ask for a second step back), and keep an entry for any layer under it.
  const top = layers.pop();
  top?.close();
  if (layers.length) push();
  settled();
}

function check() {
  checkQueued = false;
  if (layers.length || !entry || leaving) return;
  // Only step back off our own entry: a navigation made with the layer up (a link to the
  // menu) has already moved on, and stepping back from there would undo it.
  if (onMarker()) {
    leaving = true;
    history.back();
  } else {
    entry = false;
    settled();
  }
}

/**
 * A link followed with a layer up (the drawer's achievements button, the page's own Back
 * link beside an open drawer) would stack its page on top of the marker entry, and the
 * phone's Back from there would land on the marker — the same puzzle, looking like a Back
 * that did nothing. Close the layers and step off the marker first, then follow the link.
 */
function onLinkClick(e: MouseEvent) {
  if (!entry || e.defaultPrevented || e.button !== 0) return;
  if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const a = e.target instanceof Element ? e.target.closest('a[href]') : null;
  const href = a?.getAttribute('href');
  if (!href || !href.startsWith('#/') || a?.getAttribute('target')) return;
  e.preventDefault();
  for (const layer of layers.splice(0).reverse()) layer.close();
  waiting.push(() => {
    location.hash = href;
  });
  if (!leaving) {
    if (onMarker()) {
      leaving = true;
      history.back();
    } else {
      entry = false;
      settled();
    }
  }
}

/**
 * Register an open layer; `close` is how Back shuts it. Returns the function the layer
 * calls when it closes by any other means (safe to call more than once, or after Back).
 */
export function pushLayer(close: () => void): () => void {
  if (!listening) {
    listening = true;
    window.addEventListener('popstate', onPopState);
    document.addEventListener('click', onLinkClick, true);
  }
  const layer: Layer = { close };
  layers.push(layer);
  if (!entry && !leaving) push();
  return () => {
    const i = layers.indexOf(layer);
    if (i < 0) return;
    layers.splice(i, 1);
    if (!layers.length && !checkQueued) {
      checkQueued = true;
      setTimeout(check, 0);
    }
  };
}

/**
 * Run `fn` — a `history.replaceState` of the page's address — once no marker entry is left
 * to step back over. Replacing the address on the marker entry would make the step back
 * onto the page's own entry a change of address, which the router takes for a navigation.
 */
export function afterLayers(fn: () => void): void {
  if (!entry && !leaving && !layers.length) fn();
  else waiting.push(fn);
}
