import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { LOCKED, rotate } from './core';
import type { NetParams, NetState } from './index';

type C = typeof PALETTE;

/**
 * A block of wired tiles at (x, y), `s` a side: `rows` gives each tile's wires as letters
 * from "ruld" (right, up, left, down), '.' for a tile with none. Lit wires are blue and
 * the rest grey, as on the board; a tile named in `shaded` gets the shaded background.
 */
function wires(
  c: C,
  x: number,
  y: number,
  s: number,
  rows: string[][],
  opts: { lit?: (i: number, j: number) => boolean; shaded?: string } = {},
): string {
  const w = s * 0.3;
  let bg = '';
  let under = '';
  let over = '';
  let ends = '';
  rows.forEach((row, j) => {
    row.forEach((cell, i) => {
      const px = x + i * s;
      const py = y + j * s;
      const fill = opts.shaded === `${i},${j}` ? c.shade : c.paper;
      bg += `<rect x="${px}" y="${py}" width="${s}" height="${s}" fill="${fill}" stroke="${c.pencil}" stroke-width="1.5"/>`;
      if (cell === '.') return;
      const cx = px + s / 2;
      const cy = py + s / 2;
      const to: Record<string, string> = {
        r: `${px + s} ${cy}`,
        u: `${cx} ${py}`,
        l: `${px} ${cy}`,
        d: `${cx} ${py + s}`,
      };
      let d = '';
      for (const k of cell) d += `M${cx} ${cy} L${to[k]} `;
      const colour = (opts.lit?.(i, j) ?? true) ? c.blue : c.lowlight;
      under += `<path d="${d}" stroke="${c.ink}" stroke-width="${w + 3}"/><circle cx="${cx}" cy="${cy}" r="${w / 2 + 1.5}" fill="${c.ink}"/>`;
      over += `<path d="${d}" stroke="${colour}" stroke-width="${w}"/><circle cx="${cx}" cy="${cy}" r="${w / 2}" fill="${colour}"/>`;
      if (cell.length === 1)
        ends += `<circle cx="${cx}" cy="${cy}" r="${s * 0.2}" fill="${colour}" stroke="${c.ink}" stroke-width="2.5"/>`;
    });
  });
  const W = rows[0].length * s;
  const H = rows.length * s;
  return (
    bg +
    under +
    over +
    ends +
    `<rect x="${x}" y="${y}" width="${W}" height="${H}" fill="none" stroke="${c.ink}" stroke-width="3.5"/>`
  );
}

/** Quarter turns between two orientations of a tile, the short way round. */
function turnsBetween(from: number, to: number): number {
  let best = Infinity;
  for (let n = 0; n < 4; n++)
    if ((rotate(from, n) & 15) === (to & 15)) best = Math.min(best, n, 4 - n);
  return best;
}

/** Tiles whose wiring differs between two boards (a lock alone changes none). */
function turned(a: NetState, b: NetState): number[] {
  const out: number[] = [];
  for (let i = 0; i < a.tiles.length; i++) if ((a.tiles[i] & 15) !== (b.tiles[i] & 15)) out.push(i);
  return out;
}

const bigBoard = (p: NetParams) => p.w >= 9 && p.h >= 9;

export const achievements = defineAchievements<NetParams, NetState>([
  {
    id: 'no-locks',
    name: 'Nothing Under Lock',
    description: 'Solve a Net of 9×9 or larger without locking a single tile.',
    tier: 'silver',
    hue: 'teal',
    // A wired tile with an open padlock beside it.
    art: (c) =>
      wires(c, 20, 34, 34, [['rld']]) +
      `<path d="M64 47 V38 Q64 27 73 27 Q82 27 82 37" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round"/>` +
      `<rect x="58" y="47" width="24" height="22" rx="4" fill="${c.yellow}" stroke="${c.ink}" stroke-width="4"/>` +
      `<circle cx="70" cy="56" r="3.5" fill="${c.ink}"/><path d="M70 57 V63" stroke="${c.ink}" stroke-width="3.5" stroke-linecap="round"/>`,
    test: (ctx) =>
      bigBoard(ctx.params) && ctx.history.every((s) => !s.tiles.some((t) => t & LOCKED)),
  },
  {
    id: 'not-a-turn-wasted',
    name: 'Not a Turn Wasted',
    description: 'Solve a Net of 9×9 or larger without turning any tile more than it needs.',
    tier: 'gold',
    hue: 'yellow',
    // A single corner tile with one clean quarter-turn arrow round it.
    art: (c) =>
      wires(c, 34, 34, 34, [['ur']]) +
      `<path d="M24 50 A28 28 0 0 1 48 23" fill="none" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round"/>` +
      `<path d="M41 18 L49 22.5 L43 30" fill="none" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/>` +
      `<path d="M58 76 L65 82 L80 66" fill="none" stroke="${c.green}" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: (ctx) => {
      if (!bigBoard(ctx.params)) return false;
      let turns = 0;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1];
        const b = ctx.history[k];
        const changed = turned(a, b);
        if (changed.length > 1) return false; // a Jumble
        for (const i of changed) turns += turnsBetween(a.tiles[i], b.tiles[i]);
      }
      let needed = 0;
      for (let i = 0; i < ctx.initial.tiles.length; i++)
        needed += turnsBetween(ctx.initial.tiles[i], ctx.state.tiles[i]);
      return turns <= needed;
    },
  },
  {
    id: 'jumbled',
    name: 'All Shook Up',
    description: 'Press Jumble and still go on to solve the puzzle.',
    tier: 'bronze',
    hidden: true,
    hue: 'pink',
    // Four tiles knocked askew, with shake lines.
    art: (c) =>
      `<g transform="rotate(-12 36 36)">${wires(c, 23, 23, 26, [['rd']])}</g>` +
      `<g transform="rotate(10 64 36)">${wires(c, 51, 23, 26, [['lu']], { lit: () => false })}</g>` +
      `<g transform="rotate(8 36 64)">${wires(c, 23, 51, 26, [['ud']], { lit: () => false })}</g>` +
      `<g transform="rotate(-9 64 64)">${wires(c, 51, 51, 26, [['l']])}</g>` +
      `<path d="M16 38 Q12 50 16 62 M84 38 Q88 50 84 62" fill="none" stroke="${c.ink}" stroke-width="4" stroke-linecap="round"/>`,
    // Jumble is the only move that turns more than one tile at once — apart from Restart,
    // which puts every tile back as dealt and so is told apart by matching the deal.
    test: (ctx) =>
      ctx.history
        .slice(1)
        .some((s, k) => turned(ctx.history[k], s).length > 1 && turned(ctx.initial, s).length > 0),
  },
]);
