import { tx } from '../../i18n';
/**
 * Game descriptions, in the original collection's format so its game IDs keep working:
 * the 4w clues (top, bottom, left, right; blank when missing) separated by `/`, then
 * optionally `,` and the given digits in reading order with runs of empty squares as
 * letters (`a` = 1 … `z` = 26) and `_` between two adjacent digits.
 */
export interface TowersDesc {
  clues: Int32Array;
  grid: Uint8Array;
}

export function encodeDesc(w: number, clues: ArrayLike<number>, grid: ArrayLike<number>): string {
  const a = w * w;
  const parts: string[] = [];
  for (let c = 0; c < 4 * w; c++) parts.push(clues[c] ? String(clues[c]) : '');
  let desc = parts.join('/');
  let anyGiven = false;
  for (let i = 0; i < a; i++) if (grid[i]) anyGiven = true;
  if (!anyGiven) return desc;
  desc += ',';
  let run = 0;
  for (let i = 0; i <= a; i++) {
    const n = i < a ? grid[i] : -1;
    if (n === 0) {
      run++;
      continue;
    }
    if (run) {
      while (run > 0) {
        const chunk = Math.min(run, 26);
        desc += String.fromCharCode(96 + chunk);
        run -= chunk;
      }
    } else if (i > 0 && n > 0) {
      desc += '_';
    }
    if (n > 0) desc += String(n);
  }
  return desc;
}

/** Parse a description, returning the clues and given digits or an error message. */
export function parseDesc(w: number, desc: string): TowersDesc | string {
  const a = w * w;
  const clues = new Int32Array(4 * w);
  const grid = new Uint8Array(a);
  let p = 0;
  const digitAt = (i: number) => i < desc.length && desc[i] >= '0' && desc[i] <= '9';
  for (let c = 0; c < 4 * w; c++) {
    if (p >= desc.length) return tx`Too few clues for grid size`;
    if (c > 0) {
      if (desc[p] !== '/') return tx`Expected slashes between clues`;
      p++;
    }
    if (digitAt(p)) {
      let q = p;
      while (digitAt(q)) q++;
      const clue = parseInt(desc.slice(p, q), 10);
      p = q;
      if (clue <= 0 || clue > w) return tx`Clue number out of range`;
      clues[c] = clue;
    }
  }
  if (p < desc.length && desc[p] === '/') return tx`Too many clues for grid size`;
  if (p < desc.length) {
    if (desc[p] !== ',') return tx`Invalid character in game description`;
    p++;
    let pos = 0;
    while (p < desc.length) {
      const ch = desc[p++];
      if (ch >= 'a' && ch <= 'z') {
        pos += ch.charCodeAt(0) - 96;
      } else if (ch === '_') {
        // separator between two digits
      } else if (ch >= '1' && ch <= '9') {
        let q = p;
        while (digitAt(q)) q++;
        const val = parseInt(desc.slice(p - 1, q), 10);
        p = q;
        if (val < 1 || val > w) return tx`Out-of-range number in grid description`;
        if (pos < a) grid[pos] = val;
        pos++;
      } else {
        return tx`Invalid character in game description`;
      }
    }
    if (pos < a) return tx`Not enough data to fill grid`;
    if (pos > a) return tx`Too much data to fit in grid`;
  }
  return { clues, grid };
}
