/**
 * Singles (Hitori) board model shared by the game, the solver and the generator.
 *
 * A puzzle is a `w × h` grid of numbers `1..o` where `o = max(w, h)`. The player marks
 * each cell either black (its number is removed) or circled (it is definitely white);
 * an unmarked cell counts as white. A finished grid must satisfy three rules: no number
 * appears twice among the white cells of a row or column, no two black cells touch
 * orthogonally, and the white cells form one connected region.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

/** Cell flag: blacked out. */
export const F_BLACK = 1;
/** Cell flag: circled (asserted white). */
export const F_CIRCLE = 2;

// ------------------------------------------------------------- description format

/** The character for a number in a description: `1`–`9`, then `a`–`z`, then `A`–`Z`. */
export function numToChar(num: number): string {
  if (num < 10) return String.fromCharCode(48 + num);
  if (num < 36) return String.fromCharCode(97 + num - 10);
  return String.fromCharCode(65 + num - 36);
}

/** The number for a description character, or -1 when it is not one. */
export function charToNum(ch: string): number {
  const c = ch.charCodeAt(0);
  if (c >= 48 && c <= 57) return c - 48;
  if (c >= 97 && c <= 122) return c - 97 + 10;
  if (c >= 65 && c <= 90) return c - 65 + 36;
  return -1;
}

/**
 * Parse a description: exactly one character per cell, each a number in `1..max(w, h)`.
 * Returns the numbers or an error message.
 */
export function parseDesc(desc: string, w: number, h: number): Uint8Array | string {
  const n = w * h;
  const o = Math.max(w, h);
  if (desc.length !== n) return tx`Game description is wrong length`;
  const nums = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const v = charToNum(desc[i]);
    if (v <= 0 || v > o) return tx`Game description contains unexpected characters`;
    nums[i] = v;
  }
  return nums;
}

export function encodeDesc(nums: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < nums.length; i++) s += numToChar(nums[i]);
  return s;
}

/** Encode a solution's black cells as a string of `0`/`1` (for `aux`). */
export function encodeBlacks(flags: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < flags.length; i++) s += flags[i] & F_BLACK ? '1' : '0';
  return s;
}

/** Decode `encodeBlacks` output into flags (blacks only), or null when malformed. */
export function decodeBlacks(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n || !/^[01]*$/.test(aux)) return null;
  const flags = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (aux[i] === '1') flags[i] = F_BLACK;
  return flags;
}

// ------------------------------------------------------------- rule checking

export interface GridCheck {
  /** Every rule holds: no duplicate whites, no touching blacks, whites connected. */
  complete: boolean;
  /** 1 for black cells that touch another black cell. */
  badBlack: Uint8Array;
  /** 1 for white cells outside the largest white region. */
  cutOff: Uint8Array;
  /** 1 for circled cells sharing a line with another circled cell of the same number. */
  clash: Uint8Array;
}

/** Union-find over the grid joining orthogonal neighbours of the same colour. */
export function colourRegions(flags: Uint8Array, w: number, h: number): DSF {
  const dsf = new DSF(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      const b = flags[i] & F_BLACK;
      if (x < w - 1 && (flags[i + 1] & F_BLACK) === b) dsf.merge(i, i + 1);
      if (y < h - 1 && (flags[i + w] & F_BLACK) === b) dsf.merge(i, i + w);
    }
  }
  return dsf;
}

/**
 * Check the three rules and work out what to highlight. Two identical white numbers in a
 * line are only flagged when both are circled: any pair of equal numbers in a line is a
 * conflict the player still has to resolve, and pointing at them (or at the partner of a
 * circled one) would solve the puzzle for them.
 */
export function checkGrid(nums: Uint8Array, flags: Uint8Array, w: number, h: number): GridCheck {
  const n = w * h;
  const badBlack = new Uint8Array(n);
  const cutOff = new Uint8Array(n);
  const clash = new Uint8Array(n);
  let complete = true;
  const dsf = colourRegions(flags, w, h);

  let nwhite = 0;
  for (let i = 0; i < n; i++) {
    if (flags[i] & F_BLACK) {
      if (dsf.sizeOf(i) > 1) {
        badBlack[i] = 1;
        complete = false;
      }
    } else {
      nwhite++;
    }
  }

  const line = (start: number, step: number, len: number) => {
    for (let a = 0, i = start; a < len; a++, i += step) {
      if (flags[i] & F_BLACK) continue;
      for (let b = a + 1, j = i + step; b < len; b++, j += step) {
        if (flags[j] & F_BLACK || nums[i] !== nums[j]) continue;
        complete = false;
        if (flags[i] & F_CIRCLE && flags[j] & F_CIRCLE) {
          clash[i] = 1;
          clash[j] = 1;
        }
      }
    }
  };
  for (let x = 0; x < w; x++) line(x, w, h);
  for (let y = 0; y < h; y++) line(y * w, 1, w);

  // Several white regions: the largest one (lowest index on a tie) is the real one.
  let largest = 0;
  let canonical = -1;
  for (let i = 0; i < n; i++) {
    if (flags[i] & F_BLACK) continue;
    const size = dsf.sizeOf(i);
    if (size > largest) {
      largest = size;
      canonical = dsf.find(i);
    }
  }
  if (largest < nwhite) {
    complete = false;
    for (let i = 0; i < n; i++) {
      if (!(flags[i] & F_BLACK) && dsf.find(i) !== canonical) cutOff[i] = 1;
    }
  }
  if (nwhite === 0) complete = false;
  return { complete, badBlack, cutOff, clash };
}

/** Whether a black/white assignment (blacks in `flags`) is a valid finished grid. */
export function isValidSolution(nums: Uint8Array, flags: Uint8Array, w: number, h: number) {
  return checkGrid(nums, flags, w, h).complete;
}
