import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { FILL } from './solver';
import type { FloodState, FloodUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/**
 * The square of colour `colour` that touches the controlled patch, earliest in reading
 * order, or null when that colour is not adjacent to the patch at all.
 */
function nextTo(state: FloodState, colour: number): number | null {
  const { w, h, grid } = state;
  const own = grid[FILL];
  const seen = new Uint8Array(w * h);
  const queue: number[] = [FILL];
  seen[FILL] = 1;
  let best: number | null = null;
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q];
    const x = i % w;
    const y = (i - x) / w;
    const nbs: number[] = [];
    if (x > 0) nbs.push(i - 1);
    if (x + 1 < w) nbs.push(i + 1);
    if (y > 0) nbs.push(i - w);
    if (y + 1 < h) nbs.push(i + w);
    for (const j of nbs) {
      if (seen[j]) continue;
      seen[j] = 1;
      if (grid[j] === own) queue.push(j);
      else if (grid[j] === colour && (best === null || j < best)) best = j;
    }
  }
  return best;
}

function squareRect(state: FloodState, tileSize: number, colour: number) {
  const i = nextTo(state, colour);
  if (i === null) return null;
  return cellRect(i % state.w, Math.floor(i / state.w), tileSize, border(tileSize));
}

function squarePoint(state: FloodState, tileSize: number, colour: number) {
  const i = nextTo(state, colour);
  if (i === null) return null;
  return cellCentre(i % state.w, Math.floor(i / state.w), tileSize, border(tileSize));
}

/** Colour indices, in the order the palette assigns them. */
const RED = 0;
const BLUE = 1;
const GREEN = 2;

/**
 * A fixed 4x4 grid of three colours that finishes in red, blue, green — three moves out
 * of a limit of four.
 */
export const tutorial: Tutorial<FloodState, FloodUI> = {
  steps: [
    {
      gameId: '4x4c3:1002012202111111,4',
      text: 'You own the top-left square and everything joined to it in the same colour. Each move repaints that patch, so touching squares of the new colour join in. Make the whole grid one colour inside the **four move** limit.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'Your patch is just that one blue corner for now. Click the **red** square next to it: the patch turns red and every red square it touches comes with it.',
      highlight: ({ state, tileSize }) => squareRect(state, tileSize, RED),
      pointer: ({ state, tileSize }) => squarePoint(state, tileSize, RED),
      waitFor: ({ state }) => state.moves >= 1 && state.grid[FILL] === RED,
    },
    {
      text: 'Now click a **blue** square on the edge of your patch. A well-chosen colour can chain a long way across the grid in one move.',
      highlight: ({ state, tileSize }) => squareRect(state, tileSize, BLUE),
      pointer: ({ state, tileSize }) => squarePoint(state, tileSize, BLUE),
      waitFor: ({ state }) => state.moves >= 2 && state.grid[FILL] === BLUE,
    },
    {
      text: 'Only **green** is left outside your patch. One more click sweeps the rest of the grid in.',
      highlight: ({ state, tileSize }) => squareRect(state, tileSize, GREEN),
      pointer: ({ state, tileSize }) => squarePoint(state, tileSize, GREEN),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Three moves of the four — the status line keeps the count. Run out before the grid is uniform and the round is lost. Stuck? A **Hint** plays one good colour for you, and **Solve** finishes the grid as an auto-solve.',
      target: '[data-cmd="hint"]',
    },
  ],
};
