import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { GuessParams, GuessState } from './index';

type C = typeof PALETTE;

function peg(c: C, cx: number, cy: number, r: number, fill: string): string {
  return (
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}" stroke="${c.ink}" stroke-width="2.8"/>` +
    `<circle cx="${cx - r * 0.35}" cy="${cy - r * 0.35}" r="${r * 0.28}" fill="${c.highlight}" fill-opacity="0.8"/>`
  );
}

/** A marking peg: black for right colour and place, hollow for right colour only. */
function mark(c: C, cx: number, cy: number, r: number, black: boolean): string {
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${black ? c.ink : c.paper}" stroke="${c.ink}" stroke-width="2.2"/>`;
}

/** Four marks in a 2×2 block centred on (cx, cy): `black` of them black, `hollow` hollow. */
function marks(c: C, cx: number, cy: number, black: number, hollow: number): string {
  let out = '';
  for (let i = 0; i < 4; i++) {
    const x = cx + (i % 2 ? 4.5 : -4.5);
    const y = cy + (i < 2 ? -4.5 : 4.5);
    if (i < black) out += mark(c, x, y, 3, true);
    else if (i < black + hollow) out += mark(c, x, y, 3, false);
    else out += `<circle cx="${x}" cy="${y}" r="1.4" fill="${c.pencil}"/>`;
  }
  return out;
}

export const achievements = defineAchievements<GuessParams, GuessState>([
  {
    id: 'five-guesses',
    name: 'Code Cracker',
    description: 'Find the hidden row in five guesses or fewer.',
    tier: 'silver',
    hue: 'blue',
    // Three rows of guesses, the last one marked all black.
    art: (c) => {
      const rows = [
        [c.red, c.blue, c.green, c.yellow],
        [c.blue, c.red, c.yellow, c.yellow],
        [c.yellow, c.red, c.green, c.blue],
      ];
      const score = [
        [1, 1],
        [1, 2],
        [4, 0],
      ];
      return (
        `<rect x="13" y="60" width="72" height="20" rx="5" fill="${c.shade}" stroke="${c.pencil}" stroke-width="2.5"/>` +
        rows
          .map(
            (row, r) =>
              row.map((col, i) => peg(c, 21 + i * 13.5, 26 + r * 22, 6, col)).join('') +
              marks(c, 75, 26 + r * 22, score[r][0], score[r][1]),
          )
          .join('')
      );
    },
    test: (ctx) => !ctx.state.revealed && ctx.state.guesses.length <= 5,
  },
  {
    id: 'super-sleuth',
    name: 'Super Sleuth',
    description: 'Find the Super hidden row of five pegs in six guesses or fewer.',
    tier: 'gold',
    hue: 'purple',
    // The shield swings up on a row of five, and every mark below is black.
    art: (c) =>
      `<g transform="rotate(-10 20 38)"><rect x="20" y="24" width="58" height="15" rx="4" fill="${c.dark}" stroke="${c.ink}" stroke-width="3.5"/></g>` +
      [c.red, c.green, c.purple, c.yellow, c.blue]
        .map((col, i) => peg(c, 22 + i * 14, 56, 6.5, col))
        .join('') +
      [0, 1, 2, 3, 4].map((i) => mark(c, 22 + i * 14, 76, 3.8, true)).join(''),
    test: (ctx) =>
      !ctx.state.revealed &&
      ctx.params.npegs >= 5 &&
      ctx.params.ncolours >= 8 &&
      ctx.state.guesses.length <= 6,
  },
  {
    id: 'so-near',
    name: 'So Near',
    description: 'Run out of guesses with every peg but one in the right place.',
    tier: 'bronze',
    hidden: true,
    hue: 'orange',
    on: 'lose',
    // The last row: three black marks and one that would not come.
    art: (c) =>
      `<rect x="16" y="22" width="68" height="18" rx="4" fill="${c.dark}" stroke="${c.ink}" stroke-width="3.5"/>` +
      [c.red, c.blue, c.green, c.green]
        .map((col, i) => peg(c, 29 + i * 14, 56, 6.5, col))
        .join('') +
      [0, 1, 2].map((i) => mark(c, 29 + i * 14, 76, 4, true)).join('') +
      `<path d="M67 72 L75 80 M75 72 L67 80" stroke="${c.red}" stroke-width="3.5" stroke-linecap="round"/>`,
    test: (ctx) => {
      const last = ctx.state.guesses[ctx.state.guesses.length - 1];
      return !!last && ctx.state.solved === -1 && last.place === ctx.params.npegs - 1;
    },
  },
]);
