import {
  ZIGGY_BODY_CLASS,
  ZIGGY_EYES_CLASS,
  ZIGGY_FEET,
  ziggyEnabled,
  ziggySVG,
  type ZiggyOptions,
} from '../framework/ziggy';
import { gsap, prefersReducedMotion } from './anim';

/**
 * Ziggy, alive.
 *
 * `framework/ziggy.ts` owns the drawing; this owns what the drawing *does*. The split
 * matters: the art has to stay renderable from a string with no timeline attached — the
 * store covers and the canvas games use it that way — so every motion here is bolted on
 * afterwards, to a Ziggy that is perfectly happy without it.
 *
 * Three layers move independently, which is the whole trick. The body breathes and sways
 * on a loop; the eyes blink on their own irregular clock; and reactions — a hop, a
 * head-shake, a slump — play on the `<svg>` itself, so a cheer never has to stop the
 * breathing or fight it for the same `transform`. The two loops are deliberately on
 * periods that do not divide into each other, so the pair never settles into a visible
 * pulse the way two matched loops do.
 *
 * Everything is off under `prefers-reduced-motion`: {@link mountMascot} still draws him,
 * he simply holds still, and every method below becomes a no-op.
 */

/** A mounted Ziggy and the small repertoire of things he can be asked to do. */
export interface Mascot {
  /** The `<svg>` itself, for callers that need to position or hide it. */
  readonly el: SVGSVGElement;
  /** Delighted: squash, hop, and wobble back down. Unlocks, wins, a poke from the player. */
  cheer(): void;
  /** "No." A quick shake of the head, for a thing the player cannot have yet. */
  nope(): void;
  /** Sags, and his eyes go to half-mast, until {@link perk} picks him back up. */
  droop(): void;
  /** Back to upright and wide awake. Safe to call when he already is. */
  perk(): void;
  /** Stop every loop and pending blink. Always call this when the host goes away. */
  destroy(): void;
}

/**
 * How long between blinks. Irregular on purpose — a mascot that blinks on the beat looks
 * like a blinking cursor — and occasionally twice in quick succession, which is what
 * actually sells it as a living thing rather than a timer.
 */
const BLINK_GAP = [2.4, 7.5] as const;
const DOUBLE_BLINK_CHANCE = 0.25;

/** How far the lids close. Not to zero: a sliver of ink left over reads as an eye. */
const LID_SHUT = 0.08;

/**
 * Draw a Ziggy into `host` and bring him to life.
 *
 * Returns `null` when the mascot is switched off (`?ziggy=0`), which is the signal for
 * "there is no mascot here" — callers can drop the whole feature on a null without
 * reaching for `ziggyEnabled()` themselves.
 */
export function mountMascot(host: Element, opts: ZiggyOptions = {}): Mascot | null {
  if (!ziggyEnabled()) return null;
  host.insertAdjacentHTML('beforeend', ziggySVG(opts));
  const el = host.lastElementChild as SVGSVGElement | null;
  return el ? animateMascot(el) : null;
}

/** As {@link mountMascot}, for a Ziggy some other code has already put in the page. */
export function animateMascot(el: SVGSVGElement): Mascot {
  const body = el.querySelector<SVGGElement>(`.${ZIGGY_BODY_CLASS}`);
  const eyes = el.querySelector<SVGGElement>(`.${ZIGGY_EYES_CLASS}`);
  const lid = eyes?.dataset.lid ?? '50 50';
  const tweens: gsap.core.Tween[] = [];
  let blinkCall: gsap.core.Tween | null = null;
  let dead = false;
  let drooping = false;

  const still: Mascot = {
    el,
    cheer: () => {},
    nope: () => {},
    droop: () => {},
    perk: () => {},
    destroy: () => {},
  };
  if (prefersReducedMotion() || !body || !eyes) return still;

  gsap.set(el, { transformOrigin: '50% 100%' });

  // ---- the two loops

  // A breath: the body rises and swells a touch, turning about his feet so he settles
  // back onto them rather than hovering.
  tweens.push(
    gsap.fromTo(
      body,
      { svgOrigin: ZIGGY_FEET, scaleY: 0.99, y: 0.5 },
      {
        scaleY: 1.025,
        y: -1.3,
        duration: 1.9,
        ease: 'sine.inOut',
        yoyo: true,
        repeat: -1,
      },
    ),
  );
  // …and a sway, on a period that is not a multiple of the breath's, so the two drift in
  // and out of phase instead of locking into one bigger movement.
  tweens.push(
    gsap.fromTo(
      body,
      { rotation: -1.3 },
      {
        rotation: 1.3,
        duration: 3.1,
        ease: 'sine.inOut',
        yoyo: true,
        repeat: -1,
        svgOrigin: ZIGGY_FEET,
      },
    ),
  );

  const blink = () => {
    if (dead) return;
    const tl = gsap.timeline({ onComplete: scheduleBlink });
    tl.set(eyes, { svgOrigin: lid })
      .to(eyes, { scaleY: LID_SHUT, duration: drooping ? 0.12 : 0.07, ease: 'power2.in' })
      .to(eyes, { scaleY: drooping ? 0.45 : 1, duration: 0.11, ease: 'power2.out' });
    if (gsap.utils.random(0, 1) < DOUBLE_BLINK_CHANCE) {
      tl.to(eyes, { scaleY: LID_SHUT, duration: 0.06, ease: 'power2.in' }).to(eyes, {
        scaleY: drooping ? 0.45 : 1,
        duration: 0.1,
        ease: 'power2.out',
      });
    }
  };
  const scheduleBlink = () => {
    if (dead) return;
    blinkCall = gsap.delayedCall(gsap.utils.random(BLINK_GAP[0], BLINK_GAP[1]), blink);
  };
  // Staggered from the very first blink, so two Ziggys on one page — the masthead and the
  // locked shelf below it — are never caught blinking in unison.
  blinkCall = gsap.delayedCall(gsap.utils.random(0.8, BLINK_GAP[1]), blink);

  // ---- reactions, all on the <svg>, all clearing after themselves

  const perk = () => {
    if (!drooping) return;
    drooping = false;
    gsap.to(el, { rotation: 0, yPercent: 0, scaleY: 1, duration: 0.3, ease: 'back.out(2)' });
    gsap.to(eyes, { scaleY: 1, duration: 0.2, ease: 'power2.out' });
  };

  return {
    el,
    cheer() {
      perk();
      // Gather, leap, land heavy, settle. The anticipation squash is what makes the hop
      // read as Ziggy jumping rather than Ziggy being lifted.
      gsap
        .timeline()
        .to(el, { scaleX: 1.12, scaleY: 0.86, duration: 0.1, ease: 'power2.out' })
        .to(el, {
          yPercent: -28,
          scaleX: 0.94,
          scaleY: 1.1,
          rotation: gsap.utils.random(-9, 9),
          duration: 0.24,
          ease: 'power2.out',
        })
        .to(el, { yPercent: 0, scaleX: 1.06, scaleY: 0.92, duration: 0.18, ease: 'power2.in' })
        .to(el, {
          scaleX: 1,
          scaleY: 1,
          rotation: 0,
          duration: 0.5,
          ease: 'elastic.out(1, 0.35)',
          clearProps: 'transform',
        });
    },
    nope() {
      perk();
      gsap
        .timeline()
        .to(el, { rotation: -9, xPercent: -6, duration: 0.08 })
        .to(el, { rotation: 9, xPercent: 6, duration: 0.1 })
        .to(el, { rotation: -6, xPercent: -4, duration: 0.09 })
        .to(el, {
          rotation: 0,
          xPercent: 0,
          duration: 0.16,
          ease: 'power2.out',
          clearProps: 'transform',
        });
    },
    droop() {
      drooping = true;
      gsap.to(el, {
        rotation: 10,
        yPercent: 6,
        scaleY: 0.9,
        duration: 0.55,
        ease: 'power2.out',
      });
      // The eyes go to half-mast and stay there — the one part of the slump that is not
      // posture, and the part that stops it reading as "knocked over".
      gsap.to(eyes, { svgOrigin: lid, scaleY: 0.45, duration: 0.4, ease: 'power2.out' });
    },
    perk,
    destroy() {
      dead = true;
      blinkCall?.kill();
      for (const tw of tweens) tw.kill();
      gsap.killTweensOf([el, body, eyes]);
    },
  };
}
