export type { PearlParams };

export interface PearlState {
  w: number;
  h: number;
  /** `NOCLUE`, `CORNER` (black pearl) or `STRAIGHT` (white pearl) per square. Shared. */
  clues: Uint8Array;
  /** Loop segments leaving each square, as `R|U|L|D` bits (stored in both squares). */
  lines: Uint8Array;
  /** "No line here" marks, same encoding as `lines`. */
  marks: Uint8Array;
  /** Per square: line directions in error (bits 0–3) and `ERROR_CLUE` (bit 4). */
  errors: Uint8Array;
  /** Set once the loop has been completed; never cleared (as in the original). */
  completed: boolean;
  usedSolve: boolean;
}

export interface PearlUI {
  /** Squares visited by the drag in progress; empty when no button is down. */
  drag: number[];
  /** A button is down: `drag` holds the start square, and more once it became a drag. */
  pressed: boolean;
  /** True once the pointer left the start square (a real drag rather than a click). */
  dragging: boolean;
  /** Canvas position of the initial press, which decides what a click means. */
  clickX: number;
  clickY: number;
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /**
   * The Cross tool: a left click or drag lays (or lifts) "no segment" crosses instead of
   * loop segments, as a right-click does for a single edge.
   */
  crossMode: boolean;
  /**
   * The drag in progress lays crosses rather than segments: taken at the press, from the
   * Cross tool or a right-button (on a phone, long-press) drag.
   */
  crossDrag: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
/** The all-pearls loop must be uniquely solvable before pearls are removed: 15×15 Tricky takes ~1 s. */
const MAX_SIDE = 15;
/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it at the gentlest setting the Type menu
 * offers at that size, and goes up the ladder when they want to.
 */
const DEFAULTS: PearlParams = { w: 8, h: 8, difficulty: DIFF_EASY, nosolve: false };
const PART_RE = /^([LNRFM])(\d+),(\d+),(\d+)$/;

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

function makeState(
  w: number,
  h: number,
  clues: Uint8Array,
  lines: Uint8Array,
  marks: Uint8Array,
  prev?: PearlState,
): PearlState {
  const check = checkGrid(w, h, clues, lines);
  return {
    w,
    h,
    clues,
    lines,
    marks,
    errors: check.errors,
    completed: check.complete || (prev?.completed ?? false),
    usedSolve: prev?.usedSolve ?? false,
  };
}

/**
 * The move that toggles the segment (or the mark) between (x, y) and its neighbour in
 * direction `d`, or `''` when it would run off the grid or cross a mark/line.
 */
function toggleMove(state: PearlState, x: number, y: number, d: number, mark: boolean): string {
  const { w, h } = state;
  const x2 = x + dx(d);
  const y2 = y + dy(d);
  if (x < 0 || y < 0 || x >= w || y >= h || x2 < 0 || y2 < 0 || x2 >= w || y2 >= h) return '';
  const d2 = flip(d);
  const a = y * w + x;
  const b = y2 * w + x2;
  const other = mark ? state.lines : state.marks;
  if (other[a] & d || other[b] & d2) return '';
  const c = mark ? 'M' : 'F';
  return `${c}${d},${x},${y};${c}${d2},${x2},${y2}`;
}

/**
 * Extend the drag path to square (gx, gy): back to an earlier square truncates the
 * path there; a rook move from the last square walks towards it, stopping at marks.
 */
function extendDrag(state: PearlState, ui: PearlUI, gx: number, gy: number): void {
  const { w, h } = state;
  if (gx < 0 || gy < 0 || gx >= w || gy >= h || !ui.pressed) return;
  const pos = gy * w + gx;
  const last = ui.drag[ui.drag.length - 1];
  if (pos === last) return;
  ui.dragging = true;
  let ox = last % w;
  let oy = Math.floor(last / w);
  if (ox !== gx && oy !== gy) {
    // Diagonal: only a return to a square already on the path means anything (it
    // truncates there); otherwise wait for the pointer to come back in line.
    const seen = ui.drag.indexOf(pos);
    if (seen >= 0) ui.drag.length = seen + 1;
    return;
  }
  const sx = Math.sign(gx - ox);
  const sy = Math.sign(gy - oy);
  const dir = sy > 0 ? D : sy < 0 ? U : sx > 0 ? R : L;
  // One square at a time, exactly as a slow drag would go: a fast pointer that jumps
  // several squares in one sample must not run the path through a square twice (a
  // square crossed again, or an edge laid twice that then cancels itself out).
  while (ox !== gx || oy !== gy) {
    if (!ui.crossDrag && state.marks[oy * w + ox] & dir) break;
    ox += sx;
    oy += sy;
    stepDrag(ui.drag, oy * w + ox);
  }
}

/**
 * Take the drag one square further, to the neighbouring square `pos`. Back onto a square
 * already on the path truncates it there — except the square the drag started from,
 * which closes the loop: tracing a whole loop in one stroke is the most natural thing to
 * do, and truncating there threw the entire stroke away just as it was finished.
 */
function stepDrag(drag: number[], pos: number): void {
  const seen = drag.indexOf(pos);
  if (seen === 0 && drag.length >= 4 && drag[drag.length - 1] !== drag[0]) drag.push(pos);
  else if (seen >= 0) drag.length = seen + 1;
  else drag.push(pos);
}

/**
 * What the drag path would do to each edge it crosses: segments already present are
 * removed until the path reaches an edge without one, after which every edge gets a
 * segment. Returns [fromSquare, dir, toSquare] for each edge that changes.
 */
function dragChanges(state: PearlState, path: number[]): [number, number, number][] {
  const w = state.w;
  const out: [number, number, number][] = [];
  let clearing = true;
  for (let i = 0; i + 1 < path.length; i++) {
    const a = path[i];
    const b = path[i + 1];
    const ax = a % w;
    const ay = Math.floor(a / w);
    const bx = b % w;
    const by = Math.floor(b / w);
    const dir = by > ay ? D : by < ay ? U : bx > ax ? R : L;
    const has = (state.lines[a] & dir) !== 0;
    if (!has) clearing = false;
    if (has === clearing) out.push([a, dir, b]);
  }
  return out;
}

/** Whether the edge from square `a` in direction `dir` carries a cross on either side. */
function hasMark(state: PearlState, a: number, dir: number, b: number): boolean {
  return (state.marks[a] & dir) !== 0 || (state.marks[b] & flip(dir)) !== 0;
}

/**
 * What a drag with the Cross tool would do to each edge it crosses, by the same rule as
 * {@link dragChanges}: crosses already there are lifted until the path reaches an edge
 * without one, after which every edge gets a cross. Edges that carry a segment are
 * passed over, since a cross cannot sit on the loop.
 */
function markChanges(state: PearlState, path: number[]): [number, number, number][] {
  const w = state.w;
  const out: [number, number, number][] = [];
  let clearing = true;
  for (let i = 0; i + 1 < path.length; i++) {
    const a = path[i];
    const b = path[i + 1];
    const ax = a % w;
    const ay = Math.floor(a / w);
    const bx = b % w;
    const by = Math.floor(b / w);
    const dir = by > ay ? D : by < ay ? U : bx > ax ? R : L;
    if (state.lines[a] & dir || state.lines[b] & flip(dir)) continue;
    const has = hasMark(state, a, dir, b);
    if (!has) clearing = false;
    if (has === clearing) out.push([a, dir, b]);
  }
  return out;
}

function solutionOf(state: PearlState, aux: string | undefined): Uint8Array | null {
  const { w, h, clues } = state;
  if (aux !== undefined) {
    const lines = decodeLines(aux, w * h);
    if (lines && checkGrid(w, h, clues, lines).complete) return lines;
  }
  const work = new Work(w, h, clues);
  const r = solveWithGuessing(work);
  if (r === SOLVE_IMPOSSIBLE) throw new Error(tx`This puzzle is not self-consistent`);
  if (r !== SOLVE_SOLVED) throw new Error(tx`Unable to find a solution to this puzzle`);
  return work.lines();
}

// ------------------------------------------------------------------ drawing

/**
 * Trace the drawn segments into polylines through square centres and edge midpoints,
 * breaking where the colour changes, so corners get proper round joins. Each segment
 * half (centre to edge midpoint) is one graph edge; a path continues through nodes of
 * degree two only.
 */
function traceLoops(
  state: PearlState,
  colourOf: (sq: number, d: number) => string,
): { points: number[]; colour: string; closed: boolean }[] {
  const { w, h, lines } = state;
  const inGrid = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h;
  const half = (sq: number, d: number) => sq * 16 + d;
  const visited = new Set<number>();
  const out: { points: number[]; colour: string; closed: boolean }[] = [];
  const centre = (sq: number): [number, number] => [(sq % w) + 0.5, Math.floor(sq / w) + 0.5];
  const mid = (sq: number, d: number): [number, number] => [
    (sq % w) + 0.5 + dx(d) / 2,
    Math.floor(sq / w) + 0.5 + dy(d) / 2,
  ];
  const neighbour = (sq: number, d: number): number => {
    const x = (sq % w) + dx(d);
    const y = Math.floor(sq / w) + dy(d);
    return inGrid(x, y) ? y * w + x : -1;
  };
  /** The other direction of a two-segment square, or 0. */
  const otherDir = (sq: number, d: number): number =>
    bitCount(lines[sq]) === 2 ? lines[sq] & ~d : 0;

  for (let sq = 0; sq < w * h; sq++) {
    for (const d of DIRS) {
      if (!(lines[sq] & d) || visited.has(half(sq, d))) continue;
      const colour = colourOf(sq, d);
      visited.add(half(sq, d));
      const pts: [number, number][] = [centre(sq), mid(sq, d)];
      let closed = false;
      // Forward: through the edge midpoint into the neighbour, then on through it.
      let cur = sq;
      let dir: number = d;
      for (;;) {
        const nb = neighbour(cur, dir);
        if (nb < 0 || !(lines[nb] & flip(dir))) break;
        const back = flip(dir);
        if (visited.has(half(nb, back))) {
          if (nb === sq && back === d) closed = true;
          break;
        }
        if (colourOf(nb, back) !== colour) break;
        visited.add(half(nb, back));
        pts.push(centre(nb));
        const next = otherDir(nb, back);
        if (!next || visited.has(half(nb, next))) {
          if (next && nb === sq && next === d) closed = true;
          break;
        }
        if (colourOf(nb, next) !== colour) break;
        visited.add(half(nb, next));
        pts.push(mid(nb, next));
        cur = nb;
        dir = next;
      }
      if (!closed) {
        // Backward from the starting square's centre.
        const rev: [number, number][] = [];
        cur = sq;
        dir = d;
        for (;;) {
          const next = otherDir(cur, dir);
          if (!next || visited.has(half(cur, next)) || colourOf(cur, next) !== colour) break;
          visited.add(half(cur, next));
          rev.push(mid(cur, next));
          const nb = neighbour(cur, next);
          if (nb < 0 || !(lines[nb] & flip(next))) break;
          const back = flip(next);
          if (visited.has(half(nb, back)) || colourOf(nb, back) !== colour) break;
          visited.add(half(nb, back));
          rev.push(centre(nb));
          cur = nb;
          dir = back;
        }
        rev.reverse();
        pts.unshift(...rev);
      } else {
        pts.pop(); // the closing point repeats the first one
      }
      out.push({ points: pts.flat(), colour, closed });
    }
  }
  return out;
}

const game = defineGame<PearlParams, PearlState, PearlUI>({
  id: 'pearl',
  name: 'Pearl',
  description:
    'Draw a single closed loop that runs straight through white pearls and turns at black ones.',
  alsoKnownAs: 'Masyu',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [6, 6, DIFF_EASY],
      [6, 6, DIFF_TRICKY],
      [8, 8, DIFF_EASY],
      [8, 8, DIFF_TRICKY],
      [10, 10, DIFF_EASY],
      [10, 10, DIFF_TRICKY],
      [12, 8, DIFF_EASY],
      [12, 8, DIFF_TRICKY],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, difficulty, nosolve: false },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${full ? `d${DIFFICULTY_CHARS[p.difficulty] ?? 'e'}${p.nosolve ? 'n' : ''}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?(n)?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    const d = m[3] ? DIFFICULTY_CHARS.indexOf(m[3]) : -1;
    return { w, h, difficulty: d >= 0 ? d : DIFF_EASY, nosolve: m[4] === 'n' };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 5) return tx`Width must be at least five`;
    if (p.h < 5) return tx`Height must be at least five`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
      { type: 'boolean', name: 'Allow unsoluble', value: p.nosolve },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    const int = (s: string) => (/^-?\d+$/.test(s) ? parseInt(s, 10) : NaN);
    return {
      w: int(str(0)),
      h: int(str(1)),
      difficulty: (items[2] as { selected: number }).selected,
      nosolve: (items[3] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const clues = parseDesc(desc, p.w, p.h) as Uint8Array;
    const n = p.w * p.h;
    return {
      ...makeState(p.w, p.h, clues, new Uint8Array(n), new Uint8Array(n)),
      completed: false,
    };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const soln = solutionOf(curr, aux)!;
    const { w, h } = curr;
    let move = 'S';
    for (let i = 0; i < w * h; i++) {
      if (curr.lines[i] !== soln[i]) move += `;R${soln[i]},${i % w},${Math.floor(i / w)}`;
    }
    return move;
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      let below = '';
      for (let x = 0; x < s.w; x++) {
        const i = y * s.w + x;
        const c = s.clues[i];
        const l = s.lines[i];
        row += c === CORNER ? 'B' : c === STRAIGHT ? 'W' : l ? '+' : '.';
        if (x < s.w - 1) row += l & R ? '-' : ' ';
        below += l & D ? '|' : ' ';
        if (x < s.w - 1) below += ' ';
      }
      rows.push(row);
      if (y < s.h - 1) rows.push(below);
    }
    return rows.join('\n');
  },

  newUI: () => ({
    drag: [],
    pressed: false,
    dragging: false,
    clickX: 0,
    clickY: 0,
    cx: 0,
    cy: 0,
    cursorVisible: false,
    crossMode: false,
    crossDrag: false,
  }),
  changedState(ui, _old, next) {
    // The board changed under a drag still in progress (a keyboard drag across Undo,
    // Restart or Solve): drop it, or its ghost stays on the new board and the next Enter
    // lays it there — even across a loop the computer has just drawn.
    ui.pressed = false;
    ui.dragging = false;
    ui.drag = [];
    if (next.completed) ui.cursorVisible = false;
  },

  actions: [
    {
      label: 'Cross',
      key: 'X',
      hud: true,
      glyph: CROSS_GLYPH,
      pressed: (_s, ui) => ui.crossMode,
      title: 'Click or drag to cross off edges the loop cannot use (X)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h } = state;
    const t = ds.tileSize;
    const bd = boardBorder(t);
    const gx = Math.floor((mx - bd) / t);
    const gy = Math.floor((my - bd) / t);
    const inGrid = gx >= 0 && gy >= 0 && gx < w && gy < h;
    let release = false;

    if (isMouseDown(b)) {
      const hadCursor = ui.cursorVisible;
      ui.cursorVisible = false;
      ui.pressed = false;
      ui.dragging = false;
      ui.drag = [];
      if (!inGrid) return hadCursor ? '' : null;
      ui.clickX = mx;
      ui.clickY = my;
      ui.drag = [gy * w + gx];
      ui.pressed = true;
      ui.crossDrag = ui.crossMode || b === RIGHT_BUTTON;
      return '';
    }
    if (b === LEFT_DRAG || b === RIGHT_DRAG) {
      if (!ui.pressed) return null;
      extendDrag(state, ui, gx, gy);
      return '';
    }
    if (isMouseRelease(b)) {
      if (!ui.pressed) return null;
      release = true;
    }

    if (b === 'x'.charCodeAt(0) || b === 'X'.charCodeAt(0)) {
      ui.crossMode = !ui.crossMode;
      return '';
    }
    if (isCursorMove(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const dir = b === 0x0209 ? U : b === 0x020a ? D : b === 0x020b ? L : R;
      if (button & (MOD_SHFT | MOD_CTRL)) {
        // Ctrl+arrow draws a segment, Shift+arrow a cross, on the edge in that direction.
        if (ui.dragging) return null;
        ui.pressed = false;
        ui.drag = [];
        return toggleMove(state, ui.cx, ui.cy, dir, (button & MOD_SHFT) !== 0);
      }
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      if (ui.pressed) extendDrag(state, ui, ui.cx, ui.cy);
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      if (b === CURSOR_SELECT) {
        if (!ui.pressed) {
          // Enter starts a keyboard drag from the cursor; Enter again finishes it.
          ui.pressed = true;
          ui.dragging = false;
          ui.crossDrag = ui.crossMode;
          ui.drag = [ui.cy * w + ui.cx];
          ui.clickX = bd + ui.cx * t + t / 2;
          ui.clickY = bd + ui.cy * t + t / 2;
          return '';
        }
        release = true;
      } else if (b === CURSOR_SELECT2) {
        if (!ui.pressed) return null;
        ui.pressed = false;
        ui.dragging = false;
        ui.drag = [];
        return '';
      }
    }

    if (release) {
      const path = ui.drag;
      const wasDrag = ui.dragging;
      ui.pressed = false;
      ui.dragging = false;
      ui.drag = [];
      if (wasDrag) {
        const parts: string[] = [];
        const c = ui.crossDrag ? 'M' : 'F';
        const changes = ui.crossDrag ? markChanges(state, path) : dragChanges(state, path);
        for (const [a, dir, o] of changes) {
          parts.push(
            `${c}${dir},${a % w},${Math.floor(a / w)};${c}${flip(dir)},${o % w},${Math.floor(o / w)}`,
          );
        }
        return parts.join(';');
      }
      // A click: the edge of the pressed square nearest to the press position.
      const sx = Math.floor((ui.clickX - bd) / t);
      const sy = Math.floor((ui.clickY - bd) / t);
      if (sx < 0 || sy < 0 || sx >= w || sy >= h) return '';
      const cx = bd + sx * t + t / 2;
      const cy = bd + sy * t + t / 2;
      const ox = ui.clickX - cx;
      const oy = ui.clickY - cy;
      if (Math.max(Math.abs(ox), Math.abs(oy)) < t / 4) return '';
      const dir = Math.abs(ox) < Math.abs(oy) ? (oy < 0 ? U : D) : ox < 0 ? L : R;
      // Only the left button draws, as in the original: a middle click (a two-finger tap
      // on a phone, which is also what a pinch that never got going ends as) crosses.
      const mark = ui.crossMode || (isMouseRelease(b) && b !== LEFT_RELEASE);
      return toggleMove(state, sx, sy, dir, mark);
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h } = state;
    const lines = state.lines.slice();
    const marks = state.marks.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = PART_RE.exec(part);
      if (!m) return null;
      const l = parseInt(m[2], 10);
      const x = parseInt(m[3], 10);
      const y = parseInt(m[4], 10);
      if (l > 15 || x >= w || y >= h) return null;
      const i = y * w + x;
      switch (m[1]) {
        case 'L':
          lines[i] |= l;
          break;
        case 'N':
          lines[i] &= ~l;
          break;
        case 'R':
          lines[i] = l;
          marks[i] &= ~l;
          break;
        case 'F':
          lines[i] ^= l;
          break;
        default:
          marks[i] ^= l;
      }
      // A line and a mark on the same edge is never a valid move.
      if (lines[i] & marks[i] & l) return null;
    }
    return { ...makeState(w, h, state.clues, lines, marks, state), usedSolve };
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, h, clues, lines, marks, errors } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const px = (x: number) => b + x * t;
    const inkColour = flash ? 'ok' : 'ink';

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(px(x), b, px(x), b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, px(y), b + w * t, px(y), 'faint', 1.2);

    if (ui.cursorVisible) {
      const inset = t * 0.08;
      dr.cursor(px(ui.cx) + inset, px(ui.cy) + inset, t - 2 * inset, t - 2 * inset);
    }

    // "No line" crosses on edge midpoints (either side may carry the mark).
    const ms = Math.max(2, t * 0.09);
    const mw = Math.max(1.2, t * 0.04);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (x + 1 < w && (marks[i] & R || marks[i + 1] & L))
          dr.cross(px(x + 1), px(y) + t / 2, ms, 'pencil', mw, { seed: i });
        if (y + 1 < h && (marks[i] & D || marks[i + w] & U))
          dr.cross(px(x) + t / 2, px(y + 1), ms, 'pencil', mw, { seed: i + 1 });
      }
    }

    // The loop so far, as continuous strokes; erroneous halves in red.
    const lw = Math.max(3, t * 0.13);
    const colourOf = (sq: number, d: number) => (errors[sq] & d ? 'error' : inkColour);
    // A segment the player has just drawn is held out of the traced loop and drawn
    // separately, growing from the middle of the edge it spans; one they have rubbed out
    // retreats the same way. The rest of the loop is traced from a board with those
    // segments masked off, so the strokes stay continuous either side of the join.
    const moved = oldState ? changedAt(oldState.lines, lines) : null;
    const grow = drawGrow(animTime);
    let traced = state;
    if (moved) {
      const settled = lines.slice();
      for (const i of moved) settled[i] = lines[i] & oldState!.lines[i];
      traced = { ...state, lines: settled };
    }
    for (const path of traceLoops(traced, colourOf)) {
      const pts = path.points.map((v) => b + v * t);
      if (path.closed) dr.polygon(pts, null, path.colour, { width: lw });
      else dr.polyline(pts, path.colour, lw);
    }
    // …and the segments still travelling, each drawn once from the square that owns its
    // right or down edge.
    if (moved) {
      for (const i of moved) {
        const x = i % w;
        const y = (i - x) / w;
        for (const d of [R, D]) {
          const j = d === R ? i + 1 : i + w;
          if (d === R ? x + 1 >= w : y + 1 >= h) continue;
          const before = (oldState!.lines[i] & d) !== 0;
          const after = (lines[i] & d) !== 0;
          if (before === after) continue;
          const g = after ? grow : 1 - grow;
          if (g <= 0) continue;
          const ax = px(x) + t / 2;
          const ay = px(y) + t / 2;
          const bx = px(j % w) + t / 2;
          const by = px((j - (j % w)) / w) + t / 2;
          const e = growSegment(ax, ay, bx, by, g);
          dr.line(e.x1, e.y1, e.x2, e.y2, colourOf(i, d), lw);
        }
      }
    }

    // Stubs leading off the grid (only reachable through hand-written moves).
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        for (const d of DIRS) {
          if (!(lines[i] & d)) continue;
          const nx = x + dx(d);
          const ny = y + dy(d);
          if (nx >= 0 && ny >= 0 && nx < w && ny < h) continue;
          const cx = px(x) + t / 2;
          const cy = px(y) + t / 2;
          dr.line(cx, cy, cx + (dx(d) * t) / 2, cy + (dy(d) * t) / 2, colourOf(i, d), lw);
        }
      }
    }

    // Drag preview: segments about to appear in accent, ones about to go faded out and
    // dashed. Opaque strokes, so overlapping round caps leave no dots at the joins.
    if (ui.dragging && ui.crossDrag) {
      // With the Cross tool: crosses about to appear in accent, ones about to go faded.
      for (const [a, dir, c] of markChanges(state, ui.drag)) {
        const mx = (px(a % w) + px(c % w)) / 2 + t / 2;
        const my = (px(Math.floor(a / w)) + px(Math.floor(c / w))) / 2 + t / 2;
        const removing = hasMark(state, a, dir, c);
        dr.cross(mx, my, ms * 1.3, removing ? 'lowlight' : 'accent', mw * 1.4, { seed: a });
      }
    } else if (ui.dragging) {
      for (const [a, dir, c] of dragChanges(state, ui.drag)) {
        const ax = px(a % w) + t / 2;
        const ay = px(Math.floor(a / w)) + t / 2;
        const cx = px(c % w) + t / 2;
        const cy = px(Math.floor(c / w)) + t / 2;
        const removing = (lines[a] & dir) !== 0;
        dr.line(ax, ay, cx, cy, removing ? 'lowlight' : 'accent', lw, { rough: 0 });
        if (removing) dr.line(ax, ay, cx, cy, 'pencil', Math.max(1, lw * 0.3), { dash: [4, 4] });
      }
    }

    // Pearls: black ones filled with ink, white ones with paper; a broken rule gets a
    // red halo behind the pearl.
    const r = t * 0.26;
    const outline = Math.max(1.6, t * 0.05);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const c = clues[i];
        if (c === NOCLUE) continue;
        const cx = px(x) + t / 2;
        const cy = px(y) + t / 2;
        const bad = (errors[i] & ERROR_CLUE) !== 0;
        if (bad) dr.circle(cx, cy, r * 1.45, 'error', null, { seed: i });
        dr.circle(cx, cy, r, c === CORNER ? inkColour : 'paper', inkColour, {
          width: outline,
          seed: i,
        });
      }
    }

    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });
  },

  animLength(oldState, newState) {
    return changedAt(oldState.lines, newState.lines) ? DRAW_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,

  // Just over half of the loop of the puzzle the menu renders (seed `thumbnail:pearl`,
  // 6×6 Easy), so the preview shows a partly drawn loop. A unit test keeps this in step
  // with the generator.
  thumbnailMoves: [
    'F1,1,0;F4,2,0;F8,2,0;F2,2,1;F1,2,1;F4,3,1;F1,3,1;F4,4,1;F1,4,1;F4,5,1;F8,5,1;F2,5,2;F8,5,2;F2,5,3;F8,5,3;F2,5,4;F8,5,4;F2,5,5;F4,5,5;F1,4,5;F4,4,5;F1,3,5;F4,3,5;F1,2,5;F2,2,5;F8,2,4;F1,2,4;F4,3,4;F1,3,4;F4,4,4;F2,4,4;F8,4,3',
  ],
});

export default game;

