/**
 * How the per-game keys are derived. Kept in one place because both the runtime and the
 * `scripts/i18n-extract.mjs` generator have to agree on them exactly, and a unit test
 * checks that `en.json` still lines up with the game definitions.
 */

/**
 * Turn a piece of English display text into a stable key segment:
 * `"No. of balls"` → `no_of_balls`, `"3×3"` → `3x3`, `"9x9 Basic"` → `9x9_basic`.
 *
 * Content-derived rather than positional, so reordering a game's presets or config rows
 * does not silently repoint every translation at the wrong string.
 */
export function keySegment(text: string): string {
  const folded = text
    .toLowerCase()
    .replace(/[×✕✖]/g, 'x')
    .replace(/[…]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return folded || 'unnamed';
}

export function gameNameKey(slug: string): string {
  return `games.${slug}.name`;
}

export function gameDescriptionKey(slug: string): string {
  return `games.${slug}.description`;
}

/** The familiar names the puzzle also goes by ("Sudoku", "Nonogram, Picross"). */
export function gameAlsoKnownAsKey(slug: string): string {
  return `games.${slug}.alsoKnownAs`;
}

export function presetKey(slug: string, name: string): string {
  return `games.${slug}.preset.${keySegment(name)}`;
}

export function configKey(slug: string, name: string): string {
  return `games.${slug}.config.${keySegment(name)}.name`;
}

/** One option of a `choices` row, e.g. a difficulty name. */
export function configChoiceKey(slug: string, name: string, choice: string): string {
  return `games.${slug}.config.${keySegment(name)}.choice.${keySegment(choice)}`;
}

export function actionLabelKey(slug: string, id: string): string {
  return `games.${slug}.action.${keySegment(id)}.label`;
}

export function actionTitleKey(slug: string, id: string): string {
  return `games.${slug}.action.${keySegment(id)}.title`;
}

export function keypadLabelKey(slug: string, ch: string): string {
  return `games.${slug}.keypad.${keySegment(ch)}`;
}

/** `index` is the step's position in the authored list, 1-based and before filtering. */
export function tutorialStepKey(slug: string, index: number, touch = false): string {
  return `tutorials.${slug}.step${index + 1}.${touch ? 'textTouch' : 'text'}`;
}

/** A game's own achievement (`Game.achievements`), by its `id`. */
export function achievementKey(slug: string, id: string, field: 'name' | 'description'): string {
  return `games.${slug}.achievement.${keySegment(id)}.${field}`;
}
