/**
 * Solo: region structures and the game-description codec.
 *
 * A Solo grid is `cr` × `cr` squares. Squares are numbered row-major, and a
 * {@link BlockStructure} says which region (sudoku block or killer cage) each square is
 * in. Regular puzzles have `c` columns of blocks by `r` rows of blocks, so every block is
 * `r` squares wide and `c` squares tall; jigsaw puzzles have `cr` arbitrary connected
 * blocks of `cr` squares each; killer cages are small connected groups of 2..cr squares.
 *
 * Descriptions follow the original collection exactly:
 *   grid[,blocks][,cages,sums]
 * where a grid is run-length encoded (letters a–z are runs of 1–26 empty squares,
 * numbers are decimal, `_` separates two adjacent numbers) and a region structure lists
 * the internal grid edges — first the vertical ones in reading order, then the horizontal
 * ones column by column — as the number of non-dividing edges between dividing ones
 * (`_` = 0, a–y = 1–25, z = 26 with no dividing edge following).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export class BlockStructure {
  readonly cr: number;
  readonly area: number;
  /** Largest region size (cr for sudoku blocks and killer cages). */
  readonly maxSquares: number;
  /** Region index of each square, -1 when it belongs to none. */
  whichblock: Int32Array;
  /** Squares of each region, in increasing order. */
  blocks: number[][];

  constructor(cr: number, maxSquares: number, whichblock?: Int32Array, blocks?: number[][]) {
    this.cr = cr;
    this.area = cr * cr;
    this.maxSquares = maxSquares;
    this.whichblock = whichblock ?? new Int32Array(this.area).fill(-1);
    this.blocks = blocks ?? [];
  }

  get nrBlocks(): number {
    return this.blocks.length;
  }

  /** The ordinary sudoku layout: `c` columns of blocks, each `r` wide and `c` tall. */
  static regular(c: number, r: number): BlockStructure {
    const cr = c * r;
    const owners = new Int32Array(cr * cr);
    for (let y = 0; y < cr; y++)
      for (let x = 0; x < cr; x++) owners[y * cr + x] = Math.floor(y / c) * c + Math.floor(x / r);
    return BlockStructure.fromOwners(cr, owners, cr);
  }

  /** Build from any labelling of the squares; regions are numbered by first appearance. */
  static fromOwners(cr: number, owners: ArrayLike<number>, maxSquares: number): BlockStructure {
    const area = cr * cr;
    const which = new Int32Array(area);
    const index = new Map<number, number>();
    const blocks: number[][] = [];
    for (let i = 0; i < area; i++) {
      const o = owners[i];
      let b = index.get(o);
      if (b === undefined) {
        b = blocks.length;
        index.set(o, b);
        blocks.push([]);
      }
      which[i] = b;
      blocks[b].push(i);
    }
    return new BlockStructure(cr, maxSquares, which, blocks);
  }

  clone(): BlockStructure {
    return new BlockStructure(
      this.cr,
      this.maxSquares,
      this.whichblock.slice(),
      this.blocks.map((b) => b.slice()),
    );
  }

  /** Merge two regions; the lower index survives and the last region fills the gap. */
  merge(a: number, b: number): void {
    const n1 = Math.min(a, b);
    const n2 = Math.max(a, b);
    for (const s of this.blocks[n2]) this.whichblock[s] = n1;
    this.blocks[n1] = this.blocks[n1].concat(this.blocks[n2]).sort((p, q) => p - q);
    const last = this.blocks.length - 1;
    if (n2 !== last) {
      this.blocks[n2] = this.blocks[last];
      for (const s of this.blocks[n2]) this.whichblock[s] = n2;
    }
    this.blocks.pop();
  }

  /** Whether squares `a` and `b` are in the same region. */
  same(a: number, b: number): boolean {
    return this.whichblock[a] === this.whichblock[b];
  }
}

// ------------------------------------------------------------------ grid codec

/** Run-length encode a grid of digits (0 = empty). */
export function encodeGrid(grid: ArrayLike<number>): string {
  const area = grid.length;
  let out = '';
  let run = 0;
  for (let i = 0; i <= area; i++) {
    const n = i < area ? grid[i] : -1;
    if (n === 0) {
      run++;
      continue;
    }
    if (run) {
      while (run > 0) {
        const k = Math.min(run, 26);
        out += String.fromCharCode(96 + k);
        run -= k;
      }
    } else if (out.length && n > 0) {
      out += '_';
    }
    if (n > 0) out += String(n);
    run = 0;
  }
  return out;
}

/**
 * Check a grid specification: `range` is the largest allowed number. Returns an error
 * message or null.
 */
export function validateGridSpec(spec: string, range: number, area: number): string | null {
  let squares = 0;
  let p = 0;
  while (p < spec.length) {
    const ch = spec[p];
    if (ch >= 'a' && ch <= 'z') {
      squares += ch.charCodeAt(0) - 96;
      p++;
    } else if (ch === '_') {
      p++;
    } else if (ch >= '1' && ch <= '9') {
      let q = p;
      while (q < spec.length && spec[q] >= '0' && spec[q] <= '9') q++;
      const val = parseInt(spec.slice(p, q), 10);
      if (val < 1 || val > range) return tx`Out-of-range number in game description`;
      squares++;
      p = q;
    } else {
      return tx`Invalid character in game description`;
    }
  }
  if (squares < area) return tx`Not enough data to fill grid`;
  if (squares > area) return tx`Too much data to fit in grid`;
  return null;
}

/** Decode a grid specification that has already been validated. */
export function decodeGrid(spec: string, area: number): Uint8Array {
  const grid = new Uint8Array(area);
  let i = 0;
  let p = 0;
  while (p < spec.length) {
    const ch = spec[p];
    if (ch >= 'a' && ch <= 'z') {
      i += ch.charCodeAt(0) - 96;
      p++;
    } else if (ch === '_') {
      p++;
    } else {
      let q = p;
      while (q < spec.length && spec[q] >= '0' && spec[q] <= '9') q++;
      grid[i++] = parseInt(spec.slice(p, q), 10);
      p = q;
    }
  }
  return grid;
}

// --------------------------------------------------------------- region codec

/** The two squares either side of internal edge number `pos`. */
function edgeSquares(pos: number, cr: number): [number, number] {
  const vertical = cr * (cr - 1);
  if (pos < vertical) {
    const y = Math.floor(pos / (cr - 1));
    const x = pos % (cr - 1);
    return [y * cr + x, y * cr + x + 1];
  }
  const x = Math.floor(pos / (cr - 1)) - cr;
  const y = pos % (cr - 1);
  return [y * cr + x, (y + 1) * cr + x];
}

/** Encode the dividing lines of a region structure. */
export function encodeBlocks(b: BlockStructure): string {
  const cr = b.cr;
  const total = 2 * cr * (cr - 1);
  let out = '';
  let run = 0;
  for (let i = 0; i <= total; i++) {
    let edge = true;
    if (i < total) {
      const [p0, p1] = edgeSquares(i, cr);
      edge = b.whichblock[p0] !== b.whichblock[p1];
    }
    if (!edge) {
      run++;
      continue;
    }
    while (run >= 26) {
      out += 'z';
      run -= 26;
    }
    out += run ? String.fromCharCode(96 + run) : '_';
    run = 0;
  }
  return out;
}

/**
 * Parse a region specification into a labelling of the squares (the canonical square of
 * each connected group). Returns an error message when the text is malformed.
 */
export function parseBlockSpec(spec: string, cr: number): Int32Array | string {
  const area = cr * cr;
  const total = 2 * cr * (cr - 1);
  const dsf = new DSF(area);
  let pos = 0;
  for (const ch of spec) {
    let c: number;
    if (ch === '_') c = 0;
    else if (ch >= 'a' && ch <= 'z') c = ch.charCodeAt(0) - 96;
    else return tx`Invalid character in block structure specification`;
    const advance = c !== 26;
    while (c-- > 0) {
      if (pos >= total) return tx`Too much data in block structure specification`;
      const [p0, p1] = edgeSquares(pos, cr);
      dsf.merge(p0, p1);
      pos++;
    }
    if (advance) pos++;
  }
  if (pos > total + 1) return tx`Too much data in block structure specification`;
  if (pos < total + 1) return tx`Not enough data in block structure specification`;
  const owners = new Int32Array(area);
  for (let i = 0; i < area; i++) owners[i] = dsf.find(i);
  return owners;
}

/**
 * Parse and check a region specification: there must be between `minBlocks` and
 * `maxBlocks` regions, each of `minSize`..`maxSize` squares.
 */
export function decodeBlocks(
  spec: string,
  cr: number,
  minBlocks: number,
  maxBlocks: number,
  minSize: number,
  maxSize: number,
  kind: 'jigsaw' | 'killer',
): BlockStructure | string {
  const owners = parseBlockSpec(spec, cr);
  if (typeof owners === 'string') return owners;
  const b = BlockStructure.fromOwners(cr, owners, maxSize);
  // One literal per kind rather than the kind spliced in: a translator needs the whole
  // sentence, and "block" and "cage" differ in gender and plural across languages.
  const jigsaw = kind === 'jigsaw';
  if (b.nrBlocks > maxBlocks)
    return jigsaw ? tx`Too many jigsaw blocks` : tx`Too many killer cages`;
  if (b.nrBlocks < minBlocks)
    return jigsaw ? tx`Not enough jigsaw blocks` : tx`Not enough killer cages`;
  for (const squares of b.blocks) {
    if (squares.length > maxSize)
      return jigsaw ? tx`A jigsaw block is too big` : tx`A killer cage is too big`;
    if (squares.length < minSize)
      return jigsaw ? tx`A jigsaw block is too small` : tx`A killer cage is too small`;
  }
  return b;
}

// ------------------------------------------------------------- whole descriptions

export interface ParsedDesc {
  grid: Uint8Array;
  blocks: BlockStructure;
  kblocks: BlockStructure | null;
  kgrid: Uint8Array | null;
}

/**
 * Validate and parse a full game description for the given shape. Returns an error
 * message when it is not acceptable.
 */
export function parseDesc(
  c: number,
  r: number,
  killer: boolean,
  desc: string,
): ParsedDesc | string {
  const cr = c * r;
  const area = cr * cr;
  const parts = desc.split(',');
  let idx = 0;

  const gridErr = validateGridSpec(parts[idx], cr, area);
  if (gridErr) return gridErr;
  const grid = decodeGrid(parts[idx++], area);

  let blocks: BlockStructure;
  if (r === 1) {
    if (idx >= parts.length) return tx`Expected jigsaw block structure in game description`;
    const b = decodeBlocks(parts[idx++], cr, cr, cr, cr, cr, 'jigsaw');
    if (typeof b === 'string') return b;
    blocks = b;
  } else {
    blocks = BlockStructure.regular(c, r);
  }

  let kblocks: BlockStructure | null = null;
  let kgrid: Uint8Array | null = null;
  if (killer) {
    if (idx >= parts.length) return tx`Expected killer cage structure in game description`;
    const k = decodeBlocks(parts[idx++], cr, cr, area, 2, cr, 'killer');
    if (typeof k === 'string') return k;
    kblocks = k;
    if (idx >= parts.length) return tx`Expected killer clue grid in game description`;
    // A cage holds at most cr distinct digits, so no sum can pass 1 + 2 + … + cr. (The
    // sums are kept in bytes: anything larger would silently wrap round to another clue.)
    const kerr = validateGridSpec(parts[idx], (cr * (cr + 1)) / 2, area);
    if (kerr) return kerr;
    kgrid = decodeGrid(parts[idx++], area);
    // Every cage needs exactly one sum, so the solver and the display can rely on it.
    const clues = new Int32Array(kblocks.nrBlocks);
    for (let i = 0; i < area; i++) if (kgrid[i]) clues[kblocks.whichblock[i]]++;
    for (let b = 0; b < clues.length; b++)
      if (clues[b] !== 1) return tx`Every killer cage must have exactly one sum`;
  }
  if (idx < parts.length) return tx`Unexpected data at end of game description`;
  return { grid, blocks, kblocks, kgrid };
}

/** Encode a puzzle as a description string. */
export function encodeDesc(
  grid: ArrayLike<number>,
  blocks: BlockStructure,
  jigsaw: boolean,
  kblocks: BlockStructure | null,
  kgrid: ArrayLike<number> | null,
): string {
  let desc = encodeGrid(grid);
  if (jigsaw) desc += ',' + encodeBlocks(blocks);
  if (kblocks && kgrid) desc += ',' + encodeBlocks(kblocks) + ',' + encodeGrid(kgrid);
  return desc;
}

/** Sum clue of each cage: the one non-zero entry of `kgrid` inside it. */
export function cageClues(kblocks: BlockStructure, kgrid: Uint8Array): Int32Array {
  const clues = new Int32Array(kblocks.nrBlocks);
  for (let i = 0; i < kgrid.length; i++) if (kgrid[i]) clues[kblocks.whichblock[i]] = kgrid[i];
  return clues;
}
