import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  KEY_BACKSPACE,
  LEFT_BUTTON,
  MIDDLE_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  BLACK,
  EMPTY,
  WHITE,
  decodeSolution,
  findRuns,
  isComplete,
  matchingLines,
  overfullLines,
  parseDesc,
} from './board';
import { generate } from './generator';
import type { GenParams } from './generator';
import { DIFFICULTY_NAMES, DIFF_EASY, DIFF_NORMAL, findSolution } from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';
import { ERASE_GLYPH } from '../../framework/glyphs';

export type UnrulyParams = GenParams;

export interface UnrulyState {
  w: number;
  h: number;
  unique: boolean;
  /** `EMPTY`, `BLACK` or `WHITE` per cell. */
  grid: Uint8Array;
  /** 1 where the cell is a given clue. Shared between states. */
  given: Uint8Array;
  completed: boolean;
  usedSolve: boolean;
}

export interface UnrulyUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** The Erase tool: a left click clears a square, as a middle click does. */
  erase: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MIN_SIDE = 6;
const MAX_SIDE = 30;
/** Difficulty letters used in game IDs, indexed by difficulty. */
const DIFF_CHARS = 'en';
/**
 * Number of distinct Unruly rows of length 2n (OEIS A177790). In unique mode a grid of
 * width 2n cannot be taller than this, and vice versa.
 */
const DISTINCT_ROWS = [
  1, 2, 6, 14, 34, 84, 208, 518, 1296, 3254, 8196, 20700, 52404, 132942, 337878, 860142,
];
const DEFAULTS: UnrulyParams = { w: 8, h: 8, unique: false, difficulty: DIFF_EASY };

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

function makeState(
  w: number,
  h: number,
  unique: boolean,
  grid: Uint8Array,
  given: Uint8Array,
  usedSolve = false,
): UnrulyState {
  return { w, h, unique, grid, given, completed: isComplete(grid, w, h, unique), usedSolve };
}

const game = defineGame<UnrulyParams, UnrulyState, UnrulyUI>({
  id: 'unruly',
  name: 'Unruly',
  description:
    'Colour every square black or white with equal numbers in each line and never three in a row.',
  alsoKnownAs: 'Binairo, Takuzu',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [8, 8, DIFF_EASY],
      [8, 8, DIFF_NORMAL],
      [10, 10, DIFF_EASY],
      [10, 10, DIFF_NORMAL],
      [14, 14, DIFF_EASY],
      [14, 14, DIFF_NORMAL],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, unique: false, difficulty },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${p.unique ? 'u' : ''}${full ? `d${DIFF_CHARS[p.difficulty] ?? '?'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(u?)(?:d(.?))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    const unique = m[3] === 'u';
    let difficulty = DIFF_EASY;
    if (m[4] !== undefined) {
      const d = DIFF_CHARS.indexOf(m[4]);
      // An unknown letter is kept as an invalid difficulty so validateParams can say so.
      difficulty = m[4] === '' || d < 0 ? DIFFICULTY_NAMES.length : d;
    }
    return { w, h, unique, difficulty };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`Width, height and difficulty must be whole numbers`;
    if (p.w % 2 || p.h % 2) return tx`Width and height must both be even`;
    if (p.w < MIN_SIDE || p.h < MIN_SIDE) return tx`Width and height must be at least ${MIN_SIDE}`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.unique) {
      if (p.w / 2 < DISTINCT_ROWS.length && p.h > DISTINCT_ROWS[p.w / 2])
        return tx`Puzzle is too tall for unique-rows mode`;
      if (p.h / 2 < DISTINCT_ROWS.length && p.w > DISTINCT_ROWS[p.h / 2])
        return tx`Puzzle is too long for unique-rows mode`;
    }
    if (full && (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty rating`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'boolean', name: 'Unique rows and columns', value: p.unique },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      unique: !!(items[2] as { value: boolean }).value,
      difficulty: (items[3] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const r = parseDesc(desc, p.w, p.h) as { grid: Uint8Array; given: Uint8Array };
    const state = makeState(p.w, p.h, p.unique, r.grid, r.given);
    // A fresh puzzle is never "completed", however many clues it has.
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(orig, curr, aux) {
    const { w, h, unique } = curr;
    let solution: Uint8Array | null = null;
    if (aux !== undefined) {
      const g = decodeSolution(aux, w * h);
      if (g && isComplete(g, w, h, unique)) solution = g;
    }
    if (!solution) {
      // Solve from the clues alone, like the original, so a wrong entry cannot block it.
      const clues = orig.grid.map((c, i) => (orig.given[i] ? c : EMPTY));
      solution = findSolution(clues, w, h, unique);
    }
    if (!solution) throw new Error(tx`No solution found`);
    let move = 'S';
    for (let i = 0; i < w * h; i++) move += solution[i] === BLACK ? '1' : '0';
    return move;
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const row: string[] = [];
      for (let x = 0; x < s.w; x++) {
        const c = s.grid[y * s.w + x];
        row.push(c === BLACK ? '1' : c === WHITE ? '0' : '.');
      }
      rows.push(row.join(' '));
    }
    return rows.join('\n');
  },

  actions: [
    {
      label: 'Erase',
      key: 'E',
      hud: true,
      glyph: ERASE_GLYPH,
      pressed: (_s, ui) => ui.erase,
      title: 'Click a square to clear it (E)',
    },
  ],

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false, erase: false }),
  changedState(ui, _old, next) {
    if (next.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, grid, given } = state;
    const ch = keyChar(b);
    // Hiding a visible cursor is itself a change worth redrawing.
    let idle: string | null = null;
    let cx: number;
    let cy: number;
    if (ch === 'e' || ch === 'E') {
      ui.erase = !ui.erase;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || b === MIDDLE_BUTTON) {
      const t = ds.tileSize;
      const bd = boardBorder(t);
      cx = Math.floor((mx - bd) / t);
      cy = Math.floor((my - bd) / t);
      if (cx < 0 || cy < 0 || cx >= w || cy >= h) return null;
      if (ui.cursorVisible) idle = '';
      ui.cursorVisible = false;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (
      b === CURSOR_SELECT ||
      b === CURSOR_SELECT2 ||
      b === KEY_BACKSPACE ||
      ch === '0' ||
      ch === '1' ||
      ch === '2'
    ) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      cx = ui.cx;
      cy = ui.cy;
    } else {
      return null;
    }
    const i = cy * w + cx;
    if (given[i]) return idle;
    const cur = grid[i];
    let next: number;
    // Enter is a click, so the lit eraser rubs out under the cursor too.
    const erasing = (b === LEFT_BUTTON || b === CURSOR_SELECT) && ui.erase;
    if (b === MIDDLE_BUTTON || b === KEY_BACKSPACE || erasing) next = EMPTY;
    else if (ch === '0' || ch === '2') next = WHITE;
    else if (ch === '1') next = BLACK;
    else if (b === RIGHT_BUTTON || b === CURSOR_SELECT2)
      next = cur === EMPTY ? WHITE : cur === WHITE ? BLACK : EMPTY;
    else next = cur === EMPTY ? BLACK : cur === BLACK ? WHITE : EMPTY;
    if (next === cur) return idle;
    return `P${next === BLACK ? '1' : next === WHITE ? '0' : '-'},${cx},${cy}`;
  },

  executeMove(state, move) {
    const { w, h, unique, given } = state;
    const n = w * h;
    if (move[0] === 'S') {
      if (move.length !== n + 1 || !/^[01]+$/.test(move.slice(1))) return null;
      const grid = new Uint8Array(n);
      for (let i = 0; i < n; i++) grid[i] = move[i + 1] === '1' ? BLACK : WHITE;
      return makeState(w, h, unique, grid, given, true);
    }
    const m = /^P([-01]),(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    if (x >= w || y >= h) return null;
    const i = y * w + x;
    if (given[i]) return null;
    const v = m[1] === '1' ? BLACK : m[1] === '0' ? WHITE : EMPTY;
    // Setting the colour already there (or erasing an empty square): no undo step.
    if (state.grid[i] === v) return state;
    const grid = state.grid.slice();
    grid[i] = v;
    return makeState(w, h, unique, grid, given, state.usedSolve);
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, grid, given, unique } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const cellX = (x: number) => b + x * t;
    const cellY = (y: number) => b + y * t;

    dr.rect(b, b, w * t, h * t, 'paper');
    // Undecided cells are a pencil-grey wash, clearly darker than a white cell.
    const emptyFill = dr.mix('shade', 'lowlight', 0.4);
    // Cell fills first so the grid lines sit on top of the colour.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const c = grid[y * w + x];
        if (c === BLACK) continue;
        dr.rect(
          cellX(x),
          cellY(y),
          t,
          t,
          c === WHITE ? (flash ? 'shade' : 'highlight') : emptyFill,
        );
      }
    }
    for (let x = 1; x < w; x++) dr.line(cellX(x), b, cellX(x), b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, cellY(y), b + w * t, cellY(y), 'faint', 1.2);

    const overfull = overfullLines(grid, w, h);
    const match = unique ? matchingLines(grid, w, h) : null;
    const inset = Math.round(t * 0.2);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const c = grid[i];
        const px = cellX(x);
        const py = cellY(y);
        if (c === BLACK) {
          const g = Math.max(0.5, t * 0.02);
          const fill = flash ? 'ok' : 'ink';
          dr.polygon(
            [px + g, py + g, px + t - g, py + g, px + t - g, py + t - g, px + g, py + t - g],
            fill,
            fill,
            { seed: i, width: 1.4 },
          );
        }
        if (c === EMPTY) continue;
        // Given clues carry a small sketched frame; the player's cells are plain.
        if (given[i]) {
          dr.rectOutline(px + inset, py + inset, t - 2 * inset, t - 2 * inset, 'pencil', {
            width: Math.max(1, t * 0.035),
            seed: i,
            rough: 0.6,
          });
        }
        // Too many of this colour in the row or column.
        if (overfull.rows[y] & c || overfull.cols[x] & c) {
          dr.text(px + t / 2, py + t / 2, '!', {
            size: t * 0.6,
            bold: true,
            colour: 'error',
          });
        }
      }
    }
    // Three (or more) in a row: a red frame around the whole run.
    const margin = t * 0.08;
    for (const run of findRuns(grid, w, h)) {
      const rw = run.horizontal ? run.len * t : t;
      const rh = run.horizontal ? t : run.len * t;
      dr.roundRect(
        cellX(run.x) + margin,
        cellY(run.y) + margin,
        rw - 2 * margin,
        rh - 2 * margin,
        t * 0.15,
        null,
        'error',
        { width: Math.max(2, t * 0.07), seed: run.x + run.y * w },
      );
    }
    // Unique mode: identical lines get a bar through them.
    if (match) {
      const bar = Math.max(3, t * 0.14);
      for (let y = 0; y < h; y++) {
        if (!match.rows[y]) continue;
        const cy = cellY(y) + t / 2;
        dr.line(b + t * 0.15, cy, b + w * t - t * 0.15, cy, 'error', bar, { alpha: 0.75 });
      }
      for (let x = 0; x < w; x++) {
        if (!match.cols[x]) continue;
        const cx = cellX(x) + t / 2;
        dr.line(cx, b + t * 0.15, cx, b + h * t - t * 0.15, 'error', bar, { alpha: 0.75 });
      }
    }
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (ui.cursorVisible) {
      const ci = t * 0.1;
      dr.cursor(cellX(ui.cx) + ci, cellY(ui.cy) + ci, t - 2 * ci, t - 2 * ci);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
