import { tx } from '../../i18n';
/**
 * Board model shared by the game, solver and generator: the run-length description
 * format, the two edge arrays and the rectangle inference used for the win check.
 *
 * Edges are stored the way the original does it: `vedge[y * w + x]` (x ≥ 1) is the
 * vertical edge on the left of cell (x, y) and `hedge[y * w + x]` (y ≥ 1) is the
 * horizontal edge above cell (x, y). The outer border is implicit and always present.
 */

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** A closed region found on the board: a rectangle with no edges inside it. */
export interface Region extends Rect {
  /** Clue numbers found inside the region. */
  numbers: number[];
  /** Exactly one number and it equals the area. */
  valid: boolean;
}

export const RUN_MAX = 26;

/**
 * Encode a grid of clue numbers (0 = empty) the way the original does: digits for a
 * number, a letter `a`..`z` for a run of 1..26 empty cells, and `_` between two
 * numbers that are directly adjacent in reading order.
 */
export function encodeDesc(numbers: ArrayLike<number>): string {
  let out = '';
  let run = 0;
  for (let i = 0; i <= numbers.length; i++) {
    const n = i < numbers.length ? numbers[i] : -1;
    if (n === 0) {
      run++;
      continue;
    }
    if (run) {
      while (run > 0) {
        const len = Math.min(run, RUN_MAX);
        out += String.fromCharCode('a'.charCodeAt(0) - 1 + len);
        run -= len;
      }
    } else if (out.length && n > 0) {
      out += '_';
    }
    if (n > 0) out += String(n);
    run = 0;
  }
  return out;
}

/** Parse a description into clue numbers, or return an error message. */
export function parseDesc(desc: string, w: number, h: number): number[] | string {
  const area = w * h;
  const grid: number[] = [];
  let i = 0;
  while (i < desc.length) {
    const c = desc[i++];
    if (c >= 'a' && c <= 'z') {
      const run = c.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
      for (let k = 0; k < run; k++) grid.push(0);
    } else if (c === '_') {
      // Separator between adjacent numbers; carries no cells.
    } else if (c >= '1' && c <= '9') {
      let s = c;
      while (i < desc.length && desc[i] >= '0' && desc[i] <= '9') s += desc[i++];
      const n = parseInt(s, 10);
      if (n > area) return tx`Description contains a number larger than the grid`;
      grid.push(n);
    } else {
      return tx`Invalid character in game description`;
    }
  }
  if (grid.length < area) return tx`Not enough data to fill grid`;
  if (grid.length > area) return tx`Too much data to fit in grid`;
  return grid;
}

/** Vertical edge index; only meaningful for 1 ≤ x < w. */
export const vIndex = (w: number, x: number, y: number) => y * w + x;
/** Horizontal edge index; only meaningful for 1 ≤ y < h. */
export const hIndex = (w: number, x: number, y: number) => y * w + x;

export function inVRange(w: number, h: number, x: number, y: number): boolean {
  return x >= 1 && x < w && y >= 0 && y < h;
}
export function inHRange(w: number, h: number, x: number, y: number): boolean {
  return x >= 0 && x < w && y >= 1 && y < h;
}

/**
 * The original's `grid_draw_rect`: with `outline` set, set every edge on the boundary
 * of the cell rectangle [x1, x2) × [y1, y2) and clear every edge strictly inside it;
 * without `outline`, only clear the inside. A degenerate rectangle (x1 == x2 or
 * y1 == y2) draws a straight line. Returns whether anything would change.
 */
export function drawRectEdges(
  w: number,
  h: number,
  hedge: Uint8Array,
  vedge: Uint8Array,
  outline: boolean,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  really: boolean,
): boolean {
  let changed = false;
  for (let x = x1; x < x2; x++) {
    for (let y = y1; y <= y2; y++) {
      if (!inHRange(w, h, x, y)) continue;
      const i = hIndex(w, x, y);
      const onOutline = y === y1 || y === y2;
      if (onOutline && !outline) continue;
      const val = onOutline ? 1 : 0;
      if (hedge[i] !== val) changed = true;
      if (really) hedge[i] = val;
    }
  }
  for (let y = y1; y < y2; y++) {
    for (let x = x1; x <= x2; x++) {
      if (!inVRange(w, h, x, y)) continue;
      const i = vIndex(w, x, y);
      const onOutline = x === x1 || x === x2;
      if (onOutline && !outline) continue;
      const val = onOutline ? 1 : 0;
      if (vedge[i] !== val) changed = true;
      if (really) vedge[i] = val;
    }
  }
  return changed;
}

/** Edge arrays describing a tiling by the given rectangles. */
export function edgesOfRects(
  w: number,
  h: number,
  rects: Rect[],
): { vedge: Uint8Array; hedge: Uint8Array } {
  const vedge = new Uint8Array(w * h);
  const hedge = new Uint8Array(w * h);
  for (const r of rects) {
    for (let y = r.y; y < r.y + r.h; y++) {
      if (r.x > 0) vedge[vIndex(w, r.x, y)] = 1;
      if (r.x + r.w < w) vedge[vIndex(w, r.x + r.w, y)] = 1;
    }
    for (let x = r.x; x < r.x + r.w; x++) {
      if (r.y > 0) hedge[hIndex(w, x, r.y)] = 1;
      if (r.y + r.h < h) hedge[hIndex(w, x, r.y + r.h)] = 1;
    }
  }
  return { vedge, hedge };
}

/** The `S` move string for a set of edges: vertical edges row by row, then horizontal. */
export function encodeEdges(w: number, h: number, vedge: Uint8Array, hedge: Uint8Array): string {
  let s = 'S';
  for (let y = 0; y < h; y++) for (let x = 1; x < w; x++) s += vedge[vIndex(w, x, y)] ? '1' : '0';
  for (let y = 1; y < h; y++) for (let x = 0; x < w; x++) s += hedge[hIndex(w, x, y)] ? '1' : '0';
  return s;
}

/**
 * Find every closed rectangle on the board and decide whether it is correct, the way
 * the original's `get_correct` does. Starting from each cell not yet assigned, walk
 * right and down to the next edges to get the candidate rectangle, then check that its
 * boundary is fully drawn and its interior is free of edges. `correct[i]` is 1 for cells
 * inside a rectangle that contains exactly one number equal to its area.
 */
export function findRegions(
  w: number,
  h: number,
  grid: ArrayLike<number>,
  vedge: Uint8Array,
  hedge: Uint8Array,
): { correct: Uint8Array; regions: Region[] } {
  const correct = new Uint8Array(w * h);
  const seen = new Uint8Array(w * h);
  const regions: Region[] = [];
  const hasV = (x: number, y: number) => !inVRange(w, h, x, y) || vedge[vIndex(w, x, y)] === 1;
  const hasH = (x: number, y: number) => !inHRange(w, h, x, y) || hedge[hIndex(w, x, y)] === 1;
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) {
      if (seen[y * w + x]) continue;
      let rw = 1;
      while (x + rw < w && !vedge[vIndex(w, x + rw, y)]) rw++;
      let rh = 1;
      while (y + rh < h && !hedge[hIndex(w, x, y + rh)]) rh++;

      let closed = true;
      for (let xx = x; xx < x + rw && closed; xx++) {
        for (let yy = y; yy <= y + rh; yy++) {
          const edge = hasH(xx, yy);
          if (edge !== (yy === y || yy === y + rh)) {
            closed = false;
            break;
          }
        }
      }
      for (let yy = y; yy < y + rh && closed; yy++) {
        for (let xx = x; xx <= x + rw; xx++) {
          const edge = hasV(xx, yy);
          if (edge !== (xx === x || xx === x + rw)) {
            closed = false;
            break;
          }
        }
      }
      if (!closed) {
        seen[y * w + x] = 1;
        continue;
      }
      const numbers: number[] = [];
      for (let yy = y; yy < y + rh; yy++) {
        for (let xx = x; xx < x + rw; xx++) {
          seen[yy * w + xx] = 1;
          const n = grid[yy * w + xx];
          if (n) numbers.push(n);
        }
      }
      const valid = numbers.length === 1 && numbers[0] === rw * rh;
      if (valid) {
        for (let yy = y; yy < y + rh; yy++)
          for (let xx = x; xx < x + rw; xx++) correct[yy * w + xx] = 1;
      }
      regions.push({ x, y, w: rw, h: rh, numbers, valid });
    }
  }
  return { correct, regions };
}

/** Plain-text picture of the board, in the original's format. */
export function textFormat(
  w: number,
  h: number,
  grid: ArrayLike<number>,
  vedge: Uint8Array,
  hedge: Uint8Array,
): string {
  let col = 2;
  for (let i = 0; i < w * h; i++) col = Math.max(col, String(grid[i]).length);
  const hEdge = (x: number, y: number) =>
    y === 0 || y === h || (inHRange(w, h, x, y) && hedge[hIndex(w, x, y)] === 1);
  const vEdge = (x: number, y: number) =>
    x === 0 || x === w || (inVRange(w, h, x, y) && vedge[vIndex(w, x, y)] === 1);
  const lines: string[] = [];
  for (let y = 0; y <= 2 * h; y++) {
    let line = '';
    for (let x = 0; x <= 2 * w; x++) {
      if (x & 1 && y & 1) {
        const v = grid[(y >> 1) * w + (x >> 1)];
        line += (v ? String(v) : '').padStart(col, ' ');
      } else if (x & 1) {
        line += (hEdge(x >> 1, y >> 1) ? '-' : ' ').repeat(col);
      } else if (y & 1) {
        line += vEdge(x >> 1, y >> 1) ? '|' : ' ';
      } else {
        const hl = x > 0 && hEdge((x - 1) >> 1, y >> 1);
        const hr = x < 2 * w && hEdge((x + 1) >> 1, y >> 1);
        const vu = y > 0 && vEdge(x >> 1, (y - 1) >> 1);
        const vd = y < 2 * h && vEdge(x >> 1, (y + 1) >> 1);
        if (!hl && !hr && !vu && !vd) line += ' ';
        else if (hl && hr && !vu && !vd) line += '-';
        else if (!hl && !hr && vu && vd) line += '|';
        else line += '+';
      }
    }
    lines.push(line);
  }
  return lines.join('\n');
}
