/**
 * Deductive solver for Net.
 *
 * The solver never guesses. It keeps, for every tile, the list of orientations still
 * possible, and for every tile edge whether a wire is known to cross it, known not to,
 * or unknown. Four kinds of reasoning shrink those lists until nothing changes:
 *
 * - an orientation that puts a wire on a closed edge (grid border, barrier, or an edge
 *   the neighbour is known not to use) or leaves an open edge empty is impossible;
 * - an edge used by every remaining orientation of a tile is open, one used by none
 *   is closed, and the neighbour then learns the same thing from its side;
 * - the finished network is a tree, so an orientation must not join a tile to a group
 *   it is already connected to (loop avoidance, tracked with a union-find);
 * - the finished network is connected, so a wire that can only ever reach a small
 *   dead-end pocket must not be the tile's only way out (dead-end counting).
 *
 * `solveNet` reports whether every tile was pinned down. `searchSolution` adds a
 * bounded backtracking search on top for hand-made puzzles the deductions alone cannot
 * finish.
 */
import { DSF } from '../../framework/dsf';
import {
  computeActive,
  connected,
  countWires,
  DIR_BITS,
  opp,
  orientations,
  wrapIndex,
  type Grid,
} from './core';

export interface SolveResult {
  /** Every tile has exactly one orientation left. */
  complete: boolean;
  /** Some tile had no orientation left: the puzzle (or a guess) is inconsistent. */
  contradiction: boolean;
  /** Remaining orientations per tile. */
  candidates: number[][];
}

const UNKNOWN = 0;
const OPEN = 1;
const CLOSED = 2;

/** A queue of tile indices that never holds the same tile twice. */
class Todo {
  private queued: Uint8Array;
  private items: number[] = [];
  private head = 0;
  constructor(n: number) {
    this.queued = new Uint8Array(n);
  }
  add(i: number): void {
    if (this.queued[i]) return;
    this.queued[i] = 1;
    this.items.push(i);
  }
  next(): number {
    if (this.head >= this.items.length) {
      this.items.length = 0;
      this.head = 0;
      return -1;
    }
    const i = this.items[this.head++];
    this.queued[i] = 0;
    return i;
  }
}

/**
 * Run the deductions on the given candidate lists (which are modified in place).
 * `barriers` may be null when only the grid border is known.
 */
export function deduce(
  g: Grid,
  candidates: number[][],
  barriers: ArrayLike<number> | null,
): SolveResult {
  const { w, h } = g;
  const n = w * h;
  let area = 0;
  for (let i = 0; i < n; i++) if (candidates[i][0] & 15) area++;

  const edge = new Uint8Array(n * 4);
  const reach = new Int32Array(n * 4).fill(area + 1); // area+1 = no dead end known
  const groups = new DSF(n);

  const closeEdge = (i: number, k: number) => {
    edge[i * 4 + k] = CLOSED;
    edge[wrapIndex(g, i, k) * 4 + opp(k)] = CLOSED;
  };
  if (!g.wrapping) {
    for (let x = 0; x < w; x++) {
      closeEdge(x, 1);
      closeEdge((h - 1) * w + x, 3);
    }
    for (let y = 0; y < h; y++) {
      closeEdge(y * w, 2);
      closeEdge(y * w + w - 1, 0);
    }
  }
  if (barriers) {
    for (let i = 0; i < n; i++) {
      for (let k = 0; k < 4; k++) if (barriers[i] & DIR_BITS[k]) closeEdge(i, k);
    }
  }

  const todo = new Todo(n);
  let progress = true;
  for (;;) {
    let i = todo.next();
    if (i < 0) {
      // Everything local has been tried; sweep the whole grid once more and stop if
      // that pass turns up nothing new.
      if (!progress) break;
      progress = false;
      for (let t = 0; t < n; t++) todo.add(t);
      i = todo.next();
    }

    const myGroup = groups.find(i);
    const list = candidates[i];
    // Largest dead-end total any orientation would hang off each outgoing direction.
    const pocket = [0, 0, 0, 0];
    const kept: number[] = [];
    for (const v of list) {
      let valid = true;
      let deadTotal = 0;
      const exits: number[] = [];
      const seen = [myGroup];
      for (let k = 0; k < 4; k++) {
        const bit = DIR_BITS[k];
        const e = edge[i * 4 + k];
        const has = (v & bit) !== 0;
        if ((e === OPEN && !has) || (e === CLOSED && has)) valid = false;
        if (!has) continue;
        if (reach[i * 4 + k] <= area) deadTotal += reach[i * 4 + k];
        else exits.push(k);
        if (e === UNKNOWN) {
          // Joining a tile we already reach by another route would close a loop.
          const other = groups.find(wrapIndex(g, i, k));
          if (seen.includes(other)) valid = false;
          else seen.push(other);
        }
      }
      if (exits.length === 0) {
        // Only dead ends: they and this tile must add up to the whole network.
        if (deadTotal > 0 && deadTotal + 1 < area) valid = false;
      } else if (exits.length === 1) {
        // Everything but one exit is a dead end, so seen from that exit this tile
        // and its pockets are themselves a dead end of this size.
        deadTotal++;
        if (pocket[exits[0]] < deadTotal) pocket[exits[0]] = deadTotal;
      } else {
        for (const k of exits) pocket[k] = area + 1;
      }
      if (valid) kept.push(v);
    }

    if (kept.length === 0) {
      return { complete: false, contradiction: true, candidates };
    }
    if (kept.length < list.length) {
      candidates[i] = kept;
      progress = true;
    }

    // Edges shared by all remaining orientations, and edges used by none.
    let all = 15;
    let any = 0;
    for (const v of candidates[i]) {
      all &= v;
      any |= v;
    }
    for (let k = 0; k < 4; k++) {
      if (edge[i * 4 + k] !== UNKNOWN) continue;
      const j = wrapIndex(g, i, k);
      const bit = DIR_BITS[k];
      if (all & bit) {
        edge[i * 4 + k] = OPEN;
        edge[j * 4 + opp(k)] = OPEN;
        groups.merge(i, j);
        progress = true;
        todo.add(j);
      } else if (!(any & bit)) {
        closeEdge(i, k);
        progress = true;
        todo.add(j);
      }
    }

    // Tell each neighbour how little it can reach by coming through this tile.
    for (let k = 0; k < 4; k++) {
      if (pocket[k] === 0) continue;
      const j = wrapIndex(g, i, k);
      const slot = j * 4 + opp(k);
      if (reach[slot] > pocket[k]) {
        reach[slot] = pocket[k];
        progress = true;
        todo.add(j);
      }
    }
  }

  let complete = true;
  for (let i = 0; i < n; i++) if (candidates[i].length !== 1) complete = false;
  return { complete, contradiction: false, candidates };
}

/** Run the deductive solver on a set of tiles (their current rotation is irrelevant). */
export function solveNet(
  g: Grid,
  tiles: ArrayLike<number>,
  barriers: ArrayLike<number> | null,
): SolveResult {
  const n = g.w * g.h;
  const candidates: number[][] = [];
  for (let i = 0; i < n; i++) candidates.push(orientations(tiles[i]));
  return deduce(g, candidates, barriers);
}

/** Whether a fully oriented grid is a single connected network without loops. */
export function isValidSolution(g: Grid, tiles: ArrayLike<number>, barriers: ArrayLike<number>) {
  const n = g.w * g.h;
  let first = -1;
  let filled = 0;
  let halfEdges = 0;
  for (let i = 0; i < n; i++) {
    if (tiles[i] & 15) {
      if (first < 0) first = i;
      filled++;
      halfEdges += countWires(tiles[i]);
    }
  }
  if (first < 0) return false;
  const active = computeActive(g, tiles, barriers, first % g.w, Math.floor(first / g.w));
  let count = 0;
  for (let i = 0; i < n; i++) if (active[i] && tiles[i] & 15) count++;
  if (count !== filled) return false;
  // Every wire must be matched, and a connected graph on `filled` nodes with exactly
  // filled-1 edges is a tree.
  let matched = 0;
  for (let i = 0; i < n; i++) {
    for (let k = 0; k < 4; k++) if (connected(g, tiles, barriers, i, k)) matched++;
  }
  return matched === halfEdges && matched === 2 * (filled - 1);
}

/**
 * Deduce as far as possible, then search over the remaining ambiguities. Returns a
 * complete orientation for every tile or null when none was found within `budget`
 * deduction passes.
 */
export function searchSolution(
  g: Grid,
  tiles: ArrayLike<number>,
  barriers: ArrayLike<number>,
  budget = 4000,
): number[] | null {
  const n = g.w * g.h;
  const state = { budget };
  const start: number[][] = [];
  for (let i = 0; i < n; i++) start.push(orientations(tiles[i]));

  const recurse = (cands: number[][]): number[] | null => {
    if (state.budget-- <= 0) return null;
    const res = deduce(g, cands, barriers);
    if (res.contradiction) return null;
    if (res.complete) {
      const sol = cands.map((c) => c[0]);
      return isValidSolution(g, sol, barriers) ? sol : null;
    }
    // Branch on the most constrained undecided tile.
    let pick = -1;
    for (let i = 0; i < n; i++) {
      if (cands[i].length > 1 && (pick < 0 || cands[i].length < cands[pick].length)) pick = i;
    }
    for (const v of cands[pick]) {
      const copy = cands.map((c, i) => (i === pick ? [v] : c.slice()));
      const found = recurse(copy);
      if (found) return found;
      if (state.budget <= 0) return null;
    }
    return null;
  };
  return recurse(start);
}
