/**
 * Localised views of the data a game declares in `defineGame(...)`.
 *
 * The English literals stay in `src/games/<slug>/index.ts` — they are what a game author
 * writes, what the tests read and what `en.json` is generated from — and these accessors
 * look up a translation for them, falling back to the literal. So a game never imports the
 * locale store, the menu and toolbars re-read the current language on every render, and a
 * new language is a JSON file and nothing else.
 */

import type { GameAchievement } from '../framework/achievements';
import type { TutorialStep } from '../framework/tutorial';
import type { ConfigItem, Game, Keypad, Preset } from '../framework/types';
import {
  achievementKey,
  actionLabelKey,
  actionTitleKey,
  configChoiceKey,
  configKey,
  gameAlsoKnownAsKey,
  gameDescriptionKey,
  gameNameKey,
  keypadLabelKey,
  presetKey,
  tutorialStepKey,
} from './keys';
import { t, tOwn } from './runtime';

export function gameName(game: Game): string {
  return t(gameNameKey(game.id), undefined, game.name);
}

export function gameDescription(game: Game): string {
  return t(gameDescriptionKey(game.id), undefined, game.description);
}

/**
 * The familiar names the puzzle also goes by, or `undefined` for a game that declares
 * none. A language may translate the list (Sudoku is Sudoku everywhere, but "15 puzzle"
 * and "sliding puzzle" are not), so it goes through the catalogue like the description.
 */
export function gameAlsoKnownAs(game: Game): string | undefined {
  if (!game.alsoKnownAs) return undefined;
  return t(gameAlsoKnownAsKey(game.id), undefined, game.alsoKnownAs);
}

/** A preset's name for the Type menu. Sizes like `9×9` normally need no translation. */
export function presetName(game: Game, preset: Preset<unknown>): string {
  return t(presetKey(game.id, preset.name), undefined, preset.name);
}

/**
 * A copy of the config rows with every visible label translated. The row `value` /
 * `selected` / `type` are untouched, so `customParams(items)` still reads exactly what it
 * always did — translations never reach a game's own parsing.
 */
export function localiseConfig(game: Game, items: ConfigItem[]): ConfigItem[] {
  return items.map((item) => {
    const name = t(configKey(game.id, item.name), undefined, item.name);
    if (item.type === 'choices') {
      return {
        ...item,
        name,
        choices: item.choices.map((c) => t(configChoiceKey(game.id, item.name, c), undefined, c)),
      };
    }
    return { ...item, name };
  });
}

/** Face of a keypad key, when the game gave it a word rather than the character. */
export function keypadLabel(game: Game, spec: Keypad, ch: string): string {
  const label = spec.labels?.[ch];
  if (label === undefined) return ch;
  return t(keypadLabelKey(game.id, ch), undefined, label);
}

export function actionLabel(game: Game, id: string, label: string): string {
  return t(actionLabelKey(game.id, id), undefined, label);
}

export function actionTitle(game: Game, id: string, title: string): string {
  return t(actionTitleKey(game.id, id), undefined, title);
}

/**
 * The markdown for one tutorial step in the active language.
 *
 * `index` is the step's position in the authored list — before `desktopOnly` steps are
 * filtered out — so the keys stay put whatever device is reading them.
 *
 * On a touch screen the `textTouch` wording wins, but only when *this* language supplied
 * it: a locale that translated `text` and left `textTouch` alone gets its own `text`
 * rather than dropping all the way back to the English touch sentence.
 */
export function tutorialStepText(
  slug: string,
  index: number,
  step: TutorialStep,
  touch: boolean,
): string {
  if (touch && step.textTouch) {
    const own = tOwn(tutorialStepKey(slug, index, true));
    if (own !== undefined) return own;
  }
  return t(tutorialStepKey(slug, index), undefined, step.text);
}

/** A game's own achievement, translated: its title and its condition. */
export function achievementText(
  game: Game,
  a: GameAchievement,
): { name: string; description: string } {
  return {
    name: t(achievementKey(game.id, a.id, 'name'), undefined, a.name),
    description: t(achievementKey(game.id, a.id, 'description'), undefined, a.description),
  };
}
