import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { RES } from './index';
import type { UntangleState, UntangleUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Where point `i` is drawn, in canvas pixels. */
function pointAt(state: UntangleState, i: number, t: number): { x: number; y: number } {
  const b = border(t);
  return { x: b + (state.pts[2 * i] * t) / RES, y: b + (state.pts[2 * i + 1] * t) / RES };
}

/** A little square around point `i`, kept inside the board. */
function pointRect(state: UntangleState, i: number, t: number): TutorialRect {
  const p = pointAt(state, i, t);
  const r = t * 0.35;
  const b = border(t);
  const lo = (v: number) => Math.max(0, Math.min(v, 2 * b + state.w * t - 2 * r));
  return { x: lo(p.x - r), y: lo(p.y - r), w: 2 * r, h: 2 * r };
}

/** How many edges are currently drawn in red. */
function tangled(state: UntangleState): number {
  return state.crossed.reduce((n, c) => n + (c ? 1 : 0), 0);
}

