/**
 * Range puzzle generation, following the original's recipe:
 *
 *  1. Start from an all-white grid and try to paint about a third of the cells black, in
 *     a random order, skipping any cell that would touch another black cell or cut the
 *     white region in two.
 *  2. Give every white cell the number it would carry as a clue.
 *  3. Remove the clues rotationally opposite the black cells (so the clue layout can be
 *     two-way symmetric), and give up on this grid if the deductive solver can no longer
 *     finish it. Then take away symmetric pairs of clues, in a random order, whenever the
 *     solver still finishes the puzzle without them.
 *
 * Because the solver only ever makes forced deductions, every puzzle it finishes has a
 * unique solution, and the player never needs to guess.
 */
import type { Random } from '../../framework/rng';
import { BLACK, WHITE, encodeDesc, encodeSolution } from './board';
import { SOLVED, Solver } from './solver';

export interface RangeParams {
  w: number;
  h: number;
}

/**
 * A random valid black pattern: `order` is a permutation of the cells; the first third
 * are tried as black cells in turn, and the last one is a cell that stays white. Returns
 * a grid of `BLACK`/`WHITE`.
 */
export function chooseBlacks(w: number, h: number, order: readonly number[]): Uint8Array {
  const n = w * h;
  const grid = new Uint8Array(n).fill(WHITE);
  const anyWhite = order[n - 1];
  const stack = new Int32Array(n);
  const seen = new Uint8Array(n);
  let nblack = 0;
  const attempts = Math.floor(n / 3);
  for (let k = 0; k < attempts; k++) {
    const i = order[k];
    const x = i % w;
    const y = (i - x) / w;
    if (
      (x > 0 && grid[i - 1] === BLACK) ||
      (x < w - 1 && grid[i + 1] === BLACK) ||
      (y > 0 && grid[i - w] === BLACK) ||
      (y < h - 1 && grid[i + w] === BLACK)
    )
      continue;
    grid[i] = BLACK;
    nblack++;
    if (countReachable(grid, w, h, anyWhite, stack, seen) + nblack < n) {
      grid[i] = WHITE;
      nblack--;
    }
  }
  return grid;
}

/** Number of white cells reachable from `start` through white cells. */
function countReachable(
  grid: Uint8Array,
  w: number,
  h: number,
  start: number,
  stack: Int32Array,
  seen: Uint8Array,
): number {
  seen.fill(0);
  let top = 0;
  let count = 0;
  stack[top++] = start;
  seen[start] = 1;
  while (top > 0) {
    const i = stack[--top];
    count++;
    const x = i % w;
    const y = (i - x) / w;
    const push = (j: number) => {
      if (!seen[j] && grid[j] !== BLACK) {
        seen[j] = 1;
        stack[top++] = j;
      }
    };
    if (x > 0) push(i - 1);
    if (x < w - 1) push(i + 1);
    if (y > 0) push(i - w);
    if (y < h - 1) push(i + w);
  }
  return count;
}

/** The number every white cell would carry: its horizontal plus vertical run, minus one. */
export function computeClues(grid: Uint8Array, w: number, h: number): Uint8Array {
  const clues = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    let start = 0;
    for (let x = 0; x <= w; x++) {
      if (x === w || grid[y * w + x] === BLACK) {
        for (let xx = start; xx < x; xx++) clues[y * w + xx] += x - start;
        start = x + 1;
      }
    }
  }
  for (let x = 0; x < w; x++) {
    let start = 0;
    for (let y = 0; y <= h; y++) {
      if (y === h || grid[y * w + x] === BLACK) {
        for (let yy = start; yy < y; yy++) clues[yy * w + x] += y - start - 1;
        start = y + 1;
      }
    }
  }
  return clues;
}

/**
 * Thin the full clue grid in place. Clues opposite a black cell go first; if the solver
 * cannot finish without them the grid is rejected (false). Otherwise every symmetric pair
 * of clues is removed, in `order`, when the solver still finishes without it.
 */
export function stripClues(
  clues: Uint8Array,
  solution: Uint8Array,
  w: number,
  h: number,
  order: readonly number[],
): boolean {
  const n = w * h;
  for (let i = 0; i < n; i++) if (solution[n - 1 - i] === BLACK) clues[i] = 0;
  if (new Solver(clues, w, h).propagate() !== SOLVED) return false;
  const done = new Uint8Array(n);
  for (const i of order) {
    const j = n - 1 - i;
    if (done[i] || solution[i] === BLACK || solution[j] === BLACK) continue;
    done[i] = done[j] = 1;
    const ci = clues[i];
    const cj = clues[j];
    clues[i] = clues[j] = 0;
    if (new Solver(clues, w, h).propagate() !== SOLVED) {
      clues[i] = ci;
      clues[j] = cj;
    }
  }
  return true;
}

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(params: RangeParams, rng: Random): { desc: string; aux: string } {
  const { w, h } = params;
  const n = w * h;
  const order: number[] = [];
  for (let i = 0; i < n; i++) order.push(i);
  for (;;) {
    rng.shuffle(order);
    const solution = chooseBlacks(w, h, order);
    const clues = computeClues(solution, w, h);
    rng.shuffle(order);
    if (stripClues(clues, solution, w, h, order)) {
      return { desc: encodeDesc(clues), aux: encodeSolution(solution) };
    }
  }
}
