import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { InertiaParams, InertiaState } from './index';
import { BLANK, GEM, slide, solveRoute } from './solver';

type C = typeof PALETTE;

/** A gem as the board draws it: a pale blue diamond with a glint. */
function gem(c: C, cx: number, cy: number, rx: number, ry: number): string {
  const d = `M${cx} ${cy - ry} L${cx + rx} ${cy} L${cx} ${cy + ry} L${cx - rx} ${cy} Z`;
  return (
    `<path d="${d}" fill="${c.highlight}"/>` +
    `<path d="${d}" fill="${c.blue}" fill-opacity="0.55" stroke="${c.blue}" stroke-width="3.5" stroke-linejoin="round"/>` +
    `<circle cx="${cx - rx * 0.25}" cy="${cy - ry * 0.4}" r="${Math.max(1.5, rx * 0.16)}" fill="${c.highlight}"/>`
  );
}

function ball(c: C, cx: number, cy: number, r: number): string {
  return (
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.accent}" stroke="${c.ink}" stroke-width="4"/>` +
    `<circle cx="${cx - r * 0.35}" cy="${cy - r * 0.35}" r="${r * 0.25}" fill="${c.highlight}" fill-opacity="0.8"/>`
  );
}

function mine(c: C, cx: number, cy: number, r: number): string {
  let spikes = '';
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4 + Math.PI / 8;
    spikes += `M${(cx + Math.cos(a) * r * 0.7).toFixed(1)} ${(cy + Math.sin(a) * r * 0.7).toFixed(1)} L${(cx + Math.cos(a) * r * 1.6).toFixed(1)} ${(cy + Math.sin(a) * r * 1.6).toFixed(1)} `;
  }
  return (
    `<path d="${spikes}" stroke="${c.ink}" stroke-width="${(r * 0.3).toFixed(1)}" stroke-linecap="round"/>` +
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.ink}"/>` +
    `<circle cx="${cx - r * 0.35}" cy="${cy - r * 0.35}" r="${r * 0.22}" fill="${c.highlight}"/>`
  );
}

/** Most gems any single roll on the kept line picked up. */
function bestRoll(history: readonly InertiaState[]): number {
  let best = 0;
  for (let k = 1; k < history.length; k++)
    best = Math.max(best, history[k - 1].gems - history[k].gems);
  return best;
}

/**
 * Rolls Solve takes from the deal until the last gem is in: its route, cut off where it
 * would turn for home (the route ends back where it started).
 */
function solverRolls(s: InertiaState): number | null {
  const route = solveRoute(s.w, s.h, s.grid, s.px, s.py);
  if (!route) return null;
  const cells = s.grid.split('');
  let { px, py, gems } = s;
  for (let k = 0; k < route.length; k++) {
    const step = slide(s.w, s.h, cells.join(''), px, py, route[k]);
    if (!step) return null;
    for (const c of step.cells) {
      if (cells[c] === GEM) {
        cells[c] = BLANK;
        gems--;
      }
    }
    const last = step.cells[step.cells.length - 1];
    px = last % s.w;
    py = (last - px) / s.w;
    if (gems === 0) return k + 1;
  }
  return route.length;
}

export const achievements = defineAchievements<InertiaParams, InertiaState>([
  {
    id: 'hat-trick',
    name: 'Hat Trick',
    description: 'Collect three gems or more with a single roll of the ball.',
    tier: 'bronze',
    hue: 'blue',
    // The ball rolls diagonally through a line of three gems.
    art: (c) =>
      `<path d="M17 83 L24 76" stroke="${c.pencil}" stroke-width="4" stroke-linecap="round" stroke-dasharray="1 6"/>` +
      gem(c, 51, 49, 6.5, 9) +
      gem(c, 63, 37, 6.5, 9) +
      gem(c, 75, 25, 6.5, 9) +
      ball(c, 34, 66, 10),
    test: (ctx) => bestRoll(ctx.history) >= 3,
  },
  {
    id: 'shortcut',
    name: 'Shortcut',
    description: 'Collect every gem on a 15×12 or larger board in fewer rolls than Solve would.',
    tier: 'gold',
    hue: 'green',
    // The long way round in pencil; the short way in ink, gem collected at its end.
    art: (c) =>
      `<path d="M24 76 V24 H76 V50 H40 V62 H76" fill="none" stroke="${c.pencil}" stroke-width="3.5" stroke-dasharray="5 5" stroke-linecap="round" stroke-linejoin="round"/>` +
      `<path d="M24 76 L60 40" fill="none" stroke="${c.ink}" stroke-width="5.5" stroke-linecap="round"/>` +
      `<path d="M54 36 L62 38 L64 46" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/>` +
      gem(c, 70, 30, 8, 11) +
      ball(c, 24, 76, 9),
    test: (ctx) => {
      const { w, h } = ctx.params;
      if (w * h < 15 * 12) return false;
      const par = solverRolls(ctx.initial);
      return par !== null && ctx.moves < par;
    },
  },
  {
    id: 'last-gem-mine',
    name: 'Pyrrhic Victory',
    description: 'Roll onto a mine with the same roll that picks up the very last gem.',
    tier: 'bronze',
    hidden: true,
    hue: 'red',
    on: 'lose',
    art: (c) =>
      `<path d="M58 18 L64 36 L82 32 L70 46 L84 58 L66 60 L68 80 L56 66 L44 78 L44 60 L26 60 L40 48 L30 32 L48 38 Z" fill="${c.yellow}" stroke="${c.orange}" stroke-width="3.5" stroke-linejoin="round"/>` +
      mine(c, 56, 50, 10) +
      gem(c, 24, 26, 6, 8) +
      `<path d="M16 26 L12 22 M24 16 V12 M32 26 L36 22" stroke="${c.blue}" stroke-width="3" stroke-linecap="round"/>`,
    test: (ctx) => ctx.state.dead && ctx.state.gems === 0,
  },
]);
