/**
 * Tracks solver: repeated application of sound deductions until nothing changes.
 *
 * Easy deductions look at one square or one line at a time (a square with two rails has
 * no others; a line with all its track squares found has none elsewhere; a rail that
 * would close a loop or join the entrance to the exit prematurely is impossible).
 * Tricky adds reasoning about where a line's last track square can be and about loose
 * ends that must continue along or across a line.
 *
 * Because every step is a valid inference, a board the solver completes is the puzzle's
 * only solution, which is what the generator relies on.
 */
import { ALL, Board, D, DIRS, L, NBITS, R, U, analyse } from './board';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Tricky'];
export const DIFFICULTY_CHARS = 'et';
export const DIFF_MAX = DIFFICULTY_NAMES.length - 1;

/** Optional listener for every deduction, used by tests to audit the solver. */
export type SolverTrace = (what: string, i: number, d: number, track: boolean, why: string) => void;
let trace: SolverTrace | null = null;
export function setSolverTrace(fn: SolverTrace | null): void {
  trace = fn;
}

class Solver {
  impossible = false;

  constructor(readonly b: Board) {}

  /**
   * Two invariants are kept at all times so every rule can trust the flags it reads: a
   * square with a rail is marked as track, and an empty square has all four sides blocked.
   */
  private setSquare(i: number, track: boolean, why: string): number {
    const arr = track ? this.b.sTrack : this.b.sNotrack;
    if (arr[i]) return 0;
    if ((track ? this.b.sNotrack : this.b.sTrack)[i]) this.impossible = true;
    arr[i] = 1;
    trace?.('square', i, 0, track, why);
    if (!track) for (const d of DIRS) this.setEdge(i, d, false, why);
    return 1;
  }

  private setEdge(i: number, d: number, track: boolean, why: string): number {
    const b = this.b;
    if ((track ? b.track : b.notrack)[i] & d) return 0;
    if ((track ? b.notrack : b.track)[i] & d) this.impossible = true;
    if (track) b.setTrack(i, d);
    else b.setNoTrack(i, d);
    trace?.('edge', i, d, track, why);
    if (track) {
      this.setSquare(i, true, why);
      const j = b.neighbour(i, d);
      if (j >= 0) this.setSquare(j, true, why);
    }
    return 1;
  }

  /** Nothing leaves the grid except the entrance and exit pieces. */
  private discountBorder(): void {
    const { w, h } = this.b;
    const border = (i: number, d: number) => {
      if (!(this.b.track[i] & d)) this.setEdge(i, d, false, 'border');
    };
    for (let x = 0; x < w; x++) {
      border(x, U);
      border((h - 1) * w + x, D);
    }
    for (let y = 0; y < h; y++) {
      border(y * w, L);
      border(y * w + w - 1, R);
    }
  }

  /** Square-local consequences of the flags around each square. */
  private updateFlags(): number {
    const b = this.b;
    let did = 0;
    for (let i = 0; i < b.n; i++) {
      if (b.sNotrack[i])
        for (const d of DIRS) did += this.setEdge(i, d, false, 'sides of an empty square');
      const nt = NBITS[b.notrack[i]];
      const t = NBITS[b.track[i]];
      if (nt >= 3) did += this.setSquare(i, false, 'three blocked sides');
      if (t > 0) did += this.setSquare(i, true, 'has a rail');
      if (b.sTrack[i]) {
        if (nt === 2 && t < 2) {
          for (const d of DIRS)
            if (!((b.track[i] | b.notrack[i]) & d))
              did += this.setEdge(i, d, true, 'two blocked sides');
        }
        if (t === 2 && nt < 2) {
          for (const d of DIRS)
            if (!((b.track[i] | b.notrack[i]) & d))
              did += this.setEdge(i, d, false, 'two rails already');
        }
        if (t > 2) this.impossible = true;
      }
    }
    return did;
  }

  /** Iterate over the squares of a line: start index, step, length, target count. */
  private line(line: number): { start: number; step: number; len: number; target: number } {
    const { w, h, layout } = this.b;
    return line < w
      ? { start: line, step: w, len: h, target: layout.numbers[line] }
      : { start: (line - w) * w, step: 1, len: w, target: layout.numbers[line] };
  }

  /** A line with all its track (or all its empty) squares known fixes the rest. */
  private countClues(): number {
    const b = this.b;
    let did = 0;
    for (let ln = 0; ln < b.w + b.h; ln++) {
      const { start, step, len, target } = this.line(ln);
      let ctrack = 0;
      let cnotrack = 0;
      for (let j = 0, i = start; j < len; j++, i += step) {
        if (b.sTrack[i]) ctrack++;
        if (b.sNotrack[i]) cnotrack++;
      }
      if (ctrack > target || cnotrack > len - target) this.impossible = true;
      if (ctrack === target) {
        for (let j = 0, i = start; j < len; j++, i += step)
          if (!b.sTrack[i]) did += this.setSquare(i, false, 'line count reached');
      }
      if (cnotrack === len - target) {
        for (let j = 0, i = start; j < len; j++, i += step)
          if (!b.sNotrack[i]) did += this.setSquare(i, true, 'line has no room to spare');
      }
    }
    return did;
  }

  /** Rails that would close a loop, or join the ends before the rest is done, are out. */
  private checkLoop(): number {
    const b = this.b;
    const { w, h, n, layout } = b;
    // A throwaway union-find; the framework DSF's inverse flags are not needed here.
    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) parent[i] = i;
    const find = (i: number): number => {
      while (parent[i] !== i) {
        parent[i] = parent[parent[i]];
        i = parent[i];
      }
      return i;
    };
    const merge = (a: number, c: number) => {
      parent[find(a)] = find(c);
    };
    for (let i = 0; i < n; i++) {
      if (i % w < w - 1 && b.track[i] & R) merge(i, i + 1);
      if (i < n - w && b.track[i] & D) merge(i, i + w);
    }
    const startc = find(layout.rowS * w);
    const endc = find((h - 1) * w + layout.colS);
    let did = 0;
    const consider = (i: number, j: number, d: number) => {
      if (!b.sTrack[i] || !b.sTrack[j]) return;
      if ((b.track[i] | b.notrack[i]) & d) return;
      const ic = find(i);
      const jc = find(j);
      if (ic === jc) {
        did += this.setEdge(i, d, false, 'would close a loop');
        return;
      }
      if ((ic === startc && jc === endc) || (ic === endc && jc === startc)) {
        // Joining the ends finishes the line: every other rail would be stranded, and
        // every count must already be met.
        for (let k = 0; k < n; k++) {
          if (b.sTrack[k]) {
            const kc = find(k);
            if (kc !== startc && kc !== endc) {
              did += this.setEdge(i, d, false, 'would strand track');
              return;
            }
          }
        }
        for (let ln = 0; ln < w + h; ln++) {
          const { start, step, len, target } = this.line(ln);
          let ctrack = 0;
          for (let jj = 0, k = start; jj < len; jj++, k += step) if (b.sTrack[k]) ctrack++;
          if (ctrack < target) {
            did += this.setEdge(i, d, false, 'would finish early');
            return;
          }
        }
      }
    };
    for (let i = 0; i < n; i++) {
      if (i % w < w - 1) consider(i, i + 1, R);
      if (i < n - w) consider(i, i + w, D);
    }
    return did;
  }

  /**
   * Tricky: a line needing exactly one more track square. That square is either crossed
   * straight through (both sides across the line must be free) or continues an existing
   * track square of the line through a free side; anywhere else is impossible.
   */
  private checkSingle(): number {
    const b = this.b;
    let did = 0;
    for (let ln = 0; ln < b.w + b.h; ln++) {
      const { start, step, len, target } = this.line(ln);
      const along = ln < b.w ? U | D : L | R;
      const across = ALL & ~along;
      let ctrack = 0;
      for (let j = 0, i = start; j < len; j++, i += step) if (b.sTrack[i]) ctrack++;
      if (target - ctrack !== 1) continue;
      for (let j = 0, i = start; j < len; j++, i += step) {
        if (b.sTrack[i] || b.sNotrack[i]) continue;
        if (!(b.notrack[i] & across)) continue;
        let canJoin = false;
        for (const d of DIRS) {
          if (!(d & along) || b.notrack[i] & d) continue;
          const k = b.neighbour(i, d);
          if (k >= 0 && b.sTrack[k] && NBITS[b.track[k]] < 2) canJoin = true;
        }
        if (!canJoin) did += this.setSquare(i, false, 'last square cannot reach here');
      }
    }
    return did;
  }

  /**
   * Tricky: loose ends. A track square with a single rail running along the line must
   * be finished either across the line or into a neighbour along it; counting how many
   * unfinished squares the line still allows decides which.
   */
  private checkLooseEnds(): number {
    const b = this.b;
    let did = 0;
    const loose = new Uint8Array(Math.max(b.w, b.h));
    for (let ln = 0; ln < b.w + b.h; ln++) {
      const { start, step, len, target } = this.line(ln);
      const along = ln < b.w ? U | D : L | R;
      const across = ALL & ~along;
      let e2 = 0;
      let nloose = 0;
      let nperp = 0;
      for (let j = 0, i = start; j < len; j++, i += step) {
        const f = NBITS[b.track[i]];
        if (f === 2) e2++;
        loose[j] = f === 1 && b.track[i] & along ? 1 : 0;
        if (loose[j]) nloose++;
        if (f !== 2 && !(b.notrack[i] & across)) nperp++;
      }
      const remaining = target - e2;
      if (nloose > remaining) this.impossible = true;
      if (nloose > 0 && nloose === remaining) {
        // No new track squares may appear: each loose end not beside another loose end
        // must turn across the line.
        for (let j = 0, i = start; j < len; j++, i += step) {
          if (!loose[j]) continue;
          if ((j > 0 && loose[j - 1]) || (j < len - 1 && loose[j + 1])) continue;
          for (const d of DIRS)
            if (d & along && !(b.track[i] & d))
              did += this.setEdge(i, d, false, 'loose end must turn');
        }
      }
      if (nloose === 1 && remaining === 2 && nperp === 0) {
        // The one other unfinished square cannot be a crossing, so it must connect to
        // the loose end along the line: the loose end runs straight on.
        for (let j = 0, i = start; j < len; j++, i += step) {
          if (!loose[j]) continue;
          for (const d of DIRS) if (d & along) did += this.setEdge(i, d, true, 'loose end runs on');
        }
      }
    }
    return did;
  }

  run(diff: number): -1 | 0 | 1 {
    for (let i = 0; i < this.b.n; i++) if (this.b.track[i]) this.b.sTrack[i] = 1;
    this.discountBorder();
    for (;;) {
      let did = this.updateFlags();
      did += this.countClues();
      did += this.checkLoop();
      if (diff >= DIFF_TRICKY) {
        did += this.checkSingle();
        did += this.checkLooseEnds();
      }
      if (!did || this.impossible) break;
    }
    if (this.impossible) return -1;
    return analyse(this.b).completed ? 1 : 0;
  }
}

/**
 * Solve `board` in place with deductions up to `diff`. Returns 1 when the board is
 * completely and uniquely determined, 0 when stuck and -1 when it is contradictory.
 */
export function solveBoard(board: Board, diff: number): -1 | 0 | 1 {
  return new Solver(board).run(diff);
}

/** How much the solver has pinned down: a monotone measure used while placing clues. */
export function solveProgress(b: Board): number {
  let p = 0;
  for (let i = 0; i < b.n; i++) {
    p += b.sTrack[i] + b.sNotrack[i] + NBITS[b.track[i]] + NBITS[b.notrack[i]];
  }
  return p;
}
