/**
 * Achievements: the store, the list, and the rules for earning them.
 *
 * Two kinds, one shelf. Collection-wide ones (`./meta`) are read off running totals —
 * credited solves, games unlocked, days played. A game's own ones come from
 * `Game.achievements` and are tested against the puzzle that just ended. The play page
 * reports what happens ({@link reportPuzzleEnd}, {@link reportHint},
 * {@link reportTutorialDone}); everything else here is bookkeeping, and nothing in it can
 * change how a puzzle plays. See `docs/ACHIEVEMENTS.md`.
 *
 * Saved through `../storage` like progress, with the same one-way merge: an achievement
 * earned on *either* tier is kept, so reconciling a portal save with a local one can never
 * take a badge away.
 */
import type { AchievementTier, BadgeArt, PuzzleEndContext } from '../framework/achievements';
import type { PaletteToken } from '../framework/palette';
import type { Game } from '../framework/types';
import { games, getGame } from '../games/registry';
import { track } from '../analytics';
import { onStorageUpgrade, readAll, writeItem } from '../storage';
import { getProgress, onProgressChange } from '../ui/progress';
import { META_ACHIEVEMENTS, type MetaAchievement, type MetaEvent, type MetaView } from './meta';

export type { MetaEvent, MetaView } from './meta';

const KEY = 'puzzlebox:achievements';
const VERSION = 1;
/** Days remembered for the "played on N days" ones; more than the largest goal needs. */
const MAX_DAYS = 60;

export interface AchievementData {
  version: number;
  /** Achievement key → when it was earned (ms since the epoch). */
  earned: Record<string, number>;
  /** Games solved at their hardest preset. */
  hardest: string[];
  /** Credited solves with no undo and no hint. */
  pure: number;
  /** Local dates (`YYYY-MM-DD`) the collection was opened on, newest last. */
  days: string[];
  /** Games whose tutorial was played to the end. */
  tutorials: string[];
}

/** One entry on the shelf, whichever kind it is. */
export interface Achievement {
  /** `first-solve` for a collection-wide one, `<slug>.<id>` for a game's own. */
  key: string;
  /** The game it belongs to, or `null` for a collection-wide one. */
  game: Game | null;
  tier: AchievementTier;
  hidden: boolean;
  hue?: PaletteToken;
  art: BadgeArt;
  /** For counting ones: how far along, and where it ends. */
  goal?: (v: MetaView) => number;
  count?: (v: MetaView) => number;
  /** Counts other achievements (see `MetaAchievement.hunter`). */
  hunter: boolean;
}

function fresh(): AchievementData {
  return { version: VERSION, earned: {}, hardest: [], pure: 0, days: [], tutorials: [] };
}

function parse(raw: string): AchievementData | null {
  try {
    const d = JSON.parse(raw) as AchievementData;
    if (d && d.version === VERSION && d.earned && typeof d.earned === 'object')
      return { ...fresh(), ...d };
  } catch {
    /* ignore */
  }
  return null;
}

/** Union of both records; an earned badge keeps its earliest date. */
function merge(a: AchievementData, b: AchievementData): AchievementData {
  const earned = { ...a.earned };
  for (const [k, v] of Object.entries(b.earned)) earned[k] = Math.min(earned[k] ?? v, v);
  return {
    version: VERSION,
    earned,
    hardest: [...new Set([...a.hardest, ...b.hardest])],
    pure: Math.max(a.pure, b.pure),
    days: [...new Set([...a.days, ...b.days])].sort().slice(-MAX_DAYS),
    tutorials: [...new Set([...a.tutorials, ...b.tutorials])],
  };
}

function load(): AchievementData {
  const found = readAll(KEY)
    .map(parse)
    .filter((d): d is AchievementData => d !== null);
  return found.length ? found.reduce(merge) : fresh();
}

let cache: AchievementData | null = null;
let touched = false;

export function getAchievementData(): AchievementData {
  if (!cache) cache = load();
  return cache;
}

function save(d: AchievementData): void {
  cache = d;
  touched = true;
  writeItem(KEY, JSON.stringify(d));
}

onStorageUpgrade(() => {
  const next = touched ? getAchievementData() : load();
  cache = next;
  writeItem(KEY, JSON.stringify(next));
  // A save from another device may have made new totals: check without fanfare.
  evaluate({ kind: 'progress' }, { quiet: true });
});

// ---------------------------------------------------------------- the list

function fromMeta(m: MetaAchievement): Achievement {
  const goal = m.goal;
  return {
    key: m.id,
    game: null,
    tier: m.tier,
    hidden: !!m.hidden,
    hue: m.hue,
    art: m.art,
    goal: goal === undefined ? undefined : typeof goal === 'number' ? () => goal : goal,
    count: m.count,
    hunter: !!m.hunter,
  };
}

/** Every achievement, collection-wide first, then each game's in the games' order. */
export const ACHIEVEMENTS: Achievement[] = [
  ...META_ACHIEVEMENTS.map(fromMeta),
  ...games.flatMap((game) =>
    (game.achievements ?? []).map((a): Achievement => ({
      key: `${game.id}.${a.id}`,
      game,
      tier: a.tier,
      hidden: !!a.hidden,
      hue: a.hue,
      art: a.art,
      hunter: false,
    })),
  ),
];

const byKey = new Map(ACHIEVEMENTS.map((a) => [a.key, a]));

export function getAchievement(key: string): Achievement | undefined {
  return byKey.get(key);
}

export function isEarned(key: string): boolean {
  return key in getAchievementData().earned;
}

export function earnedAt(key: string): number | undefined {
  return getAchievementData().earned[key];
}

/** Earned, out of how many. Only achievements that still exist are counted. */
export function achievementTotals(): { earned: number; total: number } {
  const earned = getAchievementData().earned;
  return { earned: ACHIEVEMENTS.filter((a) => a.key in earned).length, total: ACHIEVEMENTS.length };
}

// ---------------------------------------------------------------- totals

/** Credited solves since the page loaded. */
let session = 0;

export function metaView(): MetaView {
  const p = getProgress();
  const d = getAchievementData();
  const counts = Object.values(p.solved);
  const earnable = ACHIEVEMENTS.filter((a) => !a.hunter);
  return {
    solves: counts.reduce((a, b) => a + b, 0),
    bestInOneGame: counts.length ? Math.max(...counts) : 0,
    gamesSolved: Object.entries(p.solved).filter(([slug, n]) => n > 0 && getGame(slug)).length,
    unlocked: p.unlocked.filter((slug) => getGame(slug)).length,
    totalGames: games.length,
    hardest: d.hardest.filter((slug) => getGame(slug)).length,
    pure: d.pure,
    days: d.days.length,
    tutorials: d.tutorials.filter((slug) => getGame(slug)).length,
    earned: earnable.filter((a) => a.key in d.earned).length,
    earnable: earnable.length,
    session,
  };
}

/** How far along a counting achievement is, clamped to its goal; `null` for a one-off. */
export function achievementProgress(a: Achievement): { n: number; goal: number } | null {
  if (!a.goal || !a.count) return null;
  const v = metaView();
  const goal = a.goal(v);
  return { n: Math.min(goal, a.count(v)), goal };
}

// ---------------------------------------------------------------- earning

type Listener = (a: Achievement) => void;
const listeners = new Set<Listener>();

/** Called once per newly earned achievement, in the order they were earned. */
export function onAchievement(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

function award(keys: string[], quiet: boolean): void {
  if (!keys.length) return;
  const d = getAchievementData();
  const now = Date.now();
  const earned = { ...d.earned };
  for (const k of keys) earned[k] = now;
  save({ ...d, earned });
  for (const k of keys) {
    const a = byKey.get(k);
    if (!a) continue;
    track('achievement_unlock', { achievement: k, tier: a.tier, game: a.game?.id });
    if (quiet) continue;
    for (const fn of listeners) {
      try {
        fn(a);
      } catch {
        /* a broken listener must not stop the rest */
      }
    }
  }
}

function metaEarned(m: MetaAchievement, v: MetaView, e: MetaEvent): boolean {
  if (m.test) return m.test(v, e);
  if (m.count && m.goal !== undefined) {
    const goal = typeof m.goal === 'number' ? m.goal : m.goal(v);
    return goal > 0 && m.count(v) >= goal;
  }
  return false;
}

/**
 * Check every collection-wide achievement against the totals as they now stand, plus
 * `extra` game-specific ones already decided by the caller. The "earn N achievements"
 * ones go last and loop, since earning one can complete another.
 */
function evaluate(e: MetaEvent, opts: { quiet?: boolean; extra?: string[] } = {}): void {
  const got = new Set(Object.keys(getAchievementData().earned));
  const fresh: string[] = [];
  const add = (k: string) => {
    if (!got.has(k)) {
      got.add(k);
      fresh.push(k);
    }
  };
  for (const k of opts.extra ?? []) add(k);
  // The totals include what this very event earned, so "first solve" and "collector" land
  // together rather than one visit apart.
  const viewWith = (): MetaView => {
    const v = metaView();
    const earnable = ACHIEVEMENTS.filter((a) => !a.hunter);
    return { ...v, earned: earnable.filter((a) => got.has(a.key)).length };
  };
  let v = viewWith();
  for (const m of META_ACHIEVEMENTS) {
    if (m.hunter || got.has(m.id)) continue;
    if (safeTest(() => metaEarned(m, v, e))) add(m.id);
  }
  for (let changed = true; changed;) {
    changed = false;
    v = viewWith();
    for (const m of META_ACHIEVEMENTS) {
      if (!m.hunter || got.has(m.id)) continue;
      if (safeTest(() => metaEarned(m, v, e))) {
        add(m.id);
        changed = true;
      }
    }
  }
  award(fresh, !!opts.quiet);
}

/** A test that throws has not been passed. Nothing an achievement does may break a page. */
function safeTest(fn: () => boolean): boolean {
  try {
    return fn();
  } catch {
    return false;
  }
}

function today(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

// ---------------------------------------------------------------- reports from the pages

/** The collection was opened: count the day, and pick up anything already due. */
export function reportVisit(): void {
  const d = getAchievementData();
  const day = today();
  if (!d.days.includes(day)) save({ ...d, days: [...d.days, day].slice(-MAX_DAYS) });
  evaluate({ kind: 'visit' });
}

export interface PuzzleEndReport {
  game: Game;
  ctx: PuzzleEndContext;
  /** Solved by hand at a preset size (or lost, outside a tutorial). */
  eligible: boolean;
  credited: boolean;
  lostBefore: boolean;
}

/** A puzzle ended, won or lost, outside the tutorial. */
export function reportPuzzleEnd(r: PuzzleEndReport): void {
  const { game, ctx, eligible, credited } = r;
  const d = getAchievementData();
  let next = d;
  if (ctx.status === 1 && eligible && credited) {
    session++;
    if (ctx.undos === 0 && ctx.hints === 0) next = { ...next, pure: next.pure + 1 };
  }
  if (
    ctx.status === 1 &&
    eligible &&
    ctx.presetCount > 0 &&
    ctx.preset === ctx.presetCount - 1 &&
    !next.hardest.includes(game.id)
  )
    next = { ...next, hardest: [...next.hardest, game.id] };
  if (next !== d) save(next);

  const extra: string[] = [];
  if (eligible) {
    const ending = ctx.status === 1 ? 'win' : 'lose';
    for (const a of game.achievements ?? []) {
      if ((a.on ?? 'win') !== ending) continue;
      if (safeTest(() => a.test(ctx))) extra.push(`${game.id}.${a.id}`);
    }
  }
  evaluate(
    { kind: 'end', ctx, eligible, credited, lostBefore: r.lostBefore, hour: new Date().getHours() },
    { extra },
  );
}

export function reportHint(): void {
  evaluate({ kind: 'hint' });
}

export function reportTutorialDone(slug: string): void {
  const d = getAchievementData();
  if (!d.tutorials.includes(slug)) save({ ...d, tutorials: [...d.tutorials, slug] });
  evaluate({ kind: 'tutorial' });
}

/** Unlocks happen on the menu; the totals are watched rather than reported. */
let watching = false;
export function watchProgressForAchievements(): void {
  if (watching) return;
  watching = true;
  onProgressChange(() => evaluate({ kind: 'progress' }));
}

/** For tests and tooling. `null` forgets the cache, so the next read loads from storage. */
export function _resetAchievementsForTests(d: Partial<AchievementData> | null = {}): void {
  cache = d ? { ...fresh(), ...d } : null;
  session = 0;
  touched = false;
}
