import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  MIDDLE_BUTTON,
  isCursorMove,
  isCursorSelect,
  isMouseDown,
  isMouseDrag,
  isMouseRelease,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { inBounds } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { glyph } from '../../framework/glyphs';
import type { Random } from '../../framework/rng';
import { Board, DIR_NAMES, encodeDesc, labelFor, parseDesc } from './board';
import type { Puzzle } from './board';
import { generate } from './generator';
import type { SignpostParams } from './generator';
import { SOLVED, searchSolutions, solveBoard } from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type { SignpostParams } from './generator';

export interface SignpostState {
  w: number;
  h: number;
  n: number;
  /** Each square's arrow, 0 = north clockwise to 7 = north-west. */
  dirs: number[];
  /** 1 where the number was given by the puzzle. */
  immutable: number[];
  /** Numbering: 0 blank, 1..n a number, larger values a lettered chain (see `labelFor`). */
  nums: number[];
  /** Successor / predecessor of each square, or -1. */
  next: number[];
  prev: number[];
  /** 1 where the square is part of a contradiction. */
  error: number[];
  impossible: boolean;
  completed: boolean;
  usedSolve: boolean;
}

export interface SignpostUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** A link is being dragged out (mouse) or waits for its other end (keyboard). */
  dragging: boolean;
  /** The drag started at the predecessor (left button / Enter) rather than the successor. */
  dragFrom: boolean;
  /** Square the drag started on. */
  sx: number;
  sy: number;
  /** Current pointer position in canvas pixels. */
  dx: number;
  dy: number;
  /**
   * The Break tool: a left click on a square (or dragging it off the board) breaks up its
   * whole chain instead of just unlinking the square. Drags between squares still link.
   */
  breakChain: boolean;
}

/** A chain link snapped in two, for the Break tool. */
const BREAK_GLYPH = glyph(
  'M15.7 13.2 19 10A3.5 3.5 0 0 0 14 5l-3.2 3.3M8.3 10.8 5 14a3.5 3.5 0 0 0 5 5l3.2-3.3' +
    'M4 7.5h2.5M7.5 4v2.5M20 16.5h-2.5M16.5 20v-2.5',
);

/** The completion flash spins every arrow once. */
const FLASH = 0.7;
const MAX_SIDE = 12;

function border(t: number): number {
  return Math.round(t * 0.3);
}

function puzzleOf(s: SignpostState): Puzzle {
  return {
    w: s.w,
    h: s.h,
    n: s.n,
    dirs: s.dirs,
    given: s.nums.map((v, i) => (s.immutable[i] ? v : 0)),
  };
}

function boardOf(s: SignpostState): Board {
  return Board.from(puzzleOf(s), s.immutable, s.nums, s.next, s.prev);
}

function stateOf(b: Board, dirs: number[], immutable: number[], usedSolve: boolean): SignpostState {
  const completed = b.settle();
  return {
    w: b.w,
    h: b.h,
    n: b.n,
    dirs,
    immutable,
    nums: b.nums.slice(),
    next: Array.from(b.next),
    prev: Array.from(b.prev),
    error: Array.from(b.error),
    impossible: b.impossible,
    completed,
    usedSolve,
  };
}

function hasLinks(s: SignpostState, i: number): boolean {
  return s.next[i] !== -1 || s.prev[i] !== -1;
}

/** The move linking (fx, fy) to (tx, ty), or null when the rules forbid it. */
function linkMove(s: SignpostState, fx: number, fy: number, tx: number, ty: number): string | null {
  if (!inBounds(fx, fy, s.w, s.h) || !inBounds(tx, ty, s.w, s.h)) return null;
  const b = boardOf(s);
  return b.isValidMove(false, fy * s.w + fx, ty * s.w + tx) ? `L${fx},${fy}-${tx},${ty}` : null;
}

/** Replace all links with those of a complete solution given as a description. */
function applySolution(s: SignpostState, desc: string): SignpostState | null {
  const p = parseDesc(desc, s.w, s.h);
  if (typeof p === 'string') return null;
  const where = new Int32Array(s.n + 1).fill(-1);
  for (let i = 0; i < s.n; i++) {
    if (p.dirs[i] !== s.dirs[i] || p.given[i] === 0) return null;
    where[p.given[i]] = i;
  }
  const b = boardOf(s);
  for (let i = 0; i < s.n; i++) b.unlink(i);
  for (let k = 1; k < s.n; k++) {
    if (!b.rays[where[k]].includes(where[k + 1])) return null;
    b.link(where[k], where[k + 1]);
  }
  return stateOf(b, s.dirs, s.immutable, true);
}

export function applyMove(s: SignpostState, move: string): SignpostState | null {
  if (move[0] === 'S') return applySolution(s, move.slice(1));
  let m = /^L(\d+),(\d+)-(\d+),(\d+)$/.exec(move);
  if (m) {
    const [fx, fy, tx, ty] = m.slice(1).map((v) => parseInt(v, 10));
    if (!inBounds(fx, fy, s.w, s.h) || !inBounds(tx, ty, s.w, s.h)) return null;
    const b = boardOf(s);
    const from = fy * s.w + fx;
    const to = ty * s.w + tx;
    if (!b.isValidMove(false, from, to)) return null;
    b.link(from, to);
    return stateOf(b, s.dirs, s.immutable, s.usedSolve);
  }
  m = /^([CX])(\d+),(\d+)$/.exec(move);
  if (m) {
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    if (!inBounds(x, y, s.w, s.h)) return null;
    const i = y * s.w + x;
    if (!hasLinks(s, i)) return null;
    const b = boardOf(s);
    if (m[1] === 'C') b.unlink(i);
    else b.unlinkChain(i);
    const next = stateOf(b, s.dirs, s.immutable, s.usedSolve);
    // Links between two given consecutive numbers join up again at once, so cutting a
    // square held only by those changes nothing — and must not become an empty Undo step.
    const same = (a: number[], c: number[]) => a.every((v, k) => v === c[k]);
    if (same(next.next, s.next) && same(next.prev, s.prev) && same(next.nums, s.nums)) return s;
    return next;
  }
  return null;
}

/** What releasing the current drag at canvas position (mx, my) would do, if anything. */
function dropMove(s: SignpostState, ui: SignpostUI, ds: DrawState, mx: number, my: number) {
  const t = ds.tileSize;
  const bd = border(t);
  const x = Math.floor((mx - bd) / t);
  const y = Math.floor((my - bd) / t);
  const { sx, sy } = ui;
  const si = sy * s.w + sx;
  // The Break tool turns the left button's unlinking into breaking up the whole chain.
  const breaks = ui.dragFrom && ui.breakChain;
  if (x === sx && y === sy) {
    // A plain click. With the right button (or the Break tool) it clears the square's links.
    if (!hasLinks(s, si)) return null;
    return breaks ? `X${sx},${sy}` : !ui.dragFrom ? `C${sx},${sy}` : null;
  }
  if (!inBounds(x, y, s.w, s.h)) {
    // Dragged off the board: unlink the square (left) or its whole chain (right).
    if (!hasLinks(s, si)) return null;
    return ui.dragFrom && !breaks ? `C${sx},${sy}` : `X${sx},${sy}`;
  }
  return ui.dragFrom ? linkMove(s, sx, sy, x, y) : linkMove(s, x, y, sx, sy);
}

// ------------------------------------------------------------------ drawing bits

function drawArrow(
  dr: Drawing,
  cx: number,
  cy: number,
  t: number,
  dir: number,
  spin: number,
  colour: string,
  alpha: number,
  seed: number,
): void {
  const a = (dir * Math.PI) / 4 + spin;
  const ux = Math.sin(a);
  const uy = -Math.cos(a);
  const len = t * 0.2;
  dr.arrow(
    cx - ux * len,
    cy - uy * len,
    cx + ux * len,
    cy + uy * len,
    colour,
    Math.max(1.6, t * 0.06),
    t * 0.16,
    { seed, alpha },
  );
}

function drawStar(dr: Drawing, cx: number, cy: number, r: number, spin: number, seed: number) {
  const pts: number[] = [];
  for (let k = 0; k < 10; k++) {
    const a = spin + (k * Math.PI) / 5;
    const rr = k % 2 ? r * 0.45 : r;
    pts.push(cx + Math.sin(a) * rr, cy - Math.cos(a) * rr);
  }
  dr.polygon(pts, 'pencil', 'pencil', { seed, width: 1.2 });
}

// ------------------------------------------------------------------ the game

const game = defineGame<SignpostParams, SignpostState, SignpostUI>({
  id: 'signpost',
  name: 'Signpost',
  description: 'Link the squares into one numbered path, each step following an arrow.',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: [
    { name: '4×4', params: { w: 4, h: 4, corners: true } },
    { name: '4×4, free ends', params: { w: 4, h: 4, corners: false } },
    { name: '5×5', params: { w: 5, h: 5, corners: true } },
    { name: '5×5, free ends', params: { w: 5, h: 5, corners: false } },
    { name: '6×6', params: { w: 6, h: 6, corners: true } },
    { name: '7×7', params: { w: 7, h: 7, corners: true } },
  ],
  defaultParams: () => ({ w: 4, h: 4, corners: true }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full && p.corners ? 'c' : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(c?)/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    return { w, h, corners: m[3] === 'c' };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w === 2 && p.h === 2) return tx`Width and height cannot both be two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'boolean', name: 'Start and end in corners', value: p.corners },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (s: string) => (/^-?\d+$/.test(s.trim()) ? parseInt(s, 10) : NaN);
    const w = int((items[0] as { value: string }).value);
    const h = int((items[1] as { value: string }).value);
    const corners = (items[2] as { value: boolean }).value;
    return { w, h, corners };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const puzzle = parseDesc(desc, p.w, p.h) as Puzzle;
    const b = new Board(puzzle);
    const immutable = Array.from(b.immutable);
    return stateOf(b, puzzle.dirs, immutable, false);
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    // The generator's answer, if it fits this puzzle.
    if (aux) {
      const s = applySolution(curr, aux);
      if (s && s.completed) return `S${aux}`;
    }
    // Deduce from the player's position, then from scratch.
    const puzzle = puzzleOf(curr);
    for (const b of [boardOf(curr), new Board(puzzle)]) {
      if (solveBoard(b) === SOLVED) return `S${encodeDesc(curr.dirs, b.nums)}`;
    }
    // Last resort for descriptions the deductions cannot finish.
    const r = searchSolutions(puzzle, 1, 200000);
    if (r.solutions.length) return `S${encodeDesc(curr.dirs, r.solutions[0])}`;
    throw new Error(
      r.exhausted ? tx`This puzzle has no solution` : tx`Unable to solve this puzzle`,
    );
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const row: string[] = [];
      for (let x = 0; x < s.w; x++) {
        const i = y * s.w + x;
        const label = s.nums[i] ? labelFor(s.nums[i], s.n) : '';
        row.push((label + DIR_NAMES[s.dirs[i]]).padStart(6, ' '));
      }
      rows.push(row.join(''));
    }
    return rows.join('\n');
  },

  newUI: () => ({
    cx: 0,
    cy: 0,
    cursorVisible: false,
    dragging: false,
    dragFrom: true,
    sx: 0,
    sy: 0,
    dx: 0,
    dy: 0,
    breakChain: false,
  }),
  changedState(ui, _old, next) {
    ui.dragging = false;
    if (next.completed) ui.cursorVisible = false;
  },

  actions: [
    {
      label: 'Break',
      key: 'B',
      hud: true,
      glyph: BREAK_GLYPH,
      pressed: (_s, ui) => ui.breakChain,
      title: 'Click a square to break up its whole chain (B)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const ch = keyChar(b);
    if (ch === 'b' || ch === 'B') {
      ui.breakChain = !ui.breakChain;
      return '';
    }
    const { w, h } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const x = Math.floor((mx - bd) / t);
    const y = Math.floor((my - bd) / t);
    const centre = (cx: number, cy: number) => ({ x: bd + cx * t + t / 2, y: bd + cy * t + t / 2 });

    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      if (ui.dragging) {
        const c = centre(ui.cx, ui.cy);
        ui.dx = c.x;
        ui.dy = c.y;
      }
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const ci = ui.cy * w + ui.cx;
      if (ui.dragging) {
        // Second press: finish the link at the cursor.
        ui.dragging = false;
        if (ui.sx === ui.cx && ui.sy === ui.cy) return '';
        return (
          (ui.dragFrom
            ? linkMove(state, ui.sx, ui.sy, ui.cx, ui.cy)
            : linkMove(state, ui.cx, ui.cy, ui.sx, ui.sy)) ?? ''
        );
      }
      if (b === CURSOR_SELECT2) return hasLinks(state, ci) ? `C${ui.cx},${ui.cy}` : '';
      ui.dragging = true;
      ui.dragFrom = true;
      ui.sx = ui.cx;
      ui.sy = ui.cy;
      const c = centre(ui.cx, ui.cy);
      ui.dx = c.x;
      ui.dy = c.y;
      return '';
    }
    if (isMouseDown(b)) {
      const hadUI = ui.cursorVisible || ui.dragging;
      ui.cursorVisible = false;
      ui.dragging = false;
      if (b === MIDDLE_BUTTON || !inBounds(x, y, w, h)) return hadUI ? '' : null;
      ui.dragging = true;
      ui.dragFrom = b === LEFT_BUTTON;
      ui.sx = x;
      ui.sy = y;
      ui.dx = mx;
      ui.dy = my;
      return '';
    }
    if (isMouseDrag(b)) {
      if (!ui.dragging) return null;
      ui.dx = mx;
      ui.dy = my;
      return '';
    }
    if (isMouseRelease(b)) {
      if (!ui.dragging) return null;
      ui.dragging = false;
      return dropMove(state, ui, ds, mx, my) ?? '';
    }
    if ((ch === 'x' || ch === 'X') && ui.cursorVisible) {
      if (!hasLinks(state, ui.cy * w + ui.cx)) return '';
      return `${ch === 'x' ? 'C' : 'X'}${ui.cx},${ui.cy}`;
    }
    return null;
  },

  executeMove: applyMove,

  preferredTileSize: 48,
  computeSize(p, t) {
    const bd = border(t);
    return { w: p.w * t + 2 * bd, h: p.h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, n } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const X = (x: number) => bd + x * t;
    const Y = (y: number) => bd + y * t;
    const spin = flashTime > 0 ? (2 * Math.PI * flashTime) / FLASH : 0;

    // While a drag would make a valid link, show the board as it would then look.
    let shown = state;
    if (ui.dragging) {
      const mv = dropMove(state, ui, ds, ui.dx, ui.dy);
      if (mv && mv[0] === 'L') shown = applyMove(state, mv) ?? state;
    }
    const src = ui.dragging ? ui.sy * w + ui.sx : -1;
    let board: Board | null = null;
    if (ui.dragging) board = boardOf(state);

    // Backgrounds: the ends of the path, and the squares a drag may legally reach.
    for (let i = 0; i < n; i++) {
      const px = X(i % w);
      const py = Y(Math.floor(i / w));
      if (state.immutable[i] && (state.nums[i] === 1 || state.nums[i] === n))
        dr.rect(px, py, t, t, 'shade');
      if (board && i !== src) {
        const ok = ui.dragFrom
          ? board.isValidMove(false, src, i)
          : board.isValidMove(false, i, src);
        if (ok) dr.rect(px, py, t, t, dr.withAlpha('accent', 0.12));
      }
    }
    for (let x = 1; x < w; x++) dr.line(X(x), Y(0), X(x), Y(h), 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(X(0), Y(y), X(w), Y(y), 'faint', 1.2);

    // Links, drawn underneath the arrows and numbers.
    for (let i = 0; i < n; i++) {
      const j = shown.next[i];
      if (j === -1) continue;
      const fresh = state.next[i] !== j;
      dr.line(
        X(i % w) + t / 2,
        Y(Math.floor(i / w)) + t / 2,
        X(j % w) + t / 2,
        Y(Math.floor(j / w)) + t / 2,
        fresh ? 'accent' : 'blue',
        t * 0.08,
        { alpha: fresh ? 0.45 : 0.28, seed: i },
      );
    }

    for (let i = 0; i < n; i++) {
      const px = X(i % w);
      const py = Y(Math.floor(i / w));
      const num = shown.nums[i];
      const given = state.immutable[i] === 1;
      const acx = px + t * 0.64;
      const acy = py + t * 0.66;
      if (given && num === n) {
        drawStar(dr, acx, acy, t * 0.2, spin, i);
      } else {
        const linked = shown.next[i] !== -1;
        drawArrow(
          dr,
          acx,
          acy,
          t,
          state.dirs[i],
          spin,
          i === src ? 'accent' : 'pencil',
          linked && i !== src ? 0.3 : 1,
          i,
        );
      }
      // A square still waiting for its predecessor carries a dot.
      if (shown.prev[i] === -1 && num !== 1)
        dr.dot(px + t * 0.2, py + t * 0.74, t * 0.05, 'pencil');
      if (num !== 0 || hasLinks(shown, i)) {
        const bad = shown.error[i] === 1;
        const text = bad && num > n ? String(num) : labelFor(num, n);
        const real = num >= 1 && num <= n;
        const colour = bad
          ? 'error'
          : flashTime > 0
            ? 'ok'
            : given
              ? 'ink'
              : real
                ? 'blue'
                : 'pencil';
        dr.text(px + t * 0.09, py + t * 0.24, text, {
          size: t * 0.34,
          colour,
          align: 'left',
          bold: given,
          maxWidth: t * 0.82,
        });
      }
    }
    dr.rectOutline(bd, bd, w * t, h * t, 'ink', { width: 2.6 });

    if (ui.cursorVisible) {
      const inset = t * 0.08;
      dr.cursor(X(ui.cx) + inset, Y(ui.cy) + inset, t - 2 * inset, t - 2 * inset);
    }
    if (ui.dragging) {
      const pad = Math.max(2, t * 0.05);
      dr.rectOutline(X(ui.sx) + pad, Y(ui.sy) + pad, t - 2 * pad, t - 2 * pad, 'accent', {
        width: 2,
      });
      const cx = X(ui.sx) + t / 2;
      const cy = Y(ui.sy) + t / 2;
      const lw = Math.max(2, t * 0.05);
      if (ui.dragFrom) dr.arrow(cx, cy, ui.dx, ui.dy, 'accent', lw, t * 0.22, { rough: 0.5 });
      else dr.arrow(ui.dx, ui.dy, cx, cy, 'accent', lw, t * 0.22, { rough: 0.5 });
      const offBoard = !inBounds(Math.floor((ui.dx - bd) / t), Math.floor((ui.dy - bd) / t), w, h);
      if (offBoard && hasLinks(state, src)) dr.cross(ui.dx, ui.dy, t * 0.12, 'error', lw);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !newState.usedSolve ? FLASH : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
