import { gameplayStart, gameplayStop, inviteParams } from '../crazygames';
import { getGame } from '../games/registry';
import { deskCamera, mountDesk, pageIn, pageOut, type PageTurn } from './anim';
import {
  CLOSE_FADE_MS,
  OPEN_FADE_MS,
  flyClose,
  flyOpen,
  type CloseFlight,
  type OpenFlight,
} from './flight';
import { rememberBoard } from './thumbnail';
import { cancelAllModals, toast } from './dialogs';
import { renderGameView } from './gameView';
import { renderMenu } from './menu';
import { renderAchievementsPage } from './achievementsPage';
import { markWelcomed, needsWelcome, renderWelcome } from './welcome';
import { isUnlocked } from './progress';
import { backButton } from './backButton';
import {
  applyLocaleToDocument,
  gameName,
  getLocale,
  localeFromUrl,
  onLocaleChange,
  setLocaleAsync,
  t,
} from '../i18n';

interface Mounted {
  destroy(): void;
  /** The play page's game, for what the way back needs to know about the board. */
  midend?: { hasGame: boolean; status(): number; solvedByPlayer(): boolean };
  /** A tutorial's board is on show, not the player's own. */
  readonly tutorialActive?: boolean;
  /** The collection's word that the card being returned to is back in the box. */
  landed?(): void;
}

/** A journey in the air across a page swap: the flight and which way it is going. */
type Journey = { kind: 'open'; flight: OpenFlight } | { kind: 'close'; flight: CloseFlight };

/**
 * Split `#/<game>/<id>` into its two halves. A trailing `?...` is stripped first (e.g.
 * `?lang=ar` placed after the hash, which `docs/I18N.md` documents as valid): the app
 * never puts a raw `?` in a route itself — a game id is always percent-encoded before it
 * reaches the hash — so this only ever removes a query-like suffix, never part of a real
 * route. An empty `slug` is the menu.
 */
export function parseHash(hash = location.hash): { slug: string; rest: string } {
  const raw = hash.replace(/^#\/?/, '');
  const qIndex = raw.indexOf('?');
  const path = qIndex >= 0 ? raw.slice(0, qIndex) : raw;
  const slash = path.indexOf('/');
  return {
    slug: slash >= 0 ? path.slice(0, slash) : path,
    rest: slash >= 0 ? path.slice(slash + 1) : '',
  };
}

/**
 * The other half of the platform's share link (see `inviteLink` in `src/crazygames`). An
 * invite arrives as the game's own page on the portal plus a bag of parameters, never as a
 * URL carrying our hash, so the route it stands for has to be rebuilt here.
 *
 * Only ever acted on while the player is still on the menu they landed on: the SDK settles
 * a moment after boot, by which time they may already have picked something, and a link
 * must never pull anyone out of a puzzle they chose themselves. Off-platform
 * `inviteParams` resolves empty, so this does nothing at all.
 */
async function followInvite(): Promise<void> {
  const { puzzle, id } = await inviteParams(['puzzle', 'id']);
  if (!puzzle || !getGame(puzzle)) return;
  if (parseHash().slug) return;
  location.hash = id ? `#/${puzzle}/${encodeURIComponent(id)}` : `#/${puzzle}`;
}

/**
 * Hash router: `#/` is the menu, `#/<game>` plays, `#/<game>/<id>` opens a puzzle.
 *
 * Every swap is a short journey rather than a cut. Picking a card lifts it out of the box
 * and turns it over into the sheet the puzzle is played on, and going back puts the sheet
 * back into its slot (flight.ts); the page swap happens underneath, while the slip is in
 * the air. Where there is no card to fly — one not on screen, or less motion asked for —
 * the old beat stands in: see `pageOut` for why its two halves happen one after the other.
 */
export function startApp(root: HTMLElement): void {
  mountDesk();
  let current: Mounted | null = null;
  /** Which slug the mounted page is showing, so a re-mount can be told from a journey. */
  let shown: string | null = null;
  /** The exit of the page being left behind, while it is under way. */
  let leaving: { kill(): void } | null = null;
  /** A flight that has not landed yet, from the moment it takes off. */
  let airborne: Journey | null = null;

  /**
   * Tear the old page down and put the new one up. Always the second half of `route`.
   * `journey` is the flight the page is being mounted under, which lands on it.
   */
  function mount(turn: PageTurn, journey: Journey | null = null) {
    leaving = null;
    /** The flight, if it is going to the kind of page that has turned out to be mounted. */
    const take = <K extends Journey['kind']>(kind: K) => {
      if (journey?.kind === kind) return journey as Extract<Journey, { kind: K }>;
      journey?.flight.cancel();
      return null;
    };
    document.documentElement.classList.remove('turning');
    const { slug, rest } = parseHash();
    cancelAllModals();
    current?.destroy();
    current = null;
    root.innerHTML = '';
    // The document does not scroll; #app does (see styles.css), so a new page starts at
    // the top only if the scroller itself is sent back there.
    root.scrollTop = 0;
    /** `arriving` is what has just been mounted, which is not always what was asked for. */
    const enter = (arriving: PageTurn) => {
      // The camera ends up over the page that arrived: in close over a puzzle, back over
      // the box for everything else. A journey has already set it moving (`route`).
      deskCamera(arriving === 'open', { animate: turn !== 'none' });
      if (root.firstElementChild)
        pageIn(root.firstElementChild, turn === 'none' ? 'none' : arriving);
    };
    if (!slug) {
      shown = '';
      gameplayStop();
      // A first visit asks which puzzle to start with instead of showing the whole shelf.
      if (needsWelcome()) {
        take('open');
        current = renderWelcome(root, () => mount('none'));
        enter('close');
        return;
      }
      const back = take('close');
      const returning = back ? journeySlug : undefined;
      const menu = renderMenu(root, { returning });
      current = menu;
      if (!back) {
        enter('close');
        return;
      }
      const page = root.firstElementChild as HTMLElement;
      const card = page.querySelector<HTMLElement>(`.card[data-slug="${CSS.escape(returning!)}"]`);
      back.flight.arrive(
        page,
        card && !card.hidden && !card.classList.contains('off-page') ? card : null,
        () => menu.landed(),
      );
      return;
    }
    if (slug === 'achievements') {
      take('open');
      shown = slug;
      gameplayStop();
      current = renderAchievementsPage(root, rest);
      enter('none');
      return;
    }
    const game = getGame(slug);
    if (!game) {
      take('open');
      shown = slug;
      gameplayStop();
      const p = document.createElement('div');
      p.className = 'not-found';
      const h1 = document.createElement('h1');
      h1.textContent = t('ui.notFound.title');
      const body = document.createElement('p');
      body.textContent = t('ui.notFound.body', { slug });
      const back = document.createElement('p');
      back.className = 'not-found-back';
      back.append(backButton(t('ui.notFound.back')));
      p.append(back, h1, body);
      root.append(p);
      current = { destroy: () => p.remove() };
      enter('none');
      return;
    }
    // A link to one particular puzzle is a friend's invitation, not a way round the shelf:
    // turning a newcomer away from the very board they were sent — "still locked", on the
    // first screen they ever see — is the one outcome a share link must not have. It opens
    // that puzzle and unlocks nothing; the bare `#/<game>` route stays behind its credit.
    if (!isUnlocked(game.id) && !rest) {
      take('open');
      toast(t('ui.locked', { name: gameName(game) }));
      history.replaceState(null, '', '#/');
      shown = '';
      gameplayStop();
      current = renderMenu(root);
      enter('close');
      return;
    }
    shown = slug;
    let id: string | null = null;
    if (rest) {
      try {
        id = decodeURIComponent(rest);
      } catch {
        id = rest;
      }
    }
    const into = take('open');
    const view = renderGameView(root, game, id);
    current = view;
    // Arriving in a puzzle, by the welcome or by a link, is a first launch done.
    markWelcomed();
    if (into) {
      const page = root.firstElementChild as HTMLElement;
      into.flight.arrive(page, view.midend.hasGame ? page.querySelector('.canvas-wrap') : null);
    } else {
      enter('open');
    }
    // Tell the platform the player is actively playing (pairs with the gameplayStop()
    // calls above); a no-op off-platform. See docs/CRAZYGAMES.md.
    gameplayStart();
  }

  /** The game the journey in the air is to or from. */
  let journeySlug = '';

  /** Set a flight going, and swap the pages under it once the old one has faded. */
  function takeOff(journey: Journey, slug: string, fadeMs: number, turn: PageTurn) {
    airborne = journey;
    journeySlug = slug;
    void journey.flight.done.then(() => {
      if (airborne === journey) airborne = null;
    });
    const timer = window.setTimeout(() => mount(turn, journey), fadeMs);
    leaving = {
      kill() {
        clearTimeout(timer);
        journey.flight.cancel();
      },
    };
  }

  function route() {
    const { slug } = parseHash();
    const outgoing = root.firstElementChild as HTMLElement | null;
    // A second navigation while the first is still on its way out — a fast double click,
    // or Back pressed as the card lifts. Drop what is in flight and land on the newest
    // route rather than queueing one journey behind another.
    if (leaving) {
      leaving.kill();
      mount('none');
      return;
    }
    // One still coming down on the page that is up — Back pressed while the card is
    // landing — is put down at once, so the way out starts from a page that is all there.
    airborne?.flight.cancel();
    airborne = null;
    // Nothing to leave (the first route of the session), or the same page re-mounting
    // itself after a language switch, which is not a journey.
    if (!outgoing || slug === shown) {
      mount('none');
      return;
    }
    // Only the trip between the collection and a puzzle is a journey — it is the one the
    // player actually makes, and the only one with a card to fly. One
    // puzzle replaced by another, which can only happen through the address bar, is the
    // plain swap it has always been.
    const turn: PageTurn = shown === '' ? 'open' : slug ? 'none' : 'close';
    if (turn === 'none') {
      mount('none');
      return;
    }
    // Which card is being opened, so it can be lifted out of the box — or, failing a
    // flight, so the grid can zoom about it. Absent for a puzzle reached by its own URL.
    const focus =
      turn === 'open'
        ? outgoing.querySelector<HTMLElement>(`.card[data-slug="${CSS.escape(slug)}"]`)
        : null;
    if (turn === 'close') {
      // The card goes back showing the board as it was left (thumbnail.ts), so it is
      // copied now, while it is still on the page.
      const board = outgoing.querySelector<HTMLCanvasElement>('.puzzle-canvas');
      const md = current?.midend;
      if (board && md?.hasGame && !current?.tutorialActive)
        rememberBoard(shown!, board, md.status() > 0 && md.solvedByPlayer());
    }
    document.documentElement.classList.add('turning');
    const f = focus?.getBoundingClientRect();
    const origin = f ? { x: f.left + f.width / 2, y: f.top + f.height / 2 } : undefined;
    const open = focus ? flyOpen(focus, outgoing, slug) : null;
    if (open) {
      deskCamera(true, { origin });
      takeOff({ kind: 'open', flight: open }, slug, OPEN_FADE_MS, turn);
      return;
    }
    const wrap =
      turn === 'close' && current?.midend?.hasGame
        ? outgoing.querySelector<HTMLElement>('.canvas-wrap')
        : null;
    const close = wrap ? flyClose(outgoing, wrap, shown!) : null;
    if (close) {
      deskCamera(false);
      takeOff({ kind: 'close', flight: close }, shown!, CLOSE_FADE_MS, turn);
      return;
    }
    // No flight: the camera still leans in towards the card as the collection zooms about
    // it, and sits back as the board goes — the desk under both is the one surface.
    deskCamera(turn === 'open', { origin });
    const out = pageOut(outgoing, turn, focus, () => mount(turn));
    leaving = out ? { kill: () => out.kill() } : null;
  }

  // `?lang=` after the hash is read at boot, so an address edited to carry a new one (or a
  // link followed inside the page) would otherwise keep the old language: switch first,
  // and the locale change re-routes, already translated. Like at boot, not remembered.
  window.addEventListener('hashchange', () => {
    const wanted = localeFromUrl();
    if (wanted && wanted !== getLocale()) {
      // A switch re-routes by itself (`onLocaleChange`); one that could not happen — the
      // catalogue failed to arrive — must still take the player where the link points.
      const before = getLocale();
      setLocaleAsync(wanted, { persist: false }).then(() => {
        if (getLocale() === before) route();
      }, route);
      return;
    }
    route();
  });
  void followInvite();
  // Switching language re-mounts the current page, which is enough reactivity: every
  // component reads `t()` while it renders, and the game view restores the puzzle it
  // just saved, so the board and move history survive the swap.
  onLocaleChange(() => {
    applyLocaleToDocument();
    route();
  });
  route();
}
