/**
 * Deductive Bridges solver.
 *
 * The solver works on a `Work`: for every edge of the layout it tracks how many bridges
 * are certainly there (`cnt`) and how many there can be at most (`max`), plus a
 * union–find of which islands are already joined. Three tiers of reasoning, one per
 * difficulty, are applied in rounds until nothing changes:
 *
 *  - **Easy** looks at one island at a time: if its remaining bridges exactly fill the
 *    room left around it, they all go in; if its number is too big to be met while
 *    skipping any neighbour, every neighbour gets at least one bridge.
 *  - **Medium** looks at individual connections: an edge whose absence would leave the
 *    island unable to reach its number must carry a bridge, and (with loops forbidden)
 *    an edge between islands that are already joined can carry none.
 *  - **Hard** tries things: giving an edge one more bridge and seeing whether that
 *    strands a finished group or makes some island impossible caps the edge below that
 *    count; and if sending everything an island still needs *away* from one edge would
 *    strand a finished group, that edge must get a bridge.
 *
 * Every step is a sound deduction, so a puzzle the solver finishes has exactly one
 * solution. For the Solve button `solveAny` falls back to a small bounded search when
 * deduction alone gets stuck.
 */
import { DSF } from '../../framework/dsf';
import { Layout } from './board';

export const DIFF_EASY = 0;
export const DIFF_MEDIUM = 1;
export const DIFF_HARD = 2;
export const DIFFICULTY_NAMES = ['Easy', 'Medium', 'Hard'];

/** Mutable solving state over a layout. */
export class Work {
  /** Bridges certainly present on each edge. */
  cnt: Uint8Array;
  /** Most bridges each edge may still end up with (0 = never a bridge here). */
  max: Uint8Array;
  dsf: DSF;
  dead = false;

  constructor(readonly L: Layout) {
    const m = L.edges.length;
    this.cnt = new Uint8Array(m);
    this.max = new Uint8Array(m);
    for (let e = 0; e < m; e++) {
      const { a, b } = L.edges[e];
      this.max[e] = Math.min(L.maxb, L.islands[a].clue, L.islands[b].clue);
    }
    this.dsf = new DSF(L.islands.length);
  }

  clone(): Work {
    // Skip the constructor: the Hard tier clones for every trial bridge, and building a
    // fresh union–find only to throw it away dominated big maps' solving time.
    const w: Work = Object.create(Work.prototype);
    Object.assign(w, {
      L: this.L,
      cnt: this.cnt.slice(),
      max: this.max.slice(),
      dsf: this.dsf.clone(),
      dead: this.dead,
    });
    return w;
  }

  count(i: number): number {
    let c = 0;
    for (const e of this.L.islands[i].edges) if (e >= 0) c += this.cnt[e];
    return c;
  }

  missing(i: number): number {
    return this.L.islands[i].clue - this.count(i);
  }

  /** Most bridges edge `e` can carry in total, as seen from island `i`. */
  effMax(e: number, i: number): number {
    const j = this.L.other(e, i);
    return Math.min(this.max[e], this.cnt[e] + Math.max(0, this.missing(j)));
  }

  /** Extra bridges island `i` could still send along `e`. */
  cap(e: number, i: number): number {
    return Math.max(0, this.effMax(e, i) - this.cnt[e]);
  }

  /** Raise the bridge count on `e` to `n` (never lowers it). */
  setCount(e: number, n: number): void {
    if (n <= this.cnt[e]) return;
    if (n > this.max[e]) this.dead = true;
    if (this.cnt[e] === 0) {
      const { a, b, cross } = this.L.edges[e];
      if (!this.L.allowLoops && this.dsf.same(a, b)) this.dead = true;
      for (const c of cross) {
        if (this.cnt[c] > 0) this.dead = true;
        this.max[c] = 0;
      }
      this.dsf.merge(a, b);
    }
    this.cnt[e] = n;
  }

  /** Lower the maximum on `e` to `m` (never raises it). */
  setMax(e: number, m: number): void {
    if (m >= this.max[e]) return;
    this.max[e] = m;
    if (this.cnt[e] > m) this.dead = true;
  }

  /** Island `i` has too many bridges, or no longer enough room for the rest. */
  impossible(i: number): boolean {
    const missing = this.missing(i);
    if (missing < 0) return true;
    let room = 0;
    for (const e of this.L.islands[i].edges) if (e >= 0) room += this.cap(e, i);
    return room < missing;
  }

  /**
   * `impossible` for every island that raising the count on edge `e` can affect: its two
   * ends, their neighbours (whose room depends on what the ends still need) and the ends
   * of the edges it crosses. From a state where no island was impossible this answers the
   * same as checking every island, at a fraction of the cost on a big map.
   */
  impossibleNear(e: number): boolean {
    const { L } = this;
    const { a, b, cross } = L.edges[e];
    for (const i of [a, b]) {
      if (this.impossible(i)) return true;
      for (const f of L.islands[i].edges) if (f >= 0 && this.impossible(L.other(f, i))) return true;
    }
    for (const c of cross) {
      if (this.impossible(L.edges[c].a) || this.impossible(L.edges[c].b)) return true;
    }
    return false;
  }

  /**
   * The group containing island `i` consists only of finished islands yet is not the
   * whole puzzle — it can never be joined to the rest.
   */
  strandedGroup(i: number): boolean {
    const n = this.L.islands.length;
    const root = this.dsf.find(i);
    let size = 0;
    for (let j = 0; j < n; j++) {
      if (this.dsf.find(j) !== root) continue;
      if (this.missing(j) !== 0) return false;
      size++;
    }
    return size < n;
  }

  solved(): boolean {
    if (this.dead) return false;
    const n = this.L.islands.length;
    for (let i = 0; i < n; i++) if (this.missing(i) !== 0) return false;
    if (this.dsf.count() !== 1) return false;
    if (!this.L.allowLoops) {
      let used = 0;
      for (let e = 0; e < this.cnt.length; e++) if (this.cnt[e] > 0) used++;
      if (used !== n - 1) return false;
    }
    return true;
  }
}

// ------------------------------------------------------------------ the tiers

/** Easy: reasoning about one island at a time. */
function stage1(work: Work): boolean {
  const { L } = work;
  let did = false;
  for (let i = 0; i < L.islands.length; i++) {
    const is = L.islands[i];
    const missing = work.missing(i);
    if (missing < 0) {
      work.dead = true;
      return false;
    }
    if (missing === 0) continue;
    let room = 0;
    let nadj = 0;
    for (const e of is.edges) {
      if (e < 0) continue;
      const c = work.cap(e, i);
      room += c;
      if (c > 0 || work.cnt[e] > 0) nadj++;
    }
    if (room < missing) {
      work.dead = true;
      return false;
    }
    if (room === missing) {
      // Everything that can still be placed must be.
      for (const e of is.edges) {
        if (e < 0) continue;
        const c = work.cap(e, i);
        if (c > 0) {
          work.setCount(e, work.cnt[e] + c);
          did = true;
        }
      }
    } else if (is.clue > (nadj - 1) * L.maxb) {
      // Skipping any one neighbour would leave too few bridges: one in every direction.
      for (const e of is.edges) {
        if (e < 0 || work.cnt[e] > 0 || work.cap(e, i) === 0) continue;
        work.setCount(e, 1);
        did = true;
      }
    }
    if (work.dead) return false;
  }
  return did;
}

/** Medium: reasoning about individual connections. */
function stage2(work: Work): boolean {
  const { L } = work;
  let did = false;
  for (let i = 0; i < L.islands.length; i++) {
    const is = L.islands[i];
    if (work.missing(i) <= 0) continue;
    if (!L.allowLoops) {
      for (const e of is.edges) {
        if (e < 0 || work.cnt[e] > 0 || work.max[e] === 0) continue;
        const { a, b } = L.edges[e];
        if (work.dsf.same(a, b)) {
          work.setMax(e, 0);
          did = true;
        }
      }
    }
    let avail = 0;
    for (const e of is.edges) if (e >= 0) avail += work.effMax(e, i);
    for (const e of is.edges) {
      if (e < 0 || work.cnt[e] > 0) continue;
      const here = work.effMax(e, i);
      if (here > 0 && avail - here < is.clue) {
        work.setCount(e, 1);
        did = true;
      }
    }
    if (work.dead) return false;
  }
  return did;
}

/** Hard: trying a bridge and looking for a stranded group or an impossible island. */
function stage3(work: Work): boolean {
  const { L } = work;
  let did = false;
  for (let i = 0; i < L.islands.length; i++) {
    const is = L.islands[i];
    if (work.missing(i) <= 0) continue;

    // Cap each edge just below the first count that leads to trouble. Trouble only gets
    // worse with more bridges, so the first failure is the right place to stop.
    // Only the islands near the edge can turn impossible: stage 1 has just checked every
    // island, and each deduction since is sound, so the rest are still fine.
    for (const e of is.edges) {
      if (e < 0) continue;
      const curr = work.cnt[e];
      const c = work.cap(e, i);
      if (c === 0) continue;
      let newMax = -1;
      for (let n = curr + 1; n <= curr + c; n++) {
        const trial = work.clone();
        trial.setCount(e, n);
        if (trial.dead || trial.impossibleNear(e) || trial.strandedGroup(i)) {
          newMax = n - 1;
          break;
        }
      }
      if (newMax >= 0) {
        work.setMax(e, newMax);
        did = true;
      }
    }
    if (work.dead) return false;

    // If every other direction filled up exactly and that stranded a finished group,
    // this direction must get a bridge.
    for (const e of is.edges) {
      if (e < 0 || work.cnt[e] > 0 || work.cap(e, i) === 0) continue;
      const trial = work.clone();
      for (const f of is.edges) {
        if (f < 0 || f === e) continue;
        const c = work.cap(f, i);
        if (c > 0) trial.setCount(f, work.cnt[f] + c);
      }
      if (!trial.dead && trial.missing(i) === 0 && trial.strandedGroup(i)) {
        work.setCount(e, 1);
        did = true;
      }
    }
    if (work.dead) return false;
  }
  return did;
}

/**
 * Apply deductions up to the given difficulty until stuck. Returns true when the puzzle
 * is fully solved; on a contradiction `work.dead` is set.
 */
export function solveWork(work: Work, difficulty: number): boolean {
  for (;;) {
    if (work.dead) return false;
    if (stage1(work)) continue;
    if (work.dead || difficulty < DIFF_MEDIUM) break;
    if (stage2(work)) continue;
    if (work.dead || difficulty < DIFF_HARD) break;
    if (stage3(work)) continue;
    break;
  }
  return work.solved();
}

/** Solve a layout from scratch at a difficulty. */
export function solveLayout(L: Layout, difficulty: number): { solved: boolean; work: Work } {
  const work = new Work(L);
  return { solved: solveWork(work, difficulty), work };
}

/** Nodes the Solve fallback may explore before giving up. */
const SEARCH_BUDGET = 4000;

/**
 * Find a solution by deduction, guessing when deduction runs dry. Used only by the
 * Solve button, so puzzles typed in by hand can be solved even when they need it.
 */
export function solveAny(L: Layout): Work | null {
  let budget = SEARCH_BUDGET;
  const search = (work: Work): Work | null => {
    if (--budget < 0) return null;
    if (solveWork(work, DIFF_HARD)) return work;
    if (work.dead) return null;
    // Branch on the least open edge.
    let best = -1;
    let bestRange = Infinity;
    for (let e = 0; e < work.cnt.length; e++) {
      const range = work.max[e] - work.cnt[e];
      if (range > 0 && range < bestRange) {
        bestRange = range;
        best = e;
      }
    }
    if (best < 0) return null;
    for (let n = work.cnt[best]; n <= work.max[best]; n++) {
      const trial = work.clone();
      trial.setCount(best, n);
      trial.setMax(best, n);
      const r = search(trial);
      if (r) return r;
      if (budget < 0) return null;
    }
    return null;
  };
  return search(new Work(L));
}
