import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  KEY_BACKSPACE,
  LEFT_BUTTON,
  MOD_SHFT,
  RIGHT_BUTTON,
  isCursorMove,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { INK_TIME, changedAt, drawGrow, flashOn, popGrow } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { DIRS, E_DUP, checkGrid, cubeIndex, encodeSolution, parseDesc } from './board';
import type { Puzzle } from './board';
import { generate } from './generator';
import type { UnequalParams } from './generator';
import {
  DIFFICULTY_CHARS,
  DIFFICULTY_NAMES,
  DIFF_EASY,
  DIFF_EXTREME,
  DIFF_RECURSIVE,
  DIFF_SET,
  solvePuzzle,
} from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';
import { HIGHLIGHT_GLYPH, glyph } from '../../framework/glyphs';

export type { UnequalParams };

export interface UnequalState {
  order: number;
  adjacent: boolean;
  /** The fixed puzzle (givens and signs), shared between states. */
  puzzle: Puzzle;
  /** Digits in the grid, row-major, 0 for blank. */
  nums: Uint8Array;
  /** Pencil marks: hints[cubeIndex(o, x, y, n)] is set when digit n is pencilled at (x, y). */
  hints: Uint8Array;
  /** Error bits per cell (E_DUP and one bit per violated sign). */
  errors: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface UnequalUI {
  /** Selected cell. */
  hx: number;
  hy: number;
  /** Whether a cell is selected at all. */
  hshow: boolean;
  /** Typed digits become pencil marks rather than answers. */
  hpencil: boolean;
  /** The selection was last moved with the keyboard. */
  hcursor: boolean;
  /** A digit just went into the selected square: one click on it keeps it chosen. */
  hkept: boolean;
  /** The Highlight tool: every cell holding the digit last pointed at is picked out. */
  spot: boolean;
  /** The cell last clicked or moved to, whose digit Highlight picks out; -1 for none. */
  spotAt: number;
}

/**
 * A light bulb, the shell's own Hint face: this game's Hint is the one button a stuck
 * player reaches for, as the shell's is in the games that have one.
 */
const BULB_GLYPH = glyph(
  'M9 17.5h6M10 20.5h4M8.6 14.6A6 6 0 1 1 15.4 14.6c-.8.7-1.2 1.6-1.2 2.4H9.8c0-.8-.4-1.7-1.2-2.4Z',
);

const FLASH = 0.4;
const MIN_ORDER = 3;
const MAX_ORDER = 9;
const MODE_NAMES = ['Unequal', 'Adjacent'];

function geom(t: number) {
  const gap = Math.round(t * 0.5);
  const border = Math.round(t * 0.3);
  return { t, gap, border, pitch: t + gap };
}

function makeState(puzzle: Puzzle, nums: Uint8Array, hints: Uint8Array, cheated: boolean) {
  const { errors, complete } = checkGrid(puzzle, nums);
  return {
    order: puzzle.order,
    adjacent: puzzle.adjacent,
    puzzle,
    nums,
    hints,
    errors,
    completed: complete,
    cheated,
  };
}

/** The grid described by a solution string, or null if it is not a correct solution. */
function decodeSolution(state: UnequalState, move: string): Uint8Array | null {
  const { order: o, puzzle } = state;
  if (!/^S\d+$/.test(move) || move.length !== o * o + 1) return null;
  const nums = new Uint8Array(o * o);
  for (let i = 0; i < o * o; i++) {
    const v = move.charCodeAt(i + 1) - 48;
    if (v < 1 || v > o) return null;
    if (puzzle.given[i] && puzzle.given[i] !== v) return null;
    nums[i] = v;
  }
  return checkGrid(puzzle, nums).complete ? nums : null;
}

/** Which cell (if any) the point is in; the gaps between cells count as nothing. */
function cellAt(ds: DrawState, order: number, mx: number, my: number) {
  const { t, border, pitch } = geom(ds.tileSize);
  const rx = mx - border;
  const ry = my - border;
  if (rx < 0 || ry < 0) return null;
  const x = Math.floor(rx / pitch);
  const y = Math.floor(ry / pitch);
  if (x >= order || y >= order) return null;
  if (rx - x * pitch > t || ry - y * pitch > t) return null;
  return { x, y };
}

// ------------------------------------------------------------------ drawing bits

/** A sketched chevron in the gap beside a cell, pointing at the smaller neighbour. */
function drawChevron(
  dr: Drawing,
  cx: number,
  cy: number,
  dx: number,
  dy: number,
  t: number,
  gap: number,
  colour: string,
  seed: number,
) {
  const depth = gap * 0.28;
  const half = t * 0.2;
  const px = -dy;
  const py = dx;
  dr.polyline(
    [
      cx - dx * depth + px * half,
      cy - dy * depth + py * half,
      cx + dx * depth,
      cy + dy * depth,
      cx - dx * depth - px * half,
      cy - dy * depth - py * half,
    ],
    colour,
    Math.max(1.8, t * 0.07),
    { seed },
  );
}

/** Pencil marks laid out in a little grid, as in Solo. */
function drawHints(
  dr: Drawing,
  s: UnequalState,
  x: number,
  y: number,
  ox: number,
  oy: number,
  t: number,
  spot: number,
) {
  const o = s.order;
  const marks: number[] = [];
  for (let n = 1; n <= o; n++) if (s.hints[cubeIndex(o, x, y, n)]) marks.push(n);
  if (!marks.length) return;
  let hw = 1;
  while (hw * hw < marks.length) hw++;
  if (hw < 3) hw = 3;
  const hh = Math.max(2, Math.ceil(marks.length / hw));
  const hmax = Math.max(hw, hh);
  const size = t / ((hmax * (11 - hmax)) / 8);
  marks.forEach((n, j) => {
    const hx = j % hw;
    const hy = Math.floor(j / hw);
    dr.text(
      ox + ((4 * hx + 3) * t) / (4 * hw + 2),
      oy + ((4 * hy + 3) * t) / (4 * hh + 2),
      String(n),
      { size, colour: n === spot ? 'teal' : 'pencil', bold: n === spot },
    );
  });
}

/**
 * Difficulty words for the Type menu and the Custom dialog alike, in the solver's own
 * order. The generator's level names (`DIFFICULTY_NAMES`) are one step out of line with
 * this ladder — its "Extreme" is the menu's "Hard" — so showing them in the dialog made
 * the same word mean two different puzzles.
 */
const PRESET_DIFFICULTIES = ['Very Easy', 'Easy', 'Medium', 'Hard', 'Extreme'];

// ------------------------------------------------------------------ the game

/** The digit Highlight is picking out, or 0 when it is off or points at an empty cell. */
export function spotDigit(nums: Uint8Array, ui: UnequalUI): number {
  return ui.spot && ui.spotAt >= 0 && ui.spotAt < nums.length ? nums[ui.spotAt] : 0;
}

const game = defineGame<UnequalParams, UnequalState, UnequalUI>({
  id: 'unequal',
  name: 'Unequal',
  description: 'Complete the latin square so every greater-than sign holds.',
  alsoKnownAs: 'Futoshiki',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [4, DIFF_EASY, false],
      [5, DIFF_EASY, false],
      [5, DIFF_SET, false],
      [5, DIFF_SET, true],
      [5, DIFF_EXTREME, false],
      [6, DIFF_EASY, false],
      [6, DIFF_SET, false],
      [6, DIFF_SET, true],
      [6, DIFF_EXTREME, false],
      [7, DIFF_SET, false],
      [7, DIFF_SET, true],
      [7, DIFF_EXTREME, false],
    ] as [number, number, boolean][]
  ).map(([order, diff, adjacent]) => ({
    // Size and difficulty first: a phone's preset box shows only the start of the name.
    name: `${order}×${order} ${PRESET_DIFFICULTIES[diff]}${adjacent ? ' (Adjacent)' : ''}`,
    params: { order, diff, adjacent },
  })),
  defaultParams: () => ({ order: 4, diff: DIFF_EASY, adjacent: false }),
  encodeParams: (p, full) =>
    `${p.order}${p.adjacent ? 'a' : ''}${full ? `d${DIFFICULTY_CHARS[p.diff] ?? '?'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(a?)(d(.?))?/.exec(str);
    if (!m) throw new Error(tx`expected a grid size`);
    let diff = DIFF_EASY;
    if (m[3] !== undefined) {
      diff = DIFFICULTY_CHARS.indexOf(m[4] ?? '');
      if (diff < 0 || !m[4]) diff = DIFFICULTY_NAMES.length; // invalid; validateParams objects
    }
    return { order: parseInt(m[1], 10), adjacent: m[2] === 'a', diff };
  },
  validateParams(p) {
    if (!Number.isInteger(p.order) || !Number.isInteger(p.diff))
      return tx`Size and difficulty must be whole numbers`;
    if (p.order < MIN_ORDER || p.order > MAX_ORDER)
      return tx`Size must be between ${MIN_ORDER} and ${MAX_ORDER}`;
    if (p.diff < 0 || p.diff >= DIFFICULTY_NAMES.length) return tx`Unknown difficulty rating`;
    if (p.order < 5 && p.adjacent && p.diff >= DIFF_SET)
      return tx`Size must be at least 5 for Adjacent puzzles of this difficulty`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'choices', name: 'Mode', choices: MODE_NAMES, selected: p.adjacent ? 1 : 0 },
      { type: 'string', name: 'Size (s*s)', value: String(p.order) },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.diff },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const order = (items[1] as { value: string }).value.trim();
    return {
      adjacent: (items[0] as { selected: number }).selected === 1,
      order: /^-?\d+$/.test(order) ? parseInt(order, 10) : NaN,
      diff: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.order, p.adjacent);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const puzzle = parseDesc(desc, p.order, p.adjacent) as Puzzle;
    const o = p.order;
    const state = makeState(puzzle, puzzle.given.slice(), new Uint8Array(o * o * o), false);
    // Even a fully given grid starts as a game in progress.
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(orig, curr, aux) {
    if (aux && decodeSolution(curr, aux)) return aux;
    const nums = orig.puzzle.given.slice();
    if (solvePuzzle(orig.puzzle, nums, DIFF_RECURSIVE).status <= 0)
      throw new Error(tx`Unable to find a solution to this puzzle`);
    return encodeSolution(nums);
  },

  textFormat(s) {
    const { order: o, adjacent, puzzle, nums } = s;
    const rows: string[] = [];
    for (let y = 0; y < o; y++) {
      let row = '';
      for (let x = 0; x < o; x++) {
        const i = y * o + x;
        row += nums[i] ? String(nums[i]) : '.';
        if (x < o - 1) {
          if (adjacent) row += puzzle.flags[i] & DIRS[1].f ? '|' : ' ';
          else if (puzzle.flags[i] & DIRS[1].f) row += '>';
          else if (puzzle.flags[i + 1] & DIRS[3].f) row += '<';
          else row += ' ';
        }
      }
      rows.push(row);
      if (y < o - 1) {
        let sep = '';
        for (let x = 0; x < o; x++) {
          const i = y * o + x;
          if (adjacent) sep += puzzle.flags[i] & DIRS[2].f ? '-' : ' ';
          else if (puzzle.flags[i] & DIRS[2].f) sep += 'v';
          else if (puzzle.flags[i + o] & DIRS[0].f) sep += '^';
          else sep += ' ';
          if (x < o - 1) sep += ' ';
        }
        rows.push(sep);
      }
    }
    return rows.join('\n');
  },

  newUI: () => ({
    hx: 0,
    hy: 0,
    hshow: false,
    hpencil: false,
    hcursor: false,
    hkept: false,
    spot: false,
    spotAt: -1,
  }),
  changedState(ui, _old, next) {
    // A pencil selection on a cell that just got a digit (e.g. by undo) makes no sense,
    // and a finished puzzle needs no selection at all.
    if (ui.hshow && ui.hpencil && !ui.hcursor && next.nums[ui.hy * next.order + ui.hx])
      ui.hshow = false;
    if (next.completed) ui.hshow = false;
  },

  // One key per digit, a clear key and the pencil-mark latch, so a device without a
  // keyboard can still fill cells in.
  keypad: (p) => ({
    keys: Array.from({ length: p.order }, (_, i) => String(i + 1)),
    clear: true,
    pencil: true,
  }),
  actions: [
    { label: 'Marks', key: 'M', title: 'Pencil every possibility into every empty cell (M)' },
    {
      label: 'Hint',
      key: 'H',
      hud: true,
      glyph: BULB_GLYPH,
      title: 'Pencil in the possibilities easy reasoning leaves (H)',
    },
    {
      label: 'Highlight',
      key: 'L',
      hud: true,
      glyph: HIGHLIGHT_GLYPH,
      pressed: (_s, ui) => ui.spot,
      view: true,
      title: 'Pick out every cell holding the digit you last touched (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    // A click straight after a digit re-chooses the square that kept its selection rather
    // than deselecting it, so clicking a square before each digit still types.
    const kept = ui.hkept;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || isCursorMove(b)) ui.hkept = false;
    const { order: o, puzzle, nums } = state;
    if (b === 76 || b === 108) {
      ui.spot = !ui.spot;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const c = cellAt(ds, o, mx, my);
      if (!c) return null;
      const i = c.y * o + c.x;
      ui.spotAt = i;
      const same = ui.hshow && ui.hx === c.x && ui.hy === c.y;
      if (b === LEFT_BUTTON) {
        if (puzzle.given[i]) ui.hshow = false;
        else if (same && !ui.hpencil && !kept) ui.hshow = false;
        else {
          ui.hx = c.x;
          ui.hy = c.y;
          ui.hpencil = false;
          ui.hshow = true;
        }
      } else {
        if (nums[i]) ui.hshow = false;
        else if (same && ui.hpencil) ui.hshow = false;
        else {
          ui.hx = c.x;
          ui.hy = c.y;
          ui.hpencil = true;
          ui.hshow = true;
        }
      }
      ui.hcursor = false;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.hx, ui.hy, o, o);
      ui.hx = p.x;
      ui.hy = p.y;
      ui.spotAt = p.y * o + p.x;
      ui.hshow = ui.hcursor = true;
      return '';
    }
    if (ui.hshow && b === CURSOR_SELECT) {
      ui.hpencil = !ui.hpencil;
      ui.hcursor = true;
      return '';
    }
    const ch = keyChar(b);
    if (ui.hshow) {
      let n = -1;
      if (b === CURSOR_SELECT2 || b === KEY_BACKSPACE) n = 0;
      else if (ch !== null && ch >= '0' && ch <= '9') n = ch.charCodeAt(0) - 48;
      if (n >= 0 && n <= o) {
        // MOD_SHFT on a digit is the on-screen keypad's pencil latch: pencil this in
        // whatever mode the cell was selected in.
        const pencil = ui.hpencil || (button & MOD_SHFT) !== 0;
        const i = ui.hy * o + ui.hx;
        if (puzzle.given[i]) return null;
        if (pencil && nums[i]) return null;
        const move = `${pencil && n > 0 ? 'P' : 'R'}${ui.hx},${ui.hy},${n}`;
        // The selection stays after a digit, so a keypad user can rub it out or try
        // another without tapping the square again.
        if (!pencil && !ui.hcursor) ui.hkept = true;
        return move;
      }
    }
    if (ch === 'h' || ch === 'H') return 'H';
    if (ch === 'm' || ch === 'M') return 'M';
    return null;
  },

  executeMove(state, move) {
    const { order: o, puzzle } = state;
    const m = /^([PR])(\d+),(\d+),(\d+)$/.exec(move);
    if (m) {
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      const n = parseInt(m[4], 10);
      if (x >= o || y >= o || n > o) return null;
      const i = y * o + x;
      if (puzzle.given[i]) return null;
      const hints = state.hints.slice();
      if (m[1] === 'P' && n > 0) {
        if (state.nums[i]) return null;
        hints[cubeIndex(o, x, y, n)] ^= 1;
        return { ...state, hints };
      }
      // Typing the digit already there, or erasing an empty square: no undo step.
      if (state.nums[i] === n) {
        let marks = false;
        for (let k = 1; k <= o; k++) if (hints[cubeIndex(o, x, y, k)]) marks = true;
        if (!marks) return state;
      }
      const nums = state.nums.slice();
      nums[i] = n;
      for (let k = 1; k <= o; k++) hints[cubeIndex(o, x, y, k)] = 0;
      const next = makeState(puzzle, nums, hints, state.cheated);
      // A finished puzzle stays finished: rubbing a digit out afterwards does not take the
      // win back (nor would writing it in again earn a second one).
      return state.completed ? { ...next, completed: true } : next;
    }
    if (move[0] === 'S') {
      const nums = decodeSolution(state, move);
      if (!nums) return null;
      return makeState(puzzle, nums, new Uint8Array(o * o * o), true);
    }
    if (move === 'M') {
      const hints = new Uint8Array(o * o * o).fill(1);
      return sameBytes(hints, state.hints) ? state : { ...state, hints };
    }
    if (move === 'H') {
      // Pencil in exactly the candidates easy reasoning leaves open.
      const { cube } = solvePuzzle(puzzle, state.nums.slice(), DIFF_EASY);
      return sameBytes(cube, state.hints) ? state : { ...state, hints: cube };
    }
    return null;
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const { gap, border } = geom(t);
    const w = p.order * t + (p.order - 1) * gap + 2 * border;
    return { w, h: w };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { order: o, adjacent, puzzle, nums, errors } = state;
    const { t, gap, border, pitch } = geom(ds.tileSize);
    const size = o * t + (o - 1) * gap;
    const flash = flashOn(flashTime, FLASH / 3);
    const selFill = dr.withAlpha('accent', 0.13);
    // A finished board is shown clean, without the tint.
    const spot = state.completed ? 0 : spotDigit(nums, ui);

    dr.rect(border - 4, border - 4, size + 8, size + 8, flash ? 'shade' : 'paper', 'ink', {
      width: 2.4,
    });

    // A digit the player has just typed is pressed into the square rather than simply
    // being there, and one they have rubbed out shrinks away. This is the most repeated
    // action in the collection, so it is short — and a Solve, which fills the whole grid
    // at once, is left to appear whole.
    const inked = oldState ? changedAt(oldState.nums, nums, 2) : null;
    /** The digit a square is showing mid-change, and how big it is. */
    const inkAt = (i: number, d: number): { d: number; s: number } =>
      !inked?.includes(i)
        ? { d, s: 1 }
        : d
          ? { d, s: popGrow(animTime) }
          : { d: oldState!.nums[i], s: 1 - drawGrow(animTime, INK_TIME) };

    for (let y = 0; y < o; y++) {
      for (let x = 0; x < o; x++) {
        const i = y * o + x;
        const px = border + x * pitch;
        const py = border + y * pitch;
        const hon = ui.hshow && ui.hx === x && ui.hy === y;
        if (spot && nums[i] === spot) dr.rect(px, py, t, t, 'teal', null, { alpha: 0.18 });
        if (hon && !ui.hpencil) dr.rect(px, py, t, t, selFill);
        else if (hon)
          dr.polygon([px, py, px + t * 0.55, py, px, py + t * 0.55], selFill, null, { rough: 0 });
        dr.rectOutline(px, py, t, t, 'faint', { width: 1.2, seed: i });

        // Clue signs in the gaps. Unequal: every flag draws a chevron from its cell.
        // Adjacent: bars belong to a pair, drawn once from the left/top cell.
        for (let k = 0; k < 4; k++) {
          const d = DIRS[k];
          const has = (puzzle.flags[i] & d.f) !== 0;
          const bad = (errors[i] & d.e) !== 0;
          if (adjacent) {
            if (k !== 1 && k !== 2) continue;
            if (!has && !bad) continue;
            const cx = px + t / 2 + d.dx * (t / 2 + gap / 2);
            const cy = py + t / 2 + d.dy * (t / 2 + gap / 2);
            const bw = Math.max(3, gap * 0.28);
            const bl = t * 0.7;
            const rx = cx - (k === 1 ? bw / 2 : bl / 2);
            const ry = cy - (k === 1 ? bl / 2 : bw / 2);
            const rw = k === 1 ? bw : bl;
            const rh = k === 1 ? bl : bw;
            if (has)
              dr.polygon(
                [rx, ry, rx + rw, ry, rx + rw, ry + rh, rx, ry + rh],
                bad ? 'error' : 'ink',
                null,
                { seed: i },
              );
            else dr.rectOutline(rx, ry, rw, rh, 'error', { width: 1.4, seed: i, dash: [3, 2] });
          } else if (has) {
            const cx = px + t / 2 + d.dx * (t / 2 + gap / 2);
            const cy = py + t / 2 + d.dy * (t / 2 + gap / 2);
            drawChevron(dr, cx, cy, d.dx, d.dy, t, gap, bad ? 'error' : 'ink', i * 4 + k);
          }
        }

        const ink = inkAt(i, nums[i]);
        if (ink.d && ink.s > 0) {
          const colour = puzzle.given[i]
            ? flash
              ? 'ok'
              : 'ink'
            : errors[i] & E_DUP
              ? 'error'
              : flash
                ? 'ok'
                : 'blue';
          dr.text(px + t / 2, py + t / 2, String(ink.d), {
            size: t * 0.62 * ink.s,
            colour,
            bold: !!puzzle.given[i],
          });
        } else {
          drawHints(dr, state, x, y, px, py, t, spot);
        }
      }
    }

    if (ui.hshow) {
      const px = border + ui.hx * pitch;
      const py = border + ui.hy * pitch;
      dr.cursor(px - 2, py - 2, t + 4, t + 4, 'accent', 2.2, ui.hpencil ? { dash: [5, 4] } : {});
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.nums, newState.nums, 2) ? INK_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;

/** Marks unchanged by a pencil-all move, so it adds no undo step. */
function sameBytes(a: Uint8Array, b: Uint8Array): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}
