import { tx } from '../../i18n';
/**
 * Geometry for Cube: the four regular solids that can roll on a grid, the square and
 * triangular grids they roll on, and the maths of tipping a solid over one edge of its
 * bottom face onto a neighbouring cell.
 *
 * Units: one grid cell has edges of length 1. Every solid is described resting on its
 * bottom face, which lies in the plane z = 0 centred on the origin; the triangle solids
 * rest on an "up-pointing" triangle (apex towards negative y, which is up on screen).
 * The coordinate system is right-handed with y increasing down the screen and z rising
 * towards the viewer.
 */

export type Vec3 = [number, number, number];
export type SolidKind = 't' | 'c' | 'o' | 'i';
export type Dir = 'L' | 'R' | 'U' | 'D';

export const DIRS: readonly Dir[] = ['L', 'R', 'U', 'D'];
export const SOLID_KINDS: readonly SolidKind[] = ['t', 'c', 'o', 'i'];

export interface Solid {
  kind: SolidKind;
  name: string;
  vertices: Vec3[];
  /** Vertex indices of each face, wound anticlockwise seen from outside. */
  faces: number[][];
  /** Unit outward normal of each face. */
  normals: Vec3[];
  /** Index of the face lying on the grid. */
  bottom: number;
  /** Angle the solid turns through when it rolls over one edge. */
  rollAngle: number;
  /** Oblique-projection shear: how far a point moves up-left per unit of height. */
  shear: number;
  /** Margin (in cells) needed around the grid so the solid never leaves the canvas. */
  border: number;
  /** 4 for the cube (square grid), 3 for the triangle solids. */
  order: 3 | 4;
  /**
   * How many kinds of cell there are as far as this solid is concerned: a rolling
   * tetrahedron's face only ever meets one quarter of the cells, an octahedron's one
   * half (either the up- or the down-pointing triangles).
   */
  nclasses: 1 | 2 | 4;
}

const S3 = Math.sqrt(3);
/** Height of a unit equilateral triangle. */
export const TRI_H = S3 / 2;
/** Distance from a unit triangle's centre to a vertex. */
const TRI_R = 1 / S3;
const PHI = (1 + Math.sqrt(5)) / 2;

// ------------------------------------------------------------------ vectors

const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: Vec3, b: Vec3): number => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
function normalize(v: Vec3): Vec3 {
  const len = Math.hypot(v[0], v[1], v[2]);
  return [v[0] / len, v[1] / len, v[2] / len];
}
const dist = (a: Vec3, b: Vec3): number => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);

/**
 * Rotate `v` about the axis through the origin with unit direction `u` by `angle`
 * (right-hand rule): Rodrigues' formula.
 */
export function rotate(v: Vec3, u: Vec3, angle: number): Vec3 {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  const k = dot(u, v) * (1 - c);
  const w = cross(u, v);
  return [
    v[0] * c + w[0] * s + u[0] * k,
    v[1] * c + w[1] * s + u[1] * k,
    v[2] * c + w[2] * s + u[2] * k,
  ];
}

// ------------------------------------------------------------------- solids

/** The three corners of a unit up-pointing triangle centred on the origin, at height z. */
function triangle(z: number, radius = TRI_R, turn = 0): Vec3[] {
  const out: Vec3[] = [];
  for (let i = 0; i < 3; i++) {
    const a = -Math.PI / 2 + turn + (i * 2 * Math.PI) / 3;
    out.push([radius * Math.cos(a), radius * Math.sin(a), z]);
  }
  return out;
}

/** Every triple of vertices that are pairwise one unit apart: the faces of a deltahedron. */
function unitTriangles(vs: Vec3[]): number[][] {
  const adjacent = (a: number, b: number) => Math.abs(dist(vs[a], vs[b]) - 1) < 1e-6;
  const faces: number[][] = [];
  for (let a = 0; a < vs.length; a++)
    for (let b = a + 1; b < vs.length; b++)
      for (let c = b + 1; c < vs.length; c++)
        if (adjacent(a, b) && adjacent(b, c) && adjacent(a, c)) faces.push([a, b, c]);
  return faces;
}

function makeSolid(
  kind: SolidKind,
  name: string,
  vertices: Vec3[],
  rawFaces: number[][],
  shear: number,
  border: number,
  nclasses: 1 | 2 | 4,
): Solid {
  const centroid: Vec3 = [0, 0, 0];
  for (const v of vertices) for (let i = 0; i < 3; i++) centroid[i] += v[i] / vertices.length;
  const faces: number[][] = [];
  const normals: Vec3[] = [];
  for (const f of rawFaces) {
    const [a, b, c] = f.map((i) => vertices[i]);
    let n = normalize(cross(sub(b, a), sub(c, a)));
    const mid: Vec3 = [0, 0, 0];
    for (const i of f) for (let k = 0; k < 3; k++) mid[k] += vertices[i][k] / f.length;
    let order = f;
    if (dot(n, sub(mid, centroid)) < 0) {
      order = f.slice().reverse();
      n = [-n[0], -n[1], -n[2]];
    }
    faces.push(order);
    normals.push(n);
  }
  const bottom = normals.findIndex((n) => n[2] < -0.999);
  // Any face sharing an edge with the bottom one tells us the rolling angle.
  const neighbour = faces.findIndex(
    (f, i) => i !== bottom && f.filter((v) => faces[bottom].includes(v)).length === 2,
  );
  const rollAngle = Math.acos(dot(normals[bottom], normals[neighbour]));
  return {
    kind,
    name,
    vertices,
    faces,
    normals,
    bottom,
    rollAngle,
    shear,
    border,
    order: rawFaces[0].length === 4 ? 4 : 3,
    nclasses,
  };
}

function tetrahedron(): Solid {
  const vs = [...triangle(0), [0, 0, Math.sqrt(2 / 3)] as Vec3];
  return makeSolid('t', 'Tetrahedron', vs, unitTriangles(vs), 0.15, 0.4, 4);
}

function cube(): Solid {
  const vs: Vec3[] = [];
  for (const z of [0, 1])
    for (const y of [-0.5, 0.5]) for (const x of [-0.5, 0.5]) vs.push([x, y, z]);
  // Vertex index = x-bit + 2*y-bit + 4*z-bit; each face fixes one coordinate.
  const faces = [
    [0, 1, 3, 2],
    [4, 5, 7, 6],
    [0, 1, 5, 4],
    [2, 3, 7, 6],
    [0, 2, 6, 4],
    [1, 3, 7, 5],
  ];
  return makeSolid('c', 'Cube', vs, faces, 0.3, 0.5, 1);
}

function octahedron(): Solid {
  const h = 2 / Math.sqrt(6);
  const vs = [...triangle(0), ...triangle(h, TRI_R, Math.PI)];
  return makeSolid('o', 'Octahedron', vs, unitTriangles(vs), 0.15, 0.6, 2);
}

function icosahedron(): Solid {
  // Resting on a face, the twelve vertices lie in four layers whose heights and radii
  // are 1, φ and φ² (times 1/√3), alternately turned half a turn.
  const vs = [
    ...triangle(0),
    ...triangle(1 / S3, PHI / S3, Math.PI),
    ...triangle(PHI / S3, PHI / S3),
    ...triangle((PHI * PHI) / S3, TRI_R, Math.PI),
  ];
  return makeSolid('i', 'Icosahedron', vs, unitTriangles(vs), 0.15, 0.95, 1);
}

export const SOLIDS: Record<SolidKind, Solid> = {
  t: tetrahedron(),
  c: cube(),
  o: octahedron(),
  i: icosahedron(),
};

// -------------------------------------------------------------------- grids

export interface Cell {
  /** Centre. */
  cx: number;
  cy: number;
  /** Corner coordinates [x0, y0, x1, y1, ...]. */
  pts: number[];
  /** True for a down-pointing triangle (the solid is placed rotated half a turn). */
  flip: boolean;
  /** Neighbour across the edge in each direction, or -1. */
  nb: Record<Dir, number>;
  /** Indices (into pts) of the two corners bounding the edge in each direction. */
  edge: Record<Dir, [number, number] | null>;
}

export interface Grid {
  kind: SolidKind;
  d1: number;
  d2: number;
  cells: Cell[];
  /** Bounding box of every corner. */
  bbox: { l: number; r: number; u: number; d: number };
  /** Edges that belong to only one cell, as [x0, y0, x1, y1]. */
  boundary: number[][];
  classes: number[];
}

/** Number of cells in a grid of the given dimensions. */
export function gridArea(kind: SolidKind, d1: number, d2: number): number {
  if (kind === 'c') return d1 * d2;
  // A hexagon (or triangle when d2 = 0) with alternate side lengths d1 and d2.
  return d1 * d1 + d2 * d2 + 4 * d1 * d2;
}

function rawSquareCells(w: number, h: number): Omit<Cell, 'nb' | 'edge'>[] {
  const out: Omit<Cell, 'nb' | 'edge'>[] = [];
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++)
      out.push({
        cx: x,
        cy: y,
        pts: [x - 0.5, y - 0.5, x + 0.5, y - 0.5, x + 0.5, y + 0.5, x - 0.5, y + 0.5],
        flip: false,
      });
  return out;
}

/**
 * Triangular grid: `d1 + d2` rows of triangles. The top row has `d1` down-pointing
 * triangles, each row grows by one until row `d2`, then shrinks again, giving a hexagon
 * with three sides of length d1 and three of length d2. Within a row the down-pointing
 * triangles come first, then the up-pointing ones (this ordering is what game
 * descriptions index).
 */
function rawTriangleCells(d1: number, d2: number): Omit<Cell, 'nb' | 'edge'>[] {
  const out: Omit<Cell, 'nb' | 'edge'>[] = [];
  for (let row = 0; row < d1 + d2; row++) {
    const nDown = row < d2 ? d1 + row : d1 + 2 * d2 - row;
    const nUp = row < d2 ? nDown + 1 : nDown - 1;
    const y = row * TRI_H;
    for (let i = 0; i < nDown; i++) {
      const x = i - (nDown - 1) / 2;
      out.push({
        cx: x,
        cy: y + TRI_H / 3,
        pts: [x - 0.5, y, x + 0.5, y, x, y + TRI_H],
        flip: true,
      });
    }
    for (let i = 0; i < nUp; i++) {
      const x = i - (nUp - 1) / 2;
      out.push({
        cx: x,
        cy: y + (2 * TRI_H) / 3,
        pts: [x, y, x + 0.5, y + TRI_H, x - 0.5, y + TRI_H],
        flip: false,
      });
    }
  }
  return out;
}

const key = (x: number, y: number) => `${Math.round(x * 1e4)},${Math.round(y * 1e4)}`;

function buildGrid(kind: SolidKind, d1: number, d2: number): Grid {
  const raw = kind === 'c' ? rawSquareCells(d1, d2) : rawTriangleCells(d1, d2);
  const cells: Cell[] = raw.map((c) => ({
    ...c,
    nb: { L: -1, R: -1, U: -1, D: -1 },
    edge: { L: null, R: null, U: null, D: null },
  }));
  // Index every edge by its (unordered) endpoints to find who shares it.
  const owners = new Map<string, { cell: number; a: number; b: number }[]>();
  cells.forEach((c, ci) => {
    const n = c.pts.length / 2;
    for (let a = 0; a < n; a++) {
      const b = (a + 1) % n;
      const ka = key(c.pts[2 * a], c.pts[2 * a + 1]);
      const kb = key(c.pts[2 * b], c.pts[2 * b + 1]);
      const k = ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
      const list = owners.get(k) ?? [];
      list.push({ cell: ci, a, b });
      owners.set(k, list);
    }
  });
  const boundary: number[][] = [];
  for (const list of owners.values()) {
    if (list.length === 1) {
      const { cell, a, b } = list[0];
      const p = cells[cell].pts;
      boundary.push([p[2 * a], p[2 * a + 1], p[2 * b], p[2 * b + 1]]);
      continue;
    }
    for (const { cell, a, b } of list) {
      const c = cells[cell];
      const other = list.find((o) => o.cell !== cell)!.cell;
      const mx = (c.pts[2 * a] + c.pts[2 * b]) / 2 - c.cx;
      const my = (c.pts[2 * a + 1] + c.pts[2 * b + 1]) / 2 - c.cy;
      // Horizontal edges are above or below the centre; every other edge is to a side.
      const dir: Dir = Math.abs(mx) > 1e-6 ? (mx < 0 ? 'L' : 'R') : my < 0 ? 'U' : 'D';
      c.nb[dir] = other;
      c.edge[dir] = [a, b];
    }
  }
  const bbox = { l: Infinity, r: -Infinity, u: Infinity, d: -Infinity };
  for (const c of cells)
    for (let i = 0; i < c.pts.length; i += 2) {
      bbox.l = Math.min(bbox.l, c.pts[i]);
      bbox.r = Math.max(bbox.r, c.pts[i]);
      bbox.u = Math.min(bbox.u, c.pts[i + 1]);
      bbox.d = Math.max(bbox.d, c.pts[i + 1]);
    }
  const grid: Grid = { kind, d1, d2, cells, bbox, boundary, classes: [] };
  grid.classes = cellClasses(SOLIDS[kind], grid);
  return grid;
}

const gridCache = new Map<string, Grid>();

/** The (immutable, cached) grid for these parameters. */
export function gridFor(p: { solid: SolidKind; d1: number; d2: number }): Grid {
  const k = `${p.solid}${p.d1}x${p.d2}`;
  let g = gridCache.get(k);
  if (!g) {
    g = buildGrid(p.solid, p.d1, p.d2);
    gridCache.set(k, g);
  }
  return g;
}

/** The direction from cell `from` that leads to cell `to`, or null if not adjacent. */
export function directionTo(grid: Grid, from: number, to: number): Dir | null {
  const c = grid.cells[from];
  return DIRS.find((d) => c.nb[d] === to) ?? null;
}

// ---------------------------------------------------------- placing & rolling

export interface Pose {
  vertices: Vec3[];
  normals: Vec3[];
}

/** The solid's outward normals when it rests on a cell of the given orientation. */
export function restNormals(solid: Solid, flip: boolean): Vec3[] {
  return flip ? solid.normals.map((n) => [-n[0], -n[1], n[2]] as Vec3) : solid.normals;
}

/** The solid sitting at rest on a cell: turned half a turn on down-pointing triangles. */
export function restPose(solid: Solid, grid: Grid, cell: number): Pose {
  const c = grid.cells[cell];
  const s = c.flip ? -1 : 1;
  return {
    vertices: solid.vertices.map((v) => [c.cx + s * v[0], c.cy + s * v[1], v[2]] as Vec3),
    normals: restNormals(solid, c.flip),
  };
}

/**
 * The solid part-way through rolling from `from` onto the adjacent cell `to`: it has
 * turned `angle` radians about the edge the two cells share, tipping towards `to`.
 */
export function rollPose(solid: Solid, grid: Grid, from: number, to: number, angle: number): Pose {
  const dir = directionTo(grid, from, to);
  if (dir === null) throw new Error(tx`cells are not adjacent`);
  const src = grid.cells[from];
  const dst = grid.cells[to];
  const [ia, ib] = src.edge[dir]!;
  let ax = src.pts[2 * ia];
  let ay = src.pts[2 * ia + 1];
  let ux = src.pts[2 * ib] - ax;
  let uy = src.pts[2 * ib + 1] - ay;
  // A point above the axis moves along (uy, -ux); orient the axis so that is towards
  // the destination, then a positive rotation tips the solid the right way.
  if (uy * (dst.cx - src.cx) - ux * (dst.cy - src.cy) < 0) {
    ax += ux;
    ay += uy;
    ux = -ux;
    uy = -uy;
  }
  const len = Math.hypot(ux, uy);
  const u: Vec3 = [ux / len, uy / len, 0];
  const pivot: Vec3 = [ax, ay, 0];
  const rest = restPose(solid, grid, from);
  return {
    vertices: rest.vertices.map((v) => {
      const r = rotate(sub(v, pivot), u, angle);
      return [r[0] + ax, r[1] + ay, r[2]] as Vec3;
    }),
    normals: rest.normals.map((n) => rotate(n, u, angle)),
  };
}

/**
 * How the faces are relabelled by a roll from `from` to `to`: after landing, the face
 * occupying canonical position `i` is the one that occupied position `result[i]` before.
 */
export function rollFaceMap(solid: Solid, grid: Grid, from: number, to: number): number[] {
  const rolled = rollPose(solid, grid, from, to, solid.rollAngle).normals;
  const target = restNormals(solid, grid.cells[to].flip);
  return target.map((n) => {
    const j = rolled.findIndex((m) => dot(m, n) > 0.9999);
    if (j < 0) throw new Error(tx`rolled solid does not fit its destination`);
    return j;
  });
}

/**
 * Partition the cells into the classes a solid's faces are confined to. Rolling a
 * tetrahedron, each face always lands on the same quarter of the cells (found here by
 * actually rolling it everywhere); an octahedron's faces alternate between up- and
 * down-pointing triangles; the cube and icosahedron can put any face anywhere.
 */
export function cellClasses(solid: Solid, grid: Grid): number[] {
  const n = grid.cells.length;
  if (solid.nclasses === 1) return new Array(n).fill(0);
  if (solid.nclasses === 2) return grid.cells.map((c) => (c.flip ? 1 : 0));
  const classes: number[] = new Array(n).fill(-1);
  if (n === 0) return classes;
  // perm[i] = which original face now sits at canonical position i.
  const queue: { cell: number; perm: number[] }[] = [
    { cell: 0, perm: solid.faces.map((_, i) => i) },
  ];
  classes[0] = solid.bottom;
  while (queue.length) {
    const { cell, perm } = queue.shift()!;
    for (const d of DIRS) {
      const to = grid.cells[cell].nb[d];
      if (to < 0) continue;
      const map = rollFaceMap(solid, grid, cell, to);
      const next = map.map((j) => perm[j]);
      if (classes[to] < 0) {
        classes[to] = next[solid.bottom];
        queue.push({ cell: to, perm: next });
      } else if (classes[to] !== next[solid.bottom]) {
        throw new Error(tx`inconsistent face classes`);
      }
    }
  }
  return classes;
}

// ------------------------------------------------------------------- layout

/** Triangle cells are drawn a little larger than squares so the small grids stay legible. */
export const TRI_SCALE = 1.4;

export interface Layout {
  grid: Grid;
  solid: Solid;
  /** Pixels per grid unit (the edge of one cell). */
  unit: number;
  /** Pixel position of the grid origin. */
  ox: number;
  oy: number;
}

/** Where the grid lands on a canvas for the given tile size. */
export function layout(p: { solid: SolidKind; d1: number; d2: number }, tileSize: number): Layout {
  const grid = gridFor(p);
  const solid = SOLIDS[p.solid];
  const unit = solid.order === 4 ? tileSize : tileSize * TRI_SCALE;
  return {
    grid,
    solid,
    unit,
    ox: (solid.border - grid.bbox.l) * unit,
    oy: (solid.border - grid.bbox.u) * unit,
  };
}

/** Canvas size needed for the grid plus the solid's margin. */
export function canvasSize(
  p: { solid: SolidKind; d1: number; d2: number },
  tileSize: number,
): { w: number; h: number } {
  const { grid, solid, unit } = layout(p, tileSize);
  return {
    w: Math.round((grid.bbox.r - grid.bbox.l + 2 * solid.border) * unit),
    h: Math.round((grid.bbox.d - grid.bbox.u + 2 * solid.border) * unit),
  };
}

/** Oblique projection of a 3D point to grid-plane coordinates. */
export function project(v: Vec3, shear: number): [number, number] {
  return [v[0] - v[2] * shear, v[1] - v[2] * shear];
}

/** Whether a face with this normal faces the viewer under the oblique projection. */
export function facesViewer(n: Vec3, shear: number): boolean {
  return n[0] * shear + n[1] * shear + n[2] > 1e-6;
}
