/**
 * A screen of items that turns like a book instead of scrolling like a document.
 *
 * The collection and the achievements shelf used to be long web pages. A game's level
 * select is a fixed screen: as many items as fit, and a way to the next screenful. This
 * lays a grid out to exactly fill the room it is given — as many columns and rows as the
 * layout's cell size allows, read from `--cell-w` / `--cell-h` on the viewport so each
 * breakpoint's CSS stays in charge of how big an item is — and shows one page of it.
 *
 * Every way a player might try to move on works: the ◀ ▶ buttons and the dots, the arrow
 * keys and Page Up/Down, Home and End, a mouse wheel or trackpad, and a swipe. A
 * right-to-left page turns the other way round, as its reading order does.
 *
 * Items off the current page are `display: none` (`.off-page`), so they are also out of
 * the Tab order; the pager buttons are the way on for a keyboard, as the arrow keys are.
 */

import { t } from '../i18n';
import { gsap, prefersReducedMotion } from './anim';
import { registerNavPager } from './nav';
import { playSound } from './sound';

export interface PagerOptions {
  /** The element whose size is filled. Its `--cell-w` / `--cell-h` set an item's floor. */
  viewport: HTMLElement;
  /** The grid on show now (a page may switch between several, as the collection's tabs do). */
  grid: () => HTMLElement | null;
  /** The items to page through, in order: whatever is on show in `grid()`. */
  items: () => HTMLElement[];
  /** After every change of page, layout or item set. */
  onChange?: () => void;
}

export interface Pager {
  /** The ◀ • • • ▶ bar, for the page to put wherever it wants. */
  readonly controls: HTMLElement;
  readonly page: number;
  readonly pages: number;
  /** Re-read the items and the room, keeping the page (clamped) where it can. */
  refresh(): void;
  goTo(page: number, animate?: boolean): void;
  /** Turn to whichever page holds `item`. */
  showItem(item: HTMLElement, animate?: boolean): void;
  destroy(): void;
}

/** How far a wheel has to travel, summed, before it turns a page. */
const WHEEL_STEP = 60;
/** A wheel keeps sending deltas after the flick that meant one page; they are ignored this long. */
const WHEEL_REST_MS = 420;
/** How far a finger has to travel sideways for a swipe to count. */
const SWIPE_MIN = 48;
/** More than this and a press is a drag, whose click must not open the card under it. */
const DRAG_SLOP = 10;
/** Dots up to this many pages; past it the bar says "3 / 12" instead. */
const MAX_DOTS = 12;

function px(v: string, fallback: number): number {
  const n = parseFloat(v);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

const rtl = () => document.documentElement.dir === 'rtl';

export function createPager(opts: PagerOptions): Pager {
  const { viewport } = opts;
  let page = 0;
  let pages = 1;
  let perPage = 1;
  let destroyed = false;

  // ---- the bar
  const controls = document.createElement('nav');
  controls.className = 'pager';
  controls.setAttribute('aria-label', t('ui.pager.label'));
  const prev = document.createElement('button');
  prev.type = 'button';
  prev.className = 'btn pager-arrow pager-prev';
  prev.setAttribute('aria-label', t('ui.pager.prev'));
  prev.title = t('ui.pager.prev');
  prev.innerHTML = arrowSVG();
  const next = document.createElement('button');
  next.type = 'button';
  next.className = 'btn pager-arrow pager-next';
  next.setAttribute('aria-label', t('ui.pager.next'));
  next.title = t('ui.pager.next');
  next.innerHTML = arrowSVG();
  const dots = document.createElement('div');
  dots.className = 'pager-dots';
  controls.append(prev, dots, next);
  prev.addEventListener('click', () => goTo(page - 1, true));
  next.addEventListener('click', () => goTo(page + 1, true));
  dots.addEventListener('click', (e) => {
    const dot = (e.target as HTMLElement).closest<HTMLElement>('[data-page]');
    if (dot) goTo(Number(dot.dataset.page), true);
  });

  function paintBar() {
    prev.disabled = page <= 0;
    next.disabled = page >= pages - 1;
    // Hidden rather than removed, so a one-page shelf keeps the bar's height and the grid
    // is not handed a different room to fill — which would change the page count again.
    controls.classList.toggle('single', pages <= 1);
    dots.replaceChildren();
    const label = t('ui.pager.page', { n: page + 1, total: pages });
    if (pages > MAX_DOTS) {
      const count = document.createElement('span');
      count.className = 'pager-count';
      count.textContent = `${page + 1} / ${pages}`;
      count.setAttribute('aria-label', label);
      dots.append(count);
      return;
    }
    for (let i = 0; i < pages; i++) {
      const d = document.createElement('button');
      d.type = 'button';
      d.className = 'pager-dot';
      d.dataset.page = String(i);
      d.setAttribute('aria-label', t('ui.pager.page', { n: i + 1, total: pages }));
      if (i === page) d.setAttribute('aria-current', 'page');
      d.tabIndex = -1;
      dots.append(d);
    }
  }

  // ---- layout
  function measure(grid: HTMLElement): { cols: number; rows: number } {
    const cs = getComputedStyle(viewport);
    const cellW = px(cs.getPropertyValue('--cell-w'), 200);
    const cellH = px(cs.getPropertyValue('--cell-h'), 220);
    const gs = getComputedStyle(grid);
    const colGap = px(gs.columnGap, 0);
    const rowGap = px(gs.rowGap, 0);
    // The content box: a tray draws its rim with padding, and the grid fills inside it.
    const w = viewport.clientWidth - px(cs.paddingLeft, 0) - px(cs.paddingRight, 0);
    const h = viewport.clientHeight - px(cs.paddingTop, 0) - px(cs.paddingBottom, 0);
    return {
      cols: Math.max(1, Math.floor((w + colGap) / (cellW + colGap))),
      rows: Math.max(1, Math.floor((h + rowGap) / (cellH + rowGap))),
    };
  }

  function layout() {
    const grid = opts.grid();
    if (!grid) return;
    const { cols, rows } = measure(grid);
    perPage = cols * rows;
    grid.style.gridTemplateColumns = `repeat(${cols}, minmax(0, 1fr))`;
    grid.style.gridTemplateRows = `repeat(${rows}, minmax(0, 1fr))`;
    const items = opts.items();
    pages = Math.max(1, Math.ceil(items.length / perPage));
    page = Math.min(page, pages - 1);
    items.forEach((it, i) => it.classList.toggle('off-page', Math.floor(i / perPage) !== page));
    paintBar();
    opts.onChange?.();
  }

  function goTo(to: number, animate = false) {
    const target = Math.max(0, Math.min(pages - 1, to));
    if (target === page) {
      // Pushing past either end answers with a nudge, so the press was not ignored.
      if (animate && to !== page) nudge(to > page ? 1 : -1);
      return;
    }
    const dir = target > page ? 1 : -1;
    page = target;
    layout();
    if (animate) playSound('page');
    const grid = opts.grid();
    if (animate && grid && !prefersReducedMotion()) {
      const x = (rtl() ? -dir : dir) * 48;
      gsap.fromTo(
        grid,
        { x, opacity: 0.2 },
        { x: 0, opacity: 1, duration: 0.3, ease: 'power3.out', clearProps: 'transform,opacity' },
      );
    }
  }

  function nudge(dir: number) {
    const grid = opts.grid();
    if (!grid || prefersReducedMotion()) return;
    const x = (rtl() ? dir : -dir) * 10;
    gsap.fromTo(
      grid,
      { x },
      { x: 0, duration: 0.35, ease: 'elastic.out(1, 0.5)', clearProps: 'transform' },
    );
  }

  function showItem(item: HTMLElement, animate = false) {
    const i = opts.items().indexOf(item);
    if (i >= 0) goTo(Math.floor(i / perPage), animate);
  }

  // ---- keys
  const onKey = (e: KeyboardEvent) => {
    if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
    const target = e.target as HTMLElement | null;
    if (target?.closest('input, textarea, select, [contenteditable]')) return;
    // A dialog or the help drawer has the keys while it is up.
    if (document.querySelector('.dimmer, .help-drawer.open')) return;
    const back = rtl() ? 'ArrowRight' : 'ArrowLeft';
    const fwd = rtl() ? 'ArrowLeft' : 'ArrowRight';
    let to: number | null = null;
    if (e.key === fwd || e.key === 'PageDown') to = page + 1;
    else if (e.key === back || e.key === 'PageUp') to = page - 1;
    else if (e.key === 'Home') to = 0;
    else if (e.key === 'End') to = pages - 1;
    if (to === null) return;
    e.preventDefault();
    const had = document.activeElement;
    goTo(to, true);
    // A card that had the keyboard may just have left the screen; the keyboard stays on
    // the shelf rather than falling back to the top of the document.
    if (had instanceof HTMLElement && had.closest('.off-page')) {
      opts
        .items()
        .find((it) => !it.classList.contains('off-page'))
        ?.focus();
    }
  };
  document.addEventListener('keydown', onKey);

  // ---- wheel
  let wheelSum = 0;
  let wheelRestUntil = 0;
  const onWheel = (e: WheelEvent) => {
    if (pages <= 1) return;
    e.preventDefault();
    const now = performance.now();
    if (now < wheelRestUntil) {
      wheelRestUntil = now + WHEEL_REST_MS;
      return;
    }
    // Either axis: a mouse wheel is vertical, a trackpad's page flick is sideways.
    const d = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX * (rtl() ? -1 : 1) : e.deltaY;
    wheelSum += e.deltaMode === 1 ? d * 16 : d;
    if (Math.abs(wheelSum) >= WHEEL_STEP) {
      goTo(page + Math.sign(wheelSum), true);
      wheelSum = 0;
      wheelRestUntil = now + WHEEL_REST_MS;
    }
  };
  viewport.addEventListener('wheel', onWheel, { passive: false });

  // ---- swipe
  let drag: { id: number; x: number; y: number; moved: boolean } | null = null;
  let swallowClick = false;
  const onDown = (e: PointerEvent) => {
    if (e.pointerType === 'mouse' || pages <= 1) return;
    drag = { id: e.pointerId, x: e.clientX, y: e.clientY, moved: false };
  };
  const onMove = (e: PointerEvent) => {
    if (!drag || e.pointerId !== drag.id) return;
    const dx = e.clientX - drag.x;
    if (!drag.moved && Math.abs(dx) > DRAG_SLOP) drag.moved = true;
    const grid = opts.grid();
    // The page follows the finger a little, so the swipe is felt before it is decided.
    if (drag.moved && grid && !prefersReducedMotion()) gsap.set(grid, { x: dx * 0.35 });
  };
  const onUp = (e: PointerEvent) => {
    if (!drag || e.pointerId !== drag.id) return;
    const dx = e.clientX - drag.x;
    const dy = e.clientY - drag.y;
    const moved = drag.moved;
    drag = null;
    if (!moved) return;
    swallowClick = true;
    window.setTimeout(() => (swallowClick = false), 0);
    const grid = opts.grid();
    if (Math.abs(dx) >= SWIPE_MIN && Math.abs(dx) > Math.abs(dy) * 1.2) {
      const fwd = rtl() ? dx > 0 : dx < 0;
      const before = page;
      goTo(page + (fwd ? 1 : -1), true);
      if (page !== before) return;
    }
    if (grid) gsap.to(grid, { x: 0, duration: 0.2, ease: 'power2.out', clearProps: 'transform' });
  };
  const onCancel = () => {
    drag = null;
    const grid = opts.grid();
    if (grid) gsap.to(grid, { x: 0, duration: 0.2, clearProps: 'transform' });
  };
  // A drag that ends on a card must not also open it.
  const onClickCapture = (e: MouseEvent) => {
    if (!swallowClick) return;
    swallowClick = false;
    e.preventDefault();
    e.stopPropagation();
  };
  // The page allows a sideways pan (`touch-action` in feel.css), and a browser that takes a
  // pan cancels the pointer before the swipe can count. Up and down stay the browser's.
  viewport.style.touchAction = 'pan-y';
  viewport.addEventListener('pointerdown', onDown);
  viewport.addEventListener('pointermove', onMove);
  viewport.addEventListener('pointerup', onUp);
  viewport.addEventListener('pointercancel', onCancel);
  viewport.addEventListener('click', onClickCapture, true);

  // ---- room
  // Measured again whenever the room changes: a rotation, a resized window, the masthead
  // wrapping onto a second line in another language.
  let raf = 0;
  const ro = new ResizeObserver(() => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      if (!destroyed) layout();
    });
  });
  ro.observe(viewport);

  layout();
  // The arrow keys' selector (nav.ts) turns the page when it walks off the side of one.
  const leaveNav = registerNavPager(viewport, {
    turn(delta) {
      const before = page;
      goTo(page + delta, true);
      return page !== before;
    },
  });

  return {
    controls,
    get page() {
      return page;
    },
    get pages() {
      return pages;
    },
    refresh: layout,
    goTo,
    showItem,
    destroy() {
      destroyed = true;
      leaveNav();
      cancelAnimationFrame(raf);
      ro.disconnect();
      document.removeEventListener('keydown', onKey);
      const grid = opts.grid();
      if (grid) gsap.killTweensOf(grid);
    },
  };
}

/** A drawn chevron pointing forwards; `[dir='rtl']` turns it round in the stylesheet. */
function arrowSVG(): string {
  return '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><path d="M9 5.5 15.5 12 9 18.5" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}
