/**
 * No two hand-drawn boxes alike.
 *
 * Every sketched outline in the shell — buttons, cards, keys, the strip, dialogs, tags —
 * takes its wobble from `--sketch-radius` / `--sketch-radius-2` (the lopsided
 * `border-radius` trick) and its pen from `--line`. There used to be one of each shape,
 * alternated odd/even, so a row of buttons was the same two boxes over and over: it read
 * as a stylesheet, not as someone drawing.
 *
 * This gives every sketched element its own values, from a family of generated corner
 * shapes and a small range of pen weights, and does it on the element itself, so every
 * existing rule that reads the variables picks up the variation without being touched.
 * The round HUD buttons get `--blob`, a wobbly circle, the same way.
 *
 * Deterministic: the choice is seeded from what the element *is* (its class, its command
 * or slug or text, its place among its siblings), never from `Math.random`, so a box
 * looks the same every time it is drawn and a re-render does not make the page shimmer.
 */

/** Everything drawn as a sketched box. */
const SKETCHED =
  '.btn, .sketch, .card, .sketch-input, .keypad .key, .ach-tile, .badge, ' +
  '.credits-chip, .solved-tag, .statusbar, .tut-callout, kbd, .pager-arrow, .pager-dot, ' +
  '.endgame-card, .ach-summary, .progress-strip, .sketch-list';

/** FNV-1a, for a stable seed from a string. */
function hash(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** mulberry32: a small seeded generator, so one seed gives a whole shape. */
function rng(seed: number): () => number {
  let a = seed || 1;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * One hand-drawn corner set. The trick is corners with one huge radius and one tiny one,
 * which bows each edge like a pen stroke; which corners bow which way, how far, and
 * whether a corner is left nearly square instead, is what makes one box not another.
 */
function sketchRadius(r: () => number): string {
  // How freely the box was drawn: a steady hand (edges nearly straight, corners only
  // rounded) or a quick sweep (edges bowing right across the box).
  const sweep = r() < 0.35 ? 30 + r() * 60 : 140 + r() * 130;
  const big = () => Math.round(sweep * (0.75 + r() * 0.5));
  const small = () => Math.round(6 + r() * 18);
  const start = Math.floor(r() * 2);
  const h: number[] = [];
  const v: number[] = [];
  for (let i = 0; i < 4; i++) {
    if (r() < 0.22) {
      // A corner drawn tight rather than swept: both radii small.
      h.push(small());
      v.push(small());
    } else if ((i + start) % 2) {
      h.push(small());
      v.push(big());
    } else {
      h.push(big());
      v.push(small());
    }
  }
  return `${h.map((n) => `${n}px`).join(' ')} / ${v.map((n) => `${n}px`).join(' ')}`;
}

/** A circle that was drawn by hand: each quarter a few percent off. */
function blob(r: () => number): string {
  const q = () => `${Math.round(44 + r() * 12)}%`;
  return `${q()} ${q()} ${q()} ${q()} / ${q()} ${q()} ${q()} ${q()}`;
}

function seedOf(el: HTMLElement): string {
  const d = el.dataset;
  const key = d.slug ?? d.cmd ?? d.ctl ?? d.action ?? d.key ?? d.page ?? '';
  const text = key || (el.textContent ?? '').trim().slice(0, 32);
  const index = el.parentElement ? [...el.parentElement.children].indexOf(el) : 0;
  // The thing it belongs to, so thirty identical "Unlock" buttons on thirty cards are
  // thirty different drawings.
  const owner = el.parentElement?.closest<HTMLElement>('[data-slug], [data-key]');
  const whose = owner ? (owner.dataset.slug ?? owner.dataset.key ?? '') : '';
  return `${el.className}|${text}|${index}|${whose}`;
}

function vary(el: HTMLElement): void {
  if (el.dataset.sketched) return;
  el.dataset.sketched = '1';
  const r = rng(hash(seedOf(el)));
  el.style.setProperty('--sketch-radius', sketchRadius(r));
  el.style.setProperty('--sketch-radius-2', sketchRadius(r));
  el.style.setProperty('--blob', blob(r));
  // The pen pressed a little harder or lighter each time: 1.8px to 2.4px.
  el.style.setProperty('--line', `${(1.8 + r() * 0.6).toFixed(2)}px`);
}

function visit(root: ParentNode): void {
  if (root instanceof HTMLElement && root.matches(SKETCHED)) vary(root);
  root.querySelectorAll<HTMLElement>(SKETCHED).forEach(vary);
}

/** Start varying every sketched box on the page, now and as the shell draws new ones. */
export function startSketchVariety(): void {
  if (typeof document === 'undefined' || typeof MutationObserver === 'undefined') return;
  visit(document.body);
  new MutationObserver((records) => {
    for (const rec of records) {
      for (const node of rec.addedNodes) {
        if (node instanceof HTMLElement) visit(node);
      }
    }
  }).observe(document.body, { childList: true, subtree: true });
}
