export interface MenuHandle {
  destroy(): void;
  /** The card being returned to has landed back in the box (see `returning`). */
  landed(): void;
}

export interface MenuOptions {
  /**
   * The game the player is coming back from, on a journey that flies its sheet back into
   * its card (flight.ts). That card is put on screen and left as an empty slot (`.out`),
   * the cards do not deal themselves in, and anything the menu has to say about it waits
   * for {@link MenuHandle.landed}.
   */
  returning?: string;
}

const LOCK_SVG = `<svg viewBox="0 0 24 24" width="34" height="34" aria-hidden="true"><path d="M7 11V8a5 5 0 0 1 10 0v3" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/><rect x="4.5" y="11" width="15" height="10" rx="3" fill="${PALETTE.paper}" stroke="currentColor" stroke-width="2.2"/><circle cx="12" cy="16" r="1.6" fill="currentColor"/></svg>`;

/** The trophy on the achievements stat, in `currentColor` like the search glass. */
const TROPHY_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4h10v4a5 5 0 0 1-10 0V4Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M7 6H4.5a2.5 3 0 0 0 3 4M17 6h2.5a2.5 3 0 0 1-3 4M12 13v4M8 20h8M9.5 17h5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';

/** Drawn in `currentColor`, so the palette owns the colour like everything else. */
const SEARCH_SVG =
  '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.2" fill="none" stroke="currentColor" stroke-width="2.3"/><path d="M15.2 15.4 20 20.2" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg>';

/**
 * The resource bar's icons, one per counter, each in a coin of its own colour — the way a
 * game marks its currencies. `currentColor` for the ink, so the palette owns the rest.
 */
const OPEN_LOCK_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.5 11V7.6a4.6 4.6 0 0 1 9-1.3" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round"/><rect x="4.8" y="11" width="14.4" height="9.6" rx="2.6" fill="none" stroke="currentColor" stroke-width="2.3"/><circle cx="12" cy="15.8" r="1.5" fill="currentColor"/></svg>';
const CHECK_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.6 12.8l4.6 4.5L19.6 6.6" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';
/** Two dice, tumbling. */
const DICE_SVG =
  '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4.6 12.2c3.6-1.3 7.2-2.3 10.9-3 1.2 3.6 2.1 7.2 2.8 10.9-3.6 1.3-7.2 2.3-10.9 3-1.2-3.6-2.1-7.2-2.8-10.9z" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round"/><circle cx="8.7" cy="14.6" r="1.4" fill="currentColor"/><circle cx="14.3" cy="18.3" r="1.4" fill="currentColor"/><circle cx="11.5" cy="16.4" r="1.4" fill="currentColor"/><path d="M19.6 7.3c2.9.6 5.8 1.4 8.6 2.4-.6 2.9-1.4 5.8-2.4 8.6-2.9-.6-5.8-1.4-8.6-2.4.6-2.9 1.4-5.8 2.4-8.6z" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round"/><circle cx="21.4" cy="11" r="1.3" fill="currentColor"/><circle cx="25" cy="14.4" r="1.3" fill="currentColor"/></svg>';
/**
 * The last game the dice picked this visit, so throwing them again from the menu that game
 * was left for always lands somewhere new.
 */
let lastSurprise: string | null = null;
const PLAY_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.2c3.9 2 7.5 4.3 10.8 6.9-3.3 2.5-6.9 4.8-10.8 6.8-.3-4.6-.3-9.1 0-13.7z" fill="currentColor" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>';

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

export function renderMenu(root: HTMLElement, opts: MenuOptions = {}): MenuHandle {
  document.title = t('ui.appName');
  // A fixed screen, like the play page: the shelf turns pages rather than scrolling.
  document.documentElement.classList.add('screen');
  const page = el('div', 'menu-page');

  // The masthead is one box on a phone, where every row of it is a row of puzzles the
  // player cannot see yet. `display: contents` on a wide screen, so the desktop page is
  // laid out exactly as it was before this wrapper existed.
  const head = el('div', 'menu-head');
  const hero = el('header', 'hero');
  // The name now arrives with the mark beside it rather than as bare lettering: a portal
  // visitor meets this collection for two seconds between two other games, and a wordmark
  // alone gave them nothing to recognise it by on the way back. One lockup, one logo —
  // the same SVG the tab icon, the splash and the store covers are cut from.
  const logo = el('h1', 'logo');
  const logoMark = el('span', 'logo-mark');
  logoMark.innerHTML = brandMarkSVG({ className: 'brand-mark' });
  // Behind the box (`z-index: -1` in the stylesheet, so document order is free), breathing
  // and blinking for as long as the menu is up. He is the first thing on the page and the
  // page is otherwise perfectly still, so this is where a living mascot earns the most.
  const logoMascot = mountMascot(logoMark, { className: 'logo-ziggy', tilt: -12 });
  // textContent, not innerHTML: the title is a translated string.
  const logoWord = el('span', 'logo-word', t('ui.menu.title'));
  logo.append(logoMark, logoWord);
  const tagline = el('p', 'tagline', t('ui.menu.tagline', { n: menuGames.length }));
  // Continue: the puzzle the player left half done, a press away (`lastPlayed.ts`). In
  // the masthead's corner, where the language picker stood before it moved into Settings.
  const continueBtn = el('button', 'btn continue-btn');
  continueBtn.type = 'button';
  continueBtn.hidden = true;
  const continueIcon = el('span', 'continue-icon');
  continueIcon.setAttribute('aria-hidden', 'true');
  continueIcon.innerHTML = PLAY_SVG;
  const continueWord = el('span', 'continue-word', t('ui.menu.continue'));
  const continueName = el('span', 'continue-name');
  const continueText = el('span', 'continue-text');
  continueText.append(continueWord, continueName);
  continueBtn.append(continueIcon, continueText);
  hero.append(logo, tagline, continueBtn);

  /**
   * One counter of the resource bar: a coin with the icon, and the number beside it —
   * "8/38", or a bare "2" — the way a game shows its currencies. The sentence it stands
   * for ("8 of 38 unlocked") is in the chip too, hidden from the eye, for a screen reader
   * and any text search of the page; and it is the tooltip a mouse can reach.
   */
  interface Chip {
    chip: HTMLElement;
    value: HTMLElement;
    said: HTMLElement;
  }
  const makeChip = (tag: 'span' | 'a' | 'button', kind: string, icon: string): Chip => {
    const chip = el(tag, `stat chip chip-${kind}`);
    const coin = el('span', 'chip-icon');
    coin.setAttribute('aria-hidden', 'true');
    coin.innerHTML = icon;
    const value = el('span', 'chip-value');
    value.setAttribute('aria-hidden', 'true');
    const said = el('span', 'chip-said');
    chip.append(coin, value, said);
    return { chip, value, said };
  };
  const writeChip = (
    c: Chip,
    name: string,
    nodes: Record<string, Node>,
    params: TParams,
    tip?: string,
  ) => {
    const full = t(`ui.menu.stat.${name}`, params);
    // The two counters out of a total keep the translator's own "n/total"; the other two
    // are a bare number, which is what the coin beside it is for.
    if (name === 'unlocked' || name === 'achievements')
      c.value.replaceChildren(...tParts(`ui.menu.stat.tight.${name}`, nodes, params));
    else c.value.replaceChildren(...Object.values(nodes));
    c.said.textContent = full;
    setTip(c.chip, tip || full);
  };
  /** A tooltip, kept in step once gameFeel.ts has lifted it into its drawn note. */
  const setTip = (node: HTMLElement, text: string) => {
    if (node.dataset.tip !== undefined) node.dataset.tip = text;
    else node.title = text;
  };

  // The resource bar
  const strip = el('div', 'progress-strip resource-bar');
  const credits = makeChip('button', 'credits', STAR_COIN_SVG);
  const creditsEl = credits.chip as HTMLButtonElement;
  creditsEl.type = 'button';
  const creditsNum = el('b', 'stat-num', '0');
  /**
   * What a credit is for, said on its chip: a "Spend" tag while there is one to spend, and
   * the chip is then the way to the padlocks — they stand after every puzzle the player
   * already has, a page or two on, so pointing at them and leaving the player to find them
   * would be half an answer. Without a credit, pressing it says how to earn one.
   */
  const spendTag = el('span', 'chip-tag', t('ui.menu.spend'));
  spendTag.setAttribute('aria-hidden', 'true');
  spendTag.hidden = true;
  creditsEl.append(spendTag);
  let hintText = '';
  creditsEl.addEventListener('click', () => {
    if (!spendTag.hidden) jumpToLocked();
    else if (hintText) toast(hintText);
  });
  // Rebuilt on every change rather than written once: "credit" and "credits" are different
  // words, and in several languages the whole sentence changes shape with the number.
  const renderCredits = (count: number) => {
    writeChip(credits, 'credits', { n: creditsNum }, { n: count, count }, hintText);
  };
  const unlocked = makeChip('span', 'unlocked', OPEN_LOCK_SVG);
  const unlockedEl = unlocked.chip;
  const unlockedNum = el('b', 'stat-num', '0');
  const renderUnlocked = (count: number) => {
    writeChip(unlocked, 'unlocked', { n: unlockedNum }, { n: count, total: menuGames.length });
  };
  const solved = makeChip('span', 'solved', CHECK_SVG);
  const solvedEl = solved.chip;
  const solvedNum = el('b', 'stat-num', '0');
  const renderSolved = (count: number) => {
    writeChip(solved, 'solved', { n: solvedNum }, { n: count });
  };
  // The trophy cabinet: a counter like the others, and the way in to the Achievements page.
  const ach = makeChip('a', 'achievements', TROPHY_SVG);
  const achEl = ach.chip as HTMLAnchorElement;
  achEl.classList.add('ach-link');
  achEl.href = '#/achievements';
  const achNum = el('b', 'stat-num', '0');
  const renderAchievements = () => {
    const { earned, total } = achievementTotals();
    writeChip(ach, 'achievements', { n: achNum }, { n: earned, total });
    // A link reads its `aria-label` in place of its text, so it says the whole sentence.
    achEl.setAttribute('aria-label', t('ui.menu.stat.achievements', { n: earned, total }));
    achNum.textContent = String(earned);
  };
  const setHint = (text: string, jump = false) => {
    hintText = text;
    spendTag.hidden = !jump;
    creditsEl.classList.toggle('can-spend', jump);
  };

  // Search. Thirty-eight cards is a scroll, and the player who came for one puzzle knows
  // it by a name the card may not carry — so the field matches the familiar names too.
  // A magnifier in the bar until it is wanted; pressed, it opens out into the field.
  const searchBox = el('div', 'menu-search');
  const searchIcon = el('button', 'btn round-btn menu-search-toggle');
  searchIcon.type = 'button';
  searchIcon.innerHTML = SEARCH_SVG;
  searchIcon.setAttribute('aria-label', t('ui.menu.search.label'));
  searchIcon.setAttribute('aria-expanded', 'false');
  searchIcon.title = t('ui.menu.search.placeholder');
  const searchInput = el('input', 'sketch-input search-input');
  searchInput.type = 'search';
  searchInput.autocomplete = 'off';
  searchInput.spellcheck = false;
  searchInput.placeholder = t('ui.menu.search.placeholder');
  searchInput.setAttribute('aria-label', t('ui.menu.search.label'));
  searchInput.setAttribute('enterkeyhint', 'search');
  const searchClear = el('button', 'btn search-clear', '×');
  searchClear.type = 'button';
  searchClear.setAttribute('aria-label', t('ui.menu.search.clear'));
  searchClear.hidden = true;
  searchBox.append(searchIcon, searchInput, searchClear);
  searchInput.id = 'menu-search-field';
  searchIcon.setAttribute('aria-controls', searchInput.id);

  // The counters on the reading side, the tools — search and the gear — on the other. The
  // sound switch and the language picker live in Settings now (settings.ts).
  const counters = el('div', 'menu-counters');
  counters.append(creditsEl, unlockedEl, solvedEl, achEl);
  // Surprise me: a pair of dice that open a puzzle for the player who would rather play
  // than choose (`surprise.ts`). Never the game they have just come back from.
  const surpriseBtn = el('button', 'btn round-btn menu-surprise');
  surpriseBtn.type = 'button';
  surpriseBtn.innerHTML = DICE_SVG;
  surpriseBtn.setAttribute('aria-label', t('ui.menu.surprise'));
  setTip(surpriseBtn, t('ui.menu.surprise'));
  surpriseBtn.addEventListener('click', () => {
    const open = menuGames.filter((g) => isUnlocked(g.id)).map((g) => g.id);
    const slug = pickSurprise(
      open,
      getProgress().solved,
      lastSurprise ?? opts.returning ?? null,
      Math.random(),
    );
    if (!slug) return;
    lastSurprise = slug;
    track('surprise_open', { game: slug });
    const card = cardFor(slug);
    // The card the dice landed on takes off, the way a card picked by hand does.
    if (card && !card.hidden && !card.classList.contains('off-page')) {
      (card as HTMLElement).click();
    } else {
      location.hash = `#/${slug}`;
    }
  });
  const tools = el('div', 'menu-tools');
  tools.append(surpriseBtn, searchBox, settingsButton('menu-settings'));
  strip.append(counters, tools);
  head.append(hero, strip);

  // One shelf, the puzzles that can be played first and the locked ones after them. It was
  // two tabs, and a player who never opened the second one never learned there was
  // anything to earn: a padlock on the shelf is the invitation.
  const grid = el('div', 'card-grid');
  grid.id = 'shelf';
  // Ziggy delivers the locked message once, here, rather than on each of the thirty cards
  // it is about: one mascot is a character, thirty in a grid is a texture.
  const lockedNote = el('p', 'section-note');
  const lockedZig = el('span', 'section-ziggy');
  const lockedNoteText = el('span');
  // The one who is holding the padlocks shut, so he is also the one who answers when the
  // player tries one without a credit and the one who celebrates when they spend one.
  const lockedMascot = mountMascot(lockedZig, { tilt: -8 });
  if (lockedMascot) lockedNote.append(lockedZig);
  lockedNote.append(lockedNoteText);
  /** The stage the cards stand on: exactly the room the masthead and the pager leave. */
  const shelf = el('div', 'shelf');

  // Says so out loud when a query matches nothing, rather than leaving the player looking
  // at a page that has quietly gone blank. `aria-live`, so a screen reader hears it too.
  const noMatch = el('p', 'menu-empty');
  noMatch.hidden = true;
  noMatch.setAttribute('aria-live', 'polite');
  // A dead end deserves a face rather than a bare line of text. He slumps while the page
  // has nothing on it and picks himself up the moment a query matches again — which is
  // also why the sentence moved into a span of its own: the mascot has to survive the
  // rewrite that happens on every keystroke.
  const noMatchZig = el('span', 'empty-ziggy');
  const noMatchText = el('span');
  const emptyMascot = mountMascot(noMatchZig, { tilt: 6, eyes: 'e5' });
  if (emptyMascot) noMatch.append(noMatchZig);
  noMatch.append(noMatchText);

  shelf.append(grid, noMatch);
  // The rule for the locked cards goes under the box.
  page.append(head, shelf, lockedNote);
  root.append(page);
  const pager: Pager = createPager({
    viewport: shelf,
    grid: () => grid,
    items: () => [...grid.children].filter((c) => !(c as HTMLElement).hidden) as HTMLElement[],
  });
  page.append(pager.controls);

  /** Whether a card is standing on the shelf now: on the open page. */
  const onScreen = (card: HTMLElement | null): card is HTMLElement =>
    !!card && card.getClientRects().length > 0;
  /** The cards on the page on show, for an entrance. */
  const shownCards = () =>
    [...grid.children].filter(
      (c) => !(c as HTMLElement).hidden && !c.classList.contains('off-page'),
    );
  const cardFor = (slug: string) =>
    grid.querySelector<HTMLElement>(`.card[data-slug="${CSS.escape(slug)}"]`);

  const pending: { game: Game; canvas: HTMLCanvasElement }[] = [];
  let cancelled = false;
  let thumbsScheduled = false;
  /** What is typed in the search field, kept across rebuilds and unlocks. */
  let query = '';
  /**
   * The card still flying back into its slot (`opts.returning`), until it has landed. A
   * rebuild meanwhile — a credit spent, the store answering — draws its slot empty too, so
   * there is still a hole for the flight to come down into; once it has landed a rebuild
   * draws it like any other card. It used to read `opts.returning` for the life of the
   * page, so unlocking a puzzle after coming back left an empty slot where the card was.
   */
  let homing = opts.returning ?? null;
  /**
   * Padlocks coming off: the credit is only spent once the padlock animation is over, so
   * until then it is spoken for. Two padlocks tapped in quick succession on one credit used
   * to both pass the check, and the second celebrated a puzzle that stayed locked.
   */
  const unlocking = new Set<string>();

  /** Which games are open right now, so a change can be told from a mere credit change. */
  function lockSignature(): string {
    const p = getProgress();
    return `${p.unlockAll ? 1 : 0}|${[...p.unlocked].sort().join(',')}`;
  }
  let lastLocks = lockSignature();
  /**
   * The menu redraws itself right after its own edits, so while one is in flight the
   * progress listener must stay out of the way — otherwise it would tear the grid down
   * underneath the unlock animation that is still running on one of its cards.
   */
  let editing = false;
  function selfUpdate(fn: () => void): void {
    editing = true;
    try {
      fn();
    } finally {
      editing = false;
    }
  }

  function makeCard(game: Game, locked: boolean): HTMLElement {
    const p = getProgress();
    const card = el(locked ? 'div' : 'a', 'card sketch') as HTMLElement;
    card.dataset.slug = game.id;
    // Folded once here rather than on every keystroke: the search compares against this.
    card.dataset.search = searchHaystack(game);
    if (!locked) (card as HTMLAnchorElement).href = `#/${game.id}`;
    else card.classList.add('locked');
    const name = gameName(game);
    const description = gameDescription(game);
    // *Every* familiar name goes in the label, though only the best-known one is printed
    // below: this is what a screen reader reads out, and what the browser's own Ctrl+F
    // searches, so the card stays findable by any name the puzzle goes by.
    const alias = gameAlsoKnownAs(game);
    const labelKey = alias
      ? locked
        ? 'ui.menu.card.labelLockedAlias'
        : 'ui.menu.card.labelAlias'
      : locked
        ? 'ui.menu.card.labelLocked'
        : 'ui.menu.card.label';
    card.setAttribute('aria-label', t(labelKey, { name, description, alias: alias ?? '' }));
    const thumbWrap = el('div', 'thumb');
    const canvas = document.createElement('canvas');
    canvas.width = 1;
    canvas.height = 1;
    thumbWrap.append(canvas);
    if (locked) {
      const lock = el('div', 'lock-badge');
      lock.innerHTML = LOCK_SVG;
      thumbWrap.append(lock);
    }
    // The board this card was left on is solved: it wears a stamp for as long as it shows
    // that board. Coming back to it, the stamp waits to come down as the card lands.
    if (!locked && leftSolved(game.id)) {
      thumbWrap.insertAdjacentHTML('beforeend', STAMP_SVG);
      if (homing === game.id) thumbWrap.lastElementChild!.setAttribute('data-pending', '');
    }
    if (!locked && homing === game.id) card.classList.add('out');
    const h2 = el('h2', undefined, name);
    card.append(thumbWrap, h2);
    // The name the player came looking for, printed as a name: a subtitle in the title's
    // own face rather than a sentence about the card. One name, never the list.
    const familiar = bestKnownName(game);
    if (familiar) card.append(el('p', 'card-alias', familiar));
    card.append(el('p', undefined, description));
    const solved = p.solved[game.id] ?? 0;
    if (solved > 0 && !locked) {
      card.append(el('div', 'solved-tag', t('ui.menu.card.solvedTag', { n: solved })));
    }
    if (locked) {
      const btn = el('button', 'btn unlock-btn', t('ui.menu.card.unlock'));
      btn.type = 'button';
      // Thirty buttons all called "Unlock · 1 credit": each also says which puzzle it opens.
      h2.id = `card-name-${game.id}`;
      btn.setAttribute('aria-describedby', h2.id);
      card.append(btn);
      const tryUnlock = (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        // Pressed from the keyboard, the button is about to vanish with its card; the
        // player's place moves with the puzzle to its new slot instead of falling to the top.
        const hadFocus = document.activeElement === btn;
        // The card itself is a way to unlock it too, and stays clickable while the button
        // is disabled: one padlock comes off once.
        if (unlocking.has(game.id)) return;
        if (getProgress().credits - unlocking.size <= 0) {
          wiggle(card);
          // Ziggy says no from the heading he delivered the rule on, so the refusal comes
          // from the same place the rule did rather than only from the card under the
          // cursor.
          lockedMascot?.nope();
          // The card shakes its head; the same dull thud the board gives a move it cannot
          // make says so to anyone not watching that corner of the screen.
          playSound('reject');
          toast(t('ui.menu.noCredit'));
          return;
        }
        btn.disabled = true;
        unlocking.add(game.id);
        const lockEl = card.querySelector<HTMLElement>('.lock-badge');
        unlockCard(card, lockEl, () => {
          unlocking.delete(game.id);
          // Where the card is standing as the padlock comes off, read before the grid is
          // rebuilt around its absence. See `flyToShelf`.
          const from = card.getBoundingClientRect();
          const pageBefore = pager.page;
          let opened = false;
          selfUpdate(() => (opened = unlockGame(game.id)));
          // Left while the padlock was coming off: the credit is spent, the page is gone.
          if (cancelled) return;
          if (!opened) {
            // The credit went elsewhere meanwhile (the platform's store answering with
            // fewer): the padlock stays on, and says why, rather than celebrating.
            btn.disabled = false;
            if (lockEl) gsap.set(lockEl, { clearProps: 'all' });
            wiggle(card);
            playSound('reject');
            toast(t('ui.menu.noCredit'));
            return;
          }
          playSound('unlock');
          // Both of them: the one who was guarding the padlocks and the one up in the
          // masthead. It is the happiest thing that happens on this page.
          lockedMascot?.cheer();
          logoMascot?.cheer();
          // Spending a hard-earned credit is the collection's happiest beat, so this is
          // where the CrazyGames site gets told to celebrate too (a no-op off-platform).
          happytime();
          rebuild();
          // The rebuild keeps the page the player was on, so the next padlock along is
          // still under their hand.
          pager.goTo(pageBefore);
          const arrived = cardFor(game.id);
          // Where it lands, read before the flight moves it back to where it came from.
          // It joins the end of the playable cards, which is often a page back from the
          // padlock it came out of; then it stays there and the name rises where it was.
          const to = onScreen(arrived) ? arrived.getBoundingClientRect() : null;
          if (onScreen(arrived)) flyToShelf(arrived, from);
          if (hadFocus) {
            const next = onScreen(arrived) ? arrived : (firstShownLocked() ?? shownCards()[0]);
            (
              next?.querySelector<HTMLElement>('.unlock-btn') ?? (next as HTMLElement | undefined)
            )?.focus({ preventScroll: true });
          }
          // Anchored to the card on its way, so the name lands where the player is looking
          // rather than over whichever puzzle has taken its place on the shelf. A shelf off
          // screen (on a phone it always is) would take the name out of sight with it, so
          // then it rises from the spot the card left. The name rises from the card's top
          // edge, so that edge is what has to be on screen: a shelf showing only its bottom
          // strip at the top of the window put the name above the window (desktop, the
          // third locked card).
          const shelfInView = !!to && to.top >= 0 && to.top < window.innerHeight - 40;
          floatLabel(shelfInView ? arrived! : from, t('ui.menu.card.unlocked', { name }));
        });
      };
      btn.addEventListener('click', tryUnlock);
      card.addEventListener('click', tryUnlock);
    }
    // A rebuild throws every canvas away and makes a new one, so a preview this page has
    // already painted is copied straight back in. Only a first sighting joins the queue —
    // otherwise spending a credit would blank all thirty-eight cards for a second or two
    // while the queue worked its way through them again.
    // The board the player left, when they have been in this one, and otherwise the stock
    // preview.
    if (!paintLeftBoard(game, canvas) && !paintCachedThumbnail(game, canvas))
      pending.push({ game, canvas });
    return card;
  }

  function scheduleThumbs() {
    if (thumbsScheduled) return;
    thumbsScheduled = true;
    const step = () => {
      if (cancelled) return;
      const next = pending.shift();
      if (!next) {
        thumbsScheduled = false;
        return;
      }
      if (next.canvas.isConnected) {
        try {
          renderThumbnail(next.game, next.canvas);
          // Previews arrive one per frame, so without this the grid fills in with a
          // succession of pictures snapping into empty frames. Fading each one up as it
          // lands turns that into the page drawing itself.
          revealThumb(next.canvas);
        } catch (e) {
          console.error(`thumbnail for ${next.game.id} failed`, e);
        }
      }
      requestAnimationFrame(step);
    };
    // A canvas keeps whatever face it was painted in, so the previews wait for the hand
    // lettering rather than baking a fallback into every digit on the page (`fonts.ts`).
    void handFontReady().then(() => requestAnimationFrame(step));
  }

  /**
   * Which cards the query leaves standing. A query that matches nothing says so instead
   * of leaving the page mysteriously blank.
   */
  function applyFilter() {
    const tokens = searchTokens(query);
    // Cards a backspace has just brought back. They are the only ones worth animating:
    // narrowing a query should reflow the moment you type, and it is the reappearing that
    // needs a beat, not the disappearing. See `filterIn`.
    const revealed: HTMLElement[] = [];
    let shown = 0;
    let locked = 0;
    for (const node of grid.children) {
      const card = node as HTMLElement;
      const show = matchesSearch(card.dataset.search ?? '', tokens);
      if (show && card.hidden) revealed.push(card);
      card.hidden = !show;
      if (show) shown++;
      if (show && card.classList.contains('locked')) locked++;
    }
    filterIn(revealed);
    // The rule is there while a padlock is on the shelf, and only then.
    lockedNoteText.textContent = t('ui.menu.lockedNote');
    lockedNote.hidden = locked === 0;
    // Every keystroke starts the matches over from the first page.
    pager.goTo(0);
    pager.refresh();
    const found = shown > 0;
    noMatchText.textContent = found ? '' : t('ui.menu.search.empty', { q: query.trim() });
    // Popped in rather than switched on: with the grid gone the page is suddenly empty,
    // and one line of text appearing out of nowhere in the middle of it reads as a glitch.
    const wasHidden = noMatch.hidden;
    noMatch.hidden = found;
    if (!found && wasHidden) {
      popIn(noMatch, 0.9);
      // A beat after the line arrives, so the slump is something he does rather than the
      // pose he turned up in.
      gsap.delayedCall(0.35, () => {
        if (noMatch.isConnected && !noMatch.hidden) emptyMascot?.droop();
      });
    } else if (found && !wasHidden) {
      emptyMascot?.perk();
    }
    searchClear.hidden = !searchBox.classList.contains('open');
  }

  function setQuery(next: string) {
    query = next;
    applyFilter();
  }

  /** Open the field out of the magnifier, or fold it back into it. */
  function setSearchOpen(open: boolean, focus = true) {
    searchBox.classList.toggle('open', open);
    strip.classList.toggle('searching', open);
    searchIcon.setAttribute('aria-expanded', String(open));
    searchClear.hidden = !open;
    if (!focus) return;
    if (open) searchInput.focus({ preventScroll: true });
    else searchIcon.focus({ preventScroll: true });
  }
  searchIcon.addEventListener('click', () => {
    const open = !searchBox.classList.contains('open');
    if (!open && query) clearSearch(false);
    setSearchOpen(open);
  });
  searchInput.addEventListener('input', () => setQuery(searchInput.value));
  searchInput.addEventListener('keydown', (e) => {
    // Escape empties the field and a second one folds it away; Enter puts the on-screen
    // keyboard away so the phone can show what was found. Neither submits anything: the
    // list is already filtered.
    if (e.key === 'Escape') {
      e.preventDefault();
      if (searchInput.value) clearSearch();
      else setSearchOpen(false);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      searchInput.blur();
    }
  });
  // An empty field the player has moved on from folds back into its magnifier.
  searchInput.addEventListener('blur', () => {
    requestAnimationFrame(() => {
      if (!query && !searchBox.contains(document.activeElement)) setSearchOpen(false, false);
    });
  });
  function clearSearch(refocus = true) {
    searchInput.value = '';
    setQuery('');
    if (refocus) searchInput.focus();
  }
  // The cross empties a query; on an empty field it closes the field.
  searchClear.addEventListener('click', () => {
    if (query) clearSearch();
    else setSearchOpen(false);
  });

  const firstShownLocked = () =>
    [...grid.children].find((c) => !(c as HTMLElement).hidden && c.classList.contains('locked')) as
      HTMLElement | undefined;

  /**
   * Turn to the page with the first padlock on it and put its unlock button under the
   * player's hand, so the keyboard lands there too.
   */
  function jumpToLocked() {
    const first = firstShownLocked();
    if (!first) return;
    const before = pager.page;
    pager.showItem(first, true);
    if (pager.page === before) pulse(first, 1.05);
    first.querySelector<HTMLButtonElement>('.unlock-btn')?.focus({ preventScroll: true });
  }

  function updateStrip() {
    const p = getProgress();
    const unlockedCount = p.unlockAll
      ? menuGames.length
      : menuGames.filter((g) => isUnlocked(g.id)).length;
    // The hint first: it is the credit chip's tooltip.
    if (p.unlockAll) setHint(t('ui.menu.hint.allOpen'));
    else if (unlockedCount >= menuGames.length) setHint(t('ui.menu.hint.complete'));
    else if (p.credits > 0) setHint(t('ui.menu.hint.spend', { n: p.credits }), true);
    else setHint(t('ui.menu.hint.earn'));
    renderCredits(p.credits);
    renderUnlocked(unlockedCount);
    renderSolved(totalSolved());
    renderAchievements();
    countTo(creditsNum, p.credits);
    countTo(unlockedNum, unlockedCount);
    countTo(solvedNum, totalSolved());
    creditsEl.classList.toggle('has-credits', p.credits > 0);
  }

  function rebuild(animate = false) {
    pending.length = 0;
    grid.innerHTML = '';
    const unlocked = menuGames.filter((g) => isUnlocked(g.id));
    const locked = menuGames.filter((g) => !isUnlocked(g.id));
    for (const g of unlocked) grid.append(makeCard(g, false));
    for (const g of locked) grid.append(makeCard(g, true));
    applyFilter();
    lastLocks = lockSignature();
    updateStrip();
    scheduleThumbs();
    // Only what the filter left standing: a card hidden by a query has nothing to fade in.
    if (animate) staggerIn(shownCards());
  }

  // A card flying back into the box brings the box in with it; the cards stay where they lie.
  rebuild(!opts.returning);

  /**
   * Continue: shown when a puzzle the player can open was left in progress. It goes the
   * way the card does — the same route, so the card lifts out of the box and turns over
   * into the sheet (flight.ts) — after turning the shelf to the card's page if it is not
   * on this one, so that there is a card on screen to fly.
   */
  function paintContinue() {
    const slug = continueSlug((s) => menuGames.some((g) => g.id === s) && isUnlocked(s));
    const game = slug ? menuGames.find((g) => g.id === slug) : undefined;
    continueBtn.hidden = !game;
    if (!game) return;
    const name = gameName(game);
    continueBtn.dataset.slug = game.id;
    continueName.textContent = name;
    continueBtn.setAttribute('aria-label', t('ui.menu.continueLabel', { name }));
    setTip(continueBtn, t('ui.menu.continueLabel', { name }));
  }
  paintContinue();
  let continueTimer = 0;
  continueBtn.addEventListener('click', () => {
    const slug = continueBtn.dataset.slug;
    if (!slug) return;
    const card = cardFor(slug);
    const go = () => {
      location.hash = `#/${slug}`;
    };
    if (!card || card.hidden || !card.classList.contains('off-page')) {
      go();
      return;
    }
    const before = pager.page;
    pager.showItem(card, true);
    // The page turn is a quarter of a second; the card takes off once it has landed.
    if (pager.page === before || prefersReducedMotion()) go();
    else continueTimer = window.setTimeout(go, 280);
  });

  /**
   * Say something about the puzzle the player has just finished.
   *
   * Coming back from a win was silent: the grid rebuilt, staggered itself in exactly as it
   * always does, and the card they had just solved sat there with a number on it that
   * nobody ever saw change. Everything else in the collection celebrates — the board
   * pulses, confetti goes up, a credit floats out of the chip — and then the one screen
   * that keeps the score said nothing at all.
   *
   * A beat after the grid has landed, so it reads as a remark about that card rather than
   * as one more card arriving.
   */
  function congratulate(slug: string) {
    const card = cardFor(slug);
    if (!card || card.hidden || card.classList.contains('locked')) return;
    // The shelf opens on the page that holds the card they came back from.
    pager.showItem(card);
    if (opts.returning === slug) {
      // It is flying back into its slot: the landing is its bump, and the tally comes
      // down with it rather than half a second into the flight.
      afterLanding = () => {
        logoMascot?.cheer();
        const tag = card.querySelector<HTMLElement>('.solved-tag');
        if (tag) popIn(tag, 0.6);
      };
      return;
    }
    logoMascot?.cheer();
    gsap.delayedCall(prefersReducedMotion() ? 0 : 0.55, () => {
      if (!card.isConnected || card.hidden) return;
      pulse(card, 1.05);
      // The tally is the thing that changed, so it is the thing that arrives.
      const tag = card.querySelector<HTMLElement>('.solved-tag');
      if (tag) popIn(tag, 0.6);
    });
  }
  let afterLanding: (() => void) | null = null;
  const fresh = takeFreshSolve();
  if (fresh) congratulate(fresh);
  else if (opts.returning) {
    const card = cardFor(opts.returning);
    if (card && !card.hidden) pager.showItem(card);
  }

  gsap.fromTo(
    logo,
    { y: -18, opacity: 0 },
    { y: 0, opacity: 1, duration: 0.5, ease: 'back.out(1.6)' },
  );
  gsap.fromTo(
    logo,
    { '--underline': 0 },
    { '--underline': 1, duration: 0.6, delay: 0.3, ease: 'power2.out' },
  );
  // Poke the mascot and he hops. Throttled, because the pointer crosses a masthead on its
  // way to everything else on the page and a mascot that hops at every passing cursor is
  // a mascot nobody looks at twice. Pointer *and* click, so a phone can poke him too.
  let lastPoke = 0;
  const poke = () => {
    const now = Date.now();
    if (now - lastPoke < 1400) return;
    lastPoke = now;
    logoMascot?.cheer();
  };
  logoMark.addEventListener('pointerenter', poke);
  logoMark.addEventListener('click', poke);
  // Progress can also change from *outside* the menu: the CrazyGames store answers a
  // moment after boot, and what it hands back may unlock games this grid was drawn
  // without. A changed lock set means a full rebuild; anything else is just the strip.
  const unsub = onProgressChange(() => {
    if (editing) return;
    if (lockSignature() !== lastLocks) rebuild(true);
    else updateStrip();
  });
  // The day's visit is counted after the menu is drawn, and a badge it earns (a third day
  // played, or one an older save was already due) came down as a card over a trophy count
  // that still said the old number.
  const offAchievement = onAchievement(() => renderAchievements());

  return {
    landed() {
      // The flight put down the card it was aimed at; after a rebuild in the air that is no
      // longer the one in the grid, so the one that is gets its face back here.
      if (homing) {
        const card = cardFor(homing);
        card?.classList.remove('out');
        card?.querySelector('.card-stamp[data-pending]')?.removeAttribute('data-pending');
        homing = null;
      }
      const then = afterLanding;
      afterLanding = null;
      then?.();
    },
    destroy() {
      cancelled = true;
      clearTimeout(continueTimer);
      pager.destroy();
      document.documentElement.classList.remove('screen');
      unsub();
      offAchievement();
      // Idle loops repeat forever; a mascot left running on a removed page would keep
      // GSAP's ticker awake for the rest of the session.
      logoMascot?.destroy();
      lockedMascot?.destroy();
      emptyMascot?.destroy();
      page.remove();
    },
  };
}
