import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { EMPTY, FULL } from './clues';
import { geometry } from './index';
import type { PatternState, PatternUI } from './index';

/** One grid cell, or a run of them, as a canvas rectangle. */
function cells(state: PatternState, t: number, x: number, y: number, w = 1, h = 1): TutorialRect {
  const g = geometry(state, t);
  return { x: g.gx + x * t, y: g.gy + y * t, w: w * t, h: h * t };
}

function centre(state: PatternState, t: number, x: number, y: number) {
  const g = geometry(state, t);
  return { x: g.gx + (x + 0.5) * t, y: g.gy + (y + 0.5) * t };
}

/** The strip of clue numbers written above column `x`. */
function colClue(state: PatternState, t: number, x: number): TutorialRect {
  const g = geometry(state, t);
  const n = Math.max(1, state.clues.cols[x].length);
  return { x: g.gx + x * t, y: g.gy - g.gutter - n * g.pitch, w: t, h: n * g.pitch };
}

const cellIs = (s: PatternState, x: number, y: number, v: number) => s.grid[y * s.w + x] === v;

export const tutorial: Tutorial<PatternState, PatternUI> = {
  steps: [
    {
      gameId: '4x4:1/1/1.2/3/3/1/2/2',
      text: 'The numbers beside each row and column are the lengths of its black runs, in order. Work out which squares are black and fill them in.',
      highlight: ({ state, tileSize }) => {
        const g = geometry(state, tileSize);
        return {
          x: g.border,
          y: g.border,
          w: g.gx + state.w * tileSize - g.border,
          h: g.gy + state.h * tileSize - g.border,
        };
      },
    },
    {
      text: 'The **third column** reads 1 2: one black, a gap, then two blacks. In four squares that fits only one way, with the pair at the bottom. **Drag** down over them.',
      highlight: ({ state, tileSize }) => [
        colClue(state, tileSize, 2),
        cells(state, tileSize, 2, 2, 1, 2),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(state, tileSize, 2, 2),
        to: centre(state, tileSize, 2, 3),
      }),
      waitFor: ({ state }) => cellIs(state, 2, 2, FULL) && cellIs(state, 2, 3, FULL),
      placement: 'below',
    },
    {
      text: 'That makes the square above the pair the gap. **Right-click** it to dot it, which marks a square you know is white.',
      highlight: ({ state, tileSize }) => [
        colClue(state, tileSize, 2),
        cells(state, tileSize, 2, 1),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(state, tileSize, 2, 1),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => cellIs(state, 2, 1, EMPTY),
      placement: 'above',
    },
    {
      text: 'And the top square of that column is the lone black of the clue. **Click** it.',
      highlight: ({ state, tileSize }) => [
        colClue(state, tileSize, 2),
        cells(state, tileSize, 2, 0),
      ],
      pointer: ({ state, tileSize }) => centre(state, tileSize, 2, 0),
      waitFor: ({ state }) => cellIs(state, 2, 0, FULL),
      placement: 'above',
    },
    {
      text: 'The **last column** reads 3. Wherever a run of three sits in four squares it always covers the middle two, so **drag** down over those.',
      highlight: ({ state, tileSize }) => [
        colClue(state, tileSize, 3),
        cells(state, tileSize, 3, 1, 1, 2),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(state, tileSize, 3, 1),
        to: centre(state, tileSize, 3, 2),
      }),
      waitFor: ({ state }) => cellIs(state, 3, 1, FULL) && cellIs(state, 3, 2, FULL),
      placement: 'below',
    },
    {
      text: 'A clue turns grey once its line is finished. Keep chipping away like that, or let **Solve** finish this one; a middle-click wipes a square back to unknown.',
      target: '[data-cmd="solve"]',
    },
  ],
};
