/**
 * The locale store: which language the page is in, how that was decided, and how to
 * change it. Deliberately shaped like `src/ui/progress.ts` — a getter, a setter and a
 * subscription — so the UI can re-render on a change without a reactive framework.
 */

import { catalogMissing, catalogSize, isCatalogLoaded, loadCatalog } from './catalog';
import { storage } from '../storage';

/** The source language. Everything falls back to it, and it is never a stub. */
export const DEFAULT_LOCALE = 'en';

/**
 * Every locale the app ships. Adding one is a data task: drop `src/i18n/locales/<code>.json`
 * in place and add the code here with its endonym. See `docs/I18N.md`.
 */
export const SUPPORTED_LOCALES = [
  'en',
  'ar',
  'cs',
  'da',
  'de',
  'el',
  'es',
  'fi',
  'fr',
  'hu',
  'id',
  'it',
  'ja',
  'ko',
  'nb',
  'nl',
  'pl',
  'pt',
  'ro',
  'ru',
  'sv',
  'th',
  'tr',
  'uk',
  'vi',
] as const;

export type Locale = (typeof SUPPORTED_LOCALES)[number];

/** Each language's name in itself, for the language switcher. */
export const LOCALE_NAMES: Record<string, string> = {
  en: 'English',
  ar: 'العربية',
  cs: 'Čeština',
  da: 'Dansk',
  de: 'Deutsch',
  el: 'Ελληνικά',
  es: 'Español',
  fi: 'Suomi',
  fr: 'Français',
  hu: 'Magyar',
  id: 'Bahasa Indonesia',
  it: 'Italiano',
  ja: '日本語',
  ko: '한국어',
  nb: 'Norsk bokmål',
  nl: 'Nederlands',
  pl: 'Polski',
  pt: 'Português',
  ro: 'Română',
  ru: 'Русский',
  sv: 'Svenska',
  th: 'ไทย',
  tr: 'Türkçe',
  uk: 'Українська',
  vi: 'Tiếng Việt',
};

/** Languages written right to left. Only Arabic is in the shipping set. */
const RTL = new Set(['ar', 'he', 'fa', 'ur', 'yi', 'dv', 'ps', 'ckb']);

export function isRTL(locale: string): boolean {
  return RTL.has(bareLanguage(locale));
}

export function textDirection(locale: string): 'ltr' | 'rtl' {
  return isRTL(locale) ? 'rtl' : 'ltr';
}

/** `pt-BR` → `pt`, `zh_Hans_CN` → `zh`. */
export function bareLanguage(tag: string): string {
  return normaliseTag(tag).split('-')[0];
}

/** Lower-case, `_` → `-`, whitespace trimmed. `PT_br` → `pt-br`. */
export function normaliseTag(tag: string): string {
  return tag.trim().toLowerCase().replace(/_/g, '-');
}

export function isSupported(tag: string): boolean {
  return (SUPPORTED_LOCALES as readonly string[]).includes(normaliseTag(tag));
}

/**
 * Pick the best supported locale for a list of user preferences, most-wanted first.
 *
 * Each preference is tried as an exact match and then as a bare language, so `pt-BR`
 * finds `pt` and `nb-NO` finds `nb`, before moving on to the next preference. Returns
 * `null` when nothing matches, which is the caller's cue to use English.
 */
export function matchLocale(
  prefs: readonly string[],
  supported: readonly string[] = SUPPORTED_LOCALES,
): string | null {
  const avail = new Map(supported.map((s) => [normaliseTag(s), s]));
  for (const raw of prefs) {
    if (!raw) continue;
    const tag = normaliseTag(raw);
    const exact = avail.get(tag);
    if (exact) return exact;
    const bare = avail.get(tag.split('-')[0]);
    if (bare) return bare;
  }
  return null;
}

/**
 * True when a locale ships real strings rather than an empty stub. Answered from the
 * generated `catalog-sizes.ts` for a language that has not been fetched, so the switcher
 * can label all 25 without downloading any of them.
 */
export function hasTranslations(locale: string): boolean {
  return locale === DEFAULT_LOCALE || catalogSize(locale) > 0;
}

/**
 * Fetch the strings for a locale (the active one by default) so `t()` can answer in it.
 * English is bundled, so this resolves immediately; any other language is one small chunk.
 * Never rejects — a catalogue that fails to arrive leaves the page in English.
 *
 * Call it *before* rendering: `src/main.ts` awaits it during boot, and `setLocaleAsync`
 * awaits it before switching, which is what keeps `t()` synchronous everywhere else.
 */
export function loadLocaleCatalog(locale: string = getLocale()): Promise<void> {
  return loadCatalog(locale);
}

// ------------------------------------------------------------------ persistence

const KEY = 'puzzlebox:lang';

function readStored(): string | null {
  const v = storage.getItem(KEY);
  return v && isSupported(v) ? normaliseTag(v) : null;
}

function writeStored(locale: string): void {
  // Through the tiered store, not `localStorage` directly: inside the CrazyGames iframe a
  // plain write is discarded, and the player's chosen language would silently revert to
  // whatever their browser reports on every reload.
  storage.setItem(KEY, locale);
}

/** `?lang=fr` anywhere in the URL (query string or after the hash route). */
export function localeFromUrl(href?: string): string | null {
  const url = href ?? (typeof location !== 'undefined' ? location.href : '');
  if (!url) return null;
  const m = /[?&#]lang=([A-Za-z-_]{2,10})/.exec(url);
  if (!m) return null;
  const tag = normaliseTag(m[1]);
  if (isSupported(tag)) return tag;
  const bare = matchLocale([tag]);
  return bare;
}

/**
 * `href` with every `lang=` parameter taken out (query string or after the hash route),
 * tidying the `?`/`&` it leaves behind. Used when the player picks a language themselves:
 * the address must stop overriding that choice on the next reload or hash change.
 */
export function urlWithoutLang(href: string): string {
  // A parameter list is whatever follows a `?` up to the next `#` (or the end); the hash
  // route may carry one of its own. Each is filtered separately.
  return href
    .replace(/\?([^#]*)/g, (_m, params: string) => {
      const kept = params.split('&').filter((p) => p && !/^lang=/i.test(p));
      return kept.length ? `?${kept.join('&')}` : '';
    })
    .replace(/#lang=[^&]*&?/i, '#');
}

/** The browser's language preferences, most-wanted first. */
function browserPrefs(): string[] {
  if (typeof navigator === 'undefined') return [];
  const langs = navigator.languages;
  if (Array.isArray(langs) && langs.length) return [...langs];
  return navigator.language ? [navigator.language] : [];
}

/**
 * Decide the starting locale: an explicit `?lang=` wins, then a remembered choice, then
 * the browser's preferences (but only for a language that actually ships strings, so a
 * half-finished translation never hijacks a page), then English.
 */
export function detectLocale(): string {
  const url = localeFromUrl();
  if (url) return url;
  const stored = readStored();
  if (stored) return stored;
  const detected = matchLocale(browserPrefs());
  if (detected && hasTranslations(detected)) return detected;
  return DEFAULT_LOCALE;
}

// ------------------------------------------------------------------ the store

type Listener = (locale: string) => void;
const listeners = new Set<Listener>();

let current: string | null = null;

export function getLocale(): string {
  if (current === null) current = detectLocale();
  return current;
}

/**
 * Switch language: remembers the choice, updates `<html lang>`/`<html dir>` and notifies
 * every subscriber so the current page can re-render.
 *
 * Synchronous by contract. If the new language's catalogue has not been fetched yet the
 * re-render lands in English, so this kicks the fetch off and notifies a second time when
 * it arrives rather than leaving the page wrong. Prefer {@link setLocaleAsync}, which
 * waits first and so renders once, already translated.
 */
export function setLocale(locale: string, opts: { persist?: boolean } = {}): void {
  const next = isSupported(locale) ? normaliseTag(locale) : DEFAULT_LOCALE;
  if (next === getLocale()) return;
  current = next;
  if (opts.persist !== false) writeStored(next);
  applyLocaleToDocument();
  notify(next);
  if (!isCatalogLoaded(next)) {
    void loadCatalog(next).then(() => {
      if (current === next) notify(next);
    });
  }
}

/**
 * Switch language the way the UI should: wait for the catalogue, then switch, so the
 * single re-render `onLocaleChange` drives is already in the new language.
 */
export async function setLocaleAsync(
  locale: string,
  opts: { persist?: boolean } = {},
): Promise<void> {
  const next = isSupported(locale) ? normaliseTag(locale) : DEFAULT_LOCALE;
  if (next === getLocale()) return;
  await loadCatalog(next);
  // Offline, a catalogue that did not arrive would have switched a Dutch page to English
  // text under `lang="de"`. The language it is already in is the better of the two.
  if (catalogMissing(next)) return;
  setLocale(next, opts);
}

/**
 * Take the portal's idea of the player's language (CrazyGames' `systemInfo.locale`), which
 * the platform asks games to prefer over the browser's. It arrives a moment after boot, so
 * it only ever replaces a *guess*: an explicit `?lang=` or a language the player picked
 * themselves always wins, and it is not remembered — the portal will say it again next
 * visit. Resolves once any switch has rendered. Never rejects.
 */
export async function adoptPlatformLocale(tag: string | null): Promise<void> {
  if (!tag || localeFromUrl() || readStored()) return;
  const match = matchLocale([tag]);
  if (!match || !hasTranslations(match) || match === getLocale()) return;
  try {
    await setLocaleAsync(match, { persist: false });
  } catch {
    /* a catalogue that fails to arrive leaves the page as it was */
  }
}

function notify(locale: string): void {
  for (const fn of [...listeners]) fn(locale);
}

export function onLocaleChange(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** Reflect the locale on `<html>`: `lang` for screen readers, `dir` for Arabic. */
export function applyLocaleToDocument(): void {
  if (typeof document === 'undefined') return;
  const loc = getLocale();
  const root = document.documentElement;
  root.setAttribute('lang', loc);
  root.setAttribute('dir', textDirection(loc));
}

/**
 * For tests: forget the cached locale so detection runs again, or force one directly
 * (including a code that is not in `SUPPORTED_LOCALES`, so a throwaway fixture locale can
 * be exercised without shipping it).
 */
export function resetLocaleForTests(code?: string): void {
  current = code ?? null;
}
