import type { PALETTE, PaletteToken } from './palette';

/**
 * Achievements a game declares for itself: "win Mines without placing a flag", "solve a
 * Fifteen in the fewest possible moves". The shell owns everything else — storage, the
 * unlock toast, the Achievements page and the collection-wide ones such as "solve a
 * puzzle in ten different games" (`src/achievements/`). See `docs/ACHIEVEMENTS.md`.
 *
 * A game lists them in `Game.achievements`; like the rest of a game they live in its own
 * folder (`src/games/<slug>/achievements.ts` by convention) and their English text is
 * extracted into `en.json` by `npm run i18n:sync`.
 */

/** Bronze for a first step, silver for real skill, gold for a feat most players never do. */
export type AchievementTier = 'bronze' | 'silver' | 'gold';

/**
 * Everything known about a puzzle at the moment it ended. Handed to
 * {@link GameAchievement.test}, which reads it and returns whether the achievement is won.
 */
export interface PuzzleEndContext<P = any, S = any> {
  /** How it ended: 1 solved, -1 lost. */
  status: 1 | -1;
  /** The parameters the puzzle was dealt with. */
  params: P;
  /** Index into `game.presets`, or -1 for a custom size (never -1 for a win: see below). */
  preset: number;
  /** `game.presets.length`, so "the hardest preset" is `preset === presetCount - 1`. */
  presetCount: number;
  /** The board as it ended. */
  state: S;
  /** The board as it was dealt. */
  initial: S;
  /**
   * Every state from the deal — or from the last Restart, which puts the deal back — to the
   * end, in order (`history[0]` equals `initial`, the last is `state`). Undone branches and
   * an attempt thrown away by Restart are not in it: this is the line the player kept.
   */
  history: readonly S[];
  /**
   * Moves since the last Restart (`Midend.movesSinceRestart`): what a move counter on the
   * status line shows. Hints count as moves; the restart and the attempt before it don't.
   */
  moves: number;
  /** Undo presses since the deal, including ones later redone. */
  undos: number;
  /** Restarts since the deal. */
  restarts: number;
  /** Hint steps taken on the kept line. */
  hints: number;
  /** Seconds the page was visible between the deal and the end. */
  secs: number;
}

/**
 * The art for one badge: SVG markup for the picture inside the frame, in a 100×100 box.
 * The frame, the tier rim and the hand-drawn wobble are added by the shell; draw the
 * motif only, well inside 16–84, in palette colours (`c.ink`, `c.red`, …) — never a hex
 * literal. Keep it bold: the same art is shown at 40px in the unlock toast.
 */
export type BadgeArt = (c: typeof PALETTE) => string;

export interface GameAchievement<P = any, S = any> {
  /** Unique within the game, kebab-case (`no-flags`). The full id is `<slug>.<id>`. */
  id: string;
  /** English title, two to four words, shown on the badge. */
  name: string;
  /** English one-line condition, written as an instruction ("Win without…"). */
  description: string;
  tier: AchievementTier;
  /** Kept a mystery ("Secret achievement") until earned. For the joke ones. */
  hidden?: boolean;
  /** Background colour of the badge. Defaults by tier. */
  hue?: PaletteToken;
  art: BadgeArt;
  /**
   * Which ending is tested. Default `'win'`, and a win only counts when the player solved
   * it by hand at a preset size (no Solve button, hints within the allowance) — the same
   * rule that earns a credit, so a custom 2×2 cannot farm a gold badge. `'lose'` is for
   * the rueful ones ("step on a mine with your very first click").
   */
  on?: 'win' | 'lose';
  /** Whether this ending earns the achievement. Must be pure and cheap. */
  test(ctx: PuzzleEndContext<P, S>): boolean;
}

/** Helper for full type inference, as `defineGame` is for games. */
export function defineAchievements<P, S>(list: GameAchievement<P, S>[]): GameAchievement<P, S>[] {
  return list;
}
