import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { KeenState, KeenUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** The 3×3 walkthrough puzzle: a 2× cage over the top-left corner, 6× down the right
 *  column and 8+ over the rest. Its only solution is 213 / 132 / 321. */
const GAME_ID = '3:a__aa_c,m2m6a8';

/** Squares of the walkthrough grid, by position. */
const CORNER = 0;
const TOP_MID = 1;
const TOP_RIGHT = 2;
const MID = 4;

/** One rectangle per square of the cage that square `xy` belongs to. */
function cageRects(state: KeenState, xy: number, t: number): TutorialRect[] {
  const b = border(t);
  const cage = state.layout.cages[state.layout.whichCage[xy]];
  return cage.cells.map((c) => cellRect(c % state.w, Math.floor(c / state.w), t, b));
}

const cell = (state: KeenState, xy: number, t: number): TutorialRect =>
  cellRect(xy % state.w, Math.floor(xy / state.w), t, border(t));
const centre = (state: KeenState, xy: number, t: number) =>
  cellCentre(xy % state.w, Math.floor(xy / state.w), t, border(t));
/** Has digit `n` been pencilled into square `xy`? */
const pencilled = (state: KeenState, xy: number, n: number) =>
  state.pencil[xy * state.w + n - 1] === 1;

export const tutorial: Tutorial<KeenState, KeenUI> = {
  steps: [
    {
      gameId: GAME_ID,
      text: 'Fill in 1, 2 and 3 so each appears once in every row and column, and so the digits in each heavily outlined cage make its arithmetic clue.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.w),
    },
    {
      text: 'The **2×** cage multiplies to 2, so its digits are 1, 1 and 2. A cage may repeat a digit, but not down a row or column, so the 2 belongs in the corner: click that square and type **2**.',
      textTouch:
        'The **2×** cage multiplies to 2, so its digits are 1, 1 and 2. The 2 belongs in the corner: tap that square, then tap **2** on the keypad.',
      highlight: ({ state, tileSize }) => cageRects(state, CORNER, tileSize),
      target: '[data-key="2"]',
      pointer: ({ state, tileSize }) => centre(state, CORNER, tileSize),
      press: '2',
      waitFor: ({ state }) => state.grid[CORNER] === 2,
    },
    {
      text: 'The other two squares of the cage are the 1s. Click the square **right of the 2** and type **1**.',
      textTouch:
        'The other two squares of the cage are the 1s. Tap the square **right of the 2**, then tap **1** on the keypad.',
      highlight: ({ state, tileSize }) => cell(state, TOP_MID, tileSize),
      target: '[data-key="1"]',
      pointer: ({ state, tileSize }) => centre(state, TOP_MID, tileSize),
      press: '1',
      waitFor: ({ state }) => state.grid[TOP_MID] === 1,
    },
    {
      text: 'The top row already has its 2 and its 1, so the last square in it must be the 3. Click the **top-right square** and type **3**.',
      textTouch:
        'The top row already has its 2 and its 1, so the last square in it must be the 3. Tap the **top-right square**, then tap **3** on the keypad.',
      highlight: ({ state, tileSize }) => cell(state, TOP_RIGHT, tileSize),
      target: '[data-key="3"]',
      pointer: ({ state, tileSize }) => centre(state, TOP_RIGHT, tileSize),
      press: '3',
      waitFor: ({ state }) => state.grid[TOP_RIGHT] === 3,
    },
    {
      text: 'Only guessing at a square? **Right-click** the middle square and type **3** to pencil that digit in as a note instead of filling it in.',
      textTouch:
        'Only guessing at a square? **Long-press** the middle square and tap **3** to note that digit instead of filling it in. The **✎** key does the same for a square you tapped.',
      highlight: ({ state, tileSize }) => cell(state, MID, tileSize),
      target: '[data-key="pencil"]',
      pointer: ({ state, tileSize }) => ({
        ...centre(state, MID, tileSize),
        button: 'right' as const,
      }),
      press: '3',
      waitFor: ({ state }) => pencilled(state, MID, 3),
    },
    {
      text: 'Work the rest out the same way; a digit repeated in its row or column turns red, and so does a full cage that misses its clue. In the pause menu, **Marks** pencils every possibility in for you and **Solve** gives the answer away.',
      target: '[data-cmd="solve"]',
    },
  ],
};
