/**
 * Latin-square solver core and generator.
 *
 * A latin square of order `o` holds the digits 1..o once in every row and column. The
 * solver keeps a "cube" of candidates (for every square and digit, whether that digit
 * could still go there) and applies modes of reasoning of increasing sophistication:
 *
 *  - positional elimination: a digit has one place left in a row or column, or a square
 *    has one candidate left;
 *  - set elimination: k squares of a row or column whose candidates together are only k
 *    digits must hold exactly those digits (and the dual);
 *  - positional set elimination on a single digit across rows and columns;
 *  - forcing chains through squares with two candidates;
 *  - recursion: guess a digit in a constrained square and backtrack.
 *
 * Games plug their own deductions in through `userSolvers`, one per difficulty level,
 * and say at which level each generic technique becomes available. The result of a
 * solve is the hardest level that was needed, or one of the special codes below.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';

export const LATIN_IMPOSSIBLE = 10;
export const LATIN_AMBIGUOUS = 11;
export const LATIN_UNFINISHED = 12;

/** A game-specific deduction step: +1 progress, 0 nothing, -1 contradiction. */
export type UserSolver<C> = (solver: LatinSolver, ctx: C) => number;

export interface LatinLevels<C> {
  /** Level at which positional and numeric elimination are permitted. */
  simple: number;
  /** Level for set elimination within rows and columns. */
  set0: number;
  /** Level for positional set elimination on a single digit. */
  set1: number;
  /** Level for forcing chains. */
  forcing: number;
  /** Level at which guessing is permitted. */
  recursive: number;
  /** Game deductions, indexed by level; `null` where the game has none. */
  userSolvers: (UserSolver<C> | null)[];
}

export class LatinSolver {
  readonly o: number;
  /** cube[(y*o + x)*o + n-1]: digit n still possible at (x, y). */
  readonly cube: Uint8Array;
  /** The grid being solved (row-major), written to in place. */
  readonly grid: Uint8Array;
  /** row[y*o + n-1]: digit n already placed in row y. */
  readonly row: Uint8Array;
  /** col[x*o + n-1]: digit n already placed in column x. */
  readonly col: Uint8Array;

  constructor(grid: Uint8Array, o: number) {
    this.o = o;
    this.grid = grid;
    this.cube = new Uint8Array(o * o * o).fill(1);
    this.row = new Uint8Array(o * o);
    this.col = new Uint8Array(o * o);
    for (let y = 0; y < o; y++)
      for (let x = 0; x < o; x++) if (grid[y * o + x]) this.place(x, y, grid[y * o + x]);
  }

  /** Cube index of digit n at (x, y). */
  pos(x: number, y: number, n: number): number {
    return (y * this.o + x) * this.o + n - 1;
  }

  /** Whether digit n is still a candidate in square xy. */
  can(xy: number, n: number): boolean {
    return this.cube[xy * this.o + n - 1] !== 0;
  }

  /** Commit digit n to (x, y) and rule it out along its row and column. */
  place(x: number, y: number, n: number): void {
    const { o, cube } = this;
    for (let i = 1; i <= o; i++) if (i !== n) cube[this.pos(x, y, i)] = 0;
    for (let i = 0; i < o; i++) if (i !== y) cube[this.pos(x, i, n)] = 0;
    for (let i = 0; i < o; i++) if (i !== x) cube[this.pos(i, y, n)] = 0;
    this.grid[y * o + x] = n;
    this.row[y * o + n - 1] = 1;
    this.col[x * o + n - 1] = 1;
  }

  /**
   * Look at `o` cube entries starting at `start` with stride `step`: if exactly one is
   * still set, place it. Returns +1 progress, 0 nothing, -1 contradiction.
   */
  elim(start: number, step: number): number {
    const { o, cube } = this;
    let m = 0;
    let fpos = -1;
    for (let i = 0; i < o; i++) {
      if (cube[start + i * step]) {
        fpos = start + i * step;
        m++;
      }
    }
    if (m === 1) {
      const n = 1 + (fpos % o);
      const xy = Math.floor(fpos / o);
      if (!this.grid[xy]) {
        this.place(xy % o, Math.floor(xy / o), n);
        return 1;
      }
      return 0;
    }
    return m === 0 ? -1 : 0;
  }

  /**
   * Set elimination on the o×o boolean matrix whose (i, j) entry is
   * cube[start + i*step1 + j*step2]. Rows are the things being placed and columns their
   * possible values (or the other way round; the deduction is self-dual). After
   * discarding rows already decided, look for a set of columns that only as many rows
   * can use: those rows can then use nothing else.
   */
  setElim(start: number, step1: number, step2: number): number {
    const { o, cube } = this;
    const rowKeep = new Uint8Array(o).fill(1);
    const colKeep = new Uint8Array(o).fill(1);
    for (let i = 0; i < o; i++) {
      let count = 0;
      let first = -1;
      for (let j = 0; j < o; j++) {
        if (cube[start + i * step1 + j * step2]) {
          first = j;
          count++;
        }
      }
      if (count === 0) return -1;
      if (count === 1) {
        rowKeep[i] = 0;
        colKeep[first] = 0;
      }
    }
    const rows: number[] = [];
    const cols: number[] = [];
    for (let i = 0; i < o; i++) {
      if (rowKeep[i]) rows.push(i);
      if (colKeep[i]) cols.push(i);
    }
    const n = rows.length;
    if (n !== cols.length || n < 4) return 0;
    const masks = new Int32Array(n);
    for (let i = 0; i < n; i++) {
      let m = 0;
      for (let j = 0; j < n; j++) if (cube[start + rows[i] * step1 + cols[j] * step2]) m |= 1 << j;
      masks[i] = m;
    }
    const full = (1 << n) - 1;
    for (let set = 1; set < full; set++) {
      const count = popcount(set);
      if (count <= 1 || count >= n - 1) continue;
      let clear = 0;
      for (let i = 0; i < n; i++) if ((masks[i] & set) === 0) clear++;
      // More rows avoiding the set than there are columns left over means some earlier
      // deduction or clue was wrong.
      if (clear > n - count) return -1;
      if (clear < n - count) continue;
      let progress = 0;
      for (let i = 0; i < n; i++) {
        if ((masks[i] & set) === 0) continue;
        const kill = masks[i] & ~set;
        for (let j = 0; j < n; j++) {
          if (kill & (1 << j)) {
            cube[start + rows[i] * step1 + cols[j] * step2] = 0;
            progress = 1;
          }
        }
      }
      if (progress) return 1;
    }
    return 0;
  }

  /** Candidates of square xy as a bitmask with bit n set for digit n. */
  candidates(xy: number): number {
    const { o, cube } = this;
    let m = 0;
    const base = xy * o;
    for (let n = 1; n <= o; n++) if (cube[base + n - 1]) m |= 1 << n;
    return m;
  }

  /**
   * Forcing chains: a path of two-candidate squares, each adjacent pair (same row or
   * column) sharing a digit, such that ruling out digit N at the start forces N at the
   * end. A third square in line with both ends cannot then be N.
   */
  forcing(): number {
    const { o, cube } = this;
    const area = o * o;
    const number = new Int32Array(area);
    const queue = new Int32Array(area);
    for (let start = 0; start < area; start++) {
      const cand = this.candidates(start);
      if (popcount(cand) !== 2) continue;
      const sx = start % o;
      const sy = Math.floor(start / o);
      for (let n = 1; n <= o; n++) {
        if (!(cand & (1 << n))) continue;
        number.fill(o + 1);
        let head = 0;
        let tail = 0;
        queue[tail++] = start;
        number[start] = 31 - Math.clz32(cand & ~(1 << n));
        while (head < tail) {
          const xy = queue[head++];
          const x = xy % o;
          const y = Math.floor(xy / o);
          const currn = number[xy];
          for (let k = 0; k < 2 * o; k++) {
            const nb = k < o ? k * o + x : y * o + (k - o);
            if (nb === xy || number[nb] <= o) continue;
            if (!cube[nb * o + currn - 1]) continue;
            const c2 = this.candidates(nb);
            if (popcount(c2) === 2) {
              queue[tail++] = nb;
              number[nb] = 31 - Math.clz32(c2 & ~(1 << currn));
            }
            if (currn === n && (nb % o === sx || Math.floor(nb / o) === sy)) {
              cube[nb * o + n - 1] = 0;
              return 1;
            }
          }
        }
      }
    }
    return 0;
  }

  /** Row-wise and column-wise positional elimination, then numeric elimination. */
  diffSimple(): number {
    const { o } = this;
    for (let y = 0; y < o; y++) {
      for (let n = 1; n <= o; n++) {
        if (this.row[y * o + n - 1]) continue;
        const ret = this.elim(this.pos(0, y, n), o);
        if (ret !== 0) return ret;
      }
    }
    for (let x = 0; x < o; x++) {
      for (let n = 1; n <= o; n++) {
        if (this.col[x * o + n - 1]) continue;
        const ret = this.elim(this.pos(x, 0, n), o * o);
        if (ret !== 0) return ret;
      }
    }
    for (let xy = 0; xy < o * o; xy++) {
      if (this.grid[xy]) continue;
      const ret = this.elim(xy * o, 1);
      if (ret !== 0) return ret;
    }
    return 0;
  }

  /** Set elimination in every row and column, or (extreme) on every digit's positions. */
  diffSet(extreme: boolean): number {
    const { o } = this;
    if (!extreme) {
      for (let y = 0; y < o; y++) {
        const ret = this.setElim(this.pos(0, y, 1), o, 1);
        if (ret !== 0) return ret;
      }
      for (let x = 0; x < o; x++) {
        const ret = this.setElim(this.pos(x, 0, 1), o * o, 1);
        if (ret !== 0) return ret;
      }
    } else {
      for (let n = 1; n <= o; n++) {
        const ret = this.setElim(this.pos(0, 0, n), o * o, o);
        if (ret !== 0) return ret;
      }
    }
    return 0;
  }
}

export function popcount(v: number): number {
  v = v - ((v >>> 1) & 0x55555555);
  v = (v & 0x33333333) + ((v >>> 2) & 0x33333333);
  return (((v + (v >>> 4)) & 0x0f0f0f0f) * 0x01010101) >>> 24;
}

function solveTop<C>(s: LatinSolver, maxdiff: number, levels: LatinLevels<C>, ctx: C): number {
  let diff = levels.simple;
  outer: for (;;) {
    for (let i = 0; i <= maxdiff; i++) {
      const user = levels.userSolvers[i];
      let ret = user ? user(s, ctx) : 0;
      if (ret === 0 && i === levels.simple) ret = s.diffSimple();
      if (ret === 0 && i === levels.set0) ret = s.diffSet(false);
      if (ret === 0 && i === levels.set1) ret = s.diffSet(true);
      if (ret === 0 && i === levels.forcing) ret = s.forcing();
      if (ret < 0) return LATIN_IMPOSSIBLE;
      if (ret > 0) {
        diff = Math.max(diff, i);
        continue outer;
      }
    }
    break;
  }
  if (maxdiff >= levels.recursive) {
    const nsol = recurse(s, levels, ctx);
    if (nsol < 0) return LATIN_IMPOSSIBLE;
    if (nsol === 1) return levels.recursive;
    if (nsol > 1) return LATIN_AMBIGUOUS;
    return diff;
  }
  for (let xy = 0; xy < s.o * s.o; xy++) if (!s.grid[xy]) return LATIN_UNFINISHED;
  return diff;
}

/**
 * Guess in one of the most constrained empty squares and solve each branch fully.
 * Returns 0 if the grid was already complete, -1 for no solution, 1 for exactly one
 * (left in the grid) and 2 for several.
 */
function recurse<C>(s: LatinSolver, levels: LatinLevels<C>, ctx: C): number {
  const { o, grid } = s;
  let best = -1;
  let bestCount = o + 1;
  for (let xy = 0; xy < o * o; xy++) {
    if (grid[xy]) continue;
    const count = popcount(s.candidates(xy));
    if (count === 0) return -1;
    if (count < bestCount) {
      bestCount = count;
      best = xy;
    }
  }
  if (best === -1) return 0;
  const cand = s.candidates(best);
  const start = grid.slice();
  let found = 0;
  for (let n = 1; n <= o; n++) {
    if (!(cand & (1 << n))) continue;
    const out = start.slice();
    out[best] = n;
    const ret = solveTop(new LatinSolver(out, o), levels.recursive, levels, ctx);
    if (ret === LATIN_IMPOSSIBLE) continue;
    if (found === 0) grid.set(out);
    found += ret === LATIN_AMBIGUOUS ? 2 : 1;
    if (found > 1) return 2;
  }
  return found === 0 ? -1 : 1;
}

/**
 * Solve `grid` in place with techniques up to `maxdiff`. Returns the hardest level
 * needed, or LATIN_IMPOSSIBLE / LATIN_AMBIGUOUS / LATIN_UNFINISHED (the last only when
 * recursion was not permitted).
 */
export function latinSolve<C>(
  grid: Uint8Array,
  o: number,
  maxdiff: number,
  levels: LatinLevels<C>,
  ctx: C,
): number {
  return solveTop(new LatinSolver(grid, o), maxdiff, levels, ctx);
}

/** Whether `grid` is a latin square of order `o` (digits 1..o once per row and column). */
export function isLatinSquare(grid: ArrayLike<number>, o: number): boolean {
  const seen = new Uint8Array(o + 1);
  for (let y = 0; y < o; y++) {
    seen.fill(0);
    for (let x = 0; x < o; x++) {
      const d = grid[y * o + x];
      if (d < 1 || d > o || seen[d]) return false;
      seen[d] = 1;
    }
  }
  for (let x = 0; x < o; x++) {
    seen.fill(0);
    for (let y = 0; y < o; y++) {
      const d = grid[y * o + x];
      if (d < 1 || d > o || seen[d]) return false;
      seen[d] = 1;
    }
  }
  return true;
}

/**
 * A uniformly-ish random latin square of order `o`. Rows are filled one at a time (in a
 * random order): any partial latin rectangle can always be extended by another row, so
 * each row is found as a perfect matching between columns and the digits not yet used
 * in them, with the search order shuffled so every square is a possible outcome.
 */
export function latinGenerate(o: number, rng: Random): Uint8Array {
  const sq = new Uint8Array(o * o);
  const rows: number[] = [];
  for (let i = 0; i < o; i++) rows.push(i);
  rng.shuffle(rows);
  const cols: number[] = new Array(o);
  const digits: number[] = new Array(o);
  const matchDigit = new Int32Array(o); // digit index -> column, or -1
  const visited = new Uint8Array(o);
  const used = new Uint8Array(o * o); // used[x*o + d-1]: digit d already in column x

  const augment = (ci: number): boolean => {
    const x = cols[ci];
    for (let k = 0; k < o; k++) {
      const d = digits[k];
      if (visited[k] || used[x * o + d - 1]) continue;
      visited[k] = 1;
      if (matchDigit[k] < 0 || augment(matchDigit[k])) {
        matchDigit[k] = ci;
        return true;
      }
    }
    return false;
  };

  for (let r = 0; r < o; r++) {
    for (let i = 0; i < o; i++) {
      cols[i] = i;
      digits[i] = i + 1;
    }
    rng.shuffle(cols);
    rng.shuffle(digits);
    matchDigit.fill(-1);
    for (let ci = 0; ci < o; ci++) {
      visited.fill(0);
      if (!augment(ci)) throw new Error(tx`latinGenerate: no extension found`);
    }
    const y = rows[r];
    for (let k = 0; k < o; k++) {
      const x = cols[matchDigit[k]];
      sq[y * o + x] = digits[k];
      used[x * o + digits[k] - 1] = 1;
    }
  }
  return sq;
}
