import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { glyph } from '../../framework/glyphs';
import type { Random } from '../../framework/rng';
import {
  CELL_EMPTY,
  CELL_NEGATIVE,
  CELL_NEUTRAL,
  CELL_NOT_NEUTRAL,
  CELL_POSITIVE,
  Layout,
  NEGATIVE,
  NEUTRAL,
  POSITIVE,
  checkCompletion,
  clueStatus,
  decodeAux,
  isUnset,
  parseDesc,
  polarityOf,
} from './board';
import { generate } from './generator';
import type { MagnetsParams } from './generator';
import {
  DIFFICULTY_LETTERS,
  DIFFICULTY_NAMES,
  DIFF_COUNT,
  DIFF_EASY,
  DIFF_TRICKY,
  Work,
  solve,
} from './solver';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export type { MagnetsParams };

export interface MagnetsState {
  w: number;
  h: number;
  /** The domino tiling and the clues. Shared between states. */
  layout: Layout;
  /** One CELL_* value per cell. */
  cells: Uint8Array;
  /** 1 on every pole that touches a like pole. */
  errors: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface MagnetsUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /**
   * The Blank tool: a left click cycles a domino through blank, question marks and empty,
   * as a right-click does, instead of placing a magnet.
   */
  blank: boolean;
}

/** A shaded domino, the face of the Blank tool. */
const BLANK_GLYPH = glyph(
  'M3 7.5h18v9H3ZM12 7.5v9',
  '<path d="M3 7.5h18v9H3Z" fill="currentColor" fill-opacity="0.35"/>',
);

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
/** Beyond this, random grids that the solver can crack become vanishingly rare. */
const MAX_SIDE = 12;
/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it at the gentlest setting the Type menu
 * offers at that size, and goes up the ladder when they want to.
 */
const DEFAULTS: MagnetsParams = { w: 6, h: 5, diff: DIFF_EASY, strip: false };
const MOVE_RE = /^([-+.? ])(\d+),(\d+)$/;
/** Where a clue sits, measured from the grid edge in tiles. */
const CLUE_OFFSET = 0.55;

/** Room for the clues on every side plus a small margin. */
function border(t: number): number {
  return Math.round(t * 1.1);
}

function preset(w: number, h: number, diff: number, strip: boolean) {
  const name = `${w}×${h} ${DIFFICULTY_NAMES[diff]}${strip ? ', strip clues' : ''}`;
  return { name, params: { w, h, diff, strip } };
}

function makeState(layout: Layout, cells: Uint8Array, completed: boolean, cheated: boolean) {
  const check = checkCompletion(layout, cells);
  return {
    w: layout.w,
    h: layout.h,
    layout,
    cells,
    errors: check.errors,
    // As in the original, a puzzle stays completed once it has been.
    completed: completed || check.status === 1,
    cheated,
  };
}

/** The move character that puts polarity `p` on a cell. */
function charFor(p: number): string {
  return p === POSITIVE ? '+' : p === NEGATIVE ? '-' : '.';
}

/**
 * A full solution: from the aux string if it is valid, otherwise by solving from the
 * player's position and, failing that, from scratch.
 */
function findSolution(orig: MagnetsState, curr: MagnetsState, aux: string | undefined) {
  const L = curr.layout;
  if (aux !== undefined) {
    const grid = decodeAux(aux, L.n);
    if (grid) {
      const cells = new Uint8Array(L.n);
      for (let i = 0; i < L.n; i++) cells[i] = grid[i] === NEUTRAL ? CELL_NEUTRAL : grid[i];
      if (checkCompletion(L, cells).status === 1) return grid;
    }
  }
  const fromCurrent = Work.fromCells(L, curr.cells);
  if (fromCurrent && solve(fromCurrent, DIFF_COUNT - 1) > 0) return fromCurrent.grid;
  const fresh = Work.fromCells(L, orig.cells)!;
  const r = solve(fresh, DIFF_COUNT - 1);
  if (r > 0) return fresh.grid;
  throw new Error(
    r < 0 ? tx`No solution exists for this puzzle` : tx`Unable to find a solution to this puzzle`,
  );
}

// ------------------------------------------------------------------ drawing bits

/** A `+` or `-` sign centred on (cx, cy). */
function drawSign(
  dr: Drawing,
  cx: number,
  cy: number,
  t: number,
  p: number,
  colour: string,
  seed: number,
) {
  const arm = t * 0.2;
  const lw = Math.max(2, t * 0.085);
  dr.line(cx - arm, cy, cx + arm, cy, colour, lw, { seed });
  if (p === POSITIVE) dr.line(cx, cy - arm, cx, cy + arm, colour, lw, { seed: seed + 1 });
}

const game = defineGame<MagnetsParams, MagnetsState, MagnetsUI>({
  id: 'magnets',
  name: 'Magnets',
  description: 'Place magnets and blanks in the dominoes so the pole counts work out.',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: [
    preset(6, 5, DIFF_EASY, false),
    preset(6, 5, DIFF_TRICKY, false),
    preset(6, 5, DIFF_TRICKY, true),
    preset(8, 7, DIFF_EASY, false),
    preset(8, 7, DIFF_TRICKY, false),
    preset(8, 7, DIFF_TRICKY, true),
    preset(10, 9, DIFF_TRICKY, false),
    preset(10, 9, DIFF_TRICKY, true),
  ],
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${full ? `d${DIFFICULTY_LETTERS[p.diff]}${p.strip ? 'S' : ''}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?(S?)/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] !== undefined ? parseInt(m[2], 10) : w;
    let diff = DIFF_EASY;
    if (m[3] !== undefined && DIFFICULTY_LETTERS.includes(m[3]))
      diff = DIFFICULTY_LETTERS.indexOf(m[3]);
    return { w, h, diff, strip: m[4] === 'S' };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2) return tx`Width must be at least two`;
    if (p.h < 2) return tx`Height must be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.w * p.h <= 4) return tx`A 2×2 grid is too small to make a puzzle from`;
    if (full && (!Number.isInteger(p.diff) || p.diff < 0 || p.diff >= DIFF_COUNT))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.diff },
      { type: 'boolean', name: 'Strip clues', value: p.strip },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => {
      const v = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(v) ? parseInt(v, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      diff: (items[2] as { selected: number }).selected,
      strip: (items[3] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const layout = parseDesc(desc, p.w, p.h) as Layout;
    return { ...makeState(layout, layout.freshCells(), false, false), completed: false };
  },

  canSolve: true,
  solve(orig, curr, aux) {
    const grid = findSolution(orig, curr, aux);
    const { w, layout, cells } = curr;
    let move = 'S';
    for (let i = 0; i < layout.n; i++) {
      const j = layout.partner[i];
      if (j <= i) continue;
      if (polarityOf(cells[i]) === grid[i] && polarityOf(cells[j]) === grid[j]) continue;
      move += `;${charFor(grid[i])}${i % w},${Math.floor(i / w)}`;
    }
    return move;
  },

  textFormat(s) {
    const { w, h, layout, cells } = s;
    const num = (n: number) => (n < 0 ? '.' : n < 10 ? String(n) : String.fromCharCode(87 + n));
    const rule = ' +' + '-'.repeat(2 * w - 1) + '+';
    const lines: string[] = [];
    let top = '+';
    let bottom = ' ';
    for (let x = 0; x < w; x++) {
      top += ' ' + num(layout.target(x, POSITIVE));
      bottom += ' ' + num(layout.target(x, NEGATIVE));
    }
    lines.push(top, rule);
    for (let y = 0; y < h; y++) {
      let row = num(layout.target(w + y, POSITIVE)) + '|';
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const c = cells[i];
        row += layout.isSingleton(i)
          ? '#'
          : c === CELL_POSITIVE
            ? '+'
            : c === CELL_NEGATIVE
              ? '-'
              : c === CELL_NEUTRAL
                ? '*'
                : c === CELL_NOT_NEUTRAL
                  ? '?'
                  : ' ';
        if (x + 1 < w) row += layout.partner[i] === i + 1 ? ' ' : '|';
      }
      lines.push(row + '|' + num(layout.target(w + y, NEGATIVE)));
      if (y + 1 < h) {
        let sep = ' |';
        for (let x = 0; x < w; x++) {
          const i = y * w + x;
          sep += layout.partner[i] === i + w ? ' ' : '-';
          if (x + 1 < w) sep += '+';
        }
        lines.push(sep + '|');
      }
    }
    lines.push(rule, bottom + ' -');
    return lines.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false, blank: false }),

  actions: [
    {
      label: 'Blank',
      key: 'B',
      hud: true,
      glyph: BLANK_GLYPH,
      pressed: (_s, ui) => ui.blank,
      title: 'Clicks mark dominoes blank instead of placing magnets (B)',
    },
  ],
  changedState(ui, oldState, newState) {
    if (!oldState.completed && newState.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, layout, cells } = state;
    let gx: number;
    let gy: number;
    let magnet: boolean;
    // Hiding a visible cursor is itself worth a redraw.
    let idle: string | null = null;
    if (b === 'b'.charCodeAt(0) || b === 'B'.charCodeAt(0)) {
      ui.blank = !ui.blank;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      gx = ui.cx;
      gy = ui.cy;
      magnet = b === CURSOR_SELECT;
    } else if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const t = ds.tileSize;
      const bd = border(t);
      gx = Math.floor((mx - bd) / t);
      gy = Math.floor((my - bd) / t);
      if (gx < 0 || gy < 0 || gx >= w || gy >= h) return null;
      if (ui.cursorVisible) {
        ui.cursorVisible = false;
        idle = '';
      }
      magnet = b === LEFT_BUTTON && !ui.blank;
    } else {
      return null;
    }
    const i = gy * w + gx;
    if (layout.isSingleton(i)) return idle;
    const c = cells[i];
    let ch: string;
    if (magnet) {
      // empty → + → − → empty; a blank domino is not part of the cycle.
      if (c === CELL_NEUTRAL) return idle;
      ch = isUnset(c) ? '+' : c === CELL_POSITIVE ? '-' : ' ';
    } else {
      // empty → blank → "not blank" → empty; a magnet is not part of the cycle.
      if (c === CELL_POSITIVE || c === CELL_NEGATIVE) return idle;
      ch = c === CELL_NEUTRAL ? '?' : c === CELL_NOT_NEUTRAL ? ' ' : '.';
    }
    return `${ch}${gx},${gy}`;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h, layout } = state;
    const cells = state.cells.slice();
    let cheated = state.cheated;
    for (const part of move.split(';')) {
      if (part === 'S') {
        cheated = true;
        continue;
      }
      const m = MOVE_RE.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      const i = y * w + x;
      const j = layout.partner[i];
      if (i === j) return null;
      switch (m[1]) {
        case '+':
          cells[i] = CELL_POSITIVE;
          cells[j] = CELL_NEGATIVE;
          break;
        case '-':
          cells[i] = CELL_NEGATIVE;
          cells[j] = CELL_POSITIVE;
          break;
        case '.':
          cells[i] = cells[j] = CELL_NEUTRAL;
          break;
        case '?':
          cells[i] = cells[j] = CELL_NOT_NEUTRAL;
          break;
        default:
          cells[i] = cells[j] = CELL_EMPTY;
      }
    }
    return makeState(layout, cells, state.completed, cheated);
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const bd = border(t);
    return { w: p.w * t + 2 * bd, h: p.h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, layout, cells, errors } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const posFill = dr.mix('paper', 'red', 0.22);
    const negFill = dr.mix('paper', 'blue', 0.22);
    const errFill = dr.mix('paper', 'error', 0.4);

    dr.rect(bd, bd, w * t, h * t, flash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(bd + x * t, bd, bd + x * t, bd + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(bd, bd + y * t, bd + w * t, bd + y * t, 'faint', 1.2);

    // Lone squares are not part of the puzzle: hatch them out.
    for (let i = 0; i < layout.n; i++) {
      if (!layout.isSingleton(i)) continue;
      const g = t * 0.12;
      dr.hatch(
        bd + (i % w) * t + g,
        bd + Math.floor(i / w) * t + g,
        t - 2 * g,
        t - 2 * g,
        'faint',
        5,
      );
    }

    // Dominoes: each half filled for its pole, one sketched outline around both.
    const gutter = Math.max(1.5, t / 16);
    const lw = Math.max(1.6, t * 0.055);
    const fillFor = (i: number) => {
      const c = cells[i];
      if (flash) return 'highlight';
      if (errors[i]) return errFill;
      if (c === CELL_POSITIVE) return posFill;
      if (c === CELL_NEGATIVE) return negFill;
      if (c === CELL_NEUTRAL) return 'shade';
      return 'paper';
    };
    for (let i = 0; i < layout.n; i++) {
      const j = layout.partner[i];
      if (j <= i) continue;
      const horizontal = j === i + 1;
      const x = bd + (i % w) * t + gutter;
      const y = bd + Math.floor(i / w) * t + gutter;
      const dw = (horizontal ? 2 * t : t) - 2 * gutter;
      const dh = (horizontal ? t : 2 * t) - 2 * gutter;
      for (const k of [i, j]) {
        dr.clip(bd + (k % w) * t, bd + Math.floor(k / w) * t, t, t);
        dr.roundRect(x, y, dw, dh, t / 8, fillFor(k), null, { seed: i });
        dr.unclip();
      }
      // The join between the two halves.
      const inset = t * 0.12;
      if (horizontal)
        dr.line(x - gutter + t, y + inset, x - gutter + t, y + dh - inset, 'faint', 1.2);
      else dr.line(x + inset, y - gutter + t, x + dw - inset, y - gutter + t, 'faint', 1.2);
      dr.roundRect(x, y, dw, dh, t / 8, null, 'ink', { width: lw, seed: i });
    }

    // Poles and notes.
    for (let i = 0; i < layout.n; i++) {
      const c = cells[i];
      const cx = bd + (i % w) * t + t / 2;
      const cy = bd + Math.floor(i / w) * t + t / 2;
      if (c === CELL_POSITIVE || c === CELL_NEGATIVE) {
        const colour = flash ? 'ok' : errors[i] ? 'error' : c === CELL_POSITIVE ? 'red' : 'blue';
        drawSign(dr, cx, cy, t, c, colour, i);
        // Repelling poles get a ring of their own so the clash is unmistakable.
        if (errors[i] && !flash) {
          const g = gutter + t * 0.06;
          dr.roundRect(
            cx - t / 2 + g,
            cy - t / 2 + g,
            t - 2 * g,
            t - 2 * g,
            t / 10,
            null,
            'error',
            {
              width: Math.max(1.6, t * 0.05),
              seed: i + 500,
            },
          );
        }
      } else if (c === CELL_NOT_NEUTRAL) {
        dr.text(cx, cy, '?', { size: t * 0.55, colour: 'pencil' });
      }
    }
    dr.rectOutline(bd, bd, w * t, h * t, 'ink', { width: 2.4 });

    // Clues: + counts above and to the left, − counts below and to the right, with a
    // sign in the matching corner to say which is which.
    const off = t * CLUE_OFFSET;
    const clueColour = (l: number, which: number) => {
      if (flash) return 'ok';
      const s = clueStatus(layout, cells, l, which);
      return s.error ? 'error' : s.full ? 'pencil' : 'ink';
    };
    for (let x = 0; x < w; x++) {
      const cx = bd + x * t + t / 2;
      const p = layout.target(x, POSITIVE);
      const m = layout.target(x, NEGATIVE);
      if (p >= 0)
        dr.text(cx, bd - off, String(p), { size: t * 0.5, colour: clueColour(x, POSITIVE) });
      if (m >= 0)
        dr.text(cx, bd + h * t + off, String(m), {
          size: t * 0.5,
          colour: clueColour(x, NEGATIVE),
        });
    }
    for (let y = 0; y < h; y++) {
      const cy = bd + y * t + t / 2;
      const p = layout.target(w + y, POSITIVE);
      const m = layout.target(w + y, NEGATIVE);
      if (p >= 0)
        dr.text(bd - off, cy, String(p), { size: t * 0.5, colour: clueColour(w + y, POSITIVE) });
      if (m >= 0)
        dr.text(bd + w * t + off, cy, String(m), {
          size: t * 0.5,
          colour: clueColour(w + y, NEGATIVE),
        });
    }
    drawSign(dr, bd - off, bd - off, t * 0.8, POSITIVE, 'red', 101);
    drawSign(dr, bd + w * t + off, bd + h * t + off, t * 0.8, NEGATIVE, 'blue', 102);

    if (ui.cursorVisible) {
      const inset = t * 0.1;
      dr.cursor(bd + ui.cx * t + inset, bd + ui.cy * t + inset, t - 2 * inset, t - 2 * inset);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // About half of the solution of the 6×5 Easy puzzle the menu thumbnail shows (seed
  // `thumbnail:magnets`), so the card has some magnets on it; a unit test pins these.
  thumbnailMoves: ['+0,0', '+2,0', '.4,0', '-1,2', '-0,3', '+4,3', '.2,4'],
});

export default game;
