import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { DominosaParams, DominosaState } from './index';

type C = typeof PALETTE;

/** Pip positions on a half of a domino, in units of its half-width from its centre. */
const PIPS: [number, number][][] = [
  [],
  [[0, 0]],
  [
    [-0.5, -0.5],
    [0.5, 0.5],
  ],
  [
    [-0.5, -0.5],
    [0, 0],
    [0.5, 0.5],
  ],
  [
    [-0.5, -0.5],
    [0.5, -0.5],
    [-0.5, 0.5],
    [0.5, 0.5],
  ],
  [
    [-0.5, -0.5],
    [0.5, -0.5],
    [0, 0],
    [-0.5, 0.5],
    [0.5, 0.5],
  ],
  [
    [-0.5, -0.55],
    [0.5, -0.55],
    [-0.5, 0],
    [0.5, 0],
    [-0.5, 0.55],
    [0.5, 0.55],
  ],
];

/**
 * A domino with its centre at (cx, cy); `s` is the side of one half. Vertical unless
 * `across`, with `a` pips on the top (or left) half and `b` on the other.
 */
function domino(c: C, cx: number, cy: number, s: number, a: number, b: number, across = false) {
  const w = across ? 2 * s : s;
  const h = across ? s : 2 * s;
  const half = (n: number, hx: number, hy: number) =>
    PIPS[n]
      .map(
        ([px, py]) =>
          `<circle cx="${(hx + px * s * 0.46).toFixed(1)}" cy="${(hy + py * s * 0.46).toFixed(1)}" r="${(s * 0.12).toFixed(1)}" fill="${c.ink}"/>`,
      )
      .join('');
  const off = s / 2;
  const [ax, ay, bx, by] = across ? [cx - off, cy, cx + off, cy] : [cx, cy - off, cx, cy + off];
  const mid = across
    ? `M${cx} ${cy - s * 0.32} V${cy + s * 0.32}`
    : `M${cx - s * 0.32} ${cy} H${cx + s * 0.32}`;
  return (
    `<rect x="${cx - w / 2}" y="${cy - h / 2}" width="${w}" height="${h}" rx="${s * 0.2}" fill="${c.paper}" stroke="${c.ink}" stroke-width="4.5"/>` +
    `<path d="${mid}" stroke="${c.ink}" stroke-width="3" stroke-linecap="round"/>` +
    half(a, ax, ay) +
    half(b, bx, by)
  );
}

/** Dominoes the step from `a` to `b` laid, as [square, square] pairs. */
function laid(a: DominosaState, b: DominosaState): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i < b.partner.length; i++) {
    const j = b.partner[i];
    if (j > i && a.partner[i] !== j) out.push([i, j]);
  }
  return out;
}

const setSize = (n: number) => ((n + 1) * (n + 2)) / 2;

export const achievements = defineAchievements<DominosaParams, DominosaState>([
  {
    id: 'no-lines',
    name: 'No Pencil Needed',
    description: 'Solve a double-6 or bigger set without pencilling a single line.',
    tier: 'silver',
    hue: 'teal',
    art: (c) =>
      domino(c, 34, 50, 26, 5, 2) +
      `<g transform="rotate(32 68 50)">` +
      `<rect x="62" y="24" width="12" height="36" fill="${c.yellow}" stroke="${c.ink}" stroke-width="4" stroke-linejoin="round"/>` +
      `<path d="M62 60 L68 74 L74 60 Z" fill="${c.paper}" stroke="${c.ink}" stroke-width="4" stroke-linejoin="round"/>` +
      `<path d="M66.5 70 L68 74 L69.5 70 Z" fill="${c.ink}" stroke="${c.ink}" stroke-width="2"/>` +
      `</g>` +
      `<path d="M52 28 L84 72" stroke="${c.red}" stroke-width="6" stroke-linecap="round"/>`,
    test: (ctx) => ctx.params.n >= 6 && ctx.history.every((s) => !s.edges.includes(1)),
  },
  {
    id: 'one-click-each',
    name: 'One Click Each',
    description: 'Solve a double-6 or bigger set with one click per domino and no Undo.',
    tier: 'gold',
    hue: 'orange',
    // A domino being laid by a single click, and nothing else on the board.
    art: (c) =>
      domino(c, 44, 33, 26, 4, 2, true) +
      `<path d="M60 56 L60 80 L66 75 L70 84 L75 81.5 L71 73 L79 72.5 Z" fill="${c.paper}" stroke="${c.ink}" stroke-width="4" stroke-linejoin="round"/>` +
      `<path d="M53 58 L47 64 M52 51 L46 49 M55 64 L53 71" stroke="${c.accent}" stroke-width="4" stroke-linecap="round"/>`,
    // Every domino takes one click; any more (a line, a removal, a move) spoils it.
    test: (ctx) => ctx.params.n >= 6 && ctx.undos === 0 && ctx.moves === setSize(ctx.params.n),
  },
  {
    id: 'doubles-first',
    name: 'Doubles First',
    description: 'Lay every double in the set before laying any other domino.',
    tier: 'bronze',
    hidden: true,
    hue: 'pink',
    art: (c) =>
      domino(c, 27, 50, 17, 1, 1) + domino(c, 50, 50, 17, 2, 2) + domino(c, 73, 50, 17, 4, 4),
    test: (ctx) => {
      const doubles = ctx.params.n + 1;
      const order: boolean[] = [];
      // Judge the attempt since the last Restart, which puts an empty board back on the
      // line: dominoes laid before it and thrown away do not count either way.
      let from = 1;
      for (let k = 1; k < ctx.history.length; k++)
        if (ctx.history[k].partner.every((p, i) => p === i)) from = k + 1;
      for (let k = from; k < ctx.history.length && order.length < doubles; k++) {
        for (const [i, j] of laid(ctx.history[k - 1], ctx.history[k])) {
          order.push(ctx.state.numbers[i] === ctx.state.numbers[j]);
        }
      }
      return order.length >= doubles && order.slice(0, doubles).every(Boolean);
    },
  },
]);
