/**
 * Map layouts: the description format, the region adjacency graph and the geometry the
 * drawing code needs.
 *
 * A description is `<edges>,<clues>`. The edge list walks every interior grid edge —
 * first the horizontal ones (between a square and the one below it) row by row, then the
 * vertical ones column by column — and run-length encodes "border here / no border here"
 * as letters: `a` is a run of 1, `y` a run of 25, and each letter switches state, except
 * that `z` means "25 more of the same" so that longer runs can be written. The walk
 * starts with a notional non-border so the first letter is always meaningful. Regions are
 * numbered in the order their first square appears when reading the grid row by row.
 * The clue list gives each given colour as a digit `0`–`3`, with letters counting runs of
 * regions that are not given (`z` = 26 here, since there is no state to switch).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';
import { Random } from '../../framework/rng';

export const FOUR = 4;

/** Quadrants of a square. A square split diagonally has two regions among these. */
export const TE = 0;
export const BE = 1;
export const LE = 2;
export const RE = 3;

export interface MapGraph {
  n: number;
  /** Sorted neighbour lists. */
  adj: number[][];
  /** n×n adjacency matrix. */
  adjMat: Uint8Array;
  /** Every adjacency once, as [a, b] with a < b. */
  edges: [number, number][];
  /** n×n lookup from a pair of regions to its index in `edges`, or -1. */
  edgeIdx: Int32Array;
}

export interface Point {
  x: number;
  y: number;
}

/** Everything fixed about a puzzle; shared between all its states. */
export interface MapLayout extends MapGraph {
  w: number;
  h: number;
  /** Region of every square (row-major). */
  region: Int32Array;
  /** Region of every quadrant: `quad[side * w * h + i]` for side TE/BE/LE/RE. */
  quad: Int32Array;
  /** 1 for regions whose colour is given. */
  immutable: Uint8Array;
  /** A point on each edge's boundary, in doubled grid coordinates (see `canonicalPoints`). */
  edgePos: Point[];
  /** A point comfortably inside each region, in doubled grid coordinates. */
  regionPos: Point[];
}

/** Number of interior grid edges of a w×h grid. */
export function edgeCount(w: number, h: number): number {
  return 2 * w * h - w - h;
}

/** The two squares either side of interior edge number `pos` (horizontal ones first). */
function edgeSquares(w: number, h: number, pos: number): [number, number] {
  if (pos < w * (h - 1)) {
    const y = Math.floor(pos / w);
    const x = pos % w;
    return [y * w + x, (y + 1) * w + x];
  }
  const q = pos - w * (h - 1);
  const x = Math.floor(q / h);
  const y = q % h;
  return [y * w + x, y * w + x + 1];
}

/**
 * Parse the edge list at the start of a description. Returns the region of every square
 * and the unparsed remainder (which should start with the comma), or an error message.
 */
export function parseEdgeList(
  w: number,
  h: number,
  n: number,
  desc: string,
): { region: Int32Array; rest: string } | string {
  const wh = w * h;
  const total = edgeCount(w, h);
  const dsf = new DSF(wh);
  let pos = -1;
  let border = false;
  let i = 0;
  for (; i < desc.length && desc[i] !== ','; i++) {
    const ch = desc.charCodeAt(i);
    if (ch < 97 || ch > 122) return tx`Unexpected character in edge list`;
    const k = ch === 122 ? 25 : ch - 96;
    for (let j = 0; j < k; j++) {
      if (pos < 0) {
        pos++;
        continue;
      }
      if (pos >= total) return tx`Too much data in edge list`;
      if (!border) {
        const [a, b] = edgeSquares(w, h, pos);
        dsf.merge(a, b);
      }
      pos++;
    }
    if (ch !== 122) border = !border;
  }
  if (pos < total) return tx`Too little data in edge list`;

  const region = new Int32Array(wh);
  const label = new Int32Array(wh).fill(-1);
  let count = 0;
  for (let s = 0; s < wh; s++) {
    const root = dsf.find(s);
    if (label[root] < 0) label[root] = count++;
    region[s] = label[root];
  }
  if (count !== n) return tx`Edge list defines the wrong number of regions`;
  return { region, rest: desc.slice(i) };
}

/** Parse the clue list (after the comma). Returns colours (-1 = not given) or an error. */
export function parseClues(clues: string, n: number): Int8Array | string {
  const colouring = new Int8Array(n).fill(-1);
  let pos = 0;
  for (const ch of clues) {
    const c = ch.charCodeAt(0);
    if (c >= 48 && c < 48 + FOUR) {
      if (pos >= n) return tx`Too much data in clue list`;
      colouring[pos++] = c - 48;
    } else if (c >= 97 && c <= 122) {
      pos += c - 96;
    } else {
      return tx`Unexpected character in clue list`;
    }
  }
  if (pos < n) return tx`Too little data in clue list`;
  if (pos > n) return tx`Too much data in clue list`;
  return colouring;
}

/** Encode a region map and its given colours as a description. */
export function encodeDesc(
  w: number,
  h: number,
  region: ArrayLike<number>,
  colouring: ArrayLike<number>,
): string {
  let out = '';
  let run = 1;
  let prev = 0;
  const total = edgeCount(w, h);
  for (let pos = 0; pos < total; pos++) {
    const [a, b] = edgeSquares(w, h, pos);
    const v = region[a] !== region[b] ? 1 : 0;
    if (prev !== v) {
      out += String.fromCharCode(96 + run);
      run = 1;
      prev = v;
    } else {
      if (run === 25) {
        out += 'z';
        run = 0;
      }
      run++;
    }
  }
  out += String.fromCharCode(96 + run) + ',';

  run = 0;
  for (let i = 0; i < colouring.length; i++) {
    if (colouring[i] < 0) {
      if (run === 26) {
        out += 'z';
        run = 0;
      }
      run++;
    } else {
      if (run > 0) out += String.fromCharCode(96 + run);
      out += String(colouring[i]);
      run = 0;
    }
  }
  if (run > 0) out += String.fromCharCode(96 + run);
  return out;
}

/** Adjacency graph of a region map: regions are adjacent when they share a grid edge. */
export function buildGraph(region: ArrayLike<number>, w: number, h: number, n: number): MapGraph {
  const adjMat = new Uint8Array(n * n);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = region[y * w + x];
      if (x + 1 < w) {
        const r = region[y * w + x + 1];
        if (r !== v) adjMat[v * n + r] = adjMat[r * n + v] = 1;
      }
      if (y + 1 < h) {
        const d = region[(y + 1) * w + x];
        if (d !== v) adjMat[v * n + d] = adjMat[d * n + v] = 1;
      }
    }
  }
  const adj: number[][] = [];
  const edges: [number, number][] = [];
  const edgeIdx = new Int32Array(n * n).fill(-1);
  for (let a = 0; a < n; a++) {
    const list: number[] = [];
    for (let b = 0; b < n; b++) {
      if (!adjMat[a * n + b]) continue;
      list.push(b);
      if (a < b) {
        edgeIdx[a * n + b] = edgeIdx[b * n + a] = edges.length;
        edges.push([a, b]);
      }
    }
    adj.push(list);
  }
  return { n, adj, adjMat, edges, edgeIdx };
}

/**
 * Soften jagged outlines: an interior square that borders one region on two adjacent
 * sides and another on the other two, and belongs to one of them, is split along its
 * diagonal so each half joins the region beside it. The order of consideration is
 * random but seeded from the description, so a puzzle always looks the same.
 */
function smooth(quad: Int32Array, w: number, h: number, seed: string): void {
  const wh = w * h;
  const rng = new Random(seed);
  const squares: number[] = [];
  for (let i = 0; i < wh; i++) squares.push(i);
  rng.shuffle(squares);
  let changed = true;
  while (changed) {
    changed = false;
    for (const i of squares) {
      const x = i % w;
      const y = (i - x) / w;
      if (x === 0 || x === w - 1 || y === 0 || y === h - 1) continue;
      if (quad[TE * wh + i] !== quad[BE * wh + i]) continue;
      const c = quad[TE * wh + i];
      const tc = quad[BE * wh + i - w];
      const bc = quad[TE * wh + i + w];
      const lc = quad[RE * wh + i - 1];
      const rc = quad[LE * wh + i + 1];
      if (tc === bc || (tc !== c && bc !== c)) continue;
      if ((lc === tc && rc === bc) || (lc === bc && rc === tc)) {
        quad[TE * wh + i] = tc;
        quad[BE * wh + i] = bc;
        quad[LE * wh + i] = lc;
        quad[RE * wh + i] = rc;
        changed = true;
      }
    }
  }
}

/**
 * Pick a representative point for every edge (where error markers go) and every region
 * (where pencil marks and numbers go). Candidates are the midpoints of grid edges and
 * diagonals between two regions, grid vertices where exactly two regions meet cleanly,
 * and — for regions — centres of unsplit squares and vertices entirely inside a region.
 * Of each class the candidate nearest that class's centroid wins. Coordinates are
 * doubled so that midpoints stay integers.
 */
function canonicalPoints(
  g: MapGraph,
  quad: Int32Array,
  w: number,
  h: number,
): { edgePos: Point[]; regionPos: Point[] } {
  const wh = w * h;
  const classes = g.edges.length + g.n;
  const cands: Point[][] = [];
  for (let i = 0; i < classes; i++) cands.push([]);
  const q = (side: number, x: number, y: number) => quad[side * wh + y * w + x];
  const add = (a: number, b: number, x: number, y: number) => {
    const idx = a === b ? g.edges.length + a : g.edgeIdx[a * g.n + b];
    if (idx >= 0) cands[idx].push({ x, y });
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (x + 1 < w) add(q(RE, x, y), q(LE, x + 1, y), (x + 1) * 2, y * 2 + 1);
      if (y + 1 < h) add(q(BE, x, y), q(TE, x, y + 1), x * 2 + 1, (y + 1) * 2);
      add(q(TE, x, y), q(BE, x, y), x * 2 + 1, y * 2 + 1);
      if (x + 1 < w && y + 1 < h) {
        const oct = [
          q(RE, x, y),
          q(LE, x + 1, y),
          q(BE, x + 1, y),
          q(TE, x + 1, y + 1),
          q(LE, x + 1, y + 1),
          q(RE, x, y + 1),
          q(TE, x, y + 1),
          q(BE, x, y),
        ];
        let other = -1;
        let changes = 0;
        let three = false;
        for (let i = 0; i < 8; i++) {
          if (oct[i] !== oct[0]) {
            if (other < 0) other = oct[i];
            else if (other !== oct[i]) three = true;
          }
          if (oct[i] !== oct[(i + 1) & 7]) changes++;
        }
        if (!three && other >= 0 && changes === 2) add(oct[0], other, (x + 1) * 2, (y + 1) * 2);
        if (other < 0) add(oct[0], oct[0], (x + 1) * 2, (y + 1) * 2);
      }
    }
  }
  const pick = (list: Point[], fallback: Point): Point => {
    if (list.length === 0) return fallback;
    let ax = 0;
    let ay = 0;
    for (const p of list) {
      ax += p.x;
      ay += p.y;
    }
    ax /= list.length;
    ay /= list.length;
    let best = list[0];
    let bestD = Infinity;
    for (const p of list) {
      const d = Math.hypot(p.x - ax, p.y - ay);
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  };
  const edgePos = g.edges.map((_, i) => pick(cands[i], { x: 1, y: 1 }));
  const regionPos: Point[] = [];
  for (let r = 0; r < g.n; r++) {
    // Every region has a square whose top quadrant is it; use its centre as a last resort.
    let fb: Point = { x: 1, y: 1 };
    for (let i = 0; i < wh; i++) {
      if (quad[TE * wh + i] === r) {
        fb = { x: (i % w) * 2 + 1, y: Math.floor(i / w) * 2 + 1 };
        break;
      }
    }
    regionPos.push(pick(cands[g.edges.length + r], fb));
  }
  return { edgePos, regionPos };
}

/** Build the full layout from a valid description. */
export function buildLayout(w: number, h: number, n: number, desc: string): MapLayout {
  const parsed = parseEdgeList(w, h, n, desc);
  if (typeof parsed === 'string') throw new Error(parsed);
  const clues = parseClues(parsed.rest.slice(1), n);
  if (typeof clues === 'string') throw new Error(clues);
  const wh = w * h;
  const { region } = parsed;
  const g = buildGraph(region, w, h, n);
  const quad = new Int32Array(4 * wh);
  for (let s = 0; s < 4; s++) quad.set(region, s * wh);
  smooth(quad, w, h, desc);
  const immutable = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (clues[i] >= 0) immutable[i] = 1;
  const { edgePos, regionPos } = canonicalPoints(g, quad, w, h);
  return { ...g, w, h, region, quad, immutable, edgePos, regionPos };
}

/** Validate a description against the parameters; null when acceptable. */
export function validateDescription(w: number, h: number, n: number, desc: string): string | null {
  const parsed = parseEdgeList(w, h, n, desc);
  if (typeof parsed === 'string') return parsed;
  if (parsed.rest[0] !== ',') return tx`Expected comma before clue list`;
  const clues = parseClues(parsed.rest.slice(1), n);
  return typeof clues === 'string' ? clues : null;
}

/**
 * The region under canvas point (px, py) when the map's top-left square starts at
 * (mapX, mapY) with tiles of size `t`; -1 outside the map. Inside a split square the
 * side of the diagonal decides.
 */
export function regionAt(
  L: MapLayout,
  t: number,
  mapX: number,
  mapY: number,
  px: number,
  py: number,
): number {
  const tx = Math.floor((px - mapX) / t);
  const ty = Math.floor((py - mapY) / t);
  if (tx < 0 || tx >= L.w || ty < 0 || ty >= L.h) return -1;
  const dx = px - (mapX + tx * t);
  const dy = py - (mapY + ty * t);
  const quadrant = 2 * (dx > dy ? 1 : 0) + (t - dx > dy ? 1 : 0);
  const side = quadrant === 0 ? BE : quadrant === 1 ? LE : quadrant === 2 ? RE : TE;
  return L.quad[side * L.w * L.h + ty * L.w + tx];
}

/** Whether every region is coloured and no two adjacent regions share a colour. */
export function isComplete(g: MapGraph, colouring: ArrayLike<number>): boolean {
  for (let i = 0; i < g.n; i++) if (colouring[i] < 0) return false;
  for (const [a, b] of g.edges) if (colouring[a] === colouring[b]) return false;
  return true;
}

/** Indices of edges whose two regions are both coloured and clash. */
export function clashes(g: MapGraph, colouring: ArrayLike<number>): number[] {
  const out: number[] = [];
  g.edges.forEach(([a, b], i) => {
    if (colouring[a] >= 0 && colouring[a] === colouring[b]) out.push(i);
  });
  return out;
}
