import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  LEFT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type MatrixType = 'crosses' | 'random';

export interface FlipParams {
  w: number;
  h: number;
  matrix: MatrixType;
}

export interface FlipState {
  w: number;
  h: number;
  /**
   * `matrix[i * wh + j]` is 1 when pressing square `i` toggles square `j`. Shared by
   * every state of one game and never mutated.
   */
  matrix: Uint8Array;
  /** 1 = still dark, 0 = lit. The puzzle is finished when everything is lit. */
  lights: number[];
  /** Squares outlined in red by the solver; only drawn while `marksShown`. */
  marks: number[];
  marksShown: boolean;
  moves: number;
  /** Move count at which the board was first fully lit, or 0. */
  completed: number;
  usedSolve: boolean;
}

export interface FlipUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const ANIM = 0.13;
/** Seconds per ring of the completion ripple. */
const FLASH_FRAME = 0.1;
/** The solver enumerates at most 2^MAX_FREE_VARS candidate solutions. */
const MAX_FREE_VARS = 12;
const MAX_SIDE = 10;

// ------------------------------------------------------------------ bit strings

/** Pack bits into hex, four per character, most significant bit first. */
export function encodeBits(bits: ArrayLike<number>): string {
  let out = '';
  for (let i = 0; i < bits.length; i += 4) {
    let v = 0;
    for (let j = 0; j < 4; j++) if (i + j < bits.length && bits[i + j]) v |= 8 >> j;
    out += v.toString(16);
  }
  return out;
}

export function decodeBits(hex: string, len: number): Uint8Array {
  const out = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    const v = parseInt(hex[i >> 2] ?? '0', 16);
    out[i] = (v >> (3 - (i & 3))) & 1;
  }
  return out;
}

// ------------------------------------------------------------------ matrices

export function crossesMatrix(w: number, h: number): Uint8Array {
  const wh = w * h;
  const m = new Uint8Array(wh * wh);
  for (let i = 0; i < wh; i++) {
    const ix = i % w;
    const iy = Math.floor(i / w);
    for (let j = 0; j < wh; j++) {
      const jx = j % w;
      const jy = Math.floor(j / w);
      if (Math.abs(ix - jx) + Math.abs(iy - jy) <= 1) m[i * wh + j] = 1;
    }
  }
  return m;
}

function hasDuplicateRows(m: Uint8Array, wh: number): boolean {
  const seen = new Set<string>();
  for (let i = 0; i < wh; i++) {
    const key = String.fromCharCode(...m.subarray(i * wh, (i + 1) * wh));
    if (seen.has(key)) return true;
    seen.add(key);
  }
  return false;
}

/**
 * Grow a random shape around every square. Each shape starts as the square itself
 * and is extended one orthogonally-connected square at a time, never leaving the
 * 3×3 block around its centre. Growth favours output squares covered by few shapes
 * and shapes that are still small, so the result stays roughly as "dense" as the
 * crosses matrix. Matrices in which two squares would have identical effects are
 * thrown away.
 */
export function randomMatrix(w: number, h: number, rng: Random): Uint8Array {
  const wh = w * h;
  const target = 4 * wh - 2 * (w + h); // off-diagonal bits of the crosses matrix
  for (;;) {
    const m = new Uint8Array(wh * wh);
    const coverage = new Int32Array(wh).fill(1);
    const shapeSize = new Int32Array(wh).fill(1);
    const candidates = new Set<number>();
    const offer = (c: number, o: number) => {
      const cx = c % w;
      const cy = Math.floor(c / w);
      const ox = o % w;
      const oy = Math.floor(o / w);
      for (const [dx, dy] of [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
      ]) {
        const nx = ox + dx;
        const ny = oy + dy;
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (Math.abs(nx - cx) > 1 || Math.abs(ny - cy) > 1) continue;
        const key = c * wh + ny * w + nx;
        if (!m[key]) candidates.add(key);
      }
    };
    for (let c = 0; c < wh; c++) {
      m[c * wh + c] = 1;
      offer(c, c);
    }
    for (let added = 0; added < target && candidates.size > 0; added++) {
      let bestCov = Infinity;
      let bestSize = Infinity;
      let best: number[] = [];
      for (const key of candidates) {
        const c = Math.floor(key / wh);
        const o = key % wh;
        const cov = coverage[o];
        const sz = shapeSize[c];
        if (cov < bestCov || (cov === bestCov && sz < bestSize)) {
          bestCov = cov;
          bestSize = sz;
          best = [key];
        } else if (cov === bestCov && sz === bestSize) {
          best.push(key);
        }
      }
      const key = best[rng.upto(best.length)];
      const c = Math.floor(key / wh);
      const o = key % wh;
      candidates.delete(key);
      m[key] = 1;
      coverage[o]++;
      shapeSize[c]++;
      offer(c, o);
    }
    if (!hasDuplicateRows(m, wh)) return m;
  }
}

function pressInto(lights: number[], matrix: Uint8Array, i: number, wh: number): void {
  const base = i * wh;
  for (let j = 0; j < wh; j++) lights[j] ^= matrix[base + j];
}

function allLit(lights: number[]): boolean {
  return lights.every((v) => v === 0);
}

// ------------------------------------------------------------------ solver

/**
 * Find a set of squares whose presses light the whole board, using Gaussian
 * elimination over GF(2). Unknown `p[j]` is whether square `j` is pressed; output
 * square `i` gives the equation "sum over j of matrix[j][i]·p[j] = lights[i]". When
 * the system has free variables, a few thousand of their assignments are tried and
 * the one with the fewest presses wins. Returns null when no solution exists.
 */
export function solveLights(matrix: Uint8Array, lights: number[], wh: number): number[] | null {
  const rows: Uint8Array[] = [];
  for (let i = 0; i < wh; i++) {
    const row = new Uint8Array(wh + 1);
    for (let j = 0; j < wh; j++) row[j] = matrix[j * wh + i];
    row[wh] = lights[i] & 1;
    rows.push(row);
  }
  // Reduced row echelon form.
  const pivotCols: number[] = [];
  let rank = 0;
  for (let col = 0; col < wh && rank < wh; col++) {
    let p = -1;
    for (let r = rank; r < wh; r++) {
      if (rows[r][col]) {
        p = r;
        break;
      }
    }
    if (p < 0) continue;
    if (p !== rank) {
      const tmp = rows[p];
      rows[p] = rows[rank];
      rows[rank] = tmp;
    }
    const pivot = rows[rank];
    for (let r = 0; r < wh; r++) {
      if (r !== rank && rows[r][col]) {
        const row = rows[r];
        for (let k = col; k <= wh; k++) row[k] ^= pivot[k];
      }
    }
    pivotCols.push(col);
    rank++;
  }
  for (let r = rank; r < wh; r++) if (rows[r][wh]) return null;

  const isPivot = new Uint8Array(wh);
  for (const c of pivotCols) isPivot[c] = 1;
  const free: number[] = [];
  for (let c = 0; c < wh; c++) if (!isPivot[c]) free.push(c);
  const varied = Math.min(free.length, MAX_FREE_VARS);

  let best: number[] | null = null;
  let bestCount = Infinity;
  const sol = new Array<number>(wh).fill(0);
  for (let mask = 0; mask < 1 << varied; mask++) {
    sol.fill(0);
    for (let f = 0; f < varied; f++) if ((mask >> f) & 1) sol[free[f]] = 1;
    let count = 0;
    for (let r = 0; r < rank; r++) {
      const row = rows[r];
      let v = row[wh];
      for (const c of free) if (row[c] && sol[c]) v ^= 1;
      sol[pivotCols[r]] = v;
    }
    for (let j = 0; j < wh; j++) count += sol[j];
    if (count < bestCount) {
      bestCount = count;
      best = sol.slice();
    }
  }
  return best;
}

// ------------------------------------------------------------------ helpers

function descLengths(w: number, h: number) {
  const wh = w * h;
  return { wh, mlen: Math.ceil((wh * wh) / 4), glen: Math.ceil(wh / 4) };
}

function tileAt(ds: DrawState, mx: number, my: number) {
  const t = ds.tileSize;
  const border = Math.round(t * 0.3);
  return { x: Math.floor((mx - border) / t), y: Math.floor((my - border) / t) };
}

function rowIsEmpty(state: FlipState, i: number): boolean {
  const wh = state.w * state.h;
  for (let j = 0; j < wh; j++) if (state.matrix[i * wh + j]) return false;
  return true;
}

function matrixName(m: MatrixType): string {
  return m === 'crosses' ? 'Crosses' : 'Random';
}

// ------------------------------------------------------------------ the game

const game = defineGame<FlipParams, FlipState, FlipUI>({
  id: 'flip',
  name: 'Flip',
  description: 'Light every square; each press also flips the squares around it.',
  alsoKnownAs: 'Lights Out',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [3, 3, 'crosses'],
      [4, 4, 'crosses'],
      [5, 5, 'crosses'],
      [3, 3, 'random'],
      [4, 4, 'random'],
      [5, 5, 'random'],
    ] as [number, number, MatrixType][]
  ).map(([w, h, matrix]) => ({
    name: `${w}×${h} ${matrixName(matrix)}`,
    params: { w, h, matrix },
  })),
  // The smallest board the Type menu offers, rather than the original's default: a
  // newcomer's first puzzle should be one they can finish. See the other games' OPENING.
  defaultParams: () => ({ w: 3, h: 3, matrix: 'crosses' }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? (p.matrix === 'crosses' ? 'c' : 'r') : ''}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    const matrix: MatrixType = r.rest.startsWith('r') ? 'random' : 'crosses';
    return { w: r.w, h: r.h, matrix };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.matrix !== 'crosses' && p.matrix !== 'random') return tx`Unknown shape type`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      {
        type: 'choices',
        name: 'Shape type',
        choices: ['Crosses', 'Random'],
        selected: p.matrix === 'crosses' ? 0 : 1,
      },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const w = int(0);
    const h = int(1);
    const sel = (items[2] as { selected: number }).selected;
    return { w, h, matrix: sel === 1 ? 'random' : 'crosses' };
  },

  newDesc(p, rng: Random) {
    const { w, h } = p;
    const wh = w * h;
    const matrix = p.matrix === 'crosses' ? crossesMatrix(w, h) : randomMatrix(w, h, rng);
    // Pressing a random subset of squares from the lit board yields a uniformly random
    // solvable position; only the already-finished board is rejected.
    const lights = new Array<number>(wh).fill(0);
    do {
      lights.fill(0);
      for (let i = 0; i < wh; i++) if (rng.upto(2)) pressInto(lights, matrix, i, wh);
    } while (allLit(lights));
    return { desc: `${encodeBits(matrix)},${encodeBits(lights)}` };
  },

  validateDesc(p, desc) {
    const { mlen, glen } = descLengths(p.w, p.h);
    const parts = desc.split(',');
    if (parts.length !== 2) return tx`Description must be two hex strings separated by a comma`;
    const [m, g] = parts;
    if (!/^[0-9a-fA-F]*$/.test(m) || m.length !== mlen)
      return tx`Matrix description is the wrong length or not hexadecimal`;
    if (!/^[0-9a-fA-F]*$/.test(g) || g.length !== glen)
      return tx`Grid description is the wrong length or not hexadecimal`;
    return null;
  },

  newGame(p, desc) {
    const { w, h } = p;
    const wh = w * h;
    const [m, g] = desc.split(',');
    return {
      w,
      h,
      matrix: decodeBits(m, wh * wh),
      lights: Array.from(decodeBits(g, wh)),
      marks: new Array<number>(wh).fill(0),
      marksShown: false,
      moves: 0,
      completed: 0,
      usedSolve: false,
    };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (allLit(curr.lights)) throw new Error(tx`Already solved`);
    const presses = solveLights(curr.matrix, curr.lights, curr.w * curr.h);
    if (!presses) throw new Error(tx`No solution exists for this position`);
    return 'S' + presses.join('');
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) row += s.lights[y * s.w + x] ? '#' : '.';
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false }),

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    let tx: number;
    let ty: number;
    if (b === LEFT_BUTTON) {
      const wasVisible = ui.cursorVisible;
      ui.cursorVisible = false;
      ({ x: tx, y: ty } = tileAt(ds, mx, my));
      if (tx < 0 || ty < 0 || tx >= state.w || ty >= state.h) return wasVisible ? '' : null;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, state.w, state.h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (isCursorSelect(b)) {
      ui.cursorVisible = true;
      tx = ui.cx;
      ty = ui.cy;
    } else {
      return null;
    }
    // A hand-written game ID could contain a square that toggles nothing at all.
    if (rowIsEmpty(state, ty * state.w + tx)) return null;
    return `M${tx},${ty}`;
  },

  executeMove(state, move) {
    const { w, h } = state;
    const wh = w * h;
    if (move[0] === 'S') {
      if (move.length !== wh + 1 || !/^S[01]+$/.test(move)) return null;
      const lights = state.lights.slice();
      const marks = new Array<number>(wh).fill(0);
      for (let i = 0; i < wh; i++) {
        if (move[i + 1] === '1') {
          marks[i] = 1;
          pressInto(lights, state.matrix, i, wh);
        }
      }
      const done = allLit(lights);
      return {
        ...state,
        lights,
        marks,
        marksShown: true,
        usedSolve: true,
        completed: state.completed || (done ? state.moves : 0),
      };
    }
    const m = /^M(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[1], 10);
    const y = parseInt(m[2], 10);
    if (x >= w || y >= h) return null;
    const i = y * w + x;
    const lights = state.lights.slice();
    pressInto(lights, state.matrix, i, wh);
    // Solver marks show which squares still need pressing: pressing one clears its
    // mark, pressing an unmarked square means it must be pressed again later. On the
    // board Solve has just lit, the marks are a record of the presses it made rather than
    // presses still owed — nothing is owed there — so the tracking starts from nothing,
    // and the one square just pressed is what it takes to light the board again.
    const fromSolved = state.marksShown && allLit(state.lights);
    const marks = fromSolved ? new Array<number>(wh).fill(0) : state.marks.slice();
    marks[i] ^= 1;
    const moves = state.moves + 1;
    const done = allLit(lights);
    return {
      ...state,
      lights,
      marks,
      marksShown: state.marksShown && !done,
      moves,
      completed: state.completed || (done ? moves : 0),
    };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const border = Math.round(t * 0.3);
    return { w: p.w * t + 2 * border, h: p.h * t + 2 * border };
  },

  redraw(dr: Drawing, ds, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, h } = state;
    const wh = w * h;
    const t = ds.tileSize;
    const border = Math.round(t * 0.3);
    const progress = oldState ? animTime / ANIM : 1;
    const frame = flashTime > 0 ? Math.floor(flashTime / FLASH_FRAME) : -1;
    const ringsX = Math.ceil(w / 2);
    const ringsY = Math.ceil(h / 2);

    for (let i = 0; i < wh; i++) {
      const x = i % w;
      const y = Math.floor(i / w);
      const flipping = !!oldState && oldState.lights[i] !== state.lights[i];
      // Mid-flip the tile is edge-on; before that it still shows its old face.
      const dark = flipping && progress < 0.5 ? !!oldState!.lights[i] : !!state.lights[i];
      const sx = flipping ? Math.abs(Math.cos(Math.PI * progress)) : 1;
      // Completion ripple: a ring of tiles lights up in turn from the centre outwards.
      const ring = Math.max(ringsX - Math.min(x + 1, w - x), ringsY - Math.min(y + 1, h - y));
      drawTile(dr, state, i, border + x * t, border + y * t, t, {
        dark,
        mark: state.marksShown && !!state.marks[i],
        flash: frame === ring,
        sx,
      });
    }

    // Grid on top of the tiles, then the heavier outer frame.
    for (let x = 1; x < w; x++)
      dr.line(border + x * t, border, border + x * t, border + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++)
      dr.line(border, border + y * t, border + w * t, border + y * t, 'faint', 1.2);
    dr.rectOutline(border, border, w * t, h * t, 'ink', { width: 2.6 });

    if (ui.cursorVisible) {
      const pad = Math.max(2, t * 0.06);
      dr.cursor(border + ui.cx * t + pad, border + ui.cy * t + pad, t - 2 * pad, t - 2 * pad);
    }

    // Pressing on after Solve takes the board off the finished position again, so "solved
    // by the computer" would no longer be true; the original's "Auto-solver used. Moves"
    // says what happened without claiming the board is lit.
    const status = state.usedSolve
      ? allLit(state.lights)
        ? tr('status.solvedByComputer')
        : tr('status.autoSolverUsedPrefix') + tr('status.moves', { n: state.moves })
      : state.completed
        ? tr('status.movesCompleted', { n: state.completed })
        : tr('status.moves', { n: state.moves });
    dr.statusBar(status);
  },

  animLength: () => ANIM,
  flashLength(oldState, newState) {
    if (oldState.completed || !newState.completed || newState.usedSolve) return 0;
    const rings = Math.max(Math.ceil(newState.w / 2), Math.ceil(newState.h / 2));
    return FLASH_FRAME * (rings + 1);
  },
  status: (s) => (allLit(s.lights) ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  flags: { oneButton: true },
  thumbnailParams: { w: 4, h: 4, matrix: 'crosses' },
});

interface TileLook {
  dark: boolean;
  mark: boolean;
  flash: boolean;
  /** Horizontal scale about the tile centre, 1 = flat, 0 = edge-on. */
  sx: number;
}

/**
 * One square: its face, the little diagram of which squares it toggles, and the
 * solver's red mark. Everything is squeezed horizontally by `sx` while flipping.
 */
function drawTile(
  dr: Drawing,
  state: FlipState,
  i: number,
  x0: number,
  y0: number,
  t: number,
  look: TileLook,
): void {
  const { w, h } = state;
  const wh = w * h;
  const cx = x0 + t / 2;
  const cy = y0 + t / 2;
  const X = (v: number) => cx + (v - cx) * look.sx;
  const inset = 1.5;
  const face = look.flash ? 'ok' : look.dark ? 'ink' : 'highlight';
  dr.rect(X(x0 + inset), y0 + inset, (t - 2 * inset) * look.sx, t - 2 * inset, face, null);
  if (look.sx < 0.05) return;

  // Diagram: a 3×3 grid of little cells centred on the tile. The centre cell is solid,
  // the neighbours that flip along are outlined.
  const u = t * 0.14;
  const half = u * 0.4;
  const diagColour = look.flash ? 'paper' : look.dark ? 'lowlight' : 'pencil';
  const tx = i % w;
  const ty = Math.floor(i / w);
  dr.clip(x0, y0, t, t);
  for (let j = 0; j < wh; j++) {
    if (!state.matrix[i * wh + j]) continue;
    const dx = (j % w) - tx;
    const dy = Math.floor(j / w) - ty;
    const mx = cx + dx * u;
    const my = cy + dy * u;
    if (dx === 0 && dy === 0) {
      dr.rect(X(mx - half), my - half, 2 * half * look.sx, 2 * half, diagColour, null);
    } else {
      dr.rectOutline(X(mx - half), my - half, 2 * half * look.sx, 2 * half, diagColour, {
        width: 1.1,
        rough: 0.4,
        seed: i * 16 + (dx + 1) * 4 + dy + 1,
      });
    }
  }
  dr.unclip();

  if (look.mark) {
    const pad = t * 0.1;
    dr.roundRect(
      X(x0 + pad),
      y0 + pad,
      (t - 2 * pad) * look.sx,
      t - 2 * pad,
      t * 0.1,
      null,
      'red',
      {
        width: 2.6,
        seed: i,
      },
    );
  }
}

export default game;
