import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { DIFF_EXTREME, DIFF_INTERSECT } from './solver';
import type { SoloParams, SoloState } from './index';

type C = typeof PALETTE;

/** Hand-drawn digit strokes on a 4×6 box, so a badge can carry a digit without text. */
const DIGITS: Record<string, string> = {
  '1': 'M0.8 1.4 L2.4 0 V6',
  '2': 'M0 1.4 Q0.4 0 2 0 Q4 0 4 1.8 Q4 3.2 0 6 H4',
  '3': 'M0.2 0.6 Q2 -0.4 3.4 0.6 Q4.4 1.8 1.6 2.9 Q4.4 3.2 4 4.8 Q3.4 6.4 0 5.4',
  '4': 'M3 6 V0 L0 4 H4.2',
  '5': 'M3.8 0 H0.6 L0.2 2.8 Q2 2 3.4 2.9 Q4.4 4 3.6 5.2 Q2.4 6.4 0 5.6',
  '6': 'M3.6 0.3 Q0 0 0 3.8 Q0 6 2 6 Q4 6 4 4.2 Q4 2.5 2 2.5 Q0.4 2.5 0 3.8',
  '7': 'M0 0 H4 L1.4 6',
  '8': 'M2 2.8 Q3.8 2.6 3.8 1.4 Q3.8 0 2 0 Q0.2 0 0.2 1.4 Q0.2 2.6 2 2.8 Q4.2 3.1 4.2 4.5 Q4.2 6 2 6 Q-0.2 6 -0.2 4.5 Q-0.2 3.1 2 2.8 Z',
  '9': 'M3.9 2 Q3.4 3.6 2 3.6 Q0 3.6 0 1.8 Q0 0 2 0 Q4 0 4 2.2 Q4 6 0.6 6',
};

function digit(c: C, d: string, cx: number, cy: number, h: number, colour: string = c.ink): string {
  const k = h / 6;
  return (
    `<path transform="translate(${(cx - 2 * k).toFixed(1)} ${(cy - h / 2).toFixed(1)}) scale(${k.toFixed(3)})" d="${DIGITS[d]}" ` +
    `fill="none" stroke="${colour}" stroke-width="${(Math.max(2.6, h * 0.22) / k).toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>`
  );
}

/** One 3×3 block of a Solo grid, `cells` giving a digit or ' ' for each square. */
function block(
  c: C,
  x: number,
  y: number,
  s: number,
  cells: string,
  colour: string = c.ink,
): string {
  let out = `<rect x="${x}" y="${y}" width="${3 * s}" height="${3 * s}" fill="${c.paper}"/>`;
  out += `<path d="M${x + s} ${y} V${y + 3 * s} M${x + 2 * s} ${y} V${y + 3 * s} M${x} ${y + s} H${x + 3 * s} M${x} ${y + 2 * s} H${x + 3 * s}" stroke="${c.pencil}" stroke-width="1.6"/>`;
  for (let i = 0; i < 9; i++) {
    const d = cells[i];
    if (d && d !== ' ')
      out += digit(
        c,
        d,
        x + (i % 3) * s + s / 2,
        y + Math.floor(i / 3) * s + s / 2,
        s * 0.56,
        colour,
      );
  }
  return (
    out +
    `<rect x="${x}" y="${y}" width="${3 * s}" height="${3 * s}" fill="none" stroke="${c.ink}" stroke-width="4"/>`
  );
}

const nineByNine = (p: SoloParams) => p.c * p.r === 9;

export const achievements = defineAchievements<SoloParams, SoloState>([
  {
    id: 'pen-only',
    name: 'Pen, No Pencil',
    description: 'Solve a 9×9 Medium, Killer or harder Solo without a single pencil mark.',
    tier: 'silver',
    hue: 'blue',
    // A block written straight in, and a pencil crossed out.
    art: (c) =>
      block(c, 21, 21, 14, '5 3 71 9 4') +
      `<g transform="rotate(-40 66 68)"><rect x="50" y="62" width="30" height="12" fill="${c.yellow}" stroke="${c.ink}" stroke-width="3"/>` +
      `<path d="M50 62 L40 68 L50 74 Z" fill="${c.shade}" stroke="${c.ink}" stroke-width="3" stroke-linejoin="round"/>` +
      `<path d="M40 68 L44 65.6 V70.4 Z" fill="${c.ink}"/>` +
      `<rect x="80" y="62" width="5" height="12" fill="${c.pink}" stroke="${c.ink}" stroke-width="3"/></g>` +
      `<path d="M52 52 L81 81" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round"/>`,
    test: (ctx) =>
      nineByNine(ctx.params) &&
      (ctx.params.diff >= DIFF_INTERSECT || ctx.params.killer) &&
      ctx.history.every((s) => !s.pencil.includes(1)),
  },
  {
    id: 'no-second-thoughts',
    name: 'No Second Thoughts',
    description: 'Solve a 9×9 Expert or harder without ever changing or clearing a digit.',
    tier: 'gold',
    hue: 'yellow',
    // A full block, every digit right first time, and an eraser that was never needed.
    art: (c) =>
      block(c, 21, 21, 14, '534672198', c.blue) +
      `<g transform="rotate(-30 70 70)"><rect x="56" y="62" width="28" height="16" rx="3" fill="${c.pink}" stroke="${c.ink}" stroke-width="3.5"/>` +
      `<path d="M66 62 V78" stroke="${c.ink}" stroke-width="3"/></g>` +
      `<path d="M56 56 L81 81" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round"/>`,
    test: (ctx) => {
      if (!nineByNine(ctx.params) || ctx.params.diff < DIFF_EXTREME) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].grid;
        const b = ctx.history[k].grid;
        for (let i = 0; i < a.length; i++) if (a[i] && b[i] !== a[i]) return false;
      }
      return true;
    },
  },
]);
