import { tx } from '../../i18n';
/**
 * Mine layouts as bitmaps, their hex encoding, and the masking transform the original
 * collection applies so a game ID does not spell out the mine positions in plain text.
 *
 * Bit i of the bitmap (row-major square index) is stored most-significant-bit first, and
 * the hex string holds ceil(area / 4) nibbles. The masking is an OAEP-style two-step XOR:
 * the byte string is split in half, the first half is XORed with a SHA-1-derived mask of
 * the second, then the second half with a mask of the (masked) first half. Decoding runs
 * the two steps in the opposite order. Following the same recipe means IDs such as
 * `9x9:4,4,mb071b49fbd1cb6a0d5868` from the original describe the same grid here.
 */

/** SHA-1 of a byte string, as 20 bytes. */
export function sha1(data: Uint8Array): Uint8Array {
  const len = data.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const buf = new Uint8Array(total);
  buf.set(data);
  buf[len] = 0x80;
  const view = new DataView(buf.buffer);
  const bitLen = len * 8;
  view.setUint32(total - 8, Math.floor(bitLen / 0x100000000));
  view.setUint32(total - 4, bitLen >>> 0);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;
  const w = new Int32Array(80);
  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getInt32(off + i * 4);
    for (let i = 16; i < 80; i++) {
      const x = w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16];
      w[i] = (x << 1) | (x >>> 31);
    }
    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    for (let i = 0; i < 80; i++) {
      let f: number;
      let k: number;
      if (i < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const t = (((a << 5) | (a >>> 27)) + f + e + k + w[i]) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = t;
    }
    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }
  const out = new Uint8Array(20);
  const ov = new DataView(out.buffer);
  ov.setInt32(0, h0);
  ov.setInt32(4, h1);
  ov.setInt32(8, h2);
  ov.setInt32(12, h3);
  ov.setInt32(16, h4);
  return out;
}

/** XOR `target` with the mask stream derived from `seed`: SHA-1(seed ‖ "0"), SHA-1(seed ‖ "1"), … */
function applyMask(
  bytes: Uint8Array,
  seedStart: number,
  seedLen: number,
  tgtStart: number,
  tgtLen: number,
) {
  const seed = bytes.slice(seedStart, seedStart + seedLen);
  let digest: Uint8Array | null = null;
  let pos = 20;
  let counter = 0;
  for (let j = 0; j < tgtLen; j++) {
    if (pos >= 20) {
      const num = String(counter++);
      const input = new Uint8Array(seed.length + num.length);
      input.set(seed);
      for (let k = 0; k < num.length; k++) input[seed.length + k] = num.charCodeAt(k);
      digest = sha1(input);
      pos = 0;
    }
    bytes[tgtStart + j] ^= digest![pos++];
  }
}

/** Mask (or, with `decode`, unmask) a packed bitmap of `bits` bits in place. */
export function maskBitmap(bytes: Uint8Array, bits: number, decode: boolean): void {
  const nbytes = (bits + 7) >> 3;
  const first = nbytes >> 1;
  const second = nbytes - first;
  const steps: [number, number, number, number][] = [
    [first, second, 0, first], // seed = second half, target = first half
    [0, first, first, second], // seed = first half, target = second half
  ];
  if (decode) steps.reverse();
  for (const [ss, sl, ts, tl] of steps) {
    applyMask(bytes, ss, sl, ts, tl);
    if (bits % 8) bytes[bits >> 3] &= 0xff & (0xff00 >> (bits % 8));
  }
}

/** Pack a 0/1 layout into bytes, first square in the top bit. */
export function packLayout(mines: Uint8Array): Uint8Array {
  const bytes = new Uint8Array((mines.length + 7) >> 3);
  for (let i = 0; i < mines.length; i++) if (mines[i]) bytes[i >> 3] |= 0x80 >> (i & 7);
  return bytes;
}

export function unpackLayout(bytes: Uint8Array, area: number): Uint8Array {
  const mines = new Uint8Array(area);
  for (let i = 0; i < area; i++) mines[i] = (bytes[i >> 3] >> (7 - (i & 7))) & 1;
  return mines;
}

/** Number of hex digits used to describe a layout of `area` squares. */
export function layoutHexLength(area: number): number {
  return (area + 3) >> 2;
}

function toHex(bytes: Uint8Array, nibbles: number): string {
  let s = '';
  for (let i = 0; i < nibbles; i++) {
    const v = bytes[i >> 1];
    s += ((i & 1) === 0 ? v >> 4 : v & 15).toString(16);
  }
  return s;
}

function fromHex(hex: string): Uint8Array | null {
  if (!/^[0-9a-fA-F]*$/.test(hex)) return null;
  const bytes = new Uint8Array((hex.length + 1) >> 1);
  for (let i = 0; i < hex.length; i++) {
    const v = parseInt(hex[i], 16);
    bytes[i >> 1] |= (i & 1) === 0 ? v << 4 : v;
  }
  return bytes;
}

/** Hex description of a layout; `masked` applies the obfuscation transform. */
export function encodeLayout(mines: Uint8Array, masked: boolean): string {
  const bytes = packLayout(mines);
  if (masked) maskBitmap(bytes, mines.length, false);
  return toHex(bytes, layoutHexLength(mines.length));
}

/** Inverse of `encodeLayout`; null when the hex is malformed or the wrong length. */
export function decodeLayout(hex: string, area: number, masked: boolean): Uint8Array | null {
  if (hex.length !== layoutHexLength(area)) return null;
  const bytes = fromHex(hex);
  if (!bytes) return null;
  // Pad to a whole number of bytes for the masking step.
  const full = new Uint8Array((area + 7) >> 3);
  full.set(bytes.subarray(0, full.length));
  if (masked) maskBitmap(full, area, true);
  return unpackLayout(full, area);
}

// ---------------------------------------------------------------- descriptions

/**
 * A game description is one of:
 *  - `r<n>,<u|a>,<seed>`: no layout yet; `n` mines are placed around the first click,
 *    guaranteed solvable when `u`, using an RNG seeded from `<seed>`.
 *  - `[x,y,][m|u]<hex>`: a fixed layout (masked with `m`, plain with `u` or nothing),
 *    optionally with a square that is opened straight away.
 */
export type ParsedDesc =
  | { kind: 'pending'; n: number; unique: boolean; seed: string }
  | { kind: 'layout'; x: number; y: number; mines: Uint8Array };

export function parseDesc(desc: string, w: number, h: number): ParsedDesc | string {
  const area = w * h;
  const pending = /^r(\d+),([ua]),(.+)$/.exec(desc);
  if (pending) {
    const n = parseInt(pending[1], 10);
    if (n > area - 9) return tx`Too many mines for grid size`;
    return { kind: 'pending', n, unique: pending[2] === 'u', seed: pending[3] };
  }
  if (desc.startsWith('r')) return tx`Malformed pending game description`;
  const m = /^(?:(\d+),(\d+),)?([mu])?([0-9a-fA-F]*)$/.exec(desc);
  if (!m) return tx`Unrecognised characters in game description`;
  let x = -1;
  let y = -1;
  if (m[1] !== undefined) {
    x = parseInt(m[1], 10);
    y = parseInt(m[2], 10);
    if (x >= w) return tx`Initial x-coordinate was out of range`;
    if (y >= h) return tx`Initial y-coordinate was out of range`;
  }
  if (m[4].length !== layoutHexLength(area)) return tx`Game description is wrong length`;
  const mines = decodeLayout(m[4], area, m[3] === 'm');
  if (!mines) return tx`Bad mine layout in game description`;
  if (x >= 0 && mines[y * w + x]) return tx`The initial square contains a mine`;
  return { kind: 'layout', x, y, mines };
}

export function describeLayout(mines: Uint8Array, x: number, y: number): string {
  return `${x},${y},m${encodeLayout(mines, true)}`;
}
