/**
 * Puzzle generation for Pattern.
 *
 * A grid of random values is smoothed once by averaging each cell with its neighbours,
 * then cut at its median so that half the cells are black. The smoothing biases the
 * picture towards blobs of black and white, which makes for clue lists with a few
 * decent-sized runs rather than a salt-and-pepper mess, while the median cut keeps the
 * two colours balanced. Grids with an all-black or all-white row or column are thrown
 * away (too easy), as is anything the line solver cannot finish, so the puzzle handed
 * to the player is always solvable by pure single-line reasoning.
 */
import type { Random } from '../../framework/rng';
import { cluesOf, EMPTY, FULL } from './clues';
import { LineSolver, solveGrid } from './solver';

/** One random picture, without any solvability check. */
export function generatePattern(w: number, h: number, rng: Random, out?: Uint8Array): Uint8Array {
  const n = w * h;
  const grid = out ?? new Uint8Array(n);
  const noise = new Float64Array(n);
  for (let i = 0; i < n; i++) noise[i] = rng.float();

  // Average each cell with its 3×3 neighbourhood (fewer cells at the edges). A grid that
  // is only two cells across is not averaged in that direction, otherwise a 2×2 grid
  // would end up with four identical cells.
  const smooth = new Float64Array(n);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let sum = 0;
      let count = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const ny = y + dy;
          const nx = x + dx;
          if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
          if ((h === 2 && dy !== 0) || (w === 2 && dx !== 0)) continue;
          sum += noise[ny * w + nx];
          count++;
        }
      }
      smooth[y * w + x] = sum / count;
    }
  }

  const sorted = smooth.slice().sort();
  const threshold = sorted[n >> 1];
  for (let i = 0; i < n; i++) grid[i] = smooth[i] >= threshold ? FULL : EMPTY;
  return grid;
}

/** Does every row (if wider than 2) and column (if taller than 2) contain both colours? */
export function hasBothColoursEverywhere(grid: Uint8Array, w: number, h: number): boolean {
  if (w > 2) {
    for (let y = 0; y < h; y++) {
      let seen = 0;
      for (let x = 0; x < w; x++) seen |= grid[y * w + x] === FULL ? 2 : 1;
      if (seen !== 3) return false;
    }
  }
  if (h > 2) {
    for (let x = 0; x < w; x++) {
      let seen = 0;
      for (let y = 0; y < h; y++) seen |= grid[y * w + x] === FULL ? 2 : 1;
      if (seen !== 3) return false;
    }
  }
  return true;
}

/**
 * Pictures that fail the both-colours test before it is given up on. On a long, thin grid
 * (40×3, say) the smoothing makes a short line all one colour almost every time, and no
 * picture at all passed in hundreds of thousands of tries, so the generator used to spin
 * for ever and freeze the page. Past this many rejections only solvability is asked for.
 */
export const COLOUR_CHECK_TRIES = 2000;

/** Generate pictures until one is interesting and solvable line by line. */
export function generateSoluble(w: number, h: number, rng: Random): Uint8Array {
  const solver = new LineSolver(Math.max(w, h));
  const grid = new Uint8Array(w * h);
  for (let rejected = 0; ;) {
    generatePattern(w, h, rng, grid);
    if (rejected < COLOUR_CHECK_TRIES && !hasBothColoursEverywhere(grid, w, h)) {
      rejected++;
      continue;
    }
    if (solveGrid(w, h, cluesOf(grid, w, h), solver).solved) return grid;
  }
}
