/**
 * What one visit to a puzzle page tells us: which puzzles were dealt, how each ended —
 * solved by hand, solved by the Solve button, lost, or walked away from — and what it took
 * (moves, undos, hints, visible time).
 *
 * Fed by the play page from the midend's own callbacks (`onMove` for every change of the
 * board, the status transitions `checkProgress` already computes), so it adds no work of
 * its own to a move. Everything here ends in {@link track}, which is a no-op when
 * analytics is off, so the play page can call it unconditionally.
 */
import type { MoveEffect } from '../framework/midend';
import { activeMs, track } from './index';

export interface PuzzleInfo {
  /** The game's short param string, e.g. `9x9de`, which pins the size and difficulty. */
  params: string;
  /** Index into the game's presets, or -1 for a custom size. */
  preset: number;
}

export interface PuzzleTracker {
  /** A midend `onMove` effect. */
  effect(e: MoveEffect): void;
  /** The board's status changed to won (1) or lost (-1). */
  ended(status: 1 | -1, how: { byPlayer: boolean; credited: boolean }): void;
  /** A hint was applied; `free` when an ad paid for it. */
  hint(free: boolean): void;
  /** What the player answered when offered an ad for the hint that costs the credit. */
  hintOffer(choice: 'ad' | 'anyway' | 'dismiss'): void;
  /** The tutorial started, or ended (`completed` when played to the end). */
  tutorial(active: boolean, completed?: boolean): void;
  helpOpened(): void;
  shareOpened(): void;
  /** The page is going away. */
  leave(): void;
}

export function trackPuzzlePage(
  game: string,
  info: () => PuzzleInfo,
  opts: { tutorial: boolean },
): PuzzleTracker {
  const pageStart = activeMs();
  /**
   * Board changes are the tutorial's, not the player's. Starts true when the tutorial is
   * about to run on arrival, because its opening board is dealt before it starts.
   */
  let inTutorial = opts.tutorial;
  let tutorialRunning = false;
  let tutorialStart = 0;
  let completed = 0;
  /** The puzzle on the board, or null before the first deal / inside the tutorial. */
  let cur: {
    start: number;
    moves: number;
    undos: number;
    hints: number;
    restarts: number;
    ended: boolean;
  } | null = null;

  const safeInfo = (): PuzzleInfo => {
    try {
      return info();
    } catch {
      return { params: '', preset: -1 };
    }
  };
  const base = () => {
    const i = safeInfo();
    return { game, params: i.params, preset: i.preset };
  };
  const secs = (from: number) => Math.round((activeMs() - from) / 100) / 10;

  function begin() {
    cur = { start: activeMs(), moves: 0, undos: 0, hints: 0, restarts: 0, ended: false };
  }
  /** Close off a puzzle the player made moves on and then left unfinished. */
  function abandon(reason: string) {
    if (cur && !cur.ended && cur.moves > 0) {
      track('puzzle_abandon', {
        ...base(),
        reason,
        moves: cur.moves,
        hints: cur.hints,
        secs: secs(cur.start),
      });
    }
  }

  // Created before the page puts its first board up, so a fresh deal arrives as the
  // `puzzle_start` that follows; a restored board has none, and is counted from its first move.
  track('game_open', { game });

  return {
    effect(e) {
      if (inTutorial) return;
      if (e === 'new') {
        abandon('new');
        begin();
        track('puzzle_start', base());
        return;
      }
      if (!cur) begin();
      if (e === 'move') cur!.moves++;
      else if (e === 'undo') cur!.undos++;
      else if (e === 'restart') {
        cur!.restarts++;
        cur!.ended = false;
      } else if (e === 'solve') track('solve_used', { ...base(), moves: cur!.moves });
    },
    ended(status, how) {
      if (inTutorial || !cur || cur.ended) return;
      cur.ended = true;
      const common = {
        ...base(),
        moves: cur.moves,
        undos: cur.undos,
        hints: cur.hints,
        restarts: cur.restarts,
        secs: secs(cur.start),
      };
      if (status === 1) {
        completed++;
        track('puzzle_complete', {
          ...common,
          by: how.byPlayer ? 'player' : 'solver',
          credited: how.credited,
        });
      } else track('puzzle_fail', common);
    },
    hint(free) {
      if (inTutorial) return;
      if (!cur) begin();
      cur!.hints++;
      track('hint_used', { ...base(), n: cur!.hints, free });
    },
    hintOffer(choice) {
      track('rewarded_offer', { game, choice });
    },
    tutorial(active, done) {
      if (active && !tutorialRunning) {
        tutorialRunning = inTutorial = true;
        tutorialStart = activeMs();
        track('tutorial_start', { game });
      } else if (!active && tutorialRunning) {
        tutorialRunning = inTutorial = false;
        track('tutorial_end', { game, completed: !!done, secs: secs(tutorialStart) });
        // The board the player returns to is their own; count it from here.
        begin();
      }
    },
    helpOpened() {
      track('help_open', { game });
    },
    shareOpened() {
      track('share_open', { game });
    },
    leave() {
      abandon('leave');
      track('game_close', { game, secs: secs(pageStart), completed });
    },
  };
}
