import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { LINE_NO, LINE_YES } from './board';
import { geometry } from './index';
import type { LoopyState, LoopyUI } from './index';

/** Face in the middle of the grid: the one carrying the 4. */
const middle = (s: LoopyState) => Math.floor(s.h / 2) * s.w + Math.floor(s.w / 2);
/** Sides of a square face, clockwise from the top. */
const TOP = 0;
const RIGHT = 1;
const BOTTOM = 2;
const LEFT = 3;
const side = (s: LoopyState, face: number, k: number) => s.grid.faceEdges[face][k];

/** Both ends of an edge in canvas pixels. */
function ends(state: LoopyState, t: number, e: number) {
  const g = state.grid;
  const { scale, ox, oy } = geometry(state, t);
  return {
    x1: ox + g.dotX[g.edgeDot1[e]] * scale,
    y1: oy + g.dotY[g.edgeDot1[e]] * scale,
    x2: ox + g.dotX[g.edgeDot2[e]] * scale,
    y2: oy + g.dotY[g.edgeDot2[e]] * scale,
  };
}

/** A fat rectangle over one edge, wide enough to see but not to swallow its neighbours. */
function edgeRect(state: LoopyState, t: number, e: number): TutorialRect {
  const p = ends(state, t, e);
  const pad = t * 0.2;
  return {
    x: Math.min(p.x1, p.x2) - pad,
    y: Math.min(p.y1, p.y2) - pad,
    w: Math.abs(p.x2 - p.x1) + 2 * pad,
    h: Math.abs(p.y2 - p.y1) + 2 * pad,
  };
}

function edgeMid(state: LoopyState, t: number, e: number) {
  const p = ends(state, t, e);
  return { x: (p.x1 + p.x2) / 2, y: (p.y1 + p.y2) / 2 };
}

/** The face itself, as a rectangle round its inscribed circle. */
function faceRect(state: LoopyState, t: number, face: number): TutorialRect {
  const g = state.grid;
  const { scale, ox, oy } = geometry(state, t);
  const r = g.faceR[face] * scale;
  return {
    x: ox + g.faceCX[face] * scale - r,
    y: oy + g.faceCY[face] * scale - r,
    w: 2 * r,
    h: 2 * r,
  };
}

const drawn = (s: LoopyState, e: number) => s.lines[e] === LINE_YES;

/**
 * A 3×3 board with a single 4 in the middle: four clicks draw the whole loop, which
 * leaves room to show the cross as well.
 */
export const tutorial: Tutorial<LoopyState, LoopyUI> = {
  steps: [
    {
      gameId: '3x3t0:0a0a4a0a0',
      text: 'Draw **one** closed loop along the faint lines between the dots. Each number says how many of its square’s four sides the loop uses.',
      highlight: ({ state, tileSize }) => {
        const g = state.grid;
        const { scale, ox, oy } = geometry(state, tileSize);
        const pad = tileSize * 0.25;
        return {
          x: ox + g.minX * scale - pad,
          y: oy + g.minY * scale - pad,
          w: (g.maxX - g.minX) * scale + 2 * pad,
          h: (g.maxY - g.minY) * scale + 2 * pad,
        };
      },
    },
    {
      text: 'The middle square is marked **4**, so all four of its sides are on the loop. **Click** its top side to draw the first line.',
      highlight: ({ state, tileSize }) => [
        faceRect(state, tileSize, middle(state)),
        edgeRect(state, tileSize, side(state, middle(state), TOP)),
      ],
      pointer: ({ state, tileSize }) => edgeMid(state, tileSize, side(state, middle(state), TOP)),
      waitFor: ({ state }) => drawn(state, side(state, middle(state), TOP)),
    },
    {
      text: 'Now its **left side**. Clicking a line again rubs it out.',
      highlight: ({ state, tileSize }) =>
        edgeRect(state, tileSize, side(state, middle(state), LEFT)),
      pointer: ({ state, tileSize }) => edgeMid(state, tileSize, side(state, middle(state), LEFT)),
      waitFor: ({ state }) => drawn(state, side(state, middle(state), LEFT)),
    },
    {
      text: 'Every dot has two lines or none, and the dot where those two meet is full. **Right-click** the line running up from it to cross it out as unusable.',
      highlight: ({ state, tileSize }) =>
        edgeRect(state, tileSize, side(state, middle(state) - state.w, LEFT)),
      pointer: ({ state, tileSize }) => ({
        ...edgeMid(state, tileSize, side(state, middle(state) - state.w, LEFT)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => state.lines[side(state, middle(state) - state.w, LEFT)] === LINE_NO,
    },
    {
      text: 'Two sides left. **Click** the bottom side of the middle square.',
      highlight: ({ state, tileSize }) =>
        edgeRect(state, tileSize, side(state, middle(state), BOTTOM)),
      pointer: ({ state, tileSize }) =>
        edgeMid(state, tileSize, side(state, middle(state), BOTTOM)),
      waitFor: ({ state }) => drawn(state, side(state, middle(state), BOTTOM)),
    },
    {
      text: 'And the **right side** closes it. One loop, no loose ends, and the four **0**s stay clear of it.',
      highlight: ({ state, tileSize }) =>
        edgeRect(state, tileSize, side(state, middle(state), RIGHT)),
      pointer: ({ state, tileSize }) => edgeMid(state, tileSize, side(state, middle(state), RIGHT)),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved. **Undo** steps back through your lines, and **Type** in the pause menu swaps the squares for triangles, hexagons and stranger tilings.',
      target: '.type-select',
    },
  ],
};
