/**
 * Deterministic, string-seeded pseudo-random number generator.
 *
 * Any text is a valid seed. The same seed always produces the same puzzle for the
 * same version of a game's generator, which is what makes "random seed" game IDs
 * shareable. Uses a 128-bit string hash (cyrb128) to seed a small fast counter
 * generator (sfc32).
 */
export class Random {
  private a = 0;
  private b = 0;
  private c = 0;
  private d = 0;

  constructor(seed: string | [number, number, number, number]) {
    if (typeof seed === 'string') {
      [this.a, this.b, this.c, this.d] = hashSeed(seed);
    } else {
      [this.a, this.b, this.c, this.d] = seed;
    }
    // Warm up so that similar seeds diverge quickly.
    for (let i = 0; i < 12; i++) this.next();
  }

  /** An independent copy at the current position. */
  copy(): Random {
    const r = new Random([this.a, this.b, this.c, this.d]);
    // The constructor warmed up; restore the exact position instead.
    r.a = this.a;
    r.b = this.b;
    r.c = this.c;
    r.d = this.d;
    return r;
  }

  /** Uniform 32-bit unsigned integer. */
  next(): number {
    this.a >>>= 0;
    this.b >>>= 0;
    this.c >>>= 0;
    this.d >>>= 0;
    let t = (this.a + this.b) | 0;
    this.a = this.b ^ (this.b >>> 9);
    this.b = (this.c + (this.c << 3)) | 0;
    this.c = (this.c << 21) | (this.c >>> 11);
    this.d = (this.d + 1) | 0;
    t = (t + this.d) | 0;
    this.c = (this.c + t) | 0;
    return t >>> 0;
  }

  /** `bits` random bits (1..32) as an unsigned integer. */
  bits(bits: number): number {
    if (bits >= 32) return this.next();
    return this.next() >>> (32 - bits);
  }

  /** Uniform integer in [0, limit). */
  upto(limit: number): number {
    if (limit <= 0) throw new Error('Random.upto: limit must be positive');
    if (limit <= 1) return 0;
    // Rejection sampling to avoid modulo bias.
    const range = 0x100000000;
    const max = range - (range % limit);
    let r = this.next();
    while (r >= max) r = this.next();
    return r % limit;
  }

  /** Uniform integer in [lo, hi] inclusive. */
  range(lo: number, hi: number): number {
    return lo + this.upto(hi - lo + 1);
  }

  /** Uniform float in [0, 1). */
  float(): number {
    return this.next() / 0x100000000;
  }

  /** True with probability p. */
  chance(p: number): boolean {
    return this.float() < p;
  }

  /** In-place Fisher–Yates shuffle. Returns the same array. */
  shuffle<T>(arr: T[]): T[] {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = this.upto(i + 1);
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  /** A random element. */
  pick<T>(arr: readonly T[]): T {
    return arr[this.upto(arr.length)];
  }
}

function hashSeed(str: string): [number, number, number, number] {
  let h1 = 1779033703;
  let h2 = 3144134277;
  let h3 = 1013904242;
  let h4 = 2773480762;
  for (let i = 0; i < str.length; i++) {
    const k = str.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067);
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233);
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213);
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179);
  h1 ^= h2 ^ h3 ^ h4;
  h2 ^= h1;
  h3 ^= h1;
  h4 ^= h1;
  return [h1 >>> 0, h2 >>> 0, h3 >>> 0, h4 >>> 0];
}

/** A fresh 15-digit random seed string, like the original collection. */
export function newSeedString(): string {
  const buf = new Uint32Array(2);
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    crypto.getRandomValues(buf);
  } else {
    buf[0] = (Math.random() * 0x100000000) >>> 0;
    buf[1] = (Math.random() * 0x100000000) >>> 0;
  }
  const s = (buf[0].toString() + buf[1].toString() + Date.now().toString()).replace(/^0+/, '');
  return s.slice(0, 15).padStart(15, '7');
}
