import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  isMouseDrag,
  isMouseRelease,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import { hashNums } from '../../framework/drawing';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  BLANK,
  ERR_ADJ_ANY,
  ERR_OVERCOMMITTED,
  NONTENT,
  TENT,
  TREE,
  countTents,
  findErrors,
  isComplete,
  parseDesc,
} from './board';
import type { Board } from './board';
import { generate, solutionMove } from './generator';
import type { TentsParams } from './generator';
import {
  DIFFICULTY_CHARS,
  DIFFICULTY_NAMES,
  DIFF_EASY,
  DIFF_TRICKY,
  IMPOSSIBLE,
  SOLVED,
  solve,
  solveWithGuesses,
} from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type { TentsParams };

export interface TentsState {
  w: number;
  h: number;
  /** `BLANK`, `TREE`, `TENT` or `NONTENT` per cell, row-major. */
  grid: Uint8Array;
  /** Column counts then row counts; shared between states. */
  numbers: number[];
  completed: boolean;
  usedSolve: boolean;
}

export interface TentsUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** `LEFT_BUTTON` or `RIGHT_BUTTON` while a mouse gesture is in progress, else -1. */
  dragButton: number;
  /** Cells where the gesture started and where it currently is. */
  sx: number;
  sy: number;
  ex: number;
  ey: number;
  /** False once the pointer has left the grid, which cancels the gesture on release. */
  dragOk: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
/** Beyond this the row/column enumeration in the solver gets slow. */
const MAX_SIDE = 20;
const MIN_SIDE = 4;
const VALUE_CHARS = ['B', '', 'T', 'N'];

interface Geometry {
  t: number;
  /** Margin around everything. */
  border: number;
  /** Extra room to the right and below the grid for the counts. */
  gutter: number;
}

export function geometry(t: number): Geometry {
  return { t, border: Math.round(t * 0.3), gutter: Math.round(t * 0.9) };
}

function makeState(w: number, h: number, board: Board, usedSolve: boolean): TentsState {
  return {
    w,
    h,
    grid: board.grid,
    numbers: board.numbers,
    completed: isComplete(board.grid, w, h, board.numbers),
    usedSolve,
  };
}

/**
 * What a cell becomes when the current gesture is released. A click toggles a blank into
 * a tent (left) or grass (right) and clears anything else; a right drag turns the blanks
 * it covers into grass and leaves the rest alone; a left drag is just a click where it
 * started.
 */
export function dragXform(ui: TentsUI, x: number, y: number, v: number): number {
  let xmin = Math.min(ui.sx, ui.ex);
  let xmax = Math.max(ui.sx, ui.ex);
  let ymin = Math.min(ui.sy, ui.ey);
  let ymax = Math.max(ui.sy, ui.ey);
  if (ui.dragButton === LEFT_BUTTON) {
    xmin = xmax = ui.sx;
    ymin = ymax = ui.sy;
  }
  if (x < xmin || x > xmax || y < ymin || y > ymax) return v;
  if (v === TREE) return v;
  if (xmin === xmax && ymin === ymax) {
    if (ui.dragButton === LEFT_BUTTON) return v === BLANK ? TENT : BLANK;
    return v === BLANK ? NONTENT : BLANK;
  }
  if (ui.dragButton === RIGHT_BUTTON && v === BLANK) return NONTENT;
  return v;
}

// ------------------------------------------------------------------ drawing bits

function drawTree(dr: Drawing, px: number, py: number, t: number, bad: boolean, seed: number) {
  const cx = px + t / 2;
  const trunk = Math.max(2, t * 0.09);
  dr.polygon(
    [
      cx - trunk / 2,
      py + t * 0.5,
      cx + trunk / 2,
      py + t * 0.5,
      cx + trunk * 0.65,
      py + t * 0.9,
      cx - trunk * 0.65,
      py + t * 0.9,
    ],
    'brown',
    'brown',
    { seed, width: 1 },
  );
  const leaf = bad ? 'error' : 'green';
  const edge = bad ? dr.mix('error', 'ink', 0.4) : dr.mix('green', 'ink', 0.4);
  const lw = Math.max(1, t * 0.04);
  const blobs: [number, number, number][] = [
    [cx - t * 0.22, py + t * 0.44, t * 0.14],
    [cx + t * 0.22, py + t * 0.44, t * 0.14],
    [cx - t * 0.15, py + t * 0.27, t * 0.13],
    [cx + t * 0.15, py + t * 0.27, t * 0.13],
    [cx, py + t * 0.38, t * 0.22],
  ];
  for (let k = 0; k < blobs.length; k++) {
    const [bx, by, r] = blobs[k];
    dr.circle(bx, by, r, leaf, edge, { seed: seed * 7 + k, width: lw });
  }
}

function drawTent(
  dr: Drawing,
  px: number,
  py: number,
  t: number,
  bad: boolean,
  flash: boolean,
  seed: number,
) {
  const cx = px + t / 2;
  const cy = py + t / 2;
  const s = t / 3;
  const base = cy + s * 0.9;
  const fill = bad ? 'error' : flash ? 'ok' : 'orange';
  dr.polygon([cx - s, base, cx + s, base, cx, cy - s], fill, 'ink', {
    seed,
    width: Math.max(1.2, t * 0.05),
  });
  // A door, so it reads as a tent rather than a plain triangle.
  const d = s * 0.38;
  dr.polygon([cx - d, base, cx + d, base, cx, base - d * 1.7], dr.mix(fill, 'ink', 0.45), null, {
    seed: seed + 1,
  });
}

function drawGrass(dr: Drawing, px: number, py: number, t: number, seed: number) {
  dr.rect(px, py, t, t, dr.withAlpha('green', 0.16));
  const lw = Math.max(1, t * 0.04);
  const hgt = t * 0.16;
  for (let k = 0; k < 3; k++) {
    const bx = px + t * (0.22 + 0.56 * hashNums(seed, k, 1));
    const by = py + t * (0.4 + 0.45 * hashNums(seed, k, 2));
    const o = { alpha: 0.75, seed: seed + k };
    dr.line(bx, by, bx - hgt * 0.55, by - hgt, 'green', lw, o);
    dr.line(bx, by, bx, by - hgt * 1.25, 'green', lw, o);
    dr.line(bx, by, bx + hgt * 0.55, by - hgt, 'green', lw, o);
  }
}

/** A small red "!" diamond where two tents touch. */
function drawTouch(dr: Drawing, x: number, y: number, t: number, seed: number) {
  const r = t * 0.19;
  dr.polygon([x - r, y, x, y - r, x + r, y, x, y + r], 'error', 'ink', { seed, width: 1 });
  dr.line(x, y - r * 0.5, x, y + r * 0.1, 'paper', Math.max(1.2, t * 0.05), { rough: 0 });
  dr.dot(x, y + r * 0.45, Math.max(0.8, t * 0.035), 'paper');
}

// ------------------------------------------------------------------ the game

const game = defineGame<TentsParams, TentsState, TentsUI>({
  id: 'tents',
  name: 'Tents',
  description: 'Pitch a tent beside every tree without any two tents touching.',
  alsoKnownAs: 'Tents and Trees',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [8, 8, DIFF_EASY],
      [8, 8, DIFF_TRICKY],
      [10, 10, DIFF_EASY],
      [10, 10, DIFF_TRICKY],
      [15, 15, DIFF_EASY],
      [15, 15, DIFF_TRICKY],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, difficulty },
  })),
  defaultParams: () => ({ w: 8, h: 8, difficulty: DIFF_EASY }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? `d${DIFFICULTY_CHARS[p.difficulty]}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    const d = m[3] ? DIFFICULTY_CHARS.indexOf(m[3]) : DIFF_EASY;
    return { w, h, difficulty: d < 0 ? DIFF_EASY : d };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < MIN_SIDE || p.h < MIN_SIDE) return tx`Width and height must both be at least four`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      difficulty: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const board = parseDesc(desc, p.w, p.h) as Board;
    // A fresh puzzle is never complete, even one with nothing to place.
    return { ...makeState(p.w, p.h, board, false), completed: false };
  },

  canSolve: true,
  solve(orig, _curr, aux) {
    if (aux) return aux;
    const { w, h, numbers } = orig;
    const r = solve(w, h, orig.grid, numbers, DIFF_TRICKY);
    if (r.result === IMPOSSIBLE) throw new Error(tx`This puzzle is not self-consistent`);
    let grid: Uint8Array | null = r.result === SOLVED ? r.grid : null;
    if (!grid) grid = solveWithGuesses(w, h, orig.grid, numbers);
    if (!grid) throw new Error(tx`Unable to find a solution for this puzzle`);
    return solutionMove(grid, w);
  },

  textFormat(s) {
    const wide = s.numbers.some((k) => k > 9);
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const v = s.grid[y * s.w + x];
        row += v === TREE ? 'T' : v === TENT ? '*' : v === NONTENT ? '-' : '.';
      }
      rows.push(`${row} ${s.numbers[s.w + y]}`);
    }
    rows.push(s.numbers.slice(0, s.w).join(wide ? ' ' : ''));
    return rows.join('\n');
  },

  newUI: () => ({
    cx: 0,
    cy: 0,
    cursorVisible: false,
    dragButton: -1,
    sx: 0,
    sy: 0,
    ex: 0,
    ey: 0,
    dragOk: false,
  }),
  changedState(ui, _old, next) {
    if (next.completed) ui.cursorVisible = false;
    // A drag still held when Undo, Solve or a key changes the board must not be laid on
    // the new board at release.
    ui.dragButton = -1;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, grid } = state;
    const g = geometry(ds.tileSize);
    const x = Math.floor((mx - g.border) / g.t);
    const y = Math.floor((my - g.border) / g.t);
    const inside = x >= 0 && x < w && y >= 0 && y < h;

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      if (!inside) return null;
      ui.dragButton = b;
      ui.sx = ui.ex = x;
      ui.sy = ui.ey = y;
      ui.dragOk = true;
      ui.cursorVisible = false;
      return '';
    }
    if ((isMouseDrag(b) || isMouseRelease(b)) && ui.dragButton >= 0) {
      if (!inside) {
        ui.dragOk = false;
      } else {
        // Drags run along one row or column: snap to whichever the pointer is nearer.
        if (Math.abs(x - ui.sx) < Math.abs(y - ui.sy)) {
          ui.ex = ui.sx;
          ui.ey = y;
        } else {
          ui.ex = x;
          ui.ey = ui.sy;
        }
        ui.dragOk = true;
      }
      if (isMouseDrag(b)) return '';
      // Released: enact the gesture, unless it wandered off the grid.
      const parts: string[] = [];
      if (ui.dragOk) {
        const x1 = Math.min(ui.sx, ui.ex);
        const x2 = Math.max(ui.sx, ui.ex);
        const y1 = Math.min(ui.sy, ui.ey);
        const y2 = Math.max(ui.sy, ui.ey);
        for (let cy = y1; cy <= y2; cy++) {
          for (let cx = x1; cx <= x2; cx++) {
            const v = grid[cy * w + cx];
            const nv = dragXform(ui, cx, cy, v);
            if (nv !== v) parts.push(`${VALUE_CHARS[nv]}${cx},${cy}`);
          }
        }
      }
      ui.dragButton = -1;
      return parts.join(';');
    }

    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const v = grid[ui.cy * w + ui.cx];
      if (v === TREE) return '';
      let nv: number;
      if (b === CURSOR_SELECT) nv = v === BLANK ? TENT : BLANK;
      else if (b === CURSOR_SELECT2) nv = v === BLANK ? NONTENT : BLANK;
      else return null;
      return `${VALUE_CHARS[nv]}${ui.cx},${ui.cy}`;
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h, numbers } = state;
    const grid = state.grid.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        for (let i = 0; i < grid.length; i++) if (grid[i] !== TREE) grid[i] = NONTENT;
        continue;
      }
      const m = /^([BTN])(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      const i = y * w + x;
      if (grid[i] === TREE) return null;
      grid[i] = VALUE_CHARS.indexOf(m[1]);
    }
    return makeState(w, h, { grid, numbers }, usedSolve);
  },

  preferredTileSize: 32,
  computeSize(p, t) {
    const g = geometry(t);
    return { w: p.w * t + 2 * g.border + g.gutter, h: p.h * t + 2 * g.border + g.gutter };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, grid, numbers } = state;
    const g = geometry(ds.tileSize);
    const t = g.t;
    const b = g.border;
    const flash = flashOn(flashTime, FLASH_FRAME);
    const dragging = ui.dragButton >= 0;

    // What the grid will look like if the gesture in progress is released now; errors
    // only follow the cell the gesture started on, as in the original, so a right drag
    // does not flicker the highlights while it sweeps along.
    let view = grid;
    let errGrid = grid;
    if (dragging) {
      view = grid.slice();
      for (let y = 0; y < h; y++)
        for (let x = 0; x < w; x++) view[y * w + x] = dragXform(ui, x, y, grid[y * w + x]);
      errGrid = grid.slice();
      const s = ui.sy * w + ui.sx;
      errGrid[s] = dragXform(ui, ui.sx, ui.sy, grid[s]);
    }
    const errors = findErrors(errGrid, w, h, numbers);
    const counts = countTents(errGrid, w, h);

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (view[i] === NONTENT) drawGrass(dr, b + x * t, b + y * t, t, i);
      }
    }
    for (let x = 1; x < w; x++) dr.line(b + x * t, b, b + x * t, b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, b + y * t, b + w * t, b + y * t, 'faint', 1.2);

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = b + x * t;
        const py = b + y * t;
        const bad = (errors.cells[i] & ERR_OVERCOMMITTED) !== 0;
        if (view[i] === TREE) drawTree(dr, px, py, t, bad, i);
        else if (view[i] === TENT) {
          const touching = (errors.cells[i] & ERR_ADJ_ANY) !== 0;
          drawTent(dr, px, py, t, bad || touching, flash, i);
        }
      }
    }
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.4 });

    // Touching tents: one marker per pair, at the shared edge or corner.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (errGrid[i] !== TENT) continue;
        const px = b + x * t;
        const py = b + y * t;
        if (x + 1 < w && errGrid[i + 1] === TENT) drawTouch(dr, px + t, py + t / 2, t, i);
        if (y + 1 < h && errGrid[i + w] === TENT) drawTouch(dr, px + t / 2, py + t, t, i + 1);
        if (y + 1 < h && x + 1 < w && errGrid[i + w + 1] === TENT)
          drawTouch(dr, px + t, py + t, t, i + 2);
        if (y + 1 < h && x > 0 && errGrid[i + w - 1] === TENT) drawTouch(dr, px, py + t, t, i + 3);
      }
    }

    // Counts: red when they can no longer be met, grey once satisfied.
    const size = t * 0.5;
    const colourFor = (i: number) =>
      flash ? 'ok' : errors.lines[i] ? 'error' : counts[i] === numbers[i] ? 'pencil' : 'ink';
    for (let x = 0; x < w; x++) {
      dr.text(b + x * t + t / 2, b + h * t + g.gutter * 0.55, String(numbers[x]), {
        size,
        colour: colourFor(x),
        maxWidth: t * 0.9,
      });
    }
    for (let y = 0; y < h; y++) {
      dr.text(b + w * t + g.gutter * 0.55, b + y * t + t / 2, String(numbers[w + y]), {
        size,
        colour: colourFor(w + y),
        maxWidth: g.gutter * 0.9,
      });
    }

    if (dragging && ui.dragButton === RIGHT_BUTTON && (ui.ex !== ui.sx || ui.ey !== ui.sy)) {
      const x1 = Math.min(ui.sx, ui.ex);
      const y1 = Math.min(ui.sy, ui.ey);
      const x2 = Math.max(ui.sx, ui.ex);
      const y2 = Math.max(ui.sy, ui.ey);
      dr.rectOutline(b + x1 * t, b + y1 * t, (x2 - x1 + 1) * t, (y2 - y1 + 1) * t, 'accent', {
        width: 1.6,
        alpha: 0.7,
      });
    }

    if (ui.cursorVisible) {
      const inset = t * 0.1;
      dr.cursor(b + ui.cx * t + inset, b + ui.cy * t + inset, t - 2 * inset, t - 2 * inset);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // The first three tents and some grass of the puzzle the menu thumbnail shows (seed
  // `thumbnail:tents`, 8×8 Easy), so the preview shows what play looks like. A unit test
  // keeps these in step with the generator.
  thumbnailMoves: ['T0,0', 'T5,0', 'T2,1', 'N0,1', 'N1,1', 'N3,0'],
});

export default game;
