/**
 * Inertia: grid rules, puzzle generator and route solver.
 *
 * The grid is a string with one character per cell, row-major: `w` wall, `s` stop,
 * `g` gem, `m` mine, `b` blank; game descriptions additionally use `S` for the ball's
 * starting square (which behaves as a stop once the game begins). Outside the grid
 * everything counts as wall.
 *
 * The ball moves in one of eight directions and keeps going until the next square is a
 * wall, until it lands on a stop, or until it lands on a mine (and dies). Gems do not
 * stop it. Because of this the natural search space is not the set of squares but the
 * set of (square, direction) pairs: being on a square while moving one way is not the
 * same as being on it while moving another way.
 *
 * Generation follows the original design: fill a fifth of the grid with each of walls,
 * stops and mines, drop the ball somewhere, then work out which blank squares can be
 * crossed on some round trip from the start. Gems are only ever placed on those, so a
 * generated puzzle is always completable. Grids whose viable squares are bunched up in
 * one corner are rejected so the gems spread across the board.
 *
 * The solver builds the graph of resting places and gem crossings reachable from the
 * ball, then grows a tour with a nearest-insertion heuristic and trims redundant detours
 * with shortest-path replacements. It is not optimal (that would be a travelling
 * salesman problem) but it is quick and produces reasonable routes.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';

export const WALL = 'w';
export const STOP = 's';
export const GEM = 'g';
export const MINE = 'm';
export const BLANK = 'b';
export const START = 'S';

export const NDIRS = 8;
/** Direction vectors, clockwise from up; index 8 is used below to mean "at rest". */
export const DX = [0, 1, 1, 1, 0, -1, -1, -1];
export const DY = [-1, -1, 0, 1, 1, 1, 0, -1];
const REST = NDIRS;
const DP1 = NDIRS + 1;

/** The cell at (x, y), or a wall when outside the grid. */
export function cellAt(w: number, h: number, grid: string, x: number, y: number): string {
  return x < 0 || y < 0 || x >= w || y >= h ? WALL : grid[y * w + x];
}

/** Squares the ball may travel into (as opposed to walls, which block, and mines). */
function passable(c: string): boolean {
  return c === BLANK || c === GEM || c === STOP || c === START;
}

// ----------------------------------------------------------------------- sliding

export interface Slide {
  /** Every square the ball passes through, in order, ending where it comes to rest. */
  cells: number[];
  /** True when the last square is a mine. */
  dead: boolean;
}

/**
 * Slide the ball from (x, y) in direction `dir`. Returns null when the very first square
 * is a wall (the move is impossible); otherwise the squares crossed.
 */
export function slide(
  w: number,
  h: number,
  grid: string,
  x: number,
  y: number,
  dir: number,
): Slide | null {
  const dx = DX[dir];
  const dy = DY[dir];
  if (cellAt(w, h, grid, x + dx, y + dy) === WALL) return null;
  const cells: number[] = [];
  for (;;) {
    x += dx;
    y += dy;
    cells.push(y * w + x);
    const c = grid[y * w + x];
    if (c === MINE) return { cells, dead: true };
    if (c === STOP || cellAt(w, h, grid, x + dx, y + dy) === WALL) return { cells, dead: false };
  }
}

// -------------------------------------------------------------------- generation

/**
 * Whether a ball at (x1, y1) travelling in `d1` can next be at (x2, y2) travelling in
 * `d2`: either by coming to rest here and choosing a new direction (a stop, the start
 * square, or a wall ahead), or by rolling one square further in the same direction.
 */
function canGo(
  w: number,
  h: number,
  grid: string,
  x1: number,
  y1: number,
  d1: number,
  x2: number,
  y2: number,
  d2: number,
): boolean {
  const here = cellAt(w, h, grid, x1, y1);
  if (here === WALL || here === MINE) return false;
  if (x2 === x1 && y2 === y1) {
    return here === STOP || here === START || cellAt(w, h, grid, x1 + DX[d1], y1 + DY[d1]) === WALL;
  }
  return (
    d1 === d2 && x2 === x1 + DX[d1] && y2 === y1 + DY[d1] && passable(cellAt(w, h, grid, x2, y2))
  );
}

/**
 * Blank squares that can be crossed on some round trip from the start square, so a gem
 * placed there can always be collected. Two searches over (square, direction) states:
 * one forwards from the start, one backwards to it; a square qualifies when some
 * direction is marked by both.
 */
export function gemCandidates(w: number, h: number, grid: string): number[] {
  const wh = w * h;
  const start = grid.indexOf(START);
  if (start < 0) return [];
  const from = new Uint8Array(wh * NDIRS);
  const to = new Uint8Array(wh * NDIRS);
  const queue = new Int32Array(wh * NDIRS);
  for (let pass = 0; pass < 2; pass++) {
    const seen = pass === 0 ? from : to;
    const sign = pass === 0 ? 1 : -1;
    let head = 0;
    let tail = 0;
    for (let d = 0; d < NDIRS; d++) {
      const i = start * NDIRS + d;
      seen[i] = 1;
      queue[tail++] = i;
    }
    while (head < tail) {
      const i = queue[head++];
      const d = i % NDIRS;
      const cell = (i - d) / NDIRS;
      const x = cell % w;
      const y = (cell - x) / w;
      for (let n = -1; n < NDIRS; n++) {
        const x2 = n < 0 ? x + sign * DX[d] : x;
        const y2 = n < 0 ? y + sign * DY[d] : y;
        const d2 = n < 0 ? d : n;
        if (x2 < 0 || y2 < 0 || x2 >= w || y2 >= h) continue;
        const i2 = (y2 * w + x2) * NDIRS + d2;
        if (seen[i2]) continue;
        const ok =
          pass === 0
            ? canGo(w, h, grid, x, y, d, x2, y2, d2)
            : canGo(w, h, grid, x2, y2, d2, x, y, d);
        if (ok) {
          seen[i2] = 1;
          queue[tail++] = i2;
        }
      }
    }
  }
  const out: number[] = [];
  for (let c = 0; c < wh; c++) {
    if (grid[c] !== BLANK) continue;
    for (let d = 0; d < NDIRS; d++) {
      if (from[c * NDIRS + d] && to[c * NDIRS + d]) {
        out.push(c);
        break;
      }
    }
  }
  return out;
}

/**
 * Largest distance (in king moves, ignoring walls) from any square to the nearest of the
 * given squares. Used to reject layouts whose viable gem squares are all bunched up.
 */
function maxDistanceFrom(w: number, h: number, sources: number[]): number {
  const wh = w * h;
  const dist = new Int32Array(wh).fill(-1);
  const queue = new Int32Array(wh);
  let head = 0;
  let tail = 0;
  for (const s of sources) {
    dist[s] = 0;
    queue[tail++] = s;
  }
  let max = 0;
  while (head < tail) {
    const c = queue[head++];
    if (dist[c] > max) max = dist[c];
    const x = c % w;
    const y = (c - x) / w;
    for (let d = 0; d < NDIRS; d++) {
      const x2 = x + DX[d];
      const y2 = y + DY[d];
      if (x2 < 0 || y2 < 0 || x2 >= w || y2 >= h) continue;
      const c2 = y2 * w + x2;
      if (dist[c2] < 0) {
        dist[c2] = dist[c] + 1;
        queue[tail++] = c2;
      }
    }
  }
  return tail < wh ? Infinity : max;
}

/** Generate a puzzle description (one character per cell, with `S` marking the ball). */
export function generate(w: number, h: number, rng: Random): string {
  const wh = w * h;
  const fifth = Math.floor(wh / 5);
  let threshold = 2;
  let tries = 0;
  for (;;) {
    const cells: string[] = [];
    for (let i = 0; i < fifth; i++) cells.push(WALL);
    for (let i = 0; i < fifth; i++) cells.push(STOP);
    for (let i = 0; i < fifth; i++) cells.push(MINE);
    cells.push(START);
    while (cells.length < wh) cells.push(BLANK);
    rng.shuffle(cells);
    const grid = cells.join('');

    const candidates = gemCandidates(w, h, grid);
    if (candidates.length < fifth) continue;

    // Insist the viable squares are spread out; relax slowly if this layout is unlucky.
    if (maxDistanceFrom(w, h, candidates) > threshold) {
      if (++tries === 50) {
        threshold++;
        tries = 0;
      }
      continue;
    }

    rng.shuffle(candidates);
    for (let i = 0; i < fifth; i++) cells[candidates[i]] = GEM;
    return cells.join('');
  }
}

// ------------------------------------------------------------------------ solver

/**
 * Where a move from (x, y) in direction `d` ends up, as a node code `cell * 9 + dir`:
 * `dir` is 8 when the ball comes to rest, or `d` when it reaches a gem still in motion
 * (a gem is a node of its own so that routes can be cut and joined there). Returns -1
 * when the move would hit a mine.
 */
function moveGoesTo(w: number, h: number, grid: string, x: number, y: number, d: number): number {
  const dx = DX[d];
  const dy = DY[d];
  for (;;) {
    if (cellAt(w, h, grid, x + dx, y + dy) === WALL) return (y * w + x) * DP1 + REST;
    x += dx;
    y += dy;
    const c = grid[y * w + x];
    if (c === STOP) return (y * w + x) * DP1 + REST;
    if (c === GEM) return (y * w + x) * DP1 + d;
    if (c === MINE) return -1;
  }
}

interface Graph {
  /** Node codes (`cell * 9 + dir`) in discovery order; node 0 is the ball's position. */
  nodes: number[];
  /** CSR adjacency: forward edges of node i are `fwd[fwdStart[i] .. fwdStart[i+1])`. */
  fwdStart: Int32Array;
  fwd: Int32Array;
  bwdStart: Int32Array;
  bwd: Int32Array;
}

function buildGraph(w: number, h: number, grid: string, px: number, py: number): Graph {
  const wh = w * h;
  const nodeIndex = new Int32Array(wh * DP1).fill(-1);
  const nodes: number[] = [(py * w + px) * DP1 + REST];
  nodeIndex[nodes[0]] = 0;
  const targets: number[][] = [];
  for (let i = 0; i < nodes.length; i++) {
    const code = nodes[i];
    const d = code % DP1;
    const cell = (code - d) / DP1;
    const x = cell % w;
    const y = (cell - x) / w;
    const out: number[] = [];
    for (let dd = 0; dd < NDIRS; dd++) {
      if (d !== REST && d !== dd) continue;
      const to = moveGoesTo(w, h, grid, x, y, dd);
      if (to < 0 || to === code) continue;
      if (nodeIndex[to] < 0) {
        nodeIndex[to] = nodes.length;
        nodes.push(to);
      }
      out.push(nodeIndex[to]);
    }
    targets.push(out);
  }
  const n = nodes.length;
  const fwdStart = new Int32Array(n + 1);
  const bwdStart = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) {
    fwdStart[i + 1] = fwdStart[i] + targets[i].length;
    for (const j of targets[i]) bwdStart[j + 1]++;
  }
  for (let i = 0; i < n; i++) bwdStart[i + 1] += bwdStart[i];
  const fwd = new Int32Array(fwdStart[n]);
  const bwd = new Int32Array(fwdStart[n]);
  const fill = bwdStart.slice(0, n);
  for (let i = 0; i < n; i++) {
    targets[i].forEach((j, k) => {
      fwd[fwdStart[i] + k] = j;
      bwd[fill[j]++] = i;
    });
  }
  return { nodes, fwdStart, fwd, bwdStart, bwd };
}

/** Breadth-first distances from `sources` along the given adjacency into `dist`. */
function bfs(
  g: Graph,
  sources: Iterable<number>,
  backwards: boolean,
  dist: Int32Array,
  queue: Int32Array,
): void {
  const start = backwards ? g.bwdStart : g.fwdStart;
  const adj = backwards ? g.bwd : g.fwd;
  dist.fill(-1);
  let head = 0;
  let tail = 0;
  for (const s of sources) {
    if (dist[s] < 0) {
      dist[s] = 0;
      queue[tail++] = s;
    }
  }
  while (head < tail) {
    const u = queue[head++];
    for (let k = start[u]; k < start[u + 1]; k++) {
      const v = adj[k];
      if (dist[v] < 0) {
        dist[v] = dist[u] + 1;
        queue[tail++] = v;
      }
    }
  }
}

/**
 * Walk from `node` down a distance field to its zero, following forward edges when the
 * field measures distance *to* the zero, or backward edges when it measures distance
 * *from* it. Returns the nodes visited, starting with `node` and ending at the zero.
 */
function descend(g: Graph, node: number, dist: Int32Array, backwards: boolean): number[] {
  const start = backwards ? g.bwdStart : g.fwdStart;
  const adj = backwards ? g.bwd : g.fwd;
  const path = [node];
  let u = node;
  while (dist[u] > 0) {
    let next = -1;
    for (let k = start[u]; k < start[u + 1]; k++) {
      if (dist[adj[k]] === dist[u] - 1) {
        next = adj[k];
        break;
      }
    }
    if (next < 0) throw new Error(tx`inconsistent distance field`);
    path.push(next);
    u = next;
  }
  return path;
}

/**
 * Find a sequence of directions that collects every remaining gem from (px, py) without
 * touching a mine, or null when some gem cannot be collected from here. The route ends
 * back where it started, as in the original.
 */
export function solveRoute(
  w: number,
  h: number,
  grid: string,
  px: number,
  py: number,
): number[] | null {
  const wh = w * h;
  if (!grid.includes(GEM)) return [];
  const g = buildGraph(w, h, grid, px, py);
  const n = g.nodes.length;
  const cellOf = (ni: number) => Math.floor(g.nodes[ni] / DP1);
  const isGemNode = (ni: number) => grid[cellOf(ni)] === GEM;
  const dist = new Int32Array(n);
  const dist2 = new Int32Array(n);
  const queue = new Int32Array(n);

  // Grow the tour: repeatedly splice in a round trip to the nearest uncollected gem.
  const circuit = [0];
  const unvisited = new Uint8Array(wh);
  for (let c = 0; c < wh; c++) if (grid[c] === GEM) unvisited[c] = 1;
  for (;;) {
    bfs(g, circuit, false, dist, queue); // tour → node
    bfs(g, circuit, true, dist2, queue); // node → tour
    let target = -1;
    let best = -1;
    for (let i = 0; i < n; i++) {
      if (!unvisited[cellOf(i)] || dist[i] < 0 || dist2[i] < 0) continue;
      const d = dist[i] + dist2[i];
      if (best < 0 || d < best) {
        best = d;
        target = i;
      }
    }
    if (target < 0) break;

    bfs(g, [target], false, dist, queue); // target → node
    bfs(g, [target], true, dist2, queue); // node → target
    // Cheapest place to insert the detour: either a round trip from one tour node, or
    // a replacement for the edge between two consecutive tour nodes.
    let n1 = -1;
    let n2 = -1;
    best = -1;
    for (let i = 0; i < circuit.length; i++) {
      const a = circuit[i];
      if (dist[a] >= 0 && dist2[a] >= 0 && (best < 0 || dist[a] + dist2[a] < best)) {
        best = dist[a] + dist2[a];
        n1 = n2 = i;
      }
      if (i + 1 < circuit.length) {
        const b = circuit[i + 1];
        if (dist2[a] >= 0 && dist[b] >= 0 && (best < 0 || dist2[a] + dist[b] < best)) {
          best = dist2[a] + dist[b];
          n1 = i;
          n2 = i + 1;
        }
      }
    }
    if (best < 0) return null;
    const outward = descend(g, circuit[n1], dist2, false); // circuit[n1] … target
    const homeward = descend(g, circuit[n2], dist, true).reverse(); // target … circuit[n2]
    const detour = outward.concat(homeward.slice(1));
    circuit.splice(n1, n2 - n1 + 1, ...detour);
    for (const ni of detour) unvisited[cellOf(ni)] = 0;
  }

  // Trim: a stretch between two essential nodes (a gem collected nowhere else, or the
  // final node) can be replaced by a shortest path. Alternate directions so that
  // whichever visit of a repeated gem we keep, the other visits become removable.
  for (;;) {
    const before = circuit.length;
    for (const dir of [1, -1]) {
      const visits = new Int32Array(wh);
      for (const ni of circuit) if (isGemNode(ni)) visits[cellOf(ni)]++;
      for (let c = 0; c < wh; c++) if (grid[c] === GEM && visits[c] === 0) return null;
      let i = dir > 0 ? 0 : circuit.length - 1;
      let j = i;
      while (i >= 0 && i < circuit.length) {
        const c = cellOf(circuit[i]);
        if (grid[c] === GEM && visits[c] > 1) {
          visits[c]--;
        } else if (grid[c] === GEM || i === circuit.length - 1) {
          const p = Math.min(i, j);
          const q = Math.max(i, j);
          bfs(g, [circuit[p]], false, dist, queue);
          const path = descend(g, circuit[q], dist, true).reverse(); // circuit[p] … circuit[q]
          circuit.splice(p, q - p + 1, ...path);
          const newQ = p + path.length - 1;
          for (let k = p + 1; k < newQ; k++)
            if (isGemNode(circuit[k])) visits[cellOf(circuit[k])]++;
          if (dir > 0) i = newQ;
          j = i;
        }
        i += dir;
      }
    }
    if (circuit.length === before) break;
  }

  // Read the directions off the resting places along the tour.
  const route: number[] = [];
  let x = px;
  let y = py;
  for (let i = 1; i < circuit.length; i++) {
    const code = g.nodes[circuit[i]];
    if (code % DP1 !== REST) continue;
    const cell = (code - REST) / DP1;
    const x2 = cell % w;
    const y2 = (cell - x2) / w;
    const dx = Math.sign(x2 - x);
    const dy = Math.sign(y2 - y);
    if (dx === 0 && dy === 0) continue;
    const d = DX.findIndex((v, k) => v === dx && DY[k] === dy);
    route.push(d);
    x = x2;
    y = y2;
  }
  return route;
}
