/**
 * Tents puzzle generation, following the original's strategy: build a solution and keep
 * it only if the solver of the requested difficulty finds it uniquely while the next
 * easier solver cannot.
 *
 * One fifth of the squares get tents, placed greedily in a random order so that no two
 * touch. Each tent is then given its own tree on an adjacent square by a randomised
 * bipartite matching (tents first, because random tent layouts that respect the
 * separation rule are the hard part to find). Grids with an empty row or column are
 * rejected because they look dull, then the counts are read off and the solver decides.
 */
import type { Random } from '../../framework/rng';
import type { NewDesc } from '../../framework/types';
import { DIRS4, DIRS8, inBounds } from '../../framework/grid';
import { BLANK, TENT, TREE, countTents, encodeDesc } from './board';
import { augment } from './matching';
import { DIFF_EASY, SOLVED, STUCK, solve } from './solver';

export interface TentsParams {
  w: number;
  h: number;
  difficulty: number;
}

/** The Solve move for a finished grid: reset to grass, then every tent. */
export function solutionMove(grid: Uint8Array, w: number): string {
  let s = 'S';
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] === TENT) s += `;T${i % w},${Math.floor(i / w)}`;
  }
  return s;
}

/** Place `count` mutually non-touching tents, trying squares in `order`. */
export function placeTents(
  w: number,
  h: number,
  count: number,
  order: number[],
): Uint8Array | null {
  const grid = new Uint8Array(w * h);
  let left = count;
  for (let k = 0; k < order.length && left > 0; k++) {
    const i = order[k];
    const x = i % w;
    const y = Math.floor(i / w);
    let ok = true;
    for (const [dx, dy] of DIRS8) {
      const nx = x + dx;
      const ny = y + dy;
      if (inBounds(nx, ny, w, h) && grid[ny * w + nx] === TENT) {
        ok = false;
        break;
      }
    }
    if (ok) {
      grid[i] = TENT;
      left--;
    }
  }
  return left > 0 ? null : grid;
}

/** Give every tent its own adjacent tree, choosing among the possibilities at random. */
export function placeTrees(w: number, h: number, grid: Uint8Array, rng: Random): boolean {
  const tents: number[] = [];
  for (let i = 0; i < grid.length; i++) if (grid[i] === TENT) tents.push(i);
  rng.shuffle(tents);
  const adj = tents.map((i) => {
    const x = i % w;
    const y = Math.floor(i / w);
    const out: number[] = [];
    for (const [dx, dy] of DIRS4) {
      const nx = x + dx;
      const ny = y + dy;
      if (inBounds(nx, ny, w, h) && grid[ny * w + nx] !== TENT) out.push(ny * w + nx);
    }
    return rng.shuffle(out);
  });
  const matchL = new Int32Array(tents.length).fill(-1);
  const matchR = new Int32Array(grid.length).fill(-1);
  const seen = new Uint8Array(grid.length);
  for (let l = 0; l < tents.length; l++) {
    seen.fill(0);
    if (!augment(l, adj, matchL, matchR, seen)) return false;
  }
  for (let l = 0; l < tents.length; l++) grid[matchL[l]] = TREE;
  return true;
}

function everyLineOccupied(w: number, h: number, grid: Uint8Array): boolean {
  for (let x = 0; x < w; x++) {
    let any = false;
    for (let y = 0; y < h && !any; y++) if (grid[y * w + x] !== BLANK) any = true;
    if (!any) return false;
  }
  for (let y = 0; y < h; y++) {
    let any = false;
    for (let x = 0; x < w && !any; x++) if (grid[y * w + x] !== BLANK) any = true;
    if (!any) return false;
  }
  return true;
}

export function generate(p: TentsParams, rng: Random): NewDesc {
  const { w, h } = p;
  let diff = p.difficulty;
  // Tricky deductions have nothing to bite on in a 4×4; the original downgrades too.
  if (diff > DIFF_EASY && w <= 4 && h <= 4) diff = DIFF_EASY;
  const n = w * h;
  const ntrees = Math.floor(n / 5);
  const order: number[] = [];
  for (let i = 0; i < n; i++) order.push(i);

  for (;;) {
    rng.shuffle(order);
    const grid = placeTents(w, h, ntrees, order);
    if (!grid) continue;
    if (!placeTrees(w, h, grid, rng)) continue;
    if (!everyLineOccupied(w, h, grid)) continue;
    const numbers = countTents(grid, w, h);
    const puzzle = grid.map((v) => (v === TREE ? TREE : BLANK));
    if (solve(w, h, puzzle, numbers, diff - 1).result !== STUCK) continue;
    if (solve(w, h, puzzle, numbers, diff).result !== SOLVED) continue;
    return { desc: encodeDesc(puzzle, w, h, numbers), aux: solutionMove(grid, w) };
  }
}
