import { tx } from '../../i18n';
/**
 * Clue handling for Pattern (nonograms).
 *
 * A grid cell is `EMPTY` (known white), `FULL` (black) or `UNKNOWN`. A line (row or
 * column) is described by its clue: the lengths of its runs of black cells, in order.
 * Lines are numbered the way the original collection does it and the way the game
 * description lists them: columns `0..w-1` left to right, then rows `w..w+h-1` top to
 * bottom.
 */

export const EMPTY = 0;
export const FULL = 1;
export const UNKNOWN = 2;

export interface Clues {
  cols: number[][];
  rows: number[][];
}

/** Run lengths of the black cells in `line[0..len)`; unknown cells count as white. */
export function runsOf(line: ArrayLike<number>, len = line.length): number[] {
  const runs: number[] = [];
  let run = 0;
  for (let i = 0; i < len; i++) {
    if (line[i] === FULL) run++;
    else if (run) {
      runs.push(run);
      run = 0;
    }
  }
  if (run) runs.push(run);
  return runs;
}

/**
 * Copy line `index` of the grid (a column when `index < w`, else row `index - w`) into
 * `out` and return its length.
 */
export function readLine(
  grid: ArrayLike<number>,
  w: number,
  h: number,
  index: number,
  out: Uint8Array,
): number {
  if (index < w) {
    for (let y = 0; y < h; y++) out[y] = grid[y * w + index];
    return h;
  }
  const base = (index - w) * w;
  for (let x = 0; x < w; x++) out[x] = grid[base + x];
  return w;
}

/** Clues of a fully known grid. */
export function cluesOf(grid: ArrayLike<number>, w: number, h: number): Clues {
  const buf = new Uint8Array(Math.max(w, h));
  const cols: number[][] = [];
  const rows: number[][] = [];
  for (let i = 0; i < w + h; i++) {
    const len = readLine(grid, w, h, i, buf);
    (i < w ? cols : rows).push(runsOf(buf, len));
  }
  return { cols, rows };
}

/** Description string: clue lists for columns then rows, `/`-separated, runs joined by `.`. */
export function encodeClues(clues: Clues): string {
  return [...clues.cols, ...clues.rows].map((c) => c.join('.')).join('/');
}

const CLUE_RE = /^[1-9]\d*(\.[1-9]\d*)*$/;

/** Parse a description; returns the clues or a user-facing error message. */
export function parseDesc(desc: string, w: number, h: number): Clues | string {
  const parts = desc.split('/');
  if (parts.length > w + h) return tx`too many row/column specifications`;
  if (parts.length < w + h) return tx`too few row/column specifications`;
  const cols: number[][] = [];
  const rows: number[][] = [];
  for (let i = 0; i < w + h; i++) {
    const part = parts[i];
    const len = i < w ? h : w;
    let clue: number[] = [];
    if (part !== '') {
      if (!CLUE_RE.test(part)) return tx`unrecognised character in game description`;
      clue = part.split('.').map(Number);
    }
    let space = len + 1;
    for (const n of clue) space -= n + 1;
    if (space < 0)
      return i < w
        ? tx`at least one column contains more numbers than will fit`
        : tx`at least one row contains more numbers than will fit`;
    (i < w ? cols : rows).push(clue);
  }
  return { cols, rows };
}

export function sameRuns(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** True when the black runs of every row and column equal the clues. */
export function gridMatchesClues(grid: ArrayLike<number>, w: number, h: number, clues: Clues) {
  const buf = new Uint8Array(Math.max(w, h));
  for (let i = 0; i < w + h; i++) {
    const len = readLine(grid, w, h, i, buf);
    const clue = i < w ? clues.cols[i] : clues.rows[i - w];
    if (!sameRuns(runsOf(buf, len), clue)) return false;
  }
  return true;
}

/**
 * Is a partially filled line provably wrong? Deliberately a weak check, like the
 * original's: only *complete* black runs (bounded on both sides by a white cell or the
 * edge) are compared with the clue. Runs separated purely by white cells must appear
 * consecutively in the clue; an unknown cell in between lets them match clue entries
 * further apart. Anything stronger would give away deductions the player has not made.
 */
export function lineHasError(line: ArrayLike<number>, len: number, clue: number[]): boolean {
  // Pretend the clue has a 0 at both ends and the line a white cell at both ends; the
  // edge cases then fall out of the ordinary handling.
  const at = (k: number) => (k < 0 || k >= clue.length ? 0 : clue[k]);
  let pos = 0; // lowest clue index where the next run may match
  let contig = 1; // runs matched consecutively so far (the leading 0 counts)
  const found = (r: number): boolean => {
    for (let p = pos; p <= clue.length; p++) {
      if (at(p) !== r) continue;
      let ok = true;
      for (let i = 1; i <= contig && ok; i++) if (at(p - i) !== at(pos - i)) ok = false;
      if (!ok) continue;
      pos = p + 1;
      contig++;
      return true;
    }
    return false;
  };
  let run = 0; // -1 while the current run started after an unknown cell
  for (let j = 0; j <= len; j++) {
    const v = j === len ? EMPTY : line[j];
    if (v === UNKNOWN) {
      run = -1;
      contig = 0;
    } else if (v === FULL) {
      if (run >= 0) run++;
    } else {
      if (run > 0 && !found(run)) return true;
      run = 0;
    }
  }
  return !found(0);
}
