/**
 * Filling puzzle generation.
 *
 * A solved board is built by tiling the grid with regions: every square starts as its
 * own region, and while any two neighbouring regions have the same size one of them is
 * merged into a neighbour (preferably one of a different size). When no two adjacent
 * regions are equal in size, writing each region's size into its squares gives a valid
 * Fillomino solution. Boards where a region outgrows the largest allowed digit are
 * thrown away and the tiling starts again.
 *
 * Clues are then removed one at a time, largest digits first, keeping every clue whose
 * removal leaves the deductive solver unable to finish the puzzle. The result is a
 * puzzle the solver can complete from the clues alone, so its solution is unique.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { maxDigit, solveDeductive } from './solver';

export interface FillingParams {
  w: number;
  h: number;
}

const DX = [-1, 1, 0, 0];
const DY = [0, 0, -1, 1];

/** Randomly tile the grid with regions; returns each square's region size. */
export function makeBoard(w: number, h: number, rng: Random): Uint8Array {
  const sz = w * h;
  const maxsize = maxDigit(w, h);
  const order: number[] = [];
  for (let i = 0; i < sz; i++) order.push(i);
  const parent = new Int32Array(sz);
  const size = new Int32Array(sz);
  const find = (i: number): number => {
    while (parent[i] !== i) {
      parent[i] = parent[parent[i]];
      i = parent[i];
    }
    return i;
  };
  /** Distinct roots of the regions next to region `a`, gathered from all its squares. */
  const members: number[][] = [];
  const neighbours = (a: number): number[] => {
    const out: number[] = [];
    for (const i of members[a]) {
      const x = i % w;
      const y = (i - x) / w;
      for (let d = 0; d < 4; d++) {
        const nx = x + DX[d];
        const ny = y + DY[d];
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        const b = find(ny * w + nx);
        if (b !== a && !out.includes(b)) out.push(b);
      }
    }
    return out;
  };
  const merge = (a: number, b: number): void => {
    parent[b] = a;
    size[a] += size[b];
    members[a].push(...members[b]);
    members[b] = [];
  };

  for (;;) {
    rng.shuffle(order);
    for (let i = 0; i < sz; i++) parent[i] = i;
    size.fill(1);
    members.length = 0;
    for (let i = 0; i < sz; i++) members.push([i]);
    let ok = true;
    let change = true;
    while (change && ok) {
      change = false;
      for (let k = 0; k < sz && ok; k++) {
        const a = find(order[k]);
        const nbrs = neighbours(a);
        const equal = nbrs.filter((b) => size[b] === size[a]);
        if (!equal.length) continue;
        // Two neighbouring regions have the same size, so one of them has to grow. Prefer
        // growing this one into a differently sized neighbour (so sizes do not simply
        // keep doubling), then merging the equal pair, then growing the other region;
        // any option that keeps regions within the largest digit will do.
        const fits = (x: number, y: number) => size[x] + size[y] <= maxsize;
        let options = nbrs.filter((b) => size[b] !== size[a] && fits(a, b)).map((b) => [a, b]);
        if (!options.length) options = equal.filter((b) => fits(a, b)).map((b) => [a, b]);
        if (!options.length) {
          for (const b of equal) {
            for (const c of neighbours(b)) if (c !== a && fits(b, c)) options.push([b, c]);
          }
        }
        if (!options.length) {
          ok = false;
          break;
        }
        const [x, y] = rng.pick(options);
        merge(x, y);
        change = true;
      }
    }
    if (!ok) continue;
    const board = new Uint8Array(sz);
    for (let i = 0; i < sz; i++) board[i] = size[find(i)];
    return board;
  }
}

/** Remove clues that the solver does not need, largest digits first. */
export function minimiseClues(board: Uint8Array, w: number, h: number, rng: Random): Uint8Array {
  const sz = w * h;
  const clues = board.slice();
  const order: number[] = [];
  for (let i = 0; i < sz; i++) order.push(i);
  rng.shuffle(order);
  // Stable sort keeps the shuffled order within each digit.
  order.sort((a, b) => board[b] - board[a]);
  for (const i of order) {
    const v = clues[i];
    clues[i] = 0;
    if (!solveDeductive(clues, w, h)) clues[i] = v;
  }
  return clues;
}

export function encodeBoard(board: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < board.length; i++) s += String.fromCharCode(48 + board[i]);
  return s;
}

/**
 * The clues as the original collection writes them: a digit for each given square and a
 * letter for each run of empty ones (`a` is one, `z` twenty-six), so its game IDs and
 * ours are the same thing.
 */
export function encodeDesc(clues: ArrayLike<number>): string {
  let s = '';
  let run = 0;
  const flush = () => {
    for (; run > 26; run -= 26) s += 'z';
    if (run) s += String.fromCharCode(96 + run);
    run = 0;
  };
  for (let i = 0; i < clues.length; i++) {
    if (!clues[i]) {
      run++;
      continue;
    }
    flush();
    s += String.fromCharCode(48 + clues[i]);
  }
  flush();
  return s;
}

/** Generate a puzzle description plus the solved board as `aux` (`s` + digits). */
export function generateFilling(p: FillingParams, rng: Random): { desc: string; aux: string } {
  const board = makeBoard(p.w, p.h, rng);
  const clues = minimiseClues(board, p.w, p.h, rng);
  return { desc: encodeDesc(clues), aux: 's' + encodeBoard(board) };
}

/**
 * Parse a description into clue digits, or return an error message. A letter is a run
 * of empty squares, as in the original; a `0` is one empty square, which is how this
 * collection used to write them, so old saved games still load.
 */
export function parseDesc(w: number, h: number, desc: string): Uint8Array | string {
  const sz = w * h;
  const max = maxDigit(w, h);
  const clues = new Uint8Array(sz);
  let i = 0;
  for (const ch of desc) {
    const c = ch.charCodeAt(0);
    if (c >= 97 && c <= 122) {
      i += c - 96;
      if (i > sz) return tx`Description is too long`;
      continue;
    }
    const v = c - 48;
    if (v < 0 || v > 9) return tx`Description must contain only digits`;
    if (i >= sz) return tx`Description is too long`;
    if (v > max) return tx`Digits in a ${w}×${h} puzzle cannot exceed ${max}`;
    clues[i++] = v;
  }
  if (i < sz) return tx`Description is too short`;
  return clues;
}
