import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { NONTENT, TENT } from './board';
import type { TentsParams, TentsState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A tent with its apex at (x, y), `w` wide at the base and `h` tall. */
function tent(c: C, x: number, y: number, w: number, h: number): string {
  const b = y + h;
  return (
    shape(`M${x} ${y} L${x + w / 2} ${b} H${x - w / 2} Z`, c.orange, c.ink) +
    shape(`M${x} ${y + h * 0.35} L${x + w * 0.16} ${b} H${x - w * 0.16} Z`, c.ink, c.ink, 3)
  );
}

function tree(c: C, x: number, y: number, r: number): string {
  return (
    shape(
      `M${x - r * 0.22} ${y + r * 0.6} H${x + r * 0.22} V${y + r * 1.9} H${x - r * 0.22} Z`,
      c.brown,
      c.ink,
      3.5,
    ) +
    `<circle cx="${x}" cy="${y}" r="${r}" fill="${c.green}" stroke="${c.ink}" stroke-width="4"/>`
  );
}

export const achievements = defineAchievements<TentsParams, TentsState>([
  {
    id: 'no-grass',
    name: 'Pitch Perfect',
    description: 'Solve a 10×10 or larger Tents without marking a single square as grass.',
    tier: 'silver',
    hue: 'green',
    art: (c) =>
      tent(c, 38, 30, 40, 36) +
      tree(c, 70, 34, 12) +
      line('M20 76 H56', c.ink, 4.5) +
      // A tuft of grass, struck out.
      line('M64 80 L62 68 M70 80 V64 M76 80 L79 68', c.green, 4.5) +
      line('M58 62 L84 84', c.red, 6),
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 100 && ctx.history.every((s) => !s.grid.includes(NONTENT)),
  },
  {
    id: 'no-strikes',
    name: 'Happy Campers',
    description: 'Solve a 15×15 Tents without ever taking down a tent.',
    tier: 'gold',
    hue: 'blue',
    art: (c) =>
      // Pitched for good: guy ropes, pegs and a pennant, under a crescent moon.
      line('M50 36 L20 76 M50 36 L80 76', c.ink, 3) +
      line('M17 73 V80 M83 73 V80', c.brown, 5) +
      tent(c, 50, 36, 44, 42) +
      line('M50 36 V20', c.ink, 4) +
      shape('M50 20 L63 25 L50 30 Z', c.red, c.ink, 3) +
      shape('M72 16 A10 10 0 1 0 82 30 A8 8 0 1 1 72 16 Z', c.yellow, c.ink, 3.5) +
      line('M18 80 H84', c.ink, 4.5),
    test: (ctx) => {
      if (ctx.params.w * ctx.params.h < 225) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].grid;
        const b = ctx.history[k].grid;
        for (let i = 0; i < b.length; i++) if (a[i] === TENT && b[i] !== TENT) return false;
      }
      return true;
    },
  },
]);
