import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { CELL_NEUTRAL, CELL_POSITIVE } from './board';
import type { MagnetsState, MagnetsUI } from './index';

/** Clues sit outside the grid on every side, so the border is more than a tile wide. */
const border = (t: number) => Math.round(t * 1.1);
/** How far a clue sits from the grid edge, in tiles (`CLUE_OFFSET` in index.ts). */
const CLUE_OFFSET = 0.55;

const at = (state: MagnetsState, x: number, y: number) => state.cells[y * state.w + x];

function clueBox(cx: number, cy: number, t: number): TutorialRect {
  const r = t * 0.36;
  return { x: cx - r, y: cy - r, w: 2 * r, h: 2 * r };
}

/** The `+` count above column `x`. */
function colPlus(x: number, t: number): TutorialRect {
  const b = border(t);
  return clueBox(b + (x + 0.5) * t, b - CLUE_OFFSET * t, t);
}

/** The `−` count below column `x`. */
function colMinus(state: MagnetsState, x: number, t: number): TutorialRect {
  const b = border(t);
  return clueBox(b + (x + 0.5) * t, b + state.h * t + CLUE_OFFSET * t, t);
}

/** The `+` count to the left of row `y`. */
function rowPlus(y: number, t: number): TutorialRect {
  const b = border(t);
  return clueBox(b - CLUE_OFFSET * t, b + (y + 0.5) * t, t);
}

/** The `−` count to the right of row `y`. */
function rowMinus(state: MagnetsState, y: number, t: number): TutorialRect {
  const b = border(t);
  return clueBox(b + state.w * t + CLUE_OFFSET * t, b + (y + 0.5) * t, t);
}

/** The grid together with the ring of clues around it. */
function boardRect(state: MagnetsState, t: number): TutorialRect {
  const b = border(t);
  const m = (CLUE_OFFSET + 0.36) * t;
  return { x: b - m, y: b - m, w: state.w * t + 2 * m, h: state.h * t + 2 * m };
}

/**
 * A 5×2 Easy puzzle: five dominoes, one of them a blank, and a bottom row that needs a
 * `−` from every domino that reaches it — which unlocks all the rest.
 */
export const tutorial: Tutorial<MagnetsState, MagnetsUI> = {
  steps: [
    {
      gameId: '5x2:11110,22,11101,13,LRTLRLRBLR',
      text: 'Each domino is either a magnet, with a **+** half and a **−** half, or a blank. The numbers count the **+** poles (top and left) and **−** poles (bottom and right) of each line, and like poles may never touch.',
      highlight: ({ state, tileSize }) => boardRect(state, tileSize),
    },
    {
      text: 'The bottom row wants three **−** poles and only three dominoes reach into it, so each must give one. **Left-click** the top half of the upright domino to make it **+**, sending its **−** downstairs.',
      highlight: ({ state, tileSize }) => [
        cellRect(2, 0, tileSize, border(tileSize), 1, 2),
        rowMinus(state, 1, tileSize),
      ],
      pointer: ({ tileSize }) => cellCentre(2, 0, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 2, 0) === CELL_POSITIVE,
    },
    {
      text: 'So the wide domino at the bottom right is a magnet too, and the **0** above the last column forbids a **+** there. **Left-click** its left half to put the **+** on that side.',
      highlight: ({ tileSize }) => [
        cellRect(3, 1, tileSize, border(tileSize), 2, 1),
        colPlus(4, tileSize),
      ],
      pointer: ({ tileSize }) => cellCentre(3, 1, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 3, 1) === CELL_POSITIVE,
    },
    {
      text: 'The fourth column now has its one **+** and wants no **−** at all, so the domino above can be neither. **Right-click** it to mark it blank.',
      highlight: ({ state, tileSize }) => [
        cellRect(3, 0, tileSize, border(tileSize), 2, 1),
        colPlus(3, tileSize),
        colMinus(state, 3, tileSize),
      ],
      pointer: ({ tileSize }) => ({
        ...cellCentre(3, 0, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => at(state, 3, 0) === CELL_NEUTRAL,
    },
    {
      text: 'The top row still needs one **+** and one **−** from the wide domino on the left. Its right half touches a **+**, and like poles cannot touch — so **left-click** its left half.',
      highlight: ({ state, tileSize }) => [
        cellRect(0, 0, tileSize, border(tileSize), 2, 1),
        cellRect(2, 0, tileSize, border(tileSize)),
        rowPlus(0, tileSize),
        rowMinus(state, 0, tileSize),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 0, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 0, 0) === CELL_POSITIVE,
    },
    {
      text: 'One domino left. The first column has spent its **+** up top, so the **+** here belongs on the right: **left-click** the right half to finish.',
      highlight: ({ tileSize }) => [
        cellRect(0, 1, tileSize, border(tileSize), 2, 1),
        colPlus(0, tileSize),
      ],
      pointer: ({ tileSize }) => cellCentre(1, 1, tileSize, border(tileSize)),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! Clicking the same half again flips a magnet round, a second right-click leaves question marks to note "magnet, but which way?", and **Undo** steps back.',
      target: '[data-cmd="undo"]',
    },
  ],
};
