/**
 * Console-style navigation: the arrow keys (and a controller's D-pad, `src/ui/gamepad.ts`)
 * move a drawn selector from one control to the nearest one in that direction, the way a
 * game's menus work, instead of the browser's Tab walk through the document.
 *
 * - **Which controls.** Whatever can take the focus in the *active layer*: the top dialog
 *   (the pause menu is one), an explicit `[data-nav-layer]` panel, the open help drawer,
 *   the results card, or else the page itself (welcome, collection, achievements). Nothing
 *   is registered per screen, so a new button or a new screen is navigable by default.
 *   A panel that is not a dialog but should hold the arrows while it is up (a settings
 *   sheet, say) marks itself `data-nav-layer`; `data-nav-default` names where the selector
 *   starts in it.
 * - **Not the board.** On the play page the arrows belong to the puzzle's own cursor, and
 *   are only taken over while something lies over it; the results card only while it has
 *   the keyboard (the board keeps its arrows when the player clicks back onto it).
 * - **Not a field.** A text field keeps Left and Right for its caret, a slider all four.
 * - **Pages.** Moving off the side of a paged grid (`src/ui/pager.ts`) turns the page and
 *   lands on the card at the matching edge of the next one.
 * - **Scrolling.** Up and Down with nothing further that way scroll the layer instead (the
 *   rules in the help drawer, a long dialog on a phone).
 * - **The selector** is a sketched ring in the accent colour that glides between targets.
 *   It shows only while the keyboard (or a controller) is what the player last used; the
 *   first pointer movement puts it away. With less motion asked for, it jumps.
 * - **Esc** keeps doing what it already does (close, pause); a screen with nowhere else to
 *   go back to (the achievements) goes back to the collection.
 *
 * Tab, Enter and Space are left to the browser: Tab order is unchanged, and a focused
 * button is still pressed by the keys that always pressed it.
 *
 * The same module gives the interface its sounds (`src/ui/sound.ts`): a tick as the
 * selector steps (or a mouse crosses onto something pressable), a click as a button goes
 * down, and the swish of a sheet laid over the page and lifted off it.
 */

import { onAdStateChange } from '../crazygames';
import { prefersReducedMotion } from './anim';
import { entryPoint, pickInDirection, type NavDir, type NavRect } from './navPick';
import { playSound } from './sound';

// ------------------------------------------------------------------ pagers

interface NavPager {
  /** Turn one page forwards (+1) or back (-1); false when there was no page that way. */
  turn(delta: 1 | -1): boolean;
}

const pagers = new Map<HTMLElement, NavPager>();

/**
 * A paged grid tells the navigator about itself, so moving off its side turns the page.
 * Returns the function that takes it off the list again.
 */
export function registerNavPager(viewport: HTMLElement, pager: NavPager): () => void {
  pagers.set(viewport, pager);
  return () => {
    if (pagers.get(viewport) === pager) pagers.delete(viewport);
  };
}

function pagerFor(el: HTMLElement): [HTMLElement, NavPager] | null {
  for (const [vp, p] of pagers) if (vp.isConnected && vp.contains(el)) return [vp, p];
  return null;
}

// ------------------------------------------------------------------ what can be reached

const FOCUSABLE =
  'button, input, select, textarea, summary, a[href], [role="link"], [role="tab"], [tabindex]';

/** Things that are pressed, for the click and the hover tick. */
const PRESSABLE =
  'button, a[href], [role="link"], [role="tab"], [role="option"], summary, .btn, .card:not(.locked)';

/** Presses that already make a sound of their own, or turn one on or off. */
const OWN_SOUND =
  '.unlock-btn, .card.locked, [data-cmd="undo"], [data-cmd="redo"], [data-cmd="hint"], .keypad, .pager-arrow, .pager-dot, .puzzle-canvas';

const TEXT_TYPES = new Set([
  'text',
  'search',
  'email',
  'url',
  'tel',
  'password',
  'number',
  'date',
  'time',
]);

function isTextField(el: Element): boolean {
  if (el instanceof HTMLTextAreaElement) return true;
  if (el instanceof HTMLElement && el.isContentEditable) return true;
  return el instanceof HTMLInputElement && TEXT_TYPES.has(el.type);
}

function isSlider(el: Element): boolean {
  return el instanceof HTMLInputElement && el.type === 'range';
}

function overflowClips(el: Element): boolean {
  const cs = getComputedStyle(el);
  return cs.overflowX !== 'visible' || cs.overflowY !== 'visible';
}

/** The part of `el` that can actually be seen, clipped by its scrollers and the window. */
function visibleRect(el: HTMLElement, layer: HTMLElement): NavRect | null {
  const r = el.getBoundingClientRect();
  if (r.width < 2 || r.height < 2) return null;
  let box: NavRect = {
    left: Math.max(0, r.left),
    top: Math.max(0, r.top),
    right: Math.min(window.innerWidth, r.right),
    bottom: Math.min(window.innerHeight, r.bottom),
  };
  for (let p = el.parentElement; p && p !== document.body; p = p.parentElement) {
    if (overflowClips(p)) {
      const c = p.getBoundingClientRect();
      box = {
        left: Math.max(box.left, c.left),
        top: Math.max(box.top, c.top),
        right: Math.min(box.right, c.right),
        bottom: Math.min(box.bottom, c.bottom),
      };
    }
    if (p === layer) break;
  }
  return box.right - box.left >= 2 && box.bottom - box.top >= 2 ? box : null;
}

/** Could the selector stand on `el` at all (ignoring whether it can be seen)? */
function reachable(el: Element): el is HTMLElement {
  if (!(el instanceof HTMLElement) || !el.matches(FOCUSABLE)) return false;
  if (el.matches(':disabled, .puzzle-canvas') || el.tabIndex < 0) return false;
  if (el.closest('[hidden], [inert], .off-page, [aria-hidden="true"]')) return false;
  if (typeof el.checkVisibility === 'function' && !el.checkVisibility({ visibilityProperty: true }))
    return false;
  return true;
}

function candidates(layer: HTMLElement): Array<{ el: HTMLElement; rect: NavRect }> {
  const out: Array<{ el: HTMLElement; rect: NavRect }> = [];
  for (const el of layer.querySelectorAll(FOCUSABLE)) {
    if (!reachable(el)) continue;
    const rect = visibleRect(el, layer);
    if (rect) out.push({ el, rect });
  }
  return out;
}

function rectOf(el: HTMLElement): NavRect {
  const r = el.getBoundingClientRect();
  return { left: r.left, top: r.top, right: r.right, bottom: r.bottom };
}

function shown(el: Element | null): el is HTMLElement {
  return el instanceof HTMLElement && !el.hidden && el.getClientRects().length > 0;
}

/**
 * Where the arrows are working right now, or `null` when they are not the navigator's
 * (the bare play page, where they move the board's cursor; the sketched dropdown, which
 * has its own keys in `gameFeel.ts`).
 */
export function navLayer(): HTMLElement | null {
  if (document.querySelector('.sketch-list')) return null;
  const dimmers = document.querySelectorAll<HTMLElement>('.dimmer');
  const dimmer = dimmers[dimmers.length - 1];
  if (dimmer) return dimmer.querySelector<HTMLElement>('.modal') ?? dimmer;
  const own = [...document.querySelectorAll<HTMLElement>('[data-nav-layer]')].filter(shown);
  if (own.length) return own[own.length - 1];
  const drawer = document.querySelector<HTMLElement>('.help-drawer.open');
  if (drawer) return drawer;
  const app = document.getElementById('app');
  const page = app?.firstElementChild as HTMLElement | null;
  if (!page) return null;
  if (page.classList.contains('game-page')) {
    const end = page.querySelector<HTMLElement>('.endgame');
    const active = document.activeElement;
    // The on-screen keypad, while a key in it has the focus (a pad's trigger took it there,
    // or Tab did): the arrows step along the keys rather than the board's cursor.
    const keys = page.querySelector<HTMLElement>('.keypad');
    if (keys && active && keys.contains(active) && shown(keys)) return keys;
    if (end && !end.hidden && !(active instanceof HTMLCanvasElement)) return end;
    return null;
  }
  return page;
}

/** Whether something lies over the play page's board, so its keys are not the board's. */
export function overlayOpen(): boolean {
  const layer = navLayer();
  return !!layer && layer !== document.getElementById('app')?.firstElementChild;
}

const DEFAULTS = ['[data-nav-default]', '.more-done', '.btn.primary'];

/**
 * Where the selector starts when nothing has the focus: a dialog's own first choice, else
 * the first thing on the page of a paged grid (a card, or a locked card's Unlock), else the
 * first control there is.
 */
function defaultIn(list: Array<{ el: HTMLElement }>): HTMLElement | null {
  for (const sel of DEFAULTS) {
    const hit = list.find((c) => c.el.matches(sel));
    if (hit) return hit.el;
  }
  const inGrid = list.find((c) => [...pagers.keys()].some((vp) => vp.contains(c.el)));
  return inGrid?.el ?? list.find((c) => c.el.matches('.card'))?.el ?? list[0]?.el ?? null;
}

function isScrollable(el: Element): boolean {
  if (!(el instanceof HTMLElement) || el.scrollHeight <= el.clientHeight + 2) return false;
  const oy = getComputedStyle(el).overflowY;
  return oy === 'auto' || oy === 'scroll';
}

/** The scroller Up or Down should move when there is nothing further that way. */
function scrollerFor(
  from: HTMLElement | null,
  layer: HTMLElement,
  dir: NavDir,
): HTMLElement | null {
  const can = (s: HTMLElement) =>
    dir === 'up' ? s.scrollTop > 1 : s.scrollTop + s.clientHeight < s.scrollHeight - 1;
  for (let p = from?.parentElement ?? null; p && layer.contains(p); p = p.parentElement) {
    if (isScrollable(p) && can(p)) return p;
  }
  const all = [layer, ...layer.querySelectorAll<HTMLElement>('*')].filter(
    (s) => isScrollable(s) && can(s),
  );
  all.sort((a, b) => b.clientHeight - a.clientHeight);
  return all[0] ?? null;
}

// ------------------------------------------------------------------ the input mode

const root = () => document.documentElement;
let keyMode = false;

/** The keyboard (or a pad) is what the player is using now: show the selector. */
export function markKeyboardInput(): void {
  if (keyMode) return;
  keyMode = true;
  root().classList.add('nav-keys');
  syncRing(false);
}

function markPointerInput(): void {
  if (!keyMode) return;
  keyMode = false;
  root().classList.remove('nav-keys');
  syncRing(false);
}

// ------------------------------------------------------------------ the selector

let ring: HTMLElement | null = null;
let ringFor: HTMLElement | null = null;
let ringShown = false;
let raf = 0;
let still = 0;
let lastBox = '';

const RING_PAD = 5;

function ensureRing(): HTMLElement {
  if (ring?.isConnected) return ring;
  ring = document.createElement('div');
  ring.className = 'nav-ring';
  ring.setAttribute('aria-hidden', 'true');
  document.body.append(ring);
  return ring;
}

/** Whether the selector belongs on `el`: anything focusable but the board itself. */
function ringable(el: Element | null): el is HTMLElement {
  return (
    el instanceof HTMLElement &&
    el !== document.body &&
    !(el instanceof HTMLCanvasElement) &&
    el.matches(FOCUSABLE) &&
    !el.matches('.drawer-body')
  );
}

/** Put the ring where the focus is (or away). `glide` lets it travel from where it was. */
function syncRing(glide: boolean): void {
  const active = document.activeElement;
  const want = keyMode && ringable(active) ? active : null;
  if (ringFor && ringFor !== want) ringFor.classList.remove('nav-ringed');
  ringFor = want;
  const r = ensureRing();
  if (!want) {
    r.classList.remove('on');
    ringShown = false;
    return;
  }
  want.classList.add('nav-ringed');
  // A ring appearing out of nowhere lands where it is going; only a visible one glides.
  place(glide && ringShown);
  r.classList.add('on');
  ringShown = true;
  still = 0;
  if (!raf) raf = requestAnimationFrame(follow);
}

function place(glide: boolean): void {
  const r = ensureRing();
  const el = ringFor;
  if (!el?.isConnected) {
    r.classList.remove('on');
    ringShown = false;
    return;
  }
  const b = el.getBoundingClientRect();
  if (b.width === 0 && b.height === 0) {
    r.classList.remove('on');
    return;
  }
  const key = `${b.left}|${b.top}|${b.width}|${b.height}`;
  if (key === lastBox && r.classList.contains('on')) return;
  lastBox = key;
  r.classList.toggle('glide', glide && !prefersReducedMotion());
  r.style.transform = `translate(${b.left - RING_PAD}px, ${b.top - RING_PAD}px)`;
  r.style.width = `${b.width + RING_PAD * 2}px`;
  r.style.height = `${b.height + RING_PAD * 2}px`;
  r.classList.add('on');
}

/**
 * Keep the ring on its target while things move under it (a dialog popping in, a page
 * turning, the desk camera), and stop looking once it has sat still for a moment.
 */
function follow(): void {
  raf = 0;
  if (!ringFor || !keyMode) return;
  const before = lastBox;
  // Following a moving target is not a glide: the transition would make the ring lag.
  place(false);
  still = lastBox === before ? still + 1 : 0;
  if (still < 30) raf = requestAnimationFrame(follow);
}

function wake(): void {
  still = 0;
  if (ringFor && keyMode && !raf) raf = requestAnimationFrame(follow);
}

// ------------------------------------------------------------------ moving

const DIRS: Record<string, NavDir> = {
  ArrowUp: 'up',
  ArrowDown: 'down',
  ArrowLeft: 'left',
  ArrowRight: 'right',
};

/** Keys that say "the keyboard is in charge now". */
const KEYS = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Tab',
  'Enter',
  ' ',
  'Escape',
  'PageUp',
  'PageDown',
  'Home',
  'End',
]);

let stepped = false;

function moveTo(el: HTMLElement): void {
  stepped = true;
  el.focus({ preventScroll: true });
  stepped = false;
  // Scrolled only as far as it takes, so a long list does not jump about.
  el.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
  playSound('tick');
  syncRing(true);
}

/**
 * Move the selector one step in `dir`. Returns whether the press was the navigator's (so
 * nothing else should act on it).
 */
export function navMove(dir: NavDir): boolean {
  const layer = navLayer();
  if (!layer) return false;
  const active = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const horizontal = dir === 'left' || dir === 'right';
  if (active && layer.contains(active)) {
    if (isSlider(active)) return false;
    if (horizontal && isTextField(active)) return false;
  }
  const list = candidates(layer);
  const from = active && layer.contains(active) && reachable(active) ? active : null;
  if (!from) {
    // Focus somewhere inside the layer that is not a control — the help's text, which
    // scrolls — keeps the keys for itself.
    if (active && active !== document.body && layer.contains(active) && isScrollable(active))
      return false;
    const d = defaultIn(list);
    if (!d) return false;
    moveTo(d);
    return true;
  }
  const fromRect = rectOf(from);
  const others = list.filter((c) => c.el !== from);
  // Along a paged grid, only the cards on the same row count as "further along"; past the
  // last of them is the edge of the page.
  const paged = horizontal ? pagerFor(from) : null;
  if (paged) {
    const [vp, pager] = paged;
    const inGrid = others.filter((c) => vp.contains(c.el));
    const i = pickInDirection(
      fromRect,
      inGrid.map((c) => c.rect),
      dir,
      { sameLine: true },
    );
    if (i >= 0) {
      moveTo(inGrid[i].el);
      return true;
    }
    const rtl = document.documentElement.dir === 'rtl';
    const forward = dir === 'right' ? !rtl : rtl;
    if (pager.turn(forward ? 1 : -1)) {
      const fresh = candidates(layer).filter((c) => vp.contains(c.el));
      const j = entryPoint(
        fromRect,
        fresh.map((c) => c.rect),
        dir,
        rectOf(vp),
      );
      const land = fresh[j]?.el ?? fresh[0]?.el;
      if (land) moveTo(land);
    }
    return true;
  }
  const rects = others.map((c) => c.rect);
  // Straight on first: the next thing in the same row or column, however far along.
  let i = pickInDirection(fromRect, rects, dir, { sameLine: true });
  // Off the end of the pager's own bar (the achievements, whose badges are only looked
  // at): Left and Right keep turning the pages, as they did before there was a selector.
  if (i < 0 && horizontal && from.closest('.pager')) {
    const bar = [...pagers].find(([vp]) => vp.isConnected && layer.contains(vp));
    const rtl = document.documentElement.dir === 'rtl';
    if (bar) bar[1].turn((dir === 'right') !== rtl ? 1 : -1);
    return true;
  }
  // Then the nearest thing that way at all; sideways only within a cone, so Left from the
  // bottom of the screen does not leap to the top corner.
  if (i < 0) i = pickInDirection(fromRect, rects, dir, horizontal ? { cone: 1 } : {});
  if (i >= 0) {
    moveTo(others[i].el);
    return true;
  }
  if (!horizontal) {
    const s = scrollerFor(from, layer, dir);
    if (s) {
      const step = Math.max(40, s.clientHeight * 0.6) * (dir === 'up' ? -1 : 1);
      s.scrollBy({ top: step, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
      wake();
    }
  }
  return true;
}

// ------------------------------------------------------------------ install

let installed = false;
let adUp = false;
let tabAt = -Infinity;

/** Hover can tick only where there is a real hover: a mouse, not a finger. */
const fineHover = () => {
  try {
    return matchMedia('(hover: hover) and (pointer: fine)').matches;
  } catch {
    return false;
  }
};

export function installNav(): void {
  if (installed || typeof document === 'undefined') return;
  installed = true;
  onAdStateChange((on) => {
    adUp = on;
    // Nothing of ours is drawn over an ad; the next key press brings the selector back.
    if (on) markPointerInput();
  });

  // Capture on the document, so a press the navigator takes never reaches the board, the
  // pager's own arrow keys or a dialog underneath. The sketched dropdown listens earlier
  // still (on the window) and keeps its keys.
  document.addEventListener(
    'keydown',
    (e) => {
      if (adUp) return;
      if (KEYS.has(e.key)) markKeyboardInput();
      if (e.key === 'Tab') tabAt = performance.now();
      const dir = DIRS[e.key];
      if (!dir || e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey || e.shiftKey) return;
      // The first press over the title card skips it, as it does in any game.
      if (document.querySelector('.splash-overlay')) return;
      if (navMove(dir)) {
        e.preventDefault();
        e.stopPropagation();
      }
    },
    true,
  );

  // The way back from a screen that has no dialog to close and no pause to open.
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape' || e.defaultPrevented || adUp) return;
    if (document.querySelector('.dimmer, .sketch-list')) return;
    if (/^#\/?achievements(\/|$)/.test(location.hash)) {
      e.preventDefault();
      location.hash = '#/';
    }
  });

  document.addEventListener('focusin', (e) => {
    // A Tab step ticks like an arrow step; focus moved by the page itself does not.
    if (!stepped && keyMode && performance.now() - tabAt < 250 && ringable(e.target as Element))
      playSound('tick');
    syncRing(keyMode && ringShown);
  });
  document.addEventListener('focusout', () => {
    // Where the focus goes next is only known once it has arrived.
    queueMicrotask(() => {
      if (!document.activeElement || document.activeElement === document.body) syncRing(false);
    });
  });

  // Any real pointer use puts the selector away. A mouse sends a move with no distance
  // when the page under it changes; only one that actually travelled counts.
  let px = -1;
  let py = -1;
  document.addEventListener(
    'pointermove',
    (e) => {
      if (e.pointerType !== 'mouse') return;
      if (px >= 0 && Math.abs(e.clientX - px) + Math.abs(e.clientY - py) > 3) markPointerInput();
      px = e.clientX;
      py = e.clientY;
    },
    { passive: true },
  );
  document.addEventListener('pointerdown', markPointerInput, { capture: true, passive: true });
  window.addEventListener('resize', wake);
  document.addEventListener('scroll', wake, { capture: true, passive: true });

  // ---- interface sounds
  let hovered: Element | null = null;
  document.addEventListener(
    'pointerover',
    (e) => {
      if (e.pointerType !== 'mouse' || !fineHover()) return;
      const el = (e.target as Element | null)?.closest?.(PRESSABLE) ?? null;
      if (el === hovered) return;
      hovered = el;
      if (!el || el.matches(':disabled') || el.closest(OWN_SOUND)) return;
      playSound('tick');
    },
    { passive: true },
  );
  document.addEventListener(
    'click',
    (e) => {
      const el = (e.target as Element | null)?.closest?.(PRESSABLE);
      if (!el || el.matches(':disabled') || el.closest(OWN_SOUND)) return;
      playSound('click');
    },
    true,
  );
  // A sheet laid over the page (every dialog, the pause menu among them) and taken off.
  new MutationObserver((records) => {
    for (const rec of records) {
      for (const n of rec.addedNodes)
        if (n instanceof HTMLElement && n.classList.contains('dimmer')) playSound('swish');
      for (const n of rec.removedNodes)
        if (n instanceof HTMLElement && n.classList.contains('dimmer')) playSound('swishOut');
    }
  }).observe(document.body, { childList: true });
}
