import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { cluePos } from './solver';
import type { TowersState, TowersUI } from './index';

const border = (t: number) => Math.round(t * 1.1);
/** Distance of a clue's centre from the grid edge, as in `redraw`. */
const CLUE_OFFSET = 0.55;

/** A box around the clue number `c` written outside the grid. */
function clueRect(state: TowersState, t: number, c: number): TutorialRect {
  const b = border(t);
  const w = state.w;
  const [cx, cy] = cluePos(w, c);
  const px =
    cx < 0 ? b - t * CLUE_OFFSET : cx >= w ? b + w * t + t * CLUE_OFFSET : b + cx * t + t / 2;
  const py =
    cy < 0 ? b - t * CLUE_OFFSET : cy >= w ? b + w * t + t * CLUE_OFFSET : b + cy * t + t / 2;
  return { x: px - t * 0.45, y: py - t * 0.45, w: t * 0.9, h: t * 0.9 };
}

const cell = (t: number, x: number, y: number) => cellRect(x, y, t, border(t));
const centre = (t: number, x: number, y: number) => cellCentre(x, y, t, border(t));
const height = (state: TowersState, x: number, y: number) => state.grid[y * state.w + x];

export const tutorial: Tutorial<TowersState, TowersUI> = {
  steps: [
    {
      gameId: '4:4/3/2/1/1/2/2/2/4/3/2/1/1/2/2/2,a2_3a2_3_4_1_3_4_1_2a1_2_3',
      text: 'Every row and column holds one tower of each height, 1 to 4. A number round the edge counts the towers you can **see** from there: a taller tower hides every shorter one behind it.',
      highlight: ({ state, tileSize }) => {
        const b = border(tileSize);
        const side = state.w * tileSize + 2 * tileSize;
        return { x: b - tileSize, y: b - tileSize, w: side, h: side };
      },
    },
    {
      text: 'The **1** on the right of the top row means just one tower is visible from that side, so the nearest one has to be the tallest. Click that square and press **4**.',
      textTouch:
        'The **1** on the right of the top row means just one tower is visible from that side, so the nearest one has to be the tallest. Tap that square, then tap **4** on the keypad.',
      target: '[data-key="4"]',
      highlight: ({ state, tileSize }) => [
        clueRect(state, tileSize, 3 * state.w),
        cell(tileSize, 3, 0),
      ],
      pointer: ({ tileSize }) => centre(tileSize, 3, 0),
      press: '4',
      waitFor: ({ state }) => height(state, 3, 0) === 4,
    },
    {
      text: 'You can jot possibilities down instead of answering. **Right-click** the empty square at the left end of the top row and press **1**.',
      textTouch:
        'You can jot possibilities down instead of answering. Tap the empty square at the left end of the top row, latch **✎** on the keypad and tap **1**.',
      target: '[data-key="pencil"]',
      highlight: ({ tileSize }) => cell(tileSize, 0, 0),
      // A plain tap on a touch screen, as `textTouch` says: a long-press selects the square
      // for pencil marks itself, and then the next step's "tap ✎ to stop pencilling" does
      // not stop it — the 1 rubs the note out again and the step never completes.
      pointer: ({ tileSize, touch }) => ({
        ...centre(tileSize, 0, 0),
        ...(touch ? {} : { button: 'right' as const }),
      }),
      press: '1',
      waitFor: ({ state }) => state.pencil[0] !== 0,
    },
    {
      text: 'The **4** on the left of the row says all four towers are visible, so they climb 1-2-3-4 from that end. **Left-click** the square and press **1** to answer it.',
      textTouch:
        'The **4** on the left of the row says all four towers are visible, so they climb 1-2-3-4 from that end. The square is still chosen, so tap **✎** to stop pencilling and then **1** to answer it.',
      target: '[data-key="1"]',
      highlight: ({ state, tileSize }) => [
        clueRect(state, tileSize, 2 * state.w),
        cell(tileSize, 0, 0),
      ],
      // On a touch screen the square is still chosen from the last step, and tapping it
      // again — what a pointer on it asks for — would deselect it; point at it only when
      // it is not chosen any more.
      pointer: ({ tileSize, ui, touch }) =>
        touch && ui.hshow && ui.hx === 0 && ui.hy === 0 ? null : centre(tileSize, 0, 0),
      press: '1',
      waitFor: ({ state }) => height(state, 0, 0) === 1,
    },
    {
      text: 'One square left, and the **1** beside its row again puts the tallest tower nearest. Click it and press **4**.',
      textTouch:
        'One square left, and the **1** beside its row again puts the tallest tower nearest. Tap it, then tap **4** on the keypad.',
      highlight: ({ state, tileSize }) => [
        clueRect(state, tileSize, 2 * state.w + 3),
        cell(tileSize, 0, 3),
      ],
      pointer: ({ tileSize }) => centre(tileSize, 0, 3),
      press: '4',
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! **Backspace** empties a square you got wrong, and **Solve**, in the pause menu, finishes a puzzle that has beaten you.',
      textTouch:
        'Solved! **⌫** on the keypad empties a square you got wrong. In the pause menu, **Marks** pencils every possibility in and **Solve** finishes a puzzle that has beaten you.',
      target: '[data-cmd="solve"]',
    },
  ],
};
