/**
 * Deductive Singles solver.
 *
 * Every step is a forced deduction, so whenever the solver fills the whole grid the
 * puzzle has exactly that one solution. Two tiers of reasoning match the difficulties:
 *
 *  - **Easy**: a black cell makes its four neighbours white; a circled cell makes every
 *    other copy of its number in its row and column black; two equal numbers with one
 *    cell between them force that cell white (one of the pair is black); two equal
 *    numbers side by side make every other copy in their line black; a white cell whose
 *    neighbours are all black but one needs that one white; and the three corner
 *    patterns (four, three or two equal numbers in a 2×2 corner).
 *  - **Tricky** adds the offset-pair argument (two copies of A in a line, each with a B
 *    beside it, offset by one) and the connectivity rule: a cell whose blackening would
 *    cut the white region in two must be white.
 *
 * `Solver.solve(diff)` runs the tiers up to `diff` to a fixed point and reports whether
 * the grid is finished. `countSolutions` is a search with propagation for puzzles the
 * deductions alone cannot finish, and for independent uniqueness checks in tests.
 */
import { F_BLACK, F_CIRCLE, checkGrid } from './board';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Tricky'];
/** Difficulty letters used in game IDs, indexed by difficulty. */
export const DIFF_CHARS = 'ek';

export const OP_BLACK = 0;
export const OP_CIRCLE = 1;

/** Solver result codes. */
export const IMPOSSIBLE = -1;
export const UNFINISHED = 0;
export const SOLVED = 1;

export class Solver {
  readonly n: number;
  flags: Uint8Array;
  /** Set when a deduction contradicts an earlier one. */
  impossible = false;
  /** Pending operations, encoded `cell * 2 + op`, applied in order by `doOps`. */
  private ops: number[] = [];
  private readonly queue: Int32Array;
  private readonly seen: Uint8Array;

  constructor(
    readonly nums: Uint8Array,
    readonly w: number,
    readonly h: number,
    flags?: Uint8Array,
  ) {
    this.n = w * h;
    this.flags = flags ? flags.slice() : new Uint8Array(this.n);
    this.queue = new Int32Array(this.n);
    this.seen = new Uint8Array(this.n);
  }

  clone(): Solver {
    const s = new Solver(this.nums, this.w, this.h, this.flags);
    s.impossible = this.impossible;
    s.ops = this.ops.slice();
    return s;
  }

  addOp(i: number, op: number): void {
    this.ops.push(i * 2 + op);
  }

  /** Orthogonal neighbour `d` (0 up, 1 right, 2 down, 3 left) of cell `i`, or -1. */
  neighbour(i: number, d: number): number {
    const { w, h } = this;
    const x = i % w;
    const y = (i - x) / w;
    if (d === 0) return y > 0 ? i - w : -1;
    if (d === 1) return x < w - 1 ? i + 1 : -1;
    if (d === 2) return y < h - 1 ? i + w : -1;
    return x > 0 ? i - 1 : -1;
  }

  get pending(): number {
    return this.ops.length;
  }

  /** Cell `j` is next to a black cell, so it must be white. */
  private wantCircle(j: number): void {
    if (this.flags[j] & F_BLACK) {
      this.impossible = true;
      return;
    }
    if (!(this.flags[j] & F_CIRCLE)) this.addOp(j, OP_CIRCLE);
  }

  /** Cell `j` shares a line with a circled `num`, so if it holds `num` it must be black. */
  private wantBlack(j: number, num: number): void {
    if (this.nums[j] !== num) return;
    if (this.flags[j] & F_CIRCLE) {
      this.impossible = true;
      return;
    }
    if (!(this.flags[j] & F_BLACK)) this.addOp(j, OP_BLACK);
  }

  /**
   * Apply every pending operation, including the ones they trigger: blackening a cell
   * circles its neighbours, circling a cell blackens its number elsewhere in its row and
   * column. Returns how many cells changed.
   */
  doOps(): number {
    const { flags, nums, w, h, ops } = this;
    let next = 0;
    let done = 0;
    while (next < ops.length && !this.impossible) {
      const code = ops[next++];
      const i = code >> 1;
      if ((code & 1) === OP_BLACK) {
        if (flags[i] & F_CIRCLE) {
          this.impossible = true;
          break;
        }
        if (flags[i] & F_BLACK) continue;
        flags[i] = F_BLACK;
        done++;
        const x = i % w;
        const y = (i - x) / w;
        if (x > 0) this.wantCircle(i - 1);
        if (x < w - 1) this.wantCircle(i + 1);
        if (y > 0) this.wantCircle(i - w);
        if (y < h - 1) this.wantCircle(i + w);
      } else {
        if (flags[i] & F_BLACK) {
          this.impossible = true;
          break;
        }
        if (flags[i] & F_CIRCLE) continue;
        flags[i] = F_CIRCLE;
        done++;
        const x = i % w;
        const y = (i - x) / w;
        const num = nums[i];
        for (let xx = 0; xx < w; xx++) if (xx !== x) this.wantBlack(y * w + xx, num);
        for (let yy = 0; yy < h; yy++) if (yy !== y) this.wantBlack(yy * w + x, num);
      }
    }
    ops.length = 0;
    return done;
  }

  // ------------------------------------------------------------ Easy deductions

  /** `A ? A` in a line: the middle cell is next to whichever A is black, so it is white. */
  singleSep(): number {
    const { nums, flags, w, h } = this;
    const before = this.ops.length;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (x < w - 2 && nums[i] === nums[i + 2] && !(flags[i + 1] & F_CIRCLE))
          this.addOp(i + 1, OP_CIRCLE);
        if (y < h - 2 && nums[i] === nums[i + 2 * w] && !(flags[i + w] & F_CIRCLE))
          this.addOp(i + w, OP_CIRCLE);
      }
    }
    return this.ops.length - before;
  }

  /** `A A` in a line: one of them is white, so every other A in that line is black. */
  doubles(): number {
    const { nums, flags, w, h } = this;
    const before = this.ops.length;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (flags[i] & F_BLACK) continue;
        const num = nums[i];
        if (x < w - 1 && !(flags[i + 1] & F_BLACK) && nums[i + 1] === num) {
          for (let xx = 0; xx < w; xx++) {
            if (xx === x || xx === x + 1) continue;
            const j = y * w + xx;
            if (nums[j] === num && !(flags[j] & F_BLACK)) this.addOp(j, OP_BLACK);
          }
        }
        if (y < h - 1 && !(flags[i + w] & F_BLACK) && nums[i + w] === num) {
          for (let yy = 0; yy < h; yy++) {
            if (yy === y || yy === y + 1) continue;
            const j = yy * w + x;
            if (nums[j] === num && !(flags[j] & F_BLACK)) this.addOp(j, OP_BLACK);
          }
        }
      }
    }
    return this.ops.length - before;
  }

  /**
   * A non-black cell with a single non-black neighbour and no circled one: that
   * neighbour is white either way (it is next to this cell if this cell is black, and
   * this cell's only way out if it is white). No way out at all is a contradiction.
   */
  allBlackButOne(): number {
    const { flags, w, h } = this;
    const before = this.ops.length;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (flags[i] & F_BLACK) continue;
        let free = -1;
        let escape = false;
        for (let d = 0; d < 4 && !escape; d++) {
          const j = this.neighbour(i, d);
          if (j < 0) continue;
          if (flags[j] & F_CIRCLE) escape = true;
          else if (!(flags[j] & F_BLACK)) {
            if (free !== -1) escape = true;
            else free = j;
          }
        }
        if (escape) continue;
        if (free === -1) {
          this.impossible = true;
          return 0;
        }
        this.addOp(free, OP_CIRCLE);
      }
    }
    return this.ops.length - before;
  }

  /** The 2×2 corner patterns: cells are (corner, along one edge, along the other, inner). */
  private corner(x: number, y: number, dx: number, dy: number): void {
    const { nums, w } = this;
    const c = y * w + x;
    const s1 = y * w + (x + dx);
    const s2 = (y + dy) * w + x;
    const d = (y + dy) * w + (x + dx);
    const nc = nums[c];
    const n1 = nums[s1];
    const n2 = nums[s2];
    const nd = nums[d];
    if (nc === n1 && nc === n2 && nc === nd) {
      // Four alike: a white corner would be walled in, so it and the inner cell are black.
      this.addOp(c, OP_BLACK);
      this.addOp(d, OP_BLACK);
    } else if (nc === n1 && nc === n2) {
      this.addOp(c, OP_BLACK);
    } else if (n1 === n2 && n1 === nd) {
      this.addOp(d, OP_BLACK);
    } else if (nc === n1 || n1 === nd) {
      // A pair through s1 puts a black next to the corner or s2; either way s2 is white.
      this.addOp(s2, OP_CIRCLE);
    } else if (nc === n2 || n2 === nd) {
      this.addOp(s1, OP_CIRCLE);
    }
  }

  corners(): number {
    const { w, h } = this;
    const before = this.ops.length;
    this.corner(0, 0, 1, 1);
    this.corner(w - 1, 0, -1, 1);
    this.corner(w - 1, h - 1, -1, -1);
    this.corner(0, h - 1, 1, -1);
    return this.ops.length - before;
  }

  // ---------------------------------------------------------- Tricky deductions

  /**
   * Two copies of A in a line at p1 and p2, with a B next to p1 (off the line) and a B
   * diagonally next to p2 on the same side: p1's A and B cannot both be black, so either
   * p2's A or p2's B is black, and both share the two cells between them, which are
   * therefore white.
   */
  private offsetPairAt(x1: number, y1: number, x2: number, y2: number): void {
    const { nums, w, h } = this;
    const ox = x1 === x2 ? 1 : 0;
    const oy = 1 - ox;
    const ax = x1 + ox;
    const ay = y1 + oy;
    const an = nums[ay * w + ax];
    for (let d = 0; d < 2; d++) {
      const sign = d === 0 ? 1 : -1;
      const bx = x2 + ox + oy * sign;
      const by = y2 + oy + ox * sign;
      if (bx < 0 || by < 0 || bx >= w || by >= h) continue;
      // The degenerate case where p2's B is p1's B itself proves nothing.
      if (bx === ax && by === ay) continue;
      if (nums[by * w + bx] !== an) continue;
      this.addOp(y2 * w + (x2 + (bx - x2)), OP_CIRCLE);
      this.addOp((y2 + (by - y2)) * w + x2, OP_CIRCLE);
    }
  }

  offsetPair(): number {
    const { nums, w, h } = this;
    const before = this.ops.length;
    for (let x = 0; x < w - 1; x++) {
      for (let y = 0; y < h; y++) {
        for (let yy = y + 1; yy < h; yy++) {
          if (nums[y * w + x] !== nums[yy * w + x]) continue;
          this.offsetPairAt(x, y, x, yy);
          this.offsetPairAt(x, yy, x, y);
        }
      }
    }
    for (let y = 0; y < h - 1; y++) {
      for (let x = 0; x < w; x++) {
        for (let xx = x + 1; xx < w; xx++) {
          if (nums[y * w + x] !== nums[y * w + xx]) continue;
          this.offsetPairAt(x, y, xx, y);
          this.offsetPairAt(xx, y, x, y);
        }
      }
    }
    return this.ops.length - before;
  }

  /** Whether every non-black cell is reachable from every other (false if none exist). */
  whitesConnected(): boolean {
    const { flags, w, h, n, queue, seen } = this;
    let start = -1;
    let nwhite = 0;
    for (let i = 0; i < n; i++) {
      if (!(flags[i] & F_BLACK)) {
        nwhite++;
        if (start < 0) start = i;
      }
    }
    if (start < 0) return false;
    seen.fill(0);
    seen[start] = 1;
    queue[0] = start;
    let head = 0;
    let tail = 1;
    while (head < tail) {
      const i = queue[head++];
      const x = i % w;
      const y = (i - x) / w;
      const visit = (j: number) => {
        if (!seen[j] && !(flags[j] & F_BLACK)) {
          seen[j] = 1;
          queue[tail++] = j;
        }
      };
      if (x > 0) visit(i - 1);
      if (x < w - 1) visit(i + 1);
      if (y > 0) visit(i - w);
      if (y < h - 1) visit(i + w);
    }
    return tail === nwhite;
  }

  /**
   * Articulation points of the graph of non-black cells: blackening any of them would
   * split the white region. Iterative Tarjan so deep grids cannot overflow the stack.
   */
  articulationPoints(): Uint8Array {
    const { flags, n } = this;
    const disc = new Int32Array(n).fill(-1);
    const low = new Int32Array(n);
    const parent = new Int32Array(n).fill(-1);
    const childCount = new Int32Array(n);
    const nextDir = new Uint8Array(n);
    const cut = new Uint8Array(n);
    const stack = this.queue;
    let time = 0;
    for (let root = 0; root < n; root++) {
      if (flags[root] & F_BLACK || disc[root] >= 0) continue;
      let sp = 0;
      stack[sp++] = root;
      disc[root] = low[root] = time++;
      while (sp > 0) {
        const i = stack[sp - 1];
        if (nextDir[i] < 4) {
          const j = this.neighbour(i, nextDir[i]++);
          if (j < 0 || flags[j] & F_BLACK) continue;
          if (disc[j] < 0) {
            parent[j] = i;
            childCount[i]++;
            disc[j] = low[j] = time++;
            stack[sp++] = j;
          } else if (j !== parent[i] && disc[j] < low[i]) {
            low[i] = disc[j];
          }
        } else {
          sp--;
          const p = parent[i];
          if (p >= 0) {
            if (low[i] < low[p]) low[p] = low[i];
            if (low[i] >= disc[p] && parent[p] >= 0) cut[p] = 1;
          }
        }
      }
      if (childCount[root] > 1) cut[root] = 1;
    }
    return cut;
  }

  /**
   * Cells diagonally next to a black cell whose blackening would disconnect the white
   * region must be white. A region that is already disconnected is a contradiction.
   */
  removeSplits(): number {
    const { flags, w, h, n } = this;
    const before = this.ops.length;
    if (!this.whitesConnected()) {
      this.impossible = true;
      return 0;
    }
    const cut = this.articulationPoints();
    const check = (j: number) => {
      if (flags[j] === 0 && cut[j]) this.addOp(j, OP_CIRCLE);
    };
    for (let i = 0; i < n; i++) {
      if (!(flags[i] & F_BLACK)) continue;
      const x = i % w;
      const y = (i - x) / w;
      if (x > 0 && y > 0) check(i - w - 1);
      if (x < w - 1 && y > 0) check(i - w + 1);
      if (x > 0 && y < h - 1) check(i + w - 1);
      if (x < w - 1 && y < h - 1) check(i + w + 1);
    }
    return this.ops.length - before;
  }

  /**
   * Not a rule of the game: a number that is unique in both its row and its column is
   * assumed white. True of every generated puzzle (black cells always duplicate a white
   * number), so harder puzzles are checked not to collapse when this shortcut is used.
   */
  sneaky(): number {
    const { nums, w, h, n } = this;
    const before = this.ops.length;
    const dup = new Uint8Array(n);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        for (let xx = x + 1; xx < w; xx++) {
          if (nums[i] === nums[y * w + xx]) dup[i] = dup[y * w + xx] = 1;
        }
        for (let yy = y + 1; yy < h; yy++) {
          if (nums[i] === nums[yy * w + x]) dup[i] = dup[yy * w + x] = 1;
        }
      }
    }
    for (let i = 0; i < n; i++) if (!dup[i]) this.addOp(i, OP_CIRCLE);
    return this.ops.length - before;
  }

  // ----------------------------------------------------------------- driver

  /** Every cell decided and the result obeys the rules. */
  isComplete(): boolean {
    for (let i = 0; i < this.n; i++) if (this.flags[i] === 0) return false;
    return checkGrid(this.nums, this.flags, this.w, this.h).complete;
  }

  /**
   * Deduce as far as difficulty `diff` allows. Returns `SOLVED`, `UNFINISHED` or
   * `IMPOSSIBLE`. With `sneaky` the unique-number shortcut is applied first.
   */
  solve(diff: number, sneaky = false): number {
    if (sneaky) this.sneaky();
    // These depend only on the numbers, so once is enough.
    this.singleSep();
    this.doubles();
    this.corners();
    if (diff >= DIFF_TRICKY) this.offsetPair();
    for (;;) {
      if (this.ops.length) this.doOps();
      if (this.impossible) break;
      if (this.allBlackButOne() > 0) continue;
      if (this.impossible) break;
      if (diff >= DIFF_TRICKY) {
        if (this.removeSplits() > 0) continue;
        if (this.impossible) break;
      }
      break;
    }
    if (this.impossible) return IMPOSSIBLE;
    return this.isComplete() ? SOLVED : UNFINISHED;
  }
}

/** Solve from scratch at a difficulty; the flags hold the solution when `result` is SOLVED. */
export function solveAt(nums: Uint8Array, w: number, h: number, diff: number, sneaky = false) {
  const solver = new Solver(nums, w, h);
  const result = solver.solve(diff, sneaky);
  return { result, flags: solver.flags };
}

/**
 * Count solutions (up to `cap`) by trying both colours for an undecided cell whenever the
 * Tricky deductions run dry. Returns the first solution found, if any.
 */
export function countSolutions(
  nums: Uint8Array,
  w: number,
  h: number,
  cap = 2,
  start?: Uint8Array,
): { count: number; solution: Uint8Array | null } {
  let count = 0;
  let solution: Uint8Array | null = null;
  const search = (s: Solver) => {
    const r = s.solve(DIFF_TRICKY);
    if (r === IMPOSSIBLE) return;
    if (r === SOLVED) {
      count++;
      solution ??= s.flags.slice();
      return;
    }
    // Guess in the cell with the most copies of its number in its lines: it is the most
    // constrained, so both branches propagate far.
    let best = -1;
    let bestScore = -1;
    for (let i = 0; i < s.n; i++) {
      if (s.flags[i] !== 0) continue;
      const x = i % s.w;
      const y = (i - x) / s.w;
      let score = 0;
      for (let xx = 0; xx < s.w; xx++) if (nums[y * s.w + xx] === nums[i]) score++;
      for (let yy = 0; yy < s.h; yy++) if (nums[yy * s.w + x] === nums[i]) score++;
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    if (best < 0) return; // fully decided but invalid
    const a = s.clone();
    a.addOp(best, OP_BLACK);
    search(a);
    if (count >= cap) return;
    const b = s.clone();
    b.addOp(best, OP_CIRCLE);
    search(b);
  };
  search(new Solver(nums, w, h, start));
  return { count, solution };
}

/** Any solution of the puzzle (deduction first, search if needed), or null. */
export function findSolution(nums: Uint8Array, w: number, h: number): Uint8Array | null {
  const direct = solveAt(nums, w, h, DIFF_TRICKY);
  if (direct.result === SOLVED) return direct.flags;
  if (direct.result === IMPOSSIBLE) return null;
  return countSolutions(nums, w, h, 1).solution;
}
