/**
 * Latin-square solver and generator.
 *
 * The solver keeps a "cube" of candidates — for every square and digit, whether that
 * digit can still go there — and repeats a fixed menu of deductions until nothing
 * changes any more:
 *  - simple: a digit with a single place left in a row or column, or a square with a
 *    single candidate;
 *  - set elimination: k squares of a row or column whose candidates are only k digits
 *    between them must hold exactly those digits;
 *  - positional set elimination: the same reasoning on the rows × columns of one digit;
 *  - forcing chains through squares with two candidates;
 *  - recursion: guess in the most constrained square and count the solutions.
 *
 * Which difficulty grade each of those earns is chosen by the caller through `levels`,
 * and a game can slot its own deductions (Towers: the visibility clues) in front of the
 * generic ones at every grade. The grid is solved in place and the result is the
 * hardest grade that was needed, or one of the three failure codes below.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';

export const LATIN_IMPOSSIBLE = 10;
export const LATIN_AMBIGUOUS = 11;
export const LATIN_UNFINISHED = 12;

/** A game-specific deduction: +1 progress, 0 nothing to do, -1 contradiction. */
export type UserSolver<C> = (solver: LatinSolver, ctx: C) => number;

/** The grade at which each generic deduction becomes available. */
export interface LatinLevels {
  simple: number;
  set0: number;
  set1: number;
  forcing: number;
  recursive: number;
}

function popcount(v: number): number {
  v = v - ((v >>> 1) & 0x55555555);
  v = (v & 0x33333333) + ((v >>> 2) & 0x33333333);
  return (((v + (v >>> 4)) & 0x0f0f0f0f) * 0x01010101) >>> 24;
}

export class LatinSolver {
  readonly o: number;
  /** grid[y*o + x], written in place as digits are placed. */
  readonly grid: Uint8Array;
  /** cube[(y*o + x)*o + n-1]: digit n still possible in square (x, y). */
  readonly cube: Uint8Array;
  /** row[y*o + n-1] / col[x*o + n-1]: digit n already placed in that row / column. */
  readonly row: Uint8Array;
  readonly col: Uint8Array;
  /** A given digit clashed with another one while the cube was being set up. */
  readonly contradiction: boolean;
  private readonly idx: Int32Array;
  private readonly matrix: Int32Array;

  constructor(grid: Uint8Array, o: number) {
    this.o = o;
    this.grid = grid;
    this.cube = new Uint8Array(o * o * o).fill(1);
    this.row = new Uint8Array(o * o);
    this.col = new Uint8Array(o * o);
    this.idx = new Int32Array(o);
    this.matrix = new Int32Array(o * o);
    let bad = false;
    for (let xy = 0; xy < o * o; xy++) {
      const n = grid[xy];
      if (!n) continue;
      if (this.cube[xy * o + n - 1]) this.place(xy % o, Math.floor(xy / o), n);
      else bad = true;
    }
    this.contradiction = bad;
  }

  /** Cube index of digit n in square (x, y). */
  pos(x: number, y: number, n: number): number {
    return (y * this.o + x) * this.o + n - 1;
  }

  /** Commit digit n to square (x, y) and rule it out along its row and column. */
  place(x: number, y: number, n: number): void {
    const { o, cube } = this;
    const xy = y * o + x;
    for (let i = 1; i <= o; i++) if (i !== n) cube[xy * o + i - 1] = 0;
    for (let i = 0; i < o; i++) if (i !== y) cube[(i * o + x) * o + n - 1] = 0;
    for (let i = 0; i < o; i++) if (i !== x) cube[(y * o + i) * o + n - 1] = 0;
    this.grid[xy] = n;
    this.row[y * o + n - 1] = 1;
    this.col[x * o + n - 1] = 1;
  }

  /** Candidates of a square as a bitmask with bit n set for digit n. */
  candidates(xy: number): number {
    const { o, cube } = this;
    let m = 0;
    for (let n = 1; n <= o; n++) if (cube[xy * o + n - 1]) m |= 1 << n;
    return m;
  }

  /**
   * If exactly one of `count` cube entries is still possible, place it. Returns +1 for
   * progress, 0 for nothing to do and -1 when none of them is possible.
   */
  elim(indices: ArrayLike<number>, count: number): number {
    const { o, cube } = this;
    let m = 0;
    let fpos = -1;
    for (let i = 0; i < count; i++) {
      if (cube[indices[i]]) {
        fpos = indices[i];
        m++;
      }
    }
    if (m === 1) {
      const n = 1 + (fpos % o);
      const xy = Math.floor(fpos / o);
      if (this.grid[xy]) return 0;
      this.place(xy % o, Math.floor(xy / o), n);
      return 1;
    }
    return m === 0 ? -1 : 0;
  }

  /** Positional elimination in rows and columns, then numeric elimination in squares. */
  simple(): number {
    const { o, idx } = this;
    for (let y = 0; y < o; y++) {
      for (let n = 1; n <= o; n++) {
        if (this.row[y * o + n - 1]) continue;
        for (let x = 0; x < o; x++) idx[x] = this.pos(x, y, n);
        const ret = this.elim(idx, o);
        if (ret) return ret;
      }
    }
    for (let x = 0; x < o; x++) {
      for (let n = 1; n <= o; n++) {
        if (this.col[x * o + n - 1]) continue;
        for (let y = 0; y < o; y++) idx[y] = this.pos(x, y, n);
        const ret = this.elim(idx, o);
        if (ret) return ret;
      }
    }
    for (let xy = 0; xy < o * o; xy++) {
      if (this.grid[xy]) continue;
      for (let n = 1; n <= o; n++) idx[n - 1] = xy * o + n - 1;
      const ret = this.elim(idx, o);
      if (ret) return ret;
    }
    return 0;
  }

  /**
   * Set elimination on an o × o matrix of cube indices (`matrix[i*o + j]`): rows are the
   * things being placed, columns their options. Rows that are already decided are
   * dropped together with their column; then any set of k columns that only k rows can
   * use must belong to exactly those rows, so those rows lose every other option.
   */
  setElim(matrix: Int32Array): number {
    const { o, cube } = this;
    const rowKeep = new Uint8Array(o).fill(1);
    const colKeep = new Uint8Array(o).fill(1);
    for (let i = 0; i < o; i++) {
      let count = 0;
      let first = -1;
      for (let j = 0; j < o; j++) {
        if (cube[matrix[i * o + j]]) {
          first = j;
          count++;
        }
      }
      if (count === 0) return -1;
      if (count === 1) {
        rowKeep[i] = 0;
        colKeep[first] = 0;
      }
    }
    const rows: number[] = [];
    const cols: number[] = [];
    for (let i = 0; i < o; i++) {
      if (rowKeep[i]) rows.push(i);
      if (colKeep[i]) cols.push(i);
    }
    const n = rows.length;
    if (n !== cols.length || n < 4) return 0;
    const masks = new Int32Array(n);
    for (let i = 0; i < n; i++) {
      let m = 0;
      for (let j = 0; j < n; j++) if (cube[matrix[rows[i] * o + cols[j]]]) m |= 1 << j;
      masks[i] = m;
    }
    const full = (1 << n) - 1;
    for (let set = 1; set < full; set++) {
      const size = popcount(set);
      if (size <= 1 || size >= n - 1) continue;
      let outside = 0;
      for (let i = 0; i < n; i++) if ((masks[i] & set) === 0) outside++;
      if (outside > n - size) return -1;
      if (outside < n - size) continue;
      let progress = 0;
      for (let i = 0; i < n; i++) {
        if ((masks[i] & set) === 0) continue;
        const kill = masks[i] & ~set;
        for (let j = 0; j < n; j++) {
          if (kill & (1 << j)) {
            cube[matrix[rows[i] * o + cols[j]]] = 0;
            progress = 1;
          }
        }
      }
      if (progress) return 1;
    }
    return 0;
  }

  /**
   * Set elimination within every row and column (`extreme` false), or on the positions
   * of each single digit across rows and columns (`extreme` true).
   */
  set(extreme: boolean): number {
    const { o, matrix } = this;
    if (!extreme) {
      for (let y = 0; y < o; y++) {
        for (let x = 0; x < o; x++)
          for (let n = 1; n <= o; n++) matrix[x * o + n - 1] = this.pos(x, y, n);
        const ret = this.setElim(matrix);
        if (ret) return ret;
      }
      for (let x = 0; x < o; x++) {
        for (let y = 0; y < o; y++)
          for (let n = 1; n <= o; n++) matrix[y * o + n - 1] = this.pos(x, y, n);
        const ret = this.setElim(matrix);
        if (ret) return ret;
      }
      return 0;
    }
    for (let n = 1; n <= o; n++) {
      for (let y = 0; y < o; y++) for (let x = 0; x < o; x++) matrix[y * o + x] = this.pos(x, y, n);
      const ret = this.setElim(matrix);
      if (ret) return ret;
    }
    return 0;
  }

  /**
   * Forcing chains: a path of two-candidate squares, each adjacent pair (same row or
   * column) sharing a digit, such that ruling out digit N at the start forces N at the
   * end. A third square in line with both ends cannot then be N.
   */
  forcing(): number {
    const { o, cube } = this;
    const area = o * o;
    const number = new Int32Array(area);
    const queue = new Int32Array(area);
    for (let start = 0; start < area; start++) {
      const cand = this.candidates(start);
      if (popcount(cand) !== 2) continue;
      const sx = start % o;
      const sy = Math.floor(start / o);
      for (let n = 1; n <= o; n++) {
        if (!(cand & (1 << n))) continue;
        number.fill(o + 1);
        let head = 0;
        let tail = 0;
        queue[tail++] = start;
        number[start] = 31 - Math.clz32(cand & ~(1 << n));
        while (head < tail) {
          const xy = queue[head++];
          const currn = number[xy];
          const x = xy % o;
          const y = Math.floor(xy / o);
          for (let k = 0; k < 2 * o; k++) {
            const nb = k < o ? k * o + x : y * o + (k - o);
            if (nb === xy || number[nb] <= o) continue;
            if (!cube[nb * o + currn - 1]) continue;
            const c2 = this.candidates(nb);
            if (popcount(c2) === 2) {
              queue[tail++] = nb;
              number[nb] = 31 - Math.clz32(c2 & ~(1 << currn));
            }
            if (currn === n && (nb % o === sx || Math.floor(nb / o) === sy)) {
              cube[nb * o + n - 1] = 0;
              return 1;
            }
          }
        }
      }
    }
    return 0;
  }
}

function top<C>(
  s: LatinSolver,
  maxdiff: number,
  levels: LatinLevels,
  userSolvers: ReadonlyArray<UserSolver<C> | null>,
  ctx: C,
): number {
  if (s.contradiction) return LATIN_IMPOSSIBLE;
  let diff = levels.simple;
  outer: for (;;) {
    for (let i = 0; i <= maxdiff; i++) {
      const user = userSolvers[i];
      let ret = user ? user(s, ctx) : 0;
      if (ret === 0 && i === levels.simple) ret = s.simple();
      if (ret === 0 && i === levels.set0) ret = s.set(false);
      if (ret === 0 && i === levels.set1) ret = s.set(true);
      if (ret === 0 && i === levels.forcing) ret = s.forcing();
      if (ret < 0) return LATIN_IMPOSSIBLE;
      if (ret > 0) {
        diff = Math.max(diff, i);
        continue outer;
      }
    }
    break;
  }
  if (maxdiff >= levels.recursive) {
    const nsol = recurse(s, levels, userSolvers, ctx);
    if (nsol < 0) return LATIN_IMPOSSIBLE;
    if (nsol === 1) return levels.recursive;
    if (nsol > 1) return LATIN_AMBIGUOUS;
    return diff;
  }
  for (let xy = 0; xy < s.o * s.o; xy++) if (!s.grid[xy]) return LATIN_UNFINISHED;
  return diff;
}

/**
 * Guess every candidate of the emptiest square and solve on from each guess.
 * Returns -1 for no solution, 0 when the grid was already complete, 1 for a unique
 * solution (left in the grid) and 2 for several.
 */
function recurse<C>(
  s: LatinSolver,
  levels: LatinLevels,
  userSolvers: ReadonlyArray<UserSolver<C> | null>,
  ctx: C,
): number {
  const { o, grid } = s;
  let best = -1;
  let bestCount = o + 1;
  for (let xy = 0; xy < o * o; xy++) {
    if (grid[xy]) continue;
    const count = popcount(s.candidates(xy));
    if (count < bestCount) {
      bestCount = count;
      best = xy;
    }
  }
  if (best === -1) return 0;
  if (bestCount === 0) return -1;
  const cand = s.candidates(best);
  const start = grid.slice();
  let diff = LATIN_IMPOSSIBLE;
  for (let n = 1; n <= o; n++) {
    if (!(cand & (1 << n))) continue;
    const out = start.slice();
    out[best] = n;
    const ret = top(new LatinSolver(out, o), levels.recursive, levels, userSolvers, ctx);
    if (diff === LATIN_IMPOSSIBLE && ret !== LATIN_IMPOSSIBLE) grid.set(out);
    if (ret === LATIN_AMBIGUOUS) diff = LATIN_AMBIGUOUS;
    else if (ret !== LATIN_IMPOSSIBLE)
      diff = diff === LATIN_IMPOSSIBLE ? levels.recursive : LATIN_AMBIGUOUS;
    if (diff === LATIN_AMBIGUOUS) break;
  }
  return diff === LATIN_IMPOSSIBLE ? -1 : diff === LATIN_AMBIGUOUS ? 2 : 1;
}

/**
 * Solve `grid` (o × o, digits 1..o, 0 for empty) in place using deductions up to
 * `maxdiff`. Returns the hardest grade used, LATIN_UNFINISHED when the allowed
 * deductions ran out, LATIN_IMPOSSIBLE or LATIN_AMBIGUOUS.
 */
export function latinSolve<C>(
  grid: Uint8Array,
  o: number,
  maxdiff: number,
  levels: LatinLevels,
  userSolvers: ReadonlyArray<UserSolver<C> | null>,
  ctx: C,
): number {
  return top(new LatinSolver(grid, o), maxdiff, levels, userSolvers, ctx);
}

/** Whether every row and column of `grid` holds each of 1..o exactly once. */
export function isLatinSquare(grid: ArrayLike<number>, o: number): boolean {
  const full = (1 << (o + 1)) - 2;
  for (let i = 0; i < o; i++) {
    let rowMask = 0;
    let colMask = 0;
    for (let j = 0; j < o; j++) {
      rowMask |= 1 << grid[i * o + j];
      colMask |= 1 << grid[j * o + i];
    }
    if (rowMask !== full || colMask !== full) return false;
  }
  return true;
}

/**
 * A uniformly-ish random latin square. Any latin rectangle with fewer than o rows can be
 * extended by one more row (Hall's theorem), so the rows are built one at a time by
 * finding a perfect matching between columns and the digits still unused in them, with
 * the column and digit orders shuffled so that the matching comes out random. Rows are
 * filled in random order too, so no direction is favoured.
 */
export function latinGenerate(o: number, rng: Random): Uint8Array {
  const sq = new Uint8Array(o * o);
  const seq = (n: number) => Array.from({ length: n }, (_, i) => i);
  const rows = rng.shuffle(seq(o));
  const cols = seq(o);
  const nums = seq(o);
  const usedInCol = new Int32Array(o);
  const matchCol = new Int32Array(o);
  const matchNum = new Int32Array(o);
  const seen = new Uint8Array(o);
  const augment = (j: number): boolean => {
    for (let k = 0; k < o; k++) {
      if (seen[k] || usedInCol[cols[j]] & (1 << (nums[k] + 1))) continue;
      seen[k] = 1;
      if (matchNum[k] < 0 || augment(matchNum[k])) {
        matchCol[j] = k;
        matchNum[k] = j;
        return true;
      }
    }
    return false;
  };
  for (const r of rows) {
    rng.shuffle(cols);
    rng.shuffle(nums);
    matchCol.fill(-1);
    matchNum.fill(-1);
    for (let j = 0; j < o; j++) {
      seen.fill(0);
      if (!augment(j)) throw new Error(tx`latin rectangle could not be extended`);
    }
    for (let j = 0; j < o; j++) {
      const d = nums[matchCol[j]] + 1;
      sq[r * o + cols[j]] = d;
      usedInCol[cols[j]] |= 1 << d;
    }
  }
  return sq;
}
