import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { BLACK, WHITE } from './board';
import type { UnrulyState, UnrulyUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

const at = (state: UnrulyState, x: number, y: number) => state.grid[y * state.w + x];

export const tutorial: Tutorial<UnrulyState, UnrulyUI> = {
  steps: [
    {
      gameId: '6x6:aAaAACaaAaABaaAaAaAaAAaAaAaaaAAaAa',
      text: 'Colour every square black or white. Each row and column needs **three of each**, and no colour may appear **three times in a row**. Three squares are still undecided.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'This row already has its three white squares, so the undecided one must be black. **Left-click** it: a left-click paints black.',
      highlight: ({ state, tileSize }) => cellRect(0, 1, tileSize, border(tileSize), state.w, 1),
      pointer: ({ tileSize }) => cellCentre(0, 1, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 0, 1) === BLACK,
    },
    {
      text: 'This row has three blacks already, so its undecided square is white. **Right-click** it — right-clicking goes the other way round and paints white first.',
      highlight: ({ state, tileSize }) => cellRect(0, 2, tileSize, border(tileSize), state.w, 1),
      pointer: ({ tileSize }) => ({
        ...cellCentre(1, 2, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => at(state, 1, 2) === WHITE,
    },
    {
      text: 'The last undecided square has two blacks to its left, and a third in a row is not allowed. **Right-click** it to paint it white and finish the grid.',
      highlight: ({ tileSize }) => cellRect(3, 0, tileSize, border(tileSize), 3, 1),
      pointer: ({ tileSize }) => ({
        ...cellCentre(5, 0, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! Clicking a coloured square again cycles it on to the other colour and then back to undecided, and **Undo** steps back through your moves.',
      target: '[data-cmd="undo"]',
    },
  ],
};
