/**
 * Signpost solver. The deductive solver repeatedly links squares that have exactly one
 * possible successor or exactly one possible predecessor, letting the chain numbering
 * of `Board` propagate the consequences; every link it makes is forced, so a puzzle it
 * finishes has exactly one solution. A depth-first search is provided for verifying
 * that claim on small grids and for solving descriptions the deductions cannot crack.
 */
import { Board } from './board';
import type { Puzzle } from './board';

export const IMPOSSIBLE = -1;
export const STUCK = 0;
export const SOLVED = 1;

/**
 * One sweep of forced links. Candidates are judged against a snapshot of the board
 * taken at the start of the sweep (its numbering is consistent, whereas squares linked
 * during the sweep are not renumbered until afterwards); the links found are applied
 * to `b`. Returns the number of links made, or -1 when some square has nowhere to go,
 * nothing can reach it, or two forced links contradict each other.
 */
function forcedLinks(b: Board): number {
  const snap = b.clone();
  const { n, nums, next, prev } = snap;
  // For each square: -1 = no square can precede it, -2 = several can, else the one.
  const from = new Int32Array(n).fill(-1);
  let links = 0;
  const forceLink = (f: number, t: number): boolean => {
    if (b.next[f] === t) return true;
    // Either end is already committed to a different forced link: a contradiction.
    if (b.next[f] !== -1 || b.prev[t] !== -1) return false;
    b.link(f, t);
    links++;
    return true;
  };
  for (let i = 0; i < n; i++) {
    if (next[i] !== -1 || nums[i] === n) continue;
    let poss = -1;
    for (const j of snap.rays[i]) {
      if (prev[j] !== -1 || !snap.isValidMove(true, i, j)) continue;
      if (snap.isReal(nums[i]) && nums[j] === nums[i] + 1) {
        // Consecutive numbers in line with each other must be linked.
        poss = j;
        from[j] = i;
        break;
      }
      poss = poss === -1 ? j : -2;
      from[j] = from[j] === -1 ? i : -2;
    }
    if (poss === -1) return -1;
    if (poss >= 0 && !forceLink(i, poss)) return -1;
  }
  for (let i = 0; i < n; i++) {
    if (prev[i] !== -1 || nums[i] === 1) continue;
    const f = from[i];
    if (f === -1) return -1;
    if (f === -2) continue;
    if (!forceLink(f, i)) return -1;
  }
  return links;
}

/**
 * Solve by deduction alone, working on `b` in place. Returns SOLVED when the whole path
 * 1..n has been found, STUCK when no more deductions are available, or IMPOSSIBLE.
 */
export function solveBoard(b: Board): number {
  for (let iter = 0; iter <= b.n + 1; iter++) {
    b.updateNumbers();
    if (b.impossible) return IMPOSSIBLE;
    const r = forcedLinks(b);
    if (r < 0) return IMPOSSIBLE;
    if (r === 0) break;
  }
  b.updateNumbers();
  if (b.impossible) return IMPOSSIBLE;
  return b.checkCompletion(false).complete ? SOLVED : STUCK;
}

export interface SearchResult {
  /** Each solution as the number of every square. */
  solutions: number[][];
  /** False when the node budget ran out before the search space was covered. */
  exhausted: boolean;
}

/**
 * Enumerate paths 1..n that follow the arrows and agree with the given numbers, by
 * depth-first search. Stops after `cap` solutions or `budget` search nodes.
 */
export function searchSolutions(puzzle: Puzzle, cap = 2, budget = Infinity): SearchResult {
  const { n, given } = puzzle;
  const board = new Board(puzzle);
  const where = new Int32Array(n + 1).fill(-1);
  for (let i = 0; i < n; i++) if (given[i] > 0) where[given[i]] = i;
  const nums = new Array<number>(n).fill(0);
  const solutions: number[][] = [];
  let nodes = 0;
  let exhausted = true;

  const extend = (k: number, c: number): void => {
    if (solutions.length >= cap || !exhausted) return;
    if (++nodes > budget) {
      exhausted = false;
      return;
    }
    if (k === n) {
      solutions.push(nums.slice());
      return;
    }
    const want = where[k + 1];
    for (const t of board.rays[c]) {
      if (nums[t] !== 0) continue;
      if (given[t] !== 0 && given[t] !== k + 1) continue;
      if (want !== -1 && want !== t) continue;
      nums[t] = k + 1;
      extend(k + 1, t);
      nums[t] = 0;
    }
  };

  const starts = where[1] !== -1 ? [where[1]] : [...Array(n).keys()].filter((i) => !given[i]);
  for (const s of starts) {
    nums[s] = 1;
    extend(1, s);
    nums[s] = 0;
    if (solutions.length >= cap || !exhausted) break;
  }
  return { solutions, exhausted };
}
