export interface UntangleParams {
  /** Number of points. */
  n: number;
}

/**
 * Points live on a virtual integer grid of `RES` units per cell, so every position a
 * move can name is exact and crossing tests never suffer from rounding. `RES` matches
 * the denominator the original uses for its starting circle, so descriptions from the
 * original collection open with the same tangle.
 */
export const RES = 64;

export interface UntangleState {
  n: number;
  /** Extent of the coordinate system in cells (the board is `w` × `h` cells). */
  w: number;
  h: number;
  /** Point positions in virtual units, [x0, y0, x1, y1, ...]. */
  pts: number[];
  /** Edges as flat pairs [a0, b0, a1, b1, ...] with a < b, sorted. Shared between states. */
  edges: number[];
  /** Per edge: does it cross some other edge right now? */
  crossed: boolean[];
  /** No two edges cross. */
  completed: boolean;
  /** Solve was used at some point. */
  cheated: boolean;
  /** This state was produced by Solve (so the transition into it animates slowly). */
  justSolved: boolean;
}

export interface UntangleUI {
  /** Point being dragged (mouse or keyboard), or -1. */
  dragPoint: number;
  /** Where the dragged point is right now, in virtual units (fractional while the mouse moves). */
  dragX: number;
  dragY: number;
  /** The drag is driven by the keyboard rather than the pointer. */
  keyboardDrag: boolean;
  /** The last move came from a drag, so the point is already where it is going. */
  justDragged: boolean;
  justMoved: boolean;
  /** Length of the animation currently in progress (set by animLength). */
  animLength: number;
  /** Point the keyboard cursor sits on, or -1 until the keyboard is used. */
  cursorPoint: number;
  cursorVisible: boolean;
  /** Dropped points snap to the centres of the cells of the virtual grid. */
  snap: boolean;
}

