/** Side of the square coordinate system, in cells, for `n` points. */
export function coordLimit(n: number): number {
  return Math.floor(Math.sqrt(n * POINT_DENSITY));
}

// ------------------------------------------------------------------ geometry

/** Sign of (b - a) × (c - a): +1 if c is to one side of the line a→b, -1 the other, 0 on it. */
function orient(ax: number, ay: number, bx: number, by: number, cx: number, cy: number): number {
  return Math.sign((bx - ax) * (cy - ay) - (by - ay) * (cx - ax));
}

/** Is (px, py) on the closed segment a–b? */
export function pointOnSegment(
  px: number,
  py: number,
  ax: number,
  ay: number,
  bx: number,
  by: number,
): boolean {
  if (orient(ax, ay, bx, by, px, py) !== 0) return false;
  return (
    Math.min(ax, bx) <= px &&
    px <= Math.max(ax, bx) &&
    Math.min(ay, by) <= py &&
    py <= Math.max(ay, by)
  );
}

/**
 * Do the closed segments a–b and c–d have a point in common? Touching counts: an
 * endpoint lying on the other segment, or collinear segments that overlap. Either
 * segment may be degenerate (a single point).
 */
export function segmentsCross(
  ax: number,
  ay: number,
  bx: number,
  by: number,
  cx: number,
  cy: number,
  dx: number,
  dy: number,
): boolean {
  const o1 = orient(ax, ay, bx, by, cx, cy);
  const o2 = orient(ax, ay, bx, by, dx, dy);
  // c and d strictly on the same side of the line a–b: no crossing.
  if ((o1 > 0 && o2 > 0) || (o1 < 0 && o2 < 0)) return false;
  if (o1 === 0 && o2 === 0) {
    // Everything is collinear (or a–b is a single point): compare positions along the line.
    if (ax === bx && ay === by) return pointOnSegment(ax, ay, cx, cy, dx, dy);
    const ux = bx - ax;
    const uy = by - ay;
    const len2 = ux * ux + uy * uy;
    const t1 = (cx - ax) * ux + (cy - ay) * uy;
    const t2 = (dx - ax) * ux + (dy - ay) * uy;
    if (t1 < 0 && t2 < 0) return false; // both before a
    if (t1 > len2 && t2 > len2) return false; // both beyond b
    return true;
  }
  const o3 = orient(cx, cy, dx, dy, ax, ay);
  const o4 = orient(cx, cy, dx, dy, bx, by);
  return !((o3 > 0 && o4 > 0) || (o3 < 0 && o4 < 0));
}

/** Do edges i and j (indices into the flat pair list) share an endpoint? */
function shareEndpoint(edges: ArrayLike<number>, i: number, j: number): boolean {
  const a = edges[2 * i];
  const b = edges[2 * i + 1];
  const c = edges[2 * j];
  const d = edges[2 * j + 1];
  return a === c || a === d || b === c || b === d;
}

function edgesCross(pts: ArrayLike<number>, edges: ArrayLike<number>, i: number, j: number) {
  const a = edges[2 * i];
  const b = edges[2 * i + 1];
  const c = edges[2 * j];
  const d = edges[2 * j + 1];
  return segmentsCross(
    pts[2 * a],
    pts[2 * a + 1],
    pts[2 * b],
    pts[2 * b + 1],
    pts[2 * c],
    pts[2 * c + 1],
    pts[2 * d],
    pts[2 * d + 1],
  );
}

/** For every edge, whether it crosses some other edge it does not share an endpoint with. */
export function findCrossings(pts: ArrayLike<number>, edges: ArrayLike<number>): boolean[] {
  const m = edges.length / 2;
  const crossed = new Array<boolean>(m).fill(false);
  for (let i = 0; i < m; i++) {
    for (let j = i + 1; j < m; j++) {
      if (shareEndpoint(edges, i, j)) continue;
      if (edgesCross(pts, edges, i, j)) crossed[i] = crossed[j] = true;
    }
  }
  return crossed;
}

/** Number of crossing edge pairs. */
export function countCrossings(pts: ArrayLike<number>, edges: ArrayLike<number>): number {
  const m = edges.length / 2;
  let count = 0;
  for (let i = 0; i < m; i++)
    for (let j = i + 1; j < m; j++)
      if (!shareEndpoint(edges, i, j) && edgesCross(pts, edges, i, j)) count++;
  return count;
}

function hasCrossing(pts: ArrayLike<number>, edges: ArrayLike<number>): boolean {
  const m = edges.length / 2;
  for (let i = 0; i < m; i++)
    for (let j = i + 1; j < m; j++)
      if (!shareEndpoint(edges, i, j) && edgesCross(pts, edges, i, j)) return true;
  return false;
}

// ---------------------------------------------------------------- layouts

/**
 * The starting layout: `n` points evenly spaced around a circle inside the `w` × `w`
 * board, point 0 at the top and the rest clockwise, with a little room to spare.
 */
export function circleLayout(n: number, w: number): number[] {
  const c = (RES * w) / 2;
  const r = Math.floor((RES * w * 3) / 7);
  const pts: number[] = [];
  for (let i = 0; i < n; i++) {
    const angle = (i * 2 * Math.PI) / n;
    pts.push(Math.floor(c + r * Math.sin(angle) + 0.5), Math.floor(c - r * Math.cos(angle) + 0.5));
  }
  return pts;
}

/** Centre of the cell containing virtual coordinate `v`, clamped to the board. */
function snapCoord(v: number, cells: number): number {
  return clamp(Math.floor(v / RES), 0, cells - 1) * RES + RES / 2;
}

// ------------------------------------------------------------- generation

export interface GeneratedGraph {
  /** Cell coordinates of each point, [x0, y0, x1, y1, ...]: a planar embedding. */
  cells: number[];
  /** Edges as flat pairs a < b, sorted. */
  edges: number[];
}

function sortEdgePairs(edges: number[]): number[] {
  const pairs: [number, number][] = [];
  for (let i = 0; i < edges.length; i += 2) {
    const a = edges[i];
    const b = edges[i + 1];
    pairs.push(a < b ? [a, b] : [b, a]);
  }
  pairs.sort((p, q) => p[0] - q[0] || p[1] - q[1]);
  return pairs.flat();
}

/**
 * Scatter `n` points over distinct cells of a `w` × `w` grid, then add straight edges
 * greedily: always try to give an edge to the vertex with the fewest so far, preferring
 * the nearest partner, and accept the first edge that would not cross an existing edge,
 * pass through another point, or push either vertex past `MAX_DEGREE`. Stop when no
 * edge can be added. The result is planar by construction, and the point positions are
 * a straight-line embedding of it.
 */
export function generatePlanarGraph(n: number, w: number, rng: Random): GeneratedGraph {
  const idx = Array.from({ length: w * w }, (_, i) => i);
  rng.shuffle(idx);
  const cells: number[] = [];
  for (let i = 0; i < n; i++) cells.push(idx[i] % w, Math.floor(idx[i] / w));

  const deg = new Array<number>(n).fill(0);
  const present = new Set<number>();
  const key = (a: number, b: number) => (a < b ? a * n + b : b * n + a);
  const edges: number[] = [];

  const blocked = (v: number, u: number): boolean => {
    const vx = cells[2 * v];
    const vy = cells[2 * v + 1];
    const ux = cells[2 * u];
    const uy = cells[2 * u + 1];
    for (let p = 0; p < n; p++) {
      if (p === v || p === u) continue;
      if (pointOnSegment(cells[2 * p], cells[2 * p + 1], vx, vy, ux, uy)) return true;
    }
    for (let e = 0; e < edges.length; e += 2) {
      const a = edges[e];
      const b = edges[e + 1];
      if (a === v || a === u || b === v || b === u) continue;
      if (
        segmentsCross(
          vx,
          vy,
          ux,
          uy,
          cells[2 * a],
          cells[2 * a + 1],
          cells[2 * b],
          cells[2 * b + 1],
        )
      )
        return true;
    }
    return false;
  };

  for (;;) {
    const order = Array.from({ length: n }, (_, i) => i).sort((p, q) => deg[p] - deg[q] || p - q);
    let added = false;
    for (let i = 0; i < n && !added; i++) {
      const v = order[i];
      if (deg[v] >= MAX_DEGREE) break; // every vertex is full
      // Partners later in the order: earlier ones already tried this edge from their side.
      const cands: number[] = [];
      for (let k = i + 1; k < n; k++) {
        const u = order[k];
        if (deg[u] < MAX_DEGREE && !present.has(key(v, u))) cands.push(u);
      }
      const dist2 = (u: number) => {
        const dx = cells[2 * u] - cells[2 * v];
        const dy = cells[2 * u + 1] - cells[2 * v + 1];
        return dx * dx + dy * dy;
      };
      cands.sort((p, q) => dist2(p) - dist2(q) || p - q);
      for (const u of cands) {
        if (blocked(v, u)) continue;
        edges.push(v, u);
        present.add(key(v, u));
        deg[v]++;
        deg[u]++;
        added = true;
        break;
      }
    }
    if (!added) break;
  }
  return { cells, edges: sortEdgePairs(edges) };
}

/**
 * Look for a straight-line embedding of the graph with every point on a distinct cell of
 * the `w` × `w` grid — the kind of layout `newDesc` starts from, so one always exists for
 * a generated puzzle. This is what Solve falls back on when the generator's answer is not
 * at hand (a puzzle opened from a share link or the tutorial). Plain backtracking: points
 * are placed one at a time, those with the most placed neighbours first, and a cell is
 * refused when it would make an edge cross another, run through a point, or put the point
 * on an edge. Returns the cell of each point, or null once `budget` placements have been
 * tried without success. With `rng`, ties in the placement order and the spot the first
 * point is tried at are shuffled, so repeated short runs explore different layouts.
 */
export function searchEmbedding(
  n: number,
  w: number,
  edges: ArrayLike<number>,
  budget = 200000,
  rng?: Random,
): number[] | null {
  const adj: number[][] = Array.from({ length: n }, () => []);
  for (let e = 0; e < edges.length; e += 2) {
    adj[edges[e]].push(edges[e + 1]);
    adj[edges[e + 1]].push(edges[e]);
  }
  // Placement order: start from the busiest point, then always take the point with the
  // most neighbours already placed, so each placement is pinned down as early as possible.
  const order: number[] = [];
  const inOrder = new Array<boolean>(n).fill(false);
  const tieBreak = Array.from({ length: n }, () => (rng ? rng.upto(64) : 0));
  while (order.length < n) {
    let best = -1;
    let bestKey = -1;
    for (let v = 0; v < n; v++) {
      if (inOrder[v]) continue;
      let placedNb = 0;
      for (const u of adj[v]) if (inOrder[u]) placedNb++;
      const k = (placedNb * 64 + adj[v].length) * 64 + tieBreak[v];
      if (k > bestKey) {
        bestKey = k;
        best = v;
      }
    }
    order.push(best);
    inOrder[best] = true;
  }

  const cells = new Array<number>(2 * n).fill(-1);
  const used = new Uint8Array(w * w);
  const placedEdges: number[] = []; // flat pairs, both ends placed
  const placedPts: number[] = [];
  let tries = 0;

  const fits = (v: number, x: number, y: number): boolean => {
    // The point must not sit on an edge that is already drawn.
    for (let e = 0; e < placedEdges.length; e += 2) {
      const a = placedEdges[e];
      const b = placedEdges[e + 1];
      if (pointOnSegment(x, y, cells[2 * a], cells[2 * a + 1], cells[2 * b], cells[2 * b + 1]))
        return false;
    }
    for (const u of adj[v]) {
      if (cells[2 * u] < 0) continue;
      const ux = cells[2 * u];
      const uy = cells[2 * u + 1];
      for (const p of placedPts) {
        if (p === u) continue;
        if (pointOnSegment(cells[2 * p], cells[2 * p + 1], x, y, ux, uy)) return false;
      }
      for (let e = 0; e < placedEdges.length; e += 2) {
        const a = placedEdges[e];
        const b = placedEdges[e + 1];
        if (a === u || b === u) continue;
        if (
          segmentsCross(
            x,
            y,
            ux,
            uy,
            cells[2 * a],
            cells[2 * a + 1],
            cells[2 * b],
            cells[2 * b + 1],
          )
        )
          return false;
      }
    }
    return true;
  };

  const place = (k: number): boolean => {
    if (k === n) return true;
    const v = order[k];
    // Try the cells nearest the placed neighbours first.
    let sx = 0;
    let sy = 0;
    let cnt = 0;
    for (const u of adj[v]) {
      if (cells[2 * u] < 0) continue;
      sx += cells[2 * u];
      sy += cells[2 * u + 1];
      cnt++;
    }
    const cx = cnt ? sx / cnt : rng ? rng.upto(w) : (w - 1) / 2;
    const cy = cnt ? sy / cnt : rng ? rng.upto(w) : (w - 1) / 2;
    const cand: number[] = [];
    for (let c = 0; c < w * w; c++) if (!used[c]) cand.push(c);
    const d = (c: number) => ((c % w) - cx) ** 2 + (Math.floor(c / w) - cy) ** 2;
    cand.sort((p, q) => d(p) - d(q) || p - q);
    for (const c of cand) {
      if (++tries > budget) return false;
      const x = c % w;
      const y = Math.floor(c / w);
      if (!fits(v, x, y)) continue;
      cells[2 * v] = x;
      cells[2 * v + 1] = y;
      used[c] = 1;
      placedPts.push(v);
      let added = 0;
      for (const u of adj[v]) {
        if (cells[2 * u] < 0 || u === v) continue;
        placedEdges.push(v, u);
        added++;
      }
      if (place(k + 1)) return true;
      placedEdges.length -= 2 * added;
      placedPts.pop();
      used[c] = 0;
      cells[2 * v] = cells[2 * v + 1] = -1;
      if (tries > budget) return false;
    }
    return false;
  };

  return place(0) ? cells : null;
}

/**
 * A crossing-free layout for a puzzle whose answer did not come with it, in board units,
 * or null if none turns up in time. One long backtracking run tends to paint itself into
 * a corner on bigger boards, so the search is many short runs from shuffled starts: first
 * on the cell centres, where the generator's answers lie too (this finds one for every
 * preset size), then on a grid twice as fine, which leaves more room on big custom boards.
 */
export function findLayout(n: number, w: number, edges: ArrayLike<number>): number[] | null {
  const rng = new Random('untangle-layout');
  // Past the preset sizes the cell centres rarely leave enough room: move on sooner.
  const coarseRuns = n <= 25 ? 60 : 10;
  for (let r = 0; r < coarseRuns; r++) {
    const coarse = searchEmbedding(n, w, edges, 5000, r ? rng : undefined);
    if (coarse) return stretch(coarse, w).map((c) => c * RES + RES / 2);
  }
  for (let r = 0; r < 120; r++) {
    const fine = searchEmbedding(n, 2 * w, edges, 5000, rng);
    if (fine) return stretch(fine, 2 * w).map((c) => (c * RES) / 2 + RES / 4);
  }
  return null;
}

/**
 * The search packs the points round where it started; stretch a layout on a `side` ×
 * `side` grid by whole factors to fill it, in place. Scaling each axis by a positive
 * factor and shifting it changes no crossing, and whole numbers keep every point on the grid.
 */
function stretch(cells: number[], side: number): number[] {
  for (let axis = 0; axis < 2; axis++) {
    let lo = side;
    let hi = 0;
    for (let i = axis; i < cells.length; i += 2) {
      lo = Math.min(lo, cells[i]);
      hi = Math.max(hi, cells[i]);
    }
    const k = hi > lo ? Math.floor((side - 1) / (hi - lo)) : 1;
    const shift = Math.floor((side - 1 - (hi - lo) * k) / 2);
    for (let i = axis; i < cells.length; i += 2) cells[i] = (cells[i] - lo) * k + shift;
  }
  return cells;
}

// ------------------------------------------------------------ descriptions

/** Parse `a-b,c-d,...` into sorted flat pairs. Assumes a valid description. */
export function parseDesc(desc: string): number[] {
  const edges: number[] = [];
  for (const part of desc.split(',')) {
    const [a, b] = part.split('-').map(Number);
    edges.push(a, b);
  }
  return sortEdgePairs(edges);
}

interface ParsedMove {
  solve: boolean;
  /** [point, x, y] triples. */
  moves: [number, number, number][];
}

/** Parse `S;P0:x,y;P1:x,y` style move strings; null if malformed or out of range. */
function parseMove(move: string, n: number, w: number, h: number): ParsedMove | null {
  if (!move) return null;
  const out: ParsedMove = { solve: false, moves: [] };
  for (const token of move.split(';')) {
    if (token === 'S') {
      out.solve = true;
      continue;
    }
    const m = /^P(\d+):(\d+),(\d+)$/.exec(token);
    if (!m) return null;
    const i = parseInt(m[1], 10);
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    if (i >= n || x > w * RES || y > h * RES) return null;
    out.moves.push([i, x, y]);
  }
  return out;
}

function encodeMove(i: number, x: number, y: number): string {
  return `P${i}:${x},${y}`;
}

// ------------------------------------------------------------------ helpers

function borderFor(t: number): number {
  return Math.round(t * 0.3);
}

function cursorDelta(button: number): [number, number] {
  switch (button) {
    case CURSOR_UP:
      return [0, -1];
    case CURSOR_DOWN:
      return [0, 1];
    case CURSOR_LEFT:
      return [-1, 0];
    default:
      return [1, 0];
  }
}

/** The point nearest the middle of the board (lowest index on a tie). */
function pointNearestCentre(state: UntangleState): number {
  const cx = (state.w * RES) / 2;
  const cy = (state.h * RES) / 2;
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < state.n; i++) {
    const dx = state.pts[2 * i] - cx;
    const dy = state.pts[2 * i + 1] - cy;
    const d = dx * dx + dy * dy;
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

/**
 * The point to move the keyboard cursor to from `from` in direction (dx, dy): the
 * nearest point within a 90° cone in that direction, or failing that the nearest point
 * that is at least somewhat in that direction. -1 if there is none.
 */
export function nextPointInDirection(
  state: UntangleState,
  from: number,
  dx: number,
  dy: number,
): number {
  const fx = state.pts[2 * from];
  const fy = state.pts[2 * from + 1];
  let best = -1;
  let bestScore = Infinity;
  for (let i = 0; i < state.n; i++) {
    if (i === from) continue;
    const ex = state.pts[2 * i] - fx;
    const ey = state.pts[2 * i + 1] - fy;
    const along = ex * dx + ey * dy;
    if (along <= 0) continue;
    const perp = Math.abs(ex * dy - ey * dx);
    const d2 = ex * ex + ey * ey;
    const score = perp <= along ? d2 : d2 + 1e12;
    if (score < bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

/** The point within grabbing distance of virtual position (vx, vy), or -1. */
function pointAt(state: UntangleState, vx: number, vy: number): number {
  // Half a tile: the nearest point within it wins, so neighbours never steal each other's
  // grab, and a fingertip on a phone (a 25-point board has ~40px tiles) still lands one.
  const threshold = RES * 0.5;
  let best = -1;
  let bestD = threshold * threshold;
  for (let i = 0; i < state.n; i++) {
    const dx = state.pts[2 * i] - vx;
    const dy = state.pts[2 * i + 1] - vy;
    const d = dx * dx + dy * dy;
    if (d <= bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

function neighbours(state: UntangleState, p: number): Set<number> {
  const out = new Set<number>();
  for (let e = 0; e < state.edges.length; e += 2) {
    if (state.edges[e] === p) out.add(state.edges[e + 1]);
    else if (state.edges[e + 1] === p) out.add(state.edges[e]);
  }
  return out;
}

/** Finish a drag: the move that puts the dragged point where it was carried to. */
function dropMove(state: UntangleState, ui: UntangleUI, vx: number, vy: number): string {
  const p = ui.dragPoint;
  ui.dragPoint = -1;
  ui.cursorPoint = p;
  let x = Math.round(clamp(vx, 0, state.w * RES));
  let y = Math.round(clamp(vy, 0, state.h * RES));
  if (ui.snap) {
    x = snapCoord(x, state.w);
    y = snapCoord(y, state.h);
  }
  if (x === state.pts[2 * p] && y === state.pts[2 * p + 1]) return '';
  ui.justDragged = true;
  return encodeMove(p, x, y);
}

// ------------------------------------------------------------------ the game

const game = defineGame<UntangleParams, UntangleState, UntangleUI>({
  id: 'untangle',
  name: 'Untangle',
  description: 'Drag the points around until no two lines cross.',
  alsoKnownAs: 'Planarity',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: [6, 10, 15, 20, 25].map((n) => ({ name: `${n} points`, params: { n } })),
  // The smallest board the Type menu offers, rather than the original's default: a
  // newcomer's first puzzle should be one they can finish. See the other games' OPENING.
  defaultParams: () => ({ n: 6 }),
  encodeParams: (p) => String(p.n),
  decodeParams(str) {
    const m = /^(\d+)/.exec(str);
    if (!m) throw new Error(tx`expected a number of points`);
    return { n: parseInt(m[1], 10) };
  },
  validateParams(p) {
    if (!Number.isInteger(p.n)) return tx`Number of points must be a whole number`;
    if (p.n < MIN_POINTS) return tx`Number of points must be at least ${MIN_POINTS}`;
    if (p.n > MAX_POINTS) return tx`Number of points must be at most ${MAX_POINTS}`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [{ type: 'string', name: 'Number of points', value: String(p.n) }];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return { n: int(0) };
  },

  newDesc(p, rng: Random) {
    const n = p.n;
    const w = coordLimit(n);
    const circle = circleLayout(n, w);
    for (;;) {
      const { cells, edges } = generatePlanarGraph(n, w, rng);
      // Relabel the points at random so that the starting circle is tangled. A graph
      // that no labelling can tangle (a star, say) is thrown away.
      const label = Array.from({ length: n }, (_, i) => i);
      for (let attempt = 0; attempt < 100; attempt++) {
        rng.shuffle(label);
        const relabelled = sortEdgePairs(edges.map((v) => label[v]));
        if (!hasCrossing(circle, relabelled)) continue;
        const parts: string[] = [];
        for (let e = 0; e < relabelled.length; e += 2)
          parts.push(`${relabelled[e]}-${relabelled[e + 1]}`);
        // The embedding we started from is the solution: cell centres, by new label.
        const sol = new Array<number>(2 * n);
        for (let i = 0; i < n; i++) {
          sol[2 * label[i]] = cells[2 * i] * RES + RES / 2;
          sol[2 * label[i] + 1] = cells[2 * i + 1] * RES + RES / 2;
        }
        let aux = 'S';
        for (let i = 0; i < n; i++) aux += ';' + encodeMove(i, sol[2 * i], sol[2 * i + 1]);
        return { desc: parts.join(','), aux };
      }
    }
  },

  validateDesc(p, desc) {
    if (!desc) return tx`Description must contain at least one edge`;
    const seen = new Set<number>();
    for (const part of desc.split(',')) {
      const m = /^(\d+)-(\d+)$/.exec(part);
      if (!m) return tx`Expected a list of edges like 0-1,1-2 in game description`;
      const a = parseInt(m[1], 10);
      const b = parseInt(m[2], 10);
      if (a >= p.n || b >= p.n) return tx`Number out of range in game description`;
      if (a === b) return tx`An edge cannot join a point to itself`;
      const k = Math.min(a, b) * p.n + Math.max(a, b);
      if (seen.has(k)) return tx`Duplicate edge in game description`;
      seen.add(k);
    }
    return null;
  },

  newGame(p, desc) {
    const n = p.n;
    const w = coordLimit(n);
    const pts = circleLayout(n, w);
    const edges = parseDesc(desc);
    const crossed = findCrossings(pts, edges);
    return {
      n,
      w,
      h: w,
      pts,
      edges,
      crossed,
      completed: !crossed.includes(true),
      cheated: false,
      justSolved: false,
    };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const n = curr.n;
    const sol = new Array<number>(2 * n).fill(-1);
    if (aux) {
      const parsed = parseMove(aux, n, curr.w, curr.h);
      if (!parsed || !parsed.solve || parsed.moves.length !== n)
        throw new Error(tx`Internal error: solution is badly formatted`);
      for (const [i, x, y] of parsed.moves) {
        sol[2 * i] = x;
        sol[2 * i + 1] = y;
      }
      if (sol.includes(-1)) throw new Error(tx`Internal error: solution is badly formatted`);
    } else {
      // No answer came with the puzzle (a share link, the tutorial): look for one.
      const layout = findLayout(n, curr.w, curr.edges);
      if (!layout) throw new Error(tx`Solution not known for this puzzle`);
      for (let i = 0; i < 2 * n; i++) sol[i] = layout[i];
    }

    // The solved layout can be reflected or rotated freely; pick the one of the eight
    // symmetries of the board that is closest to where the points are now, so that
    // they travel as little as possible.
    const cx = (curr.w * RES) / 2;
    const cy = (curr.h * RES) / 2;
    const place = (i: number, swap: boolean, sx: number, sy: number): [number, number] => {
      const px = sol[2 * i] - cx;
      const py = sol[2 * i + 1] - cy;
      return [sx * (swap ? py : px) + cx, sy * (swap ? px : py) + cy];
    };
    let best: [boolean, number, number] = [false, 1, 1];
    let bestD = Infinity;
    for (const swap of [false, true]) {
      for (const sx of [1, -1]) {
        for (const sy of [1, -1]) {
          let d = 0;
          for (let i = 0; i < n; i++) {
            const [x, y] = place(i, swap, sx, sy);
            const dx = x - curr.pts[2 * i];
            const dy = y - curr.pts[2 * i + 1];
            d += dx * dx + dy * dy;
          }
          if (d < bestD) {
            bestD = d;
            best = [swap, sx, sy];
          }
        }
      }
    }
    let move = 'S';
    for (let i = 0; i < n; i++) {
      const [x, y] = place(i, ...best);
      move += ';' + encodeMove(i, x, y);
    }
    return move;
  },

  newUI: () => ({
    dragPoint: -1,
    dragX: 0,
    dragY: 0,
    keyboardDrag: false,
    justDragged: false,
    justMoved: false,
    animLength: ANIM,
    cursorPoint: -1,
    cursorVisible: false,
    snap: false,
  }),

  changedState(ui) {
    // Whatever was being dragged has been superseded by a move, undo or redo.
    ui.dragPoint = -1;
    ui.justMoved = ui.justDragged;
    ui.justDragged = false;
  },

  // The snap grid is a toggle on `G`, which a phone does not have. It changes where the
  // next drop lands, so it sits beside Undo and lights up while it is on.
  actions: [
    {
      label: 'Snap',
      key: 'G',
      hud: true,
      glyph: SNAP_GLYPH,
      pressed: (_s, ui) => ui.snap,
      view: true,
      title: 'Snap dropped points to a grid (G)',
    },
  ],

  encodeUI: (ui) => (ui.snap ? 'snap' : ''),
  decodeUI(ui, enc) {
    ui.snap = enc === 'snap';
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const t = ds.tileSize;
    const bd = borderFor(t);
    const vx = ((mx - bd) * RES) / t;
    const vy = ((my - bd) * RES) / t;

    if (isMouseDown(b)) {
      const redraw = ui.cursorVisible || ui.dragPoint >= 0;
      ui.cursorVisible = false;
      ui.dragPoint = -1; // a keyboard drag in progress is abandoned
      const p = pointAt(state, vx, vy);
      if (p < 0) return redraw ? '' : null;
      ui.dragPoint = p;
      ui.dragX = vx;
      ui.dragY = vy;
      ui.keyboardDrag = false;
      ui.cursorPoint = p;
      return '';
    }
    if (isMouseDrag(b)) {
      if (ui.dragPoint < 0 || ui.keyboardDrag) return null;
      ui.dragX = vx;
      ui.dragY = vy;
      return '';
    }
    if (isMouseRelease(b)) {
      if (ui.dragPoint < 0 || ui.keyboardDrag) return null;
      // Letting go outside the canvas altogether cancels the drag; a drop in the
      // margin lands on the nearest edge of the board.
      const size = state.w * t + 2 * bd;
      if (mx < 0 || my < 0 || mx >= size || my >= size) {
        ui.cursorPoint = ui.dragPoint;
        ui.dragPoint = -1;
        return '';
      }
      return dropMove(state, ui, vx, vy);
    }

    if (isCursorMove(b)) {
      const [dx, dy] = cursorDelta(b);
      ui.cursorVisible = true;
      if (ui.dragPoint >= 0) {
        // Carry the picked-up point: an eighth of a cell per press, a whole cell with
        // Shift (or when snapping), a single unit with Ctrl.
        let step = RES / 8;
        if (button & MOD_SHFT || ui.snap) step = RES;
        else if (button & MOD_CTRL) step = 1;
        const x = ui.snap ? snapCoord(ui.dragX, state.w) : Math.round(ui.dragX);
        const y = ui.snap ? snapCoord(ui.dragY, state.h) : Math.round(ui.dragY);
        ui.dragX = clamp(x + dx * step, 0, state.w * RES);
        ui.dragY = clamp(y + dy * step, 0, state.h * RES);
        return '';
      }
      if (ui.cursorPoint < 0) {
        ui.cursorPoint = pointNearestCentre(state);
        return '';
      }
      const next = nextPointInDirection(state, ui.cursorPoint, dx, dy);
      if (next >= 0) ui.cursorPoint = next;
      return '';
    }

    if (isCursorSelect(b)) {
      if (ui.dragPoint >= 0) return dropMove(state, ui, ui.dragX, ui.dragY);
      if (!ui.cursorVisible || ui.cursorPoint < 0) {
        ui.cursorVisible = true;
        if (ui.cursorPoint < 0) ui.cursorPoint = pointNearestCentre(state);
        return '';
      }
      ui.dragPoint = ui.cursorPoint;
      ui.dragX = state.pts[2 * ui.cursorPoint];
      ui.dragY = state.pts[2 * ui.cursorPoint + 1];
      ui.keyboardDrag = true;
      return '';
    }

    const ch = keyChar(button);
    if (ch === 'g' || ch === 'G') {
      ui.snap = !ui.snap;
      return '';
    }
    return null;
  },

  executeMove(state, move) {
    const parsed = parseMove(move, state.n, state.w, state.h);
    if (!parsed) return null;
    const pts = state.pts.slice();
    for (const [i, x, y] of parsed.moves) {
      pts[2 * i] = x;
      pts[2 * i + 1] = y;
    }
    const crossed = findCrossings(pts, state.edges);
    return {
      ...state,
      pts,
      crossed,
      completed: !crossed.includes(true),
      cheated: state.cheated || parsed.solve,
      justSolved: parsed.solve,
    };
  },

  preferredTileSize: 64,
  computeSize(p, t) {
    const w = coordLimit(p.n);
    const bd = borderFor(t);
    return { w: w * t + 2 * bd, h: w * t + 2 * bd };
  },

  redraw(dr: Drawing, ds, oldState, state, _dir, ui, animTime, flashTime) {
    const { n, w, h, edges } = state;
    const t = ds.tileSize;
    const bd = borderFor(t);
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const r = Math.max(3.5, t / 8);

    dr.rect(bd, bd, w * t, h * t, flashing ? 'shade' : null, 'ink', { width: 2.4 });

    if (ui.snap) {
      for (let gy = 0; gy < h; gy++)
        for (let gx = 0; gx < w; gx++)
          dr.dot(bd + (gx + 0.5) * t, bd + (gy + 0.5) * t, Math.max(1.2, t * 0.025), 'faint');
    }

    // Where every point is drawn this frame: the state's position, overridden by the
    // drag for the point being carried, blended from the old state while animating.
    const frac = oldState && ui.animLength > 0 ? easeInOut(animTime / ui.animLength) : 1;
    const vpts = new Array<number>(2 * n);
    for (let i = 0; i < n; i++) {
      let x = state.pts[2 * i];
      let y = state.pts[2 * i + 1];
      if (ui.dragPoint === i) {
        x = ui.snap ? snapCoord(ui.dragX, w) : ui.dragX;
        y = ui.snap ? snapCoord(ui.dragY, h) : ui.dragY;
      } else if (oldState && frac < 1) {
        x = oldState.pts[2 * i] + (x - oldState.pts[2 * i]) * frac;
        y = oldState.pts[2 * i + 1] + (y - oldState.pts[2 * i + 1]) * frac;
      }
      vpts[2 * i] = x;
      vpts[2 * i + 1] = y;
    }
    const px = (i: number) => bd + (vpts[2 * i] * t) / RES;
    const py = (i: number) => bd + (vpts[2 * i + 1] * t) / RES;

    // Edges, with the ones that cross something drawn last so the red reads clearly.
    const crossed = findCrossings(vpts, edges);
    for (const pass of [false, true]) {
      for (let e = 0; e < edges.length / 2; e++) {
        if (crossed[e] !== pass) continue;
        const a = edges[2 * e];
        const b = edges[2 * e + 1];
        dr.line(px(a), py(a), px(b), py(b), pass ? 'error' : 'pencil', pass ? 2 : 1.8, {
          seed: e,
        });
      }
    }

    // Points: the one being dragged in accent (drawn last), its neighbours in blue.
    const near = ui.dragPoint >= 0 ? neighbours(state, ui.dragPoint) : null;
    for (let i = 0; i < n; i++) {
      if (i === ui.dragPoint) continue;
      const fill = near?.has(i) ? 'blue' : 'ink';
      dr.circle(px(i), py(i), r, fill, 'ink', { width: 1.4, seed: i });
    }
    if (ui.dragPoint >= 0) {
      const i = ui.dragPoint;
      dr.circle(px(i), py(i), r * 1.15, 'accent', 'ink', { width: 1.4, seed: i });
    }

    if (ui.cursorVisible) {
      const c = ui.dragPoint >= 0 && ui.keyboardDrag ? ui.dragPoint : ui.cursorPoint;
      if (c >= 0 && c < n) dr.cursor(px(c) - 2 * r, py(c) - 2 * r, 4 * r, 4 * r);
    }
  },

  animLength(oldState, newState, dir, ui) {
    if (ui.justMoved) return 0;
    ui.animLength = (dir < 0 ? oldState : newState).justSolved ? SOLVE_ANIM : ANIM;
    return ui.animLength;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // Solve needs the generator's layout, which only a seed brings along to whoever opens the link.
  flags: { solveAnimates: true, oneButton: true, shareBySeed: true },
  thumbnailParams: { n: 10 },
});

export default game;
