import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
// A cycle with `./index`, which imports this list; safe, because the constants are only
// read inside `test`, long after both modules have finished loading.
import { PEG, countPegs, type PegsParams, type PegsState } from './index';

type C = typeof PALETTE;

/** The game's peg: an ink ball with a highlight. */
function peg(c: C, cx: number, cy: number, r: number, fill: string = c.ink): string {
  return (
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}"/>` +
    `<circle cx="${(cx - r * 0.35).toFixed(1)}" cy="${(cy - r * 0.35).toFixed(1)}" r="${(r * 0.3).toFixed(1)}" fill="${c.highlight}"/>`
  );
}

function hole(c: C, cx: number, cy: number, r: number): string {
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.shade}" stroke="${c.pencil}" stroke-width="1.8"/>`;
}

/** Centre of cell (x, y) of the 7×7 Cross board drawn at pitch `p` round (50, 50). */
const at = (x: number, y: number, p: number): [number, number] => [
  50 + (x - 3) * p,
  50 + (y - 3) * p,
];
const onCross = (x: number, y: number) => (x >= 2 && x <= 4) || (y >= 2 && y <= 4);

/** The English Cross board, every hole empty except `pegs`. */
function crossBoard(c: C, pegs: [number, number][], pegR: number): string {
  const p = 9.4;
  const a = p * 1.5;
  const b = p * 3.5;
  const outline = `M${50 - a} ${50 - b} H${50 + a} V${50 - a} H${50 + b} V${50 + a} H${50 + a} V${50 + b} H${50 - a} V${50 + a} H${50 - b} V${50 - a} H${50 - a} Z`;
  let holes = '';
  for (let y = 0; y < 7; y++)
    for (let x = 0; x < 7; x++) {
      if (!onCross(x, y)) continue;
      const [cx, cy] = at(x, y, p);
      holes += hole(c, cx, cy, 2.4);
    }
  return (
    `<path d="${outline}" fill="${c.paper}" stroke="${c.ink}" stroke-width="4.5" stroke-linejoin="round"/>` +
    holes +
    pegs.map(([x, y]) => peg(c, ...at(x, y, p), pegR)).join('')
  );
}

/**
 * The longest run of consecutive jumps made by one and the same peg, since the last
 * Restart: a jump always takes exactly one peg off, a Restart puts them back, and the
 * attempt it threw away does not count.
 */
function longestChain(history: readonly PegsState[]): number {
  let best = 0;
  let run = 0;
  let last = -1;
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].grid;
    const b = history[k].grid;
    const w = history[k].w;
    if (countPegs(b) !== countPegs(a) - 1) {
      best = run = 0;
      last = -1;
      continue;
    }
    let to = -1;
    const emptied: number[] = [];
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== PEG && b[i] === PEG) to = i;
      else if (a[i] === PEG && b[i] !== PEG) emptied.push(i);
    }
    // Of the two squares a jump empties, the jumper's start is the one two cells away.
    const from = emptied.find(
      (i) => Math.abs((i % w) - (to % w)) + Math.abs(Math.floor(i / w) - Math.floor(to / w)) === 2,
    );
    if (to < 0 || from === undefined) {
      run = 0;
      last = -1;
      continue;
    }
    run = from === last ? run + 1 : 1;
    last = to;
    best = Math.max(best, run);
  }
  return best;
}

/** One peg hopping round a square: over a peg on each side and back to where it began. */
function hopSquare(c: C): string {
  const lo = 31;
  const hi = 69;
  const corners: [number, number][] = [
    [lo, hi],
    [lo, lo],
    [hi, lo],
    [hi, hi],
  ];
  let holes = '';
  let arcs = '';
  let heads = '';
  for (let i = 0; i < 4; i++) {
    const [x0, y0] = corners[i];
    const [x1, y1] = corners[(i + 1) % 4];
    // The pegs it hops over, each taken off the board: drawn in pencil.
    holes += peg(c, (x0 + x1) / 2, (y0 + y1) / 2, 5.5, c.lowlight);
    // Start and end a little way off the holes, bowed out over the peg they jump.
    const sx = x0 + (x1 - x0) * 0.2;
    const sy = y0 + (y1 - y0) * 0.2;
    const ex = x0 + (x1 - x0) * 0.8;
    const ey = y0 + (y1 - y0) * 0.8;
    const qx = (x0 + x1) / 2 - (50 - (x0 + x1) / 2) * 0.8;
    const qy = (y0 + y1) / 2 - (50 - (y0 + y1) / 2) * 0.8;
    arcs += `M${sx} ${sy} Q${qx} ${qy} ${ex} ${ey} `;
    // An arrowhead along the curve's last direction.
    const len = Math.hypot(ex - qx, ey - qy);
    const dx = (ex - qx) / len;
    const dy = (ey - qy) / len;
    const wing = (sgn: number) => {
      const a = (sgn * 32 * Math.PI) / 180;
      const bx = -(dx * Math.cos(a) - dy * Math.sin(a)) * 8;
      const by = -(dx * Math.sin(a) + dy * Math.cos(a)) * 8;
      return `${(ex + bx).toFixed(1)} ${(ey + by).toFixed(1)}`;
    };
    heads += `M${wing(1)} L${ex} ${ey} L${wing(-1)} `;
  }
  return (
    holes +
    `<path d="${arcs}${heads}" fill="none" stroke="${c.ink}" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/>` +
    peg(c, lo, hi, 8.5)
  );
}

export const achievements = defineAchievements<PegsParams, PegsState>([
  {
    id: 'dead-centre',
    name: 'Dead Centre',
    description: 'Finish the Cross board with the last peg in the centre hole.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) =>
      crossBoard(c, [], 0) +
      `<circle cx="50" cy="50" r="10.5" fill="none" stroke="${c.red}" stroke-width="3.5"/>` +
      peg(c, 50, 50, 6.5),
    test: (ctx) => {
      const { w, h, grid } = ctx.state;
      return (
        ctx.params.type === 'cross' &&
        w % 2 === 1 &&
        h % 2 === 1 &&
        countPegs(grid) === 1 &&
        grid[((h - 1) / 2) * w + (w - 1) / 2] === PEG
      );
    },
  },
  {
    id: 'hopscotch',
    name: 'Hopscotch',
    description: 'Win a game of Pegs with one peg jumping four times in a row.',
    tier: 'silver',
    hue: 'green',
    // Four hops round a square, jumping a peg on every side, and home again.
    art: (c) => hopSquare(c),
    test: (ctx) => longestChain(ctx.history) >= 4,
  },
  {
    id: 'pegged-out',
    name: 'Pegged Out',
    description: 'Get stuck with ten or more pegs still on the board.',
    tier: 'bronze',
    hidden: true,
    hue: 'violet',
    on: 'lose',
    art: (c) =>
      // Ten pegs left and not one of them next to another: nothing can jump.
      crossBoard(
        c,
        [
          [2, 0],
          [4, 0],
          [3, 1],
          [0, 2],
          [6, 2],
          [3, 3],
          [0, 4],
          [6, 4],
          [2, 6],
          [4, 6],
        ],
        4.2,
      ),
    test: (ctx) => countPegs(ctx.state.grid) >= 10,
  },
]);
