import { tx } from '../../i18n';
/**
 * Shared geometry for Dominosa: a set of dominoes with numbers up to `n` has one
 * domino for every unordered pair, so it tiles an (n+2) × (n+1) rectangle. Squares are
 * indexed row-major; a *placement* is one of the 2·w·h possible domino positions,
 * indexed like the original collection so that game IDs and moves stay compatible:
 * the vertical placement whose top square is `i` is `2i`, the horizontal one whose left
 * square is `i` is `2i + 1`.
 */

/** The nth triangular number. */
export function tri(n: number): number {
  return (n * (n + 1)) / 2;
}

/** How many dominoes there are in a set with numbers up to `n`. */
export function dominoCount(n: number): number {
  return tri(n + 1);
}

/** A unique index in [0, dominoCount(n)) for the domino with the two given numbers. */
export function dominoIndex(a: number, b: number): number {
  return a > b ? tri(a) + b : tri(b) + a;
}

/** Grid dimensions for a maximum number `n`. */
export function gridSize(n: number): { w: number; h: number } {
  return { w: n + 2, h: n + 1 };
}

/** True when placement `p` lies inside a w×h grid. */
export function placementValid(p: number, w: number, h: number): boolean {
  const s = p >> 1;
  if (s < 0 || s >= w * h) return false;
  return p & 1 ? s % w < w - 1 : s + w < w * h;
}

/** The two squares of a placement (first is the top/left one). */
export function placementSquares(p: number, w: number): [number, number] {
  const s = p >> 1;
  return [s, p & 1 ? s + 1 : s + w];
}

/** The placement covering adjacent squares `a` and `b` (in either order), or -1. */
export function placementOf(a: number, b: number, w: number, h: number): number {
  const lo = Math.min(a, b);
  const hi = Math.max(a, b);
  if (lo < 0 || hi >= w * h) return -1;
  if (hi === lo + 1 && lo % w < w - 1) return 2 * lo + 1;
  if (hi === lo + w) return 2 * lo;
  return -1;
}

/** The up-to-four placements that involve square `s`. */
export function placementsAt(s: number, w: number, h: number): number[] {
  const x = s % w;
  const y = Math.floor(s / w);
  const out: number[] = [];
  if (x > 0) out.push(2 * (s - 1) + 1);
  if (x + 1 < w) out.push(2 * s + 1);
  if (y > 0) out.push(2 * (s - w));
  if (y + 1 < h) out.push(2 * s);
  return out;
}

/**
 * Parse a game description (a string of digits, numbers above 9 written as `[12]`) into
 * one number per square, or return an error message.
 */
export function parseDesc(desc: string, n: number): number[] | string {
  const { w, h } = gridSize(n);
  const wh = w * h;
  const numbers: number[] = [];
  const occurrences = new Array<number>(n + 1).fill(0);
  let i = 0;
  while (i < desc.length) {
    if (numbers.length >= wh) return tx`Game description is too long`;
    const c = desc[i];
    let v: number;
    if (c >= '0' && c <= '9') {
      v = c.charCodeAt(0) - 48;
      i++;
    } else if (c === '[') {
      const close = desc.indexOf(']', i);
      if (close < 0) return tx`Invalid syntax in game description`;
      const body = desc.slice(i + 1, close);
      if (!/^\d+$/.test(body)) return tx`Invalid syntax in game description`;
      v = parseInt(body, 10);
      i = close + 1;
    } else {
      return tx`Invalid syntax in game description`;
    }
    if (v > n) return tx`Number out of range in game description`;
    occurrences[v]++;
    numbers.push(v);
  }
  if (numbers.length < wh) return tx`Game description is too short`;
  // Every number pairs with each of the n+1 numbers, and once more with itself.
  for (let v = 0; v <= n; v++)
    if (occurrences[v] !== n + 2) return tx`Incorrect number balance in game description`;
  return numbers;
}

export function encodeDesc(numbers: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < numbers.length; i++) {
    const v = numbers[i];
    s += v < 10 ? String(v) : `[${v}]`;
  }
  return s;
}

/**
 * Encode a complete tiling (`partner[i]` = the other square of the domino on `i`) as
 * one letter per square: L/R for the left/right half of a horizontal domino, T/B for
 * the top/bottom half of a vertical one.
 */
export function encodeLayout(partner: ArrayLike<number>, w: number): string {
  let s = '';
  for (let i = 0; i < partner.length; i++) {
    const p = partner[i];
    s += p === i + 1 ? 'L' : p === i - 1 ? 'R' : p === i + w ? 'T' : p === i - w ? 'B' : '.';
  }
  return s;
}

/** The placements of an encoded layout, or null when the string is malformed. */
export function decodeLayout(aux: string, w: number, h: number): number[] | null {
  if (aux.length !== w * h) return null;
  const out: number[] = [];
  for (let i = 0; i < aux.length; i++) {
    const c = aux[i];
    if (c === 'L') {
      if (aux[i + 1] !== 'R' || i % w === w - 1) return null;
      out.push(2 * i + 1);
    } else if (c === 'T') {
      if (aux[i + w] !== 'B') return null;
      out.push(2 * i);
    } else if (c !== 'R' && c !== 'B') {
      return null;
    }
  }
  return out;
}

/**
 * Count how many dominoes of each kind the player has laid. `partner[i]` is the other
 * square of the domino covering `i`, or `i` itself when the square is bare.
 */
export function countDominoes(
  partner: ArrayLike<number>,
  numbers: ArrayLike<number>,
  n: number,
): Uint8Array {
  const used = new Uint8Array(dominoCount(n));
  for (let i = 0; i < partner.length; i++) {
    const j = partner[i];
    if (j > i) {
      const d = dominoIndex(numbers[i], numbers[j]);
      if (used[d] < 2) used[d]++;
    }
  }
  return used;
}

/** A tiling is complete when every domino of the set is used exactly once. */
export function isComplete(partner: ArrayLike<number>, numbers: ArrayLike<number>, n: number) {
  const used = countDominoes(partner, numbers, n);
  let distinct = 0;
  for (let d = 0; d < used.length; d++) if (used[d]) distinct++;
  return distinct === dominoCount(n);
}
