/**
 * Pearl (Masyu) board model shared by the game, the solver and the generator.
 *
 * Every square holds a bitmask of the directions its loop segments leave in: `R`, `U`,
 * `L`, `D`. A square the loop passes straight through is `LR` or `UD`; a corner is one of
 * `LU`, `LD`, `RU`, `RD`; an empty square is `BLANK`. Lines are stored in both squares
 * they join, so a segment between (x, y) and (x + 1, y) sets `R` in the first and `L` in
 * the second. "No line here" marks use the same encoding.
 *
 * Clues: `CORNER` (a black pearl: the loop turns here and runs straight through both
 * neighbours along the loop) and `STRAIGHT` (a white pearl: the loop runs straight
 * through and turns in at least one of the neighbours along the loop).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export const NOCLUE = 0;
export const CORNER = 1;
export const STRAIGHT = 2;

export const R = 1;
export const U = 2;
export const L = 4;
export const D = 8;
export const DIRS = [R, U, L, D] as const;

export const BLANK = 0;
export const LR = L | R;
export const UD = U | D;
export const LU = L | U;
export const LD = L | D;
export const RU = R | U;
export const RD = R | D;
/** The seven possible states of a square: two straights, four corners, empty. */
export const STATES = [BLANK, RU, LR, LU, RD, UD, LD] as const;

/** Bit sets over the states above (`1 << state`). */
export const bBLANK = 1 << BLANK;
export const bSTRAIGHT = (1 << LR) | (1 << UD);
export const bCORNER = (1 << LU) | (1 << LD) | (1 << RU) | (1 << RD);
export const bANY = bBLANK | bSTRAIGHT | bCORNER;

export function dx(d: number): number {
  return d === R ? 1 : d === L ? -1 : 0;
}
export function dy(d: number): number {
  return d === D ? 1 : d === U ? -1 : 0;
}
/** The opposite direction. */
export function flip(d: number): number {
  return ((d << 2) | (d >> 2)) & 0xf;
}
/** The direction 90° clockwise. */
export function cw(d: number): number {
  return ((d << 3) | (d >> 1)) & 0xf;
}
/** The direction 90° anticlockwise. */
export function acw(d: number): number {
  return ((d << 1) | (d >> 3)) & 0xf;
}
const NBITS = [0, 1, 1, 2, 1, 2, 2, 3, 1, 2, 2, 3, 2, 3, 3, 4];
export function bitCount(mask: number): number {
  return NBITS[mask & 0xf];
}
export function isStraight(state: number): boolean {
  return state === LR || state === UD;
}
export function isCorner(state: number): boolean {
  return (bCORNER >> state) & 1 ? true : false;
}

// ------------------------------------------------------------- description format

/**
 * Parse a description: `B` is a black pearl, `W` a white one, a lower-case letter a
 * run of 1–26 empty squares. Returns an error message when the text does not describe
 * exactly `w × h` squares.
 */
export function parseDesc(desc: string, w: number, h: number): Uint8Array | string {
  const n = w * h;
  const clues = new Uint8Array(n);
  let i = 0;
  for (const c of desc) {
    if (c >= 'a' && c <= 'z') {
      i += c.charCodeAt(0) - 96;
    } else if (c === 'B' || c === 'W') {
      if (i < n) clues[i] = c === 'B' ? CORNER : STRAIGHT;
      i++;
    } else {
      return tx`Unrecognised character in game description`;
    }
  }
  if (i > n) return tx`Game description is too long`;
  if (i < n) return tx`Game description is too short`;
  return clues;
}

/** Encode a clue array in the description format. */
export function encodeDesc(clues: Uint8Array): string {
  let out = '';
  let run = 0;
  const flush = () => {
    while (run > 0) {
      const k = Math.min(run, 26);
      out += String.fromCharCode(96 + k);
      run -= k;
    }
  };
  for (const c of clues) {
    if (c === NOCLUE) {
      run++;
    } else {
      flush();
      out += c === CORNER ? 'B' : 'W';
    }
  }
  flush();
  return out;
}

/** A line array as one hex digit per square (the `aux` solver hint). */
export function encodeLines(lines: Uint8Array): string {
  let s = '';
  for (const v of lines) s += v.toString(16).toUpperCase();
  return s;
}

export function decodeLines(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n || !/^[0-9A-Fa-f]*$/.test(aux)) return null;
  const lines = new Uint8Array(n);
  for (let i = 0; i < n; i++) lines[i] = parseInt(aux[i], 16);
  return lines;
}

// ------------------------------------------------------------- clues from a loop

/**
 * Every clue the loop `lines` supports: a white pearl on each straight next to a
 * corner along the loop, a black pearl on each corner between two straights.
 */
export function maximalClues(w: number, h: number, lines: Uint8Array): Uint8Array {
  const clues = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const type = lines[y * w + x];
      if (isStraight(type)) {
        for (const d of DIRS) {
          if (!(type & d)) continue;
          if (isCorner(lines[(y + dy(d)) * w + x + dx(d)])) {
            clues[y * w + x] = STRAIGHT;
            break;
          }
        }
      } else if (isCorner(type)) {
        let ok = true;
        for (const d of DIRS) {
          if (type & d && !isStraight(lines[(y + dy(d)) * w + x + dx(d)])) ok = false;
        }
        if (ok) clues[y * w + x] = CORNER;
      }
    }
  }
  return clues;
}

// ------------------------------------------------------------- completion check

/** Error flag for "this pearl's rule is broken" (line directions use bits 0–3). */
export const ERROR_CLUE = 16;

export interface Check {
  /** Per square: line directions in error (bits 0–3) plus `ERROR_CLUE`. */
  errors: Uint8Array;
  /** A single closed loop through every pearl with no rule broken. */
  complete: boolean;
}

/**
 * Check a position the way the original does: if any closed loop exists, every line
 * off it and every pearl not on it is wrong; a square may have at most two lines; and
 * every pearl's rule must hold for the lines around it.
 */
export function checkGrid(w: number, h: number, clues: Uint8Array, lines: Uint8Array): Check {
  const n = w * h;
  const errors = new Uint8Array(n);
  let hadError = false;
  const err = (i: number, e: number) => {
    hadError = true;
    errors[i] |= e;
  };
  const inGrid = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h;

  // Join squares along their (reciprocal) lines; the first cycle found is "the" loop.
  const dsf = new DSF(n);
  let loopClass = -1;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const a = y * w + x;
      for (const d of [R, D]) {
        if (!(lines[a] & d)) continue;
        const bx = x + dx(d);
        const by = y + dy(d);
        if (!inGrid(bx, by)) continue;
        const b = by * w + bx;
        if (!(lines[b] & flip(d))) continue;
        if (dsf.same(a, b)) {
          if (loopClass === -1) loopClass = dsf.find(a);
        } else {
          dsf.merge(a, b);
        }
      }
    }
  }
  if (loopClass !== -1) {
    loopClass = dsf.find(loopClass);
    for (let i = 0; i < n; i++) {
      if (lines[i] === BLANK) {
        if (clues[i] !== NOCLUE) err(i, ERROR_CLUE);
      } else if (dsf.find(i) !== loopClass) {
        err(i, lines[i]);
      }
    }
  }

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      const type = lines[i];
      if (bitCount(type) > 2) err(i, type);
      const clue = clues[i];
      if (clue === CORNER) {
        if (isStraight(type)) err(i, ERROR_CLUE);
        for (const d of DIRS) {
          if (!(type & d)) continue;
          const xx = x + dx(d);
          const yy = y + dy(d);
          if (!inGrid(xx, yy)) err(i, d);
          else if (isCorner(lines[yy * w + xx])) err(i, ERROR_CLUE);
        }
      } else if (clue === STRAIGHT) {
        if (isCorner(type)) err(i, ERROR_CLUE);
        let straights = 0;
        for (const d of DIRS) {
          if (!(type & d)) continue;
          const xx = x + dx(d);
          const yy = y + dy(d);
          if (!inGrid(xx, yy)) err(i, d);
          else if (isStraight(lines[yy * w + xx])) straights++;
        }
        if (straights >= 2 && bitCount(type) >= 2) err(i, ERROR_CLUE);
      }
    }
  }
  return { errors, complete: !hadError && loopClass !== -1 };
}
