import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { FillingState, FillingUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** The 3×3 walkthrough puzzle, `. . 2 / 2 . . / 1 3 1`, whose only solution is
 *  `2 3 2 / 2 3 2 / 1 3 1`: four empty squares, filled in three fills. */
const GAME_ID = '3x3:002200131';

/** Squares of the walkthrough grid, by position. */
const TOP_LEFT = 0;
const TOP_MID = 1;
const TOP_RIGHT = 2;
const MID = 4;
const MID_RIGHT = 5;

const cell = (state: FillingState, xy: number, t: number, cells = 1, rows = 1): TutorialRect =>
  cellRect(xy % state.w, Math.floor(xy / state.w), t, border(t), cells, rows);
const centre = (state: FillingState, xy: number, t: number) =>
  cellCentre(xy % state.w, Math.floor(xy / state.w), t, border(t));

export const tutorial: Tutorial<FillingState, FillingUI> = {
  steps: [
    {
      gameId: GAME_ID,
      text: 'Write a digit in every empty square so that each connected block of equal digits covers exactly as many squares as the digit says.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The **3** at the foot of the middle column can only grow upwards, so its block is that column. **Drag** from the top square of it down to the middle one, then press **3**.',
      textTouch:
        'The **3** at the foot of the middle column can only grow upwards. **Drag** from the top square of it down to the middle one, then tap **3** on the keypad.',
      target: '[data-key="3"]',
      highlight: ({ state, tileSize }) => cell(state, TOP_MID, tileSize, 1, state.h),
      pointer: ({ state, tileSize }) => ({
        ...centre(state, TOP_MID, tileSize),
        to: centre(state, MID, tileSize),
      }),
      press: '3',
      waitFor: ({ state }) => state.board[TOP_MID] === 3 && state.board[MID] === 3,
    },
    {
      text: 'The **2** in the left column needs one partner and the square above it is the only one free. Click that square and press **2**.',
      textTouch:
        'The **2** in the left column needs one partner and the square above it is the only one free. Tap that square, then tap **2** on the keypad.',
      target: '[data-key="2"]',
      highlight: ({ state, tileSize }) => cell(state, TOP_LEFT, tileSize, 1, 2),
      pointer: ({ state, tileSize }) => centre(state, TOP_LEFT, tileSize),
      press: '2',
      waitFor: ({ state }) => state.board[TOP_LEFT] === 2,
    },
    {
      text: 'One square left. Click it and press **1** to see what a wrong digit looks like.',
      textTouch:
        'One square left. Tap it, then tap **1** on the keypad to see what a wrong digit looks like.',
      target: '[data-key="1"]',
      highlight: ({ state, tileSize }) => cell(state, MID_RIGHT, tileSize),
      pointer: ({ state, tileSize }) => centre(state, MID_RIGHT, tileSize),
      press: '1',
      waitFor: ({ state }) => state.board[MID_RIGHT] === 1,
    },
    {
      text: 'Red means impossible: those two **1**s touch, which would make a block of two, and the **2** at the top is walled in. That square is still selected, so press **Backspace** to empty it.',
      textTouch:
        'Red means impossible: those two **1**s touch, which would make a block of two, and the **2** at the top is walled in. That square is still selected, so tap **⌫** on the keypad to empty it.',
      target: '[data-key="backspace"]',
      highlight: ({ state, tileSize }) => cell(state, TOP_RIGHT, tileSize, 1, state.h),
      pointer: ({ state, tileSize }) => centre(state, MID_RIGHT, tileSize),
      press: '',
      waitFor: ({ state }) => state.board[MID_RIGHT] === 0,
    },
    {
      text: 'That empty square pairs up with the **2** above it instead. Click it and press **2** to finish the grid.',
      textTouch:
        'That empty square pairs up with the **2** above it instead. Tap it, then tap **2** on the keypad to finish the grid.',
      target: '[data-key="2"]',
      highlight: ({ state, tileSize }) => cell(state, TOP_RIGHT, tileSize, 1, 2),
      pointer: ({ state, tileSize }) => centre(state, MID_RIGHT, tileSize),
      press: '2',
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Filled. Heavy lines close in each finished block; **right-click** adds squares to a selection one at a time, and **Undo** takes a fill back.',
      target: '[data-cmd="undo"]',
    },
  ],
};
