/**
 * Appended for games that declare a keypad, so the help explains the row of keys under
 * the board. Written in finger words for touch and pointer words otherwise, because the
 * keypad is always there on a touch screen and behind a switch with a mouse.
 */
function keypadHelp(game: Game, touch: boolean): string {
  if (!game.keypad) return '';
  let spec: ReturnType<NonNullable<Game['keypad']>>;
  try {
    spec = game.keypad(game.defaultParams());
  } catch {
    return '';
  }
  if (!spec?.keys.length) return '';
  const intro = t(touch ? 'ui.help.keypad.introTouch' : 'ui.help.keypad.introPointer');
  return (
    `\n## ${t('ui.help.keypad.heading')}\n\n- ${intro}${t('ui.help.keypad.select')}` +
    (spec.clear ? `\n${t('ui.help.keypad.clear')}` : '') +
    (spec.pencil ? `\n${t('ui.help.keypad.pencil')}` : '') +
    '\n'
  );
}

/**
 * Slugs of the shell's own help documents, so a locale can translate them the same way it
 * translates a game's `help.md`: `src/i18n/help/<locale>/_common.md` and `_touch.md`.
 */
