/**
 * Copy the values the player typed in the *localised* copy of the config rows back onto
 * the game's own rows, so `customParams` never sees a translated label.
 */
function mergeConfig(target: ConfigItem[], edited: ConfigItem[]): ConfigItem[] {
  return target.map((item, i) => {
    const e = edited[i];
    if (!e || e.type !== item.type) return item;
    if (item.type === 'choices' && e.type === 'choices') return { ...item, selected: e.selected };
    if (item.type === 'string' && e.type === 'string') return { ...item, value: e.value };
    if (item.type === 'boolean' && e.type === 'boolean') return { ...item, value: e.value };
    return item;
  });
}

