// ---------------------------------------------------------------- end of game

/** Which way the puzzle ended. `Game.status()` returns 1 for the first, -1 for the second. */
export type EndgameKind = 'won' | 'lost';

/** What a button on the end-of-game panel does. None of them is ever an ad trigger. */
export type EndgameAction = 'next' | 'retry' | 'undo' | 'menu';

/**
 * How the puzzle went, taken the moment it ended — before anyone can undo into it — for
 * the results on the end-of-game panel. Absent for a board that was already over when it
 * was put back after a reload: its time on screen would be the time since the reload.
 */
export interface EndgameResult {
  secs: number;
  moves: number;
  hints: number;
  /** 3 by hand without a hint, 2 inside the hint allowance, 1 otherwise; 0 for a loss. */
  stars: number;
  /** The best time for this puzzle and preset, once this finish is on the books. */
  best?: number;
  /** This finish beat a best that was already there. */
  newBest: boolean;
}

/** The star rating for a win, from how much help it took. Pure, for the tests. */
export function starsFor(hints: number, byPlayer: boolean, forfeited: boolean): number {
  if (hints === 0 && !forfeited && byPlayer) return 3;
  return byPlayer ? 2 : 1;
}

/** The drawn star on the results: a five-pointed star inked slightly off true. */
const STAR_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.6 14.8 8.7 21.3 9.3 16.4 13.6 17.9 20.1 12.1 16.7 6.2 20.2 7.6 13.7 2.6 9.4 9.2 8.6Z" fill="currentColor" stroke="var(--c-ink)" stroke-width="1.7" stroke-linejoin="round"/></svg>';

export interface EndgamePlan {
  kind: EndgameKind;
  /** True when this win put a credit in the player's pocket, so the panel can say so. */
  credited: boolean;
  /** How long after the state turned the panel should appear. */
  delayMs: number;
  primary: EndgameAction;
  secondary: EndgameAction;
}

/**
 * How long the panel waits, so it reads as the next beat of the celebration rather than
 * stepping on it.
 *
 * - `credited`: the confetti burst has peaked (it flies outwards for 0.7s) and the "+1
 *   credit" label is on its way to the star counter — and this is still comfortably
 *   before the midgame ad request at 1.8s (see docs/CRAZYGAMES.md), so the panel is on
 *   screen and read before the platform ever takes over.
 * - `won`: no confetti, just the board's own moment (`celebrateBoard`: the sheet lifts and
 *   a ring spreads from the last move), which has done its work by 0.7s and fades out
 *   under the panel as it rises; inside the tutorial, the little `pulse`, over at 0.36s.
 * - `lost`: after the board's `shake`, which lasts 0.5s.
 */
export const ENDGAME_DELAY_MS = { credited: 1100, won: 700, lost: 650 } as const;

/**
 * How long after the win chime the credit's own little ping follows. Long enough to read as
 * a second beat rather than a chord, and over well before the panel arrives.
 */
const CREDIT_SOUND_DELAY_MS = 340;

/**
 * How long the completion celebration gets to itself before the platform is offered an
 * interstitial. Long enough that the confetti, the chime and the credit floating up to the
 * counter are all over; short enough to still read as part of finishing the puzzle.
 */
const MIDGAME_AD_DELAY_MS = 1800;
/** How long without a move on a fresh board before Hint offers itself (`checkStuck`). */
const STUCK_AFTER_MS = 45_000;
/** At most this many of those nudges a visit: a reminder, not a nag. */
const STUCK_NUDGES_PER_VISIT = 2;
let stuckNudges = 0;

/**
 * What the end-of-game panel should offer, decided from the terminal state the midend
 * reports. Pure, and kept out of the DOM code so it can be unit-tested on its own.
 *
 * `status` is `Game.status(state)` (0 while the puzzle is still in play), `credited` says
 * whether this win just earned a credit, and `canRestart` whether there is any history to
 * restart to (`Midend.restart()` does nothing without one). `undoLoss` is the game's
 * `flags.undoAfterLoss`: a loss that one Undo takes back.
 */
export function endgamePlan(
  status: GameStatus,
  credited: boolean,
  canRestart: boolean,
  undoLoss = false,
  lossReveals = false,
): EndgamePlan | null {
  if (status === 0) return null;
  if (status === 1) {
    return {
      kind: 'won',
      credited,
      delayMs: credited ? ENDGAME_DELAY_MS.credited : ENDGAME_DELAY_MS.won,
      primary: 'next',
      secondary: 'menu',
    };
  }
  if (undoLoss && canRestart) {
    // Taking the fatal move back keeps everything played before it; starting over is
    // still there for a player who would rather.
    return {
      kind: 'lost',
      credited: false,
      delayMs: ENDGAME_DELAY_MS.lost,
      primary: 'undo',
      secondary: 'retry',
    };
  }
  if (lossReveals) {
    return {
      kind: 'lost',
      credited: false,
      delayMs: ENDGAME_DELAY_MS.lost,
      primary: 'next',
      secondary: 'menu',
    };
  }
  return {
    kind: 'lost',
    credited: false,
    delayMs: ENDGAME_DELAY_MS.lost,
    // Trying again is the point of a loss; with nothing to restart to, a fresh puzzle is
    // the only honest offer.
    primary: canRestart ? 'retry' : 'next',
    secondary: canRestart ? 'next' : 'menu',
  };
}

/**
 * The preset a win on preset `which` (of `count`) points on to, or -1 for none: the next
 * one in the game's list, which runs from the smallest and gentlest up. Nothing after the
 * last, nor from a custom size (`which` < 0), which has no place in the list to go on from.
 */
export function stepUpPreset(which: number, count: number): number {
  return which >= 0 && which + 1 < count ? which + 1 : -1;
}

/** Breathing room between the board and the panel, whichever side of it the panel is on. */
const ENDGAME_GAP = 10;
/**
 * How wide the panel stands when it is beside the board rather than under it. Wide enough
 * for the heading and a column of two buttons, and no wider: every pixel of it is one the
 * board could have had instead.
 */
const ENDGAME_ASIDE_W = 260;
/**
 * The narrowest it may stand. A phone on its side has ~400px of stage beside its rail, and
 * at the full width the column cost more board than the strip underneath did, so the panel
 * went under a 320px-tall board and shrank it to half. Beside it, at this width, the board
 * keeps most of its size.
 */
const ENDGAME_ASIDE_MIN_W = 168;

export interface GameViewHandle {
  destroy(): void;
  midend: Midend;
  /** Whether the board on show is a tutorial's, which is never the player's game. */
  readonly tutorialActive: boolean;
}

/** Mount the play page for `game` into `root`. `gameId` optionally preselects a puzzle. */
export function renderGameView(
  root: HTMLElement,
  game: Game,
  gameId: string | null,
): GameViewHandle {
  const name = gameName(game);
  document.title = t('ui.pageTitle', { name });
  const touch = isTouch();
  // The tutorial's first step loads its own fixed puzzle, so when it is about to
  // auto-start there is no point generating (and animating in) a random board first —
  // the player would see it flash on screen for an instant before the tutorial replaces
  // it. Computed once and reused everywhere this decision matters.
  const willAutoStartTutorial = !!game.tutorial && !gameId && !tutorialSeen(game.id);
  const page = el('div', 'game-page');
  // The play page never scrolls: the board is fitted to whatever is left over.
  document.documentElement.classList.add('playing');

  // ---- header
  const header = el('header', 'topbar');
  const back = backButton();
  const title = el('h1', 'title', name);
  // A round question mark, like the way back beside it and the HUD under it. The word is
  // still in the button, hidden from the eye, so it is called "Help", and it is its tooltip.
  const helpBtn = el('button', 'btn help-btn round-btn has-glyph');
  const helpGlyph = el('span', 'btn-glyph', '?');
  helpGlyph.setAttribute('aria-hidden', 'true');
  helpBtn.append(helpGlyph, el('span', 'btn-text', t('ui.topbar.help')));
  helpBtn.type = 'button';
  helpBtn.title = t('ui.topbar.help');
  // The credits as the menu's resource bar counts them: a star coin and the number.
  const chip = el('a', 'credits-chip');
  chip.href = '#/';
  chip.title = t('ui.topbar.creditsTitle');
  const chipCoin = el('span', 'chip-icon');
  chipCoin.setAttribute('aria-hidden', 'true');
  chipCoin.innerHTML = STAR_COIN_SVG;
  const chipNum = el('b', undefined, String(getProgress().credits));
  chip.append(chipCoin, chipNum);
  // Read out as "★ 3 credits" rather than a bare star and a number.
  const labelChip = (n: number) =>
    chip.setAttribute('aria-label', t('ui.menu.stat.credits', { n }));
  labelChip(getProgress().credits);
  // The puzzle's size and difficulty, under its name: the Type menu lives in the pause menu,
  // where nobody looks for it, so the play page says what is being played and a click on it
  // opens the same list. Pencil text, not a button, so the HUD stays as bare as it was. A
  // real select laid over the words, transparent: the platform's own picker on a phone, the
  // keyboard and the console selector for free.
  const presetPick = el('label', 'preset-pick');
  const presetWord = el('span', 'preset-name');
  presetWord.setAttribute('aria-hidden', 'true');
  const presetSelect = el('select', 'preset-select');
  presetSelect.setAttribute('aria-label', t('ui.toolbar.type'));
  presetPick.append(presetWord, presetSelect);
  presetPick.hidden = game.presets.length === 0 && !game.configure;
  const titleBlock = el('div', 'title-block');
  titleBlock.append(title, presetPick);
  header.append(back, titleBlock, el('div', 'spacer'), chip, helpBtn);

  // ---- toolbar
  const toolbar = el('div', 'toolbar');
  const typeLabel = el('label', 'type-select');
  typeLabel.append(el('span', undefined, t('ui.toolbar.type')));
  const typeSelect = el('select', 'sketch-input');
  typeLabel.append(typeSelect);
  /**
   * A toolbar button. `glyph` is the wordless face a compact toolbar shows in place of the
   * label: the label stays in the button — visually hidden, so it is still the button's
   * accessible name — and the glyph is `aria-hidden`, so a screen reader reads one word
   * rather than a symbol and a word.
   */
  const mk = (label: string, cmd: string, title?: string, glyph?: string) => {
    const b = el('button', 'btn');
    b.type = 'button';
    b.dataset.cmd = cmd;
    if (glyph) {
      const g = el('span', 'btn-glyph', glyph);
      g.setAttribute('aria-hidden', 'true');
      b.append(g);
      b.classList.add('has-glyph');
    }
    b.append(el('span', 'btn-text', label));
    if (title) b.title = title;
    return b;
  };
  /** Retitle a button built by `mk` without losing its glyph. */
  const setLabel = (b: HTMLElement, label: string) => {
    b.querySelector('.btn-text')!.textContent = label;
  };
  const btnNew = mk(t('ui.toolbar.new'), 'new', t('ui.toolbar.newTitle'));
  const btnRestart = mk(t('ui.toolbar.restart'), 'restart', t('ui.toolbar.restartTitle'));
  // The two buttons a player wears out, and the two whose meaning a symbol carries
  // everywhere: on a phone they shrink to the arrow and keep the word for the screen
  // reader, which is what makes room for the preset menu beside them.
  const btnUndo = mk(t('ui.toolbar.undo'), 'undo', t('ui.toolbar.undoTitle'), '↶');
  const btnRedo = mk(t('ui.toolbar.redo'), 'redo', t('ui.toolbar.redoTitle'), '↷');
  const btnHint = mk(
    t('ui.toolbar.hint'),
    'hint',
    t('ui.toolbar.hintTitle', { n: Midend.HINT_ALLOWANCE }),
  );
  btnHint.classList.add('hint');
  squeezeGlyph(btnHint, HINT_GLYPH);
  const btnSolve = mk(t('ui.toolbar.solve'), 'solve', t('ui.toolbar.solveTitle'));
  // The one button here that ends the puzzle rather than changing it. It keeps its place
  // in the running order — the compact tiers are built from that — but it is set apart
  // from the commands either side of it, so it is not simply the next button along from
  // Redo. See `.btn.solve` in styles.css.
  btnSolve.classList.add('solve');
  const btnId = mk(t('ui.toolbar.gameId'), 'id', t('ui.toolbar.gameIdTitle'));
  const btnTap = mk(t('ui.toolbar.tapPlace'), 'tap-mode', t('ui.toolbar.tapTitle'));
  btnTap.classList.add('tap-mode');
  // Both faces, one shown per mode (`toolbar.css`), so a squeezed switch still says which
  // way round it is.
  squeezeGlyph(btnTap, TAP_PLACE_GLYPH + TAP_MARK_GLYPH);
  const btnKeypad = mk(t('ui.toolbar.keypad'), 'keypad-toggle', t('ui.toolbar.keypadTitle'));
  btnKeypad.classList.add('keypad-toggle');
  // A sign in the toolbar, where the pair reads as one control and there is no room for
  // words; the word itself in the More sheet, among a column of words, and as the
  // accessible name in both.
  const zoomOut = mk(
    t('ui.toolbar.zoomOutTitle'),
    'zoom-out',
    t('ui.toolbar.zoomOutTitle'),
    t('ui.toolbar.zoomOut'),
  );
  const zoomIn = mk(
    t('ui.toolbar.zoomInTitle'),
    'zoom-in',
    t('ui.toolbar.zoomInTitle'),
    t('ui.toolbar.zoomIn'),
  );
  zoomOut.classList.add('zoom');
  zoomIn.classList.add('zoom');
  // The way to the preferences — sound and its volume, the language, motion — which used
  // to be a loose speaker button here. It sits apart from the puzzle buttons, with the zoom
  // pair, and opens the Settings card over the pause menu (settings.ts).
  const btnSettings = mk(t('ui.settings.title'), 'settings', t('ui.settings.title'));
  btnSettings.classList.add('settings-open', 'has-glyph');
  btnSettings.setAttribute('aria-haspopup', 'dialog');
  const gearGlyph = el('span', 'btn-glyph');
  gearGlyph.setAttribute('aria-hidden', 'true');
  gearGlyph.innerHTML = GEAR_SVG;
  btnSettings.prepend(gearGlyph);
  // Game-declared extras (a hint key, a display toggle): a button each, next to Solve,
  // since they are just as welcome with a mouse.
  const actionSpecs = game.actions ?? [];
  const actionBtns = actionSpecs.map((a) => {
    const actionId = actionIdOf(a);
    const b = el('button', 'btn action');
    b.type = 'button';
    b.dataset.action = actionId;
    const text = el('span', 'btn-text', actionLabel(game, actionId, a.label));
    b.append(text);
    if (a.title) b.title = actionTitle(game, actionId, a.title);
    // A HUD action with a drawn face wears only that face in the HUD, like Undo; in the
    // pause menu the glyph is hidden and the word does the talking.
    if (a.glyph) {
      const g = el('span', 'btn-glyph');
      g.setAttribute('aria-hidden', 'true');
      g.innerHTML = a.glyph;
      b.prepend(g);
      b.classList.add('has-glyph');
    }
    if (a.hud) b.classList.add('hud-action');
    if (a.pressed) b.setAttribute('aria-pressed', 'false');
    return b;
  });
  const hudActions = hudActionIds(game);
  // The way into the pause menu, always the last of the HUD's buttons. Still `more` inside
  // the shell (the id, the class, the sheet), which is what it has always been: the rest.
  const btnMore = mk(t('ui.toolbar.pause'), 'more', t('ui.toolbar.pauseTitle'));
  btnMore.classList.add('more', 'has-glyph');
  const pauseGlyph = el('span', 'btn-glyph');
  pauseGlyph.setAttribute('aria-hidden', 'true');
  pauseGlyph.innerHTML = PAUSE_GLYPH;
  btnMore.prepend(pauseGlyph);
  btnMore.setAttribute('aria-haspopup', 'dialog');
  btnMore.setAttribute('aria-expanded', 'false');
  btnMore.dataset.ctl = 'more';

  /**
   * Every toolbar control in the order a mouse sees it, each under the id `splitToolbar`
   * reads. This list is the single source of truth for both arrangements: the desktop row
   * is rebuilt straight from it, so a phone's two tiers can never leave a control behind.
   */
  const toolbarEntries: { id: string; el: HTMLElement }[] = [];
  const addControl = (id: string, node: HTMLElement) => {
    node.dataset.ctl = id;
    toolbarEntries.push({ id, el: node });
  };
  addControl('type', typeLabel);
  // On a phone the start of the toolbar is what fits without scrolling, so the tap-mode
  // switch goes first; on a mouse it is not there at all.
  if (touch && !game.flags?.oneButton) addControl('tap-mode', btnTap);
  addControl('new', btnNew);
  addControl('restart', btnRestart);
  addControl('undo', btnUndo);
  addControl('redo', btnRedo);
  // Beside Solve, and before it: it is the gentler of the two, and being first is what
  // keeps it in view when a landscape phone's single toolbar row has to scroll.
  if (game.hint) addControl('hint', btnHint);
  if (game.canSolve) addControl('solve', btnSolve);
  for (const b of actionBtns) addControl(`${ACTION_PREFIX}${b.dataset.action}`, b);
  // A touch device always gets the keypad, so the switch is only for pointers.
  if (game.keypad && !touch) addControl('keypad-toggle', btnKeypad);
  addControl('id', btnId);
  addControl('spacer', el('div', 'spacer'));
  addControl('settings', btnSettings);
  addControl('zoom-out', zoomOut);
  addControl('zoom-in', zoomIn);

  const controlById = new Map(toolbarEntries.map((e) => [e.id, e.el]));
  /**
   * The split, over the controls that are actually on show. A game action whose `when`
   * does not hold (Net's four scroll arrows off a wrapping grid, Flood's hint on a
   * finished board) is hidden, and counting it would give a rail's rows to buttons nobody
   * can see — pushing Share and Settings behind More with room to spare, or
   * splitting Net's arrows three in the rail and one in the sheet.
   */
  const visibleTiers = () =>
    splitToolbar(
      toolbarEntries.filter((e) => !e.el.hidden).map((e) => e.id),
      hudActions,
    );
  /**
   * The second tier. It lives inside the toolbar (hidden) while the sheet is closed, so
   * the controls in it stay connected to the document.
   */
  const overflowGroup = el('div', 'toolbar-overflow');
  overflowGroup.hidden = true;
  overflowGroup.setAttribute('role', 'group');
  overflowGroup.setAttribute('aria-label', t('ui.toolbar.more'));

  /** Which arrangement is on screen, so a resize only rebuilds on a real change. */
  let toolbarArrangement: string | null = null;
  let moreSheet: ModalHandle | null = null;

  /**
   * Mark where each family starts, and which controls share a row, on whatever is in the
   * toolbar now. Cheap, and run after every arrangement, because a game action coming into
   * view or going (Flood's hint on a finished grid) moves both.
   */
  function markGroups() {
    const shown = [...toolbar.children].filter(
      (n): n is HTMLElement =>
        n instanceof HTMLElement && !!n.dataset.ctl && n.dataset.ctl !== 'spacer' && !n.hidden,
    );
    const plan = railPlan(shown.map((n) => n.dataset.ctl!));
    shown.forEach((n, i) => {
      n.classList.toggle('group-start', plan.starts[i]);
      if (plan.runs[i] >= 0) n.dataset.run = String(RAIL_ROW_RUNS[plan.runs[i]].length);
      else delete n.dataset.run;
    });
    for (const n of overflowGroup.children) {
      (n as HTMLElement).classList.remove('group-start');
      delete (n as HTMLElement).dataset.run;
    }
  }

  /**
   * Put the HUD's buttons in the toolbar and everything else behind the pause button. The
   * split is the same on every screen; what the viewport still decides is the shape the
   * chrome stands in (`.railed`: beside the board rather than above it). Both halves are
   * built from `toolbarEntries`, so a re-split is a re-parenting of the same buttons:
   * their state, their listeners and the player's place in the puzzle all survive it.
   */
  function syncToolbarTier() {
    // Which shape the chrome is in comes first: the header is part of the rail, and the
    // stage is measured against both.
    const railed = isSideRail();
    page.classList.toggle('railed', railed);
    const tiers = visibleTiers();
    const arrangement = `${railed ? 'rail' : 'band'}|${tiers.overflow.join(',')}`;
    if (arrangement === toolbarArrangement) {
      markGroups();
      return;
    }
    toolbarArrangement = arrangement;
    closeMoreSheet();
    // Hidden controls stay where they are, where they cost nothing; if one comes back into
    // view, `updateToolbar` asks for the split again.
    const behind = new Set(tiers.overflow);
    overflowGroup.replaceChildren(...tiers.overflow.map((id) => controlById.get(id)!));
    toolbar.replaceChildren(
      ...toolbarEntries.filter((e) => e.id !== 'spacer' && !behind.has(e.id)).map((e) => e.el),
      btnMore,
      overflowGroup,
    );
    page.classList.add('toolbar-tiered', 'hud');
    markGroups();
  }

  /**
   * The phone's one-row toolbar is built to fit in English, but 25 languages are not one
   * width: "Πάτημα: τοποθέτηση" and "Подсказка" pushed Hint under the pinned More button in
   * most of them. When the row with words does not fit, the tap switch and Hint wear their
   * symbols too, as Undo and Redo always do there — the words stay as the accessible names
   * and the tooltips. Measured with the words in place every time, so it cannot latch.
   */
  function syncSqueeze() {
    const row = page.classList.contains('toolbar-tiered') && !page.classList.contains('railed');
    page.classList.remove('toolbar-squeezed', 'toolbar-squeeze-hint', 'toolbar-squeeze-tap');
    if (!row || !toolbar.isConnected) return;
    const over = () => toolbar.scrollWidth > toolbar.clientWidth;
    if (!over()) return;
    // The HUD (hud.css) already shows these two as symbols; this remains the fallback for
    // a row that still carries a word. One symbol at a time — Hint first, a bulb saying
    // "hint" on its own, then the tap switch — and only a row that fits with neither word
    // loses both.
    const inRow = (b: HTMLElement) => toolbar.contains(b) && !b.hidden;
    for (const [cls, b] of [
      ['toolbar-squeeze-hint', btnHint],
      ['toolbar-squeeze-tap', btnTap],
    ] as const) {
      if (!inRow(b)) continue;
      page.classList.add(cls);
      if (!over()) return;
      page.classList.remove(cls);
    }
    page.classList.add('toolbar-squeezed');
  }

  /** Park the second tier back in the toolbar, out of sight. */
  function parkOverflow() {
    page.classList.remove('paused');
    midend.setPaused(false);
    menuPaused = false;
    syncRunClock();
    overflowGroup.hidden = true;
    if (toolbarArrangement) toolbar.append(overflowGroup);
    btnMore.setAttribute('aria-expanded', 'false');
  }

  /**
   * The pause menu: the rest of the controls, over a board that is blurred out of sight
   * and a clock that stands still until the player comes back. It is the same buttons the
   * toolbar holds while it is shut, plus the two ways off the page — the rules and the
   * collection — which on a HUD have nowhere else to be but the header.
   */
  function openMoreSheet() {
    if (moreSheet) return;
    const sheet = openModal(t('ui.pause.title'), () => {
      if (moreSheet !== sheet) return;
      moreSheet = null;
      parkOverflow();
    });
    moreSheet = sheet;
    sheet.root.classList.add('more-sheet', 'pause-menu');
    page.classList.add('paused');
    midend.setPaused(true);
    menuPaused = true;
    syncRunClock();
    // The same delegated handler the toolbar uses: the buttons are the toolbar's own, they
    // have simply moved house for as long as the sheet is up.
    sheet.body.addEventListener('click', onToolbarClick);
    const resume = el('button', 'btn more-done', t('ui.pause.resume'));
    resume.type = 'button';
    resume.addEventListener('click', () => {
      closeMoreSheet();
      canvas.focus({ preventScroll: true });
    });
    overflowGroup.hidden = false;
    const leave = el('div', 'pause-leave');
    const rules = el('button', 'btn', t('ui.topbar.help'));
    rules.type = 'button';
    rules.addEventListener('click', () => {
      closeMoreSheet();
      toggleHelp(true);
    });
    const home = el('a', 'btn', t('ui.topbar.back'));
    home.href = '#/';
    leave.append(rules, home);
    sheet.body.append(resume, overflowGroup, leave);
    btnMore.setAttribute('aria-expanded', 'true');
    updateToolbar();
    // Settings shares its row with the zoom pair, and "Налаштування" is wider than the
    // half it gets on a small phone: a little smaller before it ends in "…".
    const settingsWord = btnSettings.querySelector<HTMLElement>('.btn-text');
    if (settingsWord) fitText(settingsWord, 0.75);
    resume.focus({ preventScroll: true });
  }

  function closeMoreSheet() {
    if (!moreSheet) return;
    const sheet = moreSheet;
    moreSheet = null;
    sheet.close();
    parkOverflow();
  }

  // ---- stage
  const stage = el('main', 'stage');
  stage.dataset.dealing = t('ui.stage.generating');
  const wrap = el('div', 'canvas-wrap');
  const glow = el('div', 'pointer-glow');
  glow.hidden = true;
  wrap.append(glow);
  const canvas = el('canvas', 'puzzle-canvas');
  canvas.tabIndex = 0;
  canvas.setAttribute('aria-label', t('ui.topbar.boardLabel', { name }));
  // A focus ring only for a board reached with Tab, whose key comes up on the board itself.
  canvas.addEventListener('keyup', (e) => {
    if (e.key === 'Tab') canvas.classList.add('tabbed');
  });
  canvas.addEventListener('blur', () => canvas.classList.remove('tabbed'));
  canvas.addEventListener('pointerdown', () => canvas.classList.remove('tabbed'));
  wrap.append(canvas);
  stage.append(wrap);

  // ---- status
  const statusRow = el('div', 'status-row');
  const statusText = el('div', 'statusbar');
  const badge = el('div', 'badge');
  statusRow.append(statusText, badge);

  /**
   * The status row never gets shorter while the window keeps its width. A line that
   * wraps onto a second one (Black Box's "Tap the corner button to check" arriving with
   * the last ball) shrank the stage and moved the board up under the finger reaching for
   * it; unmarking a ball then dropped it back down. Once it has been two lines tall it
   * stays two lines tall, so the board moves at most once — and on an upright phone,
   * where two lines are reserved from the start (play.css), not at all. A new width
   * (turning the phone) starts over, since the text wraps differently there.
   */
  let statusFloor = 0;
  let statusFloorWidth = 0;
  function holdStatusFloor() {
    if (!statusRow.isConnected) return;
    if (window.innerWidth !== statusFloorWidth) {
      statusFloorWidth = window.innerWidth;
      statusFloor = 0;
      statusRow.style.minHeight = '';
    }
    const h = statusRow.offsetHeight;
    if (h > statusFloor) {
      statusFloor = h;
      statusRow.style.minHeight = `${h}px`;
    }
  }

  // ---- end-of-game panel
  // Parked in a strip at the bottom of the stage, right under the finished board rather
  // than over it (the board is refitted above it), so the obvious next move is where the
  // player is already looking instead of in the far corner of the toolbar.
  const endgame = el('div', 'endgame');
  endgame.hidden = true;
  endgame.setAttribute('role', 'region');
  endgame.setAttribute('aria-live', 'polite');
  const endCard = el('div', 'endgame-card');
  const endClose = el('button', 'endgame-close', '×');
  endClose.type = 'button';
  endClose.setAttribute('aria-label', t('ui.endgame.dismiss'));
  endClose.title = t('ui.endgame.dismiss');
  const endTitle = el('h2', 'endgame-title');
  const endNote = el('p', 'endgame-note');
  const endActions = el('div', 'endgame-actions');
  // Ziggy sits on the corner of the panel and has an opinion about how it went: he hops
  // for a win and slumps for a loss. The panel already says both of those in words, and
  // the words are what a screen reader gets (he is `aria-hidden`) — this is the same news
  // delivered by someone rather than by a heading.
  const endZig = el('span', 'endgame-ziggy');
  const endMascot = mountMascot(endZig);
  if (endMascot) endCard.append(endZig);
  // The results: a star rating, the numbers, and the best time. Filled in by
  // `showEndgame` for a finish that has just happened.
  const endResults = el('div', 'endgame-results');
  const endStars = el('div', 'endgame-stars');
  endStars.setAttribute('role', 'img');
  for (let i = 0; i < 3; i++) {
    const star = el('span', 'endgame-star');
    star.innerHTML = STAR_SVG;
    endStars.append(star);
  }
  const endStats = el('dl', 'endgame-stats');
  const endBest = el('p', 'endgame-best');
  endResults.append(endStars, endStats, endBest);
  // After a win, a quiet way on to the next preset up: the moment a player has just shown
  // this size is too easy is the one moment a harder one is welcome news rather than a
  // setting to go looking for.
  const endStep = el('button', 'endgame-step');
  endStep.type = 'button';
  endStep.hidden = true;
  endCard.append(endClose, endTitle, endNote, endResults, endActions, endStep);
  endgame.append(endCard);
  stage.append(endgame);

  // ---- on-screen keypad (games that are played by typing characters)
  // It is a flex row of its own under the status line, so the stage — and with it the
  // board — is laid out in whatever height is left.
  const keypadEl = el('div', 'keypad');
  keypadEl.hidden = true;
  keypadEl.setAttribute('role', 'group');
  keypadEl.setAttribute('aria-label', t('ui.keypad.label'));

  // ---- help drawer
  const drawer = el('aside', 'help-drawer');
  const drawerHead = el('div', 'drawer-head');
  // Ziggy stands at the head of the rules, the same character who walks the player through
  // them in the tutorial, and hops when the drawer is opened — the rules are being handed
  // over by someone. He is `aria-hidden`; the heading still says everything.
  const drawerTitle = el('div', 'drawer-title');
  const drawerZig = el('span', 'drawer-ziggy');
  const drawerMascot = mountMascot(drawerZig, { tilt: -8 });
  if (drawerMascot) drawerTitle.append(drawerZig);
  const drawerHeading = el('h2', undefined, t('ui.drawer.title', { name }));
  drawerHeading.id = 'help-drawer-title';
  drawerTitle.append(drawerHeading);
  drawer.setAttribute('aria-labelledby', drawerHeading.id);
  drawerHead.append(drawerTitle);
  const closeHelp = el('button', 'btn', t('ui.drawer.close'));
  closeHelp.type = 'button';
  drawerHead.append(closeHelp);
  const drawerBody = el('div', 'drawer-body');
  // A click in the rules gives them the keyboard (not the Tab order), so Space, the arrows
  // and Page Up/Down scroll the text the player is reading instead of moving on the board.
  drawerBody.tabIndex = -1;

  /**
   * Rebuild the drawer from the help documents for the active language. On touch devices
   * keyboard-only sections are dropped and mouse words become finger words, so the help
   * matches what the player can actually do.
   */
  function paintHelp(gameHelp: string, commonHelp: string, touchHelp: string) {
    drawerBody.innerHTML = renderMarkdown(
      gameHelp + '\n' + commonHelp + (touch ? touchHelp : '') + keypadHelp(game, touch),
      { dropKeyboard: touch, touch },
    );
    if (game.tutorial) {
      const replay = el('button', 'btn replay-tutorial', t('ui.drawer.replay'));
      replay.type = 'button';
      replay.addEventListener('click', () => startTutorial());
      drawerBody.prepend(replay);
    }
    // This puzzle's own badges, and how many are already on the shelf.
    const own = ACHIEVEMENTS.filter((x) => x.game?.id === game.id);
    if (own.length) {
      const link = el(
        'a',
        'btn drawer-achievements',
        t('ui.drawer.achievements', {
          n: own.filter((x) => isEarned(x.key)).length,
          total: own.length,
        }),
      );
      link.href = `#/achievements/${game.id}`;
      drawerBody.prepend(link);
    }
  }
  // Paint from what is already in hand (English, or a cached translation) and refresh
  // once this language's markdown files have loaded.
  paintHelp(
    helpNow(game.id, game.help),
    helpNow(COMMON_HELP_DOC, COMMON_HELP),
    helpNow(TOUCH_HELP_DOC, TOUCH_HELP),
  );
  if (getLocale() !== 'en') {
    const wanted = getLocale();
    Promise.all([
      loadHelp(game.id, game.help),
      loadHelp(COMMON_HELP_DOC, COMMON_HELP),
      loadHelp(TOUCH_HELP_DOC, TOUCH_HELP),
    ]).then(([a, b, c]) => {
      if (page.isConnected && getLocale() === wanted) paintHelp(a, b, c);
    });
  }
  drawer.append(drawerHead, drawerBody);
  gsap.set(drawer, { xPercent: drawerHiddenX() });
  // Parked off-screen is not the same as gone: without this its Close and "Replay the
  // tutorial" buttons stay in the tab order, so the first two Tab presses on the play page
  // land on controls nobody can see.
  drawer.inert = true;

  page.append(header, toolbar, stage, statusRow, keypadEl, drawer);
  root.append(page);
  syncToolbarTier();

  // ---- midend
  const drawing = new Drawing(canvas);
  // Measurement only: every call on it is a no-op when analytics is off (src/analytics).
  const stats = trackPuzzlePage(
    game.id,
    () => ({ params: game.encodeParams(midend.curParams, false), preset: midend.whichPreset() }),
    { tutorial: willAutoStartTutorial },
  );
  /** What the achievements need to know about the puzzle on the board. */
  const run = trackRun();
  // Its clock stands still behind the pause menu and behind an ad, as the help promises:
  // the results card's time and the quick-solve badges count time spent on the puzzle.
  let menuPaused = false;
  let adShowing = false;
  function syncRunClock() {
    run.pause(menuPaused || adShowing);
  }
  const unsubAdClock = onAdStateChange((on) => {
    adShowing = on;
    syncRunClock();
  });
  let zoom = 1;
  /** When the player last moved, so the status tag hops for a move and not for a deal. */
  let lastMoveAt = -Infinity;
  /** When the board last changed in any way (a deal included): see `checkStuck`. */
  let idleFrom = performance.now();
  /** The puzzle the stuck nudge was last given for, so one board gets it once. */
  let nudgedFor: string | null = null;
  /**
   * A small hop of the status tag when a move changed what it says. Checked a frame later,
   * because the midend may report the new status before or after the move itself.
   */
  const bumpStatus = () =>
    requestAnimationFrame(() => {
      if (performance.now() - lastMoveAt < 250) statusHop(statusText);
    });
  const midend = new Midend(game, drawing, {
    // Status lines are mouse-worded like the help (Black Box's "Click the corner button"),
    // so a touch screen gets the same rewrite.
    onStatus: (t) => {
      const text = touch ? touchPhrasing(t) : t;
      const was = statusText.textContent ?? '';
      statusText.textContent = text;
      if (was && withoutClock(was) !== withoutClock(text)) bumpStatus();
      holdStatusFloor();
    },
    onChange: () => {
      updateToolbar();
      scheduleSave();
      checkProgress();
      runner?.update();
    },
    // The board really moved: a tick for a move, and a step either way through the
    // history. Dealing, restarting and solving are deliberately silent — they are big
    // changes the player is already looking at, and New in particular is a button people
    // press over and over while hunting for a puzzle they fancy.
    onMove: (effect) => {
      stats.effect(effect);
      idleFrom = performance.now();
      if (!tutorialActive) run.effect(effect);
      if (effect === 'move' || effect === 'undo' || effect === 'redo' || effect === 'hint')
        lastMoveAt = performance.now();
      if (effect === 'move' || effect === 'hint') playSound('move');
      else if (effect === 'undo') playSound('undo');
      else if (effect === 'redo') playSound('redo');
    },
    onError: (m) => toast(m, 'error'),
  });

  // ---- progression
  let lastStatus = 0;
  let tutorialActive = false;
  let runner: TutorialRunner | null = null;
  const unsubProgress = onProgressChange((p) => {
    countTo(chipNum, p.credits);
    labelChip(p.credits);
  });

  function presetSized(): boolean {
    const full = game.encodeParams(midend.curParams, true);
    const short = game.encodeParams(midend.curParams, false);
    return game.presets.some(
      (p) =>
        game.encodeParams(p.params, true) === full || game.encodeParams(p.params, false) === short,
    );
  }

  /**
   * Where on the board the player last pressed, in the canvas's own pixels: the square a
   * winning move was most likely made on, which is where the win moment's rings start
   * (`celebrateBoard`). Forgotten on a key press, so a puzzle finished from the keyboard
   * rings out from the middle rather than from a square clicked minutes ago.
   */
  let lastPress: { x: number; y: number } | null = null;
  /** The rings' starting point: the last press for the player's own solve, else the middle. */
  const winOrigin = () => (midend.solvedByPlayer() ? lastPress : null);

  /** The queued interstitial, so leaving the puzzle can call it off. See the solve branch. */
  let midgameAdTimer: number | undefined;

  /**
   * Set while a saved board is being put back. A puzzle that was already finished when it
   * was saved is not being finished *now*: it gets its end-of-game panel again, but no
   * chime, shake or pulse — and the chime was worse than out of place, since a restore
   * runs at page load, before any gesture, where building the audio context is exactly
   * what the browser's autoplay policy warns about.
   */
  let restoring = false;
  function restoreQuietly(fn: () => boolean): boolean {
    restoring = true;
    try {
      return fn();
    } finally {
      restoring = false;
    }
  }

  function checkProgress() {
    const st = midend.status();
    if (st === lastStatus) return;
    lastStatus = st;
    // Back in play (undo, restart, a fresh deal) — or no puzzle loaded at all, which the
    // midend also reports as 1. Either way there is nothing to celebrate.
    if (st === 0 || !midend.hasGame) {
      endgameDismissed = false;
      hideEndgame();
      return;
    }
    if (restoring) {
      scheduleEndgame(st, false, null);
      return;
    }
    let credited = false;
    if (st === -1) {
      shake(wrap, 10);
      if (!tutorialActive) playSound('lose');
    }
    if (st === 1) {
      // With the pulse and the confetti, not with the panel that follows them: this is the
      // moment the board changes, and the sound belongs to it. Silent inside the tutorial,
      // where finishing the toy puzzle is a step rather than a win.
      // A board the Solve button finished is the answer being shown, not a win: no chime,
      // no ring, and the panel says who solved it (`showEndgame`).
      const bySolve = midend.solveUsed();
      if (!tutorialActive && !bySolve) playSound('win');
      const eligible = !tutorialActive && midend.solvedByPlayer() && presetSized();
      if (eligible && recordSolve(game.id, midend.gameId())) {
        credited = true;
        celebrateBoard(wrap, winOrigin());
        confetti(canvas);
        floatLabel(chip, t('ui.toast.creditEarned'));
        chip.classList.add('earned');
        setTimeout(() => chip.classList.remove('earned'), 1500);
        // The star lands as a second beat, once the win chime has rung out, in step with
        // the "+1 credit" label floating up to the counter.
        setTimeout(() => {
          if (page.isConnected) playSound('credit');
        }, CREDIT_SOUND_DELAY_MS);
        // A genuine "end of level" moment — let the celebration play first, then offer
        // the platform an interstitial opportunity. A no-op off-platform; see
        // docs/CRAZYGAMES.md for why this is the chosen trigger point.
        //
        // Cancelled if the player leaves in the meantime (`destroy()` below). A celebration
        // is short and "← All puzzles" is right there, so this is not a rare race — and an
        // interstitial landing a beat *after* a back button is the one thing CrazyGames'
        // placement rules single out as never acceptable, whatever queued it.
        clearTimeout(midgameAdTimer);
        midgameAdTimer = window.setTimeout(() => {
          midgameAdTimer = undefined;
          if (page.isConnected) void requestMidgameAd();
        }, MIDGAME_AD_DELAY_MS);
        // The platform celebrates along with the player. Deliberately only here: never on
        // New/Restart, a Solve-button solve, or a tutorial step.
        happytime();
      } else if (tutorialActive) {
        // A tutorial step, not a win: the old small bump, and nothing more.
        pulse(wrap, 1.03);
      } else if (!bySolve) {
        celebrateBoard(wrap, winOrigin());
      }
    }
    stats.ended(st, { byPlayer: midend.solvedByPlayer(), credited });
    if (!tutorialActive) reportEnd(st, credited);
    scheduleEndgame(st, credited, finishResult(st));
  }

  /** Tell the achievements how the puzzle ended. Never allowed to disturb the page. */
  function reportEnd(st: 1 | -1, credited: boolean) {
    try {
      // The attempt since the last Restart: what was thrown away neither earns nor spoils a
      // badge, just as undone moves don't.
      const history = midend.historySinceRestart();
      const snap = run.snapshot();
      const byPlayer = st === -1 || midend.solvedByPlayer();
      reportPuzzleEnd({
        game,
        ctx: {
          status: st,
          params: midend.curParams,
          preset: midend.whichPreset(),
          presetCount: game.presets.length,
          state: midend.state,
          initial: midend.initialState,
          history,
          moves: midend.movesSinceRestart(),
          undos: snap.undos,
          restarts: snap.restarts,
          hints: midend.hintsUsed(),
          secs: snap.secs,
        },
        eligible: byPlayer && presetSized(),
        credited,
        lostBefore: snap.lostBefore,
      });
      if (st === -1) run.lost();
    } catch (err) {
      console.error(err);
    }
  }

  // ---- end-of-game panel behaviour

  /** True while the panel is on screen (including its fade-out, which keeps the strip). */
  let endgameShown = false;
  /** Set when the player waves the panel away, so it does not come straight back. */
  let endgameDismissed = false;
  let endgameTimer: number | null = null;
  /** Bumped on every show/hide so a finishing fade-out cannot undo a newer show. */
  let endgameSeq = 0;

  function clearEndgameTimer() {
    if (endgameTimer !== null) {
      clearTimeout(endgameTimer);
      endgameTimer = null;
    }
  }

  /**
   * Where the end-of-game panel goes, and what that costs the board.
   *
   * The rule the panel has always kept is that it never covers the puzzle it is
   * congratulating the player for. Under the board, the only way to keep it is to make the
   * board smaller — and on a landscape screen that meant shrinking a 533px board to 397px
   * while half the width sat empty either side of it. So the panel takes whichever of the
   * two gaps leaves the bigger board: the strip under it, or the width beside it, which on
   * a rail layout is width the board has no use for and the board does not shrink at all.
   *
   * Decided by arithmetic rather than by a breakpoint, so an odd window lands on whichever
   * genuinely wins: `min(W - aside, H)` against `min(W, H - under)`.
   */
  function syncEndgameReserve(availW: number, availH: number): { w: number; h: number } {
    if (!endgameShown) {
      page.classList.remove('endgame-aside');
      stage.style.setProperty('--endgame-h', '0px');
      stage.style.setProperty('--endgame-w', '0px');
      return { w: 0, h: 0 };
    }
    // Measured lying across the stage, which is the stylesheet's default arrangement, so
    // the number is the one a strip underneath would actually cost.
    page.classList.remove('endgame-aside');
    const under = endgame.offsetHeight + ENDGAME_GAP;
    // No wider than the width the board cannot use anyway, within the panel's own limits.
    const asideW = Math.min(ENDGAME_ASIDE_W, Math.max(ENDGAME_ASIDE_MIN_W, availW - availH));
    const aside = asideW + ENDGAME_GAP;
    const beside = Math.min(availW - aside, availH) > Math.min(availW, availH - under);
    page.classList.toggle('endgame-aside', beside);
    stage.style.setProperty('--endgame-h', beside ? '0px' : `${under}px`);
    stage.style.setProperty('--endgame-w', beside ? `${aside}px` : '0px');
    return beside ? { w: aside, h: 0 } : { w: 0, h: under };
  }

  /** How the puzzle that has just ended went. See {@link EndgameResult}. */
  function finishResult(st: GameStatus): EndgameResult | null {
    if (tutorialActive || (st === 1 && midend.solveUsed())) return null;
    // A timed puzzle's own clock (it stops in the pause menu); otherwise the time the
    // puzzle has been on screen since it was dealt.
    const secs = game.isTimed ? midend.elapsedSeconds() : run.snapshot().secs;
    const hints = midend.hintsUsed();
    const result: EndgameResult = {
      secs,
      moves: midend.movesSinceRestart(),
      hints,
      stars: 0,
      newBest: false,
    };
    if (st !== 1) return result;
    const byPlayer = midend.solvedByPlayer();
    result.stars = starsFor(hints, byPlayer, midend.forfeited);
    // Only a hand-solved preset goes on the books: a custom size has no fair comparison.
    if (byPlayer && presetSized() && secs > 0) {
      const r = recordTime(recordKey(game.id, game.encodeParams(midend.curParams, false)), secs);
      result.best = r.best;
      result.newBest = r.previous !== undefined && secs < r.previous;
    }
    return result;
  }

  /** Fill in the results for `plan`, or hide them when there are none to give. */
  function paintResults(plan: EndgamePlan, result: EndgameResult | null) {
    endResults.hidden = !result;
    if (!result) return;
    const won = plan.kind === 'won';
    endStars.hidden = !won || !result.stars;
    endStars.setAttribute('aria-label', t('ui.endgame.stars', { n: result.stars }));
    [...endStars.children].forEach((s, i) => s.classList.toggle('on', i < result.stars));
    const rows: [string, string][] = [
      [t('ui.endgame.time'), formatTime(result.secs)],
      [t('ui.endgame.moves'), String(result.moves)],
    ];
    if (game.hint) rows.push([t('ui.endgame.hints'), String(result.hints)]);
    endStats.replaceChildren(
      ...rows.map(([label, value]) => {
        const row = el('div', 'endgame-stat');
        row.append(el('dt', undefined, label), el('dd', undefined, value));
        return row;
      }),
    );
    endBest.hidden = result.best === undefined;
    endBest.classList.toggle('new', result.newBest);
    endBest.textContent = result.newBest
      ? t('ui.endgame.newBest')
      : result.best !== undefined
        ? t('ui.endgame.best', { time: formatTime(result.best) })
        : '';
  }

  /** The results arriving, a beat behind the card: stars one by one, then the record. */
  function playResults(seq: number, result: EndgameResult | null) {
    if (!result || prefersReducedMotion()) return;
    const stars = [...endStars.children].filter((s) => s.classList.contains('on'));
    if (!endStars.hidden) {
      gsap.set(endStars.children, { scale: 0, rotation: -40 });
      gsap.to(endStars.children, {
        scale: 1,
        rotation: 0,
        duration: 0.34,
        ease: 'back.out(2.6)',
        stagger: 0.14,
        delay: 0.25,
        clearProps: 'transform',
      });
      stars.forEach((_, i) => {
        gsap.delayedCall(0.3 + i * 0.14, () => {
          if (seq === endgameSeq && !endgame.hidden) playSound('move');
        });
      });
    }
    const moves = endStats.querySelectorAll('dd')[1] as HTMLElement | undefined;
    if (moves) {
      moves.textContent = '0';
      countTo(moves, result.moves, 0.5);
    }
    if (!endBest.hidden && result.newBest) {
      gsap.fromTo(
        endBest,
        { scale: 1.8, rotation: -14, opacity: 0 },
        {
          scale: 1,
          rotation: -4,
          opacity: 1,
          duration: 0.35,
          delay: 0.3 + stars.length * 0.14 + 0.15,
          ease: 'back.out(2)',
          clearProps: 'transform,opacity',
        },
      );
    }
  }

  function scheduleEndgame(st: GameStatus, credited: boolean, result: EndgameResult | null) {
    clearEndgameTimer();
    const plan = endgamePlan(
      st,
      credited,
      midend.canUndo(),
      !!game.flags?.undoAfterLoss,
      !!game.flags?.lossRevealsAnswer,
    );
    if (!plan || tutorialActive || endgameDismissed) return;
    // Counted from the end of the move's own animation, not over it: Inertia's Solve rolls
    // the ball along the whole route, for seconds on a big board.
    endgameTimer = window.setTimeout(
      () => {
        endgameTimer = null;
        // The player may have undone, restarted or dealt again while the celebration ran.
        if (!page.isConnected || tutorialActive || endgameDismissed) return;
        if (midend.status() !== st || !midend.hasGame) return;
        showEndgame(plan, result);
      },
      plan.delayMs + midend.animRemaining() * 1000,
    );
  }

  function endgameControl(action: EndgameAction, primary: boolean): HTMLElement {
    const cls = `btn${primary ? ' primary' : ''}`;
    if (action === 'menu') {
      // A real link, so it behaves like the back link in the header (and never fires an
      // ad — docs/CRAZYGAMES.md rules navigation out as a trigger).
      const a = el('a', cls, t('ui.topbar.back'));
      a.href = '#/';
      return a;
    }
    const retry = action === 'retry';
    const undo = action === 'undo';
    const b = el(
      'button',
      cls,
      t(undo ? 'ui.toolbar.undo' : retry ? 'ui.endgame.retry' : 'ui.endgame.next'),
    );
    b.type = 'button';
    b.dataset.endgame = action;
    b.title = t(
      undo ? 'ui.toolbar.undoTitle' : retry ? 'ui.toolbar.restartTitle' : 'ui.toolbar.newTitle',
    );
    b.addEventListener('click', () => {
      hideEndgame();
      // Exactly what Undo, Restart and New do from the toolbar — no ad, no extra credit.
      if (undo) midend.undo();
      else if (retry) midend.restart();
      else freshGame();
      canvas.focus({ preventScroll: true });
    });
    return b;
  }

  function showEndgame(plan: EndgamePlan, result: EndgameResult | null = null) {
    const seq = ++endgameSeq;
    // Every game reaches "solved" through Solve as well as by hand; only the second is the
    // player's win (Black Box, Solo, Mines… all said "Puzzle solved!" to a Solve).
    const bySolve = plan.kind === 'won' && midend.solveUsed();
    endTitle.textContent = t(
      bySolve
        ? 'status.solvedByComputer'
        : plan.kind === 'won'
          ? 'ui.endgame.won'
          : 'ui.endgame.lost',
    );
    scheduleFit();
    // "Enough to unlock a new puzzle" is only true while something is still locked.
    const allOpen = menuGames.every((g) => isUnlocked(g.id));
    // A hand-finished win that would have earned a credit but for the answer having been
    // shown on the way (Solve undone, a loss that revealed it, a grid's worth of hints) says
    // so: the panel promising nothing where the last win said "+1" read as a lost credit.
    const forfeitedWin =
      plan.kind === 'won' && !bySolve && midend.forfeited && !tutorialActive && presetSized();
    endNote.textContent = plan.credited
      ? t(allOpen ? 'ui.toast.creditEarned' : 'ui.endgame.credit')
      : t(
          forfeitedWin
            ? 'ui.endgame.forfeitNote'
            : plan.kind === 'won'
              ? 'ui.endgame.wonNote'
              : 'ui.endgame.lostNote',
        );
    endNote.classList.toggle('earned', plan.credited);
    endCard.dataset.state = plan.kind;
    paintResults(plan, bySolve ? null : result);
    endgame.setAttribute('aria-label', endTitle.textContent);
    endActions.replaceChildren(
      endgameControl(plan.primary, true),
      endgameControl(plan.secondary, false),
    );
    const step =
      plan.kind === 'won' && !bySolve && !tutorialActive
        ? stepUpPreset(midend.whichPreset(), game.presets.length)
        : -1;
    endStep.hidden = step < 0;
    if (step >= 0) {
      endStep.textContent = t('ui.endgame.stepUp', {
        preset: presetName(game, game.presets[step]),
      });
      endStep.onclick = () => {
        hideEndgame();
        midend.setParams(structuredClone(game.presets[step].params));
        freshGame();
        canvas.focus({ preventScroll: true });
      };
    }
    endgame.hidden = false;
    scheduleFit();
    endgameShown = true;
    page.classList.add('has-endgame');
    // Refit the board into the room that is left, so it stays whole above the panel.
    layout();
    riseIn(endCard);
    playResults(seq, bySolve ? null : result);
    // A beat after the card has started rising, so Ziggy's verdict reads as the panel's
    // second gesture rather than as part of it arriving.
    endMascot?.perk();
    gsap.delayedCall(0.22, () => {
      if (seq !== endgameSeq || endgame.hidden) return;
      if (plan.kind === 'won') endMascot?.cheer();
      else endMascot?.droop();
    });
    // Enter should now do the obvious thing — but only take the keyboard when nothing
    // else has it, so the panel never snatches focus from a dialog or the help drawer.
    // Not on a touch screen: there is no Enter to press, and Chrome drew the focus ring
    // round the primary button, which read as a highlight on one of the two choices.
    const active = document.activeElement;
    if (
      !isTouch() &&
      seq === endgameSeq &&
      (!active || active === document.body || active === canvas)
    ) {
      endActions.querySelector<HTMLElement>('.primary')?.focus({ preventScroll: true });
    }
  }

  /** Take the panel down. `immediate` skips the fade (teardown, or a quick undo). */
  function hideEndgame(immediate = false) {
    clearEndgameTimer();
    if (endgame.hidden) return;
    const seq = ++endgameSeq;
    // Hand the keyboard back to the board rather than leaving it on a vanished button.
    if (endgame.contains(document.activeElement)) canvas.focus({ preventScroll: true });
    const done = () => {
      if (seq !== endgameSeq) return; // a newer show won
      endgame.hidden = true;
      endgameShown = false;
      page.classList.remove('has-endgame');
      if (page.isConnected) layout();
    };
    // The strip stays reserved until the card has faded, so the board grows back once
    // rather than sliding about underneath it.
    if (immediate) done();
    else popOut(endCard, done);
  }

  function dismissEndgame() {
    endgameDismissed = true;
    hideEndgame();
  }

  endClose.addEventListener('click', () => {
    dismissEndgame();
    canvas.focus({ preventScroll: true });
  });
  // Clicking away — on the board itself or the paper around it — puts the panel away, so
  // a player who wants to sit and admire the finished puzzle can.
  stage.addEventListener(
    'pointerdown',
    (e) => {
      if (endgame.hidden) return;
      if ((e.target as HTMLElement).closest('.endgame')) return;
      dismissEndgame();
    },
    true,
  );

  /**
   * One step of the solution, for a game that offers it. Unlike Solve the puzzle stays in
   * play — the hint is an ordinary undoable move and the board is still the player's to
   * finish. The first few are free of charge; the one that crosses the line says so,
   * which is fairer than letting the credit quietly fail to arrive at the end.
   */
  function takeHint() {
    // The hint that crosses the allowance is the one with a price on it, and the only one
    // worth offering a trade for: below the line nothing is at stake, and above it the
    // credit has already gone, so an ad would buy the player nothing.
    if (adsReady() && creditStillAtStake() && midend.chargeableHints() === Midend.HINT_ALLOWANCE) {
      void offerHintTrade();
      return;
    }
    applyHint(false);
  }

  /** Whether this puzzle could still earn a credit, i.e. whether a hint costs anything. */
  function creditStillAtStake(): boolean {
    return (
      !tutorialActive &&
      presetSized() &&
      !midend.forfeited &&
      midend.chargeableHints() <= Midend.HINT_ALLOWANCE
    );
  }

  function applyHint(free: boolean) {
    const before = midend.chargeableHints();
    const result = midend.hint(free);
    if (result === 'none') toast(t('ui.toast.hintNone'));
    if (result !== 'applied') return;
    stats.hint(free);
    if (!tutorialActive) reportHint();
    if (!free && before === Midend.HINT_ALLOWANCE) {
      toast(t('ui.toast.hintNoCredit', { n: Midend.HINT_ALLOWANCE }));
    }
  }

  /**
   * Ask whether to spend an ad on keeping the credit, then act on the answer. Only reached
   * when an ad can actually play; off the platform the hint is taken the way it always was.
   */
  async function offerHintTrade() {
    const choice = await rewardedHintDialog(Midend.HINT_ALLOWANCE);
    stats.hintOffer(choice ?? 'dismiss');
    if (choice === null || !page.isConnected) return;
    if (choice === 'anyway') {
      applyHint(false);
      return;
    }
    const earned = await requestRewardedAd();
    if (!page.isConnected) return;
    if (!earned) {
      // Nothing was taken away: the hint is still there at its usual price.
      toast(t('ui.toast.hintAdFailed'), 'error');
      return;
    }
    applyHint(true);
  }

  /** Deal a fresh puzzle with the board entrance animation. */
  /**
   * Deal a new puzzle of the current type. Generation runs on the main thread and a few
   * types (Solo's Killer Extreme, Keen's 9×9 Unreasonable) take seconds, which used to be
   * seconds of a frozen page with no sign why. So the stage is marked first and the work
   * starts a frame later: the notice it shows fades in on a CSS delay, which the compositor
   * runs by itself while the page is busy, so a quick deal never shows it at all.
   */
  let dealing = false;
  function freshGame() {
    if (dealing) return;
    dealing = true;
    stage.classList.add('dealing');
    requestAnimationFrame(() =>
      window.setTimeout(() => {
        dealing = false;
        stage.classList.remove('dealing');
        if (!page.isConnected) return;
        try {
          midend.newGame();
        } catch (e) {
          // A generator that gives up (a custom size with no possible puzzle) leaves the
          // current board in place; say why instead of throwing into the console.
          toast(e instanceof Error ? e.message : String(e), 'error');
          return;
        }
        layout();
        lastStatus = midend.status();
        boardEnter(wrap);
      }, 0),
    );
  }

  /**
   * What to go back to when the tutorial ends: the puzzle the player had on the board (a
   * replay from the help drawer mid-game) and the type they had chosen. The tutorial loads
   * its own boards by game ID, which also sets the type New deals, and it used to finish by
   * dealing a fresh puzzle — so replaying it threw the player's game away, autosave and
   * all, and left them on the tutorial's toy size.
   */
  let tutorialReturn: { save: SaveData | null; params: unknown } | null = null;
  function holdForTutorial() {
    tutorialActive = true;
    tutorialReturn ??= { save: midend.hasGame ? midend.serialize() : null, params: midend.params };
  }

  /**
   * Put back what `holdForTutorial` kept, or deal a fresh puzzle of the kept type. True when
   * the player is handed back a game of theirs rather than a new one, so the closing toast
   * does not promise a fresh puzzle over the board they were already playing.
   */
  function returnFromTutorial(): boolean {
    const back = tutorialReturn;
    tutorialReturn = null;
    if (back?.save && restoreQuietly(() => midend.deserialize(back.save!) === null)) {
      layout();
      lastStatus = midend.status();
      boardEnter(wrap);
      return true;
    }
    if (back) midend.setParams(back.params as typeof midend.params);
    // Arriving straight into the tutorial had no board in hand yet, but may still have a
    // saved game from an earlier visit.
    if (!back?.save && tryRestore()) {
      layout();
      lastStatus = midend.status();
      boardEnter(wrap);
      return true;
    }
    freshGame();
    return false;
  }

  /**
   * How a tutorial being cut short by a request for another puzzle ends (see
   * `leaveTutorial`): with the kept type put back, or with the type the request brought.
   */
  let leaving: 'kept-type' | 'own-type' | null = null;

  /**
   * End a running tutorial because the player asked for a different puzzle — New, a type
   * from the menu, a custom size, a code. That puzzle replaced the tutorial's board under
   * the callout, whose later steps then waited on squares that were not there, and the
   * page stayed in tutorial mode so the win was silent and earned nothing. The tutorial is
   * skipped instead and the caller deals what was asked for; the board held for the return
   * is let go (the request replaces it anyway). `ownType` keeps the parameters the request
   * has already set (a loaded code) rather than restoring the kept type.
   */
  function leaveTutorial(ownType = false) {
    if (!runner?.active) return;
    leaving = ownType ? 'own-type' : 'kept-type';
    runner.end(false);
  }

  function startTutorial() {
    if (!game.tutorial || runner?.active) return;
    toggleHelp(false);
    hideEndgame(true);
    holdForTutorial();
    stats.tutorial(true);
    runner = new TutorialRunner(game, midend, canvas, {
      onStep: () => updateToolbar(),
      layout: () => {
        layout();
        lastStatus = midend.status();
      },
      onEnd: (completed) => {
        tutorialActive = false;
        stats.tutorial(false, completed);
        markTutorialSeen(game.id);
        if (completed) reportTutorialDone(game.id);
        runner = null;
        let resumed = false;
        if (leaving) {
          const back = tutorialReturn;
          tutorialReturn = null;
          if (back && leaving === 'kept-type')
            midend.setParams(back.params as typeof midend.params);
          leaving = null;
        } else {
          resumed = returnFromTutorial();
        }
        updateToolbar(); // Solve and Hint go back to following the board
        toast(
          t(
            !completed
              ? 'ui.toast.tutorialSkipped'
              : resumed
                ? 'ui.toast.tutorialCompleteBack'
                : 'ui.toast.tutorialComplete',
          ),
          completed ? 'success' : 'info',
        );
        canvas.focus({ preventScroll: true });
      },
    });
    runner.start();
  }

  /** The preset `params` is, by its full encoding, or -1. */
  function presetIndexOf(params: unknown): number {
    try {
      const full = game.encodeParams(params as never, true);
      return game.presets.findIndex((p) => game.encodeParams(p.params, true) === full);
    } catch {
      return -1;
    }
  }

  function updateToolbar() {
    scheduleFit();
    btnUndo.disabled = !midend.canUndo();
    btnRedo.disabled = !midend.canRedo();
    // The tutorial's toy boards are rarely a preset, and "Custom…" over one of them reads
    // as though the player had changed something. Show the type they will be handed back.
    const which =
      tutorialActive && tutorialReturn
        ? presetIndexOf(tutorialReturn.params)
        : midend.whichPreset();
    showCustomNow(which < 0 && !!game.configure);
    typeSelect.value = which >= 0 ? String(which) : game.configure ? CUSTOM_NOW : 'custom';
    syncPresetPick();
    const st = midend.status();
    // Nothing to reveal on a board that is already over, either way it went.
    if (tutorialActive) {
      // Only the step that explains Solve or Hint lets them be pressed — often on the board
      // it just finished, where they only say why there is nothing to do. Earlier, a Solve
      // would finish the board under steps still waiting for the player's own moves.
      btnHint.disabled = !runner?.spotlights('hint');
      btnSolve.disabled = !runner?.spotlights('solve');
    } else {
      btnHint.disabled = st !== 0;
      // A lost board may still be shown its answer; a won one has nothing left to solve.
      // …nor has a loss that already put the answer on the board (Guess, Black Box).
      btnSolve.disabled = st === 1 || (st === -1 && !!game.flags?.lossRevealsAnswer);
    }
    badge.textContent = st === 1 ? t('ui.badge.won') : st === -1 ? t('ui.badge.lost') : '';
    badge.dataset.state = st === 1 ? 'won' : st === -1 ? 'lost' : '';
    statusRow.style.display = game.wantsStatusBar || st !== 0 ? '' : 'none';
    // An action whose `when` no longer holds (Flood's hint on a finished grid) goes away.
    const state = midend.hasGame ? midend.state : null;
    // A latching one (an eraser, a paint colour) is lit while it is on.
    let toolOn = false;
    actionBtns.forEach((b, i) => {
      const { when: w, pressed, hud, view } = actionSpecs[i];
      b.hidden = !!w && (!state || !w(state));
      if (pressed) {
        const on = !!state && pressed(state, midend.ui);
        b.setAttribute('aria-pressed', String(on));
        b.classList.toggle('on', on);
        if (on && hud && !view) toolOn = true;
      }
    });
    // …and while it is, the Tap switch stands down (see `toolLit`): still showing its
    // setting, which comes back when the tool goes off, but greyed.
    btnTap.classList.toggle('overridden', toolOn || tutorialActive);
    syncToolbarTier();
    syncKeypad();
  }

  // ---- keypad
  let keypadOn = false;
  try {
    keypadOn = localStorage.getItem(keypadKey(game)) === '1';
  } catch {
    /* storage unavailable: default to hidden */
  }
  let pencilOn = false;
  /** The spec the buttons were built from, so a redraw only rebuilds on a real change. */
  let keypadSig = '';
  /** How many keys are on screen, which is what the landscape column layout is sized by. */
  let keypadCount = 0;
  /** Finishes a keypad that is on its way out, if one is. See `syncKeypad`. */
  let keypadHiding: (() => void) | null = null;
  /**
   * The keypad is animated when the player turns it on, not when the page arrives wearing
   * it — a touch device always has one, and the page has an entrance of its own. It also
   * keeps the keys at their full 44px fingertip size from the very first frame, which a
   * scale-up entrance would briefly undercut: `mobile.spec.ts` measures them.
   */
  let keypadSettled = false;

  function setPencil(on: boolean) {
    pencilOn = on;
    const b = keypadEl.querySelector<HTMLButtonElement>(`[data-key="${PENCIL_KEY}"]`);
    if (!b) return;
    b.classList.toggle('latched', on);
    b.setAttribute('aria-pressed', String(on));
    b.title = t(on ? 'ui.keypad.pencilOnTitle' : 'ui.keypad.pencilOffTitle');
  }

  /** Rebuild the keypad when the parameters changed, and show or hide it. */
  function syncKeypad() {
    if (!game.keypad) return;
    let spec: Keypad | null = null;
    try {
      if (midend.hasGame) spec = game.keypad(midend.curParams);
    } catch (e) {
      console.warn('keypad() threw', e);
    }
    const sig = spec ? JSON.stringify(spec) : '';
    if (sig !== keypadSig) {
      keypadSig = sig;
      keypadEl.innerHTML = '';
      pencilOn = false;
      for (const ch of spec?.keys ?? []) {
        const b = el('button', 'key', spec ? keypadLabel(game, spec, ch) : ch);
        b.type = 'button';
        b.dataset.key = ch;
        keypadEl.append(b);
      }
      if (spec?.clear) {
        const b = el('button', 'key wide', '⌫');
        b.type = 'button';
        b.dataset.key = CLEAR_KEY;
        b.title = t('ui.keypad.clearTitle');
        b.setAttribute('aria-label', t('ui.keypad.clear'));
        keypadEl.append(b);
      }
      if (spec?.pencil) {
        const b = el('button', 'key wide pencil-toggle', '✎');
        b.type = 'button';
        b.dataset.key = PENCIL_KEY;
        b.setAttribute('aria-label', t('ui.keypad.pencil'));
        keypadEl.append(b);
        setPencil(false);
      }
    }
    keypadCount = keypadEl.childElementCount;
    const show = !!spec?.keys.length && (touch || keypadOn);
    if (keypadEl.hidden !== !show) {
      // The keypad is a flex row of the page, so the stage — and the board `fit` puts in
      // it — has to be measured again with the row's height taken off. The refit is one
      // frame either way; the keys come up into the room it made, or go before it is
      // taken back, so the change reads as the row arriving rather than the board jumping.
      const settle = () => {
        page.classList.toggle('has-keypad', show);
        layout();
      };
      if (show) {
        keypadEl.hidden = false;
        settle();
        if (keypadSettled) keypadIn(keypadEl);
      } else if (!keypadSettled) {
        keypadEl.hidden = true;
        settle();
      } else {
        // A second toggle while the first is still leaving: land it at once rather than
        // queueing, so `hidden` never disagrees with what the toolbar says.
        keypadHiding?.();
        keypadHiding = () => {
          keypadHiding = null;
          keypadEl.hidden = true;
          settle();
        };
        const done = keypadHiding;
        keypadOut(keypadEl, () => {
          if (keypadHiding === done) done();
        });
      }
    }
  }

  function setKeypadOn(on: boolean) {
    keypadOn = on;
    btnKeypad.setAttribute('aria-pressed', String(on));
    btnKeypad.classList.toggle('latched', on);
    try {
      localStorage.setItem(keypadKey(game), on ? '1' : '0');
    } catch {
      /* storage unavailable: ignore */
    }
    syncKeypad();
  }
  setKeypadOn(keypadOn);

  // A keypad press is a key press: it goes through the midend exactly like the keyboard,
  // so undo, autosave and the tutorial see no difference — and the square the player
  // tapped stays selected, because nothing here touches the board.
  keypadEl.addEventListener('click', (e) => {
    const b = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-key]');
    if (!b) return;
    keyPress(b);
    const key = b.dataset.key!;
    if (key === PENCIL_KEY) {
      setPencil(!pencilOn);
      canvas.focus({ preventScroll: true });
      return;
    }
    if (key === CLEAR_KEY) {
      midend.processKey(0, 0, KEY_BACKSPACE);
    } else {
      // The pencil latch is sent as a shift modifier on the character, which the digit
      // games read as "pencil this in" whatever mode the square is in.
      midend.processKey(0, 0, codeOf(key) | (pencilOn ? MOD_SHFT : 0));
    }
    canvas.focus({ preventScroll: true });
  });

  /**
   * A controller's trigger (`PAD_KEYPAD_EVENT`): a pad has no digits, so it takes the
   * selector into the keypad — showing it where a mouse keeps it behind its switch — and
   * from there back to the board. A key pressed there hands the board back by itself.
   */
  let lastPadKey: HTMLElement | null = null;
  const onPadKeypad = () => {
    if (!game.keypad || !midend.hasGame || tutorialActive) return;
    if (document.querySelector('.dimmer') || drawer.classList.contains('open')) return;
    const active = document.activeElement;
    if (active instanceof HTMLElement && keypadEl.contains(active)) {
      lastPadKey = active;
      canvas.focus({ preventScroll: true });
      return;
    }
    if (keypadEl.hidden && !touch) setKeypadOn(true);
    const keys = [...keypadEl.querySelectorAll<HTMLButtonElement>('button[data-key]')];
    const key = lastPadKey && keys.includes(lastPadKey as HTMLButtonElement) ? lastPadKey : keys[0];
    key?.focus({ preventScroll: true });
  };
  window.addEventListener(PAD_KEYPAD_EVENT, onPadKeypad);
  keypadEl.addEventListener('focusin', (e) => {
    if (e.target instanceof HTMLElement && e.target.matches('button[data-key]'))
      lastPadKey = e.target;
  });

  let customNow: HTMLOptionElement | null = null;
  function rebuildTypeMenu() {
    typeSelect.innerHTML = '';
    customNow = null;
    game.presets.forEach((p, i) => {
      const opt = document.createElement('option');
      opt.value = String(i);
      opt.textContent = presetName(game, p);
      typeSelect.append(opt);
    });
    if (game.configure) {
      const opt = document.createElement('option');
      opt.value = 'custom';
      opt.textContent = t('ui.toolbar.custom');
      // A custom game shows this hidden twin as the selection, so picking Custom… again is
      // still a change: re-picking the selected option fires no event, and the dialog would
      // never reopen to tweak the size just played.
      // Only in the list while a custom game is on (`showCustomNow`): iOS Safari's picker
      // shows hidden options too, and there it was a second "Custom…" on every preset.
      customNow = opt.cloneNode(true) as HTMLOptionElement;
      customNow.value = CUSTOM_NOW;
      customNow.hidden = true;
      typeSelect.append(opt);
    }
  }
  function showCustomNow(on: boolean) {
    if (!customNow) return;
    if (on && !customNow.isConnected) typeSelect.append(customNow);
    else if (!on && customNow.isConnected) customNow.remove();
  }
  rebuildTypeMenu();

  /** The header's copy of the Type menu: the same options, the same choice. */
  function syncPresetPick() {
    presetSelect.replaceChildren(
      ...[...typeSelect.options].map((o) => o.cloneNode(true) as HTMLOptionElement),
    );
    presetSelect.value = typeSelect.value;
    const shown = typeSelect.selectedOptions[0]?.textContent ?? '';
    // "Custom…" is a promise of a dialog in a menu; as the name of what is on the board it
    // is just "Custom".
    presetWord.textContent = typeSelect.value === CUSTOM_NOW ? shown.replace(/[….]+$/, '') : shown;
    scheduleFit();
  }
  presetSelect.addEventListener('change', () => {
    typeSelect.value = presetSelect.value;
    typeSelect.dispatchEvent(new Event('change'));
  });

  // ---- persistence
  let saveTimer: number | null = null;
  function scheduleSave() {
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = window.setTimeout(saveNow, 300);
  }
  function saveNow() {
    // Called directly too (leaving the page, hiding the tab): a save still queued would
    // otherwise land after this one — after `destroy`, over the save of a page for the same
    // game mounted in the meantime.
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = null;
    // The tutorial's toy boards are never the player's game.
    if (!midend.hasGame || tutorialActive) return;
    try {
      // `shown`: how long the puzzle has been on screen, which is the results card's time
      // for an untimed game — without it a reload started that clock again from nothing.
      const data = { ...midend.serialize(), shown: run.snapshot().secs };
      localStorage.setItem(saveKey(game), JSON.stringify(data));
      // What the menu's Continue offers: a board with a move on it that is not over — or
      // lost where one Undo takes the loss back (Inertia's mine, `undoAfterLoss`).
      const status = midend.status();
      const open = status === 0 || (status < 0 && !!game.flags?.undoAfterLoss);
      noteBoard(game.id, midend.moveCount() > 0 && open);
    } catch {
      /* storage unavailable: ignore */
    }
    keepGuestLink();
  }

  /**
   * A game still on the locked shelf is only open to a player sent here by a link to one
   * particular puzzle (see `mount` in app.ts), and the bare `#/<game>` route stays behind
   * its credit. So its address keeps naming the puzzle on the board: trimmed to `#/<game>`
   * as for an unlocked game, a reload threw the friend out to the menu, mid-puzzle.
   */
  function keepGuestLink() {
    if (isUnlocked(game.id) || !midend.hasGame || !page.isConnected) return;
    if (location.hash.replace(/^#\/?/, '').split(/[/?]/)[0] !== game.id) return;
    // The same id Share would hand out, so a reload deals exactly this board again.
    const id = (game.flags?.shareBySeed && midend.seedId()) || midend.shareGameId();
    const route = `#/${game.id}/${encodeURIComponent(id)}`;
    // Held while a dialog's Back entry is up: see `afterLayers`.
    if (location.hash !== route)
      afterLayers(() => {
        if (page.isConnected) history.replaceState(history.state, '', route);
      });
  }

  /** The saved game, when it is the very puzzle `id` names (a reload of a guest link). */
  function restoreLinked(id: string): boolean {
    if (!tryRestore()) return false;
    return midend.gameId() === id || midend.shareGameId() === id || midend.seedId() === id;
  }
  function tryRestore(): boolean {
    try {
      const raw = localStorage.getItem(saveKey(game));
      if (!raw) return false;
      const data = JSON.parse(raw) as SaveData & { shown?: number };
      if (!restoreQuietly(() => midend.deserialize(data) === null)) return false;
      if (typeof data.shown === 'number') run.carry(data.shown);
      return true;
    } catch {
      return false;
    }
  }

  // ---- layout
  // The page is a flex column of header, toolbar, stage, status line and (when a game
  // declares one) the keypad; the stage takes what is left, so measuring it is all that
  // is needed for the board to fit whether or not the keypad is showing. On a landscape
  // phone it is a grid instead, with the toolbar and the keypad standing up either side of
  // the stage — same measurement, more of it left for the board.

  /**
   * Beside the board, the keypad is a column of keys rather than a row. `keypadShape`
   * works out how many columns that takes; all this does is measure the height it has to
   * fill and hand the answer to the CSS, which is where the grid itself lives.
   */
  function syncKeypadShape() {
    const rail = !keypadEl.hidden && keypadCount > 0 && isSideRail();
    if (!rail) {
      keypadEl.style.removeProperty('--keypad-cols');
      keypadEl.style.removeProperty('--keypad-rows');
      return;
    }
    // The column runs the height of the stage and the status line together; a hidden
    // status line measures zero and drops out of the reckoning by itself.
    const stageBox = stage.getBoundingClientRect();
    const bottom = Math.max(stageBox.bottom, statusRow.getBoundingClientRect().bottom);
    const { cols, rows } = keypadShape(keypadCount, bottom - stageBox.top);
    keypadEl.style.setProperty('--keypad-cols', String(cols));
    keypadEl.style.setProperty('--keypad-rows', String(rows));
  }

  /**
   * How much of the page the help drawer is standing on, so the board can be fitted beside
   * it instead of behind it. The drawer is pinned to the viewport's inline end and the page
   * is centred inside it, so the two only overlap by however much the page reaches past
   * where the drawer starts — on a wide window, often nothing at all.
   *
   * Zero when the drawer is a full-screen sheet (a phone): there is no board left to keep
   * clear of it, and reserving its width would squeeze the board to nothing on the way.
   */
  function drawerReserve(): number {
    if (!drawer.classList.contains('open')) return 0;
    const p = page.getBoundingClientRect();
    if (p.width <= 0) return 0;
    const dw = drawer.offsetWidth;
    const rtl = getComputedStyle(page).direction === 'rtl';
    const vw = document.documentElement.clientWidth;
    const overlap = Math.max(0, rtl ? dw - p.left : p.right - (vw - dw));
    return overlap > p.width * 0.55 ? 0 : overlap;
  }

  const uprightPhone = window.matchMedia('(max-width: 640px)');
  function layout() {
    scheduleFit();
    // Written before the stage is measured: reading a rect flushes the style change, so
    // the board is fitted into the width a re-shaped keypad actually leaves it.
    syncKeypadShape();
    // `clientWidth`/`clientHeight` rather than the border box: they include the padding
    // the panels reserve (which is taken off below) but *exclude* a scrollbar, so a zoomed
    // board is fitted into the room left beside the bar that appeared for it rather than
    // into the room it had before — which would size the board to make the bar come and go.
    // On an upright phone the page is padded at the foot by `--lift` (play.css) to centre
    // the board and its status line in the room under the toolbar; the stage is measured
    // as if that padding were not there, so the lift never shrinks the board it centres.
    const lifting = uprightPhone.matches && !page.classList.contains('railed') && zoom === 1;
    const lift = parseFloat(page.style.getPropertyValue('--lift')) || 0;
    const rect = { width: stage.clientWidth, height: stage.clientHeight + lift };
    // Breathing room around the board; a phone cannot spare 12px a side, and neither can a
    // tablet on its side, where the rails already hold the chrome clear of the board and
    // every pixel of height is one the board is bounded by. Either way it is a little more
    // than the sheet the board lies on reaches past it (`--sheet-pad` in play.css), so the
    // sheet's edge and shadow stay inside the stage, which clips.
    const compact = isCompactLayout() || isSideRail();
    const margin = compact ? 6 : 16;
    // `rect` is the stage's border box, which includes whatever the end-of-game panel
    // reserves as padding; taking the reserve off here is what keeps the finished board
    // fully visible next to the panel instead of behind it.
    const help = drawerReserve();
    // On the page, not just the stage: the status line and the keypad under the board are
    // centred on it too, and were left half under the drawer on a tablet.
    page.style.setProperty('--help-w', `${help}px`);
    const availW = Math.max(80, rect.width - 2 * margin - help);
    const availH = Math.max(80, rect.height - 2 * margin);
    const reserve = syncEndgameReserve(availW, availH);
    // The board uses the room it has on every device: `fit` grows it until it fills the
    // stage or hits the tile ceiling, so small grids no longer sit in a sea of paper
    // with 20px tiles to hit, and touch needs no bump of its own.
    const board = midend.fit(
      Math.max(80, availW - reserve.w),
      Math.max(80, availH - reserve.h),
      zoom,
    );
    // A width-bound board leaves a band of desk above it; half of it goes under the
    // status line instead, so the group sits in the middle of the screen, not at its foot.
    const slack = lifting ? rect.height - 2 * margin - reserve.h - board.h : 0;
    page.style.setProperty('--lift', `${Math.max(0, Math.floor(slack / 2))}px`);
    // The pointer glow is placed in board coordinates, so a board that has just been
    // refitted or moved (the end-of-game panel, the help drawer) under a still mouse would
    // leave it glowing over the wrong square — or out in the margin. The next movement of
    // the mouse brings it back where the pointer really is.
    if (!glow.hidden) {
      gsap.killTweensOf(glow, 'opacity');
      glow.hidden = true;
    }
  }

  /**
   * Shrink any control whose word is longer than the room the layout gives it — a longer
   * translation in half a rail, a preset name in a phone's menu (see `fitText`). Once a
   * frame at most, after whatever changed the layout or a label has been applied.
   */
  let fitQueued = false;
  function scheduleFit() {
    if (fitQueued) return;
    fitQueued = true;
    requestAnimationFrame(() => {
      fitQueued = false;
      if (!page.isConnected) return;
      // Only where the layout sets the width. The phone's one-row toolbar sizes its buttons
      // to their words and has its own answer to a long language (`syncSqueeze`), which
      // must measure them at their real size.
      fitAll(
        page,
        '.game-page.railed .toolbar .btn, .game-page.railed .topbar .btn, .endgame-actions .btn, .endgame-title',
        0.65,
      );
      // The name is one line whatever it is (`RAIL_HEADER` counts on it), and big to begin
      // with, so it may give up a little more than a button's label.
      fitAll(page, '.topbar .title', 0.5);
      fitAll(page, '.topbar .preset-name', 0.7);
      // A select a little too narrow is fitted; one far too narrow ends in "…" instead.
      fitAll(page, '.game-page:not(.toolbar-tiered) .toolbar select', 0.7);
    });
  }

  /**
   * Change the zoom and refit. Past 1 the board is deliberately larger than the stage —
   * that is the whole point on a 30×16 Expert grid, whose squares are 11px wide at the
   * size that fits — so the stage becomes a scroller and the board can be panned around.
   *
   * `focalX`/`focalY` are a point on the screen to hold still (the middle of a pinch, say);
   * without them the middle of the board stays put.
   */
  function setZoom(next: number, focalX?: number, focalY?: number) {
    const z = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, next));
    if (Math.abs(z - zoom) < ZOOM_EPSILON) return;
    const before = canvas.getBoundingClientRect();
    // Where the focal point sits on the board, as a fraction of it, so it can be found
    // again once the tiles have been redrawn at their new size.
    const anchorX = focalX ?? before.left + before.width / 2;
    const anchorY = focalY ?? before.top + before.height / 2;
    const fx = before.width > 0 ? (anchorX - before.left) / before.width : 0.5;
    const fy = before.height > 0 ? (anchorY - before.top) / before.height : 0.5;
    zoom = z;
    const zoomed = zoom > 1 + ZOOM_EPSILON;
    page.classList.toggle('zoomed', zoomed);
    layout();
    if (!zoomed) {
      stage.scrollLeft = 0;
      stage.scrollTop = 0;
      if (focalX === undefined) zoomTo(canvas, before);
      return;
    }
    const after = canvas.getBoundingClientRect();
    stage.scrollLeft += after.left + fx * after.width - anchorX;
    stage.scrollTop += after.top + fy * after.height - anchorY;
    // The board is already drawn at its new size; this carries it there from the old one.
    // Deliberately after the scroll has been put right, so the anchor the caller asked to
    // hold still is where the journey ends. Only for the buttons: a pinch supplies its own
    // movement and calls this many times a second, where a quarter-second tween would be
    // nothing but lag — and a pinch is exactly the caller that passes a focal point.
    if (focalX === undefined) zoomTo(canvas, before);
  }

  const ro = new ResizeObserver(() => {
    if (window.innerWidth !== statusFloorWidth) holdStatusFloor();
    syncToolbarTier();
    syncSqueeze();
    layout();
    runner?.update();
  });
  ro.observe(stage);

  // ---- start
  if (willAutoStartTutorial) {
    // The tutorial's own first board, put up here rather than left to the startTutorial()
    // below. The play page is on screen for a beat before the tutorial speaks, and an
    // empty stage through that beat is what made arriving on a first puzzle read as a
    // blank flash with everything then appearing at once — most visible on Fifteen, the
    // first card in the collection and so the first board most players ever see. `goTo(0)`
    // loads the same id a moment later and lands on exactly this board, so nothing moves.
    const opening = game.tutorial?.steps.find((s) => s.gameId)?.gameId;
    holdForTutorial();
    if (opening && !midend.loadGameId(opening)) midend.newGame();
  } else if (gameId) {
    const guest = !isUnlocked(game.id);
    if (!(guest && restoreLinked(gameId))) {
      const err = midend.loadGameId(gameId);
      if (err) {
        toast(badCode(err), 'error');
        if (!tryRestore()) midend.newGame();
      } else {
        midend.newGame();
      }
    }
    if (guest) keepGuestLink();
    else history.replaceState(null, '', `#/${game.id}`);
  } else if (!tryRestore()) {
    midend.newGame();
  }
  layout();
  updateToolbar();
  // The page has its keypad now, if it is having one: from here on, one appearing or
  // going is the player's doing and worth animating. Deliberately after `updateToolbar`
  // and not after `setKeypadOn` above — at that point there is no puzzle yet, so the
  // keypad has no keys to show and its first real appearance is this one.
  keypadSettled = true;
  lastStatus = midend.status();
  // Every arrival deals its board in, the tutorial's opening board included; the only
  // page that does not is one whose tutorial had no board to open with.
  if (midend.hasGame) boardEnter(wrap);
  if (typeof document.fonts?.ready?.then === 'function') {
    document.fonts.ready.then(() => midend.redraw());
  }
  // Words measured in a fallback face are wider than in the hand one: once it is here,
  // ask again whether the phone row still needs its symbols.
  void handFontReady().then(() => {
    if (!page.isConnected) return;
    syncSqueeze();
    scheduleFit();
  });
  if (willAutoStartTutorial) {
    // Not over a sheet that is still coming down onto the desk (flight.ts).
    window.setTimeout(() => {
      void afterFlight().then(() => {
        if (page.isConnected) startTutorial();
      });
    }, 400);
  }

  // ---- toolbar actions
  // Bound to the toolbar and, while it is up, to the More sheet: the second tier's buttons
  // are the same elements, so one handler serves both.
  function onToolbarClick(e: Event) {
    const act = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-action]');
    if (act) {
      const spec = actionSpecs[actionBtns.indexOf(act)];
      if (spec) {
        keyPress(act);
        midend.processKey(0, 0, codeOf(spec.key));
      }
      // A repeatable action (a scroll arrow) keeps the sheet up, like the zoom pair.
      if (spec?.repeat && moreSheet) return;
      closeMoreSheet();
      canvas.focus({ preventScroll: true });
      return;
    }
    const b = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-cmd]');
    if (!b) return;
    const cmd = b.dataset.cmd;
    if (cmd === 'more') {
      openMoreSheet();
      return;
    }
    // Every command answers itself and the sheet gets out of the way — except the zoom
    // pair, which is meant to be pressed two or three times in a row.
    const keepSheet = cmd === 'zoom-in' || cmd === 'zoom-out' || cmd === 'settings';
    if (!keepSheet) closeMoreSheet();
    switch (cmd) {
      case 'settings':
        // Over the pause menu, which is still there when it closes: Esc takes one step back.
        openSettings();
        break;
      case 'new':
        leaveTutorial();
        freshGame();
        break;
      case 'restart':
        midend.restart();
        boardReset(wrap);
        break;
      case 'undo':
        midend.undo();
        break;
      case 'redo':
        midend.redo();
        break;
      case 'hint':
        takeHint();
        break;
      case 'solve':
        midend.solve();
        break;
      case 'id':
        openIdDialog();
        break;
      case 'zoom-in':
        setZoom(zoom * ZOOM_STEP);
        break;
      case 'zoom-out':
        setZoom(zoom / ZOOM_STEP);
        break;
      case 'tap-mode':
        setTapMode(tapMode === 'place' ? 'mark' : 'place', true);
        break;
      case 'keypad-toggle':
        setKeypadOn(!keypadOn);
        break;
    }
    // The board keeps the keyboard, unless the sheet is still up and wants it.
    if (!keepSheet || !moreSheet) canvas.focus({ preventScroll: true });
  }
  toolbar.addEventListener('click', onToolbarClick);

  typeSelect.addEventListener('change', async () => {
    const v = typeSelect.value;
    // Picking a type is picking the next puzzle: the pause menu it sits in has done its job.
    closeMoreSheet();
    // A browser that lists hidden options (iOS) may offer the twin too: it means the same.
    if (v === 'custom' || v === CUSTOM_NOW) {
      await openCustomDialog();
      updateToolbar();
    } else {
      leaveTutorial();
      midend.setParams(structuredClone(game.presets[Number(v)].params));
      freshGame();
    }
    canvas.focus({ preventScroll: true });
  });

  async function openCustomDialog() {
    if (!game.configure || !game.customParams) return;
    // Opened over a tutorial, it starts from the type the player will be handed back, not
    // from the tutorial's toy board.
    const items = game.configure(
      (tutorialActive && tutorialReturn
        ? tutorialReturn.params
        : midend.params) as typeof midend.params,
    );
    // The dialog edits a localised copy; `customParams` still reads the game's own rows,
    // so a translated label can never reach a game's parsing.
    const shown = localiseConfig(game, items);
    const result = await configDialog(t('ui.dialog.customTitle', { name }), shown, (its) => {
      try {
        const p = game.customParams!(mergeConfig(items, its));
        return game.validateParams(p, true);
      } catch (e) {
        return (e as Error).message;
      }
    });
    if (!result) return;
    leaveTutorial();
    midend.setParams(game.customParams(mergeConfig(items, result)));
    freshGame();
  }

  /**
   * What a player is told about a code that does not load. The game's own reason is a
   * parser's ("Invalid parameters: expected w<W>h<H>m<MIN>M<MAX>"), useful to the one who
   * wrote the parser and to nobody holding a pasted link — so it goes to the console, and
   * the player hears what to do about it.
   */
  function badCode(detail: string): string {
    console.debug(`[${game.id}] puzzle code rejected: ${detail}`);
    // A size or setting the game refuses says why in the game's own (translated) words —
    // "check you copied all of it" is no help for a 99×99 that was copied perfectly.
    if (midend.paramsRejected) return detail;
    return t('ui.dialog.badCode', { name });
  }

  function openIdDialog() {
    stats.shareOpened();
    gameIdDialog({
      descId: midend.shareGameId(),
      // Once the board has settled past its seed (Mines after the first click) the seed
      // would deal a different one, so only the settled description is offered.
      seedId: midend.settledPastSeed() ? null : midend.seedId(),
      shareUrl: async (descId) => {
        const id = (game.flags?.shareBySeed && midend.seedId()) || descId;
        // Inside the platform's frame our own origin is the iframe's — the host the build
        // sits on, not a page anyone can be sent to — so the platform's invite link is the
        // only address worth copying. `inviteLink` answers `null` everywhere else, and
        // everywhere else our own URL is exactly right. See docs/CRAZYGAMES.md.
        const invite = await inviteLink({ puzzle: game.id, id });
        if (invite) return invite;
        const base = `${location.origin}${location.pathname}`;
        return `${base}#/${game.id}/${encodeURIComponent(id)}`;
      },
      load: (id) => {
        const err = midend.loadGameId(id);
        if (err) return badCode(err);
        leaveTutorial(true);
        freshGame();
        return null;
      },
    });
  }

  // ---- help drawer
  /** Set while the drawer is open: gives the phone's Back its job of closing it. */
  let releaseHelpBack: (() => void) | null = null;
  /** What had the keys when the drawer opened, so closing it hands them back there. */
  let helpOpener: HTMLElement | null = null;
  const toggleHelp = (open?: boolean) => {
    const on = open ?? !drawer.classList.contains('open');
    if (on === drawer.classList.contains('open')) return;
    if (on) {
      const a = document.activeElement;
      helpOpener = a instanceof HTMLElement && a !== document.body ? a : null;
    }
    drawer.classList.toggle('open', on);
    playSound(on ? 'swish' : 'swishOut');
    releaseHelpBack?.();
    releaseHelpBack = on ? pushLayer(() => toggleHelp(false)) : null;
    slideDrawer(drawer, on);
    // The first-visit tip is about the board, and on a phone it would float over the help.
    if (on) hideToast();
    // The board moves out from under it rather than being read through it: opening Help to
    // check a rule should not hide the row the question is about.
    layout();
    helpBtn.setAttribute('aria-expanded', String(on));
    if (on) {
      stats.helpOpened();
      drawer.inert = false;
      // As the drawer finishes sliding in, so the hop is seen rather than spent off-screen.
      gsap.delayedCall(0.28, () => {
        if (drawer.classList.contains('open')) drawerMascot?.cheer();
      });
    } else {
      // Take focus out before hiding it from the tree, or the browser is left focusing
      // nothing and the next Tab starts from the top of the document. Back to what opened
      // it: the Help button, or the board a `?` (or a pad's Back) was pressed on. Opened
      // from the pause menu, which is gone now, the player goes back to the board.
      if (drawer.contains(document.activeElement)) {
        const back = helpOpener?.isConnected && !drawer.contains(helpOpener) ? helpOpener : canvas;
        back.focus({ preventScroll: true });
      }
      helpOpener = null;
      drawer.inert = true;
    }
  };
  helpBtn.addEventListener('click', (e) => {
    toggleHelp();
    // Opened from the keyboard (a click with no pointer behind it), the reader is taken
    // into the drawer: left on the Help button, the rules were a long Tab walk away,
    // past the whole toolbar and the board. A mouse leaves the board's focus alone.
    if (e.detail === 0 && drawer.classList.contains('open')) {
      closeHelp.focus({ preventScroll: true });
    }
  });
  closeHelp.addEventListener('click', () => toggleHelp(false));

  // ---- pointer input
  interface Pointer {
    id: number;
    button: number | null; // button code sent as "down", or null if pending (touch)
    startX: number;
    startY: number;
    /** Viewport coordinates, kept up to date so a two-finger gesture can measure them. */
    clientX: number;
    clientY: number;
    timer: number | null;
    type: string;
  }
  let pointer: Pointer | null = null;
  let touchCount = 0;

  /**
   * A second finger on the board. It was always the middle click — Net's lock — and it
   * still is, as long as neither finger travels: what changes is that a two-finger *drag*
   * now pans the zoomed board and a two-finger *spread* zooms it, which is the only way to
   * make a 30×16 grid's squares tappable and then reach the far corner of one.
   *
   * Deliberately two fingers and not one: one finger belongs to the puzzle. Untangle drags
   * points, Bridges and Signpost drag between squares, and `TOUCH_SLOP` already turns a
   * one-finger slide into a game drag — a pan gesture there would fight all of them.
   */
  interface Gesture {
    /** The second pointer; the first is `pointer`. */
    id: number;
    /** Set once either finger has travelled far enough to mean it. */
    moved: boolean;
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    /** Midpoint of the two fingers at the last frame, in viewport coordinates. */
    lastCx: number;
    lastCy: number;
    startDist: number;
    startZoom: number;
  }
  let gesture: Gesture | null = null;
  /** True from the end of a gesture until every finger is off the glass. */
  let settling = false;

  // ---- tap mode (touch only)
  // A plain tap sends `tapButton`; a long press sends the other one, so both actions stay
  // reachable whichever way round the switch is.
  // A one-button game has no switch, so a "mark" left over from before it lost it must not
  // quietly turn every tap into a right click that does nothing.
  let tapMode: TapMode = game.flags?.oneButton ? 'place' : loadTapMode(game);
  // A lit HUD tool (Erase, Lock, Cross…) is what the player just asked a tap to do, so
  // while one is on a plain tap is the left button and a long-press the right, whatever the
  // Tap switch says: with "Tap: mark" left over from earlier, lighting the eraser in
  // Pattern used to lay dots and erase only on a long-press. A `view` toggle (Highlight,
  // Numbers) is not a tool for the finger and leaves the switch in charge.
  const toolLit = (): boolean => {
    if (!midend.hasGame) return false;
    const state = midend.state;
    return actionSpecs.some((a) => a.hud && !a.view && !!a.pressed?.(state, midend.ui));
  };
  // A tutorial's steps are written for the plain setting ("tap here", "long-press
  // there"), so while one runs the switch stands down too: with "Tap: mark" left on, the
  // long-press that Mines' tutorial asks for opened a mine.
  const tapMarks = () => tapMode === 'mark' && !tutorialActive && !toolLit();
  const tapButton = () => (tapMarks() ? RIGHT_BUTTON : LEFT_BUTTON);
  const holdButton = () => (tapMarks() ? LEFT_BUTTON : RIGHT_BUTTON);

  function setTapMode(mode: TapMode, announce = false) {
    tapMode = mode;
    setLabel(btnTap, t(mode === 'mark' ? 'ui.toolbar.tapMark' : 'ui.toolbar.tapPlace'));
    btnTap.dataset.mode = mode;
    btnTap.setAttribute('aria-pressed', String(mode === 'mark'));
    btnTap.title = t(mode === 'mark' ? 'ui.toolbar.tapMarkTitle' : 'ui.toolbar.tapPlaceTitle');
    // "Tap: mark" is not "Tap: place" in width, in most languages.
    syncSqueeze();
    try {
      localStorage.setItem(tapModeKey(game), mode);
    } catch {
      /* storage unavailable: ignore */
    }
    if (announce) {
      toast(t(mode === 'mark' ? 'ui.toast.tapModeMark' : 'ui.toast.tapModePlace'));
    }
  }
  setTapMode(tapMode);

  // The first-visit touch tip is about how to play, so it goes the moment the player
  // does: a press on the board or on any control. (It sat over the board through four
  // Hint presses on Solo, since each of them re-raised the notice timer.)
  let touchTipUp = false;
  page.addEventListener(
    'pointerdown',
    () => {
      if (!touchTipUp) return;
      touchTipUp = false;
      if (document.querySelector('.toast')?.textContent === t('ui.toast.touchHint')) hideToast();
    },
    { capture: true },
  );
  if (touch) {
    let hinted = true;
    try {
      hinted = localStorage.getItem(TAP_HINT_KEY) === '1';
    } catch {
      /* storage unavailable: skip the hint */
    }
    // The tutorial teaches the same thing, so only hint when it is not about to run.
    const tutorialWillRun = !!game.tutorial && !gameId && !tutorialSeen(game.id);
    if (!hinted && !tutorialWillRun && !game.flags?.oneButton) {
      window.setTimeout(() => {
        if (!page.isConnected) return;
        // Help, a dialog or a tutorial already opened in the meantime: the tip is about the
        // board and would only float over them. It waits for the next visit instead.
        if (
          drawer.classList.contains('open') ||
          document.querySelector('.dimmer') ||
          tutorialActive
        )
          return;
        toast(t('ui.toast.touchHint'));
        touchTipUp = true;
        try {
          localStorage.setItem(TAP_HINT_KEY, '1');
        } catch {
          /* ignore */
        }
      }, 600);
    }
  }

  const canvasCoords = (e: PointerEvent) => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const mouseButton = (e: PointerEvent): number => {
    if (e.button === 2 || ((e.ctrlKey || e.metaKey) && e.button === 0)) return RIGHT_BUTTON;
    if (e.button === 1 || (e.shiftKey && e.button === 0)) return MIDDLE_BUTTON;
    return LEFT_BUTTON;
  };
  const send = (x: number, y: number, b: number) => {
    midend.processKey(Math.round(x), Math.round(y), b);
  };
  /**
   * The same, for the press that *starts* an interaction. `processKey` returning false is
   * the board saying no — a given clue, a wall, a square this button does nothing to — and
   * that deserves an answer. Drags and releases go through `send` instead: they are the
   * tail of a decision the player has already made, and sounding them would turn one
   * stroke across a grid into a stutter.
   */
  const press = (x: number, y: number, b: number) => {
    lastPress = { x, y };
    if (!midend.processKey(Math.round(x), Math.round(y), b)) playSound('reject');
  };

  // Soft glow that trails the pointer over the board (mouse only).
  const glowX = gsap.quickTo(glow, 'x', { duration: 0.25, ease: 'power2.out' });
  const glowY = gsap.quickTo(glow, 'y', { duration: 0.25, ease: 'power2.out' });
  canvas.addEventListener('pointermove', (e) => {
    if (e.pointerType !== 'mouse') return;
    const { x, y } = canvasCoords(e);
    if (glow.hidden) {
      glow.hidden = false;
      gsap.set(glow, { x, y });
      gsap.fromTo(glow, { opacity: 0 }, { opacity: 1, duration: 0.2 });
    }
    glowX(x);
    glowY(y);
  });
  canvas.addEventListener('pointerleave', () => {
    gsap.to(glow, { opacity: 0, duration: 0.2, onComplete: () => (glow.hidden = true) });
  });
  canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  // A second finger that lands just off the board — which is where it goes when a
  // two-finger tap is centred on an edge tile — still belongs to the board's gesture.
  // Capture it to the canvas so its moves and its lift arrive there too. (A control it
  // happens to land on keeps its press.)
  page.addEventListener('pointerdown', (e) => {
    if (e.target === canvas || e.pointerType !== 'touch' || pointer?.type !== 'touch') return;
    if ((e.target as Element).closest?.('button, select, input, a, label')) return;
    try {
      canvas.setPointerCapture(e.pointerId);
    } catch {
      return;
    }
    onCanvasPointerDown(e);
  });
  canvas.addEventListener('pointerdown', (e) => onCanvasPointerDown(e));
  function onCanvasPointerDown(e: PointerEvent) {
    canvas.focus({ preventScroll: true });
    if (e.pointerType === 'touch') touchCount++;
    // A gesture has just finished; the fingers still down belong to it, not to a new move.
    if (settling) return;
    // The board on screen is on its way out (see freshGame): nothing played on it counts.
    if (dealing) return;
    if (pointer) {
      // A second touch while one is held: hold the middle click back until the fingers
      // lift, so that a two-finger *drag* can pan and pinch instead.
      if (e.pointerType === 'touch' && pointer.button === null && !gesture) {
        clearLongPress(pointer);
        e.preventDefault();
        gesture = {
          id: e.pointerId,
          moved: false,
          x1: pointer.clientX,
          y1: pointer.clientY,
          x2: e.clientX,
          y2: e.clientY,
          lastCx: (pointer.clientX + e.clientX) / 2,
          lastCy: (pointer.clientY + e.clientY) / 2,
          startDist: Math.hypot(e.clientX - pointer.clientX, e.clientY - pointer.clientY),
          startZoom: zoom,
        };
      }
      return;
    }
    e.preventDefault();
    canvas.setPointerCapture(e.pointerId);
    const { x, y } = canvasCoords(e);
    pointer = {
      id: e.pointerId,
      button: null,
      startX: x,
      startY: y,
      clientX: e.clientX,
      clientY: e.clientY,
      timer: null,
      type: e.pointerType,
    };
    if (e.pointerType === 'touch') {
      pointer.timer = window.setTimeout(() => {
        if (pointer && pointer.button === null) {
          pointer.button = holdButton();
          press(pointer.startX, pointer.startY, pointer.button);
          if (navigator.vibrate) navigator.vibrate(10);
        }
      }, LONG_PRESS_MS);
    } else {
      pointer.button = mouseButton(e);
      press(x, y, pointer.button);
    }
  }
  function clearLongPress(p: Pointer) {
    if (p.timer) clearTimeout(p.timer);
    p.timer = null;
  }
  /**
   * One frame of a two-finger gesture: the midpoint of the fingers drags the board about
   * and the distance between them sets the zoom. Until one of the two has moved further
   * than a fingertip wobbles, nothing happens at all — that is still a two-finger tap.
   */
  function updateGesture(g: Gesture) {
    const cx = (g.x1 + g.x2) / 2;
    const cy = (g.y1 + g.y2) / 2;
    const dist = Math.hypot(g.x2 - g.x1, g.y2 - g.y1);
    if (!g.moved) {
      const spread = Math.abs(dist - g.startDist);
      const slid = Math.hypot(cx - g.lastCx, cy - g.lastCy);
      if (spread < TOUCH_SLOP && slid < TOUCH_SLOP) return;
      g.moved = true;
      g.lastCx = cx;
      g.lastCy = cy;
    }
    stage.scrollLeft -= cx - g.lastCx;
    stage.scrollTop -= cy - g.lastCy;
    g.lastCx = cx;
    g.lastCy = cy;
    if (g.startDist <= 0) return;
    // Measured against the start of the gesture, so the zoom never drifts away from where
    // the fingers say it should be, however many steps it took to get there.
    const want = (g.startZoom * dist) / g.startDist;
    const far = want > zoom * PINCH_STEP || want < zoom / PINCH_STEP;
    // The last step into either end is worth taking whatever its size, or a pinch can
    // never quite reach the biggest squares it is reaching for.
    if (far || want >= MAX_ZOOM || want <= MIN_ZOOM) setZoom(want, cx, cy);
  }

  canvas.addEventListener('pointermove', (e) => {
    if (gesture && (e.pointerId === gesture.id || e.pointerId === pointer?.id)) {
      e.preventDefault();
      if (e.pointerId === gesture.id) {
        gesture.x2 = e.clientX;
        gesture.y2 = e.clientY;
      } else {
        gesture.x1 = e.clientX;
        gesture.y1 = e.clientY;
        pointer!.clientX = e.clientX;
        pointer!.clientY = e.clientY;
      }
      updateGesture(gesture);
      return;
    }
    if (!pointer || e.pointerId !== pointer.id) return;
    e.preventDefault();
    pointer.clientX = e.clientX;
    pointer.clientY = e.clientY;
    const { x, y } = canvasCoords(e);
    if (pointer.button === null) {
      if (Math.hypot(x - pointer.startX, y - pointer.startY) > TOUCH_SLOP) {
        clearLongPress(pointer);
        pointer.button = tapButton();
        press(pointer.startX, pointer.startY, pointer.button);
      } else {
        return;
      }
    }
    send(x, y, pointer.button + (LEFT_DRAG - LEFT_BUTTON));
  });
  const finish = (e: PointerEvent) => {
    // The browser or the system took the touch away (an edge swipe, the notification
    // shade): a press that has not started yet never happens. One already under way still
    // gets its release, which every drag needs to end.
    const cancelled = e.type === 'pointercancel';
    if (e.pointerType === 'touch') {
      touchCount = Math.max(0, touchCount - 1);
      if (touchCount === 0) settling = false;
    }
    if (gesture && (e.pointerId === gesture.id || e.pointerId === pointer?.id)) {
      e.preventDefault();
      const g = gesture;
      gesture = null;
      // Two fingers down and up again without travelling: the middle click it always was,
      // sent between the two fingers. Two fingertips side by side cannot both be on one
      // Guess peg, and sent at the second finger it held the peg next door.
      if (!g.moved && !cancelled) {
        const r = canvas.getBoundingClientRect();
        const mx = (g.x1 + g.x2) / 2 - r.left;
        const my = (g.y1 + g.y2) / 2 - r.top;
        press(mx, my, MIDDLE_BUTTON);
        send(mx, my, MIDDLE_BUTTON + (LEFT_RELEASE - LEFT_BUTTON));
      }
      if (pointer) clearLongPress(pointer);
      pointer = null;
      // Whatever is still on the glass belongs to the gesture that just ended.
      settling = touchCount > 0;
      return;
    }
    if (!pointer || e.pointerId !== pointer.id) return;
    e.preventDefault();
    const { x, y } = canvasCoords(e);
    clearLongPress(pointer);
    if (pointer.button === null) {
      if (cancelled) {
        pointer = null;
        return;
      }
      pointer.button = tapButton();
      press(pointer.startX, pointer.startY, pointer.button);
    }
    send(x, y, pointer.button + (LEFT_RELEASE - LEFT_BUTTON));
    pointer = null;
  };
  canvas.addEventListener('pointerup', finish);
  canvas.addEventListener('pointercancel', finish);

  // ---- keyboard input
  function keyCode(e: KeyboardEvent): number | null {
    let code: number | null = null;
    switch (e.key) {
      case 'Backspace':
      case 'Delete':
        code = KEY_BACKSPACE;
        break;
      case 'Enter':
        code = KEY_ENTER;
        break;
      case 'ArrowLeft':
        code = CURSOR_LEFT;
        break;
      case 'ArrowRight':
        code = CURSOR_RIGHT;
        break;
      case 'ArrowUp':
        code = CURSOR_UP;
        break;
      case 'ArrowDown':
        code = CURSOR_DOWN;
        break;
      case 'End':
        code = MOD_NUM_KEYPAD | '1'.charCodeAt(0);
        break;
      case 'PageDown':
        code = MOD_NUM_KEYPAD | '3'.charCodeAt(0);
        break;
      case 'Home':
        code = MOD_NUM_KEYPAD | '7'.charCodeAt(0);
        break;
      case 'PageUp':
        code = MOD_NUM_KEYPAD | '9'.charCodeAt(0);
        break;
      default:
        if (e.key.length === 1) {
          code = e.key.charCodeAt(0);
          if (e.location === 3 && code >= 48 && code <= 57) code |= MOD_NUM_KEYPAD;
        }
    }
    if (code === null) return null;
    if (e.shiftKey && code >= 0x100) code |= MOD_SHFT;
    if (e.ctrlKey || e.metaKey) {
      if (code >= 0x100) code |= MOD_CTRL;
      else code = (code & 0x1f) | MOD_CTRL;
      // Ctrl+Shift+Z / Cmd+Shift+Z is redo almost everywhere else; it must not undo.
      if (e.shiftKey && e.key.toLowerCase() === 'z') code = 0x19 | MOD_CTRL;
    }
    return code;
  }
  const SCROLL_KEYS = new Set([
    ' ',
    'Enter',
    'ArrowUp',
    'ArrowDown',
    'ArrowLeft',
    'ArrowRight',
    'PageUp',
    'PageDown',
    'Home',
    'End',
  ]);
  const onKeyDown = (e: KeyboardEvent) => {
    const target = e.target as HTMLElement;
    if (target !== canvas) {
      if (target.closest('input, select, textarea, .modal, [contenteditable]')) return;
      if (document.querySelector('.dimmer')) return;
      // A button or link has the keyboard (the toolbar, the end-of-game panel, the help
      // drawer): Enter and Space are its own, to activate it — sent to the board as well,
      // they made a move at the cursor, and the board's preventDefault then swallowed the
      // button's click, so Tab to Undo + Enter moved instead of undoing. Every other key
      // still goes through, so Undo (U, Ctrl+Z) works from any of them.
      if ((e.key === 'Enter' || e.key === ' ') && target.closest('button, a[href], summary'))
        return;
      // Reading the help: the keys that scroll it are the drawer's own. Undo, `?` and Esc
      // still work from there.
      if (target.closest('.drawer-body') && SCROLL_KEYS.has(e.key)) return;
    }
    if (e.key === '?') {
      toggleHelp();
      e.preventDefault();
      return;
    }
    // Esc (a pad's B) on the keypad goes back to the board without typing anything.
    if (e.key === 'Escape' && keypadEl.contains(target)) {
      canvas.focus({ preventScroll: true });
      e.preventDefault();
      return;
    }
    if (e.key === 'Escape' && drawer.classList.contains('open')) {
      toggleHelp(false);
      return;
    }
    if (e.key === 'Escape' && !endgame.hidden) {
      dismissEndgame();
      canvas.focus({ preventScroll: true });
      e.preventDefault();
      return;
    }
    // Esc with nothing else to close pauses, as it does in any game. The menu closes itself
    // on the next Esc (`openModal`), so the key toggles.
    if (e.key === 'Escape' && !runner?.active && !document.querySelector('.dimmer')) {
      openMoreSheet();
      e.preventDefault();
      return;
    }
    // Leave browser shortcuts alone. `r` among them: Ctrl+R / Cmd+R is how a page is
    // reloaded, and the midend's Tatham-era Ctrl+R redo swallowed it — Redo is `R` or
    // `Ctrl+Y`, which is what the help documents.
    if (
      (e.metaKey || e.ctrlKey) &&
      ['c', 'v', 'x', 'a', 'l', 't', 'w', 'q', 'r', '='].includes(e.key.toLowerCase())
    ) {
      return;
    }
    if ((e.metaKey || e.ctrlKey) && e.key === '-') return;
    // H is the Hint button in every game that offers one, as it was when Range and Flood
    // drew their own; no game with a hint gives the key a meaning of its own.
    if (game.hint && !e.metaKey && !e.ctrlKey && !e.altKey && e.key.toLowerCase() === 'h') {
      if (!btnHint.disabled) void takeHint();
      e.preventDefault();
      return;
    }
    // Ctrl+S is Solve inside the midend; it answers to the button's state like H does.
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's' && btnSolve.disabled) {
      e.preventDefault();
      return;
    }
    // N is New inside the midend, which would deal under a running tutorial and skips
    // everything the button does around the deal: a generator that throws went to the
    // console instead of a toast, and the board was neither refitted nor dealt in. It goes
    // the way the New button does. No game gives the key a meaning of its own.
    if (!e.metaKey && !e.ctrlKey && !e.altKey && e.key.toLowerCase() === 'n' && !dealing) {
      e.preventDefault();
      leaveTutorial();
      freshGame();
      return;
    }
    const code = keyCode(e);
    if (code === null || dealing) return;
    lastPress = null;
    const handled = midend.processKey(0, 0, code);
    if (handled || code >= 0x100 || e.key === ' ' || e.key === 'Backspace') e.preventDefault();
  };
  document.addEventListener('keydown', onKeyDown);

  const onVisibility = () => {
    if (document.visibilityState === 'hidden') saveNow();
    // Time away from the tab is not time spent stuck on the board.
    else idleFrom = performance.now();
  };

  /**
   * A player who has not touched the board for a while, early in a puzzle, is very often a
   * player about to leave it — and the one button made for that moment sits quietly in the
   * corner. So once per board, at most twice a visit, Hint gives a wiggle and a line says
   * what it costs (nothing, up to the allowance). Never in the tutorial, over a dialog or
   * the help, on a finished board, or once a hint has been taken: they know where it is.
   */
  function checkStuck() {
    if (!game.hint || !midend.hasGame || tutorialActive || stuckNudges >= STUCK_NUDGES_PER_VISIT)
      return;
    if (document.visibilityState !== 'visible' || moreSheet || !endgame.hidden) return;
    if (drawer.classList.contains('open') || document.querySelector('.dimmer')) return;
    if (btnHint.disabled || midend.status() !== 0 || midend.hintsUsed() > 0) return;
    const id = midend.gameId();
    if (nudgedFor === id || performance.now() - idleFrom < STUCK_AFTER_MS) return;
    nudgedFor = id;
    stuckNudges++;
    wiggle(btnHint);
    btnHint.classList.add('nudged');
    window.setTimeout(() => btnHint.classList.remove('nudged'), 4000);
    toast(t('ui.toast.stuck'));
  }
  const stuckTimer = window.setInterval(checkStuck, 5000);
  document.addEventListener('visibilitychange', onVisibility);

  (window as any).__puzzlebox = {
    midend,
    game,
    canvas,
    startTutorial,
    get tutorialActive() {
      return tutorialActive;
    },
    get tapMode() {
      return tapMode;
    },
    get keypadOn() {
      return !keypadEl.hidden;
    },
    get endgameShown() {
      return !endgame.hidden;
    },
    get pencilOn() {
      return pencilOn;
    },
    get zoom() {
      return zoom;
    },
    get moreOpen() {
      return !!moreSheet;
    },
  };
  canvas.focus({ preventScroll: true });

  return {
    midend,
    /** Whether the board on show is a tutorial's, which is never the player's game. */
    get tutorialActive() {
      return tutorialActive;
    },
    destroy() {
      releaseHelpBack?.();
      saveNow();
      stats.leave();
      run.destroy();
      unsubAdClock();
      clearTimeout(midgameAdTimer);
      clearInterval(stuckTimer);
      closeMoreSheet();
      hideEndgame(true);
      endMascot?.destroy();
      drawerMascot?.destroy();
      runner?.destroy();
      unsubProgress();
      ro.disconnect();
      document.removeEventListener('keydown', onKeyDown);
      window.removeEventListener(PAD_KEYPAD_EVENT, onPadKeypad);
      document.removeEventListener('visibilitychange', onVisibility);
      midend.destroy();
      // `quickTo` parks a paused tween in GSAP's global timeline, and a paused tween is
      // never cleaned up by itself — so every play page the pointer never crossed (every
      // one, on a phone) stayed reachable through the glow it targets, canvas and all.
      glowX.tween.kill();
      glowY.tween.kill();
      gsap.killTweensOf(glow);
      delete (window as any).__puzzlebox;
      document.documentElement.classList.remove('playing');
      page.remove();
    },
  };
}
