/**
 * The browser, taken out of the picture.
 *
 * A game made in an engine never shows the machinery it runs in: no URL in the corner
 * when the pointer crosses a button, no grey system tooltip, no system arrow, no "Save
 * page as…" on Ctrl+S, no browser menu on a right-click, no page zooming in on a double
 * tap, no text turning blue under a drag. Each of those says "web page", and each is
 * removed here — once, for the whole shell, rather than at every call site:
 *
 * - **Links** (`<a href="#/…">`) become in-game links: the address moves to `data-href`,
 *   so there is no URL preview, and the element keeps `role="link"`, the Tab order and
 *   Enter, so it is still a link to a keyboard and a screen reader.
 * - **Tooltips**: a `title` is lifted into a drawn note the first time the pointer rests
 *   on the element (`data-tip`), so the words stay and the system box never appears.
 * - **Cursors** are drawn in the palette — an inked arrow, the same arrow in the accent
 *   over anything that can be pressed, and a pencil over the board — as `--cur-*`.
 * - **Dropdowns**: a mouse opening a `<select>` gets a sketched list instead of the
 *   operating system's. A finger keeps the native picker, which is the better one there.
 * - **Keys and gestures**: the browser's right-click menu, Ctrl+S and Ctrl+P, and
 *   double-tap zoom are turned off; text selection is off outside fields (feel.css).
 *
 * Nothing here may break a control: every listener is delegated and defensive, and an
 * element this does not recognise is left exactly as it was.
 */

import { PALETTE } from '../framework/palette';

// ------------------------------------------------------------------ cursors

/** An SVG cursor as a CSS `cursor` value, with its hotspot and a system fallback. */
function cursor(svg: string, x: number, y: number, fallback: string): string {
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}") ${x} ${y}, ${fallback}`;
}

function cursors(): Record<string, string> {
  const { ink, paper, accent, yellow, pink } = PALETTE;
  const svg = (body: string) =>
    `<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 28 28">${body}</svg>`;
  // A drawn arrow: not quite straight, as if inked with a nib.
  const arrow = (fill: string) =>
    svg(
      `<path d="M4 3.2 4.3 21.4 9.1 16.8 12.6 24.3 15.7 22.9 12.2 15.5 18.7 15.1Z" fill="${fill}" stroke="${ink}" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>`,
    );
  // A pencil lying at 45°, writing with its tip in the bottom-left corner.
  const pencil = svg(
    `<g stroke="${ink}" stroke-width="1.4" stroke-linejoin="round">` +
      `<path d="M19.7 3.7 22.7 0.9 27.1 5.3 24.3 8.3Z" fill="${pink}"/>` +
      `<path d="M5.7 17.7 19.7 3.7 24.3 8.3 10.3 22.3Z" fill="${yellow}"/>` +
      `<path d="M3 25 5.7 17.7 10.3 22.3Z" fill="${paper}"/>` +
      `<path d="M3 25 4.1 22 6 23.9Z" fill="${ink}"/></g>`,
  );
  return {
    '--cur-default': cursor(arrow(paper), 4, 3, 'default'),
    '--cur-pointer': cursor(arrow(accent), 4, 3, 'pointer'),
    '--cur-pencil': cursor(pencil, 3, 25, 'crosshair'),
  };
}

// ------------------------------------------------------------------ links

const LINK = 'a[href^="#"]';

/** Take the address off a link, so hovering it shows nothing, and keep it a link. */
function adoptLink(a: HTMLAnchorElement): void {
  const href = a.getAttribute('href');
  if (href === null) return;
  a.dataset.href = href;
  a.removeAttribute('href');
  a.setAttribute('role', 'link');
  if (!a.hasAttribute('tabindex')) a.tabIndex = 0;
}

function adoptLinksIn(root: ParentNode): void {
  if (root instanceof HTMLAnchorElement && root.matches(LINK)) adoptLink(root);
  root.querySelectorAll<HTMLAnchorElement>(LINK).forEach(adoptLink);
}

function follow(el: HTMLElement): void {
  const to = el.dataset.href;
  if (!to || to === '#') return;
  if (location.hash === to) return;
  location.hash = to;
}

// ------------------------------------------------------------------ tooltips

const TIP_DELAY_MS = 450;
let tip: HTMLElement | null = null;
let tipFor: Element | null = null;
let tipTimer = 0;

function hideTip(): void {
  window.clearTimeout(tipTimer);
  tipFor = null;
  tip?.remove();
  tip = null;
}

/** Move a `title` into `data-tip`, keeping it as the name when it was the only one. */
function adoptTitle(el: HTMLElement): string {
  const title = el.getAttribute('title');
  if (title !== null) {
    el.dataset.tip = title;
    el.removeAttribute('title');
    if (!el.hasAttribute('aria-label') && !(el.textContent ?? '').trim()) {
      el.setAttribute('aria-label', title);
    }
  }
  return el.dataset.tip ?? '';
}

function showTip(el: HTMLElement): void {
  const text = el.dataset.tip;
  if (!text || !el.isConnected) return;
  tip?.remove();
  tip = document.createElement('div');
  tip.className = 'tip';
  tip.setAttribute('role', 'tooltip');
  tip.textContent = text;
  document.body.append(tip);
  const r = el.getBoundingClientRect();
  const t = tip.getBoundingClientRect();
  const gap = 8;
  let top = r.bottom + gap;
  if (top + t.height > window.innerHeight - 4) top = r.top - gap - t.height;
  const left = Math.max(
    6,
    Math.min(window.innerWidth - t.width - 6, r.left + r.width / 2 - t.width / 2),
  );
  tip.style.left = `${left}px`;
  tip.style.top = `${Math.max(4, top)}px`;
}

// ------------------------------------------------------------------ dropdowns

let list: HTMLElement | null = null;
let listFor: HTMLSelectElement | null = null;

function closeList(refocus = true): void {
  const was = listFor;
  list?.remove();
  list = null;
  listFor = null;
  if (refocus && was?.isConnected) was.focus({ preventScroll: true });
}

function choose(select: HTMLSelectElement, value: string): void {
  closeList();
  if (select.value === value) return;
  select.value = value;
  select.dispatchEvent(new Event('input', { bubbles: true }));
  select.dispatchEvent(new Event('change', { bubbles: true }));
}

/** A sketched list of `select`'s options, under it, in place of the system's. */
function openList(select: HTMLSelectElement): void {
  closeList(false);
  const options = [...select.options].filter((o) => !o.hidden);
  if (!options.length) return;
  list = document.createElement('div');
  list.className = 'sketch-list';
  list.setAttribute('role', 'listbox');
  listFor = select;
  for (const o of options) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'sketch-option';
    b.setAttribute('role', 'option');
    b.textContent = o.textContent;
    b.disabled = o.disabled;
    b.dataset.value = o.value;
    if (o.selected) b.setAttribute('aria-selected', 'true');
    b.addEventListener('click', () => choose(select, o.value));
    list.append(b);
  }
  document.body.append(list);
  const r = select.getBoundingClientRect();
  list.style.minWidth = `${r.width}px`;
  const lr = list.getBoundingClientRect();
  const below = window.innerHeight - r.bottom - 8;
  const above = r.top - 8;
  const maxH = Math.max(120, below >= Math.min(lr.height, 260) || below >= above ? below : above);
  list.style.maxHeight = `${maxH}px`;
  const h = Math.min(lr.height, maxH);
  const top = below >= h || below >= above ? r.bottom + 4 : r.top - 4 - h;
  const left = Math.max(6, Math.min(window.innerWidth - lr.width - 6, r.left));
  list.style.left = `${left}px`;
  list.style.top = `${top}px`;
  const current =
    list.querySelector<HTMLElement>('[aria-selected="true"]') ?? list.querySelector('button');
  current?.focus({ preventScroll: true });
  current?.scrollIntoView({ block: 'nearest' });
}

function moveInList(step: number): void {
  if (!list) return;
  const items = [...list.querySelectorAll<HTMLButtonElement>('.sketch-option:not(:disabled)')];
  const at = items.indexOf(document.activeElement as HTMLButtonElement);
  const next = items[Math.max(0, Math.min(items.length - 1, (at < 0 ? 0 : at) + step))];
  next?.focus({ preventScroll: true });
  next?.scrollIntoView({ block: 'nearest' });
}

// ------------------------------------------------------------------ install

let installed = false;

export function installGameFeel(): void {
  if (installed || typeof document === 'undefined') return;
  installed = true;
  const root = document.documentElement;
  for (const [k, v] of Object.entries(cursors())) root.style.setProperty(k, v);

  // Links: those on the page now, and every one the shell draws from here on.
  adoptLinksIn(document.body);
  new MutationObserver((records) => {
    for (const rec of records) {
      if (rec.type === 'attributes') {
        const t = rec.target;
        if (t instanceof HTMLAnchorElement && t.matches(LINK)) adoptLink(t);
        continue;
      }
      for (const node of rec.addedNodes) if (node instanceof HTMLElement) adoptLinksIn(node);
    }
  }).observe(document.body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['href'],
  });
  // Last in line, so a link's own handler can still call it off.
  document.addEventListener('click', (e) => {
    if (e.defaultPrevented || e.button !== 0) return;
    const a = (e.target as Element | null)?.closest?.<HTMLElement>('[data-href]');
    if (!a) return;
    e.preventDefault();
    follow(a);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' || e.defaultPrevented) return;
    const a = e.target as HTMLElement;
    if (a?.matches?.('[role="link"][data-href]')) {
      e.preventDefault();
      a.click();
    }
  });

  // Tooltips, for a mouse (a finger has no hover to show one on).
  document.addEventListener('pointerover', (e) => {
    if (e.pointerType !== 'mouse') return;
    const el = (e.target as Element | null)?.closest?.<HTMLElement>('[title], [data-tip]');
    if (!el || el === tipFor) return;
    hideTip();
    if (!adoptTitle(el)) return;
    tipFor = el;
    tipTimer = window.setTimeout(() => showTip(el), TIP_DELAY_MS);
  });
  document.addEventListener('pointerout', (e) => {
    if (!tipFor) return;
    const to = e.relatedTarget as Node | null;
    if (to && tipFor.contains(to)) return;
    if ((e.target as Node) === tipFor || tipFor.contains(e.target as Node)) hideTip();
  });
  for (const type of ['pointerdown', 'keydown', 'wheel'] as const) {
    document.addEventListener(type, hideTip, { capture: true, passive: true });
  }
  // A focused control that carries a title still has one from the keyboard's side: the
  // system tooltip never appeared for focus, so the title only needs taking off.
  document.addEventListener('focusin', (e) => {
    const el = e.target as HTMLElement;
    if (el?.hasAttribute?.('title')) adoptTitle(el);
  });

  // Dropdowns: a mouse gets the sketched list.
  document.addEventListener(
    'mousedown',
    (e) => {
      if (list && !list.contains(e.target as Node)) closeList(false);
      const select = (e.target as Element | null)?.closest?.('select');
      if (!(select instanceof HTMLSelectElement) || select.multiple || select.disabled) return;
      if (e.button !== 0) return;
      e.preventDefault();
      select.focus({ preventScroll: true });
      if (listFor === select) closeList();
      else openList(select);
    },
    true,
  );
  // Capture, and first: while the list is up its keys are its own — Esc closes the list,
  // not the pause menu under it.
  window.addEventListener(
    'keydown',
    (e) => {
      if (list) {
        const stop = () => {
          e.preventDefault();
          e.stopImmediatePropagation();
        };
        if (e.key === 'Escape') {
          stop();
          closeList();
        } else if (e.key === 'ArrowDown') {
          stop();
          moveInList(1);
        } else if (e.key === 'ArrowUp') {
          stop();
          moveInList(-1);
        } else if (e.key === 'Home' || e.key === 'End') {
          stop();
          moveInList(e.key === 'Home' ? -999 : 999);
        } else if (e.key === 'Tab') {
          stop();
          closeList();
        }
        return;
      }
      // The keys that would open the system's list from a focused select open ours.
      const t = e.target;
      if (
        t instanceof HTMLSelectElement &&
        !t.multiple &&
        (e.key === ' ' || e.key === 'Enter' || (e.altKey && e.key === 'ArrowDown'))
      ) {
        e.preventDefault();
        e.stopImmediatePropagation();
        openList(t);
      }
    },
    true,
  );
  window.addEventListener('resize', () => closeList(false));

  // The browser's own menu and its page commands.
  document.addEventListener('contextmenu', (e) => {
    const t = e.target as Element | null;
    if (t?.closest?.('input, textarea, [contenteditable="true"]')) return;
    e.preventDefault();
  });
  // Bubble phase and last: the play page's own Ctrl+S (Solve) has had its turn by now.
  window.addEventListener('keydown', (e) => {
    if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
    const k = e.key.toLowerCase();
    if (k === 's' || k === 'p') e.preventDefault();
  });
}
