/**
 * Whether the shell moves things about: the one answer every animation asks.
 *
 * It used to be the operating system's `prefers-reduced-motion`, read once in `anim.ts`
 * and once in `splash.ts`, with the stylesheets asking the same media query on their own.
 * A game's settings screen has a "Reduce motion" switch of its own, so the question now
 * has two parts: what the player chose in Settings, and — until they have chosen — what
 * their system asks for. The answer is also stamped on `<html>` as `.reduce-motion`, which
 * is what the stylesheets key off instead of the media query, so a player who turns motion
 * back on in Settings gets it back in the CSS as well as in GSAP.
 *
 * A leaf module (storage only), because `anim.ts`, `flight.ts` and the splash all need it
 * and must not import each other through it.
 */

import { onStorageUpgrade, readItem, writeItem } from '../storage';

const KEY = 'puzzlebox:motion';
const QUERY = '(prefers-reduced-motion: reduce)';

type Choice = 'reduce' | 'full' | null;
type Listener = (reduced: boolean) => void;
const listeners = new Set<Listener>();

const systemWatch: MediaQueryList | null =
  typeof matchMedia === 'function' ? matchMedia(QUERY) : null;

function readChoice(): Choice {
  const v = readItem(KEY);
  return v === 'reduce' || v === 'full' ? v : null;
}

let choice: Choice = readChoice();

/** What the operating system asks for, whatever the player chose here. */
export function systemReducedMotion(): boolean {
  return !!systemWatch?.matches;
}

/** True when the shell should keep still: the player's choice, else the system's. */
export function reducedMotion(): boolean {
  return choice ? choice === 'reduce' : systemReducedMotion();
}

/** The player's own choice, or `null` while it still follows the system. */
export function motionChoice(): Choice {
  return choice;
}

function apply(): void {
  if (typeof document === 'undefined') return;
  document.documentElement.classList.toggle('reduce-motion', reducedMotion());
}

function notify(): void {
  apply();
  const now = reducedMotion();
  for (const fn of [...listeners]) {
    try {
      fn(now);
    } catch (e) {
      console.debug('[motion] listener threw; ignoring.', e);
    }
  }
}

/** Set the switch in Settings. Remembered, and it outranks the system from then on. */
export function setReducedMotion(on: boolean): void {
  const next: Choice = on ? 'reduce' : 'full';
  if (next === choice) return;
  choice = next;
  writeItem(KEY, next);
  notify();
}

/** Watch the answer. Returns an unsubscribe function. */
export function onMotionChange(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

apply();
// The system's switch flipped with the page open: it matters only while the player has
// not made a choice of their own.
systemWatch?.addEventListener?.('change', () => {
  if (!choice) notify();
});
// A choice saved on CrazyGames arrives with the platform store, a moment after boot.
onStorageUpgrade(() => {
  const next = readChoice();
  if (next !== choice) {
    choice = next;
    notify();
  }
});

/** Tests only: forget the choice and read the store again. */
export function _reloadMotionForTests(): void {
  choice = readChoice();
  apply();
}
