import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { EXIT_NONE, GUESS, portToGrid } from './index';
import type { BlackboxState, BlackboxUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Ports used by the walkthrough: down the second column, the first column, and in from the left. */
const HIT_PORT = 1;
const REFLECT_PORT = 0;
const THROUGH_PORT = 14;
/** Arena square the ball is hiding in. */
const BALL_CELL = { x: 1, y: 0 };

/** Rectangle of a grid cell (the frame of ports plus the box itself). */
const gridCell = (gx: number, gy: number, t: number): TutorialRect =>
  cellRect(gx, gy, t, border(t));
const gridCentre = (gx: number, gy: number, t: number) => cellCentre(gx, gy, t, border(t));

function portRect(state: BlackboxState, t: number, n: number): TutorialRect {
  const p = portToGrid(state.w, state.h, n)!;
  return gridCell(p.x, p.y, t);
}
function portCentre(state: BlackboxState, t: number, n: number) {
  const p = portToGrid(state.w, state.h, n)!;
  return gridCentre(p.x, p.y, t);
}
const fired = (state: BlackboxState, n: number) => state.exits[n] !== EXIT_NONE;

export const tutorial: Tutorial<BlackboxState, BlackboxUI> = {
  steps: [
    {
      gameId: 'w4h4m1M1:f3748783',
      text: 'One ball is hiding in this 4×4 box. Fire lasers in from the dots around the edge, work out where it must be, mark it and press the corner button.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w + 2, state.h + 2),
    },
    {
      text: 'Click the dot on the **left edge, level with the second row**. The beam gets bent on its way through and comes out elsewhere; both ends are given the same number.',
      highlight: ({ state, tileSize }) => {
        const rects = [portRect(state, tileSize, THROUGH_PORT)];
        // Once it has been fired, spotlight the far end of the beam as well.
        const exit = state.exits[THROUGH_PORT];
        if (exit >= 0) rects.push(portRect(state, tileSize, exit));
        return rects;
      },
      pointer: ({ state, tileSize }) => portCentre(state, tileSize, THROUGH_PORT),
      waitFor: ({ state }) => fired(state, THROUGH_PORT),
      placement: 'left',
    },
    {
      text: 'Now fire the dot at the **top of the second column**. An **H** means the beam ran straight into a ball and never came out.',
      highlight: ({ state, tileSize }) => portRect(state, tileSize, HIT_PORT),
      pointer: ({ state, tileSize }) => portCentre(state, tileSize, HIT_PORT),
      waitFor: ({ state }) => fired(state, HIT_PORT),
      placement: 'above',
    },
    {
      text: 'Fire the dot at the **top of the first column** too. An **R** means the beam bounced straight back out, which happens when a ball sits diagonally beside the port.',
      highlight: ({ state, tileSize }) => portRect(state, tileSize, REFLECT_PORT),
      pointer: ({ state, tileSize }) => portCentre(state, tileSize, REFLECT_PORT),
      waitFor: ({ state }) => fired(state, REFLECT_PORT),
      placement: 'above',
    },
    {
      text: 'The R puts a ball diagonally next to the first column, and the H puts one straight down the second: only this square satisfies both.',
      highlight: ({ state, tileSize }) => [
        portRect(state, tileSize, REFLECT_PORT),
        portRect(state, tileSize, HIT_PORT),
        gridCell(BALL_CELL.x + 1, BALL_CELL.y + 1, tileSize),
      ],
      placement: 'below',
    },
    {
      text: '**Click that square** to mark your ball there.',
      highlight: ({ tileSize }) => gridCell(BALL_CELL.x + 1, BALL_CELL.y + 1, tileSize),
      pointer: ({ tileSize }) => gridCentre(BALL_CELL.x + 1, BALL_CELL.y + 1, tileSize),
      waitFor: ({ state }) => (state.cells[BALL_CELL.y * state.w + BALL_CELL.x] & GUESS) !== 0,
    },
    {
      text: 'All the balls are marked, so the **tick in the top-left corner** is live. Click it to have your answer checked.',
      highlight: ({ tileSize }) => gridCell(0, 0, tileSize),
      pointer: ({ tileSize }) => gridCentre(0, 0, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
      placement: 'left',
    },
    {
      text: 'Correct. While you are working, **right-click** a square to padlock it once you are sure it is empty, and **Solve** gives the answer away.',
      target: '[data-cmd="solve"]',
    },
  ],
};
