import { tx } from '../../i18n';
/**
 * Unruly board model shared by the game, the solver and the generator.
 *
 * A grid is a `Uint8Array` of `w * h` cells (row-major, `y * w + x`) holding `EMPTY`,
 * `BLACK` or `WHITE`. The rules: every row holds `w / 2` cells of each colour, every
 * column `h / 2`, and no three consecutive cells in a line share a colour. In "unique"
 * mode no two finished rows may match, and likewise no two columns.
 */

export const EMPTY = 0;
export const BLACK = 1;
export const WHITE = 2;

export type Cell = typeof EMPTY | typeof BLACK | typeof WHITE;

export const other = (c: number): number => (c === BLACK ? WHITE : BLACK);

// ------------------------------------------------------------- description format

/**
 * Parse a description in the original's run-length format. Each letter stands for a
 * run of empty cells followed by one clue: `a`–`y` is 0–24 empties then a white clue,
 * `A`–`Y` 0–24 empties then a black clue, and `z`/`Z` is 25 empties with no clue. The
 * text ends with one extra (white) "clue" just past the last cell, so the letters must
 * account for exactly `w * h + 1` positions. Returns an error message when they do not.
 */
export function parseDesc(
  desc: string,
  w: number,
  h: number,
): { grid: Uint8Array; given: Uint8Array } | string {
  const n = w * h;
  const grid = new Uint8Array(n);
  const given = new Uint8Array(n);
  let pos = 0;
  for (const ch of desc) {
    const code = ch.charCodeAt(0);
    if (ch === 'z' || ch === 'Z') {
      pos += 25;
    } else if (code >= 97 && code < 122) {
      pos += code - 97;
      if (pos < n) {
        grid[pos] = WHITE;
        given[pos] = 1;
      }
      pos++;
    } else if (code >= 65 && code < 90) {
      pos += code - 65;
      if (pos < n) {
        grid[pos] = BLACK;
        given[pos] = 1;
      }
      pos++;
    } else {
      return tx`Description contains invalid characters`;
    }
    if (pos > n + 1) return tx`Description too long`;
  }
  if (pos < n + 1) return tx`Description too short`;
  if (pos > n + 1) return tx`Description too long`;
  return { grid, given };
}

/** Encode a grid of clues (empties and colours) in the format `parseDesc` reads. */
export function encodeDesc(grid: Uint8Array): string {
  let out = '';
  let run = 0;
  for (let i = 0; i <= grid.length; i++) {
    const c = i === grid.length ? WHITE : grid[i];
    if (c === EMPTY) {
      run++;
      continue;
    }
    const big = c === WHITE ? 'z' : 'Z';
    const base = c === WHITE ? 97 : 65;
    while (run > 24) {
      out += big;
      run -= 25;
    }
    out += String.fromCharCode(base + run);
    run = 0;
  }
  return out;
}

/** Solver hint stored with a generated puzzle: the full solution as `0`/`1` digits. */
export function encodeSolution(grid: Uint8Array): string {
  let s = '';
  for (let i = 0; i < grid.length; i++) s += grid[i] === BLACK ? '1' : '0';
  return s;
}

export function decodeSolution(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n || !/^[01]*$/.test(aux)) return null;
  const grid = new Uint8Array(n);
  for (let i = 0; i < n; i++) grid[i] = aux[i] === '1' ? BLACK : WHITE;
  return grid;
}

// ------------------------------------------------------------------- rule checks

/** How many cells of colour `c` sit in row `y` / column `x`. */
export function rowCount(grid: Uint8Array, w: number, y: number, c: number): number {
  let n = 0;
  for (let x = 0; x < w; x++) if (grid[y * w + x] === c) n++;
  return n;
}
export function colCount(grid: Uint8Array, w: number, h: number, x: number, c: number): number {
  let n = 0;
  for (let y = 0; y < h; y++) if (grid[y * w + x] === c) n++;
  return n;
}

/** A maximal run of three or more equal coloured cells along a row or column. */
export interface Run {
  x: number;
  y: number;
  /** Number of cells in the run. */
  len: number;
  horizontal: boolean;
  colour: number;
}

/** Every run of three or more same-coloured cells, merged into maximal runs. */
export function findRuns(grid: Uint8Array, w: number, h: number): Run[] {
  const runs: Run[] = [];
  const scan = (
    count: number,
    len: number,
    at: (line: number, k: number) => number,
    horizontal: boolean,
  ) => {
    for (let line = 0; line < count; line++) {
      let start = 0;
      while (start < len) {
        const c = grid[at(line, start)];
        let end = start + 1;
        while (end < len && grid[at(line, end)] === c) end++;
        if (c !== EMPTY && end - start >= 3) {
          runs.push({
            x: horizontal ? start : line,
            y: horizontal ? line : start,
            len: end - start,
            horizontal,
            colour: c,
          });
        }
        start = end;
      }
    }
  };
  scan(h, w, (y, x) => y * w + x, true);
  scan(w, h, (x, y) => y * w + x, false);
  return runs;
}

/** Whether any three consecutive cells in a line share a colour. */
export function anyThrees(grid: Uint8Array, w: number, h: number): boolean {
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = grid[y * w + x];
      if (c === EMPTY) continue;
      if (x + 2 < w && grid[y * w + x + 1] === c && grid[y * w + x + 2] === c) return true;
      if (y + 2 < h && grid[(y + 1) * w + x] === c && grid[(y + 2) * w + x] === c) return true;
    }
  }
  return false;
}

/**
 * Lines holding too many cells of one colour. `rows[y]` / `cols[x]` is a bit mask of the
 * offending colours (bit 1 for black, bit 2 for white).
 */
export function overfullLines(
  grid: Uint8Array,
  w: number,
  h: number,
): { rows: Uint8Array; cols: Uint8Array; any: boolean } {
  const rows = new Uint8Array(h);
  const cols = new Uint8Array(w);
  let any = false;
  for (let y = 0; y < h; y++) {
    for (const c of [BLACK, WHITE]) {
      if (rowCount(grid, w, y, c) > w / 2) {
        rows[y] |= c;
        any = true;
      }
    }
  }
  for (let x = 0; x < w; x++) {
    for (const c of [BLACK, WHITE]) {
      if (colCount(grid, w, h, x, c) > h / 2) {
        cols[x] |= c;
        any = true;
      }
    }
  }
  return { rows, cols, any };
}

/**
 * In unique mode: fully filled rows (and columns) that exactly match another. Returns
 * flags per row and per column.
 */
export function matchingLines(
  grid: Uint8Array,
  w: number,
  h: number,
): { rows: Uint8Array; cols: Uint8Array; any: boolean } {
  const rows = new Uint8Array(h);
  const cols = new Uint8Array(w);
  let any = false;
  const check = (
    count: number,
    len: number,
    at: (line: number, k: number) => number,
    flags: Uint8Array,
  ) => {
    for (let a = 0; a < count; a++) {
      let full = true;
      for (let k = 0; k < len && full; k++) if (grid[at(a, k)] === EMPTY) full = false;
      if (!full) continue;
      for (let b = a + 1; b < count; b++) {
        let same = true;
        for (let k = 0; k < len && same; k++) if (grid[at(a, k)] !== grid[at(b, k)]) same = false;
        if (same) {
          flags[a] = flags[b] = 1;
          any = true;
        }
      }
    }
  };
  check(h, w, (y, x) => y * w + x, rows);
  check(w, h, (x, y) => y * w + x, cols);
  return { rows, cols, any };
}

/** Every rule holds and every cell is coloured. */
export function isComplete(grid: Uint8Array, w: number, h: number, unique: boolean): boolean {
  for (let y = 0; y < h; y++) if (rowCount(grid, w, y, BLACK) !== w / 2) return false;
  for (let y = 0; y < h; y++) if (rowCount(grid, w, y, WHITE) !== w / 2) return false;
  for (let x = 0; x < w; x++) if (colCount(grid, w, h, x, BLACK) !== h / 2) return false;
  for (let x = 0; x < w; x++) if (colCount(grid, w, h, x, WHITE) !== h / 2) return false;
  if (anyThrees(grid, w, h)) return false;
  if (unique && matchingLines(grid, w, h).any) return false;
  return true;
}
