import { tx } from '../../i18n';
/**
 * The fixed part of an Unequal puzzle: its size, mode, given digits and clue flags, plus
 * the description format and the error checks shared by the game and its tests.
 *
 * A clue flag on a cell always refers to the neighbour in that direction. In Unequal
 * mode the flag means "this cell is greater than that neighbour", so the `>` sign is
 * drawn in the gap with its point towards the smaller cell; in Adjacent mode it means
 * "this cell differs from that neighbour by exactly one" and both cells carry the flag.
 */

export const F_ADJ_UP = 1;
export const F_ADJ_RIGHT = 2;
export const F_ADJ_DOWN = 4;
export const F_ADJ_LEFT = 8;
export const F_ADJ_MASK = F_ADJ_UP | F_ADJ_RIGHT | F_ADJ_DOWN | F_ADJ_LEFT;

/** Error bits computed for a position: a duplicate digit, or a violated sign per side. */
export const E_DUP = 1;
export const E_UP = 2;
export const E_RIGHT = 4;
export const E_DOWN = 8;
export const E_LEFT = 16;

export interface Dir {
  /** Flag bit for this direction. */
  f: number;
  /** Flag bit for the opposite direction (as seen from the neighbour). */
  fo: number;
  /** Error bit for this direction. */
  e: number;
  dx: number;
  dy: number;
  /** Letter used in game descriptions. */
  ch: string;
  /** Sign drawn in text format (Unequal mode) or bar (Adjacent mode). */
  sign: string;
  bar: string;
}

/** Up, right, down, left — the order the description letters are written in. */
export const DIRS: readonly Dir[] = [
  { f: F_ADJ_UP, fo: F_ADJ_DOWN, e: E_UP, dx: 0, dy: -1, ch: 'U', sign: '^', bar: '-' },
  { f: F_ADJ_RIGHT, fo: F_ADJ_LEFT, e: E_RIGHT, dx: 1, dy: 0, ch: 'R', sign: '>', bar: '|' },
  { f: F_ADJ_DOWN, fo: F_ADJ_UP, e: E_DOWN, dx: 0, dy: 1, ch: 'D', sign: 'v', bar: '-' },
  { f: F_ADJ_LEFT, fo: F_ADJ_RIGHT, e: E_LEFT, dx: -1, dy: 0, ch: 'L', sign: '<', bar: '|' },
];

export interface Puzzle {
  order: number;
  adjacent: boolean;
  /** Clue flags per cell (F_ADJ_* bits), row-major. */
  flags: Uint8Array;
  /** Given digits per cell (0 = blank), row-major. Given cells cannot be edited. */
  given: Uint8Array;
}

/** Index into an order³ candidate cube: cell (x, y), digit n (1-based). */
export function cubeIndex(o: number, x: number, y: number, n: number): number {
  return (x * o + y) * o + n - 1;
}

/**
 * Parse a description: one entry per cell, row-major, separated by commas. Each entry
 * is the digit (0 for blank) followed by any of the letters U, R, D, L naming the
 * neighbours this cell is greater than (or adjacent to). A trailing comma is allowed,
 * and a run of lower-case letters skips that many blank cells (a form the original
 * accepts). Returns the puzzle or an error message.
 */
export function parseDesc(desc: string, order: number, adjacent: boolean): Puzzle | string {
  const o = order;
  const n2 = o * o;
  const flags = new Uint8Array(n2);
  const given = new Uint8Array(n2);
  let i = 0;
  let p = 0;
  while (p < desc.length) {
    while (p < desc.length && desc[p] >= 'a' && desc[p] <= 'z') {
      i += desc.charCodeAt(p) - 96;
      p++;
    }
    if (i >= n2) return tx`Too much data to fill grid`;
    const m = /^\d+/.exec(desc.slice(p));
    if (!m) return tx`Expecting number in game description`;
    const v = parseInt(m[0], 10);
    if (v > o) return tx`Out-of-range number in game description`;
    given[i] = v;
    p += m[0].length;
    while (p < desc.length && 'URDL'.includes(desc[p])) {
      flags[i] |= DIRS['URDL'.indexOf(desc[p])].f;
      p++;
    }
    i++;
    if (i < n2 && desc[p] !== ',') return tx`Missing separator`;
    if (desc[p] === ',') p++;
  }
  if (i < n2) return tx`Not enough data to fill grid`;

  for (let y = 0; y < o; y++) {
    for (let x = 0; x < o; x++) {
      const f = flags[y * o + x];
      for (const d of DIRS) {
        if (!(f & d.f)) continue;
        const nx = x + d.dx;
        const ny = y + d.dy;
        if (nx < 0 || ny < 0 || nx >= o || ny >= o) return tx`Flags go off grid`;
        const back = (flags[ny * o + nx] & d.fo) !== 0;
        // Adjacency is mutual; "greater than" cannot be.
        if (adjacent ? !back : back) return tx`Flags contradicting each other`;
      }
    }
  }
  return { order: o, adjacent, flags, given };
}

/** The description of a puzzle in the original format (every cell ends with a comma). */
export function encodeDesc(order: number, given: Uint8Array, flags: Uint8Array): string {
  let out = '';
  for (let i = 0; i < order * order; i++) {
    out += String(given[i]);
    for (const d of DIRS) if (flags[i] & d.f) out += d.ch;
    out += ',';
  }
  return out;
}

/**
 * Check a position: duplicate digits within a row or column, and every clue sign
 * against the digits on both of its sides. Returns the error bits per cell and whether
 * the grid is completely and correctly filled.
 */
export function checkGrid(
  puzzle: Puzzle,
  nums: Uint8Array,
): { errors: Uint8Array; complete: boolean } {
  const { order: o, adjacent, flags } = puzzle;
  const errors = new Uint8Array(o * o);
  let complete = true;
  for (let y = 0; y < o; y++) {
    for (let x = 0; x < o; x++) {
      const i = y * o + x;
      const v = nums[i];
      if (v === 0) {
        complete = false;
        continue;
      }
      for (let k = 0; k < o; k++) {
        if ((k !== x && nums[y * o + k] === v) || (k !== y && nums[k * o + x] === v)) {
          errors[i] |= E_DUP;
          complete = false;
          break;
        }
      }
      for (const d of DIRS) {
        const nx = x + d.dx;
        const ny = y + d.dy;
        if (nx < 0 || ny < 0 || nx >= o || ny >= o) continue;
        const dv = nums[ny * o + nx];
        if (dv === 0) continue;
        const has = (flags[i] & d.f) !== 0;
        let bad: boolean;
        if (adjacent) {
          bad = has !== (Math.abs(v - dv) === 1);
        } else {
          bad = has && v <= dv;
        }
        if (bad) {
          errors[i] |= d.e;
          complete = false;
        }
      }
    }
  }
  return { errors, complete };
}

/** The solution string used by Solve and as the generator's aux hint. */
export function encodeSolution(nums: Uint8Array): string {
  let s = 'S';
  for (let i = 0; i < nums.length; i++) s += String(nums[i]);
  return s;
}
