import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { BridgesState, BridgesUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

interface Cell {
  x: number;
  y: number;
}

/** Islands of the fixed 5×5 board the walkthrough talks about. */
const BOTTOM: Cell = { x: 2, y: 4 };
const TOP: Cell = { x: 2, y: 0 };
const LEFT_ONE: Cell = { x: 0, y: 2 };
const RIGHT_ONE: Cell = { x: 4, y: 2 };

const islandAt = (state: BridgesState, c: Cell): number =>
  state.layout.islandAt[c.y * state.w + c.x];

/** The edge joining two islands of the tutorial board, or -1. */
function edgeBetween(state: BridgesState, a: Cell, b: Cell): number {
  const i = islandAt(state, a);
  const j = islandAt(state, b);
  return i < 0 || j < 0 ? -1 : state.layout.edgeBetween(i, j);
}

const rect = (c: Cell, t: number): TutorialRect => cellRect(c.x, c.y, t, border(t));
const centre = (c: Cell, t: number) => cellCentre(c.x, c.y, t, border(t));

/** The strip of board between two islands in line with each other, islands included. */
function laneRect(a: Cell, b: Cell, t: number): TutorialRect {
  const x = Math.min(a.x, b.x);
  const y = Math.min(a.y, b.y);
  return cellRect(x, y, t, border(t), Math.abs(a.x - b.x) + 1, Math.abs(a.y - b.y) + 1);
}

function bridgeCount(state: BridgesState, a: Cell, b: Cell): number {
  const e = edgeBetween(state, a, b);
  return e < 0 ? 0 : state.bridges[e];
}

export const tutorial: Tutorial<BridgesState, BridgesUI> = {
  steps: [
    {
      gameId: '5x5m2:2a4a2e1c1g2b',
      text: "Each island's number is how many bridge ends it wants. Join every island into one network, with at most two bridges between a pair and no bridge crossing another.",
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The **2 at the bottom** has only one island in line with it: the **4** at the top. **Drag** from the 2 towards the 4 to throw a bridge across.',
      highlight: ({ tileSize }) => laneRect(BOTTOM, TOP, tileSize),
      pointer: ({ tileSize }) => ({ ...centre(BOTTOM, tileSize), to: centre(TOP, tileSize) }),
      waitFor: ({ state }) => bridgeCount(state, BOTTOM, TOP) >= 1,
    },
    {
      text: 'It wants two bridge ends, and that pair is the only place they can go. **Drag** the same way again for a second, parallel bridge.',
      highlight: ({ tileSize }) => laneRect(BOTTOM, TOP, tileSize),
      pointer: ({ tileSize }) => ({ ...centre(BOTTOM, tileSize), to: centre(TOP, tileSize) }),
      waitFor: ({ state }) => bridgeCount(state, BOTTOM, TOP) >= 2,
    },
    {
      text: 'That island is done. **Click** it to mark it finished: it turns grey and its bridges lock, so you cannot disturb them by accident.',
      highlight: ({ tileSize }) => rect(BOTTOM, tileSize),
      pointer: ({ tileSize }) => centre(BOTTOM, tileSize),
      waitFor: ({ state }) => {
        const i = islandAt(state, BOTTOM);
        return i >= 0 && state.marked[i] === 1;
      },
    },
    {
      text: 'No bridge may cross another, so the line between the **two 1s** is dead now. **Right-drag** from the left 1 towards the right one to pencil that in.',
      highlight: ({ tileSize }) => laneRect(LEFT_ONE, RIGHT_ONE, tileSize),
      pointer: ({ tileSize }) => ({
        ...centre(LEFT_ONE, tileSize),
        to: centre(RIGHT_ONE, tileSize),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => {
        const e = edgeBetween(state, LEFT_ONE, RIGHT_ONE);
        return e >= 0 && state.noline[e] === 1;
      },
    },
    {
      text: 'Each 1 now has one way out, and the four remaining bridges follow from that. **Solve** finishes the puzzle off (and **G** shows every line a bridge could take).',
      textTouch:
        'Each 1 now has one way out, and the four remaining bridges follow from that. **Solve** finishes the puzzle off.',
      target: '[data-cmd="solve"]',
    },
  ],
};
