import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_SELECT2,
  CURSOR_UP,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  stripMods,
} from '../../framework/input';
import { easeInOut, flashOn, parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export interface SixteenParams {
  w: number;
  h: number;
  /** Shuffle by exactly this many single moves instead of a uniform shuffle (0 = off). */
  moveTarget: number;
}

/** One row or column rotation: `row` selects the axis, `dir` is +1 (right/down) or -1. */
export interface LineMove {
  row: boolean;
  index: number;
  dir: 1 | -1;
}

export interface SixteenState {
  w: number;
  h: number;
  /** Tile at each cell, row-major, numbered 1..w*h. */
  tiles: number[];
  moves: number;
  /** Move count at which the grid first came into order, or 0. */
  completed: number;
  moveTarget: number;
  usedSolve: boolean;
  /** The move that produced this state (drives the sliding animation). */
  last: LineMove | null;
}

export interface SixteenUI {
  /** Cursor cell in grid coordinates; exactly one of cx/cy is -1 or w/h (the arrow strip). */
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const ANIM = 0.13;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_DIM = 12;
const MAX_SHUFFLE = 10000;

export function isSolved(tiles: number[]): boolean {
  for (let i = 0; i < tiles.length; i++) if (tiles[i] !== i + 1) return false;
  return true;
}

/** Parity of a permutation of 0..n-1 (0 = even, 1 = odd), via cycle decomposition. */
function permutationParity(perm: number[]): number {
  const seen = new Uint8Array(perm.length);
  let parity = 0;
  for (let i = 0; i < perm.length; i++) {
    if (seen[i]) continue;
    let len = 0;
    let j = i;
    while (!seen[j]) {
      seen[j] = 1;
      j = perm[j];
      len++;
    }
    parity ^= (len - 1) & 1;
  }
  return parity;
}

/**
 * Every move is a cyclic rotation of a full row or column. When both dimensions are odd
 * each rotation is an even permutation, so only even arrangements can be reached; with
 * an even side available every arrangement is reachable.
 */
export function solvable(tiles: number[], w: number, h: number): boolean {
  if ((w & h & 1) === 0) return true;
  return permutationParity(tiles.map((t) => t - 1)) === 0;
}

/** Rotate one row or column of `tiles` by a single step, returning a new array. */
export function applyLineMove(tiles: number[], w: number, h: number, mv: LineMove): number[] {
  const out = tiles.slice();
  if (mv.row) {
    const base = mv.index * w;
    for (let x = 0; x < w; x++) out[base + x] = tiles[base + ((x - mv.dir + w) % w)];
  } else {
    for (let y = 0; y < h; y++)
      out[y * w + mv.index] = tiles[((y - mv.dir + h) % h) * w + mv.index];
  }
  return out;
}

function sameTiles(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

function parseMove(move: string): LineMove | null {
  const m = /^([RC])(\d+),(-?1)$/.exec(move);
  if (!m) return null;
  return { row: m[1] === 'R', index: parseInt(m[2], 10), dir: m[3] === '1' ? 1 : -1 };
}

function encodeMove(mv: LineMove): string {
  return `${mv.row ? 'R' : 'C'}${mv.index},${mv.dir}`;
}

// ------------------------------------------------------------------ generation

/** Uniformly random arrangement, restricted to even permutations when required. */
function shuffleUniform(w: number, h: number, rng: Random): number[] {
  const n = w * h;
  const tiles: number[] = [];
  for (let i = 1; i <= n; i++) tiles.push(i);
  rng.shuffle(tiles);
  if (!solvable(tiles, w, h)) {
    // Swapping any two tiles flips the parity; this maps odd permutations onto even
    // ones one-to-one, so the result stays uniform over the reachable arrangements.
    const t = tiles[n - 1];
    tiles[n - 1] = tiles[n - 2];
    tiles[n - 2] = t;
  }
  return tiles;
}

/**
 * Scramble the ordered grid with exactly `target` single moves. Consecutive moves on the
 * same axis are not allowed to undo each other, nor to push one line so far that fewer
 * moves the other way would do the same job; the bookkeeping resets whenever a move on
 * the other axis is made.
 */
function shuffleByMoves(w: number, h: number, target: number, rng: Random): number[] {
  const n = w * h;
  let tiles: number[] = [];
  for (let i = 1; i <= n; i++) tiles.push(i);
  let axisIsRow: boolean | null = null;
  const net = new Int32Array(Math.max(w, h));
  for (let i = 0; i < target; i++) {
    let mv: LineMove;
    for (;;) {
      const pick = rng.upto(w + h);
      const row = pick >= w;
      const index = row ? pick - w : pick;
      const len = row ? w : h;
      const dir: 1 | -1 = rng.upto(2) === 0 ? -1 : 1;
      if (axisIsRow === row) {
        const total = net[index] + dir;
        if (Math.abs(2 * total) > len || Math.abs(total) < Math.abs(net[index])) continue;
      } else {
        net.fill(0);
        axisIsRow = row;
      }
      net[index] += dir;
      mv = { row, index, dir };
      break;
    }
    tiles = applyLineMove(tiles, w, h, mv);
  }
  return tiles;
}

// -------------------------------------------------------------------- geometry

/** The arrow strip is one tile wide all the way round. */
function border(ds: DrawState): number {
  return ds.tileSize;
}

/** Direction a click on grid cell (cx, cy) moves things, or null if it is not an arrow. */
function arrowAt(w: number, h: number, cx: number, cy: number): LineMove | null {
  const inRow = cy >= 0 && cy < h;
  const inCol = cx >= 0 && cx < w;
  if (cx === -1 && inRow) return { row: true, index: cy, dir: -1 };
  if (cx === w && inRow) return { row: true, index: cy, dir: 1 };
  if (cy === -1 && inCol) return { row: false, index: cx, dir: -1 };
  if (cy === h && inCol) return { row: false, index: cx, dir: 1 };
  return null;
}

/**
 * The border arrows form a ring, numbered clockwise from the top-left: top row, right
 * column, bottom row (right to left), left column (bottom to top).
 */
function ringPos(w: number, h: number, cx: number, cy: number): number {
  if (cy === -1) return cx;
  if (cx === w) return w + cy;
  if (cy === h) return w + h + (w - 1 - cx);
  return 2 * w + h + (h - 1 - cy);
}

function ringCell(w: number, h: number, pos: number): { cx: number; cy: number } {
  const len = 2 * (w + h);
  pos = ((pos % len) + len) % len;
  if (pos < w) return { cx: pos, cy: -1 };
  pos -= w;
  if (pos < h) return { cx: w, cy: pos };
  pos -= h;
  if (pos < w) return { cx: w - 1 - pos, cy: h };
  pos -= w;
  return { cx: -1, cy: h - 1 - pos };
}

/**
 * How far along the ring a cursor key moves (+1 clockwise). Keys along an edge walk it;
 * a key pointing into the grid from the end of an edge turns the corner.
 */
function ringStep(w: number, h: number, cx: number, cy: number, button: number): number {
  const top = cy === -1;
  const bottom = cy === h;
  const left = cx === -1;
  const right = cx === w;
  if (top && button === CURSOR_RIGHT) return 1;
  if (top && button === CURSOR_LEFT) return -1;
  if (right && button === CURSOR_DOWN) return 1;
  if (right && button === CURSOR_UP) return -1;
  if (bottom && button === CURSOR_LEFT) return 1;
  if (bottom && button === CURSOR_RIGHT) return -1;
  if (left && button === CURSOR_UP) return 1;
  if (left && button === CURSOR_DOWN) return -1;
  if (top && button === CURSOR_DOWN) return cx === 0 ? -1 : cx === w - 1 ? 1 : 0;
  if (bottom && button === CURSOR_UP) return cx === 0 ? 1 : cx === w - 1 ? -1 : 0;
  if (left && button === CURSOR_RIGHT) return cy === 0 ? 1 : cy === h - 1 ? -1 : 0;
  if (right && button === CURSOR_LEFT) return cy === 0 ? -1 : cy === h - 1 ? 1 : 0;
  return 0;
}

// ---------------------------------------------------------------------- drawing

/**
 * A chunky sketched arrow. (ex, ey) is the midpoint of the grid edge it sits against and
 * (ax, ay) the unit direction pointing away from the grid.
 */
function drawArrow(
  dr: Drawing,
  ex: number,
  ey: number,
  ax: number,
  ay: number,
  t: number,
  highlighted: boolean,
): void {
  const bx = -ay;
  const by = ax;
  const shape: [number, number][] = [
    [0.78, 0],
    [0.5, 0.27],
    [0.5, 0.12],
    [0.22, 0.12],
    [0.22, -0.12],
    [0.5, -0.12],
    [0.5, -0.27],
  ];
  const pts: number[] = [];
  for (const [a, b] of shape) pts.push(ex + (a * ax + b * bx) * t, ey + (a * ay + b * by) * t);
  dr.polygon(pts, highlighted ? 'accent' : 'shade', highlighted ? 'ink' : 'pencil', {
    width: 1.5,
  });
}

function drawTile(
  dr: Drawing,
  px: number,
  py: number,
  t: number,
  tile: number,
  inPlace: boolean,
  flashing: boolean,
): void {
  const pad = Math.max(2, t * 0.06);
  dr.roundRect(
    px + pad,
    py + pad,
    t - 2 * pad,
    t - 2 * pad,
    t * 0.14,
    inPlace ? 'shade' : 'paper',
    'ink',
    { width: 1.8, seed: tile },
  );
  dr.text(px + t / 2, py + t / 2, String(tile), {
    size: t * 0.5,
    colour: flashing ? 'ok' : 'ink',
    maxWidth: t * 0.8,
  });
}

/** The single move that turns `from` into `to` in the direction of play, if there is one. */
function animatedMove(from: SixteenState, to: SixteenState, dir: number): LineMove | null {
  let mv: LineMove | null;
  if (dir < 0) {
    mv = from.last ? { ...from.last, dir: from.last.dir === 1 ? -1 : 1 } : null;
  } else {
    mv = to.last;
  }
  if (!mv) return null;
  return sameTiles(applyLineMove(from.tiles, from.w, from.h, mv), to.tiles) ? mv : null;
}

function statusText(s: SixteenState): string {
  if (s.usedSolve) return tr('status.movesSinceSolve', { n: s.moves - s.completed });
  let text =
    (s.completed ? tr('status.completedPrefix') : '') +
    tr('status.moves', { n: s.completed || s.moves });
  if (s.moveTarget) text += tr('status.target', { n: s.moveTarget });
  return text;
}

// ------------------------------------------------------------------------ game

const game = defineGame<SixteenParams, SixteenState, SixteenUI>({
  id: 'sixteen',
  name: 'Sixteen',
  description: 'Slide whole rows and columns round the grid to put the tiles in order.',
  help,
  tutorial,
  achievements,
  presets: [
    { name: '3×3', params: { w: 3, h: 3, moveTarget: 0 } },
    { name: '4×3', params: { w: 4, h: 3, moveTarget: 0 } },
    { name: '4×4', params: { w: 4, h: 4, moveTarget: 0 } },
    { name: '5×4', params: { w: 5, h: 4, moveTarget: 0 } },
    { name: '5×5', params: { w: 5, h: 5, moveTarget: 0 } },
  ],
  defaultParams: () => ({ w: 4, h: 4, moveTarget: 0 }),
  // The shuffle target is part of the short form too: the status bar shows it.
  encodeParams: (p) => `${p.w}x${p.h}${p.moveTarget ? `m${p.moveTarget}` : ''}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    const m = /^m(\d+)/.exec(r.rest);
    return { w: r.w, h: r.h, moveTarget: m ? parseInt(m[1], 10) : 0 };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > MAX_DIM || p.h > MAX_DIM) return tx`Width and height must be at most ${MAX_DIM}`;
    if (!Number.isInteger(p.moveTarget))
      return tx`Number of shuffling moves must be a whole number`;
    if (p.moveTarget < 0) return tx`Number of shuffling moves cannot be negative`;
    if (p.moveTarget > MAX_SHUFFLE)
      return tx`Number of shuffling moves must be at most ${MAX_SHUFFLE}`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: 'Number of shuffling moves', value: String(p.moveTarget) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "4.5" or "4x" as 4, and used to turn
    // a shuffle count of "1.5" into 1 and "abc" into 0.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    // A shuffle count left blank is the default, 0: a completely random arrangement.
    const target = (items[2] as { value: string }).value.trim() === '' ? 0 : int(2);
    return { w: int(0), h: int(1), moveTarget: target };
  },

  newDesc(p, rng: Random) {
    let tiles: number[];
    do {
      tiles =
        p.moveTarget > 0
          ? shuffleByMoves(p.w, p.h, p.moveTarget, rng)
          : shuffleUniform(p.w, p.h, rng);
    } while (isSolved(tiles));
    return { desc: tiles.join(',') };
  },

  validateDesc(p, desc) {
    const n = p.w * p.h;
    const parts = desc.split(',');
    if (parts.length !== n) return tx`Description must contain ${n} numbers`;
    const seen = new Uint8Array(n + 1);
    for (const part of parts) {
      if (!/^\d+$/.test(part)) return tx`Description must contain only numbers`;
      const v = parseInt(part, 10);
      if (v < 1 || v > n) return tx`Description contains a number out of range`;
      if (seen[v]) return tx`Description contains a duplicate number`;
      seen[v] = 1;
    }
    if (!solvable(parts.map(Number), p.w, p.h)) return tx`This arrangement cannot be solved`;
    return null;
  },

  newGame(p, desc) {
    return {
      w: p.w,
      h: p.h,
      tiles: desc.split(',').map(Number),
      moves: 0,
      completed: 0,
      moveTarget: p.moveTarget,
      usedSolve: false,
      last: null,
    };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (isSolved(curr.tiles)) throw new Error(tx`Already solved`);
    return 'S';
  },

  textFormat(s) {
    const width = String(s.w * s.h).length;
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const row: string[] = [];
      for (let x = 0; x < s.w; x++) row.push(String(s.tiles[y * s.w + x]).padStart(width, ' '));
      rows.push(row.join(' '));
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: -1, cursorVisible: false }),

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h } = state;

    if (isCursorMove(b)) {
      const pos = ringPos(w, h, ui.cx, ui.cy) + ringStep(w, h, ui.cx, ui.cy, b);
      const cell = ringCell(w, h, pos);
      ui.cx = cell.cx;
      ui.cy = cell.cy;
      ui.cursorVisible = true;
      return '';
    }

    let cx: number;
    let cy: number;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const bd = border(ds);
      cx = Math.floor((mx - bd) / ds.tileSize);
      cy = Math.floor((my - bd) / ds.tileSize);
      ui.cursorVisible = false;
    } else if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      cx = ui.cx;
      cy = ui.cy;
    } else {
      return null;
    }

    const mv = arrowAt(w, h, cx, cy);
    if (!mv) return '';
    // The secondary action slides the line the opposite way.
    if (b === RIGHT_BUTTON || b === CURSOR_SELECT2) mv.dir = mv.dir === 1 ? -1 : 1;
    return encodeMove(mv);
  },

  executeMove(state, move) {
    if (move === 'S') {
      const tiles: number[] = [];
      for (let i = 1; i <= state.w * state.h; i++) tiles.push(i);
      const moves = state.moves + 1;
      return { ...state, tiles, moves, completed: moves, usedSolve: true, last: null };
    }
    const mv = parseMove(move);
    if (!mv) return null;
    if (mv.index >= (mv.row ? state.h : state.w)) return null;
    const tiles = applyLineMove(state.tiles, state.w, state.h, mv);
    const moves = state.moves + 1;
    return {
      ...state,
      tiles,
      moves,
      completed: state.completed || (isSolved(tiles) ? moves : 0),
      last: mv,
    };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    return { w: (p.w + 2) * t, h: (p.h + 2) * t };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h } = state;
    const t = ds.tileSize;
    const bd = border(ds);
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const cur = ui.cursorVisible ? ui : null;
    const isCursor = (cx: number, cy: number) => !!cur && cur.cx === cx && cur.cy === cy;

    // Arrows all the way round, each pointing the way it slides its line.
    for (let x = 0; x < w; x++) {
      const ex = bd + x * t + t / 2;
      drawArrow(dr, ex, bd, 0, -1, t, isCursor(x, -1));
      drawArrow(dr, ex, bd + h * t, 0, 1, t, isCursor(x, h));
    }
    for (let y = 0; y < h; y++) {
      const ey = bd + y * t + t / 2;
      drawArrow(dr, bd, ey, -1, 0, t, isCursor(-1, y));
      drawArrow(dr, bd + w * t, ey, 1, 0, t, isCursor(w, y));
    }
    if (cur) {
      const m = t * 0.08;
      dr.cursor(bd + cur.cx * t + m, bd + cur.cy * t + m, t - 2 * m, t - 2 * m);
    }

    // Board frame.
    dr.rect(bd - 4, bd - 4, w * t + 8, h * t + 8, flashing ? 'shade' : null, 'ink', {
      width: 2.4,
    });

    // Tiles, with the moving line offset from where it came from. The tile that fell
    // off one edge is drawn a second time so it can be seen arriving at the other.
    const mv = oldState ? animatedMove(oldState, state, dir) : null;
    const progress = mv ? easeInOut(animTime / ANIM) : 1;
    dr.clip(bd, bd, w * t, h * t);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const tile = state.tiles[i];
        const inPlace = tile === i + 1;
        let px = bd + x * t;
        let py = bd + y * t;
        if (mv && (mv.row ? y === mv.index : x === mv.index)) {
          const shift = (progress - 1) * mv.dir * t;
          const len = mv.row ? w : h;
          const wraps = mv.dir === 1 ? (mv.row ? x : y) === 0 : (mv.row ? x : y) === len - 1;
          if (mv.row) px += shift;
          else py += shift;
          if (wraps) {
            const back = len * mv.dir * t;
            drawTile(
              dr,
              mv.row ? px + back : px,
              mv.row ? py : py + back,
              t,
              tile,
              inPlace,
              flashing,
            );
          }
        }
        drawTile(dr, px, py, t, tile, inPlace, flashing);
      }
    }
    dr.unclip();

    // Keep showing the previous status until the slide has finished.
    dr.statusBar(statusText(oldState ? oldState : state));
  },

  animLength: () => ANIM,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (isSolved(s.tiles) ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
});

export default game;
