import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { F_BLACK, F_CIRCLE } from './board';
import type { SinglesState, SinglesUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

const flag = (state: SinglesState, x: number, y: number) => state.flags[y * state.w + x];

/**
 * A 4×4 Easy puzzle whose four black squares fall out one after the other, starting from
 * the pair of 4s with a gap between them in the third row.
 */
export const tutorial: Tutorial<SinglesState, SinglesUI> = {
  steps: [
    {
      gameId: '4x4:3134231224343243',
      text: 'Black out squares until no number is repeated among the white squares of any row or column. Two black squares may never share an edge, and the white squares must stay one connected region.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The two **4**s in this row have one square between them. Blacking that square out would leave both 4s white, so it must be white itself — **right-click** it to circle it.',
      highlight: ({ tileSize }) => cellRect(1, 2, tileSize, border(tileSize), 3, 1),
      pointer: ({ tileSize }) => ({
        ...cellCentre(2, 2, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => (flag(state, 2, 2) & F_CIRCLE) !== 0,
    },
    {
      text: 'That circled **3** is white for good, and its column holds another 3 at the top. **Left-click** the top one to black it out.',
      highlight: ({ tileSize }) => [
        cellRect(2, 0, tileSize, border(tileSize)),
        cellRect(2, 2, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(2, 0, tileSize, border(tileSize)),
      waitFor: ({ state }) => (flag(state, 2, 0) & F_BLACK) !== 0,
    },
    {
      text: 'Black squares never touch, so the **4** just right of it stays white. **Left-click** the other 4 in that last column.',
      highlight: ({ tileSize }) => [
        cellRect(3, 0, tileSize, border(tileSize)),
        cellRect(3, 2, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(3, 2, tileSize, border(tileSize)),
      waitFor: ({ state }) => (flag(state, 3, 2) & F_BLACK) !== 0,
    },
    {
      text: 'Same again: the **2** directly above your new black square is white, and its row has another 2 on the far left. **Left-click** that one.',
      highlight: ({ tileSize }) => [
        cellRect(3, 1, tileSize, border(tileSize)),
        cellRect(0, 1, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 1, tileSize, border(tileSize)),
      waitFor: ({ state }) => (flag(state, 0, 1) & F_BLACK) !== 0,
    },
    {
      text: 'One to go. The **3** above that black square is white, so the other 3 at the foot of the column has to go. **Left-click** it.',
      highlight: ({ tileSize }) => [
        cellRect(0, 0, tileSize, border(tileSize)),
        cellRect(0, 3, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 3, tileSize, border(tileSize)),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved, and the white squares are still all joined up. Circles are only notes, and **Undo** walks back through your moves.',
      target: '[data-cmd="undo"]',
    },
  ],
};
