import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { clamp, easeInOut, flashOn, parseWxH } from '../../framework/grid';
