export interface SameGameParams {
  w: number;
  h: number;
  /** Number of colours, 2..9. */
  ncols: number;
  /** A removed group of n squares scores (n - scoresub)^2; 1 or 2. */
  scoresub: number;
  /** Generate grids that are guaranteed to be clearable (generation-only). */
  soluble: boolean;
}

export interface SameGameState {
  w: number;
  h: number;
  ncols: number;
  scoresub: number;
  /** Colour of each cell (row-major, y down); 0 is empty. */
  tiles: number[];
  score: number;
  /** Every square has been removed. */
  complete: boolean;
  /** Squares remain but no two equal colours touch, so nothing can be removed. */
  impossible: boolean;
  /**
   * Where this board came from, so the move can be drawn rather than simply appearing.
   * `from[i]` is the index this cell held in the previous board (-1 for an empty square),
   * and `removed` lists the squares the previous board lost. Both are empty on a fresh
   * game, which is what `animLength` reads to tell a move from a deal.
   */
  from: number[];
  removed: number[];
}

export interface SameGameUI {
  /** 1 for each square in the currently selected group. */
  sel: Uint8Array;
  nsel: number;
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const FLASH_FRAME = 0.13;
/** How long a group takes to go and the board above it to come down. */
const ANIM = 0.34;
const MAX_SIDE = 40;
const MAX_AREA_3 = 150;
const MAX_AREA = 800;

// ------------------------------------------------------------------ rules

/** Points for removing a group of `n` squares. */
export function npoints(n: number, scoresub: number): number {
  const d = n - scoresub;
  return d > 0 ? d * d : 0;
}

/** Indices of the connected same-coloured group containing cell `start` (ascending). */
export function groupAt(tiles: ArrayLike<number>, w: number, h: number, start: number): number[] {
  const c = tiles[start];
  if (!c) return [];
  const seen = new Uint8Array(w * h);
  const out = [start];
  seen[start] = 1;
  for (let k = 0; k < out.length; k++) {
    const i = out[k];
    const x = i % w;
    const y = (i - x) / w;
    if (x > 0 && !seen[i - 1] && tiles[i - 1] === c) {
      seen[i - 1] = 1;
      out.push(i - 1);
    }
    if (x + 1 < w && !seen[i + 1] && tiles[i + 1] === c) {
      seen[i + 1] = 1;
      out.push(i + 1);
    }
    if (y > 0 && !seen[i - w] && tiles[i - w] === c) {
      seen[i - w] = 1;
      out.push(i - w);
    }
    if (y + 1 < h && !seen[i + w] && tiles[i + w] === c) {
      seen[i + w] = 1;
      out.push(i + w);
    }
  }
  return out.sort((a, b) => a - b);
}

/** Let unsupported squares fall, then slide empty columns out to the right. In place. */
export function settle(tiles: number[], w: number, h: number): void {
  settleMap(tiles, w, h);
}

/**
 * {@link settle}, reporting where everything went: `map[i]` is the index the square now
 * at `i` occupied before the gravity ran, or -1 where nothing landed. The drop and the
 * shunt left are the whole visible shape of a Same Game move, and this is what lets
 * `redraw` draw them travelling instead of teleporting.
 */
export function settleMap(tiles: number[], w: number, h: number): number[] {
  const map = new Array<number>(w * h).fill(-1);
  let dst = 0;
  for (let x = 0; x < w; x++) {
    // Gather this column bottom-up into column `dst`, then blank the rest of it.
    let y = h - 1;
    for (let src = h - 1; src >= 0; src--) {
      const v = tiles[src * w + x];
      if (v) {
        map[y * w + dst] = src * w + x;
        tiles[y-- * w + dst] = v;
      }
    }
    if (y < h - 1) {
      while (y >= 0) {
        map[y * w + dst] = -1;
        tiles[y-- * w + dst] = 0;
      }
      dst++;
    }
  }
  for (let x = dst; x < w; x++)
    for (let y = 0; y < h; y++) {
      map[y * w + x] = -1;
      tiles[y * w + x] = 0;
    }
  return map;
}

/** Whether the board is cleared, and whether any removable pair remains. */
export function inspect(
  tiles: ArrayLike<number>,
  w: number,
  h: number,
): { complete: boolean; impossible: boolean } {
  let complete = true;
  let impossible = true;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = tiles[y * w + x];
      if (!c) continue;
      complete = false;
      if (
        (x + 1 < w && tiles[y * w + x + 1] === c) ||
        (y + 1 < h && tiles[(y + 1) * w + x] === c)
      ) {
        impossible = false;
      }
    }
  }
  return { complete, impossible: !complete && impossible };
}

// ------------------------------------------------------------------ generation

/**
 * Build a grid that can certainly be cleared, by playing the game backwards: start
 * from a tiny blob and repeatedly *insert* a two-square blob (a domino, pushed into
 * a column or into a brand new column) whose colour differs from everything it
 * touches, so that removing it again is a legal move which restores the previous
 * grid. Every insertion keeps the still-empty part of the grid fillable by dominoes;
 * when that fails for every candidate position the attempt is thrown away and the
 * whole thing starts over.
 *
 * Returns the grid plus the sequence of groups (as cell indices) that clears it,
 * which is exactly the inverse of the insertions.
 */
export function generateSolubleGrid(
  w: number,
  h: number,
  nc: number,
  rng: Random,
): { grid: number[]; solution: number[][] } {
  const wh = w * h;
  const NEW = nc + 1; // placeholder for the blob being inserted
  const grid = new Array<number>(wh).fill(0);
  const trial = new Array<number>(wh).fill(0);
  const points: number[] = [];
  const bottom = (x: number) => (h - 1) * w + x;

  /** Shift column `x` rows 1..y up by one so that (x, y) can be overwritten. */
  const openSlot = (arr: number[], x: number, y: number) => {
    for (let i = 0; i < y; i++) arr[i * w + x] = arr[(i + 1) * w + x];
  };

  const tryInsert = (pos: number): number[] | null => {
    const x = pos % w;
    let y = (pos - x) / w;
    for (let i = 0; i < wh; i++) trial[i] = grid[i];
    if (y === h) {
      // Insert a fresh empty column at x (the last column is known to be empty).
      for (let i = w - 1; i > x; i--)
        for (let j = 0; j < h; j++) trial[j * w + i] = trial[j * w + i - 1];
      for (let j = 0; j < h; j++) trial[j * w + x] = 0;
      y = h - 1;
    }
    openSlot(trial, x, y);

    // Choose a colour that none of the four neighbours already has.
    let banned = 0;
    if (x > 0) banned |= 1 << trial[y * w + x - 1];
    if (x + 1 < w) banned |= 1 << trial[y * w + x + 1];
    if (y > 0) banned |= 1 << trial[(y - 1) * w + x];
    if (y + 1 < h) banned |= 1 << trial[(y + 1) * w + x];
    banned &= ~1; // empty neighbours ban nothing
    let allowed = 0;
    for (let k = 1; k <= nc; k++) if (!(banned & (1 << k))) allowed++;
    if (allowed === 0) return null;
    let pick = rng.upto(allowed);
    let c = 1;
    for (;;) {
      if (!(banned & (1 << c))) {
        if (pick === 0) break;
        pick--;
      }
      c++;
    }
    trial[y * w + x] = NEW;

    // Extend the blob left, right or upwards (up twice, so horizontal and vertical
    // dominoes come out about equally often).
    const dirs: number[] = [];
    const sideOk = (nx: number, far: number) =>
      nx >= 0 &&
      nx < w &&
      trial[y * w + nx] !== c &&
      trial[nx] === 0 &&
      (y + 1 >= h || (trial[(y + 1) * w + nx] !== c && trial[(y + 1) * w + nx] !== 0)) &&
      (far < 0 || far >= w || trial[y * w + far] !== c);
    if (sideOk(x - 1, x - 2)) dirs.push(-1);
    if (sideOk(x + 1, x + 2)) dirs.push(1);
    if (
      y > 0 &&
      trial[x] === 0 &&
      (x === 0 || trial[(y - 1) * w + x - 1] !== c) &&
      (x + 1 >= w || trial[(y - 1) * w + x + 1] !== c)
    ) {
      dirs.push(0, 0);
    }
    if (dirs.length === 0) return null;
    const dir = dirs[rng.upto(dirs.length)];
    openSlot(trial, x + dir, y);
    trial[y * w + x + dir] = NEW;

    // Full columns split the empty space into separate pockets; each pocket must
    // have an even number of cells (or, when h is odd, be fixable by adding a column).
    let odd = 0;
    let spare = 0;
    let pocket = 0;
    for (let i = 0; i < w; i++) {
      if (trial[bottom(i)] === 0) {
        if (h % 2) spare++;
        continue;
      }
      let free = 0;
      while (trial[free * w + i] === 0) free++;
      if (free === 0) {
        if (pocket % 2) odd++;
        pocket = 0;
      } else {
        pocket += free;
      }
    }
    if (pocket % 2) odd++;
    if (odd > spare) return null;

    const cells =
      dir === 0
        ? [(y - 1) * w + x, y * w + x]
        : [y * w + Math.min(x, x + dir), y * w + Math.max(x, x + dir)];
    for (const i of cells) trial[i] = c;
    for (let i = 0; i < wh; i++) grid[i] = trial[i];
    return cells;
  };

  for (;;) {
    grid.fill(0);
    const history: number[][] = [];
    const seedSize = 2 + (wh % 2);
    const c0 = 1 + rng.upto(nc);
    const seed: number[] = [];
    if (seedSize <= w) {
      for (let i = 0; i < seedSize; i++) seed.push(bottom(i));
    } else {
      for (let i = 0; i < seedSize; i++) seed.push((h - 1 - i) * w);
    }
    for (const i of seed) grid[i] = c0;
    history.push(seed.sort((a, b) => a - b));

    let stuck = false;
    for (;;) {
      points.length = 0;
      if (grid[wh - 1] === 0) {
        // The last column is empty, so a new column can go before any existing one
        // or right after the last.
        for (let x = 0; x < w; x++) {
          points.push(wh + x);
          if (grid[bottom(x)] === 0) break;
        }
      }
      for (let x = 0; x < w; x++) {
        if (grid[bottom(x)] === 0) break; // no more columns
        if (grid[x] !== 0) continue; // column full
        for (let y = h - 1; y >= 0; y--) {
          points.push(y * w + x);
          if (grid[y * w + x] === 0) break;
        }
      }
      if (points.length === 0) break; // grid is full
      rng.shuffle(points);
      let placed: number[] | null = null;
      for (const pos of points) {
        placed = tryInsert(pos);
        if (placed) break;
      }
      if (!placed) {
        stuck = true;
        break;
      }
      history.push(placed);
    }
    if (!stuck) return { grid: grid.slice(), solution: history.reverse() };
  }
}

/**
 * The quick generator: a uniformly random grid, except that every colour appears at
 * least twice and at least one removable pair exists.
 */
export function generateRandomGrid(w: number, h: number, nc: number, rng: Random): number[] {
  const n = w * h;
  const grid = new Array<number>(n).fill(0);
  for (;;) {
    grid.fill(0);
    for (let c = 1; c <= nc; c++) {
      for (let k = 0; k < 2; k++) {
        let i: number;
        do i = rng.upto(n);
        while (grid[i] !== 0);
        grid[i] = c;
      }
    }
    for (let i = 0; i < n; i++) if (grid[i] === 0) grid[i] = 1 + rng.upto(nc);
    if (!inspect(grid, w, h).impossible) return grid;
  }
}

// ------------------------------------------------------------------ helpers

function makeState(
  p: Pick<SameGameParams, 'w' | 'h' | 'ncols' | 'scoresub'>,
  tiles: number[],
  score = 0,
  from: number[] = [],
  removed: number[] = [],
): SameGameState {
  const { complete, impossible } = inspect(tiles, p.w, p.h);
  return {
    w: p.w,
    h: p.h,
    ncols: p.ncols,
    scoresub: p.scoresub,
    tiles,
    score,
    complete,
    impossible,
    from,
    removed,
  };
}

function clearSelection(ui: SameGameUI): void {
  ui.sel.fill(0);
  ui.nsel = 0;
}

function colourName(c: number): string {
  return SERIES[(c - 1) % SERIES.length];
}

function geometry(ds: DrawState) {
  const t = ds.tileSize;
  const border = Math.round(t * 0.3);
  return { t, border };
}

// ------------------------------------------------------------------ the game

const game = defineGame<SameGameParams, SameGameState, SameGameUI>({
  id: 'samegame',
  name: 'Same Game',
  description: 'Clear the board by removing groups of touching same-coloured squares.',
  alsoKnownAs: 'Clickomania',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [5, 5, 3],
      [10, 5, 3],
      [15, 10, 3],
      [15, 10, 4],
      [20, 15, 4],
    ] as [number, number, number][]
  ).map(([w, h, ncols]) => ({
    name: `${w}×${h}, ${ncols} colours`,
    params: { w, h, ncols, scoresub: 2, soluble: true },
  })),
  defaultParams: () => ({ w: 5, h: 5, ncols: 3, scoresub: 2, soluble: true }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}c${p.ncols}s${p.scoresub}${full && !p.soluble ? 'r' : ''}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    const m = /^(?:c(\d+))?(?:s(\d+))?(r)?/.exec(r.rest)!;
    return {
      w: r.w,
      h: r.h,
      ncols: m[1] ? parseInt(m[1], 10) : 3,
      scoresub: m[2] ? parseInt(m[2], 10) : 2,
      soluble: !m[3],
    };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.ncols, p.scoresub].every(Number.isInteger))
      return tx`Width, height and number of colours must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must both be positive`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.w * p.h > MAX_AREA) return tx`The grid may have at most ${MAX_AREA} squares`;
    if (p.ncols > 9) return tx`Maximum of 9 colours`;
    // Solubility is a generation-only setting: the short parameters of a descriptive id
    // leave it out, so they read back as soluble and must not refuse two colours.
    if (!full) {
      if (p.ncols < 2) return tx`Number of colours must be at least two`;
      if (p.w * p.h <= 1) return tx`Grid area must be greater than 1`;
    } else if (p.soluble) {
      if (p.ncols < 3) return tx`Number of colours must be at least three`;
      if (p.w * p.h <= 1) return tx`Grid area must be greater than 1`;
      // With only three colours the search for a clearable grid blows up past the largest
      // preset's 15×10 (seconds at 20×10, minutes at 25×15), on the main thread.
      // Only for generating: a shared grid of any size still loads.
      if (full && p.ncols === 3 && p.w * p.h > MAX_AREA_3)
        return tx`With three colours, a solvable grid may have at most ${MAX_AREA_3} squares`;
    } else {
      if (p.ncols < 2) return tx`Number of colours must be at least two`;
      if (p.w * p.h < p.ncols * 2) return tx`Too many colours makes given grid size impossible`;
    }
    if (p.scoresub !== 1 && p.scoresub !== 2) return tx`Scoring system not recognised`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: 'No. of colours', value: String(p.ncols) },
      {
        type: 'choices',
        name: 'Scoring system',
        choices: ['(n-1)^2', '(n-2)^2'],
        selected: p.scoresub - 1,
      },
      { type: 'boolean', name: 'Ensure solubility', value: p.soluble },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const str = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return {
      w: str(0),
      h: str(1),
      ncols: str(2),
      scoresub: (items[3] as { selected: number }).selected + 1,
      soluble: (items[4] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    const grid = p.soluble
      ? generateSolubleGrid(p.w, p.h, p.ncols, rng).grid
      : generateRandomGrid(p.w, p.h, p.ncols, rng);
    return { desc: grid.join(',') };
  },

  validateDesc(p, desc) {
    const parts = desc.split(',');
    if (parts.length !== p.w * p.h) return tx`Description must contain ${p.w * p.h} numbers`;
    for (const part of parts) {
      if (!/^\d+$/.test(part)) return tx`Description must contain only numbers`;
      if (parseInt(part, 10) > p.ncols) return tx`Colour out of range`;
    }
    return null;
  },

  newGame(p, desc) {
    return makeState(p, desc.split(',').map(Number));
  },

  canSolve: false,

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const c = s.tiles[y * s.w + x];
        row += c === 0 ? ' ' : c < 10 ? String(c) : String.fromCharCode(87 + c);
      }
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI: (s) => ({ sel: new Uint8Array(s.w * s.h), nsel: 0, cx: 0, cy: 0, cursorVisible: false }),
  changedState(ui, _old, s) {
    clearSelection(ui);
    if (s.complete || s.impossible) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h } = state;
    let tx: number;
    let ty: number;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const wasVisible = ui.cursorVisible;
      ui.cursorVisible = false;
      const { t, border } = geometry(ds);
      tx = Math.floor((mx - border) / t);
      ty = Math.floor((my - border) / t);
      if (tx < 0 || ty < 0 || tx >= w || ty >= h) return wasVisible ? '' : null;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h, true);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (isCursorSelect(b)) {
      ui.cursorVisible = true;
      tx = ui.cx;
      ty = ui.cy;
    } else {
      return null;
    }
    const i = ty * w + tx;
    if (state.tiles[i] === 0) return b === LEFT_BUTTON || b === RIGHT_BUTTON ? '' : null;
    if (ui.sel[i]) {
      if (b === RIGHT_BUTTON || b === CURSOR_SELECT2) {
        clearSelection(ui);
        return '';
      }
      const cells: number[] = [];
      for (let k = 0; k < ui.sel.length; k++) if (ui.sel[k]) cells.push(k);
      clearSelection(ui);
      return 'M' + cells.join(',');
    }
    clearSelection(ui);
    const group = groupAt(state.tiles, w, h, i);
    if (group.length > 1) {
      for (const k of group) ui.sel[k] = 1;
      ui.nsel = group.length;
    }
    return '';
  },

  executeMove(state, move) {
    if (!/^M\d+(,\d+)*$/.test(move)) return null;
    const { w, h } = state;
    const cells = move.slice(1).split(',').map(Number);
    if (cells.length < 2) return null;
    const first = cells[0];
    if (first >= w * h || state.tiles[first] === 0) return null;
    // The move must name exactly one whole connected group, in any order.
    const group = groupAt(state.tiles, w, h, first);
    if (group.length !== cells.length) return null;
    const sorted = cells.slice().sort((a, b) => a - b);
    for (let k = 0; k < group.length; k++) if (group[k] !== sorted[k]) return null;
    const tiles = state.tiles.slice();
    for (const i of cells) tiles[i] = 0;
    const from = settleMap(tiles, w, h);
    return makeState(
      state,
      tiles,
      state.score + npoints(cells.length, state.scoresub),
      from,
      cells.slice(),
    );
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const border = Math.round(t * 0.3);
    return { w: p.w * t + 2 * border, h: p.h * t + 2 * border };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h } = state;
    const { t, border } = geometry(ds);
    const flashing = flashOn(flashTime, FLASH_FRAME);

    dr.rect(border - 3, border - 3, w * t + 6, h * t + 6, flashing ? 'shade' : null, 'ink', {
      width: 2.4,
    });

    if (oldState) {
      drawMove(dr, ds, oldState, state, dir, animTime);
    } else {
      const regions = findRegions(state.tiles, w, h);
      for (const region of sortByNesting(regions)) {
        const colour = colourName(region.colour);
        const selected = ui.sel[region.cells[0]] === 1;
        const fill = state.impossible
          ? dr.mix(colour, 'paper', 0.55)
          : selected
            ? dr.mix(colour, 'highlight', 0.4)
            : colour;
        const stroke = state.impossible ? 'pencil' : 'ink';
        const width = selected ? 3.2 : 1.6;
        region.loops.forEach((loop, k) => {
          const pts = outlinePoints(loop, t, border, t * 0.05, t * 0.16);
          // Only the outer loop is filled; regions sitting in a hole are drawn later on top.
          dr.polygon(pts, k === 0 ? fill : null, stroke, { width, seed: region.cells[0] });
        });
        if (state.impossible) {
          for (const i of region.cells) {
            const x = i % w;
            const y = (i - x) / w;
            dr.cross(border + (x + 0.5) * t, border + (y + 0.5) * t, t * 0.13, 'pencil', 1.4, {
              seed: i,
            });
          }
        }
      }
    }

    if (ui.cursorVisible && !oldState) {
      const pad = Math.max(2, t * 0.1);
      dr.cursor(border + ui.cx * t + pad, border + ui.cy * t + pad, t - 2 * pad, t - 2 * pad);
    }

    const score = tr('games.samegame.status.score', { n: state.score });
    dr.statusBar(
      state.complete
        ? tr('games.samegame.status.complete', { score })
        : state.impossible
          ? tr('games.samegame.status.stuck', { score })
          : ui.nsel
            ? tr('games.samegame.status.selected', {
                score,
                n: ui.nsel,
                points: npoints(ui.nsel, state.scoresub),
              })
            : score,
    );
  },

  animLength(oldState, newState, dir) {
    // A deal has no provenance to draw, and neither has a Solve or a Restart (the midend
    // keeps those instant). Only a group actually being taken off the board travels.
    const later = dir > 0 ? newState : oldState;
    return later.removed.length > 0 ? ANIM : 0;
  },
  flashLength(oldState, newState) {
    if (!oldState.complete && newState.complete) return 2 * FLASH_FRAME;
    if (!oldState.impossible && newState.impossible) return 2 * FLASH_FRAME;
    return 0;
  },
  status: (s) => (s.complete ? 1 : s.impossible ? -1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  // Stranded squares are one Undo away from another try, as the help and the tutorial
  // both say: the end panel should offer that, not a Restart that throws the board away.
  flags: { undoAfterLoss: true },
});

// ------------------------------------------------------------------ region outlines

/**
 * A move, drawn as the thing it actually is: the group you picked shrinks into the paper,
 * and everything still standing falls into the gap and shunts left behind it. Without
 * this the whole board rearranges between two frames, which is the one moment in Same
 * Game where the player most needs to see what their click did.
 */
function drawMove(
  dr: Drawing,
  ds: DrawState,
  oldState: SameGameState,
  state: SameGameState,
  dir: number,
  animTime: number,
): void {
  const { w, h } = state;
  const { t, border } = geometry(ds);
  // `oldState` is whatever was on screen a moment ago whichever way the move is running,
  // so raw progress runs from it to `state`. `p` puts that back on the move's own axis:
  // 0 is the board before the group went, 1 is the board after it settled. An undo simply
  // walks it backwards, and the group rises out of the paper again.
  const q = clamp(animTime / ANIM, 0, 1);
  const later = dir > 0 ? state : oldState;
  const earlier = dir > 0 ? oldState : state;
  const p = dir > 0 ? q : 1 - q;
  // The group goes first and the fall overlaps its last moments, so the board is never
  // still: by the time the squares above have gathered speed there is a gap to fall into.
  const vanish = clamp(p / 0.42, 0, 1);
  const fall = easeInOut(clamp((p - 0.3) / 0.7, 0, 1));

  const cellX = (i: number) => i % w;
  const cellY = (i: number) => Math.floor(i / w);
  const shift = (pts: number[], ox: number, oy: number) => {
    for (let j = 0; j < pts.length; j += 2) {
      pts[j] += ox;
      pts[j + 1] += oy;
    }
    return pts;
  };

  // What survived, grouped by colour *and* by how far it is travelling, so a block moving
  // as one is still outlined as one. Two same-coloured blocks that are about to become
  // neighbours keep their own outlines until they land — which is the one moment in this
  // game where the merge is the whole point, and worth seeing happen.
  const classes = new Map<string, number>();
  const info: { colour: number; dx: number; dy: number }[] = [];
  const key = new Int32Array(w * h);
  for (let i = 0; i < w * h; i++) {
    const colour = later.tiles[i];
    if (!colour) continue;
    const src = later.from[i];
    const dx = src >= 0 ? cellX(i) - cellX(src) : 0;
    const dy = src >= 0 ? cellY(i) - cellY(src) : 0;
    const name = `${colour}:${dx}:${dy}`;
    let id = classes.get(name);
    if (id === undefined) {
      id = info.push({ colour, dx, dy });
      classes.set(name, id);
    }
    key[i] = id;
  }
  for (const region of sortByNesting(findRegions(key, w, h))) {
    const { colour, dx, dy } = info[region.colour - 1];
    // Held back from where it ends up, by the whole distance at `fall` 0 and by none of
    // it at 1.
    const ox = -dx * t * (1 - fall);
    const oy = -dy * t * (1 - fall);
    region.loops.forEach((loop, k) => {
      const pts = shift(outlinePoints(loop, t, border, t * 0.05, t * 0.16), ox, oy);
      dr.polygon(pts, k === 0 ? colourName(colour) : null, 'ink', {
        width: 1.6,
        seed: region.cells[0],
      });
    });
  }

  // And the group that was taken, collapsing towards its own middle as it fades.
  if (vanish < 1) {
    const gone = new Int32Array(w * h);
    for (const i of later.removed) gone[i] = earlier.tiles[i];
    for (const region of findRegions(gone, w, h)) {
      let cx = 0;
      let cy = 0;
      for (const i of region.cells) {
        cx += cellX(i) + 0.5;
        cy += cellY(i) + 0.5;
      }
      cx = border + (cx / region.cells.length) * t;
      cy = border + (cy / region.cells.length) * t;
      const scale = 1 - 0.55 * vanish;
      region.loops.forEach((loop, k) => {
        const pts = outlinePoints(loop, t, border, t * 0.05, t * 0.16);
        for (let j = 0; j < pts.length; j += 2) {
          pts[j] = cx + (pts[j] - cx) * scale;
          pts[j + 1] = cy + (pts[j + 1] - cy) * scale;
        }
        dr.polygon(pts, k === 0 ? colourName(region.colour) : null, 'ink', {
          width: 1.6,
          seed: region.cells[0],
          alpha: 1 - vanish,
        });
      });
    }
  }
}

interface Region {
  colour: number;
  cells: number[];
  /** Boundary loops as lattice points [x0, y0, x1, y1, ...]; loops[0] is the outer one. */
  loops: number[][];
  /** Centre of the first cell, in lattice units, for nesting tests. */
  px: number;
  py: number;
  /** How many other regions' holes this one sits inside. */
  depth: number;
}

/** Split the board into connected same-coloured regions with their boundary loops. */
export function findRegions(tiles: ArrayLike<number>, w: number, h: number): Region[] {
  const seen = new Uint8Array(w * h);
  const regions: Region[] = [];
  for (let i = 0; i < w * h; i++) {
    if (seen[i] || !tiles[i]) continue;
    const cells = groupAt(tiles, w, h, i);
    for (const k of cells) seen[k] = 1;
    const x = i % w;
    regions.push({
      colour: tiles[i],
      cells,
      loops: traceLoops(cells, w),
      px: x + 0.5,
      py: (i - x) / w + 0.5,
      depth: 0,
    });
  }
  return regions;
}

/**
 * Boundary loops of a set of cells, walked clockwise (on screen) with the region on
 * the right-hand side. At a vertex where two cells of the region touch only
 * diagonally the walk turns right, which keeps every loop simple. The loop through
 * the top-left corner of the top-left-most cell is the outer one and comes first.
 */
function traceLoops(cells: number[], w: number): number[][] {
  const inRegion = new Set(cells);
  // Directed edges keyed by start vertex; vertex key = vy * (w + 1) + vx.
  const W1 = w + 1;
  const edges = new Map<number, number[]>();
  const add = (x0: number, y0: number, x1: number, y1: number) => {
    const k = y0 * W1 + x0;
    const list = edges.get(k);
    if (list) list.push(y1 * W1 + x1);
    else edges.set(k, [y1 * W1 + x1]);
  };
  for (const i of cells) {
    const x = i % w;
    const y = (i - x) / w;
    if (!inRegion.has(i - w) || y === 0) add(x, y, x + 1, y);
    if (x + 1 >= w || !inRegion.has(i + 1)) add(x + 1, y, x + 1, y + 1);
    if (!inRegion.has(i + w)) add(x + 1, y + 1, x, y + 1);
    if (x === 0 || !inRegion.has(i - 1)) add(x, y + 1, x, y);
  }
  const loops: number[][] = [];
  const first = cells[0]; // cells are sorted, so this is the top-left-most
  const startKey = Math.floor(first / w) * W1 + (first % w);
  const takeFrom = (k: number, prevDx: number, prevDy: number): number => {
    const list = edges.get(k)!;
    let best = 0;
    if (list.length > 1) {
      // Prefer the right turn: with y down, turning right from (dx, dy) gives (-dy, dx).
      const vx = k % W1;
      const vy = (k - vx) / W1;
      for (let j = 0; j < list.length; j++) {
        const nx = list[j] % W1;
        const ny = (list[j] - nx) / W1;
        if (nx - vx === -prevDy && ny - vy === prevDx) best = j;
      }
    }
    const next = list[best];
    list.splice(best, 1);
    if (list.length === 0) edges.delete(k);
    return next;
  };
  const walk = (start: number): number[] => {
    const pts: number[] = [];
    let k = start;
    let dx = 0;
    let dy = 0;
    do {
      const vx = k % W1;
      const vy = (k - vx) / W1;
      const next = takeFrom(k, dx, dy);
      const nx = next % W1;
      const ny = (next - nx) / W1;
      const ndx = Math.sign(nx - vx);
      const ndy = Math.sign(ny - vy);
      // Skip vertices along a straight run so that each side is one long stroke.
      if (ndx !== dx || ndy !== dy) pts.push(vx, vy);
      dx = ndx;
      dy = ndy;
      k = next;
    } while (k !== start && edges.has(k));
    // A hole walk may begin mid-side; drop that first point if it is collinear.
    const n = pts.length / 2;
    if (n > 2) {
      const [ax, ay] = [pts[2 * n - 2], pts[2 * n - 1]];
      const [bx, by] = [pts[0], pts[1]];
      const [cx, cy] = [pts[2], pts[3]];
      if ((ax === bx && bx === cx) || (ay === by && by === cy)) pts.splice(0, 2);
    }
    return pts;
  };
  loops.push(walk(startKey));
  while (edges.size > 0) loops.push(walk(edges.keys().next().value!));
  return loops;
}

/** Cell centres inside a lattice loop (even-odd rule) are what we test for nesting. */
function pointInLoop(loop: number[], px: number, py: number): boolean {
  let inside = false;
  const n = loop.length / 2;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = loop[2 * i];
    const yi = loop[2 * i + 1];
    const xj = loop[2 * j];
    const yj = loop[2 * j + 1];
    if (yi > py !== yj > py && px < xi + ((xj - xi) * (py - yi)) / (yj - yi)) inside = !inside;
  }
  return inside;
}

/**
 * Order regions so that any region lying in a hole of another is drawn after it.
 * Only regions with more than one boundary loop can contain anything, and nesting is
 * a tree, so the number of holes a region sits inside is its depth.
 */
function sortByNesting(regions: Region[]): Region[] {
  const holed = regions.filter((r) => r.loops.length > 1);
  if (holed.length === 0) return regions;
  for (const r of regions) {
    r.depth = 0;
    for (const outer of holed) {
      if (outer === r) continue;
      for (let k = 1; k < outer.loops.length; k++) {
        if (pointInLoop(outer.loops[k], r.px, r.py)) r.depth++;
      }
    }
  }
  return regions.slice().sort((a, b) => a.depth - b.depth);
}

/**
 * Screen-space polygon for a lattice loop: inset by `g` (so neighbouring blobs
 * leave a small gap) and rounded at convex corners with radius `r`.
 */
function outlinePoints(loop: number[], t: number, border: number, g: number, r: number): number[] {
  const n = loop.length / 2;
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    const px = loop[2 * ((i + n - 1) % n)];
    const py = loop[2 * ((i + n - 1) % n) + 1];
    const x = loop[2 * i];
    const y = loop[2 * i + 1];
    const qx = loop[2 * ((i + 1) % n)];
    const qy = loop[2 * ((i + 1) % n) + 1];
    const d1x = Math.sign(x - px);
    const d1y = Math.sign(y - py);
    const d2x = Math.sign(qx - x);
    const d2y = Math.sign(qy - y);
    // Inward (right-hand) normals of the incoming and outgoing edges.
    const n1x = -d1y;
    const n1y = d1x;
    const n2x = -d2y;
    const n2y = d2x;
    const vx = border + x * t + (n1x + n2x) * g;
    const vy = border + y * t + (n1y + n2y) * g;
    const rightTurn = d2x === -d1y && d2y === d1x;
    if (d1x === d2x && d1y === d2y) {
      // Straight through: a plain inset point.
      out.push(border + x * t + n1x * g, border + y * t + n1y * g);
      continue;
    }
    if (!rightTurn || r <= 0) {
      out.push(vx, vy);
      continue;
    }
    const cx = vx + (n1x + n2x) * r;
    const cy = vy + (n1y + n2y) * r;
    const a0 = Math.atan2(vy - d1y * r - cy, vx - d1x * r - cx);
    const steps = 3;
    for (let s = 0; s <= steps; s++) {
      const a = a0 + ((Math.PI / 2) * s) / steps;
      out.push(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
  }
  return out;
}

export default game;
