import type { Game } from '../framework/types';

/**
 * Every `src/games/<slug>/index.ts` that default-exports a Game is picked up here, so
 * adding a game never requires touching a shared file.
 */
const modules = import.meta.glob<{ default: Game }>('./*/index.ts', { eager: true });

export const games: Game[] = Object.values(modules)
  .map((m) => m.default)
  .filter((g): g is Game => !!g && typeof g.id === 'string')
  .sort((a, b) => a.name.localeCompare(b.name));

const byId = new Map(games.map((g) => [g.id, g]));

export function getGame(id: string): Game | undefined {
  return byId.get(id);
}

/** A game that does not say otherwise is "quick to pick up". See `Game.menuTier`. */
export const DEFAULT_MENU_TIER = 2;

export function menuTier(game: Game): number {
  return game.menuTier ?? DEFAULT_MENU_TIER;
}

/**
 * The order the menu shows its cards in: the puzzles a newcomer already knows first, the
 * ones that want their help page last, alphabetical inside each tier. Plain alphabetical
 * order opened the collection on Black Box, which is nobody's idea of a first puzzle.
 *
 * The English name is the tie-break, as it is for `games`, so the running order does not
 * shuffle itself when the player changes language.
 */
export const menuGames: Game[] = [...games].sort(
  (a, b) => menuTier(a) - menuTier(b) || a.name.localeCompare(b.name),
);
