/**
 * Towers solver.
 *
 * The grid is a latin square, so the generic latin-square machinery does the digit
 * bookkeeping; this module adds the reasoning about the visibility clues around the
 * edge and grades puzzles:
 *  - Easy: a pair of facing clues adding up to w+1 pins the tallest tower; the square
 *    right next to a clue that is one short of complete must be tall enough to be the
 *    last visible tower; and every tower has a lower bound on its distance from a clue
 *    (the tallest cannot be among the first clue-1 squares, and so on) — plus the plain
 *    row/column eliminations of a latin square.
 *  - Hard: for one clue, enumerate every arrangement of its line that fits the
 *    candidates and the clue, and rule out digits that occur in none of them; plus set
 *    elimination within rows and columns.
 *  - Extreme: positional set elimination on a single digit and forcing chains.
 *  - Unreasonable: guessing and backtracking.
 */
import {
  LATIN_AMBIGUOUS,
  LATIN_IMPOSSIBLE,
  LATIN_UNFINISHED,
  LatinSolver,
  latinSolve,
} from './latin';

export const DIFF_EASY = 0;
export const DIFF_HARD = 1;
export const DIFF_EXTREME = 2;
export const DIFF_UNREASONABLE = 3;
export const DIFF_COUNT = 4;
export const DIFF_IMPOSSIBLE = LATIN_IMPOSSIBLE;
export const DIFF_AMBIGUOUS = LATIN_AMBIGUOUS;
export const DIFF_UNFINISHED = LATIN_UNFINISHED;
export const DIFF_NAMES = ['Easy', 'Hard', 'Extreme', 'Unreasonable'];
export const DIFF_CHARS = 'ehxu';

/**
 * Clues are numbered 0..4w-1: the first w sit above the columns, the next w below them,
 * then w down the left of the rows and w down the right. `clueLine` gives the grid index
 * of the square nearest the clue and the step that walks away from it.
 */
export function clueLine(w: number, c: number): [start: number, step: number] {
  if (c < w) return [c, w];
  if (c < 2 * w) return [(w - 1) * w + (c - w), -w];
  if (c < 3 * w) return [w * (c - 2 * w), 1];
  return [w * (c - 3 * w) + (w - 1), -1];
}

/** Grid coordinates (one step outside the grid) of the square where clue `c` is written. */
export function cluePos(w: number, c: number): [x: number, y: number] {
  if (c < w) return [c, -1];
  if (c < 2 * w) return [c - w, w];
  if (c < 3 * w) return [-1, c - 2 * w];
  return [w, c - 3 * w];
}

/** The clue facing `c` from the other end of the same line. */
export function facingClue(w: number, c: number): number {
  return c < w ? c + w : c < 2 * w ? c - w : c < 3 * w ? c + w : c - w;
}

/** How many towers are seen looking along `heights` from its start (taller hides shorter). */
export function visibleCount(heights: ArrayLike<number>): number {
  let best = 0;
  let seen = 0;
  for (let i = 0; i < heights.length; i++) {
    if (heights[i] > best) {
      best = heights[i];
      seen++;
    }
  }
  return seen;
}

/** Heights along the line of clue `c`, nearest the clue first. */
export function lineHeights(w: number, grid: ArrayLike<number>, c: number): number[] {
  const [start, step] = clueLine(w, c);
  const out: number[] = [];
  for (let i = 0; i < w; i++) out.push(grid[start + i * step]);
  return out;
}

/** All 4w clues of a complete grid. */
export function computeClues(w: number, grid: ArrayLike<number>): Int32Array {
  const clues = new Int32Array(4 * w);
  for (let c = 0; c < 4 * w; c++) clues[c] = visibleCount(lineHeights(w, grid, c));
  return clues;
}

export interface TowersErrors {
  /** 1 where a digit is repeated in its row or column. */
  cells: Uint8Array;
  /** 1 for each clue that the filled-in towers already contradict. */
  clues: Uint8Array;
  /** Anything wrong or unfinished — false exactly when the puzzle is solved. */
  any: boolean;
}

/**
 * Duplicate digits and violated clues. Only the unbroken run of towers next to a clue is
 * read, and it violates the clue once it shows more towers than the clue allows; once it
 * reaches the tallest tower and shows fewer, since nothing behind that can be seen; or
 * once it shows exactly the clue without the tallest, which is still to come and will
 * be seen too.
 */
export function checkErrors(w: number, clues: ArrayLike<number>, grid: ArrayLike<number>) {
  const a = w * w;
  const cells = new Uint8Array(a);
  const clueErr = new Uint8Array(4 * w);
  let any = false;
  const full = (1 << (w + 1)) - 2;
  for (let y = 0; y < w; y++) {
    let mask = 0;
    let dup = 0;
    for (let x = 0; x < w; x++) {
      const bit = 1 << grid[y * w + x];
      dup |= mask & bit;
      mask |= bit;
    }
    if (mask !== full) {
      any = true;
      dup &= ~1;
      for (let x = 0; x < w; x++) if (dup & (1 << grid[y * w + x])) cells[y * w + x] = 1;
    }
  }
  for (let x = 0; x < w; x++) {
    let mask = 0;
    let dup = 0;
    for (let y = 0; y < w; y++) {
      const bit = 1 << grid[y * w + x];
      dup |= mask & bit;
      mask |= bit;
    }
    if (mask !== full) {
      any = true;
      dup &= ~1;
      for (let y = 0; y < w; y++) if (dup & (1 << grid[y * w + x])) cells[y * w + x] = 1;
    }
  }
  for (let c = 0; c < 4 * w; c++) {
    if (!clues[c]) continue;
    const [start, step] = clueLine(w, c);
    let best = 0;
    let seen = 0;
    let j = 0;
    for (; j < w; j++) {
      const d = grid[start + j * step];
      if (!d) break;
      if (d > best) {
        best = d;
        seen++;
      }
    }
    if (seen > clues[c] || (best === w && seen < clues[c]) || (best < w && seen === clues[c])) {
      clueErr[c] = 1;
      any = true;
    }
  }
  const errors: TowersErrors = { cells, clues: clueErr, any };
  return errors;
}

interface Ctx {
  w: number;
  clues: ArrayLike<number>;
  /** The one-off facing-clues deduction has been done (shared with sub-solvers). */
  started: boolean;
  /** Scratch: position along the current line of each digit, or w if not placed. */
  where: Int32Array;
}

function solverEasy(s: LatinSolver, ctx: Ctx): number {
  const { w, clues, where } = ctx;
  const { grid, cube } = s;
  let ret = 0;

  if (!ctx.started) {
    ctx.started = true;
    // Facing clues adding up to w+1 mean the line rises to the tallest tower from both
    // ends, so the tallest tower sits exactly clue squares in from either side.
    for (let c = 0; c < 3 * w; c = c === w - 1 ? 2 * w : c + 1) {
      const c2 = facingClue(w, c);
      if (!clues[c] || !clues[c2] || clues[c] + clues[c2] !== w + 1) continue;
      const [start, step] = clueLine(w, c);
      const pos = start + (clues[c] - 1) * step;
      if (!cube[pos * w + w - 1]) return -1;
      if (grid[pos]) continue;
      s.place(pos % w, Math.floor(pos / w), w);
      ret = 1;
    }
    if (ret) return ret;
  }

  for (let c = 0; c < 4 * w; c++) {
    const clue = clues[c];
    if (!clue) continue;
    const [start, step] = clueLine(w, c);
    where.fill(w);
    for (let i = 0; i < w; i++) {
      const d = grid[start + i * step];
      if (d) where[d - 1] = i;
    }

    // The tallest towers that are all placed form a visible run of `seen` towers whose
    // nearest member is `furthest` squares in. If the clue needs exactly one more, the
    // square next to the clue must be the missing one, and it overlooks the furthest-1
    // squares between: it cannot be any of the furthest-1 smallest available digits.
    let seen = 0;
    let furthest = w;
    for (let i = w; i >= 1; i--) {
      if (where[i - 1] === w) break;
      if (where[i - 1] < furthest) {
        furthest = where[i - 1];
        seen++;
      }
    }
    if (clue === seen + 1 && furthest > 1) {
      let j = furthest - 1;
      for (let i = 1; i <= w && j > 0; i++) {
        if (where[i - 1] < w && where[i - 1] >= furthest) continue;
        j--;
        if (cube[start * w + i - 1]) {
          cube[start * w + i - 1] = 0;
          ret = 1;
        }
      }
    }
    if (ret) return ret;

    // Lower bounds: the tallest tower cannot be among the first clue-1 squares (there
    // would be no room for the rising sequence that ends at it), the next tallest that
    // could still be visible not among the first clue-2, and so on. A placed tower with a
    // taller one nearer the clue is hidden and does not count.
    let rank = 0;
    for (let n = w; n > 0; n--) {
      if (where[n - 1] < w) {
        let hidden = false;
        for (let m = n + 1; m <= w; m++) {
          if (where[m - 1] < where[n - 1]) {
            hidden = true;
            break;
          }
        }
        if (hidden) continue;
      }
      for (let j = 0; j < clue - rank - 1; j++) {
        const p = (start + j * step) * w + n - 1;
        if (cube[p]) {
          cube[p] = 0;
          ret = 1;
        }
      }
      rank++;
    }
  }
  return ret;
}

function solverHard(s: LatinSolver, ctx: Ctx): number {
  const { w, clues } = ctx;
  const { cube } = s;
  const possible = new Int32Array(w);
  const vals = new Int32Array(w);
  for (let c = 0; c < 4 * w; c++) {
    const clue = clues[c];
    if (!clue) continue;
    const [start, step] = clueLine(w, c);
    possible.fill(0);
    // Enumerate every arrangement of the line that respects the candidates and shows
    // exactly `clue` towers, remembering which digits appear at each position.
    const rec = (i: number, used: number, best: number, seen: number): void => {
      if (i === w) {
        if (seen === clue) for (let j = 0; j < w; j++) possible[j] |= 1 << vals[j];
        return;
      }
      if (seen + (w - i) < clue || (best === w && seen < clue)) return;
      const base = (start + i * step) * w;
      for (let d = 1; d <= w; d++) {
        if (used & (1 << d) || !cube[base + d - 1]) continue;
        if (d > best && seen === clue) continue;
        vals[i] = d;
        if (d > best) rec(i + 1, used | (1 << d), d, seen + 1);
        else rec(i + 1, used | (1 << d), best, seen);
      }
    };
    rec(0, 0, 0, 0);
    let ret = 0;
    for (let i = 0; i < w; i++) {
      const base = (start + i * step) * w;
      for (let d = 1; d <= w; d++) {
        if (cube[base + d - 1] && !(possible[i] & (1 << d))) {
          cube[base + d - 1] = 0;
          ret = 1;
        }
      }
    }
    // Go back to the easier deductions as soon as one clue yields something.
    if (ret) return ret;
  }
  return 0;
}

const LEVELS = {
  simple: DIFF_EASY,
  set0: DIFF_HARD,
  set1: DIFF_EXTREME,
  forcing: DIFF_EXTREME,
  recursive: DIFF_UNREASONABLE,
};
const USER_SOLVERS = [solverEasy, solverHard, null, null];

/**
 * Solve `grid` in place with deductions up to `maxdiff`. Returns the difficulty needed,
 * DIFF_UNFINISHED if that was not enough, or DIFF_IMPOSSIBLE / DIFF_AMBIGUOUS.
 */
export function solveTowers(
  w: number,
  clues: ArrayLike<number>,
  grid: Uint8Array,
  maxdiff: number,
): number {
  const ctx: Ctx = { w, clues, started: false, where: new Int32Array(w) };
  return latinSolve(grid, w, maxdiff, LEVELS, USER_SOLVERS, ctx);
}
