/**
 * Tents board model: cell values, the game description format, the completion test and
 * the error highlighter.
 *
 * A description is a run-length encoding of the trees followed by the row and column
 * counts, exactly as in the original collection: `_` is a tree with no blanks before it,
 * `a`..`y` are 1..25 blanks followed by a tree, `z` is 25 blanks with no tree, and the
 * grid is terminated by one virtual tree at index w*h. Then `,n` for each column count
 * (left to right) and each row count (top to bottom). The rare `!` and `-` characters
 * turn the square just emitted into a given tent or given grass mark.
 */
import { tx } from '../../i18n';
import { DIRS4, inBounds } from '../../framework/grid';
import { DSF } from '../../framework/dsf';
import { maxMatching } from './matching';

export const BLANK = 0;
export const TREE = 1;
export const TENT = 2;
export const NONTENT = 3;

export interface Board {
  /** Cell values, row-major. */
  grid: Uint8Array;
  /** Column counts (w of them) then row counts (h of them). */
  numbers: number[];
}

/** Parse a description, returning the initial grid and counts or an error message. */
export function parseDesc(desc: string, w: number, h: number): Board | string {
  const n = w * h;
  const comma = desc.indexOf(',');
  const gridPart = comma < 0 ? desc : desc.slice(0, comma);
  const grid = new Uint8Array(n);
  let i = 0;
  let done = false;
  for (const ch of gridPart) {
    // Nothing may follow the terminating virtual tree.
    if (done) return tx`Too much data to fill grid`;
    let run: number;
    let type = TREE;
    if (ch === '_') run = 0;
    else if (ch >= 'a' && ch < 'z') run = ch.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
    else if (ch === 'z') {
      run = 25;
      type = BLANK;
    } else if (ch === '!' || ch === '-') {
      run = -1;
      type = ch === '!' ? TENT : NONTENT;
    } else return tx`Invalid character in grid specification`;
    i += run;
    if (i < 0) return tx`Invalid character in grid specification`;
    if (i > n) return tx`Too much data to fill grid`;
    if (i === n) {
      if (type !== TREE) return tx`Too much data to fill grid`;
      done = true;
      continue;
    }
    if (type !== BLANK) grid[i++] = type;
  }
  if (!done) return tx`Not enough data to fill grid`;

  const numbers: number[] = [];
  const rest = comma < 0 ? '' : desc.slice(comma);
  const parts = rest.split(',');
  // parts[0] is the empty string before the first comma.
  if (parts.length - 1 < w + h) return tx`Not enough numbers given after grid specification`;
  if (parts.length - 1 > w + h) return tx`Unexpected additional data at end of game description`;
  for (let k = 1; k < parts.length; k++) {
    if (!/^\d+$/.test(parts[k])) return tx`Invalid character in number list`;
    numbers.push(parseInt(parts[k], 10));
  }
  return { grid, numbers };
}

/** Encode trees (any non-tree value in `grid` counts as blank) and counts as a description. */
export function encodeDesc(grid: Uint8Array, w: number, h: number, numbers: number[]): string {
  const n = w * h;
  let out = '';
  let run = 0;
  for (let i = 0; i <= n; i++) {
    if (i === n || grid[i] === TREE) {
      out += run === 0 ? '_' : String.fromCharCode('a'.charCodeAt(0) + run - 1);
      run = 0;
    } else {
      run++;
      while (run > 25) {
        out += 'z';
        run -= 25;
      }
    }
  }
  for (const k of numbers) out += `,${k}`;
  return out;
}

/** Tent counts per column then per row. */
export function countTents(grid: Uint8Array, w: number, h: number): number[] {
  const numbers = new Array<number>(w + h).fill(0);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (grid[y * w + x] === TENT) {
        numbers[x]++;
        numbers[w + y]++;
      }
    }
  }
  return numbers;
}

/** Whether any two tents touch, even diagonally. */
export function tentsTouch(grid: Uint8Array, w: number, h: number): boolean {
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (grid[y * w + x] !== TENT) continue;
      for (const [dx, dy] of [
        [1, 0],
        [-1, 1],
        [0, 1],
        [1, 1],
      ]) {
        const nx = x + dx;
        const ny = y + dy;
        if (inBounds(nx, ny, w, h) && grid[ny * w + nx] === TENT) return true;
      }
    }
  }
  return false;
}

/**
 * Whether the trees and tents can be paired off so that every tree is orthogonally
 * adjacent to its own tent: a perfect matching of the tree/tent adjacency graph.
 */
export function treesMatchTents(grid: Uint8Array, w: number, h: number): boolean {
  const trees: number[] = [];
  const tentIndex = new Int32Array(w * h).fill(-1);
  let ntents = 0;
  for (let i = 0; i < w * h; i++) {
    if (grid[i] === TREE) trees.push(i);
    else if (grid[i] === TENT) tentIndex[i] = ntents++;
  }
  if (trees.length !== ntents) return false;
  const adj: number[][] = trees.map((i) => {
    const x = i % w;
    const y = Math.floor(i / w);
    const out: number[] = [];
    for (const [dx, dy] of DIRS4) {
      const nx = x + dx;
      const ny = y + dy;
      if (inBounds(nx, ny, w, h) && tentIndex[ny * w + nx] >= 0) out.push(tentIndex[ny * w + nx]);
    }
    return out;
  });
  return maxMatching(trees.length, ntents, adj).size === trees.length;
}

/** The full win condition. */
export function isComplete(grid: Uint8Array, w: number, h: number, numbers: number[]): boolean {
  const counts = countTents(grid, w, h);
  for (let i = 0; i < w + h; i++) if (counts[i] !== numbers[i]) return false;
  if (tentsTouch(grid, w, h)) return false;
  return treesMatchTents(grid, w, h);
}

// ------------------------------------------------------------------ error highlighting

/** Bits in `Errors.cells`: a tent touching its neighbour in that direction. */
export const ERR_ADJ_TOPLEFT = 1 << 0;
export const ERR_ADJ_TOP = 1 << 1;
export const ERR_ADJ_TOPRIGHT = 1 << 2;
export const ERR_ADJ_LEFT = 1 << 3;
export const ERR_ADJ_RIGHT = 1 << 4;
export const ERR_ADJ_BOTLEFT = 1 << 5;
export const ERR_ADJ_BOT = 1 << 6;
export const ERR_ADJ_BOTRIGHT = 1 << 7;
/** A tent in a group with too few trees, or a tree in a group with no room for its tent. */
export const ERR_OVERCOMMITTED = 1 << 8;
export const ERR_ADJ_ANY = ERR_OVERCOMMITTED - 1;

export interface Errors {
  /** Bit set per cell. */
  cells: Int32Array;
  /** 1 per column then row whose count can no longer be met exactly. */
  lines: Uint8Array;
}

/**
 * Highlight play errors. Beyond touching tents and violated counts, the tree/tent
 * matching failures are found the way the original does it: split the tree–tent
 * adjacency graph into connected components and flag any component with more tents than
 * trees (the tents are wrong) or, counting blanks as possible tents, more trees than
 * room (the trees can no longer all be served). A tree is never flagged merely because
 * its tent has not been placed yet.
 */
export function findErrors(grid: Uint8Array, w: number, h: number, numbers: number[]): Errors {
  const n = w * h;
  const cells = new Int32Array(n);
  const lines = new Uint8Array(w + h);

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (grid[i] !== TENT) continue;
      if (x + 1 < w && grid[i + 1] === TENT) {
        cells[i] |= ERR_ADJ_RIGHT;
        cells[i + 1] |= ERR_ADJ_LEFT;
      }
      if (y + 1 < h && grid[i + w] === TENT) {
        cells[i] |= ERR_ADJ_BOT;
        cells[i + w] |= ERR_ADJ_TOP;
      }
      if (y + 1 < h && x + 1 < w && grid[i + w + 1] === TENT) {
        cells[i] |= ERR_ADJ_BOTRIGHT;
        cells[i + w + 1] |= ERR_ADJ_TOPLEFT;
      }
      if (y + 1 < h && x > 0 && grid[i + w - 1] === TENT) {
        cells[i] |= ERR_ADJ_BOTLEFT;
        cells[i + w - 1] |= ERR_ADJ_TOPRIGHT;
      }
    }
  }

  for (let x = 0; x < w; x++) {
    let tents = 0;
    let maybe = 0;
    for (let y = 0; y < h; y++) {
      const v = grid[y * w + x];
      if (v === TENT) tents++;
      else if (v === BLANK) maybe++;
    }
    lines[x] = tents > numbers[x] || tents + maybe < numbers[x] ? 1 : 0;
  }
  for (let y = 0; y < h; y++) {
    let tents = 0;
    let maybe = 0;
    for (let x = 0; x < w; x++) {
      const v = grid[y * w + x];
      if (v === TENT) tents++;
      else if (v === BLANK) maybe++;
    }
    lines[w + y] = tents > numbers[w + y] || tents + maybe < numbers[w + y] ? 1 : 0;
  }

  // Two passes: first tents only, then blanks counted as potential tents.
  for (let pass = 0; pass < 2; pass++) {
    const isTent = (v: number) => v === TENT || (pass === 1 && v === BLANK);
    const dsf = new DSF(n);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (x + 1 < w) {
          const a = grid[i];
          const b = grid[i + 1];
          if ((a === TREE && isTent(b)) || (isTent(a) && b === TREE)) dsf.merge(i, i + 1);
        }
        if (y + 1 < h) {
          const a = grid[i];
          const b = grid[i + w];
          if ((a === TREE && isTent(b)) || (isTent(a) && b === TREE)) dsf.merge(i, i + w);
        }
      }
    }
    const balance = new Int32Array(n);
    for (let i = 0; i < n; i++) {
      if (grid[i] === TREE) balance[dsf.find(i)]++;
      else if (isTent(grid[i])) balance[dsf.find(i)]--;
    }
    for (let i = 0; i < n; i++) {
      const b = balance[dsf.find(i)];
      if (pass === 0 && grid[i] === TENT && b < 0) cells[i] |= ERR_OVERCOMMITTED;
      if (pass === 1 && grid[i] === TREE && b > 0) cells[i] |= ERR_OVERCOMMITTED;
    }
  }

  return { cells, lines };
}
