import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { NONTENT, TENT } from './board';
import type { TentsState, TentsUI } from './index';

/** Mirrors `geometry()` in index.ts without importing it (that would be a cycle). */
const border = (t: number) => Math.round(t * 0.3);
const gutter = (t: number) => Math.round(t * 0.9);

const at = (state: TentsState, x: number, y: number) => state.grid[y * state.w + x];

/** The count printed at the right-hand end of row `y`. */
function rowCount(state: TentsState, y: number, t: number): TutorialRect {
  const b = border(t);
  return { x: b + state.w * t, y: b + y * t, w: gutter(t), h: t };
}

/** The count printed under column `x`. */
function colCount(state: TentsState, x: number, t: number): TutorialRect {
  const b = border(t);
  return { x: b + x * t, y: b + state.h * t, w: t, h: gutter(t) };
}

/** The grid together with the count gutters along its right and bottom edges. */
function boardRect(state: TentsState, t: number): TutorialRect {
  const b = border(t);
  const g = gutter(t);
  return { x: b, y: b, w: state.w * t + g, h: state.h * t + g };
}

/**
 * A 4×4 Easy puzzle with three trees and three tents. Two lines want no tents at all,
 * which gives the grass marks something to do, and each tent is then forced in turn.
 */
export const tutorial: Tutorial<TentsState, TentsUI> = {
  steps: [
    {
      gameId: '4x4:di__,1,1,0,1,1,0,1,1',
      text: 'Pitch one tent beside every tree — up, down, left or right of it, never diagonally. No two tents may touch, and the numbers count the tents in each row and column.',
      highlight: ({ state, tileSize }) => boardRect(state, tileSize),
    },
    {
      text: 'The **0** at the end of the second row means that row gets no tents. **Right-click** the square next to the tree to mark it as grass.',
      highlight: ({ state, tileSize }) => [
        cellRect(1, 1, tileSize, border(tileSize)),
        rowCount(state, 1, tileSize),
      ],
      pointer: ({ tileSize }) => ({
        ...cellCentre(1, 1, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => at(state, 1, 1) === NONTENT,
    },
    {
      text: 'The third column is empty too. **Right-drag** from its top square down to the third row to grass all three in one go.',
      highlight: ({ state, tileSize }) => [
        cellRect(2, 0, tileSize, border(tileSize), 1, 3),
        colCount(state, 2, tileSize),
      ],
      pointer: ({ tileSize }) => ({
        ...cellCentre(2, 0, tileSize, border(tileSize)),
        to: cellCentre(2, 2, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) =>
        at(state, 2, 0) === NONTENT && at(state, 2, 1) === NONTENT && at(state, 2, 2) === NONTENT,
    },
    {
      text: 'The bottom-right tree sits in the corner with another tree beside it, so its only free neighbour is above. **Left-click** that square to pitch a tent.',
      highlight: ({ tileSize }) => [
        cellRect(3, 2, tileSize, border(tileSize)),
        cellRect(3, 3, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(3, 2, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 3, 2) === TENT,
    },
    {
      text: 'That tent fills the third row, so the tree on the left edge cannot camp below it either. **Left-click** the top-left square.',
      highlight: ({ state, tileSize }) => [
        cellRect(0, 0, tileSize, border(tileSize), 1, 2),
        rowCount(state, 2, tileSize),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 0, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 0, 0) === TENT,
    },
    {
      text: 'One tree still has no tent, and only the square to its left is free. **Left-click** it to finish the campsite.',
      highlight: ({ tileSize }) => [
        cellRect(1, 3, tileSize, border(tileSize)),
        cellRect(2, 3, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(1, 3, tileSize, border(tileSize)),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! Clicking a tent or a grass mark again clears it, the arrow keys with Enter and Space do the same job, and **Undo** steps back.',
      textTouch: 'Solved! Tapping a tent or a grass mark again clears it, and **Undo** steps back.',
      target: '[data-cmd="undo"]',
    },
  ],
};
