/**
 * Player analytics, sent to Google Analytics 4 through its Measurement Protocol.
 *
 * The one rule this module lives by: **analytics must never be able to hurt the game.**
 * Every export is synchronous, returns nothing the caller has to handle, never throws and
 * never waits on the network. If it is not configured, not allowed, blocked by the
 * browser, offline, or GA answers with an error, the only difference anywhere in the game
 * is that fewer events arrive. There is no script tag, no cookie and no `gtag`: events are
 * queued in memory and posted as a batch with `navigator.sendBeacon` (falling back to a
 * fire-and-forget `fetch`), whose answer is never read.
 *
 * Turned on only when all of these hold (see {@link analyticsConfig}):
 * - the build was given `VITE_GA_MEASUREMENT_ID` and `VITE_GA_API_SECRET`;
 * - the page is not being driven by automation (`navigator.webdriver` — the e2e suite and
 *   the store-art scripts), and not on localhost, unless `?analytics=1|debug` says so;
 * - the player has not switched it off ({@link setAnalyticsOptOut}).
 *
 * `?analytics=debug` also logs every batch to the console and sends it to GA's validation
 * endpoint instead, whose answer is printed — the way to check a new event by hand.
 *
 * What is collected is gameplay, never identity: a random per-player id kept in the game's
 * own storage (so on CrazyGames it travels with the player's progress), the session, the
 * language, a coarse device class, and what they play. The event catalogue is documented in
 * `docs/ANALYTICS.md`; the per-puzzle events are produced by `./puzzle.ts`.
 */
import { ensureReady, onAdOutcome, type AdOutcome } from '../crazygames';
import { getLocale, onLocaleChange } from '../i18n';
import { onStorageUpgrade, readItem, storageTier, writeItem } from '../storage';
import { getProgress, onProgressChange, type ProgressData } from '../ui/progress';

export type ParamValue = string | number | boolean | null | undefined;
export type Params = Record<string, ParamValue>;

/** GA4's own limits for the Measurement Protocol; anything beyond them is dropped by GA. */
const MAX_EVENTS_PER_REQUEST = 25;
const MAX_PARAMS_PER_EVENT = 25;
const MAX_VALUE_LENGTH = 100;
const NAME_RE = /^[a-zA-Z][a-zA-Z0-9_]{0,39}$/;

/** Send a batch this long after its first event, or sooner if it fills up. */
const FLUSH_DELAY_MS = 5000;
const FLUSH_AT = 20;
/** A queue that cannot drain (offline, blocked) must not grow without bound. */
const MAX_QUEUE = 200;
/** A runaway loop must not be able to cost anything: this many events per page, then quiet. */
const MAX_EVENTS_PER_PAGE = 1500;
const MAX_ERRORS_PER_PAGE = 5;
/** GA's own definition: a gap this long starts a new session. */
const SESSION_GAP_MS = 30 * 60 * 1000;

const CLIENT_KEY = 'puzzlebox:cid';
const FIRST_SEEN_KEY = 'puzzlebox:firstSeen';
const OPT_OUT_KEY = 'puzzlebox:analytics';

export interface AnalyticsConfig {
  measurementId: string;
  apiSecret: string;
  debug: boolean;
}

interface QueuedEvent {
  name: string;
  params: Record<string, string | number>;
}

type Transport = (url: string, body: string, debug: boolean) => void;

let config: AnalyticsConfig | null = null;
let started = false;
let queue: QueuedEvent[] = [];
let flushTimer: ReturnType<typeof setTimeout> | undefined;
let sentThisPage = 0;
let errorsThisPage = 0;
let clientId = '';
let sessionId = 0;
let platform: 'crazygames' | 'web' = 'web';
/** Visible time not yet attributed to an event; GA needs it to count a user as active. */
let engagedMs = 0;
let visibleSince: number | null = null;
let hiddenAt: number | null = null;
/** Visible time since the page loaded, for durations that should not count a hidden tab. */
let activeTotalMs = 0;
let transport: Transport = defaultTransport;
/** The player's choice, read once from storage (and again when the platform's arrives). */
let optedOut: boolean | null = null;
const userProps: Record<string, string | number> = {};

function now(): number {
  return typeof performance !== 'undefined' ? performance.now() : Date.now();
}

function safe<T>(fn: () => T, fallback: T): T {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

/** What the build and the page say about whether, and where, to send events. */
export function analyticsConfig(
  env: Record<string, unknown> = import.meta.env ?? {},
  loc: { hostname: string; search: string } | null = typeof location !== 'undefined'
    ? location
    : null,
  nav: { webdriver?: boolean } | null = typeof navigator !== 'undefined' ? navigator : null,
): AnalyticsConfig | null {
  const measurementId = String(env.VITE_GA_MEASUREMENT_ID ?? '').trim();
  const apiSecret = String(env.VITE_GA_API_SECRET ?? '').trim();
  if (!measurementId || !apiSecret) return null;
  const flag = safe(() => new URLSearchParams(loc?.search ?? '').get('analytics'), null);
  if (flag === '0') return null;
  const forced = flag === '1' || flag === 'debug';
  if (!forced) {
    if (nav?.webdriver) return null;
    const host = loc?.hostname ?? '';
    if (host === 'localhost' || host === '127.0.0.1' || host === '' || host.endsWith('.local'))
      return null;
  }
  return { measurementId, apiSecret, debug: flag === 'debug' };
}

/** Whether the player has turned analytics off. */
export function analyticsOptedOut(): boolean {
  optedOut ??= safe(() => readItem(OPT_OUT_KEY) === '0', false);
  return optedOut;
}

/** Let the player turn analytics off (or back on). Takes effect at once, and is remembered. */
export function setAnalyticsOptOut(out: boolean): void {
  safe(() => {
    if (out) {
      // The last event this player sends is that they left; nothing after it.
      track('analytics_opt_out');
      flush();
    }
    optedOut = out;
    writeItem(OPT_OUT_KEY, out ? '0' : '1');
    if (!out) track('analytics_opt_in');
  }, undefined);
}

/**
 * True when this build and page would send events at all — whether or not the player has
 * opted out. Settings shows its privacy note (and the switch) only then.
 */
export function analyticsConfigured(): boolean {
  return started && config !== null;
}

/** True when events are actually being sent. */
export function analyticsEnabled(): boolean {
  return started && config !== null && !analyticsOptedOut();
}

function randomId(): string {
  const n = safe(
    () => {
      const a = new Uint32Array(1);
      crypto.getRandomValues(a);
      return a[0];
    },
    Math.floor(Math.random() * 0xffffffff),
  );
  // GA's own client id shape: a random number, a dot, the first-seen time in seconds.
  return `${n}.${Math.floor(Date.now() / 1000)}`;
}

function loadClientId(): string {
  const stored = safe(() => readItem(CLIENT_KEY), null);
  if (stored && /^\d+\.\d+$/.test(stored)) return stored;
  const id = randomId();
  safe(() => writeItem(CLIENT_KEY, id), undefined);
  return id;
}

function deviceClass(): string {
  return safe(() => {
    const coarse = matchMedia('(pointer: coarse)').matches;
    const short = Math.min(screen.width, screen.height);
    if (!coarse) return 'desktop';
    return short < 600 ? 'phone' : 'tablet';
  }, 'unknown');
}

function inputKind(): string {
  return safe(() => (matchMedia('(pointer: coarse)').matches ? 'touch' : 'mouse'), 'unknown');
}

/** Where the game is embedded, from the referrer — the portal's host, never a full URL. */
function embedHost(): string {
  return safe(() => {
    if (window.top === window) return 'top';
    return document.referrer ? new URL(document.referrer).hostname : 'unknown';
  }, 'unknown');
}

function markVisible(visible: boolean): void {
  const t = now();
  if (visible) {
    if (visibleSince === null) visibleSince = t;
    return;
  }
  if (visibleSince !== null) {
    engagedMs += t - visibleSince;
    activeTotalMs += t - visibleSince;
    visibleSince = null;
  }
}

/** Milliseconds this page has been visible — a clock that stops while the tab is hidden. */
export function activeMs(): number {
  return activeTotalMs + (visibleSince !== null ? now() - visibleSince : 0);
}

function takeEngagement(): number {
  if (visibleSince !== null) {
    const t = now();
    engagedMs += t - visibleSince;
    activeTotalMs += t - visibleSince;
    visibleSince = t;
  }
  const ms = Math.round(engagedMs);
  engagedMs = 0;
  return ms;
}

function clean(params: Params | undefined): Record<string, string | number> {
  const out: Record<string, string | number> = {};
  if (!params) return out;
  let n = 0;
  for (const [k, v] of Object.entries(params)) {
    if (n >= MAX_PARAMS_PER_EVENT - 3) break; // leave room for session and engagement
    if (!NAME_RE.test(k) || v === null || v === undefined) continue;
    if (typeof v === 'number') {
      if (!Number.isFinite(v)) continue;
      out[k] = Math.round(v * 1000) / 1000;
    } else if (typeof v === 'boolean') out[k] = v ? 1 : 0;
    else out[k] = String(v).slice(0, MAX_VALUE_LENGTH);
    n++;
  }
  return out;
}

/**
 * Record an event. Cheap, synchronous, never throws; a no-op when analytics is off. Names
 * are GA event names (letters, digits, underscores, 40 characters); a bad one is dropped.
 */
export function track(name: string, params?: Params): void {
  try {
    if (!started || !config || analyticsOptedOut()) return;
    if (!NAME_RE.test(name) || sentThisPage >= MAX_EVENTS_PER_PAGE) return;
    sentThisPage++;
    const p = clean(params);
    p.session_id = sessionId;
    // GA ignores an event with no engagement for "active user" counts; 1ms is its own floor.
    p.engagement_time_msec = Math.max(1, takeEngagement());
    if (config.debug) p.debug_mode = 1;
    queue.push({ name, params: p });
    if (queue.length > MAX_QUEUE) queue.splice(0, queue.length - MAX_QUEUE);
    if (queue.length >= FLUSH_AT) flush();
    else if (flushTimer === undefined) flushTimer = setTimeout(flush, FLUSH_DELAY_MS);
  } catch {
    /* never let a measurement reach the game */
  }
}

/** Set a user-scoped property sent with every later batch (language, device, …). */
export function setUserProperty(name: string, value: string | number): void {
  safe(() => {
    if (NAME_RE.test(name))
      userProps[name] = typeof value === 'string' ? value.slice(0, 36) : value;
  }, undefined);
}

/** Send whatever is queued, now. Used on the way out of the page; safe to call any time. */
export function flush(): void {
  try {
    if (flushTimer !== undefined) clearTimeout(flushTimer);
    flushTimer = undefined;
    if (!config || queue.length === 0) return;
    const cfg = config;
    const batch = queue;
    queue = [];
    const user_properties: Record<string, { value: string | number }> = {};
    for (const [k, v] of Object.entries(userProps)) user_properties[k] = { value: v };
    const path = cfg.debug ? 'debug/mp/collect' : 'mp/collect';
    const url =
      `https://www.google-analytics.com/${path}` +
      `?measurement_id=${encodeURIComponent(cfg.measurementId)}` +
      `&api_secret=${encodeURIComponent(cfg.apiSecret)}`;
    for (let i = 0; i < batch.length; i += MAX_EVENTS_PER_REQUEST) {
      const body = JSON.stringify({
        client_id: clientId,
        user_properties,
        events: batch.slice(i, i + MAX_EVENTS_PER_REQUEST),
      });
      if (cfg.debug) console.info('[analytics]', JSON.parse(body));
      transport(url, body, cfg.debug);
    }
  } catch {
    /* dropped: see the module comment */
  }
}

function defaultTransport(url: string, body: string, debug: boolean): void {
  if (debug) {
    // The validation endpoint answers with what is wrong; worth reading, but only here.
    void fetch(url, { method: 'POST', body, credentials: 'omit' })
      .then((r) => r.json())
      .then((j) => console.info('[analytics] validation', j))
      .catch(() => undefined);
    return;
  }
  // `sendBeacon` survives the page being closed, and a string body goes as text/plain,
  // which needs no CORS preflight. Either path is fire-and-forget: GA's answer is not read.
  try {
    if (navigator.sendBeacon?.(url, body)) return;
  } catch {
    /* fall through */
  }
  try {
    void fetch(url, {
      method: 'POST',
      body,
      keepalive: true,
      mode: 'no-cors',
      credentials: 'omit',
    }).catch(() => undefined);
  } catch {
    /* dropped */
  }
}

function pageName(): string {
  return safe(() => {
    const raw = location.hash.replace(/^#\/?/, '').split('?')[0];
    const slug = raw.split('/')[0];
    return slug || 'menu';
  }, 'menu');
}

function trackPage(): void {
  const page = pageName();
  track('page_view', {
    page_title: page,
    page_location: safe(
      () => `${location.origin}${location.pathname}#/${page === 'menu' ? '' : page}`,
      page,
    ),
  });
}

function trackAd(o: AdOutcome): void {
  track('ad_result', {
    ad_type: o.type,
    outcome: o.outcome,
    wait_ms: o.waitMs,
    watch_ms: o.watchMs,
  });
}

function onVisibility(): void {
  const visible = document.visibilityState === 'visible';
  if (!visible) {
    markVisible(false);
    hiddenAt = Date.now();
    track('app_pause');
    flush();
    return;
  }
  // Coming back after GA's session gap is a new session, as GA itself would count it.
  if (hiddenAt !== null && Date.now() - hiddenAt > SESSION_GAP_MS) {
    sessionId = Math.floor(Date.now() / 1000);
    markVisible(true);
    track('app_open', { resumed: 1 });
  } else markVisible(true);
  hiddenAt = null;
}

/**
 * Progression, read off the progress record rather than hooked into the menu: an unlock
 * is a new game in the list *paid for* with a credit (a merge from the platform's store
 * adds games too, and is not an event); a reset is the list getting shorter.
 */
function watchProgress(): void {
  let prev: ProgressData = getProgress();
  const describe = (p: ProgressData) => {
    setUserProperty('games_unlocked', p.unlockAll ? 38 : p.unlocked.length);
    setUserProperty(
      'puzzles_solved',
      Object.values(p.solved).reduce((a, b) => a + b, 0),
    );
    setUserProperty('unlock_all', p.unlockAll ? 1 : 0);
  };
  describe(prev);
  onProgressChange((p) =>
    safe(() => {
      const added = p.unlocked.filter((g) => !prev.unlocked.includes(g));
      if (p.unlocked.length < prev.unlocked.length) track('progress_reset');
      else if (added.length === 1 && p.credits === prev.credits - 1)
        track('game_unlock', {
          game: added[0],
          credits_left: p.credits,
          unlocked: p.unlocked.length,
        });
      if (p.unlockAll !== prev.unlockAll) track('unlock_all', { on: p.unlockAll });
      prev = p;
      describe(p);
    }, undefined),
  );
}

function installErrorReporting(): void {
  const report = (message: string, source: string) => {
    if (errorsThisPage >= MAX_ERRORS_PER_PAGE) return;
    errorsThisPage++;
    track('js_error', { message, source, page: pageName() });
  };
  window.addEventListener('error', (e) =>
    safe(
      () =>
        report(
          String(e.message || 'error'),
          `${String(e.filename || '')
            .split('/')
            .pop()}:${e.lineno ?? 0}`,
        ),
      undefined,
    ),
  );
  window.addEventListener('unhandledrejection', (e) =>
    safe(() => report(String((e.reason as Error)?.message ?? e.reason), 'promise'), undefined),
  );
}

/**
 * Start analytics for this page. Call once, early in boot; `loadMs` is how long the boot
 * took. Does nothing at all when analytics is not configured or not allowed here.
 */
export function initAnalytics(opts: { loadMs?: number } = {}): void {
  try {
    if (started) return;
    config = analyticsConfig();
    if (!config) return;
    started = true;
    clientId = loadClientId();
    sessionId = Math.floor(Date.now() / 1000);
    markVisible(safe(() => document.visibilityState !== 'hidden', true));

    const firstSeen = Number(safe(() => readItem(FIRST_SEEN_KEY), null)) || 0;
    const today = Math.floor(Date.now() / 86_400_000);
    if (!firstSeen) safe(() => writeItem(FIRST_SEEN_KEY, String(today)), undefined);

    setUserProperty('lang', getLocale());
    setUserProperty('device', deviceClass());
    setUserProperty('input', inputKind());
    setUserProperty('platform', platform);
    setUserProperty('app_version', String(import.meta.env?.VITE_APP_VERSION ?? 'dev'));

    if (!firstSeen) track('new_player');
    track('app_open', {
      load_ms: opts.loadMs,
      host: embedHost(),
      returning: firstSeen ? 1 : 0,
      days_since_first: firstSeen ? today - firstSeen : 0,
      storage: storageTier(),
      screen_w: safe(() => window.innerWidth, 0),
      screen_h: safe(() => window.innerHeight, 0),
    });
    trackPage();

    window.addEventListener('hashchange', () => safe(trackPage, undefined));
    document.addEventListener('visibilitychange', () => safe(onVisibility, undefined));
    // The last chance to send anything; `sendBeacon` is what makes it survive the unload.
    window.addEventListener('pagehide', () => safe(flush, undefined));
    onLocaleChange(() => {
      const lang = getLocale();
      track('language_change', { to: lang, from: userProps.lang });
      setUserProperty('lang', lang);
    });
    onAdOutcome(trackAd);
    watchProgress();
    installErrorReporting();

    // The platform's storage answers after boot. If it already knew this player, keep its
    // id from now on, so one person is one player across devices and browsers.
    onStorageUpgrade(() => {
      const stored = safe(() => readItem(CLIENT_KEY), null);
      if (stored && /^\d+\.\d+$/.test(stored) && stored !== clientId) {
        flush();
        clientId = stored;
      } else safe(() => writeItem(CLIENT_KEY, clientId), undefined);
      setUserProperty('storage', storageTier());
      optedOut = null;
    });
    void ensureReady().then((ok) => {
      platform = ok ? 'crazygames' : 'web';
      setUserProperty('platform', platform);
    });
  } catch {
    /* analytics stays off */
  }
}

/** Test hooks. */
export function _resetAnalyticsForTests(t?: Transport): void {
  if (flushTimer !== undefined) clearTimeout(flushTimer);
  flushTimer = undefined;
  config = null;
  started = false;
  queue = [];
  sentThisPage = errorsThisPage = 0;
  engagedMs = activeTotalMs = 0;
  visibleSince = hiddenAt = null;
  for (const k of Object.keys(userProps)) delete userProps[k];
  optedOut = null;
  transport = t ?? defaultTransport;
}

export function _startForTests(cfg: AnalyticsConfig, t: Transport): void {
  _resetAnalyticsForTests(t);
  config = cfg;
  started = true;
  clientId = '1.1';
  sessionId = 1;
  markVisible(true);
}
