/**
 * Map puzzle generation.
 *
 * The map is grown from `n` random seed squares: at every step a square that borders a
 * region is chosen with a weight that favours extensions that shorten the region's
 * perimeter (so regions stay chunky), and an extension is refused when it would make a
 * region wrap around and stop being simply connected. The finished map is four-coloured
 * by a randomised backtracking search, then colours are removed one region at a time
 * while the solver at the requested difficulty can still finish the puzzle. At least one
 * region of each colour always stays given so there is always somewhere to drag from.
 * Finally the puzzle must defeat the next easier solver, or a new map is grown.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { buildGraph, encodeDesc, FOUR } from './board';
import type { MapGraph } from './board';
import { SOLVE_UNIQUE, solveMap } from './solver';

export interface MapParams {
  w: number;
  h: number;
  /** Number of regions. */
  n: number;
  diff: number;
}

/** Weights for extending a region into a square, by effect on its perimeter. */
const WEIGHT_INCREASED = 2;
const WEIGHT_UNCHANGED = 3;
const WEIGHT_DECREASED = 4;

/** Maps tried before the difficulty requirement is relaxed one step. */
const MAX_ATTEMPTS = 400;
/**
 * Work, counted as regions squared per rejected map (each map costs about one solver run
 * per region, and a run grows with the region count), after which the difficulty
 * requirement is relaxed one step anyway. Presets never get near it — 400 maps of 75
 * regions is a quarter of it — but a 40×40 custom map with a region per square costs
 * about 0.2 s a map, and trying 50 or 400 of those froze the page for 10–20 seconds.
 */
const WORK_PER_LEVEL = 8_000_000;
/** Fresh starts `fourColour` may make; a run almost never needs a second one. */
const MAX_COLOUR_RUNS = 1000;

/** Fenwick tree of the extension weights, for weighted random choice of a square. */
class Fenwick {
  private readonly tree: Int32Array;
  total = 0;
  constructor(readonly size: number) {
    this.tree = new Int32Array(size + 1);
  }
  add(i: number, delta: number): void {
    this.total += delta;
    for (let j = i + 1; j <= this.size; j += j & -j) this.tree[j] += delta;
  }
  /** Sum of the weights of elements 0..i-1. */
  prefix(i: number): number {
    let s = 0;
    for (let j = i; j > 0; j -= j & -j) s += this.tree[j];
    return s;
  }
  /** The element whose cumulative range contains `k` (0 ≤ k < total). */
  find(k: number): number {
    let pos = 0;
    let bit = 1;
    while (bit * 2 <= this.size) bit *= 2;
    for (; bit > 0; bit >>= 1) {
      const next = pos + bit;
      if (next <= this.size && this.tree[next] <= k) {
        pos = next;
        k -= this.tree[next];
      }
    }
    return pos;
  }
}

/**
 * Which regions may grow into empty square (x, y)? With `index` < 0 return the total
 * weight of all options; otherwise return the option that the weighted index selects.
 * A region qualifies if it touches the square orthogonally and appears in exactly one
 * run around the square's eight neighbours (otherwise it would wrap around).
 */
function extendOptions(
  w: number,
  h: number,
  map: Int32Array,
  x: number,
  y: number,
  index: number,
): number {
  if (map[y * w + x] >= 0) return 0;
  // Neighbours clockwise-ish: 0 left, 1 below-left, 2 below, 3 below-right, 4 right,
  // 5 above-right, 6 above, 7 above-left. Even slots are the orthogonal ones.
  const col = new Array<number>(8);
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      if (dx === 0 && dy === 0) continue;
      const slot = dy < 0 ? 6 - dx : dy > 0 ? 2 + dx : 2 * (1 + dx);
      const nx = x + dx;
      const ny = y + dy;
      col[slot] = nx >= 0 && nx < w && ny >= 0 && ny < h ? map[ny * w + nx] : -1;
    }
  }
  const cands: number[] = [];
  for (let i = 0; i < 8; i += 2) if (col[i] >= 0 && !cands.includes(col[i])) cands.push(col[i]);
  cands.sort((a, b) => a - b);
  let total = 0;
  for (const c of cands) {
    let neighbours = 0;
    for (let i = 0; i < 8; i += 2) if (col[i] === c) neighbours++;
    let runs = 0;
    for (let i = 0; i < 8; i++) if (col[i] === c && col[(i + 1) & 7] !== c) runs++;
    if (runs !== 1) continue;
    const weight =
      neighbours === 1 ? WEIGHT_INCREASED : neighbours === 2 ? WEIGHT_UNCHANGED : WEIGHT_DECREASED;
    total += weight;
    if (index >= 0) {
      if (index < weight) return c;
      index -= weight;
    }
  }
  return total;
}

/** Grow `n` regions over a w×h grid. Regions are numbered by first appearance. */
export function genMap(w: number, h: number, n: number, rng: Random): Int32Array {
  const wh = w * h;
  const map = new Int32Array(wh).fill(-1);
  const pool: number[] = [];
  for (let i = 0; i < wh; i++) pool.push(i);
  let k = wh;
  for (let i = 0; i < n; i++) {
    const j = rng.upto(k);
    map[pool[j]] = i;
    pool[j] = pool[--k];
  }

  const weight = new Int32Array(wh);
  const fen = new Fenwick(wh);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = extendOptions(w, h, map, x, y, -1);
      weight[y * w + x] = v;
      fen.add(y * w + x, v);
    }
  }
  while (fen.total > 0) {
    let pick = rng.upto(fen.total);
    const sq = fen.find(pick);
    pick -= fen.prefix(sq);
    const x = sq % w;
    const y = (sq - x) / w;
    map[sq] = extendOptions(w, h, map, x, y, pick);
    for (let yy = Math.max(0, y - 1); yy < Math.min(h, y + 2); yy++) {
      for (let xx = Math.max(0, x - 1); xx < Math.min(w, x + 2); xx++) {
        const i = yy * w + xx;
        const v = extendOptions(w, h, map, xx, yy, -1);
        fen.add(i, v - weight[i]);
        weight[i] = v;
      }
    }
  }
  // Planarity guarantees every square gets filled; be safe anyway.
  for (let i = 0; i < wh; i++) {
    if (map[i] >= 0) continue;
    const x = i % w;
    const nb = [x > 0 ? i - 1 : -1, x + 1 < w ? i + 1 : -1, i - w, i + w];
    for (const j of nb) if (j >= 0 && j < wh && map[j] >= 0) map[i] = map[j];
  }

  const label = new Int32Array(n).fill(-1);
  let next = 0;
  for (let i = 0; i < wh; i++) {
    if (label[map[i]] < 0) label[map[i]] = next++;
    map[i] = label[map[i]];
  }
  return map;
}

/**
 * A random proper four-colouring: repeatedly colour a random vertex among those with
 * the fewest colours left, backtracking when stuck (which the Four Colour Theorem says
 * never happens at the top level).
 *
 * A good run needs about one step per region, but now and then an early choice leaves a
 * corner that plain backtracking takes exponentially long to undo — on big custom maps
 * (40×40 with a few hundred regions) that was one deal in six, and the page froze for
 * minutes. So each run gets a step budget, and a run that exceeds it starts over from
 * scratch with fresh random choices.
 */
export function fourColour(g: MapGraph, rng: Random): Int8Array {
  const n = g.n;
  const budget = Math.max(1000, 20 * n);
  for (let run = 0; run < MAX_COLOUR_RUNS; run++) {
    const colouring = colourRun(g, rng, budget);
    if (colouring) return colouring;
  }
  throw new Error(tx`Could not four-colour the map`);
}

/** One attempt at `fourColour`, or null once it has taken more than `budget` steps. */
function colourRun(g: MapGraph, rng: Random, budget: number): Int8Array | null {
  const n = g.n;
  const colouring = new Int8Array(n).fill(-1);
  // Per vertex: how many neighbours have each colour, then how many colours are free.
  const scratch = new Int32Array(n * 5);
  for (let i = 0; i < n; i++) scratch[i * 5 + FOUR] = FOUR;
  let steps = 0;

  // true: coloured; false: dead end, back up; null: over budget, give up on this run.
  const recurse = (): boolean | null => {
    if (++steps > budget) return null;
    let fewest = FOUR + 1;
    let count = 0;
    for (let i = 0; i < n; i++) {
      if (colouring[i] >= 0) continue;
      const f = scratch[i * 5 + FOUR];
      if (f < fewest) {
        fewest = f;
        count = 0;
      }
      if (f === fewest) count++;
    }
    if (count === 0) return true;
    let pick = rng.upto(count);
    let v = 0;
    for (; v < n; v++) {
      if (colouring[v] < 0 && scratch[v * 5 + FOUR] === fewest && pick-- === 0) break;
    }
    const colours: number[] = [];
    for (let c = 0; c < FOUR; c++) if (scratch[v * 5 + c] === 0) colours.push(c);
    rng.shuffle(colours);
    for (const c of colours) {
      colouring[v] = c;
      for (const k of g.adj[v]) {
        if (scratch[k * 5 + c] === 0) scratch[k * 5 + FOUR]--;
        scratch[k * 5 + c]++;
      }
      const r = recurse();
      if (r !== false) return r;
      for (const k of g.adj[v]) {
        scratch[k * 5 + c]--;
        if (scratch[k * 5 + c] === 0) scratch[k * 5 + FOUR]++;
      }
      colouring[v] = -1;
    }
    return false;
  };
  return recurse() ? colouring : null;
}

/**
 * Generate a description and, as `aux`, the solution colours as one digit per region.
 * `stats.maps`, when given, counts the maps drawn on the way — what the tests bound, since
 * a count of rejected maps is the work done whatever the machine's speed.
 */
export function generateMap(
  p: MapParams,
  rng: Random,
  stats?: { maps: number },
): { desc: string; aux: string } {
  const { w, h, n } = p;
  const wh = w * h;
  let minDiff = p.diff;
  let tries = 50;
  let attempts = 0;
  let work = 0;
  for (;;) {
    if (stats) stats.maps++;
    const region = genMap(w, h, n, rng);
    const g = buildGraph(region, w, h, n);
    const colouring = fourColour(g, rng);
    const solution = Array.from(colouring).join('');

    const freq = [0, 0, 0, 0];
    const order: number[] = [];
    for (let i = 0; i < n; i++) {
      freq[colouring[i]]++;
      order.push(i);
    }
    rng.shuffle(order);
    const scratch = new Int8Array(n);
    for (const j of order) {
      if (freq[colouring[j]] === 1) continue;
      scratch.set(colouring);
      scratch[j] = -1;
      if (solveMap(g, scratch, p.diff) === SOLVE_UNIQUE) {
        freq[colouring[j]]--;
        colouring[j] = -1;
      }
    }

    // Too easy (or already solved)? Try another map. Degenerate parameter choices may
    // never reach the requested difficulty, so eventually settle for less.
    scratch.set(colouring);
    if (solveMap(g, scratch, minDiff - 1) === SOLVE_UNIQUE) {
      work += n * n;
      if (minDiff > 0 && (n < 9 || n > (2 * wh) / 3)) {
        if (tries-- <= 0 || work > WORK_PER_LEVEL) minDiff = 0;
      } else if (minDiff > 0 && (++attempts >= MAX_ATTEMPTS || work > WORK_PER_LEVEL)) {
        minDiff--;
        attempts = 0;
        work = 0;
      }
      continue;
    }
    return { desc: encodeDesc(w, h, region, colouring), aux: solution };
  }
}
