import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { anyThrees } from './board';
import type { UnrulyParams, UnrulyState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** Rows of squares of side `s` from (x, y); `B` is black, anything else white. */
function squares(c: C, x: number, y: number, s: number, rows: string[]): string {
  // A grey board behind, and each square inset a little so neighbours stay apart.
  const w = rows[0].length * s;
  const h = rows.length * s;
  let out = shape(`M${x - 3} ${y - 3} h${w + 6} v${h + 6} h${-w - 6} Z`, c.lowlight, c.ink, 4);
  const g = 2.5;
  rows.forEach((row, j) => {
    for (let i = 0; i < row.length; i++)
      out += `<rect x="${x + i * s + g / 2}" y="${y + j * s + g / 2}" width="${s - g}" height="${s - g}" rx="1.5" fill="${row[i] === 'B' ? c.ink : c.white}"/>`;
  });
  return out;
}

/**
 * Whether no square was changed again after the player had moved on from it. Clicking
 * one square round to the colour wanted is one go.
 */
function neverRevisited<S>(history: readonly S[], cells: (s: S) => ArrayLike<number>): boolean {
  const settled = new Set<number>();
  let current = -1;
  for (let k = 1; k < history.length; k++) {
    const a = cells(history[k - 1]);
    const b = cells(history[k]);
    const changed: number[] = [];
    for (let i = 0; i < b.length; i++) if (a[i] !== b[i]) changed.push(i);
    const only = changed.length === 1 ? changed[0] : -1;
    if (current >= 0 && current !== only && a[current]) settled.add(current);
    for (const i of changed) if (settled.has(i)) return false;
    if (only < 0) for (const i of changed) if (b[i]) settled.add(i);
    current = only;
  }
  return true;
}

export const achievements = defineAchievements<UnrulyParams, UnrulyState>([
  {
    id: 'no-threes',
    name: 'Never Three',
    description: 'Solve a 10×10 or larger Unruly without ever making three in a row.',
    tier: 'silver',
    hue: 'pink',
    art: (c) =>
      squares(c, 23, 20, 18, ['BBB']) +
      line('M18 29 H82', c.red, 7) +
      squares(c, 23, 54, 18, ['BBW']),
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 100 && ctx.history.every((s) => !anyThrees(s.grid, s.w, s.h)),
  },
  {
    id: 'first-time',
    name: 'Black and White',
    description: 'Solve a 14×14 Unruly without going back to change a square.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) => squares(c, 22, 22, 14, ['BBWW', 'WWBB', 'BWBW', 'WBWB']),
    test: (ctx) => ctx.params.w * ctx.params.h >= 196 && neverRevisited(ctx.history, (s) => s.grid),
  },
]);
