import { PALETTE, hexToRgb, mix } from './palette';

/** A palette token (e.g. `'ink'`) or any CSS colour string. */
export type Colour = string;

export type HAlign = 'left' | 'center' | 'right';
export type VAlign = 'top' | 'middle' | 'bottom' | 'baseline';

export interface StrokeOpts {
  /** Line width in CSS pixels. Defaults to `Drawing.lineWidth`. */
  width?: number;
  /** Wobble multiplier; 0 draws perfectly straight. Defaults to `Drawing.roughness`. */
  rough?: number;
  /** Extra hash input so moving shapes keep a stable wobble. */
  seed?: number;
  dash?: number[];
  alpha?: number;
  cap?: CanvasLineCap;
}

export interface TextOpts {
  size?: number;
  colour?: Colour;
  align?: HAlign;
  valign?: VAlign;
  bold?: boolean;
  /** Shrink the text to fit this width. */
  maxWidth?: number;
  alpha?: number;
}

const FONT_STACK = '"Patrick Hand", "Segoe Print", "Bradley Hand", "Comic Sans MS", cursive';

/** Deterministic hash of a handful of numbers to [0, 1). */
export function hashNums(...vals: number[]): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < vals.length; i++) {
    const x = Math.round(vals[i] * 2) | 0;
    h ^= x;
    h = Math.imul(h, 16777619) >>> 0;
    h ^= h >>> 13;
  }
  h = Math.imul(h ^ (h >>> 16), 0x45d9f3b) >>> 0;
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function jitter(amp: number, ...seed: number[]): number {
  return (hashNums(...seed) - 0.5) * 2 * amp;
}

/**
 * Canvas drawing API with a consistent hand-drawn look.
 *
 * All coordinates are CSS pixels; the canvas backing store is scaled for the device
 * pixel ratio automatically. Strokes are perturbed by a hash of their coordinates so
 * that identical shapes redraw identically (no shimmer between frames) while still
 * looking sketched.
 */
export class Drawing {
  readonly canvas: HTMLCanvasElement;
  readonly ctx: CanvasRenderingContext2D;
  width = 0;
  height = 0;
  /** Global wobble amount. 1 = default sketchiness, 0 = clean vector lines. */
  roughness = 1;
  /** Default stroke width. */
  lineWidth = 1.6;
  /** Called when a game sets status bar text. */
  onStatus: ((text: string) => void) | null = null;
  private palette: Record<string, string> = { ...PALETTE };
  private dpr = 1;
  private clipDepth = 0;

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('2D canvas context unavailable');
    this.ctx = ctx;
  }

  /**
   * How many device pixels the backing store may hold. A phone at DPR 3, zoomed into a
   * 30×30 board so its squares are big enough to tap, would otherwise ask for a 5000×5000
   * bitmap — 100MB, on exactly the low-end device that needed the zoom. Past this budget
   * the board keeps its CSS size and gives up sharpness instead, which is invisible on a
   * board several times the size of the screen. Nothing that fits a screen comes near it.
   */
  static MAX_BACKING_PIXELS = 8e6;

  /** Resize to CSS pixel dimensions. */
  resize(w: number, h: number): void {
    const want = typeof window !== 'undefined' ? Math.max(1, window.devicePixelRatio || 1) : 1;
    const area = Math.max(1, w * h);
    const dpr = Math.max(1, Math.min(want, Math.sqrt(Drawing.MAX_BACKING_PIXELS / area)));
    this.dpr = dpr;
    this.width = w;
    this.height = h;
    this.canvas.width = Math.max(1, Math.round(w * dpr));
    this.canvas.height = Math.max(1, Math.round(h * dpr));
    this.canvas.style.width = `${w}px`;
    this.canvas.style.height = `${h}px`;
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  setPalette(p: Partial<Record<string, string>>): void {
    Object.assign(this.palette, p);
  }

  /** Resolve a palette token or CSS colour to a CSS colour. */
  colour(c: Colour): string {
    return this.palette[c] ?? c;
  }

  /** A colour with alpha applied (palette tokens or hex colours only). */
  withAlpha(c: Colour, alpha: number): string {
    const css = this.colour(c);
    if (css.startsWith('#')) {
      const [r, g, b] = hexToRgb(css);
      return `rgba(${r},${g},${b},${alpha})`;
    }
    return css;
  }

  /** Blend two colours (palette tokens or hex). */
  mix(a: Colour, b: Colour, t: number): string {
    return mix(this.colour(a), this.colour(b), t);
  }

  begin(): void {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    while (this.clipDepth > 0) this.unclip();
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.clearRect(0, 0, this.width, this.height);
  }

  end(): void {
    while (this.clipDepth > 0) this.unclip();
  }

  /** Fill the whole canvas. */
  clear(colour: Colour = 'paper'): void {
    this.ctx.fillStyle = this.colour(colour);
    this.ctx.fillRect(0, 0, this.width, this.height);
  }

  statusBar(text: string): void {
    this.onStatus?.(text);
  }

  clip(x: number, y: number, w: number, h: number): void {
    this.ctx.save();
    this.ctx.beginPath();
    this.ctx.rect(x, y, w, h);
    this.ctx.clip();
    this.clipDepth++;
  }

  unclip(): void {
    if (this.clipDepth > 0) {
      this.ctx.restore();
      this.clipDepth--;
    }
  }

  // ---------------------------------------------------------------- primitives

  private applyStroke(colour: Colour, opts?: StrokeOpts): void {
    const ctx = this.ctx;
    ctx.strokeStyle = this.colour(colour);
    ctx.lineWidth = opts?.width ?? this.lineWidth;
    ctx.lineCap = opts?.cap ?? 'round';
    ctx.setLineDash(opts?.dash ?? []);
    ctx.globalAlpha = opts?.alpha ?? 1;
  }

  private resetAlpha(): void {
    this.ctx.globalAlpha = 1;
    this.ctx.setLineDash([]);
  }

  /** Append a sketchy line segment to the current path (moveTo is done by caller). */
  private sketchSegment(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    rough: number,
    seed: number,
  ): void {
    const ctx = this.ctx;
    const dx = x2 - x1;
    const dy = y2 - y1;
    const len = Math.hypot(dx, dy);
    if (rough <= 0 || len < 6) {
      ctx.lineTo(x2, y2);
      return;
    }
    const amp = rough * Math.min(1.7, 0.35 + len / 110);
    const nx = -dy / len;
    const ny = dx / len;
    if (len < 90) {
      const t = 0.35 + hashNums(seed, x1, y1, x2, y2, 1) * 0.3;
      const off = jitter(amp, seed, x1, y1, x2, y2, 2);
      const cx = x1 + dx * t + nx * off;
      const cy = y1 + dy * t + ny * off;
      ctx.quadraticCurveTo(cx, cy, x2, y2);
    } else {
      const o1 = jitter(amp, seed, x1, y1, x2, y2, 3);
      const o2 = jitter(amp, seed, x1, y1, x2, y2, 4);
      ctx.bezierCurveTo(
        x1 + dx * 0.3 + nx * o1,
        y1 + dy * 0.3 + ny * o1,
        x1 + dx * 0.7 + nx * o2,
        y1 + dy * 0.7 + ny * o2,
        x2,
        y2,
      );
    }
  }

  private endJitter(rough: number, ...seed: number[]): number {
    return rough <= 0 ? 0 : jitter(rough * 0.55, ...seed);
  }

  /** Build a sketchy path through the given points; closes it if `close`. */
  private sketchPath(points: number[], close: boolean, rough: number, seed: number): void {
    const ctx = this.ctx;
    const n = points.length / 2;
    if (n === 0) return;
    const px: number[] = [];
    const py: number[] = [];
    for (let i = 0; i < n; i++) {
      const x = points[2 * i];
      const y = points[2 * i + 1];
      px.push(x + this.endJitter(rough, seed, x, y, 11));
      py.push(y + this.endJitter(rough, seed, x, y, 12));
    }
    ctx.moveTo(px[0], py[0]);
    for (let i = 1; i < n; i++)
      this.sketchSegment(px[i - 1], py[i - 1], px[i], py[i], rough, seed + i);
    if (close && n > 2) {
      this.sketchSegment(px[n - 1], py[n - 1], px[0], py[0], rough, seed + n);
      ctx.closePath();
    }
  }

  line(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    colour: Colour,
    width?: number,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    const rough = opts.rough ?? this.roughness;
    const seed = opts.seed ?? 0;
    this.applyStroke(colour, { ...opts, width: width ?? opts.width });
    ctx.beginPath();
    const ax = x1 + this.endJitter(rough, seed, x1, y1, x2, y2, 21);
    const ay = y1 + this.endJitter(rough, seed, x1, y1, x2, y2, 22);
    const bx = x2 + this.endJitter(rough, seed, x1, y1, x2, y2, 23);
    const by = y2 + this.endJitter(rough, seed, x1, y1, x2, y2, 24);
    ctx.moveTo(ax, ay);
    this.sketchSegment(ax, ay, bx, by, rough, seed);
    ctx.stroke();
    this.resetAlpha();
  }

  /** Open polyline through `points` = [x0, y0, x1, y1, ...]. */
  polyline(points: number[], colour: Colour, width?: number, opts: StrokeOpts = {}): void {
    if (points.length < 4) return;
    const rough = opts.rough ?? this.roughness;
    this.applyStroke(colour, { ...opts, width: width ?? opts.width });
    this.ctx.beginPath();
    this.sketchPath(points, false, rough, opts.seed ?? 0);
    this.ctx.stroke();
    this.resetAlpha();
  }

  /** Filled and/or outlined polygon. `points` = [x0, y0, x1, y1, ...]. */
  polygon(
    points: number[],
    fill?: Colour | null,
    stroke?: Colour | null,
    opts: StrokeOpts = {},
  ): void {
    if (points.length < 6) return;
    const ctx = this.ctx;
    const rough = opts.rough ?? this.roughness;
    ctx.beginPath();
    this.sketchPath(points, true, rough, opts.seed ?? 0);
    if (fill) {
      ctx.globalAlpha = opts.alpha ?? 1;
      ctx.fillStyle = this.colour(fill);
      ctx.fill();
    }
    if (stroke) {
      this.applyStroke(stroke, opts);
      ctx.stroke();
    }
    this.resetAlpha();
  }

  rect(
    x: number,
    y: number,
    w: number,
    h: number,
    fill?: Colour | null,
    stroke?: Colour | null,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    if (fill) {
      ctx.globalAlpha = opts.alpha ?? 1;
      ctx.fillStyle = this.colour(fill);
      ctx.fillRect(x, y, w, h);
      ctx.globalAlpha = 1;
    }
    if (stroke) this.rectOutline(x, y, w, h, stroke, opts);
  }

  /** Sketched rectangle outline with slight pen overshoot at the corners. */
  rectOutline(
    x: number,
    y: number,
    w: number,
    h: number,
    stroke: Colour,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    const rough = opts.rough ?? this.roughness;
    const seed = opts.seed ?? 0;
    this.applyStroke(stroke, opts);
    if (rough <= 0) {
      ctx.strokeRect(x, y, w, h);
      this.resetAlpha();
      return;
    }
    const over = Math.min(1.5, rough * 0.9);
    const corners = [
      [x, y],
      [x + w, y],
      [x + w, y + h],
      [x, y + h],
    ];
    ctx.beginPath();
    for (let i = 0; i < 4; i++) {
      const [ax, ay] = corners[i];
      const [bx, by] = corners[(i + 1) % 4];
      const dx = Math.sign(bx - ax);
      const dy = Math.sign(by - ay);
      const o1 = hashNums(seed, ax, ay, bx, by, 31) * over;
      const o2 = hashNums(seed, ax, ay, bx, by, 32) * over;
      const sx = ax - dx * o1 + this.endJitter(rough, seed, ax, ay, i, 33);
      const sy = ay - dy * o1 + this.endJitter(rough, seed, ax, ay, i, 34);
      const ex = bx + dx * o2 + this.endJitter(rough, seed, bx, by, i, 35);
      const ey = by + dy * o2 + this.endJitter(rough, seed, bx, by, i, 36);
      ctx.moveTo(sx, sy);
      this.sketchSegment(sx, sy, ex, ey, rough, seed + i);
    }
    ctx.stroke();
    this.resetAlpha();
  }

  roundRect(
    x: number,
    y: number,
    w: number,
    h: number,
    r: number,
    fill?: Colour | null,
    stroke?: Colour | null,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    const rough = opts.rough ?? this.roughness;
    const seed = opts.seed ?? 0;
    const rr = Math.min(r, w / 2, h / 2);
    const j = (k: number) => this.endJitter(rough * 0.8, seed, x, y, w, h, k);
    ctx.beginPath();
    ctx.moveTo(x + rr, y + j(1));
    this.sketchSegment(x + rr, y + j(1), x + w - rr, y + j(2), rough, seed + 1);
    ctx.quadraticCurveTo(x + w, y, x + w + j(3), y + rr);
    this.sketchSegment(x + w + j(3), y + rr, x + w + j(4), y + h - rr, rough, seed + 2);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h + j(5));
    this.sketchSegment(x + w - rr, y + h + j(5), x + rr, y + h + j(6), rough, seed + 3);
    ctx.quadraticCurveTo(x, y + h, x + j(7), y + h - rr);
    this.sketchSegment(x + j(7), y + h - rr, x + j(8), y + rr, rough, seed + 4);
    ctx.quadraticCurveTo(x, y, x + rr, y + j(1));
    ctx.closePath();
    if (fill) {
      ctx.globalAlpha = opts.alpha ?? 1;
      ctx.fillStyle = this.colour(fill);
      ctx.fill();
    }
    if (stroke) {
      this.applyStroke(stroke, opts);
      ctx.stroke();
    }
    this.resetAlpha();
  }

  circle(
    cx: number,
    cy: number,
    r: number,
    fill?: Colour | null,
    stroke?: Colour | null,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    const rough = opts.rough ?? this.roughness;
    const seed = opts.seed ?? 0;
    ctx.beginPath();
    if (rough <= 0 || r < 3) {
      ctx.arc(cx, cy, Math.max(0.1, r), 0, Math.PI * 2);
    } else {
      // Four Bézier arcs with jittered anchor radii for a hand-drawn ellipse.
      const k = 0.5523;
      const amp = Math.max(0.35, r * 0.03) * rough;
      const rot = hashNums(seed, cx, cy, r, 41) * Math.PI * 2;
      const anchors: [number, number][] = [];
      for (let i = 0; i < 4; i++) {
        const a = rot + (i * Math.PI) / 2;
        const rr = r + jitter(amp, seed, cx, cy, r, 42 + i);
        anchors.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr]);
      }
      ctx.moveTo(anchors[0][0], anchors[0][1]);
      for (let i = 0; i < 4; i++) {
        const a0 = rot + (i * Math.PI) / 2;
        const a1 = a0 + Math.PI / 2;
        const [x0, y0] = anchors[i];
        const [x1, y1] = anchors[(i + 1) % 4];
        const r0 = Math.hypot(x0 - cx, y0 - cy);
        const r1 = Math.hypot(x1 - cx, y1 - cy);
        ctx.bezierCurveTo(
          x0 - Math.sin(a0) * r0 * k,
          y0 + Math.cos(a0) * r0 * k,
          x1 + Math.sin(a1) * r1 * k,
          y1 - Math.cos(a1) * r1 * k,
          x1,
          y1,
        );
      }
      ctx.closePath();
    }
    if (fill) {
      ctx.globalAlpha = opts.alpha ?? 1;
      ctx.fillStyle = this.colour(fill);
      ctx.fill();
    }
    if (stroke) {
      this.applyStroke(stroke, opts);
      ctx.stroke();
    }
    this.resetAlpha();
  }

  /** Small solid dot. */
  dot(cx: number, cy: number, r: number, colour: Colour, opts: StrokeOpts = {}): void {
    this.circle(cx, cy, r, colour, null, opts);
  }

  /** A hand-drawn X centred on (cx, cy) with half-size `size`. */
  cross(
    cx: number,
    cy: number,
    size: number,
    colour: Colour,
    width?: number,
    opts: StrokeOpts = {},
  ): void {
    this.line(cx - size, cy - size, cx + size, cy + size, colour, width, {
      ...opts,
      seed: (opts.seed ?? 0) + 1,
    });
    this.line(cx - size, cy + size, cx + size, cy - size, colour, width, {
      ...opts,
      seed: (opts.seed ?? 0) + 2,
    });
  }

  /** A tick/check mark inside a box of half-size `size`. */
  tick(
    cx: number,
    cy: number,
    size: number,
    colour: Colour,
    width?: number,
    opts: StrokeOpts = {},
  ): void {
    this.polyline(
      [cx - size, cy, cx - size * 0.3, cy + size * 0.7, cx + size, cy - size * 0.8],
      colour,
      width,
      opts,
    );
  }

  /** Line with an arrow head at (x2, y2). */
  arrow(
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    colour: Colour,
    width?: number,
    head = 6,
    opts: StrokeOpts = {},
  ): void {
    this.line(x1, y1, x2, y2, colour, width, opts);
    const a = Math.atan2(y2 - y1, x2 - x1);
    const s = Math.PI / 6;
    this.polyline(
      [
        x2 - head * Math.cos(a - s),
        y2 - head * Math.sin(a - s),
        x2,
        y2,
        x2 - head * Math.cos(a + s),
        y2 - head * Math.sin(a + s),
      ],
      colour,
      width,
      { ...opts, seed: (opts.seed ?? 0) + 7 },
    );
  }

  /** Diagonal pencil hatching inside a rectangle. */
  hatch(
    x: number,
    y: number,
    w: number,
    h: number,
    colour: Colour,
    spacing = 6,
    angle = Math.PI / 4,
    width = 1,
    opts: StrokeOpts = {},
  ): void {
    const ctx = this.ctx;
    this.clip(x, y, w, h);
    this.applyStroke(colour, { ...opts, width });
    const rough = opts.rough ?? this.roughness;
    const seed = opts.seed ?? 0;
    const diag = Math.hypot(w, h);
    const cx = x + w / 2;
    const cy = y + h / 2;
    const ux = Math.cos(angle);
    const uy = Math.sin(angle);
    const nx = -uy;
    const ny = ux;
    ctx.beginPath();
    const count = Math.ceil(diag / spacing);
    for (let i = -count; i <= count; i++) {
      const off = i * spacing + jitter(rough * 0.6, seed, x, y, i, 51);
      const px = cx + nx * off;
      const py = cy + ny * off;
      const ax = px - ux * diag;
      const ay = py - uy * diag;
      const bx = px + ux * diag;
      const by = py + uy * diag;
      ctx.moveTo(ax, ay);
      this.sketchSegment(ax, ay, bx, by, rough * 0.7, seed + i);
    }
    ctx.stroke();
    this.resetAlpha();
    this.unclip();
  }

  /** Standard keyboard-cursor highlight: a sketched rounded box. */
  cursor(
    x: number,
    y: number,
    w: number,
    h: number,
    colour: Colour = 'accent',
    width = 2.2,
    opts: StrokeOpts = {},
  ): void {
    this.roundRect(x, y, w, h, Math.min(6, w / 4, h / 4), null, colour, { ...opts, width });
  }

  /**
   * Highlight the square a hint has just revealed: a wash and a bold ring, drawn over
   * whatever is in the square. Blinked for a moment by the games that offer `hint`
   * (see `hintFlashCell` in `framework/grid`), so the player sees where the help landed.
   */
  hintBox(x: number, y: number, w: number, h: number): void {
    this.rect(x, y, w, h, 'accent', null, { alpha: 0.22 });
    this.cursor(x, y, w, h, 'accent', 3.2);
  }

  /** Draw text. Vertical alignment defaults to `middle`, horizontal to `center`. */
  text(x: number, y: number, str: string, opts: TextOpts = {}): void {
    if (!str) return;
    const ctx = this.ctx;
    let size = opts.size ?? 16;
    ctx.font = this.font(size, opts.bold);
    if (opts.maxWidth) {
      const m = ctx.measureText(str).width;
      if (m > opts.maxWidth) {
        size = Math.max(6, (size * opts.maxWidth) / m);
        ctx.font = this.font(size, opts.bold);
      }
    }
    ctx.fillStyle = this.colour(opts.colour ?? 'ink');
    ctx.textAlign = opts.align ?? 'center';
    const v = opts.valign ?? 'middle';
    ctx.textBaseline = v === 'baseline' ? 'alphabetic' : v;
    ctx.globalAlpha = opts.alpha ?? 1;
    // Nudge slightly: handwriting fonts sit a little high at 'middle'.
    ctx.fillText(str, x, v === 'middle' ? y + size * 0.04 : y);
    ctx.globalAlpha = 1;
  }

  measureText(str: string, size = 16, bold = false): number {
    this.ctx.font = this.font(size, bold);
    return this.ctx.measureText(str).width;
  }

  font(size: number, bold = false): string {
    return `${bold ? 'bold ' : ''}${size}px ${FONT_STACK}`;
  }
}
