/**
 * Filling (Fillomino) solver.
 *
 * The board is a flat array of digits, 0 for an empty square. A *region* is a maximal
 * orthogonally connected group of filled squares carrying the same digit; a region of
 * digit n is *complete* when it has exactly n squares. The solver grows regions with
 * these deductions, all of which are forced (never guesses):
 *
 * - Candidate bitmaps: for each digit n, look at the squares that are empty or already
 *   hold n. An empty square cannot be n if its connected group of such squares holds
 *   fewer than n squares, or if writing n there would join neighbouring n-regions into
 *   one of more than n squares (which also rules out a square next to a complete
 *   n-region, or between two regions whose sizes add up to n or more). A group of
 *   exactly n squares containing an n is that n's whole region. A square with a single
 *   candidate left takes it.
 * - Blocked expansion: an incomplete region with only one square it can grow into
 *   must grow into it.
 * - Critical squares: a region of digit n and size s can only ever reach squares within
 *   n − s steps through compatible squares; if fewer than n squares are within reach it
 *   is impossible, if exactly n are they all belong to it, and if excluding one of them
 *   drops the reachable count below n that square belongs to it.
 *
 * `solveDeductive` uses only these deductions and reports success when the whole board
 * follows from the clues (which also proves the solution unique). `solveFilling` adds
 * backtracking as a fallback, for user-entered puzzles that need guessing.
 */

export const EMPTY = 0;

/** The largest digit a puzzle of this size may use (the original's rule). */
export function maxDigit(w: number, h: number): number {
  return Math.min(Math.max(w, h, 3), 9);
}

const DX = [-1, 1, 0, 0];
const DY = [0, 0, -1, 1];

export type SolveOutcome = 'solved' | 'stuck' | 'contradiction';

/** Union–find over the squares of the board, with set sizes. */
class Regions {
  readonly parent: Int32Array;
  readonly size: Int32Array;

  constructor(n: number) {
    this.parent = new Int32Array(n);
    this.size = new Int32Array(n);
    this.reset();
  }

  reset(): void {
    for (let i = 0; i < this.parent.length; i++) this.parent[i] = i;
    this.size.fill(1);
  }

  copyFrom(o: Regions): void {
    this.parent.set(o.parent);
    this.size.set(o.size);
  }

  find(i: number): number {
    const p = this.parent;
    while (p[i] !== i) {
      p[i] = p[p[i]];
      i = p[i];
    }
    return i;
  }

  /** Merge the sets of `a` and `b`; returns the new root. */
  merge(a: number, b: number): number {
    a = this.find(a);
    b = this.find(b);
    if (a === b) return a;
    if (this.size[a] < this.size[b]) {
      const t = a;
      a = b;
      b = t;
    }
    this.parent[b] = a;
    this.size[a] += this.size[b];
    return a;
  }

  sizeOf(i: number): number {
    return this.size[this.find(i)];
  }
}

function popcount(v: number): number {
  let c = 0;
  while (v) {
    v &= v - 1;
    c++;
  }
  return c;
}

class SolverState {
  readonly w: number;
  readonly h: number;
  readonly sz: number;
  readonly maxD: number;
  readonly board: Uint8Array;
  /** Same-digit regions of filled squares. */
  readonly regions: Regions;
  nempty: number;
  /** Bit n set when digit n is still possible in an (empty) square. */
  readonly cand: Uint16Array;

  // Scratch space, never part of the logical state.
  private readonly compat: Regions;
  private readonly hasN: Uint8Array;
  private readonly stamp: Int32Array;
  private stampGen = 0;
  private readonly dist: Int32Array;
  private readonly queue: Int32Array;
  private readonly head: Int32Array;
  private readonly next: Int32Array;
  private readonly reached: Int32Array;
  private nreached = 0;
  private readonly pending: number[] = [];

  constructor(clues: ArrayLike<number>, w: number, h: number) {
    this.w = w;
    this.h = h;
    this.sz = w * h;
    this.maxD = maxDigit(w, h);
    this.board = new Uint8Array(this.sz);
    this.regions = new Regions(this.sz);
    this.cand = new Uint16Array(this.sz);
    this.compat = new Regions(this.sz);
    this.hasN = new Uint8Array(this.sz);
    this.stamp = new Int32Array(this.sz);
    this.dist = new Int32Array(this.sz);
    this.queue = new Int32Array(this.sz);
    this.head = new Int32Array(this.sz);
    this.next = new Int32Array(this.sz);
    this.reached = new Int32Array(this.sz);
    this.nempty = this.sz;
    const all = ((1 << (this.maxD + 1)) - 1) & ~1;
    this.cand.fill(all);
    for (let i = 0; i < this.sz; i++) {
      if (clues[i]) {
        this.board[i] = clues[i];
        this.nempty--;
      }
    }
    for (let i = 0; i < this.sz; i++) {
      const n = this.board[i];
      if (!n) continue;
      const x = i % w;
      if (x + 1 < w && this.board[i + 1] === n) this.regions.merge(i, i + 1);
      if (i + w < this.sz && this.board[i + w] === n) this.regions.merge(i, i + w);
    }
  }

  clone(): SolverState {
    const c = new SolverState(this.board, this.w, this.h);
    c.cand.set(this.cand);
    return c;
  }

  /** Fill an empty square. Returns false when its region becomes too big. */
  set(i: number, n: number): boolean {
    if (this.board[i] !== EMPTY) return this.board[i] === n;
    this.board[i] = n;
    this.nempty--;
    const { w, h, board, regions } = this;
    const x = i % w;
    const y = (i - x) / w;
    let r = i;
    for (let k = 0; k < 4; k++) {
      const nx = x + DX[k];
      const ny = y + DY[k];
      if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
      const j = ny * w + nx;
      if (board[j] === n) r = regions.merge(r, j);
    }
    return regions.size[r] <= n;
  }

  /** Size of the region of n that would form if n were written into empty square i. */
  private expandSize(i: number, n: number): number {
    const { w, h, board, regions } = this;
    const x = i % w;
    const y = (i - x) / w;
    let size = 1;
    let r0 = -1;
    let r1 = -1;
    let r2 = -1;
    for (let k = 0; k < 4; k++) {
      const nx = x + DX[k];
      const ny = y + DY[k];
      if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
      const j = ny * w + nx;
      if (board[j] !== n) continue;
      const r = regions.find(j);
      if (r === r0 || r === r1 || r === r2) continue;
      if (r0 < 0) r0 = r;
      else if (r1 < 0) r1 = r;
      else r2 = r;
      size += regions.size[r];
    }
    return size;
  }

  /** True when every square is filled and every region is exactly as big as its digit. */
  verify(): boolean {
    for (let i = 0; i < this.sz; i++) {
      const n = this.board[i];
      if (!n || this.regions.sizeOf(i) !== n) return false;
    }
    return true;
  }

  /** Apply a batch of (square, digit) deductions. Returns the number of squares filled or -1. */
  private applyPending(): number {
    const p = this.pending;
    let learned = 0;
    for (let k = 0; k < p.length; k += 2) {
      const i = p[k];
      const n = p[k + 1];
      if (this.board[i] === EMPTY) learned++;
      if (!this.set(i, n)) {
        p.length = 0;
        return -1;
      }
    }
    p.length = 0;
    return learned;
  }

  /** Candidate-bitmap deductions. Returns squares filled, or -1 on a contradiction. */
  learnBitmap(): number {
    const { w, sz, board, cand, compat, hasN, pending } = this;
    const all = ((1 << (this.maxD + 1)) - 1) & ~1;
    for (let i = 0; i < sz; i++) if (board[i] === EMPTY) cand[i] = all;

    for (let n = 1; n <= this.maxD; n++) {
      const bit = 1 << n;
      compat.reset();
      for (let i = 0; i < sz; i++) {
        const v = board[i];
        if (v !== EMPTY && v !== n) continue;
        const x = i % w;
        if (x + 1 < w) {
          const v2 = board[i + 1];
          if (v2 === EMPTY || v2 === n) compat.merge(i, i + 1);
        }
        if (i + w < sz) {
          const v2 = board[i + w];
          if (v2 === EMPTY || v2 === n) compat.merge(i, i + w);
        }
      }
      hasN.fill(0);
      for (let i = 0; i < sz; i++) if (board[i] === n) hasN[compat.find(i)] = 1;
      for (let i = 0; i < sz; i++) {
        const v = board[i];
        if (v === n) {
          if (compat.sizeOf(i) < n) return -1;
        } else if (v === EMPTY && cand[i] & bit) {
          const r = compat.find(i);
          const cs = compat.size[r];
          if (cs < n || this.expandSize(i, n) > n) cand[i] &= ~bit;
          else if (cs === n && hasN[r]) pending.push(i, n);
        }
      }
    }
    for (let i = 0; i < sz; i++) {
      if (board[i] !== EMPTY) continue;
      const c = cand[i];
      if (c === 0) return -1;
      if ((c & (c - 1)) === 0) pending.push(i, 31 - Math.clz32(c));
    }
    return this.applyPending();
  }

  /** Link every square into a list per region root. */
  private buildMemberLists(): void {
    const { sz, board, regions, head, next } = this;
    head.fill(-1);
    for (let i = sz - 1; i >= 0; i--) {
      if (board[i] === EMPTY) continue;
      const r = regions.find(i);
      next[i] = head[r];
      head[r] = i;
    }
  }

  /** Incomplete regions with a single square to grow into. */
  learnBlocked(): number {
    const { w, h, sz, board, regions, cand, stamp, head, next } = this;
    this.buildMemberLists();
    let learned = 0;
    for (let r = 0; r < sz; r++) {
      if (head[r] < 0 || regions.parent[r] !== r) continue;
      const n = board[r];
      const s = regions.size[r];
      if (s >= n) continue;
      const bit = 1 << n;
      const gen = ++this.stampGen;
      let count = 0;
      let exp = -1;
      let members = 0;
      for (let j = head[r]; j >= 0 && count < 2; j = next[j]) {
        members++;
        const x = j % w;
        const y = (j - x) / w;
        for (let k = 0; k < 4; k++) {
          const nx = x + DX[k];
          const ny = y + DY[k];
          if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
          const t = ny * w + nx;
          if (board[t] !== EMPTY || stamp[t] === gen) continue;
          stamp[t] = gen;
          if (cand[t] & bit) {
            count++;
            exp = t;
          }
        }
      }
      // A region that grew since the lists were built is handled on the next pass.
      if (count < 2 && members !== s) continue;
      if (count === 0) return -1;
      if (count === 1) {
        if (!this.set(exp, n)) return -1;
        learned++;
      }
    }
    return learned;
  }

  /**
   * Count the squares that region `r` (digit n, radius d) could still reach, not passing
   * through `blocked`. Stops early once `limit` is reached. With `collect`, the empty
   * squares reached are stored in `reached`.
   */
  private reach(r: number, n: number, d: number, blocked: number, limit: number, collect: boolean) {
    const { w, h, board, cand, stamp, dist, queue, head, next } = this;
    const bit = 1 << n;
    const gen = ++this.stampGen;
    let qh = 0;
    let qt = 0;
    let count = 0;
    this.nreached = 0;
    for (let j = head[r]; j >= 0; j = next[j]) {
      stamp[j] = gen;
      dist[j] = 0;
      queue[qt++] = j;
      count++;
    }
    while (qh < qt) {
      const j = queue[qh++];
      const dj = dist[j];
      if (dj >= d) continue;
      const x = j % w;
      const y = (j - x) / w;
      for (let k = 0; k < 4; k++) {
        const nx = x + DX[k];
        const ny = y + DY[k];
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        const t = ny * w + nx;
        if (stamp[t] === gen || t === blocked) continue;
        const v = board[t];
        if (v === n || (v === EMPTY && cand[t] & bit)) {
          stamp[t] = gen;
          dist[t] = dj + 1;
          queue[qt++] = t;
          count++;
          if (collect && v === EMPTY) this.reached[this.nreached++] = t;
          if (count >= limit) return count;
        }
      }
    }
    return count;
  }

  /** Squares an incomplete region cannot do without. */
  learnCritical(): number {
    const { sz, board, regions, head, reached, pending } = this;
    this.buildMemberLists();
    let learned = 0;
    for (let r = 0; r < sz; r++) {
      if (head[r] < 0 || regions.parent[r] !== r) continue;
      const n = board[r];
      const s = regions.size[r];
      if (s >= n) continue;
      const d = n - s;
      const count = this.reach(r, n, d, -1, sz + 1, true);
      if (count < n) return -1;
      const nr = this.nreached;
      if (count === n) {
        for (let k = 0; k < nr; k++) pending.push(reached[k], n);
      } else {
        for (let k = 0; k < nr; k++) {
          const j = reached[k];
          if (this.reach(r, n, d, j, n, false) < n) pending.push(j, n);
        }
      }
      // Apply straight away so later regions see the new squares. Regions merged by a
      // fill are then stale in the member lists and skipped until the next pass.
      const got = this.applyPending();
      if (got < 0) return -1;
      learned += got;
      if (got) this.buildMemberLists();
    }
    return learned;
  }

  /** Run deductions until the board is full, nothing more follows, or a contradiction. */
  run(): SolveOutcome {
    while (this.nempty > 0) {
      let r = this.learnBitmap();
      if (r < 0) return 'contradiction';
      if (r > 0) continue;
      r = this.learnBlocked();
      if (r < 0) return 'contradiction';
      if (r > 0) continue;
      r = this.learnCritical();
      if (r < 0) return 'contradiction';
      if (r > 0) continue;
      return 'stuck';
    }
    return this.verify() ? 'solved' : 'contradiction';
  }

  /** The empty square with the fewest candidates (for guessing). */
  branchSquare(): number {
    let best = -1;
    let bestCount = 99;
    for (let i = 0; i < this.sz; i++) {
      if (this.board[i] !== EMPTY) continue;
      const c = popcount(this.cand[i]);
      if (c < bestCount) {
        bestCount = c;
        best = i;
        if (c <= 2) break;
      }
    }
    return best;
  }
}

/**
 * Solve by deduction only. Returns the full board when every square follows from the
 * clues (so the solution is unique), otherwise null.
 */
export function solveDeductive(clues: ArrayLike<number>, w: number, h: number): Uint8Array | null {
  const st = new SolverState(clues, w, h);
  return st.run() === 'solved' ? st.board : null;
}

export interface SolveResult {
  status: 'unique' | 'ambiguous' | 'impossible' | 'unknown';
  board: Uint8Array | null;
}

/**
 * Full solver: deductions first, then backtracking on the most constrained square.
 * Stops as soon as two solutions are found; `maxNodes` bounds the search so pathological
 * inputs (a big empty grid) fail with 'unknown' instead of hanging.
 */
export function solveFilling(
  clues: ArrayLike<number>,
  w: number,
  h: number,
  maxNodes = 50000,
): SolveResult {
  const solutions: Uint8Array[] = [];
  let nodes = 0;
  let exceeded = false;
  const rec = (st: SolverState): void => {
    const out = st.run();
    if (out === 'contradiction') return;
    if (out === 'solved') {
      solutions.push(st.board.slice());
      return;
    }
    if (++nodes > maxNodes) {
      exceeded = true;
      return;
    }
    const i = st.branchSquare();
    const c = st.cand[i];
    for (let n = 1; n <= st.maxD && solutions.length < 2 && !exceeded; n++) {
      if (!(c & (1 << n))) continue;
      const child = st.clone();
      if (!child.set(i, n)) continue;
      rec(child);
    }
  };
  rec(new SolverState(clues, w, h));
  if (solutions.length >= 2) return { status: 'ambiguous', board: solutions[0] };
  if (solutions.length === 1)
    return { status: exceeded ? 'unknown' : 'unique', board: solutions[0] };
  return { status: exceeded ? 'unknown' : 'impossible', board: null };
}

/** Same-digit regions of a board: root and size per square. Empty squares are singletons. */
export function boardRegions(
  board: ArrayLike<number>,
  w: number,
  h: number,
): { root: Int32Array; size: Int32Array } {
  const sz = w * h;
  const reg = new Regions(sz);
  for (let i = 0; i < sz; i++) {
    const n = board[i];
    if (!n) continue;
    const x = i % w;
    if (x + 1 < w && board[i + 1] === n) reg.merge(i, i + 1);
    if (i + w < sz && board[i + w] === n) reg.merge(i, i + w);
  }
  const root = new Int32Array(sz);
  const size = new Int32Array(sz);
  for (let i = 0; i < sz; i++) {
    root[i] = reg.find(i);
    size[i] = reg.size[root[i]];
  }
  return { root, size };
}

/** True when every square holds a digit equal to the size of its region. */
export function isComplete(board: ArrayLike<number>, w: number, h: number): boolean {
  const { size } = boardRegions(board, w, h);
  for (let i = 0; i < w * h; i++) if (!board[i] || board[i] !== size[i]) return false;
  return true;
}
