/**
 * The translation runtime: `t()` for keyed messages and `tx` for messages keyed by their
 * own English text. Dependency-free; plural categories come from `Intl.PluralRules`, so
 * Arabic, Russian, Polish and Czech get their real CLDR rules rather than an
 * English-shaped one/other guess.
 *
 * See `docs/I18N.md` for the conventions a translator has to follow.
 */

import {
  isPluralForms,
  lookup,
  lookupMessage,
  lookupTouchPhrases,
  type Message,
  type PluralForms,
} from './catalog';
import { DEFAULT_LOCALE, getLocale } from './locale';

export type TParams = Record<string, string | number | undefined>;

/** Order to fall back through when a locale's catalogue omits a plural category. */
const PLURAL_FALLBACK: (keyof PluralForms)[] = ['other', 'many', 'few', 'two', 'one', 'zero'];

const pluralRules = new Map<string, Intl.PluralRules | null>();

function rulesFor(locale: string): Intl.PluralRules | null {
  if (!pluralRules.has(locale)) {
    let r: Intl.PluralRules | null;
    try {
      r = new Intl.PluralRules(locale);
    } catch {
      // An unknown or malformed tag: fall back to the English-shaped one/other rule.
      r = null;
    }
    pluralRules.set(locale, r);
  }
  return pluralRules.get(locale)!;
}

/** The CLDR plural category of `n` in `locale` (`one`, `few`, `other`, …). */
export function pluralCategory(locale: string, n: number): string {
  const r = rulesFor(locale);
  if (r) return r.select(n);
  return n === 1 ? 'one' : 'other';
}

/** Choose the form for `n`, falling back through the categories a locale did supply. */
function selectForm(forms: PluralForms, locale: string, n: number): string {
  const cat = pluralCategory(locale, n) as keyof PluralForms;
  const chosen = forms[cat];
  if (typeof chosen === 'string') return chosen;
  for (const k of PLURAL_FALLBACK) {
    const v = forms[k];
    if (typeof v === 'string') return v;
  }
  return '';
}

const PLACEHOLDER = /\{(\w+)\}/g;

/** Substitute `{name}` holes from `params`; an unknown hole is left in place, visibly. */
export function interpolate(template: string, params?: TParams): string {
  if (!params) return template;
  return template.replace(PLACEHOLDER, (whole, name: string) => {
    const v = params[name];
    return v === undefined ? whole : String(v);
  });
}

/** Render a catalogue entry: pick a plural form if there is one, then interpolate. */
function render(msg: Message, params: TParams | undefined, locale: string): string {
  if (typeof msg === 'string') return interpolate(msg, params);
  const n = Number(params?.n ?? params?.count ?? 0);
  return interpolate(selectForm(msg, locale, Number.isFinite(n) ? n : 0), params);
}

/**
 * Translate `key` in the active locale.
 *
 * ```ts
 * t('ui.toolbar.new')                       // "New"
 * t('games.fifteen.status.moves', { n: 5 }) // "Moves: 5"
 * ```
 *
 * A key whose catalogue entry is an object of plural categories is pluralised on
 * `params.n`. Lookup order is: the active locale, then English, then `fallback`, then the
 * key itself (which shows up loudly in the UI, which is the point).
 */
export function t(key: string, params?: TParams, fallback?: Message): string {
  const locale = getLocale();
  let msg = lookup(locale, key);
  if (msg === undefined && locale !== DEFAULT_LOCALE) msg = lookup(DEFAULT_LOCALE, key);
  if (msg === undefined) msg = fallback;
  if (msg === undefined) return key;
  return render(msg, params, locale);
}

/**
 * A translated string split around live DOM nodes, so a value that is animated in place
 * (the counters in the menu's progress strip) can sit inside a sentence the translator is
 * free to reorder.
 *
 * ```ts
 * el.append(...tParts('ui.menu.stat.credits', { n: creditsNum }));
 * ```
 */
export function tParts(
  key: string,
  nodes: Record<string, Node>,
  params?: TParams,
): (string | Node)[] {
  const rendered = t(key, params);
  const out: (string | Node)[] = [];
  let last = 0;
  for (const m of rendered.matchAll(PLACEHOLDER)) {
    const node = nodes[m[1]];
    if (!node) continue;
    if (m.index > last) out.push(rendered.slice(last, m.index));
    out.push(node);
    last = m.index + m[0].length;
  }
  if (last < rendered.length) out.push(rendered.slice(last));
  return out;
}

/**
 * Translate `key` using only the active locale's own catalogue, with no English fallback.
 * Returns `undefined` when this language has not supplied the key — which is what lets a
 * caller choose a *different* translated string rather than dropping back into English.
 */
export function tOwn(key: string, params?: TParams): string | undefined {
  const locale = getLocale();
  const msg = lookup(locale, key);
  return msg === undefined ? undefined : render(msg, params, locale);
}

/** True when the active locale (or English) actually has this key. */
export function hasKey(key: string): boolean {
  const locale = getLocale();
  return lookup(locale, key) !== undefined || lookup(DEFAULT_LOCALE, key) !== undefined;
}

/**
 * A message keyed by its own English text — the pattern used for the many one-off
 * validation and solver messages inside the games, where inventing a key per sentence
 * would be more noise than help.
 *
 * ```ts
 * return tx`Width and height must be at most ${MAX_SIDE}`;
 * ```
 *
 * The tag rebuilds the pattern `"Width and height must be at most {0}"`, looks it up in
 * the locale's `messages` map and substitutes the values back in. With no translation it
 * returns exactly what the plain template literal would have produced, so English output
 * is unchanged by construction.
 *
 * `tx` cannot pluralise. A message whose English changes shape with a count needs a keyed
 * `t()` entry with plural forms instead.
 */
export function tx(strings: TemplateStringsArray, ...values: unknown[]): string {
  const english = strings.reduce(
    (acc, part, i) => acc + (i > 0 ? String(values[i - 1]) : '') + part,
    '',
  );
  if (values.length === 0) {
    return lookupMessageWithFallback(strings[0]) ?? english;
  }
  const pattern = strings.reduce((acc, part, i) => acc + (i > 0 ? `{${i - 1}}` : '') + part, '');
  const translated = lookupMessageWithFallback(pattern);
  if (translated === undefined) return english;
  const params: TParams = {};
  values.forEach((v, i) => (params[String(i)] = String(v)));
  return interpolate(translated, params);
}

function lookupMessageWithFallback(pattern: string): string | undefined {
  const locale = getLocale();
  if (locale === DEFAULT_LOCALE) return undefined; // English is the pattern itself
  return lookupMessage(locale, pattern);
}

/**
 * The active locale's mouse→touch phrase map for the help/tutorial rewriter, or `null`
 * when it supplies none (in which case the text is left exactly as written — better than
 * applying English rules to another language). See `src/ui/markdown.ts`.
 */
export function touchPhraseMap(): [string, string][] | null {
  return lookupTouchPhrases(getLocale()) ?? null;
}

export { isPluralForms };
export type { Message, PluralForms };
