/**
 * Rectangles generator, following the original's recipe:
 *
 *  1. Tile a (possibly smaller) grid by repeatedly picking an uncovered cell and a
 *     random rectangle that covers it, then patch up any 1×1 leftovers by borrowing
 *     from a neighbour.
 *  2. Stretch the tiling to the requested size by inserting rows and columns
 *     (the "expansion factor"), so large boards can have fewer, bigger rectangles.
 *  3. Hand the tiling to the solver with every cell of each rectangle as a candidate
 *     position for its number; the solver winnows the candidates until the tiling is
 *     the unique solution, and the number goes on one of the survivors.
 */
import type { Random } from '../../framework/rng';
import type { Rect } from './board';
import { encodeDesc, encodeEdges, edgesOfRects } from './board';
import { solveRects } from './solver';
import type { NumberData } from './solver';

/**
 * A tiling as the original stores it: each cell holds the index (y * w + x) of the
 * top-left cell of its rectangle; -1 = not yet covered, -2 = a singleton to fix later.
 */
export interface Tiling {
  w: number;
  h: number;
  cells: Int32Array;
}

/** Thrown when an attempt reaches a layout the fix-up rules cannot handle; try again. */
class RetryError extends Error {}

function tilingRects(t: Tiling): Rect[] {
  const out: Rect[] = [];
  for (let y = 0; y < t.h; y++)
    for (let x = 0; x < t.w; x++)
      if (t.cells[y * t.w + x] === y * t.w + x) out.push(findRect(t, x, y));
  return out;
}

/** The rectangle containing (x, y); a lone uncovered cell counts as 1×1. */
export function findRect(t: Tiling, x: number, y: number): Rect {
  const idx = t.cells[y * t.w + x];
  if (idx < 0) return { x, y, w: 1, h: 1 };
  const x0 = idx % t.w;
  const y0 = Math.floor(idx / t.w);
  let w = 1;
  while (x0 + w < t.w && t.cells[y0 * t.w + x0 + w] === idx) w++;
  let h = 1;
  while (y0 + h < t.h && t.cells[(y0 + h) * t.w + x0] === idx) h++;
  return { x: x0, y: y0, w, h };
}

function placeRect(t: Tiling, r: Rect): void {
  const idx = r.y * t.w + r.x;
  for (let y = r.y; y < r.y + r.h; y++)
    for (let x = r.x; x < r.x + r.w; x++) t.cells[y * t.w + x] = idx;
}

/**
 * Enumerate the rectangles that could be placed over the uncovered cell (sx, sy):
 * with `pick` undefined, return how many there are; otherwise return the `pick`-th.
 * Rectangles are limited to a sixth of the grid area and may not span the full width
 * or height of the grid (unless the grid is tiny), as in the original.
 */
export function enumRects(
  t: Tiling,
  sx: number,
  sy: number,
  scratch: Int32Array,
  pick?: number,
): number | Rect {
  const { w, h, cells } = t;
  let maxArea = Math.floor((w * h) / 6);
  if (maxArea < 2) maxArea = 2;

  // For each column, how far up and down from the start row the free space reaches,
  // never further than the column before it (working outwards from sx).
  const top = scratch.subarray(0, w);
  const bottom = scratch.subarray(w, 2 * w);
  for (const dy of [-1, 1]) {
    const arr = dy === -1 ? top : bottom;
    for (const dx of [-1, 1]) {
      for (let x = sx; x >= 0 && x < w; x += dx) {
        arr[x] = -2 * h * dy;
        for (let y = sy; y >= 0 && y < h; y += dy) {
          if (cells[y * w + x] === -1 && (x === sx || dy * y <= dy * arr[x - dx])) arr[x] = y;
          else break;
        }
      }
    }
  }

  // The largest rectangle that fits, so the loops below can stop early.
  let realMax = 0;
  for (let x = 0; x < w; x++) {
    const rh = bottom[x] - top[x] + 1;
    if (rh <= 0) continue;
    const dx = x > sx ? -1 : 1;
    let x2 = x;
    for (; x2 >= 0 && x2 < w; x2 += dx) if (bottom[x2] < bottom[x] || top[x2] > top[x]) break;
    const rw = Math.abs(x2 - x);
    if (realMax < rw * rh) realMax = rw * rh;
  }
  if (realMax > maxArea) realMax = maxArea;

  let mw = w - 1;
  if (mw < 3) mw++;
  let mh = h - 1;
  if (mh < 3) mh++;

  let index = 0;
  for (let rw = 1; rw <= mw; rw++) {
    for (let rh = 1; rh <= mh; rh++) {
      if (rw * rh > realMax || rw * rh === 1) continue;
      for (let x = Math.max(sx - rw + 1, 0); x <= Math.min(sx, w - rw); x++) {
        for (let y = Math.max(sy - rh + 1, 0); y <= Math.min(sy, h - rh); y++) {
          if (
            top[x] <= y &&
            top[x + rw - 1] <= y &&
            bottom[x] >= y + rh - 1 &&
            bottom[x + rw - 1] >= y + rh - 1
          ) {
            if (pick !== undefined && index === pick) return { x, y, w: rw, h: rh };
            index++;
          }
        }
      }
    }
  }
  if (pick !== undefined) throw new Error('enumRects: pick out of range');
  return index;
}

/** Cover the grid with random rectangles; cells that cannot be covered are left as -2. */
function fillTiling(t: Tiling, rng: Random): void {
  const { w, h, cells } = t;
  const scratch = new Int32Array(2 * w);
  let free = w * h;
  while (free > 0) {
    let which = rng.upto(free);
    let sx = -1;
    let sy = -1;
    outer: for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (cells[y * w + x] === -1 && which-- === 0) {
          sx = x;
          sy = y;
          break outer;
        }
      }
    }
    const count = enumRects(t, sx, sy, scratch) as number;
    if (!count) {
      cells[sy * w + sx] = -2;
      free--;
    } else {
      const r = enumRects(t, sx, sy, scratch, rng.upto(count)) as Rect;
      placeRect(t, r);
      free -= r.w * r.h;
    }
  }
}

/**
 * Absorb every 1×1 leftover into a neighbour. A singleton can extend into a
 * neighbouring rectangle when it sits at one end of the side it touches (shaving a
 * row or column off that rectangle) or when the neighbour is a 2×1 seen end-on. When
 * no direction works the singleton is surrounded by four 2-cell rectangles pinwheel
 * fashion, and the whole 3×3 block becomes one rectangle.
 */
function removeSingletons(t: Tiling, rng: Random): void {
  const { w, h, cells } = t;
  for (let x = 0; x < w; x++) {
    for (let y = 0; y < h; y++) {
      if (cells[y * w + x] >= 0) continue;
      const dirs: number[] = [];
      if (x < w - 1) {
        const r = findRect(t, x + 1, y);
        if ((r.w * r.h > 2 && (r.y === y || r.y + r.h - 1 === y)) || r.h === 1) dirs.push(1);
      }
      if (y > 0) {
        const r = findRect(t, x, y - 1);
        if ((r.w * r.h > 2 && (r.x === x || r.x + r.w - 1 === x)) || r.w === 1) dirs.push(2);
      }
      if (x > 0) {
        const r = findRect(t, x - 1, y);
        if ((r.w * r.h > 2 && (r.y === y || r.y + r.h - 1 === y)) || r.h === 1) dirs.push(4);
      }
      if (y < h - 1) {
        const r = findRect(t, x, y + 1);
        if ((r.w * r.h > 2 && (r.x === x || r.x + r.w - 1 === x)) || r.w === 1) dirs.push(8);
      }
      if (dirs.length === 0) {
        if (x < 1 || y < 1 || x >= w - 1 || y >= h - 1) throw new RetryError();
        placeRect(t, { x: x - 1, y: y - 1, w: 3, h: 3 });
        continue;
      }
      const dir = dirs[rng.upto(dirs.length)];
      let r1: Rect;
      let r2: Rect;
      switch (dir) {
        case 1:
          r1 = findRect(t, x + 1, y);
          r2 = { x, y, w: 1 + r1.w, h: 1 };
          if (r1.y === y) r1.y++;
          r1.h--;
          break;
        case 2:
          r1 = findRect(t, x, y - 1);
          r2 = { x, y: r1.y, w: 1, h: 1 + r1.h };
          if (r1.x === x) r1.x++;
          r1.w--;
          break;
        case 4:
          r1 = findRect(t, x - 1, y);
          r2 = { x: r1.x, y, w: 1 + r1.w, h: 1 };
          if (r1.y === y) r1.y++;
          r1.h--;
          break;
        default:
          r1 = findRect(t, x, y + 1);
          r2 = { x, y, w: 1, h: 1 + r1.h };
          if (r1.x === x) r1.x++;
          r1.w--;
          break;
      }
      if (r1.h > 0 && r1.w > 0) placeRect(t, r1);
      placeRect(t, r2);
    }
  }
}

/**
 * Stretch a tiling to `newH` rows by inserting rows between existing ones. Each edge
 * that ran along a row boundary is moved to a random position among the rows inserted
 * there, so the rectangles on both sides grow by varying amounts. The result is
 * returned transposed (so calling this twice stretches both dimensions).
 */
function expandAndTranspose(t: Tiling, newH: number, rng: Random): Tiling {
  const { w, h, cells } = t;
  const grid2 = new Int32Array(w * newH);
  const expand = new Int32Array(Math.max(0, h - 1));
  for (let y = h; y < newH; y++) expand[rng.upto(h - 1)]++;
  const where = new Int32Array(w);

  let y2 = 0;
  let y2last = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const val = cells[y * w + x];
      const startsHere = Math.floor(val / w) === y;
      const alreadyStarted = y2 > 0 && Math.floor(grid2[(y2 - 1) * w + x] / w) >= y2last;
      grid2[y2 * w + x] =
        startsHere && !alreadyStarted ? y2 * w + (val % w) : grid2[(y2 - 1) * w + x];
    }
    if (++y2 === newH) break;
    y2last = y2;

    let yx = -1;
    for (let x = 0; x < w; x++) {
      if (cells[y * w + x] !== cells[(y + 1) * w + x]) {
        const fresh =
          x === 0 ||
          (cells[y * w + x - 1] !== cells[y * w + x] &&
            cells[(y + 1) * w + x - 1] !== cells[(y + 1) * w + x]);
        if (fresh) yx = rng.upto(expand[y] + 1);
      } else {
        yx = -1;
      }
      where[x] = yx;
    }
    for (let k = 0; k < expand[y]; k++) {
      for (let x = 0; x < w; x++) {
        grid2[y2 * w + x] =
          k === where[x] ? y2 * w + (cells[(y + 1) * w + x] % w) : grid2[(y2 - 1) * w + x];
      }
      y2++;
    }
  }

  const out: Tiling = { w: newH, h: w, cells: new Int32Array(newH * w) };
  for (let x = 0; x < out.w; x++) {
    for (let y = 0; y < out.h; y++) {
      const v = grid2[x * w + y];
      out.cells[y * out.w + x] = (v % w) * out.w + Math.floor(v / w);
    }
  }
  return out;
}

export interface GeneratedPuzzle {
  desc: string;
  aux: string;
  /** Clue numbers per cell. */
  numbers: number[];
  rects: Rect[];
}

/** Build the tiling for one attempt: fill, fix singletons, expand to full size. */
export function generateTiling(w: number, h: number, expandFactor: number, rng: Random): Tiling {
  let w2 = Math.floor(w / (1 + expandFactor));
  if (w2 < 2 && w >= 2) w2 = 2;
  let h2 = Math.floor(h / (1 + expandFactor));
  if (h2 < 2 && h >= 2) h2 = 2;
  // A one-row (or one-column) board cannot shrink at all.
  if (w2 < 1) w2 = 1;
  if (h2 < 1) h2 = 1;
  let t: Tiling = { w: w2, h: h2, cells: new Int32Array(w2 * h2).fill(-1) };
  fillTiling(t, rng);
  removeSingletons(t, rng);
  // Stretch to height h and transpose, then stretch to height w and transpose back.
  t = expandAndTranspose(t, h, rng);
  t = expandAndTranspose(t, w, rng);
  return t;
}

export function generateRect(
  w: number,
  h: number,
  expandFactor: number,
  unique: boolean,
  rng: Random,
): GeneratedPuzzle {
  for (let attempt = 0; ; attempt++) {
    let t: Tiling;
    try {
      t = generateTiling(w, h, expandFactor, rng);
    } catch (e) {
      if (e instanceof RetryError) continue;
      throw e;
    }
    const rects = tilingRects(t);
    // A tiling that is one rectangle covering the whole grid is a puzzle that starts out
    // solved (the frame alone closes it), which a small custom board such as 3×3 or 4×1
    // rolls often. Try again; a board of two or three squares in a line can never be cut
    // any other way (the generator makes no 1×1 rectangles), so give up on those.
    if (rects.length === 1 && attempt < 100) continue;
    const candidates: NumberData[] = rects.map((r) => {
      const points = [];
      for (let y = r.y; y < r.y + r.h; y++)
        for (let x = r.x; x < r.x + r.w; x++) points.push({ x, y });
      return { area: r.w * r.h, points };
    });
    let numbersData = candidates;
    if (unique) {
      const res = solveRects(w, h, candidates, rng);
      if (res.outcome !== 1) continue;
      numbersData = res.numbers;
    }
    const numbers = new Array<number>(w * h).fill(0);
    for (const nd of numbersData) {
      const p = nd.points[rng.upto(nd.points.length)];
      numbers[p.y * w + p.x] = nd.area;
    }
    const { vedge, hedge } = edgesOfRects(w, h, rects);
    return { desc: encodeDesc(numbers), aux: encodeEdges(w, h, vedge, hedge), numbers, rects };
  }
}
