/**
 * Signpost generator: lay a random path that visits every square (each square's arrow
 * points at its successor), then keep just enough of the numbers for the deductive
 * solver to find the path, so the puzzle has exactly one solution.
 */
import type { Random } from '../../framework/rng';
import { Board, DX, DY, encodeDesc, opposite, whichDir } from './board';
import type { Puzzle } from './board';
import { SOLVED, solveBoard } from './solver';

export interface SignpostParams {
  w: number;
  h: number;
  /** Put 1 in the top-left corner and n in the bottom-right. */
  corners: boolean;
}

/** A full solution: every square's arrow and number. */
export interface Solution {
  dirs: number[];
  nums: number[];
}

/** Unnumbered squares in any of the eight directions from `i`, with the direction. */
function reachable(w: number, h: number, nums: number[], i: number): { i: number; d: number }[] {
  const out: { i: number; d: number }[] = [];
  const sx = i % w;
  const sy = Math.floor(i / w);
  for (let d = 0; d < 8; d++) {
    let x = sx + DX[d];
    let y = sy + DY[d];
    while (x >= 0 && y >= 0 && x < w && y < h) {
      const j = y * w + x;
      if (nums[j] === 0) out.push({ i: j, d });
      x += DX[d];
      y += DY[d];
    }
  }
  return out;
}

/**
 * Grow a path from `head` (which becomes 1) and back from `tail` (which becomes n) by
 * random steps until every square is used, then join the two ends. Steps that leave
 * only one way onward are followed immediately. Returns null when the growth gets
 * stuck or the ends cannot see each other.
 */
export function fillPath(
  w: number,
  h: number,
  head: number,
  tail: number,
  rng: Random,
): Solution | null {
  const n = w * h;
  const nums = new Array<number>(n).fill(0);
  const dirs = new Array<number>(n).fill(0);
  nums[head] = 1;
  nums[tail] = n;
  let filled = 2;
  while (filled < n) {
    let adj = reachable(w, h, nums, head);
    do {
      if (adj.length === 0) return null;
      const pick = adj[rng.upto(adj.length)];
      dirs[head] = pick.d;
      nums[pick.i] = nums[head] + 1;
      filled++;
      head = pick.i;
      adj = reachable(w, h, nums, head);
    } while (adj.length === 1 && filled < n);
    if (filled === n) break;
    adj = reachable(w, h, nums, tail);
    do {
      if (adj.length === 0) return null;
      const pick = adj[rng.upto(adj.length)];
      dirs[pick.i] = opposite(pick.d);
      nums[pick.i] = nums[tail] - 1;
      filled++;
      tail = pick.i;
      adj = reachable(w, h, nums, tail);
    } while (adj.length === 1 && filled < n);
  }
  const d = whichDir(head % w, Math.floor(head / w), tail % w, Math.floor(tail / w));
  if (d < 0) return null;
  dirs[head] = d;
  return { dirs, nums };
}

function boardWith(puzzle: Puzzle, keep: Uint8Array): Board {
  return new Board(puzzle, keep);
}

/**
 * Choose which numbers of a solution to show. Starting from 1 and n, numbers are added
 * in random order (skipping squares the solver already worked out) until the solver
 * succeeds, then each added number is dropped again if the solver still succeeds
 * without it. Returns null if even showing everything does not help (it always should).
 */
export function chooseGivens(sol: Solution, w: number, h: number, rng: Random): Uint8Array | null {
  const n = w * h;
  const puzzle: Puzzle = { w, h, n, dirs: sol.dirs, given: sol.nums };
  const keep = new Uint8Array(n);
  keep[sol.nums.indexOf(1)] = 1;
  keep[sol.nums.indexOf(n)] = 1;
  let board = boardWith(puzzle, keep);
  if (solveBoard(board) === SOLVED) return keep;

  const order = rng.shuffle([...Array(n).keys()]);
  let solved = false;
  for (const j of order) {
    if (board.isReal(board.nums[j])) continue; // already deduced
    keep[j] = 1;
    board = boardWith(puzzle, keep);
    if (solveBoard(board) === SOLVED) {
      solved = true;
      break;
    }
  }
  if (!solved) return null;
  for (const j of order) {
    if (!keep[j] || sol.nums[j] === 1 || sol.nums[j] === n) continue;
    keep[j] = 0;
    if (solveBoard(boardWith(puzzle, keep)) !== SOLVED) keep[j] = 1;
  }
  return keep;
}

/** Generate a puzzle description; `aux` is the complete solution in the same format. */
export function generate(p: SignpostParams, rng: Random): { desc: string; aux: string } {
  const { w, h } = p;
  const n = w * h;
  for (;;) {
    let head: number;
    let tail: number;
    if (p.corners) {
      head = 0;
      tail = n - 1;
    } else {
      do {
        head = rng.upto(n);
        tail = rng.upto(n);
      } while (head === tail);
    }
    const sol = fillPath(w, h, head, tail, rng);
    if (!sol) continue;
    const keep = chooseGivens(sol, w, h, rng);
    if (!keep) continue;
    const given = sol.nums.map((v, i) => (keep[i] ? v : 0));
    return { desc: encodeDesc(sol.dirs, given), aux: encodeDesc(sol.dirs, sol.nums) };
  }
}
