/**
 * Puzzle generation for Net.
 *
 * 1. Grow a random spanning tree out of the centre tile, never making a full cross.
 * 2. When a unique solution is wanted, run the solver; wherever it leaves an ambiguous
 *    patch, rewire that patch (add one link across its boundary and cut the loop this
 *    makes somewhere else) and try again. If a round of rewiring fails to reduce the
 *    number of patches, start over with a fresh tree.
 * 3. Rotate every tile at random, re-rolling until the start position is neither
 *    solved-looking nor contains a loop.
 * 4. Finally pick barriers among the edges that carry no wire. Doing this last means
 *    the same seed gives the same grid whatever the barrier rate, and more barriers are
 *    always a superset of fewer.
 */
import type { Random } from '../../framework/rng';
import {
  borderBarriers,
  computeLoops,
  countWires,
  D,
  DIR_BITS,
  L,
  LOCKED,
  neighbourIndex,
  opp,
  R,
  rotate,
  rotF,
  U,
  type Grid,
} from './core';
import { solveNet } from './solver';

export interface GeneratedNet {
  /** The scrambled starting grid. */
  puzzle: number[];
  /** The unscrambled tree the puzzle was made from. */
  solution: number[];
  barriers: number[];
}

/** A set of small integers with O(1) add, remove and uniform random removal. */
class KeySet {
  private list: number[] = [];
  private pos: Int32Array;
  constructor(capacity: number) {
    this.pos = new Int32Array(capacity).fill(-1);
  }
  get size(): number {
    return this.list.length;
  }
  has(key: number): boolean {
    return this.pos[key] >= 0;
  }
  add(key: number): void {
    if (this.pos[key] >= 0) return;
    this.pos[key] = this.list.length;
    this.list.push(key);
  }
  remove(key: number): void {
    const p = this.pos[key];
    if (p < 0) return;
    const last = this.list.pop()!;
    if (p < this.list.length) {
      this.list[p] = last;
      this.pos[last] = p;
    }
    this.pos[key] = -1;
  }
  removeAt(index: number): number {
    const key = this.list[index];
    this.remove(key);
    return key;
  }
}

/**
 * Random spanning tree over the whole grid. A frontier of (tile, direction) pairs
 * leading from reached tiles into unreached ones is kept; one is picked uniformly at
 * random, the link is made, and the frontier is updated. A tile that has just gained
 * its third wire loses its fourth possibility so no crosses appear (this can never
 * strand a tile: an unreachable pocket would have to be fenced in by T-pieces whose
 * wires join up into a loop, and loops are never created).
 */
function spanningTree(g: Grid, rng: Random): number[] {
  const n = g.w * g.h;
  const tiles = new Array<number>(n).fill(0);
  const frontier = new KeySet(n * 4);
  const centre = (g.h >> 1) * g.w + (g.w >> 1);
  for (let k = 0; k < 4; k++) {
    const j = neighbourIndex(g, centre, k);
    if (j >= 0 && j !== centre) frontier.add(centre * 4 + k);
  }
  while (frontier.size > 0) {
    const key = frontier.removeAt(rng.upto(frontier.size));
    const i = key >> 2;
    const k = key & 3;
    const j = neighbourIndex(g, i, k);
    tiles[i] |= DIR_BITS[k];
    tiles[j] |= DIR_BITS[opp(k)];
    if (countWires(tiles[i]) === 3) {
      const missing = DIR_BITS.indexOf(15 ^ (tiles[i] & 15));
      frontier.remove(i * 4 + missing);
    }
    for (let k2 = 0; k2 < 4; k2++) {
      // Other frontier entries aiming at the tile we just reached would make loops.
      const m = neighbourIndex(g, j, k2);
      if (m >= 0) frontier.remove(m * 4 + opp(k2));
    }
    for (let k2 = 0; k2 < 4; k2++) {
      if (k2 === opp(k)) continue;
      const m = neighbourIndex(g, j, k2);
      if (m < 0 || tiles[m] || m === j) continue;
      frontier.add(j * 4 + k2);
    }
  }
  return tiles;
}

interface Edge {
  x: number;
  y: number;
  k: number;
}

/**
 * Rewire the ambiguous patch containing tile (sx, sy), whose neighbour in direction
 * `sk` is already pinned down by the solver. Tiles carrying LOCKED are the pinned ones.
 *
 * Walk round the boundary of the patch, then pick a boundary edge at random where a new
 * wire can be added without making a cross; add it, find the single loop this creates
 * and cut it somewhere else. Finally mark the whole patch LOCKED so it is not touched
 * again this round.
 */
function perturb(g: Grid, tiles: number[], rng: Random, sx: number, sy: number, sk: number) {
  const { w } = g;
  const idx = (x: number, y: number) => y * w + x;
  const step = (x: number, y: number, k: number): { x: number; y: number } | null => {
    const j = neighbourIndex(g, idx(x, y), k);
    return j < 0 ? null : { x: j % w, y: Math.floor(j / w) };
  };
  const pinned = (p: { x: number; y: number } | null) =>
    !p || (tiles[idx(p.x, p.y)] & LOCKED) !== 0;

  // Trace the boundary, keeping the pinned tiles on our facing side.
  const boundary: Edge[] = [];
  let x = sx;
  let y = sy;
  let k = sk;
  do {
    boundary.push({ x, y, k });
    const left = (k + 1) & 3;
    const side = step(x, y, left);
    if (pinned(side)) {
      k = left;
    } else {
      x = side!.x;
      y = side!.y;
      const ahead = step(x, y, k);
      if (!pinned(ahead)) {
        x = ahead!.x;
        y = ahead!.y;
        k = (k + 3) & 3;
      }
    }
  } while (x !== sx || y !== sy || k !== sk);

  // Choose where to add a wire.
  const order = rng.shuffle(boundary.slice());
  let join: Edge | null = null;
  for (const e of order) {
    const to = step(e.x, e.y, e.k);
    if (!to) continue;
    const a = idx(e.x, e.y);
    const b = idx(to.x, to.y);
    if (tiles[a] & DIR_BITS[e.k]) continue;
    if (((tiles[a] | DIR_BITS[e.k]) & 15) === 15) continue;
    if (((tiles[b] | DIR_BITS[opp(e.k)]) & 15) === 15) continue;
    tiles[a] |= DIR_BITS[e.k];
    tiles[b] |= DIR_BITS[opp(e.k)];
    join = e;
    break;
  }
  if (!join) return;

  // Two walkers follow the network from the new wire, one hugging the left wall and one
  // the right, so the loop is found quickly whichever way round it is shorter. Steps that
  // exactly retrace the previous one (dead-end branches) cancel out.
  const walkers = [0, 1].map(() => ({ x: join!.x, y: join!.y, k: join!.k, path: [] as Edge[] }));
  outer: for (;;) {
    for (let wi = 0; wi < 2; wi++) {
      const wk = walkers[wi];
      const to = step(wk.x, wk.y, wk.k)!;
      const last = wk.path[wk.path.length - 1];
      if (last && last.x === to.x && last.y === to.y && last.k === opp(wk.k)) wk.path.pop();
      else wk.path.push({ x: wk.x, y: wk.y, k: wk.k });
      let d = opp(wk.k);
      for (let tries = 0; tries < 4; tries++) {
        d = wi === 0 ? (d + 1) & 3 : (d + 3) & 3;
        if (tiles[idx(to.x, to.y)] & DIR_BITS[d]) break;
      }
      wk.x = to.x;
      wk.y = to.y;
      wk.k = d;
      const first = wk.path[0];
      if (wk.x === first.x && wk.y === first.y && wk.k === first.k) {
        if (wk.path.length > 1) {
          const cut = wk.path[rng.upto(wk.path.length - 1) + 1];
          const far = step(cut.x, cut.y, cut.k)!;
          tiles[idx(cut.x, cut.y)] &= ~DIR_BITS[cut.k];
          tiles[idx(far.x, far.y)] &= ~DIR_BITS[opp(cut.k)];
        }
        break outer;
      }
    }
  }

  // Lock the patch: sort its boundary into columns and fill between each up-facing
  // edge and the down-facing edge below it (runs that wrap round start or end at the
  // grid edge).
  boundary.sort((a, b) => a.x - b.x || a.y - b.y || DIR_BITS[a.k] - DIR_BITS[b.k]);
  let col = -1;
  let fillY = -1;
  for (let i = 0; i <= boundary.length; i++) {
    if (i === boundary.length || boundary[i].x > col) {
      if (col !== -1) {
        for (; fillY < g.h; fillY++) tiles[idx(col, fillY)] |= LOCKED;
      }
      if (i === boundary.length) break;
      col = boundary[i].x;
      fillY = 0;
    }
    const e = boundary[i];
    if (DIR_BITS[e.k] === U) {
      col = e.x;
      fillY = e.y;
    } else if (DIR_BITS[e.k] === D) {
      for (; fillY <= e.y; fillY++) tiles[idx(col, fillY)] |= LOCKED;
      col = fillY = -1;
    }
  }
}

/**
 * Make the tree uniquely solvable by repeated perturbation. Returns false when a round
 * made no headway and the caller should start from a new tree.
 */
function ensureUnique(g: Grid, tiles: number[], rng: Random): boolean {
  const { w, h } = g;
  let previous = -1;
  for (;;) {
    const res = solveNet(g, tiles, null);
    for (let i = 0; i < tiles.length; i++) {
      tiles[i] = (tiles[i] & 15) | (res.candidates[i].length === 1 ? LOCKED : 0);
    }
    if (res.complete) return true;
    let patches = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (x + 1 < w && (tiles[i] ^ tiles[i + 1]) & LOCKED) {
          patches++;
          if (tiles[i] & LOCKED) perturb(g, tiles, rng, x + 1, y, 2);
          else perturb(g, tiles, rng, x, y, 0);
        }
        if (y + 1 < h && (tiles[i] ^ tiles[i + w]) & LOCKED) {
          patches++;
          if (tiles[i] & LOCKED) perturb(g, tiles, rng, x, y + 1, 1);
          else perturb(g, tiles, rng, x, y, 3);
        }
      }
    }
    if (previous !== -1 && previous <= patches) return false;
    previous = patches;
  }
}

/**
 * Rotate every tile at random. The result must contain no loop (fixed by re-rolling
 * just the tiles on loops, or everything if that makes matters worse) and must have at
 * least one visible mismatch between neighbours so it is obviously not solved.
 */
function scramble(g: Grid, solution: number[], rng: Random): number[] {
  const { w, h } = g;
  const n = w * h;
  const border = g.wrapping ? null : borderBarriers(w, h);
  for (;;) {
    const tiles = solution.map((v) => rotate(v, rng.upto(4)));
    let previousLoopTiles = n + 1;
    let ok = true;
    for (;;) {
      const loops = computeLoops(g, tiles, border);
      let loopTiles = 0;
      for (let i = 0; i < n; i++) {
        if (loops[i]) {
          tiles[i] = rotate(tiles[i], rng.upto(4));
          loopTiles++;
        }
      }
      if (loopTiles > previousLoopTiles) {
        ok = false;
        break;
      }
      if (loopTiles === 0) break;
      previousLoopTiles = loopTiles;
    }
    if (!ok) continue;
    let mismatches = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (x + 1 < w && (rotF(tiles[i]) ^ tiles[i + 1]) & L) mismatches++;
        if (y + 1 < h && (rotF(tiles[i]) ^ tiles[i + w]) & U) mismatches++;
      }
    }
    if (mismatches > 0) return tiles;
  }
}

export interface GenerateOptions {
  w: number;
  h: number;
  wrapping: boolean;
  unique: boolean;
  barrierProbability: number;
}

export function generateNet(opts: GenerateOptions, rng: Random): GeneratedNet {
  const g: Grid = { w: opts.w, h: opts.h, wrapping: opts.wrapping };
  const n = g.w * g.h;
  let solution: number[];
  for (;;) {
    solution = spanningTree(g, rng);
    if (!opts.unique || ensureUnique(g, solution, rng)) break;
  }
  for (let i = 0; i < n; i++) solution[i] &= 15;

  const puzzle = scramble(g, solution, rng);

  // Candidate barrier positions: edges without a wire, inside the grid (or anywhere
  // on a wrapping grid).
  const slots = new KeySet(n * 4);
  for (let y = 0; y < g.h; y++) {
    for (let x = 0; x < g.w; x++) {
      const i = y * g.w + x;
      if (!(solution[i] & R) && (g.wrapping || x < g.w - 1)) slots.add(i * 4 + 0);
      if (!(solution[i] & D) && (g.wrapping || y < g.h - 1)) slots.add(i * 4 + 3);
    }
  }
  const barriers = new Array<number>(n).fill(0);
  let wanted = Math.floor(opts.barrierProbability * slots.size);
  while (wanted-- > 0 && slots.size > 0) {
    const key = slots.removeAt(rng.upto(slots.size));
    const i = key >> 2;
    const k = key & 3;
    const j = neighbourIndex(g, i, k);
    barriers[i] |= DIR_BITS[k];
    barriers[j] |= DIR_BITS[opp(k)];
  }
  return { puzzle, solution, barriers };
}
