/**
 * Slant board model shared by the game, the solver and the generator.
 *
 * The grid has `w × h` squares and `(w + 1) × (h + 1)` grid points. Throughout this
 * folder `W = w + 1` and `H = h + 1` are the point-grid dimensions. Clues live on
 * points (`Int8Array` of `W * H`, `NO_CLUE` where blank); the player's diagonals live on
 * squares (`Int8Array` of `w * h`: `FORWARD` for `/`, `BACK` for `\`, `EMPTY`).
 *
 * A `\` in square (x, y) joins points (x, y) and (x+1, y+1); a `/` joins (x+1, y) and
 * (x, y+1).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export const NO_CLUE = -1;
export const EMPTY = 0;
/** A forward slash `/`. */
export const FORWARD = 1;
/** A backslash `\`. */
export const BACK = -1;

// ------------------------------------------------------------- description format

/**
 * Parse a description: digits 0–4 are clues on successive grid points, a lower-case
 * letter is a run of 1–26 blank points. Returns an error message when the text does not
 * describe exactly `(w + 1) × (h + 1)` points.
 */
export function parseDesc(desc: string, w: number, h: number): Int8Array | string {
  const n = (w + 1) * (h + 1);
  const clues = new Int8Array(n).fill(NO_CLUE);
  let i = 0;
  for (const c of desc) {
    if (c >= 'a' && c <= 'z') {
      i += c.charCodeAt(0) - 96;
    } else if (c >= '0' && c <= '4') {
      if (i < n) clues[i] = c.charCodeAt(0) - 48;
      i++;
    } else {
      return tx`Invalid character in game description`;
    }
  }
  if (i < n) return tx`Not enough data to fill grid`;
  if (i > n) return tx`Too much data to fit in grid`;
  return clues;
}

/** Encode a clue array in the description format (runs longer than 26 become `z…`). */
export function encodeDesc(clues: Int8Array): string {
  let out = '';
  let run = 0;
  const flush = () => {
    while (run > 0) {
      const k = Math.min(run, 26);
      out += String.fromCharCode(96 + k);
      run -= k;
    }
  };
  for (let i = 0; i < clues.length; i++) {
    if (clues[i] === NO_CLUE) {
      run++;
    } else {
      flush();
      out += String(clues[i]);
    }
  }
  flush();
  return out;
}

/** Solver hint stored with a generated puzzle: one `\` or `/` per square, row-major. */
export function encodeSolution(soln: Int8Array): string {
  let s = '';
  for (let i = 0; i < soln.length; i++) s += soln[i] === BACK ? '\\' : '/';
  return s;
}

export function decodeSolution(aux: string, n: number): Int8Array | null {
  if (aux.length !== n) return null;
  const soln = new Int8Array(n);
  for (let i = 0; i < n; i++) {
    const c = aux[i];
    if (c === '\\') soln[i] = BACK;
    else if (c === '/') soln[i] = FORWARD;
    else return null;
  }
  return soln;
}

// ------------------------------------------------------------- geometry helpers

/**
 * The squares around point (px, py) together with the slash each would need to touch
 * the point, listed in order around the point: top-left, bottom-left, bottom-right,
 * top-right. Consecutive entries (and, when all four exist, the last and first) are
 * edge-adjacent squares.
 */
export function pointNeighbours(
  w: number,
  h: number,
  px: number,
  py: number,
): { pos: number; slash: number }[] {
  const out: { pos: number; slash: number }[] = [];
  if (px > 0 && py > 0) out.push({ pos: (py - 1) * w + (px - 1), slash: BACK });
  if (px > 0 && py < h) out.push({ pos: py * w + (px - 1), slash: FORWARD });
  if (px < w && py < h) out.push({ pos: py * w + px, slash: BACK });
  if (px < w && py > 0) out.push({ pos: (py - 1) * w + px, slash: FORWARD });
  return out;
}

/** Number of diagonals currently touching point (px, py). */
export function pointDegree(w: number, h: number, soln: Int8Array, px: number, py: number): number {
  let n = 0;
  for (const nb of pointNeighbours(w, h, px, py)) if (soln[nb.pos] === nb.slash) n++;
  return n;
}

/**
 * Number of squares around point (px, py) whose diagonal definitely misses it. Squares
 * that do not exist (beyond the border) count as missing too, so `4 - antiDegree` is the
 * most lines the point could ever have.
 */
export function pointAntiDegree(
  w: number,
  h: number,
  soln: Int8Array,
  px: number,
  py: number,
): number {
  let n = 0;
  const nbs = pointNeighbours(w, h, px, py);
  for (const nb of nbs) if (soln[nb.pos] === -nb.slash) n++;
  return n + (4 - nbs.length);
}

/** Every point's clue for a completely filled grid. */
export function computeClues(w: number, h: number, soln: Int8Array): Int8Array {
  const W = w + 1;
  const clues = new Int8Array(W * (h + 1));
  for (let y = 0; y <= h; y++)
    for (let x = 0; x <= w; x++) clues[y * W + x] = pointDegree(w, h, soln, x, y);
  return clues;
}

// ------------------------------------------------------------- completion check

export interface Check {
  /** 1 for each square whose diagonal is part of a closed loop. */
  loopErr: Uint8Array;
  /** 1 for each clue point that has too many lines, or too few even when full. */
  clueErr: Uint8Array;
  /** Every square filled and nothing wrong. */
  complete: boolean;
}

/**
 * Find loops and violated clues.
 *
 * Loops are found through the regions of the plane: think of a diamond around every
 * orthogonal grid edge. Two diamonds that meet in a square are the same region unless
 * the square's diagonal separates them. If a diagonal ends up between two different
 * regions it must be part of a closed loop (all the outside diamonds are one region, so
 * anything on the border of a second region is enclosed).
 */
export function checkGrid(w: number, h: number, clues: Int8Array, soln: Int8Array): Check {
  const W = w + 1;
  const H = h + 1;
  // Vertical edge (x, y), 0 <= x <= w, 0 <= y < h, is region y*W+x; horizontal edge
  // (x, y), 0 <= x < w, 0 <= y <= h, is region W*h + y*w + x.
  const vert = (x: number, y: number) => y * W + x;
  const horiz = (x: number, y: number) => W * h + y * w + x;
  const dsf = new DSF(W * h + w * H);
  for (let y = 0; y < h; y++) {
    dsf.merge(0, vert(0, y));
    dsf.merge(0, vert(w, y));
  }
  for (let x = 0; x < w; x++) {
    dsf.merge(0, horiz(x, 0));
    dsf.merge(0, horiz(x, h));
  }
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = soln[y * w + x];
      if (s !== BACK) {
        // No `\`: the top edge joins the left one and the bottom joins the right.
        dsf.merge(vert(x, y), horiz(x, y));
        dsf.merge(vert(x + 1, y), horiz(x, y + 1));
      }
      if (s !== FORWARD) {
        // No `/`: the top edge joins the right one and the bottom joins the left.
        dsf.merge(vert(x, y), horiz(x, y + 1));
        dsf.merge(vert(x + 1, y), horiz(x, y));
      }
    }
  }
  const loopErr = new Uint8Array(w * h);
  let err = false;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = soln[y * w + x];
      let bad = false;
      if (s === FORWARD) bad = !dsf.same(vert(x + 1, y), horiz(x, y));
      else if (s === BACK) bad = !dsf.same(vert(x, y), horiz(x, y));
      if (bad) {
        loopErr[y * w + x] = 1;
        err = true;
      }
    }
  }
  const clueErr = new Uint8Array(W * H);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const c = clues[y * W + x];
      if (c === NO_CLUE) continue;
      if (pointDegree(w, h, soln, x, y) > c || pointAntiDegree(w, h, soln, x, y) > 4 - c) {
        clueErr[y * W + x] = 1;
        err = true;
      }
    }
  }
  let complete = !err;
  if (complete) for (let i = 0; i < soln.length; i++) if (soln[i] === EMPTY) complete = false;
  return { loopErr, clueErr, complete };
}
