import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  RIGHT_BUTTON,
  RIGHT_DRAG,
  RIGHT_RELEASE,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  DIFFICULTY_CHARS,
  DIFFICULTY_NAMES,
  DIFF_NORMAL,
  checkComplete,
  decodeEdgeBits,
  inUI,
  initialEdges,
  isEdgePos,
  isTilePos,
  isVertexPos,
  parseDesc,
  textFormat,
  touchingTiles,
} from './board';
import type { Check, Layout } from './board';
import { generate } from './generator';
import type { GalaxiesParams } from './generator';
import { dotsTooClose, solveEdges } from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type { GalaxiesParams };

export interface GalaxiesState {
  w: number;
  h: number;
  /** Doubled-grid dimensions, 2w+1 × 2h+1. */
  sx: number;
  sy: number;
  layout: Layout;
  /** 1 at edge positions carrying a wall (the outer border is always set). */
  edges: Uint8Array;
  /** Dot (grid index) each tile has been assigned to with an arrow, or -1. */
  assoc: Int32Array;
  check: Check;
  completed: boolean;
  usedSolve: boolean;
}

export interface GalaxiesUI {
  /** An arrow is being dragged. */
  dragging: boolean;
  /** …with the keyboard, so mouse events leave it alone and it follows the cursor. */
  keyDrag: boolean;
  /** Pixel position of the dragged arrow. */
  dx: number;
  dy: number;
  /** Grid index of the dot the arrow points at. */
  dot: number;
  /** Where the drag started: the dot itself, or a tile whose arrow was picked up. */
  src: number;
  /** Keyboard cursor in doubled coordinates (any tile, edge or vertex inside the border). */
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const MAX_SIDE = 25;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const BORDER = 0.3;
/** How close to a dot (in tiles) a press must be to pick up its arrow. */
const LEFT_DOT_RADIUS = 0.32;
const RIGHT_DOT_RADIUS = 0.5;
const EDGE_WIDTH = 0.11;

export function border(t: number): number {
  return Math.round(t * BORDER);
}

/**
 * Snap a position in tile units to the nearest edge, in doubled coordinates: the nearer
 * of the horizontal and vertical edges beside the closest vertex.
 */
export function coordRoundToEdge(x: number, y: number): [number, number] {
  const xs = Math.floor(x) + 0.5;
  const ys = Math.floor(y) + 0.5;
  const xv = Math.floor(x + 0.5);
  const yv = Math.floor(y + 0.5);
  const dx = Math.abs(x - xs);
  const dy = Math.abs(y - ys);
  if (dx > dy) return [2 * xv, 1 + 2 * Math.floor(ys)];
  return [1 + 2 * Math.floor(xs), 2 * yv];
}

/** Grid index of the tile under a position in tile units, or -1 outside the grid. */
function tileAt(L: Layout, fx: number, fy: number): number {
  const tx = 2 * Math.floor(fx) + 1;
  const ty = 2 * Math.floor(fy) + 1;
  return inUI(L, tx, ty) ? ty * L.sx + tx : -1;
}

/** The dot within `radius` tiles of a position in tile units, or -1. */
function nearestDot(L: Layout, fx: number, fy: number, radius: number): number {
  const px = Math.round(fx * 2);
  const py = Math.round(fy * 2);
  let best = -1;
  let bestDist = radius;
  for (let y = py - 1; y <= py + 1; y++) {
    for (let x = px - 1; x <= px + 1; x++) {
      if (!inUI(L, x, y) || !L.dot[y * L.sx + x]) continue;
      const dist = Math.hypot(fx - x / 2, fy - y / 2);
      if (dist < bestDist) {
        bestDist = dist;
        best = y * L.sx + x;
      }
    }
  }
  return best;
}

function makeState(
  layout: Layout,
  edges: Uint8Array,
  assoc: Int32Array,
  usedSolve: boolean,
  wasCompleted = false,
): GalaxiesState {
  const check = checkComplete(layout, edges);
  return {
    w: layout.w,
    h: layout.h,
    sx: layout.sx,
    sy: layout.sy,
    layout,
    edges,
    assoc,
    check,
    // Once finished, a puzzle stays finished (as the original's `completed` flag does), so
    // breaking the board afterwards neither takes the win back nor flashes it again.
    completed: wasCompleted || check.complete,
    usedSolve,
  };
}

function startDrag(ui: GalaxiesUI, dot: number, src: number, x: number, y: number, key: boolean) {
  ui.dragging = true;
  ui.keyDrag = key;
  ui.dot = dot;
  ui.src = src;
  ui.dx = x;
  ui.dy = y;
}

/** Moves for dropping the dragged arrow on tile `target` (-1 for off the grid). */
function dropMoves(state: GalaxiesState, ui: GalaxiesUI, target: number): string {
  const { sx, layout: L, assoc } = state;
  if (target === ui.src) return '';
  // Squares touching the dot are obviously its own: dropping there is dropping on the dot.
  if (target >= 0 && touchingTiles(L, ui.dot).includes(target)) target = -1;
  const parts: string[] = [];
  const at = (i: number) => `${i % sx},${Math.floor(i / sx)}`;
  if (ui.src !== ui.dot && assoc[ui.src] >= 0) parts.push(`U${at(ui.src)}`);
  if (target >= 0 && !L.dot[target] && assoc[target] !== ui.dot)
    parts.push(`A${at(target)},${at(ui.dot)}`);
  return parts.join(';');
}

/** A short arrow centred on (cx, cy) pointing at (tx, ty). */
function drawArrow(
  dr: Drawing,
  cx: number,
  cy: number,
  tx: number,
  ty: number,
  t: number,
  colour: string,
  seed: number,
) {
  const ddx = tx - cx;
  const ddy = ty - cy;
  const len = Math.hypot(ddx, ddy);
  const width = Math.max(1.6, t * 0.05);
  if (len < 1) {
    dr.dot(cx, cy, t * 0.08, colour, { seed });
    return;
  }
  const ux = ddx / len;
  const uy = ddy / len;
  const half = t * 0.27;
  dr.arrow(cx - ux * half, cy - uy * half, cx + ux * half, cy + uy * half, colour, width, t * 0.2, {
    seed,
  });
}

/**
 * Difficulty words, in the solver's own order, for the Type menu and the Custom dialog
 * alike: a player who picks "Extreme" from one and opens the other must find the same
 * word selected there. The solver's own level names (`DIFFICULTY_NAMES`) stay in the code.
 */
const PRESET_DIFFICULTIES = ['Medium', 'Extreme'];

const game = defineGame<GalaxiesParams, GalaxiesState, GalaxiesUI>({
  id: 'galaxies',
  name: 'Galaxies',
  description: 'Divide the grid into regions, each symmetric about the single dot inside it.',
  alsoKnownAs: 'Spiral Galaxies, Tentai Show',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [7, 7, 0],
      [7, 7, 1],
      [10, 10, 0],
      [15, 15, 0],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${PRESET_DIFFICULTIES[difficulty]}`,
    params: { w, h, difficulty },
  })),
  defaultParams: () => ({ w: 7, h: 7, difficulty: DIFF_NORMAL }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? `d${DIFFICULTY_CHARS[p.difficulty]}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    const d = m[3] ? DIFFICULTY_CHARS.indexOf(m[3]) : -1;
    return { w, h, difficulty: d < 0 ? DIFF_NORMAL : d };
  },
  validateParams(p) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 3 || p.h < 3) return tx`Width and height must both be at least 3`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length)
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    const int = (s: string) => (/^-?\d+$/.test(s) ? parseInt(s, 10) : NaN);
    return {
      w: int(str(0)),
      h: int(str(1)),
      difficulty: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    if (typeof r === 'string') return r;
    // Every square has to end up in a region round a dot, so a grid without one is not a
    // puzzle at all — an empty (or all-`z`) description would otherwise load as one.
    if (r.dots.length === 0) return tx`Game description contains no dots`;
    if (dotsTooClose(r)) return tx`Dots too close together`;
    return null;
  },

  newGame(p, desc) {
    const layout = parseDesc(desc, p.w, p.h) as Layout;
    return makeState(layout, initialEdges(layout), new Int32Array(layout.n).fill(-1), false);
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const L = curr.layout;
    let target: Uint8Array | null = null;
    if (aux && aux[0] === 'S') {
      const e = decodeEdgeBits(L, aux.slice(1));
      if (e && checkComplete(L, e).complete) target = e;
    }
    if (!target) target = solveEdges(L, curr.edges, curr.assoc);
    if (!target) throw new Error(tx`Unable to find a solution to this puzzle`);
    const at = (i: number) => `${i % L.sx},${Math.floor(i / L.sx)}`;
    let move = 'S';
    for (const e of L.edgeList) if (curr.edges[e] !== target[e]) move += `;E${at(e)}`;
    for (const t of L.tiles) if (curr.assoc[t] >= 0) move += `;U${at(t)}`;
    return move;
  },

  textFormat: (s) => textFormat(s.layout, s.edges, s.assoc),

  newUI: () => ({
    dragging: false,
    keyDrag: false,
    dx: 0,
    dy: 0,
    dot: -1,
    src: -1,
    cx: 1,
    cy: 1,
    cursorVisible: false,
  }),
  changedState(ui, old, next) {
    if (next.completed && !old.completed) ui.cursorVisible = false;
    // An arrow still being dragged (mouse or keyboard) when Undo, Solve or a hint changes
    // the board must not be dropped on the new board.
    ui.dragging = ui.keyDrag = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { sx, sy, layout: L, assoc } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const fx = (mx - bd) / t;
    const fy = (my - bd) / t;
    const P = (g: number) => bd + (g * t) / 2;

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      // A press cancels any keyboard drag and hides the cursor.
      const redraw = ui.cursorVisible || ui.dragging;
      ui.cursorVisible = ui.dragging = ui.keyDrag = false;
      if (b === RIGHT_BUTTON) {
        // An arrow under the pointer wins over a dot on the square's edge: the right
        // button's generous dot radius covers half of each square beside such a dot, and
        // an arrow sitting there (for some other galaxy) could otherwise never be picked
        // up — a finger pressing anywhere near that edge took the dot instead.
        const tile = tileAt(L, fx, fy);
        if (tile >= 0 && assoc[tile] >= 0 && nearestDot(L, fx, fy, LEFT_DOT_RADIUS) < 0) {
          startDrag(ui, assoc[tile], tile, mx, my, false);
          return '';
        }
      }
      const d = nearestDot(L, fx, fy, b === LEFT_BUTTON ? LEFT_DOT_RADIUS : RIGHT_DOT_RADIUS);
      if (d >= 0) {
        startDrag(ui, d, d, mx, my, false);
        return '';
      }
      if (b === RIGHT_BUTTON) {
        // Pick up an existing arrow.
        const tile = tileAt(L, fx, fy);
        if (tile >= 0 && assoc[tile] >= 0) {
          startDrag(ui, assoc[tile], tile, mx, my, false);
          return '';
        }
        return redraw ? '' : null;
      }
      const [ex, ey] = coordRoundToEdge(fx, fy);
      if (!inUI(L, ex, ey)) return redraw ? '' : null;
      return `E${ex},${ey}`;
    }
    if (b === LEFT_DRAG || b === RIGHT_DRAG) {
      if (!ui.dragging || ui.keyDrag) return null;
      ui.dx = mx;
      ui.dy = my;
      return '';
    }
    if (b === LEFT_RELEASE || b === RIGHT_RELEASE) {
      if (!ui.dragging || ui.keyDrag) return null;
      ui.dragging = false;
      return dropMoves(state, ui, tileAt(L, fx, fy));
    }
    if (isCursorMove(b)) {
      // The cursor roams the whole interior of the doubled grid, edges and vertices included.
      const p = moveCursor(b, ui.cx - 1, ui.cy - 1, sx - 2, sy - 2);
      ui.cx = p.x + 1;
      ui.cy = p.y + 1;
      ui.cursorVisible = true;
      if (ui.dragging && ui.keyDrag) {
        ui.dx = P(ui.cx);
        ui.dy = P(ui.cy);
      }
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const pos = ui.cy * sx + ui.cx;
      const tile = isTilePos(ui.cx, ui.cy);
      if (ui.dragging) {
        if (!ui.keyDrag) return null;
        ui.dragging = ui.keyDrag = false;
        return dropMoves(state, ui, tile ? pos : -1);
      }
      if (L.dot[pos]) {
        startDrag(ui, pos, pos, P(ui.cx), P(ui.cy), true);
        return '';
      }
      if (tile && assoc[pos] >= 0) {
        startDrag(ui, assoc[pos], pos, P(ui.cx), P(ui.cy), true);
        return '';
      }
      if (isEdgePos(ui.cx, ui.cy)) return `E${ui.cx},${ui.cy}`;
      return null;
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { sx, layout: L } = state;
    const edges = state.edges.slice();
    const assoc = state.assoc.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      let m = /^([EU])(\d+),(\d+)$/.exec(part);
      if (m) {
        const x = parseInt(m[2], 10);
        const y = parseInt(m[3], 10);
        if (!inUI(L, x, y)) return null;
        const i = y * sx + x;
        if (m[1] === 'E') {
          if (!isEdgePos(x, y)) return null;
          edges[i] ^= 1;
        } else {
          if (!isTilePos(x, y) || assoc[i] < 0) return null;
          assoc[i] = -1;
        }
        continue;
      }
      m = /^A(\d+),(\d+),(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[1], 10);
      const y = parseInt(m[2], 10);
      const ax = parseInt(m[3], 10);
      const ay = parseInt(m[4], 10);
      if (!inUI(L, x, y) || !inUI(L, ax, ay) || !isTilePos(x, y)) return null;
      const i = y * sx + x;
      const d = ay * sx + ax;
      if (!L.dot[d] || L.dot[i]) return null;
      assoc[i] = d;
    }
    return makeState(L, edges, assoc, usedSolve, state.completed);
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const bd = border(t);
    return { w: p.w * t + 2 * bd, h: p.h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, sx, layout: L, edges, assoc, check } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    /** Pixel position of a doubled-grid coordinate. */
    const P = (g: number) => bd + (g * t) / 2;
    const cellX = (c: number) => bd + (c % w) * t;
    const cellY = (c: number) => bd + Math.floor(c / w) * t;

    dr.rect(bd, bd, w * t, h * t, 'paper');

    // Finished regions are shaded; regions with no dot in them are hatched as wrong.
    for (let c = 0; c < w * h; c++) {
      if (check.valid[c] && !flash)
        dr.rect(cellX(c), cellY(c), t, t, check.blackRegion[c] ? 'lowlight' : 'shade');
    }
    const hatched = new Set<number>();
    for (let c = 0; c < w * h; c++) {
      if (!check.dotless[c] || hatched.has(check.comp[c])) continue;
      const r = check.comp[c];
      hatched.add(r);
      // Hatch the whole region's bounding box, clipped to each of its cells, so the
      // strokes line up across cell boundaries.
      let x0 = w;
      let y0 = h;
      let x1 = -1;
      let y1 = -1;
      for (let k = 0; k < w * h; k++) {
        if (check.comp[k] !== r) continue;
        x0 = Math.min(x0, k % w);
        x1 = Math.max(x1, k % w);
        y0 = Math.min(y0, Math.floor(k / w));
        y1 = Math.max(y1, Math.floor(k / w));
      }
      for (let k = 0; k < w * h; k++) {
        if (check.comp[k] !== r) continue;
        dr.clip(cellX(k), cellY(k), t, t);
        dr.hatch(
          bd + x0 * t,
          bd + y0 * t,
          (x1 - x0 + 1) * t,
          (y1 - y0 + 1) * t,
          'error',
          t * 0.4,
          Math.PI / 4,
          1,
          { alpha: 0.35 },
        );
        dr.unclip();
      }
    }

    for (let x = 1; x < w; x++) dr.line(P(2 * x), P(0), P(2 * x), P(2 * h), 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(P(0), P(2 * y), P(2 * w), P(2 * y), 'faint', 1.2);

    // Arrows in assigned tiles that are not yet part of a finished region.
    for (const tile of L.tiles) {
      const d = assoc[tile];
      if (d < 0 || d === tile) continue;
      const tx = tile % sx;
      const ty = (tile - tx) / sx;
      if (check.valid[((ty - 1) / 2) * w + (tx - 1) / 2]) continue;
      if (ui.dragging && ui.src === tile) continue;
      drawArrow(dr, P(tx), P(ty), P(d % sx), P(Math.floor(d / sx)), t, 'blue', tile);
    }

    // Walls, merged into runs so each is one sketched stroke.
    const ew = Math.max(2.4, t * EDGE_WIDTH);
    for (let y = 2; y < 2 * h; y += 2) {
      for (let x = 1; x < 2 * w;) {
        if (!edges[y * sx + x]) {
          x += 2;
          continue;
        }
        const x0 = x;
        while (x < 2 * w && edges[y * sx + x]) x += 2;
        dr.line(P(x0 - 1), P(y), P(x - 1), P(y), 'ink', ew);
      }
    }
    for (let x = 2; x < 2 * w; x += 2) {
      for (let y = 1; y < 2 * h;) {
        if (!edges[y * sx + x]) {
          y += 2;
          continue;
        }
        const y0 = y;
        while (y < 2 * h && edges[y * sx + x]) y += 2;
        dr.line(P(x), P(y0 - 1), P(x), P(y - 1), 'ink', ew);
      }
    }
    dr.rectOutline(bd, bd, w * t, h * t, 'ink', { width: ew });

    // Dots.
    const r = Math.max(3, t * 0.19);
    L.dots.forEach((d, k) => {
      const x = P(d % sx);
      const y = P(Math.floor(d / sx));
      const colour = flash ? 'ok' : check.dotError[k] ? 'error' : 'ink';
      dr.circle(x, y, r, colour, colour, { seed: d, width: 1.4 });
      if (L.black[d]) dr.dot(x, y, r * 0.4, 'paper', { seed: d + 1 });
      if (ui.dragging && ui.dot === d)
        dr.circle(x, y, r + Math.max(3, t * 0.09), null, 'accent', { seed: d, width: 2 });
    });

    // The arrow being dragged, plus a hint of the tile it would land on.
    if (ui.dragging) {
      const fx = (ui.dx - bd) / t;
      const fy = (ui.dy - bd) / t;
      const target = tileAt(L, fx, fy);
      if (target >= 0 && !L.dot[target] && target !== ui.src) {
        const inset = t * 0.08;
        dr.rectOutline(
          bd + Math.floor(fx) * t + inset,
          bd + Math.floor(fy) * t + inset,
          t - 2 * inset,
          t - 2 * inset,
          'accent',
          { width: 1.6, alpha: 0.7 },
        );
      }
      drawArrow(
        dr,
        ui.dx,
        ui.dy,
        P(ui.dot % sx),
        P(Math.floor(ui.dot / sx)),
        t,
        'accent',
        Math.round(ui.dx * 7 + ui.dy * 13),
      );
    }

    if (ui.cursorVisible) {
      const x = P(ui.cx);
      const y = P(ui.cy);
      const inset = t * 0.12;
      const thin = t * 0.24;
      if (isTilePos(ui.cx, ui.cy)) {
        dr.cursor(x - t / 2 + inset, y - t / 2 + inset, t - 2 * inset, t - 2 * inset);
      } else if (isVertexPos(ui.cx, ui.cy)) {
        dr.cursor(x - thin * 0.7, y - thin * 0.7, thin * 1.4, thin * 1.4);
      } else if ((ui.cx & 1) === 1) {
        dr.cursor(x - t / 2 + inset, y - thin / 2, t - 2 * inset, thin);
      } else {
        dr.cursor(x - thin / 2, y - t / 2 + inset, thin, t - 2 * inset);
      }
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !newState.usedSolve ? FLASH : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
