import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { TracksParams, TracksState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A straight run of track along y = `y`, from x0 to x1: sleepers under two rails. */
function straight(c: C, x0: number, x1: number, y: number): string {
  let sleepers = '';
  for (let x = x0 + 4; x <= x1 - 2; x += 10) sleepers += `M${x} ${y - 11} V${y + 11} `;
  return (
    line(sleepers, c.brown, 5) + line(`M${x0} ${y - 6} H${x1} M${x0} ${y + 6} H${x1}`, c.ink, 4)
  );
}

/** Squares that picked up rails in this move. */
function newTrackSquares(a: TracksState, b: TracksState): number {
  let n = 0;
  for (let i = 0; i < b.board.track.length; i++) if (!a.board.track[i] && b.board.track[i]) n++;
  return n;
}

function same(a: ArrayLike<number>, b: ArrayLike<number>): boolean {
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

export const achievements = defineAchievements<TracksParams, TracksState>([
  {
    id: 'no-crosses',
    name: 'Nothing Crossed Out',
    description: 'Solve a 10×10 or larger Tracks without crossing out a square or a side.',
    tier: 'silver',
    hue: 'teal',
    art: (c) => {
      // The line coming in from the left and turning down to the exit.
      let sleepers = '';
      for (let k = 0; k < 5; k++) {
        const a = (Math.PI / 2) * ((k + 0.5) / 5);
        const x = (r: number) => (18 + r * Math.sin(a)).toFixed(1);
        const y = (r: number) => (82 - r * Math.cos(a)).toFixed(1);
        sleepers += `M${x(19)} ${y(19)} L${x(45)} ${y(45)} `;
      }
      return (
        line(sleepers, c.brown, 5) +
        line('M18 58 A24 24 0 0 1 42 82 M18 42 A40 40 0 0 1 58 82', c.ink, 4.5) +
        `<circle cx="66" cy="32" r="15" fill="${c.paper}" stroke="${c.red}" stroke-width="5"/>` +
        line('M60 26 L72 38 M72 26 L60 38', c.pencil, 4.5) +
        line('M55.5 42.5 L76.5 21.5', c.red, 5)
      );
    },
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 100 &&
      ctx.history.every(
        (s) =>
          same(s.board.notrack, ctx.initial.board.notrack) &&
          same(s.board.sNotrack, ctx.initial.board.sNotrack),
      ),
  },
  {
    id: 'no-lift',
    name: 'Full Steam Ahead',
    description: 'Solve a 15×10 or larger Tracks without ever lifting a rail you laid.',
    tier: 'gold',
    hue: 'red',
    art: (c) =>
      `<circle cx="64" cy="24" r="6" fill="${c.paper}" stroke="${c.pencil}" stroke-width="3"/>` +
      `<circle cx="76" cy="16" r="5" fill="${c.paper}" stroke="${c.pencil}" stroke-width="3"/>` +
      straight(c, 16, 84, 76) +
      shape('M56 32 H64 V44 H56 Z', c.ink, c.ink, 3) +
      shape('M34 44 H70 Q76 44 76 50 V64 H34 Z', c.red, c.ink) +
      shape('M18 34 H38 V64 H18 Z', c.red, c.ink) +
      shape('M22 40 H34 V50 H22 Z', c.paper, c.ink, 3) +
      line('M14 32 H42', c.ink, 5) +
      shape('M76 56 L82 64 H76 Z', c.ink, c.ink, 3) +
      `<circle cx="28" cy="66" r="7" fill="${c.ink}"/>` +
      `<circle cx="48" cy="67" r="6" fill="${c.ink}"/>` +
      `<circle cx="64" cy="67" r="6" fill="${c.ink}"/>` +
      `<circle cx="28" cy="66" r="2.5" fill="${c.paper}"/>`,
    test: (ctx) => {
      if (ctx.params.w * ctx.params.h < 150) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].board.track;
        const b = ctx.history[k].board.track;
        for (let i = 0; i < b.length; i++) if (a[i] & ~b[i]) return false;
      }
      return true;
    },
  },
  {
    id: 'long-haul',
    name: 'Long Haul',
    description: 'Lay rails through ten squares in one drag, then complete the line.',
    tier: 'bronze',
    hidden: true,
    hue: 'green',
    art: (c) =>
      straight(c, 16, 84, 62) +
      `<circle cx="22" cy="32" r="6" fill="${c.ink}"/>` +
      line('M22 32 H76', c.ink, 5) +
      line('M68 24 L78 32 L68 40', c.ink, 5),
    test: (ctx) => {
      for (let k = 1; k < ctx.history.length; k++)
        if (newTrackSquares(ctx.history[k - 1], ctx.history[k]) >= 10) return true;
      return false;
    },
  },
]);
