/**
 * Undead puzzle generation, after the original's recipe.
 *
 * Mirrors are scattered at random (about two squares in five) and the grid is kept only
 * if between roughly half and three quarters of the squares are free for monsters and no
 * line of sight passes more monsters than the difficulty allows. Monsters are then chosen
 * path by path, shortest paths first: for each path an assignment is picked whose pair of
 * sightings no other assignment of that path produces, so that the clue pair pins those
 * monsters down. Easy puzzles fill nearly the whole grid this way; harder ones stop early
 * and fill the rest at random. Finally the clues are read off the finished grid and the
 * puzzle is graded with the solver; it is kept only if it needs exactly the requested
 * tier of reasoning (and, for Tricky, still has a single solution).
 */
import type { Random } from '../../framework/rng';
import {
  ALL_TYPES,
  CELL_EMPTY,
  CELL_L,
  CELL_R,
  GHOST,
  Layout,
  Path,
  TYPES,
  TYPE_INDEX,
  VAMPIRE,
  ZOMBIE,
  computeClues,
  encodeDesc,
  encodeSolution,
} from './board';
import { DIFF_EASY, DIFF_NORMAL, DIFF_TRICKY, gradePuzzle } from './solver';

export interface GenParams {
  w: number;
  h: number;
  diff: number;
}

/** Longest list of distinct monsters a single path may pass at each difficulty. */
export function maxPathMonsters(w: number, h: number, diff: number): number {
  if (diff === DIFF_EASY) return Math.min(w, h) + 1;
  if (diff === DIFF_NORMAL) return Math.floor((Math.max(w, h) * 3) / 2);
  return 9;
}

/** Sightings from both ends of `path` under the assignment `types`. */
function viewPair(p: Path, types: Uint8Array): number {
  let s = 0;
  let e = 0;
  for (let k = 0; k < p.slots.length; k++) {
    const slot = p.slots[k];
    if (slot < 0) continue;
    if (types[slot] & p.visStart[k]) s++;
    if (types[slot] & p.visEnd[k]) e++;
  }
  return s * (p.slots.length + 1) + e;
}

/**
 * Give the undecided monsters on `path` types such that the resulting pair of sightings
 * arises from no other assignment of the path (so the two clues determine it). When no
 * assignment is that distinctive the path is left alone.
 */
export function assignUnique(p: Path, types: Uint8Array, rng: Random): boolean {
  const m = p.monsters.length;
  const options = p.monsters.map((s) => TYPES.filter((t) => types[s] & t));
  const seen = new Map<number, number>();
  const uniques: number[] = [];
  const firstOf = new Map<number, Uint8Array>();
  const trial = new Uint8Array(m);
  const rec = (k: number): void => {
    if (k === m) {
      for (let j = 0; j < m; j++) types[p.monsters[j]] = trial[j];
      const key = viewPair(p, types);
      const n = (seen.get(key) ?? 0) + 1;
      seen.set(key, n);
      if (n === 1) {
        uniques.push(key);
        firstOf.set(key, trial.slice());
      }
      return;
    }
    for (const t of options[k]) {
      trial[k] = t;
      rec(k + 1);
    }
  };
  const saved = p.monsters.map((s) => types[s]);
  rec(0);
  for (let j = 0; j < m; j++) types[p.monsters[j]] = saved[j];
  const candidates = uniques.filter((key) => seen.get(key) === 1);
  if (candidates.length === 0) return false;
  const chosen = firstOf.get(candidates[rng.upto(candidates.length)])!;
  for (let j = 0; j < m; j++) types[p.monsters[j]] = chosen[j];
  return true;
}

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(params: GenParams, rng: Random): { desc: string; aux: string } {
  const { w, h, diff } = params;
  const n = w * h;
  const maxLen = maxPathMonsters(w, h, diff);
  for (;;) {
    const cells = new Uint8Array(n);
    let free = 0;
    for (let i = 0; i < n; i++) {
      const r = rng.upto(5);
      if (r >= 2) {
        cells[i] = CELL_EMPTY;
        free++;
      } else {
        cells[i] = r === 0 ? CELL_L : CELL_R;
      }
    }
    // Too few monsters is boring; the monster/mirror balance should be reasonable.
    if (free <= 4) continue;
    const ratio = free / n;
    if (ratio < 0.48 || ratio > 0.78) continue;

    const L = new Layout(w, h, cells, [0, 0, 0], []);
    if (L.paths.some((p) => p.monsters.length > maxLen)) continue;
    const order = L.paths.slice().sort((a, b) => a.monsters.length - b.monsters.length);

    // Decide monsters along the shortest paths first, until only `filling` are left open.
    const types = new Uint8Array(L.numSlots).fill(ALL_TYPES);
    const filling =
      diff === DIFF_EASY
        ? 2
        : diff === DIFF_NORMAL
          ? Math.min(w + h, L.numSlots >> 1)
          : Math.max(w + h, L.numSlots >> 1);
    const undecided = () => types.reduce((k, t) => k + (t === ALL_TYPES ? 1 : 0), 0);
    for (let k = 0; k < order.length && undecided() > filling; k++) {
      if (order[k].monsters.length > 0) assignUnique(order[k], types, rng);
    }
    for (let i = 0; i < L.numSlots; i++) {
      if (types[i] === ALL_TYPES) {
        const r = rng.upto(3);
        types[i] = r === 0 ? GHOST : r === 1 ? VAMPIRE : ZOMBIE;
      }
    }

    const total = [0, 0, 0];
    for (const t of types) total[TYPE_INDEX[t]]++;
    // A single kind of monster makes a trivial puzzle; Tricky wants a few of each kind.
    if (total.filter((c) => c === 0).length >= 2) continue;
    if (diff === DIFF_TRICKY && total.some((c) => c <= 1)) continue;

    L.total = total;
    L.clues = computeClues(L, types);
    if (gradePuzzle(L) !== diff) continue;
    return { desc: encodeDesc(cells, total, L.clues), aux: encodeSolution(types) };
  }
}
