import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { D, R } from './board';
import type { PearlState, PearlUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

const idx = (s: PearlState, x: number, y: number) => y * s.w + x;
/** A loop segment leaves square (x, y) in direction `d`. */
const seg = (s: PearlState, x: number, y: number, d: number) => (s.lines[idx(s, x, y)] & d) !== 0;
/** A "no segment here" cross sits on that side of the square. */
const cross = (s: PearlState, x: number, y: number, d: number) => (s.marks[idx(s, x, y)] & d) !== 0;

/**
 * A 5×5 board whose white pearl on the top row and black pearl on the left edge each have
 * only one possible shape, which is enough to teach both pearl rules, the click, the drag
 * and the right-click cross.
 */
export const tutorial: Tutorial<PearlState, PearlUI> = {
  steps: [
    {
      gameId: '5x5:bWdWfBBaWg',
      text: 'Draw one closed loop from square centre to square centre. It need not visit every square, but it must pass through every pearl.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'A **white pearl** means the loop runs straight through it. On the top row the only straight is sideways, so **drag** from the square left of that pearl to the square on its right.',
      highlight: ({ tileSize }) => cellRect(1, 0, tileSize, border(tileSize), 3, 1),
      pointer: ({ tileSize }) => {
        const b = border(tileSize);
        return { ...cellCentre(1, 0, tileSize, b), to: cellCentre(3, 0, tileSize, b) };
      },
      waitFor: ({ state }) => seg(state, 1, 0, R) && seg(state, 2, 0, R),
    },
    {
      text: 'That pearl now has both its segments, so nothing else can leave it. **Right-click** the edge below it to cross that side off.',
      highlight: ({ tileSize }) => cellRect(2, 0, tileSize, border(tileSize), 1, 2),
      pointer: ({ tileSize }) => {
        const c = cellCentre(2, 0, tileSize, border(tileSize));
        return { x: c.x, y: c.y + tileSize * 0.35, button: 'right' as const };
      },
      waitFor: ({ state }) => cross(state, 2, 0, D),
    },
    {
      text: 'A **black pearl** turns, and the loop then runs straight through the square on either side of it. The one on the **left edge** cannot turn down — that would need a straight line through the bottom-left corner — so **click** its right-hand edge.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, state.h - 2, tileSize, border(tileSize), 2, 1),
      pointer: ({ state, tileSize }) => {
        const c = cellCentre(0, state.h - 2, tileSize, border(tileSize));
        return { x: c.x + tileSize * 0.35, y: c.y };
      },
      waitFor: ({ state }) => seg(state, 0, state.h - 2, R),
    },
    {
      text: 'So the square beside it runs straight on — and so does the white pearl beyond that. **Drag** from that square across to the fourth column.',
      highlight: ({ state, tileSize }) =>
        cellRect(1, state.h - 2, tileSize, border(tileSize), 3, 1),
      pointer: ({ state, tileSize }) => {
        const b = border(tileSize);
        return {
          ...cellCentre(1, state.h - 2, tileSize, b),
          to: cellCentre(3, state.h - 2, tileSize, b),
        };
      },
      waitFor: ({ state }) => seg(state, 1, state.h - 2, R) && seg(state, 2, state.h - 2, R),
    },
    {
      text: 'Keep working out from the pearls; a pearl gets a red halo the moment its rule breaks. **Solve** draws the whole loop if you want to see it.',
      target: '[data-cmd="solve"]',
    },
  ],
};
