import type { GameAchievement } from './achievements';
import type { Drawing } from './drawing';
import type { Random } from './rng';
import type { Tutorial } from './tutorial';

/** A named configuration preset (entry in the Type menu). */
export interface Preset<P> {
  name: string;
  params: P;
}

/** One field in the custom-parameters dialog. */
export type ConfigItem =
  | {
      type: 'string';
      name: string;
      value: string;
      /**
       * Which on-screen keyboard the field should summon on a phone. Left out — which is
       * the normal case — the shell reads the shape of `value`, so a plain count gets a
       * number pad and a value with punctuation in it keeps the full keyboard. Set it
       * only where the value on show is a poor guide to what the field accepts: Black Box
       * writes its ball count as `3-6` when the range is open but as `5` when it is not,
       * and the second spelling would otherwise hide the hyphen the player needs.
       */
      keyboard?: 'text' | 'numeric' | 'decimal';
    }
  | { type: 'choices'; name: string; choices: string[]; selected: number }
  | { type: 'boolean'; name: string; value: boolean };

/** Result of generating a new puzzle description. `aux` is hidden solver help. */
export interface NewDesc {
  desc: string;
  aux?: string;
}

/**
 * Per-game drawing bookkeeping. The midend owns `tileSize` and updates it whenever
 * the puzzle is resized; games may extend this with cached geometry.
 */
export interface DrawState {
  tileSize: number;
}

/** -1 = lost/failed, 0 = still playing, 1 = solved. */
export type GameStatus = -1 | 0 | 1;

/**
 * An on-screen keypad, for games whose main input is a typed character. The shell renders
 * it under the board on touch devices (and on demand behind a toolbar toggle with a
 * mouse) and sends every press through `midend.processKey` exactly as if the key had been
 * typed, so `interpretMove` needs no special case for it.
 */
export interface Keypad {
  /**
   * The characters to send, in order. Single characters: `['1', …, '9']` for a 9×9 grid,
   * `['1', …, '9', 'a', 'b', …]` where a game numbers above 9 with letters, `['G','V','Z']`
   * for Undead. They are sent as their char code, so use the same character the keyboard
   * path accepts.
   */
  keys: string[];
  /** Face of a key when the character itself is not what the player should read. */
  labels?: Record<string, string>;
  /** Add a `⌫` key that sends `KEY_BACKSPACE`. */
  clear?: boolean;
  /**
   * Add a latching pencil-mark toggle. While it is on, the keys go out with `MOD_SHFT`
   * set, which the digit games read as "pencil this in" whatever the selected square's
   * own mode is (see `docs/ADDING-A-GAME.md`).
   */
  pencil?: boolean;
}

/**
 * An extra toolbar button that sends one key code to the midend, for actions a game only
 * offers on the keyboard (a hint key, a display toggle). Rendered next to Solve on every
 * device, since they are handy with a mouse too.
 */
export interface GameAction<S = any, U = any> {
  /** Button face. Keep it to one word or one glyph. */
  label: string;
  /** A single character (sent as its char code) or a code from `framework/input`. */
  key: number | string;
  /** Tooltip; mention the keyboard equivalent. */
  title?: string;
  /** Value of the button's `data-action` attribute (defaults to a string `key`). */
  id?: string;
  /** Render the button only while this holds for the current state. */
  when?: (state: S) => boolean;
  /**
   * Meant to be pressed several times in a row (Net's view-scroll arrows): on a phone,
   * where the action lives in the More sheet, the sheet stays up after it instead of
   * closing, as it does for the zoom buttons.
   */
  repeat?: boolean;
  /**
   * Pressed during play (an eraser, a colour to paint with, a mode switch), so it stays
   * among the HUD's round buttons instead of waiting in the pause menu with the display
   * toggles. Keep it to the two or three that earn the room.
   */
  hud?: boolean;
  /**
   * SVG markup for the button's face in the HUD: a 24×24 `viewBox`, drawn in
   * `currentColor` like the shell's own glyphs. The label stays the accessible name.
   * Without one a HUD action is a pill with its label written on it.
   */
  glyph?: string;
  /**
   * A latching switch (a mode, a display toggle): lit while this holds. Read after every
   * change, so the key it sends only has to flip a field on the UI or the state.
   */
  pressed?: (state: S, ui: U) => boolean;
  /**
   * A latching `hud` switch that changes what the board shows (Highlight, Numbers) rather
   * than what a tap does. Without it a lit HUD switch counts as a tool: while it is on, a
   * plain tap is the left button and a long-press the right, whatever the Tap switch says.
   */
  view?: boolean;
}

export interface GameFlags {
  /** Animate the transition into the solved state (Untangle). */
  solveAnimates?: boolean;
  /**
   * Pairs [held, pressed]: if `held` is currently down and `pressed` is pressed, the
   * new press is ignored rather than fabricating a release (Mines: left beats right).
   */
  buttonBeats?: [number, number][];
  /**
   * Every action is a left click (Cube, Fifteen, Flood…): a right click does nothing. The
   * shell then offers no **Tap:** switch on touch, which would only make taps do nothing,
   * and skips the "long-press for the second action" tip. Also set by a game whose own
   * HUD switch already swaps what a tap does (Twiddle's Clockwise), where the Tap switch
   * would be a second copy of it; a long-press still sends the right button.
   */
  oneButton?: boolean;
  /**
   * The share link carries the random seed rather than the description, whenever there is
   * one. For a game whose `solve` needs the generator's `aux` (Untangle: the planar layout
   * cannot be worked out from the edges), a description link hands the recipient a puzzle
   * that Solve refuses; a seed regenerates the aux with it.
   */
  shareBySeed?: boolean;
  /**
   * A loss is one move to take back, not the end of the puzzle (Inertia's mine): the
   * end-of-game panel then offers **Undo** first, where it would otherwise offer to
   * restart the whole puzzle and throw away everything played before the fatal move.
   */
  undoAfterLoss?: boolean;
  /**
   * A loss shows the answer (Guess prints the hidden code, Black Box the balls), so the
   * end panel offers a fresh puzzle rather than another go at one already given away.
   */
  lossRevealsAnswer?: boolean;
}

/**
 * The contract every puzzle implements. Generic over the parameter object `P`, the
 * immutable game state `S`, the mutable UI state `U` (cursor position, drag state) and
 * the draw state `DS`.
 *
 * States must be treated as immutable: `executeMove` returns a fresh state and never
 * mutates its input, which is what makes undo/redo trivial.
 */
export interface Game<P = any, S = any, U = any, DS extends DrawState = DrawState> {
  /** URL slug, e.g. `net`. */
  id: string;
  /** Display name, e.g. `Net`. */
  name: string;
  /**
   * The names the same puzzle goes by elsewhere, comma-separated, e.g. `Sudoku` for Solo
   * and `Nonogram, Picross, Griddlers` for Pattern. Shown under the name on the menu card
   * so a player who knows the puzzle can find it. Omit it when the puzzle really is only
   * known by the name above — never invent one.
   */
  alsoKnownAs?: string;
  /** One-line description for the menu. */
  description: string;
  /**
   * Where the game sits in the menu's running order, lowest first: `1` for a puzzle most
   * people already know by name, `2` for one that is quick to pick up, `3` for one that
   * wants its help page first. Defaults to `2`; games sharing a tier stay alphabetical.
   */
  menuTier?: 1 | 2 | 3;
  /** Rules and controls, in markdown. */
  help: string;

  presets: Preset<P>[];
  defaultParams(): P;
  /** `full` includes generation-only parameters such as difficulty. */
  encodeParams(params: P, full: boolean): string;
  /** Parse a parameter string; unknown parts are ignored, missing parts default. */
  decodeParams(str: string): P;
  /** Human-readable error, or null when the parameters are acceptable. */
  validateParams(params: P, full: boolean): string | null;
  /**
   * Optional: the full parameters a description implies, for a game whose short
   * parameters leave out something the description itself shows (Pegs: `7x7` says nothing
   * of cross, octagon or random, but the board in the description does). Called when a game
   * ID is loaded with short parameters, after `validateDesc` passed; return `params` with
   * what the description settles filled in, or null to leave them as they are. The result
   * then counts as full parameters: it is what the Type menu, New, credits and bests see.
   */
  paramsFromDesc?(params: P, desc: string): P | null;
  /** Fields for the Custom dialog. Omit for games without custom parameters. */
  configure?(params: P): ConfigItem[];
  customParams?(items: ConfigItem[]): P;

  /** Generate a new puzzle description from the RNG. */
  newDesc(params: P, rng: Random, interactive: boolean): NewDesc;
  validateDesc(params: P, desc: string): string | null;
  newGame(params: P, desc: string): S;

  canSolve: boolean;
  /**
   * Return a move string that transforms `curr` into a solved state. Throw an Error
   * with a user-facing message when the puzzle cannot be solved.
   */
  solve?(orig: S, curr: S, aux: string | undefined): string;

  /**
   * Reveal **one** step of the solution: a move string that moves the player forward by a
   * single deduction — one square filled in, or one square the board says is wrong put
   * right — or `null` when there is nothing left to give. Throw an Error with a
   * user-facing message when the solution cannot be worked out, exactly as `solve` does.
   *
   * Optional and purely additive: the shell shows its **Hint** button only for the games
   * that implement it, and a game without one behaves as it always did. Keep the step
   * small — a hinted puzzle is still the player's to finish, and up to
   * `Midend.HINT_ALLOWANCE` hints still count as hand-solved (see `docs/ADDING-A-GAME.md`).
   *
   * `ui` is passed so the hint can mark the square it touched; `markHint` in
   * `framework/grid` records it and asks for the little flash that shows where the help
   * landed.
   */
  hint?(orig: S, curr: S, aux: string | undefined, ui: U): string | null;

  /** Plain-text rendering of a state (for copy/paste). */
  textFormat?(state: S): string;

  /**
   * A description of the puzzle as it now stands, for a game whose description settles
   * during play (Mines places its mines at the first click). Share hands this out, so the
   * recipient gets the very board rather than the same seed with a different first click.
   * Null while there is nothing more settled than the original description.
   */
  settledDesc?(state: S): string | null;

  newUI(state: S): U;
  changedState?(ui: U, oldState: S, newState: S): void;
  encodeUI?(ui: U): string;
  decodeUI?(ui: U, encoding: string): void;

  /**
   * Interpret a mouse/keyboard event.
   * - `null`: not handled (the midend may apply a global shortcut).
   * - `''`: UI-only change; redraw but do not create a move.
   * - other string: a move to pass to `executeMove`.
   */
  interpretMove(state: S, ui: U, ds: DS, x: number, y: number, button: number): string | null;
  /** Apply a move. Return `null` for an invalid move string. */
  executeMove(state: S, move: string): S | null;

  /**
   * On-screen keypad for the current parameters, so a device without a keyboard can still
   * type. Return `null` when this size needs none.
   */
  keypad?(params: P): Keypad | null;
  /** Extra toolbar buttons that send a key code (hints, display toggles). */
  actions?: GameAction<S, U>[];

  preferredTileSize: number;
  computeSize(params: P, tileSize: number): { w: number; h: number };
  newDrawState?(state: S, params: P): Omit<DS, 'tileSize'>;

  redraw(
    dr: Drawing,
    ds: DS,
    oldState: S | null,
    newState: S,
    dir: number,
    ui: U,
    animTime: number,
    flashTime: number,
  ): void;
  /** Duration in seconds of the animation between two states (0 for none). */
  animLength(oldState: S, newState: S, dir: number, ui: U): number;
  /** Duration in seconds of the completion flash (0 for none). */
  flashLength(oldState: S, newState: S, dir: number, ui: U): number;
  status(state: S): GameStatus;

  wantsStatusBar: boolean;
  isTimed: boolean;
  timingState?(state: S, ui: U): boolean;
  flags?: GameFlags;

  /** Parameters used to render the menu thumbnail (defaults to the first preset). */
  thumbnailParams?: P;
  /** Moves applied to the fresh state before rendering the thumbnail (e.g. a few lasers fired). */
  thumbnailMoves?: string[];
  /** Interactive walkthrough shown on first visit and replayable from Help. */
  tutorial?: Tutorial<S, U>;
  /** This game's own achievements (see `framework/achievements` and `docs/ACHIEVEMENTS.md`). */
  achievements?: GameAchievement<P, S>[];
}

/** Helper to get full type inference when declaring a game. */
export function defineGame<P, S, U, DS extends DrawState = DrawState>(
  game: Game<P, S, U, DS>,
): Game<P, S, U, DS> {
  return game;
}
