/**
 * Pearl solver.
 *
 * The workspace keeps, for every square, the set of states it might still be in (see
 * `STATES` in board.ts) and, for every edge between two squares, whether the loop is
 * known to cross it, known not to, or unknown. Deductions alternate between the two:
 * a known edge rules out square states, and the states a square has left may nail its
 * edges down. On top of that sit the pearl rules (a black pearl's neighbours along the
 * loop are straights, a white pearl has a corner next to it along the loop) and, at
 * Tricky, a union–find of the squares joined so far that forbids any edge or state
 * which would close a loop before every known-occupied square has been collected.
 *
 * The first closed loop found is the answer: everything outside it must be empty.
 */
import { DSF } from '../../framework/dsf';
import {
  BLANK,
  CORNER,
  DIRS,
  STATES,
  STRAIGHT,
  acw,
  bANY,
  bBLANK,
  bCORNER,
  bSTRAIGHT,
  cw,
  dx,
  dy,
  flip,
} from './board';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Tricky'];
export const DIFFICULTY_CHARS = 'et';

export const SOLVE_IMPOSSIBLE = 0;
export const SOLVE_SOLVED = 1;
export const SOLVE_STUCK = 2;

const CONN = 1;
const DISC = 2;
const UNKNOWN = 3;

/** Solver workspace for one puzzle. */
export class Work {
  readonly n: number;
  /** Horizontal links (between (x-1,y) and (x,y)) come first, then vertical ones. */
  private readonly nH: number;
  /** Possible states of each square, as a bit set over `STATES`. */
  sq: Uint16Array;
  /** `CONN`, `DISC` or `UNKNOWN` for every edge; the grid border is disconnected. */
  edges: Uint8Array;

  constructor(
    readonly w: number,
    readonly h: number,
    readonly clues: Uint8Array,
  ) {
    this.n = w * h;
    this.nH = h * (w + 1);
    this.sq = new Uint16Array(this.n);
    for (let i = 0; i < this.n; i++)
      this.sq[i] = clues[i] === CORNER ? bCORNER : clues[i] === STRAIGHT ? bSTRAIGHT : bANY;
    this.edges = new Uint8Array(this.nH + (h + 1) * w).fill(UNKNOWN);
    for (let y = 0; y < h; y++) {
      this.edges[y * (w + 1)] = DISC;
      this.edges[y * (w + 1) + w] = DISC;
    }
    for (let x = 0; x < w; x++) {
      this.edges[this.nH + x] = DISC;
      this.edges[this.nH + h * w + x] = DISC;
    }
  }

  /** Index of the edge leaving square (x, y) in direction `d`. */
  edge(x: number, y: number, d: number): number {
    const { w, nH } = this;
    if (d === 1) return y * (w + 1) + x + 1; // R
    if (d === 4) return y * (w + 1) + x; // L
    if (d === 2) return nH + y * w + x; // U
    return nH + (y + 1) * w + x; // D
  }

  clone(): Work {
    const c = new Work(this.w, this.h, this.clues);
    c.sq.set(this.sq);
    c.edges.set(this.edges);
    return c;
  }

  /** The single remaining state of every square, once solved. */
  lines(): Uint8Array {
    const out = new Uint8Array(this.n);
    for (let i = 0; i < this.n; i++) {
      for (const s of STATES) if (this.sq[i] === 1 << s) out[i] = s;
    }
    return out;
  }
}

/**
 * Run deductions at the given difficulty until the loop closes, a contradiction turns
 * up, or nothing more can be found.
 */
export function solve(work: Work, difficulty: number): number {
  const { w, h, n, clues, sq, edges } = work;
  const inGrid = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h;

  for (;;) {
    let done = false;

    // Discard square states that disagree with a known edge.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        let mask = sq[i];
        for (const s of STATES) {
          if (!(mask & (1 << s))) continue;
          for (const d of DIRS) {
            if (edges[work.edge(x, y, d)] === (s & d ? DISC : CONN)) {
              mask &= ~(1 << s);
              done = true;
              break;
            }
          }
        }
        if (!mask) return SOLVE_IMPOSSIBLE;
        sq[i] = mask;
      }
    }

    // An edge every remaining state agrees on is known.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const mask = sq[y * w + x];
        let or = 0;
        let and = 15;
        for (const s of STATES) {
          if (mask & (1 << s)) {
            or |= s;
            and &= s;
          }
        }
        if (and & ~or) return SOLVE_IMPOSSIBLE;
        for (const d of DIRS) {
          const e = work.edge(x, y, d);
          if (edges[e] !== UNKNOWN) continue;
          if (!(or & d)) {
            edges[e] = DISC;
            done = true;
          } else if (and & d) {
            edges[e] = CONN;
            done = true;
          }
        }
      }
    }
    if (done) continue;

    // Pearl rules that reach one square further.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        if (clues[i] === CORNER) {
          for (const d of DIRS) {
            const fx = x + dx(d);
            const fy = y + dy(d);
            if (!inGrid(fx, fy)) continue;
            const f = fy * w + fx;
            const straight = 1 << (d | flip(d));
            const e = edges[work.edge(x, y, d)];
            if (e === CONN) {
              // Leaving a black pearl this way, the loop must run straight on. (Keep
              // this monotone: re-adding an eliminated state could loop forever.)
              if (sq[f] & ~straight) {
                sq[f] &= straight;
                done = true;
              }
            } else if (e === UNKNOWN && !(sq[f] & straight)) {
              // ...so if the next square cannot do that, the loop does not go this way.
              edges[work.edge(x, y, d)] = DISC;
              done = true;
            }
          }
        } else if (clues[i] === STRAIGHT) {
          // A white pearl cannot lie along an axis where neither neighbour can be a
          // corner that connects to it.
          for (const d of [1, 2]) {
            const type = d | flip(d);
            if (!(sq[i] & (1 << type))) continue;
            const fx = x + dx(d);
            const fy = y + dy(d);
            const gx = x - dx(d);
            const gy = y - dy(d);
            const fCorner = (1 << (flip(d) | acw(d))) | (1 << (flip(d) | cw(d)));
            const gCorner = (1 << (d | acw(d))) | (1 << (d | cw(d)));
            const fOk = inGrid(fx, fy) && sq[fy * w + fx] & fCorner;
            const gOk = inGrid(gx, gy) && sq[gy * w + gx] & gCorner;
            if (!fOk && !gOk) {
              sq[i] &= ~(1 << type);
              done = true;
            }
          }
          // A white pearl with a known direction whose one neighbour is surely
          // straight needs a corner on the other side.
          for (const d of DIRS) {
            const type = d | flip(d);
            if (sq[i] !== 1 << type) continue;
            const fx = x + dx(d);
            const fy = y + dy(d);
            const gx = x - dx(d);
            const gy = y - dy(d);
            if (!inGrid(fx, fy) || !inGrid(gx, gy)) continue;
            const f = fy * w + fx;
            const g = gy * w + gx;
            if (!(sq[f] & ~bSTRAIGHT) && sq[g] & ~bCORNER) {
              sq[g] &= bCORNER;
              done = true;
            }
          }
        }
      }
    }
    if (done) continue;

    // Join squares along known edges. The first closed loop is the solution.
    const dsf = new DSF(n);
    let nonblanks = 0;
    let loopClass = -1;
    for (let i = 0; i < n; i++) if (!(sq[i] & bBLANK)) nonblanks++;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const a = y * w + x;
        for (const d of [1, 8]) {
          const bx = x + dx(d);
          const by = y + dy(d);
          if (!inGrid(bx, by) || edges[work.edge(x, y, d)] !== CONN) continue;
          const b = by * w + bx;
          if (dsf.same(a, b)) {
            if (loopClass !== -1) return SOLVE_IMPOSSIBLE; // two separate loops
            loopClass = dsf.find(a);
          } else {
            dsf.merge(a, b);
          }
        }
      }
    }
    if (loopClass !== -1) {
      loopClass = dsf.find(loopClass);
      for (let i = 0; i < n; i++) {
        if (dsf.find(i) === loopClass) continue;
        if (!(sq[i] & bBLANK)) return SOLVE_IMPOSSIBLE;
        sq[i] = bBLANK;
      }
      return SOLVE_SOLVED;
    }

    if (difficulty >= DIFF_TRICKY) {
      // Closing a loop that leaves out a known-occupied square is never allowed:
      // neither by an edge between two squares already joined...
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const a = y * w + x;
          for (const d of [1, 8]) {
            const bx = x + dx(d);
            const by = y + dy(d);
            if (!inGrid(bx, by)) continue;
            const e = work.edge(x, y, d);
            if (edges[e] !== UNKNOWN) continue;
            const b = by * w + bx;
            if (dsf.same(a, b) && dsf.sizeOf(a) < nonblanks) {
              edges[e] = DISC;
              done = true;
            }
          }
        }
      }
      // ...nor by a square state that would join two squares already joined.
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const i = y * w + x;
          const mine = dsf.find(i);
          for (const s of STATES) {
            if (s === BLANK || !(sq[i] & (1 << s))) continue;
            let cls = -1;
            let known = 0;
            for (const d of DIRS) {
              if (!(s & d)) continue;
              const nx = x + dx(d);
              const ny = y + dy(d);
              if (!inGrid(nx, ny)) {
                cls = -2;
                break;
              }
              if (edges[work.edge(x, y, d)] === CONN) known++;
              const c = dsf.find(ny * w + nx);
              if (cls === -1) cls = c;
              else if (cls !== c) cls = -2;
            }
            // Both edges already drawn: the neighbours are joined *through* this
            // square, so the state adds nothing and closes nothing.
            if (cls < 0 || known === 2) continue;
            const loopSize = dsf.sizeOf(cls) + (cls === mine ? 0 : 1);
            if (loopSize < nonblanks) {
              sq[i] &= ~(1 << s);
              done = true;
            }
          }
        }
      }
    }
    if (done) continue;

    return SOLVE_STUCK;
  }
}

/** Solve from scratch; `lines` is filled in when the result is `SOLVE_SOLVED`. */
export function solveFresh(
  w: number,
  h: number,
  clues: Uint8Array,
  difficulty: number,
): { result: number; lines: Uint8Array } {
  const work = new Work(w, h, clues);
  const result = solve(work, difficulty);
  return { result, lines: result === SOLVE_SOLVED ? work.lines() : new Uint8Array(w * h) };
}

/**
 * Find *a* solution even when deduction alone gets stuck, by trying both values of an
 * unknown edge and recursing. Only the Solve button uses this, for hand-made puzzles;
 * `budget` bounds the number of solver runs.
 */
export function solveWithGuessing(work: Work, budget = { left: 4000 }): number {
  const r = solve(work, DIFF_TRICKY);
  if (r !== SOLVE_STUCK || budget.left <= 0) return r;
  // Branch on an unknown edge next to a square with few options left.
  let best = -1;
  let bestCount = 99;
  const { w, h, sq, edges } = work;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let count = 0;
      for (const s of STATES) if (sq[y * w + x] & (1 << s)) count++;
      if (count <= 1 || count >= bestCount) continue;
      for (const d of DIRS) {
        const e = work.edge(x, y, d);
        if (edges[e] === UNKNOWN) {
          best = e;
          bestCount = count;
          break;
        }
      }
    }
  }
  if (best < 0) return SOLVE_STUCK;
  let stuck = false;
  for (const v of [CONN, DISC]) {
    budget.left--;
    const trial = work.clone();
    trial.edges[best] = v;
    const rr = solveWithGuessing(trial, budget);
    if (rr === SOLVE_SOLVED) {
      work.sq.set(trial.sq);
      work.edges.set(trial.edges);
      return SOLVE_SOLVED;
    }
    if (rr === SOLVE_STUCK) stuck = true;
  }
  return stuck ? SOLVE_STUCK : SOLVE_IMPOSSIBLE;
}
