/**
 * Deductive Unruly solver.
 *
 * The solver only ever makes forced deductions, so whenever it fills the grid completely
 * the puzzle has exactly that one solution. Two tiers of reasoning correspond to the
 * difficulty levels:
 *
 *  - **Easy**: two adjacent cells of one colour (or two with a gap between them) force
 *    the neighbouring cell to the other colour; a line that already holds its quota of
 *    one colour gets the other colour everywhere else; and, in unique mode, a line that
 *    is one cell short of copying a finished line must differ in that cell.
 *  - **Normal** adds the "nearly complete line" argument: when a line needs just one more
 *    cell of colour X, any three consecutive cells that hold no X yet must be where it
 *    goes — otherwise they would all end up the other colour — so every other empty cell
 *    in the line is the other colour.
 *
 * `Solver.run(diff)` applies the tiers up to `diff` until nothing changes and reports the
 * hardest tier it needed. The Easy rules are local to a line, so they are driven by a
 * worklist of rows and columns that changed rather than by whole-grid passes.
 * `countSolutions` and `findSolution` are plain backtracking searches (with Easy
 * propagation) for tests and for solving arbitrary descriptions.
 */
import { BLACK, EMPTY, WHITE, anyThrees, isComplete, matchingLines, other } from './board';

export const DIFF_EASY = 0;
export const DIFF_NORMAL = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Normal'];

/** Temporary marker for cells excluded from a line fill. */
const BOGUS = 3;

export class Solver {
  readonly n: number;
  grid: Uint8Array;
  /** Cells of each colour per row / column, indexed `[colour][line]`. */
  rows: [Int16Array, Int16Array, Int16Array];
  cols: [Int16Array, Int16Array, Int16Array];
  /** Lines whose contents changed since they were last examined: rows `y`, columns `h + x`. */
  private dirty: Uint8Array;
  private queue: number[] = [];

  constructor(
    readonly w: number,
    readonly h: number,
    readonly unique: boolean,
    grid: Uint8Array,
  ) {
    this.n = w * h;
    this.grid = grid.slice();
    this.rows = [new Int16Array(h), new Int16Array(h), new Int16Array(h)];
    this.cols = [new Int16Array(w), new Int16Array(w), new Int16Array(w)];
    for (let i = 0; i < this.n; i++) {
      const c = this.grid[i];
      if (c === BLACK || c === WHITE) {
        this.rows[c][Math.floor(i / w)]++;
        this.cols[c][i % w]++;
      }
    }
    this.dirty = new Uint8Array(w + h).fill(1);
    for (let q = 0; q < w + h; q++) this.queue.push(q);
  }

  clone(): Solver {
    return new Solver(this.w, this.h, this.unique, this.grid);
  }

  /** Colour an empty cell. */
  set(i: number, c: number): void {
    const y = Math.floor(i / this.w);
    const x = i % this.w;
    this.grid[i] = c;
    this.rows[c][y]++;
    this.cols[c][x]++;
    this.touch(y);
    this.touch(this.h + x);
  }

  /** Empty a coloured cell. */
  clear(i: number): void {
    const c = this.grid[i];
    if (c !== BLACK && c !== WHITE) return;
    const y = Math.floor(i / this.w);
    const x = i % this.w;
    this.grid[i] = EMPTY;
    this.rows[c][y]--;
    this.cols[c][x]--;
    this.touch(y);
    this.touch(this.h + x);
  }

  private touch(q: number): void {
    if (!this.dirty[q]) {
      this.dirty[q] = 1;
      this.queue.push(q);
    }
  }

  isFull(): boolean {
    for (let i = 0; i < this.n; i++) if (this.grid[i] === EMPTY) return false;
    return true;
  }

  /** The grid is complete and obeys every rule. */
  solved(): boolean {
    return isComplete(this.grid, this.w, this.h, this.unique);
  }

  /** A rule is already broken: three in a row, an over-full line or two matching lines. */
  contradiction(): boolean {
    const { w, h } = this;
    for (const c of [BLACK, WHITE]) {
      for (let y = 0; y < h; y++) if (this.rows[c][y] > w / 2) return true;
      for (let x = 0; x < w; x++) if (this.cols[c][x] > h / 2) return true;
    }
    if (anyThrees(this.grid, w, h)) return true;
    return this.unique && matchingLines(this.grid, w, h).any;
  }

  /**
   * Apply deductions up to and including tier `diff` until nothing more follows. Returns
   * the hardest tier that contributed, or -1 when nothing could be deduced.
   */
  run(diff: number): number {
    let maxdiff = -1;
    for (;;) {
      if (this.easy()) {
        maxdiff = Math.max(maxdiff, DIFF_EASY);
        continue;
      }
      if (this.unique && this.uniques()) {
        maxdiff = Math.max(maxdiff, DIFF_EASY);
        continue;
      }
      if (diff < DIFF_NORMAL) break;
      if (this.nearComplete()) {
        maxdiff = Math.max(maxdiff, DIFF_NORMAL);
        continue;
      }
      break;
    }
    return maxdiff;
  }

  /** Drain the worklist, applying the line-local Easy rules to every changed line. */
  private easy(): number {
    let done = 0;
    while (this.queue.length) {
      const q = this.queue.pop()!;
      this.dirty[q] = 0;
      const horizontal = q < this.h;
      const line = horizontal ? q : q - this.h;
      done += this.threes(horizontal, line);
      done += this.completeLine(horizontal, line);
    }
    return done;
  }

  /** Any two of three consecutive cells sharing a colour force the third. */
  private threes(horizontal: boolean, line: number): number {
    const { grid } = this;
    const len = horizontal ? this.w : this.h;
    const stride = horizontal ? 1 : this.w;
    let done = 0;
    let i1 = horizontal ? line * this.w : line;
    for (let k = 0; k + 2 < len; k++, i1 += stride) {
      const i2 = i1 + stride;
      const i3 = i2 + stride;
      const a = grid[i1];
      const b = grid[i2];
      const c = grid[i3];
      if (a === EMPTY) {
        if (b !== EMPTY && b === c) {
          this.set(i1, other(b));
          done++;
        }
      } else if (b === EMPTY) {
        if (a === c) {
          this.set(i2, other(a));
          done++;
        }
      } else if (c === EMPTY && a === b) {
        this.set(i3, other(a));
        done++;
      }
    }
    return done;
  }

  /** Fill every empty cell of a line with `c`, skipping BOGUS markers. */
  private fillLine(horizontal: boolean, line: number, c: number): number {
    const len = horizontal ? this.w : this.h;
    const stride = horizontal ? 1 : this.w;
    let done = 0;
    let i = horizontal ? line * this.w : line;
    for (let k = 0; k < len; k++, i += stride) {
      if (this.grid[i] === EMPTY) {
        this.set(i, c);
        done++;
      }
    }
    return done;
  }

  /** A line holding its full quota of one colour gets the other colour everywhere else. */
  private completeLine(horizontal: boolean, line: number): number {
    const half = (horizontal ? this.w : this.h) / 2;
    const counts = horizontal ? this.rows : this.cols;
    for (const c of [BLACK, WHITE]) {
      if (counts[c][line] === half && counts[other(c)][line] < half)
        return this.fillLine(horizontal, line, other(c));
    }
    return 0;
  }

  /** Cell index for position `k` along row/column `line`. */
  private at(horizontal: boolean, line: number, k: number): number {
    return horizontal ? line * this.w + k : k * this.w + line;
  }

  /**
   * Unique mode: a line with all but one of its `c` cells in the same places as a line
   * that already has its full quota of `c` must put something else in the last place.
   */
  private uniques(): number {
    const { grid } = this;
    let done = 0;
    for (const horizontal of [true, false]) {
      const lines = horizontal ? this.h : this.w;
      const len = horizontal ? this.w : this.h;
      const half = len / 2;
      const counts = horizontal ? this.rows : this.cols;
      for (const c of [BLACK, WHITE]) {
        for (let r = 0; r < lines; r++) {
          if (counts[c][r] !== half) continue;
          for (let r2 = 0; r2 < lines; r2++) {
            if (counts[c][r2] !== half - 1) continue;
            let nmatch = 0;
            let nonmatch = -1;
            for (let k = 0; k < len; k++) {
              if (grid[this.at(horizontal, r, k)] !== c) continue;
              if (grid[this.at(horizontal, r2, k)] === c) nmatch++;
              else nonmatch = k;
            }
            if (nmatch !== half - 1 || nonmatch < 0) continue;
            const i = this.at(horizontal, r2, nonmatch);
            if (grid[i] === EMPTY) {
              this.set(i, other(c));
              done++;
            }
          }
        }
      }
    }
    return done;
  }

  /**
   * Normal: a line needing exactly one more cell of colour X. Three consecutive cells
   * that contain no X (empties and the other colour only) must be where that X goes,
   * so every empty cell outside them takes the other colour.
   */
  private nearComplete(): number {
    const { grid } = this;
    let done = 0;
    for (const horizontal of [true, false]) {
      const lines = horizontal ? this.h : this.w;
      const len = horizontal ? this.w : this.h;
      const half = len / 2;
      const counts = horizontal ? this.rows : this.cols;
      for (const fill of [WHITE, BLACK]) {
        const need = other(fill);
        for (let line = 0; line < lines; line++) {
          // One `need` left to place, at least two `fill`s.
          if (counts[need][line] < half - 1 || counts[fill][line] > half - 2) continue;
          for (let k = 0; k + 2 < len; k++) {
            const idx = [
              this.at(horizontal, line, k),
              this.at(horizontal, line, k + 1),
              this.at(horizontal, line, k + 2),
            ];
            let empties = 0;
            let ok = true;
            for (const i of idx) {
              if (grid[i] === EMPTY) empties++;
              else if (grid[i] !== fill) ok = false;
            }
            if (!ok || empties < 2) continue;
            // Nothing to do when every empty cell of the line is inside the triple.
            if (len - counts[BLACK][line] - counts[WHITE][line] === empties) continue;
            for (const i of idx) if (grid[i] === EMPTY) grid[i] = BOGUS;
            done += this.fillLine(horizontal, line, fill);
            for (const i of idx) if (grid[i] === BOGUS) grid[i] = EMPTY;
          }
        }
      }
    }
    return done;
  }
}

/** Thrown when a backtracking search exceeds its node budget. */
export class SearchBudgetExceeded extends Error {}

/**
 * Backtracking search with Easy propagation. Calls `onSolution` for every complete
 * valid grid found and stops once it returns true. Returns the number of solutions
 * reported. `budget` bounds the number of guesses.
 */
function search(
  solver: Solver,
  onSolution: (grid: Uint8Array) => boolean,
  budget: { nodes: number },
): number {
  const stack: Solver[] = [solver];
  let found = 0;
  while (stack.length) {
    const s = stack.pop()!;
    s.run(DIFF_EASY);
    if (s.contradiction()) continue;
    const i = s.grid.indexOf(EMPTY);
    if (i < 0) {
      if (s.solved()) {
        found++;
        if (onSolution(s.grid)) break;
      }
      continue;
    }
    if (--budget.nodes < 0) throw new SearchBudgetExceeded('search budget exceeded');
    for (const c of [WHITE, BLACK]) {
      const next = s.clone();
      next.set(i, c);
      stack.push(next);
    }
  }
  return found;
}

/** Number of solutions of a clue grid, counting no further than `limit`. */
export function countSolutions(
  grid: Uint8Array,
  w: number,
  h: number,
  unique: boolean,
  limit = 2,
  budget = 1_000_000,
): number {
  let n = 0;
  return search(
    new Solver(w, h, unique, grid),
    () => {
      n++;
      return n >= limit;
    },
    { nodes: budget },
  );
}

/**
 * A solution of the puzzle, or null when there is none. Deduction first (all tiers),
 * then a bounded backtracking search from whatever that left.
 */
export function findSolution(
  grid: Uint8Array,
  w: number,
  h: number,
  unique: boolean,
  budget = 200_000,
): Uint8Array | null {
  const solver = new Solver(w, h, unique, grid);
  solver.run(DIFF_NORMAL);
  if (solver.contradiction()) return null;
  if (solver.isFull()) return solver.solved() ? solver.grid : null;
  let result: Uint8Array | null = null;
  search(
    solver,
    (g) => {
      result = g;
      return true;
    },
    { nodes: budget },
  );
  return result;
}
