/**
 * Progression: the collection starts with a few games unlocked; solving a puzzle by hand at
 * a preset size earns a credit, and a credit unlocks one more game. Everything is stored
 * through `./storage`, which prefers the CrazyGames platform store and falls back to
 * `localStorage`, so it survives reloads and needs no account — including inside the
 * CrazyGames iframe, where plain `localStorage` writes can be discarded outright.
 */

import { onStorageUpgrade, readAll, writeItem } from '../storage';

/**
 * Open from the very first visit, with no credit spent. Chosen to span genres and to put
 * something a newcomer already recognises in front of them straight away — a portal player
 * arriving cold should not have to earn their way to Sudoku or Minesweeper.
 */
export const STARTER_GAMES = [
  'fifteen',
  'flood',
  'mines',
  'net',
  'pattern',
  'samegame',
  'solo',
  'untangle',
];
const KEY = 'puzzlebox:progress';
const VERSION = 1;

export interface ProgressData {
  version: number;
  unlocked: string[];
  credits: number;
  /** Puzzles solved per game (by hand, at preset sizes). */
  solved: Record<string, number>;
  /** Game IDs already rewarded, so undo/redo cannot farm credits. */
  awarded: string[];
  /** Everything open, no gating (opt-out). */
  unlockAll: boolean;
}

type Listener = (p: ProgressData) => void;
const listeners = new Set<Listener>();

function parse(raw: string): ProgressData | null {
  try {
    const d = JSON.parse(raw) as ProgressData;
    if (d && d.version === VERSION && Array.isArray(d.unlocked))
      return withStarters({ ...fresh(), ...d });
  } catch {
    /* ignore */
  }
  return null;
}

/**
 * Combine two saved records. Only ever needed when the storage tiers disagree — a player
 * who earned credits on the site directly and then opened it inside the CrazyGames frame,
 * or vice versa. The rule is deliberately one-way: an unlock, a solve or a rewarded puzzle
 * present on *either* side is kept, so reconciling can never take progress away. Credits
 * take the higher of the two, which at worst hands out one or two extra.
 */
function merge(a: ProgressData, b: ProgressData): ProgressData {
  const solved: Record<string, number> = { ...a.solved };
  for (const [k, v] of Object.entries(b.solved ?? {})) {
    solved[k] = Math.max(solved[k] ?? 0, v);
  }
  return {
    version: VERSION,
    unlocked: [...new Set([...a.unlocked, ...b.unlocked])],
    credits: Math.max(a.credits ?? 0, b.credits ?? 0),
    solved,
    awarded: [...new Set([...a.awarded, ...b.awarded])].slice(-300),
    unlockAll: !!(a.unlockAll || b.unlockAll),
  };
}

function load(): ProgressData {
  const found = readAll(KEY)
    .map(parse)
    .filter((d): d is ProgressData => d !== null);
  if (!found.length) return fresh();
  return found.reduce(merge);
}

/**
 * The starter set is free by definition, so a record saved before a game joined it still
 * gets that game — widening the set must reach players who already have progress, not just
 * new ones. Never removes anything.
 */
function withStarters(p: ProgressData): ProgressData {
  if (STARTER_GAMES.every((g) => p.unlocked.includes(g))) return p;
  return { ...p, unlocked: [...new Set([...p.unlocked, ...STARTER_GAMES])] };
}

function fresh(): ProgressData {
  return {
    version: VERSION,
    unlocked: [...STARTER_GAMES],
    credits: 0,
    solved: {},
    awarded: [],
    unlockAll: false,
  };
}

/** Order-independent fingerprint, to tell a real change from a re-read of the same record. */
function signature(p: ProgressData): string {
  const solved = Object.keys(p.solved)
    .sort()
    .map((k) => `${k}=${p.solved[k]}`)
    .join(',');
  return [
    p.credits,
    [...p.unlocked].sort().join(','),
    solved,
    [...p.awarded].sort().join(','),
    p.unlockAll ? 1 : 0,
  ].join('|');
}

let cache: ProgressData | null = null;
/** Whether the player has changed anything since boot (see the upgrade handler). */
let touched = false;

export function getProgress(): ProgressData {
  if (!cache) cache = load();
  return cache;
}

/** Store `p` in every tier and tell everyone watching. */
function commit(p: ProgressData, notify: boolean): void {
  cache = p;
  writeItem(KEY, JSON.stringify(p));
  if (notify) for (const fn of listeners) fn(p);
}

function save(p: ProgressData): void {
  touched = true;
  commit(p, true);
}

/**
 * The CrazyGames SDK initialises a moment *after* the app has already booted and read
 * progress from the fallback tiers, so the platform store arrives late. When it does:
 *
 * - if the player has already changed something this visit, that is the truth — push it up
 *   to the platform store (this is also what makes a *reset* stick);
 * - otherwise re-read across all tiers and merge, which both adopts progress saved on
 *   another device and seeds the platform store with progress that was, until now, only
 *   in `localStorage`.
 *
 * Either way we write through, so the new tier is never left empty, and we only notify
 * listeners when the record genuinely changed — the menu redraws itself on that.
 */
onStorageUpgrade(() => {
  const current = getProgress();
  const next = touched ? current : load();
  commit(next, signature(next) !== signature(current));
  const seen = loadSeen();
  if (seen.seen.length || seen.seenAll) writeItem(TUT_KEY, JSON.stringify(seen));
});

export function onProgressChange(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function isUnlocked(slug: string): boolean {
  const p = getProgress();
  return p.unlockAll || p.unlocked.includes(slug);
}

export function totalSolved(): number {
  return Object.values(getProgress().solved).reduce((a, b) => a + b, 0);
}

/** Spend a credit to unlock a game. Returns false when there is no credit to spend. */
export function unlockGame(slug: string): boolean {
  const p = getProgress();
  if (p.unlocked.includes(slug)) return true;
  if (p.credits <= 0) return false;
  save({ ...p, credits: p.credits - 1, unlocked: [...p.unlocked, slug] });
  return true;
}

/**
 * The puzzle just solved, waiting for the menu to say something about it.
 *
 * Deliberately in memory and not in the saved record: it is worth one celebration on the
 * way back to the collection, not a badge that survives a reload. {@link takeFreshSolve}
 * hands it over exactly once.
 */
let freshSolve: string | null = null;

/**
 * Which game the player has just finished something in, if they have not been back to the
 * collection since. Reading it clears it, so the card is congratulated once and the menu
 * is its ordinary self every time after.
 */
export function takeFreshSolve(): string | null {
  const slug = freshSolve;
  freshSolve = null;
  return slug;
}

/**
 * Record a hand-solved puzzle. Returns true if a credit was earned (first time this exact
 * puzzle is solved).
 */
export function recordSolve(slug: string, gameId: string): boolean {
  const p = getProgress();
  const key = `${slug}:${gameId}`;
  if (p.awarded.includes(key)) return false;
  const awarded = [...p.awarded, key].slice(-300);
  const solved = { ...p.solved, [slug]: (p.solved[slug] ?? 0) + 1 };
  save({ ...p, awarded, solved, credits: p.credits + 1 });
  freshSolve = slug;
  return true;
}

export function setUnlockAll(on: boolean): void {
  save({ ...getProgress(), unlockAll: on });
}

export function resetProgress(): void {
  save(fresh());
}

/** For tests and tooling: replace the whole record. */
export function setProgress(p: Partial<ProgressData>): void {
  save({ ...fresh(), ...p });
}

// ---------------------------------------------------------------- tutorials seen

const TUT_KEY = 'puzzlebox:tutorials';

interface TutorialsSeen {
  seen: string[];
  seenAll?: boolean;
}

/** Union across tiers: a tutorial seen anywhere counts as seen, same rule as {@link merge}. */
function loadSeen(): TutorialsSeen {
  const seen = new Set<string>();
  let seenAll = false;
  for (const raw of readAll(TUT_KEY)) {
    try {
      const d = JSON.parse(raw) as TutorialsSeen;
      if (d && Array.isArray(d.seen)) {
        for (const s of d.seen) seen.add(s);
        if (d.seenAll) seenAll = true;
      }
    } catch {
      /* ignore */
    }
  }
  return seenAll ? { seen: [...seen], seenAll: true } : { seen: [...seen] };
}

export function tutorialSeen(slug: string): boolean {
  const d = loadSeen();
  return !!d.seenAll || d.seen.includes(slug);
}

export function markTutorialSeen(slug: string): void {
  const d = loadSeen();
  if (!d.seen.includes(slug)) d.seen.push(slug);
  writeItem(TUT_KEY, JSON.stringify(d));
}
