/**
 * Galaxies generator.
 *
 * Visit every position of the doubled grid in random order. At a tile or an edge, try to
 * fold the one or two tiles there into a neighbouring region: either the region can grow
 * symmetrically to take them (their mirror images are free too), or its dot can slide to
 * the new centre of gravity so that the enlarged region is symmetric about the new spot.
 * When nothing wants the tiles, drop a new dot there. Every tile ends up in a region, so
 * the result is a valid tiling; it is kept only if the solver rates it at the requested
 * difficulty (a too-easy Unreasonable puzzle is tolerated after many attempts, as in the
 * original).
 */
import type { Random } from '../../framework/rng';
import type { NewDesc } from '../../framework/types';
import {
  checkComplete,
  edgesFromAssoc,
  encodeDesc,
  encodeEdgeBits,
  inGrid,
  inUI,
  isEdgePos,
  isTilePos,
  isVertexPos,
  makeLayout,
  opposite,
  touchingTiles,
} from './board';
import type { Grid } from './board';
import { Work, solverState } from './solver';

export interface GalaxiesParams {
  w: number;
  h: number;
  difficulty: number;
}

/** Attempts before a too-easy puzzle is accepted at a harder difficulty setting. */
const MAX_TRIES = 50;

/** Region-growing scratch state. */
class Gen implements Grid {
  readonly sx: number;
  readonly sy: number;
  readonly n: number;
  readonly dot: Uint8Array;
  readonly assoc: Int32Array;
  /** Number of tiles belonging to the dot at each position. */
  readonly nassoc: Int32Array;

  constructor(
    readonly w: number,
    readonly h: number,
  ) {
    this.sx = 2 * w + 1;
    this.sy = 2 * h + 1;
    this.n = this.sx * this.sy;
    this.dot = new Uint8Array(this.n);
    this.assoc = new Int32Array(this.n).fill(-1);
    this.nassoc = new Int32Array(this.n);
  }

  setAssoc(tile: number, d: number): void {
    const cur = this.assoc[tile];
    if (cur >= 0) this.nassoc[cur]--;
    this.assoc[tile] = d;
    this.nassoc[d]++;
  }

  x(i: number): number {
    return i % this.sx;
  }
  y(i: number): number {
    return (i - (i % this.sx)) / this.sx;
  }
}

/**
 * A new dot may go at `p` when nothing is nearby: no dot within its "halo" (the box of
 * positions it would share a tile with) and none of the tiles it touches is taken.
 */
function dotIsPossible(g: Gen, p: number): boolean {
  const x = g.x(p);
  const y = g.y(p);
  if (!inUI(g, x, y)) return false;
  let bx = 1;
  let by = 1;
  if (isVertexPos(x, y)) bx = by = 2;
  else if (isEdgePos(x, y)) {
    if ((x & 1) === 0) bx = 2;
    else by = 2;
  }
  for (let dy = -by; dy <= by; dy++) {
    for (let dx = -bx; dx <= bx; dx++) {
      const nx = x + dx;
      const ny = y + dy;
      if (!inGrid(g, nx, ny)) continue;
      const q = ny * g.sx + nx;
      if (isTilePos(nx, ny) && g.assoc[q] >= 0) return false;
      if ((dx !== 0 || dy !== 0) && g.dot[q]) return false;
    }
  }
  return true;
}

/**
 * Give the tiles `toadd` to dot `d`: grow the region if their mirror images are free,
 * otherwise try moving the dot to the new centre of gravity. Returns whether it worked.
 */
function expandOrMove(g: Gen, d: number, toadd: number[]): boolean {
  let canExpand = true;
  for (const t of toadd) {
    const o = opposite(g, t, d);
    if (o < 0 || g.assoc[o] >= 0) {
      canExpand = false;
      break;
    }
  }
  if (canExpand) {
    for (const t of toadd) {
      g.setAssoc(t, d);
      g.setAssoc(opposite(g, t, d), d);
    }
    return true;
  }

  const nnew = g.nassoc[d] + toadd.length;
  let cx = g.x(d) * g.nassoc[d];
  let cy = g.y(d) * g.nassoc[d];
  for (const t of toadd) {
    cx += g.x(t);
    cy += g.y(t);
  }
  if (cx % nnew !== 0 || cy % nnew !== 0) return false;
  const nd = (cy / nnew) * g.sx + cx / nnew;
  if (nd !== d && g.dot[nd]) return false;
  // Every tile of the region, and every new tile, needs a free (or own) mirror image
  // about the new centre.
  const mine: number[] = [];
  for (let t = 0; t < g.n; t++) if (g.assoc[t] === d) mine.push(t);
  for (const t of [...mine, ...toadd]) {
    const o = opposite(g, t, nd);
    if (o < 0) return false;
    const a = g.assoc[o];
    if (a >= 0 && a !== d) return false;
  }
  for (const t of toadd) {
    g.setAssoc(t, d);
    mine.push(t);
  }
  g.dot[d] = 0;
  g.dot[nd] = 1;
  for (const t of mine) {
    g.setAssoc(t, nd);
    g.setAssoc(opposite(g, t, nd), nd);
  }
  return true;
}

/** Try to hand the free tiles in the block (x1,y1)–(x2,y2) to one of the regions around it. */
function tryBlock(
  g: Gen,
  rng: Random,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  maxsz: number,
): boolean {
  if (!inGrid(g, x1, y1) || !inGrid(g, x2, y2)) return false;
  const toadd: number[] = [];
  for (let y = y1; y <= y2; y += 2) {
    for (let x = x1; x <= x2; x += 2) {
      const t = y * g.sx + x;
      if (g.assoc[t] >= 0) return false;
      toadd.push(t);
    }
  }
  const outside: number[] = [];
  const add = (x: number, y: number) => {
    if (inGrid(g, x, y)) outside.push(y * g.sx + x);
  };
  for (let x = x1; x <= x2; x += 2) {
    add(x, y1 - 2);
    add(x, y2 + 2);
  }
  for (let y = y1; y <= y2; y += 2) {
    add(x1 - 2, y);
    add(x2 + 2, y);
  }
  rng.shuffle(outside);
  for (const o of outside) {
    const d = g.assoc[o];
    if (d < 0) continue;
    if (g.nassoc[d] >= maxsz) continue;
    if (expandOrMove(g, d, toadd)) return true;
  }
  return false;
}

/** One complete tiling of the grid into symmetric regions, or null if it went wrong. */
function generatePass(w: number, h: number, rng: Random, scratch: number[]): Gen | null {
  const g = new Gen(w, h);
  // Regions are kept to roughly 2·√area tiles so they stay interesting.
  const maxsz = Math.floor(Math.sqrt(w * h)) * 2;
  rng.shuffle(scratch);
  for (let i = 0; i < scratch.length; i++) {
    const p = scratch[i];
    const x = g.x(p);
    const y = g.y(p);
    const edge = isEdgePos(x, y);
    if (!isVertexPos(x, y)) {
      let x1 = x;
      let y1 = y;
      let x2 = x;
      let y2 = y;
      if (edge) {
        if ((x & 1) === 0) {
          x1--;
          x2++;
        } else {
          y1--;
          y2++;
        }
      }
      if (tryBlock(g, rng, x1, y1, x2, y2, maxsz)) continue;
    }
    // Only every other edge is allowed to seed a dot, or the grid fills with tiny regions.
    if (edge && i % 2 === 1) continue;
    if (dotIsPossible(g, p)) {
      g.dot[p] = 1;
      for (const t of touchingTiles(g, p)) g.setAssoc(t, p);
    }
  }
  for (let i = 0; i < g.n; i++) {
    if (isTilePos(g.x(i), g.y(i)) && g.assoc[i] < 0) return null;
  }
  return g;
}

export function generate(p: GalaxiesParams, rng: Random): NewDesc {
  const { w, h } = p;
  const scratch: number[] = [];
  for (let i = 0; i < (2 * w + 1) * (2 * h + 1); i++) scratch.push(i);
  for (let tries = 1; ; tries++) {
    const g = generatePass(w, h, rng, scratch);
    if (!g) continue;
    const L = makeLayout(w, h, g.dot, new Uint8Array(g.n));
    const edges = edgesFromAssoc(L, g.assoc);
    if (!checkComplete(L, edges).complete) continue;
    const diff = solverState(new Work(L), p.difficulty);
    if (diff !== p.difficulty && (diff > p.difficulty || tries < MAX_TRIES)) continue;
    return { desc: encodeDesc(L), aux: 'S' + encodeEdgeBits(L, edges) };
  }
}
