import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  countDominoes,
  decodeLayout,
  dominoIndex,
  gridSize,
  isComplete,
  parseDesc,
  placementOf,
  placementSquares,
  placementsAt,
} from './board';
import { generate } from './generator';
import type { DominosaParams } from './generator';
import {
  DIFFICULTY_LETTERS,
  DIFFICULTY_NAMES,
  DIFF_AMBIGUOUS,
  DIFF_BASIC,
  DIFF_EXTREME,
  DIFF_HARD,
  search,
} from './solver';
import { tutorial } from './tutorial';
import { achievements } from './achievements';
import help from './help.md?raw';

export type { DominosaParams };

export interface DominosaState {
  n: number;
  w: number;
  h: number;
  /** The number in each square, row-major. Shared between states. */
  numbers: readonly number[];
  /** `partner[i]` is the other square of the domino laid on `i`, or `i` when bare. */
  partner: Int32Array;
  /** 1 where the player has marked a placement (see board.ts) as "no domino here". */
  edges: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

/**
 * The keyboard cursor lives on a (2w-1) × (2h-1) lattice: even coordinates are square
 * centres, odd ones are the boundaries between squares. It is only "useful" — Enter and
 * Space do something — when exactly one coordinate is odd, i.e. it sits on an edge.
 */
export interface DominosaUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
/** Beyond this the chance of a random grid having a unique solution gets too small. */
const MAX_N = 12;
/** Hard and Extreme puzzles are rarer still, and their solver passes are dearer. */
const MAX_N_HARD = 10;
/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it on the smallest board the Type menu
 * offers, and goes up the ladder when they want to.
 */
const DEFAULTS: DominosaParams = { n: 3, diff: DIFF_BASIC };
const MOVE_RE = /^([DE])(\d+),(\d+)$/;

function border(t: number): number {
  return Math.round(t * 0.3);
}

function makeState(
  base: Pick<DominosaState, 'n' | 'w' | 'h' | 'numbers'>,
  partner: Int32Array,
  edges: Uint8Array,
  cheated: boolean,
): DominosaState {
  return {
    ...base,
    partner,
    edges,
    completed: isComplete(partner, base.numbers, base.n),
    cheated,
  };
}

/** The lattice cursor's placement, or -1 when it is not on an edge. */
function cursorPlacement(ui: DominosaUI, w: number, h: number): number {
  if (!((ui.cx ^ ui.cy) & 1)) return -1;
  const a = (ui.cy >> 1) * w + (ui.cx >> 1);
  const b = ((ui.cy + 1) >> 1) * w + ((ui.cx + 1) >> 1);
  return placementOf(a, b, w, h);
}

/** A bare square that no domino can reach any more: its neighbours are all taken or marked. */
function stranded(state: DominosaState, s: number): boolean {
  if (state.partner[s] !== s) return false;
  for (const p of placementsAt(s, state.w, state.h)) {
    if (state.edges[p]) continue;
    const [a, b] = placementSquares(p, state.w);
    const other = a === s ? b : a;
    if (state.partner[other] === other) return false;
  }
  return true;
}

function moveFor(letter: string, p: number, w: number): string {
  const [a, b] = placementSquares(p, w);
  return `${letter}${a},${b}`;
}

const game = defineGame<DominosaParams, DominosaState, DominosaUI>({
  id: 'dominosa',
  name: 'Dominosa',
  description: 'Find where the shuffled set of dominoes lies in a grid of numbers.',
  help,
  tutorial,
  achievements,
  presets: [3, 4, 5, 6, 7, 8, 9].map((n) => ({
    name: `Up to double-${n}`,
    params: { n, diff: DIFF_BASIC },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) => `${p.n}${full ? `d${DIFFICULTY_LETTERS[p.diff]}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(.*)$/.exec(str);
    if (!m) throw new Error(tx`expected a maximum number`);
    const n = parseInt(m[1], 10);
    const rest = m[2];
    let diff = DIFF_BASIC;
    const d = /d([a-z])/.exec(rest);
    if (d && DIFFICULTY_LETTERS.includes(d[1])) diff = DIFFICULTY_LETTERS.indexOf(d[1]);
    // The original collection's "don't ensure a unique solution" flag.
    else if (rest.includes('a')) diff = DIFF_AMBIGUOUS;
    return { n, diff };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.n)) return tx`Maximum face number must be a whole number`;
    if (p.n < 1) return tx`Maximum face number must be at least one`;
    if (p.n > MAX_N) return tx`Maximum face number must be at most ${MAX_N}`;
    if (full) {
      if (!Number.isInteger(p.diff) || p.diff < 0 || p.diff >= DIFFICULTY_NAMES.length)
        return tx`Unknown difficulty level`;
      if ((p.diff === DIFF_HARD || p.diff === DIFF_EXTREME) && p.n > MAX_N_HARD)
        return tx`Hard and Extreme puzzles are limited to a maximum number of ${MAX_N_HARD}`;
    }
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Maximum number on dominoes', value: String(p.n) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.diff },
    ];
  },
  customParams(items) {
    const s = (items[0] as { value: string }).value.trim();
    return {
      n: /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN,
      diff: (items[1] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.n);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const numbers = parseDesc(desc, p.n) as number[];
    const { w, h } = gridSize(p.n);
    const partner = new Int32Array(w * h);
    for (let i = 0; i < partner.length; i++) partner[i] = i;
    return {
      ...makeState({ n: p.n, w, h, numbers }, partner, new Uint8Array(2 * w * h), false),
      completed: false,
    };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const { w, h, n, numbers } = curr;
    let placements: number[] | null = null;
    if (aux) {
      const layout = decodeLayout(aux, w, h);
      if (layout) {
        const partner = new Int32Array(w * h);
        for (let i = 0; i < partner.length; i++) partner[i] = i;
        for (const p of layout) {
          const [a, b] = placementSquares(p, w);
          partner[a] = b;
          partner[b] = a;
        }
        if (isComplete(partner, numbers, n)) placements = layout;
      }
    }
    if (!placements) {
      const sols = search(numbers, n, 1);
      if (!sols.length) throw new Error(tx`No solution exists for this puzzle`);
      placements = sols[0];
    }
    return 'S' + placements.map((p) => `;${moveFor('D', p, w)}`).join('');
  },

  textFormat(s) {
    const { w, h, numbers, partner } = s;
    const width = String(s.n).length;
    const rows: string[] = [];
    for (let y = 0; y < h; y++) {
      let row = '';
      let below = '';
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        row += String(numbers[i]).padStart(width, ' ');
        row += x + 1 < w ? (partner[i] === i + 1 ? '-' : ' ') : '';
        below += (partner[i] === i + w ? '|' : ' ').padStart(width, ' ') + (x + 1 < w ? ' ' : '');
      }
      rows.push(row);
      if (y + 1 < h) rows.push(below.trimEnd());
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false }),
  changedState(ui, oldState, newState) {
    if (!oldState.completed && newState.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, partner } = state;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const idle = ui.cursorVisible ? '' : null;
      ui.cursorVisible = false;
      const t = ds.tileSize;
      const bd = border(t);
      const tx = Math.floor((mx - bd) / t);
      const ty = Math.floor((my - bd) / t);
      if (tx < 0 || tx >= w || ty < 0 || ty >= h) return idle;
      // Which edge of the square is the click nearest to?
      const dx = 2 * (mx - (bd + tx * t)) - t;
      const dy = 2 * (my - (bd + ty * t)) - t;
      const s = ty * w + tx;
      let p = -1;
      if (Math.abs(dx) > Math.abs(dy)) {
        if (dx < 0 && tx > 0) p = placementOf(s - 1, s, w, h);
        else if (dx > 0 && tx + 1 < w) p = placementOf(s, s + 1, w, h);
      } else if (Math.abs(dy) > Math.abs(dx)) {
        if (dy < 0 && ty > 0) p = placementOf(s - w, s, w, h);
        else if (dy > 0 && ty + 1 < h) p = placementOf(s, s + w, w, h);
      }
      if (p < 0) return idle;
      const [a, c] = placementSquares(p, w);
      // A "no domino" mark makes no sense beside a domino.
      if (b === RIGHT_BUTTON && (partner[a] !== a || partner[c] !== c)) return idle;
      return moveFor(b === RIGHT_BUTTON ? 'E' : 'D', p, w);
    }
    if (isCursorMove(b)) {
      const pos = moveCursor(b, ui.cx, ui.cy, 2 * w - 1, 2 * h - 1);
      ui.cx = pos.x;
      ui.cy = pos.y;
      ui.cursorVisible = true;
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const p = cursorPlacement(ui, w, h);
      if (p < 0) return null;
      const [a, c] = placementSquares(p, w);
      if (b === CURSOR_SELECT2 && (partner[a] !== a || partner[c] !== c)) return null;
      return moveFor(b === CURSOR_SELECT2 ? 'E' : 'D', p, w);
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h } = state;
    const partner = state.partner.slice();
    const edges = state.edges.slice();
    let cheated = state.cheated;
    for (const part of move.split(';')) {
      if (part === 'S') {
        cheated = true;
        for (let i = 0; i < partner.length; i++) partner[i] = i;
        edges.fill(0);
        continue;
      }
      const m = MOVE_RE.exec(part);
      if (!m) return null;
      const a = parseInt(m[2], 10);
      const b = parseInt(m[3], 10);
      const p = placementOf(a, b, w, h);
      if (p < 0 || a >= b) return null;
      if (m[1] === 'D') {
        if (partner[a] === b) {
          partner[a] = a;
          partner[b] = b;
          continue;
        }
        // Anything the new domino overlaps goes, and so do marks touching its squares.
        for (const s of [a, b]) {
          const other = partner[s];
          if (other !== s) partner[other] = other;
          for (const q of placementsAt(s, w, h)) edges[q] = 0;
        }
        partner[a] = b;
        partner[b] = a;
      } else {
        if (partner[a] !== a || partner[b] !== b) return null;
        edges[p] ^= 1;
      }
    }
    return makeState(state, partner, edges, cheated);
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const { w, h } = gridSize(p.n);
    const bd = border(t);
    return { w: w * t + 2 * bd, h: h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, n, numbers, partner, edges } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const used = countDominoes(partner, numbers, n);

    dr.rect(bd, bd, w * t, h * t, 'paper');
    for (let x = 1; x < w; x++) dr.line(bd + x * t, bd, bd + x * t, bd + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(bd, bd + y * t, bd + w * t, bd + y * t, 'faint', 1.2);

    // Dominoes: a rounded tile over both squares, red when the same domino is laid twice.
    const gutter = Math.max(1.5, t / 16);
    const lw = Math.max(1.6, t * 0.055);
    for (let i = 0; i < partner.length; i++) {
      const j = partner[i];
      if (j <= i) continue;
      const clash = used[dominoIndex(numbers[i], numbers[j])] > 1;
      const x = bd + (i % w) * t + gutter;
      const y = bd + Math.floor(i / w) * t + gutter;
      const dw = (j === i + 1 ? 2 * t : t) - 2 * gutter;
      const dh = (j === i + w ? 2 * t : t) - 2 * gutter;
      const fill = flash ? 'highlight' : clash ? dr.withAlpha('error', 0.16) : 'shade';
      dr.roundRect(x, y, dw, dh, t / 8, fill, clash ? 'error' : 'ink', {
        width: clash ? lw * 1.3 : lw,
        seed: i,
      });
    }

    // "No domino here" marks: a pencil bar along the boundary between the two squares.
    const inset = t * 0.14;
    const ew = Math.max(2, t * 0.07);
    for (let p = 0; p < edges.length; p++) {
      if (!edges[p]) continue;
      const [a, b] = placementSquares(p, w);
      const ax = bd + (a % w) * t;
      const ay = bd + Math.floor(a / w) * t;
      if (b === a + 1)
        dr.line(ax + t, ay + inset, ax + t, ay + t - inset, 'pencil', ew, { seed: p });
      else dr.line(ax + inset, ay + t, ax + t - inset, ay + t, 'pencil', ew, { seed: p });
    }

    for (let i = 0; i < numbers.length; i++) {
      const colour = flash ? 'ok' : stranded(state, i) ? 'error' : 'ink';
      dr.text(bd + (i % w) * t + t / 2, bd + Math.floor(i / w) * t + t / 2, String(numbers[i]), {
        size: t * 0.5,
        colour,
        maxWidth: t * 0.8,
      });
    }
    dr.rectOutline(bd, bd, w * t, h * t, 'ink', { width: 2.4 });

    if (ui.cursorVisible) {
      const p = cursorPlacement(ui, w, h);
      if (p >= 0) {
        // On an edge: outline the domino that Enter would lay.
        const [a, b] = placementSquares(p, w);
        const x = bd + (a % w) * t;
        const y = bd + Math.floor(a / w) * t;
        const cw = b === a + 1 ? 2 * t : t;
        const ch = b === a + w ? 2 * t : t;
        const pad = t * 0.1;
        dr.cursor(x + pad, y + pad, cw - 2 * pad, ch - 2 * pad);
      } else {
        // On a square centre or a corner: a small marker, since nothing can happen here.
        const cx = bd + ((ui.cx + 1) * t) / 2;
        const cy = bd + ((ui.cy + 1) * t) / 2;
        const r = t / 4;
        dr.cursor(cx - r, cy - r, 2 * r, 2 * r, 'pencil', 1.6);
      }
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // Half of the solution of the puzzle the menu thumbnail shows (seed `thumbnail:dominosa`,
  // up to double-3), so the preview has some dominoes on it. A unit test keeps these in
  // step with the generator.
  thumbnailMoves: ['D0,5', 'D1,6', 'D2,3', 'D4,9', 'D7,12'],
});

export default game;
