/**
 * Unequal puzzle generation.
 *
 * A random latin square is the answer. Clues are then *assembled*: starting from an empty
 * grid (Adjacent mode: with every adjacency bar already in place, since bars are never
 * hidden) the solver of the requested difficulty runs, and while it cannot finish, the
 * clue it would find most informative — a sign or digit on the cell with the most
 * candidates left — is added. Once solvable, every clue is tried for removal in a random
 * order and kept only if the puzzle stops being solvable without it. Finally the puzzle
 * must defeat the solver one level down, otherwise a fresh square is tried; after many
 * failures the generator settles for what it has.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import type { NewDesc } from '../../framework/types';
import { DIRS, cubeIndex, encodeDesc, encodeSolution } from './board';
import type { Puzzle } from './board';
import { DIFF_RECURSIVE, solvePuzzle } from './solver';
import type { SolveBudget } from './latin';

export interface UnequalParams {
  order: number;
  diff: number;
  adjacent: boolean;
}

/** Attempts at the requested difficulty before accepting an easier puzzle. */
const MAX_TRIES = 50;
/**
 * Guesses one uniqueness check may make while stripping a Recursive (Extreme) puzzle.
 * Up to 7×7 a check needs a few dozen; on a sparse 9×9 one can run to hundreds of
 * thousands, which froze the page for minutes (a 9×9 Adjacent took over three). A check
 * that runs out keeps its clue, so the puzzle is still proven unique and still needs
 * guessing — it just keeps a clue it might have spared. 9×9 now deals in about a second.
 */
const STRIP_BUDGET = 200;

/**
 * A uniformly random-looking latin square of order `o`, built row by row. Each new row
 * is a perfect matching between columns and the digits still unused in them (found by
 * augmenting paths in random order); the latin-rectangle extension theorem guarantees
 * such a matching always exists, so this never backtracks.
 */
export function generateLatin(o: number, rng: Random): Uint8Array {
  const sq = new Uint8Array(o * o);
  const rows = rng.shuffle([...Array(o).keys()]);
  const used = new Uint8Array(o * o); // used[c·o + n − 1]: digit n already in column c
  const matchCol = new Int8Array(o); // digit → column in the current row
  const visited = new Uint8Array(o);
  const cols = [...Array(o).keys()];
  const digits = [...Array(o).keys()];
  const augment = (c: number): boolean => {
    for (const n of digits) {
      if (used[c * o + n] || visited[n]) continue;
      visited[n] = 1;
      if (matchCol[n] < 0 || augment(matchCol[n])) {
        matchCol[n] = c;
        return true;
      }
    }
    return false;
  };
  for (const r of rows) {
    rng.shuffle(cols);
    rng.shuffle(digits);
    matchCol.fill(-1);
    for (const c of cols) {
      visited.fill(0);
      if (!augment(c)) throw new Error(tx`latin rectangle could not be extended`);
    }
    for (let n = 0; n < o; n++) {
      sq[r * o + matchCol[n]] = n + 1;
      used[matchCol[n] * o + n] = 1;
    }
  }
  return sq;
}

/** Working copy of a puzzle under construction. */
interface Work {
  nums: Uint8Array;
  flags: Uint8Array;
}

/**
 * Clue codes: cell·5 + which, where which 0–3 is a sign in DIRS order and 4 is the digit.
 */
const DIGIT = 4;

function puzzleOf(order: number, adjacent: boolean, w: Work): Puzzle {
  return { order, adjacent, flags: w.flags, given: w.nums };
}

/** Add a clue if it is missing and correct for `latin`. Returns whether it could be. */
function placeClue(
  w: Work,
  order: number,
  adjacent: boolean,
  code: number,
  latin: Uint8Array,
  checkOnly: boolean,
): boolean {
  const loc = Math.floor(code / 5);
  const which = code % 5;
  if (which === DIGIT) {
    if (w.nums[loc]) return false;
    if (!checkOnly) w.nums[loc] = latin[loc];
    return true;
  }
  if (adjacent) return false; // bars are all present from the start
  const d = DIRS[which];
  if (w.flags[loc] & d.f) return false;
  const x = loc % order;
  const y = Math.floor(loc / order);
  const nx = x + d.dx;
  const ny = y + d.dy;
  if (nx < 0 || ny < 0 || nx >= order || ny >= order) return false;
  if (latin[loc] <= latin[ny * order + nx]) return false;
  if (!checkOnly) w.flags[loc] |= d.f;
  return true;
}

/** Take a clue away. Returns whether there was one. */
function removeClue(w: Work, adjacent: boolean, code: number): boolean {
  const loc = Math.floor(code / 5);
  const which = code % 5;
  if (which === DIGIT) {
    if (!w.nums[loc]) return false;
    w.nums[loc] = 0;
    return true;
  }
  if (adjacent) return false;
  if (!(w.flags[loc] & DIRS[which].f)) return false;
  w.flags[loc] &= ~DIRS[which].f;
  return true;
}

/**
 * The most useful clue to add next: one on the cell with the most candidates left after
 * the last solver run, preferring cells with fewer signs already. Signs are considered
 * before digits so ties favour them.
 */
function bestClue(
  copy: Work,
  order: number,
  adjacent: boolean,
  cube: Uint8Array,
  scratch: number[],
  latin: Uint8Array,
): number {
  let maxposs = 0;
  let minclues = 5;
  let best = -1;
  for (let i = scratch.length - 1; i >= 0; i--) {
    if (!placeClue(copy, order, adjacent, scratch[i], latin, true)) continue;
    const loc = Math.floor(scratch[i] / 5);
    const x = loc % order;
    const y = Math.floor(loc / order);
    let nposs = 0;
    for (let n = 1; n <= order; n++) if (cube[cubeIndex(order, x, y, n)]) nposs++;
    let nclues = 0;
    for (const d of DIRS) if (copy.flags[loc] & d.f) nclues++;
    if (nposs > maxposs || (nposs === maxposs && nclues < minclues)) {
      best = i;
      maxposs = nposs;
      minclues = nclues;
    }
  }
  if (best < 0) throw new Error(tx`no clue left to place`);
  return best;
}

/** Add clues until the solver at `difficulty` finishes the puzzle. */
function assemble(
  w: Work,
  order: number,
  adjacent: boolean,
  scratch: number[],
  latin: Uint8Array,
  difficulty: number,
): void {
  // A guessing solver could "solve" with wrong digits, so assemble never guesses; the
  // stripping step, which does, makes the puzzle hard enough afterwards.
  if (difficulty >= DIFF_RECURSIVE) difficulty = DIFF_RECURSIVE - 1;
  const copy: Work = { nums: w.nums.slice(), flags: w.flags.slice() };
  for (;;) {
    // The solver fills in what it can, so digits it has deduced are never added as clues.
    const r = solvePuzzle(puzzleOf(order, adjacent, copy), copy.nums, difficulty);
    if (r.status === 1) break;
    if (r.status < 0) throw new Error(tx`inconsistent clues while assembling`);
    const best = bestClue(copy, order, adjacent, r.cube, scratch, latin);
    placeClue(w, order, adjacent, scratch[best], latin, false);
    placeClue(copy, order, adjacent, scratch[best], latin, false);
  }
}

/** Remove every clue the solver at `difficulty` can do without. */
function strip(
  w: Work,
  order: number,
  adjacent: boolean,
  scratch: number[],
  latin: Uint8Array,
  difficulty: number,
): void {
  for (const code of scratch) {
    if (!removeClue(w, adjacent, code)) continue;
    const copy: Work = { nums: w.nums.slice(), flags: w.flags.slice() };
    const budget: SolveBudget | undefined =
      difficulty >= DIFF_RECURSIVE ? { nodes: STRIP_BUDGET } : undefined;
    const r = solvePuzzle(puzzleOf(order, adjacent, copy), copy.nums, difficulty, budget);
    if (r.status !== 1) {
      placeClue(w, order, adjacent, code, latin, false);
    }
  }
}

/** Every adjacency bar implied by the answer (Adjacent mode shows them all). */
export function adjacentFlags(order: number, latin: Uint8Array): Uint8Array {
  const flags = new Uint8Array(order * order);
  for (let y = 0; y < order; y++) {
    for (let x = 0; x < order; x++) {
      const i = y * order + x;
      if (x < order - 1 && Math.abs(latin[i] - latin[i + 1]) === 1) {
        flags[i] |= DIRS[1].f;
        flags[i + 1] |= DIRS[3].f;
      }
      if (y < order - 1 && Math.abs(latin[i] - latin[i + order]) === 1) {
        flags[i] |= DIRS[2].f;
        flags[i + order] |= DIRS[0].f;
      }
    }
  }
  return flags;
}

export function generate(params: UnequalParams, rng: Random): NewDesc {
  const { order: o, adjacent, diff } = params;
  const n2 = o * o;
  // Digit clues first, then the four signs of every cell; each group is shuffled on its
  // own so digits are always considered for removal before signs.
  const digitCodes: number[] = [];
  const signCodes: number[] = [];
  for (let i = 0; i < n2; i++) digitCodes.push(i * 5 + DIGIT);
  for (let which = 3; which >= 0; which--)
    for (let i = 0; i < n2; i++) signCodes.push(i * 5 + which);

  let latin: Uint8Array;
  let w: Work;
  for (let tries = 1; ; tries++) {
    latin = generateLatin(o, rng);
    rng.shuffle(digitCodes);
    rng.shuffle(signCodes);
    const scratch = digitCodes.concat(signCodes);
    w = {
      nums: new Uint8Array(n2),
      flags: adjacent ? adjacentFlags(o, latin) : new Uint8Array(n2),
    };
    assemble(w, o, adjacent, scratch, latin, diff);
    strip(w, o, adjacent, scratch, latin, diff);
    if (diff === 0) break;
    // Too easy if the next level down can already solve it.
    const copy: Work = { nums: w.nums.slice(), flags: w.flags.slice() };
    if (solvePuzzle(puzzleOf(o, adjacent, copy), copy.nums, diff - 1).status !== 1) break;
    // Give up on the requested level eventually and hand over the easier puzzle.
    if (tries >= MAX_TRIES) break;
  }
  return { desc: encodeDesc(o, w.nums, w.flags), aux: encodeSolution(latin) };
}
