/**
 * Deductive Tents solver.
 *
 * The solver keeps, besides the grid, a set of *links*: tree/tent pairs that are known to
 * belong together. Because generated puzzles have a unique tree–tent matching, that
 * matching can always be recovered by pairing off any tent with a single unlinked tree
 * next to it and vice versa (see the proof in the original's source). Deductions:
 *
 *  - **Links only** (`diff` -1, used to grade Easy): pair tents with their only tree.
 *  - **Easy**: a blank next to no unlinked tree, or touching a tent, is grass; a tree
 *    with a single possible tent square gets its tent there; and for every row and column
 *    all placements of the remaining tents among the blanks are enumerated (rejecting
 *    touching pairs) to find squares that come out the same every time.
 *  - **Tricky** adds three things: a tree whose two possible squares sit diagonally
 *    rules out the square adjacent to both; the row/column enumeration also records
 *    squares in the *neighbouring* lines that every placement makes grass; and a
 *    bipartite matching of the unlinked trees against their candidate squares detects an
 *    impossible position and any square that every perfect matching must use.
 *
 * `solve` returns `IMPOSSIBLE`, `SOLVED` (grid and links complete) or `STUCK`.
 */
import { DIRS4, DIRS8, inBounds } from '../../framework/grid';
import { BLANK, NONTENT, TENT, TREE, isComplete } from './board';
import { augment, maxMatching } from './matching';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Tricky'];
export const DIFFICULTY_CHARS = 'et';

export const IMPOSSIBLE = 0;
export const SOLVED = 1;
export const STUCK = 2;

/** Link directions: 0 = none, then up, left, right, down (so opposite(d) = 5 - d). */
const LDX = [0, 0, -1, 1, 0];
const LDY = [0, -1, 0, 0, 1];
const opposite = (d: number) => 5 - d;
/** A placeholder meaning "no information yet" in the per-line invariance rows. */
const MAGIC = 4;

export interface SolveResult {
  result: number;
  /** The grid as far as it got: trees, tents and grass, blanks where undecided. */
  grid: Uint8Array;
  /** Link direction per cell (0 = unlinked). */
  links: Int8Array;
}

class Solver {
  readonly n: number;
  readonly grid: Uint8Array;
  readonly links: Int8Array;
  private readonly locs: number[] = [];
  private readonly mrow: Uint8Array;
  private readonly trow: Uint8Array;
  /**
   * Per row/column, its contents when `deduceLine` last finished with it. The deduction
   * reads nothing but the line itself, and everything it found has already been written,
   * so a line that has not changed since would find nothing new and is skipped. (Large
   * custom grids re-scan every line after each small step elsewhere; without this a 20×20
   * Easy deal, which tries hundreds of grids, froze the page for several seconds.)
   */
  private readonly lineSeen: (string | null)[];

  constructor(
    readonly w: number,
    readonly h: number,
    start: Uint8Array,
    readonly numbers: number[],
    readonly diff: number,
    readonly useMatching: boolean,
  ) {
    this.n = w * h;
    this.grid = start.slice();
    this.links = new Int8Array(this.n);
    const len = Math.max(w, h);
    this.mrow = new Uint8Array(3 * len);
    this.trow = new Uint8Array(3 * len);
    this.lineSeen = new Array<string | null>(w + h).fill(null);
  }

  private link(i: number, d: number): void {
    const j = (Math.floor(i / this.w) + LDY[d]) * this.w + (i % this.w) + LDX[d];
    this.links[i] = d;
    this.links[j] = opposite(d);
  }

  /** Neighbour index of cell `i` in link direction `d`, or -1 when off the grid. */
  private step(i: number, d: number): number {
    const x = (i % this.w) + LDX[d];
    const y = Math.floor(i / this.w) + LDY[d];
    return inBounds(x, y, this.w, this.h) ? y * this.w + x : -1;
  }

  run(): number {
    const { grid, links, n, diff } = this;
    for (;;) {
      // Any tent with exactly one unlinked tree beside it belongs to that tree.
      let progress = false;
      for (let i = 0; i < n; i++) {
        if (grid[i] !== TENT || links[i]) continue;
        let found = 0;
        let count = 0;
        for (let d = 1; d <= 4; d++) {
          const j = this.step(i, d);
          if (j >= 0 && grid[j] === TREE && !links[j]) {
            found = d;
            count++;
          }
        }
        if (count === 0) return IMPOSSIBLE;
        if (count === 1) {
          this.link(i, found);
          progress = true;
        }
      }
      if (progress) continue;
      if (diff < 0) break;

      // A blank next to no unlinked tree can never be a tent.
      for (let i = 0; i < n; i++) {
        if (grid[i] !== BLANK) continue;
        let possible = false;
        for (let d = 1; d <= 4 && !possible; d++) {
          const j = this.step(i, d);
          if (j >= 0 && grid[j] === TREE && !links[j]) possible = true;
        }
        if (!possible) {
          grid[i] = NONTENT;
          progress = true;
        }
      }
      if (progress) continue;

      // A blank touching a tent (even diagonally) is grass.
      for (let i = 0; i < n; i++) {
        if (grid[i] !== BLANK) continue;
        const x = i % this.w;
        const y = Math.floor(i / this.w);
        for (const [dx, dy] of DIRS8) {
          const nx = x + dx;
          const ny = y + dy;
          if (inBounds(nx, ny, this.w, this.h) && grid[ny * this.w + nx] === TENT) {
            grid[i] = NONTENT;
            progress = true;
            break;
          }
        }
      }
      if (progress) continue;

      // A tree with a single candidate square (blank or unlinked tent) gets its tent there.
      for (let i = 0; i < n; i++) {
        if (grid[i] !== TREE || links[i]) continue;
        let d1 = 0;
        let d2 = 0;
        let count = 0;
        for (let d = 1; d <= 4; d++) {
          const j = this.step(i, d);
          if (j < 0) continue;
          if (grid[j] === BLANK || (grid[j] === TENT && !links[j])) {
            if (d1) d2 = d;
            else d1 = d;
            count++;
          }
        }
        if (count === 0) return IMPOSSIBLE;
        if (count === 1) {
          grid[this.step(i, d1)] = TENT;
          this.link(i, d1);
          progress = true;
        } else if (
          count === 2 &&
          diff >= DIFF_TRICKY &&
          LDX[d1] !== LDX[d2] &&
          LDY[d1] !== LDY[d2]
        ) {
          // Two candidates around a corner: the square adjacent to both cannot be a tent,
          // whichever of them the tree ends up with.
          const x = (i % this.w) + LDX[d1] + LDX[d2];
          const y = Math.floor(i / this.w) + LDY[d1] + LDY[d2];
          const j = y * this.w + x;
          if (grid[j] === BLANK) {
            grid[j] = NONTENT;
            progress = true;
          }
        }
      }
      if (progress) continue;

      for (let line = 0; line < this.w + this.h; line++) {
        const r = this.deduceLine(line);
        if (r === IMPOSSIBLE) return IMPOSSIBLE;
        if (r) progress = true;
      }
      if (progress) continue;

      if (diff >= DIFF_TRICKY && this.useMatching) {
        const r = this.deduceMatching();
        if (r === IMPOSSIBLE) return IMPOSSIBLE;
        if (r) progress = true;
      }
      if (!progress) break;
    }

    for (let i = 0; i < n; i++) {
      if (grid[i] === BLANK) return STUCK;
      if (grid[i] !== NONTENT && !links[i]) return STUCK;
    }
    return SOLVED;
  }

  /**
   * Enumerate every way of placing the tents still missing from one row or column among
   * its blanks, and fix any square that comes out the same in all of them. Returns
   * IMPOSSIBLE, or whether anything was deduced.
   */
  private deduceLine(line: number): number | boolean {
    const { w, h, grid, diff, locs, mrow, trow } = this;
    let start: number;
    let step: number;
    let len: number;
    let start1 = -1;
    let start2 = -1;
    if (line < w) {
      start = line;
      step = w;
      len = h;
      if (line > 0) start1 = start - 1;
      if (line + 1 < w) start2 = start + 1;
    } else {
      const y = line - w;
      start = y * w;
      step = 1;
      len = w;
      if (y > 0) start1 = start - w;
      if (y + 1 < h) start2 = start + w;
    }
    // Only Tricky looks at what the placements imply for the neighbouring lines.
    if (diff < DIFF_TRICKY) start1 = start2 = -1;

    let key = '';
    for (let j = 0; j < len; j++) key += grid[start + j * step];
    if (this.lineSeen[line] === key) return false;

    let k = this.numbers[line];
    locs.length = 0;
    for (let j = 0; j < len; j++) {
      const v = grid[start + j * step];
      if (v === TENT) k--;
      else if (v === BLANK) locs.push(j);
    }
    const n = locs.length;
    if (k < 0 || k > n) return IMPOSSIBLE;
    if (n === 0) return false;

    // Only Tricky reads the neighbouring lines' part of the rows.
    const span = start1 < 0 && start2 < 0 ? len : 3 * len;
    mrow.fill(MAGIC, 0, span);
    // Enumerate the placements of k tents among the blanks, skipping touching pairs as
    // they arise rather than generating every combination and rejecting it afterwards.
    const isTent = new Uint8Array(n);
    const record = () => {
      trow.fill(MAGIC, 0, len);
      if (span > len) trow.fill(BLANK, len, span);
      for (let j = 0; j < n; j++) {
        trow[locs[j]] = isTent[j] ? TENT : NONTENT;
        if (isTent[j] && span > len) {
          for (let jj = locs[j] - 1; jj <= locs[j] + 1; jj++) {
            if (jj >= 0 && jj < len) trow[len + jj] = trow[2 * len + jj] = NONTENT;
          }
        }
      }
      live = 0;
      for (let j = 0; j < span; j++) {
        if (trow[j] === MAGIC) continue;
        if (mrow[j] === MAGIC || mrow[j] === trow[j]) mrow[j] = trow[j];
        else mrow[j] = BLANK;
        if (mrow[j] !== BLANK) live++;
      }
    };
    // Squares still agreed on by every placement so far; none left means nothing to find.
    let live = -1;
    // fit[j]: the most non-touching tents that locs[j..] can still take.
    const fit = new Int32Array(n + 2);
    for (let j = n - 1; j >= 0; j--) {
      const next = j + 1 < n && locs[j + 1] === locs[j] + 1 ? j + 2 : j + 1;
      fit[j] = Math.max(fit[j + 1], 1 + fit[next]);
    }
    const place = (from: number, left: number, prev: number) => {
      if (left === 0) {
        record();
        return;
      }
      for (let j = from; fit[j] >= left && live !== 0; j++) {
        if (prev >= 0 && locs[j] === locs[prev] + 1) continue;
        isTent[j] = 1;
        place(j + 1, left - 1, j);
        isTent[j] = 0;
      }
    };
    place(0, k, -1);

    if (mrow[locs[0]] === MAGIC) return IMPOSSIBLE;

    let progress = false;
    for (let j = 0; j < len; j++) {
      for (let which = 0; which < 3; which++) {
        const tstart = which === 0 ? start : which === 1 ? start1 : start2;
        if (tstart < 0) continue;
        const v = mrow[which * len + j];
        const pos = tstart + j * step;
        if (v !== MAGIC && v !== BLANK && grid[pos] === BLANK) {
          grid[pos] = v;
          progress = true;
        }
      }
    }
    key = '';
    for (let j = 0; j < len; j++) key += grid[start + j * step];
    this.lineSeen[line] = key;
    return progress;
  }

  /**
   * Match the unlinked trees against the squares that could still hold their tents. No
   * perfect matching means the position is impossible; a square that every perfect
   * matching uses must be a tent.
   */
  private deduceMatching(): number | boolean {
    const { grid, links, n } = this;
    const trees: number[] = [];
    const squareIndex = new Int32Array(n).fill(-1);
    const squares: number[] = [];
    for (let i = 0; i < n; i++) {
      if (grid[i] === TREE && !links[i]) trees.push(i);
      else if (grid[i] === BLANK || (grid[i] === TENT && !links[i])) {
        squareIndex[i] = squares.length;
        squares.push(i);
      }
    }
    if (trees.length === 0) return false;
    const adj = trees.map((i) => {
      const out: number[] = [];
      for (let d = 1; d <= 4; d++) {
        const j = this.step(i, d);
        if (j >= 0 && squareIndex[j] >= 0) out.push(squareIndex[j]);
      }
      return out;
    });
    const m = maxMatching(trees.length, squares.length, adj);
    if (m.size < trees.length) return IMPOSSIBLE;

    let progress = false;
    const seen = new Uint8Array(squares.length);
    const forbidden = new Uint8Array(squares.length);
    for (let l = 0; l < trees.length; l++) {
      const r = m.matchL[l];
      if (grid[squares[r]] !== BLANK) continue;
      // Take the square away and see whether its tree can be served some other way.
      m.matchL[l] = -1;
      m.matchR[r] = -1;
      forbidden[r] = 1;
      seen.fill(0);
      const alternative = augment(l, adj, m.matchL, m.matchR, seen, forbidden);
      forbidden[r] = 0;
      if (!alternative) {
        m.matchL[l] = r;
        m.matchR[r] = l;
        grid[squares[r]] = TENT;
        progress = true;
      }
    }
    return progress;
  }
}

/**
 * Solve from `start` (trees plus any given marks) at difficulty `diff` (-1, Easy or
 * Tricky). `useMatching` switches the Tricky matching deduction off, which is only useful
 * for measuring how often it is needed.
 */
export function solve(
  w: number,
  h: number,
  start: Uint8Array,
  numbers: number[],
  diff: number,
  useMatching = true,
): SolveResult {
  const s = new Solver(w, h, start, numbers, diff, useMatching);
  const result = s.run();
  return { result, grid: s.grid, links: s.links };
}

/** The lowest difficulty whose solver finishes the puzzle, or -1 if none does. */
export function grade(w: number, h: number, start: Uint8Array, numbers: number[]): number {
  for (let d = DIFF_EASY; d <= DIFF_TRICKY; d++) {
    if (solve(w, h, start, numbers, d).result === SOLVED) return d;
  }
  return -1;
}

/**
 * Find some solution by deduction plus backtracking, for puzzles the deductive solver
 * cannot finish (hand-typed IDs). `budget` bounds the number of guesses.
 */
export function solveWithGuesses(
  w: number,
  h: number,
  start: Uint8Array,
  numbers: number[],
  budget = 5000,
): Uint8Array | null {
  const counter = { left: budget };
  const search = (grid: Uint8Array): Uint8Array | null => {
    const r = solve(w, h, grid, numbers, DIFF_TRICKY);
    if (r.result === IMPOSSIBLE) return null;
    if (r.result === SOLVED) return isComplete(r.grid, w, h, numbers) ? r.grid : null;
    if (counter.left-- <= 0) return null;
    // Guess at the first blank beside an unlinked tree.
    let pick = -1;
    for (let i = 0; i < w * h && pick < 0; i++) {
      if (r.grid[i] !== BLANK) continue;
      const x = i % w;
      const y = Math.floor(i / w);
      for (const [dx, dy] of DIRS4) {
        const nx = x + dx;
        const ny = y + dy;
        if (inBounds(nx, ny, w, h) && r.grid[ny * w + nx] === TREE && !r.links[ny * w + nx]) {
          pick = i;
          break;
        }
      }
    }
    if (pick < 0) pick = r.grid.indexOf(BLANK);
    if (pick < 0) return isComplete(r.grid, w, h, numbers) ? r.grid : null;
    for (const v of [TENT, NONTENT]) {
      const next = r.grid.slice();
      next[pick] = v;
      const found = search(next);
      if (found) return found;
      if (counter.left <= 0) return null;
    }
    return null;
  };
  return search(start);
}
