/**
 * The "Achievement unlocked" card: the badge, the name, a short hold, gone.
 *
 * Installed once for the whole app, since an achievement can land anywhere — a solve on
 * the play page, an unlock on the menu, a visit on a new day. Several at once queue and
 * come down one after the other rather than stacking into a wall; each waits a beat
 * first, so it arrives after the win chime and the "+1 credit" rather than over them.
 *
 * It slides in from the side of the screen like a console's trophy, into whichever corner
 * covers least of what the player is looking at — the board, the HUD, the keypad, the
 * results card; the logo and the cards on the menu (see {@link placeCard}) — and slides
 * back out the way it came.
 *
 * Clicking the card opens the Achievements page — except on the play page, where it can
 * still land over the edge of a big board: there `achievements.css` lets clicks fall
 * through to the board, so a move is never turned into a page change. It never takes
 * focus.
 */
import { onAchievement, type Achievement } from '../achievements';
import { badgeSVG } from '../achievements/art';
import { achievementText, t } from '../i18n';
import { gsap, prefersReducedMotion } from './anim';
import { isTouch } from './device';
import { touchPhrasing } from './markdown';
import { playSound } from './sound';

const FIRST_DELAY_MS = 900;
const HOLD_MS = 3600;
/**
 * A burst — a returning player whose old progress earns a dozen badges on the first visit
 * after achievements shipped — shows this many cards, then one card for the rest.
 */
const MAX_CARDS = 3;

let installed = false;
const queue: Achievement[] = [];
let busy = false;
let shownInBurst = 0;

/**
 * The title and condition of any achievement, in the current language. Conditions are
 * written in mouse words like the help, so a touch screen gets the same rewrite.
 */
export function achievementCopy(a: Achievement): { name: string; description: string } {
  const own = a.game?.achievements?.find((x) => `${a.game!.id}.${x.id}` === a.key);
  const copy =
    a.game && own
      ? achievementText(a.game, own)
      : {
          name: t(`ui.achievements.meta.${a.key}.name`),
          description: t(`ui.achievements.meta.${a.key}.description`),
        };
  return isTouch()
    ? { name: touchPhrasing(copy.name), description: touchPhrasing(copy.description) }
    : copy;
}

function show(a: Achievement, more: number, done: () => void): void {
  const card = document.createElement('a');
  card.className = `achievement-toast tier-${a.tier}`;
  card.href = '#/achievements';
  card.setAttribute('role', 'status');
  const { name } = achievementCopy(a);
  const art = document.createElement('span');
  art.className = 'achievement-toast-art';
  art.innerHTML = badgeSVG({ key: a.key, tier: a.tier, hue: a.hue, art: a.art });
  const text = document.createElement('span');
  text.className = 'achievement-toast-text';
  const kicker = document.createElement('small');
  kicker.textContent = t('ui.achievements.unlocked');
  const title = document.createElement('b');
  title.textContent = more ? t('ui.achievements.andMore', { n: more }) : name;
  text.append(kicker, title);
  card.append(art, text);
  document.body.append(card);
  let slot = placeCard(card, null);
  // The page rearranges itself under the card as a win settles (the results panel takes
  // the strip under the board, or the width beside it), so it moves if its corner fills up.
  const follow = window.setInterval(() => {
    slot = placeCard(card, slot);
  }, 200);
  playSound('unlock');

  /** Off the edge it came in from: a whole card's width, and its margin, past the side. */
  const offstage = () => (card.offsetWidth + 24) * (slot.side === 'left' ? -1 : 1);
  let gone = false;
  const leave = () => {
    if (gone) return;
    gone = true;
    gsap.to(card, {
      ...(prefersReducedMotion() ? {} : { x: offstage() }),
      opacity: 0,
      duration: 0.3,
      ease: 'power2.in',
      onComplete: () => {
        window.clearInterval(follow);
        card.remove();
        done();
      },
    });
  };
  card.addEventListener('click', () => leave());
  if (prefersReducedMotion()) {
    gsap.set(card, { opacity: 1 });
  } else {
    gsap.fromTo(
      card,
      { x: offstage(), opacity: 0 },
      { x: 0, opacity: 1, duration: 0.45, ease: 'back.out(1.4)' },
    );
    gsap.fromTo(
      art,
      { scale: 0.4, rotation: -25 },
      { scale: 1, rotation: 0, duration: 0.6, delay: 0.15, ease: 'elastic.out(1, 0.5)' },
    );
  }
  window.setTimeout(leave, HOLD_MS);
}

/** Where the card stands: a corner (or the gap under a phone's HUD), and its side. */
interface Slot {
  id: string;
  side: 'left' | 'right';
  left: number;
  top: number;
}

/**
 * What the card must keep off, and how much each matters: a square of board covered is
 * worth five of a square of menu card. Anything absent from the page scores nothing.
 */
const KEEP_CLEAR: [string, number][] = [
  ['.puzzle-canvas', 10],
  ['.endgame', 8],
  ['.tut-callout', 8],
  ['.modal', 8],
  // The controls themselves, not the columns they stand in: a rail is as tall as the page.
  ['.game-page .keypad > *', 6],
  ['.game-page .toolbar > *', 6],
  ['.game-page .topbar > *', 4],
  ['.toast', 4],
  ['.statusbar', 2],
  // The menu's own controls — the magnifier, the gear, Continue and the counter chips — are
  // buttons a player reaches for right after a win, not a strip of type to cover.
  ['.menu-page .menu-tools > *', 6],
  ['.menu-page .continue-btn:not([hidden])', 6],
  ['.menu-page .resource-bar .chip', 4],
  // The Achievements page: its way back, its heading and the shelf of badges.
  ['.ach-topbar > *', 6],
  ['.ach-summary', 3],
  ['.ach-grid > *', 2],
  ['.menu-page .logo', 4],
  ['.welcome-head', 4],
  ['.pager', 3],
  ['.progress-strip', 2],
  ['.lang-select', 2],
  ['.shelf .card:not(.off-page)', 2],
  ['.welcome-more', 1],
  ['.section-note', 0.5],
];

/** The card's distance from the edge of the screen, past any notch or rounded corner. */
function edge(card: HTMLElement, side: 'top' | 'right' | 'bottom' | 'left'): number {
  const v = getComputedStyle(card).getPropertyValue(`--safe-${side}`);
  return 12 + (parseFloat(v) || 0);
}

/** Every place the card might stand, in the order it is preferred when they tie. */
function candidates(card: HTMLElement, w: number, h: number): Slot[] {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const l = edge(card, 'left');
  const r = vw - edge(card, 'right') - w;
  const t = edge(card, 'top');
  const b = vh - edge(card, 'bottom') - h;
  // A console's trophy comes in along the bottom, on the side a line of text starts from.
  const near = document.documentElement.dir === 'rtl' ? 'right' : 'left';
  const far = near === 'left' ? 'right' : 'left';
  const x = (side: 'left' | 'right') => (side === 'left' ? l : r);
  const slots: Slot[] = [
    { id: 'bottom-near', side: near, left: x(near), top: b },
    { id: 'bottom-far', side: far, left: x(far), top: b },
    { id: 'top-near', side: near, left: x(near), top: t },
    { id: 'top-far', side: far, left: x(far), top: t },
  ];
  // An upright phone leaves a strip of desk between the HUD and the board.
  const bar = document.querySelector<HTMLElement>('.game-page .toolbar');
  if (bar && document.documentElement.classList.contains('playing')) {
    const under = bar.getBoundingClientRect().bottom + 8;
    if (under + h < vh / 2)
      slots.push({ id: 'under-hud', side: near, left: Math.max(l, (vw - w) / 2), top: under });
  }
  return slots;
}

function overlap(a: DOMRect, s: Slot, w: number, h: number): number {
  const x = Math.min(a.right, s.left + w) - Math.max(a.left, s.left);
  const y = Math.min(a.bottom, s.top + h) - Math.max(a.top, s.top);
  return x > 0 && y > 0 ? x * y : 0;
}

/** How much of what matters the card would cover standing in `s`. */
function cost(card: HTMLElement, s: Slot, w: number, h: number): number {
  let sum = 0;
  for (const [sel, weight] of KEEP_CLEAR) {
    for (const el of document.querySelectorAll<HTMLElement>(sel)) {
      if (card.contains(el)) continue;
      const r = el.getBoundingClientRect();
      if (r.width && r.height) sum += weight * overlap(r, s, w, h);
    }
  }
  return sum;
}

/**
 * Put the card in the place that covers least, keeping `current` unless another is now
 * clearly better: a card that hopped about every time the page shifted by a pixel would
 * be the one thing on screen that moved.
 */
function placeCard(card: HTMLElement, current: Slot | null): Slot {
  const w = card.offsetWidth;
  const h = card.offsetHeight;
  const slots = candidates(card, w, h);
  const costs = slots.map((s) => cost(card, s, w, h));
  let i = costs.indexOf(Math.min(...costs));
  const kept = current ? slots.findIndex((s) => s.id === current.id) : -1;
  if (kept >= 0 && costs[kept] <= costs[i] + w * h * 0.5) i = kept;
  const best = slots[i];
  if (current && best.id !== current.id) card.style.transition = 'top 0.3s ease, left 0.3s ease';
  card.style.left = `${Math.round(best.left)}px`;
  card.style.top = `${Math.round(best.top)}px`;
  card.dataset.slot = best.id;
  return best;
}

function next(): void {
  const a = queue.shift();
  if (!a) {
    busy = false;
    return;
  }
  shownInBurst++;
  // The last card of a long burst stands for everything still waiting.
  const more = shownInBurst === MAX_CARDS && queue.length ? queue.length + 1 : 0;
  if (more) queue.length = 0;
  show(a, more, () => window.setTimeout(next, 150));
}

export function installAchievementToasts(): void {
  if (installed) return;
  installed = true;
  onAchievement((a) => {
    queue.push(a);
    if (busy) return;
    busy = true;
    shownInBurst = 0;
    window.setTimeout(next, FIRST_DELAY_MS);
  });
}
