import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { BlackboxParams, BlackboxState } from './index';

type C = typeof PALETTE;

/** The box: a square of `n`×`n` cells with its grid, top-left at (x, y), cell size `s`. */
function box(c: C, x: number, y: number, n: number, s: number, fill: string): string {
  let grid = '';
  for (let i = 1; i < n; i++) {
    grid += `M${x + i * s} ${y} V${y + n * s} M${x} ${y + i * s} H${x + n * s} `;
  }
  return (
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" rx="3" fill="${fill}"/>` +
    `<path d="${grid}" stroke="${c.lowlight}" stroke-width="1.6"/>` +
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" rx="3" fill="none" stroke="${c.ink}" stroke-width="4.5"/>`
  );
}

/** A found ball: solid ink with a highlight. */
function ball(c: C, cx: number, cy: number, r: number, fill: string = c.ink): string {
  return (
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}"/>` +
    `<circle cx="${cx - r * 0.35}" cy="${cy - r * 0.35}" r="${r * 0.28}" fill="${c.highlight}"/>`
  );
}

/** A wrong mark, crossed out in red as the reveal does. */
function cross(c: C, cx: number, cy: number, r: number): string {
  return `<path d="M${cx - r} ${cy - r} L${cx + r} ${cy + r} M${cx + r} ${cy - r} L${cx - r} ${cy + r}" stroke="${c.red}" stroke-width="5" stroke-linecap="round"/>`;
}

/** Total ports on the frame: every row and column has one at each end. */
const ports = (s: BlackboxState) => 2 * (s.w + s.h);

export const achievements = defineAchievements<BlackboxParams, BlackboxState>([
  {
    id: 'sparing-shots',
    name: 'Sparing Shots',
    description: 'Find every ball while firing lasers from no more than half of the ports.',
    tier: 'silver',
    hue: 'teal',
    // One beam, bent by the only ball it needed to meet: a single shot's worth of news.
    art: (c) =>
      box(c, 30, 20, 4, 12, c.shade) +
      ball(c, 60, 38, 6.5) +
      `<path d="M17 50 H48 V74" fill="none" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/>` +
      `<path d="M41 68 L48 78 L55 68" fill="none" stroke="${c.red}" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: (ctx) => ctx.state.nFired * 2 <= ports(ctx.state),
  },
  {
    id: 'pinpoint',
    name: 'Pinpoint',
    description:
      'Find every ball in an 8×8 or larger box, firing at most three lasers for each ball.',
    tier: 'gold',
    hue: 'red',
    art: (c) =>
      box(c, 22, 22, 4, 14, c.shade) +
      ball(c, 71, 29, 5.5) +
      ball(c, 29, 71, 5.5) +
      ball(c, 57, 57, 6.5) +
      `<circle cx="57" cy="57" r="13" fill="none" stroke="${c.red}" stroke-width="4"/>` +
      `<path d="M57 38 V47 M57 67 V76 M38 57 H47 M67 57 H76" stroke="${c.red}" stroke-width="4" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 8 && ctx.params.h >= 8 && ctx.state.nFired <= 3 * ctx.state.nBalls,
  },
  {
    id: 'shot-in-the-dark',
    name: 'Shot in the Dark',
    description: 'Have your balls checked without firing a single laser, and get it wrong.',
    tier: 'bronze',
    hidden: true,
    hue: 'violet',
    on: 'lose',
    // The box stayed dark: guesses crossed out in red, the balls it hid shown in red.
    art: (c) =>
      box(c, 24, 24, 4, 13, c.dark) +
      cross(c, 30.5, 30.5, 4.5) +
      cross(c, 56.5, 43.5, 4.5) +
      ball(c, 43.5, 56.5, 5, c.red) +
      ball(c, 69.5, 69.5, 5, c.red),
    test: (ctx) => ctx.state.nFired === 0,
  },
]);
