/*
 * Terminology, borrowed from the original:
 * - The 'arena' is the w×h box the balls hide in; arena coordinates run 0..w-1, 0..h-1.
 * - The 'grid' is the arena plus a one-cell frame of laser ports; grid coordinates run
 *   0..w+1, 0..h+1, so arena cell (x, y) is grid cell (x+1, y+1). Grid cell (0, 0) is
 *   the "check my guesses" button; the other three corners are unused.
 * - A 'port' is a laser position on the frame, numbered 0 .. 2(w+h)-1 clockwise from
 *   the top-left: along the top, down the right side, back along the bottom, up the
 *   left side.
 */

export interface BlackboxParams {
  w: number;
  h: number;
  minBalls: number;
  maxBalls: number;
}

/** Arena cell flags. */
export const BALL = 1; // a real ball hides here
export const GUESS = 2; // the player has marked a ball here
export const LOCK = 4; // the player has locked this cell against changes

/** Special values of `exits[port]`; non-negative values are the exit port. */
export const EXIT_NONE = -1;
export const EXIT_HIT = -2;
export const EXIT_REFLECT = -3;

/** Feedback marks on ports, set by a wrong reveal. */
export const MARK_WRONG = 1; // a fired laser that contradicts the guesses (ringed)
export const MARK_OMITTED = 2; // a laser the player never fired that would have told (red)

export interface BlackboxState {
  w: number;
  h: number;
  minBalls: number;
  maxBalls: number;
  /** Number of real balls. */
  nBalls: number;
  /** Arena cells, row-major, BALL | GUESS | LOCK flags. */
  cells: number[];
  /** Per port: EXIT_NONE (not fired), EXIT_HIT, EXIT_REFLECT or the port it emerged from. */
  exits: number[];
  /** Per port: the number written on a numbered port (0 when none). */
  labels: number[];
  /** Per port: MARK_* flags. */
  marks: number[];
  /** Next number to hand out to an entry/exit pair. */
  nextLaser: number;
  nGuesses: number;
  /** Lasers fired by the player. */
  nFired: number;
  /** The answer has been revealed (by the check button or by Solve). */
  reveal: boolean;
  nRight: number;
  nWrong: number;
  nMissed: number;
  /** The balls went in by Solve rather than by the player's own check. */
  usedSolve?: boolean;
}

export interface BlackboxUI {
  /** Cursor in grid coordinates. */
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** Port whose beam (entry and exit) is highlighted, or -1. */
  highlight: number;
  /** The highlight came from the keyboard and stays until the cursor moves. */
  highlightSticky: boolean;
}

const FLASH_FRAME = 0.13;
const MAX_SIDE = 20;
const DX = [0, 1, 0, -1];
const DY = [-1, 0, 1, 0];
/** Colours used to tell numbered pairs apart; both ends of a pair share one. */
const PAIR_COLOURS = ['blue', 'green', 'purple', 'teal', 'pink', 'brown'];

// ------------------------------------------------------------------ geometry

export interface Port {
  /** Grid coordinates of the port cell. */
  x: number;
  y: number;
  /** Direction the beam travels when fired from here: 0 up, 1 right, 2 down, 3 left. */
  dir: number;
}

export function portCount(w: number, h: number): number {
  return 2 * (w + h);
}

/** Grid position and firing direction of port `n`, or null when out of range. */
export function portToGrid(w: number, h: number, n: number): Port | null {
  if (n < 0) return null;
  if (n < w) return { x: n + 1, y: 0, dir: 2 };
  n -= w;
  if (n < h) return { x: w + 1, y: n + 1, dir: 3 };
  n -= h;
  if (n < w) return { x: w - n, y: h + 1, dir: 0 };
  n -= w;
  if (n < h) return { x: 0, y: h - n, dir: 1 };
  return null;
}

/** Port number of grid cell (gx, gy), or -1 for arena cells, corners and outside. */
export function gridToPort(w: number, h: number, gx: number, gy: number): number {
  const x1 = w + 1;
  const y1 = h + 1;
  if (gx < 0 || gx > x1 || gy < 0 || gy > y1) return -1;
  if (gx > 0 && gx < x1 && gy > 0 && gy < y1) return -1;
  if ((gx === 0 || gx === x1) && (gy === 0 || gy === y1)) return -1;
  if (gy === 0) return gx - 1;
  if (gx === x1) return w + gy - 1;
  if (gy === y1) return w + h + (w - gx);
  return 2 * w + h + (h - gy);
}

function inArena(w: number, h: number, gx: number, gy: number): boolean {
  return gx >= 1 && gy >= 1 && gx <= w && gy <= h;
}

// ------------------------------------------------------------------ lasers

/**
 * Fire a laser from `entry` through an arena whose balls are the cells with `flag` set
 * (BALL for the real answer, GUESS for the player's layout). Returns EXIT_HIT,
 * EXIT_REFLECT or the port the beam emerges from.
 *
 * A ball straight ahead absorbs the beam. A ball diagonally ahead deflects it 90°
 * away from that ball; when balls sit on both diagonals the beam is turned back. Either
 * kind of ball next to the entry deflects the beam before it enters, which counts as a
 * reflection, as does any beam that finds its way back out through its own port.
 */
export function traceLaser(
  w: number,
  h: number,
  cells: ArrayLike<number>,
  flag: number,
  entry: number,
): number {
  const port = portToGrid(w, h, entry);
  if (!port) throw new Error(tx`no such laser: ${entry}`);
  let { x, y, dir } = port;
  const ball = (gx: number, gy: number) =>
    inArena(w, h, gx, gy) && (cells[(gy - 1) * w + (gx - 1)] & flag) !== 0;
  const ahead = () => ball(x + DX[dir], y + DY[dir]);
  const aheadLeft = () => {
    const l = (dir + 3) & 3;
    return ball(x + DX[dir] + DX[l], y + DY[dir] + DY[l]);
  };
  const aheadRight = () => {
    const r = (dir + 1) & 3;
    return ball(x + DX[dir] + DX[r], y + DY[dir] + DY[r]);
  };

  // Standing on the port: a ball on the first rank absorbs, a diagonal one reflects.
  if (ahead()) return EXIT_HIT;
  if (aheadLeft() || aheadRight()) return EXIT_REFLECT;
  x += DX[dir];
  y += DY[dir];

  // The beam can never spin in place: it only enters a cell whose two diagonals behind
  // it are empty, so at most two turns happen per cell. The bound is just insurance.
  for (let guard = 8 * (w + 2) * (h + 2); guard > 0; guard--) {
    const out = gridToPort(w, h, x, y);
    if (out >= 0) return out === entry ? EXIT_REFLECT : out;
    if (ahead()) return EXIT_HIT;
    if (aheadLeft()) {
      dir = (dir + 1) & 3; // ball to the front-left: turn right
      continue;
    }
    if (aheadRight()) {
      dir = (dir + 3) & 3; // ball to the front-right: turn left
      continue;
    }
    x += DX[dir];
    y += DY[dir];
  }
  return EXIT_HIT;
}

type Mutable = BlackboxState;

/** Fire port `n` for real: record the result and number a new entry/exit pair. */
function fireLaser(s: Mutable, n: number): void {
  const exit = traceLaser(s.w, s.h, s.cells, BALL, n);
  s.exits[n] = exit;
  if (exit >= 0) {
    const num = s.nextLaser++;
    s.labels[n] = num;
    s.labels[exit] = num;
    s.exits[exit] = n;
  }
}

/**
 * Compare the player's guesses with the answer and reveal the result.
 *
 * Every laser is fired through both layouts. A layout that no laser could distinguish
 * from the answer is correct — and then it *is* the answer, even if a ball sits
 * somewhere else than the computer put it (with several balls more than one layout can
 * behave identically). Otherwise the answer is shown: fired lasers the guesses get
 * wrong are ringed, and lasers that were never fired but would have told the layouts
 * apart are fired now and written in red.
 */
function checkGuesses(s: Mutable): void {
  const { w, h } = s;
  const firedByPlayer = s.exits.map((e) => e !== EXIT_NONE);
  let ok = true;
  for (let i = 0; i < s.exits.length; i++) {
    if (traceLaser(w, h, s.cells, BALL, i) === traceLaser(w, h, s.cells, GUESS, i)) continue;
    ok = false;
    if (firedByPlayer[i]) {
      s.marks[i] |= MARK_WRONG;
    } else {
      if (s.exits[i] === EXIT_NONE) fireLaser(s, i);
      s.marks[i] |= MARK_OMITTED;
    }
  }
  if (ok && s.nGuesses >= s.minBalls && s.nGuesses <= s.maxBalls) {
    // Proven equivalent: the guesses become the answer.
    s.cells = s.cells.map((c) => (c & GUESS ? c | BALL : c & ~BALL));
  }
  s.nRight = s.nWrong = s.nMissed = 0;
  for (const c of s.cells) {
    const bs = c & (BALL | GUESS);
    if (bs === (BALL | GUESS)) s.nRight++;
    else if (bs === GUESS) s.nWrong++;
    else if (bs === BALL) s.nMissed++;
  }
  s.reveal = true;
}

export function canReveal(s: BlackboxState): boolean {
  return s.nGuesses >= s.minBalls && s.nGuesses <= s.maxBalls && !s.reveal;
}

function isWon(s: BlackboxState): boolean {
  return s.reveal && s.nWrong === 0 && s.nMissed === 0 && s.nRight >= s.minBalls;
}

function copyState(s: BlackboxState): Mutable {
  return {
    ...s,
    cells: s.cells.slice(),
    exits: s.exits.slice(),
    labels: s.labels.slice(),
    marks: s.marks.slice(),
  };
}

// ------------------------------------------------------------------ descriptions

/** Ball positions of a description, or null when it is malformed for these params. */
export function decodeDesc(p: BlackboxParams, desc: string): [number, number][] | null {
  if (desc.length < 4 || desc.length % 4 !== 0 || !/^[0-9a-fA-F]+$/.test(desc)) return null;
  const bmp = hexToBytes(desc);
  obfuscateBitmap(bmp, bmp.length * 8, true);
  if (bmp[0] !== p.w || bmp[1] !== p.h) return null;
  const balls: [number, number][] = [];
  const seen = new Set<number>();
  for (let i = 2; i < bmp.length; i += 2) {
    const x = bmp[i];
    const y = bmp[i + 1];
    if (x >= p.w || y >= p.h || seen.has(y * p.w + x)) return null;
    seen.add(y * p.w + x);
    balls.push([x, y]);
  }
  return balls;
}

export function encodeDesc(w: number, h: number, balls: [number, number][]): string {
  const bmp = new Uint8Array(2 + 2 * balls.length);
  bmp[0] = w;
  bmp[1] = h;
  balls.forEach(([x, y], i) => {
    bmp[2 + 2 * i] = x;
    bmp[3 + 2 * i] = y;
  });
  obfuscateBitmap(bmp, bmp.length * 8, false);
  return bytesToHex(bmp);
}

function ballsText(min: number, max: number): string {
  return min === max ? `${min}` : `${min}-${max}`;
}

// ------------------------------------------------------------------ drawing helpers

function borderFor(t: number): number {
  return Math.round(t * 0.3);
}

function drawBall(dr: Drawing, cx: number, cy: number, t: number, colour: string, seed: number) {
  const r = t * 0.32;
  dr.circle(cx, cy, r, colour, colour, { width: 1.6, seed });
  dr.dot(cx - r * 0.35, cy - r * 0.38, r * 0.2, 'highlight', { alpha: 0.7, seed });
}

/** A small padlock in the top-right corner of a locked cell. */
function drawPadlock(dr: Drawing, x: number, y: number, t: number, seed: number) {
  const s = t * 0.1;
  const cx = x + t - s * 2.1;
  const cy = y + s * 2.3;
  dr.roundRect(cx - s, cy - s * 0.2, 2 * s, 1.7 * s, s * 0.3, 'pencil', 'pencil', {
    width: 1,
    seed,
  });
  const pts: number[] = [];
  for (let i = 0; i <= 6; i++) {
    const a = Math.PI + (i / 6) * Math.PI;
    pts.push(cx + Math.cos(a) * s * 0.7, cy - s * 0.2 + Math.sin(a) * s * 0.9);
  }
  dr.polyline(pts, 'pencil', 1.3, { seed: seed + 1, rough: 0.4 });
}

// ------------------------------------------------------------------ the game

/**
 * How long a shot spends in the box, and how much of that is the spark going in. The
 * player fires and the answer used to be there in the same frame; a beam that takes no
 * time at all makes the arena feel like a lookup table rather than a box with something
 * in it.
 */
const SHOT_TIME = 0.26;
const SHOT_TRAVEL = 0.55;

/**
 * The ports a single shot just lit, or null. Both ends of a beam are returned together and
 * treated identically — which end the player fired from is not recoverable here, and
 * showing it would be a hint they did not ask for.
 */
function readShot(
  oldState: BlackboxState,
  newState: BlackboxState,
  dir: number,
): Set<number> | null {
  const earlier = dir > 0 ? oldState : newState;
  const later = dir > 0 ? newState : oldState;
  if (earlier.exits.length !== later.exits.length) return null;
  const ports = new Set<number>();
  for (let n = 0; n < earlier.exits.length; n++) {
    if (earlier.exits[n] === later.exits[n]) continue;
    if (earlier.exits[n] !== EXIT_NONE) return null;
    ports.add(n);
  }
  // A shot lights one port (a hit or a reflection) or two (a beam that came out again).
  return ports.size === 1 || ports.size === 2 ? ports : null;
}

/** Which way is into the box from a port on the edge. */
function inwards(w: number, h: number, n: number): { dx: number; dy: number } {
  const p = portToGrid(w, h, n)!;
  if (p.x === 0) return { dx: 1, dy: 0 };
  if (p.x === w + 1) return { dx: -1, dy: 0 };
  if (p.y === 0) return { dx: 0, dy: 1 };
  return { dx: 0, dy: -1 };
}

const game = defineGame<BlackboxParams, BlackboxState, BlackboxUI>({
  id: 'blackbox',
  name: 'Black Box',
  description: 'Find the hidden balls by firing lasers into the box and watching them emerge.',
  // Written against the thumbnail's own 5×5 board (twenty ports): two numbered pairs, an
  // H and an R, and two of its three balls found.
  thumbnailMoves: ['F0', 'F1', 'F2', 'F3', 'F9', 'T2,3', 'T4,2'],
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: [
    { name: '5×5, 3 balls', params: { w: 5, h: 5, minBalls: 3, maxBalls: 3 } },
    { name: '8×8, 5 balls', params: { w: 8, h: 8, minBalls: 5, maxBalls: 5 } },
    { name: '8×8, 3-6 balls', params: { w: 8, h: 8, minBalls: 3, maxBalls: 6 } },
    { name: '10×10, 5 balls', params: { w: 10, h: 10, minBalls: 5, maxBalls: 5 } },
    { name: '10×10, 4-10 balls', params: { w: 10, h: 10, minBalls: 4, maxBalls: 10 } },
  ],
  // The smallest board the Type menu offers, rather than the original's default: a
  // newcomer's first puzzle should be one they can finish. See the other games' OPENING.
  defaultParams: () => ({ w: 5, h: 5, minBalls: 3, maxBalls: 3 }),
  // The original's format, so its game IDs keep working. `8x8m3-6` is accepted too.
  encodeParams: (p) => `w${p.w}h${p.h}m${p.minBalls}M${p.maxBalls}`,
  decodeParams(str) {
    const p = { w: 8, h: 8, minBalls: 5, maxBalls: 5 };
    if (/^\d/.test(str)) {
      const r = parseWxH(str);
      if (!r) throw new Error(tx`expected WxH`);
      p.w = r.w;
      p.h = r.h;
      const m = /^m(\d+)(?:-(\d+))?/.exec(r.rest);
      if (m) {
        p.minBalls = parseInt(m[1], 10);
        p.maxBalls = m[2] ? parseInt(m[2], 10) : p.minBalls;
      }
      return p;
    }
    const re = /([whmM])(\d+)/g;
    let m: RegExpExecArray | null;
    let any = false;
    while ((m = re.exec(str))) {
      any = true;
      const v = parseInt(m[2], 10);
      if (m[1] === 'w') p.w = v;
      else if (m[1] === 'h') p.h = v;
      else if (m[1] === 'm') p.minBalls = v;
      else p.maxBalls = v;
    }
    if (!any) throw new Error(tx`expected w<W>h<H>m<MIN>M<MAX>`);
    return p;
  },
  validateParams(p) {
    if (![p.w, p.h, p.minBalls, p.maxBalls].every(Number.isInteger))
      return tx`Width, height and ball counts must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.minBalls < 1) return tx`There must be at least one ball`;
    if (p.minBalls > p.maxBalls) return tx`Minimum number of balls may not be greater than maximum`;
    if (p.maxBalls >= p.w * p.h) return tx`Too many balls to fit in the grid`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      // A `min-max` range is as valid here as a plain count, and a phone's number pad
      // has no hyphen on it, so this one field keeps the full keyboard.
      {
        type: 'string',
        name: 'No. of balls',
        value: ballsText(p.minBalls, p.maxBalls),
        keyboard: 'text',
      },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (s: string) => (/^-?\d+$/.test(s.trim()) ? parseInt(s, 10) : NaN);
    const w = int((items[0] as { value: string }).value);
    const h = int((items[1] as { value: string }).value);
    const balls = (items[2] as { value: string }).value.trim();
    const m = /^(\d+)\s*-\s*(\d+)$/.exec(balls);
    const minBalls = m ? parseInt(m[1], 10) : int(balls);
    const maxBalls = m ? parseInt(m[2], 10) : minBalls;
    return { w, h, minBalls, maxBalls };
  },

  newDesc(p, rng: Random) {
    let n = p.minBalls;
    if (p.maxBalls > p.minBalls) n += rng.upto(p.maxBalls - p.minBalls + 1);
    const taken = new Uint8Array(p.w * p.h);
    const balls: [number, number][] = [];
    for (let i = 0; i < n; i++) {
      let x: number;
      let y: number;
      do {
        x = rng.upto(p.w);
        y = rng.upto(p.h);
      } while (taken[y * p.w + x]);
      taken[y * p.w + x] = 1;
      balls.push([x, y]);
    }
    return { desc: encodeDesc(p.w, p.h, balls) };
  },

  validateDesc(p, desc) {
    if (desc.length < 4 || desc.length % 4 !== 0) return tx`Game description is the wrong length`;
    if (!/^[0-9a-fA-F]+$/.test(desc)) return tx`Game description must be hexadecimal`;
    const n = (desc.length / 2 - 2) / 2;
    if (n < p.minBalls || n > p.maxBalls)
      return tx`Game description has ${n} balls; expected ${ballsText(p.minBalls, p.maxBalls)}`;
    if (!decodeDesc(p, desc)) return tx`Game description is corrupted`;
    return null;
  },

  newGame(p, desc) {
    const balls = decodeDesc(p, desc) ?? [];
    const cells = new Array<number>(p.w * p.h).fill(0);
    for (const [x, y] of balls) cells[y * p.w + x] |= BALL;
    const np = portCount(p.w, p.h);
    return {
      w: p.w,
      h: p.h,
      minBalls: p.minBalls,
      maxBalls: p.maxBalls,
      nBalls: balls.length,
      cells,
      exits: new Array<number>(np).fill(EXIT_NONE),
      labels: new Array<number>(np).fill(0),
      marks: new Array<number>(np).fill(0),
      nextLaser: 1,
      nGuesses: 0,
      nFired: 0,
      reveal: false,
      nRight: 0,
      nWrong: 0,
      nMissed: 0,
    };
  },

  canSolve: true,
  solve(_orig, curr) {
    if (isWon(curr)) throw new Error(tx`Already solved`);
    return 'S';
  },

  textFormat(s) {
    const { w, h } = s;
    const label = (n: number) => {
      const e = s.exits[n];
      if (e === EXIT_NONE) return null;
      return e === EXIT_HIT ? 'H' : e === EXIT_REFLECT ? 'R' : String(s.labels[n] % 10);
    };
    const cell = (x: number, y: number) => {
      const c = s.cells[y * w + x];
      if (!s.reveal) return c & GUESS ? 'o' : '.';
      if ((c & (BALL | GUESS)) === (BALL | GUESS)) return 'O';
      if (c & GUESS) return 'x';
      if (c & BALL) return '!';
      return '.';
    };
    const rows: string[] = [];
    let top = ' ';
    for (let x = 0; x < w; x++) top += label(gridToPort(w, h, x + 1, 0)) ?? '-';
    rows.push(top);
    for (let y = 0; y < h; y++) {
      let row = label(gridToPort(w, h, 0, y + 1)) ?? '|';
      for (let x = 0; x < w; x++) row += cell(x, y);
      row += label(gridToPort(w, h, w + 1, y + 1)) ?? '|';
      rows.push(row);
    }
    let bottom = ' ';
    for (let x = 0; x < w; x++) bottom += label(gridToPort(w, h, x + 1, h + 1)) ?? '-';
    rows.push(bottom);
    return rows.join('\n');
  },

  newUI: () => ({
    cx: 1,
    cy: 1,
    cursorVisible: false,
    highlight: -1,
    highlightSticky: false,
  }),
  changedState(ui, _old, s) {
    if (ui.highlight >= 0 && s.exits[ui.highlight] === EXIT_NONE) ui.highlight = -1;
    if (ui.cx === 0 && ui.cy === 0 && !canReveal(s)) ui.cx = ui.cy = 1;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h } = state;

    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w + 2, h + 2);
      ui.cursorVisible = true;
      ui.highlight = -1;
      const corner = (p.x === 0 || p.x === w + 1) && (p.y === 0 || p.y === h + 1);
      if (corner && !(p.x === 0 && p.y === 0 && canReveal(state))) return '';
      ui.cx = p.x;
      ui.cy = p.y;
      return '';
    }

    let gx: number;
    let gy: number;
    let right: boolean;
    let sticky = false;
    const wasLit = ui.highlight;
    // A click puts out the light and hides the cursor; when it does nothing else, it
    // still has to ask for the redraw that shows them gone.
    const shown = wasLit >= 0 || ui.cursorVisible;
    let idle: '' | null;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const t = ds.tileSize;
      const bd = borderFor(t);
      gx = Math.floor((mx - bd) / t);
      gy = Math.floor((my - bd) / t);
      right = b === RIGHT_BUTTON;
      ui.cursorVisible = false;
      ui.highlight = -1;
      idle = shown ? '' : null;
    } else if (b === LEFT_RELEASE || b === RIGHT_RELEASE) {
      if (ui.highlight >= 0 && !ui.highlightSticky) {
        ui.highlight = -1;
        return '';
      }
      return null;
    } else if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      gx = ui.cx;
      gy = ui.cy;
      right = b === CURSOR_SELECT2;
      sticky = true;
      ui.highlight = -1;
      idle = wasLit >= 0 ? '' : null;
    } else {
      return null;
    }

    let move: string;
    if (gx === 0 && gy === 0) {
      if (right || !canReveal(state)) return idle;
      if (sticky) ui.cx = ui.cy = 1;
      move = 'R';
    } else if (inArena(w, h, gx, gy)) {
      const ax = gx - 1;
      const ay = gy - 1;
      if (right) move = `LB${ax},${ay}`;
      else if (state.cells[ay * w + ax] & LOCK) return idle;
      else move = `T${ax},${ay}`;
    } else {
      const port = gridToPort(w, h, gx, gy);
      if (port < 0) return idle;
      if (right) {
        move = gy === 0 || gy === h + 1 ? `LC${gx - 1}` : `LR${gy - 1}`;
      } else {
        // Clicking a port that has been fired just lights up its beam. The light stays
        // on after the button comes up — a tap on a phone is over before anyone could
        // see it, and holding a finger down is a long-press, which locks the row — and
        // goes out at the next click, or at a second click on the same port.
        if (state.exits[port] !== EXIT_NONE) {
          if (!sticky && wasLit === port && ui.highlightSticky) return '';
          ui.highlight = port;
          ui.highlightSticky = true;
          return '';
        }
        if (state.reveal) return idle;
        ui.highlight = port;
        ui.highlightSticky = sticky;
        move = `F${port}`;
      }
    }
    return state.reveal ? idle : move;
  },

  executeMove(state, move) {
    if (!move) return null;
    const s = copyState(state);

    if (move === 'S') {
      // Give up: put the real balls in as guesses and reveal.
      s.marks.fill(0);
      s.cells = s.cells.map((c) => (c & BALL ? c | GUESS : c & ~GUESS));
      s.nGuesses = s.nBalls;
      s.reveal = false;
      s.usedSolve = true;
      checkGuesses(s);
      return s;
    }
    if (state.reveal) return null;

    const { w, h } = s;
    let m: RegExpExecArray | null;
    if ((m = /^T(\d+),(\d+)$/.exec(move))) {
      const x = parseInt(m[1], 10);
      const y = parseInt(m[2], 10);
      if (x >= w || y >= h) return null;
      const i = y * w + x;
      if (s.cells[i] & LOCK) return null;
      s.cells[i] ^= GUESS;
      s.nGuesses += s.cells[i] & GUESS ? 1 : -1;
      return s;
    }
    if ((m = /^F(\d+)$/.exec(move))) {
      const n = parseInt(m[1], 10);
      if (n >= s.exits.length || s.exits[n] !== EXIT_NONE) return null;
      fireLaser(s, n);
      s.nFired++;
      return s;
    }
    if (move === 'R') {
      if (s.nGuesses < s.minBalls || s.nGuesses > s.maxBalls) return null;
      checkGuesses(s);
      return s;
    }
    if ((m = /^LB(\d+),(\d+)$/.exec(move))) {
      const x = parseInt(m[1], 10);
      const y = parseInt(m[2], 10);
      if (x >= w || y >= h) return null;
      s.cells[y * w + x] ^= LOCK;
      return s;
    }
    if ((m = /^L([CR])(\d+)$/.exec(move))) {
      // Lock a whole column/row, or unlock it when most of it is already locked.
      const col = m[1] === 'C';
      const k = parseInt(m[2], 10);
      if (k >= (col ? w : h)) return null;
      const idx: number[] = [];
      if (col) for (let y = 0; y < h; y++) idx.push(y * w + k);
      else for (let x = 0; x < w; x++) idx.push(k * w + x);
      const locked = idx.filter((i) => s.cells[i] & LOCK).length;
      const unlock = locked > Math.floor(idx.length / 2);
      for (const i of idx) s.cells[i] = unlock ? s.cells[i] & ~LOCK : s.cells[i] | LOCK;
      return s;
    }
    return null;
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const bd = borderFor(t);
    return { w: (p.w + 2) * t + 2 * bd, h: (p.h + 2) * t + 2 * bd };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h } = state;
    const t = ds.tileSize;
    const bd = borderFor(t);
    const X = (gx: number) => bd + gx * t;
    const Y = (gy: number) => bd + gy * t;
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const pad = Math.max(2, t * 0.08);

    // The frame of laser ports: a soft outline with faint dividers.
    dr.roundRect(X(0), Y(0), (w + 2) * t, (h + 2) * t, t * 0.35, null, 'pencil', { width: 1.3 });
    for (let x = 1; x <= w + 1; x++) {
      dr.line(X(x), Y(0), X(x), Y(1), 'faint', 1.2);
      dr.line(X(x), Y(h + 1), X(x), Y(h + 2), 'faint', 1.2);
    }
    for (let y = 1; y <= h + 1; y++) {
      dr.line(X(0), Y(y), X(1), Y(y), 'faint', 1.2);
      dr.line(X(w + 1), Y(y), X(w + 2), Y(y), 'faint', 1.2);
    }

    // The box itself.
    dr.rect(X(1), Y(1), w * t, h * t, flashing ? 'paper' : 'shade', null);
    for (let x = 1; x < w; x++) dr.line(X(1 + x), Y(1), X(1 + x), Y(1 + h), 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(X(1), Y(1 + y), X(1 + w), Y(1 + y), 'faint', 1.2);
    dr.rectOutline(X(1), Y(1), w * t, h * t, 'ink', { width: 2.4 });

    // Balls: guesses, and after the reveal the verdict on each cell.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const c = state.cells[y * w + x];
        const cx = X(x + 1) + t / 2;
        const cy = Y(y + 1) + t / 2;
        const seed = y * w + x;
        const guessed = (c & GUESS) !== 0;
        const real = (c & BALL) !== 0;
        if (!state.reveal) {
          if (guessed) drawBall(dr, cx, cy, t, 'accent', seed);
        } else if (guessed && real) {
          drawBall(dr, cx, cy, t, flashing ? 'ok' : 'ink', seed);
        } else if (guessed) {
          drawBall(dr, cx, cy, t, 'accent', seed);
          dr.cross(cx, cy, t * 0.36, 'error', 3, { seed });
        } else if (real) {
          drawBall(dr, cx, cy, t, 'error', seed);
        }
        if (c & LOCK) drawPadlock(dr, X(x + 1), Y(y + 1), t, seed);
      }
    }

    // Ports. A shot just fired is still in the box: its ports keep their blank dot for a
    // beat, a spark runs in from each of them, and only then does the answer arrive. What
    // the beam does in there is the whole secret of this puzzle, so the animation says
    // only that time passed — never which way anything went.
    const shot = oldState ? readShot(oldState, state, dir) : null;
    const shotAt = shot ? (dir > 0 ? animTime : SHOT_TIME - animTime) : 0;
    const hl = ui.highlight;
    const hlExit = hl >= 0 ? state.exits[hl] : EXIT_NONE;
    for (let n = 0; n < state.exits.length; n++) {
      const p = portToGrid(w, h, n)!;
      const cx = X(p.x) + t / 2;
      const cy = Y(p.y) + t / 2;
      const exit = state.exits[n];
      const firing = shot?.has(n) ? clamp(shotAt / SHOT_TIME, 0, 1) : -1;
      if (firing >= 0) {
        // The spark, travelling one square into the box and fading as it goes.
        if (firing < SHOT_TRAVEL) {
          const k = firing / SHOT_TRAVEL;
          const into = inwards(w, h, n);
          dr.dot(
            cx + into.dx * t * k,
            cy + into.dy * t * k,
            Math.max(1.6, t * 0.09) * (1 - k * 0.4),
            'accent',
            { alpha: 1 - k * 0.7 },
          );
        }
        if (firing < SHOT_TRAVEL || exit === EXIT_NONE) {
          dr.dot(cx, cy, Math.max(1.2, t * 0.045), 'faint');
          continue;
        }
      }
      if (exit === EXIT_NONE) {
        dr.dot(cx, cy, Math.max(1.2, t * 0.045), 'faint');
        continue;
      }
      const label = exit === EXIT_HIT ? 'H' : exit === EXIT_REFLECT ? 'R' : String(state.labels[n]);
      const lit = hl >= 0 && (n === hl || (hlExit >= 0 && n === hlExit));
      const omitted = (state.marks[n] & MARK_OMITTED) !== 0;
      const wrong = (state.marks[n] & MARK_WRONG) !== 0;
      let colour: string;
      if (lit) colour = 'accent';
      else if (omitted) colour = 'error';
      else if (flashing) colour = 'ok';
      else if (exit >= 0) colour = PAIR_COLOURS[(state.labels[n] - 1) % PAIR_COLOURS.length];
      else colour = 'ink';
      if (wrong) dr.circle(cx, cy, t * 0.42, null, 'error', { width: 2.2, seed: n });
      if (lit) dr.circle(cx, cy, t * 0.4, 'shade', 'accent', { width: 1.6, seed: n });
      // An answer that has just come back arrives at its full size from nothing.
      const arrive = firing >= 0 ? clamp((firing - SHOT_TRAVEL) / (1 - SHOT_TRAVEL), 0, 1) : 1;
      dr.text(cx, cy, label, { size: t * 0.56 * arrive, colour, maxWidth: t * 0.82 });
    }

    // The "check my guesses" button in the top-left corner.
    {
      const cx = X(0) + t / 2;
      const cy = Y(0) + t / 2;
      if (canReveal(state)) {
        dr.circle(cx, cy, t * 0.38, 'ok', 'ink', { width: 1.8 });
        dr.tick(cx, cy, t * 0.18, 'paper', 2.6);
      } else if (state.reveal) {
        if (isWon(state)) dr.tick(cx, cy, t * 0.2, 'ok', 3);
        else dr.cross(cx, cy, t * 0.18, 'error', 3);
      } else {
        dr.circle(cx, cy, t * 0.34, null, 'faint', { width: 1.4, dash: [t * 0.1, t * 0.09] });
      }
    }

    if (ui.cursorVisible) dr.cursor(X(ui.cx) + pad, Y(ui.cy) + pad, t - 2 * pad, t - 2 * pad);

    // Status line.
    let text: string;
    if (state.reveal) {
      // Solve's reveal is always right, and saying "Correct!" to someone who gave up (or
      // who had just lost) reads as praise; say who solved it instead, as other games do.
      text = state.usedSolve
        ? tr('status.autoSolved')
        : isWon(state)
          ? tr('games.blackbox.status.correct')
          : tr('games.blackbox.status.wrong', { wrong: state.nWrong, n: state.nMissed });
    } else {
      const range = ballsText(state.minBalls, state.maxBalls);
      text = tr('games.blackbox.status.marked', {
        n: state.nGuesses,
        range,
        fired: state.nFired,
      });
      if (state.nGuesses > state.maxBalls)
        text += tr('games.blackbox.status.tooMany', { n: state.nGuesses - state.maxBalls });
      else if (state.nGuesses >= state.minBalls) text += tr('games.blackbox.status.check');
    }
    dr.statusBar(text);
  },

  animLength(oldState, newState, dir) {
    return readShot(oldState, newState, dir) ? SHOT_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.reveal && newState.reveal && isWon(newState) ? 4 * FLASH_FRAME : 0;
  },
  status(s) {
    if (!s.reveal) return 0;
    return isWon(s) ? 1 : -1;
  },
  wantsStatusBar: true,
  isTimed: false,
  flags: { lossRevealsAnswer: true },
});

export default game;
