/**
 * Deductive Range solver.
 *
 * Every step is a forced deduction, so whenever the deductions alone fill the grid the
 * puzzle has exactly that one solution. The three arguments, mirroring the original:
 *
 *  - **adjacency**: the four neighbours of a black cell are white;
 *  - **not too big**: a number that already sees its count has a black cell at the end of
 *    every white run; a single undecided cell whose whitening would join a further white
 *    run and push the count over the number is black; and when the other three directions
 *    cannot supply enough cells, the first few cells in the fourth direction are white;
 *  - **connectedness**: a cell whose blackening would cut the white region in two (a cut
 *    vertex of the graph of non-black cells) is white.
 *
 * `propagate()` runs these to a fixed point and says whether the grid is finished, and
 * `search()` branches on an undecided cell when they are not enough (for descriptions
 * typed in by hand, and for independent uniqueness checks in the tests). Contradictions
 * are detected along the way so that a wrong branch dies quickly.
 */
import { BLACK, EMPTY, WHITE } from './board';

/** Solver result codes. */
export const IMPOSSIBLE = -1;
export const UNFINISHED = 0;
export const SOLVED = 1;

const DX = [0, 1, 0, -1];
const DY = [-1, 0, 1, 0];

/** Run kinds for `Solver.run`. */
const K_WHITE = 0;
const K_EMPTY = 1;
const K_NOT_BLACK = 2;

export class Solver {
  readonly n: number;
  /** `EMPTY`, `WHITE` or `BLACK` per cell; numbered cells are `WHITE` from the start. */
  grid: Uint8Array;
  /** Set when a deduction contradicts an earlier one. */
  impossible = false;
  /** Decided cells in order as `cell * 4 + value`, when a log has been attached. */
  log: number[] | null = null;
  private undecided = 0;

  constructor(
    readonly clues: Uint8Array,
    readonly w: number,
    readonly h: number,
    grid?: Uint8Array,
  ) {
    this.n = w * h;
    this.grid = grid ? grid.slice() : new Uint8Array(this.n);
    for (let i = 0; i < this.n; i++) {
      if (clues[i] > 0) {
        if (this.grid[i] === BLACK) this.impossible = true;
        this.grid[i] = WHITE;
      }
      if (this.grid[i] === EMPTY) this.undecided++;
    }
  }

  clone(): Solver {
    const s = new Solver(this.clues, this.w, this.h, this.grid);
    s.impossible = this.impossible;
    return s;
  }

  /** Decide cell `i`; deciding it differently from before is a contradiction. */
  set(i: number, v: number): void {
    const cur = this.grid[i];
    if (cur === v) return;
    if (cur !== EMPTY) {
      this.impossible = true;
      return;
    }
    this.grid[i] = v;
    this.undecided--;
    this.log?.push(i * 4 + v);
  }

  private setXY(x: number, y: number, v: number): void {
    if (x >= 0 && y >= 0 && x < this.w && y < this.h) this.set(y * this.w + x, v);
  }

  /** Length of the run of cells of `kind` starting at (x, y) and going in direction `d`. */
  private run(x: number, y: number, d: number, kind: number): number {
    const { w, h, grid } = this;
    let len = 0;
    while (x >= 0 && y >= 0 && x < w && y < h) {
      const v = grid[y * w + x];
      if (kind === K_WHITE ? v !== WHITE : kind === K_EMPTY ? v !== EMPTY : v === BLACK) break;
      len++;
      x += DX[d];
      y += DY[d];
    }
    return len;
  }

  /** The four neighbours of every black cell are white. */
  adjacency(): void {
    const { n, w, grid } = this;
    for (let i = 0; i < n && !this.impossible; i++) {
      if (grid[i] !== BLACK) continue;
      const x = i % w;
      const y = (i - x) / w;
      for (let d = 0; d < 4; d++) this.setXY(x + DX[d], y + DY[d], WHITE);
    }
  }

  /** Everything that follows from a number's count, one number at a time. */
  notTooBig(): void {
    const { n, w, clues } = this;
    const white = [0, 0, 0, 0];
    const empty = [0, 0, 0, 0];
    const beyond = [0, 0, 0, 0];
    const space = [0, 0, 0, 0];
    for (let i = 0; i < n && !this.impossible; i++) {
      const clue = clues[i];
      if (!clue) continue;
      const x = i % w;
      const y = (i - x) / w;
      // In each direction: the definite whites next to the number, the undecided cells
      // after them, the whites after those, and the total non-black reach.
      let whites = 1;
      for (let d = 0; d < 4; d++) {
        let px = x + DX[d];
        let py = y + DY[d];
        white[d] = this.run(px, py, d, K_WHITE);
        px += DX[d] * white[d];
        py += DY[d] * white[d];
        empty[d] = this.run(px, py, d, K_EMPTY);
        px += DX[d] * empty[d];
        py += DY[d] * empty[d];
        beyond[d] = this.run(px, py, d, K_WHITE);
        px += DX[d] * beyond[d];
        py += DY[d] * beyond[d];
        space[d] = white[d] + empty[d] + beyond[d] + this.run(px, py, d, K_NOT_BLACK);
        whites += white[d];
      }
      if (whites > clue) {
        this.impossible = true;
        return;
      }
      for (let d = 0; d < 4; d++) {
        const bx = x + DX[d] * (white[d] + 1);
        const by = y + DY[d] * (white[d] + 1);
        if (whites === clue) {
          // Seeing enough already: the cell past each white run is black.
          this.setXY(bx, by, BLACK);
          continue;
        }
        if (whites + empty[d] + beyond[d] > clue) {
          // Whitening all the undecided cells would join the whites beyond them and see
          // too much, so at least one of them is black: the reach shrinks, and a lone
          // undecided cell is the black one.
          if (empty[d] === 1) this.setXY(bx, by, BLACK);
          space[d] = white[d] + empty[d] - 1;
        }
      }
      const total = 1 + space[0] + space[1] + space[2] + space[3];
      if (total < clue) {
        this.impossible = true;
        return;
      }
      for (let d = 0; d < 4; d++) {
        // What the other three directions cannot supply, this one must.
        const need = clue - (total - space[d]);
        for (let k = 1; k <= need; k++) this.setXY(x + DX[d] * k, y + DY[d] * k, WHITE);
      }
    }
  }

  /**
   * Cut vertices of the graph of non-black cells are white, since painting one black
   * would split the white region. Finding the non-black cells already split is a
   * contradiction (every component holds a white cell on any grid bigger than one cell).
   */
  connectedness(): void {
    const { n, w, h, grid } = this;
    let root = 0;
    while (root < n && grid[root] === BLACK) root++;
    if (root >= n) return;
    const depth = new Int32Array(n).fill(-1);
    let visited = 0;
    const visit = (i: number, parent: number, d: number): number => {
      depth[i] = d;
      visited++;
      let low = d;
      let children = 0;
      const x = i % w;
      const y = (i - x) / w;
      for (let k = 0; k < 4; k++) {
        const nx = x + DX[k];
        const ny = y + DY[k];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        const j = ny * w + nx;
        if (grid[j] === BLACK) continue;
        if (depth[j] < 0) {
          children++;
          const childLow = visit(j, i, d + 1);
          if (childLow >= d && d > 0) this.set(i, WHITE);
          if (childLow < low) low = childLow;
        } else if (j !== parent && depth[j] < low) {
          low = depth[j];
        }
      }
      if (d === 0 && children >= 2) this.set(i, WHITE);
      return low;
    };
    visit(root, -1, 0);
    let nonBlack = 0;
    for (let i = 0; i < n; i++) if (grid[i] !== BLACK) nonBlack++;
    if (visited < nonBlack && n > 1) this.impossible = true;
  }

  /** Run every deduction to a fixed point. */
  propagate(): number {
    while (!this.impossible) {
      const before = this.undecided;
      this.adjacency();
      if (this.impossible) break;
      this.notTooBig();
      if (this.impossible) break;
      this.connectedness();
      if (this.undecided === before) break;
    }
    if (this.impossible) return IMPOSSIBLE;
    return this.undecided === 0 ? SOLVED : UNFINISHED;
  }

  /**
   * Deductions plus branching: find up to `limit` solutions (as full grids of
   * `BLACK`/`WHITE`) and append them to `out`.
   */
  search(limit: number, out: Uint8Array[] = []): Uint8Array[] {
    const r = this.propagate();
    if (r === IMPOSSIBLE) return out;
    if (r === SOLVED) {
      out.push(this.grid.slice());
      return out;
    }
    let i = 0;
    while (this.grid[i] !== EMPTY) i++;
    for (const v of [BLACK, WHITE]) {
      const branch = this.clone();
      branch.set(i, v);
      branch.search(limit, out);
      if (out.length >= limit) break;
    }
    return out;
  }
}

/** Whether the deductions alone finish the puzzle from a blank grid. */
export function solvesDeductively(clues: Uint8Array, w: number, h: number): boolean {
  return new Solver(clues, w, h).propagate() === SOLVED;
}

/** A solution (full grid of `BLACK`/`WHITE`) found by deduction and search, or null. */
export function findSolution(clues: Uint8Array, w: number, h: number): Uint8Array | null {
  return new Solver(clues, w, h).search(1)[0] ?? null;
}

/** The number of solutions, counting up to `limit`. */
export function countSolutions(clues: Uint8Array, w: number, h: number, limit = 2): number {
  return new Solver(clues, w, h).search(limit).length;
}

/**
 * One cell the player could decide next from the position `grid` (the player's dots
 * taken as true): the first forced deduction if there is one, otherwise a cell from a
 * solution found by search. Null when the position is contradictory or solved.
 */
export function hint(
  clues: Uint8Array,
  w: number,
  h: number,
  grid: Uint8Array,
): { cell: number; value: number } | null {
  const s = new Solver(clues, w, h, grid);
  s.log = [];
  const r = s.propagate();
  if (r === IMPOSSIBLE) return null;
  if (s.log.length > 0) return { cell: s.log[0] >> 2, value: s.log[0] & 3 };
  if (r === SOLVED) return null;
  const solution = s.search(1)[0];
  if (!solution) return null;
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] === EMPTY && clues[i] === 0) return { cell: i, value: solution[i] };
  }
  return null;
}
