export interface MinesParams {
  w: number;
  h: number;
  n: number;
  /** Generate grids that can be solved without guessing. */
  unique: boolean;
}

/** Values in the knowledge grid besides 0–8 (an open square's neighbour count). */
export const COVERED = -2;
export const FLAG = -1;
/** A mine shown when the game was lost. */
export const SHOWN_MINE = 64;
/** The mine that was stepped on. */
export const HIT_MINE = 65;
/** A flag on a square that turned out not to hold a mine. */
export const WRONG_FLAG = 66;

export interface MinesState {
  w: number;
  h: number;
  /** Mines in the layout, or the number promised for one that is still to be generated. */
  n: number;
  unique: boolean;
  /** Seed for generating the layout at the first click; null once it exists. */
  seed: string | null;
  /** 1 where there is a mine; null until the first click. */
  mines: Uint8Array | null;
  /** What the player knows about each square. */
  grid: Int8Array;
  dead: boolean;
  won: boolean;
  usedSolve: boolean;
  /** The square the generated layout was opened from, once it exists (for sharing). */
  start?: number;
}

export interface MinesUI extends HintMark {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** Square under a held button (-1 for none) and how far the pressed look extends. */
  hx: number;
  hy: number;
  hradius: number;
  /** Whether the pending release may clear around a number (1) or only open one square (0). */
  validRadius: number;
  /** Mines stepped on so far; Undo does not take these back. */
  deaths: number;
  /** The grid has been completed at some point, so the clock stays stopped. */
  completed: boolean;
  flashIsDeath: boolean;
}

const FLASH_FRAME = 0.13;
const MAX_SIDE = 50;
const NUMBER_COLOURS = ['', 'blue', 'green', 'red', 'purple', 'brown', 'teal', 'ink', 'pencil'];
const DEFAULTS: MinesParams = { w: 9, h: 9, n: 10, unique: true };

function boardBorder(t: number): number {
  return Math.round(t * 0.35);
}

function countMines(mines: Uint8Array): number {
  let n = 0;
  for (let i = 0; i < mines.length; i++) n += mines[i];
  return n;
}

function flagsAround(grid: Int8Array, w: number, h: number, x: number, y: number): number {
  let n = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < w && ny >= 0 && ny < h && grid[ny * w + nx] === FLAG) n++;
    }
  }
  return n;
}

/** Covered, unflagged neighbours of (x, y) as square indices. */
function coveredAround(grid: Int8Array, w: number, h: number, x: number, y: number): number[] {
  const out: number[] = [];
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < w && ny >= 0 && ny < h && grid[ny * w + nx] === COVERED)
        out.push(ny * w + nx);
    }
  }
  return out;
}

/** Whether (x, y) has an opened number beside it: the edge the player is working along. */
function touchesOpen(grid: Int8Array, w: number, h: number, i: number): boolean {
  const x = i % w;
  const y = (i - x) / w;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx;
      const ny = y + dy;
      if ((dx === 0 && dy === 0) || nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
      if (grid[ny * w + nx] >= 0) return true;
    }
  }
  return false;
}

/** The game is lost: show every mine and cross out every misplaced flag. */
function explode(state: MinesState, hit: number): MinesState {
  const mines = state.mines!;
  const grid = state.grid.slice();
  for (let i = 0; i < grid.length; i++) {
    if (mines[i] && grid[i] === COVERED) grid[i] = SHOWN_MINE;
    else if (!mines[i] && grid[i] === FLAG) grid[i] = WRONG_FLAG;
  }
  grid[hit] = HIT_MINE;
  return { ...state, grid, dead: true };
}

/**
 * Open the given covered squares, spreading through empty ones, and check for a win.
 * Stepping on a mine loses the game before anything is opened.
 */
function openSquares(state: MinesState, squares: number[]): MinesState {
  const { w, h } = state;
  const mines = state.mines!;
  for (const i of squares) if (state.grid[i] === COVERED && mines[i]) return explode(state, i);
  const grid = state.grid.slice();
  const queue: number[] = [];
  for (const i of squares) {
    if (grid[i] !== COVERED) continue;
    grid[i] = countAround(mines, w, h, i % w, Math.floor(i / w));
    queue.push(i);
  }
  while (queue.length) {
    const i = queue.pop()!;
    if (grid[i] !== 0) continue;
    const x = i % w;
    const y = (i - x) / w;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        const j = ny * w + nx;
        if (grid[j] !== COVERED) continue;
        grid[j] = countAround(mines, w, h, nx, ny);
        queue.push(j);
      }
    }
  }
  let covered = 0;
  for (let i = 0; i < grid.length; i++) if (grid[i] < 0) covered++;
  if (covered === state.n) {
    for (let i = 0; i < grid.length; i++) if (grid[i] < 0) grid[i] = FLAG;
    return { ...state, grid, won: true };
  }
  return { ...state, grid };
}

/** The fully revealed grid: every mine flagged, every safe square open. */
function solveState(state: MinesState): MinesState {
  const { w, h } = state;
  const mines = state.mines!;
  const grid = new Int8Array(w * h);
  for (let i = 0; i < grid.length; i++)
    grid[i] = mines[i] ? FLAG : countAround(mines, w, h, i % w, Math.floor(i / w));
  return { ...state, grid, won: true, usedSolve: true };
}

function layoutFor(state: MinesState, x: number, y: number): Uint8Array {
  return generateLayout(state.w, state.h, state.n, x, y, state.unique, new Random(state.seed!));
}

/** The move that opens (x, y); the first one also carries the freshly generated layout. */
function openMove(state: MinesState, ui: MinesUI, x: number, y: number): string {
  if (state.mines) {
    if (state.mines[y * state.w + x]) ui.deaths++;
    return `O${x},${y}`;
  }
  return `L${encodeLayout(layoutFor(state, x, y), false)};O${x},${y}`;
}

/** Clear around a satisfied number: the move, or '' when there is nothing to do. */
function clearMove(state: MinesState, ui: MinesUI, x: number, y: number): string {
  const { w, h, grid } = state;
  const v = grid[y * w + x];
  if (v <= 0 || flagsAround(grid, w, h, x, y) !== v) return '';
  if (coveredAround(grid, w, h, x, y).some((i) => state.mines![i])) ui.deaths++;
  return `C${x},${y}`;
}

// ------------------------------------------------------------------ drawing bits

function drawCovered(dr: Drawing, x: number, y: number, t: number, seed: number, alpha = 1): void {
  if (alpha <= 0) return;
  const pad = Math.max(1, t * 0.06);
  const r = t * 0.14;
  const lift = Math.max(1, t * 0.05);
  dr.roundRect(x + pad + lift, y + pad + lift, t - 2 * pad, t - 2 * pad, r, 'lowlight', null, {
    seed,
    alpha,
  });
  dr.roundRect(x + pad, y + pad, t - 2 * pad, t - 2 * pad, r, 'shade', 'pencil', {
    seed,
    width: 1.3,
    alpha,
  });
}

/**
 * How long an opening takes to spread, and the shape of it. A click on a blank square can
 * uncover sixty at once, and all sixty used to appear in the same frame — a flash-bang
 * where the game's best moment is a lid coming off. `readOpening` finds the squares that
 * were uncovered and where the spread started; each one then lifts when the ripple
 * reaches it, in the same way Net's completion flash travels out from its source.
 */
const OPEN_STEP = 0.035;
const OPEN_LIFT = 0.1;

/**
 * How fast the ripple travels, and how long the whole thing takes. An Expert board can
 * open forty squares deep, so the step shrinks on a big one: a spread is a beat, never a
 * wait, and it is capped at a little under half a second however far it has to go.
 */
function openStep(far: number): number {
  return Math.min(OPEN_STEP, 0.35 / Math.max(1, far));
}
function openingTime(far: number): number {
  return OPEN_LIFT + far * openStep(far);
}

function readOpening(
  oldState: MinesState,
  newState: MinesState,
  dir: number,
): { dist: Int16Array; far: number } | null {
  const earlier = dir > 0 ? oldState : newState;
  const later = dir > 0 ? newState : oldState;
  // Dying reveals the whole board at once and has a flash of its own to deliver; it is
  // not an opening and should not be kept waiting behind one.
  if (later.dead || earlier.grid.length !== later.grid.length) return null;
  const { w, grid } = earlier;
  const opened: number[] = [];
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] === later.grid[i]) continue;
    if (grid[i] !== COVERED || later.grid[i] < 0) return null;
    opened.push(i);
  }
  if (opened.length < 2) return null;
  // Where the click was is not recorded anywhere by the time this runs, so the spread
  // starts from the uncovered square nearest the middle of what was uncovered — which for
  // a flood fill is within a square or two of the real thing, and reads the same.
  let cx = 0;
  let cy = 0;
  for (const i of opened) {
    cx += i % w;
    cy += Math.floor(i / w);
  }
  cx /= opened.length;
  cy /= opened.length;
  let origin = opened[0];
  let best = Infinity;
  for (const i of opened) {
    const d = Math.hypot((i % w) - cx, Math.floor(i / w) - cy);
    if (d < best) {
      best = d;
      origin = i;
    }
  }
  const ox = origin % w;
  const oy = Math.floor(origin / w);
  const dist = new Int16Array(grid.length).fill(-1);
  let far = 0;
  for (const i of opened) {
    const d = Math.max(Math.abs((i % w) - ox), Math.abs(Math.floor(i / w) - oy));
    dist[i] = d;
    if (d > far) far = d;
  }
  return { dist, far };
}

function drawFlag(dr: Drawing, x: number, y: number, t: number, seed: number): void {
  const pole = x + t * 0.42;
  const lw = Math.max(1.4, t * 0.06);
  dr.line(pole, y + t * 0.2, pole, y + t * 0.78, 'ink', lw, { seed });
  dr.line(x + t * 0.27, y + t * 0.78, x + t * 0.63, y + t * 0.78, 'ink', lw, { seed: seed + 1 });
  dr.polygon(
    [pole, y + t * 0.2, x + t * 0.74, y + t * 0.36, pole, y + t * 0.52],
    'accent',
    'accent',
    {
      seed,
      width: 1,
    },
  );
}

function drawMine(dr: Drawing, x: number, y: number, t: number, seed: number): void {
  const cx = x + t / 2;
  const cy = y + t / 2;
  const r = t * 0.24;
  const lw = Math.max(1.5, t * 0.07);
  for (let k = 0; k < 8; k++) {
    const a = (k * Math.PI) / 4;
    const c = Math.cos(a);
    const s = Math.sin(a);
    dr.line(cx + c * r * 0.6, cy + s * r * 0.6, cx + c * r * 1.55, cy + s * r * 1.55, 'ink', lw, {
      seed: seed * 8 + k,
    });
  }
  dr.circle(cx, cy, r, 'ink', null, { seed });
  dr.dot(cx - r * 0.35, cy - r * 0.35, r * 0.22, 'highlight');
}

// ------------------------------------------------------------------ the game

const game = defineGame<MinesParams, MinesState, MinesUI>({
  id: 'mines',
  name: 'Mines',
  description: 'Uncover every square that is not a mine; you never have to guess.',
  alsoKnownAs: 'Minesweeper',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [9, 9, 10, '9×9 Beginner, 10 mines'],
      [9, 9, 35, '9×9, 35 mines'],
      [16, 16, 40, '16×16 Intermediate, 40 mines'],
      [16, 16, 99, '16×16, 99 mines'],
      [30, 16, 99, '30×16 Expert, 99 mines'],
      [30, 16, 170, '30×16, 170 mines'],
    ] as [number, number, number, string][]
  ).map(([w, h, n, name]) => ({ name, params: { w, h, n, unique: true } })),
  defaultParams: () => ({ ...DEFAULTS }),
  // The mine count only matters for generation: a layout description carries its own.
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? `n${p.n}${p.unique ? '' : 'a'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    const rest = str.slice(m[0].length);
    const nm = /n(\d+)/.exec(rest);
    return {
      w,
      h,
      n: nm ? parseInt(nm[1], 10) : Math.floor((w * h) / 10),
      unique: !rest.includes('a'),
    };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.n].every(Number.isInteger)) return tx`All parameters must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must both be at least one`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && p.unique && (p.w <= 2 || p.h <= 2))
      return tx`Width and height must both be greater than two`;
    if (full && p.n < 1) return tx`There must be at least one mine`;
    if (full && p.n > p.w * p.h - 9) return tx`Too many mines for grid size`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: 'Mines', value: String(p.n) },
      { type: 'boolean', name: 'Ensure solubility', value: p.unique },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    const int = (v: string) => (/^-?\d+$/.test(v) ? parseInt(v, 10) : NaN);
    const w = int(str(0));
    const h = int(str(1));
    // Mines may be given as a percentage of the grid, e.g. "20%".
    const minesStr = str(2);
    const pct = /^(.*?)\s*%$/.exec(minesStr);
    let n = int(pct ? pct[1] : minesStr);
    if (pct) n = Math.floor((n * w * h) / 100);
    return { w, h, n, unique: (items[3] as { value: boolean }).value };
  },

  newDesc(p, rng: Random, interactive) {
    // Draw a first-click position even when it is not used, so a seed generates the
    // same layout whether played interactively (clicking there) or in batch.
    const x = rng.upto(p.w);
    const y = rng.upto(p.h);
    let seed = '';
    for (let i = 0; i < 4; i++) seed += rng.next().toString(16).padStart(8, '0');
    if (interactive) return { desc: `r${p.n},${p.unique ? 'u' : 'a'},${seed}` };
    const mines = generateLayout(p.w, p.h, p.n, x, y, p.unique, new Random(seed));
    return { desc: describeLayout(mines, x, y) };
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  settledDesc(state) {
    // A layout that came with the description is already what `gameId` names.
    if (!state.mines || state.start === undefined || state.start < 0) return null;
    return describeLayout(state.mines, state.start % state.w, Math.floor(state.start / state.w));
  },

  newGame(p, desc) {
    const { w, h } = p;
    const r = parseDesc(desc, w, h) as ParsedDesc;
    const grid = new Int8Array(w * h).fill(COVERED);
    const base = { w, h, grid, dead: false, won: false, usedSolve: false };
    if (r.kind === 'pending')
      return { ...base, n: r.n, unique: r.unique, seed: r.seed, mines: null };
    const state: MinesState = {
      ...base,
      n: countMines(r.mines),
      unique: p.unique,
      seed: null,
      mines: r.mines,
    };
    return r.x >= 0 ? openSquares({ ...state, start: r.y * w + r.x }, [r.y * w + r.x]) : state;
  },

  canSolve: true,
  solve(_orig, curr) {
    if (curr.dead) throw new Error(tx`You have hit a mine; undo that move first`);
    if (curr.won) throw new Error(tx`Already solved`);
    if (curr.mines) return 'S';
    // Not started: settle the layout as if the middle square had been clicked.
    const x = curr.w >> 1;
    const y = curr.h >> 1;
    return `L${encodeLayout(layoutFor(curr, x, y), false)};S`;
  },

  /**
   * One square, and never a fatal one. A flag on a square that holds no mine comes first,
   * because a player stuck behind a wrong flag can deduce nothing at all; otherwise a
   * safe square is opened, preferring one beside a number already on the board so the
   * help lands where the player is working rather than in an untouched corner.
   */
  hint(_orig, curr, _aux, ui) {
    if (curr.dead || curr.won) return null;
    const { w, h, grid } = curr;
    const at = (i: number) => `${i % w},${Math.floor(i / w)}`;
    // Nothing is settled until the first square is opened, so that first click is the
    // step — with the layout it generates, exactly as a click of the player's own.
    if (!curr.mines) {
      // The middle square, or the unflagged one nearest it: a flag the player has already
      // put there cannot be opened, and the move would be refused.
      let best = -1;
      let bestD = Infinity;
      for (let i = 0; i < grid.length; i++) {
        if (grid[i] !== COVERED) continue;
        const d = Math.abs((i % w) - (w >> 1)) + Math.abs(Math.floor(i / w) - (h >> 1));
        if (d < bestD) {
          bestD = d;
          best = i;
        }
      }
      if (best < 0) return null;
      const x = best % w;
      const y = Math.floor(best / w);
      const layout = encodeLayout(layoutFor(curr, x, y), false);
      return markHint(ui, y * w + x, `L${layout};O${x},${y}`);
    }
    const mines = curr.mines;
    for (let i = 0; i < grid.length; i++) {
      if (grid[i] === FLAG && !mines[i]) return markHint(ui, i, `F${at(i)}`);
    }
    for (const frontier of [true, false]) {
      for (let i = 0; i < grid.length; i++) {
        if (grid[i] !== COVERED || mines[i]) continue;
        if (frontier && !touchesOpen(grid, w, h, i)) continue;
        return markHint(ui, i, `O${at(i)}`);
      }
    }
    // Every safe square is open already: the rest are mines, so mark one.
    for (let i = 0; i < grid.length; i++) {
      if (grid[i] === COVERED) return markHint(ui, i, `F${at(i)}`);
    }
    return null;
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const v = s.grid[y * s.w + x];
        row +=
          v === 0
            ? '-'
            : v > 0 && v <= 8
              ? String(v)
              : v === FLAG
                ? '*'
                : v === COVERED
                  ? '?'
                  : '!';
      }
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI: () => ({
    ...noHint(),
    cx: 0,
    cy: 0,
    cursorVisible: false,
    hx: -1,
    hy: -1,
    hradius: 0,
    validRadius: 0,
    deaths: 0,
    completed: false,
    flashIsDeath: false,
  }),
  encodeUI: (ui) => `D${ui.deaths}${ui.completed ? 'C' : ''}`,
  decodeUI(ui, enc) {
    const m = /^D(\d+)(C?)$/.exec(enc);
    if (!m) return;
    ui.deaths = parseInt(m[1], 10);
    ui.completed = m[2] === 'C';
  },
  changedState(ui, _old, next) {
    if (next.won) ui.completed = true;
    // A press still held when Undo or a hint changes the board is dropped: releasing it
    // must not open or clear squares on a board it was not made on.
    ui.hx = ui.hy = -1;
    ui.hradius = 0;
    ui.validRadius = -1;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    if (state.dead || state.won) return null;
    const { w, h, grid } = state;

    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const v = grid[ui.cy * w + ui.cx];
      if (b === CURSOR_SELECT2) return v === COVERED || v === FLAG ? `F${ui.cx},${ui.cy}` : null;
      if (v === COVERED) return openMove(state, ui, ui.cx, ui.cy);
      return clearMove(state, ui, ui.cx, ui.cy);
    }

    const t = ds.tileSize;
    const border = boardBorder(t);
    const cx = Math.floor((mx - border) / t);
    const cy = Math.floor((my - border) / t);
    const inside = cx >= 0 && cx < w && cy >= 0 && cy < h;

    if (b === LEFT_BUTTON || b === LEFT_DRAG || b === MIDDLE_BUTTON || b === MIDDLE_DRAG) {
      // A press dropped by a board change stays dropped until the button is let go.
      if ((b === LEFT_DRAG || b === MIDDLE_DRAG) && ui.validRadius < 0) return null;
      if (!inside) {
        if (ui.hx < 0) return null;
        ui.hx = ui.hy = -1;
        return '';
      }
      // Pressing only shows which squares a release would affect.
      ui.hx = cx;
      ui.hy = cy;
      ui.hradius = grid[cy * w + cx] >= 0 ? 1 : 0;
      if (b === LEFT_BUTTON) ui.validRadius = ui.hradius;
      else if (b === MIDDLE_BUTTON) ui.validRadius = 1;
      ui.cursorVisible = false;
      return '';
    }
    if (b === RIGHT_BUTTON) {
      if (!inside) return null;
      const v = grid[cy * w + cx];
      if (v !== COVERED && v !== FLAG) return null;
      ui.cursorVisible = false;
      return `F${cx},${cy}`;
    }
    if (b === LEFT_RELEASE || b === MIDDLE_RELEASE) {
      ui.hx = ui.hy = -1;
      ui.hradius = 0;
      if (!inside) return '';
      const v = grid[cy * w + cx];
      if (b === LEFT_RELEASE && v === COVERED && ui.validRadius === 0)
        return openMove(state, ui, cx, cy);
      if (ui.validRadius === 1) return clearMove(state, ui, cx, cy);
      return '';
    }
    return null;
  },

  executeMove(state, move) {
    const { w, h } = state;
    if (state.dead || state.won) return null;
    let cur = state;
    for (const cmd of move.split(';')) {
      if (cmd[0] === 'L') {
        if (cur.mines) return null;
        const mines = decodeLayout(cmd.slice(1), w * h, false);
        if (!mines) return null;
        cur = { ...cur, mines, n: countMines(mines), seed: null, start: -1 };
        continue;
      }
      if (cmd === 'S') {
        if (!cur.mines) return null;
        cur = solveState(cur);
        break;
      }
      const m = /^([FOC])(\d+),(\d+)$/.exec(cmd);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      const i = y * w + x;
      const v = cur.grid[i];
      if (m[1] === 'F') {
        if (v !== COVERED && v !== FLAG) return null;
        const grid = cur.grid.slice();
        grid[i] = v === COVERED ? FLAG : COVERED;
        cur = { ...cur, grid };
      } else if (m[1] === 'O') {
        if (!cur.mines || v !== COVERED) return null;
        // The first square opened on a layout generated in play is the one it was made for.
        if (cur.start === -1) cur = { ...cur, start: i };
        cur = openSquares(cur, [i]);
      } else {
        if (!cur.mines || v <= 0 || flagsAround(cur.grid, w, h, x, y) !== v) return null;
        const around = coveredAround(cur.grid, w, h, x, y);
        if (around.length) cur = openSquares(cur, around);
      }
      if (cur.dead || cur.won) break;
    }
    return cur;
  },

  preferredTileSize: 32,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, grid } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const hintCell = hintFlashCell(ui, flashTime);
    // A hint owns the flash it asked for: only a finished game recolours the board.
    const flash = !hintFlashing(ui) && flashOn(flashTime, FLASH_FRAME);
    const winFlash = flash && !ui.flashIsDeath;

    dr.rect(b, b, w * t, h * t, winFlash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(b + x * t, b, b + x * t, b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, b + y * t, b + w * t, b + y * t, 'faint', 1.2);

    // An opening still spreading: every square it has not reached yet keeps its lid on,
    // and the ones it has just reached lift theirs.
    const opening = oldState ? readOpening(oldState, state, dir) : null;
    // `animTime` always counts up from the board on screen a moment ago, so an undo runs
    // the same clock backwards and the lids drop back on in reverse.
    const elapsed = opening ? (dir > 0 ? animTime : openingTime(opening.far) - animTime) : 0;

    let flags = 0;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const v = grid[i];
        const px = b + x * t;
        const py = b + y * t;
        if (v === FLAG) flags++;
        if (v === COVERED || v === FLAG) {
          const pressed =
            v === COVERED &&
            ui.hx >= 0 &&
            Math.abs(x - ui.hx) <= ui.hradius &&
            Math.abs(y - ui.hy) <= ui.hradius;
          if (!pressed) drawCovered(dr, px, py, t, i);
          if (v === FLAG) drawFlag(dr, px, py, t, i);
        } else if (v >= 1 && v <= 8) {
          if (flagsAround(grid, w, h, x, y) > v)
            dr.rect(px, py, t, t, 'error', null, { alpha: 0.18 });
          dr.text(px + t / 2, py + t / 2, String(v), {
            size: t * 0.62,
            bold: true,
            colour: winFlash ? 'ok' : NUMBER_COLOURS[v],
          });
        } else if (v >= SHOWN_MINE) {
          if (v === HIT_MINE) dr.rect(px, py, t, t, 'error');
          drawMine(dr, px, py, t, i);
          if (v === WRONG_FLAG)
            dr.cross(px + t / 2, py + t / 2, t * 0.36, 'error', Math.max(2, t * 0.09), { seed: i });
        }
        // The lid still coming off this square, over whatever it was hiding. Squares the
        // ripple has not reached yet are still fully covered, which is what makes the
        // opening travel rather than simply fade.
        if (opening && opening.dist[i] >= 0) {
          const off = clamp((elapsed - opening.dist[i] * openStep(opening.far)) / OPEN_LIFT, 0, 1);
          drawCovered(dr, px, py, t, i, 1 - off);
        }
      }
    }
    if (flash && ui.flashIsDeath) dr.rect(b, b, w * t, h * t, 'error', null, { alpha: 0.35 });
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (hintCell >= 0) {
      dr.hintBox(b + (hintCell % w) * t, b + Math.floor(hintCell / w) * t, t, t);
    }

    if (ui.cursorVisible) {
      const inset = t * 0.1;
      const args = [
        b + ui.cx * t + inset,
        b + ui.cy * t + inset,
        t - 2 * inset,
        t - 2 * inset,
      ] as const;
      dr.cursor(...args, 'paper', 4.5);
      dr.cursor(...args, 'accent', 2.2);
    }

    let text = state.dead
      ? tr('status.dead')
      : state.won
        ? state.usedSolve
          ? tr('status.autoSolved')
          : tr('status.completed')
        : tr('games.mines.status.marked', { n: flags, total: state.n });
    if (ui.deaths) text += tr('games.mines.status.deaths', { n: ui.deaths });
    dr.statusBar(text);
  },

  animLength(oldState, newState, dir) {
    const opening = readOpening(oldState, newState, dir);
    return opening ? openingTime(opening.far) : 0;
  },
  flashLength(oldState, newState, dir, ui) {
    const hint = takeHintFlash(ui);
    if (hint > 0) ui.flashIsDeath = false;
    if (oldState.usedSolve || newState.usedSolve) return 0;
    if (dir > 0 && !oldState.dead && !oldState.won) {
      if (newState.dead) {
        ui.flashIsDeath = true;
        return 3 * FLASH_FRAME;
      }
      if (newState.won) {
        ui.flashIsDeath = false;
        return 2 * FLASH_FRAME;
      }
    }
    return hint;
  },
  status: (s) => (s.dead ? -1 : s.won ? 1 : 0),
  wantsStatusBar: true,
  isTimed: true,
  timingState: (s, ui) => s.mines !== null && !s.dead && !s.won && !ui.completed,
  // Stepping on a mine is one click to take back, and the help promises exactly that.
  flags: { buttonBeats: [[LEFT_BUTTON, RIGHT_BUTTON]], undoAfterLoss: true },
  thumbnailParams: { w: 9, h: 9, n: 10, unique: true },
});

export default game;
