/**
 * The press every control makes, for the presses CSS cannot see.
 *
 * `:active` covers a held mouse button, but a tap on a phone can be over before a frame
 * has painted it, and a key press (Enter, Space, a gamepad's A through ui/nav.ts) never
 * sets it at all — so those buttons never went down. This puts `.pressing` on whatever was
 * pressed for at least {@link MIN_PRESS_MS}, and feel.css draws `.pressing` exactly as it
 * draws `:active`. It never delays or swallows the press itself: the click goes through
 * the moment it would have anyway, and only the drawing lingers.
 *
 * Also here, since they are the same kind of thing — the page answering a finger as a
 * game does, not as a document: no ghost image dragged off a link or a card, and no
 * pinch-zoom of the whole shell on iOS, which ignores `touch-action` for pinches.
 */

/** Long enough to be seen on a 60 Hz screen, short enough never to feel held. */
export const MIN_PRESS_MS = 110;

/** What goes down when pressed; matches the selectors in feel.css. */
export const PRESSABLE = 'button, .btn, .keypad .key, .card, [role="button"]';

let installed = false;

/** The pressable under `target`, if it can be pressed right now. */
function pressable(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) return null;
  const el = target.closest<HTMLElement>(PRESSABLE);
  if (!el || (el as HTMLButtonElement).disabled || el.getAttribute('aria-disabled') === 'true')
    return null;
  return el;
}

/**
 * Show `el` pressed, and let it up no sooner than {@link MIN_PRESS_MS} from now once
 * `release` is called. Returns that release.
 */
export function pressFor(el: HTMLElement): () => void {
  const since = performance.now();
  el.classList.add('pressing');
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const wait = Math.max(0, MIN_PRESS_MS - (performance.now() - since));
    window.setTimeout(() => el.classList.remove('pressing'), wait);
  };
}

export function installPress(): void {
  if (installed || typeof document === 'undefined') return;
  installed = true;

  let pointerUp: (() => void) | null = null;
  const up = () => {
    pointerUp?.();
    pointerUp = null;
  };
  document.addEventListener(
    'pointerdown',
    (e) => {
      if (e.button !== 0) return;
      up();
      const el = pressable(e.target);
      if (el) pointerUp = pressFor(el);
    },
    true,
  );
  for (const type of ['pointerup', 'pointercancel', 'dragstart'] as const)
    document.addEventListener(type, up, true);
  window.addEventListener('blur', up);

  // Enter and Space on a focused control: down on the key, up when it is let go.
  const keysDown = new Map<string, () => void>();
  document.addEventListener(
    'keydown',
    (e) => {
      if (e.repeat || (e.key !== 'Enter' && e.key !== ' ')) return;
      if (keysDown.has(e.key)) return;
      const el = pressable(document.activeElement);
      if (el) keysDown.set(e.key, pressFor(el));
    },
    true,
  );
  document.addEventListener(
    'keyup',
    (e) => {
      keysDown.get(e.key)?.();
      keysDown.delete(e.key);
    },
    true,
  );
  window.addEventListener('blur', () => {
    keysDown.forEach((release) => release());
    keysDown.clear();
  });

  // Nothing on the page is carried off by a drag: a link or a card would otherwise leave a
  // ghost of itself under the pointer (Firefox has no CSS for this). A field's own text
  // may still be dragged.
  document.addEventListener('dragstart', (e) => {
    const t = e.target;
    if (t instanceof Element && t.closest('input, textarea, [contenteditable="true"]')) return;
    e.preventDefault();
  });

  // Safari's own pinch, which `touch-action` does not stop there. The board handles its
  // pinches itself with pointer events, which these gesture events do not touch.
  for (const type of ['gesturestart', 'gesturechange'])
    document.addEventListener(type, (e) => e.preventDefault(), { passive: false });
}
