/**
 * `#/achievements`: the whole shelf. The collection-wide badges first, then every game's
 * own under its name, in the menu's running order. Earned ones in colour with the date;
 * the rest greyed, with a progress bar where there is something to count; a secret one
 * shows only a question mark until it is found.
 *
 * `#/achievements/<slug>` opens the same page turned to that game's badges.
 *
 * A fixed screen like the collection: one shelf of badges that turns pages (`pager.ts`)
 * rather than a long document of sections, each game's badges carrying its name.
 */
import {
  ACHIEVEMENTS,
  achievementProgress,
  achievementTotals,
  earnedAt,
  onAchievement,
  type Achievement,
} from '../achievements';
import { badgeSVG } from '../achievements/art';
import { menuGames } from '../games/registry';
import { gameName, getLocale, t } from '../i18n';
import { achievementCopy } from './achievementToast';
import { staggerIn } from './anim';
import { createPager } from './pager';
import { backButton } from './backButton';

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

function formatDate(ms: number): string {
  try {
    return new Intl.DateTimeFormat(getLocale(), { dateStyle: 'medium' }).format(ms);
  } catch {
    return new Date(ms).toLocaleDateString();
  }
}

function tile(a: Achievement, group?: string): HTMLElement {
  const when = earnedAt(a.key);
  const earned = when !== undefined;
  const secret = a.hidden && !earned;
  const card = el('li', `ach-tile tier-${a.tier}${earned ? ' earned' : ' locked'}`);
  card.dataset.key = a.key;
  const art = el('div', 'ach-art');
  art.innerHTML = badgeSVG({ key: a.key, tier: a.tier, hue: a.hue, art: a.art, secret });
  const body = el('div', 'ach-body');
  const copy = secret
    ? {
        name: t('ui.achievements.secret.name'),
        description: t('ui.achievements.secret.description'),
      }
    : achievementCopy(a);
  // Which puzzle a badge belongs to, now that the shelf is one run rather than a section
  // per game under its own heading.
  if (group) body.append(el('span', 'ach-game', group));
  const title = el('h3', 'ach-name', copy.name);
  const tier = el('span', 'ach-tier', t(`ui.achievements.tier.${a.tier}`));
  body.append(title, el('p', 'ach-desc', copy.description));
  const foot = el('div', 'ach-foot');
  foot.append(tier);
  if (earned) {
    foot.append(el('span', 'ach-date', t('ui.achievements.earnedOn', { date: formatDate(when) })));
  } else {
    const prog = achievementProgress(a);
    if (prog && prog.goal > 1) {
      const bar = el('span', 'ach-bar');
      bar.style.setProperty('--fill', String(prog.n / prog.goal));
      bar.setAttribute('role', 'progressbar');
      bar.setAttribute('aria-valuemin', '0');
      bar.setAttribute('aria-valuemax', String(prog.goal));
      bar.setAttribute('aria-valuenow', String(prog.n));
      const label = t('ui.achievements.progress', { n: prog.n, goal: prog.goal });
      bar.setAttribute('aria-label', label);
      foot.append(bar, el('span', 'ach-count', label));
    }
  }
  body.append(foot);
  card.append(art, body);
  return card;
}

export function renderAchievementsPage(root: HTMLElement, focusSlug = ''): { destroy(): void } {
  document.title = `${t('ui.achievements.title')} · ${t('ui.appName')}`;
  document.documentElement.classList.add('screen');
  const page = el('div', 'achievements-page');

  const header = el('header', 'topbar ach-topbar');
  const back = backButton();
  const title = el('h1', 'title', t('ui.achievements.title'));
  header.append(back, title);

  const summary = el('div', 'ach-summary sketch');
  const shelf = el('div', 'ach-shelf');
  const grid = el('ul', 'ach-grid');
  shelf.append(grid);

  const render = () => {
    const { earned, total } = achievementTotals();
    summary.replaceChildren();
    summary.append(
      el('b', 'ach-summary-count', t('ui.achievements.summary', { n: earned, total })),
    );
    const bar = el('span', 'ach-bar big');
    bar.style.setProperty('--fill', String(total ? earned / total : 0));
    summary.append(bar);
    const tiers = el('span', 'ach-tier-counts');
    for (const tier of ['gold', 'silver', 'bronze'] as const) {
      const of = ACHIEVEMENTS.filter((a) => a.tier === tier);
      const got = of.filter((a) => earnedAt(a.key) !== undefined).length;
      const chip = el('span', `ach-tier-chip tier-${tier}`, `${got}/${of.length}`);
      chip.title = t(`ui.achievements.tier.${tier}`);
      tiers.append(chip);
    }
    summary.append(tiers);

    grid.replaceChildren();
    const groups: { id: string; title?: string; items: Achievement[] }[] = [
      { id: 'collection', items: ACHIEVEMENTS.filter((a) => !a.game) },
      ...menuGames.map((g) => ({
        id: g.id,
        title: gameName(g),
        items: ACHIEVEMENTS.filter((a) => a.game?.id === g.id),
      })),
    ];
    for (const g of groups) {
      for (const a of g.items) {
        const li = tile(a, g.title);
        li.dataset.group = g.id;
        grid.append(li);
      }
    }
    pager?.refresh();
  };
  let pager: ReturnType<typeof createPager> | null = null;
  render();

  page.append(header, summary, shelf);
  root.append(page);
  pager = createPager({
    viewport: shelf,
    grid: () => grid,
    items: () => [...grid.children] as HTMLElement[],
  });
  page.append(pager.controls);
  const off = onAchievement(() => render());

  const first = focusSlug
    ? grid.querySelector<HTMLElement>(`[data-group="${CSS.escape(focusSlug)}"]`)
    : null;
  if (first) pager.showItem(first);
  staggerIn(
    [...grid.children].filter((c) => !c.classList.contains('off-page')),
    { stagger: 0.03 },
  );

  return {
    destroy() {
      off();
      pager?.destroy();
      document.documentElement.classList.remove('screen');
      page.remove();
    },
  };
}
