import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { SixteenParams, SixteenState } from './index';

type C = typeof PALETTE;

/** Hand-drawn digit strokes on a 4×6 box, so a badge can carry a tile number without text. */
const DIGITS: Record<string, string> = {
  '1': 'M0.8 1.4 L2.4 0 V6',
  '2': 'M0 1.4 Q0.4 0 2 0 Q4 0 4 1.8 Q4 3.2 0 6 H4',
  '3': 'M0.2 0.6 Q2 -0.4 3.4 0.6 Q4.4 1.8 1.6 2.9 Q4.4 3.2 4 4.8 Q3.4 6.4 0 5.4',
  '4': 'M3 6 V0 L0 4 H4.2',
};

function tile(c: C, x: number, y: number, s: number, n: string, fill: string = c.paper): string {
  const k = (s * 0.5) / 6;
  return (
    `<rect x="${x}" y="${y}" width="${s}" height="${s}" rx="${s * 0.14}" fill="${fill}" stroke="${c.ink}" stroke-width="3.5"/>` +
    (n
      ? `<path transform="translate(${(x + s / 2 - 2 * k).toFixed(1)} ${(y + s * 0.25).toFixed(1)}) scale(${k.toFixed(3)})" d="${DIGITS[n]}" fill="none" stroke="${c.ink}" stroke-width="${(Math.max(2.6, s * 0.12) / k).toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>`
      : '')
  );
}

/** One of the edge arrows the lines are slid with, pointing along (dx, dy). */
function arrow(
  c: C,
  x: number,
  y: number,
  dx: number,
  dy: number,
  r: number,
  fill: string,
): string {
  const px = -dy;
  const py = dx;
  const pt = (a: number, b: number) =>
    `${(x + dx * a + px * b).toFixed(1)} ${(y + dy * a + py * b).toFixed(1)}`;
  return `<path d="M${pt(r, 0)} L${pt(-r * 0.6, r)} L${pt(-r * 0.6, -r)} Z" fill="${fill}" stroke="${c.ink}" stroke-width="3" stroke-linejoin="round"/>`;
}

/** Longest run of the same slide repeated back to back, and whether it went all the way round. */
function wentRound(ctx: { history: readonly SixteenState[] }): boolean {
  let run = 0;
  for (let k = 1; k < ctx.history.length; k++) {
    const s = ctx.history[k];
    const a = s.last;
    const b = ctx.history[k - 1].last;
    if (!a) {
      run = 0;
      continue;
    }
    run = k > 1 && b && a.row === b.row && a.index === b.index && a.dir === b.dir ? run + 1 : 1;
    if (run >= (a.row ? s.w : s.h)) return true;
  }
  return false;
}

export const achievements = defineAchievements<SixteenParams, SixteenState>([
  {
    id: 'lean-slides',
    name: 'Lean Slider',
    description: 'Put the 4×4 in order in 100 slides or fewer.',
    tier: 'silver',
    hue: 'teal',
    // A row in order with an arrow at each end: one slide, and the tiles wrap round.
    art: (c) =>
      arrow(c, 20, 50, -1, 0, 7, c.shade) +
      tile(c, 28, 38, 22, '1', c.shade) +
      tile(c, 50, 38, 22, '2', c.shade) +
      arrow(c, 80, 50, 1, 0, 7, c.teal) +
      `<path d="M72 34 Q72 20 50 20 Q30 20 30 32" fill="none" stroke="${c.ink}" stroke-width="4" stroke-linecap="round"/>` +
      `<path d="M25 27 L30 34 L36 28" fill="none" stroke="${c.ink}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>` +
      tile(c, 28, 62, 22, '3') +
      tile(c, 50, 62, 22, '4'),
    test: (ctx) => ctx.params.w === 4 && ctx.params.h === 4 && ctx.moves <= 100,
  },
  {
    id: 'five-in-200',
    name: 'Grand Sorter',
    description: 'Put the 5×5 in order in 200 slides or fewer.',
    tier: 'gold',
    hue: 'yellow',
    // A board in order, framed by the arrows that slide its lines.
    art: (c) => {
      let out = '';
      for (let j = 0; j < 3; j++)
        for (let i = 0; i < 3; i++) out += tile(c, 29 + i * 14, 29 + j * 14, 14, '', c.shade);
      out += tile(c, 29, 29, 14, '1') + tile(c, 43, 29, 14, '2') + tile(c, 57, 29, 14, '3');
      for (let i = 0; i < 3; i++) {
        const m = 36 + i * 14;
        out += arrow(c, m, 22, 0, -1, 4.5, c.paper) + arrow(c, m, 78, 0, 1, 4.5, c.paper);
        out += arrow(c, 22, m, -1, 0, 4.5, c.paper) + arrow(c, 78, m, 1, 0, 4.5, c.paper);
      }
      return out;
    },
    test: (ctx) => ctx.params.w === 5 && ctx.params.h === 5 && ctx.moves <= 200,
  },
  {
    id: 'round-the-doughnut',
    name: 'Round the Doughnut',
    description: 'Slide one line all the way round until it is back where it began.',
    tier: 'bronze',
    hidden: true,
    hue: 'pink',
    // The grid is a doughnut after all: an iced ring with an arrow chasing round it.
    art: (c) =>
      `<circle cx="50" cy="50" r="21" fill="none" stroke="${c.ink}" stroke-width="25"/>` +
      `<circle cx="50" cy="50" r="21" fill="none" stroke="${c.brown}" stroke-width="19"/>` +
      `<circle cx="50" cy="50" r="21" fill="none" stroke="${c.pink}" stroke-width="12"/>` +
      `<path d="M48 67 l2 2 M34 60 l-2 2 M66 58 l2 1 M30 44 l-1 -3" stroke="${c.yellow}" stroke-width="2.5" stroke-linecap="round"/>` +
      `<path d="M30.3 42.8 A21 21 0 0 1 69.0 41.1" fill="none" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round"/>` +
      `<path d="M71.0 33.6 L69.9 42.9 L62.0 37.8" fill="none" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: wentRound,
  },
]);
