import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  KEY_BACKSPACE,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  RIGHT_BUTTON,
  RIGHT_DRAG,
  RIGHT_RELEASE,
  isCursorMove,
  isCursorSelect,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { INK_TIME, changedAt, drawGrow, parseWxH, popGrow } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { encodeBoard, generateFilling, parseDesc } from './generator';
import type { FillingParams } from './generator';
import { boardRegions, isComplete, maxDigit, solveFilling } from './solver';
import { tutorial } from './tutorial';
import { achievements } from './achievements';
import help from './help.md?raw';
import { FILL_GLYPH } from '../../framework/glyphs';

export type { FillingParams } from './generator';

export interface FillingState {
  w: number;
  h: number;
  /** Given digits (0 where the player fills in). */
  clues: Uint8Array;
  /** Current digits, 0 for empty. */
  board: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface FillingUI {
  /** 1 for each highlighted square, or null when nothing is selected. */
  sel: Uint8Array | null;
  curX: number;
  curY: number;
  curVisible: boolean;
  /**
   * A digit has just gone into the selection, which stays up so the keypad can rub it out
   * or try another digit; the next click, drag or cursor key starts a selection afresh.
   */
  selKept: boolean;
  /** The move being made is that digit, so its change of state keeps the selection. */
  keepOnChange: boolean;
  /**
   * The Fill tool: a left drag that starts on a digit writes that digit into every
   * square it passes over, with no trip to the keypad.
   */
  fill: boolean;
  /** The digit a Fill drag is spreading (0 when none is), and the square it started on. */
  fillFrom: number;
  fillStart: number;
  /**
   * The board changed under a button still held down (undo, redo, restart): the rest of
   * that drag is ignored, so it can neither spread a digit the change took away nor grow a
   * selection nobody started. The next press clears it.
   */
  dragDead: boolean;
}

const FLASH = 0.4;
/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it on the smallest board the Type menu
 * offers, and goes up the ladder when they want to.
 */
const DEFAULTS: FillingParams = { w: 9, h: 7 };
/** Generation is quadratic in the area; this keeps the biggest grids around a second. */
const MAX_DIM = 25;
const MAX_AREA = 400;

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

export function makeState(w: number, h: number, clues: Uint8Array): FillingState {
  return { w, h, clues, board: clues.slice(), completed: false, cheated: false };
}

export interface BoardInfo {
  /** Size of the same-digit region each square belongs to. */
  size: Int32Array;
  /** 1 where the region is bigger than its digit, or too small with no room left to grow. */
  error: Uint8Array;
  /** 1 where the region has exactly as many squares as its digit. */
  complete: Uint8Array;
  /** 1 when a heavy border separates (x, y) from (x + 1, y). */
  borderR: Uint8Array;
  /** 1 when a heavy border separates (x, y) from (x, y + 1). */
  borderD: Uint8Array;
}

/** Region sizes, error flags and border placement for the current board. */
export function analyse(board: Uint8Array, w: number, h: number): BoardInfo {
  const sz = w * h;
  const { root, size } = boardRegions(board, w, h);
  const canGrow = new Uint8Array(sz);
  for (let i = 0; i < sz; i++) {
    if (!board[i]) continue;
    const x = i % w;
    const y = (i - x) / w;
    if (
      (x > 0 && !board[i - 1]) ||
      (x + 1 < w && !board[i + 1]) ||
      (y > 0 && !board[i - w]) ||
      (y + 1 < h && !board[i + w])
    )
      canGrow[root[i]] = 1;
  }
  const error = new Uint8Array(sz);
  const complete = new Uint8Array(sz);
  for (let i = 0; i < sz; i++) {
    const v = board[i];
    if (!v) continue;
    const s = size[i];
    if (s === v) complete[i] = 1;
    else if (s > v || !canGrow[root[i]]) error[i] = 1;
  }
  // A border goes between two squares with different contents when both are filled, or
  // when one of them belongs to a region that is already complete (or overfull).
  const wall = (a: number, b: number): number => {
    const v1 = board[a];
    const v2 = board[b];
    if (v1 === v2) return 0;
    if (v1 && v2) return 1;
    if (v1 && size[a] >= v1) return 1;
    if (v2 && size[b] >= v2) return 1;
    return 0;
  };
  const borderR = new Uint8Array(sz);
  const borderD = new Uint8Array(sz);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (x + 1 < w) borderR[i] = wall(i, i + 1);
      if (y + 1 < h) borderD[i] = wall(i, i + w);
    }
  }
  return { size, error, complete, borderR, borderD };
}

/**
 * Stroke the interior grid edges selected by the predicates, merging runs of collinear
 * edges into single sketched lines so borders read as continuous strokes.
 * `vert(gx, y)` is the edge on grid line gx (1..w-1) beside row y; `horiz(x, gy)` is
 * the edge on grid line gy (1..h-1) above column x.
 */
function strokeEdges(
  dr: Drawing,
  w: number,
  h: number,
  b: number,
  t: number,
  vert: (gx: number, y: number) => boolean,
  horiz: (x: number, gy: number) => boolean,
  colour: string,
  width: number,
  seed: number,
): void {
  for (let gx = 1; gx < w; gx++) {
    let y0 = -1;
    for (let y = 0; y <= h; y++) {
      const on = y < h && vert(gx, y);
      if (on && y0 < 0) y0 = y;
      if (!on && y0 >= 0) {
        dr.line(b + gx * t, b + y0 * t, b + gx * t, b + y * t, colour, width, { seed });
        y0 = -1;
      }
    }
  }
  for (let gy = 1; gy < h; gy++) {
    let x0 = -1;
    for (let x = 0; x <= w; x++) {
      const on = x < w && horiz(x, gy);
      if (on && x0 < 0) x0 = x;
      if (!on && x0 >= 0) {
        dr.line(b + x0 * t, b + gy * t, b + x * t, b + gy * t, colour, width, { seed });
        x0 = -1;
      }
    }
  }
}

const game = defineGame<FillingParams, FillingState, FillingUI>({
  id: 'filling',
  name: 'Filling',
  description: 'Fill the grid so every group of equal digits is exactly that many squares.',
  alsoKnownAs: 'Fillomino',
  help,
  tutorial,
  achievements,
  presets: [
    { name: '9×7', params: { w: 9, h: 7 } },
    { name: '13×9', params: { w: 13, h: 9 } },
    { name: '17×13', params: { w: 17, h: 13 } },
  ],
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p) => `${p.w}x${p.h}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    return { w: r.w, h: r.h };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 1) return tx`Width must be at least one`;
    if (p.h < 1) return tx`Height must be at least one`;
    if (p.w > MAX_DIM || p.h > MAX_DIM) return tx`Width and height must be at most ${MAX_DIM}`;
    if (p.w * p.h > MAX_AREA) return tx`The grid can have at most ${MAX_AREA} squares`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const w = int(0);
    const h = int(1);
    return { w, h };
  },

  newDesc(p, rng: Random) {
    return generateFilling(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(p.w, p.h, desc);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    return makeState(p.w, p.h, parseDesc(p.w, p.h, desc) as Uint8Array);
  },

  canSolve: true,
  solve(orig, _curr, aux) {
    if (aux) return aux;
    const res = solveFilling(orig.clues, orig.w, orig.h);
    if (res.status === 'ambiguous') throw new Error(tx`Multiple solutions exist for this puzzle`);
    if (res.status === 'impossible') throw new Error(tx`No solution exists for this puzzle`);
    if (!res.board) throw new Error(tx`Unable to find a solution to this puzzle`);
    return 's' + encodeBoard(res.board);
  },

  textFormat(s) {
    const { w, h, board } = s;
    const rule = '+' + '---+'.repeat(w);
    const lines: string[] = [rule];
    for (let y = 0; y < h; y++) {
      let line = '|';
      for (let x = 0; x < w; x++) {
        const v = board[y * w + x];
        line += ` ${v ? String(v) : ' '} |`;
      }
      lines.push(line, rule);
    }
    return lines.join('\n');
  },

  newUI: () => ({
    sel: null,
    curX: 0,
    curY: 0,
    curVisible: false,
    selKept: false,
    keepOnChange: false,
    fill: false,
    fillFrom: 0,
    fillStart: -1,
    dragDead: false,
  }),
  changedState(ui, old, next) {
    // Any change of state (undo, redo, solve, restart) drops the highlight, except the
    // digit just typed into it; and a puzzle just finished needs no selection at all.
    const keep = ui.keepOnChange && !(next.completed && !old.completed);
    ui.keepOnChange = false;
    if (!keep) {
      ui.sel = null;
      ui.selKept = false;
      ui.fillFrom = 0;
      ui.dragDead = true;
    }
  },

  actions: [
    {
      label: 'Fill',
      key: 'F',
      hud: true,
      glyph: FILL_GLYPH,
      pressed: (_s, ui) => ui.fill,
      title: 'Drag from a digit to write it into every square you pass (F)',
    },
  ],

  // One key per digit this grid can use, plus a clear key: the selection is made with
  // taps and drags, and the digit comes from here on a device with no keyboard.
  keypad: (p) => ({
    keys: Array.from({ length: maxDigit(p.w, p.h) }, (_, i) => String(i + 1)),
    clear: true,
  }),

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, clues, board } = state;
    const sz = w * h;
    const t = ds.tileSize;
    const border = boardBorder(t);
    const tx = Math.floor((mx - border) / t);
    const ty = Math.floor((my - border) / t);
    const inside = tx >= 0 && tx < w && ty >= 0 && ty < h;
    const clicked = ty * w + tx;
    ui.keepOnChange = false;
    const ch = keyChar(b);
    if (ch === 'f' || ch === 'F') {
      ui.fill = !ui.fill;
      ui.fillFrom = 0;
      return '';
    }
    // A selection kept after a digit only takes further digits: anything else that
    // selects starts over, as it did before the digit went in.
    const selecting =
      b === LEFT_BUTTON || b === RIGHT_BUTTON || isCursorMove(b) || isCursorSelect(b);
    if (ui.selKept && selecting) ui.sel = null;
    if (selecting) ui.selKept = false;

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) ui.dragDead = false;
    else if (ui.dragDead && (b === LEFT_DRAG || b === RIGHT_DRAG)) return null;
    else if (ui.dragDead && (b === LEFT_RELEASE || b === RIGHT_RELEASE)) {
      ui.dragDead = false;
      return null;
    }

    if (b === LEFT_BUTTON || b === LEFT_DRAG) {
      // A fresh click starts a new selection; dragging adds to it.
      if (b === LEFT_BUTTON) {
        ui.sel = null;
        ui.fillFrom = ui.fill && inside ? board[clicked] : 0;
        ui.fillStart = clicked;
      }
      if (inside && !clues[clicked]) {
        if (!ui.sel) ui.sel = new Uint8Array(sz);
        ui.sel[clicked] = 1;
      }
      ui.curVisible = false;
      return '';
    }
    if (b === LEFT_RELEASE) {
      // A Fill drag lets go: its digit goes into every square it crossed. A plain click
      // leaves the square selected, as it does without the tool.
      const v = ui.fillFrom;
      ui.fillFrom = 0;
      const sel = ui.sel;
      if (!v || !sel || !sel.some((on, i) => on && i !== ui.fillStart)) return null;
      ui.sel = null;
      const cells: number[] = [];
      for (let i = 0; i < sz; i++) if (sel[i] && !clues[i] && board[i] !== v) cells.push(i);
      return cells.length ? `${cells.join(',')}_${v}` : '';
    }
    if (b === RIGHT_BUTTON || b === RIGHT_DRAG) {
      // The right button adds to the selection without clearing it; a right-click on a
      // selected square removes it again.
      if (!inside) return null;
      if (!clues[clicked]) {
        if (!ui.sel) ui.sel = new Uint8Array(sz);
        if (b === RIGHT_BUTTON) ui.sel[clicked] ^= 1;
        else ui.sel[clicked] = 1;
        if (!ui.sel.some(Boolean)) ui.sel = null;
      }
      ui.curVisible = false;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.curX, ui.curY, w, h);
      ui.curX = p.x;
      ui.curY = p.y;
      ui.curVisible = true;
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.curVisible) {
        ui.curVisible = true;
        return '';
      }
      const i = ui.curY * w + ui.curX;
      if (!clues[i]) {
        if (!ui.sel) ui.sel = new Uint8Array(sz);
        ui.sel[i] ^= 1;
        if (!ui.sel.some(Boolean)) ui.sel = null;
      }
      return '';
    }

    let value: number;
    if (b === KEY_BACKSPACE) value = 0;
    else if (b >= 48 && b <= 57) value = b - 48;
    else return null;
    if (value > maxDigit(w, h)) return null;

    const cells: number[] = [];
    if (ui.sel) {
      for (let i = 0; i < sz; i++) if (ui.sel[i] && !clues[i] && board[i] !== value) cells.push(i);
    } else if (ui.curVisible) {
      const i = ui.curY * w + ui.curX;
      if (!clues[i] && board[i] !== value) cells.push(i);
    }
    // The selection stays after a digit, so a keypad user can rub it out or try another
    // without choosing the squares again.
    if (ui.sel) ui.selKept = true;
    if (cells.length) {
      ui.keepOnChange = ui.sel !== null;
      return `${cells.join(',')}_${value}`;
    }
    return ui.sel ? '' : null;
  },

  executeMove(state, move) {
    const { w, h, clues } = state;
    const sz = w * h;
    if (move[0] === 's') {
      if (move.length !== sz + 1) return null;
      const board = new Uint8Array(sz);
      for (let i = 0; i < sz; i++) {
        const v = move.charCodeAt(i + 1) - 48;
        if (v < 1 || v > 9) return null;
        if (clues[i] && clues[i] !== v) return null;
        board[i] = v;
      }
      return {
        ...state,
        board,
        completed: state.completed || isComplete(board, w, h),
        cheated: true,
      };
    }
    const m = /^(\d+(?:,\d+)*)_(\d)$/.exec(move);
    if (!m) return null;
    const value = parseInt(m[2], 10);
    if (value > maxDigit(w, h)) return null;
    const board = state.board.slice();
    for (const part of m[1].split(',')) {
      const i = parseInt(part, 10);
      if (i >= sz || clues[i]) return null;
      board[i] = value;
    }
    return { ...state, board, completed: state.completed || isComplete(board, w, h) };
  },

  preferredTileSize: 44,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, h, board, clues } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashTime > 0 && (flashTime <= FLASH / 3 || flashTime >= (2 * FLASH) / 3);
    const info = analyse(board, w, h);
    const sel = ui.sel;

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    if (!flash) {
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const i = y * w + x;
          if (sel && sel[i]) dr.rect(b + x * t, b + y * t, t, t, 'shade');
          else if (board[i] && info.complete[i])
            dr.rect(b + x * t, b + y * t, t, t, 'shade', null, { alpha: 0.5 });
        }
      }
    }

    for (let i = 1; i < w; i++) dr.line(b + i * t, b, b + i * t, b + h * t, 'faint', 1.2);
    for (let i = 1; i < h; i++) dr.line(b, b + i * t, b + w * t, b + i * t, 'faint', 1.2);

    strokeEdges(
      dr,
      w,
      h,
      b,
      t,
      (gx, y) => info.borderR[y * w + gx - 1] === 1,
      (x, gy) => info.borderD[(gy - 1) * w + x] === 1,
      'ink',
      2.6,
      0,
    );

    // A digit the player has just typed is pressed into the square rather than simply
    // being there, and one they have rubbed out shrinks away. This is the most repeated
    // action in the collection, so it is short — and a Solve, which fills the whole grid
    // at once, is left to appear whole.
    const inked = oldState ? changedAt(oldState.board, board, 2) : null;
    /** The digit a square is showing mid-change, and how big it is. */
    const inkAt = (i: number, d: number): { d: number; s: number } =>
      !inked?.includes(i)
        ? { d, s: 1 }
        : d
          ? { d, s: popGrow(animTime) }
          : { d: oldState!.board[i], s: 1 - drawGrow(animTime, INK_TIME) };

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const ink = inkAt(i, board[i]);
        const v = ink.d;
        if (!v || ink.s <= 0) continue;
        const colour = info.error[i] ? 'error' : flash ? 'ok' : clues[i] ? 'ink' : 'blue';
        dr.text(b + x * t + t / 2, b + y * t + t / 2, String(v), { size: t * 0.55, colour });
      }
    }

    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (sel) {
      const at = (x: number, y: number) =>
        x >= 0 && x < w && y >= 0 && y < h && sel[y * w + x] === 1;
      strokeEdges(
        dr,
        w,
        h,
        b,
        t,
        (gx, y) => at(gx - 1, y) !== at(gx, y),
        (x, gy) => at(x, gy - 1) !== at(x, gy),
        'accent',
        2.2,
        5,
      );
      // Selected squares on the rim need their outer edge marked too.
      for (let y = 0; y < h; y++) {
        if (at(0, y)) dr.line(b, b + y * t, b, b + (y + 1) * t, 'accent', 2.2, { seed: 5 });
        if (at(w - 1, y))
          dr.line(b + w * t, b + y * t, b + w * t, b + (y + 1) * t, 'accent', 2.2, { seed: 5 });
      }
      for (let x = 0; x < w; x++) {
        if (at(x, 0)) dr.line(b + x * t, b, b + (x + 1) * t, b, 'accent', 2.2, { seed: 5 });
        if (at(x, h - 1))
          dr.line(b + x * t, b + h * t, b + (x + 1) * t, b + h * t, 'accent', 2.2, { seed: 5 });
      }
    }

    if (ui.curVisible) {
      const inset = t * 0.1;
      dr.cursor(b + ui.curX * t + inset, b + ui.curY * t + inset, t - 2 * inset, t - 2 * inset);
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.board, newState.board, 2) ? INK_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
