import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { RectParams, RectState } from './index';

type C = typeof PALETTE;

/** Hand-lettered digits, as strokes in a box about 10 wide and 14 high round (0, 0). */
const DIGITS: Record<number, string> = {
  2: 'M-4.5 -4 Q-4 -7.5 0 -7.5 Q4.5 -7.5 4.5 -3.5 Q4.5 -0.5 -4.5 7 H5',
  3: 'M-4.5 -6 Q0 -9.5 4 -5.5 Q5 -1.5 0 -0.5 Q5 0 4.8 3.8 Q3.5 8.5 -4.5 6',
  4: 'M2.5 7.5 V-7.5 L-5 3 H5.5',
  6: 'M3.5 -7 Q-4.5 -5 -4.5 2.5 Q-4.5 7.5 0 7.5 Q4.5 7.5 4.5 3 Q4.5 -1 0 -1 Q-3.5 -1 -4.4 1.5',
};

function digit(c: C, n: number, cx: number, cy: number, s: number): string {
  return `<path d="${DIGITS[n]}" transform="translate(${cx} ${cy}) scale(${s})" fill="none" stroke="${c.ink}" stroke-width="${(2.6 / s).toFixed(2)}" stroke-linecap="round" stroke-linejoin="round"/>`;
}

/**
 * A 5×5 board carved into six rectangles, each holding its area: cells of size `s` from
 * (x, y). `last` draws the last rectangle as the drag the player is making.
 */
function carved(c: C, x: number, y: number, s: number, last: boolean, hide = -1): string {
  const R = (cx: number, cy: number, w: number, h: number) => [
    x + cx * s,
    y + cy * s,
    w * s,
    h * s,
  ];
  const rects = [
    { r: R(0, 0, 3, 2), n: 6, at: [1, 0] },
    { r: R(3, 0, 2, 3), n: 6, at: [4, 1] },
    { r: R(0, 2, 1, 3), n: 3, at: [0, 3] },
    { r: R(3, 3, 2, 1), n: 2, at: [4, 3] },
    { r: R(1, 4, 4, 1), n: 4, at: [1, 4] },
    { r: R(1, 2, 2, 2), n: 4, at: [1, 2] },
  ];
  let lines = '';
  for (let i = 1; i < 5; i++)
    lines += `M${x + i * s} ${y} V${y + 5 * s} M${x} ${y + i * s} H${x + 5 * s} `;
  let out = `<rect x="${x}" y="${y}" width="${5 * s}" height="${5 * s}" fill="${c.paper}"/>`;
  // Every rectangle but the one being dragged is finished, and shaded as the game does.
  rects.forEach(({ r }, i) => {
    if (!(last && i === rects.length - 1))
      out += `<rect x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}" fill="${c.shade}"/>`;
  });
  out += `<path d="${lines}" stroke="${c.lowlight}" stroke-width="1.8"/>`;
  rects.forEach(({ r }, i) => {
    if (!(last && i === rects.length - 1))
      out += `<rect x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}" fill="none" stroke="${c.ink}" stroke-width="4" stroke-linejoin="round"/>`;
  });
  if (last) {
    const [lx, ly, lw, lh] = rects[rects.length - 1].r;
    out += `<rect x="${lx}" y="${ly}" width="${lw}" height="${lh}" fill="none" stroke="${c.accent}" stroke-width="4.5" stroke-linejoin="round"/>`;
  }
  out += `<rect x="${x}" y="${y}" width="${5 * s}" height="${5 * s}" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>`;
  // `hide` leaves out a number that something drawn on top would only half cover.
  rects.forEach(({ n, at }, i) => {
    if (i !== hide) out += digit(c, n, x + (at[0] + 0.5) * s, y + (at[1] + 0.5) * s, s / 18);
  });
  return out;
}

/** A mouse pointer with its tip at (x, y). */
function pointer(c: C, x: number, y: number): string {
  return `<path transform="translate(${x} ${y}) scale(0.85)" d="M0 0 l0 19 l5 -4.5 l3.6 7.5 l3.6 -1.7 l-3.6 -7.3 l6.6 0 Z" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.4" stroke-linejoin="round"/>`;
}

/** A stopwatch, face (cx, cy). */
function stopwatch(c: C, cx: number, cy: number, r: number): string {
  return (
    `<path d="M${cx - 4} ${cy - r - 6} H${cx + 4} M${cx} ${cy - r - 6} V${cy - r}" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round"/>` +
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.paper}" stroke="${c.ink}" stroke-width="4.5"/>` +
    `<path d="M${cx} ${cy} V${cy - r * 0.62} M${cx} ${cy} L${cx + r * 0.45} ${cy + r * 0.3}" stroke="${c.accent}" stroke-width="4" stroke-linecap="round"/>` +
    `<circle cx="${cx}" cy="${cy}" r="2.4" fill="${c.ink}"/>`
  );
}

export const achievements = defineAchievements<RectParams, RectState>([
  {
    id: 'clean-cuts',
    name: 'Clean Cuts',
    description: 'Solve an 11×11 Rectangles or larger in no more moves than it has numbers.',
    tier: 'silver',
    hue: 'teal',
    art: (c) => carved(c, 17, 17, 12.4, true) + pointer(c, 54, 66),
    // One drag per rectangle; the last one often closes up by itself, so fewer is fine.
    test: (ctx) =>
      ctx.params.w >= 11 &&
      ctx.params.h >= 11 &&
      ctx.moves <= ctx.state.grid.filter((n) => n > 0).length,
  },
  {
    id: 'quick-carver',
    name: 'Quick Carver',
    description: 'Solve a 19×19 Rectangles in under ten minutes.',
    tier: 'gold',
    hue: 'orange',
    art: (c) => carved(c, 16, 16, 10.4, false, 3) + stopwatch(c, 67, 67, 14),
    test: (ctx) => ctx.params.w >= 19 && ctx.params.h >= 19 && ctx.secs < 600,
  },
]);
