import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { groupAt } from './index';
import type { SameGameState, SameGameUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Every distinct group left on the board, each listed once. */
function groups(state: SameGameState): number[][] {
  const out: number[][] = [];
  for (let i = 0; i < state.tiles.length; i++) {
    if (!state.tiles[i]) continue;
    const g = groupAt(state.tiles, state.w, state.h, i);
    if (g[0] === i) out.push(g);
  }
  return out;
}

function biggestGroup(state: SameGameState): number[] {
  return groups(state).reduce((best, g) => (g.length > best.length ? g : best), [] as number[]);
}

/** The first group of exactly `n` squares, in reading order. */
function groupOfSize(state: SameGameState, n: number): number[] {
  return groups(state).find((g) => g.length === n) ?? [];
}

/** Whatever is selected right now, or `fallback` when nothing is. */
function selection(ui: SameGameUI, fallback: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < ui.sel.length; i++) if (ui.sel[i]) out.push(i);
  return out.length ? out : fallback;
}

function rects(state: SameGameState, tileSize: number, cells: number[]): TutorialRect[] | null {
  if (!cells.length) return null;
  const b = border(tileSize);
  return cells.map((i) => cellRect(i % state.w, Math.floor(i / state.w), tileSize, b));
}

function centre(state: SameGameState, tileSize: number, cells: number[]) {
  if (!cells.length) return null;
  const i = cells[0];
  return cellCentre(i % state.w, Math.floor(i / state.w), tileSize, border(tileSize));
}

/**
 * A fixed 4x4 board whose top row is a block of four red squares, with a lone green
 * square in the far corner to show what cannot be removed.
 */
export const tutorial: Tutorial<SameGameState, SameGameUI> = {
  steps: [
    {
      gameId: '4x4c3s2:1,1,1,1,3,3,3,2,1,2,1,2,1,2,1,3',
      text: 'Clear the board by taking away groups of two or more touching squares that share a colour. A group of _n_ squares scores (_n_ − 2)², so the big ones are what count.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'Click any of the four **red** squares along the top. The first click only selects the group: it lightens and gets a heavy outline.',
      highlight: ({ state, tileSize }) => rects(state, tileSize, biggestGroup(state)),
      pointer: ({ state, tileSize }) => centre(state, tileSize, biggestGroup(state)),
      waitFor: ({ ui }) => ui.nsel >= 3,
      placement: 'below',
    },
    {
      text: 'Click the selected group again to lift it off the board and score four points. Squares above a gap drop into it, and an empty column pulls its neighbours across.',
      highlight: ({ state, ui, tileSize }) =>
        rects(state, tileSize, selection(ui, biggestGroup(state))),
      pointer: ({ state, ui, tileSize }) =>
        centre(state, tileSize, selection(ui, biggestGroup(state))),
      waitFor: ({ state }) => state.score > 0,
      placement: 'below',
    },
    {
      text: 'This **green** square sits on its own. Nothing next to it shares its colour, so it can never be selected — it has to wait until the board shuffles a partner alongside it.',
      highlight: ({ state, tileSize }) => rects(state, tileSize, groupOfSize(state, 1)),
    },
    {
      text: 'Now the **blue pair** highlighted here. Click either of the two squares to select both of them.',
      highlight: ({ state, tileSize }) => rects(state, tileSize, groupOfSize(state, 2)),
      pointer: ({ state, tileSize }) => centre(state, tileSize, groupOfSize(state, 2)),
      waitFor: ({ ui }) => ui.nsel === 2,
    },
    {
      text: 'Changed your mind? **Right-click** the selection to let it go again — nothing is removed until you click it a second time.',
      highlight: ({ state, ui, tileSize }) =>
        rects(state, tileSize, selection(ui, groupOfSize(state, 2))),
      pointer: ({ state, ui, tileSize }) => {
        const c = centre(state, tileSize, selection(ui, groupOfSize(state, 2)));
        return c && { ...c, button: 'right' as const };
      },
      waitFor: ({ ui }) => ui.nsel === 0,
    },
    {
      text: 'That is the whole game. Every board can be cleared, so keep going — **Undo** rewinds when you strand a square, and there is no Solve button to save you.',
      target: '[data-cmd="undo"]',
    },
  ],
};
