import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { DIFF_TRICKY } from './solver';
import type { UndeadParams, UndeadState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A ghost `2r` wide whose head is centred on (cx, cy). */
function ghost(c: C, cx: number, cy: number, r: number): string {
  const step = (2 * r) / 6;
  let hem = '';
  for (let i = 0; i < 6; i++) hem += ` l${-step.toFixed(2)} ${i % 2 ? r * 0.3 : -r * 0.3}`;
  const bottom = cy + r * 1.5;
  return (
    shape(
      `M${cx - r} ${bottom} V${cy} A${r} ${r} 0 0 1 ${cx + r} ${cy} V${bottom + r * 0.3}${hem} Z`,
      c.paper,
      c.ink,
    ) +
    `<ellipse cx="${cx - r * 0.38}" cy="${cy}" rx="${r * 0.14}" ry="${r * 0.22}" fill="${c.ink}"/>` +
    `<ellipse cx="${cx + r * 0.38}" cy="${cy}" rx="${r * 0.14}" ry="${r * 0.22}" fill="${c.ink}"/>`
  );
}

/**
 * Whether no square was changed again after the player had moved on from it. Clicking
 * one square round to the monster wanted is one go.
 */
function neverRevisited<S>(history: readonly S[], cells: (s: S) => ArrayLike<number>): boolean {
  const settled = new Set<number>();
  let current = -1;
  for (let k = 1; k < history.length; k++) {
    const a = cells(history[k - 1]);
    const b = cells(history[k]);
    const changed: number[] = [];
    for (let i = 0; i < b.length; i++) if (a[i] !== b[i]) changed.push(i);
    const only = changed.length === 1 ? changed[0] : -1;
    if (current >= 0 && current !== only && a[current]) settled.add(current);
    for (const i of changed) if (settled.has(i)) return false;
    if (only < 0) for (const i of changed) if (b[i]) settled.add(i);
    current = only;
  }
  return true;
}

export const achievements = defineAchievements<UndeadParams, UndeadState>([
  {
    id: 'no-pencil',
    name: 'Trust Your Eyes',
    description: 'Solve a 5×5 or larger Undead without making a single pencil mark.',
    tier: 'silver',
    hue: 'purple',
    art: (c) =>
      // A ghost, and the mirror it is only ever seen in.
      shape('M58 84 L84 58 L84 70 L70 84 Z', c.faint, c.ink, 3.5) +
      line('M60 80 L80 60', c.highlight, 3) +
      ghost(c, 42, 38, 18),
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 25 && ctx.history.every((s) => !s.pencil.some((m) => m !== 0)),
  },
  {
    id: 'fearless',
    name: 'Fearless',
    description: 'Solve a Tricky Undead without going back to change a monster.',
    tier: 'gold',
    hue: 'red',
    art: (c) =>
      // A vampire: high collar, widow's peak and fangs.
      shape('M22 84 L30 58 L46 76 Z', c.red, c.ink, 4) +
      shape('M78 84 L70 58 L54 76 Z', c.red, c.ink, 4) +
      `<ellipse cx="50" cy="50" rx="18" ry="22" fill="${c.paper}" stroke="${c.ink}" stroke-width="4.5"/>` +
      shape('M32 46 Q30 26 50 26 Q70 26 68 46 L60 36 L50 46 L40 36 Z', c.ink, c.ink, 3) +
      `<circle cx="43" cy="53" r="3" fill="${c.red}"/><circle cx="57" cy="53" r="3" fill="${c.red}"/>` +
      line('M42 63 Q50 67 58 63', c.ink, 3.5) +
      shape('M44 64 L46 71 L48 65 Z', c.highlight, c.ink, 2) +
      shape('M56 64 L54 71 L52 65 Z', c.highlight, c.ink, 2),
    test: (ctx) => ctx.params.diff >= DIFF_TRICKY && neverRevisited(ctx.history, (s) => s.types),
  },
]);
