import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { PearlParams, PearlState } from './index';

type C = typeof PALETTE;

/** Square centres of a 4×4 patch of the board. */
const G = [23, 41, 59, 77];

/**
 * The loop both badges draw: it turns on a black pearl in the top-left square and runs
 * straight through two white ones, each beside a turn, as the rules want.
 */
const LOOP = `M${G[0]} ${G[0]} H${G[3]} V${G[2]} H${G[2]} V${G[3]} H${G[0]} Z`;

function pearls(c: C): string {
  return (
    `<circle cx="${G[0]}" cy="${G[0]}" r="7.5" fill="${c.ink}"/>` +
    `<circle cx="${G[0] - 2.3}" cy="${G[0] - 2.3}" r="2" fill="${c.pencil}"/>` +
    `<circle cx="${G[2]}" cy="${G[0]}" r="7" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.5"/>` +
    `<circle cx="${G[1]}" cy="${G[3]}" r="7" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.5"/>`
  );
}

function gridLines(c: C): string {
  let d = '';
  for (const v of [32, 50, 68]) d += `M${v} 16 V84 M16 ${v} H84 `;
  return `<path d="${d}" stroke="${c.lowlight}" stroke-width="2"/>`;
}

/** How many moves in the kept line drew or rubbed out any loop segment. */
function lineMoves(history: readonly PearlState[]): number {
  let n = 0;
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].lines;
    const b = history[k].lines;
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) {
        n++;
        break;
      }
    }
  }
  return n;
}

export const achievements = defineAchievements<PearlParams, PearlState>([
  {
    id: 'no-crosses',
    name: 'String of Pearls',
    description: 'Solve a 10×10 Pearl without placing a single cross.',
    tier: 'silver',
    hue: 'teal',
    art: (c) =>
      gridLines(c) +
      `<path d="${LOOP}" fill="none" stroke="${c.ink}" stroke-width="6" stroke-linejoin="round"/>` +
      pearls(c) +
      // The cross nobody placed, in the one corner the loop leaves free.
      `<circle cx="73" cy="73" r="9.5" fill="${c.paper}" stroke="${c.red}" stroke-width="4"/>` +
      `<path d="M69 69 L77 77 M77 69 L69 77" stroke="${c.pencil}" stroke-width="3" stroke-linecap="round"/>` +
      `<path d="M66 80 L80 66" stroke="${c.red}" stroke-width="4" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 10 && ctx.params.h >= 10 && ctx.history.every((s) => !s.marks.some((m) => m)),
  },
  {
    id: 'one-stroke',
    name: 'One Stroke',
    description: 'Draw the whole loop of an 8×8 Pearl or larger in a single drag.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) =>
      gridLines(c) +
      // The drag, in the game's drag colour, coming home to the square it started from.
      `<circle cx="${G[0]}" cy="${G[1] + 2}" r="5" fill="${c.accent}"/>` +
      `<path d="M${G[0]} ${G[1] + 2} V${G[0]} H${G[3]} V${G[2]} H${G[2]} V${G[3]} H${G[0]} V${G[2] - 5}" fill="none" stroke="${c.accent}" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>` +
      `<path d="M${G[0] - 7} ${G[2] + 1} L${G[0]} ${G[2] - 8} L${G[0] + 7} ${G[2] + 1}" fill="none" stroke="${c.accent}" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>` +
      pearls(c),
    // The loop goes down in one move; crosses placed along the way do not matter.
    test: (ctx) => ctx.params.w >= 8 && ctx.params.h >= 8 && lineMoves(ctx.history) === 1,
  },
]);
