/**
 * Towers generator.
 *
 * 1. Draw a random latin square and read all 4w clues off it.
 * 2. Visit the squares in random order and blank each one whose removal leaves the
 *    puzzle solvable at the requested difficulty. Small Easy puzzles insist on an
 *    entirely empty grid first, since those are the nicest to play.
 * 3. Above Easy, do the same with the clues themselves.
 * 4. Grade the result; if it came out easier than asked for, start again.
 */
import type { Random } from '../../framework/rng';
import { encodeDesc } from './desc';
import { latinGenerate } from './latin';
import { DIFF_EASY, DIFF_HARD, computeClues, solveTowers } from './solver';

/** Generate a puzzle description and its solution (as a Solve move) from the RNG. */
export function generateTowers(
  w: number,
  diff: number,
  rng: Random,
): { desc: string; aux: string } {
  const a = w * w;
  // Every 3×3 puzzle that Hard cannot do is ambiguous, so nothing harder exists.
  if (diff > DIFF_HARD && w <= 3) diff = DIFF_HARD;
  const work = new Uint8Array(a);

  for (;;) {
    const grid = latinGenerate(w, rng);
    const clues = computeClues(w, grid);
    const soln = grid.slice();

    if (diff === DIFF_EASY && w <= 5) {
      work.fill(0);
      if (solveTowers(w, clues, work, diff) > diff) continue;
    }

    const order = rng.shuffle(Array.from({ length: a }, (_, i) => i));
    for (const j of order) {
      work.set(grid);
      work[j] = 0;
      if (solveTowers(w, clues, work, diff) <= diff) grid[j] = 0;
    }

    if (diff > DIFF_EASY) {
      const corder = rng.shuffle(Array.from({ length: 4 * w }, (_, i) => i));
      for (const j of corder) {
        const clue = clues[j];
        clues[j] = 0;
        work.set(grid);
        if (solveTowers(w, clues, work, diff) > diff) clues[j] = clue;
      }
    }

    work.set(grid);
    if (solveTowers(w, clues, work, diff) !== diff) continue;
    return { desc: encodeDesc(w, clues, grid), aux: 'S' + Array.from(soln).join('') };
  }
}
