import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { SignpostState, SignpostUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

interface Cell {
  x: number;
  y: number;
}

/** Squares of the fixed 3×2 board the walkthrough talks about. */
const ONE: Cell = { x: 0, y: 0 };
const TWO: Cell = { x: 1, y: 0 };
const THREE: Cell = { x: 2, y: 0 };
const MID: Cell = { x: 1, y: 1 };
const CORNER: Cell = { x: 2, y: 1 };

const at = (state: SignpostState, c: Cell): number => c.y * state.w + c.x;
const rect = (c: Cell, t: number): TutorialRect => cellRect(c.x, c.y, t, border(t));
const drag = (from: Cell, to: Cell, t: number) => ({
  ...cellCentre(from.x, from.y, t, border(t)),
  to: cellCentre(to.x, to.y, t, border(t)),
});

export const tutorial: Tutorial<SignpostState, SignpostUI> = {
  steps: [
    {
      gameId: '3x2:1cc3e6agg',
      text: 'Every square carries an arrow. Join all six into one chain numbered **1 to 6**, where each square is followed by a square somewhere along its own arrow.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The **1** points east. **Drag** from it onto the square on its right to make that one the 2.',
      highlight: ({ tileSize }) => [rect(ONE, tileSize), rect(TWO, tileSize)],
      pointer: ({ tileSize }) => drag(ONE, TWO, tileSize),
      waitFor: ({ state }) => state.next[at(state, ONE)] === at(state, TWO),
    },
    {
      text: 'The **3** hooked itself on, as numbers that follow each other and point the right way always do. Now **drag** the bottom-right square onto the square to its left.',
      highlight: ({ tileSize }) => [rect(CORNER, tileSize), rect(MID, tileSize)],
      pointer: ({ tileSize }) => drag(CORNER, MID, tileSize),
      waitFor: ({ state }) => state.next[at(state, CORNER)] === at(state, MID),
    },
    {
      text: 'Neither of those two has a number yet, so the pair is labelled **a** and **a+1**. **Right-click** the middle square of the bottom row to pull them apart again.',
      highlight: ({ tileSize }) => [rect(CORNER, tileSize), rect(MID, tileSize)],
      pointer: ({ tileSize }) => ({
        ...cellCentre(MID.x, MID.y, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => state.next[at(state, CORNER)] === -1,
    },
    {
      text: 'Real numbers are better: **drag** the **3** onto the square below it, which becomes the 4.',
      highlight: ({ tileSize }) => [rect(THREE, tileSize), rect(CORNER, tileSize)],
      pointer: ({ tileSize }) => drag(THREE, CORNER, tileSize),
      waitFor: ({ state }) => state.next[at(state, THREE)] === at(state, CORNER),
    },
    {
      text: 'Last link: **drag** that 4 onto the square to its left. It becomes the 5, and the 6 closes the path by itself.',
      highlight: ({ tileSize }) => [rect(CORNER, tileSize), rect(MID, tileSize)],
      pointer: ({ tileSize }) => drag(CORNER, MID, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved. A **right-click and drag** links the other way, from a square back to the one before it, and **Solve** lays out the whole path.',
      target: '[data-cmd="solve"]',
    },
  ],
};
