/**
 * Settings: the one screen a game keeps its preferences on, instead of a picker in the
 * masthead's corner, a speaker in the stats strip and a switch in the footer.
 *
 * Opened by the gear in the menu's resource bar and by Settings in the pause menu, as a
 * card in the pause menu's own sketch (`settings.css`). It holds:
 *
 * - **Language** — the same picker and the same switching code as before
 *   (`languageSwitcher`). A switch re-renders the page under the dialog, which takes the
 *   dialog down with it; it comes straight back up in the new language.
 * - **Sound** — on/off and a master volume (`sound.ts`). The portal's own mute outranks
 *   both, exactly as it outranks the speaker button: while it is on, the two show the
 *   sound as off, cannot be changed, and say why.
 * - **Reduce motion** — defaults to the system's `prefers-reduced-motion`; once set here it
 *   is the player's choice (`motion.ts`).
 * - **Play statistics** — the analytics opt-out, when analytics is configured at all, with
 *   the one line under it that says what is counted: the notice CrazyGames asks for, which
 *   lives only here, not on the home page.
 *
 * Esc, the phone's Back, the dimmer and Done all close it, and the keyboard goes back to
 * whatever opened it (`openModal`).
 */

import { analyticsConfigured, analyticsOptedOut, setAnalyticsOptOut } from '../analytics';
import { t } from '../i18n';
import { openModal, type ModalHandle } from './dialogs';
import { languageSwitcher } from './language';
import { motionChoice, onMotionChange, reducedMotion, setReducedMotion } from './motion';
import { buzzFor, canVibrate, hapticsOn, onHapticsChange, setHaptics } from './haptics';
import {
  getVolume,
  isMuted,
  isPortalMuted,
  onMuteChange,
  onVolumeChange,
  setMuted,
  setVolume,
} from './sound';

/** A cog, drawn in `currentColor` like the HUD's glyphs. */
export const GEAR_SVG =
  '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">' +
  '<path d="M12 2.6l1.5 2.3 2.7-.6.6 2.7 2.4 1.4-1.2 2.5 1.2 2.5-2.4 1.4-.6 2.7-2.7-.6L12 19.8l-1.5-2.3-2.7.6-.6-2.7-2.4-1.4 1.2-2.5-1.2-2.5 2.4-1.4.6-2.7 2.7.6z" ' +
  'fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" transform="translate(0 .8)"/>' +
  '<circle cx="12" cy="12" r="3.1" fill="none" stroke="currentColor" stroke-width="2"/>' +
  '</svg>';

let current: ModalHandle | null = null;
let seq = 0;

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

/** One row: a caption on the reading side, its control on the other. */
function row(label: string, cls: string): { row: HTMLElement; id: string; tail: HTMLElement } {
  const r = el('div', `settings-row ${cls}`);
  const id = `settings-${cls}-${++seq}`;
  const caption = el('span', 'settings-label', label);
  caption.id = id;
  const tail = el('div', 'settings-control');
  r.append(caption, tail);
  return { row: r, id, tail };
}

/**
 * A drawn on/off switch: a pill with a knob and the state written in it. A real button
 * with `role="switch"`, so Space and Enter flip it and a screen reader reads "on"/"off".
 */
function sketchSwitch(labelledBy: string, onFlip: (on: boolean) => void) {
  const b = el('button', 'sketch-switch');
  b.type = 'button';
  b.setAttribute('role', 'switch');
  b.setAttribute('aria-labelledby', labelledBy);
  const track = el('span', 'switch-track');
  track.setAttribute('aria-hidden', 'true');
  const knob = el('span', 'switch-knob');
  const word = el('span', 'switch-word');
  track.append(word, knob);
  b.append(track);
  const set = (on: boolean) => {
    b.setAttribute('aria-checked', String(on));
    b.classList.toggle('on', on);
    word.textContent = t(on ? 'ui.settings.on' : 'ui.settings.off');
  };
  b.addEventListener('click', () => {
    if (b.disabled) return;
    onFlip(b.getAttribute('aria-checked') !== 'true');
  });
  return { el: b, set };
}

export interface SettingsOptions {
  /** Which control has the keyboard when the card comes up. */
  focus?: 'language' | 'sound' | 'volume' | 'motion';
}

/** Whether the Settings card is up. */
export function settingsOpen(): boolean {
  return !!current;
}

/** Open the Settings card, or leave the one that is up as it is. */
export function openSettings(opts: SettingsOptions = {}): void {
  if (current) return;
  const offs: (() => void)[] = [];
  const cleanup = () => {
    if (current === modal) current = null;
    for (const off of offs.splice(0)) off();
  };
  const modal = openModal(t('ui.settings.title'), cleanup);
  current = modal;
  modal.root.classList.add('settings-sheet');
  const body = modal.body;

  // ---- language
  const lang = row(t('ui.menu.language'), 'language');
  // Back up after the page it was on has been re-rendered in the new language. The re-render
  // took the pause menu with it, so one opened from there goes back on top of a fresh pause
  // menu: the clock stays stopped, and Esc still steps back to the menu, not to the board.
  const fromPause = !!document.querySelector('.more-sheet');
  const picker = languageSwitcher(() => {
    if (fromPause) document.querySelector<HTMLElement>('#app .toolbar .btn.more')?.click();
    openSettings({ focus: 'language' });
  });
  lang.tail.append(picker);
  const select = picker.querySelector('select')!;

  // ---- sound
  const sound = row(t('ui.settings.sound'), 'sound');
  const soundSwitch = sketchSwitch(sound.id, (on) => setMuted(!on));
  const volume = el('input', 'sketch-range');
  volume.type = 'range';
  volume.min = '0';
  volume.max = '100';
  volume.step = '5';
  volume.setAttribute('aria-label', t('ui.settings.volume'));
  volume.addEventListener('input', () => setVolume(Number(volume.value) / 100));
  const volumeWrap = el('div', 'settings-volume');
  volumeWrap.append(volume);
  sound.tail.append(soundSwitch.el, volumeWrap);
  const portalNote = el('p', 'settings-note', t('ui.settings.portalMuted'));
  const paintSound = () => {
    const portal = isPortalMuted();
    const on = !isMuted() && !portal;
    soundSwitch.set(on);
    soundSwitch.el.disabled = portal;
    volume.disabled = !on;
    volume.value = String(Math.round(getVolume() * 100));
    volume.style.setProperty('--fill', String(getVolume()));
    volume.setAttribute('aria-valuetext', `${Math.round(getVolume() * 100)}%`);
    portalNote.hidden = !portal;
  };
  paintSound();
  offs.push(onMuteChange(paintSound), onVolumeChange(paintSound));

  // ---- motion
  const motion = row(t('ui.settings.reduceMotion'), 'motion');
  const motionSwitch = sketchSwitch(motion.id, (on) => setReducedMotion(on));
  motion.tail.append(motionSwitch.el);
  const paintMotion = () => {
    motionSwitch.set(reducedMotion());
    motionSwitch.el.dataset.source = motionChoice() ? 'player' : 'system';
  };
  paintMotion();
  offs.push(onMotionChange(paintMotion));

  body.append(lang.row, sound.row, portalNote, motion.row);

  // ---- vibration, only where the device can buzz (`haptics.ts`)
  if (canVibrate()) {
    const buzz = row(t('ui.settings.vibration'), 'vibration');
    const buzzSwitch = sketchSwitch(buzz.id, (on) => {
      setHaptics(on);
      if (on) buzzFor('move');
    });
    buzz.tail.append(buzzSwitch.el);
    buzzSwitch.set(hapticsOn());
    offs.push(onHapticsChange((on) => buzzSwitch.set(on)));
    body.append(buzz.row);
  }

  // ---- play statistics
  if (analyticsConfigured()) {
    const stats = row(t('ui.settings.statistics'), 'statistics');
    const statsSwitch = sketchSwitch(stats.id, (on) => {
      setAnalyticsOptOut(!on);
      statsSwitch.set(!analyticsOptedOut());
    });
    statsSwitch.set(!analyticsOptedOut());
    stats.tail.append(statsSwitch.el);
    body.append(stats.row, el('p', 'settings-note', t('ui.menu.privacy.note')));
  }

  const done = el('button', 'btn settings-done', t('ui.settings.done'));
  done.type = 'button';
  done.addEventListener('click', () => {
    // `close` skips the cancel callback, which is where the listeners are let go.
    cleanup();
    modal.close();
  });
  body.append(done);

  const target =
    opts.focus === 'sound'
      ? soundSwitch.el
      : opts.focus === 'volume'
        ? volume
        : opts.focus === 'motion'
          ? motionSwitch.el
          : opts.focus === 'language'
            ? select
            : null;
  (target ?? done).focus({ preventScroll: true });
}

/**
 * The round gear button that opens Settings, for the menu's resource bar. Its name is the
 * word, its tooltip the same word drawn (`gameFeel.ts`).
 */
export function settingsButton(extraClass = ''): HTMLButtonElement {
  const b = el('button', `btn round-btn settings-open ${extraClass}`.trim());
  b.type = 'button';
  b.innerHTML = GEAR_SVG;
  b.setAttribute('aria-label', t('ui.settings.title'));
  b.setAttribute('aria-haspopup', 'dialog');
  b.title = t('ui.settings.title');
  b.addEventListener('click', () => openSettings());
  return b;
}
