/**
 * Bridges board model shared by the game, the solver and the generator.
 *
 * A puzzle is a graph: the islands are its vertices and every pair of islands that see
 * each other along a row or column (with nothing but empty squares between them) is an
 * edge — a place where bridges could run. Each edge remembers the squares it passes
 * through and which perpendicular edges it would cross; two crossing edges can never
 * both carry bridges. Everything the player changes — bridge counts, "no bridge" markers
 * and "finished" marks — lives in plain typed arrays indexed by edge or island.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

/** Direction indices used for an island's four possible edges. */
export const DIR_LEFT = 0;
export const DIR_RIGHT = 1;
export const DIR_UP = 2;
export const DIR_DOWN = 3;
export const DX = [-1, 1, 0, 0];
export const DY = [0, 0, -1, 1];

/** The most parallel bridges the rules can ever allow between two islands. */
export const MAX_BRIDGES = 4;

export interface IslandSpec {
  x: number;
  y: number;
  clue: number;
}

export interface Island extends IslandSpec {
  /** Edge index in each of the four directions (left, right, up, down), or -1. */
  edges: number[];
}

export interface Edge {
  /** The two islands; `a` is the one further left or further up. */
  a: number;
  b: number;
  horizontal: boolean;
  /** Squares the bridge would pass through (never islands). */
  cells: number[];
  /** Perpendicular edges sharing a square with this one. */
  cross: number[];
}

export class Layout {
  readonly n: number;
  readonly islands: Island[];
  readonly edges: Edge[] = [];
  /** Island index at each square, or -1. */
  readonly islandAt: Int32Array;
  /** Horizontal / vertical edge passing through each square, or -1. */
  readonly hEdgeAt: Int32Array;
  readonly vEdgeAt: Int32Array;

  constructor(
    readonly w: number,
    readonly h: number,
    islands: IslandSpec[],
    readonly maxb: number,
    readonly allowLoops: boolean,
  ) {
    this.n = w * h;
    this.islands = islands.map((s) => ({ ...s, edges: [-1, -1, -1, -1] }));
    this.islandAt = new Int32Array(this.n).fill(-1);
    this.hEdgeAt = new Int32Array(this.n).fill(-1);
    this.vEdgeAt = new Int32Array(this.n).fill(-1);
    this.islands.forEach((is, i) => (this.islandAt[is.y * w + is.x] = i));
    // Look right and down from every island for the next island in line.
    for (let i = 0; i < this.islands.length; i++) {
      const is = this.islands[i];
      for (const dir of [DIR_RIGHT, DIR_DOWN]) {
        const cells: number[] = [];
        let x = is.x + DX[dir];
        let y = is.y + DY[dir];
        while (x < w && y < h) {
          const j = this.islandAt[y * w + x];
          if (j >= 0) {
            // Islands right next to each other cannot have a bridge between them.
            if (cells.length > 0) this.addEdge(i, j, dir, cells);
            break;
          }
          cells.push(y * w + x);
          x += DX[dir];
          y += DY[dir];
        }
      }
    }
    for (let e = 0; e < this.edges.length; e++) {
      const edge = this.edges[e];
      for (const c of edge.cells) {
        const other = edge.horizontal ? this.vEdgeAt[c] : this.hEdgeAt[c];
        if (other >= 0) edge.cross.push(other);
      }
    }
  }

  private addEdge(a: number, b: number, dir: number, cells: number[]): void {
    const e = this.edges.length;
    const horizontal = dir === DIR_RIGHT;
    this.edges.push({ a, b, horizontal, cells, cross: [] });
    this.islands[a].edges[dir] = e;
    this.islands[b].edges[dir === DIR_RIGHT ? DIR_LEFT : DIR_UP] = e;
    const at = horizontal ? this.hEdgeAt : this.vEdgeAt;
    for (const c of cells) at[c] = e;
  }

  /** The edge joining islands `i` and `j`, or -1. */
  edgeBetween(i: number, j: number): number {
    for (const e of this.islands[i].edges) {
      if (e < 0) continue;
      const edge = this.edges[e];
      if (edge.a === j || edge.b === j) return e;
    }
    return -1;
  }

  /** The island at the far end of edge `e` from island `i`. */
  other(e: number, i: number): number {
    const edge = this.edges[e];
    return edge.a === i ? edge.b : edge.a;
  }
}

// ------------------------------------------------------------------ bookkeeping

/** Bridges attached to every island. */
export function islandCounts(L: Layout, bridges: ArrayLike<number>): Int32Array {
  const counts = new Int32Array(L.islands.length);
  L.edges.forEach((edge, e) => {
    counts[edge.a] += bridges[e];
    counts[edge.b] += bridges[e];
  });
  return counts;
}

/** Union–find over the islands, joined wherever there is at least one bridge. */
export function components(L: Layout, bridges: ArrayLike<number>): DSF {
  const dsf = new DSF(L.islands.length);
  L.edges.forEach((edge, e) => {
    if (bridges[e] > 0) dsf.merge(edge.a, edge.b);
  });
  return dsf;
}

/** Whether a bridge along `e` is blocked by a bridge crossing it. */
export function crossed(L: Layout, bridges: ArrayLike<number>, e: number): boolean {
  for (const c of L.edges[e].cross) if (bridges[c] > 0) return true;
  return false;
}

/**
 * Edges (with bridges) that lie on a cycle, found with the usual depth-first lowlink
 * search: an edge whose removal would not disconnect its ends is part of a loop.
 * Parallel bridges between the same pair count as one connection.
 */
export function loopEdges(L: Layout, bridges: ArrayLike<number>): Uint8Array {
  const n = L.islands.length;
  const onLoop = new Uint8Array(L.edges.length);
  const disc = new Int32Array(n).fill(-1);
  const low = new Int32Array(n);
  let time = 0;
  const visit = (v: number, viaEdge: number): void => {
    disc[v] = low[v] = time++;
    for (const e of L.islands[v].edges) {
      if (e < 0 || bridges[e] === 0 || e === viaEdge) continue;
      const u = L.other(e, v);
      if (disc[u] < 0) {
        visit(u, e);
        low[v] = Math.min(low[v], low[u]);
        if (low[u] > disc[v]) continue; // a tree edge that is a graph bridge
        onLoop[e] = 1;
      } else {
        low[v] = Math.min(low[v], disc[u]);
        onLoop[e] = 1;
      }
    }
  };
  for (let v = 0; v < n; v++) if (disc[v] < 0) visit(v, -1);
  return onLoop;
}

export interface Analysis {
  counts: Int32Array;
  /** Islands to show in the error colour. */
  errIsland: Uint8Array;
  /** Edges whose bridges to show in the error colour. */
  errEdge: Uint8Array;
  completed: boolean;
}

/**
 * The most extra bridges island `i` could still send along `e` as things stand: none if
 * the edge is marked or crossed, otherwise limited by the per-pair maximum and by what
 * the island at the other end still needs.
 */
export function spareCapacity(
  L: Layout,
  bridges: ArrayLike<number>,
  noline: ArrayLike<number>,
  counts: ArrayLike<number>,
  i: number,
  e: number,
): number {
  if (noline[e] || crossed(L, bridges, e)) return 0;
  const j = L.other(e, i);
  const remaining = L.islands[j].clue - counts[j];
  return Math.max(0, Math.min(L.maxb - bridges[e], remaining));
}

/**
 * Everything the display needs to know about a position: which islands and bridges are
 * definitely wrong, and whether the puzzle is finished. An island is wrong when it has
 * too many bridges, when it is marked finished but short, or when there is no longer
 * room to give it enough. A group of islands that are all full but do not include every
 * island can never be joined to the rest, so it is wrong too; and with loops disallowed
 * every bridge on a loop is wrong.
 */
export function analyse(
  L: Layout,
  bridges: ArrayLike<number>,
  noline: ArrayLike<number>,
  marked: ArrayLike<number>,
): Analysis {
  const n = L.islands.length;
  const counts = islandCounts(L, bridges);
  const errIsland = new Uint8Array(n);
  const errEdge = new Uint8Array(L.edges.length);
  let allFull = true;
  for (let i = 0; i < n; i++) {
    const clue = L.islands[i].clue;
    const missing = clue - counts[i];
    if (missing !== 0) allFull = false;
    if (missing < 0 || (marked[i] && missing > 0)) {
      errIsland[i] = 1;
      continue;
    }
    if (missing === 0) continue;
    let room = 0;
    for (const e of L.islands[i].edges) {
      if (e >= 0) room += spareCapacity(L, bridges, noline, counts, i, e);
    }
    if (room < missing) errIsland[i] = 1;
  }

  const dsf = components(L, bridges);
  const groups = dsf.count();
  if (groups > 1) {
    // A full group that is not the whole puzzle is stranded.
    const fullGroup = new Map<number, boolean>();
    for (let i = 0; i < n; i++) {
      const r = dsf.find(i);
      const full = counts[i] === L.islands[i].clue;
      fullGroup.set(r, (fullGroup.get(r) ?? true) && full);
    }
    for (let i = 0; i < n; i++) if (fullGroup.get(dsf.find(i))) errIsland[i] = 1;
    L.edges.forEach((edge, e) => {
      if (bridges[e] > 0 && fullGroup.get(dsf.find(edge.a))) errEdge[e] = 1;
    });
  }

  let loops = false;
  if (!L.allowLoops) {
    const onLoop = loopEdges(L, bridges);
    for (let e = 0; e < onLoop.length; e++) {
      if (onLoop[e]) {
        errEdge[e] = 1;
        loops = true;
      }
    }
  }

  return { counts, errIsland, errEdge, completed: allFull && groups === 1 && !loops };
}

// ------------------------------------------------------------- description format

/**
 * Parse a description: squares run row by row; a lower-case letter is a run of 1–26
 * empty squares, a digit 1–9 an island with that many bridges and `A`–`G` an island
 * with 10–16. Returns an error message when the text does not describe a usable
 * `w × h` puzzle.
 */
export function parseDesc(desc: string, w: number, h: number): IslandSpec[] | string {
  const n = w * h;
  const islands: IslandSpec[] = [];
  const taken = new Uint8Array(n);
  let i = 0;
  for (const c of desc) {
    if (i >= n) return tx`Description is longer than expected`;
    let clue: number;
    if (c >= 'a' && c <= 'z') {
      i += c.charCodeAt(0) - 96;
      continue;
    } else if (c >= '1' && c <= '9') {
      clue = c.charCodeAt(0) - 48;
    } else if (c >= 'A' && c <= 'G') {
      clue = c.charCodeAt(0) - 55;
    } else {
      return tx`Description contains an unexpected character`;
    }
    taken[i] = 1;
    islands.push({ x: i % w, y: Math.floor(i / w), clue });
    i++;
  }
  if (i > n) return tx`Description is longer than expected`;
  if (i < n) return tx`Description is shorter than expected`;
  if (islands.length < 2) return tx`Description must contain at least two islands`;
  for (const is of islands) {
    const k = is.y * w + is.x;
    if ((is.x + 1 < w && taken[k + 1]) || (is.y + 1 < h && taken[k + w]))
      return tx`Description places two islands next to each other`;
  }
  return islands;
}

export function encodeDesc(w: number, h: number, islands: IslandSpec[]): string {
  const clueAt = new Int32Array(w * h).fill(-1);
  for (const is of islands) clueAt[is.y * w + is.x] = is.clue;
  let out = '';
  let run = 0;
  const flush = () => {
    if (run) out += String.fromCharCode(96 + run);
    run = 0;
  };
  for (let i = 0; i < w * h; i++) {
    const c = clueAt[i];
    if (c >= 0) {
      flush();
      out += c < 10 ? String(c) : String.fromCharCode(55 + c);
    } else {
      if (run === 26) flush();
      run++;
    }
  }
  flush();
  return out;
}

/** Solver hint stored with a generated puzzle: one digit per edge, in layout order. */
export function encodeBridges(bridges: ArrayLike<number>): string {
  let s = '';
  for (let e = 0; e < bridges.length; e++) s += String(bridges[e]);
  return s;
}

export function decodeBridges(aux: string, L: Layout): Uint8Array | null {
  if (aux.length !== L.edges.length || !/^[0-4]*$/.test(aux)) return null;
  const out = new Uint8Array(aux.length);
  for (let e = 0; e < aux.length; e++) out[e] = aux.charCodeAt(e) - 48;
  return out;
}
