/**
 * Reversible obfuscation of a small byte string, so that a game description does not
 * spell out the answer when it appears in a URL. This follows the scheme the original
 * collection uses for Black Box (and Guess) so that its game IDs remain valid here:
 *
 * - The bytes are split in two halves (the first half rounded down).
 * - A mask generated from the second half is XORed over the first half.
 * - A mask generated from the (now masked) first half is XORed over the second half.
 *
 * Decoding performs the same two steps in the opposite order. The mask for a seed is
 * the concatenation of SHA-1(seed ‖ "0"), SHA-1(seed ‖ "1"), … as needed.
 */

function rotl(x: number, n: number): number {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

/** SHA-1 digest of a byte array (20 bytes). */
export function sha1(msg: Uint8Array): Uint8Array {
  const ml = msg.length;
  const padLen = (64 - ((ml + 1 + 8) % 64)) % 64;
  const total = ml + 1 + padLen + 8;
  const buf = new Uint8Array(total);
  buf.set(msg);
  buf[ml] = 0x80;
  const view = new DataView(buf.buffer);
  const bits = ml * 8;
  view.setUint32(total - 8, Math.floor(bits / 0x100000000));
  view.setUint32(total - 4, bits >>> 0);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;
  const w = new Uint32Array(80);
  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 80; i++) w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    for (let i = 0; i < 80; i++) {
      let f: number;
      let k: number;
      if (i < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + w[i]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }
    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }
  const out = new Uint8Array(20);
  const ov = new DataView(out.buffer);
  ov.setUint32(0, h0);
  ov.setUint32(4, h1);
  ov.setUint32(8, h2);
  ov.setUint32(12, h3);
  ov.setUint32(16, h4);
  return out;
}

/** XOR the SHA-1 based mask stream for `seed` over `bmp[start .. start+len)`. */
function applyMask(bmp: Uint8Array, seed: Uint8Array, start: number, len: number): void {
  let digest: Uint8Array = new Uint8Array(0);
  let pos = 20;
  let counter = 0;
  for (let j = 0; j < len; j++) {
    if (pos >= 20) {
      const num = String(counter++);
      const input = new Uint8Array(seed.length + num.length);
      input.set(seed);
      for (let k = 0; k < num.length; k++) input[seed.length + k] = num.charCodeAt(k);
      digest = sha1(input);
      pos = 0;
    }
    bmp[start + j] ^= digest[pos++];
  }
}

/**
 * Obfuscate (or, with `decode`, de-obfuscate) the first `bits` bits of `bmp` in place.
 * Padding bits in the final byte are always left clear.
 */
export function obfuscateBitmap(bmp: Uint8Array, bits: number, decode: boolean): void {
  const bytes = (bits + 7) >> 3;
  const first = bytes >> 1;
  const second = bytes - first;
  const steps: [number, number, number, number][] = [
    // [seed start, seed length, target start, target length]
    [first, second, 0, first],
    [0, first, first, second],
  ];
  if (decode) steps.reverse();
  for (const [seedStart, seedLen, targetStart, targetLen] of steps) {
    const seed = bmp.slice(seedStart, seedStart + seedLen);
    applyMask(bmp, seed, targetStart, targetLen);
    if (bits % 8) bmp[bits >> 3] &= 0xff & (0xff00 >> (bits % 8));
  }
}

export function bytesToHex(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += b.toString(16).padStart(2, '0');
  return s;
}

/** Parse a hex string (even length, validated by the caller) into bytes. */
export function hexToBytes(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length >> 1);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(2 * i, 2 * i + 2), 16);
  return out;
}
