import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
// A cycle with `./index`, which imports this list; safe, because `computeActive` is only
// called inside `test`, long after both modules have finished loading.
import { computeActive, type NetslideParams, type NetslideState } from './index';

type C = typeof PALETTE;

/**
 * A block of wired tiles at (x, y), `s` a side: `rows` gives each tile's wires as letters
 * from "ruld" (right, up, left, down), '.' for a tile with none. Lit wires are blue and
 * the rest grey, as on the board; a tile named in `shaded` gets the shaded background.
 */
function wires(
  c: C,
  x: number,
  y: number,
  s: number,
  rows: string[][],
  opts: { lit?: (i: number, j: number) => boolean; shaded?: string } = {},
): string {
  const w = s * 0.3;
  let bg = '';
  let under = '';
  let over = '';
  let ends = '';
  rows.forEach((row, j) => {
    row.forEach((cell, i) => {
      const px = x + i * s;
      const py = y + j * s;
      const fill = opts.shaded === `${i},${j}` ? c.shade : c.paper;
      bg += `<rect x="${px}" y="${py}" width="${s}" height="${s}" fill="${fill}" stroke="${c.pencil}" stroke-width="1.5"/>`;
      if (cell === '.') return;
      const cx = px + s / 2;
      const cy = py + s / 2;
      const to: Record<string, string> = {
        r: `${px + s} ${cy}`,
        u: `${cx} ${py}`,
        l: `${px} ${cy}`,
        d: `${cx} ${py + s}`,
      };
      let d = '';
      for (const k of cell) d += `M${cx} ${cy} L${to[k]} `;
      const colour = (opts.lit?.(i, j) ?? true) ? c.blue : c.lowlight;
      under += `<path d="${d}" stroke="${c.ink}" stroke-width="${w + 3}"/><circle cx="${cx}" cy="${cy}" r="${w / 2 + 1.5}" fill="${c.ink}"/>`;
      over += `<path d="${d}" stroke="${colour}" stroke-width="${w}"/><circle cx="${cx}" cy="${cy}" r="${w / 2}" fill="${colour}"/>`;
      if (cell.length === 1)
        ends += `<circle cx="${cx}" cy="${cy}" r="${s * 0.2}" fill="${colour}" stroke="${c.ink}" stroke-width="2.5"/>`;
    });
  });
  const W = rows[0].length * s;
  const H = rows.length * s;
  return (
    bg +
    under +
    over +
    ends +
    `<rect x="${x}" y="${y}" width="${W}" height="${H}" fill="none" stroke="${c.ink}" stroke-width="3.5"/>`
  );
}

function arrow(
  c: C,
  x: number,
  y: number,
  dx: number,
  dy: number,
  r: number,
  fill: string,
): string {
  const px = -dy;
  const py = dx;
  const pt = (a: number, b: number) =>
    `${(x + dx * a + px * b).toFixed(1)} ${(y + dy * a + py * b).toFixed(1)}`;
  return `<path d="M${pt(r, 0)} L${pt(-r * 0.6, r)} L${pt(-r * 0.6, -r)} Z" fill="${fill}" stroke="${c.ink}" stroke-width="3" stroke-linejoin="round"/>`;
}

function lit(s: NetslideState): number {
  let n = 0;
  for (const v of computeActive(s)) n += v;
  return n;
}

export const achievements = defineAchievements<NetslideParams, NetslideState>([
  {
    id: 'tidy-four',
    name: 'Tidy Rewiring',
    description: 'Solve a 4×4 Netslide in 18 slides or fewer.',
    tier: 'silver',
    hue: 'teal',
    // Two rows of network, the bottom one not yet slid into place, and its arrow.
    art: (c) =>
      wires(c, 22, 22, 18, [['rd', 'lrd', 'l']]) +
      wires(c, 22, 40, 18, [['u', 'ud', 'd']], { lit: (i) => i === 1 }) +
      `<path d="M24 72 H64" stroke="${c.ink}" stroke-width="4" stroke-linecap="round"/>` +
      arrow(c, 72, 72, 1, 0, 8, c.teal),
    test: (ctx) => ctx.params.w === 4 && ctx.params.h === 4 && ctx.moves <= 18,
  },
  {
    id: 'lean-five',
    name: 'Lineman',
    description: 'Solve a 5×5 Netslide in 32 slides or fewer.',
    tier: 'gold',
    hue: 'yellow',
    // A finished 3×3 of network round the shaded source, every wire lit.
    art: (c) =>
      wires(
        c,
        23,
        23,
        18,
        [
          ['r', 'lrd', 'ld'],
          ['rd', 'ul', 'ud'],
          ['u', 'r', 'ul'],
        ],
        { shaded: '1,1' },
      ),
    test: (ctx) => ctx.params.w === 5 && ctx.params.h === 5 && ctx.moves <= 32,
  },
  {
    id: 'big-switch',
    name: 'The Big Switch',
    description: 'Light the whole network with one slide when under half of it was lit.',
    tier: 'bronze',
    hidden: true,
    hue: 'orange',
    // A dark network lighting up all at once, with a lightning bolt.
    art: (c) =>
      wires(
        c,
        20,
        30,
        20,
        [
          ['rd', 'l'],
          ['ur', 'l'],
        ],
        { lit: (_i, j) => j === 1 },
      ) +
      `<path d="M72 18 L60 48 H71 L62 80 L84 42 H73 L82 18 Z" fill="${c.yellow}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>`,
    test: (ctx) => {
      const before = ctx.history[ctx.history.length - 2];
      return !!before && lit(before) * 2 < before.w * before.h;
    },
  },
]);
