/**
 * Unruly puzzle generation.
 *
 * A full valid grid is built by a randomised backtracking search: cells are visited in
 * a shuffled order, each empty one is given a random colour, the solver fills in what
 * that forces, and the search backs up when a rule breaks. Then the cells are visited
 * in another shuffled order and each one is emptied as long as the solver of the chosen
 * difficulty can still complete the puzzle from the remaining clues. Because the solver
 * only makes forced deductions, that guarantees a unique solution. Finally a Normal
 * puzzle must defeat the Easy solver, otherwise a new grid is tried.
 */
import type { Random } from '../../framework/rng';
import { BLACK, EMPTY, WHITE, encodeDesc, encodeSolution } from './board';
import { DIFF_NORMAL, Solver } from './solver';

export interface GenParams {
  w: number;
  h: number;
  /** No two rows and no two columns may match. */
  unique: boolean;
  difficulty: number;
}

/**
 * Dead ends tolerated per fill attempt. A random order that gets into trouble usually
 * went wrong long before the search notices, so a fresh shuffle beats backtracking.
 */
const FILL_DEAD_ENDS = 12;

/**
 * A random complete grid obeying the rules, or null if the search hit too many dead
 * ends (the caller reshuffles and tries again).
 */
export function fillGrid(w: number, h: number, unique: boolean, rng: Random): Uint8Array | null {
  const n = w * h;
  const order: number[] = [];
  for (let i = 0; i < n; i++) order.push(i);
  rng.shuffle(order);
  let deadEnds = 0;

  const step = (solver: Solver, k: number): Uint8Array | null => {
    while (k < n && solver.grid[order[k]] !== EMPTY) k++;
    if (k === n) return solver.solved() ? solver.grid : null;
    const first = rng.upto(2) ? BLACK : WHITE;
    for (const c of [first, first === BLACK ? WHITE : BLACK]) {
      const next = solver.clone();
      next.set(order[k], c);
      next.run(DIFF_NORMAL);
      if (next.contradiction()) continue;
      const r = step(next, k + 1);
      if (r || deadEnds > FILL_DEAD_ENDS) return r;
    }
    deadEnds++;
    return null;
  };
  return step(new Solver(w, h, unique, new Uint8Array(n)), 0);
}

/** Whether the solver of tier `diff` completes the puzzle from these clues alone. */
export function solvableAt(
  clues: Uint8Array,
  w: number,
  h: number,
  unique: boolean,
  diff: number,
): boolean {
  const s = new Solver(w, h, unique, clues);
  s.run(diff);
  return s.isFull() && s.solved();
}

/**
 * Remove clues from a full grid in random order while the puzzle stays solvable at the
 * requested difficulty.
 */
export function winnow(
  solution: Uint8Array,
  w: number,
  h: number,
  unique: boolean,
  diff: number,
  rng: Random,
): Uint8Array {
  const clues = solution.slice();
  const order: number[] = [];
  for (let i = 0; i < clues.length; i++) order.push(i);
  rng.shuffle(order);
  for (const i of order) {
    const c = clues[i];
    clues[i] = EMPTY;
    if (!solvableAt(clues, w, h, unique, diff)) clues[i] = c;
  }
  return clues;
}

export function generate(p: GenParams, rng: Random): { desc: string; aux: string } {
  const { w, h, unique, difficulty } = p;
  for (;;) {
    let solution: Uint8Array | null = null;
    while (!solution) solution = fillGrid(w, h, unique, rng);
    const clues = winnow(solution, w, h, unique, difficulty, rng);
    // A puzzle meant to be Normal must not fall to the Easy solver.
    if (difficulty > 0 && solvableAt(clues, w, h, unique, difficulty - 1)) continue;
    return { desc: encodeDesc(clues), aux: encodeSolution(solution) };
  }
}
