/**
 * The language switcher: a sketched `<select>` of every locale the collection ships,
 * labelled in each language's own name. Choosing one calls `setLocaleAsync`, which fetches
 * that language's catalogue, persists the choice, updates `<html lang>`/`<html dir>` and
 * re-renders the current page — in that order, so the page never blinks through English on
 * its way to the language the player just asked for.
 */

import {
  LOCALE_NAMES,
  SUPPORTED_LOCALES,
  getLocale,
  hasTranslations,
  localeFromUrl,
  setLocaleAsync,
  t,
  urlWithoutLang,
} from '../i18n';

/**
 * `onSwitched` runs once the page is in the new language — after the re-render the switch
 * causes, which takes any dialog the picker was in down with the page it belonged to. The
 * Settings screen uses it to come straight back up, in the new language.
 */
export function languageSwitcher(onSwitched?: () => void): HTMLLabelElement {
  const label = document.createElement('label');
  label.className = 'lang-select';
  const caption = document.createElement('span');
  caption.textContent = t('ui.menu.language');
  const select = document.createElement('select');
  select.className = 'sketch-input';
  select.setAttribute('aria-label', t('ui.menu.language'));
  const current = getLocale();
  const codes = [...SUPPORTED_LOCALES].sort((a, b) =>
    a === 'en' ? -1 : b === 'en' ? 1 : (LOCALE_NAMES[a] ?? a).localeCompare(LOCALE_NAMES[b] ?? b),
  );
  for (const code of codes) {
    const opt = document.createElement('option');
    opt.value = code;
    opt.textContent = LOCALE_NAMES[code] ?? code;
    // A language whose catalogue is still a stub falls back to English; say so rather
    // than letting it look broken.
    if (!hasTranslations(code)) opt.textContent += ' …';
    opt.selected = code === current;
    select.append(opt);
  }
  select.addEventListener('change', () => {
    // The catalogue is a chunk of its own; awaiting it here is what keeps `t()` — and so
    // every component that renders with it — synchronous.
    // A `?lang=` in the address outranks the remembered choice, so it has to go: left in,
    // it put the page straight back into its language on the next reload, and on the very
    // next hash change (opening a puzzle) through the router's `hashchange` handler.
    if (localeFromUrl()) {
      try {
        history.replaceState(history.state, '', urlWithoutLang(location.href));
      } catch {
        /* a sandboxed frame may refuse; the choice still applies for this visit */
      }
    }
    // A catalogue that cannot be fetched (offline) leaves the page as it was; so must the
    // picker, rather than naming a language the page is not in.
    const before = getLocale();
    void setLocaleAsync(select.value).then(() => {
      if (select.isConnected) select.value = getLocale();
      if (getLocale() !== before) onSwitched?.();
    });
  });
  label.append(caption, select);
  return label;
}
