import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { KeenParams } from './generator';
import type { KeenState } from './index';
import { DIFF_NORMAL } from './solver';

type C = typeof PALETTE;

/** A yellow pencil lying along `angle` degrees, its point at the right in local terms. */
function pencil(c: C, cx: number, cy: number, angle: number): string {
  return (
    `<g transform="translate(${cx} ${cy}) rotate(${angle})">` +
    `<path d="M-28 -6 H-20 V6 H-28 Z" fill="${c.pink}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
    `<path d="M-20 -6 H12 V6 H-20 Z" fill="${c.yellow}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
    `<path d="M12 -6 L25 0 L12 6 Z" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
    `<path d="M20 -2.3 L25 0 L20 2.3 Z" fill="${c.ink}"/>` +
    `</g>`
  );
}

/** A little Keen board: `n`×`n` squares of size `s` from (x, y), with a cage wall. */
function board(c: C, x: number, y: number, n: number, s: number, cage: string): string {
  let thin = '';
  for (let i = 1; i < n; i++) {
    thin += `M${x + i * s} ${y} V${y + n * s} M${x} ${y + i * s} H${x + n * s} `;
  }
  return (
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" fill="${c.paper}"/>` +
    `<path d="${thin}" stroke="${c.pencil}" stroke-width="2"/>` +
    `<path d="${cage}" fill="none" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/>` +
    `<rect x="${x}" y="${y}" width="${n * s}" height="${n * s}" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>`
  );
}

/** A multiplication sign, the operator the gold one is about. */
function times(c: C, cx: number, cy: number, r: number, w: number): string {
  return `<path d="M${cx - r} ${cy - r} L${cx + r} ${cy + r} M${cx + r} ${cy - r} L${cx - r} ${cy + r}" stroke="${c.red}" stroke-width="${w}" stroke-linecap="round"/>`;
}

export const achievements = defineAchievements<KeenParams, KeenState>([
  {
    id: 'no-pencil',
    name: 'Mental Arithmetic',
    description: 'Solve a 6×6 Keen or larger without writing a single pencil mark.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      board(c, 17, 17, 3, 16, 'M33 17 V49 H65 M17 49 H33') +
      // Two digits inked in, no notes anywhere.
      `<path d="M21 23 Q25 19 29 23 Q31 26 21 34 H30 M40 23 L44 20 V35" fill="none" stroke="${c.ink}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>` +
      pencil(c, 64, 64, -50) +
      `<path d="M48 54 L80 76" stroke="${c.red}" stroke-width="6" stroke-linecap="round"/>`,
    test: (ctx) => ctx.params.w >= 6 && ctx.history.every((s) => !s.pencil.includes(1)),
  },
  {
    id: 'products-only',
    name: 'Pure Product',
    description: 'Solve a 6×6 Medium Keen with multiplication only.',
    tier: 'gold',
    hue: 'orange',
    art: (c) =>
      board(c, 20, 20, 2, 30, 'M50 20 V50 H80') +
      times(c, 35, 35, 7, 6) +
      times(c, 65, 35, 7, 6) +
      times(c, 35, 65, 7, 6) +
      times(c, 65, 65, 7, 6),
    test: (ctx) => ctx.params.multOnly && ctx.params.w >= 6 && ctx.params.diff >= DIFF_NORMAL,
  },
]);
