/**
 * Per-game help text, per locale.
 *
 * English lives where a game author writes it: `src/games/<slug>/help.md`, imported by the
 * game and exposed as `game.help`. A translation is a plain Markdown file at
 * `src/i18n/help/<locale>/<slug>.md` — real Markdown a translator can edit with normal
 * tooling, keeping the `### Keyboard` heading and the mouse wording that the shell rewrites
 * for touch screens. Nothing has to be escaped into JSON, and a missing file simply means
 * the English help is shown.
 *
 * Translations are loaded on demand (there are 38 files per language), so the help drawer
 * paints from whatever is cached — English on the first open — and refreshes itself when
 * the translation arrives.
 */

import { DEFAULT_LOCALE, getLocale } from './locale';

const translated = import.meta.glob<string>('./help/*/*.md', {
  query: '?raw',
  import: 'default',
});

const cache = new Map<string, string>();
const inFlight = new Map<string, Promise<string | null>>();

function pathFor(locale: string, slug: string): string {
  return `./help/${locale}/${slug}.md`;
}

/** Locales that ship at least one translated help file. */
export function helpLocales(): string[] {
  const out = new Set<string>();
  for (const p of Object.keys(translated)) {
    const m = /^\.\/help\/([^/]+)\//.exec(p);
    if (m) out.add(m[1]);
  }
  return [...out].sort();
}

/**
 * The markdown to show right now for one help document: the cached translation when there
 * is one, the English source otherwise. Always synchronous, so the drawer can be built in
 * one pass and refreshed when `loadHelp` resolves.
 *
 * `doc` is a game slug, or one of the shell's own documents: `_common` (the common
 * controls appended to every game) and `_touch` (the touch-screen section).
 */
export function helpNow(doc: string, english: string, locale = getLocale()): string {
  if (locale === DEFAULT_LOCALE) return english;
  return cache.get(pathFor(locale, doc)) ?? english;
}

/**
 * Fetch a translated help document, caching it. Resolves with the markdown to show — the
 * translation, or the English source when this language has no file for it.
 */
export function loadHelp(doc: string, english: string, locale = getLocale()): Promise<string> {
  if (locale === DEFAULT_LOCALE) return Promise.resolve(english);
  const path = pathFor(locale, doc);
  const cached = cache.get(path);
  if (cached !== undefined) return Promise.resolve(cached);
  const loader = translated[path];
  if (!loader) return Promise.resolve(english);
  let pending = inFlight.get(path);
  if (!pending) {
    pending = loader()
      .then((md) => {
        const text = typeof md === 'string' ? md : null;
        if (text) cache.set(path, text);
        return text;
      })
      .catch((e) => {
        console.warn(`help ${doc} in ${locale} failed to load`, e);
        return null;
      })
      .finally(() => inFlight.delete(path));
    inFlight.set(path, pending);
  }
  return pending.then((md) => md ?? english);
}

/** True when this locale ships a file for `doc`, so a reload is worth waiting for. */
export function hasTranslatedHelp(doc: string, locale = getLocale()): boolean {
  return locale !== DEFAULT_LOCALE && !!translated[pathFor(locale, doc)];
}
