import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { GalaxiesParams, GalaxiesState } from './index';

type C = typeof PALETTE;

/** Faint grid lines over a square of `n`×`n` cells of size `t` from (x, y). */
function grid(c: C, x: number, y: number, n: number, t: number): string {
  let d = '';
  for (let i = 0; i <= n; i++)
    d += `M${x + i * t} ${y} V${y + n * t} M${x} ${y + i * t} H${x + n * t} `;
  return (
    `<rect x="${x}" y="${y}" width="${n * t}" height="${n * t}" fill="${c.faint}"/>` +
    `<path d="${d}" stroke="${c.lowlight}" stroke-width="1.6"/>`
  );
}

/** The galaxy's dot: white with an ink ring, like the board's. */
function dot(c: C, cx: number, cy: number, r = 5): string {
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.highlight}" stroke="${c.ink}" stroke-width="3"/>`;
}

/** A region turned through 180° about its middle square lands on itself: an S of five. */
const S_REGION = 'M23 23 H59 V59 H77 V77 H41 V41 H23 Z';

function walled(c: C, fill: string): string {
  return (
    grid(c, 23, 23, 3, 18) +
    `<path d="${S_REGION}" fill="${fill}"/>` +
    `<path d="M23 23 H77 V77 H23 Z" fill="none" stroke="${c.ink}" stroke-width="3"/>` +
    `<path d="${S_REGION}" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>`
  );
}

/** No wall that was drawn on the kept line is ever taken away again. */
function wallsOnlyAdded(history: readonly GalaxiesState[]): boolean {
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].edges;
    const b = history[k].edges;
    for (let i = 0; i < a.length; i++) if (a[i] && !b[i]) return false;
  }
  return true;
}

export const achievements = defineAchievements<GalaxiesParams, GalaxiesState>([
  {
    id: 'no-arrows',
    name: 'No Pointers',
    description: 'Solve a 10×10 or larger Galaxies without dragging out a single arrow.',
    tier: 'silver',
    hue: 'teal',
    // A finished galaxy, and the reminder arrow that was never needed.
    art: (c) =>
      walled(c, c.highlight) +
      dot(c, 50, 50) +
      `<path d="M24 61 L40 77 M40 61 L24 77" stroke="${c.red}" stroke-width="3.5" stroke-linecap="round"/>` +
      `<path d="M26 75 L37 64 M37 64 H29.5 M37 64 V71.5" fill="none" stroke="${c.blue}" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 10 &&
      ctx.params.h >= 10 &&
      ctx.history.every((s) => !s.assoc.some((a) => a >= 0)),
  },
  {
    id: 'steady-hand',
    name: 'Fixed Stars',
    description: 'Solve a 10×10 or larger Galaxies without removing a wall or using Undo.',
    tier: 'gold',
    hue: 'violet',
    // The same galaxy, its walls drawn once, with a spiral swirling about its dot.
    art: (c) =>
      walled(c, c.highlight) +
      `<path d="M50 45 C50 32 40 29 29 32 M50 55 C50 68 60 71 71 68" fill="none" stroke="${c.violet}" stroke-width="5" stroke-linecap="round"/>` +
      `<path d="M46 43 C44 36 38 36 34 38 M54 57 C56 64 62 64 66 62" fill="none" stroke="${c.blue}" stroke-width="3" stroke-linecap="round"/>` +
      dot(c, 50, 50),
    test: (ctx) =>
      ctx.params.w >= 10 && ctx.params.h >= 10 && ctx.undos === 0 && wallsOnlyAdded(ctx.history),
  },
]);
