import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  F_BLACK,
  F_CIRCLE,
  checkGrid,
  decodeBlacks,
  isValidSolution,
  numToChar,
  parseDesc,
} from './board';
import type { GridCheck } from './board';
import { generate } from './generator';
import type { GenParams } from './generator';
import { DIFFICULTY_NAMES, DIFF_CHARS, DIFF_EASY, DIFF_TRICKY, findSolution } from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type SinglesParams = GenParams;

export interface SinglesState {
  w: number;
  h: number;
  /** The numbers, one per cell (row-major). Shared between states. */
  nums: Uint8Array;
  /** `F_BLACK`, `F_CIRCLE` or 0 per cell. */
  flags: Uint8Array;
  /** Rule check of this position, including what to highlight. */
  check: GridCheck;
  completed: boolean;
  usedSolve: boolean;
}

export interface SinglesUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MIN_SIDE = 2;
/** The description format runs out of characters at 62; bigger grids also generate slowly. */
const MAX_SIDE = 62;
/** Past this the Easy generator can take several seconds. */
const MAX_GEN_SIDE = 20;
const DEFAULTS: SinglesParams = { w: 5, h: 5, difficulty: DIFF_EASY };

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

function makeState(
  w: number,
  h: number,
  nums: Uint8Array,
  flags: Uint8Array,
  usedSolve = false,
): SinglesState {
  const check = checkGrid(nums, flags, w, h);
  return { w, h, nums, flags, check, completed: check.complete, usedSolve };
}

/**
 * Sketch a red outline around every group of cells set in `mask`, inset by `m` inside the
 * group. Edges are drawn per cell; an end reaches past the cell boundary at an inside
 * corner so the segments meet.
 */
function outlineCells(
  dr: Drawing,
  mask: Uint8Array,
  w: number,
  h: number,
  b: number,
  t: number,
  m: number,
  width: number,
): void {
  const inMask = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h && !!mask[y * w + x];
  // How far an edge running along `along` extends at the end towards (ax, ay): -m when
  // the next cell in that direction is outside the group, +m at an inside corner (the
  // next cell is in the group but the one diagonally across the edge is too), else 0.
  const reach = (x: number, y: number, ax: number, ay: number, nx: number, ny: number) => {
    if (!inMask(x + ax, y + ay)) return -m;
    return inMask(x + ax + nx, y + ay + ny) ? m : 0;
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!mask[y * w + x]) continue;
      const px = b + x * t;
      const py = b + y * t;
      const seed = y * w + x;
      if (!inMask(x, y - 1)) {
        const l = reach(x, y, -1, 0, 0, -1);
        const r = reach(x, y, 1, 0, 0, -1);
        dr.line(px - l, py + m, px + t + r, py + m, 'error', width, { seed });
      }
      if (!inMask(x, y + 1)) {
        const l = reach(x, y, -1, 0, 0, 1);
        const r = reach(x, y, 1, 0, 0, 1);
        dr.line(px - l, py + t - m, px + t + r, py + t - m, 'error', width, { seed: seed + 1 });
      }
      if (!inMask(x - 1, y)) {
        const u = reach(x, y, 0, -1, -1, 0);
        const d = reach(x, y, 0, 1, -1, 0);
        dr.line(px + m, py - u, px + m, py + t + d, 'error', width, { seed: seed + 2 });
      }
      if (!inMask(x + 1, y)) {
        const u = reach(x, y, 0, -1, 1, 0);
        const d = reach(x, y, 0, 1, 1, 0);
        dr.line(px + t - m, py - u, px + t - m, py + t + d, 'error', width, { seed: seed + 3 });
      }
    }
  }
}

const game = defineGame<SinglesParams, SinglesState, SinglesUI>({
  id: 'singles',
  name: 'Singles',
  description:
    'Black out cells so that no number repeats in a row or column, without splitting the grid.',
  alsoKnownAs: 'Hitori',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [5, 5, DIFF_EASY],
      [5, 5, DIFF_TRICKY],
      [6, 6, DIFF_EASY],
      [6, 6, DIFF_TRICKY],
      [8, 8, DIFF_EASY],
      [8, 8, DIFF_TRICKY],
      [10, 10, DIFF_EASY],
      [10, 10, DIFF_TRICKY],
      [12, 12, DIFF_EASY],
      [12, 12, DIFF_TRICKY],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, difficulty },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? `d${DIFF_CHARS[p.difficulty] ?? '?'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.?))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    let difficulty = DIFF_EASY;
    if (m[3] !== undefined) {
      const d = DIFF_CHARS.indexOf(m[3]);
      // An unknown letter is kept as an invalid difficulty so validateParams can say so.
      difficulty = m[3] === '' || d < 0 ? DIFFICULTY_NAMES.length : d;
    }
    return { w, h, difficulty };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`Width, height and difficulty must be whole numbers`;
    if (p.w < MIN_SIDE || p.h < MIN_SIDE) return tx`Width and height must be at least ${MIN_SIDE}`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Puzzle is too large`;
    if (full) {
      if (p.w > MAX_GEN_SIDE || p.h > MAX_GEN_SIDE)
        return tx`Width and height must be at most ${MAX_GEN_SIDE} to generate a puzzle`;
      if (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length)
        return tx`Unknown difficulty rating`;
    }
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    return {
      // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
      w: /^-?\d+$/.test(str(0)) ? parseInt(str(0), 10) : NaN,
      h: /^-?\d+$/.test(str(1)) ? parseInt(str(1), 10) : NaN,
      difficulty: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const nums = parseDesc(desc, p.w, p.h) as Uint8Array;
    const state = makeState(p.w, p.h, nums, new Uint8Array(p.w * p.h));
    // A fresh puzzle is never "completed", even one with no repeated numbers.
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const { w, h, nums } = curr;
    const n = w * h;
    let blacks: Uint8Array | null = null;
    if (aux !== undefined) {
      const f = decodeBlacks(aux, n);
      if (f && isValidSolution(nums, f, w, h)) blacks = f;
    }
    blacks ??= findSolution(nums, w, h);
    if (!blacks) throw new Error(tx`Unable to solve this puzzle`);
    // The solved grid has every cell decided: black, or circled to say it is white.
    let move = 'S';
    for (let i = 0; i < n; i++) {
      const want = blacks[i] & F_BLACK ? F_BLACK : F_CIRCLE;
      if (curr.flags[i] !== want)
        move += `;${want === F_BLACK ? 'B' : 'C'}${i % w},${Math.floor(i / w)}`;
    }
    return move;
  },

  textFormat(s) {
    // Two lines per row like the original: numbers (`*` for black), then `~` under circles.
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      const top: string[] = [];
      const under: string[] = [];
      for (let x = 0; x < s.w; x++) {
        const i = y * s.w + x;
        top.push(s.flags[i] & F_BLACK ? '*' : numToChar(s.nums[i]));
        under.push(s.flags[i] & F_CIRCLE ? '~' : ' ');
      }
      rows.push(top.join(' '), under.join(' ').trimEnd());
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false }),
  changedState(ui, old, next) {
    if (!old.completed && next.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, flags } = state;
    let x: number;
    let y: number;
    let circle: boolean;
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h, true);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else if (b === CURSOR_SELECT || b === CURSOR_SELECT2) {
      x = ui.cx;
      y = ui.cy;
      ui.cursorVisible = true;
      circle = b === CURSOR_SELECT2;
    } else if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      // Hiding a visible cursor is itself a change worth redrawing.
      const idle = ui.cursorVisible ? '' : null;
      ui.cursorVisible = false;
      const t = ds.tileSize;
      const bd = boardBorder(t);
      x = Math.floor((mx - bd) / t);
      y = Math.floor((my - bd) / t);
      if (x < 0 || y < 0 || x >= w || y >= h) return idle;
      circle = b === RIGHT_BUTTON;
    } else {
      return null;
    }
    const i = y * w + x;
    // Any mark is cleared by either button; an empty cell gets the button's mark.
    const c = flags[i] & (F_BLACK | F_CIRCLE) ? 'E' : circle ? 'C' : 'B';
    return `${c}${x},${y}`;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h, nums } = state;
    const flags = state.flags.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = /^([BCE])(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      flags[y * w + x] = m[1] === 'B' ? F_BLACK : m[1] === 'C' ? F_CIRCLE : 0;
    }
    return makeState(w, h, nums, flags, usedSolve);
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, nums, flags, check } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const cellX = (x: number) => b + x * t;
    const cellY = (y: number) => b + y * t;

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(cellX(x), b, cellX(x), b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, cellY(y), b + w * t, cellY(y), 'faint', 1.2);

    const textSize = t * 0.55;
    const circleR = t * 0.37;
    const circleW = Math.max(1.6, t * 0.06);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = cellX(x);
        const py = cellY(y);
        const label = String(nums[i]);
        if (flags[i] & F_BLACK) {
          const g = Math.max(0.5, t * 0.02);
          dr.polygon(
            [px + g, py + g, px + t - g, py + g, px + t - g, py + t - g, px + g, py + t - g],
            'ink',
            'ink',
            { seed: i, width: 1.4 },
          );
          // The removed number stays faintly legible, so a wrong guess can be checked.
          dr.text(px + t / 2, py + t / 2, label, {
            size: textSize,
            colour: 'paper',
            alpha: 0.28,
            maxWidth: t * 0.8,
          });
          continue;
        }
        const bad = check.clash[i] === 1;
        if (flags[i] & F_CIRCLE) {
          dr.circle(px + t / 2, py + t / 2, circleR, null, bad ? 'error' : 'pencil', {
            width: circleW,
            seed: i,
          });
        }
        dr.text(px + t / 2, py + t / 2, label, {
          size: textSize,
          colour: bad ? 'error' : flash ? 'ok' : 'ink',
          maxWidth: t * 0.72,
        });
      }
    }
    // Touching black cells get a red frame around the group; white cells cut off from the
    // main region get a red outline.
    const frameW = Math.max(2, t * 0.07);
    outlineCells(dr, check.badBlack, w, h, b, t, t * 0.1, frameW);
    outlineCells(dr, check.cutOff, w, h, b, t, t * 0.08, frameW);
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (ui.cursorVisible) {
      const ci = t * 0.1;
      dr.cursor(cellX(ui.cx) + ci, cellY(ui.cy) + ci, t - 2 * ci, t - 2 * ci);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // A few correct marks on the fixed-seed thumbnail puzzle, so the card shows the game.
  thumbnailMoves: ['B0,0', 'B3,0', 'C1,0', 'B2,1', 'C1,1', 'B0,2'],
});

export default game;
