/**
 * Deductive Light Up solver.
 *
 * The solver works on a `Work` — lights, "impossible" marks and lighting counts over a
 * fixed `Layout` — and knows three tiers of reasoning, one per difficulty:
 *
 *  - **Easy**: an unlit square that can only be lit from one place gets a light there;
 *    a clue whose remaining lights are all accounted for makes its other neighbours
 *    impossible, and one that needs as many lights as it has free neighbours gets them.
 *  - **Tricky** adds "set discounting": any unlit square yields a set of squares of which
 *    at least one must be a light (the squares that could light it), and a clue needing
 *    m of its n free neighbours yields every (n − m + 1)-subset of them. If placing a
 *    light somewhere would rule out every member of such a set, that square can never
 *    hold a light.
 *  - **Hard** allows guessing: when stuck, the square that would light the most squares
 *    is tried both ways, up to `MAX_RECURSE` levels deep.
 *
 * `solve` returns the number of solutions found (1 means unique), or -1 when it ran out
 * of recursion before it could be sure. With `SOLVE_UNIQUE` both branches of every guess
 * are explored so the count is trustworthy; without it the first solution is returned.
 */
import { Layout, NO_CLUE } from './board';

export const DIFF_EASY = 0;
export const DIFF_TRICKY = 1;
export const DIFF_HARD = 2;
export const DIFFICULTY_NAMES = ['Easy', 'Tricky', 'Hard'];

/** Insist on counting every solution rather than stopping at the first. */
export const SOLVE_UNIQUE = 1;
/** Use set discounting (Tricky). */
export const SOLVE_DISCOUNT = 2;
/** Allow guessing (Hard). */
export const SOLVE_RECURSE = 4;

export const MAX_RECURSE = 5;

/** The solver flags the generator uses for a given difficulty. */
export function solveFlags(difficulty: number): number {
  let f = SOLVE_UNIQUE;
  if (difficulty >= DIFF_TRICKY) f |= SOLVE_DISCOUNT;
  if (difficulty >= DIFF_HARD) f |= SOLVE_RECURSE;
  return f;
}

/** Mutable solving state over a layout. */
export class Work {
  light: Uint8Array;
  imposs: Uint8Array;
  /** Number of lights shining on each square (a light counts itself). */
  lit: Int16Array;
  /** Clues whose deductions were needed; the generator strips the others. */
  used: Uint8Array;
  /** Set when a contradiction was found. */
  dead = false;

  constructor(readonly L: Layout) {
    this.light = new Uint8Array(L.n);
    this.imposs = new Uint8Array(L.n);
    this.lit = new Int16Array(L.n);
    this.used = new Uint8Array(L.n);
  }

  clone(): Work {
    const w = new Work(this.L);
    w.assign(this);
    return w;
  }

  assign(o: Work): void {
    this.light.set(o.light);
    this.imposs.set(o.imposs);
    this.lit.set(o.lit);
    this.used.set(o.used);
    this.dead = o.dead;
  }

  /** A light may still go here: white, unmarked and not lit by anything. */
  couldPlace(i: number): boolean {
    return !this.L.black[i] && !this.imposs[i] && this.lit[i] === 0;
  }

  setLight(i: number, on: boolean): void {
    if (!!this.light[i] === on) return;
    const d = on ? 1 : -1;
    this.light[i] = on ? 1 : 0;
    this.lit[i] += d;
    for (const j of this.L.rays[i]) this.lit[j] += d;
  }

  overlap(): boolean {
    for (let i = 0; i < this.L.n; i++) if (this.light[i] && this.lit[i] > 1) return true;
    return false;
  }

  correct(): boolean {
    const { L } = this;
    for (let i = 0; i < L.n; i++) {
      if (L.black[i]) {
        if (L.clue[i] === NO_CLUE) continue;
        let n = 0;
        for (const j of L.adj[i]) if (this.light[j]) n++;
        if (n !== L.clue[i]) return false;
      } else if (this.lit[i] === 0 || (this.light[i] && this.lit[i] > 1)) {
        return false;
      }
    }
    return true;
  }
}

export interface SolveOutcome {
  /** Solutions found: 0 none, 1 unique, more for ambiguous, -1 for "ran out of depth". */
  nsol: number;
  /** Deepest guess level needed (0 = pure deduction). */
  maxDepth: number;
}

class Solver {
  maxDepth = 0;
  private readonly mark: Uint8Array;
  private readonly tmp: number[] = [];
  private readonly cands: number[] = [];
  private readonly set: number[] = [];

  constructor(
    readonly L: Layout,
    readonly flags: number,
    readonly maxRecurse: number,
  ) {
    this.mark = new Uint8Array(L.n);
  }

  solveSub(work: Work, depth: number): number {
    if (depth > this.maxDepth) this.maxDepth = depth;
    const { L } = this;
    const n = L.n;
    for (;;) {
      if (work.dead || work.overlap()) return 0;
      if (work.correct()) return 1;

      let did = false;
      let canPlace = 0;
      for (let i = 0; i < n; i++) {
        if (L.black[i]) {
          if (L.clue[i] !== NO_CLUE && this.trySolveNumber(work, i)) did = true;
        } else {
          if (work.couldPlace(i)) canPlace++;
          if (work.lit[i] === 0 && this.trySolveLight(work, i)) did = true;
        }
      }
      if (work.dead) return 0;
      if (did) continue;
      if (!canPlace) return 0;

      if (this.flags & SOLVE_DISCOUNT) {
        for (let i = 0; i < n && !did; i++) {
          if (L.black[i]) {
            if (L.clue[i] !== NO_CLUE) did = this.discountClue(work, i);
          } else if (work.lit[i] === 0) {
            did = this.discountUnlit(work, i);
          }
        }
        if (did) continue;
      }

      if (depth >= this.maxRecurse) return -1;

      // Guess: the placeable square that would light the most unlit squares.
      let best = -1;
      let bestN = 0;
      for (let i = 0; i < n; i++) {
        if (!work.couldPlace(i)) continue;
        let k = 1;
        for (const j of L.rays[i]) if (work.lit[j] === 0) k++;
        if (k > bestN) {
          bestN = k;
          best = i;
        }
      }
      const copy = work.clone();
      work.imposs[best] = 1;
      const selfSol = this.solveSub(work, depth + 1);
      if (!(this.flags & SOLVE_UNIQUE) && selfSol > 0) return selfSol;
      copy.setLight(best, true);
      const copySol = this.solveSub(copy, depth + 1);
      if (this.flags & SOLVE_UNIQUE && (copySol < 0 || selfSol < 0)) return -1;
      if (copySol <= 0) return selfSol;
      if (selfSol <= 0) {
        work.assign(copy);
        return copySol;
      }
      return copySol + selfSol;
    }
  }

  /** An unlit square with a single remaining way to be lit forces that light. */
  private trySolveLight(work: Work, i: number): boolean {
    let count = 0;
    let cand = -1;
    if (work.couldPlace(i)) {
      count++;
      cand = i;
    }
    for (const j of this.L.rays[i]) {
      if (!work.couldPlace(j)) continue;
      cand = j;
      if (++count > 1) break;
    }
    if (count === 0) {
      work.dead = true;
      return false;
    }
    if (count === 1) {
      work.setLight(cand, true);
      return true;
    }
    return false;
  }

  /** A clue that is already full, or needs every free neighbour, settles them all. */
  private trySolveNumber(work: Work, c: number): boolean {
    const { L } = this;
    let need = L.clue[c];
    let free = 0;
    for (const j of L.adj[c]) {
      if (work.light[j]) need--;
      else if (work.couldPlace(j)) free++;
    }
    if (need < 0 || need > free) {
      work.dead = true;
      return false;
    }
    if (free === 0) return false;
    if (need === 0) {
      work.used[c] = 1;
      for (const j of L.adj[c]) if (work.couldPlace(j)) work.imposs[j] = 1;
      return true;
    }
    if (need === free) {
      work.used[c] = 1;
      const todo: number[] = [];
      for (const j of L.adj[c]) if (work.couldPlace(j)) todo.push(j);
      for (const j of todo) work.setLight(j, true);
      return true;
    }
    return false;
  }

  /**
   * Every square where a light would rule out a light at `i`: those that would light
   * it, plus the other free neighbours of any adjacent clue that a light at `i` would
   * complete.
   */
  private ruleOut(work: Work, i: number, out: number[]): void {
    const { L } = this;
    out.length = 0;
    for (const j of L.rays[i]) if (work.couldPlace(j)) out.push(j);
    for (const c of L.adj[i]) {
      if (L.clue[c] === NO_CLUE) continue;
      let cur = 0;
      for (const j of L.adj[c]) if (work.light[j]) cur++;
      if (cur + 1 !== L.clue[c]) continue;
      for (const j of L.adj[c]) if (j !== i && work.couldPlace(j)) out.push(j);
    }
  }

  /**
   * How many squares `ruleOut` would list for `i`, without listing them; counting stops
   * once it reaches `limit`. The discounting's hot loop on big, sparse grids.
   */
  private ruleOutCount(work: Work, i: number, limit: number): number {
    const { L } = this;
    const { black, clue, adj } = L;
    const { imposs, lit, light } = work;
    let k = 0;
    for (const j of L.rays[i]) {
      if (!black[j] && !imposs[j] && lit[j] === 0 && ++k >= limit) return k;
    }
    for (const c of adj[i]) {
      if (clue[c] === NO_CLUE) continue;
      let cur = 0;
      for (const j of adj[c]) if (light[j]) cur++;
      if (cur + 1 !== clue[c]) continue;
      for (const j of adj[c]) {
        if (j !== i && !black[j] && !imposs[j] && lit[j] === 0 && ++k >= limit) return k;
      }
    }
    return k;
  }

  /** Whether the squares `ruleOut` would list for `d` include all `size` marked ones. */
  private coversMarked(work: Work, d: number, size: number): boolean {
    const { L, mark, tmp } = this;
    const { black, clue, adj } = L;
    const { imposs, lit, light } = work;
    tmp.length = 0;
    const hit = (j: number) => {
      if (mark[j] === 1 && !black[j] && !imposs[j] && lit[j] === 0) {
        mark[j] = 2;
        tmp.push(j);
      }
    };
    for (const j of L.rays[d]) hit(j);
    for (const c of adj[d]) {
      if (clue[c] === NO_CLUE) continue;
      let cur = 0;
      for (const j of adj[c]) if (light[j]) cur++;
      if (cur + 1 !== clue[c]) continue;
      for (const j of adj[c]) if (j !== d) hit(j);
    }
    for (const j of tmp) mark[j] = 1;
    return tmp.length === size;
  }

  /**
   * `set` is a list of squares of which at least one must be a light. Any square whose
   * light would rule out every member of the set can be marked impossible. Only the
   * squares that rule out the set's most constrained member need checking.
   */
  private discountSet(work: Work, set: number[]): boolean {
    if (set.length === 0) return false;
    const { cands, mark } = this;
    let best = -1;
    let bestN = Infinity;
    for (const s of set) {
      const k = this.ruleOutCount(work, s, bestN);
      if (k < bestN) {
        bestN = k;
        best = s;
        if (k === 0) return false; // nothing can rule that member out
      }
    }
    this.ruleOut(work, best, cands);
    // Mark the set once; a candidate covers it when the squares it rules out hit every
    // mark. (The same test as listing each candidate's squares, without the listing.)
    let size = 0;
    for (const s of set) {
      if (mark[s] === 0) {
        mark[s] = 1;
        size++;
      }
    }
    let did = false;
    for (const d of cands) {
      if (work.imposs[d]) continue;
      if (this.coversMarked(work, d, size)) {
        work.imposs[d] = 1;
        did = true;
      }
    }
    for (const s of set) mark[s] = 0;
    return did;
  }

  /** The squares that could light unlit square `i` form a set. */
  private discountUnlit(work: Work, i: number): boolean {
    const set = this.set;
    set.length = 0;
    if (work.couldPlace(i)) set.push(i);
    for (const j of this.L.rays[i]) if (work.couldPlace(j)) set.push(j);
    return this.discountSet(work, set);
  }

  /** A clue needing m of its n free neighbours: every (n − m + 1)-subset is a set. */
  private discountClue(work: Work, c: number): boolean {
    const { L } = this;
    let need = L.clue[c];
    if (need <= 0) return false;
    const empty: number[] = [];
    for (const j of L.adj[c]) {
      if (work.light[j]) need--;
      else if (work.couldPlace(j)) empty.push(j);
    }
    const n = empty.length;
    if (n === 0 || need <= 0 || need > n) return false;
    const r = n - need + 1;
    let did = false;
    for (let m = 1; m < 1 << n; m++) {
      let bits = 0;
      for (let b = m; b; b &= b - 1) bits++;
      if (bits !== r) continue;
      const set = this.set;
      set.length = 0;
      for (let k = 0; k < n; k++) if (m & (1 << k)) set.push(empty[k]);
      if (this.discountSet(work, set)) did = true;
    }
    return did;
  }
}

/**
 * Solve `work` in place as far as the given flags allow. On success (`nsol` > 0) the
 * work holds a solution — for a non-unique puzzle, one of them.
 */
export function solve(work: Work, flags: number, maxRecurse = MAX_RECURSE): SolveOutcome {
  work.used.fill(0);
  const solver = new Solver(work.L, flags, flags & SOLVE_RECURSE ? maxRecurse : 0);
  const nsol = solver.solveSub(work, 0);
  return { nsol, maxDepth: solver.maxDepth };
}

/** Solve a layout from scratch with the flags of a difficulty level. */
export function solveFresh(L: Layout, difficulty: number): SolveOutcome & { work: Work } {
  const work = new Work(L);
  return { ...solve(work, solveFlags(difficulty)), work };
}

/**
 * Is this a good puzzle at the given difficulty: exactly one solution, found without
 * exceeding the depth that difficulty allows?
 */
export function puzzleIsGood(L: Layout, difficulty: number): { good: boolean; work: Work } {
  const r = solveFresh(L, difficulty);
  return { good: r.nsol === 1, work: r.work };
}
