import { Drawing } from './drawing';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  isMouseDown,
  isMouseDrag,
  isMouseRelease,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  MOD_CTRL,
  KEY_BACKSPACE,
  KEY_ENTER,
  KEY_SPACE,
  stripMods,
} from './input';
import { Random, newSeedString } from './rng';
import type { DrawState, Game, GameStatus, Preset } from './types';
import { tx } from '../i18n';

export type MoveType = 'new' | 'move' | 'solve' | 'restart' | 'hint';

/**
 * What {@link Midend.hint} did. `failed` means the game threw: its message has already
 * gone out through {@link MidendCallbacks.onError}, so the caller has nothing to say.
 */
export type HintResult = 'applied' | 'none' | 'failed';

/**
 * What an interaction actually did to the board, as opposed to what the player asked for.
 * Reported to {@link MidendCallbacks.onMove} for the shell to give feedback on (a sound,
 * say); the midend neither knows nor cares what is made of it.
 *
 * Only real changes are reported: a click the game ignored, a keystroke it did not
 * understand and a move that left the state untouched are all simply absent — `processKey`
 * already says as much by returning false.
 */
export type MoveEffect = MoveType | 'undo' | 'redo';

interface Entry<S> {
  state: S;
  move: string;
  type: MoveType;
  /**
   * A hint the player paid for some other way, so it does not count against
   * {@link Midend.HINT_ALLOWANCE}. Positional like everything else in the history: undo it
   * and it stops counting, redo it and it counts again.
   */
  free?: boolean;
}

export interface MidendCallbacks {
  /** Status bar text changed. */
  onStatus?: (text: string) => void;
  /** Anything the toolbar cares about changed (undo/redo availability, game id, status). */
  onChange?: () => void;
  /** The board really moved, and in which way. See {@link MoveEffect}. */
  onMove?: (effect: MoveEffect) => void;
  /** A user-facing error (bad game ID, solve failure). */
  onError?: (message: string) => void;
}

export interface SaveData {
  version: 1;
  game: string;
  params: string;
  curParams: string;
  desc: string;
  seed: string | null;
  aux?: string;
  /** `f` marks a hint that was paid for separately; absent on every ordinary step. */
  moves: { m: string; t: MoveType; f?: 1 }[];
  pos: number;
  ui?: string;
  elapsed: number;
  /** Set once this puzzle's answer has been revealed (see {@link Midend.forfeited}). */
  forfeit?: 1;
}

type GenMode = 'random' | 'seed' | 'desc';

const SAVE_VERSION = 1;

/**
 * The midend: everything between a game's pure logic and the page. It owns the state
 * stack (undo/redo), parameters, game IDs, animation and flash timing, the elapsed-time
 * timer and drawing. It knows nothing about DOM widgets other than the canvas.
 */
export class Midend<P = any, S = any, U = any, DS extends DrawState = DrawState> {
  readonly game: Game<P, S, U, DS>;
  drawing: Drawing | null = null;
  private callbacks: MidendCallbacks;

  /** Parameters used for the next random game. */
  params: P;
  /** Parameters of the game currently being played. */
  curParams: P;
  desc = '';
  seedStr: string | null = null;
  aux: string | undefined;
  private genMode: GenMode = 'random';
  /** See {@link forfeited}. */
  private forfeit = false;

  private states: Entry<S>[] = [];
  private pos = 0;
  ui!: U;
  ds!: DS;

  private oldState: S | null = null;
  private animTime = 0;
  private animPos = 0;
  private dir = 0;
  private flashTime = 0;
  private flashPos = 0;
  private elapsed = 0;
  /** Set while the shell's pause menu is up: the clock stands still, animations do not. */
  private paused = false;
  private lastStatus = '';
  private shownStatus: string | null = null;
  private pressedButton = 0;
  private frameHandle: number | null = null;
  private lastFrame = 0;
  tileSize: number;
  /** Test hook: when false, animations and flashes complete instantly. */
  animate = true;

  constructor(game: Game<P, S, U, DS>, drawing: Drawing | null, callbacks: MidendCallbacks = {}) {
    this.game = game;
    this.callbacks = callbacks;
    this.params = game.defaultParams();
    this.curParams = this.params;
    this.tileSize = game.preferredTileSize;
    this.setDrawing(drawing);
  }

  setDrawing(drawing: Drawing | null): void {
    this.drawing = drawing;
    if (drawing) drawing.onStatus = (t) => this.setStatus(t);
  }

  // ----------------------------------------------------------------- lifecycle

  /** Start a new game from the pending description/seed, or a fresh random one. */
  newGame(): void {
    this.stopAnim();
    if (this.genMode === 'desc') {
      // desc and curParams were set by loadGameId()
    } else {
      // Committed only once generation succeeds: a generator that throws must leave the
      // puzzle on screen with the id (and size) it really has.
      const fresh = this.genMode !== 'seed';
      // A type that came in with an old link or save may be one the game now refuses to
      // generate (a size that froze the tab); deal the default rather than hang on it.
      if (fresh && this.game.validateParams(this.params, true) !== null)
        this.params = this.game.defaultParams();
      const seed = fresh ? newSeedString() : this.seedStr!;
      const params = fresh ? structuredClone(this.params) : this.curParams;
      const nd = this.game.newDesc(params, new Random(seed), true);
      this.seedStr = seed;
      this.curParams = params;
      this.desc = nd.desc;
      this.aux = nd.aux;
    }
    this.genMode = 'random';
    this.forfeit = false;
    const state = this.game.newGame(this.curParams, this.desc);
    this.states = [{ state, move: this.desc, type: 'new' }];
    this.pos = 1;
    this.ui = this.game.newUI(state);
    this.ds = this.makeDrawState(state);
    this.oldState = null;
    this.animTime = this.animPos = this.flashTime = this.flashPos = 0;
    this.dir = 0;
    this.elapsed = 0;
    this.lastStatus = '';
    this.pressedButton = 0;
    this.redraw();
    this.setTimer();
    this.moved('new');
    this.changed();
  }

  private makeDrawState(state: S): DS {
    const extra = this.game.newDrawState?.(state, this.curParams) ?? {};
    return { ...(extra as object), tileSize: this.tileSize } as DS;
  }

  destroy(): void {
    this.stopFrames();
  }

  // ------------------------------------------------------------------ accessors

  get state(): S {
    return this.states[this.pos - 1].state;
  }
  get initialState(): S {
    return this.states[0].state;
  }
  get hasGame(): boolean {
    return this.pos > 0;
  }
  /** Every state from the deal to the current one, undone branches left out. */
  history(): S[] {
    return this.states.slice(0, this.pos).map((e) => e.state);
  }
  /**
   * Moves on the current line since the last Restart (or since the deal): what a status
   * line counting "Moves" shows, and what a "in N moves or fewer" badge should judge. The
   * restart itself and the attempt it threw away do not count, just as undone moves don't.
   */
  movesSinceRestart(): number {
    return this.pos - 1 - this.lastRestart();
  }
  /**
   * The current line from the last Restart on (the restart's own state, a copy of the
   * deal, first): the attempt a "without X" or "in N moves" badge should judge.
   */
  historySinceRestart(): S[] {
    return this.states.slice(this.lastRestart(), this.pos).map((e) => e.state);
  }
  private lastRestart(): number {
    let from = 0;
    for (let i = 1; i < this.pos; i++) if (this.states[i].type === 'restart') from = i;
    return from;
  }
  canUndo(): boolean {
    return this.pos > 1;
  }
  canRedo(): boolean {
    return this.pos < this.states.length;
  }
  status(): GameStatus {
    if (this.pos === 0) return 1;
    return this.game.status(this.state);
  }
  moveCount(): number {
    return this.pos - 1;
  }
  /**
   * How many hints a puzzle may take and still count as solved by the player. A nudge or
   * two is what keeps a stuck player playing, so it must not wipe out the reward; hinting
   * a whole grid out of the game must not be a way to mint credits either, and no board
   * in the collection falls to this few hints.
   */
  static HINT_ALLOWANCE = 3;

  /**
   * True once this puzzle's answer has been shown — by Solve, or by more chargeable hints
   * than the allowance — however the history has moved since. Undoing the Solve step and
   * then copying the answer back in by hand is still not solving it; neither is taking a
   * grid's worth of hints, undoing them and replaying them. Cleared only by a new puzzle.
   */
  get forfeited(): boolean {
    return this.forfeit;
  }

  /** True when the board on show was reached through a Solve step (not merely forfeited). */
  solveUsed(): boolean {
    for (let i = 1; i < this.pos; i++) if (this.states[i].type === 'solve') return true;
    return false;
  }

  /** Hint steps in the history up to the current position, paid for or not. */
  hintsUsed(): number {
    let n = 0;
    for (let i = 1; i < this.pos; i++) if (this.states[i].type === 'hint') n++;
    return n;
  }

  /**
   * Hint steps that count against {@link Midend.HINT_ALLOWANCE} — i.e. every one the
   * player did not pay for separately. This, not {@link hintsUsed}, is what decides
   * whether the puzzle still earns its credit.
   */
  chargeableHints(): number {
    let n = 0;
    for (let i = 1; i < this.pos; i++) {
      const e = this.states[i];
      if (e.type === 'hint' && !e.free) n++;
    }
    return n;
  }

  /**
   * True when the current state is solved, no Solve step is part of the history, and no
   * more than {@link Midend.HINT_ALLOWANCE} *chargeable* hints were taken along the way.
   */
  solvedByPlayer(): boolean {
    if (this.pos === 0 || this.status() !== 1 || this.forfeit) return false;
    for (let i = 1; i < this.pos; i++) {
      if (this.states[i].type === 'solve') return false;
    }
    return this.chargeableHints() <= Midend.HINT_ALLOWANCE;
  }
  get presets(): Preset<P>[] {
    return this.game.presets;
  }
  /**
   * Index of the preset matching the puzzle being played (falling back to the pending
   * parameters when no game is loaded), or -1 for custom.
   */
  whichPreset(): number {
    const match = (params: P, loose: boolean) => {
      const full = this.game.encodeParams(params, true);
      let i = this.game.presets.findIndex((p) => this.game.encodeParams(p.params, true) === full);
      if (i < 0 && loose) {
        const short = this.game.encodeParams(params, false);
        i = this.game.presets.findIndex((p) => this.game.encodeParams(p.params, false) === short);
      }
      return i;
    };
    // Only a puzzle loaded from a description (no seed) has lost the settings the short
    // form leaves out, so only it matches a preset on size alone. A custom 10×10 Hard is
    // not the 10×10 Easy preset.
    if (this.pos > 0) return match(this.curParams, this.seedStr === null && !this.fullDescParams);
    return match(this.params, true);
  }
  setParams(p: P): void {
    this.params = p;
  }
  textFormat(): string | null {
    return this.game.textFormat ? this.game.textFormat(this.state) : null;
  }
  isTimed(): boolean {
    return this.game.isTimed;
  }
  elapsedSeconds(): number {
    return this.elapsed;
  }
  /** Stop or restart a timed game's clock. Moves still work; only the clock is held. */
  setPaused(paused: boolean): void {
    if (this.paused === paused) return;
    this.paused = paused;
    this.setTimer();
  }

  /** Descriptive game ID: `params:desc`. */
  gameId(): string {
    return `${this.game.encodeParams(this.curParams, false)}:${this.desc}`;
  }
  /**
   * The descriptive ID to share: {@link gameId}, or the game's `settledDesc` once play has
   * pinned the puzzle down further. Only for handing out — progress and saves stay keyed on
   * `gameId`, which never changes during a game.
   */
  shareGameId(): string {
    // Full parameters, unlike `gameId`: the description fixes the board, but New should go
    // on dealing the recipient the same kind (Flip's Random, Light Up's Hard), and the
    // Type menu should name it.
    const settled = this.game.settledDesc?.(this.state) ?? null;
    return `${this.game.encodeParams(this.curParams, true)}:${settled ?? this.desc}`;
  }
  /** Whether play has pinned the puzzle down past its seed (see `shareGameId`). */
  settledPastSeed(): boolean {
    return !!this.game.settledDesc?.(this.state);
  }
  /** Random-seed game ID: `params#seed`, or null if this game came from a description. */
  seedId(): string | null {
    if (!this.seedStr) return null;
    return `${this.game.encodeParams(this.curParams, true)}#${this.seedStr}`;
  }

  /**
   * Whether the last {@link loadGameId} failure was the game turning down well-formed
   * parameters (a size out of range, say). That message is the game's own, translated and
   * worth showing; a malformed code or description only yields parser detail.
   */
  paramsRejected = false;
  /** The loaded description came with full parameters, so nothing was lost to match loosely. */
  private fullDescParams = false;

  /**
   * Parse a game ID (`params:desc`, `params#seed` or bare `params`) and arrange for the
   * next `newGame()` to use it. Returns an error message or null.
   */
  loadGameId(id: string): string | null {
    this.paramsRejected = false;
    id = id.trim();
    const colon = id.indexOf(':');
    const hash = id.indexOf('#');
    let parStr: string;
    let desc: string | null = null;
    let seed: string | null = null;
    if (colon >= 0 && (hash < 0 || colon < hash)) {
      parStr = id.slice(0, colon);
      desc = id.slice(colon + 1);
    } else if (hash >= 0) {
      parStr = id.slice(0, hash);
      seed = id.slice(hash + 1);
    } else {
      parStr = id;
    }
    let newParams: P;
    if (parStr === '' && desc !== null) {
      newParams = this.curParams;
    } else if (parStr === '') {
      return tx`Game ID must include parameters`;
    } else {
      try {
        newParams = this.game.decodeParams(parStr);
      } catch (e) {
        return tx`Invalid parameters: ${(e as Error).message}`;
      }
      const err = this.game.validateParams(newParams, desc === null);
      this.paramsRejected = !!err;
      if (err) return err;
    }
    if (desc !== null) {
      const err = this.game.validateDesc(newParams, desc);
      if (err) return err;
      // The loaded puzzle's type becomes the one New deals next, as in the reference
      // midend — otherwise the Type menu shows "3×3" while New hands out a 4×4. A
      // description only carries the short parameters, so settings it cannot express (a
      // difficulty, say) are kept whenever the short forms already agree.
      // A share link carries the full parameters, and then they are taken as they are.
      let full = parStr === this.game.encodeParams(newParams, true);
      // What the short parameters could not say, the description may (`paramsFromDesc`).
      if (!full && parStr !== '' && this.game.paramsFromDesc) {
        let refined: P | null;
        try {
          refined = this.game.paramsFromDesc(newParams, desc);
        } catch {
          refined = null;
        }
        if (refined) {
          newParams = refined;
          full = true;
        }
      }
      this.fullDescParams = full;
      if (
        parStr !== '' &&
        (full ||
          this.game.encodeParams(this.params, false) !== this.game.encodeParams(newParams, false))
      ) {
        this.params = structuredClone(newParams);
      }
      this.curParams = newParams;
      this.desc = desc;
      this.seedStr = null;
      this.aux = undefined;
      this.genMode = 'desc';
    } else if (seed !== null) {
      if (!seed) return tx`Random seed must not be empty`;
      this.params = structuredClone(newParams);
      this.curParams = newParams;
      this.seedStr = seed;
      this.genMode = 'seed';
    } else {
      this.params = newParams;
      this.curParams = newParams;
      this.genMode = 'random';
    }
    return null;
  }

  // -------------------------------------------------------------------- moves

  /** Feed a mouse/keyboard event. Returns true if it was consumed. */
  processKey(x: number, y: number, button: number): boolean {
    if (this.pos === 0) return false;
    // Harmonise drags/releases with the button that is actually held.
    if (isMouseDrag(button) || isMouseRelease(button)) {
      if (this.pressedButton) {
        button = isMouseDrag(button)
          ? this.pressedButton + (LEFT_DRAG - LEFT_BUTTON)
          : this.pressedButton + (LEFT_RELEASE - LEFT_BUTTON);
      } else {
        return true; // stray drag/release: ignore
      }
    } else if (isMouseDown(button) && this.pressedButton) {
      const beats = this.game.flags?.buttonBeats ?? [];
      if (beats.some(([held, pressed]) => held === this.pressedButton && pressed === button)) {
        return true; // held button wins; ignore the new press
      }
      // Fabricate a release for the previously pressed button.
      this.reallyProcessKey(x, y, this.pressedButton + (LEFT_RELEASE - LEFT_BUTTON));
    }
    if (button === KEY_ENTER || button === 10) button = CURSOR_SELECT;
    if (button === KEY_SPACE) button = CURSOR_SELECT2;
    if (button === 127) button = KEY_BACKSPACE;

    const ret = this.reallyProcessKey(x, y, button);

    if (isMouseRelease(button)) this.pressedButton = 0;
    else if (isMouseDown(button)) this.pressedButton = button;
    return ret;
  }

  private reallyProcessKey(x: number, y: number, button: number): boolean {
    const oldState = this.state;
    const movestr = this.game.interpretMove(oldState, this.ui, this.ds, x, y, button);
    let type: MoveType = 'move';
    let gotType = false;
    let effect: MoveEffect = 'move';
    if (movestr === null || movestr === undefined) {
      // Global shortcuts.
      const c = stripMods(button);
      const ch = c < 0x100 ? String.fromCharCode(c) : '';
      const ctrl = (button & MOD_CTRL) !== 0;
      if (ch === 'n' || ch === 'N' || c === 0x0e) {
        this.newGame();
        return true;
      } else if (ch === 'u' || ch === 'U' || c === 0x1a || c === 0x1f || (ctrl && ch === 'z')) {
        this.stopAnim();
        type = this.states[this.pos - 1].type;
        gotType = true;
        if (!this.undoInternal()) return true;
        effect = 'undo';
      } else if (ch === 'r' || ch === 'R' || c === 0x12 || c === 0x19 || (ctrl && ch === 'y')) {
        this.stopAnim();
        if (!this.redoInternal()) return true;
        effect = 'redo';
      } else if (c === 0x13 && this.game.canSolve) {
        this.solve();
        return true;
      } else {
        return false;
      }
    } else if (movestr === '') {
      this.redraw();
      this.setTimer();
      this.changed();
      return true;
    } else {
      const s = this.game.executeMove(oldState, movestr);
      if (s === null || s === undefined) return true;
      if (s === oldState) {
        this.redraw();
        this.setTimer();
        return true;
      }
      this.stopAnim();
      this.states.length = this.pos;
      this.states.push({ state: s, move: movestr, type: 'move' });
      this.pos++;
      this.dir = +1;
      // A loss that shows the answer (Guess's code, Black Box's balls) gives the puzzle away
      // as surely as Solve: undoing it and typing the answer in is no win to credit.
      if (this.revealedByLoss(s)) this.forfeit = true;
      this.game.changedState?.(this.ui, oldState, s);
    }
    if (!gotType) type = this.states[this.pos - 1].type;
    let animTime = 0;
    const special = type === 'solve' || type === 'restart';
    if (!(special && !(type === 'solve' && this.game.flags?.solveAnimates))) {
      animTime = this.game.animLength(oldState, this.state, this.dir, this.ui);
    }
    if (!this.animate) animTime = 0;
    this.oldState = oldState;
    if (animTime > 0) {
      this.animTime = animTime;
    } else {
      this.animTime = 0;
      this.finishMove();
    }
    this.animPos = 0;
    this.redraw();
    this.setTimer();
    this.moved(effect);
    this.changed();
    return true;
  }

  private undoInternal(): boolean {
    if (this.pos <= 1) return false;
    const oldState = this.state;
    this.pos--;
    this.dir = -1;
    this.game.changedState?.(this.ui, oldState, this.state);
    return true;
  }

  private redoInternal(): boolean {
    if (this.pos >= this.states.length) return false;
    const oldState = this.state;
    this.pos++;
    this.dir = +1;
    this.game.changedState?.(this.ui, oldState, this.state);
    return true;
  }

  undo(): void {
    this.processKey(0, 0, 'u'.charCodeAt(0));
  }
  redo(): void {
    this.processKey(0, 0, 'r'.charCodeAt(0));
  }

  /**
   * Walk the history to position `pos` (what {@link moveCount} reported there) in one go,
   * undoing or redoing as many moves as it takes, and animate it as a single undo or redo.
   * The tutorial uses it to put back a move it did not ask for. False when `pos` is not on
   * the history (or is where the board already is).
   */
  travelTo(pos: number): boolean {
    const target = pos + 1;
    if (target < 1 || target > this.states.length || target === this.pos) return false;
    this.stopAnim();
    const oldState = this.state;
    const dir = target < this.pos ? -1 : 1;
    while (this.pos !== target) {
      if (dir < 0) this.undoInternal();
      else this.redoInternal();
    }
    this.dir = dir;
    let animTime = this.animate ? this.game.animLength(oldState, this.state, dir, this.ui) : 0;
    if (!(animTime > 0)) animTime = 0;
    this.oldState = oldState;
    this.animPos = 0;
    if (animTime > 0) this.animTime = animTime;
    else {
      this.animTime = 0;
      this.finishMove();
    }
    this.redraw();
    this.setTimer();
    this.moved(dir < 0 ? 'undo' : 'redo');
    this.changed();
    return true;
  }

  restart(): void {
    if (this.pos <= 1) return;
    this.stopAnim();
    const s = this.game.newGame(this.curParams, this.desc);
    const oldState = this.state;
    this.states.length = this.pos;
    this.states.push({ state: s, move: this.desc, type: 'restart' });
    this.pos++;
    this.game.changedState?.(this.ui, oldState, s);
    this.animTime = 0;
    this.finishMove();
    this.redraw();
    this.setTimer();
    this.moved('restart');
    this.changed();
  }

  /** Solve the puzzle, appending the solved state as an undoable move. */
  solve(): string | null {
    if (!this.game.canSolve || !this.game.solve) {
      return this.fail(tx`This game does not support the Solve operation`);
    }
    if (this.pos < 1) return this.fail(tx`No game set up to solve`);
    // A board already won stays the player's: a Solve on top of it would only take the
    // win (and its credit) away.
    if (this.status() === 1) return this.fail(tx`Already solved`);
    let movestr: string;
    try {
      movestr = this.game.solve(this.initialState, this.state, this.aux);
    } catch (e) {
      return this.fail((e as Error).message || tx`Solve operation failed`);
    }
    const oldState = this.state;
    const s = this.game.executeMove(oldState, movestr);
    if (!s) return this.fail(tx`Solve operation produced an invalid move`);
    this.stopAnim();
    this.states.length = this.pos;
    this.states.push({ state: s, move: movestr, type: 'solve' });
    this.pos++;
    this.forfeit = true;
    this.game.changedState?.(this.ui, oldState, s);
    this.dir = +1;
    if (this.game.flags?.solveAnimates && this.animate) {
      this.oldState = oldState;
      this.animTime = this.game.animLength(oldState, s, +1, this.ui);
      this.animPos = 0;
      if (this.animTime <= 0) this.finishMove();
    } else {
      this.animTime = 0;
      this.finishMove();
    }
    this.redraw();
    this.setTimer();
    this.moved('solve');
    this.changed();
    return null;
  }

  /**
   * Reveal one step of the solution, for a game that offers {@link Game.hint}. Unlike
   * Solve it leaves the puzzle in play: the step goes on the stack as an ordinary,
   * undoable move of its own type, so the player finishes the board themselves — and
   * still earns the credit while they stay inside {@link Midend.HINT_ALLOWANCE}.
   */
  /**
   * @param free when true the step does not count against {@link Midend.HINT_ALLOWANCE};
   * for a hint the player obtained some other way. The board is otherwise identical — a
   * paid-for hint is still an ordinary undoable move.
   */
  hint(free = false): HintResult {
    if (!this.game.hint || this.pos < 1) return 'none';
    let movestr: string | null;
    try {
      movestr = this.game.hint(this.initialState, this.state, this.aux, this.ui);
    } catch (e) {
      const msg = (e as Error).message;
      if (msg) this.fail(msg);
      return 'failed';
    }
    if (!movestr) return 'none';
    const oldState = this.state;
    const s = this.game.executeMove(oldState, movestr);
    // A hint that changes nothing is a bug in the game, not something to tell the player
    // about: report it the same way as having nothing to give.
    if (!s || s === oldState) return 'none';
    this.stopAnim();
    this.states.length = this.pos;
    this.states.push({ state: s, move: movestr, type: 'hint', free: free || undefined });
    this.pos++;
    if (this.chargeableHints() > Midend.HINT_ALLOWANCE) this.forfeit = true;
    this.game.changedState?.(this.ui, oldState, s);
    this.dir = +1;
    this.animTime = 0;
    this.finishMove();
    this.redraw();
    this.setTimer();
    this.moved('hint');
    this.changed();
    return 'applied';
  }

  private fail(msg: string): string {
    this.callbacks.onError?.(msg);
    return msg;
  }

  // ---------------------------------------------------------- anim/flash/timer

  private finishMove(): void {
    const special = (t: MoveType) => t === 'solve' || t === 'restart';
    if (
      (this.oldState || this.pos > 1) &&
      ((this.dir > 0 && !special(this.states[this.pos - 1].type)) ||
        (this.dir < 0 && this.pos < this.states.length && !special(this.states[this.pos].type)))
    ) {
      const from = this.oldState ?? this.states[this.pos - 2].state;
      let flash = this.game.flashLength(from, this.state, this.oldState ? this.dir : +1, this.ui);
      if (!this.animate) flash = 0;
      // A move that asks for no flash also ends one still running from an earlier move
      // (a hint's highlight), which would otherwise play on over a board it no longer fits.
      this.flashPos = 0;
      this.flashTime = flash > 0 ? flash : 0;
    }
    this.oldState = null;
    this.animPos = this.animTime = 0;
    this.dir = 0;
    this.setTimer();
  }

  stopAnim(): void {
    if (this.oldState || this.animTime !== 0) {
      this.finishMove();
      this.redraw();
    }
  }

  private wantsTimer(): boolean {
    return this.animTime > 0 || this.flashTime > 0 || this.timing();
  }

  private timing(): boolean {
    if (!this.game.isTimed || this.pos === 0 || this.paused) return false;
    return this.game.timingState ? this.game.timingState(this.state, this.ui) : this.status() === 0;
  }

  private setTimer(): void {
    if (this.wantsTimer()) this.startFrames();
    else this.stopFrames();
  }

  private startFrames(): void {
    if (this.frameHandle !== null || typeof requestAnimationFrame === 'undefined') return;
    this.lastFrame = performance.now();
    const tick = (now: number) => {
      this.frameHandle = null;
      const dt = Math.min(0.25, Math.max(0, (now - this.lastFrame) / 1000));
      this.lastFrame = now;
      this.timerTick(dt);
      if (this.wantsTimer()) this.frameHandle = requestAnimationFrame(tick);
    };
    this.frameHandle = requestAnimationFrame(tick);
  }

  private stopFrames(): void {
    if (this.frameHandle !== null && typeof cancelAnimationFrame !== 'undefined') {
      cancelAnimationFrame(this.frameHandle);
    }
    this.frameHandle = null;
  }

  private revealedByLoss(s: S): boolean {
    return !!this.game.flags?.lossRevealsAnswer && this.game.status(s) === -1;
  }

  /** Seconds left of the move animation now playing (0 when none is). */
  animRemaining(): number {
    return this.oldState && this.animTime > 0 ? Math.max(0, this.animTime - this.animPos) : 0;
  }

  /** Advance animations by `dt` seconds. Public so tests can drive it. */
  timerTick(dt: number): void {
    const needRedraw = this.animTime > 0 || this.flashTime > 0;
    this.animPos += dt;
    if (this.animPos >= this.animTime || this.animTime === 0 || !this.oldState) {
      if (this.animTime > 0) this.finishMove();
    }
    this.flashPos += dt;
    if (this.flashPos >= this.flashTime || this.flashTime === 0) {
      this.flashPos = this.flashTime = 0;
    }
    if (needRedraw) this.redraw();
    if (this.timing()) {
      const before = Math.floor(this.elapsed);
      this.elapsed += dt;
      if (before !== Math.floor(this.elapsed)) this.pushStatus();
    }
  }

  // ------------------------------------------------------------------ drawing

  /**
   * Pick a tile size so the puzzle fits in `availW` × `availH` CSS pixels and resize the
   * canvas. At `zoom` 1 the board grows to fill that box, stopping at the tile ceiling
   * (see `tileCeiling`). Zooming out shrinks the board to that fraction of the box;
   * zooming in lifts both the ceiling and the box, so a grid whose squares are smaller
   * than a fingertip can be enlarged past the screen. The caller is then responsible for
   * letting the player reach the edges — `gameView` turns the stage into a scroller and
   * pans it with two fingers.
   */
  fit(availW: number, availH: number, zoom = 1): { w: number; h: number } {
    const cap = Math.max(4, Math.round(this.tileCeiling() * zoom));
    const maxW = availW * zoom;
    const maxH = availH * zoom;
    const fits = (ts: number) => {
      const s = this.game.computeSize(this.curParams, ts);
      return s.w <= maxW && s.h <= maxH;
    };
    let lo = 2;
    let hi = cap;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (fits(mid)) lo = mid;
      else hi = mid - 1;
    }
    return this.setTileSize(lo);
  }

  /**
   * Largest tile `fit()` will hand out at zoom 1: MAX_GROW × the size the game was drawn
   * for, and never more than MAX_TILE pixels, so a coarse 3×3 board keeps a playable
   * shape on a big screen instead of becoming a handful of slabs.
   */
  tileCeiling(): number {
    return Math.min(this.game.preferredTileSize * Midend.MAX_GROW, Midend.MAX_TILE);
  }

  /** How far beyond the preferred tile size the board may grow to fill the screen. */
  static MAX_GROW = 3;
  /** Absolute ceiling on a tile, whatever the game's preferred size. */
  static MAX_TILE = 140;

  setTileSize(t: number): { w: number; h: number } {
    this.tileSize = t;
    if (this.ds) this.ds.tileSize = t;
    const size = this.game.computeSize(this.curParams, t);
    this.drawing?.resize(size.w, size.h);
    this.redraw();
    return size;
  }

  redraw(): void {
    if (!this.drawing || this.pos === 0) return;
    this.drawing.begin();
    if (this.animTime > 0 && this.animPos < this.animTime && this.oldState) {
      this.game.redraw(
        this.drawing,
        this.ds,
        this.oldState,
        this.state,
        this.dir,
        this.ui,
        this.animPos,
        this.flashPos,
      );
    } else {
      this.game.redraw(this.drawing, this.ds, null, this.state, +1, this.ui, 0, this.flashPos);
    }
    this.drawing.end();
  }

  private setStatus(text: string): void {
    this.lastStatus = text;
    this.pushStatus();
  }

  private pushStatus(): void {
    let text = this.lastStatus;
    if (this.game.isTimed) {
      const total = Math.floor(this.elapsed);
      const h = Math.floor(total / 3600);
      const m = Math.floor((total % 3600) / 60);
      const s = total % 60;
      const stamp =
        h > 0
          ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
          : `${m}:${String(s).padStart(2, '0')}`;
      text = text ? `${stamp} · ${text}` : stamp;
    }
    if (text !== this.shownStatus) {
      this.shownStatus = text;
      this.callbacks.onStatus?.(text);
    }
  }

  private changed(): void {
    this.callbacks.onChange?.();
  }

  private moved(effect: MoveEffect): void {
    this.callbacks.onMove?.(effect);
  }

  // ---------------------------------------------------------------- save/load

  serialize(): SaveData {
    return {
      version: SAVE_VERSION,
      game: this.game.id,
      params: this.game.encodeParams(this.params, true),
      curParams: this.game.encodeParams(this.curParams, true),
      desc: this.desc,
      seed: this.seedStr,
      aux: this.aux,
      moves: this.states
        .slice(1)
        .map((e) => (e.free ? { m: e.move, t: e.type, f: 1 as const } : { m: e.move, t: e.type })),
      pos: this.pos,
      ui: this.game.encodeUI ? this.game.encodeUI(this.ui) : undefined,
      elapsed: this.elapsed,
      ...(this.forfeit ? { forfeit: 1 as const } : {}),
    };
  }

  /** Restore a saved game. Returns an error message or null. */
  deserialize(data: SaveData): string | null {
    if (!data || data.version !== SAVE_VERSION || data.game !== this.game.id) {
      return 'Save data is for a different game or version';
    }
    let params: P;
    let curParams: P;
    try {
      params = this.game.decodeParams(data.params);
      curParams = this.game.decodeParams(data.curParams);
    } catch (e) {
      return `Bad parameters: ${(e as Error).message}`;
    }
    const err = this.game.validateDesc(curParams, data.desc);
    if (err) return err;
    const first = this.game.newGame(curParams, data.desc);
    const states: Entry<S>[] = [{ state: first, move: data.desc, type: 'new' }];
    for (const mv of data.moves) {
      const prev = states[states.length - 1].state;
      let next: S | null;
      if (mv.t === 'restart') next = this.game.newGame(curParams, data.desc);
      else next = this.game.executeMove(prev, mv.m);
      if (!next) return 'Saved move history is invalid';
      states.push({ state: next, move: mv.m, type: mv.t, free: mv.f ? true : undefined });
    }
    if (data.pos < 1 || data.pos > states.length) return 'Saved position is invalid';
    this.stopAnim();
    this.params = params;
    this.curParams = curParams;
    this.desc = data.desc;
    this.seedStr = data.seed;
    this.aux = data.aux;
    this.genMode = 'random';
    this.states = states;
    this.forfeit =
      !!data.forfeit ||
      states.some((e) => e.type === 'solve') ||
      states.filter((e) => e.type === 'hint' && !e.free).length > Midend.HINT_ALLOWANCE ||
      states.some((e) => this.revealedByLoss(e.state));
    this.pos = data.pos;
    this.ui = this.game.newUI(this.state);
    if (data.ui && this.game.decodeUI) this.game.decodeUI(this.ui, data.ui);
    this.ds = this.makeDrawState(this.state);
    this.oldState = null;
    this.animTime = this.animPos = this.flashTime = this.flashPos = 0;
    this.dir = 0;
    this.elapsed = data.elapsed || 0;
    this.lastStatus = '';
    this.redraw();
    this.setTimer();
    this.changed();
    return null;
  }
}
