import type { ConfigItem } from '../framework/types';
import { gsap, popIn } from './anim';
import { t } from '../i18n';
import { isSmallScreen, isTouch } from './device';
import { pushLayer } from './backLayer';

export interface ModalHandle {
  root: HTMLElement;
  body: HTMLElement;
  close: () => void;
}

/** Every modal on screen, each with the way to cancel it. See {@link cancelAllModals}. */
const openModals = new Set<() => void>();

/**
 * Cancel every open modal, as Escape would. The router calls this before it swaps pages:
 * a dialog belongs to the page that opened it, and one left behind by the browser's Back
 * button went on dimming — and swallowing every click on — the page that replaced it.
 */
export function cancelAllModals(): void {
  for (const cancel of [...openModals]) cancel();
}

/** A fresh id, for tying a field to the text that labels it. */
let idSeq = 0;
function uid(prefix: string): string {
  return `${prefix}-${++idSeq}`;
}

/**
 * Name `field` after `label` for a screen reader. The dialogs set their labels as plain
 * text above a row of controls, which a sighted player reads as one; without this a
 * screen reader met only "edit text" and a code it had no reason to understand.
 */
function labelBy(field: HTMLElement, label: HTMLElement): void {
  label.id ||= uid('label');
  field.setAttribute('aria-labelledby', label.id);
}

/**
 * The line a form's complaint is written into, announced as it appears: a rejected size or
 * code otherwise only changed pixels under the field.
 */
function formError(): HTMLDivElement {
  const err = document.createElement('div');
  err.className = 'form-error';
  err.setAttribute('role', 'alert');
  return err;
}

const FOCUSABLE =
  'button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex]:not([tabindex="-1"])';

/**
 * Keep Tab inside an `aria-modal` panel. Without it the second Tab past the last button
 * walked out of the dialog into the toolbar behind the dimmer, where the player could
 * press New on a board they could not see.
 */
function trapTab(panel: HTMLElement, e: KeyboardEvent): void {
  const items = [...panel.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
    (el) => !el.closest('[hidden]') && el.getClientRects().length > 0,
  );
  if (!items.length) {
    e.preventDefault();
    return;
  }
  const first = items[0];
  const last = items[items.length - 1];
  const active = document.activeElement;
  const inside = active instanceof Node && panel.contains(active);
  if (e.shiftKey && (active === first || !inside)) {
    e.preventDefault();
    last.focus();
  } else if (!e.shiftKey && (active === last || !inside)) {
    e.preventDefault();
    first.focus();
  }
}

/**
 * Open a modal panel. Escape or clicking the dimmer closes it (calls onCancel), and so does
 * the phone's Back. `closeButton` puts a Close button beside the title, for a dialog with
 * no Cancel of its own: on a phone the dimmer is a strip above a bottom sheet and there is
 * no Escape key, so without one the way out was a guess.
 */
export function openModal(
  title: string,
  onCancel?: () => void,
  { closeButton = false }: { closeButton?: boolean } = {},
): ModalHandle {
  const dimmer = document.createElement('div');
  dimmer.className = 'dimmer';
  const panel = document.createElement('div');
  panel.className = 'modal sketch';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'true');
  const h = document.createElement('h2');
  h.textContent = title;
  labelBy(panel, h);
  const body = document.createElement('div');
  body.className = 'modal-body';
  let closeBtn: HTMLButtonElement | null = null;
  if (closeButton) {
    const head = document.createElement('div');
    head.className = 'modal-head';
    closeBtn = button(t('ui.drawer.close'), 'modal-close');
    head.append(h, closeBtn);
    panel.append(head, body);
  } else {
    panel.append(h, body);
  }
  dimmer.append(panel);
  document.body.append(dimmer);
  // A notice raised before the dialog (the first-visit tip) was about the page behind it,
  // and on a phone it would sit over the sheet's buttons. Ones the dialog raises still show.
  hideToast();
  if (isSmallScreen()) {
    // Bottom sheet: slide it up rather than popping it in with a tilt.
    gsap.fromTo(
      panel,
      { yPercent: 12, opacity: 0 },
      { yPercent: 0, opacity: 1, duration: 0.28, ease: 'power3.out', clearProps: 'transform' },
    );
  } else {
    popIn(panel, 0.9);
  }

  // Where the player was, so closing puts them back there rather than at the top of the
  // document — a keyboard player who opened Share from the toolbar lands on Share again.
  const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const close = () => {
    releaseBack();
    openModals.delete(cancel);
    document.removeEventListener('keydown', onKey);
    const hadFocus = dimmer.contains(document.activeElement);
    dimmer.remove();
    if (hadFocus && opener?.isConnected) opener.focus({ preventScroll: true });
  };
  const cancel = () => {
    close();
    onCancel?.();
  };
  openModals.add(cancel);
  // The phone's Back closes the dialog (as Escape does) instead of leaving the page.
  const releaseBack = pushLayer(cancel);
  const onKey = (e: KeyboardEvent) => {
    // Only the dialog on top has the keys: Settings opened from the pause menu is closed
    // by Esc without taking the pause menu with it, and Tab stays in the one in front.
    if ([...openModals].pop() !== cancel) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      cancel();
    } else if (e.key === 'Tab') {
      trapTab(panel, e);
    }
  };
  document.addEventListener('keydown', onKey);
  closeBtn?.addEventListener('click', cancel);
  dimmer.addEventListener('pointerdown', (e) => {
    if (e.target === dimmer) cancel();
  });
  panel.addEventListener('pointerdown', (e) => e.stopPropagation());
  return { root: dimmer, body, close };
}

/**
 * Stop the phone from "helping" with a field that is not prose. iOS capitalises the first
 * letter of a text input, autocorrects words as they are typed and underlines what it
 * disagrees with; a game ID is case-sensitive and full of punctuation, and it is the one
 * field a player is most likely to paste in from a friend's message, so every one of
 * those quietly corrupts it. `autocomplete="off"` keeps the browser from offering saved
 * values out of unrelated forms for a field that means nothing outside this puzzle.
 *
 * All four are inert with a mouse, so the desktop dialogs behave exactly as before.
 */
function plainTextInput(input: HTMLInputElement): void {
  input.autocomplete = 'off';
  input.autocapitalize = 'off';
  input.spellcheck = false;
  // Not in the HTML standard, but it is the attribute Safari actually reads.
  input.setAttribute('autocorrect', 'off');
}

/** Just the string row of `ConfigItem` — the only one that gets a text field. */
type StringConfigItem = Extract<ConfigItem, { type: 'string' }>;

/** Digits only: `9`, `30`. */
const INTEGER_VALUE = /^\d+$/;
/** Digits around a single decimal point: `0.5`, `.5`, `10.` — what `%g` prints. */
const DECIMAL_VALUE = /^(?:\d+\.\d*|\.\d+)$/;

/**
 * The `inputmode` for a custom-parameter field, or `undefined` to leave the full keyboard
 * alone. `inputmode` rather than `type="number"`: a number input brings its own spinners
 * and validation, which would fight the hand-drawn styling and the plain `parseInt` every
 * game's `customParams` runs over these values as strings.
 *
 * Nearly every custom parameter is a number — a width, a mine count, a block size — so
 * rather than ask all 38 games to say so, the framework reads the value it was handed. A
 * field only gets the digits-only pad when its value is digits only: iOS puts neither a
 * minus sign nor a separator on that pad, so a range like Black Box's `3-6`, a negative,
 * or anything wordy keeps the full keyboard and stays typeable. A game overrides the
 * guess with `keyboard` where the value on show does not reveal what the field accepts.
 */
export function configInputMode(item: StringConfigItem): 'numeric' | 'decimal' | undefined {
  if (item.keyboard) return item.keyboard === 'text' ? undefined : item.keyboard;
  const value = item.value.trim();
  if (INTEGER_VALUE.test(value)) return 'numeric';
  if (DECIMAL_VALUE.test(value)) return 'decimal';
  return undefined;
}

function button(label: string, cls = ''): HTMLButtonElement {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = `btn ${cls}`.trim();
  b.textContent = label;
  return b;
}

/** What the player chose when a hint was about to cost them the puzzle's credit. */
export type HintChoice = 'ad' | 'anyway' | null;

/**
 * Offer to trade a short ad for the credit this hint would otherwise cost.
 *
 * Only shown when an ad could actually play, and only at the moment the next hint crosses
 * {@link Midend.HINT_ALLOWANCE}; the hint itself stays available either way, so cancelling
 * or declining leaves the player exactly where they were. Resolves `'ad'`, `'anyway'`, or
 * null if they backed out.
 */
export function rewardedHintDialog(allowance: number): Promise<HintChoice> {
  return new Promise((resolve) => {
    let answered = false;
    const settle = (choice: HintChoice) => {
      if (answered) return;
      answered = true;
      resolve(choice);
    };
    const modal = openModal(t('ui.dialog.hintAd.title'), () => settle(null));

    const body = document.createElement('p');
    body.className = 'id-label';
    body.textContent = t('ui.dialog.hintAd.body', { n: allowance });

    const actions = document.createElement('div');
    actions.className = 'modal-actions';
    const anyway = button(t('ui.dialog.hintAd.anyway'));
    anyway.addEventListener('click', () => {
      modal.close();
      settle('anyway');
    });
    const watch = button(t('ui.dialog.hintAd.watch'), 'primary');
    watch.addEventListener('click', () => {
      modal.close();
      settle('ad');
    });
    actions.append(anyway, watch);
    modal.body.append(body, actions);
    watch.focus();
  });
}

/**
 * Show the custom-parameters form. Resolves with the edited items, or null on cancel.
 * `validate` may return an error message to keep the dialog open.
 */
export function configDialog(
  title: string,
  items: ConfigItem[],
  validate: (items: ConfigItem[]) => string | null,
): Promise<ConfigItem[] | null> {
  return new Promise((resolve) => {
    const modal = openModal(title, () => resolve(null));
    const form = document.createElement('form');
    form.className = 'config-form';
    const controls: (() => void)[] = [];
    items.forEach((item, i) => {
      const row = document.createElement('label');
      row.className = 'config-row';
      const name = document.createElement('span');
      name.textContent = item.name;
      row.append(name);
      if (item.type === 'string') {
        const input = document.createElement('input');
        input.type = 'text';
        input.value = item.value;
        plainTextInput(input);
        // A number pad beats making the player hunt for the digits on a QWERTY layout.
        const mode = configInputMode(item);
        if (mode) input.inputMode = mode;
        input.className = 'sketch-input';
        // Autofocus would throw up the on-screen keyboard over the sheet on a phone.
        if (i === 0 && !isTouch()) setTimeout(() => input.select(), 0);
        row.append(input);
        controls.push(() => (item.value = input.value));
      } else if (item.type === 'choices') {
        const select = document.createElement('select');
        select.className = 'sketch-input';
        item.choices.forEach((c, idx) => {
          const opt = document.createElement('option');
          opt.value = String(idx);
          opt.textContent = c;
          opt.selected = idx === item.selected;
          select.append(opt);
        });
        row.append(select);
        controls.push(() => (item.selected = Number(select.value)));
      } else {
        const cb = document.createElement('input');
        cb.type = 'checkbox';
        cb.checked = item.value;
        row.classList.add('config-check');
        row.prepend(cb);
        controls.push(() => (item.value = cb.checked));
      }
      form.append(row);
    });
    const err = formError();
    const actions = document.createElement('div');
    actions.className = 'modal-actions';
    const ok = button(t('ui.dialog.ok'), 'primary');
    ok.type = 'submit';
    const cancel = button(t('ui.dialog.cancel'));
    cancel.addEventListener('click', () => {
      modal.close();
      resolve(null);
    });
    actions.append(cancel, ok);
    form.append(err, actions);
    // Once the player edits a field the old complaint no longer describes what is there.
    form.addEventListener('input', () => (err.textContent = ''));
    form.addEventListener('change', () => (err.textContent = ''));
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      controls.forEach((fn) => fn());
      const message = validate(items);
      if (message) {
        err.textContent = message;
        return;
      }
      modal.close();
      resolve(items);
    });
    modal.body.append(form);
  });
}

/**
 * Put `text` on the clipboard, and say whether it actually got there.
 *
 * Two attempts, because the first one is the one that fails on the platform the game ships
 * to. Inside a cross-origin iframe the Clipboard API is off unless the embedding page hands
 * the permission down (`allow="clipboard-write"`), and CrazyGames' frame does not, so
 * `writeText()` rejects with a permissions-policy error for every player there. Safari adds
 * its own version of the same disappointment: the share link has to be fetched from the SDK
 * first, and an `await` before the write loses the user gesture the write needs.
 *
 * `execCommand('copy')` is deprecated everywhere and works everywhere, in particular inside
 * that iframe — no permission, no promise, no gesture to lose. So it is the fallback, and
 * the caller only has to handle the case where both have failed.
 */
export async function copyToClipboard(text: string): Promise<boolean> {
  // Inside a frame that does not delegate `clipboard-write` (CrazyGames' does not) the call
  // is certain to fail, and Chrome reports every attempt as a permissions-policy violation
  // in the console. Ask the policy first where the browser can say.
  if (clipboardWriteAllowed()) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      /* blocked by permissions policy, insecure context, or a lapsed user gesture */
    }
  }
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.readOnly = true;
  // Off screen but not `display:none`/`hidden`: the selection has to be real for the copy
  // to be, and iOS scrolls to a focused field that has a position on the page.
  ta.style.cssText =
    'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;padding:0;border:0';
  document.body.append(ta);
  try {
    ta.focus({ preventScroll: true });
    ta.select();
    ta.setSelectionRange(0, text.length);
    return document.execCommand('copy');
  } catch {
    return false;
  } finally {
    ta.remove();
  }
}

/**
 * Whether the page's permissions policy lets it write to the clipboard. `true` wherever
 * the browser has no policy API to ask (Safari, Firefox): there the attempt is simply made.
 */
export function clipboardWriteAllowed(): boolean {
  try {
    if (typeof navigator === 'undefined' || !navigator.clipboard?.writeText) return false;
    const doc = document as Document & {
      permissionsPolicy?: { allowsFeature(f: string): boolean };
      featurePolicy?: { allowsFeature(f: string): boolean };
    };
    const policy = doc.permissionsPolicy ?? doc.featurePolicy;
    return typeof policy?.allowsFeature === 'function'
      ? policy.allowsFeature('clipboard-write')
      : true;
  } catch {
    return true;
  }
}

export interface GameIdDialogOptions {
  descId: string;
  seedId: string | null;
  /** A link that opens this exact puzzle. May have to ask the platform for it. */
  shareUrl: (id: string) => string | Promise<string>;
  /** Try to load; return an error message or null on success. */
  load: (id: string) => string | null;
}

/**
 * Share, and the enthusiast's way in behind it.
 *
 * The dialog leads with the one thing almost everyone opening it wants — a link to this
 * puzzle — rather than with two near-identical opaque strings and four buttons. The codes
 * themselves are still here, under a heading that says what they are: they are how a
 * puzzle is quoted in a forum post, and the only way to hand someone a specific board.
 */
export function gameIdDialog(opts: GameIdDialogOptions): void {
  const modal = openModal(t('ui.dialog.gameIdTitle'), undefined, { closeButton: true });
  const body = modal.body;

  // ---- the share link, first and on its own
  const lead = document.createElement('p');
  lead.className = 'id-lead';
  lead.textContent = t('ui.dialog.shareLead');
  const linkBtn = button(t('ui.dialog.copyLink'), 'primary');
  linkBtn.title = t('ui.dialog.linkTitle');
  /**
   * Where the link goes when it cannot be copied for the player — a field they can select
   * themselves, in the dialog they are already looking at. It replaces a native `prompt()`,
   * which was the wrong answer twice over: browsers ignore one called from a cross-origin
   * iframe, which is exactly where the copy fails, and a system box over a hand-drawn game
   * is not how this collection talks to anyone.
   */
  const linkFallback = document.createElement('div');
  linkFallback.className = 'id-section';
  linkFallback.hidden = true;
  const linkFallbackLabel = document.createElement('div');
  linkFallbackLabel.className = 'id-label';
  linkFallbackLabel.textContent = t('ui.dialog.linkPrompt');
  const linkField = document.createElement('input');
  linkField.className = 'sketch-input';
  linkField.readOnly = true;
  plainTextInput(linkField);
  labelBy(linkField, linkFallbackLabel);
  linkField.addEventListener('focus', () => selectLink());
  // The same row wrapper the code fields use, which is what makes it span the dialog
  // instead of shrinking to its content.
  const linkFieldRow = document.createElement('div');
  linkFieldRow.className = 'id-row';
  linkFieldRow.append(linkField);
  linkFallback.append(linkFallbackLabel, linkFieldRow);

  /**
   * Select the whole link, anchored at the *end* so the field scrolls back to show where
   * the link starts. Selecting forwards leaves the caret past the last character, and a
   * player is shown the tail of a percent-encoded puzzle id rather than a recognisable URL.
   */
  const selectLink = () => {
    try {
      linkField.setSelectionRange(0, linkField.value.length, 'backward');
    } catch {
      linkField.select();
    }
    linkField.scrollLeft = 0;
  };

  linkBtn.addEventListener('click', async () => {
    // On the platform this is the invite link, which is the only address a player can
    // actually be sent to; everywhere else it is our own URL. Either way it is resolved
    // on the press rather than up front, so opening the dialog never waits on the SDK.
    const url = await opts.shareUrl(opts.descId);
    if (await copyToClipboard(url)) {
      linkFallback.hidden = true;
      linkBtn.textContent = t('ui.dialog.linkCopied');
      setTimeout(() => (linkBtn.textContent = t('ui.dialog.copyLink')), 1400);
      return;
    }
    linkField.value = url;
    linkFallback.hidden = false;
    linkField.focus();
    selectLink();
  });
  const linkRow = document.createElement('div');
  linkRow.className = 'id-row id-share';
  linkRow.append(linkBtn);
  body.append(lead, linkRow, linkFallback);

  // ---- the codes
  const section = (label: string, value: string) => {
    const wrap = document.createElement('div');
    wrap.className = 'id-section';
    const l = document.createElement('div');
    l.className = 'id-label';
    l.textContent = label;
    const row = document.createElement('div');
    row.className = 'id-row';
    const input = document.createElement('input');
    input.readOnly = true;
    input.value = value;
    // Read-only, but a spell-checker still draws its red squiggle under an ID.
    plainTextInput(input);
    input.className = 'sketch-input mono';
    input.addEventListener('focus', () => input.select());
    labelBy(input, l);
    const copy = button(t('ui.dialog.copy'));
    // Two "Copy" buttons in a row: each says which code it copies.
    copy.setAttribute('aria-describedby', l.id);
    copy.addEventListener('click', async () => {
      if (await copyToClipboard(value)) {
        copy.textContent = t('ui.dialog.copied');
        setTimeout(() => (copy.textContent = t('ui.dialog.copy')), 1200);
        return;
      }
      // The code is on screen either way, so failing back to "here it is, selected" costs
      // the player one keystroke rather than the string.
      input.focus();
      input.select();
    });
    row.append(input, copy);
    wrap.append(l, row);
    return wrap;
  };

  const codes = document.createElement('div');
  codes.className = 'id-codes';
  const codesLabel = document.createElement('h3');
  codesLabel.className = 'id-heading';
  codesLabel.textContent = t('ui.dialog.codes');
  codes.append(codesLabel, section(t('ui.dialog.byDescription'), opts.descId));
  if (opts.seedId) codes.append(section(t('ui.dialog.bySeed'), opts.seedId));
  body.append(codes);

  const enter = document.createElement('form');
  enter.className = 'id-section';
  const l = document.createElement('div');
  l.className = 'id-label';
  l.textContent = t('ui.dialog.enterLabel');
  const row = document.createElement('div');
  row.className = 'id-row';
  const input = document.createElement('input');
  input.className = 'sketch-input mono';
  input.placeholder = opts.seedId ?? opts.descId;
  plainTextInput(input);
  labelBy(input, l);
  const go = button(t('ui.dialog.play'), 'primary');
  go.type = 'submit';
  row.append(input, go);
  const err = formError();
  enter.append(l, row, err);
  input.addEventListener('input', () => (err.textContent = ''));
  enter.addEventListener('submit', (e) => {
    e.preventDefault();
    const message = opts.load(input.value);
    if (message) {
      err.textContent = message;
    } else {
      modal.close();
    }
  });
  body.append(enter);
  // On the lead action, not on the paste field at the foot of the dialog: the link is what
  // nearly everyone opened Share for, and a lit-up empty field reads as a question.
  if (!isTouch()) setTimeout(() => linkBtn.focus(), 0);
}

let toastTimer: number | null = null;

/**
 * How far above the bottom of the viewport the foot of the play page reaches: the status
 * line and, under it, the on-screen keypad. `.toast` floats clear of that, because a
 * notice is never worth hiding the game's own status text behind — least of all the
 * "COMPLETED" line at the moment the puzzle is solved. A docked tutorial sheet needs no
 * separate measurement: the play page already reserves `--tut-dock` at its foot, so the
 * status line — and with it the toast — sits above the sheet.
 *
 * Only what genuinely sits at the foot counts. On a landscape phone the keypad stands
 * beside the board as a full-height rail, and measuring from its top would report the
 * whole viewport as foot and throw the notice off the screen — so a node is read as foot
 * only when it begins below the halfway line, which a bottom band does and a rail does not.
 */
function footHeight(): number {
  if (typeof document === 'undefined') return 0;
  let foot = 0;
  const midline = window.innerHeight / 2;
  for (const sel of ['.status-row', '.keypad']) {
    const node = document.querySelector<HTMLElement>(sel);
    if (!node) continue;
    const box = node.getBoundingClientRect();
    // A hidden row measures zero and must not be read as "the foot is the whole page".
    if (box.height > 0 && box.top >= midline) foot = Math.max(foot, window.innerHeight - box.top);
  }
  // An upright phone sets the board down on the status line with the spare desk above it
  // (play.css), so a notice lifted over the foot alone lands on the board's bottom rows.
  // When there is desk enough above the board, it waits there instead.
  const board = document.querySelector<HTMLElement>('.game-page .puzzle-canvas');
  const bar = document.querySelector<HTMLElement>('.game-page .toolbar');
  if (board && bar && foot > 0) {
    const top = board.getBoundingClientRect().top;
    if (top >= midline * 0.6 && top - bar.getBoundingClientRect().bottom >= 110) {
      foot = Math.max(foot, window.innerHeight - top);
    }
  }
  return Math.round(foot);
}

/** Non-blocking notice at the bottom of the page. */
/** Take down the notice showing now, if any (something has covered the page it was about). */
export function hideToast(): void {
  const el = document.querySelector<HTMLElement>('.toast');
  if (!el) return;
  gsap.killTweensOf(el);
  gsap.set(el, { opacity: 0 });
}

export function toast(message: string, kind: 'info' | 'error' | 'success' = 'info'): void {
  let el = document.querySelector<HTMLElement>('.toast');
  if (!el) {
    el = document.createElement('div');
    el.className = 'toast';
    // Spoken as well as shown: "Link copied", a rejected code, the tutorial's farewell.
    el.setAttribute('role', 'status');
    el.setAttribute('aria-live', 'polite');
    el.setAttribute('aria-atomic', 'true');
    document.body.append(el);
  }
  el.textContent = message;
  el.dataset.kind = kind;
  el.style.setProperty('--toast-lift', `${footHeight()}px`);
  gsap.killTweensOf(el);
  gsap.fromTo(
    el,
    { opacity: 0, y: 24, xPercent: -50 },
    { opacity: 1, y: 0, xPercent: -50, duration: 0.3, ease: 'back.out(1.8)' },
  );
  if (toastTimer) clearTimeout(toastTimer);
  // Long enough to read at a glance, short enough to be gone by the next move; an error
  // is worth an extra beat because it asks the player to do something differently.
  toastTimer = window.setTimeout(
    () => gsap.to(el!, { opacity: 0, y: 16, xPercent: -50, duration: 0.25, ease: 'power2.in' }),
    kind === 'error' ? 2800 : 2200,
  );
}
