export interface GuessParams {
  /** Colours the solution is drawn from, 2..10. */
  ncolours: number;
  /** Pegs per row. */
  npegs: number;
  /** Rows available before the game is lost. */
  nguesses: number;
  /** A guess may leave slots empty. */
  allowBlank: boolean;
  /** The solution (and guesses) may repeat a colour. */
  allowMultiple: boolean;
}

/** A marked guess. */
export interface MarkedGuess {
  /** Colour of each peg, 1-based; 0 is a blank. */
  pegs: number[];
  /** Pegs of the right colour in the right place. */
  place: number;
  /** Further pegs of a right colour but in the wrong place. */
  colour: number;
}

export interface GuessState {
  params: GuessParams;
  solution: number[];
  /** Guesses submitted so far, oldest first. */
  guesses: MarkedGuess[];
  /** Slots held over from the last guess into the next one. */
  holds: boolean[];
  /** +1 the solution is known (guessed or revealed), -1 out of guesses, 0 playing. */
  solved: -1 | 0 | 1;
  /** The solution was shown by Solve rather than guessed. */
  revealed: boolean;
}

interface Drag {
  /** Colour being dragged, 0 when the press was not on a peg. */
  col: number;
  /** Slot of the current guess the peg came from, or -1. */
  from: number;
  x: number;
  y: number;
  sx: number;
  sy: number;
  moved: boolean;
}

export interface GuessUI {
  /** The half-finished current guess; 0 is empty. */
  curr: number[];
  holds: boolean[];
  /** Selected tray colour (1-based). */
  selColour: number;
  /** Keyboard cursor: slot index, or npegs for the marking area. */
  pegCur: number;
  cursorVisible: boolean;
  /** Letter the pegs (for colour-blind players). */
  labels: boolean;
  /**
   * The Hold tool: a click on a slot of the current row holds or releases its peg, as a
   * middle-click does, instead of placing the selected colour there.
   */
  holdMode: boolean;
  drag: Drag | null;
}

/** A peg with the underline a held peg gets on the board. */
const HOLD_GLYPH = glyph(
  'M6.5 20.5h11',
  '<circle cx="12" cy="10.5" r="5.5" fill="none" stroke="currentColor" stroke-width="2"/>',
);

const FLASH = 0.5;
const FLASH_FRAME = 0.13;
const DRAG_SLOP = 4;
const MAX_PEGS = 12;
const MAX_GUESSES = 30;

// ------------------------------------------------------------------ rules

/** Whether a row is complete enough (and legal enough) to be marked. */
export function isMarkable(p: GuessParams, pegs: number[]): boolean {
  let set = 0;
  const seen = new Set<number>();
  for (const c of pegs) {
    if (c <= 0) continue;
    set++;
    if (!p.allowMultiple && seen.has(c)) return false;
    seen.add(c);
  }
  return set >= (p.allowBlank ? 1 : p.npegs);
}

/**
 * Mastermind marking. `place` counts exact matches; `colour` counts the remaining
 * pegs whose colour occurs somewhere else in the solution, each solution peg being
 * matched at most once: sum over colours of min(#guess, #solution), less `place`.
 */
export function markPegs(
  guess: number[],
  solution: number[],
  ncolours: number,
): { place: number; colour: number } {
  let place = 0;
  const inGuess = new Array<number>(ncolours + 1).fill(0);
  const inSolution = new Array<number>(ncolours + 1).fill(0);
  for (let i = 0; i < solution.length; i++) {
    if (guess[i] === solution[i]) place++;
    if (guess[i] > 0 && guess[i] <= ncolours) inGuess[guess[i]]++;
    inSolution[solution[i]]++;
  }
  let both = 0;
  for (let c = 1; c <= ncolours; c++) both += Math.min(inGuess[c], inSolution[c]);
  return { place, colour: both - place };
}

// ------------------------------------------------------------------ description

/**
 * The description is the solution, but a game ID should not spell out the answer, so
 * the bytes are XORed with a keystream that depends on their position, the row length
 * and the previous *scrambled* byte. That makes it reversible with the same keystream
 * (`unscramble`) while identical colours still encode differently.
 */
function keyByte(i: number, prev: number, n: number): number {
  let h = (0x6b75d9a3 ^ Math.imul(n + 1, 0x9e3779b1)) >>> 0;
  h = Math.imul(h ^ (i + 1), 0x85ebca6b) >>> 0;
  h ^= h >>> 13;
  h = Math.imul(h ^ (prev + 1), 0xc2b2ae35) >>> 0;
  h ^= h >>> 16;
  return h & 0xff;
}

export function scramble(bytes: number[]): number[] {
  const out: number[] = [];
  let prev = 0;
  for (let i = 0; i < bytes.length; i++) {
    out.push((bytes[i] ^ keyByte(i, prev, bytes.length)) & 0xff);
    prev = out[i];
  }
  return out;
}

export function unscramble(bytes: number[]): number[] {
  const out: number[] = [];
  let prev = 0;
  for (let i = 0; i < bytes.length; i++) {
    out.push((bytes[i] ^ keyByte(i, prev, bytes.length)) & 0xff);
    prev = bytes[i];
  }
  return out;
}

/** Solution colours (1-based) → description string. */
export function encodeSolution(solution: number[]): string {
  return scramble(solution)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/** Description string → solution colours, or null if malformed. */
export function decodeSolution(desc: string, npegs: number): number[] | null {
  if (desc.length !== npegs * 2 || !/^[0-9a-fA-F]*$/.test(desc)) return null;
  const bytes: number[] = [];
  for (let i = 0; i < npegs; i++) bytes.push(parseInt(desc.slice(2 * i, 2 * i + 2), 16));
  return unscramble(bytes);
}

function encodeGuess(pegs: number[], holds: boolean[]): string {
  return 'G' + pegs.map((c, i) => `${c}${holds[i] ? '_' : ''}`).join(',');
}

// ------------------------------------------------------------------ geometry

const GAP = 0.1;
const HINT = 0.35;
const BORDER = 0.4;
const TRAY_PAD = 0.22;
const BOARD_PAD = 0.28;
const MARKER = 0.85;

export interface Geometry {
  t: number;
  gap: number;
  hint: number;
  pegOff: number;
  hintOff: number;
  hintW: number;
  trayX: number;
  trayY: number;
  trayW: number;
  trayH: number;
  colX: number;
  colY: number;
  guessX: number;
  guessY: number;
  hintX: number;
  hintBlockW: number;
  solnY: number;
  sepY: number;
  boardX: number;
  boardY: number;
  boardW: number;
  boardH: number;
  w: number;
  h: number;
}

export function geometry(t: number, p: GuessParams): Geometry {
  const gap = t * GAP;
  const hint = t * HINT;
  const border = t * BORDER;
  const pegOff = t + gap;
  const hintOff = hint + gap;
  const hintW = Math.ceil(p.npegs / 2);
  const trayPad = t * TRAY_PAD;
  const boardPad = t * BOARD_PAD;
  const trayX = border;
  const trayW = t + 2 * trayPad;
  const guessX = trayX + trayW + t * MARKER;
  const hintX = guessX + p.npegs * pegOff + gap;
  const hintBlockW = hintW * hintOff - gap;
  const boardX = guessX - boardPad;
  const boardW = hintX + hintBlockW + boardPad - boardX;
  const solnRel = boardPad;
  const guessRel = solnRel + pegOff + t * 0.3;
  const boardH = guessRel + p.nguesses * pegOff - gap + boardPad;
  const trayH = p.ncolours * pegOff - gap + 2 * trayPad;
  const h = Math.ceil(2 * border + Math.max(boardH, trayH));
  const w = Math.ceil(boardX + boardW + border);
  const boardY = (h - boardH) / 2;
  const trayY = (h - trayH) / 2;
  return {
    t,
    gap,
    hint,
    pegOff,
    hintOff,
    hintW,
    trayX,
    trayY,
    trayW,
    trayH,
    colX: trayX + trayPad,
    colY: trayY + trayPad,
    guessX,
    guessY: boardY + guessRel,
    hintX,
    hintBlockW,
    solnY: boardY + solnRel,
    sepY: boardY + solnRel + t + (t * 0.3 + gap) / 2,
    boardX,
    boardY,
    boardW,
    boardH,
    w,
    h,
  };
}

type Hit =
  | { kind: 'colour'; c: number }
  | { kind: 'slot'; i: number }
  | { kind: 'hint' }
  | { kind: 'past'; row: number; i: number };

function hitTest(g: Geometry, state: GuessState, x: number, y: number): Hit | null {
  const p = state.params;
  if (x >= g.trayX && x < g.trayX + g.trayW) {
    const c = Math.floor((y - g.colY + g.gap / 2) / g.pegOff);
    if (c >= 0 && c < p.ncolours) return { kind: 'colour', c: c + 1 };
    return null;
  }
  const row = Math.floor((y - g.guessY + g.gap / 2) / g.pegOff);
  if (row < 0 || row >= p.nguesses || x < g.guessX - g.gap / 2) return null;
  const nextRow = state.guesses.length;
  if (x < g.hintX - g.gap / 2) {
    const i = Math.floor((x - g.guessX + g.gap / 2) / g.pegOff);
    if (i < 0 || i >= p.npegs) return null;
    if (row === nextRow && !state.solved) return { kind: 'slot', i };
    if (row < nextRow) return { kind: 'past', row, i };
    return null;
  }
  if (x < g.hintX + g.hintBlockW + g.gap && row === nextRow && !state.solved)
    return { kind: 'hint' };
  return null;
}

// ------------------------------------------------------------------ helpers

function colourName(c: number): string {
  return SERIES[(c - 1) % SERIES.length];
}

/** Text colour that stays legible on peg colour `c`. */
function labelColour(c: number): string {
  const [r, g, b] = hexToRgb(PALETTE[colourName(c) as keyof typeof PALETTE]);
  return 0.299 * r + 0.587 * g + 0.114 * b < 140 ? 'paper' : 'ink';
}

function letter(c: number): string {
  return String.fromCharCode(96 + c);
}

function defaultParams(): GuessParams {
  return { ncolours: 6, npegs: 4, nguesses: 10, allowBlank: false, allowMultiple: true };
}

function makeState(params: GuessParams, solution: number[]): GuessState {
  return {
    params,
    solution,
    guesses: [],
    holds: new Array<boolean>(params.npegs).fill(false),
    solved: 0,
    revealed: false,
  };
}

// ------------------------------------------------------------------ the game

/**
 * The pause between two of the marker's pegs going down, and how long a whole verdict
 * takes. In the game this is made of, the marker holds their hand over the board and sets
 * the black and white pegs out one at a time, and that pause is the tension of the thing.
 */
const MARK_STEP = 0.075;
const MARK_POP = 0.14;

function markTime(npegs: number): number {
  return (npegs - 1) * MARK_STEP + MARK_POP;
}

/**
 * The row whose verdict has just been set out, or -1. Only ever a forward move: undoing a
 * guess takes the row off the board entirely, and there is nothing left to draw it on.
 */
function markedRow(oldState: GuessState, newState: GuessState, dir: number): number {
  if (dir < 0) return -1;
  if (newState.guesses.length !== oldState.guesses.length + 1) return -1;
  return newState.guesses.length - 1;
}

/**
 * How big the `i`th peg of a verdict is right now: nothing until its turn, then pressed
 * into the board with a little overshoot, the way a peg pushed into a hole settles back.
 */
function markScale(animTime: number, i: number): number {
  const u = clamp((animTime - i * MARK_STEP) / MARK_POP, 0, 1);
  if (u <= 0) return 0;
  const c = 1.9;
  return 1 + (c + 1) * Math.pow(u - 1, 3) + c * Math.pow(u - 1, 2);
}

const game = defineGame<GuessParams, GuessState, GuessUI>({
  id: 'guess',
  name: 'Guess',
  description: 'Work out the hidden row of coloured pegs from the marks on your guesses.',
  alsoKnownAs: 'Mastermind',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: [
    {
      name: 'Standard',
      params: { ncolours: 6, npegs: 4, nguesses: 10, allowBlank: false, allowMultiple: true },
    },
    {
      name: 'Super',
      params: { ncolours: 8, npegs: 5, nguesses: 12, allowBlank: false, allowMultiple: true },
    },
  ],
  defaultParams,
  encodeParams: (p) =>
    `c${p.ncolours}p${p.npegs}g${p.nguesses}${p.allowBlank ? 'b' : 'B'}${p.allowMultiple ? 'm' : 'M'}`,
  decodeParams(str) {
    const p = defaultParams();
    const re = /([cpg])(\d+)|([bBmM])/gy;
    let pos = 0;
    while (pos < str.length) {
      re.lastIndex = pos;
      const m = re.exec(str);
      if (!m) throw new Error(tx`expected something like c6p4g10Bm`);
      pos = re.lastIndex;
      if (m[1] === 'c') p.ncolours = parseInt(m[2], 10);
      else if (m[1] === 'p') p.npegs = parseInt(m[2], 10);
      else if (m[1] === 'g') p.nguesses = parseInt(m[2], 10);
      else if (m[3] === 'b') p.allowBlank = true;
      else if (m[3] === 'B') p.allowBlank = false;
      else if (m[3] === 'm') p.allowMultiple = true;
      else if (m[3] === 'M') p.allowMultiple = false;
    }
    return p;
  },
  validateParams(p) {
    if (![p.ncolours, p.npegs, p.nguesses].every(Number.isInteger))
      return tx`Colours, pegs and guesses must be whole numbers`;
    if (p.ncolours < 2 || p.npegs < 2) return tx`Trivial solutions are uninteresting`;
    if (p.ncolours > SERIES.length) return tx`Too many colours (at most ${SERIES.length})`;
    if (p.npegs > MAX_PEGS) return tx`Too many pegs per guess (at most ${MAX_PEGS})`;
    if (p.nguesses < 1) return tx`Must have at least one guess`;
    if (p.nguesses > MAX_GUESSES) return tx`Too many guesses (at most ${MAX_GUESSES})`;
    if (!p.allowMultiple && p.ncolours < p.npegs)
      return tx`Disallowing duplicates requires at least as many colours as pegs`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Colours', value: String(p.ncolours) },
      { type: 'string', name: 'Pegs per guess', value: String(p.npegs) },
      { type: 'string', name: 'Guesses', value: String(p.nguesses) },
      { type: 'boolean', name: 'Allow blanks', value: p.allowBlank },
      { type: 'boolean', name: 'Allow duplicates', value: p.allowMultiple },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const str = (i: number) => {
      const v = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(v) ? parseInt(v, 10) : NaN;
    };
    const bool = (i: number) => (items[i] as { value: boolean }).value;
    return {
      ncolours: str(0),
      npegs: str(1),
      nguesses: str(2),
      allowBlank: bool(3),
      allowMultiple: bool(4),
    };
  },

  newDesc(p, rng: Random) {
    const solution: number[] = [];
    const used = new Set<number>();
    for (let i = 0; i < p.npegs; i++) {
      let c: number;
      do c = rng.upto(p.ncolours) + 1;
      while (!p.allowMultiple && used.has(c));
      used.add(c);
      solution.push(c);
    }
    return { desc: encodeSolution(solution) };
  },

  validateDesc(p, desc) {
    const solution = decodeSolution(desc, p.npegs);
    if (!solution) return tx`Description must be ${p.npegs * 2} hexadecimal digits`;
    for (const c of solution) if (c < 1 || c > p.ncolours) return tx`Description is corrupted`;
    if (!p.allowMultiple && new Set(solution).size !== solution.length)
      return tx`Description repeats a colour although duplicates are disallowed`;
    return null;
  },

  newGame(p, desc) {
    return makeState(p, decodeSolution(desc, p.npegs)!);
  },

  canSolve: true,
  solve(_orig, curr) {
    if (curr.solved === 1) throw new Error(tx`Already solved`);
    if (curr.solved === -1) throw new Error(tx`The solution has already been revealed`);
    return 'S';
  },

  textFormat(s) {
    const row = (pegs: number[]) => pegs.map((c) => (c ? letter(c) : '.')).join(' ');
    const lines = [s.solved ? row(s.solution) : s.solution.map(() => '?').join(' '), ''];
    for (const g of s.guesses)
      lines.push(`${row(g.pegs)}   ${'*'.repeat(g.place)}${'o'.repeat(g.colour)}`);
    return lines.join('\n');
  },

  newUI: (s) => ({
    curr: new Array<number>(s.params.npegs).fill(0),
    holds: new Array<boolean>(s.params.npegs).fill(false),
    selColour: 1,
    pegCur: 0,
    cursorVisible: false,
    labels: false,
    holdMode: false,
    drag: null,
  }),
  changedState(ui, _old, s) {
    const last = s.guesses[s.guesses.length - 1];
    for (let i = 0; i < s.params.npegs; i++) {
      ui.holds[i] = !s.solved && s.holds[i];
      ui.curr[i] = ui.holds[i] && last ? last.pegs[i] : 0;
    }
    ui.drag = null;
    if (ui.pegCur >= s.params.npegs && !isMarkable(s.params, ui.curr))
      ui.pegCur = s.params.npegs - 1;
  },
  encodeUI: (ui) => ui.curr.map((c, i) => `${c}${ui.holds[i] ? '_' : ''}`).join(','),
  decodeUI(ui, enc) {
    const parts = enc.split(',');
    for (let i = 0; i < ui.curr.length && i < parts.length; i++) {
      const m = /^(\d+)(_?)$/.exec(parts[i]);
      if (!m) continue;
      const c = parseInt(m[1], 10);
      if (c <= SERIES.length) ui.curr[i] = c;
      ui.holds[i] = m[2] === '_';
    }
  },

  actions: [
    {
      label: 'Hold',
      key: 'K',
      hud: true,
      glyph: HOLD_GLYPH,
      pressed: (_s, ui) => ui.holdMode,
      title: 'Click a peg in your row to carry it over into the next guess (K)',
    },
    {
      label: 'Letters',
      key: 'L',
      pressed: (_s, ui) => ui.labels,
      view: true,
      title: 'Label the pegs with letters (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const ch = keyChar(button);
    if (ch === 'l' || ch === 'L') {
      ui.labels = !ui.labels;
      return '';
    }
    if (ch === 'k' || ch === 'K') {
      ui.holdMode = !ui.holdMode;
      return '';
    }
    if (state.solved) return null;
    const p = state.params;
    const g = geometry(ds.tileSize, p);
    const hit = hitTest(g, state, mx, my);

    if (b === LEFT_BUTTON) {
      ui.cursorVisible = false;
      let col = 0;
      let from = -1;
      if (hit?.kind === 'colour') col = hit.c;
      else if (hit?.kind === 'slot') {
        col = ui.curr[hit.i];
        from = hit.i;
      } else if (hit?.kind === 'past') col = state.guesses[hit.row].pegs[hit.i];
      ui.drag = { col, from, x: mx, y: my, sx: mx, sy: my, moved: false };
      return '';
    }
    if (b === LEFT_DRAG) {
      const d = ui.drag;
      if (!d) return null;
      d.x = mx;
      d.y = my;
      if (!d.moved && Math.hypot(mx - d.sx, my - d.sy) > DRAG_SLOP) d.moved = true;
      return '';
    }
    if (b === LEFT_RELEASE) {
      const d = ui.drag;
      if (!d) return null;
      ui.drag = null;
      if (d.moved) {
        if (!d.col) return '';
        if (hit?.kind === 'slot') {
          ui.curr[hit.i] = d.col;
          ui.selColour = d.col;
        } else if (d.from >= 0) {
          ui.curr[d.from] = 0; // dragged off the row: removed
        }
        return '';
      }
      // A plain click.
      if (hit?.kind === 'colour') ui.selColour = hit.c;
      else if (hit?.kind === 'slot' && ui.holdMode) ui.holds[hit.i] = !ui.holds[hit.i];
      else if (hit?.kind === 'slot') ui.curr[hit.i] = ui.selColour;
      else if (hit?.kind === 'past' && d.col) ui.selColour = d.col;
      else if (hit?.kind === 'hint' && isMarkable(p, ui.curr))
        return encodeGuess(ui.curr, ui.holds);
      return '';
    }
    if (b === RIGHT_BUTTON) {
      if (hit?.kind !== 'slot') return null;
      ui.cursorVisible = false;
      ui.curr[hit.i] = 0;
      return '';
    }
    if (b === MIDDLE_BUTTON) {
      if (hit?.kind !== 'slot') return null;
      ui.holds[hit.i] = !ui.holds[hit.i];
      return '';
    }

    if (b === CURSOR_UP || b === CURSOR_DOWN) {
      ui.cursorVisible = true;
      ui.selColour = clamp(ui.selColour + (b === CURSOR_DOWN ? 1 : -1), 1, p.ncolours);
      return '';
    }
    if (b === CURSOR_LEFT || b === CURSOR_RIGHT) {
      ui.cursorVisible = true;
      const max = p.npegs - 1 + (isMarkable(p, ui.curr) ? 1 : 0);
      ui.pegCur = clamp(ui.pegCur + (b === CURSOR_RIGHT ? 1 : -1), 0, max);
      return '';
    }
    if (isCursorSelect(b)) {
      ui.cursorVisible = true;
      if (ui.pegCur >= p.npegs) return isMarkable(p, ui.curr) ? encodeGuess(ui.curr, ui.holds) : '';
      ui.curr[ui.pegCur] = ui.selColour;
      return '';
    }
    if (b === KEY_BACKSPACE || ch === 'd' || ch === 'D') {
      ui.cursorVisible = true;
      if (ui.pegCur < p.npegs) ui.curr[ui.pegCur] = 0;
      return '';
    }
    if (ch === 'h' || ch === 'H') {
      ui.cursorVisible = true;
      if (ui.pegCur < p.npegs) ui.holds[ui.pegCur] = !ui.holds[ui.pegCur];
      return '';
    }
    return null;
  },

  executeMove(state, move) {
    if (state.solved) return null;
    const p = state.params;
    if (move === 'S') {
      return { ...state, holds: state.holds.map(() => false), solved: 1, revealed: true };
    }
    const m = /^G(\d+_?(?:,\d+_?)*)$/.exec(move);
    if (!m) return null;
    const parts = m[1].split(',');
    if (parts.length !== p.npegs) return null;
    const pegs: number[] = [];
    const holds: boolean[] = [];
    const min = p.allowBlank ? 0 : 1;
    for (const part of parts) {
      const hold = part.endsWith('_');
      const c = parseInt(hold ? part.slice(0, -1) : part, 10);
      if (c < min || c > p.ncolours) return null;
      pegs.push(c);
      holds.push(hold);
    }
    if (!isMarkable(p, pegs)) return null;
    const mark = markPegs(pegs, state.solution, p.ncolours);
    const guesses = [...state.guesses, { pegs, ...mark }];
    let solved: GuessState['solved'] = 0;
    if (mark.place === p.npegs) solved = 1;
    else if (guesses.length >= p.nguesses) solved = -1;
    return { ...state, guesses, holds, solved };
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const g = geometry(t, p);
    return { w: g.w, h: g.h };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    // The row whose verdict is still being set out, if any.
    const marked = oldState ? markedRow(oldState, state, dir) : -1;
    const p = state.params;
    const g = geometry(ds.tileSize, p);
    const { t, gap, hint, pegOff, hintOff, hintW } = g;
    const r = t * 0.42;
    const hr = hint * 0.45;
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const nextRow = state.guesses.length;

    const peg = (cx: number, cy: number, c: number, seed: number, alpha = 1) => {
      dr.circle(cx, cy, r, colourName(c), 'ink', { width: 1.6, seed, alpha });
      if (ui.labels) {
        dr.text(cx, cy, letter(c), { size: r * 1.15, colour: labelColour(c), alpha });
      }
    };
    const hole = (cx: number, cy: number, active: boolean) => {
      dr.circle(cx, cy, r * 0.8, active ? 'shade' : null, active ? 'pencil' : 'faint', {
        width: 1.2,
        seed: Math.round(cx + cy),
      });
    };
    const hintPos = (row: number, i: number) => {
      const col = i < hintW ? i : i - hintW;
      const line = i < hintW ? 0 : 1;
      const y0 = g.guessY + row * pegOff + (t - (2 * hint + gap)) / 2;
      return { x: g.hintX + col * hintOff + hint / 2, y: y0 + line * hintOff + hint / 2 };
    };

    // The tray of colours.
    dr.roundRect(g.trayX, g.trayY, g.trayW, g.trayH, t * 0.3, 'shade', 'ink', { width: 2 });
    for (let c = 1; c <= p.ncolours; c++) {
      const cx = g.colX + t / 2;
      const cy = g.colY + (c - 1) * pegOff + t / 2;
      peg(cx, cy, c, c);
      if (ui.selColour === c && !state.solved) {
        dr.circle(cx, cy, r + gap * 0.9, null, 'accent', { width: 2.6, seed: 77 });
      }
    }

    // The board.
    dr.roundRect(
      g.boardX,
      g.boardY,
      g.boardW,
      g.boardH,
      t * 0.3,
      flashing ? 'shade' : null,
      'ink',
      {
        width: 2.4,
      },
    );
    dr.line(g.boardX + gap * 2, g.sepY, g.boardX + g.boardW - gap * 2, g.sepY, 'faint', 1.2);

    // The solution row: shielded until the game ends.
    if (state.solved) {
      for (let i = 0; i < p.npegs; i++) {
        peg(g.guessX + i * pegOff + t / 2, g.solnY + t / 2, state.solution[i], 900 + i);
      }
    } else {
      const sx = g.guessX - gap;
      const sy = g.solnY - gap;
      dr.roundRect(sx, sy, p.npegs * pegOff + gap, t + 2 * gap, t * 0.25, 'shade', 'pencil', {
        width: 1.4,
      });
      for (let i = 0; i < p.npegs; i++) {
        const cx = g.guessX + i * pegOff + t / 2;
        const cy = g.solnY + t / 2;
        dr.circle(cx, cy, r * 0.8, 'paper', 'faint', { width: 1.2, seed: 800 + i });
        dr.text(cx, cy, '?', { size: t * 0.55, colour: 'pencil' });
      }
    }
    if (state.solved) {
      // Only a row the player found earns the cheer: a Solve and a board that ran out of
      // guesses both just lift the shield.
      const found = state.solved === 1 && !state.revealed;
      dr.text(g.hintX + g.hintBlockW / 2, g.solnY + t / 2, found ? tx`yes!` : tx`shown`, {
        size: t * 0.42,
        colour: flashing ? 'ok' : 'pencil',
        maxWidth: g.hintBlockW + gap,
      });
    }

    // Guess rows.
    for (let row = 0; row < p.nguesses; row++) {
      const y = g.guessY + row * pegOff;
      const cy = y + t / 2;
      if (row < nextRow) {
        const guess = state.guesses[row];
        for (let i = 0; i < p.npegs; i++) {
          const cx = g.guessX + i * pegOff + t / 2;
          if (guess.pegs[i]) peg(cx, cy, guess.pegs[i], row * 100 + i);
          else hole(cx, cy, false);
        }
        for (let i = 0; i < p.npegs; i++) {
          const { x, y: hy } = hintPos(row, i);
          // The row just marked presses its verdict in one peg at a time. In the game this
          // is made of, the marker holds their hand over the board and sets the pegs down
          // one by one, and that pause is the whole tension of the thing — a verdict that
          // appears whole gives the player five facts in a frame and no beat to read them.
          const s = row === marked ? markScale(animTime, i) : 1;
          if (s <= 0) continue;
          if (i < guess.place) dr.circle(x, hy, hr * s, 'ink', 'ink', { width: 1.4, seed: i });
          else if (i < guess.place + guess.colour)
            dr.circle(x, hy, hr * s, 'paper', 'ink', { width: 1.6, seed: i });
          else dr.circle(x, hy, hr * 0.7 * s, null, 'faint', { width: 1, seed: i });
        }
      } else if (row === nextRow && !state.solved) {
        const markable = isMarkable(p, ui.curr);
        // Current-row marker.
        const mx = g.boardX - t * 0.3;
        const s = t * 0.14;
        dr.polygon([mx - s, cy - s, mx + s * 0.9, cy, mx - s, cy + s], 'accent', null, {
          seed: row,
        });
        for (let i = 0; i < p.npegs; i++) {
          const cx = g.guessX + i * pegOff + t / 2;
          if (ui.curr[i]) peg(cx, cy, ui.curr[i], 500 + i);
          else hole(cx, cy, true);
          if (ui.holds[i]) {
            dr.line(
              cx - t * 0.3,
              y + t + gap * 0.4,
              cx + t * 0.3,
              y + t + gap * 0.4,
              'accent',
              2.2,
              {
                seed: i,
              },
            );
          }
        }
        // The marking area lights up when the row can be marked.
        const bx = g.hintX - gap;
        const by = y - gap / 2;
        const bw = g.hintBlockW + 2 * gap;
        const bh = t + gap;
        if (markable) {
          dr.roundRect(bx, by, bw, bh, t * 0.2, 'shade', 'accent', { width: 1.6, dash: [4, 3] });
        }
        for (let i = 0; i < p.npegs; i++) {
          const { x, y: hy } = hintPos(row, i);
          dr.circle(x, hy, hr * 0.7, null, markable ? 'accent' : 'pencil', { width: 1.2, seed: i });
        }
        if (ui.cursorVisible) {
          if (ui.pegCur < p.npegs) {
            const pad = gap * 0.5;
            dr.cursor(g.guessX + ui.pegCur * pegOff - pad, y - pad, t + 2 * pad, t + 2 * pad);
          } else {
            dr.cursor(bx - gap / 2, by - gap / 2, bw + gap, bh + gap);
          }
        }
      } else {
        for (let i = 0; i < p.npegs; i++) hole(g.guessX + i * pegOff + t / 2, cy, false);
        for (let i = 0; i < p.npegs; i++) {
          const { x, y: hy } = hintPos(row, i);
          dr.circle(x, hy, hr * 0.7, null, 'faint', { width: 1, seed: i });
        }
      }
    }

    // A peg in flight.
    const d = ui.drag;
    if (d && d.moved && d.col) peg(d.x, d.y, d.col, 4242, 0.9);

    const made = state.guesses.length;
    dr.statusBar(
      state.solved === 1
        ? state.revealed
          ? tr('games.guess.status.revealed')
          : tr('games.guess.status.solved', { n: made })
        : state.solved === -1
          ? tr('games.guess.status.outOfGuesses')
          : tr('games.guess.status.guessN', { n: made + 1, total: p.nguesses }),
    );
  },

  animLength(oldState, newState, dir) {
    const row = markedRow(oldState, newState, dir);
    return row < 0 ? 0 : markTime(newState.params.npegs);
  },
  flashLength(oldState, newState) {
    return !oldState.solved && newState.solved === 1 && !newState.revealed ? FLASH : 0;
  },
  status: (s) => s.solved,
  flags: { lossRevealsAnswer: true },
  wantsStatusBar: true,
  isTimed: false,
  thumbnailParams: { ncolours: 6, npegs: 4, nguesses: 6, allowBlank: false, allowMultiple: true },
});

export default game;
