/**
 * Shared vocabulary for Net: tile bit layout, rotations, neighbour lookup, the
 * connectivity ("power") and loop computations, and the game-description codec.
 *
 * A tile is a small integer. Its low four bits say which of its edges carry a wire:
 * bit 0 = right, bit 1 = up, bit 2 = left, bit 3 = down (the same layout as the hex
 * digits in a game description). Bit 4 marks a tile the player has locked.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export const R = 1;
export const U = 2;
export const L = 4;
export const D = 8;
export const LOCKED = 16;

/** Direction index → bit, going anticlockwise from right. */
export const DIR_BITS: readonly number[] = [R, U, L, D];
export const DX: readonly number[] = [1, 0, -1, 0];
export const DY: readonly number[] = [0, -1, 0, 1];

/** Index of the opposite direction. */
export function opp(k: number): number {
  return (k + 2) & 3;
}

/** Rotate the wires of a tile a quarter turn anticlockwise (R→U→L→D→R). */
export function rotA(v: number): number {
  return (v & ~15) | (((v & 7) << 1) | ((v & 8) >> 3));
}
/** Rotate the wires of a tile a quarter turn clockwise. */
export function rotC(v: number): number {
  return (v & ~15) | (((v & 14) >> 1) | ((v & 1) << 3));
}
/** Turn the wires of a tile through 180 degrees. */
export function rotF(v: number): number {
  return (v & ~15) | (((v & 12) >> 2) | ((v & 3) << 2));
}
/** Rotate anticlockwise by `n` quarter turns. */
export function rotate(v: number, n: number): number {
  switch (n & 3) {
    case 1:
      return rotA(v);
    case 2:
      return rotF(v);
    case 3:
      return rotC(v);
    default:
      return v;
  }
}

/** Number of wires leaving a tile. */
export function countWires(v: number): number {
  return (v & 1) + ((v >> 1) & 1) + ((v >> 2) & 1) + ((v >> 3) & 1);
}

/** The distinct orientations a tile shape can take, starting with `v` itself. */
export function orientations(v: number): number[] {
  const first = v & 15;
  const out = [first];
  for (let r = rotA(first); r !== first; r = rotA(r)) out.push(r);
  return out;
}

export interface Grid {
  w: number;
  h: number;
  wrapping: boolean;
}

/**
 * Index of the tile next to tile `i` in direction `k`, wrapping around the edges.
 * Non-wrapping grids rely on their border barriers (or the solver's closed edges) to
 * make the wrapped-around neighbour irrelevant, exactly like the original.
 */
export function wrapIndex(g: Grid, i: number, k: number): number {
  const x = ((((i % g.w) + DX[k]) % g.w) + g.w) % g.w;
  const y = (((Math.floor(i / g.w) + DY[k]) % g.h) + g.h) % g.h;
  return y * g.w + x;
}

/** Like `wrapIndex`, but -1 when a non-wrapping grid has no tile in that direction. */
export function neighbourIndex(g: Grid, i: number, k: number): number {
  if (!g.wrapping) {
    const x = (i % g.w) + DX[k];
    const y = Math.floor(i / g.w) + DY[k];
    if (x < 0 || y < 0 || x >= g.w || y >= g.h) return -1;
    return y * g.w + x;
  }
  return wrapIndex(g, i, k);
}

/** Whether the wire leaving tile `i` in direction `k` meets a wire coming the other way. */
export function connected(
  g: Grid,
  tiles: ArrayLike<number>,
  barriers: ArrayLike<number> | null,
  i: number,
  k: number,
): boolean {
  if (!(tiles[i] & DIR_BITS[k])) return false;
  if (barriers && barriers[i] & DIR_BITS[k]) return false;
  const j = wrapIndex(g, i, k);
  return (tiles[j] & DIR_BITS[opp(k)]) !== 0;
}

/**
 * Flood-fill from the source tile through matched, unblocked wires. The result has a
 * 1 for every tile that is "powered".
 */
export function computeActive(
  g: Grid,
  tiles: ArrayLike<number>,
  barriers: ArrayLike<number>,
  sx: number,
  sy: number,
): Uint8Array {
  const n = g.w * g.h;
  const active = new Uint8Array(n);
  const start = sy * g.w + sx;
  const queue = [start];
  active[start] = 1;
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q];
    for (let k = 0; k < 4; k++) {
      if (!connected(g, tiles, barriers, i, k)) continue;
      const j = wrapIndex(g, i, k);
      if (!active[j]) {
        active[j] = 1;
        queue.push(j);
      }
    }
  }
  return active;
}

/**
 * Find wires that lie on a closed loop. Returns, per tile, the direction bits of its
 * wires that are part of some loop.
 *
 * The method is a union-find over the two *sides* of every wire: around each tile
 * centre the sides of consecutive wires are joined, and across every matched edge each
 * side is joined to the corresponding side of the partner wire. Unmatched or missing
 * wires have their two sides joined directly. Afterwards a wire lies on a loop exactly
 * when its two sides ended up in different classes — this works even for loops that
 * go all the way round a wrapping grid.
 */
export function computeLoops(
  g: Grid,
  tiles: ArrayLike<number>,
  barriers: ArrayLike<number> | null,
): Uint8Array {
  const n = g.w * g.h;
  // Node (i, k, side): side 0 is the clockwise side of wire k, side 1 the anticlockwise.
  const node = (i: number, k: number, side: number) => i * 8 + k * 2 + side;
  const dsf = new DSF(n * 8);
  for (let i = 0; i < n; i++) {
    for (let k = 0; k < 4; k++) {
      // The wedge between wire k and the next wire anticlockwise is one region.
      dsf.merge(node(i, k, 1), node(i, (k + 1) & 3, 0));
      if (connected(g, tiles, barriers, i, k)) {
        const j = wrapIndex(g, i, k);
        const o = opp(k);
        dsf.merge(node(i, k, 0), node(j, o, 1));
        dsf.merge(node(i, k, 1), node(j, o, 0));
      } else {
        dsf.merge(node(i, k, 0), node(i, k, 1));
      }
    }
  }
  const loops = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    for (let k = 0; k < 4; k++) {
      if (tiles[i] & DIR_BITS[k] && !dsf.same(node(i, k, 0), node(i, k, 1))) {
        loops[i] |= DIR_BITS[k];
      }
    }
  }
  return loops;
}

/** Barrier bits for the outer edge of a non-wrapping grid. */
export function borderBarriers(w: number, h: number): number[] {
  const b = new Array<number>(w * h).fill(0);
  for (let x = 0; x < w; x++) {
    b[x] |= U;
    b[(h - 1) * w + x] |= D;
  }
  for (let y = 0; y < h; y++) {
    b[y * w] |= L;
    b[y * w + w - 1] |= R;
  }
  return b;
}

const HEX = '0123456789abcdef';

/** The hex-digit string for a set of tile wires (locks are dropped). */
export function tilesToHex(tiles: ArrayLike<number>): string {
  let s = '';
  for (let i = 0; i < tiles.length; i++) s += HEX[tiles[i] & 15];
  return s;
}

export function hexToTiles(hex: string): number[] {
  const out: number[] = [];
  for (const c of hex) out.push(parseInt(c, 16));
  return out;
}

/**
 * Check a game description: one hex digit per tile, each optionally followed by `v`
 * (barrier on its right) and/or `h` (barrier below it). Returns an error or null.
 */
export function validateDescription(w: number, h: number, desc: string): string | null {
  const n = w * h;
  let p = 0;
  for (let i = 0; i < n; i++) {
    if (p >= desc.length) return tx`Game description is shorter than expected`;
    if (!/[0-9a-fA-F]/.test(desc[p])) return tx`Game description contains an unexpected character`;
    p++;
    while (desc[p] === 'h' || desc[p] === 'v') p++;
  }
  if (p < desc.length) return tx`Game description is longer than expected`;
  return null;
}

export interface ParsedDescription {
  tiles: number[];
  barriers: number[];
  /** False when a nominally wrapping description has barriers all round its edge. */
  wrapping: boolean;
}

/** Decode a (valid) game description into tiles and barriers. */
export function parseDescription(
  w: number,
  h: number,
  wrapping: boolean,
  desc: string,
): ParsedDescription {
  const n = w * h;
  const g: Grid = { w, h, wrapping: true };
  const tiles = new Array<number>(n).fill(0);
  const barriers = new Array<number>(n).fill(0);
  let p = 0;
  for (let i = 0; i < n; i++) {
    tiles[i] = parseInt(desc[p++], 16);
    while (desc[p] === 'h' || desc[p] === 'v') {
      const k = desc[p] === 'v' ? 0 : 3;
      barriers[i] |= DIR_BITS[k];
      barriers[wrapIndex(g, i, k)] |= DIR_BITS[opp(k)];
      p++;
    }
  }
  if (!wrapping) {
    const border = borderBarriers(w, h);
    for (let i = 0; i < n; i++) barriers[i] |= border[i];
  } else {
    wrapping = false;
    for (let x = 0; x < w && !wrapping; x++) {
      if (!(barriers[x] & U) || !(barriers[(h - 1) * w + x] & D)) wrapping = true;
    }
    for (let y = 0; y < h && !wrapping; y++) {
      if (!(barriers[y * w] & L) || !(barriers[y * w + w - 1] & R)) wrapping = true;
    }
  }
  return { tiles, barriers, wrapping };
}

/** Encode tiles and barriers as a game description. */
export function encodeDescription(g: Grid, tiles: ArrayLike<number>, barriers: ArrayLike<number>) {
  let s = '';
  for (let y = 0; y < g.h; y++) {
    for (let x = 0; x < g.w; x++) {
      const i = y * g.w + x;
      s += HEX[tiles[i] & 15];
      if ((g.wrapping || x < g.w - 1) && barriers[i] & R) s += 'v';
      if ((g.wrapping || y < g.h - 1) && barriers[i] & D) s += 'h';
    }
  }
  return s;
}
