/**
 * The geometry behind console-style menu navigation (`src/ui/nav.ts`): given where the
 * selector is and where everything it could move to is, which one does an arrow press
 * mean? Pure functions over rectangles, so the choice can be unit-tested without a page.
 *
 * The rule is the one a game menu follows: the nearest item *in that direction*, where a
 * step sideways off the line of travel costs more than a step along it — so Right moves
 * along a row of cards rather than jumping to the one diagonally below that happens to be
 * a few pixels closer.
 */

export type NavDir = 'up' | 'down' | 'left' | 'right';

export interface NavRect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

/** How much a step off the line of travel costs, against one along it. */
const CROSS_WEIGHT = 3;
/** A nudge towards the candidate whose centre lines up best, to settle near-ties. */
const CENTRE_WEIGHT = 0.2;

interface Axes {
  /** Near and far edges of `r` along the line of travel, signed so "forward" is larger. */
  near(r: NavRect): number;
  far(r: NavRect): number;
  centre(r: NavRect): number;
  /** The span of `r` across the line of travel. */
  cross(r: NavRect): [number, number];
}

function axes(dir: NavDir): Axes {
  const horizontal = dir === 'left' || dir === 'right';
  const sign = dir === 'right' || dir === 'down' ? 1 : -1;
  if (horizontal) {
    return {
      near: (r) => (sign > 0 ? r.left : -r.right),
      far: (r) => (sign > 0 ? r.right : -r.left),
      centre: (r) => (sign * (r.left + r.right)) / 2,
      cross: (r) => [r.top, r.bottom],
    };
  }
  return {
    near: (r) => (sign > 0 ? r.top : -r.bottom),
    far: (r) => (sign > 0 ? r.bottom : -r.top),
    centre: (r) => (sign * (r.top + r.bottom)) / 2,
    cross: (r) => [r.left, r.right],
  };
}

function contains(outer: NavRect, inner: NavRect): boolean {
  return (
    outer.left <= inner.left &&
    outer.top <= inner.top &&
    outer.right >= inner.right &&
    outer.bottom >= inner.bottom
  );
}

/** The gap between two spans across the line of travel; 0 when they overlap. */
function crossGap(a: [number, number], b: [number, number]): number {
  return Math.max(0, b[0] - a[1], a[0] - b[1]);
}

/**
 * The cost of moving from `from` to `to` in `dir`, or `null` when `to` is not that way
 * at all. Lower is nearer.
 */
export function navScore(from: NavRect, to: NavRect, dir: NavDir): number | null {
  if (contains(to, from) || contains(from, to)) return null;
  const a = axes(dir);
  // Ahead: its centre past ours, and it reaches further than we do. An element that
  // merely overlaps us, or one we sit inside, is not "to the right" of us.
  if (a.centre(to) <= a.centre(from) + 1) return null;
  if (a.far(to) <= a.far(from) + 1) return null;
  const main = Math.max(0, a.near(to) - a.far(from));
  const fc = a.cross(from);
  const tc = a.cross(to);
  const gap = crossGap(fc, tc);
  const offset = Math.abs((tc[0] + tc[1]) / 2 - (fc[0] + fc[1]) / 2);
  return main + gap * CROSS_WEIGHT + offset * CENTRE_WEIGHT;
}

/** Whether two rectangles share some of the span across the line of travel of `dir`. */
export function inLine(from: NavRect, to: NavRect, dir: NavDir): boolean {
  const a = axes(dir);
  const fc = a.cross(from);
  const tc = a.cross(to);
  return Math.min(fc[1], tc[1]) - Math.max(fc[0], tc[0]) > 1;
}

/**
 * Whether `to` lies inside a cone opening from `from` in `dir`: at most `k` pixels off
 * the line of travel for every pixel along it (plus a little slack for neighbours).
 */
export function inCone(from: NavRect, to: NavRect, dir: NavDir, k: number): boolean {
  const a = axes(dir);
  const main = Math.max(0, a.near(to) - a.far(from));
  return crossGap(a.cross(from), a.cross(to)) <= main * k + 16;
}

export interface PickOptions {
  /**
   * Only candidates that share a row (or a column) with `from`: how a paged grid tells
   * "the next card along" from "the edge of the page".
   */
  sameLine?: boolean;
  /** Only candidates inside a cone this wide (see {@link inCone}). */
  cone?: number;
}

/**
 * The index of the candidate an arrow press in `dir` moves to from `from`, or -1 when
 * there is nothing that way. Ties go to the earlier candidate (document order).
 */
export function pickInDirection(
  from: NavRect,
  candidates: readonly NavRect[],
  dir: NavDir,
  { sameLine = false, cone }: PickOptions = {},
): number {
  let best = -1;
  let bestScore = Infinity;
  candidates.forEach((c, i) => {
    if (sameLine && !inLine(from, c, dir)) return;
    if (cone !== undefined && !inCone(from, c, dir, cone)) return;
    const s = navScore(from, c, dir);
    if (s !== null && s < bestScore) {
      best = i;
      bestScore = s;
    }
  });
  return best;
}

/**
 * Where the selector lands on a page just turned to: the first item met coming in from
 * the edge the page was entered by, on the row the selector left from. `bounds` is the
 * area the page's items stand in.
 */
export function entryPoint(
  from: NavRect,
  candidates: readonly NavRect[],
  dir: NavDir,
  bounds: NavRect,
): number {
  const pad = 4;
  const virtual: NavRect =
    dir === 'right'
      ? {
          left: bounds.left - pad - 1,
          right: bounds.left - pad,
          top: from.top,
          bottom: from.bottom,
        }
      : dir === 'left'
        ? {
            left: bounds.right + pad,
            right: bounds.right + pad + 1,
            top: from.top,
            bottom: from.bottom,
          }
        : dir === 'down'
          ? {
              top: bounds.top - pad - 1,
              bottom: bounds.top - pad,
              left: from.left,
              right: from.right,
            }
          : {
              top: bounds.bottom + pad,
              bottom: bounds.bottom + pad + 1,
              left: from.left,
              right: from.right,
            };
  return pickInDirection(virtual, candidates, dir);
}
