import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { ABSENT, PEG } from './index';
import type { PegsState, PegsUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** The three jumps of the tutorial board, in the only order they can be played. */
const JUMPS = [
  { sx: 2, sy: 0, tx: 2, ty: 2 },
  { sx: 3, sy: 2, tx: 1, ty: 2 },
  { sx: 0, sy: 2, tx: 2, ty: 2 },
] as const;

const pegAt = (s: PegsState, x: number, y: number) => s.grid[y * s.w + x] === PEG;

/** Bounding box of the cells that are actually part of the board. */
function boardRect(state: PegsState, tileSize: number): TutorialRect {
  let x0 = state.w;
  let y0 = state.h;
  let x1 = 0;
  let y1 = 0;
  state.grid.forEach((v, i) => {
    if (v === ABSENT) return;
    const x = i % state.w;
    const y = Math.floor(i / state.w);
    x0 = Math.min(x0, x);
    y0 = Math.min(y0, y);
    x1 = Math.max(x1, x);
    y1 = Math.max(y1, y);
  });
  return cellRect(x0, y0, tileSize, border(tileSize), x1 - x0 + 1, y1 - y0 + 1);
}

/** The three cells a jump touches: source, jumped peg and landing hole. */
function jumpRect(n: number, tileSize: number): TutorialRect {
  const j = JUMPS[n];
  const x = Math.min(j.sx, j.tx);
  const y = Math.min(j.sy, j.ty);
  const across = j.sy === j.ty;
  return cellRect(x, y, tileSize, border(tileSize), across ? 3 : 1, across ? 1 : 3);
}

export const tutorial: Tutorial<PegsState, PegsUI> = {
  steps: [
    {
      gameId: '4x3:OOPOOOPOPHHP',
      text: 'A peg jumps over a neighbour into the empty hole beyond, and the peg it jumped over is taken away. Clear this little board down to **one peg**: three jumps.',
      highlight: ({ state, tileSize }) => boardRect(state, tileSize),
    },
    {
      text: '**Drag** the peg at the top of the stalk down over its neighbour, into the hole at the bottom.',
      highlight: ({ tileSize }) => jumpRect(0, tileSize),
      pointer: ({ tileSize }) => {
        const b = border(tileSize);
        return { ...cellCentre(2, 0, tileSize, b), to: cellCentre(2, 2, tileSize, b) };
      },
      waitFor: ({ state }) => pegAt(state, 2, 2),
    },
    {
      text: 'Clicking works too. Click the **right-hand peg** to pick it up, then click the hole two squares to its left.',
      highlight: ({ tileSize }) => jumpRect(1, tileSize),
      pointer: ({ ui, tileSize }) => {
        const b = border(tileSize);
        // Once the peg is in hand, point at where it has to land.
        return ui.selX === 3 && ui.selY === 2
          ? cellCentre(1, 2, tileSize, b)
          : cellCentre(3, 2, tileSize, b);
      },
      waitFor: ({ state }) => pegAt(state, 1, 2),
    },
    {
      text: 'Last jump: drag the peg in the **bottom-left corner** over its neighbour into the middle.',
      highlight: ({ tileSize }) => jumpRect(2, tileSize),
      pointer: ({ tileSize }) => {
        const b = border(tileSize);
        return { ...cellCentre(0, 2, tileSize, b), to: cellCentre(2, 2, tileSize, b) };
      },
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'One peg left — solved. **Undo** takes a jump back when you strand yourself, and the arrow keys work too: Enter picks a peg up, then an arrow pushes it.',
      textTouch:
        'One peg left — solved. **Undo** takes a jump back whenever you strand yourself, as far back as you like.',
      target: '[data-cmd="undo"]',
    },
  ],
};
