import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { L, LOCKED, R } from './core';
import type { NetState, NetUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Wire bits of the tile at (x, y), ignoring its lock. */
function wires(state: NetState, x: number, y: number): number {
  return state.tiles[y * state.w + x] & 15;
}

/**
 * Three tiles of the fixed 3x3 puzzle point their wire at a wall. The walkthrough turns
 * the bottom-left one anticlockwise, the bottom-right one clockwise, locks the four-way
 * tile in the middle, and finishes with the top-right corner.
 */
export const tutorial: Tutorial<NetState, NetUI> = {
  steps: [
    {
      gameId: '3x3:1d21f4878',
      text: 'Every tile carries a piece of wire, and the whole net has been spun round at random. Turn the tiles until all nine hang off the tile marked in the middle: **blue** wires are already live, grey ones are not.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The bottom-left tile points its wire straight at the wall. **Left-click** it for a quarter turn anticlockwise, so the wire reaches its neighbour on the right.',
      highlight: ({ state, tileSize }) => cellRect(0, state.h - 1, tileSize, border(tileSize)),
      pointer: ({ state, tileSize }) => cellCentre(0, state.h - 1, tileSize, border(tileSize)),
      waitFor: ({ state }) => wires(state, 0, state.h - 1) === R,
    },
    {
      text: '**Right-click** turns a tile the other way. Give the bottom-right tile one clockwise turn and its wire swings round to the left.',
      highlight: ({ state, tileSize }) =>
        cellRect(state.w - 1, state.h - 1, tileSize, border(tileSize)),
      pointer: ({ state, tileSize }) => ({
        ...cellCentre(state.w - 1, state.h - 1, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => wires(state, state.w - 1, state.h - 1) === L,
    },
    {
      text: 'The middle tile has wires on all four sides, so it cannot be wrong. **Middle-click** it to lock it, or switch on the **padlock** beside Undo and click it: a locked tile is shaded and refuses to turn.',
      textTouch:
        'The middle tile has wires on all four sides, so it cannot be wrong. Switch on the **padlock** beside Undo and tap the tile to lock it: a locked tile is shaded and refuses to turn.',
      highlight: ({ ui, tileSize }) => cellRect(ui.curX, ui.curY, tileSize, border(tileSize)),
      // The padlock is lit up too: under the tutorial's dimming it read as switched off,
      // and on a phone it is the only way the step can be done.
      target: '[data-action="K"]',
      // On touch the text teaches the padlock and a plain tap, not a two-finger tap.
      pointer: ({ ui, tileSize, touch }) => ({
        ...cellCentre(ui.curX, ui.curY, tileSize, border(tileSize)),
        button: touch ? ('left' as const) : ('middle' as const),
      }),
      waitFor: ({ state }) => state.tiles.some((t) => (t & LOCKED) !== 0),
    },
    {
      text: 'One tile left over. With the **padlock** switched off, **left-click** the top-right corner to bring its wire round to the left and light up the whole net.',
      textTouch:
        'One tile left over. With the **padlock** switched off, tap the top-right corner to bring its wire round to the left and light up the whole net.',
      highlight: ({ state, tileSize }) => cellRect(state.w - 1, 0, tileSize, border(tileSize)),
      pointer: ({ state, tileSize }) => cellCentre(state.w - 1, 0, tileSize, border(tileSize)),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'All nine tiles are live. **Undo** steps back through your turns; with the keyboard, arrow keys move a cursor and **A**, **D** and **F** turn the tile under it.',
      textTouch:
        'All nine tiles are live. **Undo** steps back through your turns, locking a tile you are sure of keeps it safe from a stray tap, and **Jumble** spins every unlocked tile again.',
      target: '[data-cmd="undo"]',
    },
  ],
};
