export type LightupParams = GenParams;

export interface LightupState {
  w: number;
  h: number;
  /** The fixed puzzle: black squares, clues and precomputed rays. Shared between states. */
  layout: Layout;
  /** 1 where the player has put a light. */
  light: Uint8Array;
  /** 1 where the player has marked "no light here". */
  imposs: Uint8Array;
  /** How many lights shine on each square. */
  lit: Uint8Array;
  completed: boolean;
  usedSolve: boolean;
}

export interface LightupUI extends HintMark {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** The Cross tool: a left click pencils in or rubs out a cross instead of a bulb. */
  cross: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_SIDE = 30;
/** Recursion depth for Solve, which only needs one solution and can afford to dig. */
const SOLVE_DEPTH = 8;
const DEFAULTS: LightupParams = { w: 7, h: 7, blackpc: 20, symm: SYMM_ROT4, difficulty: 0 };

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

function makeState(layout: Layout, light: Uint8Array, imposs: Uint8Array): LightupState {
  const lit = computeLit(layout, light);
  return {
    w: layout.w,
    h: layout.h,
    layout,
    light,
    imposs,
    lit,
    completed: isCorrect(layout, light, lit),
    usedSolve: false,
  };
}

/** A solution to `state`'s puzzle as a light array, or null. */
function findSolution(state: LightupState, aux: string | undefined): Uint8Array | null {
  const L = state.layout;
  if (aux !== undefined) {
    const light = decodeLights(aux, L.n);
    if (light && isCorrect(L, light, computeLit(L, light))) return light;
  }
  const flags = SOLVE_DISCOUNT | SOLVE_RECURSE;
  // Try to continue from the player's position first, then from a clean grid.
  const work = new Work(L);
  for (let i = 0; i < L.n; i++) if (state.light[i]) work.setLight(i, true);
  work.imposs.set(state.imposs);
  if (solve(work, flags, SOLVE_DEPTH).nsol > 0) return work.light;
  const fresh = new Work(L);
  if (solve(fresh, flags, SOLVE_DEPTH).nsol > 0) return fresh.light;
  return null;
}

// ------------------------------------------------------------------ drawing bits

function drawBulb(dr: Drawing, x: number, y: number, t: number, bad: boolean, seed: number) {
  const cx = x + t / 2;
  const cy = y + t * 0.45;
  const r = t * 0.22;
  const lw = Math.max(1.4, t * 0.055);
  // Neck and base.
  const nw = t * 0.1;
  const ny = cy + r * 0.85;
  dr.polygon(
    [cx - nw, ny, cx + nw, ny, cx + nw * 0.8, ny + t * 0.13, cx - nw * 0.8, ny + t * 0.13],
    'ink',
    'ink',
    {
      seed,
      width: 1,
    },
  );
  dr.circle(cx, cy, r, bad ? 'error' : 'highlight', bad ? 'error' : 'ink', { seed, width: lw });
  // A little filament.
  dr.polyline(
    [
      cx - r * 0.35,
      cy + r * 0.15,
      cx - r * 0.15,
      cy - r * 0.25,
      cx + r * 0.15,
      cy + r * 0.15,
      cx + r * 0.35,
      cy - r * 0.25,
    ],
    bad ? 'highlight' : 'ink',
    Math.max(1, t * 0.03),
    { seed: seed + 3 },
  );
}

/**
 * Difficulty words, in the solver's own order, for the Type menu and the Custom dialog
 * alike: a player who picks "Extreme" from one and opens the other must find the same
 * word selected there. The solver's own level names (`DIFFICULTY_NAMES`) stay in the code.
 */
const PRESET_DIFFICULTIES = ['Easy', 'Medium', 'Hard'];

// ------------------------------------------------------------------ the game

/**
 * How fast light runs down a row, and how long the whole sweep takes. A lamp lights its
 * row and column out to the nearest wall, and all of it used to arrive in the same frame
 * the lamp did — which is the one thing in this puzzle that is supposed to travel.
 */
const BEAM_STEP = 0.022;
const BEAM_RISE = 0.07;

function beamStep(far: number): number {
  return Math.min(BEAM_STEP, 0.3 / Math.max(1, far));
}

function beamTime(far: number): number {
  return BEAM_RISE + far * beamStep(far);
}

/**
 * The lamp that moved and how far its light reached, taken from the boards either side of
 * the move. Returns null unless exactly one lamp changed — a Solve, a Restart, or a lamp
 * that lit nothing new, none of which has a beam to run.
 */
interface Beam {
  /** Distance from the lamp for each square the light reached, or -1. */
  dist: Int16Array;
  /** 1 where the square is lit once the sweep is over, 0 where it goes dark. */
  endsLit: Uint8Array;
  far: number;
}

function readBeam(oldState: LightupState, newState: LightupState, dir: number): Beam | null {
  const earlier = dir > 0 ? oldState : newState;
  const later = dir > 0 ? newState : oldState;
  const { w, light } = earlier;
  if (later.light.length !== light.length) return null;
  let lamp = -1;
  for (let i = 0; i < light.length; i++) {
    if (light[i] === later.light[i]) continue;
    if (lamp >= 0) return null;
    lamp = i;
  }
  if (lamp < 0) return null;
  const lx = lamp % w;
  const ly = Math.floor(lamp / w);
  const dist = new Int16Array(light.length).fill(-1);
  const endsLit = new Uint8Array(light.length);
  let far = 0;
  let any = false;
  for (let i = 0; i < light.length; i++) {
    // Only squares that actually went dark or came up: one that two lamps already shine
    // on does not flicker when a third arrives.
    if (earlier.lit[i] > 0 === later.lit[i] > 0) continue;
    const d = Math.abs((i % w) - lx) + Math.abs(Math.floor(i / w) - ly);
    dist[i] = d;
    endsLit[i] = later.lit[i] > 0 ? 1 : 0;
    any = true;
    if (d > far) far = d;
  }
  return any ? { dist, endsLit, far } : null;
}

/**
 * How lit a square is right now. The sweep always runs outward from the lamp, so a square
 * the light is leaving darkens in the same order it once lit — which is what makes taking
 * a lamp away read as the light being drawn back into it rather than simply switched off.
 */
function beamAt(beam: Beam, i: number, elapsed: number): number {
  const passed = clamp((elapsed - beam.dist[i] * beamStep(beam.far)) / BEAM_RISE, 0, 1);
  return beam.endsLit[i] ? passed : 1 - passed;
}

const game = defineGame<LightupParams, LightupState, LightupUI>({
  id: 'lightup',
  name: 'Light Up',
  description: 'Place light bulbs so every square is lit and no bulb shines on another.',
  alsoKnownAs: 'Akari',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [7, 7, SYMM_ROT4, DIFF_EASY],
      [7, 7, SYMM_ROT4, DIFF_TRICKY],
      [7, 7, SYMM_ROT4, DIFF_HARD],
      [10, 10, SYMM_ROT2, DIFF_EASY],
      [10, 10, SYMM_ROT2, DIFF_TRICKY],
      [10, 10, SYMM_ROT2, DIFF_HARD],
      [14, 14, SYMM_ROT2, DIFF_EASY],
      [14, 14, SYMM_ROT2, DIFF_TRICKY],
      [14, 14, SYMM_ROT2, DIFF_HARD],
    ] as [number, number, number, number][]
  ).map(([w, h, symm, difficulty]) => ({
    name: `${w}×${h} ${PRESET_DIFFICULTIES[difficulty]}`,
    params: { w, h, blackpc: 20, symm, difficulty },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${full ? `b${p.blackpc}s${p.symm}d${p.difficulty}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    const rest = str.slice(m[0].length);
    const num = (key: string, dflt: number) => {
      const r = new RegExp(`${key}(\\d+)`).exec(rest);
      return r ? parseInt(r[1], 10) : dflt;
    };
    // Four-way rotation is the default but only makes sense on a square grid.
    let symm = num('s', w === h ? SYMM_ROT4 : SYMM_ROT2);
    if (!/s\d/.test(rest) && symm === SYMM_ROT4 && w !== h) symm = SYMM_ROT2;
    // Very old ids spelt "hard" as `r`.
    const difficulty = num('d', rest.includes('r') ? DIFF_HARD : DIFF_EASY);
    return { w, h, blackpc: num('b', 20), symm, difficulty };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.blackpc, p.symm, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full) {
      if (p.blackpc < 5 || p.blackpc > 100)
        return tx`Percentage of black squares must be between 5% and 100%`;
      if (p.symm < 0 || p.symm >= SYMMETRY_NAMES.length) return tx`Unknown symmetry type`;
      if (p.symm === SYMM_ROT4 && p.w !== p.h)
        return tx`4-way rotational symmetry needs a square grid`;
      if (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length)
        return tx`Unknown difficulty level`;
    }
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: '% of black squares', value: String(p.blackpc) },
      { type: 'choices', name: 'Symmetry', choices: SYMMETRY_NAMES, selected: p.symm },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => (/^-?\d+$/.test(str(i)) ? parseInt(str(i), 10) : NaN);
    const sel = (i: number) => (items[i] as { selected: number }).selected;
    return {
      w: int(0),
      h: int(1),
      blackpc: /^-?\d+%?$/.test(str(2)) ? parseInt(str(2), 10) : NaN,
      symm: sel(3),
      difficulty: sel(4),
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const r = parseDesc(desc, p.w, p.h) as { black: Uint8Array; clue: Int8Array };
    const layout = new Layout(p.w, p.h, r.black, r.clue);
    const state = makeState(layout, new Uint8Array(layout.n), new Uint8Array(layout.n));
    // A fresh puzzle is never "completed", even a degenerate all-black one.
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const solution = findSolution(curr, aux);
    if (!solution) throw new Error(tx`Unable to find a solution to this puzzle`);
    const { w, layout } = curr;
    let move = 'S';
    for (let i = 0; i < layout.n; i++) {
      if (!!curr.light[i] !== !!solution[i]) move += `;L${i % w},${Math.floor(i / w)}`;
    }
    return move;
  },

  /**
   * One square. A bulb that the answer does not have comes out first, and a square marked
   * as impossible that has to hold a bulb is lit — a player is stuck for good behind
   * either. Otherwise one missing bulb goes in, preferring a square beside a numbered
   * black one so the hint lands on a clue the player can check for themselves.
   */
  hint(_orig, curr, aux, ui) {
    if (curr.completed) return null;
    const L = curr.layout;
    const empty = new Uint8Array(L.n);
    // From a clean grid, so this is the puzzle's own answer rather than a completion of
    // whatever the player has put down — the point is to tell the two apart.
    const solution = findSolution({ ...curr, light: empty, imposs: empty }, aux);
    if (!solution) throw new Error(tx`Unable to find a solution to this puzzle`);
    const light = (i: number) => markHint(ui, i, `L${i % curr.w},${Math.floor(i / curr.w)}`);

    for (let i = 0; i < L.n; i++) if (curr.light[i] && !solution[i]) return light(i);
    for (let i = 0; i < L.n; i++) if (curr.imposs[i] && solution[i]) return light(i);
    const nextTo = (i: number) => L.adj[i].some((j) => L.clue[j] !== NO_CLUE);
    for (const beside of [true, false]) {
      for (let i = 0; i < L.n; i++) {
        if (!solution[i] || curr.light[i]) continue;
        if (beside && !nextTo(i)) continue;
        return light(i);
      }
    }
    return null;
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const i = y * s.w + x;
        const c = s.layout.clue[i];
        row += s.layout.black[i]
          ? c === NO_CLUE
            ? '#'
            : String(c)
          : s.light[i]
            ? 'L'
            : s.imposs[i]
              ? 'x'
              : s.lit[i]
                ? '.'
                : ' ';
      }
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false, cross: false, ...noHint() }),

  actions: [
    {
      label: 'Cross',
      key: 'X',
      hud: true,
      glyph: CROSS_GLYPH,
      pressed: (_s, ui) => ui.cross,
      title: 'Clicks put in crosses instead of bulbs (X)',
    },
  ],
  changedState(ui, _old, next) {
    if (next.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, layout } = state;
    let cx = -1;
    let cy = -1;
    let mark = false;
    let act = false;
    // Hiding a visible cursor is itself a change worth redrawing.
    let idle: string | null = null;
    const ch = keyChar(b);
    if (ch === 'x' || ch === 'X') {
      ui.cross = !ui.cross;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      if (ui.cursorVisible) idle = '';
      ui.cursorVisible = false;
      const t = ds.tileSize;
      const bd = boardBorder(t);
      cx = Math.floor((mx - bd) / t);
      cy = Math.floor((my - bd) / t);
      mark = b === RIGHT_BUTTON || ui.cross;
      act = true;
    } else if (isCursorSelect(b) || ch === 'i' || ch === 'I') {
      if (ui.cursorVisible) {
        cx = ui.cx;
        cy = ui.cy;
        mark = b === CURSOR_SELECT2 || ch !== null;
        act = true;
      }
      ui.cursorVisible = true;
      idle = '';
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else {
      return null;
    }
    if (!act || cx < 0 || cy < 0 || cx >= w || cy >= h) return idle;
    const i = cy * w + cx;
    if (layout.black[i]) return idle;
    // Lights and marks exclude each other: clear one before placing the other.
    if (mark ? state.light[i] : state.imposs[i]) return idle;
    return `${mark ? 'I' : 'L'}${cx},${cy}`;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h, layout } = state;
    const light = state.light.slice();
    const imposs = state.imposs.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = /^([LI])(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      const i = y * w + x;
      if (layout.black[i]) return null;
      if (m[1] === 'L') {
        imposs[i] = 0;
        light[i] ^= 1;
      } else {
        light[i] = 0;
        imposs[i] ^= 1;
      }
    }
    return { ...makeState(layout, light, imposs), usedSolve };
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, layout, light, imposs, lit } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const hintCell = hintFlashCell(ui, flashTime);
    // A hint owns the flash it asked for: only a finished puzzle washes the whole board.
    const flash = !hintFlashing(ui) && flashOn(flashTime, FLASH_FRAME);
    const litColour = flash ? dr.colour('shade') : dr.withAlpha('yellow', 0.32);
    // A lamp just put down or taken away, and how far its light has got. `animTime` always
    // counts up from the board on screen a moment ago, so an undo runs the beam backwards
    // and the light retreats into the lamp.
    const beam = oldState ? readBeam(oldState, state, dir) : null;
    const elapsed = beam ? (dir > 0 ? animTime : beamTime(beam.far) - animTime) : 0;

    dr.rect(b, b, w * t, h * t, 'paper');
    // Washes and black squares first, so the grid lines sit on top of the colour.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = b + x * t;
        const py = b + y * t;
        if (layout.black[i]) continue;
        // Light travels: a square the beam has not reached yet is still dark, and one it
        // has just reached comes up rather than snapping on.
        const reach = beam && beam.dist[i] >= 0 ? beamAt(beam, i, elapsed) : lit[i] > 0 ? 1 : 0;
        if (reach > 0) dr.rect(px, py, t, t, litColour, null, { alpha: reach });
      }
    }
    for (let x = 1; x < w; x++) dr.line(b + x * t, b, b + x * t, b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, b + y * t, b + w * t, b + y * t, 'faint', 1.2);

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = b + x * t;
        const py = b + y * t;
        if (layout.black[i]) {
          const g = Math.max(0.5, t * 0.02);
          dr.polygon(
            [px + g, py + g, px + t - g, py + g, px + t - g, py + t - g, px + g, py + t - g],
            'ink',
            'ink',
            { seed: i, width: 1.4 },
          );
          const c = layout.clue[i];
          if (c !== NO_CLUE) {
            const wrong = clueWrong(layout, light, imposs, lit, i);
            dr.text(px + t / 2, py + t / 2, String(c), {
              size: t * 0.62,
              bold: true,
              colour: wrong ? 'error' : 'paper',
            });
          }
        } else if (light[i]) {
          drawBulb(dr, px, py, t, lit[i] > 1, i);
        } else if (imposs[i]) {
          dr.cross(px + t / 2, py + t / 2, t * 0.16, 'pencil', Math.max(1.3, t * 0.045), {
            seed: i,
          });
        }
      }
    }
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (hintCell >= 0) {
      dr.hintBox(b + (hintCell % w) * t, b + Math.floor(hintCell / w) * t, t, t);
    }

    if (ui.cursorVisible) {
      const inset = t * 0.1;
      dr.cursor(b + ui.cx * t + inset, b + ui.cy * t + inset, t - 2 * inset, t - 2 * inset);
    }
  },

  animLength(oldState, newState, dir) {
    const beam = readBeam(oldState, newState, dir);
    return beam ? beamTime(beam.far) : 0;
  },
  flashLength(oldState, newState, _dir, ui) {
    const hint = takeHintFlash(ui);
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : hint;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
