/**
 * Deductive four-colouring solver, graded by difficulty.
 *
 * Every region carries a bitmask of the colours it may still take. Placing a colour
 * removes it from all neighbours. The tiers are:
 *
 *  - **Easy**: a region with a single remaining colour takes it.
 *  - **Normal**: two adjacent regions that share the same pair of remaining colours must
 *    use both of them between them, so a region adjacent to both can be neither.
 *  - **Hard**: forcing chains. Starting from a two-colour region and supposing it is
 *    *not* colour C, follow neighbours that are also down to two colours and are forced
 *    in turn. If the chain reaches a region forced to be C, then either the start or that
 *    region is C, and any region adjacent to both cannot be.
 *  - **Unreasonable**: when deduction stalls, guess a colour for the most constrained
 *    region and recurse, counting solutions so ambiguity is detected.
 *
 * `solveMap` returns 0 for an inconsistent puzzle, 1 when it found the unique solution
 * (written into `colouring`) and 2 when it could not finish at this difficulty — the
 * puzzle is either too hard for the tier or has several solutions.
 */
import type { MapGraph } from './board';
import { FOUR } from './board';

export const DIFF_EASY = 0;
export const DIFF_NORMAL = 1;
export const DIFF_HARD = 2;
export const DIFF_RECURSE = 3;
export const DIFFICULTY_NAMES = ['Easy', 'Normal', 'Hard', 'Unreasonable'];
export const DIFFICULTY_CHARS = 'enhu';

export const SOLVE_IMPOSSIBLE = 0;
export const SOLVE_UNIQUE = 1;
export const SOLVE_UNRESOLVED = 2;

const ALL = (1 << FOUR) - 1;

function bitcount(v: number): number {
  v = ((v & 0xa) >> 1) + (v & 0x5);
  return ((v & 0xc) >> 2) + (v & 0x3);
}

class Solver {
  private readonly queue: Int32Array;
  private readonly bfsColour: Int32Array;

  constructor(readonly g: MapGraph) {
    this.queue = new Int32Array(g.n);
    this.bfsColour = new Int32Array(g.n);
  }

  /** Give region `i` colour `c`, ruling it out for the neighbours. False if not allowed. */
  place(possible: Uint8Array, colouring: Int8Array, i: number, c: number): boolean {
    if (!(possible[i] & (1 << c))) return false;
    possible[i] = 1 << c;
    colouring[i] = c;
    for (const k of this.g.adj[i]) possible[k] &= ~(1 << c);
    return true;
  }

  run(possible: Uint8Array, colouring: Int8Array, difficulty: number): number {
    const { g } = this;
    const n = g.n;
    for (;;) {
      let did = false;
      if (difficulty < DIFF_EASY) break;

      // Easy: a region with one remaining colour.
      for (let i = 0; i < n; i++) {
        if (colouring[i] >= 0) continue;
        const p = possible[i];
        if (p === 0) return SOLVE_IMPOSSIBLE;
        if ((p & (p - 1)) === 0) {
          this.place(possible, colouring, i, 31 - Math.clz32(p));
          did = true;
        }
      }
      if (did) continue;
      if (difficulty < DIFF_NORMAL) break;

      // Normal: an adjacent pair sharing the same two colours uses both of them.
      for (const [j1, j2] of g.edges) {
        if (colouring[j1] >= 0 || colouring[j2] >= 0) continue;
        const v = possible[j1];
        if (v !== possible[j2] || bitcount(v) !== 2) continue;
        for (const k of g.adj[j1]) {
          if (g.adjMat[k * n + j2] && possible[k] & v) {
            possible[k] &= ~v;
            did = true;
          }
        }
      }
      if (did) continue;
      if (difficulty < DIFF_HARD) break;

      // Hard: forcing chains.
      const { queue, bfsColour } = this;
      for (let i = 0; i < n; i++) {
        if (colouring[i] >= 0 || bitcount(possible[i]) !== 2) continue;
        for (let c = 0; c < FOUR; c++) {
          const orig = 1 << c;
          if (!(possible[i] & orig)) continue;
          bfsColour.fill(-1);
          let head = 0;
          let tail = 0;
          queue[tail++] = i;
          // The colour each visited region is forced to, if `i` is not `c`.
          bfsColour[i] = possible[i] & ~orig;
          while (head < tail) {
            const j = queue[head++];
            const curr = bfsColour[j];
            for (const k of g.adj[j]) {
              if (
                bfsColour[k] < 0 &&
                colouring[k] < 0 &&
                bitcount(possible[k]) === 2 &&
                possible[k] & curr
              ) {
                queue[tail++] = k;
                bfsColour[k] = possible[k] & ~curr;
              }
              // j is forced to be c unless i is: a region next to both cannot be c.
              if (curr === orig && g.adjMat[k * n + i] && possible[k] & orig) {
                possible[k] &= ~orig;
                did = true;
              }
            }
          }
        }
      }
      if (!did) break;
    }

    let complete = true;
    for (let i = 0; i < n; i++) {
      if (colouring[i] < 0) {
        complete = false;
        break;
      }
    }
    if (complete) return SOLVE_UNIQUE;
    if (difficulty < DIFF_RECURSE) return SOLVE_UNRESOLVED;

    // Unreasonable: guess at the most constrained region.
    let best = -1;
    let bestCount = FOUR + 1;
    for (let i = 0; i < n; i++) {
      if (colouring[i] >= 0) continue;
      const c = bitcount(possible[i]);
      if (c < bestCount) {
        bestCount = c;
        best = i;
      }
    }
    let found: Int8Array | null = null;
    for (let c = 0; c < FOUR; c++) {
      if (!(possible[best] & (1 << c))) continue;
      const sp = possible.slice();
      const sc = colouring.slice();
      this.place(sp, sc, best, c);
      const sub = this.run(sp, sc, difficulty);
      if (sub === SOLVE_UNRESOLVED || (sub === SOLVE_UNIQUE && found)) return SOLVE_UNRESOLVED;
      if (sub === SOLVE_UNIQUE) found = sc;
    }
    if (!found) return SOLVE_IMPOSSIBLE;
    colouring.set(found);
    return SOLVE_UNIQUE;
  }
}

/**
 * Solve in place from the colours already in `colouring` (-1 = unknown) using the
 * deductions allowed at `difficulty`. A difficulty below Easy does nothing at all, which
 * is a handy way of asking "is this already solved?".
 */
export function solveMap(g: MapGraph, colouring: Int8Array, difficulty: number): number {
  const possible = new Uint8Array(g.n).fill(ALL);
  const solver = new Solver(g);
  for (let i = 0; i < g.n; i++) {
    if (colouring[i] >= 0 && !solver.place(possible, colouring, i, colouring[i]))
      return SOLVE_IMPOSSIBLE;
  }
  return solver.run(possible, colouring, difficulty);
}

/**
 * The easiest difficulty whose solver finishes the puzzle: 0–3, or -1 when the givens
 * are inconsistent, or `DIFF_RECURSE + 1` when even guessing finds no unique solution.
 */
export function gradeMap(g: MapGraph, givens: ArrayLike<number>): number {
  for (let d = DIFF_EASY; d <= DIFF_RECURSE; d++) {
    const c = Int8Array.from(givens);
    const ret = solveMap(g, c, d);
    if (ret === SOLVE_IMPOSSIBLE) return -1;
    if (ret === SOLVE_UNIQUE) return d;
  }
  return DIFF_RECURSE + 1;
}
