/**
 * Personal best times: one per puzzle and preset, the number a results screen compares
 * this win against. Kept in the tiered store (`src/storage.ts`), so a best survives a
 * reload inside the CrazyGames frame like progress does. Never throws: a store that
 * cannot be read is an empty record book, and one that cannot be written is ignored.
 */

import { storage } from '../storage';

const KEY = 'puzzlebox:best';

type Book = Record<string, number>;

function read(): Book {
  try {
    const raw = storage.getItem(KEY);
    const parsed = raw ? (JSON.parse(raw) as unknown) : null;
    return parsed && typeof parsed === 'object' ? (parsed as Book) : {};
  } catch {
    return {};
  }
}

/** The key a best is filed under: the game and the preset's short parameters. */
export function recordKey(gameId: string, params: string): string {
  return `${gameId}|${params}`;
}

export function bestTime(key: string): number | undefined {
  const v = read()[key];
  return typeof v === 'number' && v > 0 ? v : undefined;
}

/**
 * File a finishing time. Returns what the best was before it, so the caller can tell a
 * first time on the board from a record broken.
 */
export function recordTime(key: string, secs: number): { previous?: number; best: number } {
  const book = read();
  const previous = typeof book[key] === 'number' && book[key] > 0 ? book[key] : undefined;
  const best = previous === undefined ? secs : Math.min(previous, secs);
  if (best !== previous) {
    book[key] = best;
    try {
      storage.setItem(KEY, JSON.stringify(book));
    } catch {
      /* a best that cannot be kept is still shown this once */
    }
  }
  return { previous, best };
}

/** A duration as the clock shows one: 0:42, 12:05, 1:03:20. */
export function formatTime(secs: number): string {
  const s = Math.max(0, Math.round(secs));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const ss = String(s % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`;
}
