/**
 * Singles puzzle generation.
 *
 * A finished Singles grid is a latin rectangle (no repeated numbers in any row or
 * column) with black cells scattered so that none touch and the rest stay connected. So:
 *
 *  1. draw a random latin rectangle;
 *  2. blacken random cells one at a time, letting the solver's propagation mark the cells
 *     that are thereby forced white, until every cell is decided;
 *  3. give each black cell a new number that already appears among the white cells of
 *     its row or column (otherwise leaving it white would be another solution);
 *  4. keep the result only if the solver at the requested difficulty finishes it and, for
 *     Tricky, the Easy solver — even with the unique-number shortcut — does not.
 *
 * Step 3 is retried a few times per black pattern before starting over from step 1.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { F_BLACK, encodeBlacks, encodeDesc } from './board';
import { DIFF_EASY, OP_BLACK, SOLVED, Solver } from './solver';

export interface GenParams {
  w: number;
  h: number;
  difficulty: number;
}

/** Number re-randomisations per black pattern before a fresh pattern is drawn. */
const MAX_TRIES = 20;

/**
 * A random latin square of order `o` (digits `1..o` once per row and column), built one
 * row at a time. Each row is a perfect matching between columns and the digits they have
 * not used yet, found by augmenting paths in a shuffled order; a partial latin rectangle
 * can always be extended, so the matching always exists.
 */
export function latinSquare(o: number, rng: Random): Uint8Array {
  const sq = new Uint8Array(o * o);
  const used = new Uint8Array(o * o); // used[x * o + d - 1]: digit d already in column x
  const cols: number[] = [];
  const digits: number[] = [];
  const match = new Int32Array(o); // digit slot -> column slot
  const tried = new Uint8Array(o);
  const augment = (ci: number): boolean => {
    const x = cols[ci];
    for (let k = 0; k < o; k++) {
      if (tried[k] || used[x * o + digits[k] - 1]) continue;
      tried[k] = 1;
      if (match[k] < 0 || augment(match[k])) {
        match[k] = ci;
        return true;
      }
    }
    return false;
  };
  for (let y = 0; y < o; y++) {
    cols.length = digits.length = 0;
    for (let i = 0; i < o; i++) {
      cols.push(i);
      digits.push(i + 1);
    }
    rng.shuffle(cols);
    rng.shuffle(digits);
    match.fill(-1);
    for (let ci = 0; ci < o; ci++) {
      tried.fill(0);
      if (!augment(ci)) throw new Error(tx`latinSquare: rectangle could not be extended`);
    }
    for (let k = 0; k < o; k++) {
      const x = cols[match[k]];
      sq[y * o + x] = digits[k];
      used[x * o + digits[k] - 1] = 1;
    }
  }
  return sq;
}

/** The top-left `w × h` of a random latin square of order `max(w, h)`. */
export function latinRect(w: number, h: number, rng: Random): Uint8Array {
  const o = Math.max(w, h);
  const sq = latinSquare(o, rng);
  const out = new Uint8Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) out[y * w + x] = sq[y * o + x];
  return out;
}

/**
 * A random valid black pattern over `nums`: cells are blackened in random order, skipping
 * any the propagation has already decided. Returns the solver (whose flags hold the
 * pattern, every cell black or circled) or null if the process painted itself into a
 * corner.
 */
export function placeBlacks(nums: Uint8Array, w: number, h: number, rng: Random): Solver | null {
  const s = new Solver(nums, w, h);
  const order: number[] = [];
  for (let i = 0; i < nums.length; i++) order.push(i);
  rng.shuffle(order);
  for (const i of order) {
    if (s.flags[i]) continue;
    s.addOp(i, OP_BLACK);
    s.doOps();
    s.allBlackButOne();
    s.doOps();
    s.removeSplits();
    s.doOps();
    if (s.impossible) return null;
  }
  return s;
}

/**
 * Choose the number for black cell `i`: preferably one that appears exactly once among
 * the whites of both its row and its column (so it does not look unique), otherwise any
 * number present in either. `rowCount`/`colCount` are updated as if the number were white
 * so that later choices in the same line stay varied.
 */
export function pickBlackNumber(
  i: number,
  w: number,
  o: number,
  rowCount: Int32Array,
  colCount: Int32Array,
  rng: Random,
): number {
  const x = i % w;
  const y = (i - x) / w;
  const cand: number[] = [];
  for (let d = 1; d <= o; d++) cand.push(d);
  rng.shuffle(cand);
  let pick = -1;
  for (const d of cand) {
    if (rowCount[y * o + d - 1] === 1 && colCount[x * o + d - 1] === 1) {
      pick = d;
      break;
    }
  }
  if (pick < 0) {
    for (const d of cand) {
      if (rowCount[y * o + d - 1] !== 0 || colCount[x * o + d - 1] !== 0) {
        pick = d;
        break;
      }
    }
  }
  if (pick < 0) pick = cand[0];
  rowCount[y * o + pick - 1]++;
  colCount[x * o + pick - 1]++;
  return pick;
}

/**
 * Is this a good puzzle at `difficulty`: the solver of that level finishes it, and (above
 * Easy) the level below cannot, even when it also assumes unique numbers are white?
 */
export function puzzleIsGood(nums: Uint8Array, w: number, h: number, difficulty: number) {
  if (new Solver(nums, w, h).solve(difficulty) !== SOLVED) return false;
  if (difficulty > DIFF_EASY && new Solver(nums, w, h).solve(difficulty - 1, true) === SOLVED)
    return false;
  return true;
}

/** Grids up to this many squares cannot hold a Tricky puzzle (2×4 and 3×3 are the largest). */
export const EASY_ONLY_AREA = 9;

/** Generate a puzzle description plus its solution's black cells (as `aux`). */
export function generate(params: GenParams, rng: Random): { desc: string; aux: string } {
  const { w, h } = params;
  // Nine squares or fewer leave no room for anything the Easy solver cannot already do,
  // so asking for Tricky there used to loop for ever and freeze the page. The original
  // collection falls back to Easy on tiny grids in the same way.
  const difficulty = w * h <= EASY_ONLY_AREA ? DIFF_EASY : params.difficulty;
  const o = Math.max(w, h);
  const n = w * h;
  for (;;) {
    const nums = latinRect(w, h, rng);
    const pattern = placeBlacks(nums, w, h, rng);
    if (!pattern) continue;
    const flags = pattern.flags;

    // How often each number occurs among the white cells of every row and column.
    const rowBase = new Int32Array(h * o);
    const colBase = new Int32Array(w * o);
    for (let i = 0; i < n; i++) {
      if (flags[i] & F_BLACK) continue;
      const x = i % w;
      const y = (i - x) / w;
      rowBase[y * o + nums[i] - 1]++;
      colBase[x * o + nums[i] - 1]++;
    }

    for (let attempt = 0; attempt <= MAX_TRIES; attempt++) {
      const rowCount = rowBase.slice();
      const colCount = colBase.slice();
      for (let i = 0; i < n; i++) {
        if (flags[i] & F_BLACK) nums[i] = pickBlackNumber(i, w, o, rowCount, colCount, rng);
      }
      if (puzzleIsGood(nums, w, h, difficulty)) {
        return { desc: encodeDesc(nums), aux: encodeBlacks(flags) };
      }
    }
  }
}
