/**
 * String catalogues: one JSON file per locale under `src/i18n/locales/`.
 *
 * English is bundled with the app — it is the source language and the fallback for every
 * key, so nothing may ever have to wait for it. Every *other* language is a chunk of its
 * own, fetched only while it is the active language: the 24 catalogues a player is not
 * reading came to ~485 kB gzipped, which was the bulk of the first-load bundle.
 *
 * `t()` stays synchronous. What makes that work is that the catalogue is awaited *before*
 * the thing that needs it renders — once during boot (`src/main.ts`) and again when the
 * switcher changes language (`setLocaleAsync` in `locale.ts`) — so by the time anything
 * asks for a string, the answer is already in memory. Help markdown is loaded the same
 * way, per locale and per game (see `help.ts`).
 *
 * How big each catalogue is, without fetching it, comes from the generated
 * `catalog-sizes.ts`; that is what lets the switcher mark a still-stubbed language.
 */

import { CATALOG_SIZES } from './catalog-sizes';

/** A plural-form set, keyed by CLDR plural category. `other` is always required. */
export interface PluralForms {
  zero?: string;
  one?: string;
  two?: string;
  few?: string;
  many?: string;
  other: string;
}

/** What a catalogue key can resolve to. */
export type Message = string | PluralForms;

/** A namespace inside a catalogue. */
export interface Namespace {
  [key: string]: Message | Namespace | unknown;
}

export interface Catalog extends Namespace {
  /** Metadata; keys starting with `$` are never looked up as strings. */
  $locale?: string;
  /** English-source template messages, keyed by the English text with `{0}` holes. */
  messages?: Record<string, string>;
  /** Locale-aware mouse→touch phrase map: `[english-or-local phrase, replacement]`. */
  touchPhrases?: [string, string][];
}

const PLURAL_KEYS = ['zero', 'one', 'two', 'few', 'many', 'other'] as const;
const PLURAL_SET = new Set<string>(PLURAL_KEYS);

/**
 * True when a catalogue value is a plural-form set rather than a nested namespace: every
 * one of its keys is a CLDR plural category. No namespace is called `one` or `other`, so
 * this is unambiguous in practice.
 */
export function isPluralForms(v: unknown): v is PluralForms {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return false;
  const keys = Object.keys(v as object);
  return keys.length > 0 && keys.every((k) => PLURAL_SET.has(k));
}

// English eagerly (through a glob rather than a plain import, so its type is the `Catalog`
// declared above rather than the JSON's own literal type), every other language lazily —
// one chunk per file, emitted by Vite and fetched by `loadCatalog`.
const bundled = import.meta.glob<{ default: Catalog }>('./locales/en.json', { eager: true });
const chunks = import.meta.glob<{ default: Catalog }>(['./locales/*.json', '!./locales/en.json']);

function codeOf(path: string): string {
  return path.replace(/^.*\/([^/]+)\.json$/, '$1');
}

const catalogs: Record<string, Catalog> = {};
for (const [path, mod] of Object.entries(bundled)) catalogs[codeOf(path)] = mod.default ?? {};

const inFlight = new Map<string, Promise<void>>();

/** True when this locale's strings are in memory, so `t()` can already answer in it. */
export function isCatalogLoaded(locale: string): boolean {
  return catalogs[locale] !== undefined;
}

/**
 * Fetch a locale's catalogue chunk, once, and keep it.
 *
 * Resolves immediately for English (bundled) and for anything already loaded, and never
 * rejects: a chunk that fails to arrive leaves the page in the language it was already in
 * (see {@link catalogMissing}) rather than breaking it.
 */
export function loadCatalog(locale: string): Promise<void> {
  if (isCatalogLoaded(locale)) return Promise.resolve();
  const load = chunks[`./locales/${locale}.json`];
  if (!load) return Promise.resolve();
  let pending = inFlight.get(locale);
  if (!pending) {
    pending = load()
      .then((mod) => {
        catalogs[locale] = mod.default ?? {};
      })
      .catch((e: unknown) => {
        console.warn(
          `i18n: the ${locale} catalogue failed to load; keeping the current language`,
          e,
        );
      })
      .finally(() => inFlight.delete(locale));
    inFlight.set(locale, pending);
  }
  return pending;
}

/**
 * True when this locale ships a catalogue chunk that is not in memory — i.e. it was never
 * fetched, or the fetch failed (offline, a deploy that replaced the chunk). Switching to
 * such a locale would render English under its `lang`, so `setLocaleAsync` stays put.
 */
export function catalogMissing(locale: string): boolean {
  return !isCatalogLoaded(locale) && !!chunks[`./locales/${locale}.json`];
}

export function getCatalog(locale: string): Catalog | undefined {
  return catalogs[locale];
}

/** Every locale code that ships a catalogue file (populated or not, loaded or not). */
export function catalogLocales(): string[] {
  return [...new Set([...Object.keys(CATALOG_SIZES), ...Object.keys(catalogs)])].sort();
}

/** Number of leaf strings in a catalogue, ignoring `$metadata`. */
export function countStrings(cat: Catalog): number {
  let n = 0;
  const walk = (v: unknown) => {
    if (typeof v === 'string') {
      n++;
    } else if (isPluralForms(v)) {
      n++;
    } else if (Array.isArray(v)) {
      for (const x of v) walk(x);
    } else if (v && typeof v === 'object') {
      for (const [k, x] of Object.entries(v)) {
        if (k.startsWith('$')) continue;
        walk(x);
      }
    }
  };
  for (const [k, v] of Object.entries(cat)) {
    if (k.startsWith('$')) continue;
    walk(v);
  }
  return n;
}

/**
 * How many strings a locale ships. Used to spot a stub — a language that is in the
 * switcher but has nothing in it yet. Answered from the generated manifest when the
 * catalogue has not been fetched, because asking the question must not drag all 24
 * languages back into the bundle.
 */
export function catalogSize(locale: string): number {
  const cat = catalogs[locale];
  if (cat) return countStrings(cat);
  return CATALOG_SIZES[locale] ?? 0;
}

/**
 * Resolve a dotted key path (`ui.menu.title`) inside one catalogue. Returns `undefined`
 * when any part of the path is missing, so the caller can fall back to English.
 */
export function lookup(locale: string, key: string): Message | undefined {
  const cat = catalogs[locale];
  if (!cat) return undefined;
  let node: unknown = cat;
  for (const part of key.split('.')) {
    if (!node || typeof node !== 'object') return undefined;
    node = (node as Namespace)[part];
  }
  if (typeof node === 'string') return node;
  if (isPluralForms(node)) return node;
  return undefined;
}

/** Look up an English-source template message (`tx`). Keys may contain dots. */
export function lookupMessage(locale: string, pattern: string): string | undefined {
  const m = catalogs[locale]?.messages;
  const v = m ? m[pattern] : undefined;
  return typeof v === 'string' && v.length > 0 ? v : undefined;
}

/** The locale's mouse→touch phrase map, or `undefined` when it supplies none. */
export function lookupTouchPhrases(locale: string): [string, string][] | undefined {
  const p = catalogs[locale]?.touchPhrases;
  return Array.isArray(p) && p.length > 0 ? p : undefined;
}

/** Test seam: install or replace a catalogue at runtime. */
export function registerCatalog(locale: string, cat: Catalog): void {
  catalogs[locale] = cat;
}
