import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { geometry } from './index';
import type { MapState, MapUI } from './index';

const BLUE = 1;
const YELLOW = 3;

/** Region of the square at (x, y). */
const rgn = (s: MapState, x: number, y: number) => s.map.region[y * s.map.w + x];

/** Does any quadrant of square (x, y) belong to region `r`? */
function inRegion(s: MapState, x: number, y: number, r: number): boolean {
  const wh = s.map.w * s.map.h;
  const i = y * s.map.w + x;
  for (let q = 0; q < 4; q++) if (s.map.quad[q * wh + i] === r) return true;
  return false;
}

/** A region as one rectangle per horizontal run of its squares, so the spotlight fits it. */
function regionRects(state: MapState, t: number, r: number): TutorialRect[] {
  const g = geometry(t, state.map.w, state.map.h);
  const out: TutorialRect[] = [];
  for (let y = 0; y < state.map.h; y++) {
    let run = 0;
    for (let x = 0; x <= state.map.w; x++) {
      if (x < state.map.w && inRegion(state, x, y, r)) {
        run++;
        continue;
      }
      if (run) out.push({ x: g.mapX + (x - run) * t, y: g.mapY + y * t, w: run * t, h: t });
      run = 0;
    }
  }
  return out;
}

/** Middle of the square at (x, y): somewhere the pointer can press or drop a colour. */
function centre(state: MapState, t: number, x: number, y: number) {
  const g = geometry(t, state.map.w, state.map.h);
  return { x: g.mapX + (x + 0.5) * t, y: g.mapY + (y + 0.5) * t };
}

/** One palette swatch, 0–3 for the colours and 4 for the eraser. */
function swatch(state: MapState, t: number, s: number): TutorialRect {
  const g = geometry(t, state.map.w, state.map.h);
  return { x: g.palX + s * (g.sw + g.gap), y: g.palY, w: g.sw, h: g.sw };
}

/**
 * A 5×5 map cut into seven regions, four of them given. The three blanks fall in a chain:
 * the tall region on the right has only blue left, that leaves yellow for the big region
 * across the top, and red for the corner at the bottom.
 */
export const tutorial: Tutorial<MapState, MapUI> = {
  steps: [
    {
      gameId: '5x5n7:gfaabccaaacacaacab,a02b13',
      text: 'Colour every region so that no two regions sharing a stretch of border match. Four colours are always enough, and three regions here are still blank.',
      highlight: ({ state, tileSize }) => {
        const g = geometry(tileSize, state.map.w, state.map.h);
        return { x: g.mapX, y: g.mapY, w: g.mapW, h: g.mapH };
      },
    },
    {
      text: 'Pick a colour up first: **click** the **blue swatch**, second in the row under the map.',
      highlight: ({ state, tileSize }) => swatch(state, tileSize, BLUE),
      pointer: ({ state, tileSize }) => {
        const r = swatch(state, tileSize, BLUE);
        return { x: r.x + r.w / 2, y: r.y + r.h / 2 };
      },
      waitFor: ({ ui }) => ui.selColour === BLUE,
    },
    {
      text: 'With a colour in hand, a **right-click** on a blank region pencils a dot of it in — a note that the region *might* be that colour. Try it on the tall region down the right-hand side.',
      highlight: ({ state, tileSize }) =>
        regionRects(state, tileSize, rgn(state, state.map.w - 1, state.map.h - 1)),
      pointer: ({ state, tileSize }) => {
        const c = centre(state, tileSize, state.map.w - 2, 2);
        // Nudged left of centre so the "right-click" tag stays clear of the callout.
        return { x: c.x - tileSize * 0.25, y: c.y, button: 'right' as const };
      },
      waitFor: ({ state }) => state.pencil[rgn(state, state.map.w - 1, state.map.h - 1)] !== 0,
    },
    {
      text: 'It is more than a maybe: that region already borders red, green and yellow, so blue is all that is left. **Click** it to paint it in.',
      highlight: ({ state, tileSize }) =>
        regionRects(state, tileSize, rgn(state, state.map.w - 1, state.map.h - 1)),
      pointer: ({ state, tileSize }) => centre(state, tileSize, state.map.w - 2, 2),
      waitFor: ({ state }) =>
        state.colouring[rgn(state, state.map.w - 1, state.map.h - 1)] === BLUE,
    },
    {
      text: 'You can also **drag** a colour from one region to another. The big region across the top now touches red, green and blue, so **drag** yellow up to it from the small region at the bottom.',
      highlight: ({ state, tileSize }) => [
        ...regionRects(state, tileSize, rgn(state, state.map.w - 2, state.map.h - 1)),
        ...regionRects(state, tileSize, rgn(state, 0, 0)),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(state, tileSize, state.map.w - 2, state.map.h - 1),
        to: centre(state, tileSize, 1, 0),
      }),
      waitFor: ({ state }) => state.colouring[rgn(state, 0, 0)] === YELLOW,
    },
    {
      text: 'One blank left, in the **bottom-left corner**: it borders green, blue and that new yellow, so it has to be red. **Drag** red down to it from the region in the top-right corner.',
      highlight: ({ state, tileSize }) => [
        ...regionRects(state, tileSize, rgn(state, state.map.w - 1, 0)),
        ...regionRects(state, tileSize, rgn(state, 0, state.map.h - 1)),
      ],
      pointer: ({ state, tileSize }) => ({
        ...centre(state, tileSize, state.map.w - 1, 0),
        to: centre(state, tileSize, 0, state.map.h - 1),
      }),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Done — a clash would have shown a red **!** on the border between the two regions. **Undo** steps back, and the arrow keys with **1**–**4** colour without the mouse.',
      textTouch:
        'Done — a clash would have shown a red **!** on the border between the two regions. **Undo** steps back, and the eraser swatch at the end of the row wipes a region you have changed your mind about.',
      target: '[data-cmd="undo"]',
    },
  ],
};
