import { gsap, prefersReducedMotion } from './anim';

/**
 * The journey between the box and a puzzle, as a slip of paper in the air.
 *
 * Opening a card lifts that one slip out of the tray, flies it to the middle of the desk
 * and turns it over: its face is the card, its back is the sheet the puzzle is played on,
 * and it lands like paper — a drop, a squash, a flutter — with the board appearing on it.
 * Going back is the same trip the other way: the sheet lifts, the box comes back into view
 * with an empty slot where the card was, and the sheet turns back over into it, carrying
 * the board as it was left (see `rememberBoard` in thumbnail.ts).
 *
 * All of the flying is the Web Animations API on transforms and opacity, never GSAP, and
 * that is the point of it: those run on the compositor, so they keep moving while the main
 * thread is busy. Mounting a game generates a puzzle, which can hold the main thread for a
 * good fraction of a second — the old dive had to finish before the swap and then showed
 * an empty desk for as long as the generator took. Now the swap happens *under* the slip,
 * while it is in the air, and the stall is hidden inside the flip.
 *
 * Each direction is two halves. The first half is known the moment the player clicks and
 * is handed to the compositor at once: out of the box towards where the sheet is expected
 * to be, or off the board into the air. The second half needs the page on the far side —
 * the real sheet, the real card — so it starts once that page is mounted and measured: a
 * landing that corrects whatever the guess got wrong, or the flight down into the slot.
 * Should the far side take longer than the first half, the slip hovers where it is.
 */

interface Box {
  left: number;
  top: number;
  width: number;
  height: number;
}

/** The first half of the way in, from the click to the slip hovering over the desk. */
const OPEN_MS = 780;
/** How long the box takes to fall away behind the lifted card; the page swaps after it. */
export const OPEN_FADE_MS = 280;
/** The sheet coming down onto the desk. */
const LAND_MS = 440;
/** How long the play page takes to fade under the lifted sheet; the page swaps after it. */
export const CLOSE_FADE_MS = 160;
/** The sheet lifting off the board, the first half of the way back. */
const LIFT_MS = 200;
/** The flight down into the slot, the second half of the way back. */
const HOME_MS = 640;

let airborne = 0;

/**
 * Whether a slip is in the air or landing. The board's own entrance (`boardEnter`) stands
 * aside meanwhile: the landing already is the board's arrival.
 */
export function flightActive(): boolean {
  return airborne > 0;
}

let waiting: (() => void)[] = [];

/**
 * Resolves once nothing is in the air. A play page that has something to put over the
 * board as it opens — the first-visit tutorial — waits for the sheet to land first.
 */
export function afterFlight(): Promise<void> {
  if (!airborne) return Promise.resolve();
  return new Promise((res) => waiting.push(res));
}

function takeOff(): void {
  airborne++;
}

function touchDown(): void {
  airborne = Math.max(0, airborne - 1);
  if (airborne) return;
  const then = waiting;
  waiting = [];
  then.forEach((f) => f());
}

/** Where the sheet was the last time this game was on screen, at that size of window. */
const sheets = new Map<string, { box: Box; vw: number; vh: number }>();

function rememberSheet(slug: string, box: Box): void {
  sheets.set(slug, { box, vw: window.innerWidth, vh: window.innerHeight });
}

/**
 * Where the sheet is expected to land, before the page that holds it exists. Exact on a
 * second visit at the same window size; the first time, a square in the room under the
 * HUD — the landing corrects the rest, and a sheet settling into its final size as it
 * comes down reads as nothing more than paper settling.
 */
function guessSheet(slug: string): Box {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const seen = sheets.get(slug);
  if (seen && seen.vw === vw && seen.vh === vh) return seen.box;
  const side = Math.max(120, Math.min(vw - 40, vh - 170) * 0.94);
  return { left: (vw - side) / 2, top: 64 + (vh - 64 - 60 - side) / 2, width: side, height: side };
}

/** The sheet under the board: the wrap and the paper edge it draws past it (play.css). */
function sheetBox(wrap: HTMLElement): Box | null {
  const r = wrap.getBoundingClientRect();
  if (r.width <= 0 || r.height <= 0) return null;
  const pad = parseFloat(getComputedStyle(wrap).getPropertyValue('--sheet-pad')) || 0;
  return {
    left: r.left - pad,
    top: r.top - pad,
    width: r.width + 2 * pad,
    height: r.height + 2 * pad,
  };
}

const centre = (b: Box): [number, number] => [b.left + b.width / 2, b.top + b.height / 2];

function onScreen(r: Box): boolean {
  return (
    r.width > 0 &&
    r.height > 0 &&
    r.left + r.width > 0 &&
    r.top + r.height > 0 &&
    r.left < window.innerWidth &&
    r.top < window.innerHeight
  );
}

const tf = (x: number, y: number, r: number, s: number | [number, number]) =>
  `translate(${x}px, ${y}px) rotate(${r}deg) scale(${Array.isArray(s) ? s.join(', ') : s})`;

/** A card's own slight angle in the tray (desk.css), in degrees. */
function tiltOf(card: HTMLElement): number {
  return parseFloat(getComputedStyle(card).rotate) || 0;
}

/** How far the hover loop has carried the slip, so the next half starts from there. */
function hoverOffset(el: HTMLElement): number {
  const t = getComputedStyle(el).transform;
  return t && t !== 'none' ? new DOMMatrixReadOnly(t).f : 0;
}

function copyCanvas(from: HTMLCanvasElement, to: HTMLCanvasElement): void {
  to.width = from.width;
  to.height = from.height;
  to.getContext('2d')?.drawImage(from, 0, 0);
}

/**
 * The slip: laid out at the sheet's size and scaled down to the card, so the side that
 * ends up big is drawn at its full size and stays sharp. `pos` carries it about the desk,
 * `spin` turns it over, `hover` bobs it while it waits, and its shadow travels separately
 * so it can stay flat on the desk while the slip tilts above it.
 */
interface Slip {
  root: HTMLElement;
  hover: HTMLElement;
  pos: HTMLElement;
  spin: HTMLElement;
  front: HTMLElement;
  back: HTMLElement;
  shadow: HTMLElement;
  box: Box;
}

function makeSlip(box: Box): Slip {
  const div = (cls: string) => {
    const d = document.createElement('div');
    d.className = cls;
    return d;
  };
  const root = div('flight');
  root.setAttribute('aria-hidden', 'true');
  const place = (el: HTMLElement) => {
    el.style.left = `${box.left}px`;
    el.style.top = `${box.top}px`;
    el.style.width = `${box.width}px`;
    el.style.height = `${box.height}px`;
  };
  const shadow = div('flight-shadow');
  place(shadow);
  const hover = div('flight-hover');
  const pos = div('flight-pos');
  place(pos);
  const spin = div('flight-spin');
  const front = div('flight-face flight-front');
  const back = div('flight-face flight-back');
  spin.append(front, back);
  pos.append(spin);
  hover.append(pos);
  root.append(shadow, hover);
  document.body.append(root);
  return { root, hover, pos, spin, front, back, shadow, box };
}

/**
 * Dress the slip's face as `card`, returning the scale at which the slip is exactly the
 * card's size. The copy sits in a bare `.shelf` so every rule that draws a card in the
 * tray still applies to it; the tray's own box is taken off in desk.css.
 */
function dressFront(slip: Slip, card: HTMLElement): number {
  const cw = card.offsetWidth;
  const ch = card.offsetHeight;
  const s = cw / slip.box.width;
  const fh = ch / s;
  slip.front.style.width = `${slip.box.width}px`;
  slip.front.style.height = `${fh}px`;
  slip.front.style.top = `${(slip.box.height - fh) / 2}px`;
  const shelf = document.createElement('div');
  shelf.className = 'shelf flight-shelf';
  const grid = document.createElement('div');
  grid.className = 'card-grid';
  const copy = card.cloneNode(true) as HTMLElement;
  copy.classList.remove('out', 'pressing');
  // A picture of the card, not a second one: nothing that finds, names or follows a card
  // may find this copy too.
  for (const n of [copy, ...copy.querySelectorAll('[id]')]) n.removeAttribute('id');
  for (const attr of [
    'data-slug',
    'data-href',
    'data-search',
    'href',
    'role',
    'tabindex',
    'aria-label',
  ])
    copy.removeAttribute(attr);
  const cs = getComputedStyle(card);
  Object.assign(copy.style, {
    position: 'absolute',
    left: '0',
    top: '0',
    width: `${cw}px`,
    height: `${ch}px`,
    margin: '0',
    rotate: 'none',
    translate: 'none',
    scale: 'none',
    transition: 'none',
    borderRadius: cs.borderRadius,
    transform: `scale(${1 / s})`,
    transformOrigin: '0 0',
  });
  const from = card.querySelectorAll('canvas');
  copy.querySelectorAll('canvas').forEach((c, i) => from[i] && copyCanvas(from[i], c));
  grid.append(copy);
  shelf.append(grid);
  slip.front.replaceChildren(shelf);
  return s;
}

/** Dress the slip's back as the sheet, with the board on it when there is one to copy. */
function dressBack(slip: Slip, board: HTMLCanvasElement | null): void {
  const paper = document.createElement('div');
  paper.className = 'flight-sheet';
  if (board) {
    const r = board.getBoundingClientRect();
    const c = document.createElement('canvas');
    copyCanvas(board, c);
    Object.assign(c.style, {
      position: 'absolute',
      left: `${r.left - slip.box.left}px`,
      top: `${r.top - slip.box.top}px`,
      width: `${r.width}px`,
      height: `${r.height}px`,
    });
    paper.append(c);
  }
  slip.back.replaceChildren(paper);
}

/** The gentle bob of a slip waiting in the air, queued on the compositor behind `after`. */
function hoverAfter(slip: Slip, after: number): Animation {
  return slip.hover.animate([{ transform: 'none' }, { transform: 'translateY(-5px)' }], {
    duration: 800,
    delay: after,
    iterations: Infinity,
    direction: 'alternate',
    easing: 'ease-in-out',
  });
}

/** The chrome of a page — everything but the part that holds `keep` — faded in. */
function chromeIn(page: HTMLElement, keep: HTMLElement | null, delay: number): void {
  for (const child of page.children) {
    if (keep && child.contains(keep)) continue;
    (child as HTMLElement).animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 260,
      delay,
      easing: 'cubic-bezier(.2,.7,.3,1)',
      fill: 'backwards',
    });
  }
}

// ------------------------------------------------------------------ into a puzzle

export interface OpenFlight {
  /**
   * The play page is mounted. `wrap` is its board's wrap, or null for a page with no board
   * to land on (a tutorial that opens on words); the page is hidden until the slip lands.
   */
  arrive(page: HTMLElement, wrap: HTMLElement | null): void;
  /** Put everything where it belongs at once: another navigation got in first. */
  cancel(): void;
  /** Settles when the journey is over, landed or cancelled. */
  readonly done: Promise<void>;
}

/**
 * Lift `card` out of the collection page `outgoing` and set it flying towards the sheet
 * `slug` will be played on. Null when there is to be no flight (less motion asked for, or
 * a card that is not on screen); the caller falls back to the plain page swap.
 */
export function flyOpen(card: HTMLElement, outgoing: HTMLElement, slug: string): OpenFlight | null {
  if (prefersReducedMotion()) return null;
  const cr = card.getBoundingClientRect();
  if (!onScreen(cr) || !card.offsetWidth) return null;
  const [cx, cy] = centre(cr);
  const tilt = tiltOf(card);
  const box = guessSheet(slug);
  const slip = makeSlip(box);
  const s0 = dressFront(slip, card);
  dressBack(slip, null);
  const [bx, by] = centre(box);
  const dx = cx - bx;
  const dy = cy - by;
  card.classList.add('out');
  takeOff();

  // 1. Lift and straighten. 2. Fly and turn over, ending just above the desk.
  const flight = slip.pos.animate(
    [
      { transform: tf(dx, dy, tilt, s0), easing: 'cubic-bezier(.2,.8,.3,1)' },
      {
        transform: tf(dx, dy - 12, 0, s0 * 1.1),
        offset: 0.2,
        easing: 'cubic-bezier(.5,0,.2,1)',
      },
      { transform: tf(0, -8, -1, 1.03) },
    ],
    { duration: OPEN_MS, fill: 'forwards' },
  );
  const spin = slip.spin.animate(
    [
      { transform: 'rotateY(0deg) rotateX(0deg)' },
      {
        transform: 'rotateY(0deg) rotateX(0deg)',
        offset: 0.2,
        easing: 'cubic-bezier(.45,0,.35,1)',
      },
      {
        transform: 'rotateY(95deg) rotateX(9deg)',
        offset: 0.55,
        easing: 'cubic-bezier(.3,0,.25,1)',
      },
      { transform: 'rotateY(180deg) rotateX(0deg)', offset: 0.92 },
      { transform: 'rotateY(180deg) rotateX(0deg)' },
    ],
    { duration: OPEN_MS, fill: 'forwards' },
  );
  const shade = slip.shadow.animate(
    [
      { transform: tf(dx, dy + 4, 0, s0), opacity: 0.45 },
      { transform: tf(dx, dy + 18, 0, s0 * 1.12), opacity: 0.3, offset: 0.2 },
      { transform: tf(0, 22, 0, 1.06), opacity: 0.28 },
    ],
    { duration: OPEN_MS, fill: 'forwards', easing: 'cubic-bezier(.5,0,.2,1)' },
  );
  const bob = hoverAfter(slip, OPEN_MS);

  // The rest of the box falls away behind it, about the card.
  const pr = outgoing.getBoundingClientRect();
  outgoing.style.transformOrigin = `${cx - pr.left}px ${cy - pr.top}px`;
  outgoing.animate(
    [
      { opacity: 1, transform: 'none' },
      { opacity: 1, transform: 'scale(1.015)', offset: 0.3 },
      { opacity: 0, transform: 'scale(1.07)' },
    ],
    { duration: OPEN_FADE_MS, easing: 'ease-in', fill: 'forwards' },
  );

  let flown = false;
  let over = false;
  let target: { page: HTMLElement; wrap: HTMLElement | null } | null = null;
  let finish!: () => void;
  const done = new Promise<void>((res) => (finish = res));

  const end = () => {
    if (over) return;
    over = true;
    window.removeEventListener('pointerdown', hurry, true);
    window.removeEventListener('keydown', hurry, true);
    touchDown();
    finish();
  };
  /**
   * A press while the slip is still turning over — the board is already on its face, and a
   * player who has seen it goes for it — puts it down at once rather than letting the press
   * fall through the gap between a card and a page that is not up yet. From the moment the
   * page is mounted; the landing that follows is the page itself, and takes input.
   */
  function hurry() {
    if (over || flown || !target) return;
    for (const a of [flight, spin, shade]) a.finish();
  }
  window.addEventListener('pointerdown', hurry, true);
  window.addEventListener('keydown', hurry, true);

  function land() {
    const { page, wrap } = target!;
    const to = wrap && !page.classList.contains('zoomed') ? sheetBox(wrap) : null;
    const lift = hoverOffset(slip.hover);
    bob.cancel();
    if (!to) {
      // Nothing to land on: the slip fades where it is and the page comes up under it.
      page.style.visibility = '';
      page.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, easing: 'ease-out' });
      slip.root
        .animate([{ opacity: 1 }, { opacity: 0 }], { duration: 220, fill: 'forwards' })
        .finished.then(
          () => slip.root.remove(),
          () => slip.root.remove(),
        );
      end();
      return;
    }
    rememberSheet(slug, to);
    const [tx, ty] = centre(to);
    // The real sheet is put exactly where the slip is hovering — the same size, the same
    // lean — and then let fall into its own place.
    const from = tf(bx - tx, by - 8 + lift - ty, -1, [
      (box.width * 1.03) / to.width,
      (box.height * 1.03) / to.height,
    ]);
    slip.root.remove();
    page.style.visibility = '';
    const fall = wrap!.animate(
      [
        { transform: from, easing: 'cubic-bezier(.55,0,.9,.45)' },
        {
          transform: 'translateY(1.5px) rotate(.5deg) scale(.99) skewX(-.6deg)',
          offset: 0.36,
          easing: 'cubic-bezier(.2,.6,.4,1)',
        },
        {
          transform: 'translateY(-1px) rotate(-.25deg) scale(1.004) skewX(.25deg)',
          offset: 0.7,
          easing: 'ease-in-out',
        },
        { transform: 'none' },
      ],
      { duration: LAND_MS },
    );
    // The shadow presses in under it as it touches, and the board comes up on the paper.
    gsap.fromTo(
      wrap,
      { '--sheet-lift': '16px' },
      {
        '--sheet-lift': '0px',
        duration: (LAND_MS / 1000) * 0.5,
        ease: 'power2.in',
        onComplete: () => wrap!.style.removeProperty('--sheet-lift'),
      },
    );
    wrap!
      .querySelector('canvas')
      ?.animate([{ opacity: 0 }, { opacity: 0, offset: 0.2 }, { opacity: 1 }], {
        duration: LAND_MS * 0.8,
        easing: 'ease-out',
      });
    chromeIn(page, wrap, LAND_MS * 0.3);
    fall.finished.then(end, end);
  }

  const tryLand = () => {
    if (flown && target && !over) land();
  };
  flight.finished.then(
    () => {
      flown = true;
      tryLand();
    },
    () => {},
  );

  return {
    arrive(page, wrap) {
      if (over) return;
      page.style.visibility = 'hidden';
      target = { page, wrap };
      tryLand();
    },
    cancel() {
      if (over) return;
      slip.root.remove();
      card.classList.remove('out');
      outgoing.getAnimations().forEach((a) => a.cancel());
      outgoing.style.transformOrigin = '';
      if (target) target.page.style.visibility = '';
      end();
    },
    done,
  };
}

// ------------------------------------------------------------------ back to the box

export interface CloseFlight {
  /**
   * The collection is mounted. `card` is the slot to fly into — the card for the game
   * being left, already on screen and marked `.out` — or null to put the sheet down
   * without one. `onLanded` runs once the card is back in the box.
   */
  arrive(page: HTMLElement, card: HTMLElement | null, onLanded?: () => void): void;
  cancel(): void;
  readonly done: Promise<void>;
}

/**
 * Lift the sheet off the play page `outgoing` and hold it in the air while the collection
 * is mounted under it. Null when there is to be no flight; the caller falls back to the
 * plain page swap.
 */
export function flyClose(
  outgoing: HTMLElement,
  wrap: HTMLElement,
  slug: string,
): CloseFlight | null {
  if (prefersReducedMotion()) return null;
  if (outgoing.classList.contains('zoomed')) return null;
  const found = sheetBox(wrap);
  if (!found || !onScreen(found)) return null;
  const box: Box = found;
  rememberSheet(slug, box);
  const slip = makeSlip(box);
  dressBack(slip, wrap.querySelector('canvas'));
  slip.spin.style.transform = 'rotateY(180deg)';
  wrap.style.visibility = 'hidden';
  takeOff();

  outgoing.animate([{ opacity: 1 }, { opacity: 0 }], {
    duration: CLOSE_FADE_MS,
    easing: 'ease-in',
    fill: 'forwards',
  });
  const lift = slip.pos.animate(
    [{ transform: tf(0, 0, 0, 1) }, { transform: tf(0, -12, 0.6, 1.03) }],
    { duration: LIFT_MS, easing: 'cubic-bezier(.2,.8,.3,1)', fill: 'forwards' },
  );
  const shadowUp = slip.shadow.animate(
    [
      { transform: tf(0, 10, 0, 0.98), opacity: 0.42 },
      { transform: tf(0, 26, 0, 1.06), opacity: 0.3 },
    ],
    { duration: LIFT_MS, easing: 'cubic-bezier(.2,.8,.3,1)', fill: 'forwards' },
  );
  const bob = hoverAfter(slip, LIFT_MS);

  let over = false;
  let landedPage: HTMLElement | null = null;
  let landedCard: HTMLElement | null = null;
  let finish!: () => void;
  const done = new Promise<void>((res) => (finish = res));
  const end = () => {
    if (over) return;
    over = true;
    touchDown();
    finish();
  };

  function home(page: HTMLElement, card: HTMLElement | null, onLanded?: () => void) {
    const cr = card?.getBoundingClientRect();
    if (!card || !cr || !onScreen(cr)) {
      // No slot on screen to aim for: the sheet shrinks away where it is.
      bob.cancel();
      page.style.opacity = '';
      page.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, easing: 'ease-out' });
      slip.root
        .animate([{ opacity: 1 }, { opacity: 0, transform: 'scale(.9)' }], {
          duration: 240,
          fill: 'forwards',
        })
        .finished.then(
          () => slip.root.remove(),
          () => slip.root.remove(),
        );
      card?.classList.remove('out');
      onLanded?.();
      end();
      return;
    }
    const s = dressFront(slip, card);
    const [cx, cy] = centre(cr);
    const [bx, by] = centre(box);
    const dx = cx - bx;
    const dy = cy - by;
    const tilt = tiltOf(card);
    const up = hoverOffset(slip.hover);
    bob.cancel();
    const flight = slip.pos.animate(
      [
        { transform: tf(0, -12 + up, 0.6, 1.03), easing: 'cubic-bezier(.5,0,.25,1)' },
        {
          transform: tf(dx, dy - 8, tilt, s * 1.08),
          offset: 0.72,
          easing: 'cubic-bezier(.6,0,.9,.5)',
        },
        { transform: tf(dx, dy + 1, tilt, s * 0.965), offset: 0.87, easing: 'ease-out' },
        { transform: tf(dx, dy, tilt, s) },
      ],
      { duration: HOME_MS, fill: 'forwards' },
    );
    lift.cancel();
    slip.spin.animate(
      [
        { transform: 'rotateY(180deg) rotateX(0deg)', easing: 'cubic-bezier(.45,0,.35,1)' },
        {
          transform: 'rotateY(275deg) rotateX(-9deg)',
          offset: 0.4,
          easing: 'cubic-bezier(.3,0,.25,1)',
        },
        { transform: 'rotateY(360deg) rotateX(0deg)', offset: 0.7 },
        { transform: 'rotateY(360deg) rotateX(0deg)' },
      ],
      { duration: HOME_MS, fill: 'forwards' },
    );
    slip.shadow.animate(
      [
        { transform: tf(0, 26 + up, 0, 1.06), opacity: 0.3 },
        { transform: tf(dx, dy + 14, 0, s * 1.1), opacity: 0.3, offset: 0.72 },
        { transform: tf(dx, dy + 3, 0, s), opacity: 0.55, offset: 0.87 },
        { transform: tf(dx, dy + 4, 0, s), opacity: 0 },
      ],
      { duration: HOME_MS, fill: 'forwards', easing: 'cubic-bezier(.5,0,.3,1)' },
    );
    shadowUp.cancel();

    // The box comes back into view about the empty slot, so there is somewhere to aim.
    const pr = page.getBoundingClientRect();
    page.style.transformOrigin = `${cx - pr.left}px ${cy - pr.top}px`;
    page.style.opacity = '';
    page.animate(
      [
        { opacity: 0, transform: 'scale(1.07)' },
        { opacity: 1, transform: 'none' },
      ],
      {
        duration: HOME_MS * 0.6,
        delay: HOME_MS * 0.04,
        easing: 'cubic-bezier(.2,.7,.3,1)',
        fill: 'backwards',
      },
    );

    flight.finished.then(
      () => {
        slip.root.remove();
        page.style.transformOrigin = '';
        card.classList.remove('out');
        settle(card);
        onLanded?.();
        end();
      },
      () => {},
    );
  }

  return {
    arrive(page, card, onLanded) {
      if (over) return;
      landedPage = page;
      landedCard = card;
      page.style.opacity = '0';
      // Aim once the sheet is up; the lift is short, and the main thread is free again.
      const go = () => {
        if (!over) home(page, card, onLanded);
      };
      if (lift.playState === 'finished') go();
      else lift.finished.then(go, () => {});
    },
    cancel() {
      if (over) return;
      slip.root.remove();
      wrap.style.visibility = '';
      outgoing.getAnimations().forEach((a) => a.cancel());
      if (landedPage) {
        landedPage.style.opacity = '';
        landedPage.style.transformOrigin = '';
        landedPage.getAnimations().forEach((a) => a.cancel());
      }
      landedCard?.classList.remove('out');
      end();
    },
    done,
  };
}

/**
 * A slip dropped back into its slot: it squashes as it lands, its neighbours in the tray
 * are nudged away from it and settle back, and a stamp waiting on it comes down.
 */
function settle(card: HTMLElement): void {
  card.animate(
    [
      { transform: 'scale(.965)' },
      { transform: 'scale(1.012)', offset: 0.5 },
      { transform: 'none' },
    ],
    { duration: 300, easing: 'ease-out' },
  );
  const [cx, cy] = centre(card.getBoundingClientRect());
  for (const other of card.parentElement?.children ?? []) {
    const c = other as HTMLElement;
    if (c === card || c.hidden || c.classList.contains('off-page')) continue;
    const [qx, qy] = centre(c.getBoundingClientRect());
    const d = Math.hypot(qx - cx, qy - cy) || 1;
    const m = 7 * Math.exp(-d / 230);
    if (m < 0.5) continue;
    const ux = (qx - cx) / d;
    const uy = (qy - cy) / d;
    const rot = (ux >= 0 ? 1 : -1) * m * 0.12;
    c.animate(
      [
        { transform: 'none' },
        { transform: `translate(${ux * m}px, ${uy * m}px) rotate(${rot}deg)`, offset: 0.3 },
        { transform: `translate(${-ux * m * 0.25}px, ${-uy * m * 0.25}px)`, offset: 0.65 },
        { transform: 'none' },
      ],
      { duration: 440, easing: 'ease-out' },
    );
  }
  const stamp = card.querySelector<SVGElement>('.card-stamp[data-pending]');
  if (stamp) {
    stamp.removeAttribute('data-pending');
    stamp.animate(
      [
        { opacity: 0, transform: 'rotate(-32deg) scale(2.4)' },
        { opacity: 1, transform: 'rotate(-12deg) scale(.9)', offset: 0.62 },
        { opacity: 1, transform: 'rotate(-14deg) scale(1)' },
      ],
      { duration: 340, delay: 140, easing: 'cubic-bezier(.35,.1,.4,1)', fill: 'backwards' },
    );
    card.animate(
      [{ transform: 'none' }, { transform: 'translateY(2px) scale(.985)' }, { transform: 'none' }],
      { duration: 200, delay: 340, easing: 'ease-out' },
    );
  }
}

