import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import type { NewDesc } from '../../framework/types';
import { encodeDesc, encodeLayout, gridSize } from './board';
import { DIFF_AMBIGUOUS, DIFF_BASIC, DIFF_TRIVIAL, solve } from './solver';

export interface DominosaParams {
  /** Highest number on a domino; the grid is (n+2) × (n+1). */
  n: number;
  /** One of the DIFF_* constants; DIFF_AMBIGUOUS skips the uniqueness check. */
  diff: number;
}

/**
 * Tile a w×h rectangle with dominoes at random. Returns `partner[i]`: the other square
 * of the domino covering square `i` (or `i` itself for the single leftover square when
 * the area is odd).
 *
 * Dominoes are first dropped greedily in a random order, which leaves scattered single
 * squares. Each singleton is then paired off with another by finding a path between
 * them that steps through whole dominoes, and shuffling every domino on that path along
 * by one.
 */
export function dominoLayout(w: number, h: number, rng: Random): Int32Array {
  const wh = w * h;
  const partner = new Int32Array(wh);
  for (let i = 0; i < wh; i++) partner[i] = i;

  const places: number[] = [];
  for (let y = 0; y < h - 1; y++) for (let x = 0; x < w; x++) places.push(2 * (y * w + x));
  for (let y = 0; y < h; y++) for (let x = 0; x < w - 1; x++) places.push(2 * (y * w + x) + 1);
  rng.shuffle(places);
  for (const p of places) {
    const a = p >> 1;
    const b = p & 1 ? a + 1 : a + w;
    if (partner[a] === a && partner[b] === b) {
      partner[a] = b;
      partner[b] = a;
    }
  }

  // `back[k]` records, for the square k adjacent to where the search came from, the
  // square it came from; the search continues from the other end of k's domino.
  const back = new Int32Array(wh);
  const dist = new Int32Array(wh);
  const queue: number[] = [];
  for (;;) {
    let start = -1;
    let singles = 0;
    for (let i = 0; i < wh; i++) {
      if (partner[i] === i) {
        singles++;
        start = i;
      }
    }
    if (singles === wh % 2) break;

    back.fill(-1);
    dist.fill(-1);
    dist[start] = 0;
    queue.length = 0;
    queue.push(start);
    let found = -1;
    let qi = 0;
    while (qi < queue.length && found < 0) {
      const cur = queue[qi++];
      const x = cur % w;
      const y = Math.floor(cur / w);
      const nbrs: number[] = [];
      if (x > 0) nbrs.push(cur - 1);
      if (x + 1 < w) nbrs.push(cur + 1);
      if (y > 0) nbrs.push(cur - w);
      if (y + 1 < h) nbrs.push(cur + w);
      rng.shuffle(nbrs);
      for (const k of nbrs) {
        if (partner[k] === k) {
          back[k] = cur;
          found = k;
          break;
        }
        const m = partner[k];
        if (dist[m] < 0 || dist[m] > dist[cur] + 1) {
          dist[m] = dist[cur] + 1;
          back[k] = cur;
          queue.push(m);
        }
      }
    }
    if (found < 0) throw new Error(tx`domino layout: no path between singletons`);

    // Walk the trail back, re-laying each domino one step along it.
    let i = found;
    for (;;) {
      const j = back[i];
      const k = partner[j];
      partner[i] = j;
      partner[j] = i;
      if (k === j) break;
      i = k;
    }
  }
  return partner;
}

/** Shuffled list of all dominoes with numbers up to n, as [a, b] pairs. */
function shuffledDominoes(n: number, rng: Random): [number, number][] {
  const list: [number, number][] = [];
  for (let i = 0; i <= n; i++) for (let j = 0; j <= i; j++) list.push([i, j]);
  return rng.shuffle(list);
}

/**
 * Write domino numbers onto a layout. When `avoidSwaps` is set, a domino that forms a
 * 2×2 block with an already-numbered parallel neighbour and shares a number with it is
 * turned so the equal numbers sit side by side rather than diagonally, since the
 * diagonal arrangement can always be re-tiled the other way and so ruins uniqueness.
 */
export function numberLayout(
  partner: Int32Array,
  w: number,
  n: number,
  rng: Random,
  avoidSwaps: boolean,
): number[] {
  const wh = partner.length;
  const numbers = new Array<number>(wh).fill(0);
  const dominoes = shuffledDominoes(n, rng);
  let next = 0;
  for (let i = 0; i < wh; i++) {
    const j = partner[i];
    if (j <= i) continue;
    const [p, q] = dominoes[next++];
    let flip = -1;
    if (avoidSwaps) {
      // Neighbouring parallel domino: to the left of a vertical one, above a horizontal.
      const step = j === i + w ? 1 : w;
      const ok = j === i + w ? i % w > 0 : i >= w;
      if (ok && partner[i - step] === j - step) {
        const n1 = numbers[i - step];
        const n2 = numbers[j - step];
        if (n1 === p || n1 === q || n2 === p || n2 === q) flip = n1 === p || n2 === q ? 0 : 1;
      }
    }
    if (flip < 0) flip = rng.upto(2);
    numbers[i] = flip ? q : p;
    numbers[j] = flip ? p : q;
  }
  return numbers;
}

/**
 * The hardest level a set this small can call for. Double-1 (a 3×2 grid) always falls to
 * the trivial rules and double-2 never needs more than the basic ones, so asking for more
 * would send the generator looking for a puzzle that does not exist.
 */
export function maxDifficulty(n: number): number {
  return n <= 1 ? DIFF_TRIVIAL : n === 2 ? DIFF_BASIC : Infinity;
}

/** Generate a puzzle; the aux string is the tiling it was made from. */
export function generate(params: DominosaParams, rng: Random): NewDesc {
  const { n } = params;
  const diff =
    params.diff === DIFF_AMBIGUOUS ? params.diff : Math.min(params.diff, maxDifficulty(n));
  const { w, h } = gridSize(n);
  const unique = diff !== DIFF_AMBIGUOUS;
  for (;;) {
    const partner = dominoLayout(w, h, rng);
    const numbers = numberLayout(partner, w, n, rng, unique);
    if (unique) {
      const r = solve(numbers, n, diff);
      // A puzzle must be solvable by the requested reasoning and, unless it is only meant
      // to be trivial, actually need it.
      if (r.status !== 'solved') continue;
      if (diff > DIFF_TRIVIAL && r.difficulty < diff) continue;
    }
    return { desc: encodeDesc(numbers), aux: encodeLayout(partner, w) };
  }
}
