import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { FifteenState, FifteenUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

function tileCell(state: FifteenState, tile: number) {
  const i = state.tiles.indexOf(tile);
  return { x: i % state.w, y: Math.floor(i / state.w) };
}

export const tutorial: Tutorial<FifteenState, FifteenUI> = {
  steps: [
    {
      gameId: '3x3:1,2,3,4,0,6,7,5,8',
      text: 'Slide the numbered tiles into the empty space until they read **1 to 8** in order, with the gap in the bottom-right corner. This little board is two moves from done.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'Any tile in the same row or column as the gap can slide. Click the **5** to push it up into the gap.',
      highlight: ({ state, tileSize }) => {
        const c = tileCell(state, 5);
        return cellRect(c.x, c.y, tileSize, border(tileSize));
      },
      pointer: ({ state, tileSize }) => {
        const c = tileCell(state, 5);
        return cellCentre(c.x, c.y, tileSize, border(tileSize));
      },
      waitFor: ({ state }) => state.tiles[4] === 5,
    },
    {
      text: 'One more. Click the **8** to finish the row.',
      highlight: ({ state, tileSize }) => {
        const c = tileCell(state, 8);
        return cellRect(c.x, c.y, tileSize, border(tileSize));
      },
      pointer: ({ state, tileSize }) => {
        const c = tileCell(state, 8);
        return cellCentre(c.x, c.y, tileSize, border(tileSize));
      },
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! **Undo** and **Redo** step through your moves, and **New**, in the pause menu, deals a fresh puzzle. The arrow keys slide a tile into the gap too, in the direction of the arrow.',
      textTouch:
        'Solved! **Undo** and **Redo** step through your moves, and **New**, in the pause menu, deals a fresh puzzle. A whole row or column slides at once, so aim for the far tile.',
      target: '[data-cmd="undo"]',
    },
  ],
};
