export interface TracksState {
  w: number;
  h: number;
  layout: Layout;
  board: Board;
  analysis: Analysis;
  completed: boolean;
  usedSolve: boolean;
}

interface Drag {
  /** LEFT_BUTTON or RIGHT_BUTTON. */
  button: number;
  /** Square and pixel where the button went down. */
  sx: number;
  sy: number;
  px: number;
  py: number;
  /** Left drags: squares visited in order. */
  path: number[];
  /** Right drags: the far end of the straight line, and whether it is a real line. */
  ex: number;
  ey: number;
  line: boolean;
  /** A left drag made with the Erase tool: it wipes the squares it passes over. */
  erase: boolean;
}

export interface TracksUI {
  /** Keyboard cursor on the half-size grid: odd/odd is a square, one even is an edge. */
  cx: number;
  cy: number;
  cursorVisible: boolean;
  drag: Drag | null;
  /**
   * The Erase tool: a left click or drag wipes every square it touches — rails, bars,
   * crosses and marks — instead of laying track.
   */
  erase: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_SIDE = 20;
const MOVE_RE = /^([TtNn])([SUDLR])(\d+),(\d+)$/;

interface Geometry {
  t: number;
  pad: number;
  gutter: number;
  gx: number;
  gy: number;
}

export function geometry(t: number): Geometry {
  const pad = Math.round(t * 0.3);
  const gutter = Math.round(t * 0.7);
  return { t, pad, gutter, gx: pad + gutter, gy: pad + gutter };
}

function makeState(layout: Layout, board: Board, usedSolve: boolean): TracksState {
  const analysis = analyse(board);
  return {
    w: layout.w,
    h: layout.h,
    layout,
    board,
    analysis,
    completed: analysis.completed,
    usedSolve,
  };
}

// ------------------------------------------------------------------ move legality

/** An edge touching a given piece is fixed for good. */
function fixedEdge(b: Board, i: number, d: number): boolean {
  const j = b.neighbour(i, d);
  return j < 0 || b.layout.clue[i] !== 0 || b.layout.clue[j] !== 0;
}

function canSetTrack(b: Board, i: number, d: number): boolean {
  const j = b.neighbour(i, d);
  if (j < 0 || fixedEdge(b, i, d)) return false;
  if (b.notrack[i] & d || b.sNotrack[i] || b.sNotrack[j]) return false;
  return NBITS[b.track[i]] < 2 && NBITS[b.track[j]] < 2;
}

function canClearTrack(b: Board, i: number, d: number): boolean {
  return !fixedEdge(b, i, d) && (b.track[i] & d) !== 0;
}

/** Whether a click may toggle the square mark; `notrack` selects the cross. */
function canFlipSquare(b: Board, i: number, notrack: boolean): boolean {
  if (b.layout.clue[i]) return false;
  if (notrack) return b.sNotrack[i] !== 0 || (!b.sTrack[i] && b.track[i] === 0);
  return b.sTrack[i] !== 0 || !b.sNotrack[i];
}

function canFlipEdge(b: Board, i: number, d: number, notrack: boolean): boolean {
  const j = b.neighbour(i, d);
  if (j < 0) return false;
  if (notrack) return (b.notrack[i] & d) !== 0 || !(b.track[i] & d);
  return b.track[i] & d ? canClearTrack(b, i, d) : canSetTrack(b, i, d);
}

function edgeMove(b: Board, i: number, d: number, notrack: boolean): string {
  const on = notrack ? b.notrack[i] & d : b.track[i] & d;
  const c = notrack ? (on ? 'n' : 'N') : on ? 't' : 'T';
  return `${c}${DIR_CHAR[d]}${i % b.w},${Math.floor(i / b.w)}`;
}

function squareMove(b: Board, i: number, notrack: boolean): string {
  const on = notrack ? b.sNotrack[i] : b.sTrack[i];
  const c = notrack ? (on ? 'n' : 'N') : on ? 't' : 'T';
  return `${c}S${i % b.w},${Math.floor(i / b.w)}`;
}

/**
 * The outcome of a drag: the board as it will look and the move that gets there.
 * A left drag lays rails between consecutive squares of its path, or lifts them all
 * when every edge along the path is already track. A right drag toggles "no track"
 * crosses along a straight line, following the first square.
 */
function dragResult(state: TracksState, drag: Drag): { board: Board; move: string } {
  const b = state.board;
  const after = b.clone();
  const parts: string[] = [];
  if (drag.erase) {
    for (const i of drag.path) eraseSquare(b, after, i, parts);
  } else if (drag.button === LEFT_BUTTON) {
    const edges: { i: number; d: number }[] = [];
    for (let k = 1; k < drag.path.length; k++) {
      const a = drag.path[k - 1];
      const c = drag.path[k];
      const ddx = (c % b.w) - (a % b.w);
      const ddy = Math.floor(c / b.w) - Math.floor(a / b.w);
      const d = ddx === 1 ? R : ddx === -1 ? L : ddy === 1 ? D : U;
      edges.push({ i: a, d });
    }
    const lifting = edges.length > 0 && edges.every((e) => b.track[e.i] & e.d);
    for (const e of edges) {
      if (lifting) {
        if (!canClearTrack(after, e.i, e.d)) continue;
        after.clearTrack(e.i, e.d);
        parts.push(edgeMove(b, e.i, e.d, false));
      } else {
        if (after.track[e.i] & e.d || !canSetTrack(after, e.i, e.d)) continue;
        after.setTrack(e.i, e.d);
        parts.push(edgeMove(b, e.i, e.d, false));
      }
    }
  } else {
    const start = drag.sy * b.w + drag.sx;
    const clearing = b.sNotrack[start] !== 0;
    const x1 = Math.min(drag.sx, drag.ex);
    const x2 = Math.max(drag.sx, drag.ex);
    const y1 = Math.min(drag.sy, drag.ey);
    const y2 = Math.max(drag.sy, drag.ey);
    for (let y = y1; y <= y2; y++) {
      for (let x = x1; x <= x2; x++) {
        const i = y * b.w + x;
        if ((b.sNotrack[i] !== 0) !== clearing) continue;
        if (!canFlipSquare(b, i, true)) continue;
        after.sNotrack[i] = clearing ? 0 : 1;
        parts.push(squareMove(b, i, true));
      }
    }
  }
  return { board: after, move: parts.join(';') };
}

/**
 * Wipe square `i` of `after` clean — every rail through it that is not fixed, every "no
 * rail" bar on its sides and its own mark or cross — adding the moves to `parts`.
 */
function eraseSquare(b: Board, after: Board, i: number, parts: string[]): void {
  const x = i % b.w;
  const y = Math.floor(i / b.w);
  for (const d of DIRS) {
    if (canClearTrack(after, i, d)) {
      after.clearTrack(i, d);
      parts.push(`t${DIR_CHAR[d]}${x},${y}`);
    }
    if (after.notrack[i] & d && after.neighbour(i, d) >= 0) {
      after.clearNoTrack(i, d);
      parts.push(`n${DIR_CHAR[d]}${x},${y}`);
    }
  }
  if (b.layout.clue[i]) return;
  if (after.sTrack[i]) {
    after.sTrack[i] = 0;
    parts.push(`tS${x},${y}`);
  }
  if (after.sNotrack[i]) {
    after.sNotrack[i] = 0;
    parts.push(`nS${x},${y}`);
  }
}

/** Extend a left drag's path towards the square now under the pointer. */
function extendPath(b: Board, path: number[], x: number, y: number): void {
  if (!b.inGrid(x, y)) return;
  const target = y * b.w + x;
  const last = path[path.length - 1];
  if (target === last) return;
  const lx = last % b.w;
  const ly = Math.floor(last / b.w);
  if (lx !== x && ly !== y) return; // diagonal jump: wait for a clearer sample
  const sx = Math.sign(x - lx);
  const sy = Math.sign(y - ly);
  let cx = lx;
  let cy = ly;
  // One square at a time, exactly as a slow drag would: stepping back onto the square
  // before the last takes the last one off again, so a fast pointer that jumps back
  // several squares in one sample retracts the path instead of doubling it.
  while (cx !== x || cy !== y) {
    cx += sx;
    cy += sy;
    const i = cy * b.w + cx;
    if (path.length >= 2 && path[path.length - 2] === i) path.pop();
    else path.push(i);
  }
}

/** The move for a click at pixel offset (rx, ry) inside square (x, y). */
function clickMove(
  b: Board,
  x: number,
  y: number,
  rx: number,
  ry: number,
  t: number,
  notrack: boolean,
) {
  const i = y * b.w + x;
  const ox = rx - t / 2;
  const oy = ry - t / 2;
  if (Math.max(Math.abs(ox), Math.abs(oy)) < t / 4) {
    return canFlipSquare(b, i, notrack) ? squareMove(b, i, notrack) : '';
  }
  const d = Math.abs(ox) < Math.abs(oy) ? (oy < 0 ? U : D) : ox < 0 ? L : R;
  return canFlipEdge(b, i, d, notrack) ? edgeMove(b, i, d, notrack) : '';
}

/** The solution's direction bits per square, from `aux` or by solving. */
function findSolution(state: TracksState, aux: string | undefined): Uint8Array | null {
  const { layout } = state;
  if (aux) {
    const track = decodeTrack(aux, layout.n);
    if (track) {
      const b = new Board(layout);
      let ok = true;
      for (let i = 0; i < layout.n; i++) {
        b.track[i] = track[i];
        b.sTrack[i] = track[i] ? 1 : 0;
        if (layout.clue[i] && layout.clue[i] !== track[i]) ok = false;
      }
      if (ok && analyse(b).completed) return track;
    }
  }
  const fromHere = state.board.clone();
  if (solveBoard(fromHere, DIFF_MAX) === 1) return fromHere.track;
  const fresh = boardFromLayout(layout);
  if (solveBoard(fresh, DIFF_MAX) === 1) return fresh.track;
  return null;
}

// ------------------------------------------------------------------ drawing

interface RailOpts {
  seed: number;
  alpha?: number;
}

/**
 * Draw one square's piece: two rails a third of the way in from either side with a few
 * sleepers across them. Straights and quarter-circle curves fill the square; a single
 * rail is drawn from its edge to the centre, ending in a short buffer.
 */
function drawPiece(
  dr: Drawing,
  ox: number,
  oy: number,
  t: number,
  f: number,
  colour: string,
  o: RailOpts,
): void {
  if (!f) return;
  const r1 = t / 3;
  const r2 = (2 * t) / 3;
  const railW = Math.max(1.6, t * 0.085);
  const tieW = Math.max(1, t * 0.045);
  const tie0 = t / 6;
  const tie1 = (5 * t) / 6;
  const rail = { rough: 0.7, alpha: o.alpha, seed: o.seed };
  const tie = (x1: number, y1: number, x2: number, y2: number, k: number) =>
    dr.line(x1, y1, x2, y2, colour, tieW, { rough: 0.5, alpha: o.alpha, seed: o.seed + 10 * k });

  if (f === (L | R)) {
    for (let k = 1; k <= 7; k += 2)
      tie(ox + (t * k) / 8, oy + tie0, ox + (t * k) / 8, oy + tie1, k);
    dr.line(ox, oy + r1, ox + t, oy + r1, colour, railW, rail);
    dr.line(ox, oy + r2, ox + t, oy + r2, colour, railW, rail);
    return;
  }
  if (f === (U | D)) {
    for (let k = 1; k <= 7; k += 2)
      tie(ox + tie0, oy + (t * k) / 8, ox + tie1, oy + (t * k) / 8, k);
    dr.line(ox + r1, oy, ox + r1, oy + t, colour, railW, rail);
    dr.line(ox + r2, oy, ox + r2, oy + t, colour, railW, rail);
    return;
  }
  if (NBITS[f] === 2) {
    // A curve: quarter circles around the corner between its two sides.
    const cx = f & L ? ox : ox + t;
    const cy = f & U ? oy : oy + t;
    const a0 = f & L ? (f & U ? 0 : 1.5 * Math.PI) : f & U ? 0.5 * Math.PI : Math.PI;
    for (let k = 0; k < 3; k++) {
      const th = a0 + Math.PI / 12 + (k * Math.PI) / 6;
      const c = Math.cos(th);
      const s = Math.sin(th);
      tie(cx + tie0 * c, cy + tie0 * s, cx + tie1 * c, cy + tie1 * s, k);
    }
    for (const r of [r1, r2]) {
      const pts: number[] = [];
      const steps = 8;
      for (let s = 0; s <= steps; s++) {
        const th = a0 + (s * Math.PI) / 2 / steps;
        pts.push(cx + r * Math.cos(th), cy + r * Math.sin(th));
      }
      dr.polyline(pts, colour, railW, { rough: 0.35, alpha: o.alpha, seed: o.seed + r });
    }
    return;
  }
  // Loose rails: each runs from its side to the middle of the square.
  const mx = ox + t / 2;
  const my = oy + t / 2;
  for (const d of DIRS) {
    if (!(f & d)) continue;
    if (d === L || d === R) {
      const ex = d === L ? ox : ox + t;
      const tx = d === L ? ox + t / 4 : ox + (3 * t) / 4;
      tie(tx, oy + tie0, tx, oy + tie1, d);
      tie(mx, oy + t / 4, mx, oy + (3 * t) / 4, d + 4);
      dr.line(ex, oy + r1, mx, oy + r1, colour, railW, rail);
      dr.line(ex, oy + r2, mx, oy + r2, colour, railW, rail);
    } else {
      const ey = d === U ? oy : oy + t;
      const ty = d === U ? oy + t / 4 : oy + (3 * t) / 4;
      tie(ox + tie0, ty, ox + tie1, ty, d);
      tie(ox + t / 4, my, ox + (3 * t) / 4, my, d + 4);
      dr.line(ox + r1, ey, ox + r1, my, colour, railW, rail);
      dr.line(ox + r2, ey, ox + r2, my, colour, railW, rail);
    }
  }
}

/** Colour of a square's piece: given pieces (and rails fixed by them) in ink, the rest blue. */
function pieceColour(b: Board, i: number, error: boolean, flash: boolean): string {
  if (flash) return 'ok';
  if (error) return 'error';
  if (b.layout.clue[i]) return 'ink';
  let fixed = b.track[i] !== 0;
  for (const d of DIRS) if (b.track[i] & d && !fixedEdge(b, i, d)) fixed = false;
  return fixed ? 'ink' : 'blue';
}

// ------------------------------------------------------------------ the game

/** The Type menu: width, height and difficulty. */
const PRESET_SIZES: [number, number, number][] = [
  [8, 8, 0],
  [8, 8, 1],
  [10, 8, 0],
  [10, 8, 1],
  [10, 10, 0],
  [10, 10, 1],
  [15, 10, 0],
  [15, 10, 1],
  [15, 15, 0],
  [15, 15, 1],
];

const game = defineGame<TracksParams, TracksState, TracksUI>({
  id: 'tracks',
  name: 'Tracks',
  description: 'Lay a single railway from the entrance to the exit, matching the counts.',
  alsoKnownAs: 'Train Tracks',
  help,
  tutorial,
  achievements,
  presets: PRESET_SIZES.map(([w, h, diff]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[diff]}`,
    params: { w, h, diff, singleOnes: true },
  })),
  // The gentlest 8×8 the Type menu offers, rather than the original's Tricky.
  defaultParams: () => ({ w: 8, h: 8, diff: DIFF_EASY, singleOnes: true }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${full ? `d${DIFFICULTY_CHARS[p.diff]}${p.singleOnes ? '' : 'o'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d([a-z]?))?(o)?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    // A descriptive ID (a share link) carries only the size. Read it as the first preset
    // of that size — the one the Type menu then shows — so New deals what the menu says;
    // other sizes keep the original's Tricky.
    let diff = PRESET_SIZES.find(([pw, ph]) => pw === w && ph === h)?.[2] ?? DIFF_TRICKY;
    if (m[3] !== undefined) {
      const k = DIFFICULTY_CHARS.indexOf(m[3]);
      if (k >= 0 && m[3]) diff = k;
    }
    return { w, h, diff, singleOnes: m[4] !== 'o' };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 4 || p.h < 4) return tx`Width and height must both be at least four`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && (!Number.isInteger(p.diff) || p.diff < 0 || p.diff > DIFF_MAX))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.diff },
      { type: 'boolean', name: 'Disallow consecutive 1 clues', value: p.singleOnes },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    const int = (s: string) => (/^-?\d+$/.test(s) ? parseInt(s, 10) : NaN);
    return {
      w: int(str(0)),
      h: int(str(1)),
      diff: (items[2] as { selected: number }).selected,
      singleOnes: (items[3] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const layout = parseDesc(desc, p.w, p.h) as Layout;
    return { ...makeState(layout, boardFromLayout(layout), false), completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const sol = findSolution(curr, aux);
    if (!sol) throw new Error(tx`Unable to find a solution to this puzzle`);
    const b = curr.board;
    const { w, n, clue } = curr.layout;
    const parts = ['S'];
    for (let i = 0; i < n; i++) {
      const x = i % w;
      const y = Math.floor(i / w);
      for (const d of [R, D]) {
        const j = b.neighbour(i, d);
        if (j < 0) continue;
        const want = (sol[i] & d) !== 0;
        const have = (b.track[i] & d) !== 0;
        if (want !== have && !fixedEdge(b, i, d))
          parts.push(`${want ? 'T' : 't'}${DIR_CHAR[d]}${x},${y}`);
        if (want && b.notrack[i] & d) parts.push(`n${DIR_CHAR[d]}${x},${y}`);
      }
      if (b.sTrack[i] && !sol[i] && !clue[i]) parts.push(`tS${x},${y}`);
      if (b.sNotrack[i] && sol[i]) parts.push(`nS${x},${y}`);
    }
    return parts.join(';');
  },

  textFormat(s) {
    const { w, h, layout, board } = s;
    const rows: string[] = [];
    let top = '  ';
    for (let x = 0; x < w; x++) top += layout.numbers[x].toString(36).toUpperCase();
    rows.push(top);
    for (let y = 0; y < h; y++) {
      let row = y === layout.rowS ? '=' : ' ';
      row += '|';
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const f = board.track[i];
        row +=
          f === (L | R)
            ? '-'
            : f === (U | D)
              ? '|'
              : f === (L | U) || f === (R | D)
                ? '/'
                : f === (L | D) || f === (R | U)
                  ? '\\'
                  : f
                    ? '+'
                    : board.sNotrack[i]
                      ? 'x'
                      : board.sTrack[i]
                        ? 'o'
                        : ' ';
      }
      row += '|' + layout.numbers[w + y].toString(36).toUpperCase();
      rows.push(row);
    }
    rows.push('  ' + ' '.repeat(layout.colS) + '"');
    return rows.join('\n');
  },

  actions: [
    {
      label: 'Erase',
      key: 'E',
      hud: true,
      glyph: ERASE_GLYPH,
      pressed: (_s, ui) => ui.erase,
      title: 'Click or drag to wipe squares clean (E)',
    },
  ],

  newUI: () => ({ cx: 1, cy: 1, cursorVisible: false, drag: null, erase: false }),
  changedState(ui, _old, next) {
    if (next.completed) ui.cursorVisible = false;
    // A drag still held when Solve, Undo or a key changes the board would otherwise be laid
    // on the new board at release — over a solved railway, say.
    ui.drag = null;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, board } = state;
    const g = geometry(ds.tileSize);
    const t = g.t;
    const cx = Math.floor((mx - g.gx) / t);
    const cy = Math.floor((my - g.gy) / t);
    const inside = board.inGrid(cx, cy);
    const ch = keyChar(b);

    if (ch === 'e' || ch === 'E') {
      ui.erase = !ui.erase;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const redraw = ui.cursorVisible || ui.drag !== null;
      ui.cursorVisible = false;
      ui.drag = null;
      if (!inside) return redraw ? '' : null;
      ui.drag = {
        button: b,
        sx: cx,
        sy: cy,
        px: mx,
        py: my,
        path: [cy * w + cx],
        ex: cx,
        ey: cy,
        line: false,
        erase: ui.erase && b === LEFT_BUTTON,
      };
      return '';
    }
    if (b === LEFT_DRAG || b === RIGHT_DRAG) {
      const drag = ui.drag;
      if (!drag || drag.button !== b - (LEFT_DRAG - LEFT_BUTTON)) return null;
      if (b === LEFT_DRAG) {
        extendPath(board, drag.path, cx, cy);
      } else if (cy === drag.sy) {
        drag.ex = clamp(cx, 0, w - 1);
        drag.ey = drag.sy;
        drag.line = true;
      } else if (cx === drag.sx) {
        drag.ex = drag.sx;
        drag.ey = clamp(cy, 0, h - 1);
        drag.line = true;
      } else {
        drag.ex = drag.sx;
        drag.ey = drag.sy;
        drag.line = false;
      }
      return '';
    }
    if (b === LEFT_RELEASE || b === RIGHT_RELEASE) {
      const drag = ui.drag;
      if (!drag || drag.button !== b - (LEFT_RELEASE - LEFT_BUTTON)) return null;
      ui.drag = null;
      // The eraser wipes the square it was clicked on, or every square it was dragged over.
      if (drag.erase) return dragResult(state, drag).move;
      const dragged =
        drag.button === LEFT_BUTTON
          ? drag.path.length > 1
          : drag.line && (drag.ex !== drag.sx || drag.ey !== drag.sy);
      if (dragged) return dragResult(state, drag).move;
      // A click acts where the button went down.
      const rx = drag.px - (g.gx + drag.sx * t);
      const ry = drag.py - (g.gy + drag.sy * t);
      return clickMove(board, drag.sx, drag.sy, rx, ry, t, drag.button === RIGHT_BUTTON);
    }

    if (isCursorMove(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const ddx = b === CURSOR_LEFT ? -1 : b === CURSOR_RIGHT ? 1 : 0;
      const ddy = b === CURSOR_UP ? -1 : b === CURSOR_DOWN ? 1 : 0;
      ui.cx += ddx;
      ui.cy += ddy;
      if (ui.cx % 2 === 0 && ui.cy % 2 === 0) {
        // Corners are not positions: step on to the next edge or square.
        ui.cx += ddx;
        ui.cy += ddy;
      }
      ui.cx = clamp(ui.cx, 1, 2 * w - 1);
      ui.cy = clamp(ui.cy, 1, 2 * h - 1);
      return '';
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const notrack = b === CURSOR_SELECT2;
      const x = ui.cx >> 1;
      const y = ui.cy >> 1;
      if (ui.erase && !notrack) {
        // Enter is a click, and a click with the eraser lit wipes: the square under the
        // cursor, or the rail and bar on the side it stands on.
        const i = y * w + x;
        const parts: string[] = [];
        if (ui.cx % 2 && ui.cy % 2) eraseSquare(board, board.clone(), i, parts);
        else {
          const d = ui.cx % 2 === 0 ? L : U;
          const c = `${DIR_CHAR[d]}${x},${y}`;
          if (canClearTrack(board, i, d)) parts.push(`t${c}`);
          if (board.notrack[i] & d) parts.push(`n${c}`);
        }
        return parts.join(';');
      }
      if (ui.cx % 2 === 0) {
        // On a vertical edge: it belongs to the square on its right as its left side.
        const i = y * w + x;
        return canFlipEdge(board, i, L, notrack) ? edgeMove(board, i, L, notrack) : '';
      }
      if (ui.cy % 2 === 0) {
        const i = y * w + x;
        return canFlipEdge(board, i, U, notrack) ? edgeMove(board, i, U, notrack) : '';
      }
      const i = y * w + x;
      return canFlipSquare(board, i, notrack) ? squareMove(board, i, notrack) : '';
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { layout } = state;
    const board = state.board.clone();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = MOVE_RE.exec(part);
      if (!m) return null;
      const x = parseInt(m[3], 10);
      const y = parseInt(m[4], 10);
      if (!board.inGrid(x, y)) return null;
      const i = y * layout.w + x;
      const on = m[1] === 'T' || m[1] === 'N';
      const isTrack = m[1] === 'T' || m[1] === 't';
      if (m[2] === 'S') {
        if (layout.clue[i]) return null;
        (isTrack ? board.sTrack : board.sNotrack)[i] = on ? 1 : 0;
        continue;
      }
      const d = dirOf(m[2]);
      const j = board.neighbour(i, d);
      if (j < 0) return null;
      if (isTrack) {
        if (layout.clue[i] || layout.clue[j]) return null;
        if (on) board.setTrack(i, d);
        else board.clearTrack(i, d);
      } else if (on) board.setNoTrack(i, d);
      else board.clearNoTrack(i, d);
    }
    return makeState(layout, board, usedSolve);
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const g = geometry(t);
    return { w: p.w * t + 2 * g.gx, h: p.h * t + 2 * g.gy };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, h, layout, analysis } = state;
    const g = geometry(ds.tileSize);
    const t = g.t;
    const flash = flashOn(flashTime, FLASH_FRAME);
    const before = state.board;
    const preview = ui.drag ? dragResult(state, ui.drag) : null;
    const view = preview ? preview.board : before;

    dr.rect(g.gx, g.gy, w * t, h * t, flash ? 'shade' : 'paper');

    // Washes under the pieces, then the faint grid, then the rails on top of both.
    const playerWash = dr.withAlpha('blue', 0.09);
    const errorWash = dr.withAlpha('error', 0.14);
    for (let i = 0; i < layout.n; i++) {
      const px = g.gx + (i % w) * t;
      const py = g.gy + Math.floor(i / w) * t;
      if (layout.clue[i]) dr.rect(px, py, t, t, 'shade');
      else if (!flash && analysis.cellError[i]) dr.rect(px, py, t, t, errorWash);
      else if (!flash && view.hasTrack(i)) dr.rect(px, py, t, t, playerWash);
    }
    for (let x = 1; x < w; x++)
      dr.line(g.gx + x * t, g.gy, g.gx + x * t, g.gy + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++)
      dr.line(g.gx, g.gy + y * t, g.gx + w * t, g.gy + y * t, 'faint', 1.2);

    // A rail the player has just laid is inked in rather than simply being there, and one
    // they have lifted fades off the paper. A piece is a sleeper-and-rail drawing that
    // spans the whole square, so it arrives by being inked rather than by growing out of
    // the middle the way a bare pencil line does.
    const laying = oldState && !preview ? changedAt(oldState.board.track, before.track) : null;
    const ink = drawGrow(animTime);

    for (let i = 0; i < layout.n; i++) {
      const px = g.gx + (i % w) * t;
      const py = g.gy + Math.floor(i / w) * t;
      const f = view.track[i];
      const was = before.track[i];
      if (laying?.includes(i)) {
        const colour = pieceColour(before, i, analysis.cellError[i] === 1, flash);
        const gone = oldState!.board.track[i];
        if (gone) drawPiece(dr, px, py, t, gone, colour, { seed: i, alpha: 1 - ink });
        if (f) drawPiece(dr, px, py, t, f, colour, { seed: i, alpha: ink });
      } else if (preview && f !== was) {
        if (NBITS[f] < NBITS[was]) {
          // Rails being lifted fade out; whatever remains is drawn normally.
          drawPiece(dr, px, py, t, was, 'pencil', { seed: i, alpha: 0.45 });
          drawPiece(dr, px, py, t, f, pieceColour(view, i, false, false), { seed: i });
        } else {
          drawPiece(dr, px, py, t, f, 'blue', { seed: i, alpha: 0.7 });
        }
      } else {
        drawPiece(dr, px, py, t, f, pieceColour(before, i, analysis.cellError[i] === 1, flash), {
          seed: i,
        });
      }
    }

    // "No track" marks: a cross in the square, a short bar across a blocked side.
    const crossW = Math.max(1.3, t * 0.045);
    for (let i = 0; i < layout.n; i++) {
      const px = g.gx + (i % w) * t;
      const py = g.gy + Math.floor(i / w) * t;
      if (view.sNotrack[i]) {
        const pending = preview && view.sNotrack[i] !== before.sNotrack[i];
        dr.cross(px + t / 2, py + t / 2, t * 0.16, 'pencil', crossW, {
          seed: i,
          alpha: pending ? 0.6 : 1,
        });
      } else if (preview && before.sNotrack[i]) {
        dr.cross(px + t / 2, py + t / 2, t * 0.16, 'pencil', crossW, { seed: i, alpha: 0.3 });
      }
      const nf = view.notrack[i] & ALL;
      // Each interior edge is drawn once, from the square on its left or above.
      for (const d of [R, D]) {
        if (!(nf & d) || view.neighbour(i, d) < 0) continue;
        const ex = px + (d === R ? t : t / 2);
        const ey = py + (d === D ? t : t / 2);
        const half = t * 0.17;
        const bw = Math.max(2, t * 0.09);
        if (d === R) dr.line(ex, ey - half, ex, ey + half, 'pencil', bw, { seed: i + 3 });
        else dr.line(ex - half, ey, ex + half, ey, 'pencil', bw, { seed: i + 5 });
      }
    }

    dr.rectOutline(g.gx, g.gy, w * t, h * t, 'ink', { width: 2.6 });

    // Entrance and exit: rails running off the grid.
    const stubColour = flash ? 'ok' : 'ink';
    const stub = g.gutter * 0.75;
    const railW = Math.max(1.6, t * 0.085);
    const rail = { rough: 0.6, seed: 99 };
    const ey = g.gy + layout.rowS * t;
    dr.line(g.gx - stub, ey + t / 3, g.gx, ey + t / 3, stubColour, railW, rail);
    dr.line(g.gx - stub, ey + (2 * t) / 3, g.gx, ey + (2 * t) / 3, stubColour, railW, rail);
    dr.line(
      g.gx - stub * 0.55,
      ey + t / 6,
      g.gx - stub * 0.55,
      ey + (5 * t) / 6,
      stubColour,
      railW * 0.55,
      rail,
    );
    const ex = g.gx + layout.colS * t;
    const by = g.gy + h * t;
    dr.line(ex + t / 3, by, ex + t / 3, by + stub, stubColour, railW, rail);
    dr.line(ex + (2 * t) / 3, by, ex + (2 * t) / 3, by + stub, stubColour, railW, rail);
    dr.line(
      ex + t / 6,
      by + stub * 0.55,
      ex + (5 * t) / 6,
      by + stub * 0.55,
      stubColour,
      railW * 0.55,
      rail,
    );

    // Counts: above each column and to the right of each row.
    for (let ln = 0; ln < w + h; ln++) {
      const colour = flash
        ? 'ok'
        : analysis.lineError[ln]
          ? 'error'
          : analysis.lineDone[ln]
            ? 'pencil'
            : 'ink';
      const x = ln < w ? g.gx + ln * t + t / 2 : g.gx + w * t + g.gutter / 2;
      const y = ln < w ? g.gy - g.gutter / 2 : g.gy + (ln - w) * t + t / 2;
      dr.text(x, y, String(layout.numbers[ln]), { size: t * 0.5, colour });
    }

    if (ui.cursorVisible) {
      const x = g.gx + (ui.cx >> 1) * t;
      const y = g.gy + (ui.cy >> 1) * t;
      const across = t * 0.3;
      const along = t * 0.64;
      if (ui.cx % 2 === 0) {
        dr.cursor(x - across / 2, y + (t - along) / 2, across, along);
      } else if (ui.cy % 2 === 0) {
        dr.cursor(x + (t - along) / 2, y - across / 2, along, across);
      } else {
        const inset = t * 0.12;
        dr.cursor(x + inset, y + inset, t - 2 * inset, t - 2 * inset);
      }
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.board.track, newState.board.track) ? DRAW_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !newState.usedSolve ? FLASH : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
});

export default game;
