/**
 * Dominosa solver. Works on the set of *placements* (see board.ts): every placement is
 * either still possible, ruled out, or definitely part of the tiling. Deductions are
 * graded so the generator can ask for puzzles of a particular difficulty:
 *
 * - Trivial: a domino with a single possible placement goes there; a square with a
 *   single possible placement must be covered by it.
 * - Basic: every placement of a square is for the same domino, so that domino cannot go
 *   anywhere else; every placement of a domino overlaps some placement P, so P is out.
 * - Hard: parity (a placement that would cut off an odd number of squares is out) and
 *   set analysis on the squares carrying one number (k of them that between them can
 *   only take k dominoes' worth of coverage claim those dominoes).
 * - Extreme: try a placement, follow the Trivial consequences, and rule it out when they
 *   collide.
 *
 * Anything beyond that is `Ambiguous`: the generator does not check uniqueness at all
 * and Solve falls back to a backtracking search.
 */
import {
  dominoCount,
  dominoIndex,
  gridSize,
  placementSquares,
  placementValid,
  placementsAt,
} from './board';

export const DIFF_TRIVIAL = 0;
export const DIFF_BASIC = 1;
export const DIFF_HARD = 2;
export const DIFF_EXTREME = 3;
export const DIFF_AMBIGUOUS = 4;
/** The Custom dialog's words, on the same ladder as every other game's difficulty. */
export const DIFFICULTY_NAMES = ['Very Easy', 'Easy', 'Hard', 'Extreme', 'Ambiguous'];
/** Letters used after `d` in a parameter string, indexed by difficulty. */
export const DIFFICULTY_LETTERS = 'tbhea';

export type SolveStatus = 'solved' | 'stuck' | 'impossible';

export interface SolveResult {
  status: SolveStatus;
  /** The hardest kind of deduction that was needed (-1 when nothing was needed). */
  difficulty: number;
  /** Placements that are definitely part of the tiling. */
  placed: Uint8Array;
  /** Placements still considered possible (includes the placed ones). */
  active: Uint8Array;
}

/** Static facts about a puzzle, shared between a solver and its clones. */
interface Static {
  n: number;
  w: number;
  h: number;
  wh: number;
  np: number;
  dc: number;
  numbers: ArrayLike<number>;
  /** Domino index of each placement, -1 when the placement is off the grid. */
  dominoOf: Int16Array;
  domPlacements: number[][];
  sqPlacements: number[][];
  /** Other placements sharing a square with each placement. */
  overlaps: number[][];
}

function buildStatic(numbers: ArrayLike<number>, n: number): Static {
  const { w, h } = gridSize(n);
  const wh = w * h;
  const np = 2 * wh;
  const dc = dominoCount(n);
  const dominoOf = new Int16Array(np).fill(-1);
  const domPlacements: number[][] = Array.from({ length: dc }, () => []);
  const sqPlacements: number[][] = [];
  for (let s = 0; s < wh; s++) sqPlacements.push(placementsAt(s, w, h));
  for (let p = 0; p < np; p++) {
    if (!placementValid(p, w, h)) continue;
    const [a, b] = placementSquares(p, w);
    const d = dominoIndex(numbers[a], numbers[b]);
    dominoOf[p] = d;
    domPlacements[d].push(p);
  }
  const overlaps: number[][] = [];
  for (let p = 0; p < np; p++) {
    const list: number[] = [];
    if (dominoOf[p] >= 0) {
      const [a, b] = placementSquares(p, w);
      for (const q of sqPlacements[a]) if (q !== p) list.push(q);
      for (const q of sqPlacements[b]) if (q !== p) list.push(q);
    }
    overlaps.push(list);
  }
  return { n, w, h, wh, np, dc, numbers, dominoOf, domPlacements, sqPlacements, overlaps };
}

export class Solver {
  readonly st: Static;
  active: Uint8Array;
  placed: Uint8Array;
  covered: Uint8Array;
  domDone: Uint8Array;
  nPlaced = 0;
  contradiction = false;
  difficulty = -1;

  constructor(numbers: ArrayLike<number>, n: number, st?: Static) {
    this.st = st ?? buildStatic(numbers, n);
    const { np, wh, dc, dominoOf } = this.st;
    this.active = new Uint8Array(np);
    for (let p = 0; p < np; p++) this.active[p] = dominoOf[p] >= 0 ? 1 : 0;
    this.placed = new Uint8Array(np);
    this.covered = new Uint8Array(wh);
    this.domDone = new Uint8Array(dc);
  }

  clone(): Solver {
    const c = new Solver(this.st.numbers, this.st.n, this.st);
    c.active.set(this.active);
    c.placed.set(this.placed);
    c.covered.set(this.covered);
    c.domDone.set(this.domDone);
    c.nPlaced = this.nPlaced;
    c.contradiction = this.contradiction;
    c.difficulty = this.difficulty;
    return c;
  }

  ruleOut(p: number): void {
    if (!this.active[p]) return;
    if (this.placed[p]) {
      this.contradiction = true;
      return;
    }
    this.active[p] = 0;
  }

  place(p: number): void {
    if (this.placed[p]) return;
    if (!this.active[p]) {
      this.contradiction = true;
      return;
    }
    const { w, dominoOf, domPlacements, overlaps } = this.st;
    this.placed[p] = 1;
    this.nPlaced++;
    const [a, b] = placementSquares(p, w);
    this.covered[a] = this.covered[b] = 1;
    const d = dominoOf[p];
    if (this.domDone[d]) this.contradiction = true;
    this.domDone[d] = 1;
    for (const q of domPlacements[d]) if (q !== p) this.ruleOut(q);
    for (const q of overlaps[p]) this.ruleOut(q);
  }

  /** Active placements of a domino. */
  private activeOf(d: number): number[] {
    const out: number[] = [];
    for (const p of this.st.domPlacements[d]) if (this.active[p]) out.push(p);
    return out;
  }

  /** Active placements involving a square. */
  private activeAt(s: number): number[] {
    const out: number[] = [];
    for (const p of this.st.sqPlacements[s]) if (this.active[p]) out.push(p);
    return out;
  }

  // ------------------------------------------------------------------ Trivial

  private trivial(): boolean {
    const { dc, wh } = this.st;
    let changed = false;
    for (let d = 0; d < dc && !this.contradiction; d++) {
      if (this.domDone[d]) continue;
      const list = this.activeOf(d);
      if (list.length === 0) this.contradiction = true;
      else if (list.length === 1) {
        this.place(list[0]);
        changed = true;
      }
    }
    for (let s = 0; s < wh && !this.contradiction; s++) {
      if (this.covered[s]) continue;
      const list = this.activeAt(s);
      if (list.length === 0) this.contradiction = true;
      else if (list.length === 1) {
        this.place(list[0]);
        changed = true;
      }
    }
    return changed;
  }

  // ------------------------------------------------------------------ Basic

  private basic(): boolean {
    const { dc, wh, w, dominoOf, domPlacements, overlaps } = this.st;
    let changed = false;
    // Every placement at a square is the same domino: that domino cannot go elsewhere.
    for (let s = 0; s < wh && !this.contradiction; s++) {
      if (this.covered[s]) continue;
      const list = this.activeAt(s);
      if (list.length < 2) continue;
      const d = dominoOf[list[0]];
      if (!list.every((p) => dominoOf[p] === d)) continue;
      for (const q of domPlacements[d]) {
        if (!this.active[q]) continue;
        const [a, b] = placementSquares(q, w);
        if (a !== s && b !== s) {
          this.ruleOut(q);
          changed = true;
        }
      }
    }
    // Every placement of a domino overlaps placement P: P is impossible.
    for (let d = 0; d < dc && !this.contradiction; d++) {
      if (this.domDone[d]) continue;
      const list = this.activeOf(d);
      if (list.length < 2) continue;
      let common = overlaps[list[0]];
      for (let i = 1; i < list.length && common.length; i++) {
        const other = overlaps[list[i]];
        common = common.filter((q) => other.includes(q));
      }
      for (const q of common) {
        if (this.active[q]) {
          this.ruleOut(q);
          changed = true;
        }
      }
    }
    return changed;
  }

  // ------------------------------------------------------------------ Hard

  /**
   * Sizes of the connected components of the uncovered squares (joined by active
   * placements) when the squares flagged in `skip` are removed. Returns false as soon
   * as an odd component is found.
   */
  private componentsEven(skip: Uint8Array | null, seen: Int32Array, stamp: number): boolean {
    const { wh, w, sqPlacements } = this.st;
    const queue: number[] = [];
    for (let s = 0; s < wh; s++) {
      if (this.covered[s] || seen[s] === stamp || (skip && skip[s])) continue;
      seen[s] = stamp;
      queue.length = 0;
      queue.push(s);
      let size = 0;
      while (queue.length) {
        const cur = queue.pop()!;
        size++;
        for (const p of sqPlacements[cur]) {
          if (!this.active[p]) continue;
          const [a, b] = placementSquares(p, w);
          const nb = a === cur ? b : a;
          if (seen[nb] === stamp || this.covered[nb] || (skip && skip[nb])) continue;
          seen[nb] = stamp;
          queue.push(nb);
        }
      }
      if (size & 1) return false;
    }
    return true;
  }

  private parity(): boolean {
    const { wh, np, w } = this.st;
    const seen = new Int32Array(wh);
    let stamp = 1;
    if (!this.componentsEven(null, seen, stamp++)) {
      this.contradiction = true;
      return false;
    }
    let changed = false;
    const skip = new Uint8Array(wh);
    for (let p = 0; p < np; p++) {
      if (!this.active[p] || this.placed[p]) continue;
      const [a, b] = placementSquares(p, w);
      skip[a] = skip[b] = 1;
      const ok = this.componentsEven(skip, seen, stamp++);
      skip[a] = skip[b] = 0;
      if (!ok) {
        this.ruleOut(p);
        changed = true;
      }
    }
    return changed;
  }

  private numberSets(): boolean {
    const { n, wh, w, numbers, dominoOf, domPlacements, sqPlacements } = this.st;
    let changed = false;
    const inSet = new Uint8Array(wh);
    const cap = new Uint8Array(this.st.dc);
    const touched: number[] = [];
    for (let v = 0; v <= n && !this.contradiction; v++) {
      const squares: number[] = [];
      for (let s = 0; s < wh; s++) if (!this.covered[s] && numbers[s] === v) squares.push(s);
      const m = squares.length;
      if (m < 2) continue;
      // Every proper, non-empty subset of the squares showing v.
      for (let mask = 1; mask < (1 << m) - 1 && !this.contradiction; mask++) {
        let k = 0;
        for (let i = 0; i < m; i++) {
          if (mask & (1 << i)) {
            inSet[squares[i]] = 1;
            k++;
          }
        }
        // Each domino can cover at most one of these squares, or two if it is the
        // double and can lie entirely inside the subset.
        let total = 0;
        for (let i = 0; i < m; i++) {
          if (!(mask & (1 << i))) continue;
          const s = squares[i];
          for (const p of sqPlacements[s]) {
            if (!this.active[p]) continue;
            const [a, b] = placementSquares(p, w);
            const other = a === s ? b : a;
            const c = inSet[other] ? 2 : 1;
            const d = dominoOf[p];
            if (cap[d] === 0) touched.push(d);
            if (cap[d] < c) {
              total += c - cap[d];
              cap[d] = c;
            }
          }
        }
        if (total < k) this.contradiction = true;
        else if (total === k) {
          // These dominoes are all spoken for: they cannot cover squares outside the set.
          for (const d of touched) {
            for (const q of domPlacements[d]) {
              if (!this.active[q]) continue;
              const [a, b] = placementSquares(q, w);
              if (inSet[a] + inSet[b] < cap[d]) {
                this.ruleOut(q);
                changed = true;
              }
            }
          }
        }
        for (const d of touched) cap[d] = 0;
        touched.length = 0;
        for (let i = 0; i < m; i++) inSet[squares[i]] = 0;
      }
    }
    return changed;
  }

  private hard(): boolean {
    if (this.parity()) return true;
    if (this.contradiction) return false;
    return this.numberSets();
  }

  // ------------------------------------------------------------------ Extreme

  private extreme(): boolean {
    const { np } = this.st;
    let changed = false;
    for (let p = 0; p < np && !this.contradiction; p++) {
      if (!this.active[p] || this.placed[p]) continue;
      const trial = this.clone();
      trial.place(p);
      while (!trial.contradiction && trial.nPlaced < trial.st.dc && trial.trivial());
      if (trial.contradiction) {
        this.ruleOut(p);
        changed = true;
      }
    }
    return changed;
  }

  // ------------------------------------------------------------------ driver

  /** Deduce as much as possible using deductions up to `maxDiff`. */
  run(maxDiff: number): SolveStatus {
    for (;;) {
      if (this.contradiction) return 'impossible';
      if (this.nPlaced === this.st.dc) return 'solved';
      if (this.trivial()) {
        this.difficulty = Math.max(this.difficulty, DIFF_TRIVIAL);
        continue;
      }
      if (this.contradiction) return 'impossible';
      if (maxDiff >= DIFF_BASIC && this.basic()) {
        this.difficulty = Math.max(this.difficulty, DIFF_BASIC);
        continue;
      }
      if (this.contradiction) return 'impossible';
      if (maxDiff >= DIFF_HARD && this.hard()) {
        this.difficulty = Math.max(this.difficulty, DIFF_HARD);
        continue;
      }
      if (this.contradiction) return 'impossible';
      if (maxDiff >= DIFF_EXTREME && this.extreme()) {
        this.difficulty = Math.max(this.difficulty, DIFF_EXTREME);
        continue;
      }
      return this.contradiction ? 'impossible' : 'stuck';
    }
  }
}

/** Solve a puzzle by deduction alone, using deductions up to `maxDiff`. */
export function solve(numbers: ArrayLike<number>, n: number, maxDiff: number): SolveResult {
  const s = new Solver(numbers, n);
  const status = s.run(maxDiff);
  return { status, difficulty: s.difficulty, placed: s.placed, active: s.active };
}

/**
 * Find up to `limit` tilings by deduction plus backtracking. Each solution is the list
 * of its placements.
 */
export function search(numbers: ArrayLike<number>, n: number, limit: number): number[][] {
  const results: number[][] = [];
  const root = new Solver(numbers, n);
  const recurse = (s: Solver) => {
    const status = s.run(DIFF_EXTREME);
    if (status === 'impossible') return;
    if (status === 'solved') {
      const sol: number[] = [];
      for (let p = 0; p < s.st.np; p++) if (s.placed[p]) sol.push(p);
      results.push(sol);
      return;
    }
    // Guess at the bare square with the fewest options.
    let best = -1;
    let bestList: number[] = [];
    for (let sq = 0; sq < s.st.wh; sq++) {
      if (s.covered[sq]) continue;
      const list = s.st.sqPlacements[sq].filter((p) => s.active[p]);
      if (best < 0 || list.length < bestList.length) {
        best = sq;
        bestList = list;
      }
    }
    for (const p of bestList) {
      if (results.length >= limit) return;
      const child = s.clone();
      child.place(p);
      recurse(child);
    }
  };
  recurse(root);
  return results;
}
