/**
 * The badge every achievement is drawn on.
 *
 * An achievement brings only its motif (`BadgeArt`, SVG in a 100×100 box); the frame is
 * the same for all of them so a shelf of a hundred reads as one set: a paper sticker with
 * a thick ink edge, tinted by the achievement's hue, ringed in its tier's colour — brown
 * for bronze, pencil grey for silver, yellow for gold, which also earns a pair of
 * sparkles — and the whole thing pushed through a small displacement filter so the ruler-
 * straight SVG wobbles like the sketched strokes on the boards (`framework/drawing`).
 *
 * Returned as a string because it goes to three places that each want it differently: the
 * Achievements page, the unlock toast, and the store-art scripts.
 */
import type { AchievementTier, BadgeArt } from '../framework/achievements';
import { mix, PALETTE, type PaletteToken } from '../framework/palette';

export const TIER_RIM: Record<AchievementTier, PaletteToken> = {
  bronze: 'brown',
  silver: 'pencil',
  gold: 'yellow',
};

const TIER_HUE: Record<AchievementTier, PaletteToken> = {
  bronze: 'orange',
  silver: 'blue',
  gold: 'yellow',
};

/** A question mark, drawn rather than typeset, for a secret nobody has found yet. */
export const SECRET_ART: BadgeArt = (c) =>
  `<path d="M36 38 Q36 22 50 22 Q64 22 64 36 Q64 45 55 50 Q50 53 50 61" fill="none" stroke="${c.ink}" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/>` +
  `<circle cx="50" cy="75" r="5.5" fill="${c.ink}"/>`;

/** Tiny four-pointed sparkle, for gold badges and for icons that want one. */
export function sparkle(cx: number, cy: number, r: number, fill: string): string {
  const q = r * 0.28;
  return `<path d="M${cx} ${cy - r} Q${cx + q} ${cy - q} ${cx + r} ${cy} Q${cx + q} ${cy + q} ${cx} ${cy + r} Q${cx - q} ${cy + q} ${cx - r} ${cy} Q${cx - q} ${cy - q} ${cx} ${cy - r} Z" fill="${fill}"/>`;
}

/** Same string in, same number out: the per-badge tilt and wobble seed. */
function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

let uid = 0;

export interface BadgeOptions {
  /** Stable identity, e.g. `mines.no-flags`: picks the tilt and the wobble. */
  key: string;
  tier: AchievementTier;
  hue?: PaletteToken;
  art: BadgeArt;
  /** Rendered size in px; omit to let CSS size it. */
  size?: number;
  /** Replace the motif with a question mark (a hidden achievement not yet earned). */
  secret?: boolean;
  /** Leave out the wobble filter (static store art that is rasterised elsewhere). */
  flat?: boolean;
}

export function badgeSVG(opts: BadgeOptions): string {
  const { key, tier, size, secret = false, flat = false } = opts;
  const c = PALETTE;
  const h = hash(key);
  const tilt = ((h % 7) - 3) * 0.9;
  const id = `bw${++uid}`;
  const hue = c[opts.hue ?? TIER_HUE[tier]];
  const rim = c[TIER_RIM[tier]];
  const bg = secret ? c.shade : mix(hue, c.paper, 0.62);
  const inner = mix(hue, c.paper, 0.8);
  const art = secret ? SECRET_ART(c) : opts.art(c);
  const dim = size ? ` width="${size}" height="${size}"` : '';
  const filter = flat
    ? ''
    : `<defs><filter id="${id}" x="-10%" y="-10%" width="120%" height="120%"><feTurbulence type="fractalNoise" baseFrequency="0.04" numOctaves="2" seed="${h % 97}"/><feDisplacementMap in="SourceGraphic" scale="3.4" xChannelSelector="R" yChannelSelector="G"/></filter></defs>`;
  const sparkles =
    tier === 'gold'
      ? sparkle(88, 12, 8, c.yellow) + sparkle(12, 86, 5.5, c.yellow)
      : tier === 'silver'
        ? sparkle(88, 12, 6, c.highlight)
        : '';
  return `<svg class="badge-art tier-${tier}" viewBox="0 0 100 100"${dim} aria-hidden="true">${filter}<g${flat ? '' : ` filter="url(#${id})"`} transform="rotate(${tilt.toFixed(1)} 50 50)"><rect x="5" y="5" width="90" height="90" rx="20" fill="${bg}" stroke="${c.ink}" stroke-width="4.5"/><rect x="12" y="12" width="76" height="76" rx="14" fill="${inner}" stroke="${rim}" stroke-width="5"/>${art}${sparkles}</g></svg>`;
}
