import { tx } from '../../i18n';
/**
 * Magnets board: the fixed puzzle (domino layout plus clue counts), the description
 * format, and the checks the game and its solver share.
 *
 * A description is five comma-separated fields: the `+` counts above each column, the
 * `+` counts left of each row, the `-` counts below each column, the `-` counts right of
 * each row (one character per count: a digit, a letter for 10 and up, or `.` for no clue),
 * and finally one character per cell describing the domino tiling — `L`/`R` for the left
 * and right halves of a horizontal domino, `T`/`B` for the top and bottom halves of a
 * vertical one, and `*` for a single square left over when the area is odd. Commas may be
 * sprinkled through the tiling as row separators. For example `3x3:201,102,120,111,LRTT*BBLR`.
 */

/** Polarities, as counted by the clues and reasoned about by the solver. */
export const NEUTRAL = 0;
export const POSITIVE = 1;
export const NEGATIVE = 2;

/** What the player has put in a cell. Magnet poles share their values with the polarities. */
export const CELL_EMPTY = 0;
export const CELL_POSITIVE = POSITIVE;
export const CELL_NEGATIVE = NEGATIVE;
export const CELL_NEUTRAL = 3;
/** The "this domino is not blank" note. */
export const CELL_NOT_NEUTRAL = 4;

/** The other pole of a magnet; neutral stays neutral. */
export function opposite(which: number): number {
  return (which * 2) % 3;
}

/** A cell that still needs filling in. */
export function isUnset(cell: number): boolean {
  return cell === CELL_EMPTY || cell === CELL_NOT_NEUTRAL;
}

/** The polarity of a settled cell, or -1 when it is still unknown. */
export function polarityOf(cell: number): number {
  if (cell === CELL_POSITIVE || cell === CELL_NEGATIVE) return cell;
  if (cell === CELL_NEUTRAL) return NEUTRAL;
  return -1;
}

/**
 * The unchanging part of a puzzle. Lines are numbered with the columns first (0..w-1)
 * and the rows after them (w..w+h-1); `targets[3 * line + polarity]` is the clue for
 * that line, or -1 for none. The neutral target is derived from the other two and is
 * -1 whenever either of them is.
 */
export class Layout {
  readonly n: number;

  constructor(
    readonly w: number,
    readonly h: number,
    /** `partner[i]` is the other cell of the domino on `i`, or `i` for a lone square. */
    readonly partner: Int32Array,
    readonly targets: Int32Array,
  ) {
    this.n = w * h;
  }

  get lines(): number {
    return this.w + this.h;
  }

  /** Where a line starts, how far apart its cells are and how many there are. */
  line(l: number): { start: number; step: number; len: number } {
    return l < this.w
      ? { start: l, step: this.w, len: this.h }
      : { start: (l - this.w) * this.w, step: 1, len: this.w };
  }

  target(l: number, which: number): number {
    return this.targets[3 * l + which];
  }

  /** Recompute the neutral target of a line from its two pole targets. */
  fixNeutral(l: number): void {
    const p = this.targets[3 * l + POSITIVE];
    const m = this.targets[3 * l + NEGATIVE];
    this.targets[3 * l + NEUTRAL] = p < 0 || m < 0 ? -1 : this.line(l).len - p - m;
  }

  isSingleton(i: number): boolean {
    return this.partner[i] === i;
  }

  /** A fresh player grid: everything empty except lone squares, which are neutral. */
  freshCells(): Uint8Array {
    const cells = new Uint8Array(this.n);
    for (let i = 0; i < this.n; i++) if (this.partner[i] === i) cells[i] = CELL_NEUTRAL;
    return cells;
  }
}

// ------------------------------------------------------------------ description

function numToChar(num: number): string {
  if (num < 0) return '.';
  if (num < 10) return String(num);
  if (num < 36) return String.fromCharCode(97 + num - 10);
  return String.fromCharCode(65 + num - 36);
}

function charToNum(c: string): number {
  if (c >= '0' && c <= '9') return c.charCodeAt(0) - 48;
  if (c >= 'a' && c <= 'z') return c.charCodeAt(0) - 97 + 10;
  if (c >= 'A' && c <= 'Z') return c.charCodeAt(0) - 65 + 36;
  return -1;
}

/** Compute clue targets for every line from a complete polarity grid. */
export function countTargets(w: number, h: number, grid: Uint8Array): Int32Array {
  const targets = new Int32Array(3 * (w + h));
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const v = grid[y * w + x];
      targets[3 * x + v]++;
      targets[3 * (w + y) + v]++;
    }
  }
  return targets;
}

/** Parse a description into a layout, or return an error message. */
export function parseDesc(desc: string, w: number, h: number): Layout | string {
  const n = w * h;
  let pos = 0;
  const targets = new Int32Array(3 * (w + h)).fill(-1);
  const readRow = (count: number, lineBase: number, which: number): string | null => {
    for (let i = 0; i < count; i++) {
      if (pos >= desc.length) return tx`Game description is too short`;
      const c = desc[pos++];
      const num = c === '.' ? -1 : charToNum(c);
      if (c !== '.' && num < 0) return tx`Game description contained unexpected characters`;
      targets[3 * (lineBase + i) + which] = num;
    }
    if (pos >= desc.length) return tx`Game description is too short`;
    if (desc[pos++] !== ',') return tx`Game description contained unexpected characters`;
    return null;
  };
  let err = readRow(w, 0, POSITIVE);
  if (err) return err;
  err = readRow(h, w, POSITIVE);
  if (err) return err;
  err = readRow(w, 0, NEGATIVE);
  if (err) return err;
  err = readRow(h, w, NEGATIVE);
  if (err) return err;

  const partner = new Int32Array(n);
  const layout = new Layout(w, h, partner, targets);
  for (let l = 0; l < w + h; l++) {
    const p = targets[3 * l + POSITIVE];
    const m = targets[3 * l + NEGATIVE];
    if (p >= 0 && m >= 0 && p + m > layout.line(l).len)
      return l < w ? tx`Column counts inconsistent` : tx`Row counts inconsistent`;
    layout.fixNeutral(l);
  }

  for (let i = 0; i < n; i++) {
    let c: string;
    do {
      if (pos >= desc.length) return tx`Game description is too short`;
      c = desc[pos++];
    } while (c === ',');
    const x = i % w;
    const y = Math.floor(i / w);
    if (c === 'L' && x + 1 < w) partner[i] = i + 1;
    else if (c === 'R' && x > 0) partner[i] = i - 1;
    else if (c === 'T' && y + 1 < h) partner[i] = i + w;
    else if (c === 'B' && y > 0) partner[i] = i - w;
    else if (c === '*') partner[i] = i;
    else if ('LRTB'.includes(c)) return tx`Domino descriptions inconsistent`;
    else return tx`Game description contained unexpected characters`;
  }
  for (let i = 0; i < n; i++)
    if (partner[partner[i]] !== i) return tx`Domino descriptions inconsistent`;
  if (desc.slice(pos).replace(/,/g, '') !== '') return tx`Game description too long`;
  return layout;
}

export function encodeDesc(L: Layout): string {
  const { w, h, partner } = L;
  const row = (count: number, base: number, which: number) => {
    let s = '';
    for (let i = 0; i < count; i++) s += numToChar(L.target(base + i, which));
    return s;
  };
  let tiles = '';
  for (let i = 0; i < L.n; i++) {
    const j = partner[i];
    tiles += j === i ? '*' : j === i + 1 ? 'L' : j === i - 1 ? 'R' : j === i + w ? 'T' : 'B';
  }
  return [
    row(w, 0, POSITIVE),
    row(h, w, POSITIVE),
    row(w, 0, NEGATIVE),
    row(h, w, NEGATIVE),
    tiles,
  ].join(',');
}

/** The solution as one character per cell, `.`, `+` or `-`. */
export function encodeAux(grid: Uint8Array): string {
  let s = '';
  for (let i = 0; i < grid.length; i++) s += '.+-'[grid[i]];
  return s;
}

export function decodeAux(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n) return null;
  const grid = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    const v = '.+-'.indexOf(aux[i]);
    if (v < 0) return null;
    grid[i] = v;
  }
  return grid;
}

// ------------------------------------------------------------------ checks

export interface Completion {
  /** -1 something is wrong, 0 not finished, 1 solved. */
  status: -1 | 0 | 1;
  /** 1 on every magnet pole that touches a like pole. */
  errors: Uint8Array;
}

/** How many cells of a line hold `which`; pass -1 to count the cells still unset. */
export function countLine(L: Layout, cells: Uint8Array, l: number, which: number): number {
  const { start, step, len } = L.line(l);
  let count = 0;
  for (let k = 0, i = start; k < len; k++, i += step) {
    if (which < 0 ? isUnset(cells[i]) : cells[i] === which) count++;
  }
  return count;
}

/** Judge a player grid: count clues, filled dominoes and repelling poles. */
export function checkCompletion(L: Layout, cells: Uint8Array): Completion {
  const { w, h, n, partner } = L;
  const errors = new Uint8Array(n);
  let wrong = false;
  let incomplete = false;
  for (let l = 0; l < L.lines; l++) {
    for (const which of [POSITIVE, NEGATIVE]) {
      const target = L.target(l, which);
      if (target < 0) continue;
      const count = countLine(L, cells, l, which);
      if (count < target) incomplete = true;
      if (count > target) wrong = true;
    }
  }
  for (let i = 0; i < n; i++) {
    if (partner[i] === i) continue;
    const v = cells[i];
    if (isUnset(v)) incomplete = true;
    if (v !== CELL_POSITIVE && v !== CELL_NEGATIVE) continue;
    const x = i % w;
    const y = Math.floor(i / w);
    const nbrs = [
      x > 0 ? i - 1 : -1,
      x + 1 < w ? i + 1 : -1,
      y > 0 ? i - w : -1,
      y + 1 < h ? i + w : -1,
    ];
    for (const j of nbrs) {
      if (j >= 0 && cells[j] === v) {
        wrong = true;
        errors[i] = 1;
        errors[j] = 1;
      }
    }
  }
  return { status: wrong ? -1 : incomplete ? 0 : 1, errors };
}

/**
 * How a clue should be shown: `error` when it can no longer be met (too many poles, or
 * too few with no empty cell left), `full` when it is exactly met.
 */
export function clueStatus(
  L: Layout,
  cells: Uint8Array,
  l: number,
  which: number,
): { error: boolean; full: boolean } {
  const target = L.target(l, which);
  const count = countLine(L, cells, l, which);
  const empty = countLine(L, cells, l, -1);
  return {
    error: count > target || (count < target && empty === 0),
    full: count === target,
  };
}
