import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  RIGHT_BUTTON,
  isCursorMove,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import {
  flashOn,
  hintFlashCell,
  hintFlashing,
  markHint,
  noHint,
  parseWxH,
  takeHintFlash,
  type HintMark,
} from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { ERASE_GLYPH } from '../../framework/glyphs';
import type { Random } from '../../framework/rng';
import {
  BLACK,
  EMPTY,
  WHITE,
  checkGrid,
  decodeSolution,
  isValidSolution,
  parseDesc,
} from './board';
import type { GridCheck } from './board';
import { generate } from './generator';
import type { RangeParams } from './generator';
import { findSolution, hint as nextDeduction } from './solver';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export type { RangeParams };

export interface RangeState {
  w: number;
  h: number;
  /** The numbers, 0 where there is none (row-major). Shared between states. */
  clues: Uint8Array;
  /** `EMPTY`, `WHITE` (dot) or `BLACK` per cell. */
  grid: Uint8Array;
  /** Rule check of this position, including what to highlight. */
  check: GridCheck;
  completed: boolean;
  cheated: boolean;
}

export interface RangeUI extends HintMark {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  dragging: boolean;
  /** Drag and release codes of the button that started the current gesture. */
  dragButton: number;
  releaseButton: number;
  /**
   * Value being painted, and the value a cell must have to be painted over (`ANY_MARK`:
   * any black square or dot, for the eraser).
   */
  dragValue: number;
  dragFrom: number;
  /** Cells painted so far in this gesture, in order. */
  painted: number[];
  /** Last pointer cell seen during the gesture. */
  lastX: number;
  lastY: number;
  /**
   * The Erase tool: a left click or sweep clears every black square and dot it passes
   * over, whichever it is.
   */
  erase: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
/** Past this, descriptions get unwieldy and the solver's recursion deep. */
const MAX_SIDE = 40;
/** Generation stays well under a second up to about here. */
const MAX_GEN_SIDE = 30;
const DEFAULTS: RangeParams = { w: 9, h: 6 };
/** Move letters indexed by cell value (EMPTY, WHITE, BLACK). */
const VALUE_CHARS = ['E', 'W', 'B'];
/** `dragFrom` of an eraser sweep: it takes whatever mark it meets. */
const ANY_MARK = -1;

/** Whether a sweep that started on `from` paints over a cell holding `value`. */
function sweeps(from: number, value: number): boolean {
  return from === ANY_MARK ? value !== EMPTY : value === from;
}

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

/** The finished grid: the generator's own answer where there is one, else solved afresh. */
function solutionOf(state: RangeState, aux: string | undefined): Uint8Array | null {
  const { w, h, clues } = state;
  if (aux !== undefined) {
    const g = decodeSolution(aux, w * h);
    if (g && isValidSolution(clues, g, w, h)) return g;
  }
  return findSolution(clues, w, h);
}

/** The value a cell takes after a left click (`dir` = -1) or a right click (`dir` = +1). */
export function cycle(value: number, dir: number): number {
  // Left: empty → black → dot → empty.  Right: empty → dot → black → empty.
  if (dir < 0) return value === EMPTY ? BLACK : value === BLACK ? WHITE : EMPTY;
  return value === EMPTY ? WHITE : value === WHITE ? BLACK : EMPTY;
}

function cellMove(value: number, x: number, y: number): string {
  return `${VALUE_CHARS[value]}${x},${y}`;
}

function makeState(
  w: number,
  h: number,
  clues: Uint8Array,
  grid: Uint8Array,
  cheated = false,
): RangeState {
  const check = checkGrid(clues, grid, w, h);
  return { w, h, clues, grid, check, completed: check.complete, cheated };
}

/**
 * Sketch a red outline around every group of cells set in `mask`, inset by `m` inside the
 * group. Edges are drawn per cell; an end reaches past the cell boundary at an inside
 * corner so the segments meet.
 */
function outlineCells(
  dr: Drawing,
  mask: Uint8Array,
  w: number,
  h: number,
  b: number,
  t: number,
  m: number,
  width: number,
): void {
  const inMask = (x: number, y: number) => x >= 0 && y >= 0 && x < w && y < h && !!mask[y * w + x];
  const reach = (x: number, y: number, ax: number, ay: number, nx: number, ny: number) => {
    if (!inMask(x + ax, y + ay)) return -m;
    return inMask(x + ax + nx, y + ay + ny) ? m : 0;
  };
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      if (!mask[y * w + x]) continue;
      const px = b + x * t;
      const py = b + y * t;
      const seed = y * w + x;
      if (!inMask(x, y - 1)) {
        const l = reach(x, y, -1, 0, 0, -1);
        const r = reach(x, y, 1, 0, 0, -1);
        dr.line(px - l, py + m, px + t + r, py + m, 'error', width, { seed });
      }
      if (!inMask(x, y + 1)) {
        const l = reach(x, y, -1, 0, 0, 1);
        const r = reach(x, y, 1, 0, 0, 1);
        dr.line(px - l, py + t - m, px + t + r, py + t - m, 'error', width, { seed: seed + 1 });
      }
      if (!inMask(x - 1, y)) {
        const u = reach(x, y, 0, -1, -1, 0);
        const d = reach(x, y, 0, 1, -1, 0);
        dr.line(px + m, py - u, px + m, py + t + d, 'error', width, { seed: seed + 2 });
      }
      if (!inMask(x + 1, y)) {
        const u = reach(x, y, 0, -1, 1, 0);
        const d = reach(x, y, 0, 1, 1, 0);
        dr.line(px + t - m, py - u, px + t - m, py + t + d, 'error', width, { seed: seed + 3 });
      }
    }
  }
}

const game = defineGame<RangeParams, RangeState, RangeUI>({
  id: 'range',
  name: 'Range',
  description:
    'Paint cells black so that every number sees exactly that many white cells along its row and column.',
  alsoKnownAs: 'Kurodoko, Kuromasu',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [9, 6],
      [12, 8],
      [13, 9],
      [16, 11],
    ] as [number, number][]
  ).map(([w, h]) => ({ name: `${w}×${h}`, params: { w, h } })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p) => `${p.w}x${p.h}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    return { w: r.w, h: r.h };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must both be at least one`;
    // The generation limit comes first when generating: naming the larger limit for a 99
    // would only have the player try 40 and be refused again.
    if (full && (p.w > MAX_GEN_SIDE || p.h > MAX_GEN_SIDE))
      return tx`Width and height must be at most ${MAX_GEN_SIDE} to generate a puzzle`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    // No puzzle of these sizes has a unique solution with symmetric clues.
    if (full && (p.w * p.h <= 2 || (p.w === 2 && p.h === 2)))
      return tx`Can't create ${p.w}×${p.h} puzzles`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => {
      const v = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(v) ? parseInt(v, 10) : NaN;
    };
    return { w: int(0), h: int(1) };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const clues = parseDesc(desc, p.w, p.h) as Uint8Array;
    const state = makeState(p.w, p.h, clues, new Uint8Array(p.w * p.h));
    // A fresh puzzle is never "completed", even a degenerate one with no black cells.
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const { w, clues } = curr;
    const n = w * curr.h;
    const solution = solutionOf(curr, aux);
    if (!solution) throw new Error(tx`This puzzle instance contains a contradiction`);
    // The solved grid has every cell decided: black, or dotted to say it is white.
    let move = 'S';
    for (let i = 0; i < n; i++) {
      if (clues[i] > 0) continue;
      const want = solution[i] === BLACK ? BLACK : WHITE;
      if (curr.grid[i] !== want) move += `;${cellMove(want, i % w, Math.floor(i / w))}`;
    }
    return move;
  },

  /**
   * One square. A black square or a dot that contradicts the answer is put right first,
   * since nothing sound follows from it; otherwise the first square the rules settle from
   * what is on the board, and only when none does, a square straight from the answer.
   */
  hint(_orig, curr, aux, ui) {
    if (curr.completed) return null;
    const { w, h, clues, grid } = curr;
    const solution = solutionOf(curr, aux);
    if (!solution) throw new Error(tx`This puzzle instance contains a contradiction`);
    const want = (i: number) => (solution[i] === BLACK ? BLACK : WHITE);
    const cell = (i: number, v: number) => markHint(ui, i, cellMove(v, i % w, Math.floor(i / w)));
    for (let i = 0; i < grid.length; i++) {
      if (clues[i] === 0 && grid[i] !== EMPTY && grid[i] !== want(i)) return cell(i, want(i));
    }
    const next = nextDeduction(clues, w, h, grid);
    if (next && grid[next.cell] === EMPTY && next.value === want(next.cell))
      return cell(next.cell, next.value);
    for (let i = 0; i < grid.length; i++) {
      if (clues[i] === 0 && grid[i] === EMPTY) return cell(i, want(i));
    }
    return null;
  },

  textFormat(s) {
    // Boxed cells like the original: numbers, `#` for black, `.` for a dot.
    let digits = 1;
    for (let i = 0; i < s.clues.length; i++) digits = Math.max(digits, String(s.clues[i]).length);
    const rule = `+${Array.from({ length: s.w }, () => '-'.repeat(digits)).join('+')}+`;
    const rows: string[] = [rule];
    for (let y = 0; y < s.h; y++) {
      let row = '|';
      for (let x = 0; x < s.w; x++) {
        const i = y * s.w + x;
        const v = s.grid[i];
        const ch =
          s.clues[i] > 0 ? String(s.clues[i]) : v === BLACK ? '#' : v === WHITE ? '.' : ' ';
        row += `${ch.padStart(digits, s.clues[i] > 0 ? ' ' : ch)}|`;
      }
      rows.push(row, rule);
    }
    return rows.join('\n');
  },

  newUI: () => ({
    ...noHint(),
    cx: 0,
    cy: 0,
    cursorVisible: false,
    dragging: false,
    dragButton: 0,
    releaseButton: 0,
    dragValue: EMPTY,
    dragFrom: EMPTY,
    painted: [],
    lastX: 0,
    lastY: 0,
    erase: false,
  }),
  changedState(ui, old, next) {
    // A sweep still in progress was planned on the old board (Undo, Restart, Solve or Hint
    // changed it under the held button): releasing it must not paint the new one.
    ui.dragging = false;
    ui.painted = [];
    if (!old.completed && next.completed) ui.cursorVisible = false;
  },

  actions: [
    {
      label: 'Erase',
      key: 'E',
      hud: true,
      glyph: ERASE_GLYPH,
      pressed: (_s, ui) => ui.erase,
      title: 'Click or drag to clear black squares and dots (E)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const ch = keyChar(b);
    if (ch === 'e' || ch === 'E') {
      ui.erase = !ui.erase;
      return '';
    }
    const { w, h, clues, grid } = state;
    const t = ds.tileSize;
    const bd = boardBorder(t);
    const px = Math.floor((mx - bd) / t);
    const py = Math.floor((my - bd) / t);
    const inside = px >= 0 && py >= 0 && px < w && py < h;

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      // Hiding a visible cursor is itself a change worth redrawing.
      const idle = ui.cursorVisible ? '' : null;
      ui.cursorVisible = false;
      ui.dragging = false;
      if (!inside) return idle;
      ui.cx = px;
      ui.cy = py;
      const i = py * w + px;
      if (clues[i] > 0) return idle;
      // The first cell decides what is painted; dragging on paints the same over every
      // cell that started out like it.
      ui.dragging = true;
      ui.dragButton = b + (LEFT_DRAG - LEFT_BUTTON);
      ui.releaseButton = b + (LEFT_RELEASE - LEFT_BUTTON);
      if (ui.erase && b === LEFT_BUTTON) {
        // The eraser clears black squares and dots alike, and passes over blank ones.
        ui.dragFrom = ANY_MARK;
        ui.dragValue = EMPTY;
        ui.painted = grid[i] === EMPTY ? [] : [i];
      } else {
        ui.dragFrom = grid[i];
        ui.dragValue = cycle(grid[i], b === LEFT_BUTTON ? -1 : 1);
        ui.painted = [i];
      }
      ui.lastX = px;
      ui.lastY = py;
      return '';
    }
    if (ui.dragging && b === ui.dragButton) {
      if (!inside) {
        // Off the board the sweep is broken: coming back in somewhere else must not paint
        // a straight line across cells the pointer never crossed.
        ui.lastX = ui.lastY = -1;
        return null;
      }
      const reentry = ui.lastX < 0;
      if (reentry) {
        ui.lastX = px;
        ui.lastY = py;
      }
      // Walk from the last cell to this one so a quick sweep leaves no gaps.
      const steps = Math.max(Math.abs(px - ui.lastX), Math.abs(py - ui.lastY));
      let changed = false;
      for (let s = reentry ? 0 : 1; s <= steps; s++) {
        const x = steps ? Math.round(ui.lastX + ((px - ui.lastX) * s) / steps) : px;
        const y = steps ? Math.round(ui.lastY + ((py - ui.lastY) * s) / steps) : py;
        const i = y * w + x;
        if (clues[i] > 0 || !sweeps(ui.dragFrom, grid[i]) || ui.painted.includes(i)) continue;
        ui.painted.push(i);
        changed = true;
      }
      ui.lastX = px;
      ui.lastY = py;
      return changed ? '' : null;
    }
    if (ui.dragging && b === ui.releaseButton) {
      ui.dragging = false;
      return ui.painted.map((i) => cellMove(ui.dragValue, i % w, Math.floor(i / w))).join(';');
    }

    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    }
    if (b === CURSOR_SELECT || b === CURSOR_SELECT2) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const i = ui.cy * w + ui.cx;
      if (clues[i] > 0) return null;
      return cellMove(cycle(grid[i], b === CURSOR_SELECT ? -1 : 1), ui.cx, ui.cy);
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h, clues } = state;
    const grid = state.grid.slice();
    let cheated = state.cheated;
    for (const part of move.split(';')) {
      if (part === 'S') {
        cheated = true;
        continue;
      }
      const m = /^([BWE])(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h || clues[y * w + x] > 0) return null;
      grid[y * w + x] = VALUE_CHARS.indexOf(m[1]);
    }
    return makeState(w, h, clues, grid, cheated);
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, clues, grid, check } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const hintCell = hintFlashCell(ui, flashTime);
    // A hint owns the flash it asked for: only a finished grid recolours the clues.
    const flash = !hintFlashing(ui) && flashOn(flashTime, FLASH_FRAME);
    const cellX = (x: number) => b + x * t;
    const cellY = (y: number) => b + y * t;
    let view = grid;
    if (ui.dragging) {
      view = grid.slice();
      for (const i of ui.painted) view[i] = ui.dragValue;
    }

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(cellX(x), b, cellX(x), b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, cellY(y), b + w * t, cellY(y), 'faint', 1.2);

    const textSize = t * 0.55;
    const dotR = Math.max(2, t * 0.09);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const px = cellX(x);
        const py = cellY(y);
        if (clues[i] > 0) {
          dr.text(px + t / 2, py + t / 2, String(clues[i]), {
            size: textSize,
            colour: check.badClue[i] ? 'error' : flash ? 'ok' : 'ink',
            maxWidth: t * 0.8,
          });
        } else if (view[i] === BLACK) {
          const g = Math.max(0.5, t * 0.02);
          dr.polygon(
            [px + g, py + g, px + t - g, py + g, px + t - g, py + t - g, px + g, py + t - g],
            'ink',
            'ink',
            { seed: i, width: 1.4 },
          );
        } else if (view[i] === WHITE) {
          dr.dot(px + t / 2, py + t / 2, dotR, check.cutOff[i] ? 'error' : 'pencil', { seed: i });
        }
      }
    }
    // Touching black cells get a red frame around the group; white cells cut off from the
    // main region get a red outline.
    const frameW = Math.max(2, t * 0.07);
    outlineCells(dr, check.badBlack, w, h, b, t, t * 0.1, frameW);
    outlineCells(dr, check.cutOff, w, h, b, t, t * 0.08, frameW);
    dr.rectOutline(b, b, w * t, h * t, 'ink', { width: 2.6 });

    if (hintCell >= 0) dr.hintBox(cellX(hintCell % w), cellY(Math.floor(hintCell / w)), t, t);

    if (ui.cursorVisible) {
      const ci = t * 0.1;
      dr.cursor(cellX(ui.cx) + ci, cellY(ui.cy) + ci, t - 2 * ci, t - 2 * ci);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState, _dir, ui) {
    const hint = takeHintFlash(ui);
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : hint;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // A few correct marks on the fixed-seed thumbnail puzzle, so the card shows the game.
  // A unit test keeps these in step with the generator.
  thumbnailMoves: ['B3,0', 'W4,0', 'B5,0', 'B1,1', 'W3,1', 'W4,1', 'B6,1', 'B0,2', 'W1,2', 'B2,2'],
});

export default game;
