/**
 * Penrose tilings (P2 kites and darts, P3 thick and thin rhombs) by recursive
 * subdivision of half-tiles.
 *
 * Vectors are kept as integer combinations of four unit vectors 36° apart, which makes
 * equality exact and rotation by multiples of 36° a matter of integer arithmetic: with
 * basis vectors A, B, C, D and E = D − C + B − A (the fifth spoke of a pentagram), one
 * clockwise notch maps (a, b, c, d) to (−d, d + a, b − d, c + d). Scaling by the golden
 * ratio φ or 1/φ is likewise a fixed integer transform. Only at the very end are
 * vectors turned into plane coordinates.
 */

export const PENROSE_P2 = 0;
export const PENROSE_P3 = 1;

const PHI = 1.6180339887;
const COS54 = 0.5877852;
const SIN54 = 0.8090169;
const COS18 = 0.9510565;
const SIN18 = 0.3090169;
/** Radius of the circle inscribed in the starting triangle, relative to its long side. */
const INCIRCLE_RADIUS = 0.22426;

interface V {
  a: number;
  b: number;
  c: number;
  d: number;
}

export const vx = (v: V): number => (v.a + v.d) * COS54 + (v.b + v.c) * COS18;
export const vy = (v: V): number => (v.a - v.d) * SIN54 + (v.b - v.c) * SIN18;

const trans = (v: V, t: V): V => ({ a: v.a + t.a, b: v.b + t.b, c: v.c + t.c, d: v.d + t.d });
const rot36 = (v: V): V => ({ a: -v.d, b: v.d + v.a, c: -v.d + v.b, d: v.d + v.c });

function rotate(v: V, ang: number): V {
  while (ang < 0) ang += 360;
  ang = 360 - ang;
  const n = (ang / 36) % 10;
  for (let i = 0; i < n; i++) v = rot36(v);
  return v;
}

const growPhi = (v: V): V => ({
  a: v.a + v.b - v.d,
  b: v.c + v.d,
  c: v.a + v.b,
  d: v.c + v.d - v.a,
});
const shrinkPhi = (v: V): V => ({
  a: v.b - v.d,
  b: v.c + v.d - v.b,
  c: v.a + v.b - v.c,
  d: v.c - v.a,
});

/** `edge`, optionally scaled by φ (`shrink` > 0) or 1/φ (< 0), rotated, then moved to `origin`. */
function xform(edge: V, shrink: number, origin: V, ang: number): V {
  let v = edge;
  if (shrink < 0) v = shrinkPhi(v);
  else if (shrink > 0) v = growPhi(v);
  return trans(rotate(v, ang), origin);
}

export interface PenroseSink {
  /** Called for every whole tile at the deepest level, with its four corner vectors. */
  tile(vs: V[], depth: number): void;
}

class Gen {
  constructor(
    readonly maxDepth: number,
    readonly sink: PenroseSink,
  ) {}

  p2Large(depth: number, flip: number, o: V, e: V): void {
    if (flip > 0) {
      this.sink.tile([o, xform(e, 0, o, -36), xform(e, 0, o, 0), xform(e, 0, o, 36)], depth);
    }
    if (depth >= this.maxDepth) return;
    const oo = trans(o, rotate(e, -36 * flip));
    const ee = rotate(e, 108 * flip);
    this.p2Small(depth + 1, flip, o, shrinkPhi(e));
    this.p2Large(depth + 1, flip, oo, shrinkPhi(ee));
    this.p2Large(depth + 1, -flip, oo, shrinkPhi(ee));
  }

  p2Small(depth: number, flip: number, o: V, e: V): void {
    if (flip > 0) {
      this.sink.tile([o, xform(e, 0, o, -72), xform(e, -1, o, -36), xform(e, 0, o, 0)], depth);
    }
    if (depth >= this.maxDepth) return;
    const oo = trans(o, e);
    this.p2Large(depth + 1, -flip, o, shrinkPhi(rotate(e, -36 * flip)));
    this.p2Small(depth + 1, flip, oo, shrinkPhi(rotate(e, -144 * flip)));
  }

  p3Large(depth: number, flip: number, o: V, e: V): void {
    if (flip > 0) {
      this.sink.tile([o, xform(e, 0, o, -36), xform(e, 1, o, 0), xform(e, 0, o, 36)], depth);
    }
    if (depth >= this.maxDepth) return;
    let oo = trans(o, e);
    this.p3Large(depth + 1, -flip, oo, shrinkPhi(rotate(e, 180)));
    this.p3Small(depth + 1, flip, oo, shrinkPhi(rotate(e, -108 * flip)));
    oo = trans(o, growPhi(e));
    this.p3Large(depth + 1, flip, oo, shrinkPhi(rotate(e, -144 * flip)));
  }

  p3Small(depth: number, flip: number, o: V, e: V): void {
    if (flip > 0) {
      const v3 = xform(e, 0, o, 0);
      this.sink.tile([o, xform(e, 0, o, -36), xform(e, 0, v3, -36), v3], depth);
    }
    if (depth >= this.maxDepth) return;
    const oo = trans(o, e);
    this.p3Large(depth + 1, -flip, oo, shrinkPhi(rotate(e, 180)));
    this.p3Small(depth + 1, flip, oo, shrinkPhi(rotate(e, -108 * flip)));
  }
}

/**
 * Subdivide one big triangle of side `startSize`, rotated by `angle` (a multiple of 36),
 * `maxDepth` times and report every tile at the deepest level.
 */
export function penrose(
  which: number,
  startSize: number,
  maxDepth: number,
  angle: number,
  sink: PenroseSink,
): void {
  let vo: V = { a: 0, b: -startSize, c: -startSize, d: 0 };
  vo = shrinkPhi(shrinkPhi(vo));
  let vb: V = { a: 0, b: startSize, c: 0, d: 0 };
  vo = rotate(vo, angle);
  vb = rotate(vb, angle);
  const gen = new Gen(maxDepth, sink);
  if (which === PENROSE_P2) gen.p2Large(0, 1, vo, vb);
  else gen.p3Small(0, 1, vo, vb);
}

/**
 * How big a starting triangle, and how many subdivisions, are needed so that a patch
 * `w × h` tiles across can be cut from anywhere within a circle of the returned radius.
 */
export function penroseCalculateSize(
  which: number,
  tilesize: number,
  w: number,
  h: number,
): { radius: number; startSize: number; depth: number } {
  // The two tilings are scaled differently purely for looks.
  tilesize = which === PENROSE_P2 ? Math.floor((tilesize * 3) / 2) : Math.floor((tilesize * 5) / 4);
  const radius = tilesize * 3.11 * Math.sqrt(w * w + h * h);
  let size = tilesize;
  let depth = 0;
  while (size * INCIRCLE_RADIUS < radius) {
    depth++;
    size *= PHI;
  }
  return { radius, startSize: Math.floor(size), depth };
}
