import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { FillingParams, FillingState } from './index';

type C = typeof PALETTE;

/** A handwritten 4 centred on (cx, cy), `s` tall. */
function four(colour: string, cx: number, cy: number, s: number): string {
  const k = s / 14;
  const p = (x: number, y: number) => `${(cx + x * k).toFixed(1)} ${(cy + y * k).toFixed(1)}`;
  return `<path d="M${p(2.5, 7)} L${p(2.5, -7)} L${p(-5, 3)} L${p(5, 3)}" fill="none" stroke="${colour}" stroke-width="${(3.6 * k * 1.1).toFixed(1)}" stroke-linecap="round" stroke-linejoin="round"/>`;
}

/** Faint grid lines over the given cells (x, y in cell units from the origin). */
function cells(c: C, ox: number, oy: number, t: number, list: [number, number][], fill: string) {
  return list
    .map(
      ([x, y]) =>
        `<rect x="${ox + x * t}" y="${oy + y * t}" width="${t}" height="${t}" fill="${fill}" stroke="${c.faint}" stroke-width="1.5"/>`,
    )
    .join('');
}

/** Groups to write: runs of equal digits over squares the player had to fill. */
function groupsToFill(s: FillingState): number {
  const { w, h, clues, board } = s;
  const seen = new Uint8Array(w * h);
  let groups = 0;
  for (let i = 0; i < w * h; i++) {
    if (clues[i] || seen[i]) continue;
    groups++;
    seen[i] = 1;
    const stack = [i];
    while (stack.length) {
      const q = stack.pop()!;
      const x = q % w;
      const y = (q - x) / w;
      for (const n of [
        x > 0 ? q - 1 : -1,
        x < w - 1 ? q + 1 : -1,
        y > 0 ? q - w : -1,
        y < h - 1 ? q + w : -1,
      ]) {
        if (n < 0 || seen[n] || clues[n] || board[n] !== board[q]) continue;
        seen[n] = 1;
        stack.push(n);
      }
    }
  }
  return groups;
}

export const achievements = defineAchievements<FillingParams, FillingState>([
  {
    id: 'in-ink',
    name: 'Written in Ink',
    description: 'Solve a Filling without changing or rubbing out any digit, and without Undo.',
    tier: 'silver',
    hue: 'blue',
    // A finished block of four 4s, and the eraser that never came out.
    art: (c) =>
      cells(
        c,
        18,
        18,
        20,
        [
          [0, 0],
          [1, 0],
          [0, 1],
          [1, 1],
        ],
        c.paper,
      ) +
      `<rect x="18" y="18" width="40" height="40" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>` +
      four(c.blue, 28, 28, 13) +
      four(c.blue, 48, 28, 13) +
      four(c.blue, 28, 48, 13) +
      four(c.blue, 48, 48, 13) +
      `<g transform="rotate(-30 65 67)">` +
      `<rect x="54" y="60" width="22" height="14" rx="3" fill="${c.pink}" stroke="${c.ink}" stroke-width="4"/>` +
      `<path d="M62 60 V74" stroke="${c.ink}" stroke-width="3"/>` +
      `</g>` +
      `<path d="M53 79 L77 55" stroke="${c.red}" stroke-width="6" stroke-linecap="round"/>`,
    test: (ctx) => {
      if (ctx.undos > 0) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].board;
        const b = ctx.history[k].board;
        for (let i = 0; i < a.length; i++) if (a[i] && b[i] !== a[i]) return false;
      }
      return true;
    },
  },
  {
    id: 'one-stroke',
    name: 'Each in One Go',
    description: 'Solve a 13×9 or larger Filling writing each group of digits in a single move.',
    tier: 'gold',
    hue: 'green',
    // An L of four squares, selected with one drag and filled with one digit.
    art: (c) => {
      const L: [number, number][] = [
        [0, 0],
        [0, 1],
        [0, 2],
        [1, 2],
      ];
      return (
        cells(c, 24, 18, 20, L, c.shade) +
        `<path d="M24 18 H44 V58 H64 V78 H24 Z" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>` +
        `<path d="M34 26 V68 H58" fill="none" stroke="${c.accent}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" stroke-opacity="0.8"/>` +
        four(c.blue, 34, 28, 13) +
        four(c.blue, 34, 48, 13) +
        four(c.blue, 34, 68, 13) +
        four(c.blue, 54, 68, 13) +
        `<path d="M66 60 L66 82 L71.5 77 L75.5 85 L79.5 83 L75.5 75 L82.5 74.5 Z" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>`
      );
    },
    // A move writes one digit into any selection, so one per group is the fewest possible.
    test: (ctx) => ctx.params.w * ctx.params.h >= 13 * 9 && ctx.moves <= groupsToFill(ctx.state),
  },
]);
