import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { UntangleParams, UntangleState } from './index';

type C = typeof PALETTE;

/** Points and the straight lines between them, as the board draws them. */
function graph(
  c: C,
  pts: [number, number][],
  edges: [number, number][],
  opts: { red?: number[]; dot?: (i: number) => string } = {},
): string {
  let out = '';
  edges.forEach(([a, b], k) => {
    const colour = opts.red?.includes(k) ? c.red : c.ink;
    out += `<path d="M${pts[a][0]} ${pts[a][1]} L${pts[b][0]} ${pts[b][1]}" stroke="${colour}" stroke-width="3.5" stroke-linecap="round"/>`;
  });
  pts.forEach(([x, y], i) => {
    out += `<circle cx="${x}" cy="${y}" r="6" fill="${opts.dot?.(i) ?? c.blue}" stroke="${c.ink}" stroke-width="3"/>`;
  });
  return out;
}

/** Index of every point that moved between two boards. */
function movedPoints(a: UntangleState, b: UntangleState): number[] {
  const out: number[] = [];
  for (let i = 0; i < a.n; i++)
    if (a.pts[2 * i] !== b.pts[2 * i] || a.pts[2 * i + 1] !== b.pts[2 * i + 1]) out.push(i);
  return out;
}

const redLines = (s: UntangleState) => s.crossed.filter(Boolean).length;

export const achievements = defineAchievements<UntangleParams, UntangleState>([
  {
    id: 'one-touch',
    name: 'Light Touch',
    description: 'Untangle 10 points or more without picking up the same point twice.',
    tier: 'silver',
    hue: 'teal',
    // One point lifted once, along a dashed trail, straight to where it belongs.
    art: (c) =>
      `<path d="M30 76 Q46 72 58 58" fill="none" stroke="${c.pencil}" stroke-width="3.5" stroke-dasharray="5 5" stroke-linecap="round"/>` +
      `<circle cx="30" cy="76" r="5" fill="none" stroke="${c.pencil}" stroke-width="3" stroke-dasharray="3 3"/>` +
      graph(
        c,
        [
          [24, 26],
          [58, 20],
          [80, 44],
          [58, 58],
          [26, 52],
        ],
        [
          [0, 1],
          [1, 2],
          [2, 3],
          [3, 4],
          [4, 0],
          [1, 3],
        ],
        { dot: (i) => (i === 3 ? c.orange : c.blue) },
      ),
    test: (ctx) => {
      if (ctx.params.n < 10) return false;
      const touched = new Set<number>();
      for (let k = 1; k < ctx.history.length; k++)
        for (const i of movedPoints(ctx.history[k - 1], ctx.history[k])) {
          if (touched.has(i)) return false;
          touched.add(i);
        }
      return true;
    },
  },
  {
    id: 'only-downhill',
    name: 'Only Downhill',
    description: 'Untangle 20 points or more without a move ever adding to the red lines.',
    tier: 'gold',
    hue: 'yellow',
    // A crossing in red, and beside it a staircase that only ever steps down.
    art: (c) =>
      graph(
        c,
        [
          [20, 34],
          [50, 34],
          [20, 66],
          [50, 66],
        ],
        [
          [0, 3],
          [1, 2],
          [0, 1],
          [2, 3],
        ],
        { red: [0, 1] },
      ) +
      `<path d="M60 22 H67 V38 H74 V54 H81 V72" fill="none" stroke="${c.green}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/>` +
      `<path d="M75 67 L81 75 L87 67" fill="none" stroke="${c.green}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/>`,
    test: (ctx) => {
      if (ctx.params.n < 20) return false;
      for (let k = 1; k < ctx.history.length; k++)
        if (redLines(ctx.history[k]) > redLines(ctx.history[k - 1])) return false;
      return true;
    },
  },
]);
