/**
 * Rectangles solver.
 *
 * Like the original's, this solver is more general than solving needs: each number is
 * given a *set* of candidate cells rather than a fixed position. The generator uses this
 * to run the solver on a finished tiling before the numbers are placed, letting the
 * solver narrow the candidate cells down until the tiling is forced. For an ordinary
 * puzzle every number has exactly one candidate cell.
 *
 * Deductions, repeated until nothing changes:
 *  - a number with a single candidate cell claims that cell for its rectangle;
 *  - the intersection of all remaining placements of a rectangle belongs to it;
 *  - a placement is dropped if it covers a cell claimed by another rectangle, if it
 *    covers every candidate cell of another number, or none of its own;
 *  - a cell that only one rectangle can still cover forces that rectangle to cover it.
 *
 * On top of that, `searchSolutions` branches over a rectangle's placements to settle
 * puzzles that deduction alone leaves open.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import type { Rect } from './board';

export interface Point {
  x: number;
  y: number;
}

/** A number and the cells it could be in. */
export interface NumberData {
  area: number;
  points: Point[];
}

/** 0 = inconsistent, 1 = fully determined, 2 = still ambiguous. */
export type SolveOutcome = 0 | 1 | 2;

export interface SolveResult {
  outcome: SolveOutcome;
  /** Remaining candidate placements per number. */
  placements: Rect[][];
  /** Remaining candidate cells per number (winnowed when an RNG was given). */
  numbers: NumberData[];
}

const KNOWN_OTHER = -1;
const KNOWN_MINE = -2;

export class RectSolver {
  readonly w: number;
  readonly h: number;
  readonly n: number;
  placements: Rect[][];
  numbers: NumberData[];
  /** overlaps[(i * h + y) * w + x]: placements of rect i covering (x, y); -1/-2 = known. */
  overlaps: Int32Array;
  /** Which rectangle each cell is a candidate number position for, or -1. */
  rectByPlace: Int32Array;

  constructor(w: number, h: number, numbers: NumberData[], fromClone = false) {
    this.w = w;
    this.h = h;
    this.n = numbers.length;
    this.numbers = numbers;
    this.overlaps = new Int32Array(this.n * w * h);
    this.rectByPlace = new Int32Array(w * h).fill(-1);
    this.placements = [];
    if (fromClone) return;
    for (let i = 0; i < this.n; i++) {
      this.placements.push(this.candidatePlacements(numbers[i]));
      for (const r of this.placements[i]) this.addOverlap(i, r, 1);
    }
    for (let i = 0; i < this.n; i++) {
      for (const p of numbers[i].points) {
        if (this.rectByPlace[p.y * w + p.x] !== -1)
          throw new Error(tx`a cell may be a number position for only one rectangle`);
        this.rectByPlace[p.y * w + p.x] = i;
      }
    }
  }

  /** Every rectangle of the right area that contains at least one candidate cell. */
  private candidatePlacements(nd: NumberData): Rect[] {
    const { w, h } = this;
    const out: Rect[] = [];
    let minx = w;
    let miny = h;
    let maxx = -1;
    let maxy = -1;
    for (const p of nd.points) {
      minx = Math.min(minx, p.x);
      miny = Math.min(miny, p.y);
      maxx = Math.max(maxx, p.x);
      maxy = Math.max(maxy, p.y);
    }
    for (let rw = 1; rw <= nd.area && rw <= w; rw++) {
      if (nd.area % rw) continue;
      const rh = nd.area / rw;
      if (rh > h) continue;
      for (let y = Math.max(0, miny - rh + 1); y <= maxy && y + rh <= h; y++) {
        for (let x = Math.max(0, minx - rw + 1); x <= maxx && x + rw <= w; x++) {
          if (nd.points.some((p) => p.x >= x && p.x < x + rw && p.y >= y && p.y < y + rh))
            out.push({ x, y, w: rw, h: rh });
        }
      }
    }
    return out;
  }

  clone(): RectSolver {
    const s = new RectSolver(
      this.w,
      this.h,
      this.numbers.map((nd) => ({ area: nd.area, points: nd.points.slice() })),
      true,
    );
    s.placements = this.placements.map((list) => list.slice());
    s.overlaps.set(this.overlaps);
    s.rectByPlace.set(this.rectByPlace);
    return s;
  }

  private addOverlap(i: number, r: Rect, delta: number): void {
    const { w, h, overlaps } = this;
    for (let y = r.y; y < r.y + r.h; y++) {
      const row = (i * h + y) * w;
      for (let x = r.x; x < r.x + r.w; x++) {
        if (delta > 0) overlaps[row + x]++;
        else if (overlaps[row + x] > 0) overlaps[row + x]--;
      }
    }
  }

  private removePlacement(i: number, j: number): void {
    const list = this.placements[i];
    this.addOverlap(i, list[j], -1);
    list[j] = list[list.length - 1];
    list.pop();
  }

  private removeNumberPoint(k: number, m: number): void {
    const pts = this.numbers[k].points;
    this.rectByPlace[pts[m].y * this.w + pts[m].x] = -1;
    pts[m] = pts[pts.length - 1];
    pts.pop();
  }

  /** Claim cell (x, y) for rectangle i. Returns false when that is contradictory. */
  private claim(i: number, x: number, y: number): boolean {
    const { w, h, n, overlaps } = this;
    const idx = (i * h + y) * w + x;
    if (overlaps[idx] < KNOWN_OTHER) return true; // already ours
    if (overlaps[idx] <= 0) return false; // known to be someone else's, or unreachable
    for (let j = 0; j < n; j++) overlaps[(j * h + y) * w + x] = KNOWN_OTHER;
    overlaps[idx] = KNOWN_MINE;
    return true;
  }

  /**
   * Run the deduction loop. With `rng`, whenever deduction stalls a random candidate
   * number cell is discarded so that some placement becomes impossible (the generator's
   * way of choosing where to put the numbers).
   */
  deduce(rng?: Random | null): SolveOutcome {
    const { w, h, n, overlaps, rectByPlace, numbers, placements } = this;
    const workspace = new Int32Array(n);
    for (;;) {
      let progress = false;

      for (let i = 0; i < n; i++) {
        if (numbers[i].points.length === 1) {
          const p = numbers[i].points[0];
          if (!this.claim(i, p.x, p.y)) return 0;
        }
      }

      for (let i = 0; i < n; i++) {
        let minx = 0;
        let miny = 0;
        let maxx = w;
        let maxy = h;
        for (const r of placements[i]) {
          if (minx < r.x) minx = r.x;
          if (miny < r.y) miny = r.y;
          if (maxx > r.x + r.w) maxx = r.x + r.w;
          if (maxy > r.y + r.h) maxy = r.y + r.h;
        }
        for (let y = miny; y < maxy; y++)
          for (let x = minx; x < maxx; x++) if (!this.claim(i, x, y)) return 0;
      }

      for (let i = 0; i < n; i++) {
        const list = placements[i];
        for (let j = 0; j < list.length; j++) {
          const r = list[j];
          workspace.fill(0);
          let del = false;
          for (let y = r.y; y < r.y + r.h && !del; y++) {
            for (let x = r.x; x < r.x + r.w; x++) {
              if (overlaps[(i * h + y) * w + x] === KNOWN_OTHER) {
                del = true;
                break;
              }
              const k = rectByPlace[y * w + x];
              if (k !== -1) workspace[k]++;
            }
          }
          if (!del) {
            for (let k = 0; k < n; k++) {
              if (k !== i && workspace[k] === numbers[k].points.length) {
                del = true;
                break;
              }
            }
            if (!del && workspace[i] === 0) del = true;
          }
          if (del) {
            this.removePlacement(i, j);
            j--;
            progress = true;
          }
        }
      }

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          if (overlaps[y * w + x] < 0) continue; // known cells are negative for every rect
          let count = 0;
          let only = -1;
          for (let i = 0; i < n; i++) {
            if (overlaps[(i * h + y) * w + x] > 0) {
              count++;
              only = i;
            }
          }
          if (count !== 1) continue;
          const list = placements[only];
          for (let j = 0; j < list.length; j++) {
            const r = list[j];
            if (x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h) continue;
            this.removePlacement(only, j);
            j--;
            progress = true;
          }
        }
      }

      if (progress) continue;

      if (rng) {
        // Deduction has stalled. Find placements that cover a candidate number cell of
        // another rectangle; discarding that number's other candidates rules the
        // placement out next time round.
        const options: { rect: number; placement: number; number: number }[] = [];
        for (let i = 0; i < n; i++) {
          placements[i].forEach((r, j) => {
            for (let y = r.y; y < r.y + r.h; y++) {
              for (let x = r.x; x < r.x + r.w; x++) {
                const k = rectByPlace[y * w + x];
                if (k >= 0 && k !== i) options.push({ rect: i, placement: j, number: k });
              }
            }
          });
        }
        if (options.length) {
          const pick = options[rng.upto(options.length)];
          const r = placements[pick.rect][pick.placement];
          const pts = numbers[pick.number].points;
          for (let m = 0; m < pts.length; m++) {
            const p = pts[m];
            if (p.x < r.x || p.x >= r.x + r.w || p.y < r.y || p.y >= r.y + r.h) {
              this.removeNumberPoint(pick.number, m);
              m--;
              progress = true;
            }
          }
        }
      }

      if (!progress) break;
    }

    let outcome: SolveOutcome = 1;
    for (let i = 0; i < n; i++) {
      if (placements[i].length === 0) return 0;
      if (placements[i].length > 1) outcome = 2;
    }
    return outcome;
  }

  /** Keep only placement `j` of rectangle `i`. */
  restrict(i: number, j: number): void {
    const keep = this.placements[i][j];
    const list = this.placements[i];
    for (let k = 0; k < list.length; k++) {
      if (list[k] === keep) continue;
      this.removePlacement(i, k);
      k--;
    }
  }

  /** The single remaining placement of every rectangle. Only meaningful after outcome 1. */
  solution(): Rect[] {
    return this.placements.map((list) => list[0]);
  }
}

/** Do these rectangles tile the whole grid without overlapping? */
export function isTiling(w: number, h: number, rects: Rect[]): boolean {
  const cover = new Uint8Array(w * h);
  for (const r of rects) {
    if (r.x < 0 || r.y < 0 || r.x + r.w > w || r.y + r.h > h) return false;
    for (let y = r.y; y < r.y + r.h; y++) {
      for (let x = r.x; x < r.x + r.w; x++) {
        if (cover[y * w + x]) return false;
        cover[y * w + x] = 1;
      }
    }
  }
  return cover.every((c) => c === 1);
}

/** Run the deductive solver once. `numbers` is not modified. */
export function solveRects(
  w: number,
  h: number,
  numbers: NumberData[],
  rng?: Random | null,
): SolveResult {
  const s = new RectSolver(
    w,
    h,
    numbers.map((nd) => ({ area: nd.area, points: nd.points.slice() })),
  );
  let outcome = s.deduce(rng);
  if (outcome === 1 && !isTiling(w, h, s.solution())) outcome = 0;
  return { outcome, placements: s.placements, numbers: s.numbers };
}

/**
 * Find up to `limit` tilings satisfying the numbers, by deduction plus branching over
 * the placements of the most constrained undecided rectangle.
 */
export function searchSolutions(w: number, h: number, numbers: NumberData[], limit = 2): Rect[][] {
  const out: Rect[][] = [];
  const root = new RectSolver(
    w,
    h,
    numbers.map((nd) => ({ area: nd.area, points: nd.points.slice() })),
  );
  const visit = (s: RectSolver): void => {
    const outcome = s.deduce();
    if (outcome === 0) return;
    if (outcome === 1) {
      const sol = s.solution();
      if (isTiling(w, h, sol)) out.push(sol);
      return;
    }
    let best = -1;
    for (let i = 0; i < s.n; i++) {
      const len = s.placements[i].length;
      if (len > 1 && (best < 0 || len < s.placements[best].length)) best = i;
    }
    for (let j = 0; j < s.placements[best].length && out.length < limit; j++) {
      const branch = s.clone();
      branch.restrict(best, j);
      visit(branch);
    }
  };
  visit(root);
  return out;
}

/** Numbers of an ordinary puzzle: one candidate cell each. */
export function numbersOfGrid(w: number, h: number, grid: ArrayLike<number>): NumberData[] {
  const out: NumberData[] = [];
  for (let i = 0; i < w * h; i++) {
    if (grid[i]) out.push({ area: grid[i], points: [{ x: i % w, y: Math.floor(i / w) }] });
  }
  return out;
}
