import { LEFT_BUTTON, LEFT_DRAG, LEFT_RELEASE, MIDDLE_BUTTON, RIGHT_BUTTON } from './input';
import type { Midend } from './midend';

/** A rectangle in canvas CSS pixels. */
export interface TutorialRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** What the tutorial engine hands to step callbacks. */
export interface TutorialCtx<S = any, U = any> {
  state: S;
  ui: U;
  tileSize: number;
  midend: Midend;
  /**
   * True on a touch screen, where `textTouch` is what the player reads. A pointer hint that
   * has to agree with that text (a `textTouch` that says "tap" where the mouse text says
   * "right-click") reads it.
   */
  touch?: boolean;
}

export interface PointerHint {
  /** Canvas position of the hint. */
  x: number;
  y: number;
  /** For drags: where the pointer should end up. */
  to?: { x: number; y: number };
  /**
   * Which button the hint suggests (default left). `middle` is tagged "middle-click", or
   * "two-finger tap" on a touch screen.
   */
  button?: 'left' | 'middle' | 'right';
}

export interface TutorialStep<S = any, U = any> {
  /** Markdown shown in the callout. Keep it to one or two short sentences. */
  text: string;
  /** Load this puzzle when entering the step (usually only on the first step). */
  gameId?: string;
  /** Canvas region(s) to spotlight, computed from the current state. */
  highlight?: (ctx: TutorialCtx<S, U>) => TutorialRect | TutorialRect[] | null;
  /**
   * CSS selector of a page element to spotlight as well as (or instead of) `highlight`:
   * a toolbar button, or a key of the on-screen keypad (`'[data-key="5"]'`). An element
   * that is not on screen — the keypad with a mouse, say — is quietly ignored.
   */
  target?: string;
  /** Animated pointer hint, recomputed whenever the state changes. */
  pointer?: (ctx: TutorialCtx<S, U>) => PointerHint | null;
  /**
   * When present, the step completes automatically once this returns true after a state
   * change; otherwise the player presses Next.
   */
  waitFor?: (ctx: TutorialCtx<S, U>) => boolean;
  /** Where to place the callout relative to the highlight (default auto). */
  placement?: 'above' | 'below' | 'left' | 'right';
  /** Alternative text for touch devices (no keyboard, long-press instead of right-click). */
  textTouch?: string;
  /** Skip this step entirely on touch devices (e.g. it teaches a keyboard shortcut). */
  desktopOnly?: boolean;
  /**
   * Let the player move freely during this step. By default a move the step did not ask
   * for — any board change that leaves `waitFor` false, or any at all on a step without
   * one — is taken back, so the steps after it still describe the board. Set this on a
   * step whose `waitFor` needs several moves to come true. The last step is always free.
   */
  free?: boolean;
  /**
   * Keys the step's move needs after its pointer hint ("click the square and press **2**"),
   * one character each (`''` for Backspace). "Skip step" presses them when it makes the
   * step's move for the player; see {@link demonstrate}.
   */
  press?: string;
}

export interface Tutorial<S = any, U = any> {
  steps: TutorialStep<S, U>[];
}

/**
 * The steps a player actually sees. `desktopOnly` steps (keyboard shortcuts and the like)
 * disappear on touch devices, and the step counter is based on this list so it never
 * announces "Step 3 of 6" for a walkthrough that only shows five.
 */
export function visibleSteps<S, U>(
  steps: TutorialStep<S, U>[],
  touch: boolean,
): TutorialStep<S, U>[] {
  return touch ? steps.filter((s) => !s.desktopOnly) : steps;
}

/** The text to show for a step: `textTouch` replaces `text` on touch devices. */
export function stepText(step: TutorialStep, touch: boolean): string {
  return (touch && step.textTouch) || step.text;
}

/** Helper for the common case of highlighting one grid cell. */
export function cellRect(
  x: number,
  y: number,
  tileSize: number,
  border: number,
  cells = 1,
  rows = 1,
): TutorialRect {
  return {
    x: border + x * tileSize,
    y: border + y * tileSize,
    w: cells * tileSize,
    h: rows * tileSize,
  };
}

/** Centre of a grid cell, for pointer hints. */
export function cellCentre(
  x: number,
  y: number,
  tileSize: number,
  border: number,
): { x: number; y: number } {
  return { x: border + (x + 0.5) * tileSize, y: border + (y + 0.5) * tileSize };
}

/**
 * Do what a pointer hint shows: press its button, drag along to `to` if it has one, and
 * let go. "Skip step" uses it to make a step's move for the player, so the steps after it
 * still describe the board.
 */
export function playHint(midend: Midend, hint: PointerHint): void {
  const down =
    hint.button === 'right' ? RIGHT_BUTTON : hint.button === 'middle' ? MIDDLE_BUTTON : LEFT_BUTTON;
  const offset = down - LEFT_BUTTON;
  const key = (x: number, y: number, b: number) =>
    midend.processKey(Math.round(x), Math.round(y), b);
  key(hint.x, hint.y, down);
  const to = hint.to;
  if (to) {
    const n = 8;
    for (let k = 1; k <= n; k++) {
      key(
        hint.x + ((to.x - hint.x) * k) / n,
        hint.y + ((to.y - hint.y) * k) / n,
        LEFT_DRAG + offset,
      );
    }
  }
  const end = to ?? hint;
  key(end.x, end.y, LEFT_RELEASE + offset);
}

/**
 * Make a step's move the way the player was asked to: play its pointer hint as a mouse
 * would (a touch screen's hint may stand for a different gesture), then press its `press`
 * keys if the hint only picked something out. A hint that only changes the selection (pick
 * a peg up, then the hole) is played again from the new selection, a few times at most.
 * True when the step's `waitFor` is satisfied afterwards.
 */
export function demonstrate<S, U>(
  midend: Midend,
  step: TutorialStep<S, U>,
  ctx: () => TutorialCtx<S, U>,
): boolean {
  const done = () => !!step.waitFor?.(ctx());
  if (!step.waitFor || !midend.hasGame) return false;
  for (let round = 0; round < 3; round++) {
    const hint = step.pointer?.({ ...ctx(), touch: false }) ?? null;
    const before = midend.state;
    if (hint) playHint(midend, hint);
    if (step.press && midend.state === before) {
      for (const ch of step.press) midend.processKey(0, 0, ch.charCodeAt(0));
    }
    if (done()) return true;
    if (!hint || midend.state !== before) break;
  }
  return done();
}
