/**
 * Unequal solver: latin-square reasoning plus the deductions the clue signs allow.
 *
 * Difficulty levels, each adding to the previous:
 *  - **Trivial**: latin-square deductions only (no signs are needed, or generated).
 *  - **Easy**: a `>` sign bounds both cells: the greater side cannot be as small as the
 *    smaller side's smallest candidate, and vice versa. In Adjacent mode a placed digit
 *    fixes its neighbours to (or away from) the two adjacent values.
 *  - **Tricky**: set elimination within rows and columns; in Adjacent mode also the
 *    candidate-set form of the adjacency rule (a neighbour can only be a value that is
 *    adjacent to — or non-adjacent to — *some* candidate of this cell).
 *  - **Extreme**: positional set elimination per digit and forcing chains.
 *  - **Recursive**: guessing, with every branch explored so uniqueness is known.
 */
import type { Puzzle } from './board';
import { DIRS } from './board';
import { DIFF_AMBIGUOUS, DIFF_IMPOSSIBLE, DIFF_UNFINISHED, LatinSolver, latinSolve } from './latin';
import type { LatinLevels, SolveBudget, UserSolver } from './latin';

export const DIFF_LATIN = 0;
export const DIFF_EASY = 1;
export const DIFF_SET = 2;
export const DIFF_EXTREME = 3;
export const DIFF_RECURSIVE = 4;
export const DIFFICULTY_NAMES = ['Trivial', 'Easy', 'Tricky', 'Extreme', 'Recursive'];
/** Letters used in parameter strings, in difficulty order. */
export const DIFFICULTY_CHARS = 'tekxr';

const LEVELS: LatinLevels = {
  simple: DIFF_LATIN,
  set: DIFF_SET,
  positionalSet: DIFF_EXTREME,
  forcing: DIFF_EXTREME,
  recursive: DIFF_RECURSIVE,
};

export interface SolveResult {
  /** −1 impossible, 0 not finished within the allowed reasoning, 1 solved, 2 ambiguous. */
  status: -1 | 0 | 1 | 2;
  /** The hardest level used when solved, else one of the DIFF_* special values. */
  diff: number;
  /** Remaining candidates per cell (see `cubeIndex`), useful as pencil-mark hints. */
  cube: Uint8Array;
}

/** A `>` clue: (gx, gy) is greater than (lx, ly). */
interface Link {
  gx: number;
  gy: number;
  lx: number;
  ly: number;
}

function buildLinks(puzzle: Puzzle): Link[] {
  const links: Link[] = [];
  const o = puzzle.order;
  for (let y = 0; y < o; y++)
    for (let x = 0; x < o; x++)
      for (const d of DIRS)
        if (puzzle.flags[y * o + x] & d.f) links.push({ gx: x, gy: y, lx: x + d.dx, ly: y + d.dy });
  return links;
}

/** Easy, Unequal mode: trim each end of every `>` link against the other end's range. */
function linkElim(links: Link[]): UserSolver {
  return (s) => {
    const o = s.o;
    let changed = 0;
    for (const l of links) {
      const [, gmax] = s.minMax(l.gx, l.gy);
      const [lmin] = s.minMax(l.lx, l.ly);
      for (let j = 0; j < o; j++) {
        // The greater end cannot be at or below the smaller end's minimum...
        if (j < lmin + 1 && s.has(l.gx, l.gy, j + 1)) changed += s.rule(l.gx, l.gy, j + 1);
        // ...and the smaller end cannot be at or above the greater end's maximum.
        if (j > gmax - 1 && s.has(l.lx, l.ly, j + 1)) changed += s.rule(l.lx, l.ly, j + 1);
      }
    }
    return changed;
  };
}

/** Easy, Adjacent mode: a placed digit decides which values its neighbours may take. */
function adjacentElim(puzzle: Puzzle): UserSolver {
  const o = puzzle.order;
  return (s) => {
    let changed = 0;
    for (let x = 0; x < o; x++) {
      for (let y = 0; y < o; y++) {
        const v = s.grid[y * o + x];
        if (!v) continue;
        for (const d of DIRS) {
          const nx = x + d.dx;
          const ny = y + d.dy;
          if (nx < 0 || ny < 0 || nx >= o || ny >= o) continue;
          const isAdj = (puzzle.flags[y * o + x] & d.f) !== 0;
          for (let n = 1; n <= o; n++) {
            const gd = Math.abs(n - v);
            if (isAdj ? gd === 1 : gd !== 1) continue; // still allowed
            changed += s.rule(nx, ny, n);
          }
        }
      }
    }
    return changed;
  };
}

/**
 * Tricky, Adjacent mode: a neighbour may only hold values compatible with at least one
 * of this cell's remaining candidates.
 */
function adjacentSetElim(puzzle: Puzzle): UserSolver {
  const o = puzzle.order;
  const scratch = new Uint8Array(o);
  return (s) => {
    let changed = 0;
    for (let x = 0; x < o; x++) {
      for (let y = 0; y < o; y++) {
        for (const d of DIRS) {
          const nx = x + d.dx;
          const ny = y + d.dy;
          if (nx < 0 || ny < 0 || nx >= o || ny >= o) continue;
          const isAdj = (puzzle.flags[y * o + x] & d.f) !== 0;
          scratch.fill(0);
          for (let n = 0; n < o; n++) {
            if (!s.has(x, y, n + 1)) continue;
            for (let nn = 0; nn < o; nn++) {
              if (n === nn) continue;
              const gd = Math.abs(nn - n);
              if (isAdj ? gd !== 1 : gd === 1) continue;
              scratch[nn] = 1;
            }
          }
          for (let n = 0; n < o; n++) if (!scratch[n]) changed += s.rule(nx, ny, n + 1);
        }
      }
    }
    return changed;
  };
}

/**
 * Solve `nums` (modified in place: digits the solver is sure of are filled in) using
 * reasoning up to `maxdiff`. The clue signs come from `puzzle`; `nums` may include the
 * player's own entries. A `budget` caps the guessing at the Recursive level; running out
 * reports status 0, as if the reasoning allowed had not been enough.
 */
export function solvePuzzle(
  puzzle: Puzzle,
  nums: Uint8Array,
  maxdiff: number,
  budget?: SolveBudget,
): SolveResult {
  const users: (UserSolver | null)[] = [null, null, null, null, null];
  if (puzzle.adjacent) {
    users[DIFF_EASY] = adjacentElim(puzzle);
    users[DIFF_SET] = adjacentSetElim(puzzle);
  } else {
    users[DIFF_EASY] = linkElim(buildLinks(puzzle));
  }
  const solver = new LatinSolver(nums, puzzle.order);
  const diff = latinSolve(solver, maxdiff, LEVELS, users, budget);
  const status =
    diff === DIFF_IMPOSSIBLE ? -1 : diff === DIFF_UNFINISHED ? 0 : diff === DIFF_AMBIGUOUS ? 2 : 1;
  return { status, diff, cube: solver.cube };
}

/** The difficulty of a puzzle from its givens: the first level whose solver finishes it. */
export function rateDifficulty(puzzle: Puzzle): number {
  for (let d = DIFF_LATIN; d <= DIFF_RECURSIVE; d++) {
    const r = solvePuzzle(puzzle, puzzle.given.slice(), d);
    if (r.status === 1) return d;
    if (r.status !== 0) return r.diff;
  }
  return DIFF_UNFINISHED;
}
