import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { SlantParams, SlantState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** `n`×`n` squares of side `s`, with the grid points as small dots like the board's. */
function grid(c: C, x: number, y: number, s: number, n: number): string {
  let out = shape(`M${x} ${y} h${n * s} v${n * s} h${-n * s} Z`, c.paper, c.ink, 3.5);
  for (let i = 1; i < n; i++)
    out += line(`M${x + i * s} ${y} v${n * s} M${x} ${y + i * s} h${n * s}`, c.faint, 2.5);
  return out;
}

/** A diagonal through square (col, row): `\` when `back`, else `/`. */
function slash(x: number, y: number, s: number, col: number, row: number, back: boolean) {
  const x0 = x + col * s;
  const y0 = y + row * s;
  return back ? `M${x0} ${y0} L${x0 + s} ${y0 + s} ` : `M${x0} ${y0 + s} L${x0 + s} ${y0} `;
}

/** A pencil whose point is at (x, y), lying at `deg` degrees (0 = pointing straight down). */
function pencil(c: C, x: number, y: number, deg: number, k = 1): string {
  return (
    `<g transform="translate(${x} ${y}) rotate(${deg}) scale(${k})">` +
    shape('M0 0 L-6 -12 H6 Z', c.paper, c.ink, 3.5) +
    shape('M-2 -4 L0 0 L2 -4 Z', c.ink, c.ink, 2) +
    shape('M-6 -12 H6 V-40 H-6 Z', c.yellow, c.ink, 3.5) +
    shape('M-6 -40 H6 V-47 H-6 Z', c.pink, c.ink, 3.5) +
    '</g>'
  );
}

/**
 * Whether no square was changed again after the player had moved on from it. Clicking
 * one square several times in a row (cycling round to the line wanted) is one go.
 */
function neverRevisited<S>(history: readonly S[], cells: (s: S) => ArrayLike<number>): boolean {
  const settled = new Set<number>();
  let current = -1;
  for (let k = 1; k < history.length; k++) {
    const a = cells(history[k - 1]);
    const b = cells(history[k]);
    const changed: number[] = [];
    for (let i = 0; i < b.length; i++) if (a[i] !== b[i]) changed.push(i);
    const only = changed.length === 1 ? changed[0] : -1;
    if (current >= 0 && current !== only && a[current]) settled.add(current);
    for (const i of changed) if (settled.has(i)) return false;
    if (only < 0) for (const i of changed) if (b[i]) settled.add(i);
    current = only;
  }
  return true;
}

export const achievements = defineAchievements<SlantParams, SlantState>([
  {
    id: 'no-loops',
    name: 'Loop-Free',
    description: 'Solve an 8×8 or larger Slant without ever closing a loop.',
    tier: 'silver',
    hue: 'green',
    art: (c) =>
      grid(c, 22, 22, 28, 2) +
      // Three sides of the diamond a loop would make; the fourth leans the other way.
      line(slash(22, 22, 28, 1, 1, false), c.lowlight, 5).replace(
        '/>',
        ' stroke-dasharray="2 9"/>',
      ) +
      line(
        slash(22, 22, 28, 0, 0, false) +
          slash(22, 22, 28, 1, 0, true) +
          slash(22, 22, 28, 0, 1, true),
        c.ink,
        7,
      ) +
      line(slash(22, 22, 28, 1, 1, true), c.green, 7),
    test: (ctx) =>
      ctx.params.w * ctx.params.h >= 64 && ctx.history.every((s) => !s.loopErr.includes(1)),
  },
  {
    id: 'steady-hand',
    name: 'No Second Guesses',
    description: 'Solve a 12×10 Slant without going back to change a line.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) =>
      grid(c, 18, 24, 22, 2) +
      line(
        slash(18, 24, 22, 0, 0, true) +
          slash(18, 24, 22, 1, 0, false) +
          slash(18, 24, 22, 0, 1, false),
        c.ink,
        7,
      ) +
      line(slash(18, 24, 22, 1, 1, true), c.blue, 7) +
      pencil(c, 62, 68, 40, 0.8),
    test: (ctx) => ctx.params.w * ctx.params.h >= 120 && neverRevisited(ctx.history, (s) => s.soln),
  },
]);
