import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { BridgesParams, BridgesState } from './index';
import { DIFF_HARD } from './solver';

type C = typeof PALETTE;

function island(c: C, cx: number, cy: number, r = 9.5): string {
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.paper}" stroke="${c.ink}" stroke-width="4.5"/>`;
}

function bridge(c: C, d: string): string {
  return `<path d="${d}" stroke="${c.ink}" stroke-width="4.5" stroke-linecap="round"/>`;
}

/** The pencilled "no bridge here" cross. */
function noline(c: C, cx: number, cy: number, r: number): string {
  return `<path d="M${cx - r} ${cy - r} L${cx + r} ${cy + r} M${cx + r} ${cy - r} L${cx - r} ${cy + r}" stroke="${c.pencil}" stroke-width="3.5" stroke-linecap="round"/>`;
}

export const achievements = defineAchievements<BridgesParams, BridgesState>([
  {
    id: 'no-markers',
    name: 'Clear Waters',
    description: 'Solve a 10×10 or larger puzzle without drawing a single "no bridge" marker.',
    tier: 'silver',
    hue: 'teal',
    // A double bridge below; above it, the pencilled markers that were never needed.
    art: (c) =>
      bridge(c, 'M30 60 H70 M30 70 H70') +
      island(c, 24, 65) +
      island(c, 76, 65) +
      noline(c, 42, 32, 5) +
      noline(c, 58, 32, 5) +
      `<circle cx="50" cy="32" r="17" fill="none" stroke="${c.red}" stroke-width="4.5"/>` +
      `<path d="M38 44 L62 20" stroke="${c.red}" stroke-width="4.5" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.w >= 10 && ctx.params.h >= 10 && ctx.history.every((s) => !s.noline.includes(1)),
  },
  {
    id: 'sure-footing',
    name: 'Sure Footing',
    description: 'Solve a 10×10 or larger Hard puzzle without removing a bridge or using Undo.',
    tier: 'gold',
    hue: 'blue',
    // A finished ring of islands, every bridge laid once and left alone.
    art: (c) =>
      bridge(c, 'M30 24 H70 M30 33 H70 M26 30 V70 M70 30 V70 M79 30 V70 M30 72 H70') +
      island(c, 26, 28) +
      island(c, 74, 28) +
      island(c, 26, 72) +
      island(c, 74, 72) +
      `<path d="M39 51 L47 59 L62 42" fill="none" stroke="${c.ok}" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>`,
    test: (ctx) => {
      if (ctx.params.w < 10 || ctx.params.h < 10 || ctx.params.difficulty < DIFF_HARD) return false;
      if (ctx.undos > 0) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].bridges;
        const b = ctx.history[k].bridges;
        for (let e = 0; e < a.length; e++) if (b[e] < a[e]) return false;
      }
      return true;
    },
  },
]);
