import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cubeIndex } from './board';
import type { UnequalState, UnequalUI } from './index';

/** The same geometry `computeSize` and `redraw` use. */
function geom(t: number) {
  const gap = Math.round(t * 0.5);
  const border = Math.round(t * 0.3);
  return { t, gap, border, pitch: t + gap };
}

/** One cell of the grid. */
function cell(t: number, x: number, y: number, cells = 1): TutorialRect {
  const g = geom(t);
  return {
    x: g.border + x * g.pitch,
    y: g.border + y * g.pitch,
    w: cells * g.t + (cells - 1) * g.gap,
    h: g.t,
  };
}

const centre = (r: TutorialRect) => ({ x: r.x + r.w / 2, y: r.y + r.h / 2 });

const num = (state: UnequalState, x: number, y: number) => state.nums[y * state.order + x];

/** Is anything pencilled into cell (x, y)? */
function hasHint(state: UnequalState, x: number, y: number): boolean {
  for (let n = 1; n <= state.order; n++)
    if (state.hints[cubeIndex(state.order, x, y, n)]) return true;
  return false;
}

export const tutorial: Tutorial<UnequalState, UnequalUI> = {
  steps: [
    {
      gameId: '4:4D,1,0R,0,2D,3U,4R,1,1,4,0,0,3R,2,1,4U,',
      text: 'Each row and column needs 1, 2, 3 and 4 once each — and every sign between two cells must point at the **smaller** of the pair.',
      highlight: ({ state, tileSize }) => {
        const g = geom(tileSize);
        const size = state.order * g.t + (state.order - 1) * g.gap;
        return { x: g.border, y: g.border, w: size, h: size };
      },
    },
    {
      text: 'The sign here points right, so the **left** cell is the bigger one. This row still needs a 2 and a 3: click the left cell and press **3**.',
      textTouch:
        'The sign here points right, so the **left** cell is the bigger one. This row still needs a 2 and a 3: tap the left cell, then tap **3** on the keypad.',
      target: '[data-key="3"]',
      highlight: ({ tileSize }) => cell(tileSize, 2, 0, 2),
      pointer: ({ tileSize }) => centre(cell(tileSize, 2, 0)),
      press: '3',
      waitFor: ({ state }) => num(state, 2, 0) === 3,
    },
    {
      text: 'The cell the sign points at gets the smaller number. Click it and press **2**.',
      textTouch:
        'The cell the sign points at gets the smaller number. Tap it, then tap **2** on the keypad.',
      target: '[data-key="2"]',
      highlight: ({ tileSize }) => cell(tileSize, 3, 0),
      pointer: ({ tileSize }) => centre(cell(tileSize, 3, 0)),
      press: '2',
      waitFor: ({ state }) => num(state, 3, 0) === 2,
    },
    {
      text: 'Its column now has a 3, so this cell can only be a 2. **Right-click** it and press **2** to pencil that in as a note.',
      textTouch:
        'Its column now has a 3, so this cell can only be a 2. Tap it, latch **✎** on the keypad and tap **2** to pencil that in as a note.',
      target: '[data-key="pencil"]',
      highlight: ({ tileSize }) => cell(tileSize, 2, 2),
      // A plain tap on a touch screen, as `textTouch` says: a long-press selects the cell
      // for pencil marks itself, and then the next step's "tap ✎ to stop pencilling" does
      // not stop it — the 2 rubs the note out again and the step never completes.
      pointer: ({ tileSize, touch }) => ({
        ...centre(cell(tileSize, 2, 2)),
        ...(touch ? {} : { button: 'right' as const }),
      }),
      press: '2',
      waitFor: ({ state }) => hasHint(state, 2, 2),
    },
    {
      text: 'A note is not an answer. **Left-click** the same cell and press **2** to commit to it.',
      textTouch:
        'A note is not an answer. The cell is still chosen, so tap **✎** to stop pencilling and then **2** to commit to it.',
      target: '[data-key="2"]',
      highlight: ({ tileSize }) => cell(tileSize, 2, 2),
      // On a touch screen the cell is still chosen from the last step, and tapping it
      // again — what a pointer on it asks for — would deselect it; point at it only when
      // it is not chosen any more.
      pointer: ({ tileSize, ui, touch }) =>
        touch && ui.hshow && ui.hx === 2 && ui.hy === 2 ? null : centre(cell(tileSize, 2, 2)),
      press: '2',
      waitFor: ({ state }) => num(state, 2, 2) === 2,
    },
    {
      text: 'One cell left. Click it and press **3** to finish the square.',
      textTouch: 'One cell left. Tap it, then tap **3** on the keypad to finish the square.',
      highlight: ({ tileSize }) => cell(tileSize, 3, 2),
      pointer: ({ tileSize }) => centre(cell(tileSize, 3, 2)),
      press: '3',
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! **Undo** takes back a digit, and **Solve** fills in the answer if a puzzle beats you.',
      textTouch:
        'Solved! **Undo** takes back a digit, **Marks** and **Hint** pencil the possibilities in, and **Solve** fills in the answer if a puzzle beats you.',
      target: '[data-cmd="undo"]',
    },
  ],
};
