import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { InertiaState, InertiaUI } from './index';

const border = (t: number) => Math.round(t * 0.5);

/** The ball has come to rest on (x, y). */
const restingAt = (s: InertiaState, x: number, y: number) => s.px === x && s.py === y;

export const tutorial: Tutorial<InertiaState, InertiaUI> = {
  steps: [
    {
      gameId: '6x5:Sbgbbbbwbbwgsbmbbswbbmbmbsbgbb',
      text: 'You are the ball in the top-left corner, and there are **three gems** to collect. Once the ball starts rolling it only halts at a wall or a stop — and a mine kills it.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'Click a square to the **right** of the ball. It rolls that way until the edge of the board stops it, sweeping up the gem it passes.',
      highlight: ({ state, tileSize }) => {
        const from = Math.min(state.px + 1, state.w - 1);
        return cellRect(from, state.py, tileSize, border(tileSize), state.w - from);
      },
      pointer: ({ tileSize }) => cellCentre(4, 0, tileSize, border(tileSize)),
      waitFor: ({ state }) => restingAt(state, 5, 0),
    },
    {
      text: 'Now click **below** the ball. It takes the next gem and the broken ring two squares down — a stop — brings it to a halt.',
      highlight: ({ tileSize }) => cellRect(5, 1, tileSize, border(tileSize), 1, 2),
      pointer: ({ tileSize }) => cellCentre(5, 2, tileSize, border(tileSize)),
      waitFor: ({ state }) => restingAt(state, 5, 2),
      placement: 'left',
    },
    {
      text: 'Careful: the spiky thing directly below the ball is a **mine**. Rolling onto one ends the game, and only Undo gets you out of it.',
      highlight: ({ tileSize }) => cellRect(5, 3, tileSize, border(tileSize)),
      placement: 'left',
    },
    {
      text: 'Go **diagonally** instead: click the square two down and two left, and the ball slides past the mine onto the last gem.',
      highlight: ({ tileSize }) => [
        cellRect(4, 3, tileSize, border(tileSize)),
        cellRect(3, 4, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(3, 4, tileSize, border(tileSize)),
      waitFor: ({ midend }) => midend.status() === 1,
      placement: 'below',
    },
    {
      text: 'All three gems — done. **Undo** rewinds a roll that went wrong; the arrow keys roll straight and Home, Page Up, End and Page Down roll diagonally.',
      textTouch:
        'All three gems — done. **Undo** rewinds a roll that went wrong, and tapping outside the grid works too, which helps when the ball is against an edge.',
      target: '[data-cmd="undo"]',
    },
  ],
};
