import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_UP,
  LEFT_BUTTON,
  MOD_NUM_KEYPAD,
  stripMods,
} from '../../framework/input';
import { clamp, flashOn } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  DIRS,
  SOLIDS,
  SOLID_KINDS,
  canvasSize,
  directionTo,
  facesViewer,
  gridArea,
  gridFor,
  layout,
  project,
  restPose,
  rollFaceMap,
  rollPose,
} from './geometry';
import type { Dir, Grid, Pose, SolidKind, Vec3 } from './geometry';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export interface CubeParams {
  solid: SolidKind;
  /** Square grid: width and height. Triangular grid: length of the top and bottom sides. */
  d1: number;
  d2: number;
}

export interface CubeState {
  solid: SolidKind;
  d1: number;
  d2: number;
  /** 1 for each grid cell that is currently blue. */
  blue: number[];
  /** 1 for each face of the solid that is blue, indexed like `Solid.faces`. */
  faces: number[];
  /** Cell the solid rests on. */
  cell: number;
  /** Cell it rolled from in the last move, or -1 (drives the animation). */
  prev: number;
  moves: number;
  /** Move count at which every face became blue, or 0. */
  completed: number;
}

export type CubeUI = Record<string, never>;

const ANIM = 0.16;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_DIM = 10;
const SOLID_NAMES = SOLID_KINDS.map((k) => SOLIDS[k].name);

// ---------------------------------------------------------------- descriptions

/** Pack cell flags into hex, four cells per digit, first cell in the high bit. */
export function encodeBlue(blue: number[]): string {
  let out = '';
  for (let i = 0; i < blue.length; i += 4) {
    let v = 0;
    for (let b = 0; b < 4; b++) if (blue[i + b]) v |= 8 >> b;
    out += v.toString(16).toUpperCase();
  }
  return out;
}

/** Parse a description into its parts, or return a user-facing error. */
function parseDesc(p: CubeParams, desc: string): { blue: number[]; cell: number } | string {
  const area = gridArea(p.solid, p.d1, p.d2);
  const digits = Math.ceil(area / 4);
  const m = /^([0-9a-fA-F]+),(\d+)$/.exec(desc);
  if (!m) return tx`Description must be hex digits, a comma and a cell number`;
  if (m[1].length !== digits) return tx`Description must start with ${digits} hex digits`;
  const blue: number[] = [];
  for (const ch of m[1]) {
    const v = parseInt(ch, 16);
    for (let b = 3; b >= 0; b--) blue.push((v >> b) & 1);
  }
  if (blue.slice(area).some((v) => v)) return tx`Description marks cells beyond the grid as blue`;
  blue.length = area;
  const cell = parseInt(m[2], 10);
  if (cell >= area) return tx`Starting cell is outside the grid`;
  if (blue[cell]) return tx`The solid cannot start on a blue cell`;
  const solid = SOLIDS[p.solid];
  const total = blue.reduce((a, b) => a + b, 0);
  if (total !== solid.faces.length)
    return tx`Description must mark exactly ${solid.faces.length} cells blue`;
  const grid = gridFor(p);
  const perClass = solid.faces.length / solid.nclasses;
  for (let c = 0; c < solid.nclasses; c++) {
    let n = 0;
    for (let i = 0; i < area; i++) if (blue[i] && grid.classes[i] === c) n++;
    if (n !== perClass) return tx`Blue cells are placed where some faces could never reach them`;
  }
  return { blue, cell };
}

// ----------------------------------------------------------------------- moves

function allBlue(faces: number[]): boolean {
  return faces.every((f) => f === 1);
}

/** Roll the solid one cell in direction `dir`, or return null if there is no cell there. */
export function roll(state: CubeState, dir: Dir): CubeState | null {
  const grid = gridFor(state);
  const solid = SOLIDS[state.solid];
  const to = grid.cells[state.cell].nb[dir];
  if (to < 0) return null;
  const map = rollFaceMap(solid, grid, state.cell, to);
  const faces = map.map((j) => state.faces[j]);
  const blue = state.blue.slice();
  const moves = state.moves + 1;
  let completed = state.completed;
  // Once finished the all-blue solid may still be rolled about, but nothing changes hands.
  if (!completed) {
    const landed = faces[solid.bottom];
    faces[solid.bottom] = blue[to];
    blue[to] = landed;
    if (allBlue(faces)) completed = moves;
  }
  return { ...state, blue, faces, cell: to, prev: state.cell, moves, completed };
}

/**
 * Keypad diagonals on a triangular grid: a down-pointing triangle has two edges facing
 * upwards and one below, an up-pointing one the reverse, so each diagonal is read as the
 * edge nearest to it. Squares have no diagonal moves.
 */
function diagonal(grid: Grid, cell: number, digit: string): Dir | null {
  if (grid.kind === 'c') return null;
  const flip = grid.cells[cell].flip;
  switch (digit) {
    case '7':
      return flip ? 'U' : 'L';
    case '9':
      return flip ? 'U' : 'R';
    case '1':
      return flip ? 'L' : 'D';
    case '3':
      return flip ? 'R' : 'D';
  }
  return null;
}

// --------------------------------------------------------------------- drawing

/** Light from the upper left and above, for shading the faces. */
const LIGHT: Vec3 = (() => {
  const v: Vec3 = [-1, -1.5, 2.2];
  const len = Math.hypot(...v);
  return [v[0] / len, v[1] / len, v[2] / len];
})();

const game = defineGame<CubeParams, CubeState, CubeUI>({
  id: 'cube',
  name: 'Cube',
  description: 'Roll a solid around a grid to pick up every blue square on its faces.',
  help,
  tutorial,
  achievements,
  presets: [
    { name: 'Cube', params: { solid: 'c', d1: 4, d2: 4 } },
    { name: 'Tetrahedron', params: { solid: 't', d1: 1, d2: 2 } },
    { name: 'Octahedron', params: { solid: 'o', d1: 2, d2: 2 } },
    { name: 'Icosahedron', params: { solid: 'i', d1: 3, d2: 3 } },
  ],
  defaultParams: () => ({ solid: 'c', d1: 4, d2: 4 }),

  encodeParams: (p) => `${p.solid}${p.d1}x${p.d2}`,
  decodeParams(str) {
    const m = /^([tcoi]?)(\d+)(?:x(\d+))?$/.exec(str);
    if (!m) throw new Error(tx`expected a solid letter followed by WxH`);
    const d1 = parseInt(m[2], 10);
    return { solid: (m[1] || 'c') as SolidKind, d1, d2: m[3] ? parseInt(m[3], 10) : d1 };
  },
  validateParams(p) {
    if (!SOLID_KINDS.includes(p.solid)) return tx`Unrecognised solid type`;
    if (!Number.isInteger(p.d1) || !Number.isInteger(p.d2))
      return tx`Grid dimensions must be whole numbers`;
    const solid = SOLIDS[p.solid];
    if (solid.order === 4) {
      if (p.d1 < 1 || p.d2 < 1) return tx`Both grid dimensions must be at least one`;
      if (p.d1 < 2 || p.d2 < 2)
        return tx`A cube rolling along a single row can never turn over all six faces`;
    } else if (p.d1 < 0 || p.d2 < 0) {
      return tx`Grid dimensions cannot be negative`;
    } else if (p.d1 === 0 && p.d2 === 0) {
      return tx`At least one grid dimension must be greater than zero`;
    }
    if (p.d1 > MAX_DIM || p.d2 > MAX_DIM) return tx`Grid dimensions must be at most ${MAX_DIM}`;
    const area = gridArea(p.solid, p.d1, p.d2);
    if (area < solid.faces.length + 1)
      return tx`Not enough space to place the solid on an empty cell`;
    const grid = gridFor(p);
    const perClass = solid.faces.length / solid.nclasses;
    for (let c = 0; c < solid.nclasses; c++) {
      if (grid.classes.filter((x) => x === c).length < perClass)
        return tx`Not enough grid space to place all blue faces`;
    }
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      {
        type: 'choices',
        name: 'Type of solid',
        choices: SOLID_NAMES,
        selected: SOLID_KINDS.indexOf(p.solid),
      },
      { type: 'string', name: 'Width / top', value: String(p.d1) },
      { type: 'string', name: 'Height / bottom', value: String(p.d2) },
    ];
  },
  customParams(items) {
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const sel = (items[0] as { selected: number }).selected;
    return { solid: SOLID_KINDS[sel] ?? 'c', d1: int(1), d2: int(2) };
  },

  newDesc(p, rng: Random) {
    const grid = gridFor(p);
    const solid = SOLIDS[p.solid];
    const blue: number[] = new Array(grid.cells.length).fill(0);
    // Each face needs a blue cell it can actually reach: pick from every class in turn.
    const perClass = solid.faces.length / solid.nclasses;
    for (let c = 0; c < solid.nclasses; c++) {
      const pool: number[] = [];
      grid.classes.forEach((cls, i) => cls === c && pool.push(i));
      for (let k = 0; k < perClass; k++) blue[pool.splice(rng.upto(pool.length), 1)[0]] = 1;
    }
    const empty: number[] = [];
    blue.forEach((b, i) => !b && empty.push(i));
    return { desc: `${encodeBlue(blue)},${rng.pick(empty)}` };
  },
  validateDesc(p, desc) {
    const r = parseDesc(p, desc);
    return typeof r === 'string' ? r : null;
  },
  newGame(p, desc) {
    const r = parseDesc(p, desc);
    if (typeof r === 'string') throw new Error(r);
    return {
      solid: p.solid,
      d1: p.d1,
      d2: p.d2,
      blue: r.blue,
      faces: new Array(SOLIDS[p.solid].faces.length).fill(0),
      cell: r.cell,
      prev: -1,
      moves: 0,
      completed: 0,
    };
  },

  canSolve: false,

  newUI: () => ({}),

  interpretMove(state, _ui, ds, mx, my, button) {
    const grid = gridFor(state);
    const c = stripMods(button);
    const keypad = (button & MOD_NUM_KEYPAD) !== 0;
    let dir: Dir | null = null;
    if (c === CURSOR_UP || (keypad && c === 56)) dir = 'U';
    else if (c === CURSOR_DOWN || (keypad && c === 50)) dir = 'D';
    else if (c === CURSOR_LEFT || (keypad && c === 52)) dir = 'L';
    else if (c === CURSOR_RIGHT || (keypad && c === 54)) dir = 'R';
    else if (keypad && c >= 48 && c < 58) dir = diagonal(grid, state.cell, String.fromCharCode(c));
    else if (c === LEFT_BUTTON) {
      // Roll towards the pointer: pick the edge whose direction from the centre of the
      // current cell is angularly nearest to the click.
      const { unit, ox, oy } = layout(state, ds.tileSize);
      const cell = grid.cells[state.cell];
      const dx = mx - (ox + cell.cx * unit);
      const dy = my - (oy + cell.cy * unit);
      if (Math.hypot(dx, dy) < 1) return null;
      const bearing = Math.atan2(dy, dx);
      let best = Infinity;
      for (const d of DIRS) {
        const e = cell.edge[d];
        if (!e) continue;
        const ex = (cell.pts[2 * e[0]] + cell.pts[2 * e[1]]) / 2 - cell.cx;
        const ey = (cell.pts[2 * e[0] + 1] + cell.pts[2 * e[1] + 1]) / 2 - cell.cy;
        let diff = Math.abs(Math.atan2(ey, ex) - bearing);
        if (diff > Math.PI) diff = 2 * Math.PI - diff;
        if (diff < best) {
          best = diff;
          dir = d;
        }
      }
    } else {
      return null;
    }
    if (dir === null || grid.cells[state.cell].nb[dir] < 0) return null;
    return dir;
  },

  executeMove(state, move) {
    if (move.length !== 1 || !DIRS.includes(move as Dir)) return null;
    return roll(state, move as Dir);
  },

  preferredTileSize: 48,
  computeSize: (p, t) => canvasSize(p, t),

  redraw(dr: Drawing, ds: DrawState, oldState, state, dir, _ui, animTime, flashTime) {
    const { grid, solid, unit, ox, oy } = layout(state, ds.tileSize);
    const X = (x: number) => ox + x * unit;
    const Y = (y: number) => oy + y * unit;

    // While a roll is animating, the picture shows the earlier state with the solid
    // tipping from its cell towards the later one; undo simply runs that backwards.
    let shown = state;
    let pose: Pose | null = null;
    if (oldState) {
      const earlier = dir > 0 ? oldState : state;
      const later = dir > 0 ? state : oldState;
      if (later.prev === earlier.cell && directionTo(grid, earlier.cell, later.cell) !== null) {
        const frac = clamp(dir > 0 ? animTime / ANIM : 1 - animTime / ANIM, 0, 1);
        shown = earlier;
        pose = rollPose(solid, grid, earlier.cell, later.cell, solid.rollAngle * frac);
      }
    }
    if (!pose) pose = restPose(solid, grid, shown.cell);

    const flashing = flashOn(flashTime, FLASH_FRAME);
    const blueCell = dr.mix('blue', 'paper', 0.55);
    grid.cells.forEach((cell, i) => {
      const pts = cell.pts.map((v, k) => (k % 2 === 0 ? X(v) : Y(v)));
      const fill = shown.blue[i] ? blueCell : flashing ? 'shade' : 'paper';
      dr.polygon(pts, fill, 'faint', { width: 1.2 });
    });
    if (grid.kind === 'c') {
      dr.rectOutline(X(grid.bbox.l), Y(grid.bbox.u), grid.d1 * unit, grid.d2 * unit, 'ink', {
        width: 2.4,
      });
    } else {
      for (const [x0, y0, x1, y1] of grid.boundary) dr.line(X(x0), Y(y0), X(x1), Y(y1), 'ink', 2.4);
    }

    // The solid: only faces turned towards the viewer, lit from the upper left.
    const dark = dr.mix('shade', 'lowlight', 0.6);
    const darkBlue = dr.mix('blue', 'ink', 0.4);
    solid.faces.forEach((face, i) => {
      const n = pose!.normals[i];
      if (!facesViewer(n, solid.shear)) return;
      const pts: number[] = [];
      for (const vi of face) {
        const [px, py] = project(pose!.vertices[vi], solid.shear);
        pts.push(X(px), Y(py));
      }
      const light = clamp(0.5 + 0.5 * (n[0] * LIGHT[0] + n[1] * LIGHT[1] + n[2] * LIGHT[2]), 0, 1);
      const fill = shown.faces[i] ? dr.mix(darkBlue, 'blue', light) : dr.mix(dark, 'paper', light);
      dr.polygon(pts, fill, flashing ? 'ok' : 'ink', { width: 1.8, seed: i + 1 });
    });

    dr.statusBar(
      shown.completed
        ? tr('status.completedMoves', { n: shown.completed })
        : tr('status.moves', { n: shown.moves }),
    );
  },

  animLength(oldState, newState, dir) {
    const earlier = dir > 0 ? oldState : newState;
    const later = dir > 0 ? newState : oldState;
    if (later.prev !== earlier.cell) return 0;
    return directionTo(gridFor(earlier), earlier.cell, later.cell) === null ? 0 : ANIM;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed ? FLASH : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  flags: { oneButton: true },
});

export default game;
