import type { Tutorial, TutorialCtx } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { FlipState, FlipUI } from './index';

type Ctx = TutorialCtx<FlipState, FlipUI>;

const border = (t: number) => Math.round(t * 0.3);

/** Spotlight one square and point at it. */
function square(x: number, y: number) {
  return {
    highlight: ({ tileSize }: Ctx) => cellRect(x, y, tileSize, border(tileSize)),
    pointer: ({ tileSize }: Ctx) => cellCentre(x, y, tileSize, border(tileSize)),
  };
}

/**
 * `marks[i]` flips every time square `i` is pressed, so an odd mark is a reliable record
 * of "the player pressed exactly this square", even if they wandered off first.
 */
function pressed(state: FlipState, x: number, y: number): boolean {
  return state.marks[y * state.w + x] === 1;
}

export const tutorial: Tutorial<FlipState, FlipUI> = {
  steps: [
    {
      gameId: '3x3:d074191345d1644c17058,888',
      text: 'Light up all nine squares. Pressing one flips it **and** the squares around it, so lit squares can go dark again.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The little diagram inside a square shows what it flips: the solid block is the square itself, the outlines are its neighbours.',
      highlight: ({ tileSize }) => cellRect(1, 1, tileSize, border(tileSize)),
    },
    {
      text: 'Time to light this one up. Press the **top-left** square, the dark one in the corner.',
      ...square(0, 0),
      waitFor: ({ state }) => pressed(state, 0, 0),
    },
    {
      text: 'The corner is lit, but its two neighbours went dark. Press the **centre** square next.',
      ...square(1, 1),
      waitFor: ({ state }) => pressed(state, 1, 1),
    },
    {
      text: 'Only the bottom-right corner is dark now. Press the **bottom-right** square to finish it.',
      ...square(2, 2),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'All lit! **Undo** takes back a press, and you can steer a cursor with the arrow keys and press Enter instead of clicking.',
      textTouch:
        'All lit! **Undo** takes back a press, and pressing the same square twice always cancels out, so the order never matters.',
      target: '[data-cmd="undo"]',
    },
  ],
};
