/**
 * Bridges puzzle generation.
 *
 * A map is grown rather than solved into existence: starting from one island, an
 * existing island is picked at random and a bridge (of random thickness) is thrown out
 * in a random direction to a brand-new island — or, when loops are allowed, sometimes
 * to an island already standing in that line. The new island lands somewhere between two
 * squares away and the furthest free square; the *expansion* parameter is the chance of
 * choosing the furthest spot. Bridges never cross because a line already in the way
 * stops the search short. Growing stops when enough of the grid is islands or when new
 * islands stop fitting; maps that do not reach all four sides are thrown away.
 *
 * Each island's number is then simply the bridges touching it, and the solver decides the
 * map's fate: it must be solvable by deduction at the requested difficulty and — for
 * Medium and Hard — not at the one below.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { DX, DY, Layout, encodeBridges, encodeDesc } from './board';
import type { IslandSpec } from './board';
import { DIFF_HARD, solveLayout } from './solver';

export interface GenParams {
  w: number;
  h: number;
  /** Most parallel bridges between two islands. */
  maxb: number;
  /** Rough percentage of squares that should become islands. */
  islands: number;
  /** Percentage chance of stretching a new bridge as far as it will go. */
  expansion: number;
  allowLoops: boolean;
  difficulty: number;
}

/** Failed attempts to place a new island before a map is declared finished. */
const MAX_NEW_ISLAND_TRIES = 50;
/** Maps this small are not graded for being too easy. */
const MIN_SENSIBLE_ISLANDS = 3;
/** Whole maps tried before giving up on a set of parameters. */
const MAX_MAPS = 20000;
/**
 * Once a fallback map is in hand, the squares grown across all attempts (maps × grid area)
 * before settling for it. Growing a 25×25 map is slow and big maps with many bridges per
 * pair rarely hit the requested difficulty, so without this a custom deal could search all
 * MAX_MAPS for ten seconds or more. Presets stay far below it (at most ~15 000).
 */
const FALLBACK_WORK = 1_000_000;

/** Mutable map under construction: island squares plus bridge counts per square. */
class GrowingMap {
  readonly islandAt: Int32Array;
  /** Horizontal / vertical bridges passing through each square. */
  readonly lineH: Uint8Array;
  readonly lineV: Uint8Array;
  readonly islands: { x: number; y: number }[] = [];

  constructor(
    readonly w: number,
    readonly h: number,
  ) {
    this.islandAt = new Int32Array(w * h).fill(-1);
    this.lineH = new Uint8Array(w * h);
    this.lineV = new Uint8Array(w * h);
  }

  inGrid(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.w && y < this.h;
  }

  hasIsland(x: number, y: number): boolean {
    return this.inGrid(x, y) && this.islandAt[y * this.w + x] >= 0;
  }

  hasLine(x: number, y: number): boolean {
    const k = y * this.w + x;
    return this.lineH[k] > 0 || this.lineV[k] > 0;
  }

  addIsland(x: number, y: number): number {
    this.islandAt[y * this.w + x] = this.islands.length;
    this.islands.push({ x, y });
    return this.islands.length - 1;
  }

  /** Lay `n` bridges along the straight line between two islands. */
  join(i: number, j: number, n: number): void {
    const a = this.islands[i];
    const b = this.islands[j];
    const dx = Math.sign(b.x - a.x);
    const dy = Math.sign(b.y - a.y);
    const lines = dx ? this.lineH : this.lineV;
    for (let x = a.x + dx, y = a.y + dy; x !== b.x || y !== b.y; x += dx, y += dy)
      lines[y * this.w + x] = n;
  }
}

/**
 * Try to throw a bridge out of island `i` in direction `dir`, to a new island or (when
 * loops are allowed) to one already in line. Returns false when nothing fits there.
 */
function extend(map: GrowingMap, p: GenParams, rng: Random, i: number, dir: number): boolean {
  const is = map.islands[i];
  const dx = DX[dir];
  const dy = DY[dir];
  let x = is.x + dx;
  let y = is.y + dy;
  // A bridge already leaves this island in that direction.
  if (map.hasLine(x, y)) return false;
  // Walk until something is in the way; the new island can sit anywhere from two
  // squares away up to the last free square (leaving a gap before another island).
  let join = -1;
  let far: number;
  for (;;) {
    if (!map.inGrid(x, y)) {
      far = dx ? x - dx : y - dy;
      break;
    }
    if (map.hasIsland(x, y)) {
      join = map.islandAt[y * map.w + x];
      far = dx ? x - 2 * dx : y - 2 * dy;
      break;
    }
    if (map.hasLine(x, y)) {
      far = dx ? x - dx : y - dy;
      break;
    }
    x += dx;
    y += dy;
  }
  if (p.allowLoops && join >= 0 && rng.upto(100) < p.expansion) {
    map.join(i, join, rng.upto(p.maxb) + 1);
    return true;
  }
  const near = dx ? is.x + 2 * dx : is.y + 2 * dy;
  const span = (far - near) * (dx || dy);
  if (span < 0) return false;
  const pos = rng.upto(100) < p.expansion ? far : near + rng.upto(span + 1) * (dx || dy);
  const nx = dx ? pos : is.x;
  const ny = dx ? is.y : pos;
  // Never put an island right beside another one.
  if (map.hasIsland(nx + dy, ny + dx) || map.hasIsland(nx - dy, ny - dx)) return false;
  const j = map.addIsland(nx, ny);
  map.join(i, j, rng.upto(p.maxb) + 1);
  return true;
}

/**
 * Grow one map. Returns null when it came out degenerate (a single island, or not
 * touching every side of the grid).
 */
export function growMap(p: GenParams, rng: Random): GrowingMap | null {
  const { w, h } = p;
  const map = new GrowingMap(w, h);
  const wanted = Math.max(Math.floor((p.islands * w * h) / 100), MIN_SENSIBLE_ISLANDS);
  map.addIsland(rng.upto(w), rng.upto(h));
  let bad = 0;

  while (map.islands.length < wanted) {
    const i = rng.upto(map.islands.length);
    const is = map.islands[i];
    // Directions that stay inside the grid, in the fixed order left, right, up, down.
    const dirs: number[] = [];
    for (let d = 0; d < 4; d++) if (map.inGrid(is.x + DX[d], is.y + DY[d])) dirs.push(d);
    if (extend(map, p, rng, i, dirs[rng.upto(dirs.length)])) {
      bad = 0;
    } else if (++bad > MAX_NEW_ISLAND_TRIES) {
      break;
    }
  }

  if (map.islands.length < 2) return null;
  let sides = 0;
  for (const is of map.islands) {
    if (is.x === 0) sides |= 1;
    if (is.x === w - 1) sides |= 2;
    if (is.y === 0) sides |= 4;
    if (is.y === h - 1) sides |= 8;
  }
  return sides === 15 ? map : null;
}

/** Turn a grown map into a layout (islands numbered by their bridges) plus its solution. */
export function layoutOfMap(map: GrowingMap, p: GenParams): { L: Layout; solution: Uint8Array } {
  const { w } = map;
  const specs: IslandSpec[] = map.islands
    .map((is) => ({ x: is.x, y: is.y, clue: 0 }))
    .sort((a, b) => a.y - b.y || a.x - b.x);
  for (const is of specs) {
    for (let d = 0; d < 4; d++) {
      const x = is.x + DX[d];
      const y = is.y + DY[d];
      if (!map.inGrid(x, y)) continue;
      is.clue += DX[d] ? map.lineH[y * w + x] : map.lineV[y * w + x];
    }
  }
  const L = new Layout(w, map.h, specs, p.maxb, p.allowLoops);
  const solution = new Uint8Array(L.edges.length);
  L.edges.forEach((edge, e) => {
    solution[e] = edge.horizontal ? map.lineH[edge.cells[0]] : map.lineV[edge.cells[0]];
  });
  return { L, solution };
}

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(p: GenParams, rng: Random): { desc: string; aux: string } {
  // The first map that was merely too easy. Some settings (a small grid with one bridge
  // per pair and no loops, say) rarely or never grow a map that needs the full
  // difficulty; rather than refuse to deal at all, those get an easier puzzle — still one
  // the solver proves has a single solution.
  let easier: { desc: string; aux: string } | null = null;
  // Likewise the first map that was too hard: a big grid with up to four bridges per pair
  // seldom or never grows one that Easy's deductions can finish. Such settings get a
  // harder puzzle instead of none, still one the Hard solver proves unique.
  let harder: { desc: string; aux: string } | null = null;
  for (let attempt = 0; attempt < MAX_MAPS; attempt++) {
    if ((easier || harder) && attempt * p.w * p.h > FALLBACK_WORK) break;
    const map = growMap(p, rng);
    if (!map) continue;
    const { L, solution } = layoutOfMap(map, p);
    const deal = () => ({ desc: encodeDesc(L.w, L.h, L.islands), aux: encodeBridges(solution) });
    if (
      p.difficulty > 0 &&
      L.islands.length > MIN_SENSIBLE_ISLANDS &&
      solveLayout(L, p.difficulty - 1).solved
    ) {
      easier ??= deal();
      continue; // too easy
    }
    if (!solveLayout(L, p.difficulty).solved) {
      if (!harder && p.difficulty < DIFF_HARD && solveLayout(L, DIFF_HARD).solved) harder = deal();
      continue; // too hard
    }
    return deal();
  }
  if (easier) return easier;
  if (harder) return harder;
  throw new Error(tx`Unable to generate a puzzle with these parameters`);
}
