/**
 * Magnets puzzle generation.
 *
 * A random domino tiling of the grid is filled with magnets and blanks: a few dominoes
 * are made neutral up front, the rest are laid as magnets wherever the poles already
 * placed allow (falling back to neutral), with the solver's domino bookkeeping run after
 * every placement so that forced consequences are honoured. The clue counts are read off
 * the finished grid. The puzzle is kept only if the solver of the requested difficulty
 * finds the grid and — for Tricky — the Easy solver does not. With "strip clues" on, the
 * clues are then removed one at a time in random order, each staying out only while the
 * puzzle remains solvable at that difficulty.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import type { NewDesc } from '../../framework/types';
import { Layout, NEGATIVE, NEUTRAL, POSITIVE, countTargets, encodeAux, encodeDesc } from './board';
import { DIFF_COUNT, DIFF_EASY, Work, solve, solveUnnumbered } from './solver';

export interface MagnetsParams {
  w: number;
  h: number;
  /** DIFF_EASY or DIFF_TRICKY. */
  diff: number;
  /** Remove clues that are not needed. */
  strip: boolean;
}

/**
 * Tile a w×h rectangle with dominoes at random, returning `partner[i]`: the other cell
 * of the domino on `i`, or `i` itself for the single square left over when w×h is odd.
 *
 * Dominoes are first dropped wherever they fit, in a random order, which strands some
 * single squares. Each stranded square is then joined to another by a breadth-first
 * search that hops through whole dominoes; every domino along the path found is slid one
 * step towards the start, which frees a square next to the far singleton and covers the
 * near one. The path always has even length, so its two ends are on opposite colours of
 * the chessboard and pairing them is always possible.
 */
export function dominoLayout(w: number, h: number, rng: Random): Int32Array {
  const n = w * h;
  const partner = new Int32Array(n);
  for (let i = 0; i < n; i++) partner[i] = i;

  const spots: number[] = [];
  for (let y = 0; y + 1 < h; y++) for (let x = 0; x < w; x++) spots.push(2 * (y * w + x));
  for (let y = 0; y < h; y++) for (let x = 0; x + 1 < w; x++) spots.push(2 * (y * w + x) + 1);
  rng.shuffle(spots);
  for (const s of spots) {
    const a = s >> 1;
    const b = s & 1 ? a + 1 : a + w;
    if (partner[a] === a && partner[b] === b) {
      partner[a] = b;
      partner[b] = a;
    }
  }

  // `from[k]` is the cell the search stepped from to reach k; `dist[m]` the number of
  // dominoes crossed to reach the far end m of a domino.
  const from = new Int32Array(n);
  const dist = new Int32Array(n);
  const queue = new Int32Array(n);
  for (;;) {
    let start = -1;
    let singles = 0;
    for (let i = 0; i < n; i++) {
      if (partner[i] === i) {
        singles++;
        start = i;
      }
    }
    if (singles === n % 2) return partner;

    from.fill(-1);
    dist.fill(-1);
    dist[start] = 0;
    queue[0] = start;
    let head = 0;
    let tail = 1;
    let found = -1;
    while (head < tail && found < 0) {
      const cur = queue[head++];
      const x = cur % w;
      const y = Math.floor(cur / w);
      const nbrs: number[] = [];
      if (x > 0) nbrs.push(cur - 1);
      if (x + 1 < w) nbrs.push(cur + 1);
      if (y > 0) nbrs.push(cur - w);
      if (y + 1 < h) nbrs.push(cur + w);
      rng.shuffle(nbrs);
      for (const k of nbrs) {
        if (partner[k] === k) {
          from[k] = cur;
          found = k;
          break;
        }
        const m = partner[k];
        if (dist[m] < 0 || dist[m] > dist[cur] + 1) {
          dist[m] = dist[cur] + 1;
          from[k] = cur;
          queue[tail++] = m;
        }
      }
    }
    if (found < 0) throw new Error(tx`domino layout: stranded square cannot be paired`);

    // Walk back along the path, re-laying each domino one step towards the start.
    let i = found;
    for (;;) {
      const j = from[i];
      const k = partner[j];
      partner[i] = j;
      partner[j] = i;
      if (k === j) break;
      i = k;
    }
  }
}

/**
 * Fill a tiling with magnets and blanks. Returns the polarity of every cell, or null
 * when the random choices painted themselves into a corner.
 */
export function layPolarities(L: Layout, rng: Random): Uint8Array | null {
  const work = new Work(L);
  const order: number[] = [];
  for (let i = 0; i < L.n; i++) order.push(i);
  rng.shuffle(order);
  // A handful of dominoes start out neutral; too many makes big grids insoluble.
  const initialNeutral = L.n > 100 ? 5 : Math.floor(L.n / 10);

  for (let k = 0; k < L.n; k++) {
    const i = order[k];
    if (work.isSet(i)) continue;
    let r: number;
    if (k < initialNeutral) r = work.set(i, NEUTRAL);
    else if (work.possible(i, POSITIVE)) r = work.set(i, POSITIVE);
    else if (work.possible(i, NEGATIVE)) r = work.set(i, NEGATIVE);
    else r = work.set(i, NEUTRAL);
    if (r <= 0) return null;
    const s = solveUnnumbered(work);
    if (s < 0) return null;
    if (s > 0) break;
  }
  for (let i = 0; i < L.n; i++) if (!work.isSet(i)) return null;
  return work.grid;
}

/** Is `grid` exactly what a fresh solve of `L` at `diff` deduces? */
function solvesTo(L: Layout, diff: number, grid: Uint8Array): boolean {
  const work = new Work(L);
  if (solve(work, diff) <= 0) return false;
  for (let i = 0; i < L.n; i++) if (work.grid[i] !== grid[i]) return false;
  return true;
}

/** The easiest difficulty whose solver finds `grid`, or -1 if none does. */
function levelOf(L: Layout, grid: Uint8Array): number {
  for (let diff = DIFF_EASY; diff < DIFF_COUNT; diff++) if (solvesTo(L, diff, grid)) return diff;
  return -1;
}

/**
 * Remove clues in random order, keeping each one out only while the puzzle can still be
 * solved at `diff`.
 */
function stripClues(L: Layout, grid: Uint8Array, diff: number, rng: Random): void {
  const clues: number[] = [];
  for (let c = 0; c < 2 * L.lines; c++) clues.push(c);
  rng.shuffle(clues);
  for (const c of clues) {
    const which = c < L.lines ? POSITIVE : NEGATIVE;
    const l = c % L.lines;
    const saved = L.targets[3 * l + which];
    L.targets[3 * l + which] = -1;
    L.fixNeutral(l);
    if (!solvesTo(L, diff, grid)) {
      L.targets[3 * l + which] = saved;
      L.fixNeutral(l);
    }
  }
}

/**
 * Random grids that need exactly the requested reasoning are rare on small boards
 * (Tricky below about 5×5) and on the largest ones, so after this many attempts the
 * generator settles for the first grid it saw that was solvable at an easier level.
 */
const MAX_ATTEMPTS = 4000;
/** Re-lays of the polarities on one tiling before a fresh tiling is tried. */
const MAX_LAYS = 50;

/** Generate a puzzle description; the aux string is its solution grid. */
export function generate(p: MagnetsParams, rng: Random): NewDesc {
  const { w, h } = p;
  let fallback: { L: Layout; grid: Uint8Array; level: number } | null = null;
  const finish = (L: Layout, grid: Uint8Array, level: number): NewDesc => {
    if (p.strip) stripClues(L, grid, level, rng);
    return { desc: encodeDesc(L), aux: encodeAux(grid) };
  };
  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
    const partner = dominoLayout(w, h, rng);
    const bare = new Layout(w, h, partner, new Int32Array(3 * (w + h)).fill(-1));
    let grid: Uint8Array | null = null;
    for (let k = 0; k < MAX_LAYS && !grid; k++) grid = layPolarities(bare, rng);
    if (!grid) continue;
    const L = new Layout(w, h, partner, countTargets(w, h, grid));
    const level = levelOf(L, grid);
    if (level === p.diff) return finish(L, grid, level);
    if (level >= 0 && level < p.diff && !fallback) fallback = { L, grid, level };
  }
  if (fallback) return finish(fallback.L, fallback.grid, fallback.level);
  throw new Error(tx`Unable to generate a puzzle of this size`);
}
