/**
 * Waiting for the hand-drawn face before painting with it on a canvas.
 *
 * CSS text re-lays itself out the moment a web font arrives; a canvas does not. Whatever
 * was drawn with the fallback face stays drawn with it — and the menu keeps every preview
 * it paints for the rest of the visit (see `thumbnail.ts`), so on a slow connection the
 * Fifteen card, the clues on Solo, every digit on every preview came out in Bradley Hand
 * or Comic Sans for good. `document.fonts.ready` is not the answer on its own: it only
 * waits for loads already under way, and before the first layout nothing has asked for
 * Patrick Hand yet, so it resolves at once. `load()` asks for it, and waits.
 */

/** How long a canvas may be held back for the font before it is painted without it. */
export const HAND_FONT_WAIT_MS = 3000;

const PROBE = '20px "Patrick Hand"';

let waiting: Promise<void> | null = null;

/**
 * Resolves once Patrick Hand is usable on a canvas, or after {@link HAND_FONT_WAIT_MS},
 * or at once where there is no font loading API at all. Never rejects.
 */
export function handFontReady(): Promise<void> {
  waiting ??= new Promise<void>((resolve) => {
    const timer = setTimeout(resolve, HAND_FONT_WAIT_MS);
    const done = () => {
      clearTimeout(timer);
      resolve();
    };
    try {
      const fonts = typeof document !== 'undefined' ? document.fonts : undefined;
      if (!fonts || typeof fonts.load !== 'function') return done();
      fonts.load(PROBE).then(done, done);
    } catch {
      done();
    }
  });
  return waiting;
}

/** Whether Patrick Hand has arrived. `true` where that cannot be asked. */
export function handFontLoaded(): boolean {
  try {
    const fonts = typeof document !== 'undefined' ? document.fonts : undefined;
    return !fonts || typeof fonts.check !== 'function' || fonts.check(PROBE);
  } catch {
    return true;
  }
}
