/**
 * Loopy board model shared by the game, the solver and the generator: line states,
 * the description format and the completion check.
 *
 * A puzzle is a grid (see `grid.ts`) with a clue on some faces. The player marks edges
 * as part of the loop (`LINE_YES`) or definitely not (`LINE_NO`); untouched edges are
 * `LINE_UNKNOWN`. The description lists the faces in order: a digit (or `A`–`Z` for
 * 10–35) is a clue, a lower-case letter a run of that many blank faces (`a` = 1 …
 * `z` = 26). An optional grid description precedes it, separated by `_`.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';
import type { Grid } from './grid';

export const LINE_UNKNOWN = 0;
export const LINE_YES = 1;
export const LINE_NO = 2;
export const NO_CLUE = -1;

/** The other definite state: YES ↔ NO. */
export function opposite(s: number): number {
  return s === LINE_YES ? LINE_NO : s === LINE_NO ? LINE_YES : LINE_UNKNOWN;
}

// ------------------------------------------------------------- description format

/** Split a description into its optional grid part and the clue part. */
export function splitDesc(desc: string): { gridDesc: string | null; clueDesc: string } {
  const i = desc.indexOf('_');
  if (i < 0) return { gridDesc: null, clueDesc: desc };
  return { gridDesc: desc.slice(0, i), clueDesc: desc.slice(i + 1) };
}

/** Parse the clue part of a description for a grid with `nf` faces. */
export function parseClues(clueDesc: string, nf: number): Int8Array | string {
  const clues = new Int8Array(nf).fill(NO_CLUE);
  let i = 0;
  for (const ch of clueDesc) {
    if (ch >= 'a' && ch <= 'z') {
      i += ch.charCodeAt(0) - 96;
    } else if (ch >= '0' && ch <= '9') {
      if (i < nf) clues[i] = ch.charCodeAt(0) - 48;
      i++;
    } else if (ch >= 'A' && ch <= 'Z') {
      if (i < nf) clues[i] = ch.charCodeAt(0) - 55;
      i++;
    } else {
      return tx`Unknown character in description`;
    }
  }
  if (i < nf) return tx`Description too short for board size`;
  if (i > nf) return tx`Description too long for board size`;
  return clues;
}

/** Encode clues in the description format. */
export function encodeClues(clues: Int8Array): string {
  let out = '';
  let run = 0;
  const flush = () => {
    if (run > 0) out += String.fromCharCode(96 + run);
    run = 0;
  };
  for (let i = 0; i < clues.length; i++) {
    const c = clues[i];
    if (c < 0) {
      if (run === 26) flush();
      run++;
    } else {
      flush();
      out += c < 10 ? String(c) : String.fromCharCode(55 + c);
    }
  }
  flush();
  return out;
}

/** Solver hint stored with a generated puzzle: the loop's edges as a hex bitmask. */
export function encodeLines(lines: Uint8Array): string {
  let out = '';
  for (let i = 0; i < lines.length; i += 4) {
    let v = 0;
    for (let k = 0; k < 4; k++) if (lines[i + k] === LINE_YES) v |= 1 << k;
    out += v.toString(16);
  }
  return out;
}

export function decodeLines(aux: string, ne: number): Uint8Array | null {
  if (aux.length !== Math.ceil(ne / 4) || !/^[0-9a-f]*$/.test(aux)) return null;
  const lines = new Uint8Array(ne).fill(LINE_NO);
  for (let i = 0; i < aux.length; i++) {
    const v = parseInt(aux[i], 16);
    for (let k = 0; k < 4; k++) {
      const e = 4 * i + k;
      if (e >= ne) {
        if (v & (1 << k)) return null;
      } else if (v & (1 << k)) {
        lines[e] = LINE_YES;
      }
    }
  }
  return lines;
}

// ------------------------------------------------------------- counting helpers

export function faceCount(g: Grid, lines: Uint8Array, f: number, v: number): number {
  let n = 0;
  for (const e of g.faceEdges[f]) if (lines[e] === v) n++;
  return n;
}

export function dotCount(g: Grid, lines: Uint8Array, d: number, v: number): number {
  let n = 0;
  for (const e of g.dotEdges[d]) if (lines[e] === v) n++;
  return n;
}

// ------------------------------------------------------------- completion check

export interface Completion {
  /** 1 for every drawn edge that is wrong: part of a bad loop or of an overfull dot. */
  lineErr: Uint8Array;
  /** When solved, 1 for every face inside the loop. */
  inside: Uint8Array | null;
  solved: boolean;
}

/**
 * Find errors and decide whether the grid is solved.
 *
 * Faces separated only by non-loop edges are merged (with the outside as one extra
 * face). A drawn edge between two faces of the same class is not part of any closed
 * loop; one between different classes is. If there is exactly one loop, every drawn
 * edge lies on it and every clue is satisfied, the puzzle is solved. Otherwise every
 * loop edge is an error (a loop that is not the answer is always wrong), as is every
 * drawn edge at a dot with three or more lines or with a dead end.
 */
export function checkCompletion(g: Grid, clues: Int8Array, lines: Uint8Array): Completion {
  const INF = g.nf;
  const dsf = new DSF(g.nf + 1);
  const faceOf = (f: number) => (f < 0 ? INF : f);
  for (let e = 0; e < g.ne; e++) {
    if (lines[e] !== LINE_YES) dsf.merge(faceOf(g.edgeFace1[e]), faceOf(g.edgeFace2[e]));
  }
  const lineErr = new Uint8Array(g.ne);
  const infArea = dsf.find(INF);
  let finiteArea = -1;
  let loopsFound = 0;
  let strayEdge = false;
  for (let e = 0; e < g.ne; e++) {
    if (lines[e] !== LINE_YES) continue;
    const c1 = dsf.find(faceOf(g.edgeFace1[e]));
    const c2 = dsf.find(faceOf(g.edgeFace2[e]));
    if (c1 === c2) {
      strayEdge = true;
      continue;
    }
    lineErr[e] = 1;
    if (loopsFound === 0) loopsFound = 1;
    if (loopsFound === 2) continue;
    if (finiteArea === -1) finiteArea = c1 !== infArea ? c1 : c2;
    if ((c1 !== infArea && c1 !== finiteArea) || (c2 !== infArea && c2 !== finiteArea)) {
      loopsFound = 2;
    }
  }

  if (loopsFound === 1 && !strayEdge) {
    let ok = true;
    for (let f = 0; f < g.nf && ok; f++) {
      if (clues[f] >= 0 && faceCount(g, lines, f, LINE_YES) !== clues[f]) ok = false;
    }
    if (ok) {
      const inside = new Uint8Array(g.nf);
      for (let f = 0; f < g.nf; f++) if (dsf.find(f) !== infArea) inside[f] = 1;
      return { lineErr: new Uint8Array(g.ne), inside, solved: true };
    }
  }

  for (let d = 0; d < g.nd; d++) {
    const yes = dotCount(g, lines, d, LINE_YES);
    const unknown = dotCount(g, lines, d, LINE_UNKNOWN);
    if ((yes === 1 && unknown === 0) || yes >= 3) {
      for (const e of g.dotEdges[d]) if (lines[e] === LINE_YES) lineErr[e] = 1;
    }
  }
  return { lineErr, inside: null, solved: false };
}
