/**
 * Galaxies solver.
 *
 * Works on a tile → dot assignment plus the set edges. Every deduction is made in mirror
 * pairs so the region of each dot stays symmetric by construction:
 *
 *  - tiles touching a dot belong to it (`solverObvious`);
 *  - an edge between tiles of different dots is set, and a set edge next to an assigned
 *    tile is mirrored through its dot (`linesOpposite`);
 *  - a tile whose open sides all lead to one dot's tiles belongs to that dot
 *    (`spacesOneposs`);
 *  - a tile that only one dot can reach, through symmetric pairs of free tiles, belongs
 *    to that dot; a tile no dot can reach is a contradiction (`expandDots`).
 *
 * Those make up the Normal level. Unreasonable adds guessing: pick a free tile, try every
 * dot it could belong to and count the solutions.
 */
import {
  DIFF_NORMAL,
  DIFF_UNREASONABLE,
  checkComplete,
  edgeTiles,
  initialEdges,
  opposite,
  touchingTiles,
} from './board';
import type { Layout } from './board';

export const DIFF_IMPOSSIBLE = 2;
export const DIFF_AMBIGUOUS = 3;
export const DIFF_UNFINISHED = 4;

/** Nested guesses allowed before the solver gives up with `DIFF_UNFINISHED`. */
const MAX_RECURSE = 5;

/** Offsets of the four edges around a tile: up, right, down, left. */
function steps(sx: number): number[] {
  return [-sx, 1, sx, -1];
}

/** Mutable solving state. */
export class Work {
  readonly L: Layout;
  edges: Uint8Array;
  /** Dot (grid index) each tile belongs to, or -1. */
  assoc: Int32Array;

  constructor(L: Layout, edges?: Uint8Array, assoc?: Int32Array) {
    this.L = L;
    this.edges = edges ? edges.slice() : initialEdges(L);
    this.assoc = assoc ? assoc.slice() : new Int32Array(L.n).fill(-1);
  }

  clone(): Work {
    return new Work(this.L, this.edges, this.assoc);
  }
}

/**
 * Assign `tile` and its mirror image to dot `d`. Returns 1 when something changed, 0 when
 * it already was, -1 when that is impossible.
 */
export function addAssoc(work: Work, tile: number, d: number): number {
  const cur = work.assoc[tile];
  if (cur >= 0) return cur === d ? 0 : -1;
  const opp = opposite(work.L, tile, d);
  if (opp < 0) return -1;
  const other = work.assoc[opp];
  if (other >= 0 && other !== d) return -1;
  work.assoc[tile] = d;
  work.assoc[opp] = d;
  return 1;
}

/** Tiles touching a dot belong to it. */
export function solverObvious(work: Work): number {
  let did = 0;
  for (const d of work.L.dots) {
    for (const t of touchingTiles(work.L, d)) {
      const r = addAssoc(work, t, d);
      if (r < 0) return -1;
      if (r > 0) did = 1;
    }
  }
  return did;
}

/** Whether the dots of a layout overlap each other's tiles, which no description may do. */
export function dotsTooClose(L: Layout): boolean {
  return solverObvious(new Work(L)) < 0;
}

function linesOpposite(work: Work): number {
  const { L, edges, assoc } = work;
  let did = 0;
  for (const e of L.edgeList) {
    const [t1, t2] = edgeTiles(L, e);
    const a1 = assoc[t1];
    const a2 = assoc[t2];
    if (!edges[e] && a1 >= 0 && a2 >= 0 && a1 !== a2) {
      edges[e] = 1;
      did = 1;
    }
    if (!edges[e]) continue;
    for (const t of [t1, t2]) {
      const a = assoc[t];
      if (a < 0) continue;
      if (opposite(L, t, a) < 0) return -1;
      const eo = opposite(L, e, a);
      if (eo >= 0 && !edges[eo]) {
        edges[eo] = 1;
        did = 1;
      }
    }
  }
  return did;
}

function spacesOneposs(work: Work): number {
  const { L, edges, assoc } = work;
  const st = steps(L.sx);
  let did = 0;
  for (const t of L.tiles) {
    if (assoc[t] >= 0) continue;
    let eset = 0;
    let d = -1;
    let ok = true;
    for (const s of st) {
      if (edges[t + s]) {
        eset++;
        continue;
      }
      const a = assoc[t + 2 * s];
      if (a < 0 || (d >= 0 && a !== d)) {
        ok = false;
        break;
      }
      d = a;
    }
    if (!ok) continue;
    if (eset === 4) return -1;
    if (addAssoc(work, t, d) < 0) return -1;
    did = 1;
  }
  return did;
}

/**
 * From each dot, flood outwards through tiles that are free (or already its own), always
 * in mirror pairs and never across a set edge. A free tile reached by exactly one dot
 * must belong to it; one reached by none makes the position impossible.
 */
function expandDots(work: Work, list: Int32Array, mark: Uint8Array, reach: Int32Array): number {
  const { L, edges, assoc } = work;
  const st = steps(L.sx);
  reach.fill(-1);
  for (const d of L.dots) {
    mark.fill(0);
    const seeds = touchingTiles(L, d);
    // Two tiles that are certainly the dot's, opposite each other (or the same tile twice).
    let s0: number;
    let s1: number;
    if (seeds.length === 1) s0 = s1 = seeds[0];
    else if (seeds.length === 2) [s0, s1] = seeds;
    else {
      s0 = seeds[0];
      s1 = seeds[3];
    }
    list[0] = s0;
    list[1] = s1;
    mark[s0] = mark[s1] = 1;
    let start = 0;
    let end = 2;
    let next = 2;
    for (;;) {
      for (let i = start; i < end; i += 2) {
        const t1 = list[i];
        for (const s of st) {
          if (edges[t1 + s]) continue;
          const nt = t1 + 2 * s;
          if (mark[nt]) continue;
          const nt2 = opposite(L, nt, d);
          if (nt2 < 0) {
            mark[nt] = 1;
            continue;
          }
          const a1 = assoc[nt];
          const a2 = assoc[nt2];
          if ((a1 < 0 || a1 === d) && (a2 < 0 || a2 === d)) {
            list[next++] = nt;
            list[next++] = nt2;
          }
          mark[nt] = mark[nt2] = 1;
        }
      }
      if (next === end) break;
      start = end;
      end = next;
    }
    for (let i = 0; i < end; i++) {
      const t = list[i];
      if (assoc[t] >= 0) continue;
      if (reach[t] === -1) reach[t] = d;
      else if (reach[t] !== d) reach[t] = -2;
    }
  }
  let did = 0;
  for (const t of L.tiles) {
    if (assoc[t] >= 0) continue;
    if (reach[t] === -1) return -1;
    if (reach[t] < 0) continue;
    if (addAssoc(work, t, reach[t]) < 0) return -1;
    did = 1;
  }
  return did;
}

/** Dots that `tile` could still belong to: its mirror must exist and not be someone else's. */
function candidates(work: Work, tile: number): number[] {
  const out: number[] = [];
  for (const d of work.L.dots) {
    const o = opposite(work.L, tile, d);
    if (o < 0) continue;
    const a = work.assoc[o];
    if (a >= 0 && a !== d) continue;
    out.push(d);
  }
  return out;
}

/**
 * Solve as far as `maxdiff` allows. Returns the difficulty needed (DIFF_NORMAL or
 * DIFF_UNREASONABLE) when a unique solution was found, or one of DIFF_IMPOSSIBLE,
 * DIFF_AMBIGUOUS, DIFF_UNFINISHED. On success `work` holds the solution.
 */
export function solverState(work: Work, maxdiff: number, depth = 0): number {
  const L = work.L;
  if (solverObvious(work) < 0) return DIFF_IMPOSSIBLE;
  const list = new Int32Array(L.n * 2);
  const mark = new Uint8Array(L.n);
  const reach = new Int32Array(L.n);
  for (;;) {
    let ret = linesOpposite(work);
    if (ret < 0) return DIFF_IMPOSSIBLE;
    if (ret > 0) continue;
    ret = spacesOneposs(work);
    if (ret < 0) return DIFF_IMPOSSIBLE;
    if (ret > 0) continue;
    ret = expandDots(work, list, mark, reach);
    if (ret < 0) return DIFF_IMPOSSIBLE;
    if (ret > 0) continue;
    break;
  }
  if (checkComplete(L, work.edges).complete) return DIFF_NORMAL;
  if (maxdiff < DIFF_UNREASONABLE) return DIFF_UNFINISHED;
  return recurse(work, maxdiff, depth);
}

function recurse(work: Work, maxdiff: number, depth: number): number {
  if (depth >= MAX_RECURSE) return DIFF_UNFINISHED;
  // Guess on the free tile with the fewest possible dots.
  let best = -1;
  let bestCands: number[] = [];
  for (const t of work.L.tiles) {
    if (work.assoc[t] >= 0) continue;
    const c = candidates(work, t);
    if (c.length === 0) return DIFF_IMPOSSIBLE;
    if (best < 0 || c.length < bestCands.length) {
      best = t;
      bestCands = c;
    }
  }
  // Everything is assigned yet the regions are not right: a dead end.
  if (best < 0) return DIFF_IMPOSSIBLE;
  let diff = DIFF_IMPOSSIBLE;
  let solution: Work | null = null;
  for (const d of bestCands) {
    const trial = work.clone();
    if (addAssoc(trial, best, d) < 0) continue;
    const r = solverState(trial, maxdiff, depth + 1);
    if (r === DIFF_IMPOSSIBLE) continue;
    if (r === DIFF_AMBIGUOUS || r === DIFF_UNFINISHED) {
      diff = r;
      break;
    }
    if (solution) {
      diff = DIFF_AMBIGUOUS;
      break;
    }
    solution = trial;
    diff = DIFF_UNREASONABLE;
  }
  if (solution && diff === DIFF_UNREASONABLE) {
    work.edges.set(solution.edges);
    work.assoc.set(solution.assoc);
  }
  return diff;
}

/**
 * Edges of a solution, preferring one consistent with the player's current position and
 * falling back to a clean start. Null when the puzzle cannot be solved.
 */
export function solveEdges(L: Layout, edges: Uint8Array, assoc: Int32Array): Uint8Array | null {
  const fromCurrent = new Work(L, edges, assoc);
  let r = solverState(fromCurrent, DIFF_UNREASONABLE);
  if (r === DIFF_NORMAL || r === DIFF_UNREASONABLE) return fromCurrent.edges;
  const fresh = new Work(L);
  r = solverState(fresh, DIFF_UNREASONABLE);
  if (r === DIFF_NORMAL || r === DIFF_UNREASONABLE) return fresh.edges;
  return null;
}
