/**
 * A game controller, through the Gamepad API.
 *
 * Nothing here has a code path of its own: every button becomes the key it stands for,
 * dispatched where a real key press would have gone, so the pad drives exactly what the
 * keyboard drives — the menus through `src/ui/nav.ts`, the board through its keyboard
 * cursor, the pause menu through Esc. The one exception is A on a control, which presses
 * it (`click()`), because a synthesised Enter does not activate a button the way a real
 * one does. The other is a trigger in a puzzle played by typing (Solo, Keen, Unequal…):
 * a pad has no digits, so it takes the selector to the on-screen keypad
 * ({@link PAD_KEYPAD_EVENT}); A types the key and hands the board back, B goes back unused.
 *
 * | Pad                  | Menus and dialogs           | On the board                  |
 * | -------------------- | --------------------------- | ----------------------------- |
 * | D-pad / left stick   | move the selector           | move the cursor               |
 * | A                    | press                       | Enter (the main action)       |
 * | B                    | back (Esc)                  | pause (Esc)                   |
 * | X                    | —                           | Space (the second action)     |
 * | Y                    | —                           | hint (H)                      |
 * | LB / RB              | previous / next page        | undo / redo                   |
 * | LT / RT              | —                           | to the on-screen keys, and back |
 * | Start                | —                           | pause, and back to the board  |
 * | Back / Select        | —                           | the rules (?)                 |
 *
 * It costs nothing until a pad is connected: the only thing installed up front is a pair
 * of connect/disconnect listeners, and the polling loop runs only while a pad is there
 * (and, being a `requestAnimationFrame` loop, not at all in a hidden tab).
 */

import { onAdStateChange } from '../crazygames';
import { t } from '../i18n';
import { toast } from './dialogs';
import { markKeyboardInput, overlayOpen } from './nav';

/** Standard-mapping button indices (https://w3c.github.io/gamepad/#remapping). */
const BTN = {
  a: 0,
  b: 1,
  x: 2,
  y: 3,
  lb: 4,
  rb: 5,
  lt: 6,
  rt: 7,
  back: 8,
  start: 9,
  up: 12,
  down: 13,
  left: 14,
  right: 15,
} as const;

type Control = keyof typeof BTN;

/** How far the stick must lean to count, and how far back it must come to let go. */
const STICK_ON = 0.55;
const STICK_OFF = 0.35;
/** Held directions repeat like a held key: a pause, then a steady rate. */
const REPEAT_DELAY_MS = 380;
const REPEAT_EVERY_MS = 110;

const DIRECTIONS: readonly Control[] = ['up', 'down', 'left', 'right'];

/**
 * Sent on `window` by a trigger on the play page: the page moves the focus into its keypad
 * (showing it, on a screen that keeps it behind a switch), or back to the board from there.
 * There is no key for it — a keyboard has the digits themselves.
 */
export const PAD_KEYPAD_EVENT = 'puzzlebox:pad-keypad';

const ARROW: Record<string, string> = {
  up: 'ArrowUp',
  down: 'ArrowDown',
  left: 'ArrowLeft',
  right: 'ArrowRight',
};

/**
 * Which controls are held on `pad`, with the left stick folded into the D-pad. `prev`
 * gives the stick its hysteresis, so a stick resting near the threshold does not chatter.
 */
export function heldControls(
  pad: { buttons: readonly { pressed: boolean; value: number }[]; axes: readonly number[] },
  prev: ReadonlySet<Control> = new Set(),
): Set<Control> {
  const held = new Set<Control>();
  for (const [name, i] of Object.entries(BTN) as [Control, number][]) {
    const b = pad.buttons[i];
    if (b && (b.pressed || b.value > 0.5)) held.add(name);
  }
  const x = pad.axes[0] ?? 0;
  const y = pad.axes[1] ?? 0;
  const lean = (v: number, dir: Control) => v >= (prev.has(dir) ? STICK_OFF : STICK_ON);
  // One axis at a time, the stronger one, so a diagonal lean moves one way, not both.
  if (Math.abs(x) >= Math.abs(y)) {
    if (lean(x, 'right')) held.add('right');
    if (lean(-x, 'left')) held.add('left');
  } else {
    if (lean(y, 'down')) held.add('down');
    if (lean(-y, 'up')) held.add('up');
  }
  return held;
}

// ------------------------------------------------------------------ sending keys

function onPlayPage(): boolean {
  return !!document.querySelector('#app > .game-page');
}

function board(): HTMLCanvasElement | null {
  return document.querySelector<HTMLCanvasElement>('#app > .game-page .puzzle-canvas');
}

/** The element a key press would go to: whatever has the focus, else the board or page. */
function keyTarget(): HTMLElement {
  const a = document.activeElement;
  if (a instanceof HTMLElement && a !== document.body) return a;
  if (onPlayPage() && !overlayOpen()) {
    const c = board();
    if (c) {
      c.focus({ preventScroll: true });
      return c;
    }
  }
  return document.body;
}

function sendKey(key: string, code = key): void {
  const target = keyTarget();
  const init = { key, code, bubbles: true, cancelable: true, composed: true };
  target.dispatchEvent(new KeyboardEvent('keydown', init));
  target.dispatchEvent(new KeyboardEvent('keyup', init));
}

const PRESSES =
  'button, a, [role="link"], [role="tab"], [role="option"], summary, label, input[type="checkbox"], input[type="radio"], .card';

/** A: press the control with the selector on it, or Enter on the board. */
function pressA(): void {
  markKeyboardInput();
  const a = document.activeElement;
  // The tutorial's Next, while the board has the keys: the step is waiting for it.
  const next = document.querySelector<HTMLButtonElement>('.tut-next');
  if (
    next &&
    !next.disabled &&
    next.getClientRects().length &&
    (!a || a === document.body || a instanceof HTMLCanvasElement)
  ) {
    next.click();
    return;
  }
  if (a instanceof HTMLElement && !(a instanceof HTMLCanvasElement) && a.matches(PRESSES)) {
    a.click();
    return;
  }
  sendKey('Enter');
}

function press(control: Control): void {
  const play = onPlayPage() && !overlayOpen();
  switch (control) {
    case 'up':
    case 'down':
    case 'left':
    case 'right':
      sendKey(ARROW[control]);
      return;
    case 'a':
      pressA();
      return;
    case 'b':
      sendKey('Escape');
      return;
    case 'start':
      // A toggle on the play page: Esc opens the pause menu and closes it again.
      if (onPlayPage()) sendKey('Escape');
      return;
    case 'back':
      if (onPlayPage()) sendKey('?', 'Slash');
      return;
    case 'x':
      if (play) sendKey(' ', 'Space');
      return;
    case 'y':
      if (play) sendKey('h', 'KeyH');
      return;
    case 'lb':
      if (play) sendKey('u', 'KeyU');
      else if (!onPlayPage()) sendKey('PageUp');
      return;
    case 'rb':
      if (play) sendKey('r', 'KeyR');
      else if (!onPlayPage()) sendKey('PageDown');
      return;
    case 'lt':
    case 'rt':
      // Not `play`: from the keys, which hold the arrows while they have the focus, the
      // same trigger is the way back. The page itself says no under a dialog.
      if (onPlayPage()) {
        markKeyboardInput();
        window.dispatchEvent(new CustomEvent(PAD_KEYPAD_EVENT));
      }
      return;
  }
}

// ------------------------------------------------------------------ polling

let raf = 0;
let adUp = false;
/** Per pad index: what was held last frame, and when each held direction fires next. */
const state = new Map<number, { held: Set<Control>; nextAt: Map<Control, number> }>();

function pads(): Gamepad[] {
  try {
    return [...(navigator.getGamepads?.() ?? [])].filter((p): p is Gamepad => !!p && p.connected);
  } catch {
    return [];
  }
}

function poll(): void {
  raf = 0;
  const list = pads();
  if (!list.length) {
    state.clear();
    return;
  }
  const now = performance.now();
  for (const pad of list) {
    let s = state.get(pad.index);
    if (!s) {
      s = { held: new Set(), nextAt: new Map() };
      state.set(pad.index, s);
    }
    const held = heldControls(pad, s.held);
    for (const c of held) {
      const fresh = !s.held.has(c);
      if (fresh) {
        s.nextAt.set(c, now + REPEAT_DELAY_MS);
        if (!adUp) safely(() => press(c));
      } else if (DIRECTIONS.includes(c) && now >= (s.nextAt.get(c) ?? Infinity)) {
        s.nextAt.set(c, now + REPEAT_EVERY_MS);
        if (!adUp) safely(() => press(c));
      }
    }
    for (const c of s.held) if (!held.has(c)) s.nextAt.delete(c);
    s.held = held;
  }
  raf = requestAnimationFrame(poll);
}

function safely(fn: () => void): void {
  try {
    fn();
  } catch (e) {
    console.debug('[gamepad] a press threw; ignoring.', e);
  }
}

function start(): void {
  if (!raf) raf = requestAnimationFrame(poll);
}

let installed = false;
let greeted = false;

export function installGamepad(): void {
  if (installed || typeof window === 'undefined' || !('getGamepads' in navigator)) return;
  installed = true;
  onAdStateChange((on) => {
    adUp = on;
  });
  window.addEventListener('gamepadconnected', () => {
    markKeyboardInput();
    if (!greeted) {
      greeted = true;
      toast(t('ui.gamepad.connected'), 'success');
    }
    start();
  });
  window.addEventListener('gamepaddisconnected', (e) => {
    state.delete(e.gamepad.index);
  });
  // A pad already known to the browser from earlier on this page load.
  if (pads().length) start();
}
