import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { border } from './index';
import type { GalaxiesState, GalaxiesUI } from './index';

/**
 * The fixed 5×3 board has two dots: one on the line inside the left-hand 2×3 block, one
 * in the middle of the right-hand 3×3 block. Positions below are doubled-grid
 * coordinates, as the game uses them.
 */
const LEFT_DOT = { x: 2, y: 3 };
const RIGHT_DOT = { x: 7, y: 3 };
/** The three wall segments that part the two galaxies, top to bottom. */
const WALLS = [
  { x: 4, y: 1 },
  { x: 4, y: 3 },
  { x: 4, y: 5 },
];
/** The square that gets an arrow, in ordinary cell coordinates. */
const ARROW_CELL = { x: 4, y: 0 };

/** Pixel position of a doubled-grid coordinate. */
function pos(gx: number, gy: number, t: number): { x: number; y: number } {
  const b = border(t);
  return { x: b + (gx * t) / 2, y: b + (gy * t) / 2 };
}

/** A thin box around one wall segment (vertical here: even x, odd y). */
function wallRect(w: { x: number; y: number }, t: number): TutorialRect {
  const p = pos(w.x, w.y - 1, t);
  const thick = t * 0.3;
  return { x: p.x - thick / 2, y: p.y, w: thick, h: t };
}

/** A little box around a dot. */
function dotRect(d: { x: number; y: number }, t: number): TutorialRect {
  const p = pos(d.x, d.y, t);
  const r = t * 0.3;
  return { x: p.x - r, y: p.y - r, w: 2 * r, h: 2 * r };
}

const edgeSet = (state: GalaxiesState, w: { x: number; y: number }) =>
  state.edges[w.y * state.sx + w.x] === 1;

export const tutorial: Tutorial<GalaxiesState, GalaxiesUI> = {
  steps: [
    {
      gameId: '5x3:te',
      text: 'Two dots, so two galaxies. Draw walls along the grid lines so that each dot ends up at the centre of its own region: turn a region 180° about its dot and it must land exactly on itself.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The left dot sits on a line between two squares, so its galaxy has to be the two left-hand columns. **Click** the grid line just right of them, in the **top row**.',
      highlight: ({ tileSize }) => [wallRect(WALLS[0], tileSize), dotRect(LEFT_DOT, tileSize)],
      pointer: ({ tileSize }) => pos(WALLS[0].x, WALLS[0].y, tileSize),
      waitFor: ({ state }) => edgeSet(state, WALLS[0]),
    },
    {
      text: 'Dots double as notepaper. **Drag** from the right-hand dot into the **top-right square** to leave an arrow there, marking that square as part of its galaxy.',
      highlight: ({ tileSize }) => [
        dotRect(RIGHT_DOT, tileSize),
        cellRect(ARROW_CELL.x, ARROW_CELL.y, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => ({
        ...pos(RIGHT_DOT.x, RIGHT_DOT.y, tileSize),
        to: cellCentre(ARROW_CELL.x, ARROW_CELL.y, tileSize, border(tileSize)),
      }),
      waitFor: ({ state }) => {
        const cell = (2 * ARROW_CELL.y + 1) * state.sx + 2 * ARROW_CELL.x + 1;
        return state.assoc[cell] === RIGHT_DOT.y * state.sx + RIGHT_DOT.x;
      },
    },
    {
      text: 'Back to the wall: **click** the same grid line one row down, in the **middle row**.',
      highlight: ({ tileSize }) => wallRect(WALLS[1], tileSize),
      pointer: ({ tileSize }) => pos(WALLS[1].x, WALLS[1].y, tileSize),
      waitFor: ({ state }) => edgeSet(state, WALLS[1]),
    },
    {
      text: 'One segment left, in the **bottom row**. **Click** it to close both galaxies off.',
      highlight: ({ tileSize }) => wallRect(WALLS[2], tileSize),
      pointer: ({ tileSize }) => pos(WALLS[2].x, WALLS[2].y, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Both regions shaded, so both are right. **Solve** draws a whole answer, and a click on a wall rubs it out again.',
      target: '[data-cmd="solve"]',
    },
  ],
};
