import { t } from '../i18n';
import { gsap, staggerIn } from './anim';
import { ziggyEnabled, ziggySVG } from '../framework/ziggy';
import { animateMascot } from './mascot';
import { brandMarkSVG } from './brand';
import { READY_CAP_MS, dropBootScreen, firstScreenReady, fontsReady } from './boot';
import { reducedMotion } from './motion';

/** Asked at the moment of moving, so the switch in Settings takes effect at once. */
const reduced = (): boolean => reducedMotion();

/**
 * How long the drawing waits for the lettering. The wordmark is one span per letter, so a
 * face that lands halfway through would swap under letters already in the air; past this
 * the splash plays in whatever face there is rather than keep the player looking at paper.
 */
const FONT_WAIT_MS = 1500;
/** A first screen still being drawn after the hold gets a loading mark only past this. */
const PROGRESS_AFTER_MS = 250;

/**
 * A two-second animated splash shown once per page load, on top of the app (which mounts
 * underneath it immediately, so nothing is actually delayed). The icon draws itself in,
 * the wordmark pops in letter by letter with its sketchy underline, and then the lockup
 * flies up into the menu's masthead while the paper opens under it (see {@link handOff}).
 *
 * The overlay is `pointer-events: none` — a real click always reaches the app underneath,
 * splash or not — so it can never eat a tap meant for the menu or a game. It respects
 * reduced-motion (skipped entirely) and gets out of the way at the first sign the player
 * would rather be playing: any key press, any press on the page (which still does whatever
 * it was going to do underneath), or the small "Skip" corner control.
 *
 * It takes over from the loading screen (`#boot`, ui/boot.ts) on the same paper, starts
 * drawing once the hand lettering has arrived, and — played through to the end — lifts only
 * once the page under it is drawn too, with a pencil progress line if that takes a moment,
 * so nothing pops in after it has gone. False when there is no splash (reduced motion).
 */
export function showSplash(): boolean {
  if (reduced()) return false;

  const overlay = document.createElement('div');
  overlay.className = 'splash-overlay';
  overlay.setAttribute('aria-hidden', 'true');
  // The wordmark is one flex item per letter, and a flex row runs in the page's direction:
  // on an Arabic page "Puzzlebox" came out backwards. `dir="auto"` takes the direction
  // from the name itself instead.
  // The one mark, from src/ui/brand.ts — the splash used to draw its own box-and-cross,
  // which is how the tab icon and the splash drifted into being two different logos.
  overlay.innerHTML = `
    <div class="splash-markwrap">
      ${ziggyEnabled() ? ziggySVG({ className: 'splash-ziggy', size: 76, tilt: -10 }) : ''}
      ${brandMarkSVG({ className: 'splash-icon brand-mark', size: 120 })}
    </div>
    <div class="splash-word" dir="auto">${[...t('ui.appName')]
      .map((c) => `<span>${c === ' ' ? '&nbsp;' : c}</span>`)
      .join('')}</div>
    <div class="splash-underline"></div>
    <div class="splash-tagline">${t('ui.splash.tagline')}</div>
    <div class="splash-progress"><span></span></div>
    <button type="button" class="splash-skip" tabindex="-1">${t('ui.splash.skip')}</button>
  `;
  document.body.append(overlay);

  const box = overlay.querySelector('.brand-box') as unknown as SVGGeometryElement;
  const barH = overlay.querySelector('.brand-bar-h') as unknown as SVGGeometryElement;
  const barV = overlay.querySelector('.brand-bar-v') as unknown as SVGGeometryElement;
  const piece = overlay.querySelector('.brand-piece')!;
  const ziggy = overlay.querySelector<SVGSVGElement>('.splash-ziggy');
  // Breathing and blinking from the moment he is drawn, which is under the box and out of
  // sight; by the time he steps out from behind it he is already alive rather than
  // starting to be. The idle loops run on his body, the entrance below on the `<svg>`, so
  // the two never write the same transform (see ui/mascot.ts).
  const mascot = ziggy ? animateMascot(ziggy) : null;
  const icon = overlay.querySelector('.splash-icon')!;
  const letters = overlay.querySelectorAll('.splash-word span');
  const underline = overlay.querySelector('.splash-underline')!;
  const tagline = overlay.querySelector('.splash-tagline')!;
  const progress = overlay.querySelector<HTMLElement>('.splash-progress')!;
  const skip = overlay.querySelector('.splash-skip')!;

  const setupDash = (el: SVGGeometryElement) => {
    const len = el.getTotalLength();
    el.style.strokeDasharray = `${len}`;
    el.style.strokeDashoffset = `${len}`;
  };
  try {
    setupDash(box);
    setupDash(barH);
    setupDash(barV);
  } catch {
    /* getTotalLength unsupported: the shapes just render solid, still fine */
  }
  gsap.set(icon, { scale: 0.85, opacity: 0, transformOrigin: '50% 50%' });
  // The box is filled in the shared mark; here it starts empty so the outline can draw
  // itself onto bare paper and the fill arrives with it.
  gsap.set(box, { fillOpacity: 0 });
  // GSAP writes the whole `transform`, so the mark's own `rotate(-12 …)` would be wiped
  // the moment the piece is tweened: the tilt has to be part of the tween's end state.
  gsap.set(piece, {
    opacity: 0,
    y: -30,
    rotation: -34,
    scale: 0.6,
    transformOrigin: '77px 21px',
  });
  if (ziggy) gsap.set(ziggy, { opacity: 0, y: 26, scale: 0.7, transformOrigin: '50% 100%' });
  gsap.set(letters, { opacity: 0, y: 14 });
  gsap.set(underline, { scaleX: 0 });
  gsap.set(tagline, { opacity: 0, y: 6 });
  gsap.set(skip, { opacity: 0 });

  let done = false;
  /**
   * Hand over to the page underneath. `hurried` is a player who pressed something: they
   * get the same move at twice the speed, since their press has already gone through to
   * the app and they are waiting on nothing but us.
   */
  const finish = (hurried: boolean) => {
    if (done) return;
    done = true;
    // Cut short, the drawing is finished in one frame before it moves: a half-drawn box and
    // half the letters flying up to the masthead would land as something other than the
    // logo.
    tl.progress(1, true).kill();
    dropBootScreen();
    mascot?.destroy();
    document.removeEventListener('keydown', onPress);
    document.removeEventListener('pointerdown', onPress);
    const out = handOff(overlay) ?? fadeOut(overlay);
    if (hurried) out.timeScale(2);
    // A press that navigated (a card, a key) turns the page mid-flight: there is no
    // masthead left to land on, so get out of the way at once.
    const bail = () => out.progress(1);
    window.addEventListener('hashchange', bail, { once: true });
    out.eventCallback('onComplete', () => {
      window.removeEventListener('hashchange', bail);
      overlay.remove();
    });
  };
  const onPress = () => finish(true);

  /**
   * Played through: hold on the finished lockup until the page under it is drawn, so the
   * hand-off opens on a finished screen. A wait long enough to notice shows a pencil line
   * filling as the pictures land; it is capped (`READY_CAP_MS`), never a trap.
   */
  const settle = () => {
    if (done) return;
    const markAfter = performance.now() + PROGRESS_AFTER_MS;
    void firstScreenReady(READY_CAP_MS, (fraction) => {
      if (done) return;
      if (performance.now() >= markAfter) progress.classList.add('shown');
      progress.style.setProperty('--progress', fraction.toFixed(3));
    }).then(() => finish(false));
  };
  const tl = gsap.timeline({ paused: true, onComplete: settle });
  tl.to(icon, { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(2)' }, 0)
    .to(box, { strokeDashoffset: 0, duration: 0.5, ease: 'power2.inOut' }, 0.05)
    .to(barH, { strokeDashoffset: 0, duration: 0.22, ease: 'power2.out' }, 0.4)
    .to(barV, { strokeDashoffset: 0, duration: 0.22, ease: 'power2.out' }, 0.48)
    .to(box, { fillOpacity: 1, duration: 0.3, ease: 'power1.out' }, 0.3)
    // The piece drops into the box, and the box takes the knock — the whole mark is one
    // gesture rather than a logo that merely appears.
    .to(
      piece,
      { opacity: 1, y: 0, rotation: -12, scale: 1, duration: 0.34, ease: 'back.out(2.2)' },
      0.5,
    )
    // Ziggy comes up from behind once the piece has landed — he is reacting to it, so he
    // must not arrive first.
    .to(
      ziggy ?? {},
      ziggy ? { opacity: 1, y: 0, scale: 1, duration: 0.42, ease: 'back.out(2.4)' } : {},
      0.86,
    )
    .to(icon, { rotation: -4, duration: 0.09 }, 0.62)
    .to(icon, { rotation: 4, duration: 0.09 }, 0.71)
    .to(icon, { rotation: 0, duration: 0.12, clearProps: 'rotation' }, 0.8)
    .to(letters, { opacity: 1, y: 0, duration: 0.4, ease: 'back.out(1.8)', stagger: 0.03 }, 0.55)
    .to(underline, { scaleX: 1, duration: 0.35, ease: 'power2.out' }, 0.95)
    .to(tagline, { opacity: 1, y: 0, duration: 0.35, ease: 'power2.out' }, 1.1)
    .to(skip, { opacity: 1, duration: 0.3 }, 1.1)
    // The tagline is the last word, so Ziggy gets the last gesture: one hop into the hold,
    // which is the only movement on screen while the whole thing settles.
    .call(() => mascot?.cheer(), undefined, 1.34)
    .to({}, { duration: 0.55 }, 1.45); // hold, so the whole thing reads for ~2s

  // The Skip corner is reached by the same press as the rest of the page: `pointerdown`
  // lands before its `click` would.
  document.addEventListener('keydown', onPress, { once: true });
  document.addEventListener('pointerdown', onPress, { once: true });

  // The loading screen stays over the (identical) paper until the drawing can start.
  void fontsReady(FONT_WAIT_MS).then(() => {
    if (done) return;
    dropBootScreen();
    tl.play();
  });
  return true;
}

/** The old exit, for when there is no masthead on screen to hand over to. */
function fadeOut(overlay: HTMLElement): gsap.core.Timeline {
  return gsap
    .timeline()
    .to(overlay, { opacity: 0, scale: 1.05, duration: 0.35, ease: 'power2.in' });
}

/**
 * The splash does not leave; it becomes the menu. The mark and the wordmark fly up into
 * the masthead's lockup and settle there as the real one, the paper behind them opens
 * from the middle like an iris, and the collection deals its cards in under it — so the
 * first thing a player sees move on the menu is the logo they have just watched being
 * drawn, arriving where it lives.
 *
 * Returns null when there is no visible masthead to land on (a narrow frame scrolled
 * past it, a layout without one), and the caller falls back to a plain fade.
 */
function handOff(overlay: HTMLElement): gsap.core.Timeline | null {
  // The menu's masthead has the mark and the wordmark; the first-visit welcome has the
  // mark over its question, so there the word has nowhere to go and fades where it is.
  const logo =
    document.querySelector<HTMLElement>('.menu-page .logo') ??
    document.querySelector<HTMLElement>('.welcome-page .welcome-mark');
  const toMark = logo?.matches('.welcome-mark')
    ? logo
    : logo?.querySelector<HTMLElement>('.logo-mark');
  const toWord = logo?.querySelector<HTMLElement>('.logo-word') ?? null;
  const fromMark = overlay.querySelector<HTMLElement>('.splash-markwrap');
  const fromWord = overlay.querySelector<HTMLElement>('.splash-word');
  if (!logo || !toMark || !fromMark || !fromWord) return null;
  const a = fromMark.getBoundingClientRect();
  const b = toMark.getBoundingClientRect();
  const w = fromWord.getBoundingClientRect();
  const v = toWord?.getBoundingClientRect();
  if (!b.width || (v && !v.height) || b.bottom < 0 || b.top > window.innerHeight) return null;

  // Sizes from the layout box, not the bounding one: the masthead's mark is tilted, and a
  // rotated box measures bigger than the thing drawn in it.
  const markScale = toMark.offsetWidth / fromMark.offsetWidth;
  const wordScale = toWord
    ? parseFloat(getComputedStyle(toWord).fontSize) /
      parseFloat(getComputedStyle(fromWord).fontSize)
    : 1;
  const cards = [
    ...document.querySelectorAll<HTMLElement>('.menu-page .card, .welcome-page .card'),
  ].filter(
    (c) =>
      !c.hidden && !c.classList.contains('off-page') && c.getBoundingClientRect().top < innerHeight,
  );

  // The real lockup waits, invisible, for its double to arrive. The menu's own entrance
  // played under the splash where nobody saw it, so it is taken back and played again.
  gsap.killTweensOf(logo);
  gsap.set(logo, { opacity: 0, y: 0, '--underline': 0 });
  gsap.killTweensOf(cards);
  gsap.set(cards, { opacity: 0 });

  // The iris opens where the mark was, and wide enough to clear the furthest corner.
  const cx = a.left + a.width / 2;
  const cy = a.top + a.height / 2;
  const reach = Math.hypot(Math.max(cx, innerWidth - cx), Math.max(cy, innerHeight - cy));
  overlay.style.setProperty('--iris-x', `${cx}px`);
  overlay.style.setProperty('--iris-y', `${cy}px`);
  overlay.classList.add('handing-off');

  const fly = { duration: 0.7, ease: 'power3.inOut' };
  const tl = gsap.timeline();
  tl.to(
    overlay.querySelectorAll('.splash-underline, .splash-tagline, .splash-progress, .splash-skip'),
    {
      opacity: 0,
      y: 8,
      duration: 0.18,
      ease: 'power1.in',
    },
  )
    .fromTo(
      overlay,
      { '--iris': '0px' },
      { '--iris': `${reach + 40}px`, duration: 0.75, ease: 'power2.in' },
      0.05,
    )
    .to(
      fromMark,
      {
        ...fly,
        x: b.left + b.width / 2 - cx,
        y: b.top + b.height / 2 - cy,
        scale: markScale,
        rotation: -3.5,
      },
      0,
    )
    .to(
      fromWord,
      v
        ? {
            ...fly,
            x: v.left + v.width / 2 - (w.left + w.width / 2),
            y: v.top + v.height / 2 - (w.top + w.height / 2),
            scale: wordScale,
          }
        : { opacity: 0, y: -10, scale: 0.9, duration: 0.3, ease: 'power2.in' },
      0.04,
    )
    // Landed: the real lockup takes over from its double in one frame, and draws its
    // underline as if it had been the one flying all along.
    .set(logo, { opacity: 1 }, fly.duration + 0.04)
    .set([fromMark, fromWord], { opacity: 0 }, fly.duration + 0.04)
    .to(logo, { '--underline': 1, duration: 0.4, ease: 'power2.out' }, fly.duration + 0.04)
    // The collection arrives through the opening, in the order the eye reaches it.
    .call(() => staggerIn(cards), undefined, 0.35)
    // Long enough for the underline; the cards finish on their own after the overlay goes.
    .to({}, { duration: 0.01 }, fly.duration + 0.45);
  return tl;
}
