import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { FloodParams, FloodState } from './index';
import { solveGrid } from './solver';

type C = typeof PALETTE;

/**
 * A little Flood board: `rows` holds one letter per square, each a colour token's initial
 * (b blue, r red, y yellow, g green, o orange, p purple).
 */
function board(c: C, x: number, y: number, s: number, rows: string[]): string {
  const colour: Record<string, string> = {
    b: c.blue,
    r: c.red,
    y: c.yellow,
    g: c.green,
    o: c.orange,
    p: c.purple,
  };
  let out = '';
  rows.forEach((row, j) => {
    for (let i = 0; i < row.length; i++)
      out += `<rect x="${x + i * s}" y="${y + j * s}" width="${s}" height="${s}" fill="${colour[row[i]]}"/>`;
  });
  const w = rows[0].length * s;
  const h = rows.length * s;
  let lines = '';
  for (let i = 1; i < rows[0].length; i++) lines += `M${x + i * s} ${y} V${y + h} `;
  for (let j = 1; j < rows.length; j++) lines += `M${x} ${y + j * s} H${x + w} `;
  return (
    out +
    `<path d="${lines}" stroke="${c.ink}" stroke-width="1.2" opacity="0.3"/>` +
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" stroke="${c.ink}" stroke-width="4"/>`
  );
}

/** A water drop with its point at the top. */
function drop(c: C, cx: number, cy: number, r: number, fill: string): string {
  return `<path d="M${cx} ${cy - r * 1.9} Q${cx + r * 1.1} ${cy - r * 0.5} ${cx + r} ${cy + r * 0.2} A${r} ${r} 0 1 1 ${cx - r} ${cy + r * 0.2} Q${cx - r * 1.1} ${cy - r * 0.5} ${cx} ${cy - r * 1.9} Z" fill="${fill}" stroke="${c.ink}" stroke-width="3" stroke-linejoin="round"/>`;
}

/**
 * The number of moves the computer's own solution takes, worked out again from the deal
 * exactly as the generator did. The limit less the params' spare moves is not enough: a
 * puzzle opened from a shared code carries no spare-move count, so its params hold the
 * default one rather than the one the limit was built with.
 */
function solverMoves(ctx: { initial: FloodState }): number {
  const { grid, w, h, colours } = ctx.initial;
  return solveGrid(grid, w, h, colours).length;
}

export const achievements = defineAchievements<FloodParams, FloodState>([
  {
    id: 'spare-moves',
    name: 'Moves to Spare',
    description: 'Flood the grid with at least three moves left over.',
    tier: 'silver',
    hue: 'blue',
    // The finished grid, with three unused drops lined up beside it.
    art: (c) =>
      board(c, 20, 26, 12, ['bbbb', 'bbbb', 'bbbb', 'bbbb']) +
      drop(c, 74, 30, 5.5, c.blue) +
      drop(c, 74, 51, 5.5, c.blue) +
      drop(c, 74, 72, 5.5, c.blue),
    test: (ctx) => ctx.state.moveLimit - ctx.state.moves >= 3,
  },
  {
    id: 'beat-the-solver',
    name: 'Beat the Machine',
    description: "Flood the grid in fewer moves than the computer's own solution.",
    tier: 'gold',
    hue: 'yellow',
    // The flood from the corner rolling over the computer's cog.
    art: (c) => {
      let teeth = '';
      for (let i = 0; i < 8; i++) {
        const a = (i * Math.PI) / 4 + Math.PI / 8;
        const x = 60 + Math.cos(a) * 15;
        const y = 60 + Math.sin(a) * 15;
        teeth += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="5" fill="${c.pencil}" stroke="${c.ink}" stroke-width="3"/>`;
      }
      return (
        board(c, 20, 20, 15, ['bbbr', 'bbgy', 'byro', 'rogy']) +
        teeth +
        `<circle cx="60" cy="60" r="14" fill="${c.pencil}" stroke="${c.ink}" stroke-width="3.5"/>` +
        `<circle cx="60" cy="60" r="5" fill="${c.shade}" stroke="${c.ink}" stroke-width="3"/>` +
        `<path d="M24 30 Q30 26 36 30 M24 42 Q30 38 36 42" fill="none" stroke="${c.highlight}" stroke-width="3" stroke-linecap="round"/>`
      );
    },
    test: (ctx) => ctx.state.moves < solverMoves(ctx),
  },
  {
    id: 'one-colour-short',
    name: 'One Colour Short',
    description: 'Run out of moves with only two colours left on the grid.',
    tier: 'bronze',
    hidden: true,
    hue: 'orange',
    on: 'lose',
    // A grid flooded all but one stubborn square.
    art: (c) =>
      board(c, 22, 22, 13, ['bbbb', 'bbbb', 'bbbb', 'bbbo']) +
      `<circle cx="67.5" cy="67.5" r="11" fill="none" stroke="${c.red}" stroke-width="4"/>`,
    test: (ctx) => {
      const seen = new Set<number>();
      for (const v of ctx.state.grid) seen.add(v);
      return seen.size === 2;
    },
  },
]);
