import type { PointerHint, Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellRect } from '../../framework/tutorial';
import { placementOf } from './board';
import type { DominosaState, DominosaUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** The walkthrough puzzle: the double-1 set (0-0, 0-1, 1-1) in a 3×2 grid, reading
 *  `0 0 1 / 1 1 0`. The only tiling that uses each domino once is the two left-hand
 *  pairs plus the right-hand column. */
const GAME_ID = '1:001110';

/** The pair of squares a domino would cover, as one 2×1 or 1×2 rectangle. */
function pairRect(state: DominosaState, a: number, b: number, t: number): TutorialRect {
  const across = b === a + 1;
  return cellRect(
    a % state.w,
    Math.floor(a / state.w),
    t,
    border(t),
    across ? 2 : 1,
    across ? 1 : 2,
  );
}

/** The middle of the boundary between two neighbouring squares: where to click. */
function edgeCentre(state: DominosaState, a: number, b: number, t: number): PointerHint {
  const bd = border(t);
  const x = a % state.w;
  const y = Math.floor(a / state.w);
  return b === a + 1
    ? { x: bd + (x + 1) * t, y: bd + (y + 0.5) * t }
    : { x: bd + (x + 0.5) * t, y: bd + (y + 1) * t };
}

/** Squares of the walkthrough grid, by position. */
const TOP_LEFT = 0;
const TOP_MID = 1;
const TOP_RIGHT = 2;
const BOT_LEFT = 3;
const BOT_MID = 4;
const BOT_RIGHT = 5;

export const tutorial: Tutorial<DominosaState, DominosaUI> = {
  steps: [
    {
      gameId: GAME_ID,
      text: 'Three dominoes — 0-0, 0-1 and 1-1 — were laid out here and then taken away, leaving their numbers. Split the grid into pairs to put each of them back exactly once.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'No domino may be used twice. Pairing this **0** with the **1** below it would make both outer columns a 0-1, so **right-click** between them to note that they are not a pair.',
      highlight: ({ state, tileSize }) => pairRect(state, TOP_MID, BOT_MID, tileSize),
      pointer: ({ state, tileSize }) => ({
        ...edgeCentre(state, TOP_MID, BOT_MID, tileSize),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => state.edges[placementOf(TOP_MID, BOT_MID, state.w, state.h)] === 1,
    },
    {
      text: 'The only two **0**s that touch are the pair in the top-left corner, so that is where the 0-0 goes. **Click the boundary between them** to lay it.',
      highlight: ({ state, tileSize }) => pairRect(state, TOP_LEFT, TOP_MID, tileSize),
      pointer: ({ state, tileSize }) => edgeCentre(state, TOP_LEFT, TOP_MID, tileSize),
      waitFor: ({ state }) => state.partner[TOP_LEFT] === TOP_MID,
    },
    {
      text: 'Likewise the only touching **1**s are the two along the bottom-left. Click the boundary between them for the 1-1.',
      highlight: ({ state, tileSize }) => pairRect(state, BOT_LEFT, BOT_MID, tileSize),
      pointer: ({ state, tileSize }) => edgeCentre(state, BOT_LEFT, BOT_MID, tileSize),
      waitFor: ({ state }) => state.partner[BOT_LEFT] === BOT_MID,
    },
    {
      text: 'That leaves the right-hand column for the 0-1. Click the boundary between its two numbers to finish.',
      highlight: ({ state, tileSize }) => pairRect(state, TOP_RIGHT, BOT_RIGHT, tileSize),
      pointer: ({ state, tileSize }) => edgeCentre(state, TOP_RIGHT, BOT_RIGHT, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Every domino used once. Click a domino again to lift it off, a repeated one is drawn in red, and **Undo** steps back through your moves.',
      target: '[data-cmd="undo"]',
    },
  ],
};
