/**
 * Planar grids for Loopy.
 *
 * A grid is a set of faces, edges and dots (vertices) with full adjacency. Every tiling
 * is described simply as a list of faces, each a list of corner coordinates in
 * clockwise order (y grows downwards); `makeConsistent` then dedupes the corners, finds
 * the edges and works out, for every dot, the edges and faces around it in clockwise
 * order. The conventions match the original collection's `grid.c`, which the solver's
 * "dline" reasoning relies on:
 *
 *  - around face `f`, `faceEdges[f][k]` joins `faceDots[f][k]` and `faceDots[f][k+1]`;
 *  - around dot `d`, going clockwise one meets `dotFaces[d][0]`, `dotEdges[d][0]`,
 *    `dotFaces[d][1]`, `dotEdges[d][1]`, …; the infinite outside face is `-1`.
 *
 * Coordinates are integers in "grid units"; `tile` says how many units make one tile,
 * so the renderer can scale every tiling to a comparable size.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';
import type { Random } from '../../framework/rng';
import { PENROSE_P2, PENROSE_P3, penrose, penroseCalculateSize, vx, vy } from './penrose';

export interface Grid {
  readonly type: number;
  readonly nf: number;
  readonly ne: number;
  readonly nd: number;
  readonly dotX: Float64Array;
  readonly dotY: Float64Array;
  /** Edges around each dot, clockwise. */
  readonly dotEdges: Int32Array[];
  /** Faces around each dot, clockwise; `dotFaces[d][k]` precedes `dotEdges[d][k]`. -1 is outside. */
  readonly dotFaces: Int32Array[];
  readonly edgeDot1: Int32Array;
  readonly edgeDot2: Int32Array;
  /** The face on each side of an edge; -1 for the outside. `edgeFace1` is never -1. */
  readonly edgeFace1: Int32Array;
  readonly edgeFace2: Int32Array;
  /** Corners of each face, clockwise. */
  readonly faceDots: Int32Array[];
  /** Edges of each face, clockwise; edge k joins corners k and k+1. */
  readonly faceEdges: Int32Array[];
  /** Centre of the largest circle that fits in each face, and its radius. */
  readonly faceCX: Float64Array;
  readonly faceCY: Float64Array;
  readonly faceR: Float64Array;
  readonly minX: number;
  readonly minY: number;
  readonly maxX: number;
  readonly maxY: number;
  /** Grid units per tile. */
  readonly tile: number;
}

export const GRID_SQUARE = 0;
export const GRID_TRIANGULAR = 1;
export const GRID_HONEYCOMB = 2;
export const GRID_SNUBSQUARE = 3;
export const GRID_CAIRO = 4;
export const GRID_GREATHEXAGONAL = 5;
export const GRID_OCTAGONAL = 6;
export const GRID_KITES = 7;
export const GRID_FLORET = 8;
export const GRID_DODECAGONAL = 9;
export const GRID_GREATDODECAGONAL = 10;
export const GRID_PENROSE_P2 = 11;
export const GRID_PENROSE_P3 = 12;

export interface GridTypeInfo {
  name: string;
  /** Both dimensions must be at least this. */
  amin: number;
  /** At least one dimension must be at least this. */
  omin: number;
  /** Rough number of faces per w×h cell, to bound generation time. */
  density: number;
}

export const GRID_TYPES: readonly GridTypeInfo[] = [
  { name: 'Squares', amin: 3, omin: 3, density: 1 },
  { name: 'Triangular', amin: 3, omin: 3, density: 2 },
  { name: 'Honeycomb', amin: 3, omin: 3, density: 1 },
  { name: 'Snub-Square', amin: 3, omin: 3, density: 3 },
  { name: 'Cairo', amin: 3, omin: 4, density: 2 },
  { name: 'Great-Hexagonal', amin: 3, omin: 3, density: 6 },
  { name: 'Octagonal', amin: 3, omin: 3, density: 2 },
  { name: 'Kites', amin: 3, omin: 3, density: 6 },
  { name: 'Floret', amin: 1, omin: 2, density: 6 },
  { name: 'Dodecagonal', amin: 2, omin: 2, density: 3 },
  { name: 'Great-Dodecagonal', amin: 2, omin: 2, density: 6 },
  { name: 'Penrose (kite/dart)', amin: 3, omin: 3, density: 1 },
  { name: 'Penrose (rhombs)', amin: 3, omin: 3, density: 1 },
];

const PENROSE_TILE = 100;

// ------------------------------------------------------------------ building

/** Collects faces as lists of dot indices, deduplicating dots by coordinate. */
class Builder {
  readonly xs: number[] = [];
  readonly ys: number[] = [];
  readonly faces: number[][] = [];
  private readonly index = new Map<number, number>();

  dot(x: number, y: number): number {
    const key = (x + 50000) * 100003 + (y + 50000);
    let i = this.index.get(key);
    if (i === undefined) {
      i = this.xs.length;
      this.xs.push(x);
      this.ys.push(y);
      this.index.set(key, i);
    }
    return i;
  }

  /** Add a face given as a flat list of clockwise corner coordinates. */
  face(coords: number[]): void {
    const f: number[] = [];
    for (let i = 0; i < coords.length; i += 2) f.push(this.dot(coords[i], coords[i + 1]));
    this.faces.push(f);
  }
}

/**
 * Trim away any faces not attached to the largest cluster of "landlocked" dots (dots
 * not touching the outside), so that a random patch of an irregular tiling is a single
 * well-formed blob. Operates on the raw face lists before `makeConsistent`.
 */
function trimVigorously(b: Builder): void {
  const nd = b.xs.length;
  const pairs = new Map<number, number>();
  for (let f = 0; f < b.faces.length; f++) {
    const dots = b.faces[f];
    let d0 = dots[dots.length - 1];
    for (const d1 of dots) {
      pairs.set(d0 * nd + d1, f);
      d0 = d1;
    }
  }
  const landlocked = new Uint8Array(nd).fill(1);
  for (const key of pairs.keys()) {
    const i = Math.floor(key / nd);
    const j = key % nd;
    if (!pairs.has(j * nd + i)) landlocked[i] = landlocked[j] = 0;
  }
  const dsf = new DSF(nd);
  for (const key of pairs.keys()) {
    const i = Math.floor(key / nd);
    const j = key % nd;
    if (landlocked[i] && landlocked[j] && pairs.has(j * nd + i)) dsf.merge(i, j);
  }
  let best = -1;
  let bestSize = 0;
  for (let i = 0; i < nd; i++) {
    if (!landlocked[i]) continue;
    const s = dsf.sizeOf(i);
    if (s > bestSize) {
      bestSize = s;
      best = dsf.find(i);
    }
  }
  const keepFace = b.faces.map((dots) => best >= 0 && dots.some((d) => dsf.find(d) === best));
  const newIndex = new Int32Array(nd).fill(-1);
  const xs: number[] = [];
  const ys: number[] = [];
  const faces: number[][] = [];
  for (let f = 0; f < b.faces.length; f++) {
    if (!keepFace[f]) continue;
    faces.push(
      b.faces[f].map((d) => {
        if (newIndex[d] < 0) {
          newIndex[d] = xs.length;
          xs.push(b.xs[d]);
          ys.push(b.ys[d]);
        }
        return newIndex[d];
      }),
    );
  }
  b.xs.length = 0;
  b.ys.length = 0;
  b.faces.length = 0;
  b.xs.push(...xs);
  b.ys.push(...ys);
  b.faces.push(...faces);
}

function segmentDistance(px: number, py: number, ax: number, ay: number, bx: number, by: number) {
  const dx = bx - ax;
  const dy = by - ay;
  const len2 = dx * dx + dy * dy;
  let t = len2 > 0 ? ((px - ax) * dx + (py - ay) * dy) / len2 : 0;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
}

function pointInPolygon(px: number, py: number, xs: number[], ys: number[]): boolean {
  let inside = false;
  const n = xs.length;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const yi = ys[i];
    const yj = ys[j];
    if (yi > py !== yj > py && px < ((xs[j] - xs[i]) * (py - yi)) / (yj - yi) + xs[i]) {
      inside = !inside;
    }
  }
  return inside;
}

/**
 * Centre and radius of (very nearly) the largest circle inside a polygon: a coarse
 * search over the bounding box followed by a pattern search. Non-convex faces such as
 * Penrose darts are handled, which the plain centroid would not manage.
 */
export function incentre(xs: number[], ys: number[]): { x: number; y: number; r: number } {
  const n = xs.length;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let i = 0; i < n; i++) {
    minX = Math.min(minX, xs[i]);
    maxX = Math.max(maxX, xs[i]);
    minY = Math.min(minY, ys[i]);
    maxY = Math.max(maxY, ys[i]);
  }
  const clearance = (px: number, py: number): number => {
    if (!pointInPolygon(px, py, xs, ys)) return -1;
    let best = Infinity;
    for (let i = 0, j = n - 1; i < n; j = i++) {
      best = Math.min(best, segmentDistance(px, py, xs[j], ys[j], xs[i], ys[i]));
    }
    return best;
  };
  const G = 24;
  let bx = 0;
  let by = 0;
  let br = -1;
  for (let i = 0; i <= G; i++) {
    for (let j = 0; j <= G; j++) {
      const px = minX + ((maxX - minX) * (i + 0.5)) / (G + 1);
      const py = minY + ((maxY - minY) * (j + 0.5)) / (G + 1);
      const r = clearance(px, py);
      if (r > br) {
        br = r;
        bx = px;
        by = py;
      }
    }
  }
  if (br < 0) {
    // Degenerate sliver: fall back to the corner centroid.
    let sx = 0;
    let sy = 0;
    for (let i = 0; i < n; i++) {
      sx += xs[i];
      sy += ys[i];
    }
    return { x: sx / n, y: sy / n, r: 0 };
  }
  let step = Math.max(maxX - minX, maxY - minY) / (G + 1);
  const limit = step / 512;
  while (step > limit) {
    let moved = false;
    for (const [dx, dy] of [
      [step, 0],
      [-step, 0],
      [0, step],
      [0, -step],
    ]) {
      const r = clearance(bx + dx, by + dy);
      if (r > br) {
        br = r;
        bx += dx;
        by += dy;
        moved = true;
      }
    }
    if (!moved) step /= 2;
  }
  return { x: bx, y: by, r: br };
}

/**
 * Turn the collected faces into a full grid. Throws if the faces do not form a proper
 * planar patch (an edge shared by three faces, a dot the outside touches twice, …).
 */
function makeConsistent(b: Builder, type: number, tile: number): Grid {
  const nd = b.xs.length;
  const nf = b.faces.length;
  const faceDots = b.faces.map((f) => Int32Array.from(f));

  // Edges: each is first seen from one face; the second face, if any, completes it.
  const edgeDot1: number[] = [];
  const edgeDot2: number[] = [];
  const edgeFace1: number[] = [];
  const edgeFace2: number[] = [];
  const incomplete = new Map<number, number>();
  for (let f = 0; f < nf; f++) {
    const dots = faceDots[f];
    for (let j = 0; j < dots.length; j++) {
      const d1 = dots[j];
      const d2 = dots[(j + 1) % dots.length];
      const key = Math.min(d1, d2) * nd + Math.max(d1, d2);
      const e = incomplete.get(key);
      if (e !== undefined) {
        if (edgeFace2[e] !== -1) throw new Error(tx`edge shared by three faces`);
        edgeFace2[e] = f;
        incomplete.delete(key);
      } else {
        edgeDot1.push(d1);
        edgeDot2.push(d2);
        edgeFace1.push(f);
        edgeFace2.push(-1);
        incomplete.set(key, edgeDot1.length - 1);
      }
    }
  }
  const ne = edgeDot1.length;

  // Each face's edges, in the slot matching its corners.
  const faceEdges = faceDots.map((f) => new Int32Array(f.length).fill(-1));
  for (let e = 0; e < ne; e++) {
    for (const f of [edgeFace1[e], edgeFace2[e]]) {
      if (f < 0) continue;
      const dots = faceDots[f];
      const n = dots.length;
      const k = dots.indexOf(edgeDot1[e]);
      if (dots[(k + 1) % n] === edgeDot2[e]) faceEdges[f][k] = e;
      else if (dots[(k + n - 1) % n] === edgeDot2[e]) faceEdges[f][(k + n - 1) % n] = e;
      else throw new Error(tx`edge does not follow its face`);
    }
  }

  // Each dot's edges and faces, clockwise, by walking around the dot from any face.
  const order = new Int32Array(nd);
  for (let e = 0; e < ne; e++) {
    order[edgeDot1[e]]++;
    order[edgeDot2[e]]++;
  }
  const dotEdges: Int32Array[] = [];
  const dotFaces: Int32Array[] = [];
  for (let d = 0; d < nd; d++) {
    if (order[d] < 2) throw new Error(tx`dot with fewer than two edges`);
    dotEdges.push(new Int32Array(order[d]).fill(-1));
    dotFaces.push(new Int32Array(order[d]).fill(-1));
  }
  for (let f = 0; f < nf; f++) for (const d of faceDots[f]) dotFaces[d][0] = f;
  const otherFace = (e: number, f: number) => (edgeFace1[e] === f ? edgeFace2[e] : edgeFace1[e]);
  for (let d = 0; d < nd; d++) {
    const n = order[d];
    const edges = dotEdges[d];
    const faces = dotFaces[d];
    // Clockwise: from a face, the next edge round the dot is the one arriving at the
    // dot when walking clockwise round that face.
    let cur1 = 0;
    for (;;) {
      const f = faces[cur1];
      const dots = faceDots[f];
      const j = (dots.indexOf(d) + dots.length - 1) % dots.length;
      const e = faceEdges[f][j];
      edges[cur1] = e;
      cur1++;
      if (cur1 === n) break;
      faces[cur1] = otherFace(e, f);
      if (faces[cur1] < 0) break;
    }
    if (cur1 === n) continue;
    // Blocked by the outside: fill in the rest anticlockwise from the starting face.
    let cur2 = 0;
    for (;;) {
      const f = faces[cur2];
      const dots = faceDots[f];
      const e = faceEdges[f][dots.indexOf(d)];
      cur2 = cur2 === 0 ? n - 1 : cur2 - 1;
      edges[cur2] = e;
      if (cur2 === cur1) break;
      faces[cur2] = otherFace(e, f);
      if (faces[cur2] < 0) throw new Error(tx`dot touches the outside twice`);
    }
  }

  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let d = 0; d < nd; d++) {
    minX = Math.min(minX, b.xs[d]);
    maxX = Math.max(maxX, b.xs[d]);
    minY = Math.min(minY, b.ys[d]);
    maxY = Math.max(maxY, b.ys[d]);
  }

  const faceCX = new Float64Array(nf);
  const faceCY = new Float64Array(nf);
  const faceR = new Float64Array(nf);
  for (let f = 0; f < nf; f++) {
    const xs = Array.from(faceDots[f], (d) => b.xs[d]);
    const ys = Array.from(faceDots[f], (d) => b.ys[d]);
    const c = incentre(xs, ys);
    faceCX[f] = c.x;
    faceCY[f] = c.y;
    faceR[f] = c.r;
  }

  return {
    type,
    nf,
    ne,
    nd,
    dotX: Float64Array.from(b.xs),
    dotY: Float64Array.from(b.ys),
    dotEdges,
    dotFaces,
    edgeDot1: Int32Array.from(edgeDot1),
    edgeDot2: Int32Array.from(edgeDot2),
    edgeFace1: Int32Array.from(edgeFace1),
    edgeFace2: Int32Array.from(edgeFace2),
    faceDots,
    faceEdges,
    faceCX,
    faceCY,
    faceR,
    minX,
    minY,
    maxX,
    maxY,
    tile,
  };
}

// ------------------------------------------------------------------ tilings

function squares(w: number, h: number): Builder {
  const a = 20;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = a * x;
      const py = a * y;
      b.face([px, py, px + a, py, px + a, py + a, px, py + a]);
    }
  }
  return b;
}

function honeycomb(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const cx = 3 * a * x;
      const cy = 2 * c * y + (x % 2 ? c : 0);
      b.face([
        cx - a,
        cy - c,
        cx + a,
        cy - c,
        cx + 2 * a,
        cy,
        cx + a,
        cy + c,
        cx - a,
        cy + c,
        cx - 2 * a,
        cy,
      ]);
    }
  }
  return b;
}

/**
 * Triangles. The old style (no grid description) has "ears" — corner triangles joined
 * to only one other face — and is kept so old game IDs still work; the new style ("0")
 * trims them and is symmetric.
 */
function triangular(w: number, h: number, oldStyle: boolean): Builder {
  const vx = 15;
  const vy = 26;
  const b = new Builder();
  if (oldStyle) {
    const dx = (x: number, y: number) => x * 2 * vx + (y % 2 ? vx : 0);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const p = (xx: number, yy: number) => [dx(xx, yy), yy * vy];
        if (y % 2) {
          b.face([...p(x, y), ...p(x + 1, y + 1), ...p(x, y + 1)]);
          b.face([...p(x, y), ...p(x + 1, y), ...p(x + 1, y + 1)]);
        } else {
          b.face([...p(x, y), ...p(x + 1, y), ...p(x, y + 1)]);
          b.face([...p(x + 1, y), ...p(x + 1, y + 1), ...p(x, y + 1)]);
        }
      }
    }
    return b;
  }
  for (let y = 0; y < h; y++) {
    let y0 = y * vy;
    let y1 = y0;
    if (y % 2) y1 += vy;
    else y0 += vy;
    const flip = y % 2 === 1;
    for (let x = 0; x <= w; x++) {
      if (h % 2 === 1 && y === h - 1 && (x === 0 || x === w)) continue;
      const x0 = 2 * x * vx;
      const x1 = x0 + vx;
      const x2 = x1 + vx;
      // Corner order flips with the row parity so every face stays clockwise.
      b.face(flip ? [x0, y0, x2, y0, x1, y1] : [x0, y0, x1, y1, x2, y0]);
    }
    for (let x = 0; x < w; x++) {
      const x0 = (2 * x + 1) * vx;
      const x1 = x0 + vx;
      const x2 = x1 + vx;
      b.face(flip ? [x0, y1, x1, y0, x2, y1] : [x0, y1, x2, y1, x1, y0]);
    }
  }
  return b;
}

function snubSquare(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = (a + c) * x;
      const py = (a + c) * y;
      const odd = (x + y) % 2 === 1;
      if (odd) b.face([px + a, py, px + a + c, py + a, px + c, py + a + c, px, py + c]);
      else b.face([px + c, py, px + a + c, py + c, px + a, py + a + c, px, py + a]);
      if (x > 0) {
        if (odd) b.face([px + a, py, px, py + c, px - a, py]);
        else b.face([px, py + a, px + a, py + a + c, px - a, py + a + c]);
      }
      if (y > 0) {
        if (odd) b.face([px + a, py, px + a + c, py - a, px + a + c, py + a]);
        else b.face([px, py - a, px + c, py, px, py + a]);
      }
    }
  }
  return b;
}

function cairo(w: number, h: number): Builder {
  const a = 14;
  const c = 31;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = 2 * c * x;
      const py = 2 * c * y;
      const odd = (x + y) % 2 === 1;
      if (y > 0) {
        if (odd) {
          b.face([px + a, py - c, px + 2 * c - a, py - c, px + 2 * c, py, px + c, py + a, px, py]);
        } else {
          b.face([px, py, px + c, py - a, px + 2 * c, py, px + 2 * c - a, py + c, px + a, py + c]);
        }
      }
      if (x > 0) {
        if (odd) {
          b.face([px, py, px + c, py + a, px + c, py + 2 * c - a, px, py + 2 * c, px - a, py + c]);
        } else {
          b.face([px, py, px + a, py + c, px, py + 2 * c, px - c, py + 2 * c - a, px - c, py + a]);
        }
      }
    }
  }
  return b;
}

function greatHexagonal(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = (3 * a + c) * x;
      const py = (2 * a + 2 * c) * y + (x % 2 ? a + c : 0);
      b.face([
        px - a,
        py - c,
        px + a,
        py - c,
        px + 2 * a,
        py,
        px + a,
        py + c,
        px - a,
        py + c,
        px - 2 * a,
        py,
      ]);
      if (y < h - 1) {
        b.face([px - a, py + c, px + a, py + c, px + a, py + 2 * a + c, px - a, py + 2 * a + c]);
      }
      if (x < w - 1 && (x % 2 === 0 || y < h - 1)) {
        b.face([px + 2 * a, py, px + 2 * a + c, py + a, px + a + c, py + a + c, px + a, py + c]);
      }
      if (x > 0 && (x % 2 === 0 || y < h - 1)) {
        b.face([px - 2 * a, py, px - a, py + c, px - a - c, py + a + c, px - 2 * a - c, py + a]);
      }
      if (x < w - 1 && y < h - 1) {
        b.face([px + a, py + c, px + a + c, py + a + c, px + a, py + 2 * a + c]);
      }
      if (x > 0 && y < h - 1) {
        b.face([px - a, py + c, px - a, py + 2 * a + c, px - a - c, py + a + c]);
      }
    }
  }
  return b;
}

function octagonal(w: number, h: number): Builder {
  const a = 29;
  const c = 41;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = (2 * a + c) * x;
      const py = (2 * a + c) * y;
      b.face([
        px + a,
        py,
        px + a + c,
        py,
        px + 2 * a + c,
        py + a,
        px + 2 * a + c,
        py + a + c,
        px + a + c,
        py + 2 * a + c,
        px + a,
        py + 2 * a + c,
        px,
        py + a + c,
        px,
        py + a,
      ]);
      if (x > 0 && y > 0) b.face([px, py - a, px + a, py, px, py + a, px - a, py]);
    }
  }
  return b;
}

function kites(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = 4 * c * x + (y % 2 ? 2 * c : 0);
      const py = 6 * a * y;
      b.face([px, py, px + 2 * c, py, px + 2 * c, py + 2 * a, px + c, py + 3 * a]);
      b.face([px, py, px + c, py + 3 * a, px, py + 4 * a, px - c, py + 3 * a]);
      b.face([px, py, px - c, py + 3 * a, px - 2 * c, py + 2 * a, px - 2 * c, py]);
      b.face([px, py, px - 2 * c, py, px - 2 * c, py - 2 * a, px - c, py - 3 * a]);
      b.face([px, py, px - c, py - 3 * a, px, py - 4 * a, px + c, py - 3 * a]);
      b.face([px, py, px + c, py - 3 * a, px + 2 * c, py - 2 * a, px + 2 * c, py]);
    }
  }
  return b;
}

function floret(w: number, h: number): Builder {
  const px = 75;
  const py = -26;
  const qx = 60;
  const qy = 52;
  const rx = qx - px;
  const ry = qy - py;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const cx = ((6 * px + 3 * qx) / 2) * x;
      let cy = (4 * py - 5 * qy) * y;
      if (x % 2) cy -= (4 * py - 5 * qy) / 2;
      else if (y && y === h - 1) continue;
      const pent = (v1x: number, v1y: number, v2x: number, v2y: number) => [
        cx,
        cy,
        cx + 2 * v1x,
        cy + 2 * v1y,
        cx + 2 * v1x + v2x,
        cy + 2 * v1y + v2y,
        cx + 2 * v2x + v1x,
        cy + 2 * v2y + v1y,
        cx + 2 * v2x,
        cy + 2 * v2y,
      ];
      b.face(pent(rx, ry, qx, qy));
      b.face(pent(qx, qy, px, py));
      b.face(pent(px, py, -rx, -ry));
      b.face(pent(-rx, -ry, -qx, -qy));
      b.face(pent(-qx, -qy, -px, -py));
      b.face(pent(-px, -py, rx, ry));
    }
  }
  return b;
}

function dodecagon(b: Builder, px: number, py: number, a: number, c: number): void {
  b.face([
    px + a,
    py - (2 * a + c),
    px + a + c,
    py - (a + c),
    px + 2 * a + c,
    py - a,
    px + 2 * a + c,
    py + a,
    px + a + c,
    py + a + c,
    px + a,
    py + 2 * a + c,
    px - a,
    py + 2 * a + c,
    px - (a + c),
    py + a + c,
    px - (2 * a + c),
    py + a,
    px - (2 * a + c),
    py - a,
    px - (a + c),
    py - (a + c),
    px - a,
    py - (2 * a + c),
  ]);
}

function dodecagonal(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = (4 * a + 2 * c) * x + (y % 2 ? 2 * a + c : 0);
      const py = (3 * a + 2 * c) * y;
      dodecagon(b, px, py, a, c);
      const inner = (x < w - 1 || y % 2 === 0) && (x > 0 || y % 2 === 1);
      if (y < h - 1 && inner) {
        b.face([px + a, py + 2 * a + c, px, py + 2 * a + 2 * c, px - a, py + 2 * a + c]);
      }
      if (y > 0 && inner) {
        b.face([px - a, py - (2 * a + c), px, py - (2 * a + 2 * c), px + a, py - (2 * a + c)]);
      }
    }
  }
  return b;
}

function greatDodecagonal(w: number, h: number): Builder {
  const a = 15;
  const c = 26;
  const b = new Builder();
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const px = (6 * a + 2 * c) * x + (y % 2 ? 3 * a + c : 0);
      const py = (3 * a + 3 * c) * y;
      dodecagon(b, px, py, a, c);
      const inner = (x < w - 1 || y % 2 === 0) && (x > 0 || y % 2 === 1);
      if (y < h - 1 && inner) {
        b.face([
          px + a,
          py + 2 * a + c,
          px + 2 * a,
          py + 2 * a + 2 * c,
          px + a,
          py + 2 * a + 3 * c,
          px - a,
          py + 2 * a + 3 * c,
          px - 2 * a,
          py + 2 * a + 2 * c,
          px - a,
          py + 2 * a + c,
        ]);
      }
      if (y > 0 && inner) {
        b.face([
          px - a,
          py - (2 * a + c),
          px - 2 * a,
          py - (2 * a + 2 * c),
          px - a,
          py - (2 * a + 3 * c),
          px + a,
          py - (2 * a + 3 * c),
          px + 2 * a,
          py - (2 * a + 2 * c),
          px + a,
          py - (2 * a + c),
        ]);
      }
      if (x < w - 1) {
        b.face([
          px + 2 * a + c,
          py - a,
          px + 4 * a + c,
          py - a,
          px + 4 * a + c,
          py + a,
          px + 2 * a + c,
          py + a,
        ]);
      }
      if (y > 0 && (x < w - 1 || y % 2 === 0)) {
        b.face([
          px + a,
          py - (2 * a + c),
          px + 2 * a,
          py - (2 * a + 2 * c),
          px + 2 * a + c,
          py - (a + 2 * c),
          px + a + c,
          py - (a + c),
        ]);
      }
      if (y > 0 && (x > 0 || y % 2 === 1)) {
        b.face([
          px - (a + c),
          py - (a + c),
          px - (2 * a + c),
          py - (a + 2 * c),
          px - 2 * a,
          py - (2 * a + 2 * c),
          px - a,
          py - (2 * a + c),
        ]);
      }
    }
  }
  return b;
}

/** Grid description for a Penrose patch: offset within the big tiling and a rotation. */
export function parsePenroseDesc(
  desc: string,
): { xoff: number; yoff: number; aoff: number } | null {
  const m = /^G(-?\d+),(-?\d+),(-?\d+)$/.exec(desc);
  if (!m) return null;
  return { xoff: parseInt(m[1], 10), yoff: parseInt(m[2], 10), aoff: parseInt(m[3], 10) };
}

function penroseInnerRadius(which: number, w: number, h: number): number {
  const { radius } = penroseCalculateSize(which, PENROSE_TILE, w, h);
  return Math.trunc(radius - Math.sqrt(w * w + h * h));
}

/** Check a Penrose grid description without building the grid. */
export function validatePenroseDesc(
  type: number,
  w: number,
  h: number,
  desc: string,
): string | null {
  const p = parsePenroseDesc(desc);
  if (!p) return tx`Invalid format grid description string.`;
  const which = type === GRID_PENROSE_P2 ? PENROSE_P2 : PENROSE_P3;
  if (Math.hypot(p.xoff, p.yoff) > penroseInnerRadius(which, w, h))
    return tx`Patch offset out of bounds.`;
  if (p.aoff % 36 !== 0 || p.aoff < 0 || p.aoff >= 360) return tx`Angle offset out of bounds.`;
  return null;
}

/**
 * Cut a `w × h` window out of a large Penrose tiling: every tile whose corners all lie
 * inside the window is kept, then stray bits are trimmed and the patch is centred in
 * the window. Returns null when nothing usable is left.
 */
function penroseGrid(type: number, w: number, h: number, desc: string): Grid | null {
  const p = parsePenroseDesc(desc);
  if (!p) return null;
  const which = type === GRID_PENROSE_P2 ? PENROSE_P2 : PENROSE_P3;
  const { startSize, depth } = penroseCalculateSize(which, PENROSE_TILE, w, h);
  const xsz = w * PENROSE_TILE;
  const ysz = h * PENROSE_TILE;
  const xmin = p.xoff - xsz / 2;
  const xmax = p.xoff + xsz / 2;
  const ymin = p.yoff - ysz / 2;
  const ymax = p.yoff + ysz / 2;
  const roundAway = (r: number) => (r > 0 ? Math.floor(r + 0.5) : Math.ceil(r - 0.5));
  const b = new Builder();
  penrose(which, startSize, depth, p.aoff, {
    tile(vs, d) {
      if (d < depth) return;
      const coords: number[] = [];
      for (const v of vs) {
        const x = roundAway(vx(v));
        const y = roundAway(vy(v));
        if (x < xmin || x > xmax || y < ymin || y > ymax) return;
        coords.push(x, y);
      }
      b.face(coords);
    },
  });
  if (b.faces.length === 0) return null;
  trimVigorously(b);
  if (b.faces.length === 0) return null;
  let g: Grid;
  try {
    g = makeConsistent(b, type, PENROSE_TILE);
  } catch {
    return null;
  }
  // Centre the patch in the window it was promised.
  const minX = g.minX - (xmax - xmin - (g.maxX - g.minX)) / 2;
  const minY = g.minY - (ymax - ymin - (g.maxY - g.minY)) / 2;
  return { ...g, minX, maxX: minX + (xmax - xmin), minY, maxY: minY + (ymax - ymin) };
}

/** Pick a random Penrose patch that yields a usable grid. */
export function newPenroseDesc(type: number, w: number, h: number, rng: Random): string {
  const which = type === GRID_PENROSE_P2 ? PENROSE_P2 : PENROSE_P3;
  const inner = penroseInnerRadius(which, w, h);
  for (;;) {
    let xoff: number;
    let yoff: number;
    do {
      xoff = rng.upto(2 * inner) - inner;
      yoff = rng.upto(2 * inner) - inner;
    } while (Math.hypot(xoff, yoff) > inner);
    const aoff = rng.upto(10) * 36;
    const desc = `G${xoff},${yoff},${aoff}`;
    if (getGrid(type, w, h, desc)) return desc;
  }
}

// ------------------------------------------------------------------ public API

/** The grid description a freshly generated puzzle of this type carries, if any. */
export function defaultGridDesc(type: number): string | null {
  return type === GRID_TRIANGULAR ? '0' : null;
}

/** Validate the optional grid description for a grid type. */
export function validateGridDesc(type: number, w: number, h: number, desc: string | null) {
  if (type === GRID_PENROSE_P2 || type === GRID_PENROSE_P3) {
    if (desc === null) return tx`Missing grid description string.`;
    const err = validatePenroseDesc(type, w, h, desc);
    if (err) return err;
    if (!getGrid(type, w, h, desc))
      return tx`Patch coordinates do not identify a usable grid fragment`;
    return null;
  }
  if (type === GRID_TRIANGULAR) {
    return desc === null || desc === '0' ? null : tx`Unrecognised grid description.`;
  }
  return desc === null ? null : tx`Grid description strings not used with this grid type`;
}

function buildGrid(type: number, w: number, h: number, desc: string | null): Grid | null {
  switch (type) {
    case GRID_SQUARE:
      return makeConsistent(squares(w, h), type, 20);
    case GRID_TRIANGULAR:
      return makeConsistent(triangular(w, h, desc === null), type, 18);
    case GRID_HONEYCOMB:
      return makeConsistent(honeycomb(w, h), type, 45);
    case GRID_SNUBSQUARE:
      return makeConsistent(snubSquare(w, h), type, 18);
    case GRID_CAIRO:
      return makeConsistent(cairo(w, h), type, 40);
    case GRID_GREATHEXAGONAL:
      return makeConsistent(greatHexagonal(w, h), type, 18);
    case GRID_OCTAGONAL:
      return makeConsistent(octagonal(w, h), type, 40);
    case GRID_KITES:
      return makeConsistent(kites(w, h), type, 40);
    case GRID_FLORET:
      return makeConsistent(floret(w, h), type, 150);
    case GRID_DODECAGONAL:
      return makeConsistent(dodecagonal(w, h), type, 26);
    case GRID_GREATDODECAGONAL:
      return makeConsistent(greatDodecagonal(w, h), type, 26);
    case GRID_PENROSE_P2:
    case GRID_PENROSE_P3:
      return desc === null ? null : penroseGrid(type, w, h, desc);
    default:
      return null;
  }
}

const cache = new Map<string, Grid | null>();

/** Build (or fetch from the cache) the grid for these parameters. */
export function getGrid(type: number, w: number, h: number, desc: string | null): Grid | null {
  const key = `${type}:${w}x${h}:${desc ?? ''}`;
  let g = cache.get(key);
  if (g === undefined) {
    g = buildGrid(type, w, h, desc);
    if (cache.size > 64) cache.delete(cache.keys().next().value!);
    cache.set(key, g);
  }
  return g;
}

/** Width and height of a grid type in grid units, plus its units per tile. */
export function gridExtent(
  type: number,
  w: number,
  h: number,
): { w: number; h: number; tile: number } {
  if (type === GRID_PENROSE_P2 || type === GRID_PENROSE_P3) {
    return { w: w * PENROSE_TILE, h: h * PENROSE_TILE, tile: PENROSE_TILE };
  }
  const g = getGrid(type, w, h, defaultGridDesc(type));
  if (!g) return { w, h, tile: 1 };
  return { w: g.maxX - g.minX, h: g.maxY - g.minY, tile: g.tile };
}

/**
 * The edge nearest to a point, or -1 if none is reasonably close: the point must lie
 * within the edge's "span" (acute angles at both ends) and within half the edge's length
 * of it.
 */
export function nearestEdge(g: Grid, x: number, y: number): number {
  let best = -1;
  let bestDist = Infinity;
  for (let e = 0; e < g.ne; e++) {
    const x1 = g.dotX[g.edgeDot1[e]];
    const y1 = g.dotY[g.edgeDot1[e]];
    const x2 = g.dotX[g.edgeDot2[e]];
    const y2 = g.dotY[g.edgeDot2[e]];
    const e2 = (x1 - x2) ** 2 + (y1 - y2) ** 2;
    const a2 = (x1 - x) ** 2 + (y1 - y) ** 2;
    const b2 = (x2 - x) ** 2 + (y2 - y) ** 2;
    if (a2 >= e2 + b2 || b2 >= e2 + a2) continue;
    const det = Math.abs(x1 * y2 - x2 * y1 + x2 * y - x * y2 + x * y1 - x1 * y);
    const dist = det / Math.sqrt(e2);
    if (4 * dist * dist > e2) continue;
    if (dist < bestDist) {
      bestDist = dist;
      best = e;
    }
  }
  return best;
}

/** Midpoint of an edge. */
export function edgeMid(g: Grid, e: number): { x: number; y: number } {
  return {
    x: (g.dotX[g.edgeDot1[e]] + g.dotX[g.edgeDot2[e]]) / 2,
    y: (g.dotY[g.edgeDot1[e]] + g.dotY[g.edgeDot2[e]]) / 2,
  };
}

/** The edge nearest the middle of the grid, for the keyboard cursor's first appearance. */
export function centralEdge(g: Grid): number {
  const cx = (g.minX + g.maxX) / 2;
  const cy = (g.minY + g.maxY) / 2;
  let best = 0;
  let bestD = Infinity;
  for (let e = 0; e < g.ne; e++) {
    const m = edgeMid(g, e);
    const d = Math.hypot(m.x - cx, m.y - cy);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  return best;
}

/**
 * Move the keyboard cursor from edge `from` in direction (dx, dy): among the edges that
 * share an end with it and lie that way, pick the nearest one, with distance stretched
 * by how far off the direction it lies. Returns `from` when nothing lies that way.
 *
 * Distance has to count, not just the angle: on the triangular grid the horizontal edges
 * are never the most nearly straight step from anywhere (a diagonal two rows away always
 * lines up better), so a purely angular choice could never put the cursor on them.
 */
export function stepEdge(g: Grid, from: number, dx: number, dy: number): number {
  const m0 = edgeMid(g, from);
  let best = from;
  let bestScore = Infinity;
  for (const d of [g.edgeDot1[from], g.edgeDot2[from]]) {
    for (const e of g.dotEdges[d]) {
      if (e === from) continue;
      const m = edgeMid(g, e);
      const vx = m.x - m0.x;
      const vy = m.y - m0.y;
      const len = Math.hypot(vx, vy);
      const forward = (vx * dx + vy * dy) / len;
      if (forward <= 1e-9) continue;
      const score = len * (1 + 3 * (1 - forward));
      if (score < bestScore) {
        bestScore = score;
        best = e;
      }
    }
  }
  return best;
}
