import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { canvasSize, directionTo, gridFor, layout } from './geometry';
import type { Dir } from './geometry';
import type { CubeState, CubeUI } from './index';

/** Bounding box of one grid cell, in canvas pixels. */
function cellBox(state: CubeState, tileSize: number, cell: number): TutorialRect | null {
  if (cell < 0) return null;
  const { grid, unit, ox, oy } = layout(state, tileSize);
  const pts = grid.cells[cell].pts;
  let l = Infinity;
  let r = -Infinity;
  let u = Infinity;
  let d = -Infinity;
  for (let i = 0; i < pts.length; i += 2) {
    l = Math.min(l, pts[i]);
    r = Math.max(r, pts[i]);
    u = Math.min(u, pts[i + 1]);
    d = Math.max(d, pts[i + 1]);
  }
  return { x: ox + l * unit, y: oy + u * unit, w: (r - l) * unit, h: (d - u) * unit };
}

/** Centre of one grid cell, in canvas pixels. */
function cellPoint(state: CubeState, tileSize: number, cell: number) {
  if (cell < 0) return null;
  const { grid, unit, ox, oy } = layout(state, tileSize);
  const c = grid.cells[cell];
  return { x: ox + c.cx * unit, y: oy + c.cy * unit };
}

/** The whole playing area: the grid plus the margin the solid leans into. */
function boardBox(state: CubeState, tileSize: number): TutorialRect {
  const { w, h } = canvasSize(state, tileSize);
  return { x: 0, y: 0, w, h };
}

/** Cell the solid would roll onto in a direction, or -1. */
function neighbour(state: CubeState, dir: Dir): number {
  return gridFor(state).cells[state.cell].nb[dir];
}

/** Direction of the roll that produced the current position, if any. */
function lastRoll(state: CubeState): Dir | null {
  if (state.prev < 0) return null;
  return directionTo(gridFor(state), state.prev, state.cell);
}

function blueFaces(state: CubeState): number {
  return state.faces.reduce((a, b) => a + b, 0);
}

/**
 * A 5x2 board whose six blue cells can be collected in six rolls: down, right, right, up,
 * right, right. The walkthrough plays the first three and leaves the rest to the player.
 */
export const tutorial: Tutorial<CubeState, CubeUI> = {
  steps: [
    {
      gameId: 'c5x2:3F0,0',
      text: 'The cube has six faces and six cells are painted blue. Roll it around until every face has collected one: each time it lands, the face underneath and the cell trade colours.',
      highlight: ({ state, tileSize }) => boardBox(state, tileSize),
    },
    {
      text: 'A click tips the cube over the edge towards the cell you pick. **Click the blue cell just below the cube** to take its colour onto the face that lands.',
      highlight: ({ state, tileSize }) => cellBox(state, tileSize, neighbour(state, 'D')),
      pointer: ({ state, tileSize }) => cellPoint(state, tileSize, neighbour(state, 'D')),
      waitFor: ({ state }) => lastRoll(state) === 'D',
    },
    {
      text: 'The cell it left is plain now — the colours really do swap. **Click the blue cell to the right** to turn a second face blue.',
      highlight: ({ state, tileSize }) => cellBox(state, tileSize, neighbour(state, 'R')),
      pointer: ({ state, tileSize }) => cellPoint(state, tileSize, neighbour(state, 'R')),
      waitFor: ({ state }) => lastRoll(state) === 'R',
    },
    {
      text: 'The **arrow keys** roll the cube as well. Press **→** once to pick up the third blue square.',
      textTouch:
        'Every neighbouring cell is one tap away. **Tap the next blue cell to the right** to pick up the third blue square.',
      highlight: ({ state, tileSize }) => cellBox(state, tileSize, neighbour(state, 'R')),
      pointer: ({ state, tileSize }) => cellPoint(state, tileSize, neighbour(state, 'R')),
      waitFor: ({ state }) => blueFaces(state) >= 3,
    },
    {
      text: 'Three faces blue, three to go — this board can be finished in six rolls in all, and the status line counts them. **Undo** takes one back when you overshoot.',
      target: '[data-cmd="undo"]',
    },
  ],
};
