export interface NetslideParams {
  w: number;
  h: number;
  /** Connections (and barriers) may cross from one edge of the grid to the opposite one. */
  wrapping: boolean;
  /** Fraction (0..1) of the unconnected tile edges that get an immovable barrier. */
  barrierProb: number;
  /** Scramble with exactly this many slides; 0 picks a size-dependent default. */
  moveTarget: number;
}

/** Connection bits. The description format encodes each tile as one hex digit of these. */
export const R = 1;
export const U = 2;
export const L = 4;
export const D = 8;
const DIRS: readonly number[] = [R, U, L, D];

/** One row or column slide: `dir` is +1 towards the right/bottom, -1 the other way. */
export interface LineMove {
  row: boolean;
  index: number;
  dir: 1 | -1;
}

export interface NetslideState {
  w: number;
  h: number;
  /** The centre tile: the power source, and the one cell that never moves. */
  cx: number;
  cy: number;
  wrapping: boolean;
  /** Connection mask per cell, row-major. */
  tiles: number[];
  /** Barrier mask per cell: a set bit means a wall on that side of the cell. */
  barriers: number[];
  moves: number;
  /** Move count at which the network first became complete, or 0. */
  completed: number;
  moveTarget: number;
  usedSolve: boolean;
  /** The slide that produced this state (drives the animation). */
  last: LineMove | null;
}

export interface NetslideUI {
  /** Cursor cell in grid coordinates; exactly one of cx/cy is -1 or w/h (the arrow strip). */
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

/** The parts of a state the network helpers need. */
interface Net {
  w: number;
  h: number;
  cx: number;
  cy: number;
  tiles: number[];
  barriers: number[];
}

const ANIM = 0.13;
const FLASH_FRAME = 0.07;
const MAX_DIM = 12;
const MAX_SHUFFLE = 10000;
const HEX = '0123456789abcdef';

// ------------------------------------------------------------------ directions

/**
 * The barrier probability as typed. A decimal comma is read as a point — a Dutch or German
 * phone's decimal keypad offers only the comma — and anything that is not a number gives
 * NaN, so `validateParams` rejects it instead of `parseFloat` quietly reading `0,5` as 0.
 */
function parseProbability(s: string): number {
  return s === '' ? 0 : Number(s.replace(',', '.'));
}

function dx(d: number): number {
  return d === R ? 1 : d === L ? -1 : 0;
}
function dy(d: number): number {
  return d === D ? 1 : d === U ? -1 : 0;
}
/** The bit for the opposite side: R↔L, U↔D. */
export function opposite(d: number): number {
  return ((d << 2) | (d >> 2)) & 15;
}
export function bitCount(m: number): number {
  return (m & 1) + ((m >> 1) & 1) + ((m >> 2) & 1) + ((m >> 3) & 1);
}
/** Index of the cell one step from cell `i` in direction `d`, always wrapping. */
function neighbour(w: number, h: number, i: number, d: number): number {
  const x = i % w;
  const y = (i - x) / w;
  return ((y + dy(d) + h) % h) * w + ((x + dx(d) + w) % w);
}

// ------------------------------------------------------------------- network

/**
 * Which cells receive power from the centre: a flood fill along matching connections
 * that are not blocked by a barrier. Cells in `skipRow`/`skipCol` are treated as absent,
 * which keeps the power from appearing to jump across a line that is still sliding.
 */
export function computeActive(net: Net, skipRow = -1, skipCol = -1): Uint8Array {
  const { w, h, tiles, barriers } = net;
  const active = new Uint8Array(w * h);
  const start = net.cy * w + net.cx;
  active[start] = 1;
  const queue = [start];
  for (let qi = 0; qi < queue.length; qi++) {
    const i = queue[qi];
    for (const d of DIRS) {
      if (!(tiles[i] & d) || barriers[i] & d) continue;
      const j = neighbour(w, h, i, d);
      if (j % w === skipCol || (j - (j % w)) / w === skipRow) continue;
      if (active[j] || !(tiles[j] & opposite(d))) continue;
      active[j] = 1;
      queue.push(j);
    }
  }
  return active;
}

/** True when every cell is powered. */
export function isComplete(net: Net): boolean {
  const active = computeActive(net);
  for (let i = 0; i < active.length; i++) if (!active[i]) return false;
  return true;
}

/** Slide one row or column of `tiles` by a single step, returning a new array. */
export function applyLineMove(tiles: number[], w: number, h: number, mv: LineMove): number[] {
  const out = tiles.slice();
  if (mv.row) {
    const base = mv.index * w;
    for (let x = 0; x < w; x++) out[base + x] = tiles[base + ((x - mv.dir + w) % w)];
  } else {
    for (let y = 0; y < h; y++)
      out[y * w + mv.index] = tiles[((y - mv.dir + h) % h) * w + mv.index];
  }
  return out;
}

function sameTiles(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

function sameMultiset(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  const counts = new Int32Array(16);
  for (const t of a) counts[t]++;
  for (const t of b) counts[t]--;
  return counts.every((c) => c === 0);
}

function encodeTiles(tiles: number[]): string {
  return tiles.map((t) => HEX[t & 15]).join('');
}

// --------------------------------------------------------------- description

interface ParsedDesc {
  tiles: number[];
  barriers: number[];
}

/**
 * Description format: one hex digit per cell (row-major) giving its connection bits,
 * each optionally followed by `v` (a barrier on its right edge) and/or `h` (a barrier
 * below it). Barriers are recorded on both cells they separate.
 */
function parseDesc(p: NetslideParams, desc: string): ParsedDesc | string {
  const { w, h } = p;
  const n = w * h;
  const tiles: number[] = [];
  const barriers = new Array<number>(n).fill(0);
  let pos = 0;
  for (let i = 0; i < n; i++) {
    if (pos >= desc.length) return tx`Description is too short`;
    const v = HEX.indexOf(desc[pos].toLowerCase());
    if (v < 0) return tx`Unexpected character '${desc[pos]}' in description`;
    tiles.push(v);
    pos++;
    while (desc[pos] === 'h' || desc[pos] === 'v') {
      const d = desc[pos] === 'v' ? R : D;
      barriers[i] |= d;
      barriers[neighbour(w, h, i, d)] |= opposite(d);
      pos++;
    }
  }
  if (pos < desc.length) return tx`Description is too long`;
  if (!p.wrapping) {
    // The outside of a non-wrapping grid is one long wall.
    for (let x = 0; x < w; x++) {
      barriers[x] |= U;
      barriers[(h - 1) * w + x] |= D;
    }
    for (let y = 0; y < h; y++) {
      barriers[y * w] |= L;
      barriers[y * w + w - 1] |= R;
    }
  }
  return { tiles, barriers };
}

function encodeDesc(p: NetslideParams, tiles: number[], barriers: number[]): string {
  const { w, h } = p;
  let out = '';
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      out += HEX[tiles[i]];
      if (barriers[i] & R && (p.wrapping || x < w - 1)) out += 'v';
      if (barriers[i] & D && (p.wrapping || y < h - 1)) out += 'h';
    }
  }
  return out;
}

// ---------------------------------------------------------------- generation

/**
 * Grow a random spanning tree out from the centre. The frontier holds (cell, direction)
 * pairs that would extend the tree into an unused cell; one is picked at random each
 * step. A cell is never given a fourth arm, since a full cross has only one orientation
 * and would give the game away.
 */
function growTree(p: NetslideParams, rng: Random): number[] {
  const { w, h, wrapping } = p;
  const n = w * h;
  const tiles = new Array<number>(n).fill(0);
  const canStep = (i: number, d: number): boolean => {
    if (wrapping) return true;
    const x = i % w;
    const y = (i - x) / w;
    return x + dx(d) >= 0 && x + dx(d) < w && y + dy(d) >= 0 && y + dy(d) < h;
  };
  const frontier: number[] = []; // cell * 16 + direction
  const drop = (key: number) => {
    const at = frontier.indexOf(key);
    if (at < 0) return;
    frontier[at] = frontier[frontier.length - 1];
    frontier.pop();
  };
  const centre = (h >> 1) * w + (w >> 1);
  for (const d of DIRS) if (canStep(centre, d)) frontier.push(centre * 16 + d);

  while (frontier.length > 0) {
    const at = rng.upto(frontier.length);
    const key = frontier[at];
    frontier[at] = frontier[frontier.length - 1];
    frontier.pop();
    const from = key >> 4;
    const d = key & 15;
    const to = neighbour(w, h, from, d);
    tiles[from] |= d;
    tiles[to] |= opposite(d);
    // Three arms is the limit: retire the fourth direction of a T-piece.
    if (bitCount(tiles[from]) === 3) drop(from * 16 + (15 ^ tiles[from]));
    // Nothing else may grow into the cell we just reached.
    for (const e of DIRS) drop(neighbour(w, h, to, e) * 16 + opposite(e));
    // The new cell can grow into any still-empty neighbour.
    for (const e of DIRS) {
      if (!canStep(to, e)) continue;
      if (tiles[neighbour(w, h, to, e)] === 0) frontier.push(to * 16 + e);
    }
  }
  return tiles;
}

/**
 * Scramble with `count` random slides of non-centre lines. A slide never directly undoes
 * the previous one, and a line is never pushed so far that going the other way would
 * have been quicker.
 */
function scramble(
  solved: number[],
  w: number,
  h: number,
  count: number,
  rng: Random,
): { tiles: number[]; last: LineMove | null } {
  const cx = w >> 1;
  const cy = h >> 1;
  let tiles = solved;
  let prev: LineMove | null = null;
  let repeats = 0;
  for (let done = 0; done < count;) {
    const row = rng.upto(2) === 1;
    let index = rng.upto((row ? h : w) - 1);
    if (index >= (row ? cy : cx)) index++;
    const dir: 1 | -1 = rng.upto(2) === 0 ? -1 : 1;
    const len = row ? w : h;
    const sameLine = prev !== null && prev.row === row && prev.index === index;
    if (sameLine) {
      if (prev!.dir !== dir) continue;
      if ((repeats + 1) * 2 > len) continue;
    }
    repeats = sameLine ? repeats + 1 : 1;
    prev = { row, index, dir };
    tiles = applyLineMove(tiles, w, h, prev);
    done++;
  }
  return { tiles, last: prev };
}

// ------------------------------------------------------------------- solving

/**
 * Find an arrangement of the current tiles in which every connection meets a matching
 * one, no barrier is crossed and everything is powered from the (fixed) centre. Cells
 * are filled row by row; each placed cell fixes the facing bits of its later neighbours,
 * and a union-find rejects any placement that would close a loop. Returns null when
 * there is no such arrangement or the search budget runs out. The budget is enough for
 * every preset — a shared 5×5 Hard, which arrives without the generator's answer, used to
 * run out about one time in six at a fifth of this — and still gives up within a second
 * or so on a large custom grid.
 */
export function findSolvedArrangement(net: Net, budget = 10_000_000): number[] | null {
  const { w, h, barriers } = net;
  const n = w * h;
  const centre = net.cy * w + net.cx;
  const counts = new Int32Array(16);
  for (const t of net.tiles) counts[t]++;
  const grid = new Int32Array(n).fill(-1);
  grid[centre] = net.tiles[centre];
  counts[grid[centre]]--;

  const parent = new Int32Array(n);
  for (let i = 0; i < n; i++) parent[i] = i;
  const find = (v: number): number => {
    while (parent[v] !== v) v = parent[v];
    return v;
  };
  const trail: number[] = [];
  let unions = 0;
  let nodes = 0;
  let aborted = false;

  const place = (i: number): boolean => {
    while (i < n && grid[i] >= 0) i++;
    if (i === n) return unions === n - 1;
    if (++nodes > budget) {
      aborted = true;
      return false;
    }
    let need = 0;
    let forbid = barriers[i];
    for (const d of DIRS) {
      const j = neighbour(w, h, i, d);
      if (grid[j] < 0) continue;
      if (grid[j] & opposite(d)) need |= d;
      else forbid |= d;
    }
    if (need & forbid) return false;
    for (let m = 0; m < 16; m++) {
      if (counts[m] === 0 || (m & need) !== need || m & forbid) continue;
      const mark = trail.length;
      let ok = true;
      for (const d of DIRS) {
        if (!(m & d)) continue;
        const j = neighbour(w, h, i, d);
        if (grid[j] < 0) continue;
        const a = find(i);
        const b = find(j);
        if (a === b) {
          ok = false;
          break;
        }
        parent[a] = b;
        trail.push(a);
        unions++;
      }
      if (ok) {
        grid[i] = m;
        counts[m]--;
        if (place(i + 1)) return true;
        grid[i] = -1;
        counts[m]++;
      }
      while (trail.length > mark) {
        const r = trail.pop()!;
        parent[r] = r;
        unions--;
      }
      if (aborted) return false;
    }
    return false;
  };
  return place(0) ? Array.from(grid) : null;
}

// ---------------------------------------------------------------------- moves

function parseMove(move: string): LineMove | null {
  const m = /^([RC])(\d+),(-?1)$/.exec(move);
  if (!m) return null;
  return { row: m[1] === 'R', index: parseInt(m[2], 10), dir: m[3] === '1' ? 1 : -1 };
}

function encodeMove(mv: LineMove): string {
  return `${mv.row ? 'R' : 'C'}${mv.index},${mv.dir}`;
}

/** The single slide that turns `from` into `to` in the direction of play, if any. */
function animatedMove(from: NetslideState, to: NetslideState, dir: number): LineMove | null {
  let mv: LineMove | null;
  if (dir < 0) mv = from.last ? { ...from.last, dir: from.last.dir === 1 ? -1 : 1 } : null;
  else mv = to.last;
  if (!mv) return null;
  return sameTiles(applyLineMove(from.tiles, from.w, from.h, mv), to.tiles) ? mv : null;
}

// -------------------------------------------------------------------- geometry

/** The arrow strip is one tile wide all the way round. */
function border(ds: DrawState): number {
  return ds.tileSize;
}

/** The slide a click on grid cell (cx, cy) asks for, or null if that is not an arrow. */
function arrowAt(s: NetslideState, cx: number, cy: number): LineMove | null {
  const { w, h } = s;
  const inRow = cy >= 0 && cy < h && cy !== s.cy;
  const inCol = cx >= 0 && cx < w && cx !== s.cx;
  if (cx === -1 && inRow) return { row: true, index: cy, dir: -1 };
  if (cx === w && inRow) return { row: true, index: cy, dir: 1 };
  if (cy === -1 && inCol) return { row: false, index: cx, dir: -1 };
  if (cy === h && inCol) return { row: false, index: cx, dir: 1 };
  return null;
}

/**
 * The border arrows form a ring numbered clockwise from the top-left: top row, right
 * column, bottom row (right to left), left column (bottom to top).
 */
function ringPos(w: number, h: number, cx: number, cy: number): number {
  if (cy === -1) return cx;
  if (cx === w) return w + cy;
  if (cy === h) return w + h + (w - 1 - cx);
  return 2 * w + h + (h - 1 - cy);
}

function ringCell(w: number, h: number, pos: number): { cx: number; cy: number } {
  const len = 2 * (w + h);
  pos = ((pos % len) + len) % len;
  if (pos < w) return { cx: pos, cy: -1 };
  pos -= w;
  if (pos < h) return { cx: w, cy: pos };
  pos -= h;
  if (pos < w) return { cx: w - 1 - pos, cy: h };
  pos -= w;
  return { cx: -1, cy: h - 1 - pos };
}

/**
 * How far along the ring a cursor key moves (+1 clockwise): keys along an edge walk it,
 * and a key pointing into the grid from the end of an edge turns the corner.
 */
function ringStep(w: number, h: number, cx: number, cy: number, button: number): number {
  const top = cy === -1;
  const bottom = cy === h;
  const left = cx === -1;
  const right = cx === w;
  if (top && button === CURSOR_RIGHT) return 1;
  if (top && button === CURSOR_LEFT) return -1;
  if (right && button === CURSOR_DOWN) return 1;
  if (right && button === CURSOR_UP) return -1;
  if (bottom && button === CURSOR_LEFT) return 1;
  if (bottom && button === CURSOR_RIGHT) return -1;
  if (left && button === CURSOR_UP) return 1;
  if (left && button === CURSOR_DOWN) return -1;
  if (top && button === CURSOR_DOWN) return cx === 0 ? -1 : cx === w - 1 ? 1 : 0;
  if (bottom && button === CURSOR_UP) return cx === 0 ? 1 : cx === w - 1 ? -1 : 0;
  if (left && button === CURSOR_RIGHT) return cy === 0 ? 1 : cy === h - 1 ? -1 : 0;
  if (right && button === CURSOR_LEFT) return cy === 0 ? -1 : cy === h - 1 ? 1 : 0;
  return 0;
}

// ---------------------------------------------------------------------- drawing

/**
 * A chunky sketched arrow. (ex, ey) is the midpoint of the grid edge it sits against and
 * (ax, ay) the unit direction pointing away from the grid.
 */
function drawArrow(
  dr: Drawing,
  ex: number,
  ey: number,
  ax: number,
  ay: number,
  t: number,
  highlighted: boolean,
): void {
  const bx = -ay;
  const by = ax;
  const shape: [number, number][] = [
    [0.78, 0],
    [0.5, 0.27],
    [0.5, 0.12],
    [0.22, 0.12],
    [0.22, -0.12],
    [0.5, -0.12],
    [0.5, -0.27],
  ];
  const pts: number[] = [];
  for (const [a, b] of shape) pts.push(ex + (a * ax + b * bx) * t, ey + (a * ay + b * by) * t);
  dr.polygon(pts, highlighted ? 'accent' : 'shade', highlighted ? 'ink' : 'pencil', {
    width: 1.5,
  });
}

/** The wiring of one tile: arms from the centre to the edges, and a dot on a loose end. */
function drawWires(
  dr: Drawing,
  px: number,
  py: number,
  t: number,
  mask: number,
  powered: boolean,
  seed: number,
): void {
  const colour = powered ? 'blue' : 'pencil';
  const width = Math.max(2.4, t * 0.09);
  const mx = px + t / 2;
  const my = py + t / 2;
  const opts = { seed };
  // A straight run is one stroke, so the wobble carries across the tile.
  if (mask & L && mask & R) dr.line(px, my, px + t, my, colour, width, opts);
  else if (mask & L) dr.line(mx, my, px, my, colour, width, opts);
  else if (mask & R) dr.line(mx, my, px + t, my, colour, width, opts);
  if (mask & U && mask & D) dr.line(mx, py, mx, py + t, colour, width, opts);
  else if (mask & U) dr.line(mx, my, mx, py, colour, width, opts);
  else if (mask & D) dr.line(mx, my, mx, py + t, colour, width, opts);
  if (bitCount(mask) === 1) dr.dot(mx, my, t * 0.13, colour, opts);
}

/** Draw the barriers as heavy walls, merging neighbouring segments into single strokes. */
function drawWalls(dr: Drawing, s: NetslideState, bd: number, t: number, width: number): void {
  const { w, h, barriers } = s;
  // In a non-wrapping grid the outer edge is drawn as the frame instead.
  const lo = s.wrapping ? 0 : 1;
  for (let yl = lo; yl <= h - lo; yl++) {
    const wall = (x: number) => (yl === 0 ? barriers[x] & U : barriers[(yl - 1) * w + x] & D);
    let x = 0;
    while (x < w) {
      if (!wall(x)) {
        x++;
        continue;
      }
      const x0 = x;
      while (x < w && wall(x)) x++;
      dr.line(bd + x0 * t, bd + yl * t, bd + x * t, bd + yl * t, 'ink', width);
    }
  }
  for (let xl = lo; xl <= w - lo; xl++) {
    const wall = (y: number) => (xl === 0 ? barriers[y * w] & L : barriers[y * w + xl - 1] & R);
    let y = 0;
    while (y < h) {
      if (!wall(y)) {
        y++;
        continue;
      }
      const y0 = y;
      while (y < h && wall(y)) y++;
      dr.line(bd + xl * t, bd + y0 * t, bd + xl * t, bd + y * t, 'ink', width);
    }
  }
}

function statusText(s: NetslideState, active: number): string {
  let text = s.usedSolve
    ? tr('status.movesSinceSolve', { n: s.moves - s.completed })
    : (s.completed ? tr('status.completedPrefix') : '') +
      tr('status.moves', { n: s.completed || s.moves });
  if (s.moveTarget) text += tr('status.target', { n: s.moveTarget });
  return text + tr('games.netslide.status.active', { n: active, total: s.w * s.h });
}

/** The completion flash ripples outwards from the centre; this is how long that takes. */
function flashDuration(s: NetslideState): number {
  const size = Math.max(s.cx + 1, s.cy + 1, s.w - s.cx, s.h - s.cy);
  return FLASH_FRAME * (size + 4);
}

