import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { BACK, FORWARD } from './board';
import type { SlantState, SlantUI } from './index';

/** Clue circles sit on the grid points, so Slant uses a wider border than most games. */
const border = (t: number) => Math.round(t * 0.45);

/** The diagonal currently in the square at (x, y). */
const at = (state: SlantState, x: number, y: number) => state.soln[y * state.w + x];

/** A box around the clue circle on grid point (px, py). */
function clueRect(px: number, py: number, t: number): TutorialRect {
  const b = border(t);
  const r = t * 0.33;
  return { x: b + px * t - r, y: b + py * t - r, w: 2 * r, h: 2 * r };
}

/** The grid plus the clue circles sitting on its border. */
function boardRect(state: SlantState, t: number): TutorialRect {
  const b = border(t);
  const r = t * 0.33;
  return { x: b - r, y: b - r, w: state.w * t + 2 * r, h: state.h * t + 2 * r };
}

/**
 * A 4×4 Easy puzzle with a 0 in the top-left corner, a 4 low down on the left and a 1 on
 * the left edge between them: each of the four squares the walkthrough asks for is forced
 * outright by one clue.
 */
export const tutorial: Tutorial<SlantState, SlantUI> = {
  steps: [
    {
      gameId: '4x4:0a11b2a1a1e4a2d2a',
      text: 'Draw one diagonal through every square. A circled number counts the lines that touch its corner, and the lines must never close a loop.',
      highlight: ({ state, tileSize }) => boardRect(state, tileSize),
    },
    {
      text: 'The **0** in the top-left corner wants nothing touching it, so its one square must lean the other way. **Right-click** that square to draw a `/`.',
      highlight: ({ tileSize }) => [
        clueRect(0, 0, tileSize),
        cellRect(0, 0, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => ({
        ...cellCentre(0, 0, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => at(state, 0, 0) === FORWARD,
    },
    {
      text: 'The **4** needs a line from all four squares around it. **Left-click** the one above and left of it — a left-click draws a `\\`.',
      highlight: ({ tileSize }) => [
        clueRect(1, 3, tileSize),
        cellRect(0, 2, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 2, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 0, 2) === BACK,
    },
    {
      text: 'The square above and right of the **4** has to slant down-left instead. **Right-click** it for a `/`.',
      highlight: ({ tileSize }) => [
        clueRect(1, 3, tileSize),
        cellRect(1, 2, tileSize, border(tileSize)),
      ],
      pointer: ({ tileSize }) => ({
        ...cellCentre(1, 2, tileSize, border(tileSize)),
        button: 'right' as const,
      }),
      waitFor: ({ state }) => at(state, 1, 2) === FORWARD,
    },
    {
      text: 'The **1** on the left edge already has its single line, from the square below it. So the square above must lean away: **left-click** it for a `\\`.',
      highlight: ({ tileSize }) => [
        clueRect(0, 2, tileSize),
        cellRect(0, 1, tileSize, border(tileSize), 1, 2),
      ],
      pointer: ({ tileSize }) => cellCentre(0, 1, tileSize, border(tileSize)),
      waitFor: ({ state }) => at(state, 0, 1) === BACK,
    },
    {
      text: 'Carry on the same way. A number that can no longer work out turns red, and so does any line caught in a closed loop. **Solve**, in the pause menu, fills the rest in.',
      target: '[data-cmd="solve"]',
    },
  ],
};
