import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import { DIFF_EXTREME } from './solver';
import type { TowersParams, TowersState } from './index';

type C = typeof PALETTE;

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;

/** A tower standing on `base`, with a column of windows. */
function tower(c: C, x: number, w: number, top: number, base: number, fill: string, ink = c.ink) {
  let out = shape(`M${x} ${base} V${top} H${x + w} V${base} Z`, fill, ink, 4);
  for (let y = top + 6; y < base - 7; y += 9)
    out += `<rect x="${x + w / 2 - 2.5}" y="${y}" width="5" height="4" fill="${c.paper}"/>`;
  return out;
}

/**
 * Whether no square was changed again after the player had moved on from it. Retyping the
 * square just filled in (a slip of the finger) is still one go.
 */
function neverRevisited<S>(history: readonly S[], cells: (s: S) => ArrayLike<number>): boolean {
  const settled = new Set<number>();
  let current = -1;
  for (let k = 1; k < history.length; k++) {
    const a = cells(history[k - 1]);
    const b = cells(history[k]);
    const changed: number[] = [];
    for (let i = 0; i < b.length; i++) if (a[i] !== b[i]) changed.push(i);
    const only = changed.length === 1 ? changed[0] : -1;
    if (current >= 0 && current !== only && a[current]) settled.add(current);
    for (const i of changed) if (settled.has(i)) return false;
    if (only < 0) for (const i of changed) if (b[i]) settled.add(i);
    current = only;
  }
  return true;
}

export const achievements = defineAchievements<TowersParams, TowersState>([
  {
    id: 'no-pencil',
    name: 'Mental Skyline',
    description: 'Solve a 6×6 Towers without writing a single pencil mark.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      // The skyline, worked out in a thought bubble.
      shape(
        'M26 58 Q14 56 16 44 Q14 30 28 30 Q30 16 46 20 Q56 12 66 22 Q84 20 82 36 Q90 50 76 58 Z',
        c.paper,
        c.ink,
      ) +
      `<circle cx="28" cy="70" r="5" fill="${c.paper}" stroke="${c.ink}" stroke-width="3.5"/>` +
      `<circle cx="20" cy="80" r="3" fill="${c.paper}" stroke="${c.ink}" stroke-width="3"/>` +
      tower(c, 28, 10, 44, 56, c.blue) +
      tower(c, 38, 10, 28, 56, c.blue) +
      tower(c, 48, 10, 38, 56, c.blue) +
      tower(c, 58, 10, 34, 56, c.blue) +
      line('M24 56 H74', c.ink, 4.5),
    test: (ctx) => ctx.params.w >= 6 && ctx.history.every((s) => !s.pencil.some((m) => m !== 0)),
  },
  {
    id: 'clean-build',
    name: 'Built to Last',
    description: 'Solve a 6×6 Expert or Extreme Towers without going back to change a tower.',
    tier: 'gold',
    hue: 'orange',
    art: (c) =>
      // A crane lowering the last block onto a finished tower.
      line('M22 82 V20 M30 82 V26', c.ink, 4) +
      line('M22 34 L30 42 L22 50 L30 58 L22 66 L30 74 L22 82', c.ink, 2.5) +
      line('M16 22 H82', c.ink, 5) +
      line('M22 20 L36 14 L50 22', c.ink, 3) +
      shape('M18 22 H30 V30 H18 Z', c.yellow, c.ink, 3.5) +
      line('M66 22 V36', c.ink, 3) +
      shape('M58 36 H74 V47 H58 Z', c.yellow, c.ink, 4) +
      tower(c, 54, 24, 54, 82, c.blue) +
      line('M16 82 H84', c.ink, 5),
    test: (ctx) =>
      ctx.params.w >= 6 &&
      ctx.params.diff >= DIFF_EXTREME &&
      neverRevisited(ctx.history, (s) => s.grid),
  },
  {
    id: 'tallest-first',
    name: 'Tallest First',
    description: 'Build every one of the tallest towers before any other, then solve the grid.',
    tier: 'bronze',
    hidden: true,
    hue: 'pink',
    art: (c) =>
      tower(c, 40, 20, 18, 80, c.purple) +
      `<g stroke-dasharray="3 6">` +
      shape('M20 80 V56 H36 V80', 'none', c.pencil, 3.5) +
      shape('M64 80 V46 H80 V80', 'none', c.pencil, 3.5) +
      '</g>' +
      line('M16 80 H84', c.ink, 5),
    // Whenever a shorter tower goes up, every tallest one is already standing.
    test: (ctx) => {
      const w = ctx.params.w;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].grid;
        const b = ctx.history[k].grid;
        let tallest = 0;
        let shorter = false;
        for (let i = 0; i < b.length; i++) {
          if (a[i] === w) tallest++;
          if (b[i] !== a[i] && b[i] !== 0 && b[i] !== w) shorter = true;
        }
        if (shorter && tallest < w) return false;
      }
      return true;
    },
  },
]);
