import { tx } from '../../i18n';
/**
 * Undead (Haunted Mirror Maze) board model shared by the game, the solver and the
 * generator.
 *
 * A `Layout` is the fixed part of a puzzle: which squares hold mirrors, how many of each
 * monster there are, the sighting clue at every edge position, and (precomputed) the
 * path a line of sight takes from each edge position through the mirrors. Every square
 * that is not a mirror is a *slot* for a monster; the player's guesses live in a typed
 * array indexed by slot.
 *
 * Monster types are bit flags so a set of candidates is a single byte: a ghost is `1`,
 * a vampire `2`, a zombie `4`. Looking along a path, a vampire is only seen before the
 * first mirror and a ghost only after one; zombies are seen either way.
 */

export const GHOST = 1;
export const VAMPIRE = 2;
export const ZOMBIE = 4;
export const ALL_TYPES = GHOST | VAMPIRE | ZOMBIE;
export const TYPES: readonly number[] = [GHOST, VAMPIRE, ZOMBIE];
export const TYPE_LETTERS: Record<number, string> = { [GHOST]: 'G', [VAMPIRE]: 'V', [ZOMBIE]: 'Z' };
export const TYPE_INDEX: Record<number, number> = { [GHOST]: 0, [VAMPIRE]: 1, [ZOMBIE]: 2 };

/** Types visible directly, i.e. before the line of sight has met a mirror. */
export const SEEN_DIRECT = VAMPIRE | ZOMBIE;
/** Types visible once the line of sight has been reflected. */
export const SEEN_MIRRORED = GHOST | ZOMBIE;

/** Contents of a square in a description: empty slot, a mirror, or a fixed monster. */
export const CELL_EMPTY = 0;
/** A `\` mirror (top-left to bottom-right). */
export const CELL_L = 1;
/** A `/` mirror (bottom-left to top-right). */
export const CELL_R = 2;
export const CELL_G = 3;
export const CELL_V = 4;
export const CELL_Z = 5;
const CELL_TYPE = [0, 0, 0, GHOST, VAMPIRE, ZOMBIE];

/** One line of sight through the maze, between two edge positions. */
export interface Path {
  /** Edge position where the path starts (its clue index). */
  start: number;
  /** Edge position where it leaves the grid again. */
  end: number;
  /** Grid square of every step, mirrors included. A square can occur twice (crossing). */
  cells: number[];
  /** Slot at every step, or -1 at a mirror. */
  slots: number[];
  /** Types visible at every step when looking in from `start` (0 at mirrors). */
  visStart: Uint8Array;
  /** Types visible at every step when looking in from `end`. */
  visEnd: Uint8Array;
  /** Distinct slots on the path, in order of first appearance. */
  monsters: number[];
}

/**
 * Where a line of sight enters for edge position `r`, and the direction it travels.
 * Positions run clockwise from the top-left: along the top (0..w-1), down the right side,
 * along the bottom right-to-left, and up the left side, as in the original.
 */
export function edgeEntry(
  r: number,
  w: number,
  h: number,
): { x: number; y: number; dx: number; dy: number } {
  if (r < w) return { x: r, y: 0, dx: 0, dy: 1 };
  r -= w;
  if (r < h) return { x: w - 1, y: r, dx: -1, dy: 0 };
  r -= h;
  if (r < w) return { x: w - 1 - r, y: h - 1, dx: 0, dy: -1 };
  r -= w;
  return { x: 0, y: h - 1 - r, dx: 1, dy: 0 };
}

/** The edge position a line of sight reaches when it steps off the grid at (x, y). */
function edgeExit(x: number, y: number, w: number, h: number): number {
  if (y < 0) return x;
  if (x >= w) return w + y;
  if (y >= h) return w + h + (w - 1 - x);
  return 2 * w + h + (h - 1 - y);
}

export class Layout {
  readonly w: number;
  readonly h: number;
  readonly n: number;
  /** `CELL_EMPTY`, `CELL_L` or `CELL_R` per square (fixed monsters count as empty here). */
  readonly mirror: Uint8Array;
  /** Slot index of every square, or -1 for a mirror. */
  readonly slot: Int16Array;
  /** Square of every slot. */
  readonly slotCell: number[];
  readonly numSlots: number;
  /** Monster type of every slot fixed by the description, 0 when the player fills it. */
  readonly fixed: Uint8Array;
  /** Total number of ghosts, vampires and zombies. */
  total: number[];
  /** The sighting clue at every edge position (2(w+h) of them). */
  clues: number[];
  readonly paths: Path[];
  /** Path index of every edge position. */
  readonly cluePath: Int16Array;
  /** 1 when the edge position is the start of its path, 0 when it is the end. */
  readonly clueAtStart: Uint8Array;

  constructor(w: number, h: number, cells: Uint8Array, total: number[], clues: number[]) {
    this.w = w;
    this.h = h;
    this.n = w * h;
    this.total = total;
    this.clues = clues;
    this.mirror = new Uint8Array(this.n);
    this.slot = new Int16Array(this.n).fill(-1);
    this.slotCell = [];
    const fixed: number[] = [];
    for (let i = 0; i < this.n; i++) {
      const c = cells[i];
      if (c === CELL_L || c === CELL_R) {
        this.mirror[i] = c;
      } else {
        this.slot[i] = this.slotCell.length;
        this.slotCell.push(i);
        fixed.push(CELL_TYPE[c]);
      }
    }
    this.numSlots = this.slotCell.length;
    this.fixed = Uint8Array.from(fixed);
    const nEdge = 2 * (w + h);
    this.cluePath = new Int16Array(nEdge).fill(-1);
    this.clueAtStart = new Uint8Array(nEdge);
    this.paths = [];
    for (let r = 0; r < nEdge; r++) {
      if (this.cluePath[r] >= 0) continue;
      const p = this.trace(r);
      this.cluePath[p.start] = this.paths.length;
      this.clueAtStart[p.start] = 1;
      this.cluePath[p.end] = this.paths.length;
      this.paths.push(p);
    }
  }

  /** Follow the line of sight entering at edge position `r` until it leaves the grid. */
  private trace(r: number): Path {
    const { w, h } = this;
    let { x, y, dx, dy } = edgeEntry(r, w, h);
    const cells: number[] = [];
    const slots: number[] = [];
    const vis: number[] = [];
    let mirrored = false;
    while (x >= 0 && y >= 0 && x < w && y < h) {
      const i = y * w + x;
      cells.push(i);
      const m = this.mirror[i];
      if (m === CELL_L) {
        slots.push(-1);
        vis.push(0);
        [dx, dy] = [dy, dx];
        mirrored = true;
      } else if (m === CELL_R) {
        slots.push(-1);
        vis.push(0);
        [dx, dy] = [-dy, -dx];
        mirrored = true;
      } else {
        slots.push(this.slot[i]);
        vis.push(mirrored ? SEEN_MIRRORED : SEEN_DIRECT);
      }
      x += dx;
      y += dy;
    }
    const visEnd = new Uint8Array(cells.length);
    mirrored = false;
    for (let k = cells.length - 1; k >= 0; k--) {
      if (slots[k] < 0) mirrored = true;
      else visEnd[k] = mirrored ? SEEN_MIRRORED : SEEN_DIRECT;
    }
    const monsters: number[] = [];
    for (const s of slots) if (s >= 0 && !monsters.includes(s)) monsters.push(s);
    return {
      start: r,
      end: edgeExit(x, y, w, h),
      cells,
      slots,
      visStart: Uint8Array.from(vis),
      visEnd,
      monsters,
    };
  }
}

/**
 * How many monsters are seen looking along `path` from one end, given a complete
 * assignment of types (one bit per slot).
 */
export function countSeen(path: Path, types: Uint8Array, fromStart: boolean): number {
  const vis = fromStart ? path.visStart : path.visEnd;
  let n = 0;
  for (let k = 0; k < path.slots.length; k++) {
    const s = path.slots[k];
    if (s >= 0 && types[s] & vis[k]) n++;
  }
  return n;
}

/**
 * The fewest and most monsters that could be seen from one end of `path` when some
 * slots are still empty (0): an empty slot may or may not turn out to be visible.
 */
export function seenRange(path: Path, types: Uint8Array, fromStart: boolean): [number, number] {
  const vis = fromStart ? path.visStart : path.visEnd;
  let lo = 0;
  let hi = 0;
  for (let k = 0; k < path.slots.length; k++) {
    const s = path.slots[k];
    if (s < 0) continue;
    const t = types[s];
    if (t === 0) hi++;
    else if (t & vis[k]) {
      lo++;
      hi++;
    }
  }
  return [lo, hi];
}

/** The clue every edge position would carry for the complete assignment `types`. */
export function computeClues(L: Layout, types: Uint8Array): number[] {
  const clues = new Array<number>(2 * (L.w + L.h)).fill(0);
  for (const p of L.paths) {
    clues[p.start] = countSeen(p, types, true);
    clues[p.end] = countSeen(p, types, false);
  }
  return clues;
}

export interface BoardCheck {
  /** Every slot is filled, every clue and every total is met. */
  complete: boolean;
  /** Per monster type: more placed than allowed, or the grid is full and the count is off. */
  countBad: boolean[];
  /** Per edge position: 1 when its path is fully filled and matches, -1 when the clue can no longer be met, 0 otherwise. */
  clueState: Int8Array;
}

/** Judge the player's assignment (0 = empty) against the clues and totals. */
export function checkBoard(L: Layout, types: Uint8Array): BoardCheck {
  const count = [0, 0, 0];
  let filled = 0;
  for (let i = 0; i < L.numSlots; i++) {
    const t = types[i];
    if (t) {
      count[TYPE_INDEX[t]]++;
      filled++;
    }
  }
  const full = filled === L.numSlots;
  const countBad = [0, 1, 2].map((k) => count[k] > L.total[k] || (full && count[k] !== L.total[k]));
  const clueState = new Int8Array(2 * (L.w + L.h));
  let complete = full && !countBad.some(Boolean);
  for (const p of L.paths) {
    for (const fromStart of [true, false]) {
      const pos = fromStart ? p.start : p.end;
      const [lo, hi] = seenRange(p, types, fromStart);
      const c = L.clues[pos];
      if (c < lo || c > hi) {
        clueState[pos] = -1;
        complete = false;
      } else if (lo === hi) {
        clueState[pos] = 1;
      } else {
        complete = false;
      }
    }
  }
  return { complete, countBad, clueState };
}

// ------------------------------------------------------------- description format

export interface ParsedDesc {
  total: number[];
  cells: Uint8Array;
  clues: number[];
}

/**
 * Parse `G,V,Z,<grid>,<clue>,...`: three monster totals, the grid as a run-length string
 * (a lower-case letter is a run of 1–26 empty squares, `L`/`R` are mirrors, `G`/`V`/`Z`
 * are fixed monsters), then one clue per edge position clockwise from the top-left.
 */
export function parseDesc(desc: string, w: number, h: number): ParsedDesc | string {
  const parts = desc.split(',');
  if (parts.length < 4) return tx`Faulty game description`;
  const total: number[] = [];
  for (let k = 0; k < 3; k++) {
    if (!/^\d+$/.test(parts[k])) return tx`Invalid character in number list`;
    total.push(parseInt(parts[k], 10));
  }
  const cells = new Uint8Array(w * h);
  let area = 0;
  let monsters = 0;
  for (const ch of parts[3]) {
    if (ch >= 'a' && ch <= 'z') {
      const run = ch.charCodeAt(0) - 96;
      for (let k = 0; k < run && area < cells.length; k++) cells[area + k] = CELL_EMPTY;
      area += run;
      monsters += run;
    } else if (ch === 'L' || ch === 'R' || ch === 'G' || ch === 'V' || ch === 'Z') {
      if (area < cells.length)
        cells[area] = { L: CELL_L, R: CELL_R, G: CELL_G, V: CELL_V, Z: CELL_Z }[ch]!;
      area++;
      if (ch !== 'L' && ch !== 'R') monsters++;
    } else {
      return tx`Invalid character in grid specification`;
    }
  }
  if (area < w * h) return tx`Not enough data to fill grid`;
  if (area > w * h) return tx`Too much data to fill grid`;
  if (monsters !== total[0] + total[1] + total[2])
    return tx`Monster numbers do not match grid spaces`;
  const nEdge = 2 * (w + h);
  const clueParts = parts.slice(4);
  if (clueParts.length < nEdge) return tx`Not enough numbers given after grid specification`;
  if (clueParts.length > nEdge) return tx`Unexpected additional data at end of game description`;
  const clues: number[] = [];
  for (const c of clueParts) {
    if (!/^\d+$/.test(c)) return tx`Invalid character in number list`;
    clues.push(parseInt(c, 10));
  }
  return { total, cells, clues };
}

export function encodeDesc(cells: Uint8Array, total: number[], clues: number[]): string {
  let grid = '';
  let run = 0;
  const flush = () => {
    if (run) grid += String.fromCharCode(96 + run);
    run = 0;
  };
  for (const c of cells) {
    if (c === CELL_L || c === CELL_R) {
      flush();
      grid += c === CELL_L ? 'L' : 'R';
    } else if (c === CELL_EMPTY) {
      if (run === 26) flush();
      run++;
    } else {
      flush();
      grid += TYPE_LETTERS[CELL_TYPE[c]];
    }
  }
  flush();
  return `${total.join(',')},${grid},${clues.join(',')}`;
}

/** Solver hint stored with a generated puzzle: one letter per slot. */
export function encodeSolution(types: Uint8Array): string {
  let s = '';
  for (const t of types) s += TYPE_LETTERS[t] ?? '.';
  return s;
}

export function decodeSolution(aux: string, numSlots: number): Uint8Array | null {
  if (aux.length !== numSlots) return null;
  const types = new Uint8Array(numSlots);
  for (let i = 0; i < numSlots; i++) {
    const t = { G: GHOST, V: VAMPIRE, Z: ZOMBIE }[aux[i]];
    if (!t) return null;
    types[i] = t;
  }
  return types;
}
