/**
 * Deductive Slant solver with two tiers of reasoning.
 *
 *  - **Easy** works one square at a time. A clue point whose remaining lines are all
 *    accounted for (or which needs a line from every undecided square around it) is
 *    filled in, and a square is forced whenever one of its diagonals would close a
 *    loop, which is tracked with a disjoint-set forest over the grid points.
 *  - **Hard** adds reasoning about *relationships* between squares. Two undecided
 *    squares may be known to slant the same way without knowing which way: a clue point
 *    needing exactly one more line from two adjacent squares says so, and so does a pair
 *    of squares for which both "v" shapes have been ruled out (1 clues reject any v
 *    pointing at them, 3 clues any v pointing away, and 2 clues copy a rejected v from
 *    one side to the other). Such equivalent pairs count as a single line around a clue
 *    point, and once one square of a class is filled the rest follow. Hard also avoids
 *    dead ends: joining two point groups that neither touch the border nor have more
 *    than one possible way out would wall them off and force a loop later.
 *
 * `solve` returns 0 when the clues are contradictory, 1 when the grid was completed and
 * 2 when it could not be completed with the allowed deductions. Neither tier guesses.
 */
import { DSF } from '../../framework/dsf';
import { BACK, EMPTY, FORWARD, NO_CLUE, pointNeighbours } from './board';

export const DIFF_EASY = 0;
export const DIFF_HARD = 1;
export const DIFFICULTY_NAMES = ['Easy', 'Hard'];
/** Letters used in parameter strings, indexed by difficulty. */
export const DIFFICULTY_CHARS = 'eh';

export const SOLVE_IMPOSSIBLE = 0;
export const SOLVE_SOLVED = 1;
export const SOLVE_STUCK = 2;

// Bits in `vbitmap`: which v-shapes a square might still form with its neighbours.
/** This square `\` and the one to its right `/`: a v pointing at the point below. */
const V_DOWN = 0x1;
/** This square `/` and the one to its right `\`: a ^ pointing at the point above. */
const V_UP = 0x2;
/** This square `\` and the one below `/`: a > pointing at the point to the right. */
const V_RIGHT = 0x4;
/** This square `/` and the one below `\`: a < pointing at the point to the left. */
const V_LEFT = 0x8;

/**
 * Working state of one solve. Reusable across runs of the same grid size, which the
 * generator relies on.
 */
export class Scratch {
  readonly W: number;
  readonly H: number;
  /** Connected groups of grid points. */
  connected!: DSF;
  /** Possible simultaneous ways out of each point group (indexed by group root). */
  readonly exits: Int32Array;
  /** Whether each point group (by root) contains a border point. */
  readonly border: Uint8Array;
  /** Squares known to slant the same way. */
  equiv!: DSF;
  /** The known slash of each equivalence class (by root), or EMPTY. */
  readonly slashval: Int8Array;
  readonly vbitmap: Uint8Array;
  /** Squares around each point, in order (see `pointNeighbours`), 4 slots per point. */
  readonly nbPos: Int32Array;
  readonly nbSlash: Int8Array;
  readonly nbCount: Uint8Array;
  clues!: Int8Array;
  soln!: Int8Array;
  difficulty = DIFF_EASY;
  /** Set when a forced diagonal closed a loop: the clues are inconsistent. */
  dead = false;

  constructor(
    readonly w: number,
    readonly h: number,
  ) {
    this.W = w + 1;
    this.H = h + 1;
    const np = this.W * this.H;
    this.exits = new Int32Array(np);
    this.border = new Uint8Array(np);
    this.slashval = new Int8Array(w * h);
    this.vbitmap = new Uint8Array(w * h);
    this.nbPos = new Int32Array(np * 4);
    this.nbSlash = new Int8Array(np * 4);
    this.nbCount = new Uint8Array(np);
    for (let y = 0; y < this.H; y++) {
      for (let x = 0; x < this.W; x++) {
        const p = y * this.W + x;
        const nbs = pointNeighbours(w, h, x, y);
        this.nbCount[p] = nbs.length;
        nbs.forEach((nb, k) => {
          this.nbPos[p * 4 + k] = nb.pos;
          this.nbSlash[p * 4 + k] = nb.slash;
        });
      }
    }
  }

  reset(clues: Int8Array, soln: Int8Array, difficulty: number): void {
    const { w, h, W, H } = this;
    this.clues = clues;
    this.soln = soln;
    this.difficulty = difficulty;
    this.dead = false;
    soln.fill(EMPTY);
    this.connected = new DSF(W * H);
    this.equiv = new DSF(w * h);
    this.slashval.fill(EMPTY);
    this.vbitmap.fill(V_DOWN | V_UP | V_RIGHT | V_LEFT);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const i = y * W + x;
        this.border[i] = y === 0 || y === H - 1 || x === 0 || x === W - 1 ? 1 : 0;
        this.exits[i] = clues[i] === NO_CLUE ? 4 : clues[i];
      }
    }
  }

  /** Join two point groups, combining their exit counts and border flags. */
  mergePoints(i: number, j: number): void {
    const ri = this.connected.find(i);
    const rj = this.connected.find(j);
    if (ri === rj) {
      // Already joined: this diagonal closes a loop, which no valid grid contains.
      this.dead = true;
      return;
    }
    // One exit of each group has just been used up.
    const exits = this.exits[ri] + this.exits[rj] - 2;
    const border = this.border[ri] || this.border[rj];
    this.connected.merge(ri, rj);
    const r = this.connected.find(ri);
    this.exits[r] = exits;
    this.border[r] = border;
  }

  /** A way out of point `i` was just blocked; unclued points lose a potential exit. */
  decrExits(i: number): void {
    if (this.clues[i] === NO_CLUE) this.exits[this.connected.find(i)]--;
  }

  /** Put slash `v` in square (x, y), updating the point groups and equivalence class. */
  fill(x: number, y: number, v: number): void {
    const { w, W } = this;
    const i = y * w + x;
    if (this.soln[i] !== EMPTY) return;
    this.soln[i] = v;
    this.slashval[this.equiv.find(i)] = v;
    if (v === BACK) {
      this.mergePoints(y * W + x, (y + 1) * W + (x + 1));
      this.decrExits(y * W + (x + 1));
      this.decrExits((y + 1) * W + x);
    } else {
      this.mergePoints(y * W + (x + 1), (y + 1) * W + x);
      this.decrExits(y * W + x);
      this.decrExits((y + 1) * W + (x + 1));
    }
  }

  /**
   * Record that squares `a` and `b` slant the same way. Returns false when their
   * classes are already known to slant differently.
   */
  mergeEquiv(a: number, b: number): boolean {
    const ra = this.equiv.find(a);
    const rb = this.equiv.find(b);
    if (ra === rb) return true;
    const sa = this.slashval[ra];
    const sb = this.slashval[rb];
    if (sa !== EMPTY && sb !== EMPTY && sa !== sb) return false;
    this.equiv.merge(ra, rb);
    this.slashval[this.equiv.find(ra)] = sa !== EMPTY ? sa : sb;
    return true;
  }

  /** Clear v-shape bits of square (x, y). Returns whether anything changed. */
  clearV(x: number, y: number, bits: number): boolean {
    const i = y * this.w + x;
    const had = this.vbitmap[i] & bits;
    this.vbitmap[i] &= ~bits;
    return had !== 0;
  }
}

/**
 * Deductions from one clue point. Returns false on contradiction.
 */
function solveClue(sc: Scratch, p: number, c: number, progress: { did: boolean }): boolean {
  const { w, soln, difficulty, nbPos, nbSlash } = sc;
  const n = sc.nbCount[p];
  const base = p * 4;
  // Count undecided squares and lines still needed. At Hard, two adjacent undecided
  // squares in the same equivalence class contribute exactly one line between them, so
  // they count as one line and drop out of the undecided count. Only one such pair is
  // tracked to avoid being misled by overlapping pairs.
  let nu = 0;
  let nl = c;
  let last = nbPos[base + n - 1];
  let eq = soln[last] === EMPTY ? sc.equiv.find(last) : -1;
  let mj1 = -1;
  let mj2 = -1;
  for (let k = 0; k < n; k++) {
    const j = nbPos[base + k];
    if (soln[j] === EMPTY) {
      nu++;
      if (mj1 < 0 && difficulty > DIFF_EASY) {
        const eq2 = sc.equiv.find(j);
        if (eq === eq2 && last !== j) {
          mj1 = last;
          mj2 = j;
          nl--;
          nu -= 2;
        } else {
          eq = eq2;
        }
      }
    } else {
      eq = -1;
      if (soln[j] === nbSlash[base + k]) nl--;
    }
    last = j;
  }
  if (nl < 0 || nl > nu) return false;

  if (nu > 0 && (nl === 0 || nl === nu)) {
    for (let k = 0; k < n; k++) {
      const j = nbPos[base + k];
      if (soln[j] === EMPTY && j !== mj1 && j !== mj2)
        sc.fill(j % w, Math.floor(j / w), nl ? nbSlash[base + k] : -nbSlash[base + k]);
    }
    progress.did = true;
    return true;
  }

  if (nu === 2 && nl === 1 && difficulty > DIFF_EASY) {
    // Exactly one line to place between two adjacent undecided squares: they must
    // slant the same way.
    let first = -1;
    let second = -1;
    for (let k = 0; k < n; k++) {
      const j = nbPos[base + k];
      if (soln[j] !== EMPTY || j === mj1 || j === mj2) continue;
      if (first < 0) first = k;
      else if (first === k - 1 || (first === 0 && k === 3)) {
        second = k;
        break;
      }
    }
    if (second >= 0) {
      const a = nbPos[base + first];
      const b = nbPos[base + second];
      if (sc.equiv.find(a) !== sc.equiv.find(b)) {
        if (!sc.mergeEquiv(a, b)) return false;
        progress.did = true;
      }
    }
  }
  return true;
}

/**
 * Loop avoidance (and, at Hard, dead-end avoidance and known equivalences) for one
 * undecided square. Returns false on contradiction.
 */
function solveSquare(sc: Scratch, x: number, y: number, progress: { did: boolean }): boolean {
  const { w, W, difficulty } = sc;
  const hard = difficulty > DIFF_EASY;
  const v = hard ? sc.slashval[sc.equiv.find(y * w + x)] : EMPTY;
  const deadEnd = (c1: number, c2: number) =>
    hard && !sc.border[c1] && !sc.border[c2] && sc.exits[c1] <= 1 && sc.exits[c2] <= 1;

  // Joining (x, y) to (x+1, y+1) with a `\` must not close a loop or seal a dead end.
  let c1 = sc.connected.find(y * W + x);
  let c2 = sc.connected.find((y + 1) * W + (x + 1));
  const fs = c1 === c2 || deadEnd(c1, c2) || v === FORWARD;
  // Likewise for a `/` between (x+1, y) and (x, y+1).
  c1 = sc.connected.find(y * W + (x + 1));
  c2 = sc.connected.find((y + 1) * W + x);
  const bs = c1 === c2 || deadEnd(c1, c2) || v === BACK;

  if (fs && bs) return false;
  if (fs) {
    sc.fill(x, y, FORWARD);
    progress.did = true;
  } else if (bs) {
    sc.fill(x, y, BACK);
    progress.did = true;
  }
  return true;
}

/** V-shape bookkeeping (Hard only). Returns false on contradiction. */
function solveVShapes(sc: Scratch, progress: { did: boolean }): boolean {
  const { w, h, W, soln, clues, vbitmap } = sc;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      // A known diagonal rules out the v-shapes that contradict it.
      const s = soln[i];
      if (s !== EMPTY) {
        if (x > 0 && sc.clearV(x - 1, y, s === BACK ? V_DOWN : V_UP)) progress.did = true;
        if (x + 1 < w && sc.clearV(x, y, s === BACK ? V_UP : V_DOWN)) progress.did = true;
        if (y > 0 && sc.clearV(x, y - 1, s === BACK ? V_RIGHT : V_LEFT)) progress.did = true;
        if (y + 1 < h && sc.clearV(x, y, s === BACK ? V_LEFT : V_RIGHT)) progress.did = true;
      }
      // A pair that can form neither v-shape slants the same way.
      if (x + 1 < w && !(vbitmap[i] & (V_DOWN | V_UP)) && !sc.equiv.same(i, i + 1)) {
        if (!sc.mergeEquiv(i, i + 1)) return false;
        progress.did = true;
      }
      if (y + 1 < h && !(vbitmap[i] & (V_RIGHT | V_LEFT)) && !sc.equiv.same(i, i + w)) {
        if (!sc.mergeEquiv(i, i + w)) return false;
        progress.did = true;
      }
      // The rest concerns the interior clue point at the top-left corner of this square.
      if (x === 0 || y === 0) continue;
      const c = clues[y * W + x];
      if (c === NO_CLUE) continue;
      if (c === 1) {
        // No v may point at a 1: it would give the point two lines.
        if (sc.clearV(x - 1, y - 1, V_DOWN | V_RIGHT)) progress.did = true;
        if (sc.clearV(x - 1, y, V_UP)) progress.did = true;
        if (sc.clearV(x, y - 1, V_LEFT)) progress.did = true;
      } else if (c === 3) {
        // No v may point away from a 3: both its squares would miss the point.
        if (sc.clearV(x - 1, y - 1, V_UP | V_LEFT)) progress.did = true;
        if (sc.clearV(x - 1, y, V_DOWN)) progress.did = true;
        if (sc.clearV(x, y - 1, V_RIGHT)) progress.did = true;
      } else if (c === 2) {
        // Around a 2 the pair on one side mirrors the pair on the other: a v pointing
        // at it from above forces a v pointing away below, and so on. So a v ruled out
        // on one side is ruled out on the opposite side too.
        const horizAbove = i - w - 1;
        const horizBelow = i - 1;
        const vertLeft = i - w - 1;
        const vertRight = i - w;
        const H_BITS = V_DOWN | V_UP;
        const V_BITS = V_RIGHT | V_LEFT;
        if (sc.clearV(x - 1, y - 1, (vbitmap[horizBelow] & H_BITS) ^ H_BITS)) progress.did = true;
        if (sc.clearV(x - 1, y - 1, (vbitmap[vertRight] & V_BITS) ^ V_BITS)) progress.did = true;
        if (sc.clearV(x - 1, y, (vbitmap[horizAbove] & H_BITS) ^ H_BITS)) progress.did = true;
        if (sc.clearV(x, y - 1, (vbitmap[vertLeft] & V_BITS) ^ V_BITS)) progress.did = true;
      }
    }
  }
  return true;
}

/**
 * Solve `clues` into `soln` (which is cleared first) using the deductions allowed at
 * `difficulty`. Returns SOLVE_IMPOSSIBLE, SOLVE_SOLVED or SOLVE_STUCK.
 */
export function solve(
  w: number,
  h: number,
  clues: Int8Array,
  soln: Int8Array,
  difficulty: number,
  scratch?: Scratch,
): number {
  const sc = scratch ?? new Scratch(w, h);
  sc.reset(clues, soln, difficulty);
  const W = w + 1;
  const H = h + 1;
  const progress = { did: false };
  do {
    progress.did = false;
    for (let p = 0; p < W * H; p++) {
      const c = clues[p];
      if (c !== NO_CLUE && !solveClue(sc, p, c, progress)) return SOLVE_IMPOSSIBLE;
    }
    if (sc.dead) return SOLVE_IMPOSSIBLE;
    if (progress.did) continue;

    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        if (soln[y * w + x] !== EMPTY) continue;
        if (!solveSquare(sc, x, y, progress)) return SOLVE_IMPOSSIBLE;
      }
    }
    if (progress.did) continue;

    if (difficulty > DIFF_EASY && !solveVShapes(sc, progress)) return SOLVE_IMPOSSIBLE;
  } while (progress.did);

  for (let i = 0; i < w * h; i++) if (soln[i] === EMPTY) return SOLVE_STUCK;
  return SOLVE_SOLVED;
}

/** Convenience: solve from scratch and return the result with the grid. */
export function solveFresh(
  w: number,
  h: number,
  clues: Int8Array,
  difficulty: number,
): { result: number; soln: Int8Array } {
  const soln = new Int8Array(w * h);
  return { result: solve(w, h, clues, soln, difficulty), soln };
}
