import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT,
  CURSOR_SELECT2,
  KEY_BACKSPACE,
  LEFT_BUTTON,
  MOD_SHFT,
  RIGHT_BUTTON,
  isCursorMove,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { INK_TIME, changedAt, drawGrow, popGrow } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { generateKeen, parseDesc } from './generator';
import type { KeenParams } from './generator';
import {
  DIFF_AMBIGUOUS,
  DIFF_CHARS,
  DIFF_COUNT,
  DIFF_EASY,
  DIFF_EXTREME,
  DIFF_HARD,
  DIFF_IMPOSSIBLE,
  DIFF_NORMAL,
  DIFF_UNREASONABLE,
  OP_SYMBOLS,
  checkErrors,
  solveKeen,
} from './solver';
import type { Layout } from './solver';
import { tutorial } from './tutorial';
import help from './help.md?raw';
import { achievements } from './achievements';
import { HIGHLIGHT_GLYPH } from '../../framework/glyphs';

export type { KeenParams } from './generator';

export interface KeenState {
  w: number;
  layout: Layout;
  grid: Uint8Array;
  /** pencil[xy*w + n-1] is set when digit n is pencilled into square xy. */
  pencil: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface KeenUI {
  hx: number;
  hy: number;
  /** The highlight is shown. */
  hshow: boolean;
  /** Typed digits become pencil marks. */
  hpencil: boolean;
  /** The highlight was placed with the keyboard, so it stays after a digit is typed. */
  hcursor: boolean;
  /** A digit just went into the selected square: one click on it keeps it chosen. */
  hkept: boolean;
  /** The Highlight tool: every square holding the digit last pointed at is picked out. */
  spot: boolean;
  /** The square last clicked or moved to, whose digit Highlight picks out; -1 for none. */
  spotAt: number;
}

const FLASH = 0.4;
const DEFAULTS: KeenParams = { w: 6, diff: DIFF_NORMAL, multOnly: false };

/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it at the gentlest setting the Type menu
 * offers at that size, and goes up the ladder when they want to.
 */
const OPENING: KeenParams = { ...DEFAULTS, diff: DIFF_EASY };

/**
 * Difficulty words, in the solver's own order, for the Type menu and the Custom dialog
 * alike: a player who picks "Extreme" from one and opens the other must find the same
 * word selected there. The solver's own level names (`DIFF_NAMES`) stay in the code.
 */
const PRESET_DIFFICULTIES = ['Easy', 'Medium', 'Hard', 'Expert', 'Extreme'];

function preset(w: number, diff: number, multOnly = false): { name: string; params: KeenParams } {
  return {
    name: `${w}×${w} ${PRESET_DIFFICULTIES[diff]}${multOnly ? ', × only' : ''}`,
    params: { w, diff, multOnly },
  };
}

const PRESETS = [
  preset(4, DIFF_EASY),
  preset(5, DIFF_EASY),
  preset(5, DIFF_EASY, true),
  preset(6, DIFF_EASY),
  preset(6, DIFF_NORMAL),
  preset(6, DIFF_NORMAL, true),
  preset(6, DIFF_HARD),
  preset(6, DIFF_EXTREME),
  preset(6, DIFF_UNREASONABLE),
  preset(9, DIFF_NORMAL),
];

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

export function makeState(layout: Layout): KeenState {
  const { w } = layout;
  return {
    w,
    layout,
    grid: new Uint8Array(w * w),
    pencil: new Uint8Array(w * w * w),
    completed: false,
    cheated: false,
  };
}

/** The clue shown in a cage's first square: the total, then the operator symbol. */
export function clueText(layout: Layout, cage: number): string {
  const c = layout.cages[cage];
  return String(c.value) + (c.cells.length === 1 ? '' : OP_SYMBOLS[c.op]);
}

/**
 * Trace the outline of one cage as a polygon. The walk keeps a cage square on its
 * right and records a point at every turn.
 */
function cageOutline(layout: Layout, bi: number, border: number, t: number): number[] {
  const { w, whichCage } = layout;
  const start = layout.cages[bi].cells[0];
  const inside = (tx: number, ty: number) =>
    tx >= 0 && tx < w && ty >= 0 && ty < w && whichCage[ty * w + tx] === bi;
  let x = start % w;
  let y = Math.floor(start / w);
  let dx = -1;
  let dy = 0;
  const sx = x;
  const sy = y;
  const pts: number[] = [];
  let guard = 0;
  do {
    let nin = 0;
    if (inside(x - dy + dx, y + dx + dy)) nin++;
    if (inside(x - dy, y + dx)) nin++;
    if (nin === 0) {
      const tmp = dx;
      dx = -dy;
      dy = tmp;
    } else if (nin === 2) {
      x += dx;
      y += dy;
      const tmp = dx;
      dx = dy;
      dy = -tmp;
      x -= dx;
      y -= dy;
    } else {
      x -= dy;
      y += dx;
    }
    if (nin !== 1) {
      const cx = (2 * x + 1 + dy + dx) / 2;
      const cy = (2 * y + 1 - dx + dy) / 2;
      pts.push(border + cx * t, border + cy * t);
    }
  } while ((x !== sx || y !== sy || dx !== -1 || dy !== 0) && ++guard < 8 * w * w);
  return pts;
}

function drawPencilMarks(
  dr: Drawing,
  state: KeenState,
  xy: number,
  px: number,
  py: number,
  t: number,
  hasClue: boolean,
  spot: number,
): void {
  const { w } = state;
  const marks: number[] = [];
  for (let n = 1; n <= w; n++) if (state.pencil[xy * w + n - 1]) marks.push(n);
  const count = marks.length;
  if (!count) return;
  const pad = t * 0.06;
  const pl = px + pad;
  const pr = px + t - pad;
  let pt = py + pad;
  const pb = py + t - pad;
  if (hasClue) pt += t * 0.27;
  let bestSize = 0;
  let pw = 3;
  for (let cols = 3; cols < Math.max(count, 4); cols++) {
    const rows = Math.max(Math.ceil(count / cols), 2);
    const fs = Math.min((pr - pl) / cols, (pb - pt) / rows);
    if (fs > bestSize) {
      bestSize = fs;
      pw = cols;
    }
  }
  const ph = Math.max(Math.ceil(count / pw), 2);
  const fs = Math.min((pr - pl) / pw, (pb - pt) / ph);
  const left = px + (t - fs * pw) / 2;
  let top = py + (t - fs * ph) / 2;
  if (hasClue) top = Math.max(top, pt);
  for (let j = 0; j < count; j++) {
    const gx = j % pw;
    const gy = Math.floor(j / pw);
    const lit = marks[j] === spot;
    dr.text(left + fs * (gx + 0.5), top + fs * (gy + 0.5), String(marks[j]), {
      size: fs * 0.82,
      colour: lit ? 'teal' : 'pencil',
      bold: lit,
    });
  }
}

/** The digit Highlight is picking out, or 0 when it is off or points at an empty square. */
export function spotDigit(grid: Uint8Array, ui: KeenUI): number {
  return ui.spot && ui.spotAt >= 0 && ui.spotAt < grid.length ? grid[ui.spotAt] : 0;
}

const game = defineGame<KeenParams, KeenState, KeenUI>({
  id: 'keen',
  name: 'Keen',
  description: 'Fill the latin square so every cage makes its arithmetic clue.',
  alsoKnownAs: 'KenKen, Calcudoku',
  help,
  tutorial,
  achievements,
  presets: PRESETS,
  defaultParams: () => ({ ...OPENING }),
  encodeParams(p, full) {
    let s = String(p.w);
    if (full) {
      s += 'd' + (DIFF_CHARS[p.diff] ?? '?');
      if (p.multOnly) s += 'm';
    }
    return s;
  },
  decodeParams(str) {
    const m = /^(\d+)/.exec(str);
    if (!m) throw new Error(tx`expected a grid size`);
    const p: KeenParams = { ...DEFAULTS };
    p.w = parseInt(m[1], 10);
    // A descriptive ID (a share link) carries only the size. Read it as the first preset
    // of that size — the one the Type menu then shows — so New deals what the menu says
    // rather than a custom Medium of a size whose presets are all Easy.
    p.diff = PRESETS.find((q) => q.params.w === p.w)?.params.diff ?? DEFAULTS.diff;
    let i = m[0].length;
    if (str[i] === 'd') {
      i++;
      p.diff = DIFF_CHARS.indexOf(str[i] ?? '');
      if (i < str.length) i++;
    }
    if (str[i] === 'm') p.multOnly = true;
    return p;
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.diff))
      return tx`Parameters must be whole numbers`;
    if (p.w < 3 || p.w > 9) return tx`Grid size must be between 3 and 9`;
    if (p.diff < 0 || p.diff >= DIFF_COUNT) return tx`Unknown difficulty rating`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Grid size', value: String(p.w) },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.diff },
      { type: 'boolean', name: 'Multiplication only', value: p.multOnly },
    ];
  },
  customParams(items) {
    const s = (items[0] as { value: string }).value.trim();
    return {
      w: /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN,
      diff: (items[1] as { selected: number }).selected,
      multOnly: (items[2] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    return generateKeen(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(p.w, desc);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    return makeState(parseDesc(p.w, desc) as Layout);
  },

  canSolve: true,
  solve(orig, _curr, aux) {
    if (aux) return aux;
    const grid = new Uint8Array(orig.w * orig.w);
    const ret = solveKeen(orig.layout, grid, DIFF_UNREASONABLE);
    if (ret === DIFF_IMPOSSIBLE) throw new Error(tx`No solution exists for this puzzle`);
    if (ret === DIFF_AMBIGUOUS) throw new Error(tx`Multiple solutions exist for this puzzle`);
    return 'S' + Array.from(grid).join('');
  },

  newUI: () => ({
    hx: 0,
    hy: 0,
    hshow: false,
    hpencil: false,
    hcursor: false,
    hkept: false,
    spot: false,
    spotAt: -1,
  }),
  changedState(ui, _old, next) {
    // A pencil highlight on a square that has just been filled (by Undo, Redo or Solve)
    // makes no sense, so drop it unless the keyboard cursor is in use; and a puzzle just
    // finished needs no selection at all.
    if (ui.hshow && ui.hpencil && !ui.hcursor && next.grid[ui.hy * next.w + ui.hx] !== 0)
      ui.hshow = false;
    if (next.completed && !_old.completed) ui.hshow = false;
  },

  // One key per digit, a clear key and the pencil-mark latch, so a device without a
  // keyboard can still fill squares in.
  keypad: (p) => ({
    keys: Array.from({ length: p.w }, (_, i) => String(i + 1)),
    clear: true,
    pencil: true,
  }),

  actions: [
    {
      label: 'Marks',
      key: 'M',
      title: 'Pencil every possibility into every empty square (M)',
    },
    {
      label: 'Highlight',
      key: 'L',
      hud: true,
      glyph: HIGHLIGHT_GLYPH,
      pressed: (_s, ui) => ui.spot,
      view: true,
      title: 'Pick out every square holding the digit you last touched (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    // A click straight after a digit re-chooses the square that kept its selection rather
    // than deselecting it, so clicking a square before each digit still types.
    const kept = ui.hkept;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || isCursorMove(b)) ui.hkept = false;
    const { w } = state;
    const t = ds.tileSize;
    const border = boardBorder(t);
    const tx = Math.floor((mx - border) / t);
    const ty = Math.floor((my - border) / t);
    const inside = tx >= 0 && tx < w && ty >= 0 && ty < w;

    if (b === 76 || b === 108) {
      ui.spot = !ui.spot;
      return '';
    }
    if (inside && (b === LEFT_BUTTON || b === RIGHT_BUTTON)) ui.spotAt = ty * w + tx;
    if (inside && b === LEFT_BUTTON) {
      if (tx === ui.hx && ty === ui.hy && ui.hshow && !ui.hpencil && !kept) {
        ui.hshow = false;
      } else {
        ui.hx = tx;
        ui.hy = ty;
        ui.hshow = true;
        ui.hpencil = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (inside && b === RIGHT_BUTTON) {
      if (state.grid[ty * w + tx] === 0) {
        if (tx === ui.hx && ty === ui.hy && ui.hshow && ui.hpencil) {
          ui.hshow = false;
        } else {
          ui.hx = tx;
          ui.hy = ty;
          ui.hshow = true;
          ui.hpencil = true;
        }
      } else {
        ui.hshow = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.hx, ui.hy, w, w);
      ui.hx = p.x;
      ui.hy = p.y;
      ui.spotAt = p.y * w + p.x;
      ui.hshow = true;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow && b === CURSOR_SELECT) {
      ui.hpencil = !ui.hpencil;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow) {
      let n = -1;
      if (b >= 48 && b <= 57 && b - 48 <= w) n = b - 48;
      else if (b === CURSOR_SELECT2 || b === KEY_BACKSPACE) n = 0;
      if (n >= 0) {
        // MOD_SHFT on a digit is the on-screen keypad's pencil latch: pencil this in
        // whatever mode the square was selected in.
        const pencil = ui.hpencil || (button & MOD_SHFT) !== 0;
        // Only the keyboard cursor can pencil-highlight a filled square.
        if (pencil && state.grid[ui.hy * w + ui.hx]) return null;
        const move = `${pencil && n > 0 ? 'P' : 'R'}${ui.hx},${ui.hy},${n}`;
        // The selection stays after a digit, so a keypad user can rub it out or try
        // another without tapping the square again.
        if (!pencil && !ui.hcursor) ui.hkept = true;
        return move;
      }
    }
    if (b === 77 || b === 109) return 'M';
    return null;
  },

  executeMove(state, move) {
    const { w } = state;
    const area = w * w;
    if (move[0] === 'S') {
      if (move.length !== area + 1) return null;
      const grid = new Uint8Array(area);
      for (let i = 0; i < area; i++) {
        const v = move.charCodeAt(i + 1) - 48;
        if (v < 1 || v > w) return null;
        grid[i] = v;
      }
      return {
        ...state,
        grid,
        pencil: new Uint8Array(state.pencil.length),
        completed: true,
        cheated: true,
      };
    }
    if (move === 'M') {
      const pencil = state.pencil.slice();
      for (let xy = 0; xy < area; xy++) if (!state.grid[xy]) pencil.fill(1, xy * w, xy * w + w);
      // Every empty square already fully pencilled (or none left): an undo step that
      // changes nothing would only be confusing.
      if (pencil.every((v, i) => v === state.pencil[i])) return state;
      return { ...state, pencil };
    }
    const m = /^([PR])(\d+),(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    const n = parseInt(m[4], 10);
    if (x >= w || y >= w || n > w) return null;
    const xy = y * w + x;
    if (m[1] === 'P' && n > 0) {
      if (state.grid[xy]) return null;
      const pencil = state.pencil.slice();
      pencil[xy * w + n - 1] ^= 1;
      return { ...state, pencil };
    }
    // Rubbing out an empty square, or typing the digit a square already holds, changes
    // nothing: returning the same state keeps it from becoming an Undo step that does nothing.
    if (state.grid[xy] === n && !state.pencil.subarray(xy * w, xy * w + w).some((v) => v)) {
      return state;
    }
    const grid = state.grid.slice();
    grid[xy] = n;
    const pencil = state.pencil.slice();
    pencil.fill(0, xy * w, xy * w + w);
    const completed = state.completed || checkErrors(state.layout, grid).solved;
    return { ...state, grid, pencil, completed };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.w * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { w, grid, layout } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashTime > 0 && (flashTime <= FLASH / 3 || flashTime >= (2 * FLASH) / 3);
    const errors = checkErrors(layout, grid);

    dr.rect(b, b, w * t, w * t, flash ? 'shade' : 'paper');
    // A finished board is shown clean, without the tint.
    const spot = state.completed ? 0 : spotDigit(grid, ui);
    if (spot) {
      for (let xy = 0; xy < w * w; xy++) {
        if (grid[xy] !== spot) continue;
        dr.rect(b + (xy % w) * t, b + Math.floor(xy / w) * t, t, t, 'teal', null, { alpha: 0.18 });
      }
    }
    if (ui.hshow) {
      const hx = b + ui.hx * t;
      const hy = b + ui.hy * t;
      dr.rect(hx, hy, t, t, ui.hpencil ? 'blue' : 'yellow', null, {
        alpha: ui.hpencil ? 0.12 : 0.25,
      });
    }

    for (let i = 1; i < w; i++) {
      dr.line(b + i * t, b, b + i * t, b + w * t, 'faint', 1.2);
      dr.line(b, b + i * t, b + w * t, b + i * t, 'faint', 1.2);
    }
    for (let bi = 0; bi < layout.cages.length; bi++) {
      dr.polygon(cageOutline(layout, bi, b, t), null, 'ink', { width: 2.6, seed: bi });
    }

    // A digit the player has just typed is pressed into the square rather than simply
    // being there, and one they have rubbed out shrinks away. This is the most repeated
    // action in the collection, so it is short — and a Solve, which fills the whole grid
    // at once, is left to appear whole.
    const inked = oldState ? changedAt(oldState.grid, grid, 2) : null;
    /** The digit a square is showing mid-change, and how big it is. */
    const inkAt = (i: number, d: number): { d: number; s: number } =>
      !inked?.includes(i)
        ? { d, s: 1 }
        : d
          ? { d, s: popGrow(animTime) }
          : { d: oldState!.grid[i], s: 1 - drawGrow(animTime, INK_TIME) };

    for (let y = 0; y < w; y++) {
      for (let x = 0; x < w; x++) {
        const xy = y * w + x;
        const px = b + x * t;
        const py = b + y * t;
        const bi = layout.whichCage[xy];
        const hasClue = layout.cages[bi].cells[0] === xy;
        if (hasClue) {
          dr.text(px + t * 0.09, py + t * 0.08, clueText(layout, bi), {
            size: t * 0.27,
            colour: errors.cages[bi] ? 'error' : 'ink',
            align: 'left',
            valign: 'top',
            maxWidth: t * 0.85,
          });
        }
        const ink = inkAt(xy, grid[xy]);
        const d = ink.d;
        if (d && ink.s > 0) {
          const colour = errors.cells[xy] ? 'error' : flash ? 'ok' : 'blue';
          dr.text(px + t / 2, py + t / 2 + (hasClue ? t * 0.08 : 0), String(d), {
            size: t * (hasClue ? 0.5 : 0.55) * ink.s,
            colour,
          });
        } else if (!grid[xy]) {
          drawPencilMarks(dr, state, xy, px, py, t, hasClue, spot);
        }
      }
    }

    dr.rectOutline(b, b, w * t, w * t, 'ink', { width: 2.6 });

    if (ui.hshow) {
      const inset = t * 0.08;
      const hx = b + ui.hx * t + inset;
      const hy = b + ui.hy * t + inset;
      dr.cursor(hx, hy, t - 2 * inset, t - 2 * inset, 'accent', 2.2, {
        dash: ui.hpencil ? [Math.max(3, t * 0.1), Math.max(2, t * 0.08)] : undefined,
      });
      if (ui.hpencil) {
        // Pencil-mode marker in the top-right corner, clear of the cage clue.
        const s = t * 0.22;
        const rx = hx + t - 2 * inset;
        dr.polygon([rx, hy, rx - s, hy, rx, hy + s], 'accent', null, { seed: 7 });
      }
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.grid, newState.grid, 2) ? INK_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  thumbnailParams: { w: 5, diff: DIFF_EASY, multOnly: false },
});

export default game;
