import { t } from '../i18n';

/** A drawn arrow pointing back, in `currentColor`; mirrored on a right-to-left page (CSS). */
const BACK_SVG =
  '<svg class="back-arrow" viewBox="0 0 24 24" width="26" height="26" aria-hidden="true" focusable="false">' +
  '<path d="M19.4 12.3c-4.6-.3-9.3.1-14 .1" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>' +
  '<path d="M10.6 6.2 4.9 12.3l5.9 5.6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>' +
  '</svg>';

/** The star in the credits coin, on the menu's resource bar and the play page's header. */
export const STAR_COIN_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.2l2.6 5.5 6 .7-4.4 4.1 1.2 5.9L12 16.5l-5.4 2.9 1.2-5.9-4.4-4.1 6-.7z" fill="currentColor" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/></svg>';

/**
 * The way back to the collection, as a round drawn button like the HUD's rather than a
 * "← All puzzles" text link. The words stay: inside it, hidden from the eye, as its name
 * (`aria-label` too), and as its drawn tooltip — `title` is lifted into one by gameFeel.ts.
 *
 * A real link, so it keeps a link's keyboard and screen-reader behaviour (and never fires
 * an ad: docs/CRAZYGAMES.md rules navigation out as a trigger).
 */
export function backButton(label = t('ui.topbar.back'), href = '#/'): HTMLAnchorElement {
  const a = document.createElement('a');
  a.className = 'back round-btn';
  a.href = href;
  a.innerHTML = BACK_SVG;
  const text = document.createElement('span');
  text.className = 'back-text';
  text.textContent = label;
  a.append(text);
  a.setAttribute('aria-label', label);
  a.title = label;
  return a;
}
