/**
 * Loopy puzzle generation.
 *
 * A random loop is made by colouring faces: the outside is black, one random face is
 * white, and the two regions grow into the grey faces one at a time. A face may only
 * join a region it already touches along an edge, and only if doing so keeps both
 * regions simply connected (walking round the face, the colour must change exactly
 * twice), so the border between white and black is always a single closed loop. Faces
 * with few same-coloured neighbours are preferred, which makes the loop wiggly, and
 * afterwards single-neighbour faces are flipped to grow tendrils into any clumps, with
 * a final pass of random flips so the result is not too predictable.
 *
 * Every face is then numbered, and clues are removed in random order while the solver
 * of the requested difficulty still finds the unique answer. A puzzle the next easier
 * solver can also finish is thrown away and a new loop tried.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';
import { LINE_NO, LINE_UNKNOWN, LINE_YES, NO_CLUE, encodeClues, encodeLines } from './board';
import {
  GRID_PENROSE_P2,
  GRID_PENROSE_P3,
  Grid,
  defaultGridDesc,
  getGrid,
  newPenroseDesc,
} from './grid';
import { SOLVER_SOLVED, Solver } from './solver';

export interface LoopyParams {
  w: number;
  h: number;
  type: number;
  difficulty: number;
}

export const FACE_GREY = 0;
export const FACE_WHITE = 1;
export const FACE_BLACK = 2;

/**
 * Loops tried before giving up on parameters that never yield a solvable puzzle: at
 * least `MAX_LOOPS`, and more on small grids, where a loop is cheap to make and to test
 * (`LOOP_FACES` faces' worth in all), so a rarely solvable small grid still deals.
 */
const MAX_LOOPS = 400;
const LOOP_FACES = 100_000;
/**
 * Clue-stripping passes cost about faces × edges; after this much work a puzzle that came
 * out a level too easy is dealt instead of stripping yet another loop (about two passes on
 * the largest grids the dialog allows, a hundred or more on small ones).
 */
const MAX_WORK = 800_000;

function neighbourCount(g: Grid, board: Uint8Array, f: number, colour: number): number {
  let n = 0;
  for (const e of g.faceEdges[f]) {
    const other = g.edgeFace1[e] === f ? g.edgeFace2[e] : g.edgeFace1[e];
    if ((other < 0 ? FACE_BLACK : board[other]) === colour) n++;
  }
  return n;
}

/**
 * May face `f` (not currently `colour`) be given `colour` without breaking the shape
 * of that region? It must touch the region along an edge, and walking once round the
 * face through every face that touches it (at edges or corners) must cross between
 * `colour` and not-`colour` exactly twice.
 */
export function canColourFace(g: Grid, board: Uint8Array, f: number, colour: number): boolean {
  const colourOf = (x: number) => (x < 0 ? FACE_BLACK : board[x]);
  if (neighbourCount(g, board, f, colour) === 0) return false;
  const fd = g.faceDots[f];
  let i = 0;
  let j = 0;
  let current = g.dotFaces[fd[0]][0];
  if (current === f) {
    j = 1;
    current = g.dotFaces[fd[0]][1];
  }
  let transitions = 0;
  let state = colourOf(current) === colour;
  let startDot = -1;
  let startFace = -2;
  for (;;) {
    // Step to the next face clockwise round the current corner; on reaching `f`
    // itself, move to the next corner and carry on from the face we were at.
    for (;;) {
      j++;
      if (j === g.dotFaces[fd[i]].length) j = 0;
      if (g.dotFaces[fd[i]][j] !== f) break;
      i++;
      if (i === fd.length) i = 0;
      j = g.dotFaces[fd[i]].indexOf(current);
      if (j < 0) throw new Error(tx`grid inconsistency while walking round a face`);
    }
    current = g.dotFaces[fd[i]][j];
    const s = colourOf(current) === colour;
    if (startDot < 0) {
      startDot = fd[i];
      startFace = current;
      state = s;
    } else {
      if (s !== state) {
        transitions++;
        state = s;
        if (transitions > 2) break;
      }
      if (fd[i] === startDot && current === startFace) break;
    }
  }
  return transitions === 2;
}

/** Colour every face white (inside the loop) or black (outside). */
export function generateLoop(g: Grid, rng: Random): Uint8Array {
  const nf = g.nf;
  const board = new Uint8Array(nf);
  const random = new Uint32Array(nf);
  for (let f = 0; f < nf; f++) random[f] = rng.bits(31);
  const whiteScore = new Int32Array(nf);
  const blackScore = new Int32Array(nf);
  const lightable = new Uint8Array(nf);
  const darkable = new Uint8Array(nf);
  const update = (f: number) => {
    lightable[f] = board[f] === FACE_GREY && canColourFace(g, board, f, FACE_WHITE) ? 1 : 0;
    darkable[f] = board[f] === FACE_GREY && canColourFace(g, board, f, FACE_BLACK) ? 1 : 0;
    // Higher score = fewer same-coloured neighbours = a wigglier boundary.
    if (lightable[f]) whiteScore[f] = -neighbourCount(g, board, f, FACE_WHITE);
    if (darkable[f]) blackScore[f] = -neighbourCount(g, board, f, FACE_BLACK);
  };

  board[rng.upto(nf)] = FACE_WHITE;
  for (let f = 0; f < nf; f++) update(f);
  for (;;) {
    let nl = 0;
    let nd = 0;
    for (let f = 0; f < nf; f++) {
      nl += lightable[f];
      nd += darkable[f];
    }
    if (nl === 0 && nd === 0) break;
    let colour = rng.upto(2) ? FACE_WHITE : FACE_BLACK;
    if (colour === FACE_WHITE && nl === 0) colour = FACE_BLACK;
    else if (colour === FACE_BLACK && nd === 0) colour = FACE_WHITE;
    const cand = colour === FACE_WHITE ? lightable : darkable;
    const score = colour === FACE_WHITE ? whiteScore : blackScore;
    let best = -1;
    for (let f = 0; f < nf; f++) {
      if (!cand[f]) continue;
      if (
        best < 0 ||
        score[f] > score[best] ||
        (score[f] === score[best] && random[f] < random[best])
      ) {
        best = f;
      }
    }
    board[best] = colour;
    lightable[best] = darkable[best] = 0;
    for (const d of g.faceDots[best]) {
      for (const f2 of g.dotFaces[d])
        if (f2 >= 0 && f2 !== best && board[f2] === FACE_GREY) update(f2);
    }
  }

  // Grow tendrils into clumps, then shake things up a little.
  const order: number[] = [];
  for (let f = 0; f < nf; f++) order.push(f);
  rng.shuffle(order);
  let randomPass = false;
  for (;;) {
    let flipped = false;
    for (const f of order) {
      const opp = board[f] === FACE_WHITE ? FACE_BLACK : FACE_WHITE;
      if (!canColourFace(g, board, f, opp)) continue;
      if (randomPass) {
        if (rng.upto(10) === 0) board[f] = opp;
      } else if (neighbourCount(g, board, f, opp) === 1) {
        board[f] = opp;
        flipped = true;
      }
    }
    if (randomPass) break;
    if (!flipped) randomPass = true;
  }
  return board;
}

/** The loop itself: every edge between differently coloured faces is a line. */
export function linesFromBoard(g: Grid, board: Uint8Array): Uint8Array {
  const lines = new Uint8Array(g.ne).fill(LINE_NO);
  for (let e = 0; e < g.ne; e++) {
    const c1 = board[g.edgeFace1[e]];
    const f2 = g.edgeFace2[e];
    const c2 = f2 < 0 ? FACE_BLACK : board[f2];
    if (c1 !== c2) lines[e] = LINE_YES;
  }
  return lines;
}

/** Number every face with the count of loop edges around it. */
export function cluesFromLines(g: Grid, lines: Uint8Array): Int8Array {
  const clues = new Int8Array(g.nf);
  for (let f = 0; f < g.nf; f++)
    for (const e of g.faceEdges[f]) if (lines[e] === LINE_YES) clues[f]++;
  return clues;
}

function uniquelySolvable(solver: Solver, scratch: Uint8Array, clues: Int8Array, diff: number) {
  scratch.fill(LINE_UNKNOWN);
  solver.reset(clues, scratch, diff);
  return solver.solve() === SOLVER_SOLVED;
}

/**
 * Penrose patches tried before giving up. The patch is random, and on a small grid the
 * odd one (a few in a hundred) cannot be finished at Easy or Medium from any loop; a
 * fresh patch almost always can.
 */
const MAX_PATCHES = 5;

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(p: LoopyParams, rng: Random): { desc: string; aux: string } {
  const penrose = p.type === GRID_PENROSE_P2 || p.type === GRID_PENROSE_P3;
  for (let patch = 1; ; patch++) {
    const gridDesc = penrose ? newPenroseDesc(p.type, p.w, p.h, rng) : defaultGridDesc(p.type);
    const puzzle = generateOn(p, gridDesc, rng);
    if (puzzle) return puzzle;
    if (!penrose || patch >= MAX_PATCHES)
      throw new Error(tx`Unable to generate a puzzle with these parameters`);
  }
}

/** One grid's worth of {@link generate}; null when no loop on it could be finished. */
function generateOn(
  p: LoopyParams,
  gridDesc: string | null,
  rng: Random,
): { desc: string; aux: string } | null {
  const g = getGrid(p.type, p.w, p.h, gridDesc);
  if (!g) throw new Error(tx`Unable to build a grid for these parameters`);
  const solver = new Solver(g);
  const scratch = new Uint8Array(g.ne);
  const order: number[] = [];
  for (let f = 0; f < g.nf; f++) order.push(f);
  const maxLoops = Math.max(MAX_LOOPS, Math.ceil(LOOP_FACES / g.nf));
  let loops = 0;
  let work = 0;
  // The last finished puzzle that turned out easier than asked: dealt when the budget
  // runs out, rather than an error, since some small grids never need the harder level.
  let easier: { desc: string; aux: string } | null = null;
  for (;;) {
    let clues: Int8Array;
    let soln: Uint8Array;
    do {
      if (++loops > maxLoops || work > MAX_WORK) return easier;
      soln = linesFromBoard(g, generateLoop(g, rng));
      clues = cluesFromLines(g, soln);
    } while (!uniquelySolvable(solver, scratch, clues, p.difficulty));
    rng.shuffle(order);
    for (const f of order) {
      const c = clues[f];
      clues[f] = NO_CLUE;
      if (!uniquelySolvable(solver, scratch, clues, p.difficulty)) clues[f] = c;
    }
    work += g.nf * g.ne;
    const puzzle = {
      desc: (gridDesc ? `${gridDesc}_` : '') + encodeClues(clues),
      aux: encodeLines(soln),
    };
    // A puzzle must actually need its difficulty's reasoning.
    if (p.difficulty > 0 && uniquelySolvable(solver, scratch, clues, p.difficulty - 1)) {
      easier = puzzle;
      continue;
    }
    return puzzle;
  }
}
