import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_SELECT2,
  LEFT_BUTTON,
  MIDDLE_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  stripMods,
} from '../../framework/input';
import { DRAW_TIME, changedAt, drawGrow, flashOn, growSegment } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { CROSS_GLYPH } from '../../framework/glyphs';
import type { Random } from '../../framework/rng';
import {
  LINE_NO,
  LINE_UNKNOWN,
  LINE_YES,
  NO_CLUE,
  checkCompletion,
  decodeLines,
  faceCount,
  parseClues,
  splitDesc,
} from './board';
import {
  GRID_DODECAGONAL,
  GRID_PENROSE_P2,
  GRID_PENROSE_P3,
  GRID_SQUARE,
  GRID_TYPES,
  centralEdge,
  defaultGridDesc,
  getGrid,
  gridExtent,
  nearestEdge,
  stepEdge,
  validateGridDesc,
} from './grid';
import type { Grid } from './grid';
import { generate } from './generator';
import type { LoopyParams } from './generator';
import {
  DIFFICULTY_CHARS,
  DIFFICULTY_NAMES,
  DIFF_EASY,
  DIFF_HARD,
  DIFF_MAX,
  DIFF_NORMAL,
  SOLVER_AMBIGUOUS,
  SOLVER_MISTAKE,
  SOLVER_SOLVED,
  solveFresh,
  solveWithGuessing,
} from './solver';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export type { LoopyParams };

export interface LoopyState {
  w: number;
  h: number;
  type: number;
  /** The tiling. Shared between states. */
  grid: Grid;
  /** Clue on each face, or NO_CLUE. Shared between states. */
  clues: Int8Array;
  /** LINE_UNKNOWN, LINE_YES or LINE_NO for each edge. */
  lines: Uint8Array;
  /** 1 for each drawn edge that is part of a wrong loop or an overfull dot. */
  lineErr: Uint8Array;
  /** When solved, 1 for each face inside the loop. */
  inside: Uint8Array | null;
  /** Set once the loop has been completed; never cleared (as in the original). */
  solved: boolean;
  cheated: boolean;
}

export interface LoopyUI {
  /** Edge under the keyboard cursor, or -1 before the keyboard has been used. */
  cursor: number;
  cursorVisible: boolean;
  /** The Cross tool: a left click crosses an edge out instead of drawing a line on it. */
  cross: boolean;
}

const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_SIDE = 25;
/** Rough cap on the number of faces, to keep Hard generation to a few seconds. */
const MAX_FACES = 800;
/**
 * Most edges a grid may have for a new puzzle at each difficulty from Medium up. Removing
 * clues runs the solver once per face, and every run costs more on a bigger grid and at a
 * harder level: at the face cap alone a 25×25 Honeycomb Hard or a 16×16 Dodecagonal
 * Expert took 10 to 20 seconds to deal, with the tab frozen. These keep every deal to a
 * few seconds. (Penrose grids come out with far fewer edges than their size suggests and
 * stay fast, so the face cap is enough for them.)
 */
const MAX_EDGES = [Infinity, 1500, 1200, 1000];

/**
 * Dodecagonal grids on which the Easy or Medium solver can seldom finish a random loop
 * even with every clue shown, so deals ran out of attempts and failed. Easy works only
 * on small grids, Medium not on long thin ones (the tiling is not symmetric in width and
 * height). The limits were measured: a random loop must be solvable often enough (about
 * one in eighty) that a deal fails less than about once in a hundred. The other tilings
 * deal at every size the dialog allows.
 */
function dodecagonalUnsolvable(w: number, h: number, difficulty: number): boolean {
  if (difficulty === DIFF_EASY) return h > ([0, 0, 6, 5, 5, 5, 2][w] ?? 0);
  if (difficulty === DIFF_NORMAL)
    return h > ([0, 0, 10, 17][w] ?? Infinity) || w > ([0, 0, 6, 8, 13, 18][h] ?? Infinity);
  return false;
}
const DEFAULTS: LoopyParams = { w: 7, h: 7, type: GRID_SQUARE, difficulty: DIFF_EASY };

function borderOf(t: number): number {
  return Math.round(t * 0.35);
}

function canvasSize(type: number, w: number, h: number, t: number): { w: number; h: number } {
  const ext = gridExtent(type, w, h);
  const b = borderOf(t);
  return {
    w: Math.round((ext.w * t) / ext.tile) + 2 * b + 1,
    h: Math.round((ext.h * t) / ext.tile) + 2 * b + 1,
  };
}

/** Grid units → canvas pixels: `x * scale + ox`, with the grid centred on the canvas. */
export function geometry(state: LoopyState, t: number): { scale: number; ox: number; oy: number } {
  const ext = gridExtent(state.type, state.w, state.h);
  const size = canvasSize(state.type, state.w, state.h, t);
  const scale = t / ext.tile;
  const g = state.grid;
  return {
    scale,
    ox: (size.w - (g.maxX - g.minX) * scale) / 2 - g.minX * scale,
    oy: (size.h - (g.maxY - g.minY) * scale) / 2 - g.minY * scale,
  };
}

/** The original's move letters: left draws or clears, right crosses out or clears. */
function moveChar(current: number, button: number): string {
  if (button === MIDDLE_BUTTON || current !== LINE_UNKNOWN) return 'u';
  return button === LEFT_BUTTON ? 'y' : 'n';
}

function withLines(state: LoopyState, lines: Uint8Array, cheated: boolean): LoopyState {
  const c = checkCompletion(state.grid, state.clues, lines);
  return {
    ...state,
    lines,
    lineErr: c.lineErr,
    inside: c.inside,
    solved: state.solved || c.solved,
    cheated: state.cheated || cheated,
  };
}

const game = defineGame<LoopyParams, LoopyState, LoopyUI>({
  id: 'loopy',
  name: 'Loopy',
  description: 'Draw a single closed loop so each number counts the lines around it.',
  alsoKnownAs: 'Slitherlink',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [7, 7, DIFF_EASY, 0],
      [10, 10, DIFF_EASY, 0],
      [7, 7, DIFF_NORMAL, 0],
      [10, 10, DIFF_NORMAL, 0],
      [7, 7, DIFF_HARD, 0],
      [10, 10, DIFF_HARD, 0],
      [10, 10, DIFF_HARD, 1],
      [12, 10, DIFF_HARD, 2],
      [7, 7, DIFF_HARD, 3],
      [9, 9, DIFF_HARD, 4],
      [5, 4, DIFF_HARD, 5],
      [7, 7, DIFF_HARD, 6],
      [5, 5, DIFF_HARD, 7],
      [5, 5, DIFF_HARD, 8],
      [5, 4, DIFF_HARD, 9],
      [5, 4, DIFF_HARD, 10],
      [10, 10, DIFF_HARD, 11],
      [10, 10, DIFF_HARD, 12],
    ] as [number, number, number, number][]
  ).map(([w, h, difficulty, type]) => ({
    name: `${w}×${h} ${GRID_TYPES[type].name} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, type, difficulty },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}t${p.type}${full ? `d${DIFFICULTY_CHARS[p.difficulty] ?? 'e'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:t(\d+))?(?:d(.))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    const type = m[3] ? parseInt(m[3], 10) : 0;
    const d = m[4] ? DIFFICULTY_CHARS.indexOf(m[4]) : -1;
    return { w, h, type, difficulty: d >= 0 ? d : DIFF_EASY };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.type, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.type < 0 || p.type >= GRID_TYPES.length) return tx`Illegal grid type`;
    const info = GRID_TYPES[p.type];
    if (p.w < info.amin || p.h < info.amin)
      return tx`Width and height for this grid type must both be at least ${info.amin}`;
    if (p.w < info.omin && p.h < info.omin)
      return tx`At least one of width and height for this grid type must be at least ${info.omin}`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.w * p.h * info.density > MAX_FACES) return tx`That grid has too many faces to generate`;
    if (full && (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty level`;
    if (full && p.type === GRID_DODECAGONAL && dodecagonalUnsolvable(p.w, p.h, p.difficulty))
      return tx`Unable to generate a puzzle with these parameters`;
    if (full && p.type !== GRID_PENROSE_P2 && p.type !== GRID_PENROSE_P3) {
      const g = getGrid(p.type, p.w, p.h, defaultGridDesc(p.type));
      if (g && g.ne > MAX_EDGES[p.difficulty]) return tx`That grid has too many faces to generate`;
    }
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      {
        type: 'choices',
        name: 'Grid type',
        choices: GRID_TYPES.map((t) => t.name),
        selected: p.type,
      },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => (/^-?\d+$/.test(str(i)) ? parseInt(str(i), 10) : NaN);
    const sel = (i: number) => (items[i] as { selected: number }).selected;
    return { w: int(0), h: int(1), type: sel(2), difficulty: sel(3) };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const { gridDesc, clueDesc } = splitDesc(desc);
    const err = validateGridDesc(p.type, p.w, p.h, gridDesc);
    if (err) return err;
    const g = getGrid(p.type, p.w, p.h, gridDesc);
    if (!g) return tx`Unable to build this grid`;
    const clues = parseClues(clueDesc, g.nf);
    if (typeof clues === 'string') return clues;
    for (let f = 0; f < g.nf; f++) {
      if (clues[f] > g.faceEdges[f].length)
        return tx`Clue is larger than the number of sides of its face`;
    }
    return null;
  },

  newGame(p, desc) {
    const { gridDesc, clueDesc } = splitDesc(desc);
    const grid = getGrid(p.type, p.w, p.h, gridDesc)!;
    const clues = parseClues(clueDesc, grid.nf) as Int8Array;
    return {
      w: p.w,
      h: p.h,
      type: p.type,
      grid,
      clues,
      lines: new Uint8Array(grid.ne),
      lineErr: new Uint8Array(grid.ne),
      inside: null,
      solved: false,
      cheated: false,
    };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const g = curr.grid;
    let lines: Uint8Array | null = null;
    if (aux !== undefined) {
      const l = decodeLines(aux, g.ne);
      if (l && checkCompletion(g, curr.clues, l).solved) lines = l;
    }
    if (!lines) {
      const r = solveFresh(g, curr.clues, DIFF_MAX);
      if (r.status === SOLVER_MISTAKE) throw new Error(tx`This puzzle is not self-consistent`);
      if (r.status === SOLVER_SOLVED || r.status === SOLVER_AMBIGUOUS) lines = r.lines;
      else lines = solveWithGuessing(g, curr.clues, new Uint8Array(g.ne));
      if (!lines || !checkCompletion(g, curr.clues, lines).solved)
        throw new Error(tx`Unable to find a solution to this puzzle`);
    }
    // Draw the loop and rub out wrong lines; crosses (right or wrong) are left alone,
    // and nothing else is crossed out, so the finished picture is just the loop.
    let move = 'S';
    for (let e = 0; e < g.ne; e++) {
      if (lines[e] === LINE_YES) {
        if (curr.lines[e] !== LINE_YES) move += `${e}y`;
      } else if (curr.lines[e] === LINE_YES) {
        move += `${e}u`;
      }
    }
    return move;
  },

  textFormat(s) {
    const g = s.grid;
    if (s.type !== GRID_SQUARE) {
      return `${GRID_TYPES[s.type].name} ${s.w}×${s.h}: ${g.nf} faces, ${g.ne} edges`;
    }
    // Squares: a character grid with dots at corners, clues in cells and lines between.
    const cell = Math.abs(g.dotX[g.faceDots[0][0]] - g.dotX[g.faceDots[0][2]]);
    const w = Math.round((g.maxX - g.minX) / cell);
    const h = Math.round((g.maxY - g.minY) / cell);
    const W = 2 * w + 1;
    const rows: string[][] = [];
    for (let y = 0; y < 2 * h + 1; y++) rows.push(new Array<string>(W).fill(' '));
    const cx = (x: number) => Math.round((x - g.minX) / cell);
    const cy = (y: number) => Math.round((y - g.minY) / cell);
    for (let d = 0; d < g.nd; d++) rows[2 * cy(g.dotY[d])][2 * cx(g.dotX[d])] = '+';
    for (let e = 0; e < g.ne; e++) {
      const x1 = cx(g.dotX[g.edgeDot1[e]]);
      const x2 = cx(g.dotX[g.edgeDot2[e]]);
      const y1 = cy(g.dotY[g.edgeDot1[e]]);
      const y2 = cy(g.dotY[g.edgeDot2[e]]);
      const v = s.lines[e];
      rows[y1 + y2][x1 + x2] = v === LINE_YES ? (y1 === y2 ? '-' : '|') : v === LINE_NO ? 'x' : ' ';
    }
    for (let f = 0; f < g.nf; f++) {
      const c = s.clues[f];
      if (c === NO_CLUE) continue;
      const fd = g.faceDots[f];
      const x = cx(g.dotX[fd[0]]) + cx(g.dotX[fd[2]]);
      const y = cy(g.dotY[fd[0]]) + cy(g.dotY[fd[2]]);
      rows[y][x] = String(c);
    }
    return rows.map((r) => r.join('')).join('\n');
  },

  newUI: () => ({ cursor: -1, cursorVisible: false, cross: false }),

  actions: [
    {
      label: 'Cross',
      key: 'X',
      hud: true,
      glyph: CROSS_GLYPH,
      pressed: (_s, ui) => ui.cross,
      title: 'Clicks cross edges out instead of drawing lines (X)',
    },
  ],
  changedState(ui, _old, next) {
    if (next.solved) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const g = state.grid;
    let e: number;
    let ch: string;
    if (b === 'x'.charCodeAt(0) || b === 'X'.charCodeAt(0)) {
      ui.cross = !ui.cross;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || b === MIDDLE_BUTTON) {
      const geo = geometry(state, ds.tileSize);
      e = nearestEdge(g, (mx - geo.ox) / geo.scale, (my - geo.oy) / geo.scale);
      const hadCursor = ui.cursorVisible;
      ui.cursorVisible = false;
      if (e < 0) return hadCursor ? '' : null;
      ch = moveChar(state.lines[e], b === LEFT_BUTTON && ui.cross ? RIGHT_BUTTON : b);
    } else if (isCursorSelect(b)) {
      if (ui.cursor < 0) ui.cursor = centralEdge(g);
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      e = ui.cursor;
      ch = moveChar(state.lines[e], b === CURSOR_SELECT2 ? RIGHT_BUTTON : LEFT_BUTTON);
    } else if (isCursorMove(b)) {
      if (ui.cursor < 0) ui.cursor = centralEdge(g);
      if (ui.cursorVisible) {
        const dx = b === CURSOR_LEFT ? -1 : b === CURSOR_RIGHT ? 1 : 0;
        const dy = b === CURSOR_DOWN ? 1 : b === CURSOR_LEFT || b === CURSOR_RIGHT ? 0 : -1;
        ui.cursor = stepEdge(g, ui.cursor, dx, dy);
      }
      ui.cursorVisible = true;
      return '';
    } else {
      return null;
    }
    return `${e}${ch}`;
  },

  executeMove(state, move) {
    const m = /^(S?)((?:\d+[ynu])*)$/.exec(move);
    if (!m || move === '') return null;
    const lines = state.lines.slice();
    const re = /(\d+)([ynu])/g;
    let r: RegExpExecArray | null;
    while ((r = re.exec(m[2]))) {
      const e = parseInt(r[1], 10);
      if (e >= state.grid.ne) return null;
      lines[e] = r[2] === 'y' ? LINE_YES : r[2] === 'n' ? LINE_NO : LINE_UNKNOWN;
    }
    // Middle-clicking an edge that is already undecided changes nothing: keep it from
    // becoming an Undo step that does nothing.
    if (!m[1] && lines.every((v, i) => v === state.lines[i])) return state;
    return withLines(state, lines, m[1] === 'S');
  },

  preferredTileSize: 36,
  computeSize(p, t) {
    return canvasSize(p.type, p.w, p.h, t);
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const g = state.grid;
    const t = ds.tileSize;
    const { scale, ox, oy } = geometry(state, t);
    const X = (x: number) => ox + x * scale;
    const Y = (y: number) => oy + y * scale;
    const flash = flashOn(flashTime, FLASH_FRAME);
    const { lines, lineErr, clues } = state;

    // A wash over the inside of a finished loop (blinking during the flash).
    if (state.inside && (flashTime <= 0 || flash)) {
      for (let f = 0; f < g.nf; f++) {
        if (!state.inside[f]) continue;
        const pts: number[] = [];
        for (const d of g.faceDots[f]) pts.push(X(g.dotX[d]), Y(g.dotY[d]));
        dr.polygon(pts, 'shade', null, { rough: 0 });
      }
    }

    const x1 = (e: number) => X(g.dotX[g.edgeDot1[e]]);
    const y1 = (e: number) => Y(g.dotY[g.edgeDot1[e]]);
    const x2 = (e: number) => X(g.dotX[g.edgeDot2[e]]);
    const y2 = (e: number) => Y(g.dotY[g.edgeDot2[e]]);

    // Undecided and crossed-out edges: faint; crosses at the midpoints of the latter.
    const faintW = Math.max(1, t * 0.035);
    for (let e = 0; e < g.ne; e++) {
      if (lines[e] !== LINE_YES) dr.line(x1(e), y1(e), x2(e), y2(e), 'faint', faintW);
    }
    const crossR = Math.max(2.5, t * 0.09);
    const crossW = Math.max(1.2, t * 0.04);
    for (let e = 0; e < g.ne; e++) {
      if (lines[e] !== LINE_NO) continue;
      dr.cross((x1(e) + x2(e)) / 2, (y1(e) + y2(e)) / 2, crossR, 'pencil', crossW, { seed: e });
    }
    // The loop. An edge the player has just drawn grows out from its middle, where their
    // cursor was, rather than appearing whole; rubbing one out runs the stroke backwards,
    // and so does an undo.
    const lw = Math.max(2.6, t * 0.1);
    const drawn = oldState ? changedAt(oldState.lines, lines) : null;
    const growing = new Set(drawn ?? []);
    const grow = drawGrow(animTime);
    for (let e = 0; e < g.ne; e++) {
      const here = lines[e] === LINE_YES;
      const there = growing.has(e) && oldState!.lines[e] === LINE_YES;
      if (!here && !there) continue;
      const colour = lineErr[e] ? 'error' : flash ? 'ok' : 'ink';
      const gr = growing.has(e) ? (here ? grow : 1 - grow) : 1;
      if (gr <= 0) continue;
      const seg = growSegment(x1(e), y1(e), x2(e), y2(e), gr);
      dr.line(seg.x1, seg.y1, seg.x2, seg.y2, colour, lw);
    }
    // Dots at every vertex.
    const dotR = Math.max(1.4, t * 0.05);
    for (let d = 0; d < g.nd; d++) dr.dot(X(g.dotX[d]), Y(g.dotY[d]), dotR, 'ink');

    // Clues, sized to the room in their face; grey once satisfied, red when broken.
    for (let f = 0; f < g.nf; f++) {
      const c = clues[f];
      if (c === NO_CLUE) continue;
      const yes = faceCount(g, lines, f, LINE_YES);
      const no = faceCount(g, lines, f, LINE_NO);
      const order = g.faceEdges[f].length;
      const colour = yes > c || no > order - c ? 'error' : yes === c ? 'pencil' : 'ink';
      const room = g.faceR[f] * scale;
      dr.text(X(g.faceCX[f]), Y(g.faceCY[f]), String(c), {
        size: Math.min(t * 0.55, Math.max(t * 0.3, room * 1.6)),
        colour,
        maxWidth: room * 1.8,
      });
    }

    if (ui.cursorVisible && ui.cursor >= 0) {
      const e = ui.cursor;
      const pad = t * 0.14;
      const lx = Math.min(x1(e), x2(e)) - pad;
      const ly = Math.min(y1(e), y2(e)) - pad;
      dr.cursor(lx, ly, Math.abs(x2(e) - x1(e)) + 2 * pad, Math.abs(y2(e) - y1(e)) + 2 * pad);
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.lines, newState.lines) ? DRAW_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.solved && newState.solved && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.solved ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,

  /** Half of the loop of the puzzle the menu renders (seed `thumbnail:loopy`). */
  thumbnailMoves: [
    [
      0, 1, 6, 5, 7, 8, 12, 29, 44, 47, 46, 31, 18, 17, 19, 20, 35, 36, 48, 51, 65, 66, 64, 76, 79,
      93, 108, 109,
    ]
      .map((e) => `${e}y`)
      .join(''),
  ],
});

export default game;
