/**
 * Slant puzzle generation.
 *
 * A filled grid is made by visiting the squares in random order and choosing a random
 * diagonal for each, except where one of the two would close a loop through the points
 * already joined (tracked with a disjoint-set forest). Both can never be blocked at
 * once: the two blocking paths would have to cross, and diagonal paths only ever visit
 * grid points of one chessboard colour.
 *
 * Every grid point is then numbered, and clues are removed one at a time while the
 * solver of the requested difficulty still completes the grid. At Hard the obvious
 * starting points (4s, 0s, 2s on the border and 1s in the corners) are tried first so
 * that as few as possible survive. Finally a Hard puzzle must defeat the Easy solver,
 * otherwise a new grid is tried.
 */
import type { Random } from '../../framework/rng';
import { DSF } from '../../framework/dsf';
import { BACK, FORWARD, NO_CLUE, computeClues, encodeDesc, encodeSolution } from './board';
import { DIFF_EASY, SOLVE_SOLVED, Scratch, solve } from './solver';

export interface SlantParams {
  w: number;
  h: number;
  difficulty: number;
}

/** A random loop-free arrangement of diagonals. */
export function fillGrid(w: number, h: number, rng: Random): Int8Array {
  const W = w + 1;
  const soln = new Int8Array(w * h);
  const connected = new DSF(W * (h + 1));
  const order: number[] = [];
  for (let i = 0; i < w * h; i++) order.push(i);
  rng.shuffle(order);
  for (const i of order) {
    const x = i % w;
    const y = Math.floor(i / w);
    const tl = y * W + x;
    const tr = y * W + x + 1;
    const bl = (y + 1) * W + x;
    const br = (y + 1) * W + x + 1;
    // A `\` would join tl–br; it is forbidden if they are already connected.
    const needForward = connected.same(tl, br);
    const needBack = connected.same(tr, bl);
    const v = needForward ? FORWARD : needBack ? BACK : rng.upto(2) ? FORWARD : BACK;
    soln[i] = v;
    if (v === BACK) connected.merge(tl, br);
    else connected.merge(tr, bl);
  }
  return soln;
}

/** An obvious place to start solving: a 4, a 0, a 2 on the border or a 1 in a corner. */
function isObviousStart(x: number, y: number, W: number, H: number, v: number): boolean {
  const xb = x === 0 || x === W - 1;
  const yb = y === 0 || y === H - 1;
  return v === 4 || v === 0 || (v === 2 && (xb || yb)) || (v === 1 && xb && yb);
}

/**
 * Strip clues from `clues` in `order` while the puzzle stays solvable at `difficulty`.
 * Two passes: obvious starting points first (all clues at Easy), then the rest.
 */
function reduceClues(
  w: number,
  h: number,
  clues: Int8Array,
  order: number[],
  difficulty: number,
  sc: Scratch,
  tmp: Int8Array,
): void {
  const W = w + 1;
  const H = h + 1;
  for (let pass = 0; pass < 2; pass++) {
    for (const i of order) {
      const v = clues[i];
      if (v === NO_CLUE) continue;
      const x = i % W;
      const y = Math.floor(i / W);
      const first = difficulty === DIFF_EASY || isObviousStart(x, y, W, H, v);
      if ((first ? 0 : 1) !== pass) continue;
      clues[i] = NO_CLUE;
      if (solve(w, h, clues, tmp, difficulty, sc) !== SOLVE_SOLVED) clues[i] = v;
    }
  }
}

/** Generate a puzzle description plus its solution (as `aux`). */
export function generate(params: SlantParams, rng: Random): { desc: string; aux: string } {
  const { w, h, difficulty } = params;
  const W = w + 1;
  const H = h + 1;
  const sc = new Scratch(w, h);
  const tmp = new Int8Array(w * h);
  const order: number[] = [];
  for (let i = 0; i < W * H; i++) order.push(i);
  for (;;) {
    const soln = fillGrid(w, h, rng);
    const clues = computeClues(w, h, soln);
    rng.shuffle(order);
    reduceClues(w, h, clues, order, difficulty, sc, tmp);
    // A Hard puzzle must actually need Hard reasoning.
    if (difficulty > DIFF_EASY && solve(w, h, clues, tmp, difficulty - 1, sc) === SOLVE_SOLVED)
      continue;
    return { desc: encodeDesc(clues), aux: encodeSolution(soln) };
  }
}
