/**
 * The first second: the loading screen, and knowing when the first screen is really there.
 *
 * Every game is in one script of well over a megabyte, and until it has arrived and run
 * there is nothing to draw with. `index.html` therefore carries a screen of its
 * own, `#boot` — bare paper with a pencil line writing itself — so a slow connection
 * sees the game loading rather than a blank white page (its colours are the palette's,
 * written in at build time by the plugin in vite.config.ts). The splash takes over from
 * it on the same paper; where there is no splash (a portal's frame, a link straight into
 * a puzzle) it stays up until the page under it is drawn, and fades.
 *
 * "Drawn" is {@link firstScreenReady}: the two hand-lettered faces loaded, and every
 * picture on screen — the menu's previews, the board — painted, so nothing pops in, swaps
 * its font or fills an empty frame after the curtain has gone. It never waits for ever:
 * a screen that is not ready in {@link READY_CAP_MS} is shown as it is.
 */

import { handFontReady } from './fonts';

/** The longest the first screen is held back for, however slow the pictures are. */
export const READY_CAP_MS = 2500;

/** The caps face the titles and the wordmark use; `fonts.ts` asks for the body face. */
const CAPS_PROBE = '20px "Patrick Hand SC"';

let capsWaiting: Promise<void> | null = null;

/** Both faces the shell draws with, or {@link READY_CAP_MS}, whichever comes first. */
export function fontsReady(capMs = READY_CAP_MS): Promise<void> {
  capsWaiting ??= new Promise<void>((resolve) => {
    try {
      const fonts = typeof document !== 'undefined' ? document.fonts : undefined;
      if (!fonts || typeof fonts.load !== 'function') return resolve();
      fonts.load(CAPS_PROBE).then(
        () => resolve(),
        () => resolve(),
      );
    } catch {
      resolve();
    }
  });
  return Promise.race([
    Promise.all([capsWaiting, handFontReady()]).then(() => undefined),
    new Promise<void>((r) => setTimeout(r, capMs)),
  ]);
}

/** The canvases the player can see right now: previews on screen and the board. */
function visibleCanvases(): HTMLCanvasElement[] {
  const root = document.getElementById('app');
  if (!root) return [];
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  return [...root.querySelectorAll('canvas')].filter((c) => {
    if (c.closest('.off-page, [hidden]')) return false;
    const r = c.getBoundingClientRect();
    return r.bottom > 0 && r.right > 0 && r.top < vh && r.left < vw;
  });
}

/** How much of the first screen is drawn, 0 to 1. A canvas is drawn once it has a size. */
export function firstScreenProgress(): number {
  const all = visibleCanvases();
  if (!all.length) return 1;
  return all.filter((c) => c.width > 1 && c.height > 1).length / all.length;
}

/**
 * Resolves once the first screen is drawn (see the module comment) or after `capMs`.
 * `onProgress` hears how far it has got, once a frame, for a loading mark.
 */
export function firstScreenReady(
  capMs = READY_CAP_MS,
  onProgress?: (fraction: number) => void,
): Promise<void> {
  const until = performance.now() + capMs;
  return fontsReady(capMs).then(
    () =>
      new Promise<void>((resolve) => {
        const tick = () => {
          const p = firstScreenProgress();
          onProgress?.(p);
          // One more frame after the last picture lands, so it is on screen, not queued.
          if (p >= 1 || performance.now() >= until) requestAnimationFrame(() => resolve());
          else requestAnimationFrame(tick);
        };
        tick();
      }),
  );
}

function bootScreen(): HTMLElement | null {
  return typeof document !== 'undefined' ? document.getElementById('boot') : null;
}

/** Take the loading screen away at once: something on the same paper is already over it. */
export function dropBootScreen(): void {
  bootScreen()?.remove();
}

/** Fade the loading screen off the page once the first screen is drawn. */
export function liftBootScreenWhenReady(): void {
  const boot = bootScreen();
  if (!boot) return;
  let lifted = false;
  const lift = () => {
    if (lifted) return;
    lifted = true;
    document.removeEventListener('pointerdown', lift, true);
    document.removeEventListener('keydown', lift, true);
    boot.classList.add('lifting');
    // The fade is the stylesheet's (index.html); a reduced-motion one is instant.
    const gone = () => boot.remove();
    boot.addEventListener('transitionend', gone, { once: true });
    window.setTimeout(gone, 600);
  };
  // Like the splash, it is `pointer-events: none` and never eats a press — and a press
  // says the player would rather see the page now, drawn or not.
  document.addEventListener('pointerdown', lift, true);
  document.addEventListener('keydown', lift, true);
  void firstScreenReady().then(lift);
}
