/**
 * Signpost board logic shared by the game, the solver and the generator: the eight
 * arrow directions, the description format, the link structure and the numbering of
 * chains (real numbers where a chain contains a given, letters like `a`, `a+1` where it
 * does not).
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

/** Directions clockwise from north, matching the description letters `a`..`h`. */
export const DX: readonly number[] = [0, 1, 1, 1, 0, -1, -1, -1];
export const DY: readonly number[] = [-1, -1, 0, 1, 1, 1, 0, -1];
export const DIR_NAMES: readonly string[] = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];

export function opposite(d: number): number {
  return (d + 4) % 8;
}

/** The direction from (fx, fy) to (tx, ty) if they share a row, column or diagonal, else -1. */
export function whichDir(fx: number, fy: number, tx: number, ty: number): number {
  const dx = tx - fx;
  const dy = ty - fy;
  if (dx === 0 && dy === 0) return -1;
  if (dx !== 0 && dy !== 0 && Math.abs(dx) !== Math.abs(dy)) return -1;
  const sx = Math.sign(dx);
  const sy = Math.sign(dy);
  for (let d = 0; d < 8; d++) if (DX[d] === sx && DY[d] === sy) return d;
  return -1;
}

/** The fixed part of a puzzle: every square's arrow plus the given numbers (0 = none). */
export interface Puzzle {
  w: number;
  h: number;
  n: number;
  dirs: number[];
  given: number[];
}

/**
 * Parse a description: one entry per square, row by row, each an optional number
 * followed by a direction letter `a` (north) to `h` (north-west).
 */
export function parseDesc(desc: string, w: number, h: number): Puzzle | string {
  const n = w * h;
  const dirs: number[] = [];
  const given: number[] = [];
  let num = 0;
  let digits = false;
  for (let k = 0; k < desc.length; k++) {
    const c = desc.charCodeAt(k);
    if (c >= 48 && c <= 57) {
      num = num * 10 + (c - 48);
      digits = true;
      if (num > n) return tx`Number too large`;
    } else if (c >= 97 && c < 97 + 8) {
      if (dirs.length >= n) return tx`Game description longer than expected`;
      dirs.push(c - 97);
      given.push(num);
      num = 0;
      digits = false;
    } else {
      return tx`Game description contains unexpected characters`;
    }
  }
  if (digits) return tx`Game description longer than expected`;
  if (dirs.length < n) return tx`Game description shorter than expected`;
  const seen = new Uint8Array(n + 1);
  for (const g of given) {
    if (g === 0) continue;
    if (seen[g]) return tx`Description contains a repeated number`;
    seen[g] = 1;
  }
  return { w, h, n, dirs, given };
}

/** Encode arrows and numbers (only values 1..n are written) as a description. */
export function encodeDesc(dirs: readonly number[], nums: readonly number[]): string {
  const n = dirs.length;
  let s = '';
  for (let i = 0; i < n; i++) {
    if (nums[i] >= 1 && nums[i] <= n) s += String(nums[i]);
    s += String.fromCharCode(97 + dirs[i]);
  }
  return s;
}

/**
 * The text shown for a numbering value: real numbers as digits; chain labels as a
 * letter plus offset (`a`, `a+1`, ..., `b`, ...). Values outside both ranges (a chain
 * that overshoots its given number) are shown raw.
 */
export function labelFor(num: number, n: number): string {
  if (num <= n) return String(num);
  let set = Math.floor(num / (n + 1));
  const off = num % (n + 1);
  let s = '';
  do {
    set--;
    s = String.fromCharCode(97 + (set % 26)) + s;
    set = Math.floor(set / 26);
  } while (set > 0);
  return off ? `${s}+${off}` : s;
}

interface Head {
  i: number;
  size: number;
  start: number;
  /** 1 = has a preferred start, 0 = take any free letter, -1 = recoloured duplicate. */
  pref: number;
  /** The start came from a given number, so the chain carries real numbers. */
  real: boolean;
}

/**
 * A mutable working board. `nums[i]` is 0 for a blank square, 1..n for a real number
 * (given or deduced) and `set * (n + 1) + offset` for a square in an unnumbered chain
 * labelled with letter `set`. Values outside those ranges arise only from chains that
 * run past 1 or n and are flagged as errors.
 */
export class Board {
  readonly w: number;
  readonly h: number;
  readonly n: number;
  readonly dirs: number[];
  readonly immutable: Uint8Array;
  /** The squares along each square's arrow, nearest first. */
  readonly rays: number[][];
  nums: number[];
  next: Int32Array;
  prev: Int32Array;
  /** Which square holds each real number, or -1. */
  numsi: Int32Array;
  dsf: DSF;
  error: Uint8Array;
  /** A chain contains givens that disagree, or the links form a loop. */
  impossible = false;
  /** Squares whose chain runs past n or contradicts itself; refreshed by updateNumbers. */
  private chainError: Uint8Array;

  constructor(puzzle: Puzzle, immutable?: ArrayLike<number>, rays?: number[][]) {
    const { w, h, n } = puzzle;
    this.w = w;
    this.h = h;
    this.n = n;
    this.dirs = puzzle.dirs;
    this.immutable = new Uint8Array(n);
    this.nums = new Array<number>(n).fill(0);
    for (let i = 0; i < n; i++) {
      const keep = immutable ? immutable[i] !== 0 : puzzle.given[i] > 0;
      if (keep && puzzle.given[i] > 0) {
        this.immutable[i] = 1;
        this.nums[i] = puzzle.given[i];
      }
    }
    if (rays) {
      this.rays = rays;
    } else {
      this.rays = [];
      for (let i = 0; i < n; i++) {
        const ray: number[] = [];
        let x = (i % w) + DX[this.dirs[i]];
        let y = Math.floor(i / w) + DY[this.dirs[i]];
        while (x >= 0 && y >= 0 && x < w && y < h) {
          ray.push(y * w + x);
          x += DX[this.dirs[i]];
          y += DY[this.dirs[i]];
        }
        this.rays.push(ray);
      }
    }
    this.next = new Int32Array(n).fill(-1);
    this.prev = new Int32Array(n).fill(-1);
    this.numsi = new Int32Array(n + 1).fill(-1);
    this.dsf = new DSF(n);
    this.error = new Uint8Array(n);
    this.chainError = new Uint8Array(n);
  }

  /** Rebuild a board from stored arrays (a game state) and bring its bookkeeping up to date. */
  static from(
    puzzle: Puzzle,
    immutable: ArrayLike<number>,
    nums: ArrayLike<number>,
    next: ArrayLike<number>,
    prev: ArrayLike<number>,
  ): Board {
    const b = new Board(puzzle, immutable);
    for (let i = 0; i < b.n; i++) {
      b.nums[i] = nums[i];
      b.next[i] = next[i];
      b.prev[i] = prev[i];
    }
    b.updateNumbers();
    return b;
  }

  /** An independent copy sharing only the fixed arrows and rays. */
  clone(): Board {
    const puzzle: Puzzle = { w: this.w, h: this.h, n: this.n, dirs: this.dirs, given: this.nums };
    const c = new Board(puzzle, this.immutable, this.rays);
    for (let i = 0; i < this.n; i++) c.nums[i] = this.nums[i];
    c.next.set(this.next);
    c.prev.set(this.prev);
    c.numsi.set(this.numsi);
    c.dsf = this.dsf.clone();
    c.error.set(this.error);
    c.chainError.set(this.chainError);
    c.impossible = this.impossible;
    return c;
  }

  isReal(v: number): boolean {
    return v >= 1 && v <= this.n;
  }

  hasLinks(i: number): boolean {
    return this.next[i] !== -1 || this.prev[i] !== -1;
  }

  /** Whether `from`'s arrow points at `to`. The square numbered n points at nothing. */
  isPointing(from: number, to: number): boolean {
    if (from === to || this.nums[from] === this.n) return false;
    return this.rays[from].includes(to);
  }

  /**
   * Whether the chain containing square `i` fits in the run of missing numbers next to
   * `num` (above it for d = 1, below for d = -1).
   */
  couldFit(num: number, d: number, i: number): boolean {
    let gap = 0;
    for (let k = num + d; this.isReal(k) && this.numsi[k] === -1; k += d) gap++;
    // No gap: the neighbouring number is already placed, so only it may be linked.
    if (gap === 0) return this.nums[i] === num + d;
    if (!this.hasLinks(i)) return true;
    return this.dsf.sizeOf(i) <= gap;
  }

  /**
   * Whether linking `from` to `to` is allowed. `clever` adds the solver's tighter
   * checks about numbered chains fitting between known numbers.
   */
  isValidMove(clever: boolean, from: number, to: number): boolean {
    const { n, nums, immutable } = this;
    if (from < 0 || to < 0 || from >= n || to >= n) return false;
    if (!this.isPointing(from, to)) return false;
    const nf = nums[from];
    const nt = nums[to];
    if ((nf === n && immutable[from]) || (nt === 1 && immutable[to])) return false;
    // Joining two squares of the same chain would close a loop.
    if (this.dsf.same(from, to)) return false;
    if (this.isReal(nf) && this.isReal(nt)) return nf === nt - 1;
    if (clever && this.isReal(nf)) return this.couldFit(nf, 1, to);
    if (clever && this.isReal(nt)) return this.couldFit(nt, -1, from);
    return true;
  }

  /** Link `from` to `to`, breaking whatever either end was linked to before. */
  link(from: number, to: number): void {
    if (this.next[from] !== -1) this.prev[this.next[from]] = -1;
    this.next[from] = to;
    if (this.prev[to] !== -1) this.next[this.prev[to]] = -1;
    this.prev[to] = from;
    // Keep the region forest usable between full rebuilds; it may over-approximate
    // after a broken link, which only ever forbids more moves.
    if (!this.dsf.same(from, to)) this.dsf.merge(from, to);
  }

  /** Remove both links of one square. */
  unlink(i: number): void {
    if (this.prev[i] !== -1) {
      this.next[this.prev[i]] = -1;
      this.prev[i] = -1;
    }
    if (this.next[i] !== -1) {
      this.prev[this.next[i]] = -1;
      this.next[i] = -1;
    }
  }

  /** Remove every link of the chain containing `i`. */
  unlinkChain(i: number): void {
    const root = this.dsf.find(i);
    for (let j = 0; j < this.n; j++) if (this.dsf.find(j) === root) this.unlink(j);
  }

  private colour(v: number): number {
    return Math.floor(v / (this.n + 1));
  }

  private start(c: number): number {
    return c * (this.n + 1);
  }

  private headMeta(i: number): Head {
    const { nums, next, immutable, n } = this;
    const head: Head = { i, size: this.dsf.sizeOf(i), start: 0, pref: 0, real: false };
    // A chain with givens is numbered from them; they must agree.
    let off = 0;
    let bad = false;
    for (let j = i; j !== -1 && off <= n; j = next[j], off++) {
      if (!immutable[j]) continue;
      const ss = nums[j] - off;
      if (!head.pref) {
        head.start = ss;
        head.pref = 1;
        head.real = true;
      } else if (head.start !== ss) {
        bad = true;
      }
    }
    if (bad) {
      this.impossible = true;
      for (let j = i, k = 0; j !== -1 && k <= n; j = next[j], k++) this.chainError[j] = 1;
    }
    if (head.pref) return head;

    if (nums[i] === 0 && nums[next[i]] > n) {
      // A blank square was joined onto the front of a lettered chain: keep its letter.
      head.start = this.start(this.colour(nums[next[i]]));
      head.pref = 1;
    } else if (nums[i] <= n) {
      // Blank (or a chain that has just lost its given): any free letter will do.
      head.start = 0;
      head.pref = 0;
    } else {
      const c = this.colour(nums[i]);
      let count = 1;
      for (let j = next[i], k = 0; j !== -1 && k <= n; j = next[j], k++) {
        if (nums[j] === 0 && next[j] === -1) {
          // A blank square was joined onto the end: keep the letter.
          head.start = this.start(c);
          head.pref = 1;
          return head;
        }
        const cj = this.colour(nums[j]);
        if (cj === c || cj === 0) {
          count++;
          continue;
        }
        // Two lettered chains were joined: the larger one's letter wins.
        head.start = this.start(count < head.size - count ? cj : c);
        head.pref = 1;
        return head;
      }
      head.start = this.start(c);
      head.pref = 1;
    }
    return head;
  }

  private lowestFreeColour(heads: Head[]): number {
    for (let c = 1; c < this.n; c++) {
      if (!heads.some((h) => this.colour(h.start) === c)) return c;
    }
    return this.n;
  }

  /**
   * Recompute every square's number or label from the links and the given numbers.
   * Chains containing a given carry real numbers; other chains are lettered, keeping
   * their previous letter where possible so labels stay put as the player works.
   */
  updateNumbers(): void {
    const { n, nums, next, prev, immutable, numsi } = this;
    numsi.fill(-1);
    this.chainError.fill(0);
    this.impossible = false;
    for (let i = 0; i < n; i++) {
      if (immutable[i]) numsi[nums[i]] = i;
      else if (prev[i] === -1 && next[i] === -1) nums[i] = 0;
    }
    // Regions, detecting loops (which have no head and keep their old labels).
    this.dsf = new DSF(n);
    for (let i = 0; i < n; i++) {
      if (next[i] === -1) continue;
      if (this.dsf.same(i, next[i])) {
        this.impossible = true;
        const root = this.dsf.find(i);
        for (let j = 0; j < n; j++) if (this.dsf.find(j) === root) this.chainError[j] = 1;
        continue;
      }
      this.dsf.merge(i, next[i]);
    }

    const heads: Head[] = [];
    for (let i = 0; i < n; i++) if (prev[i] === -1 && next[i] !== -1) heads.push(this.headMeta(i));
    // Preferred starts first, then low starts, then big chains, then position.
    heads.sort((a, b) => {
      if (!!a.pref !== !!b.pref) return a.pref ? -1 : 1;
      if (a.start !== b.start) return a.start - b.start;
      if (a.size !== b.size) return b.size - a.size;
      return b.i - a.i;
    });
    // Give duplicated letters and unpreferred chains fresh letters, smallest chain first.
    for (let k = heads.length - 1; k >= 0; k--) {
      if (k > 0 && heads[k].start === heads[k - 1].start) {
        heads[k].start = this.start(this.lowestFreeColour(heads));
        heads[k].pref = -1;
        heads[k].real = false;
      } else if (!heads[k].pref) {
        heads[k].start = this.start(this.lowestFreeColour(heads));
      }
    }
    for (const head of heads) {
      let v = head.start;
      for (let j = head.i, k = 0; j !== -1 && k <= n; j = next[j], k++, v++) {
        if (immutable[j]) continue;
        if (this.isReal(v)) numsi[v] = j;
        else if (head.real && v > n) this.chainError[j] = 1;
        nums[j] = v;
      }
    }
  }

  /**
   * Check the numbering. Repeated numbers, numbers whose successor is not along their
   * arrow, chains that overshoot, and loops are errors. With `mark`, error flags are
   * refreshed and consecutive numbers that point at each other are linked up. Returns
   * whether the puzzle is complete and whether any links were added.
   */
  checkCompletion(mark: boolean): { complete: boolean; linked: boolean } {
    const { n, nums, numsi, next, prev, error } = this;
    if (mark) error.fill(0);
    let bad = this.impossible;
    const count = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) if (this.isReal(nums[i])) count[nums[i]]++;
    for (let i = 0; i < n; i++) {
      const dup = this.isReal(nums[i]) && count[nums[i]] > 1;
      const stray = nums[i] < 0 || (nums[i] === 0 && (next[i] !== -1 || prev[i] !== -1));
      if (dup || stray || this.chainError[i]) {
        bad = true;
        if (mark) error[i] = 1;
      }
    }
    let complete = true;
    let linked = false;
    for (let k = 1; k < n; k++) {
      const a = numsi[k];
      const b = numsi[k + 1];
      if (a === -1 || b === -1) {
        complete = false;
      } else if (!this.isPointing(a, b)) {
        bad = true;
        if (mark) {
          error[a] = 1;
          error[b] = 1;
        }
      } else if (mark && next[a] !== b) {
        this.link(a, b);
        linked = true;
      }
    }
    return { complete: complete && !bad, linked };
  }

  /** Bring numbers, auto-links and error flags up to date after links changed. */
  settle(): boolean {
    for (let guard = 0; ; guard++) {
      this.updateNumbers();
      const r = this.checkCompletion(true);
      if (!r.linked || guard > this.n) return r.complete;
    }
  }
}
