import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
// A cycle with `./index`, which imports this list; safe, because the constants are only
// read inside `test`, long after both modules have finished loading.
import { COVERED, FLAG, type MinesParams, type MinesState } from './index';

type C = typeof PALETTE;

/** A round mine with its spikes and a highlight: the game's own glyph, badge-sized. */
function mine(c: C, cx: number, cy: number, r: number): string {
  let spikes = '';
  for (let i = 0; i < 8; i++) {
    const a = (i * Math.PI) / 4;
    const x1 = cx + Math.cos(a) * r * 0.8;
    const y1 = cy + Math.sin(a) * r * 0.8;
    const x2 = cx + Math.cos(a) * r * 1.45;
    const y2 = cy + Math.sin(a) * r * 1.45;
    spikes += `M${x1.toFixed(1)} ${y1.toFixed(1)} L${x2.toFixed(1)} ${y2.toFixed(1)} `;
  }
  return (
    `<path d="${spikes}" stroke="${c.ink}" stroke-width="${(r * 0.32).toFixed(1)}" stroke-linecap="round"/>` +
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.ink}"/>` +
    `<circle cx="${cx - r * 0.35}" cy="${cy - r * 0.35}" r="${r * 0.25}" fill="${c.highlight}"/>`
  );
}

function flag(c: C, x: number, y: number, s: number): string {
  return (
    `<path d="M${x} ${y + 30 * s} V${y}" stroke="${c.ink}" stroke-width="${5 * s}" stroke-linecap="round"/>` +
    `<path d="M${x} ${y} L${x + 22 * s} ${y + 8 * s} L${x} ${y + 16 * s} Z" fill="${c.red}" stroke="${c.ink}" stroke-width="${3.5 * s}" stroke-linejoin="round"/>` +
    `<path d="M${x - 10 * s} ${y + 32 * s} H${x + 10 * s}" stroke="${c.ink}" stroke-width="${5 * s}" stroke-linecap="round"/>`
  );
}

/** Safe squares still covered on a board that has just blown up. */
function safeLeft(s: MinesState): number {
  if (!s.mines) return Infinity;
  let n = 0;
  for (let i = 0; i < s.grid.length; i++) if (s.grid[i] === COVERED && !s.mines[i]) n++;
  return n;
}

export const achievements = defineAchievements<MinesParams, MinesState>([
  {
    id: 'no-flags',
    name: 'Flagless',
    description: 'Win a game of Mines without placing a single flag.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      flag(c, 42, 30, 1) +
      `<path d="M24 24 L76 76" stroke="${c.accent}" stroke-width="8" stroke-linecap="round"/>`,
    // The winning move flags every mine by itself, so look at the board before it.
    test: (ctx) => ctx.history.slice(0, -1).every((s) => !s.grid.includes(FLAG)),
  },
  {
    id: 'expert-sweep',
    name: 'Bomb Squad',
    description: 'Win the 30×16 Expert board in under five minutes.',
    tier: 'gold',
    hue: 'red',
    art: (c) => mine(c, 44, 54, 15) + flag(c, 64, 22, 0.8),
    test: (ctx) =>
      ctx.params.w === 30 && ctx.params.h === 16 && ctx.params.n >= 99 && ctx.secs < 300,
  },
  {
    id: 'so-close',
    name: 'So Close',
    description: 'Step on a mine with no more than three safe squares left to open.',
    tier: 'bronze',
    hidden: true,
    hue: 'orange',
    on: 'lose',
    art: (c) =>
      mine(c, 50, 52, 14) +
      `<path d="M26 30 l-8 -8 M74 30 l8 -8 M22 54 h-8 M78 54 h8" stroke="${c.orange}" stroke-width="5" stroke-linecap="round"/>`,
    test: (ctx) => safeLeft(ctx.state) <= 3,
  },
]);
