export interface SoloParams {
  /** Columns of blocks (or the grid size for jigsaw puzzles). */
  c: number;
  /** Rows of blocks; 1 means jigsaw mode. */
  r: number;
  symm: number;
  diff: number;
  /** Both main diagonals must also hold every digit. */
  xtype: boolean;
  killer: boolean;
}

export interface SoloState {
  cr: number;
  c: number;
  r: number;
  xtype: boolean;
  killer: boolean;
  blocks: BlockStructure;
  kblocks: BlockStructure | null;
  /** Killer sum clue in the first square of each cage, 0 elsewhere. */
  kgrid: Uint8Array | null;
  grid: Uint8Array;
  /** pencil[xy*cr + n-1] is set when digit n is pencilled into square xy. */
  pencil: Uint8Array;
  immutable: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface SoloUI extends HintMark {
  hx: number;
  hy: number;
  /** The highlight is shown. */
  hshow: boolean;
  /** Typed digits become pencil marks. */
  hpencil: boolean;
  /** The highlight was placed with the keyboard, so it stays after a digit is typed. */
  hcursor: boolean;
  /** A digit just went into the selected square: one click on it keeps it chosen. */
  hkept: boolean;
  /** The Highlight tool: every square holding the digit last pointed at is picked out. */
  spot: boolean;
  /** The square last clicked or moved to, whose digit Highlight picks out; -1 for none. */
  spotAt: number;
}

const FLASH = 0.4;
const SYMM_CODES = ['a', '', 'r4', 'm2', 'md2', 'm4', 'md4', 'm8'];
const SYMM_NAMES = [
  'None',
  '2-way rotation',
  '4-way rotation',
  '2-way mirror',
  '2-way diagonal mirror',
  '4-way mirror',
  '4-way diagonal mirror',
  '8-way mirror',
];
const DIFF_CODES = ['t', 'b', 'i', 'a', 'e', 'u'];
const MAX_SYMBOLS = 31;
const DEFAULTS: SoloParams = {
  c: 3,
  r: 3,
  symm: SYMM_ROT2,
  diff: DIFF_BLOCK,
  xtype: false,
  killer: false,
};
const MAX_GENERATE = 16;
/**
 * Irregular blocks make big grids hard to fill at all (a 16×16 jigsaw never came out in
 * minutes, and with the diagonals as well even 12×12 fails most of the time), and proving
 * an Extreme puzzle unique by trial and error grows steeply with size: a 16×16 Extreme
 * took up to 25 s, a 15×15 X-diagonal one several minutes.
 */
const MAX_GENERATE_JIGSAW = 12;
const MAX_GENERATE_JIGSAW_X = 10;
const MAX_GENERATE_EXTREME = 12;
/**
 * Techniques a hint tries, easiest first, so the square it gives away is one the player
 * had the best chance of spotting. Recursion is left out: a guess is not a hint.
 */
const HINT_DIFFS = [DIFF_BLOCK, DIFF_SIMPLE, DIFF_INTERSECT, DIFF_SET, DIFF_EXTREME];

function preset(
  name: string,
  c: number,
  r: number,
  diff: number,
  opts: Partial<SoloParams> = {},
): { name: string; params: SoloParams } {
  return {
    name,
    params: { c, r, symm: SYMM_ROT2, diff, xtype: false, killer: false, ...opts },
  };
}

function boardBorder(t: number): number {
  return Math.round(t * 0.3);
}

/** How digit `n` is written: 1–9, then letters a, b, c… */
export function digitChar(n: number): string {
  return n <= 9 ? String(n) : String.fromCharCode(97 + n - 10);
}

export function makeState(c: number, r: number, xtype: boolean, killer: boolean, d: ParsedDesc) {
  const cr = c * r;
  const state: SoloState = {
    cr,
    c,
    r,
    xtype,
    killer,
    blocks: d.blocks,
    kblocks: d.kblocks,
    kgrid: d.kgrid,
    grid: d.grid,
    pencil: new Uint8Array(cr * cr * cr),
    immutable: d.grid.map((v) => (v ? 1 : 0)),
    completed: false,
    cheated: false,
  };
  return state;
}

/**
 * The solved grid: the generator's own answer where there is one, else worked out from
 * the clues. Thrown errors read the same as Solve's, since they mean the same thing.
 */
export function solutionGrid(state: SoloState, aux: string | undefined): Uint8Array {
  const area = state.cr * state.cr;
  if (aux && aux[0] === 'S') {
    const parts = aux.slice(1).split(',');
    if (parts.length === area) {
      const grid = new Uint8Array(area);
      let ok = true;
      for (let i = 0; i < area && ok; i++) {
        const v = /^\d+$/.test(parts[i]) ? parseInt(parts[i], 10) : 0;
        if (v < 1 || v > state.cr) ok = false;
        else grid[i] = v;
      }
      if (ok) return grid;
    }
  }
  const grid = state.grid.slice();
  const res = solveGrid(
    state.cr,
    state.blocks,
    state.kblocks,
    state.xtype,
    grid,
    state.kgrid,
    DIFF_RECURSIVE,
    KDIFF_INTERSECT,
  );
  if (res.diff === DIFF_IMPOSSIBLE) throw new Error(tx`No solution exists for this puzzle`);
  if (res.diff === DIFF_AMBIGUOUS) throw new Error(tx`Multiple solutions exist for this puzzle`);
  return grid;
}

export interface SoloErrors {
  /** 1 where the digit clashes with another in its row, column, block, diagonal or cage. */
  cells: Uint8Array;
  /** 1 for each cage that is fully filled but does not add up to its clue. */
  cages: Uint8Array;
}

/** Duplicate digits and wrong cage sums, for error highlighting. */
export function findErrors(state: SoloState): SoloErrors {
  const { cr, grid, blocks, kblocks, xtype } = state;
  const area = cr * cr;
  const cells = new Uint8Array(area);
  const cages = new Uint8Array(kblocks ? kblocks.nrBlocks : 0);
  const rows = new Uint8Array(area);
  const cols = new Uint8Array(area);
  const blks = new Uint8Array(area);
  const diags = new Uint8Array(2 * cr);
  const cageCount = new Uint8Array((kblocks ? kblocks.nrBlocks : 0) * cr);
  for (let xy = 0; xy < area; xy++) {
    const d = grid[xy];
    if (!d) continue;
    const x = xy % cr;
    const y = Math.floor(xy / cr);
    rows[y * cr + d - 1]++;
    cols[x * cr + d - 1]++;
    blks[blocks.whichblock[xy] * cr + d - 1]++;
    if (xtype) {
      if (onDiag0(xy, cr)) diags[d - 1]++;
      if (onDiag1(xy, cr)) diags[cr + d - 1]++;
    }
    if (kblocks) cageCount[kblocks.whichblock[xy] * cr + d - 1]++;
  }
  for (let xy = 0; xy < area; xy++) {
    const d = grid[xy];
    if (!d) continue;
    const x = xy % cr;
    const y = Math.floor(xy / cr);
    if (
      rows[y * cr + d - 1] > 1 ||
      cols[x * cr + d - 1] > 1 ||
      blks[blocks.whichblock[xy] * cr + d - 1] > 1 ||
      (xtype && onDiag0(xy, cr) && diags[d - 1] > 1) ||
      (xtype && onDiag1(xy, cr) && diags[cr + d - 1] > 1) ||
      (kblocks && cageCount[kblocks.whichblock[xy] * cr + d - 1] > 1)
    )
      cells[xy] = 1;
  }
  if (kblocks && state.kgrid) {
    const clues = cageClues(kblocks, state.kgrid);
    for (let b = 0; b < kblocks.nrBlocks; b++) {
      let sum = 0;
      let full = true;
      for (const s of kblocks.blocks[b]) {
        if (!grid[s]) full = false;
        sum += grid[s];
      }
      if (full && sum !== clues[b]) cages[b] = 1;
    }
  }
  return { cells, cages };
}

/**
 * Trace the outline of one region as a polygon, optionally inset into the region. The
 * walk keeps a region square on its right and records a point at every turn.
 */
function regionOutline(
  b: BlockStructure,
  bi: number,
  border: number,
  t: number,
  inset: number,
): number[] {
  const cr = b.cr;
  let start = -1;
  for (const s of b.blocks[bi]) {
    if (s % cr === 0 || b.whichblock[s - 1] !== bi) {
      start = s;
      break;
    }
  }
  const inside = (tx: number, ty: number) =>
    tx >= 0 && tx < cr && ty >= 0 && ty < cr && b.whichblock[ty * cr + tx] === bi;
  let x = start % cr;
  let y = Math.floor(start / cr);
  let dx = -1;
  let dy = 0;
  const sx = x;
  const sy = y;
  const pts: number[] = [];
  let guard = 0;
  do {
    let nin = 0;
    if (inside(x - dy + dx, y + dx + dy)) nin++;
    if (inside(x - dy, y + dx)) nin++;
    if (nin === 0) {
      const tmp = dx;
      dx = -dy;
      dy = tmp;
    } else if (nin === 2) {
      x += dx;
      y += dy;
      const tmp = dx;
      dx = dy;
      dy = -tmp;
      x -= dx;
      y -= dy;
    } else {
      x -= dy;
      y += dx;
    }
    if (nin !== 1) {
      const cx = (2 * x + 1 + dy + dx) / 2;
      const cy = (2 * y + 1 - dx + dy) / 2;
      let px = border + cx * t - dx * inset;
      let py = border + cy * t - dy * inset;
      if (nin === 0) {
        px -= dy * inset;
        py += dx * inset;
      } else {
        px += dy * inset;
        py -= dx * inset;
      }
      pts.push(px, py);
    }
  } while ((x !== sx || y !== sy || dx !== -1 || dy !== 0) && ++guard < 8 * cr * cr);
  return pts;
}

function drawPencilMarks(
  dr: Drawing,
  state: SoloState,
  xy: number,
  px: number,
  py: number,
  t: number,
  hasClue: boolean,
  spot: number,
): void {
  const { cr } = state;
  const marks: number[] = [];
  for (let n = 1; n <= cr; n++) if (state.pencil[xy * cr + n - 1]) marks.push(n);
  const count = marks.length;
  if (!count) return;
  const pad = t * 0.05;
  let pl = px + pad;
  let pr = px + t - pad;
  let pt = py + pad;
  let pb = py + t - pad;
  if (state.killer) {
    const ins = t * 0.1;
    pl += ins;
    pr -= ins;
    pt += ins;
    pb -= ins;
    if (hasClue) pt += t * 0.24;
  }
  let bestSize = 0;
  let pw = 3;
  for (let w = 3; w < Math.max(count, 4); w++) {
    const h = Math.max(Math.ceil(count / w), 2);
    const fs = Math.min((pr - pl) / w, (pb - pt) / h);
    if (fs > bestSize) {
      bestSize = fs;
      pw = w;
    }
  }
  const ph = Math.max(Math.ceil(count / pw), 2);
  const fs = Math.min((pr - pl) / pw, (pb - pt) / ph);
  const left = px + (t - fs * pw) / 2;
  let top = py + (t - fs * ph) / 2;
  if (hasClue) top = Math.max(top, pt);
  for (let j = 0; j < count; j++) {
    const gx = j % pw;
    const gy = Math.floor(j / pw);
    const lit = marks[j] === spot;
    dr.text(left + fs * (gx + 0.5), top + fs * (gy + 0.5), digitChar(marks[j]), {
      size: fs * 0.82,
      colour: lit ? 'teal' : 'pencil',
      bold: lit,
    });
  }
}

/** The digit Highlight is picking out, or 0 when it is off or points at an empty square. */
export function spotDigit(grid: Uint8Array, ui: SoloUI): number {
  return ui.spot && ui.spotAt >= 0 && ui.spotAt < grid.length ? grid[ui.spotAt] : 0;
}

const game = defineGame<SoloParams, SoloState, SoloUI>({
  id: 'solo',
  name: 'Solo',
  description: 'Fill the grid so every row, column and block holds each digit once.',
  alsoKnownAs: 'Sudoku',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  // Named for the board the player sees (a 3×3 block size makes a 9×9 grid), on a
  // difficulty ladder a newcomer recognises. The solver's own level names are a
  // generator concept and stay in the Custom dialog.
  presets: [
    preset('4×4 Very Easy', 2, 2, DIFF_BLOCK),
    preset('6×6 Easy', 2, 3, DIFF_SIMPLE),
    preset('9×9 Very Easy', 3, 3, DIFF_BLOCK),
    preset('9×9 Easy', 3, 3, DIFF_SIMPLE),
    preset('9×9 X-Diagonal Easy', 3, 3, DIFF_SIMPLE, { xtype: true }),
    preset('9×9 Medium', 3, 3, DIFF_INTERSECT),
    preset('9×9 Hard', 3, 3, DIFF_SET),
    preset('9×9 X-Diagonal Hard', 3, 3, DIFF_SET, { xtype: true }),
    preset('9×9 Expert', 3, 3, DIFF_EXTREME),
    preset('9×9 Extreme', 3, 3, DIFF_RECURSIVE),
    preset('9×9 Killer', 3, 3, DIFF_BLOCK, { killer: true, symm: SYMM_NONE }),
    preset('9×9 Jigsaw Easy', 9, 1, DIFF_SIMPLE),
    preset('9×9 Jigsaw X-Diagonal Easy', 9, 1, DIFF_SIMPLE, { xtype: true }),
    preset('9×9 Jigsaw Hard', 9, 1, DIFF_SET),
    preset('12×12 Easy', 3, 4, DIFF_SIMPLE),
    preset('16×16 Easy', 4, 4, DIFF_SIMPLE),
  ],
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams(p, full) {
    let s = p.r > 1 ? `${p.c}x${p.r}` : `${p.c}j`;
    if (p.xtype) s += 'x';
    if (p.killer) s += 'k';
    if (full) {
      s += SYMM_CODES[p.symm] ?? '';
      if (p.diff !== DIFF_BLOCK) s += 'd' + (DIFF_CODES[p.diff] ?? '');
    }
    return s;
  },
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?/.exec(str);
    if (!m) throw new Error(tx`expected CxR or Nj`);
    const p: SoloParams = { ...DEFAULTS };
    p.c = parseInt(m[1], 10);
    const seenR = m[2] !== undefined;
    p.r = seenR ? parseInt(m[2], 10) : p.c;
    let i = m[0].length;
    while (i < str.length) {
      const ch = str[i++];
      if (ch === 'j') {
        if (seenR) p.c *= p.r;
        p.r = 1;
      } else if (ch === 'x') {
        p.xtype = true;
      } else if (ch === 'k') {
        p.killer = true;
      } else if (ch === 'a') {
        p.symm = SYMM_NONE;
      } else if (ch === 'r' || ch === 'm') {
        let diagonal = false;
        if (ch === 'm' && str[i] === 'd') {
          diagonal = true;
          i++;
        }
        const nm = /^\d+/.exec(str.slice(i));
        const n = nm ? parseInt(nm[0], 10) : 0;
        if (nm) i += nm[0].length;
        if (ch === 'r' && n === 2) p.symm = SYMM_ROT2;
        else if (ch === 'r' && n === 4) p.symm = SYMM_ROT4;
        else if (ch === 'm' && n === 2) p.symm = diagonal ? SYMM_REF2D : SYMM_REF2;
        else if (ch === 'm' && n === 4) p.symm = diagonal ? SYMM_REF4D : SYMM_REF4;
        else if (ch === 'm' && n === 8) p.symm = SYMM_REF8;
      } else if (ch === 'd') {
        const d = DIFF_CODES.indexOf(str[i]);
        if (d >= 0) {
          p.diff = d;
          i++;
        }
      }
    }
    return p;
  },
  validateParams(p, full) {
    if (![p.c, p.r, p.symm, p.diff].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.c < 2) return tx`Both dimensions must be at least 2`;
    if (p.r < 1) return tx`Rows of blocks must be at least 1`;
    const cr = p.c * p.r;
    if (cr > MAX_SYMBOLS) return tx`Unable to support more than ${MAX_SYMBOLS} distinct symbols`;
    if (p.killer && cr > 9) return tx`Killer puzzle dimensions must be smaller than 10`;
    if (p.symm < 0 || p.symm >= SYMM_CODES.length) return tx`Unknown symmetry`;
    if (p.diff < 0 || p.diff > DIFF_RECURSIVE) return tx`Unknown difficulty`;
    if (full && cr > MAX_GENERATE)
      return tx`Puzzles with more than ${MAX_GENERATE} symbols take too long to generate`;
    if (full && p.r === 1 && cr > MAX_GENERATE_JIGSAW)
      return tx`Jigsaw puzzles with more than ${MAX_GENERATE_JIGSAW} symbols take too long to generate`;
    if (full && p.r === 1 && p.xtype && cr > MAX_GENERATE_JIGSAW_X)
      return tx`X-diagonal jigsaw puzzles with more than ${MAX_GENERATE_JIGSAW_X} symbols take too long to generate`;
    if (full && p.diff === DIFF_RECURSIVE && cr > MAX_GENERATE_EXTREME)
      return tx`Extreme puzzles with more than ${MAX_GENERATE_EXTREME} symbols take too long to generate`;
    if (full && p.xtype && cr < 4) return tx`X puzzles need at least four symbols`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Columns of sub-blocks', value: String(p.c) },
      { type: 'string', name: 'Rows of sub-blocks', value: String(p.r) },
      { type: 'boolean', name: '"X" (require every number in each main diagonal)', value: p.xtype },
      { type: 'boolean', name: 'Jigsaw (irregularly shaped sub-blocks)', value: p.r === 1 },
      { type: 'boolean', name: 'Killer (digit sums)', value: p.killer },
      { type: 'choices', name: 'Symmetry', choices: SYMM_NAMES, selected: p.symm },
      { type: 'choices', name: 'Difficulty', choices: DIFF_NAMES, selected: p.diff },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const bool = (i: number) => (items[i] as { value: boolean }).value;
    const sel = (i: number) => (items[i] as { selected: number }).selected;
    let c = int(0);
    let r = int(1);
    if (bool(3)) {
      c *= r;
      r = 1;
    }
    return { c, r, xtype: bool(2), killer: bool(4), symm: sel(5), diff: sel(6) };
  },

  newDesc(p, rng: Random) {
    return generateSolo(p, rng);
  },

  validateDesc(p, desc) {
    const d = parseDesc(p.c, p.r, p.killer, desc);
    return typeof d === 'string' ? d : null;
  },

  newGame(p, desc) {
    const d = parseDesc(p.c, p.r, p.killer, desc) as ParsedDesc;
    return makeState(p.c, p.r, p.xtype, p.killer, d);
  },

  canSolve: true,
  solve(orig, _curr, aux) {
    if (aux) return aux;
    const grid = orig.grid.slice();
    const res = solveGrid(
      orig.cr,
      orig.blocks,
      orig.kblocks,
      orig.xtype,
      grid,
      orig.kgrid,
      DIFF_RECURSIVE,
      KDIFF_INTERSECT,
    );
    if (res.diff === DIFF_IMPOSSIBLE) throw new Error(tx`No solution exists for this puzzle`);
    if (res.diff === DIFF_AMBIGUOUS) throw new Error(tx`Multiple solutions exist for this puzzle`);
    return 'S' + Array.from(grid).join(',');
  },

  /**
   * One square. A digit that contradicts the solution is put right first — knowing a
   * square is wrong is worth more than a fresh one — and otherwise the square the
   * simplest technique still settles is written in, so the hint is a deduction the
   * player could have made rather than a random reveal.
   */
  hint(orig, curr, aux, ui) {
    if (curr.completed) return null;
    const { cr } = curr;
    const area = cr * cr;
    const solution = solutionGrid(orig, aux);
    const fill = (xy: number, n: number) =>
      markHint(ui, xy, `R${xy % cr},${Math.floor(xy / cr)},${n}`);

    for (let xy = 0; xy < area; xy++) {
      if (curr.immutable[xy] || !curr.grid[xy]) continue;
      if (curr.grid[xy] !== solution[xy]) return fill(xy, solution[xy]);
    }
    for (const diff of HINT_DIFFS) {
      const grid = curr.grid.slice();
      solveGrid(cr, curr.blocks, curr.kblocks, curr.xtype, grid, curr.kgrid, diff, KDIFF_INTERSECT);
      for (let xy = 0; xy < area; xy++) {
        if (!curr.grid[xy] && grid[xy] && grid[xy] === solution[xy]) return fill(xy, grid[xy]);
      }
    }
    // Nothing the solver reaches at a human difficulty: hand over a square anyway.
    for (let xy = 0; xy < area; xy++) if (!curr.grid[xy]) return fill(xy, solution[xy]);
    return null;
  },

  textFormat(s) {
    const { cr, blocks } = s;
    const vmod = s.r > 1 ? s.r : 1;
    const hmod = s.r > 1 ? s.c : 1;
    const lines: string[] = [];
    for (let y = 0; y < cr; y++) {
      let line = '';
      for (let x = 0; x < cr; x++) {
        const xy = y * cr + x;
        const d = s.grid[xy];
        line += d ? digitChar(d) : s.xtype && (onDiag0(xy, cr) || onDiag1(xy, cr)) ? '_' : '.';
        if (x === cr - 1) break;
        line += ' ';
        if ((x + 1) % vmod) continue;
        line += (blocks.whichblock[xy] !== blocks.whichblock[xy + 1] ? '|' : ' ') + ' ';
      }
      lines.push(line);
      if (y === cr - 1 || (y + 1) % hmod) continue;
      let div = '';
      for (let x = 0; x < cr; x++) {
        const xy = y * cr + x;
        let width = x === cr - 1 ? 1 : 2;
        if (x > 0 && x % vmod === 0) width++;
        const ch = blocks.whichblock[xy] !== blocks.whichblock[xy + cr] ? '-' : ' ';
        div += ch.repeat(width);
        if (x === cr - 1) break;
        if ((x + 1) % vmod) continue;
        const tl = blocks.whichblock[xy];
        const tr = blocks.whichblock[xy + 1];
        const bl = blocks.whichblock[xy + cr];
        const br = blocks.whichblock[xy + cr + 1];
        if (tl === tr && tr === bl && bl === br) div += ' ';
        else if (tl === bl && tr === br) div += '|';
        else if (tl === tr && bl === br) div += '-';
        else div += '+';
      }
      lines.push(div);
    }
    return lines.join('\n');
  },

  newUI: () => ({
    hx: 0,
    hy: 0,
    hshow: false,
    hpencil: false,
    hcursor: false,
    hkept: false,
    spot: false,
    spotAt: -1,
    ...noHint(),
  }),
  changedState(ui, _old, next) {
    // A pencil highlight on a square that has just been filled (by Undo, Redo or Solve)
    // makes no sense, so drop it unless the keyboard cursor is in use; and a puzzle just
    // finished needs no selection at all.
    if (ui.hshow && ui.hpencil && !ui.hcursor && next.grid[ui.hy * next.cr + ui.hx] !== 0)
      ui.hshow = false;
    if (next.completed && !_old.completed) ui.hshow = false;
  },

  // One key per digit of this grid, using the same characters the keyboard accepts
  // (letters above 9), plus a clear key and the pencil-mark latch.
  keypad: (p) => ({
    keys: Array.from({ length: p.c * p.r }, (_, i) => digitChar(i + 1)),
    clear: true,
    pencil: true,
  }),

  actions: [
    {
      label: 'Marks',
      key: 'M',
      title: 'Pencil every possibility into every empty square (M)',
    },
    {
      label: 'Highlight',
      key: 'L',
      hud: true,
      glyph: HIGHLIGHT_GLYPH,
      pressed: (_s, ui) => ui.spot,
      view: true,
      title: 'Pick out every square holding the digit you last touched (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    // A click straight after a digit re-chooses the square that kept its selection rather
    // than deselecting it, so clicking a square before each digit still types.
    const kept = ui.hkept;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || isCursorMove(b)) ui.hkept = false;
    const { cr } = state;
    const t = ds.tileSize;
    const border = boardBorder(t);
    const tx = Math.floor((mx - border) / t);
    const ty = Math.floor((my - border) / t);
    const inside = tx >= 0 && tx < cr && ty >= 0 && ty < cr;

    // L is never a digit: the letters stop at g, the sixteenth.
    if (b === 76 || b === 108) {
      ui.spot = !ui.spot;
      return '';
    }
    if (inside && (b === LEFT_BUTTON || b === RIGHT_BUTTON)) ui.spotAt = ty * cr + tx;
    if (inside && b === LEFT_BUTTON) {
      if (state.immutable[ty * cr + tx]) {
        ui.hshow = false;
      } else if (tx === ui.hx && ty === ui.hy && ui.hshow && !ui.hpencil && !kept) {
        ui.hshow = false;
      } else {
        ui.hx = tx;
        ui.hy = ty;
        ui.hshow = true;
        ui.hpencil = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (inside && b === RIGHT_BUTTON) {
      if (state.grid[ty * cr + tx] === 0) {
        if (tx === ui.hx && ty === ui.hy && ui.hshow && ui.hpencil) {
          ui.hshow = false;
        } else {
          ui.hx = tx;
          ui.hy = ty;
          ui.hshow = true;
          ui.hpencil = true;
        }
      } else {
        ui.hshow = false;
      }
      ui.hcursor = false;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.hx, ui.hy, cr, cr);
      ui.hx = p.x;
      ui.hy = p.y;
      ui.spotAt = p.y * cr + p.x;
      ui.hshow = true;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow && b === CURSOR_SELECT) {
      ui.hpencil = !ui.hpencil;
      ui.hcursor = true;
      return '';
    }
    if (ui.hshow) {
      let n = -1;
      if (b >= 48 && b <= 57 && b - 48 <= cr) n = b - 48;
      else if (b >= 97 && b <= 122 && b - 97 + 10 <= cr) n = b - 97 + 10;
      else if (b >= 65 && b <= 90 && b - 65 + 10 <= cr) n = b - 65 + 10;
      else if (b === CURSOR_SELECT2 || b === KEY_BACKSPACE) n = 0;
      if (n >= 0) {
        // MOD_SHFT on a digit is the on-screen keypad's pencil latch: pencil this in
        // whatever mode the square was selected in.
        const pencil = ui.hpencil || (button & MOD_SHFT) !== 0;
        const xy = ui.hy * cr + ui.hx;
        // Only the keyboard cursor can sit on a clue or pencil-highlight a filled square.
        if (state.immutable[xy]) return null;
        if (pencil && state.grid[xy]) return null;
        const move = `${pencil && n > 0 ? 'P' : 'R'}${ui.hx},${ui.hy},${n}`;
        // The selection stays after a digit, so a keypad user can rub it out or try
        // another without tapping the square again.
        if (!pencil && !ui.hcursor) ui.hkept = true;
        return move;
      }
    }
    if (b === 77 || b === 109) return 'M';
    return null;
  },

  executeMove(state, move) {
    const { cr } = state;
    const area = cr * cr;
    if (move[0] === 'S') {
      const parts = move.slice(1).split(',');
      if (parts.length !== area) return null;
      const grid = new Uint8Array(area);
      for (let i = 0; i < area; i++) {
        if (!/^\d+$/.test(parts[i])) return null;
        const v = parseInt(parts[i], 10);
        if (v < 1 || v > cr) return null;
        grid[i] = v;
      }
      return {
        ...state,
        grid,
        pencil: new Uint8Array(state.pencil.length),
        completed: true,
        cheated: true,
      };
    }
    if (move === 'M') {
      const pencil = state.pencil.slice();
      for (let xy = 0; xy < area; xy++) if (!state.grid[xy]) pencil.fill(1, xy * cr, xy * cr + cr);
      // Every empty square already fully pencilled (or none left): an undo step that
      // changes nothing would only be confusing.
      if (pencil.every((v, i) => v === state.pencil[i])) return state;
      return { ...state, pencil };
    }
    const m = /^([PR])(\d+),(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    const n = parseInt(m[4], 10);
    if (x >= cr || y >= cr || n > cr) return null;
    const xy = y * cr + x;
    if (state.immutable[xy]) return null;
    if (m[1] === 'P' && n > 0) {
      if (state.grid[xy]) return null;
      const pencil = state.pencil.slice();
      pencil[xy * cr + n - 1] ^= 1;
      return { ...state, pencil };
    }
    // Rubbing out an empty square, or typing the digit a square already holds, changes
    // nothing: returning the same state keeps it from becoming an Undo step that does nothing.
    if (state.grid[xy] === n && !state.pencil.subarray(xy * cr, xy * cr + cr).some((v) => v)) {
      return state;
    }
    const grid = state.grid.slice();
    grid[xy] = n;
    const pencil = state.pencil.slice();
    pencil.fill(0, xy * cr, xy * cr + cr);
    const completed =
      state.completed ||
      checkValid(cr, state.blocks, state.kblocks, state.kgrid, state.xtype, grid);
    return { ...state, grid, pencil, completed };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const cr = p.c * p.r;
    const b = boardBorder(t);
    return { w: cr * t + 2 * b, h: cr * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const { cr, grid, blocks, kblocks } = state;
    const t = ds.tileSize;
    const b = boardBorder(t);
    // A hint owns the flash it asked for: only a completion recolours the whole board.
    // A move made while a hint's flash is still running clears `hintAt` but leaves that
    // flash running, so the board must also really be complete to light up green.
    const flash =
      state.completed &&
      !hintFlashing(ui) &&
      flashTime > 0 &&
      (flashTime <= FLASH / 3 || flashTime >= (2 * FLASH) / 3);
    const errors = findErrors(state);

    dr.rect(b, b, cr * t, cr * t, flash ? 'shade' : 'paper');
    if (state.xtype && !flash) {
      for (let i = 0; i < cr; i++) {
        dr.rect(b + i * t, b + i * t, t, t, 'shade');
        if (2 * i !== cr - 1) dr.rect(b + (cr - 1 - i) * t, b + i * t, t, t, 'shade');
      }
    }
    // A finished board is shown clean, without the tint.
    const spot = state.completed ? 0 : spotDigit(grid, ui);
    if (spot) {
      for (let xy = 0; xy < cr * cr; xy++) {
        if (grid[xy] !== spot) continue;
        dr.rect(b + (xy % cr) * t, b + Math.floor(xy / cr) * t, t, t, 'teal', null, {
          alpha: 0.18,
        });
      }
    }
    if (ui.hshow) {
      const hx = b + ui.hx * t;
      const hy = b + ui.hy * t;
      dr.rect(hx, hy, t, t, ui.hpencil ? 'blue' : 'yellow', null, {
        alpha: ui.hpencil ? 0.12 : 0.25,
      });
    }

    for (let i = 1; i < cr; i++) {
      dr.line(b + i * t, b, b + i * t, b + cr * t, 'faint', 1.2);
      dr.line(b, b + i * t, b + cr * t, b + i * t, 'faint', 1.2);
    }
    for (let bi = 0; bi < blocks.nrBlocks; bi++) {
      dr.polygon(regionOutline(blocks, bi, b, t, 0), null, 'ink', { width: 2.6, seed: bi });
    }
    if (kblocks) {
      const inset = t * 0.1;
      for (let bi = 0; bi < kblocks.nrBlocks; bi++) {
        dr.polygon(
          regionOutline(kblocks, bi, b, t, inset),
          null,
          errors.cages[bi] ? 'error' : 'pencil',
          {
            width: 1.3,
            seed: 100 + bi,
            dash: [Math.max(3, t * 0.09), Math.max(2, t * 0.07)],
            rough: 0.4,
          },
        );
      }
    }

    // A digit the player has just typed is pressed into the square rather than simply
    // being there, and one they have rubbed out shrinks away. This is the most repeated
    // action in the collection — eighty-one of them in a single Sudoku — so it is short,
    // and a Solve, which fills the whole grid at once, is left to appear whole.
    const inked = oldState ? changedAt(oldState.grid, grid, 2) : null;
    /** The digit a square is showing mid-change, and how big it is. */
    const inkAt = (i: number, d: number): { d: number; s: number } =>
      !inked?.includes(i)
        ? { d, s: 1 }
        : d
          ? { d, s: popGrow(animTime) }
          : { d: oldState!.grid[i], s: 1 - drawGrow(animTime, INK_TIME) };

    for (let y = 0; y < cr; y++) {
      for (let x = 0; x < cr; x++) {
        const xy = y * cr + x;
        const px = b + x * t;
        const py = b + y * t;
        const clue = state.kgrid ? state.kgrid[xy] : 0;
        if (clue) {
          dr.text(px + t * 0.16, py + t * 0.15, String(clue), {
            size: t * 0.24,
            colour: errors.cages[kblocks!.whichblock[xy]] ? 'error' : 'pencil',
            align: 'left',
            valign: 'top',
          });
        }
        const ink = inkAt(xy, grid[xy]);
        const d = ink.d;
        if (d && ink.s > 0) {
          // Clues keep their colour; only the player's own clashing digits turn red.
          const colour = state.immutable[xy]
            ? flash
              ? 'ok'
              : 'ink'
            : errors.cells[xy]
              ? 'error'
              : flash
                ? 'ok'
                : 'blue';
          dr.text(px + t / 2, py + t / 2 + (clue ? t * 0.06 : 0), digitChar(d), {
            size: t * 0.55 * ink.s,
            colour,
          });
        } else if (!grid[xy]) {
          drawPencilMarks(dr, state, xy, px, py, t, clue !== 0, spot);
        }
      }
    }

    dr.rectOutline(b, b, cr * t, cr * t, 'ink', { width: 2.6 });

    const hintCell = hintFlashCell(ui, flashTime);
    if (hintCell >= 0) {
      dr.hintBox(b + (hintCell % cr) * t, b + Math.floor(hintCell / cr) * t, t, t);
    }

    if (ui.hshow) {
      const inset = t * 0.08;
      const hx = b + ui.hx * t + inset;
      const hy = b + ui.hy * t + inset;
      dr.cursor(hx, hy, t - 2 * inset, t - 2 * inset, 'accent', 2.2, {
        dash: ui.hpencil ? [Math.max(3, t * 0.1), Math.max(2, t * 0.08)] : undefined,
      });
      if (ui.hpencil) {
        const s = t * 0.22;
        dr.polygon([hx, hy, hx + s, hy, hx, hy + s], 'accent', null, { seed: 7 });
      }
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.grid, newState.grid, 2) ? INK_TIME : 0;
  },
  flashLength(oldState, newState, _dir, ui) {
    const hint = takeHintFlash(ui);
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : hint;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  thumbnailParams: { c: 3, r: 3, symm: SYMM_ROT2, diff: DIFF_SIMPLE, xtype: false, killer: false },
});

export default game;
