import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { LightupState, LightupUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Index of the black square carrying clue `n` (the tutorial board has one of each). */
function clueCell(state: LightupState, n: number): { x: number; y: number } {
  const i = state.layout.clue.indexOf(n);
  return { x: i % state.w, y: Math.floor(i / state.w) };
}

const hasBulb = (s: LightupState, x: number, y: number) => s.light[y * s.w + x] === 1;
const marked = (s: LightupState, x: number, y: number) => s.imposs[y * s.w + x] === 1;

