export type { MapParams } from './generator';

export interface MapState {
  w: number;
  h: number;
  n: number;
  /** The fixed map, shared between states. */
  map: MapLayout;
  /** Colour of each region, -1 for none. */
  colouring: Int8Array;
  /** Pencil-mark bitmask per region (bit c = colour c noted as possible). */
  pencil: Uint8Array;
  completed: boolean;
  cheated: boolean;
}

export interface MapUI {
  /** -2 no drag; -1 dragging "blank"; 0–3 dragging that colour. */
  dragColour: number;
  /** Pencil marks carried along by a drag from a blank region. */
  dragPencil: number;
  dragX: number;
  dragY: number;
  /** Region the mouse button went down on (-1 outside the map). */
  pressRegion: number;
  /** Palette swatch the button went down on (-1 none). */
  pressSwatch: number;
  /** The pressed swatch was already selected, so releasing on it deselects. */
  swatchToggle: boolean;
  /** Palette selection: -2 none, -1 the eraser, 0–3 a colour. */
  selColour: number;
  /** The current drag was started from the keyboard. */
  keyDrag: boolean;
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** The cursor moved since the keyboard drag began (Enter twice in place clears). */
  curMoved: boolean;
  /** Last cursor key, which decides which half of a split square the cursor means. */
  lastMove: number;
  showNumbers: boolean;
}

/** Palette tokens for colours 0–3. */
export const COLOUR_TOKENS = ['red', 'blue', 'green', 'yellow'] as const;

const ANIM = 0.13;
const FLASH_FRAME = 0.13;
const FLASH = 3 * FLASH_FRAME;
const MAX_SIDE = 40;
const DEFAULTS: MapParams = { w: 20, h: 15, n: 30, diff: DIFF_NORMAL };

/**
 * What the game opens on. Deliberately not the original collection's default: a player
 * who has never seen this puzzle before meets it at the gentlest setting the Type menu
 * offers at that size, and goes up the ladder when they want to.
 */
const OPENING: MapParams = { ...DEFAULTS, diff: DIFF_EASY };

// ------------------------------------------------------------------ geometry

export interface Geometry {
  t: number;
  b: number;
  mapX: number;
  mapY: number;
  mapW: number;
  mapH: number;
  /** Swatch size and spacing of the palette row below the map. */
  sw: number;
  gap: number;
  palX: number;
  palY: number;
  W: number;
  H: number;
}

/** Smallest palette swatch, in CSS pixels, where the map is wide enough to allow it. */
const MIN_SWATCH = 40;

/** Number of swatches: the four colours and an eraser. */
const SWATCHES = FOUR + 1;

export function geometry(t: number, w: number, h: number): Geometry {
  const b = Math.round(t * 0.3);
  // The swatches are how a finger colours the map, so they never shrink below a
  // comfortable target just because a big grid made the squares small — as long as the
  // row still fits comfortably across the map (five swatches and four gaps ≈ 6.4 sw).
  const sw = Math.max(Math.round(t * 0.9), Math.min(MIN_SWATCH, Math.round((w * t) / 8)));
  const gap = Math.round(sw / 3);
  const mapW = w * t;
  const mapH = h * t;
  const palW = SWATCHES * sw + (SWATCHES - 1) * gap;
  const W = Math.max(mapW, palW) + 2 * b;
  const mapX = Math.round((W - mapW) / 2);
  const palY = b + mapH + b;
  return {
    t,
    b,
    mapX,
    mapY: b,
    mapW,
    mapH,
    sw,
    gap,
    palX: Math.round((W - palW) / 2),
    palY,
    W,
    H: palY + sw + b,
  };
}

/** Palette swatch under a canvas point: 0–3 a colour, 4 the eraser, -1 none. */
export function swatchAt(g: Geometry, x: number, y: number): number {
  if (y < g.palY || y >= g.palY + g.sw) return -1;
  for (let s = 0; s < SWATCHES; s++) {
    const sx = g.palX + s * (g.sw + g.gap);
    if (x >= sx && x < sx + g.sw) return s;
  }
  return -1;
}

/** Canvas point the keyboard cursor stands for, nudged toward its last direction. */
function cursorPoint(ui: MapUI, g: Geometry): { x: number; y: number } {
  const ex = ui.lastMove === CURSOR_RIGHT ? 1 : ui.lastMove === CURSOR_LEFT ? -1 : 0;
  const ey = ui.lastMove === CURSOR_DOWN ? 1 : ui.lastMove === CURSOR_UP ? -1 : 0;
  return { x: g.mapX + ui.cx * g.t + g.t / 2 + ex, y: g.mapY + ui.cy * g.t + g.t / 2 + ey };
}

function regionUnder(state: MapState, g: Geometry, x: number, y: number): number {
  return regionAt(state.map, g.t, g.mapX, g.mapY, x, y);
}

// ------------------------------------------------------------------ moves

function makeState(map: MapLayout, colouring: Int8Array): MapState {
  return {
    w: map.w,
    h: map.h,
    n: map.n,
    map,
    colouring,
    pencil: new Uint8Array(map.n),
    completed: false,
    cheated: false,
  };
}

/**
 * The move that gives region `r` colour `c` (-1 = none) and pencil set `p`, as a list of
 * `;`-separated parts; empty when nothing would change.
 */
function buildMove(state: MapState, r: number, c: number, p: number): string {
  const parts: string[] = [];
  let oldp = state.pencil[r];
  if (c !== state.colouring[r]) {
    parts.push(`${c < 0 ? 'C' : c}:${r}`);
    if (c >= 0) oldp = 0;
  }
  if (p !== oldp) {
    for (let i = 0; i < FOUR; i++) if ((oldp ^ p) & (1 << i)) parts.push(`p${i}:${r}`);
  }
  return parts.join(';');
}

/** Finish a drag by dropping its colour on region `r`; `alt` drops it as pencil marks. */
function drop(state: MapState, ui: MapUI, r: number, alt: boolean): string {
  let c = ui.dragColour;
  let p = ui.dragPencil;
  ui.dragColour = -2;
  ui.keyDrag = false;
  if (r < 0 || state.map.immutable[r]) return '';
  if (state.colouring[r] === c && state.pencil[r] === p) return '';
  if (alt) {
    // Pencil marks only go on blank regions; a dragged colour toggles its own mark. A
    // blank dragged with the right button behaves like a left drag.
    if (state.colouring[r] >= 0) return '';
    if (c >= 0) {
      p = state.pencil[r] ^ (1 << c);
      c = -1;
    }
  }
  return buildMove(state, r, c, p);
}

/** A colouring consistent with the givens that is a proper four-colouring, or null. */
function solutionFor(state: MapState, aux: string | undefined): Int8Array | null {
  const L = state.map;
  if (aux && aux.length === L.n && /^[0-3]+$/.test(aux)) {
    const sol = Int8Array.from(aux, (ch) => ch.charCodeAt(0) - 48);
    let ok = isComplete(L, sol);
    for (let i = 0; ok && i < L.n; i++)
      if (L.immutable[i] && state.colouring[i] !== sol[i]) ok = false;
    if (ok) return sol;
  }
  return null;
}

// ------------------------------------------------------------------ drawing

/**
 * Stroke the boundary segments for which `pred(a, b)` holds, where a and b are the
 * regions either side (-1 outside the map). Collinear segments are merged so each border
 * is one continuous sketched stroke: runs along grid lines, and runs of diagonals in
 * split squares.
 */
function strokeBoundaries(
  dr: Drawing,
  L: MapLayout,
  g: Geometry,
  pred: (a: number, b: number) => boolean,
  colour: string,
  width: number,
  seed: number,
): void {
  const { w, h } = L;
  const wh = w * h;
  const t = g.t;
  const X = (x: number) => g.mapX + x * t;
  const Y = (y: number) => g.mapY + y * t;
  const q = (side: number, x: number, y: number) => L.quad[side * wh + y * w + x];
  const opts = { seed };

  for (let gx = 0; gx <= w; gx++) {
    let y0 = -1;
    for (let y = 0; y <= h; y++) {
      const on = y < h && pred(gx > 0 ? q(RE, gx - 1, y) : -1, gx < w ? q(LE, gx, y) : -1);
      if (on && y0 < 0) y0 = y;
      if (!on && y0 >= 0) {
        dr.line(X(gx), Y(y0), X(gx), Y(y), colour, width, opts);
        y0 = -1;
      }
    }
  }
  for (let gy = 0; gy <= h; gy++) {
    let x0 = -1;
    for (let x = 0; x <= w; x++) {
      const on = x < w && pred(gy > 0 ? q(BE, x, gy - 1) : -1, gy < h ? q(TE, x, gy) : -1);
      if (on && x0 < 0) x0 = x;
      if (!on && x0 >= 0) {
        dr.line(X(x0), Y(gy), X(x), Y(gy), colour, width, opts);
        x0 = -1;
      }
    }
  }
  // "/" diagonals (top-left half is the TE region) run along x + y = s.
  for (let s = 0; s <= w + h - 2; s++) {
    const xMin = Math.max(0, s - (h - 1));
    const xMax = Math.min(w - 1, s);
    let run = 0;
    let sx = 0;
    let sy = 0;
    for (let x = xMin; x <= xMax + 1; x++) {
      const y = s - x;
      let on = false;
      if (x <= xMax) {
        const i = y * w + x;
        const te = L.quad[TE * wh + i];
        const be = L.quad[BE * wh + i];
        on = te !== be && L.quad[LE * wh + i] === te && pred(te, be);
      }
      if (on) {
        if (run === 0) {
          sx = x;
          sy = y;
        }
        run++;
      } else if (run > 0) {
        dr.line(X(sx), Y(sy + 1), X(sx + run), Y(sy + 1 - run), colour, width, opts);
        run = 0;
      }
    }
  }
  // "\" diagonals (bottom-left half is the BE region) run along x - y = d.
  for (let d = -(h - 1); d <= w - 1; d++) {
    const xMin = Math.max(0, d);
    const xMax = Math.min(w - 1, h - 1 + d);
    let run = 0;
    let sx = 0;
    let sy = 0;
    for (let x = xMin; x <= xMax + 1; x++) {
      const y = x - d;
      let on = false;
      if (x <= xMax) {
        const i = y * w + x;
        const te = L.quad[TE * wh + i];
        const be = L.quad[BE * wh + i];
        on = te !== be && L.quad[LE * wh + i] === be && pred(te, be);
      }
      if (on) {
        if (run === 0) {
          sx = x;
          sy = y;
        }
        run++;
      } else if (run > 0) {
        dr.line(X(sx), Y(sy), X(sx + run), Y(sy + run), colour, width, opts);
        run = 0;
      }
    }
  }
}

/** Up to four pencil dots in a 2×2 cluster around (cx, cy). */
function drawPencil(
  dr: Drawing,
  cx: number,
  cy: number,
  t: number,
  bits: number,
  colours: string[],
  seed: number,
): void {
  const d = t * 0.2;
  const r = Math.max(2, t * 0.11);
  for (let c = 0; c < FOUR; c++) {
    if (!(bits & (1 << c))) continue;
    const ox = c % 2 === 0 ? -d : d;
    const oy = c < 2 ? -d : d;
    dr.dot(cx + ox, cy + oy, r, colours[c], { seed: seed + c });
  }
}

/** A diamond with an exclamation mark, marking a clash between two regions. */
function drawError(dr: Drawing, cx: number, cy: number, t: number, seed: number): void {
  const s = t * 0.36;
  dr.polygon([cx - s, cy, cx, cy - s, cx + s, cy, cx, cy + s], 'paper', 'error', {
    width: Math.max(1.6, t * 0.07),
    seed,
  });
  dr.text(cx, cy, '!', { size: t * 0.5, colour: 'error', bold: true });
}

/**
 * Difficulty words, in the solver's own order, for the Type menu and the Custom dialog
 * alike: a player who picks "Extreme" from one and opens the other must find the same
 * word selected there. The solver's own level names (`DIFFICULTY_NAMES`) stay in the code.
 */
const PRESET_DIFFICULTIES = ['Easy', 'Medium', 'Hard', 'Extreme'];

// ------------------------------------------------------------------ the game

const game = defineGame<MapParams, MapState, MapUI>({
  id: 'map',
  name: 'Map',
  description: 'Colour the map with four colours so no two neighbouring regions match.',
  help,
  tutorial,
  achievements,
  presets: (
    [
      [20, 15, 30, DIFF_EASY],
      [20, 15, 30, DIFF_NORMAL],
      [20, 15, 30, DIFF_HARD],
      [20, 15, 30, DIFF_RECURSE],
      [30, 25, 75, DIFF_NORMAL],
      [30, 25, 75, DIFF_HARD],
    ] as [number, number, number, number][]
  ).map(([w, h, n, diff]) => ({
    name: `${w}×${h} ${PRESET_DIFFICULTIES[diff]}, ${n} regions`,
    params: { w, h, n, diff },
  })),
  defaultParams: () => ({ ...OPENING }),
  encodeParams: (p, full) => `${p.w}x${p.h}n${p.n}${full ? `d${DIFFICULTY_CHARS[p.diff]}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:n(\d+))?(?:d(.))?/.exec(str);
    if (!m || !m[1]) throw new Error(tx`expected WxHnN`);
    const w = parseInt(m[1], 10);
    const h = m[2] ? parseInt(m[2], 10) : w;
    const n = m[3] ? parseInt(m[3], 10) : Math.floor((w * h) / 8);
    const di = m[4] ? DIFFICULTY_CHARS.indexOf(m[4]) : -1;
    return { w, h, n, diff: di >= 0 ? di : DEFAULTS.diff };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.n, p.diff].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (p.n < 5) return tx`Must have at least five regions`;
    if (p.n > p.w * p.h) return tx`Too many regions to fit in grid`;
    if (full && (p.diff < 0 || p.diff >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'string', name: 'Regions', value: String(p.n) },
      { type: 'choices', name: 'Difficulty', choices: PRESET_DIFFICULTIES, selected: p.diff },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "20.5" or "20x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      n: int(2),
      diff: (items[3] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generateMap(p, rng);
  },

  validateDesc(p, desc) {
    return validateDescription(p.w, p.h, p.n, desc);
  },

  newGame(p, desc) {
    const map = buildLayout(p.w, p.h, p.n, desc);
    const colouring = new Int8Array(p.n).fill(-1);
    const comma = desc.indexOf(',');
    let pos = 0;
    for (const ch of desc.slice(comma + 1)) {
      const c = ch.charCodeAt(0);
      if (c >= 48 && c < 48 + FOUR) colouring[pos++] = c - 48;
      else pos += c - 96;
    }
    return makeState(map, colouring);
  },

  canSolve: true,
  solve(orig, curr, aux) {
    let sol = solutionFor(orig, aux);
    if (!sol) {
      sol = orig.colouring.slice();
      const ret = solveMap(orig.map, sol, DIFF_RECURSE);
      if (ret === SOLVE_IMPOSSIBLE) throw new Error(tx`Puzzle is inconsistent`);
      if (ret !== SOLVE_UNIQUE)
        throw new Error(tx`Unable to find a unique solution for this puzzle`);
    }
    let move = 'S';
    for (let i = 0; i < orig.n; i++) if (curr.colouring[i] !== sol[i]) move += `;${sol[i]}:${i}`;
    return move;
  },

  newUI: () => ({
    dragColour: -2,
    dragPencil: 0,
    dragX: 0,
    dragY: 0,
    pressRegion: -1,
    pressSwatch: -1,
    swatchToggle: false,
    selColour: -2,
    keyDrag: false,
    cx: 0,
    cy: 0,
    cursorVisible: false,
    curMoved: false,
    lastMove: 0,
    showNumbers: false,
  }),
  changedState(ui, old, next) {
    // A drag started on a state that no longer exists (undo, redo, new game) is dropped.
    ui.dragColour = -2;
    ui.keyDrag = false;
    // A finished map is not left with a keyboard cursor sitting on it, as in the other games.
    if (!old.completed && next.completed) ui.cursorVisible = false;
  },

  // A display toggle for talking a puzzle over, so it waits in the pause menu; it shows
  // whether it is on.
  actions: [
    {
      label: 'Numbers',
      key: 'L',
      pressed: (_s, ui) => ui.showNumbers,
      view: true,
      title: 'Show a number in every region (L)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const L = state.map;
    const g = geometry(ds.tileSize, L.w, L.h);
    const ch = keyChar(b);

    if (ch === 'l' || ch === 'L') {
      ui.showNumbers = !ui.showNumbers;
      return '';
    }
    if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, L.w, L.h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      ui.curMoved = true;
      ui.lastMove = b;
      return '';
    }
    if (ch !== null && ch >= '1' && ch <= String(FOUR)) {
      const c = ch.charCodeAt(0) - 49;
      ui.cursorVisible = true;
      ui.dragColour = -2;
      ui.keyDrag = false;
      const pt = cursorPoint(ui, g);
      const r = regionUnder(state, g, pt.x, pt.y);
      if (r < 0 || L.immutable[r] || state.colouring[r] === c) return '';
      return buildMove(state, r, c, 0);
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const pt = cursorPoint(ui, g);
      const r = regionUnder(state, g, pt.x, pt.y);
      if (ui.dragColour === -2) {
        if (b === CURSOR_SELECT2) {
          // Space clears the region under the cursor.
          if (r < 0 || L.immutable[r]) return '';
          if (state.colouring[r] < 0 && state.pencil[r] === 0) return '';
          return buildMove(state, r, -1, 0);
        }
        // Enter picks up the colour under the cursor.
        ui.dragColour = r >= 0 ? state.colouring[r] : -1;
        ui.dragPencil = r >= 0 && state.colouring[r] < 0 ? state.pencil[r] : 0;
        ui.keyDrag = true;
        ui.curMoved = false;
        return '';
      }
      // Enter again drops it; Space drops it as a pencil mark. Twice in place clears.
      if (!ui.curMoved) ui.dragColour = -1;
      return drop(state, ui, r, b === CURSOR_SELECT2);
    }

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      ui.cursorVisible = false;
      ui.keyDrag = false;
      ui.dragX = mx;
      ui.dragY = my;
      const s = swatchAt(g, mx, my);
      if (s >= 0) {
        // The selection only changes when the press comes back up on this swatch: a drag
        // from the palette onto a region paints it and leaves the selection as it was, so
        // the next tap on this swatch picks it rather than dropping it.
        const c = s < FOUR ? s : -1;
        ui.swatchToggle = ui.selColour === c;
        ui.dragColour = c;
        ui.dragPencil = 0;
        ui.pressRegion = -1;
        ui.pressSwatch = s;
        return '';
      }
      const r = regionUnder(state, g, mx, my);
      ui.pressRegion = r;
      ui.pressSwatch = -1;
      if (r >= 0) {
        ui.dragColour = state.colouring[r];
        ui.dragPencil = state.colouring[r] >= 0 ? 0 : state.pencil[r];
      } else {
        ui.dragColour = -1;
        ui.dragPencil = 0;
      }
      return '';
    }
    if ((b === LEFT_DRAG || b === RIGHT_DRAG) && ui.dragColour > -2) {
      ui.dragX = mx;
      ui.dragY = my;
      return '';
    }
    if ((b === LEFT_RELEASE || b === RIGHT_RELEASE) && ui.dragColour > -2) {
      const r = regionUnder(state, g, mx, my);
      if (ui.pressSwatch >= 0 && r < 0) {
        // Released back on the palette: a click on a swatch selects it, and a click on the
        // selected one deselects it.
        const c = ui.dragColour;
        ui.dragColour = -2;
        if (swatchAt(g, mx, my) === ui.pressSwatch) ui.selColour = ui.swatchToggle ? -2 : c;
        return '';
      }
      if (r >= 0 && r === ui.pressRegion && ui.selColour !== -2) {
        // A plain click paints with the palette selection.
        ui.dragColour = ui.selColour;
        ui.dragPencil = 0;
      }
      return drop(state, ui, r, b === RIGHT_RELEASE);
    }
    return null;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { n, map } = state;
    const colouring = state.colouring.slice();
    const pencil = state.pencil.slice();
    let cheated = state.cheated;
    for (const part of move.split(';')) {
      if (part === 'S') {
        cheated = true;
        continue;
      }
      const m = /^(p?)([0-3C]):(\d+)$/.exec(part);
      if (!m) return null;
      const k = parseInt(m[3], 10);
      if (k >= n) return null;
      const c = m[2] === 'C' ? -1 : m[2].charCodeAt(0) - 48;
      if (m[1]) {
        if (colouring[k] >= 0) return null;
        if (c < 0) pencil[k] = 0;
        else pencil[k] ^= 1 << c;
      } else {
        if (map.immutable[k] && c !== colouring[k]) return null;
        colouring[k] = c;
        pencil[k] = 0;
      }
    }
    return {
      ...state,
      colouring,
      pencil,
      cheated,
      completed: state.completed || isComplete(map, colouring),
    };
  },

  preferredTileSize: 24,
  computeSize(p, t) {
    const g = geometry(t, p.w, p.h);
    return { w: g.W, h: g.H };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, _dir, ui, animTime, flashTime) {
    const L = state.map;
    const { w, h, n } = L;
    const wh = w * h;
    const g = geometry(ds.tileSize, w, h);
    const t = g.t;
    const blank = flashTime > 0 && Math.floor(flashTime / FLASH_FRAME) % 2 === 0;
    const fills = COLOUR_TOKENS.map((tok) => dr.mix(tok, 'paper', 0.35));
    const dots = COLOUR_TOKENS.map((tok) => dr.mix(tok, 'paper', 0.1));
    const paper = dr.colour('paper');
    const shade = dr.colour('shade');
    const fillFor = (c: number) => (c < 0 ? paper : fills[c]);
    const k = oldState ? easeInOut(animTime / ANIM) : 1;

    // Region fills, crossfading any that just changed.
    const regionFill: string[] = new Array(n);
    for (let r = 0; r < n; r++) {
      if (blank) {
        regionFill[r] = shade;
        continue;
      }
      const nc = state.colouring[r];
      let f = fillFor(nc);
      if (oldState && k < 1) {
        const oc = oldState.colouring[r];
        if (oc !== nc) f = dr.mix(fillFor(oc), f, k);
      }
      regionFill[r] = f;
    }
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const tr = L.quad[TE * wh + i];
        const br = L.quad[BE * wh + i];
        const px = g.mapX + x * t;
        const py = g.mapY + y * t;
        dr.rect(px, py, t, t, regionFill[tr]);
        if (tr !== br) {
          const slash = L.quad[LE * wh + i] === tr;
          const pts = slash
            ? [px, py + t, px + t, py, px + t, py + t]
            : [px, py, px + t, py + t, px, py + t];
          dr.polygon(pts, regionFill[br], null, { rough: 0 });
        }
      }
    }

    // Pencil marks and region numbers.
    for (let r = 0; r < n; r++) {
      const p = L.regionPos[r];
      const cx = g.mapX + (p.x * t) / 2;
      const cy = g.mapY + (p.y * t) / 2;
      if (state.colouring[r] < 0 && state.pencil[r])
        drawPencil(dr, cx, cy, t, state.pencil[r], dots, r);
      if (ui.showNumbers) dr.text(cx, cy, String(r), { size: t * 0.45, colour: 'pencil' });
    }

    // Borders between regions, then the outline of the whole map.
    strokeBoundaries(dr, L, g, (a, b) => a >= 0 && b >= 0 && a !== b, 'ink', 2.2, 0);
    dr.rectOutline(g.mapX, g.mapY, g.mapW, g.mapH, 'ink', { width: 2.6 });

    for (const e of clashes(L, state.colouring)) {
      const p = L.edgePos[e];
      drawError(dr, g.mapX + (p.x * t) / 2, g.mapY + (p.y * t) / 2, t, e);
    }

    // The palette.
    for (let s = 0; s < SWATCHES; s++) {
      const sx = g.palX + s * (g.sw + g.gap);
      const sy = g.palY;
      const sel = ui.selColour === (s < FOUR ? s : -1);
      dr.roundRect(sx, sy, g.sw, g.sw, g.sw * 0.2, s < FOUR ? fills[s] : 'paper', 'ink', {
        width: 1.6,
        seed: 100 + s,
      });
      if (s < FOUR) {
        dr.text(sx + g.sw / 2, sy + g.sw / 2, String(s + 1), {
          size: g.sw * 0.5,
          colour: 'ink',
          alpha: 0.55,
        });
      } else {
        dr.cross(sx + g.sw / 2, sy + g.sw / 2, g.sw * 0.2, 'pencil', 1.6, { seed: 100 + s });
      }
      if (sel) dr.cursor(sx - 3, sy - 3, g.sw + 6, g.sw + 6);
    }

    // Keyboard cursor: outline the region it is in, plus a small box for the square.
    if (ui.cursorVisible) {
      const pt = cursorPoint(ui, g);
      const r = regionUnder(state, g, pt.x, pt.y);
      if (r >= 0) strokeBoundaries(dr, L, g, (a, b) => (a === r) !== (b === r), 'accent', 2.4, 7);
      const inset = t * 0.28;
      dr.cursor(
        g.mapX + ui.cx * t + inset,
        g.mapY + ui.cy * t + inset,
        t - 2 * inset,
        t - 2 * inset,
        'accent',
        1.8,
      );
    }

    // The colour being dragged.
    if (ui.dragColour > -2) {
      const pt = ui.keyDrag ? cursorPoint(ui, g) : { x: ui.dragX, y: ui.dragY };
      const r = t * 0.42;
      dr.circle(pt.x, pt.y, r, ui.dragColour >= 0 ? fills[ui.dragColour] : 'paper', 'ink', {
        width: 1.8,
        rough: 0.4,
      });
      if (ui.dragPencil) drawPencil(dr, pt.x, pt.y, t, ui.dragPencil, dots, 999);
    }
  },

  animLength(oldState, newState) {
    for (let i = 0; i < newState.n; i++)
      if (oldState.colouring[i] !== newState.colouring[i]) return ANIM;
    return 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  thumbnailParams: { w: 12, h: 9, n: 15, diff: DIFF_EASY },
});

export default game;
