/**
 * Input button codes. Mirrors the conventions of the original collection so game
 * logic can be reasoned about the same way: mouse buttons, drags and releases are
 * distinct codes, cursor keys have their own codes, and printable characters are
 * passed as their char code.
 */
export const LEFT_BUTTON = 0x0200;
export const MIDDLE_BUTTON = 0x0201;
export const RIGHT_BUTTON = 0x0202;
export const LEFT_DRAG = 0x0203;
export const MIDDLE_DRAG = 0x0204;
export const RIGHT_DRAG = 0x0205;
export const LEFT_RELEASE = 0x0206;
export const MIDDLE_RELEASE = 0x0207;
export const RIGHT_RELEASE = 0x0208;
export const CURSOR_UP = 0x0209;
export const CURSOR_DOWN = 0x020a;
export const CURSOR_LEFT = 0x020b;
export const CURSOR_RIGHT = 0x020c;
export const CURSOR_SELECT = 0x020d;
export const CURSOR_SELECT2 = 0x020e;

export const MOD_CTRL = 0x1000;
export const MOD_SHFT = 0x2000;
export const MOD_NUM_KEYPAD = 0x4000;
export const MOD_MASK = 0x7000;

export const KEY_BACKSPACE = 8;
export const KEY_ENTER = 13;
export const KEY_SPACE = 32;

export function isMouseDown(b: number): boolean {
  return b >= LEFT_BUTTON && b <= RIGHT_BUTTON;
}
export function isMouseDrag(b: number): boolean {
  return b >= LEFT_DRAG && b <= RIGHT_DRAG;
}
export function isMouseRelease(b: number): boolean {
  return b >= LEFT_RELEASE && b <= RIGHT_RELEASE;
}
export function isMouseEvent(b: number): boolean {
  return b >= LEFT_BUTTON && b <= RIGHT_RELEASE;
}
export function isCursorMove(b: number): boolean {
  return b === CURSOR_UP || b === CURSOR_DOWN || b === CURSOR_LEFT || b === CURSOR_RIGHT;
}
export function isCursorSelect(b: number): boolean {
  return b === CURSOR_SELECT || b === CURSOR_SELECT2;
}
/** Strip modifier bits from a button code. */
export function stripMods(b: number): number {
  return b & ~MOD_MASK;
}
/** The character for a printable key code, or null. */
export function keyChar(b: number): string | null {
  const c = stripMods(b);
  return c >= 32 && c < 0x100 ? String.fromCharCode(c) : null;
}

/**
 * Move a cursor position in response to a cursor key. Returns the new position.
 * When `wrap` is true the cursor wraps around the edges; otherwise it clamps.
 */
export function moveCursor(
  button: number,
  x: number,
  y: number,
  w: number,
  h: number,
  wrap = false,
): { x: number; y: number } {
  let dx = 0;
  let dy = 0;
  switch (stripMods(button)) {
    case CURSOR_UP:
      dy = -1;
      break;
    case CURSOR_DOWN:
      dy = 1;
      break;
    case CURSOR_LEFT:
      dx = -1;
      break;
    case CURSOR_RIGHT:
      dx = 1;
      break;
    default:
      return { x, y };
  }
  if (wrap) {
    return { x: (((x + dx) % w) + w) % w, y: (((y + dy) % h) + h) % h };
  }
  return { x: Math.max(0, Math.min(w - 1, x + dx)), y: Math.max(0, Math.min(h - 1, y + dy)) };
}
