import type { Tutorial } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import type { SoloState, SoloUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

/** Is any digit pencilled into square (x, y)? */
function hasPencil(state: SoloState, x: number, y: number): boolean {
  const xy = y * state.cr + x;
  for (let n = 0; n < state.cr; n++) if (state.pencil[xy * state.cr + n]) return true;
  return false;
}

const digit = (state: SoloState, x: number, y: number) => state.grid[y * state.cr + x];

export const tutorial: Tutorial<SoloState, SoloUI> = {
  steps: [
    {
      gameId: '2x2:a2_3_4_3_4_1a2_1_4_3_4_3a1',
      text: 'Every row, every column and every outlined **2×2 block** must hold 1, 2, 3 and 4 exactly once. Three squares are missing on this little grid.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.cr, state.cr),
    },
    {
      text: 'This **block** already has a 2, a 3 and a 4, so its blank square can only be a **1**. Click that square and press the **1** key.',
      textTouch:
        'This **block** already has a 2, a 3 and a 4, so its blank square can only be a **1**. Tap that square, then tap **1** on the keypad.',
      highlight: ({ tileSize }) => cellRect(0, 0, tileSize, border(tileSize), 2, 2),
      target: '[data-key="1"]',
      pointer: ({ tileSize }) => cellCentre(0, 0, tileSize, border(tileSize)),
      press: '1',
      waitFor: ({ state }) => digit(state, 0, 0) === 1,
    },
    {
      text: 'Not sure about a square? **Right-click** this blank one and press **2** to pencil the digit in as a note.',
      textTouch:
        'Not sure about a square? Tap this blank one, latch **✎** on the keypad, and tap **2** to pencil the digit in as a note.',
      highlight: ({ tileSize }) => cellRect(3, 1, tileSize, border(tileSize)),
      target: '[data-key="pencil"]',
      // A plain tap on a touch screen, as `textTouch` says: a long-press selects the square
      // for pencil marks itself, and then the next step's "tap ✎ to stop pencilling" does
      // not stop it — the 2 rubs the note out again and the step never completes.
      pointer: ({ tileSize, touch }) => ({
        ...cellCentre(3, 1, tileSize, border(tileSize)),
        ...(touch ? {} : { button: 'right' as const }),
      }),
      press: '2',
      waitFor: ({ state }) => hasPencil(state, 3, 1),
    },
    {
      text: 'Its row already holds 3, 4 and 1, so the note was right. **Left-click** the same square and press **2** to write the answer in.',
      textTouch:
        'Its row already holds 3, 4 and 1, so the note was right. The square is still chosen, so tap **✎** to stop pencilling and then **2** to write the answer in.',
      highlight: ({ tileSize }) => cellRect(3, 1, tileSize, border(tileSize)),
      target: '[data-key="2"]',
      // On a touch screen the square is still chosen from the last step, and tapping it
      // again — what a pointer on it asks for — would deselect it; point at it only when
      // it is not chosen any more.
      pointer: ({ tileSize, ui, touch }) =>
        touch && ui.hshow && ui.hx === 3 && ui.hy === 1
          ? null
          : cellCentre(3, 1, tileSize, border(tileSize)),
      press: '2',
      waitFor: ({ state }) => digit(state, 3, 1) === 2,
    },
    {
      text: 'One square left. Its row already has 4, 3 and 1 — click it and press the missing digit.',
      textTouch:
        'One square left. Its row already has 4, 3 and 1 — tap it, then tap the missing digit on the keypad.',
      highlight: ({ tileSize }) => cellRect(2, 3, tileSize, border(tileSize)),
      pointer: ({ tileSize }) => cellCentre(2, 3, tileSize, border(tileSize)),
      press: '2',
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Solved! **Undo** takes back a wrong digit, and the **M** key pencils every option into every blank square at once.',
      textTouch:
        'Solved! **Undo** takes back a wrong digit, and **Marks**, in the pause menu, pencils every option into every blank square at once.',
      target: '[data-cmd="undo"]',
    },
  ],
};
