import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_SELECT,
  CURSOR_SELECT2,
  CURSOR_UP,
  LEFT_BUTTON,
  MIDDLE_BUTTON,
  MOD_CTRL,
  MOD_SHFT,
  RIGHT_BUTTON,
  stripMods,
} from '../../framework/input';
import { parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { Random, newSeedString } from '../../framework/rng';
import { LOCK_GLYPH } from '../../framework/glyphs';
import help from './help.md?raw';
import {
  computeActive,
  computeLoops,
  connected,
  countWires,
  D,
  DIR_BITS,
  DX,
  DY,
  encodeDescription,
  hexToTiles,
  L,
  LOCKED,
  parseDescription,
  R,
  rotA,
  rotC,
  rotF,
  tilesToHex,
  U,
  validateDescription,
  wrapIndex,
  type Grid,
} from './core';
import { generateNet } from './generator';
import { searchSolution, solveNet } from './solver';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export interface NetParams {
  w: number;
  h: number;
  wrapping: boolean;
  /** Fraction of the wire-free edges that get a barrier, 0..1. */
  barriers: number;
  /** Generate puzzles with exactly one solution. */
  unique: boolean;
}

export interface NetState {
  w: number;
  h: number;
  wrapping: boolean;
  /** Wire bits (low four) plus LOCKED. */
  tiles: number[];
  /** Barrier bits per tile, including the border of a non-wrapping grid. */
  barriers: number[];
  /** The single tile turned by the last move, for the rotation animation. */
  lastRotate: { x: number; y: number; dir: number } | null;
  /** Every tile is currently powered. */
  solved: boolean;
  /** The network has been complete at some point. */
  completed: boolean;
  usedSolve: boolean;
}

export interface NetUI {
  /** Top-left tile of the view (scrolling is only possible on wrapping grids). */
  orgX: number;
  orgY: number;
  /** The tile from which power spreads. */
  cx: number;
  cy: number;
  curX: number;
  curY: number;
  cursorVisible: boolean;
  /** Random source for the Jumble command. */
  rng: Random;
  /**
   * The Lock tool: a left click locks or unlocks a tile instead of turning it, which is
   * otherwise a middle-click (or Shift-click, or a two-finger tap).
   */
  lockMode: boolean;
}

const ROTATE_TIME = 0.13;
const FLASH_FRAME = 0.07;
const MAX_SIDE = 32;

// ------------------------------------------------------------------ helpers

function grid(s: { w: number; h: number; wrapping: boolean }): Grid {
  return { w: s.w, h: s.h, wrapping: s.wrapping };
}

function allPowered(g: Grid, tiles: number[], barriers: number[]): boolean {
  const active = computeActive(g, tiles, barriers, 0, 0);
  for (let i = 0; i < tiles.length; i++) if (tiles[i] & 15 && !active[i]) return false;
  return true;
}

function makeState(p: NetParams, tiles: number[], barriers: number[], wrapping: boolean): NetState {
  const g = { w: p.w, h: p.h, wrapping };
  const solved = allPowered(g, tiles, barriers);
  return {
    w: p.w,
    h: p.h,
    wrapping,
    tiles,
    barriers,
    lastRotate: null,
    solved,
    completed: solved,
    usedSolve: false,
  };
}

function border(t: number): number {
  return Math.round(t * 0.3);
}

/** Move a game coordinate one step, wrapping round the grid. */
function stepWrap(x: number, y: number, k: number, w: number, h: number) {
  return { x: (x + DX[k] + w) % w, y: (y + DY[k] + h) % h };
}

function cursorDir(button: number): number {
  switch (button) {
    case CURSOR_RIGHT:
      return 0;
    case CURSOR_UP:
      return 1;
    case CURSOR_LEFT:
      return 2;
    case CURSOR_DOWN:
      return 3;
    default:
      return -1;
  }
}

function formatProbability(p: number): string {
  return String(Math.round(p * 1000) / 1000);
}

/**
 * The barrier probability as typed. A decimal comma is read as a point — a Dutch or German
 * phone's decimal keypad offers only the comma — and anything that is not a number gives
 * NaN, so `validateParams` rejects it instead of `parseFloat` quietly reading `0,5`
 * as 0 and `0.5x` as 0.5.
 */
function parseProbability(s: string): number {
  return s === '' ? 0 : Number(s.replace(',', '.'));
}

// ------------------------------------------------------------------ the game

const game = defineGame<NetParams, NetState, NetUI>({
  id: 'net',
  name: 'Net',
  description: 'Rotate the tiles until every one is wired to the centre.',
  alsoKnownAs: 'NetWalk',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [5, 5, false],
      [7, 7, false],
      [9, 9, false],
      [11, 11, false],
      [13, 11, false],
      [5, 5, true],
      [7, 7, true],
      [9, 9, true],
      [11, 11, true],
      [13, 11, true],
    ] as [number, number, boolean][]
  ).map(([w, h, wrapping]) => ({
    name: `${w}×${h}${wrapping ? ' wrapping' : ''}`,
    params: { w, h, wrapping, barriers: 0, unique: true },
  })),
  defaultParams: () => ({ w: 5, h: 5, wrapping: false, barriers: 0, unique: true }),
  encodeParams(p, full) {
    let s = `${p.w}x${p.h}`;
    if (p.wrapping) s += 'w';
    if (full && p.barriers) s += `b${formatProbability(p.barriers)}`;
    if (full && !p.unique) s += 'a';
    return s;
  },
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    const p: NetParams = { w: r.w, h: r.h, wrapping: false, barriers: 0, unique: true };
    let rest = r.rest;
    while (rest.length) {
      if (rest[0] === 'w') {
        p.wrapping = true;
        rest = rest.slice(1);
      } else if (rest[0] === 'b') {
        const m = /^b(\d*\.?\d*)/.exec(rest)!;
        p.barriers = m[1] ? parseFloat(m[1]) : 0;
        rest = rest.slice(m[0].length);
      } else if (rest[0] === 'a') {
        p.unique = false;
        rest = rest.slice(1);
      } else {
        rest = rest.slice(1);
      }
    }
    return p;
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must both be at least one`;
    if (p.w < 2 && p.h < 2) return tx`At least one of width and height must be greater than one`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (!Number.isFinite(p.barriers) || p.barriers < 0 || p.barriers > 1)
      return tx`Barrier probability must be a number between 0 and 1`;
    if (full && p.unique && p.wrapping && (p.w < 3 || p.h < 3))
      return tx`A wrapping puzzle needs a width and height of at least 3 to have a unique solution`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'boolean', name: 'Walls wrap around', value: p.wrapping },
      // A fraction between 0 and 1, even when the preset of the day happens to show `0`.
      {
        type: 'string',
        name: 'Barrier probability',
        value: formatProbability(p.barriers),
        keyboard: 'decimal',
      },
      { type: 'boolean', name: 'Ensure unique solution', value: p.unique },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value.trim();
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => (/^-?\d+$/.test(str(i)) ? parseInt(str(i), 10) : NaN);
    const bool = (i: number) => (items[i] as { value: boolean }).value;
    return {
      w: int(0),
      h: int(1),
      wrapping: bool(2),
      barriers: parseProbability(str(3)),
      unique: bool(4),
    };
  },

  newDesc(p, rng) {
    const gen = generateNet(
      { w: p.w, h: p.h, wrapping: p.wrapping, unique: p.unique, barrierProbability: p.barriers },
      rng,
    );
    const g = { w: p.w, h: p.h, wrapping: p.wrapping };
    return { desc: encodeDescription(g, gen.puzzle, gen.barriers), aux: tilesToHex(gen.solution) };
  },

  validateDesc(p, desc) {
    return validateDescription(p.w, p.h, desc);
  },

  newGame(p, desc) {
    const parsed = parseDescription(p.w, p.h, p.wrapping, desc);
    return makeState(p, parsed.tiles, parsed.barriers, parsed.wrapping);
  },

  canSolve: true,
  solve(orig, curr, aux) {
    const n = curr.w * curr.h;
    const g = grid(curr);
    // Target orientation per tile; -1 leaves a tile as it is.
    let target: number[];
    if (aux && /^[0-9a-f]+$/i.test(aux) && aux.length === n) {
      target = hexToTiles(aux);
    } else {
      const res = solveNet(g, orig.tiles, orig.barriers);
      if (res.complete) {
        target = res.candidates.map((c) => c[0]);
      } else {
        const found = res.contradiction ? null : searchSolution(g, orig.tiles, orig.barriers);
        if (found) target = found;
        else if (res.contradiction) throw new Error(tx`This puzzle has no solution`);
        else target = res.candidates.map((c) => (c.length === 1 ? c[0] : -1));
      }
    }
    const parts: string[] = [];
    for (let i = 0; i < n; i++) {
      if (target[i] < 0) continue;
      const from = curr.tiles[i];
      const want = target[i] & 15;
      const have = from & 15;
      const xy = `${i % curr.w},${Math.floor(i / curr.w)}`;
      if (have === want && from & LOCKED) continue;
      if (from & LOCKED) parts.push(`L${xy}`);
      if (want === rotA(have)) parts.push(`A${xy}`);
      else if (want === rotC(have)) parts.push(`C${xy}`);
      else if (want === rotF(have)) parts.push(`F${xy}`);
      parts.push(`L${xy}`);
    }
    if (parts.length === 0) {
      if (curr.solved) throw new Error(tx`Already solved`);
      throw new Error(tx`Unable to work out any more of this puzzle`);
    }
    return 'S;' + parts.join(';');
  },

  textFormat(s) {
    const glyphs = ' ╶╵└╴─┘┴╷┌│├┐┬┤┼';
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) row += glyphs[s.tiles[y * s.w + x] & 15];
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI(state) {
    return {
      orgX: 0,
      orgY: 0,
      cx: state.w >> 1,
      cy: state.h >> 1,
      curX: state.w >> 1,
      curY: state.h >> 1,
      cursorVisible: false,
      rng: new Random(newSeedString()),
      lockMode: false,
    };
  },
  encodeUI: (ui) => `O${ui.orgX},${ui.orgY};C${ui.cx},${ui.cy}`,
  decodeUI(ui, enc) {
    const m = /^O(\d+),(\d+);C(\d+),(\d+)$/.exec(enc);
    if (!m) return;
    ui.orgX = parseInt(m[1], 10);
    ui.orgY = parseInt(m[2], 10);
    ui.cx = parseInt(m[3], 10);
    ui.cy = parseInt(m[4], 10);
  },

  // The Lock tool in the HUD (the middle-click, for a mouse or a finger); then the
  // keyboard-only extras: shuffling every unlocked tile, and — on a wrapping grid —
  // scrolling the view, which Shift plus an arrow key does.
  actions: [
    {
      label: 'Lock',
      key: 'K',
      hud: true,
      glyph: LOCK_GLYPH,
      pressed: (_s, ui) => ui.lockMode,
      title: 'Click tiles to lock or unlock them instead of turning them (K)',
    },
    { label: 'Jumble', key: 'J', title: 'Randomly turn every unlocked tile (J)' },
    {
      label: '←',
      key: MOD_SHFT | CURSOR_LEFT,
      id: 'scroll-left',
      repeat: true,
      title: 'Scroll the view left (Shift+←)',
      when: (s) => s.wrapping,
    },
    {
      label: '↑',
      key: MOD_SHFT | CURSOR_UP,
      id: 'scroll-up',
      repeat: true,
      title: 'Scroll the view up (Shift+↑)',
      when: (s) => s.wrapping,
    },
    {
      label: '↓',
      key: MOD_SHFT | CURSOR_DOWN,
      id: 'scroll-down',
      repeat: true,
      title: 'Scroll the view down (Shift+↓)',
      when: (s) => s.wrapping,
    },
    {
      label: '→',
      key: MOD_SHFT | CURSOR_RIGHT,
      id: 'scroll-right',
      repeat: true,
      title: 'Scroll the view right (Shift+→)',
      when: (s) => s.wrapping,
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    const { w, h } = state;
    const b = stripMods(button);
    const shift = (button & MOD_SHFT) !== 0;
    const ctrl = (button & MOD_CTRL) !== 0;
    let nullret: string | null = null;
    const wasVisible = ui.cursorVisible;
    let tx: number;
    let ty: number;
    let action: 'A' | 'C' | 'F' | 'L';

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || b === MIDDLE_BUTTON) {
      if (ui.cursorVisible) {
        ui.cursorVisible = false;
        nullret = '';
      }
      const t = ds.tileSize;
      const bd = border(t);
      const px = Math.floor((mx - bd) / t);
      const py = Math.floor((my - bd) / t);
      if (px < 0 || py < 0 || px >= w || py >= h) return nullret;
      tx = (px + ui.orgX) % w;
      ty = (py + ui.orgY) % h;
      action = b === LEFT_BUTTON ? (ui.lockMode ? 'L' : 'A') : b === RIGHT_BUTTON ? 'C' : 'L';
    } else if (cursorDir(b) >= 0) {
      const k = cursorDir(b);
      if (shift && !state.wrapping) return null;
      if (shift) ({ x: ui.orgX, y: ui.orgY } = stepWrap(ui.orgX, ui.orgY, k, w, h));
      if (ctrl) ({ x: ui.cx, y: ui.cy } = stepWrap(ui.cx, ui.cy, k, w, h));
      if (!shift && !ctrl) {
        ({ x: ui.curX, y: ui.curY } = stepWrap(ui.curX, ui.curY, k, w, h));
        ui.cursorVisible = true;
      }
      return '';
    } else if ((b === CURSOR_SELECT || b === CURSOR_SELECT2) && !ui.cursorVisible) {
      // Enter and Space (a pad's A and X) first bring back the cursor they are about to act
      // on, as in the other grid games, instead of turning or locking a tile nobody can see.
      ui.cursorVisible = true;
      return '';
    } else if (b === CURSOR_SELECT || b === 'a'.charCodeAt(0) || b === 'A'.charCodeAt(0)) {
      action = 'A';
      tx = ui.curX;
      ty = ui.curY;
      ui.cursorVisible = true;
    } else if (b === 'd'.charCodeAt(0) || b === 'D'.charCodeAt(0)) {
      action = 'C';
      tx = ui.curX;
      ty = ui.curY;
      ui.cursorVisible = true;
    } else if (b === 'f'.charCodeAt(0) || b === 'F'.charCodeAt(0)) {
      action = 'F';
      tx = ui.curX;
      ty = ui.curY;
      ui.cursorVisible = true;
    } else if (
      b === CURSOR_SELECT2 ||
      b === 's'.charCodeAt(0) ||
      b === 'S'.charCodeAt(0) ||
      b === 'l'.charCodeAt(0) ||
      b === 'L'.charCodeAt(0)
    ) {
      action = 'L';
      tx = ui.curX;
      ty = ui.curY;
      ui.cursorVisible = true;
    } else if (b === 'k'.charCodeAt(0) || b === 'K'.charCodeAt(0)) {
      ui.lockMode = !ui.lockMode;
      return '';
    } else if (b === 'j'.charCodeAt(0) || b === 'J'.charCodeAt(0)) {
      const parts: string[] = [];
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const tile = state.tiles[y * w + x];
          if (tile & LOCKED) continue;
          const rot = ui.rng.upto(4);
          // A turn that leaves the tile as it was (a straight turned half round) is left
          // out, since a jumble does not animate.
          if (rot && [rotA, rotF, rotC][rot - 1](tile) !== tile)
            parts.push(`${'AFC'[rot - 1]}${x},${y}`);
        }
      }
      // With every tile locked (or every roll a no-op) nothing would change, and an undo
      // step that does nothing is only confusing.
      return parts.length ? 'J;' + parts.join(';') : null;
    } else {
      return null;
    }

    // A key that only brought the cursor back still needs a redraw to show it.
    if (!wasVisible && ui.cursorVisible) nullret = '';
    const tile = state.tiles[ty * w + tx];
    if (action !== 'L' && tile & LOCKED) return nullret;
    // A turn that leaves the tile exactly as it was (a straight turned half round, a
    // cross turned at all) is no move, so it adds no empty undo step.
    if (action !== 'L' && { A: rotA, C: rotC, F: rotF }[action](tile) === tile) return nullret;
    return `${action}${tx},${ty}`;
  },

  executeMove(state, move) {
    const { w, h } = state;
    let rest = move;
    let animate = true;
    let usedSolve = state.usedSolve;
    if (rest[0] === 'J' || rest[0] === 'S') {
      if (rest[0] === 'S') usedSolve = true;
      animate = false;
      rest = rest.slice(1);
      if (rest[0] === ';') rest = rest.slice(1);
    }
    const tiles = state.tiles.slice();
    let lastRotate: NetState['lastRotate'] = null;
    let last: { x: number; y: number } | null = null;
    if (rest.length) {
      for (const part of rest.split(';')) {
        const m = /^([ACFL])(\d+),(\d+)$/.exec(part);
        if (!m) return null;
        const x = parseInt(m[2], 10);
        const y = parseInt(m[3], 10);
        if (x >= w || y >= h) return null;
        const i = y * w + x;
        switch (m[1]) {
          case 'A':
            tiles[i] = rotA(tiles[i]);
            lastRotate = { x, y, dir: 1 };
            break;
          case 'C':
            tiles[i] = rotC(tiles[i]);
            lastRotate = { x, y, dir: -1 };
            break;
          case 'F':
            tiles[i] = rotF(tiles[i]);
            lastRotate = { x, y, dir: 2 };
            break;
          default:
            tiles[i] ^= LOCKED;
            lastRotate = null;
        }
        last = { x, y };
      }
    }
    if (animate && !last) return null;
    if (!animate) lastRotate = null;
    const solved = allPowered(grid(state), tiles, state.barriers);
    return {
      ...state,
      tiles,
      lastRotate,
      solved,
      completed: state.completed || solved,
      usedSolve,
    };
  },

  preferredTileSize: 44,
  computeSize(p, t) {
    const bd = border(t);
    return { w: p.w * t + 2 * bd, h: p.h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds, oldState, newState, dir, ui, animTime, flashTime) {
    // While a tile turns, the picture is the previous position with that tile rotated
    // part of the way; at the end of the animation the new position appears.
    let state = newState;
    let angle = 0;
    let animIdx = -1;
    const rot = dir < 0 ? oldState?.lastRotate : newState.lastRotate;
    if (oldState && rot && animTime < ROTATE_TIME) {
      state = oldState;
      animIdx = rot.y * state.w + rot.x;
      angle = rot.dir * dir * (Math.PI / 2) * (animTime / ROTATE_TIME);
    }
    const { w, h } = state;
    const g = grid(state);
    const t = ds.tileSize;
    const bd = border(t);
    const orgX = ((ui.orgX % w) + w) % w;
    const orgY = ((ui.orgY % h) + h) % h;
    const srcX = ((ui.cx % w) + w) % w;
    const srcY = ((ui.cy % h) + h) % h;
    const gameIndex = (px: number, py: number) => ((py + orgY) % h) * w + ((px + orgX) % w);
    const active = computeActive(g, state.tiles, state.barriers, srcX, srcY);
    const loops = computeLoops(g, state.tiles, state.barriers);
    const srcIdx = srcY * w + srcX;
    const srcPX = (srcX - orgX + w) % w;
    const srcPY = (srcY - orgY + h) % h;
    const frame = flashTime > 0 ? Math.floor(flashTime / FLASH_FRAME) : -1;

    // Tile backgrounds: locked tiles are shaded; the completion flash ripples the
    // shading outwards from the source.
    for (let py = 0; py < h; py++) {
      for (let px = 0; px < w; px++) {
        const i = gameIndex(px, py);
        let shaded = (state.tiles[i] & LOCKED) !== 0;
        if (frame >= 0) {
          const dist = Math.max(Math.abs(px - srcPX), Math.abs(py - srcPY));
          if (frame >= dist && frame < dist + 4) shaded = ((frame - dist) & 1) === 1;
        }
        if (shaded) dr.rect(bd + px * t, bd + py * t, t, t, 'shade');
      }
    }

    // Grid lines, and the frame: solid ink where the border is a wall, a light dashed
    // line where the grid wraps round.
    for (let x = 1; x < w; x++) dr.line(bd + x * t, bd, bd + x * t, bd + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(bd, bd + y * t, bd + w * t, bd + y * t, 'faint', 1.2);
    if (state.wrapping) {
      dr.rectOutline(bd, bd, w * t, h * t, 'pencil', { width: 1.2, dash: [5, 6] });
    } else {
      dr.rectOutline(bd, bd, w * t, h * t, 'ink', { width: 2.8 });
    }

    // Source highlight, under the wires: a soft accent wash (distinct from the
    // keyboard cursor, which is an outline).
    {
      const pad = Math.max(1.5, t * 0.05);
      dr.roundRect(
        bd + srcPX * t + pad,
        bd + srcPY * t + pad,
        t - 2 * pad,
        t - 2 * pad,
        t * 0.12,
        dr.withAlpha('accent', 0.14),
        null,
      );
    }

    // Wires. A matched pair of wires between two tiles that sit next to each other on
    // screen is drawn as one stroke from centre to centre so the join is seamless;
    // anything else (a loose end, a wire across the wrap seam, a turning tile) is a
    // stub from the centre to the edge.
    const wireWidth = (powered: boolean) => Math.max(2.5, t * (powered ? 0.11 : 0.085));
    for (let py = 0; py < h; py++) {
      for (let px = 0; px < w; px++) {
        const i = gameIndex(px, py);
        const v = state.tiles[i] & 15;
        if (!v) continue;
        const cx = bd + px * t + t / 2;
        const cy = bd + py * t + t / 2;
        const turning = i === animIdx;
        const powered = active[i] === 1;
        for (let k = 0; k < 4; k++) {
          if (!(v & DIR_BITS[k])) continue;
          const colour = loops[i] & DIR_BITS[k] ? 'red' : powered ? 'blue' : 'pencil';
          const width = wireWidth(powered);
          const j = wrapIndex(g, i, k);
          const npx = px + DX[k];
          const npy = py + DY[k];
          const adjacent = npx >= 0 && npy >= 0 && npx < w && npy < h;
          const joined =
            adjacent && j !== animIdx && connected(g, state.tiles, state.barriers, i, k);
          if (turning || !joined) {
            let ex = (DX[k] * t) / 2;
            let ey = (DY[k] * t) / 2;
            if (turning) {
              const c = Math.cos(angle);
              const s = Math.sin(angle);
              [ex, ey] = [ex * c + ey * s, -ex * s + ey * c];
            }
            dr.line(cx, cy, cx + ex, cy + ey, colour, width, turning ? { rough: 0 } : {});
          } else if (k === 0 || k === 3) {
            dr.line(cx, cy, cx + DX[k] * t, cy + DY[k] * t, colour, width);
          }
        }
      }
    }

    // Centres: a filled dot on a powered leaf, a hollow one on an unpowered leaf, and an
    // accent marker on the source tile.
    for (let py = 0; py < h; py++) {
      for (let px = 0; px < w; px++) {
        const i = gameIndex(px, py);
        const v = state.tiles[i] & 15;
        const cx = bd + px * t + t / 2;
        const cy = bd + py * t + t / 2;
        if (i === srcIdx) {
          dr.circle(cx, cy, t * 0.15, 'accent', 'ink', { width: 1.4 });
        } else if (countWires(v) === 1) {
          if (active[i]) dr.circle(cx, cy, t * 0.14, 'blue', null);
          else dr.circle(cx, cy, t * 0.14, 'paper', 'pencil', { width: 1.6 });
        }
      }
    }

    // Barriers: heavy strokes along tile edges. Consecutive barriers on one grid line
    // are merged into a single stroke.
    const barrierWidth = Math.max(3, t * 0.09);
    const drawRun = (x1: number, y1: number, x2: number, y2: number) =>
      dr.line(x1, y1, x2, y2, 'ink', barrierWidth, { cap: 'round' });
    for (let yb = 0; yb <= h; yb++) {
      if (!state.wrapping && (yb === 0 || yb === h)) continue;
      let run = -1;
      for (let px = 0; px <= w; px++) {
        const has =
          px < w &&
          (yb < h
            ? (state.barriers[gameIndex(px, yb)] & U) !== 0
            : (state.barriers[gameIndex(px, h - 1)] & D) !== 0);
        if (has && run < 0) run = px;
        if (!has && run >= 0) {
          drawRun(bd + run * t, bd + yb * t, bd + px * t, bd + yb * t);
          run = -1;
        }
      }
    }
    for (let xb = 0; xb <= w; xb++) {
      if (!state.wrapping && (xb === 0 || xb === w)) continue;
      let run = -1;
      for (let py = 0; py <= h; py++) {
        const has =
          py < h &&
          (xb < w
            ? (state.barriers[gameIndex(xb, py)] & L) !== 0
            : (state.barriers[gameIndex(w - 1, py)] & R) !== 0);
        if (has && run < 0) run = py;
        if (!has && run >= 0) {
          drawRun(bd + xb * t, bd + run * t, bd + xb * t, bd + py * t);
          run = -1;
        }
      }
    }

    if (ui.cursorVisible) {
      const cpx = (((ui.curX - orgX) % w) + w) % w;
      const cpy = (((ui.curY - orgY) % h) + h) % h;
      const pad = Math.max(2, t * 0.04);
      dr.cursor(bd + cpx * t + pad, bd + cpy * t + pad, t - 2 * pad, t - 2 * pad);
    }

    let powered = 0;
    let wired = 0;
    for (let i = 0; i < w * h; i++) {
      if (active[i]) powered++;
      if (state.tiles[i] & 15) wired++;
    }
    const prefix = state.usedSolve
      ? tr('status.autoSolvedPrefix')
      : state.completed
        ? tr('status.completedPrefix')
        : '';
    dr.statusBar(prefix + tr('games.net.status.active', { n: powered, total: wired }));
  },

  animLength(oldState, newState, dir) {
    const rot = dir < 0 ? oldState.lastRotate : newState.lastRotate;
    return rot ? ROTATE_TIME : 0;
  },
  flashLength(oldState, newState) {
    if (oldState.completed || !newState.completed || oldState.usedSolve || newState.usedSolve)
      return 0;
    return FLASH_FRAME * (Math.max(newState.w, newState.h) + 4);
  },
  status: (s) => (s.solved ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  thumbnailParams: { w: 5, h: 5, wrapping: false, barriers: 0, unique: true },
});

export default game;
