/**
 * Solo solver.
 *
 * Works on a "cube" of candidates — for every square and digit, whether that digit could
 * still go there — and applies increasingly sophisticated modes of reasoning until the
 * grid is full or nothing more can be deduced. The hardest mode needed grades the
 * puzzle; the generator uses that to hit a requested difficulty and to check uniqueness.
 *
 * Difficulty levels (each includes everything below it):
 *  - Trivial: a digit has only one possible square left in some block.
 *  - Basic: the same for rows, columns and X-diagonals, and squares with one candidate.
 *  - Intermediate: intersections — if all places for a digit in a row lie in one block,
 *    it can go nowhere else in that block (and the other way round).
 *  - Advanced: set elimination — k squares of a region whose candidates together are only
 *    k digits must hold exactly those digits.
 *  - Extreme: set elimination on the positions of one digit across rows and columns, and
 *    forcing chains through squares with two candidates.
 *  - Unreasonable: guessing a digit in a constrained square and backtracking.
 *
 * Killer puzzles add cage reasoning with its own scale: single-square cages, minimum and
 * maximum sums of the other squares, the known ways of making a sum from distinct digits,
 * and cages deduced from the fixed total of every row, column and block.
 */
import type { BlockStructure } from './blocks';
import { cageClues } from './blocks';

export const DIFF_BLOCK = 0;
export const DIFF_SIMPLE = 1;
export const DIFF_INTERSECT = 2;
export const DIFF_SET = 3;
export const DIFF_EXTREME = 4;
export const DIFF_RECURSIVE = 5;
export const DIFF_AMBIGUOUS = 6;
export const DIFF_IMPOSSIBLE = 7;

export const KDIFF_SINGLE = 0;
export const KDIFF_MINMAX = 1;
export const KDIFF_SUMS = 2;
export const KDIFF_INTERSECT = 3;

/** The Custom dialog's words: the same ladder the Type menu's presets are named on. */
export const DIFF_NAMES = ['Very Easy', 'Easy', 'Medium', 'Hard', 'Expert', 'Extreme'];

export interface SolveResult {
  /** Hardest technique used, or DIFF_AMBIGUOUS / DIFF_IMPOSSIBLE. */
  diff: number;
  /** Hardest killer technique used. */
  kdiff: number;
}

/** Square index of the i-th square on the `\` diagonal. */
export const diag0 = (i: number, cr: number) => i * (cr + 1);
/** Square index of the i-th square on the `/` diagonal (top right to bottom left). */
export const diag1 = (i: number, cr: number) => (i + 1) * (cr - 1);
export const onDiag0 = (xy: number, cr: number) => xy % (cr + 1) === 0;
export const onDiag1 = (xy: number, cr: number) =>
  xy % (cr - 1) === 0 && xy > 0 && xy < cr * cr - 1;

/**
 * Sum tables: for `k` distinct digits from 1..max, which sets of digits (as bitmasks with
 * bit n set for digit n) add up to each total. Cached per maximum digit.
 */
const sumTables = new Map<number, number[][][]>();
function sumTable(max: number): number[][][] {
  let t = sumTables.get(max);
  if (t) return t;
  const maxSum = max * 4;
  t = [];
  for (let k = 0; k <= 4; k++) {
    const rows: number[][] = [];
    for (let s = 0; s <= maxSum; s++) rows.push([]);
    t.push(rows);
  }
  const rec = (k: number, minDigit: number, sum: number, bits: number, left: number) => {
    if (left === 0) {
      t![k][sum].push(bits);
      return;
    }
    for (let d = minDigit; d <= max; d++) rec(k, d + 1, sum + d, bits | (1 << d), left - 1);
  };
  for (let k = 2; k <= 4; k++) rec(k, 1, 0, 0, k);
  sumTables.set(max, t);
  return t;
}

/**
 * A cap on the guesses an Unreasonable solve may make, shared by all its nested solvers.
 * Once it runs out the solve reports DIFF_AMBIGUOUS: uniqueness was not shown.
 */
export interface GuessBudget {
  left: number;
}

interface ExtraCage {
  squares: number[];
  clue: number;
}

class Solver {
  readonly cr: number;
  readonly area: number;
  readonly blocks: BlockStructure;
  readonly xtype: boolean;
  readonly grid: Uint8Array;
  /** cube[xy*cr + n-1]: digit n still possible in square xy. */
  readonly cube: Uint8Array;
  /** row[y*cr+n-1] etc.: digit n already placed in that row / column / block. */
  readonly row: Uint8Array;
  readonly col: Uint8Array;
  readonly blk: Uint8Array;
  /** diag[n-1] for `\`, diag[cr+n-1] for `/`. */
  readonly diag: Uint8Array | null;

  // Killer bookkeeping: a working copy of the cages that loses filled squares.
  readonly origCages: BlockStructure | null;
  readonly kgrid: Uint8Array | null;
  kb: number[][] | null = null;
  kwhich: Int32Array | null = null;
  kclues: number[] | null = null;
  extra: ExtraCage[] = [];
  /** Rows, columns and blocks as square lists, for deduced cages. */
  regions: number[][] = [];

  readonly maxdiff: number;
  readonly maxkdiff: number;
  kdiff = KDIFF_SINGLE;

  // Scratch space.
  private readonly idx: Int32Array;
  private readonly idx2: Int32Array;
  private readonly setIdx: Int32Array;

  constructor(
    cr: number,
    blocks: BlockStructure,
    kblocks: BlockStructure | null,
    xtype: boolean,
    grid: Uint8Array,
    kgrid: Uint8Array | null,
    maxdiff: number,
    maxkdiff: number,
    readonly guesses: GuessBudget | null = null,
  ) {
    this.cr = cr;
    this.area = cr * cr;
    this.blocks = blocks;
    this.xtype = xtype;
    this.grid = grid;
    this.maxdiff = maxdiff;
    this.maxkdiff = maxkdiff;
    this.cube = new Uint8Array(this.area * cr).fill(1);
    this.row = new Uint8Array(this.area);
    this.col = new Uint8Array(this.area);
    this.blk = new Uint8Array(this.area);
    this.diag = xtype ? new Uint8Array(2 * cr) : null;
    this.idx = new Int32Array(cr);
    this.idx2 = new Int32Array(cr);
    this.setIdx = new Int32Array(this.area);
    this.origCages = kblocks;
    this.kgrid = kgrid;
    if (kblocks && kgrid) {
      this.kb = kblocks.blocks.map((b) => b.slice());
      this.kwhich = kblocks.whichblock.slice();
      this.kclues = Array.from(cageClues(kblocks, kgrid));
      for (let n = 0; n < cr; n++) {
        const r: number[] = [];
        for (let i = 0; i < cr; i++) r.push(n * cr + i);
        this.regions.push(r);
      }
      for (let n = 0; n < cr; n++) {
        const c: number[] = [];
        for (let i = 0; i < cr; i++) c.push(i * cr + n);
        this.regions.push(c);
      }
      for (let n = 0; n < cr; n++) this.regions.push(blocks.blocks[n].slice());
    }
  }

  cubePos(xy: number, n: number): number {
    return xy * this.cr + n - 1;
  }

  /** Commit digit n to square (x, y) and rule it out everywhere it conflicts. */
  place(x: number, y: number, n: number): void {
    const { cr, cube } = this;
    const xy = y * cr + x;
    for (let i = 1; i <= cr; i++) if (i !== n) cube[this.cubePos(xy, i)] = 0;
    for (let i = 0; i < cr; i++) if (i !== y) cube[this.cubePos(i * cr + x, n)] = 0;
    for (let i = 0; i < cr; i++) if (i !== x) cube[this.cubePos(y * cr + i, n)] = 0;
    const bi = this.blocks.whichblock[xy];
    for (const bp of this.blocks.blocks[bi]) if (bp !== xy) cube[this.cubePos(bp, n)] = 0;
    this.grid[xy] = n;
    this.row[y * cr + n - 1] = 1;
    this.col[x * cr + n - 1] = 1;
    this.blk[bi * cr + n - 1] = 1;
    if (this.diag) {
      if (onDiag0(xy, cr)) {
        for (let i = 0; i < cr; i++) {
          const d = diag0(i, cr);
          if (d !== xy) cube[this.cubePos(d, n)] = 0;
        }
        this.diag[n - 1] = 1;
      }
      if (onDiag1(xy, cr)) {
        for (let i = 0; i < cr; i++) {
          const d = diag1(i, cr);
          if (d !== xy) cube[this.cubePos(d, n)] = 0;
        }
        this.diag[cr + n - 1] = 1;
      }
    }
  }

  /**
   * Positional/numeric elimination over `count` cube indices: if exactly one is still
   * possible, place it. Returns +1 progress, 0 nothing, -1 contradiction.
   */
  elim(indices: Int32Array, count: number): number {
    const { cr, cube } = this;
    let m = 0;
    let fpos = -1;
    for (let i = 0; i < count; i++) {
      if (cube[indices[i]]) {
        fpos = indices[i];
        m++;
      }
    }
    if (m === 1) {
      const n = 1 + (fpos % cr);
      const xy = Math.floor(fpos / cr);
      if (!this.grid[xy]) {
        this.place(xy % cr, Math.floor(xy / cr), n);
        return 1;
      }
      return 0;
    }
    return m === 0 ? -1 : 0;
  }

  /**
   * Intersection: both lists (sorted, length cr) are the cube positions of one digit in
   * two overlapping regions. If every possibility in the first lies in the overlap, the
   * digit is ruled out in the rest of the second.
   */
  intersect(a: Int32Array, b: Int32Array): number {
    const { cr, cube } = this;
    for (let i = 0, j = 0; i < cr; i++) {
      const p = a[i];
      while (j < cr && b[j] < p) j++;
      if (cube[p] && !(j < cr && b[j] === p)) return 0;
    }
    let ret = 0;
    for (let i = 0, j = 0; i < cr; i++) {
      const p = b[i];
      while (j < cr && a[j] < p) j++;
      if (cube[p] && (j >= cr || a[j] !== p)) {
        cube[p] = 0;
        ret = 1;
      }
    }
    return ret;
  }

  /**
   * Set elimination on a cr × cr matrix of cube positions (`indices[i*cr+j]`): rows are
   * the things being placed (squares of a region, or a digit's rows), columns their
   * possible values. Finds a set of columns that only `|set|` rows can use.
   */
  setElim(indices: Int32Array): number {
    const { cr, cube } = this;
    const rowIdx: number[] = [];
    const colKeep = new Uint8Array(cr).fill(1);
    const rowKeep = new Uint8Array(cr).fill(1);
    for (let i = 0; i < cr; i++) {
      let count = 0;
      let first = -1;
      for (let j = 0; j < cr; j++) {
        if (cube[indices[i * cr + j]]) {
          first = j;
          count++;
        }
      }
      if (count === 0) return -1;
      if (count === 1) {
        rowKeep[i] = 0;
        colKeep[first] = 0;
      }
    }
    const colIdx: number[] = [];
    for (let i = 0; i < cr; i++) {
      if (rowKeep[i]) rowIdx.push(i);
      if (colKeep[i]) colIdx.push(i);
    }
    const n = rowIdx.length;
    if (n !== colIdx.length || n < 3) return 0;
    const masks = new Int32Array(n);
    for (let i = 0; i < n; i++) {
      let m = 0;
      for (let j = 0; j < n; j++) if (cube[indices[rowIdx[i] * cr + colIdx[j]]]) m |= 1 << j;
      masks[i] = m;
    }
    const full = (1 << n) - 1;
    for (let set = 1; set < full; set++) {
      const count = popcount(set);
      if (count <= 1 || count >= n - 1) continue;
      let rows = 0;
      for (let i = 0; i < n; i++) if ((masks[i] & set) === 0) rows++;
      if (rows > n - count) return -1;
      if (rows < n - count) continue;
      let progress = 0;
      for (let i = 0; i < n; i++) {
        if ((masks[i] & set) === 0) continue;
        const kill = masks[i] & ~set;
        if (!kill) continue;
        for (let j = 0; j < n; j++) {
          if (kill & (1 << j)) {
            cube[indices[rowIdx[i] * cr + colIdx[j]]] = 0;
            progress = 1;
          }
        }
      }
      if (progress) return 1;
    }
    return 0;
  }

  /** Candidates of a square as a bitmask (bit n for digit n) and their count. */
  private candidates(xy: number): number {
    const { cr, cube } = this;
    let m = 0;
    for (let n = 1; n <= cr; n++) if (cube[this.cubePos(xy, n)]) m |= 1 << n;
    return m;
  }

  /** Squares sharing a row, column, block or (in X mode) diagonal with `xy`. */
  private neighbours(xy: number): number[] {
    const { cr } = this;
    const x = xy % cr;
    const y = Math.floor(xy / cr);
    const out: number[] = [];
    for (let i = 0; i < cr; i++) out.push(i * cr + x);
    for (let i = 0; i < cr; i++) out.push(y * cr + i);
    for (const s of this.blocks.blocks[this.blocks.whichblock[xy]]) out.push(s);
    if (this.diag) {
      if (onDiag0(xy, cr)) for (let i = 0; i < cr; i++) out.push(diag0(i, cr));
      if (onDiag1(xy, cr)) for (let i = 0; i < cr; i++) out.push(diag1(i, cr));
    }
    return out;
  }

  private adjacent(a: number, b: number): boolean {
    const { cr } = this;
    if (a % cr === b % cr || Math.floor(a / cr) === Math.floor(b / cr)) return true;
    if (this.blocks.whichblock[a] === this.blocks.whichblock[b]) return true;
    if (this.diag) {
      if (onDiag0(a, cr) && onDiag0(b, cr)) return true;
      if (onDiag1(a, cr) && onDiag1(b, cr)) return true;
    }
    return false;
  }

  /**
   * Forcing chains: a path of two-candidate squares, each adjacent pair sharing a digit,
   * such that ruling out digit N at the start forces N at the end. A third square
   * adjacent to both ends cannot then be N.
   */
  forcing(): number {
    const { cr, area, cube } = this;
    const number = new Int32Array(area);
    const queue = new Int32Array(area);
    for (let start = 0; start < area; start++) {
      const cand = this.candidates(start);
      if (popcount(cand) !== 2) continue;
      for (let n = 1; n <= cr; n++) {
        if (!(cand & (1 << n))) continue;
        const other = 31 - Math.clz32(cand & ~(1 << n));
        number.fill(cr + 1);
        let head = 0;
        let tail = 0;
        queue[tail++] = start;
        number[start] = other;
        while (head < tail) {
          const xy = queue[head++];
          const currn = number[xy];
          for (const nb of this.neighbours(xy)) {
            if (nb === xy || number[nb] <= cr) continue;
            if (!cube[this.cubePos(nb, currn)]) continue;
            const c2 = this.candidates(nb);
            if (popcount(c2) === 2) {
              queue[tail++] = nb;
              number[nb] = 31 - Math.clz32(c2 & ~(1 << currn));
            }
            if (currn === n && this.adjacent(nb, start)) {
              cube[this.cubePos(nb, n)] = 0;
              return 1;
            }
          }
        }
      }
    }
    return 0;
  }

  // ------------------------------------------------------------------- killer

  private removeFromCage(b: number, sq: number): void {
    this.kwhich![sq] = -1;
    this.kb![b] = this.kb![b].filter((s) => s !== sq);
  }

  /** Move `squares` (all in one cage) into a new cage with the given sum. */
  private splitCage(squares: number[], sum: number): void {
    const kb = this.kb!;
    const prev = this.kwhich![squares[0]];
    const nb = kb.length;
    const inNew = new Set(squares);
    kb.push(squares.slice());
    for (const s of squares) this.kwhich![s] = nb;
    kb[prev] = kb[prev].filter((s) => !inNew.has(s));
    this.kclues![nb] = sum;
    this.kclues![prev] -= sum;
  }

  /**
   * Strip filled squares and whole cages out of a region's square list; returns the
   * remaining squares and the total those removed account for.
   */
  private filterWholeCages(list: number[]): { squares: number[]; sum: number } {
    const { grid } = this;
    const kb = this.kb!;
    const kwhich = this.kwhich!;
    let sum = 0;
    let rem: number[] = [];
    for (const s of list) {
      if (grid[s]) sum += grid[s];
      else rem.push(s);
    }
    const inList = new Set(rem);
    for (let b = 0; b < kb.length; b++) {
      const cage = kb[b];
      if (cage.length === 0 || cage.length > rem.length) continue;
      if (!cage.every((s) => inList.has(s))) continue;
      rem = rem.filter((s) => kwhich[s] !== b);
      for (const s of cage) inList.delete(s);
      sum += this.kclues![b];
    }
    return { squares: rem, sum };
  }

  /** Rule out digits that would force a cage's sum too high or too low. */
  killerMinmax(squares: number[], clue: number): number {
    const { cr, cube } = this;
    if (clue === 0 || squares.length === 0) return 0;
    let ret = 0;
    const mins = squares.map((s) => {
      for (let m = 1; m <= cr; m++) if (cube[this.cubePos(s, m)]) return m;
      return 0;
    });
    const maxs = squares.map((s) => {
      for (let m = cr; m >= 1; m--) if (cube[this.cubePos(s, m)]) return m;
      return 0;
    });
    let minTotal = 0;
    let maxTotal = 0;
    for (let i = 0; i < squares.length; i++) {
      minTotal += mins[i];
      maxTotal += maxs[i];
    }
    for (let i = 0; i < squares.length; i++) {
      const s = squares[i];
      const minOthers = minTotal - mins[i];
      const maxOthers = maxTotal - maxs[i];
      for (let n = 1; n <= cr; n++) {
        if (!cube[this.cubePos(s, n)]) continue;
        if (maxOthers + n < clue || minOthers + n > clue) {
          cube[this.cubePos(s, n)] = 0;
          ret = 1;
        }
      }
    }
    return ret;
  }

  /**
   * Use the known ways of making a sum from distinct digits. Only valid when the squares
   * must hold distinct digits: a real cage, or a deduced one inside a single region.
   */
  killerSums(squares: number[], clue: number, isCage: boolean): number {
    const { cr, cube } = this;
    const k = squares.length;
    if (clue <= 0) return k ? -1 : 0;
    if (k < 2 || k > 4) return 0;
    if (!isCage) {
      let sameRow = true;
      let sameCol = true;
      let sameBlk = true;
      for (let i = 1; i < k; i++) {
        if (Math.floor(squares[i] / cr) !== Math.floor(squares[0] / cr)) sameRow = false;
        if (squares[i] % cr !== squares[0] % cr) sameCol = false;
        if (this.blocks.whichblock[squares[i]] !== this.blocks.whichblock[squares[0]])
          sameBlk = false;
      }
      if (!sameRow && !sameCol && !sameBlk) return 0;
    }
    const table = sumTable(cr)[k];
    if (clue >= table.length || table[clue].length === 0) return -1;
    const allowed = squares.map((s) => this.candidates(s));
    let possible = 0;
    for (const bits of table[clue]) {
      if (allowed.every((a) => (a & bits) !== 0)) possible |= bits;
    }
    if (possible === 0) return -1;
    let ret = 0;
    for (const s of squares) {
      for (let n = 1; n <= cr; n++) {
        if (cube[this.cubePos(s, n)] && !(possible & (1 << n))) {
          cube[this.cubePos(s, n)] = 0;
          ret = 1;
        }
      }
    }
    return ret;
  }

  // --------------------------------------------------------------------- main

  /** Run the solver; the grid is filled in place. Returns the difficulty reached. */
  run(): number {
    const { cr, area, cube, grid, idx, idx2, setIdx, maxdiff, maxkdiff } = this;
    const blocks = this.blocks.blocks;

    for (let xy = 0; xy < area; xy++) {
      const n = grid[xy];
      if (!n) continue;
      if (!cube[this.cubePos(xy, n)]) return DIFF_IMPOSSIBLE;
      this.place(xy % cr, Math.floor(xy / cr), n);
    }

    let diff = DIFF_BLOCK;
    const killer = this.kb !== null;

    outer: for (;;) {
      // Blockwise positional elimination.
      for (let b = 0; b < cr; b++) {
        for (let n = 1; n <= cr; n++) {
          if (this.blk[b * cr + n - 1]) continue;
          for (let i = 0; i < cr; i++) idx[i] = this.cubePos(blocks[b][i], n);
          const ret = this.elim(idx, cr);
          if (ret < 0) return DIFF_IMPOSSIBLE;
          if (ret > 0) continue outer;
        }
      }

      if (killer) {
        const kb = this.kb!;
        const kclues = this.kclues!;
        let changed = false;
        // Take filled squares out of their cages and reduce the cage sums accordingly.
        for (let b = 0; b < kb.length; b++) {
          for (let i = kb[b].length - 1; i >= 0; i--) {
            const sq = kb[b][i];
            const t = grid[sq];
            if (!t) continue;
            this.removeFromCage(b, sq);
            if (t > kclues[b]) return DIFF_IMPOSSIBLE;
            kclues[b] -= t;
            for (const s of kb[b]) cube[this.cubePos(s, t)] = 0;
          }
        }
        // Single-square cages are simply their sum.
        for (let b = 0; b < kb.length; b++) {
          if (kb[b].length !== 1) continue;
          const v = kclues[b];
          if (v < 1 || v > cr) return DIFF_IMPOSSIBLE;
          const sq = kb[b][0];
          if (!cube[this.cubePos(sq, v)]) return DIFF_IMPOSSIBLE;
          this.place(sq % cr, Math.floor(sq / cr), v);
          changed = true;
        }
        if (changed) {
          this.kdiff = Math.max(this.kdiff, KDIFF_SINGLE);
          continue outer;
        }

        if (maxkdiff >= KDIFF_INTERSECT) {
          // Every row, column and block sums to a known total; after removing the cages
          // that lie wholly inside it, the leftover squares form a cage of their own.
          this.extra = [];
          const total = (cr * (cr + 1)) / 2;
          for (const region of this.regions) {
            const { squares, sum: filtered } = this.filterWholeCages(region);
            const sum = total - filtered;
            if (squares.length === cr || squares.length === 0) continue;
            if (sum <= 0) return DIFF_IMPOSSIBLE;
            if (squares.length === 1) {
              if (sum > cr) return DIFF_IMPOSSIBLE;
              const sq = squares[0];
              if (!cube[this.cubePos(sq, sum)]) return DIFF_IMPOSSIBLE;
              this.place(sq % cr, Math.floor(sq / cr), sum);
              changed = true;
            }
            const b = this.kwhich![squares[0]];
            if (squares.every((s) => this.kwhich![s] === b)) this.splitCage(squares, sum);
            else this.extra.push({ squares, clue: sum });
          }
          if (changed) {
            this.kdiff = Math.max(this.kdiff, KDIFF_INTERSECT);
            continue outer;
          }
        }

        if (maxkdiff >= KDIFF_MINMAX) {
          for (let b = 0; b < kb.length; b++)
            if (this.killerMinmax(kb[b], kclues[b]) > 0) changed = true;
          for (const e of this.extra) if (this.killerMinmax(e.squares, e.clue) > 0) changed = true;
          if (changed) {
            this.kdiff = Math.max(this.kdiff, KDIFF_MINMAX);
            continue outer;
          }
        }

        if (maxkdiff >= KDIFF_SUMS) {
          for (let b = 0; b < kb.length; b++) {
            const ret = this.killerSums(kb[b], kclues[b], true);
            if (ret < 0) return DIFF_IMPOSSIBLE;
            if (ret > 0) changed = true;
          }
          for (const e of this.extra) {
            const ret = this.killerSums(e.squares, e.clue, false);
            if (ret < 0) return DIFF_IMPOSSIBLE;
            if (ret > 0) changed = true;
          }
          if (changed) {
            this.kdiff = Math.max(this.kdiff, KDIFF_SUMS);
            continue outer;
          }
        }
      }

      if (maxdiff <= DIFF_BLOCK) break;

      // Row-wise and column-wise positional elimination.
      for (let y = 0; y < cr; y++) {
        for (let n = 1; n <= cr; n++) {
          if (this.row[y * cr + n - 1]) continue;
          for (let x = 0; x < cr; x++) idx[x] = this.cubePos(y * cr + x, n);
          const ret = this.elim(idx, cr);
          if (ret < 0) return DIFF_IMPOSSIBLE;
          if (ret > 0) {
            diff = Math.max(diff, DIFF_SIMPLE);
            continue outer;
          }
        }
      }
      for (let x = 0; x < cr; x++) {
        for (let n = 1; n <= cr; n++) {
          if (this.col[x * cr + n - 1]) continue;
          for (let y = 0; y < cr; y++) idx[y] = this.cubePos(y * cr + x, n);
          const ret = this.elim(idx, cr);
          if (ret < 0) return DIFF_IMPOSSIBLE;
          if (ret > 0) {
            diff = Math.max(diff, DIFF_SIMPLE);
            continue outer;
          }
        }
      }
      if (this.diag) {
        for (let d = 0; d < 2; d++) {
          for (let n = 1; n <= cr; n++) {
            if (this.diag[d * cr + n - 1]) continue;
            for (let i = 0; i < cr; i++) idx[i] = this.cubePos(d ? diag1(i, cr) : diag0(i, cr), n);
            const ret = this.elim(idx, cr);
            if (ret < 0) return DIFF_IMPOSSIBLE;
            if (ret > 0) {
              diff = Math.max(diff, DIFF_SIMPLE);
              continue outer;
            }
          }
        }
      }
      // Numeric elimination.
      for (let xy = 0; xy < area; xy++) {
        if (grid[xy]) continue;
        for (let n = 1; n <= cr; n++) idx[n - 1] = this.cubePos(xy, n);
        const ret = this.elim(idx, cr);
        if (ret < 0) return DIFF_IMPOSSIBLE;
        if (ret > 0) {
          diff = Math.max(diff, DIFF_SIMPLE);
          continue outer;
        }
      }

      if (maxdiff <= DIFF_SIMPLE) break;

      // Intersections of rows, columns and diagonals with blocks.
      for (let b = 0; b < cr; b++) {
        for (let n = 1; n <= cr; n++) {
          if (this.blk[b * cr + n - 1]) continue;
          for (let i = 0; i < cr; i++) idx2[i] = this.cubePos(blocks[b][i], n);
          for (let y = 0; y < cr; y++) {
            if (this.row[y * cr + n - 1]) continue;
            for (let x = 0; x < cr; x++) idx[x] = this.cubePos(y * cr + x, n);
            if (this.intersect(idx, idx2) || this.intersect(idx2, idx)) {
              diff = Math.max(diff, DIFF_INTERSECT);
              continue outer;
            }
          }
          for (let x = 0; x < cr; x++) {
            if (this.col[x * cr + n - 1]) continue;
            for (let y = 0; y < cr; y++) idx[y] = this.cubePos(y * cr + x, n);
            if (this.intersect(idx, idx2) || this.intersect(idx2, idx)) {
              diff = Math.max(diff, DIFF_INTERSECT);
              continue outer;
            }
          }
          if (this.diag) {
            for (let d = 0; d < 2; d++) {
              if (this.diag[d * cr + n - 1]) continue;
              for (let i = 0; i < cr; i++)
                idx[i] = this.cubePos(d ? diag1(i, cr) : diag0(i, cr), n);
              if (this.intersect(idx, idx2) || this.intersect(idx2, idx)) {
                diff = Math.max(diff, DIFF_INTERSECT);
                continue outer;
              }
            }
          }
        }
      }

      if (maxdiff <= DIFF_INTERSECT) break;

      // Set elimination within blocks, rows, columns and diagonals.
      for (let b = 0; b < cr; b++) {
        for (let i = 0; i < cr; i++)
          for (let n = 1; n <= cr; n++) setIdx[i * cr + n - 1] = this.cubePos(blocks[b][i], n);
        const ret = this.setElim(setIdx);
        if (ret < 0) return DIFF_IMPOSSIBLE;
        if (ret > 0) {
          diff = Math.max(diff, DIFF_SET);
          continue outer;
        }
      }
      for (let y = 0; y < cr; y++) {
        for (let x = 0; x < cr; x++)
          for (let n = 1; n <= cr; n++) setIdx[x * cr + n - 1] = this.cubePos(y * cr + x, n);
        const ret = this.setElim(setIdx);
        if (ret < 0) return DIFF_IMPOSSIBLE;
        if (ret > 0) {
          diff = Math.max(diff, DIFF_SET);
          continue outer;
        }
      }
      for (let x = 0; x < cr; x++) {
        for (let y = 0; y < cr; y++)
          for (let n = 1; n <= cr; n++) setIdx[y * cr + n - 1] = this.cubePos(y * cr + x, n);
        const ret = this.setElim(setIdx);
        if (ret < 0) return DIFF_IMPOSSIBLE;
        if (ret > 0) {
          diff = Math.max(diff, DIFF_SET);
          continue outer;
        }
      }
      if (this.diag) {
        for (let d = 0; d < 2; d++) {
          for (let i = 0; i < cr; i++)
            for (let n = 1; n <= cr; n++)
              setIdx[i * cr + n - 1] = this.cubePos(d ? diag1(i, cr) : diag0(i, cr), n);
          const ret = this.setElim(setIdx);
          if (ret < 0) return DIFF_IMPOSSIBLE;
          if (ret > 0) {
            diff = Math.max(diff, DIFF_SET);
            continue outer;
          }
        }
      }

      if (maxdiff <= DIFF_SET) break;

      // Row-vs-column set elimination on a single digit.
      for (let n = 1; n <= cr; n++) {
        for (let y = 0; y < cr; y++)
          for (let x = 0; x < cr; x++) setIdx[y * cr + x] = this.cubePos(y * cr + x, n);
        const ret = this.setElim(setIdx);
        if (ret < 0) return DIFF_IMPOSSIBLE;
        if (ret > 0) {
          diff = Math.max(diff, DIFF_EXTREME);
          continue outer;
        }
      }
      if (this.forcing()) {
        diff = Math.max(diff, DIFF_EXTREME);
        continue outer;
      }
      break;
    }

    // Anything left? Either guess (Unreasonable) or give up.
    let best = -1;
    let bestCount = cr + 1;
    for (let xy = 0; xy < area; xy++) {
      if (grid[xy]) continue;
      const count = popcount(this.candidates(xy));
      if (count === 0) return DIFF_IMPOSSIBLE;
      if (count < bestCount) {
        bestCount = count;
        best = xy;
      }
    }
    if (best === -1) return diff;
    if (maxdiff < DIFF_RECURSIVE) return DIFF_IMPOSSIBLE;

    const cand = this.candidates(best);
    const start = grid.slice();
    diff = DIFF_IMPOSSIBLE;
    for (let n = 1; n <= cr; n++) {
      if (!(cand & (1 << n))) continue;
      // Out of guesses: the answer is unknown, and "not provably unique" is the safe one.
      if (this.guesses && this.guesses.left-- <= 0) return DIFF_AMBIGUOUS;
      const out = start.slice();
      out[best] = n;
      const sub = new Solver(
        cr,
        this.blocks,
        this.origCages,
        this.xtype,
        out,
        this.kgrid,
        maxdiff,
        maxkdiff,
        this.guesses,
      );
      const r = sub.run();
      if (diff === DIFF_IMPOSSIBLE && r !== DIFF_IMPOSSIBLE) grid.set(out);
      if (r === DIFF_AMBIGUOUS) diff = DIFF_AMBIGUOUS;
      else if (r !== DIFF_IMPOSSIBLE)
        diff = diff === DIFF_IMPOSSIBLE ? DIFF_RECURSIVE : DIFF_AMBIGUOUS;
      if (diff === DIFF_AMBIGUOUS) break;
    }
    return diff;
  }
}

function popcount(v: number): number {
  v = v - ((v >>> 1) & 0x55555555);
  v = (v & 0x33333333) + ((v >>> 2) & 0x33333333);
  return (((v + (v >>> 4)) & 0x0f0f0f0f) * 0x01010101) >>> 24;
}

/**
 * Solve `grid` in place using techniques up to `maxdiff` (and `maxkdiff` for killer
 * cages). The result says how hard the puzzle was, or that it has no or several
 * solutions. When the solver stops short without recursion the result is IMPOSSIBLE.
 */
export function solveGrid(
  cr: number,
  blocks: BlockStructure,
  kblocks: BlockStructure | null,
  xtype: boolean,
  grid: Uint8Array,
  kgrid: Uint8Array | null,
  maxdiff: number,
  maxkdiff: number,
  guesses: GuessBudget | null = null,
): SolveResult {
  const s = new Solver(cr, blocks, kblocks, xtype, grid, kgrid, maxdiff, maxkdiff, guesses);
  const diff = s.run();
  return { diff, kdiff: s.kdiff };
}

/**
 * Whether a full grid satisfies every constraint: each row, column, block and (in X
 * mode) diagonal holds every digit once, and each killer cage holds distinct digits
 * adding up to its clue.
 */
export function checkValid(
  cr: number,
  blocks: BlockStructure,
  kblocks: BlockStructure | null,
  kgrid: Uint8Array | null,
  xtype: boolean,
  grid: Uint8Array,
): boolean {
  const used = new Uint8Array(cr + 1);
  const complete = (squares: ArrayLike<number>): boolean => {
    used.fill(0);
    for (let i = 0; i < squares.length; i++) {
      const d = grid[squares[i]];
      if (d < 1 || d > cr || used[d]) return false;
      used[d] = 1;
    }
    return squares.length === cr;
  };
  const list: number[] = [];
  for (let y = 0; y < cr; y++) {
    list.length = 0;
    for (let x = 0; x < cr; x++) list.push(y * cr + x);
    if (!complete(list)) return false;
  }
  for (let x = 0; x < cr; x++) {
    list.length = 0;
    for (let y = 0; y < cr; y++) list.push(y * cr + x);
    if (!complete(list)) return false;
  }
  for (const b of blocks.blocks) if (!complete(b)) return false;
  if (xtype) {
    list.length = 0;
    for (let i = 0; i < cr; i++) list.push(diag0(i, cr));
    if (!complete(list)) return false;
    list.length = 0;
    for (let i = 0; i < cr; i++) list.push(diag1(i, cr));
    if (!complete(list)) return false;
  }
  if (kblocks && kgrid) {
    const clues = cageClues(kblocks, kgrid);
    for (let b = 0; b < kblocks.nrBlocks; b++) {
      used.fill(0);
      let sum = 0;
      for (const s of kblocks.blocks[b]) {
        const d = grid[s];
        if (d < 1 || d > cr || used[d]) return false;
        used[d] = 1;
        sum += d;
      }
      if (sum !== clues[b]) return false;
    }
  }
  return true;
}
