/**
 * Keen solver: the latin-square core plus deductions from the arithmetic cages.
 *
 * Difficulty levels (each includes everything below it):
 *  - Easy: for every cage, enumerate the digit combinations that fit the clue and are
 *    still possible; any digit that appears in none of them is ruled out of the whole
 *    cage. Plus positional elimination in rows and columns.
 *  - Normal: the same enumeration, but remembering which square each digit was in, so
 *    digits are ruled out per square.
 *  - Hard: digits that every combination puts somewhere in a given row (or column) of the
 *    cage cannot appear elsewhere in that row (or column). Plus set elimination.
 *  - Extreme: positional set elimination on a single digit and forcing chains.
 *  - Unreasonable: guessing and backtracking.
 */
import {
  LATIN_AMBIGUOUS,
  LATIN_IMPOSSIBLE,
  LATIN_UNFINISHED,
  LatinSolver,
  latinSolve,
} from './latin';
import type { LatinLevels } from './latin';

export const DIFF_EASY = 0;
export const DIFF_NORMAL = 1;
export const DIFF_HARD = 2;
export const DIFF_EXTREME = 3;
export const DIFF_UNREASONABLE = 4;
export const DIFF_COUNT = 5;
export const DIFF_IMPOSSIBLE = LATIN_IMPOSSIBLE;
export const DIFF_AMBIGUOUS = LATIN_AMBIGUOUS;
export const DIFF_UNFINISHED = LATIN_UNFINISHED;

export const DIFF_NAMES = ['Easy', 'Normal', 'Hard', 'Extreme', 'Unreasonable'];
export const DIFF_CHARS = 'enhxu';

export const OP_ADD = 0;
export const OP_MUL = 1;
export const OP_SUB = 2;
export const OP_DIV = 3;
/** Clue letters in the game description, indexed by operator. */
export const OP_CHARS = 'amsd';
/** Symbols shown after the clue total, indexed by operator. */
export const OP_SYMBOLS = ['+', '×', '−', '÷'];

export interface Cage {
  /** Square indices (row-major), in reading order; the clue is drawn in the first. */
  cells: number[];
  op: number;
  value: number;
}

/** The fixed part of a puzzle: grid size and cages. */
export interface Layout {
  w: number;
  /** Cages in order of their first square. */
  cages: Cage[];
  /** whichCage[xy]: index into `cages`. */
  whichCage: Int32Array;
}

/** Combine digits with an operator the way a clue does. Empty squares count as 0. */
export function cageResult(op: number, digits: ArrayLike<number>): number {
  let v = digits[0];
  for (let i = 1; i < digits.length; i++) {
    const d = digits[i];
    if (op === OP_ADD) v += d;
    else if (op === OP_MUL) v *= d;
    else if (op === OP_SUB) v = Math.abs(v - d);
    else {
      const lo = Math.min(v, d);
      const hi = Math.max(v, d);
      v = lo === 0 || hi % lo !== 0 ? 0 : hi / lo;
    }
  }
  return v;
}

/** Per-solve scratch state for the cage deductions. */
class ClueSolver {
  readonly w: number;
  readonly cages: Cage[];
  readonly whichCage: Int32Array;
  readonly maxdiff: number;
  private readonly digits: Int32Array;
  private readonly cellMask: Int32Array;
  private readonly rowMask: Int32Array;
  private readonly colMask: Int32Array;
  private readonly tmpRow: Int32Array;
  private readonly tmpCol: Int32Array;
  private cage!: Cage;
  private diff = DIFF_EASY;

  constructor(layout: Layout, maxdiff: number) {
    this.w = layout.w;
    this.cages = layout.cages;
    this.whichCage = layout.whichCage;
    this.maxdiff = maxdiff;
    let maxCells = 2;
    for (const c of layout.cages) maxCells = Math.max(maxCells, c.cells.length);
    this.digits = new Int32Array(maxCells);
    this.cellMask = new Int32Array(maxCells);
    this.rowMask = new Int32Array(this.w);
    this.colMask = new Int32Array(this.w);
    this.tmpRow = new Int32Array(this.w);
    this.tmpCol = new Int32Array(this.w);
  }

  /** A digit assignment for the current cage fits the clue; record what it tells us. */
  private candidate(): void {
    const { w, digits, cellMask } = this;
    const cells = this.cage.cells;
    const n = cells.length;
    if (this.diff === DIFF_EASY) {
      let mask = 0;
      for (let j = 0; j < n; j++) mask |= 1 << digits[j];
      for (let j = 0; j < n; j++) cellMask[j] |= mask;
    } else if (this.diff === DIFF_NORMAL) {
      for (let j = 0; j < n; j++) cellMask[j] |= 1 << digits[j];
    } else {
      const { rowMask, colMask, tmpRow, tmpCol } = this;
      tmpRow.fill(0);
      tmpCol.fill(0);
      for (let j = 0; j < n; j++) {
        tmpRow[Math.floor(cells[j] / w)] |= 1 << digits[j];
        tmpCol[cells[j] % w] |= 1 << digits[j];
      }
      for (let i = 0; i < w; i++) {
        rowMask[i] &= tmpRow[i];
        colMask[i] &= tmpCol[i];
      }
    }
  }

  /** Enumerate ADD/MUL assignments for cells i.. with `total` still to account for. */
  private enumerate(s: LatinSolver, i: number, total: number): void {
    const { w, digits } = this;
    const { op, cells } = this.cage;
    const n = cells.length;
    if (i === n) {
      if (total === (op === OP_ADD ? 0 : 1)) this.candidate();
      return;
    }
    const cell = cells[i];
    const x = cell % w;
    const y = Math.floor(cell / w);
    for (let j = 1; j <= w; j++) {
      if (op === OP_ADD ? total < j : total % j !== 0) continue;
      if (!s.can(cell, j)) continue;
      let clash = false;
      for (let k = 0; k < i && !clash; k++) {
        if (digits[k] === j && (cells[k] % w === x || Math.floor(cells[k] / w) === y)) clash = true;
      }
      if (clash) continue;
      digits[i] = j;
      this.enumerate(s, i + 1, op === OP_ADD ? total - j : total / j);
    }
  }

  /** One pass of cage deductions at level `diff`. */
  deduce(s: LatinSolver, diff: number): number {
    const { w, cages, cellMask, rowMask, colMask, digits } = this;
    this.diff = diff;
    let ret = 0;
    const full = ((1 << (w + 1)) - 2) | 0;
    for (let b = 0; b < cages.length; b++) {
      const cage = cages[b];
      const { cells, op, value } = cage;
      const n = cells.length;
      this.cage = cage;
      if (diff === DIFF_HARD) {
        rowMask.fill(0);
        colMask.fill(0);
        for (const c of cells) {
          rowMask[Math.floor(c / w)] = full;
          colMask[c % w] = full;
        }
      } else {
        cellMask.fill(0, 0, n);
      }

      if (op === OP_SUB || op === OP_DIV) {
        // Always a domino, so the two digits differ; try every pair both ways round.
        if (n === 2) {
          for (let i = 1; i <= w; i++) {
            const j = op === OP_SUB ? i + value : i * value;
            if (j > w) break;
            if (j < 1 || j === i) continue;
            if (s.can(cells[0], i) && s.can(cells[1], j)) {
              digits[0] = i;
              digits[1] = j;
              this.candidate();
            }
            if (s.can(cells[0], j) && s.can(cells[1], i)) {
              digits[0] = j;
              digits[1] = i;
              this.candidate();
            }
          }
        }
      } else {
        this.enumerate(s, 0, value);
      }

      if (diff < DIFF_HARD) {
        for (let i = 0; i < n; i++) {
          for (let j = 1; j <= w; j++) {
            if (s.can(cells[i], j) && !(cellMask[i] & (1 << j))) {
              s.cube[cells[i] * w + j - 1] = 0;
              ret = 1;
            }
          }
        }
      } else {
        for (let y = 0; y < w; y++) {
          const m = rowMask[y];
          if (!m) continue;
          for (let x = 0; x < w; x++) {
            const xy = y * w + x;
            if (this.whichCage[xy] === b) continue;
            for (let j = 1; j <= w; j++) {
              if (m & (1 << j) && s.can(xy, j)) {
                s.cube[xy * w + j - 1] = 0;
                ret = 1;
              }
            }
          }
        }
        for (let x = 0; x < w; x++) {
          const m = colMask[x];
          if (!m) continue;
          for (let y = 0; y < w; y++) {
            const xy = y * w + x;
            if (this.whichCage[xy] === b) continue;
            for (let j = 1; j <= w; j++) {
              if (m & (1 << j) && s.can(xy, j)) {
                s.cube[xy * w + j - 1] = 0;
                ret = 1;
              }
            }
          }
        }
        // Cross-cage deductions are the expensive kind: as soon as one cage yields
        // something, go back to the easier techniques.
        if (ret) return ret;
      }
    }
    return ret;
  }
}

const LEVELS: LatinLevels<ClueSolver> = {
  simple: DIFF_EASY,
  set0: DIFF_HARD,
  set1: DIFF_EXTREME,
  forcing: DIFF_EXTREME,
  recursive: DIFF_UNREASONABLE,
  userSolvers: [
    // Easy deductions are a subset of Normal ones, so skip them when solving at a higher
    // level. (This means an Easy puzzle solved at Normal level reports Normal; callers
    // that grade puzzles re-solve one level down to check.)
    (s, ctx) => (ctx.maxdiff > DIFF_EASY ? 0 : ctx.deduce(s, DIFF_EASY)),
    (s, ctx) => ctx.deduce(s, DIFF_NORMAL),
    (s, ctx) => ctx.deduce(s, DIFF_HARD),
    null,
    null,
  ],
};

/**
 * Solve the puzzle into `grid` (in place; may contain digits already known) using
 * techniques up to `maxdiff`. Returns the level needed, or DIFF_IMPOSSIBLE,
 * DIFF_AMBIGUOUS or DIFF_UNFINISHED.
 */
export function solveKeen(layout: Layout, grid: Uint8Array, maxdiff: number): number {
  const ctx = new ClueSolver(layout, maxdiff);
  return latinSolve(grid, layout.w, maxdiff, LEVELS, ctx);
}

/**
 * Rate a puzzle: the lowest level at which it solves uniquely, or DIFF_AMBIGUOUS /
 * DIFF_IMPOSSIBLE. The solution is left in `grid` when there is one.
 */
export function gradeKeen(layout: Layout, grid: Uint8Array): number {
  for (let diff = DIFF_EASY; diff < DIFF_COUNT; diff++) {
    grid.fill(0);
    const ret = solveKeen(layout, grid, diff);
    if (ret === DIFF_IMPOSSIBLE || ret === DIFF_AMBIGUOUS) return ret;
    if (ret <= diff) return ret;
  }
  return DIFF_AMBIGUOUS;
}

export interface KeenErrors {
  /** 1 for a digit that also appears elsewhere in its row or column. */
  cells: Uint8Array;
  /** 1 for a cage that is completely filled but does not make its clue. */
  cages: Uint8Array;
  /** Whether the grid is a finished, correct solution. */
  solved: boolean;
}

/** Check a (possibly partial) grid against the latin and cage rules. */
export function checkErrors(layout: Layout, grid: Uint8Array): KeenErrors {
  const { w, cages } = layout;
  const cells = new Uint8Array(w * w);
  const cageErr = new Uint8Array(cages.length);
  let solved = true;
  for (let b = 0; b < cages.length; b++) {
    const c = cages[b];
    let full = true;
    for (const xy of c.cells) if (!grid[xy]) full = false;
    if (!full) {
      solved = false;
      continue;
    }
    if (
      cageResult(
        c.op,
        c.cells.map((xy) => grid[xy]),
      ) !== c.value
    ) {
      cageErr[b] = 1;
      solved = false;
    }
  }
  const count = new Uint8Array(w + 1);
  for (let y = 0; y < w; y++) {
    count.fill(0);
    for (let x = 0; x < w; x++) count[grid[y * w + x]]++;
    for (let x = 0; x < w; x++) {
      const d = grid[y * w + x];
      if (!d) solved = false;
      else if (count[d] > 1) {
        cells[y * w + x] = 1;
        solved = false;
      }
    }
  }
  for (let x = 0; x < w; x++) {
    count.fill(0);
    for (let y = 0; y < w; y++) count[grid[y * w + x]]++;
    for (let y = 0; y < w; y++) {
      const d = grid[y * w + x];
      if (d && count[d] > 1) {
        cells[y * w + x] = 1;
        solved = false;
      }
    }
  }
  return { cells, cages: cageErr, solved };
}
