import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { BLACK, WHITE } from './board';
import type { RangeState, RangeUI } from './index';

const border = (t: number) => Math.round(t * 0.3);

interface Cell {
  x: number;
  y: number;
}

/** Squares of the fixed 4×3 board the walkthrough talks about. */
const SIX: Cell = { x: 1, y: 0 };
const TWO: Cell = { x: 3, y: 1 };
const THREE: Cell = { x: 2, y: 2 };
/** The two squares that have to end up black, and the one dotted on the way. */
const FIRST_BLACK: Cell = { x: 2, y: 1 };
const LAST_BLACK: Cell = { x: 3, y: 2 };
const DOT: Cell = { x: 3, y: 0 };

const at = (state: RangeState, c: Cell): number => c.y * state.w + c.x;
const rect = (c: Cell, t: number): TutorialRect => cellRect(c.x, c.y, t, border(t));
const centre = (c: Cell, t: number) => cellCentre(c.x, c.y, t, border(t));
const value = (state: RangeState, c: Cell) => state.grid[at(state, c)];

export const tutorial: Tutorial<RangeState, RangeUI> = {
  steps: [
    {
      gameId: '4x3:a6b4b2b3a',
      text: 'Paint squares black so that every number counts exactly the white squares its own square sees: itself, plus every square in line up, down, left and right until a black square or the edge stops it.',
      highlight: ({ state, tileSize }) =>
        cellRect(0, 0, tileSize, border(tileSize), state.w, state.h),
    },
    {
      text: 'The **6** can see six squares right now — its whole row plus the two below it. So nothing in that row or column may go black.',
      highlight: ({ state, tileSize }) => [
        cellRect(0, SIX.y, tileSize, border(tileSize), state.w, 1),
        cellRect(SIX.x, 0, tileSize, border(tileSize), 1, state.h),
      ],
    },
    {
      text: 'The **2** may only see itself and one more square, and the square above it has to stay white for the 6. So **click** the square on its left to paint it black.',
      highlight: ({ tileSize }) => [rect(TWO, tileSize), rect(FIRST_BLACK, tileSize)],
      pointer: ({ tileSize }) => centre(FIRST_BLACK, tileSize),
      waitFor: ({ state }) => value(state, FIRST_BLACK) === BLACK,
    },
    {
      text: 'That leaves the top-right square as the one white square the 2 still sees. **Right-click** it to pencil in a dot, which is how you note a square you know stays white.',
      highlight: ({ tileSize }) => [rect(TWO, tileSize), rect(DOT, tileSize)],
      pointer: ({ tileSize }) => ({ ...centre(DOT, tileSize), button: 'right' as const }),
      waitFor: ({ state }) => value(state, DOT) === WHITE,
    },
    {
      text: 'The **3** already sees itself and the two squares to its left, so the square on its right must be black. **Click** it.',
      highlight: ({ tileSize }) => [rect(THREE, tileSize), rect(LAST_BLACK, tileSize)],
      pointer: ({ tileSize }) => centre(LAST_BLACK, tileSize),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Finished with two black squares — the dots are only notes. **H** fills in one square that follows from the rest, and **Solve** dots the whole grid in.',
      textTouch:
        'Finished with two black squares — the dots are only notes. **Solve** dots the whole grid in when you would rather see the answer.',
      target: '[data-cmd="solve"]',
    },
  ],
};
