import { tx } from '../../i18n';
/**
 * Light Up board model shared by the game, the solver and the generator.
 *
 * A `Layout` is the fixed part of a puzzle: which squares are black, which of those
 * carry a clue, and (precomputed) which squares a light on any given white square would
 * illuminate. Everything the player changes — lights and "impossible" marks — lives in
 * plain typed arrays indexed by square (`y * w + x`).
 */

/** Value in `clue` for a square without a number (every white square, some black ones). */
export const NO_CLUE = -1;

export class Layout {
  readonly w: number;
  readonly h: number;
  readonly n: number;
  readonly black: Uint8Array;
  /** Number on each black square or `NO_CLUE`. Mutable: the generator strips clues. */
  clue: Int8Array;
  /** For a white square, every square a light there would light (itself excluded). */
  readonly rays: number[][];
  /** Orthogonal neighbours of every square. */
  readonly adj: number[][];

  constructor(w: number, h: number, black: Uint8Array, clue: Int8Array) {
    this.w = w;
    this.h = h;
    this.n = w * h;
    this.black = black;
    this.clue = clue;
    this.rays = new Array(this.n);
    this.adj = new Array(this.n);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const adj: number[] = [];
        if (x > 0) adj.push(i - 1);
        if (x < w - 1) adj.push(i + 1);
        if (y > 0) adj.push(i - w);
        if (y < h - 1) adj.push(i + w);
        this.adj[i] = adj;
        const ray: number[] = [];
        if (!black[i]) {
          for (let nx = x - 1; nx >= 0 && !black[y * w + nx]; nx--) ray.push(y * w + nx);
          for (let nx = x + 1; nx < w && !black[y * w + nx]; nx++) ray.push(y * w + nx);
          for (let ny = y - 1; ny >= 0 && !black[ny * w + x]; ny--) ray.push(ny * w + x);
          for (let ny = y + 1; ny < h && !black[ny * w + x]; ny++) ray.push(ny * w + x);
        }
        this.rays[i] = ray;
      }
    }
  }
}

/** How many lights shine on each square (a light counts itself). */
export function computeLit(L: Layout, light: Uint8Array): Uint8Array {
  const lit = new Uint8Array(L.n);
  for (let i = 0; i < L.n; i++) {
    if (!light[i]) continue;
    lit[i]++;
    for (const j of L.rays[i]) lit[j]++;
  }
  return lit;
}

/** Lights orthogonally adjacent to square `i`. */
export function lightsAround(L: Layout, light: Uint8Array, i: number): number {
  let n = 0;
  for (const j of L.adj[i]) if (light[j]) n++;
  return n;
}

/** Every white square is lit. */
export function allLit(L: Layout, lit: Uint8Array): boolean {
  for (let i = 0; i < L.n; i++) if (!L.black[i] && lit[i] === 0) return false;
  return true;
}

/** Some light is lit by another light. */
export function anyOverlap(L: Layout, light: Uint8Array, lit: Uint8Array): boolean {
  for (let i = 0; i < L.n; i++) if (light[i] && lit[i] > 1) return true;
  return false;
}

/** Every clue has exactly its number of adjacent lights. */
export function cluesSatisfied(L: Layout, light: Uint8Array): boolean {
  for (let i = 0; i < L.n; i++)
    if (L.clue[i] !== NO_CLUE && lightsAround(L, light, i) !== L.clue[i]) return false;
  return true;
}

/** The three winning conditions together. */
export function isCorrect(L: Layout, light: Uint8Array, lit: Uint8Array): boolean {
  return allLit(L, lit) && !anyOverlap(L, light, lit) && cluesSatisfied(L, light);
}

/**
 * Whether clue `i` is definitely wrong as things stand: it already has too many lights,
 * or too few even if every neighbour that could still take a light got one.
 */
export function clueWrong(
  L: Layout,
  light: Uint8Array,
  imposs: Uint8Array,
  lit: Uint8Array,
  i: number,
): boolean {
  let n = 0;
  let empty = 0;
  for (const j of L.adj[i]) {
    if (light[j]) n++;
    else if (!L.black[j] && !imposs[j] && lit[j] === 0) empty++;
  }
  return n > L.clue[i] || n + empty < L.clue[i];
}

// ------------------------------------------------------------- description format

/**
 * Parse a description: a lower-case letter is a run of 1–26 empty squares, `B` an
 * unnumbered black square and a digit 0–4 a numbered one. Returns an error message when
 * the text does not describe exactly `w × h` squares.
 */
export function parseDesc(
  desc: string,
  w: number,
  h: number,
): { black: Uint8Array; clue: Int8Array } | string {
  const n = w * h;
  const black = new Uint8Array(n);
  const clue = new Int8Array(n).fill(NO_CLUE);
  let i = 0;
  for (const c of desc) {
    if (i >= n) return tx`Description is longer than expected`;
    if (c >= 'a' && c <= 'z') {
      i += c.charCodeAt(0) - 96;
    } else if (c === 'B') {
      black[i++] = 1;
    } else if (c >= '0' && c <= '4') {
      black[i] = 1;
      clue[i++] = c.charCodeAt(0) - 48;
    } else {
      return tx`Description contains an unexpected character`;
    }
  }
  if (i > n) return tx`Description is longer than expected`;
  if (i < n) return tx`Description is shorter than expected`;
  return { black, clue };
}

export function encodeDesc(L: Layout): string {
  let out = '';
  let run = 0;
  const flush = () => {
    if (run) out += String.fromCharCode(96 + run);
    run = 0;
  };
  for (let i = 0; i < L.n; i++) {
    if (L.black[i]) {
      flush();
      out += L.clue[i] === NO_CLUE ? 'B' : String(L.clue[i]);
    } else {
      if (run === 26) flush();
      run++;
    }
  }
  flush();
  return out;
}

/** Solver hint stored with a generated puzzle: the indices of the solution's lights. */
export function encodeLights(light: Uint8Array): string {
  const idx: number[] = [];
  for (let i = 0; i < light.length; i++) if (light[i]) idx.push(i);
  return idx.join(',');
}

export function decodeLights(aux: string, n: number): Uint8Array | null {
  const light = new Uint8Array(n);
  if (aux === '') return light;
  for (const part of aux.split(',')) {
    if (!/^\d+$/.test(part)) return null;
    const i = parseInt(part, 10);
    if (i >= n) return null;
    light[i] = 1;
  }
  return light;
}
