import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { DRAW_TIME, changedAt, drawGrow, flashOn, growSegment } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import { BACK, EMPTY, FORWARD, NO_CLUE, checkGrid, decodeSolution, parseDesc } from './board';
import { generate } from './generator';
import type { SlantParams } from './generator';
import {
  DIFFICULTY_CHARS,
  DIFFICULTY_NAMES,
  DIFF_EASY,
  DIFF_HARD,
  SOLVE_IMPOSSIBLE,
  SOLVE_SOLVED,
  solveFresh,
} from './solver';
import help from './help.md?raw';
import { tutorial } from './tutorial';
import { achievements } from './achievements';

export type { SlantParams };

export interface SlantState {
  w: number;
  h: number;
  /** Clue on each of the (w+1)×(h+1) grid points, or NO_CLUE. Shared between states. */
  clues: Int8Array;
  /** FORWARD (`/`), BACK (`\`) or EMPTY for each square. */
  soln: Int8Array;
  /** 1 for squares whose diagonal lies on a closed loop. */
  loopErr: Uint8Array;
  /** 1 for clue points that cannot be satisfied any more. */
  clueErr: Uint8Array;
  /** Set once the grid has been correctly completed; never cleared (as in the original). */
  completed: boolean;
  usedSolve: boolean;
}

export interface SlantUI {
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

const FLASH_FRAME = 0.1;
const FLASH = 3 * FLASH_FRAME;
/** Generation re-solves the grid for every clue it tries to remove: 25×25 Hard takes ~1 s. */
const MAX_SIDE = 25;
const DEFAULTS: SlantParams = { w: 8, h: 8, difficulty: DIFF_EASY };

/** Clue circles sit on the grid points, so the border is wider than usual. */
function boardBorder(t: number): number {
  return Math.round(t * 0.45);
}

function makeState(
  w: number,
  h: number,
  clues: Int8Array,
  soln: Int8Array,
  prev?: SlantState,
): SlantState {
  const check = checkGrid(w, h, clues, soln);
  return {
    w,
    h,
    clues,
    soln,
    loopErr: check.loopErr,
    clueErr: check.clueErr,
    completed: check.complete || (prev?.completed ?? false),
    usedSolve: prev?.usedSolve ?? false,
  };
}

function moveChar(v: number): string {
  return v === BACK ? '\\' : v === FORWARD ? '/' : 'C';
}

const game = defineGame<SlantParams, SlantState, SlantUI>({
  id: 'slant',
  name: 'Slant',
  description: 'Draw a diagonal in every square, matching the numbers and forming no loops.',
  alsoKnownAs: 'Gokigen Naname',
  menuTier: 3,
  help,
  tutorial,
  achievements,
  presets: (
    [
      [5, 5, DIFF_EASY],
      [5, 5, DIFF_HARD],
      [8, 8, DIFF_EASY],
      [8, 8, DIFF_HARD],
      [12, 10, DIFF_EASY],
      [12, 10, DIFF_HARD],
    ] as [number, number, number][]
  ).map(([w, h, difficulty]) => ({
    name: `${w}×${h} ${DIFFICULTY_NAMES[difficulty]}`,
    params: { w, h, difficulty },
  })),
  defaultParams: () => ({ ...DEFAULTS }),
  encodeParams: (p, full) =>
    `${p.w}x${p.h}${full ? `d${DIFFICULTY_CHARS[p.difficulty] ?? 'e'}` : ''}`,
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:d(.))?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    const h = parseInt(m[2] ?? m[1], 10);
    const d = m[3] ? DIFFICULTY_CHARS.indexOf(m[3]) : -1;
    return { w, h, difficulty: d >= 0 ? d : DIFF_EASY };
  },
  validateParams(p, full) {
    if (![p.w, p.h, p.difficulty].every(Number.isInteger))
      return tx`All parameters must be whole numbers`;
    if (p.w < 2 || p.h < 2) return tx`Width and height must both be at least two`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && (p.difficulty < 0 || p.difficulty >= DIFFICULTY_NAMES.length))
      return tx`Unknown difficulty level`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      { type: 'choices', name: 'Difficulty', choices: DIFFICULTY_NAMES, selected: p.difficulty },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "4abc" as a size.
    const int = (i: number) => {
      const v = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(v) ? parseInt(v, 10) : NaN;
    };
    return {
      w: int(0),
      h: int(1),
      difficulty: (items[2] as { selected: number }).selected,
    };
  },

  newDesc(p, rng: Random) {
    return generate(p, rng);
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const clues = parseDesc(desc, p.w, p.h) as Int8Array;
    const state = makeState(p.w, p.h, clues, new Int8Array(p.w * p.h));
    return { ...state, completed: false };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const { w, h } = curr;
    let soln = aux !== undefined ? decodeSolution(aux, w * h) : null;
    if (soln && !checkGrid(w, h, curr.clues, soln).complete) soln = null;
    if (!soln) {
      const r = solveFresh(w, h, curr.clues, DIFF_HARD);
      if (r.result === SOLVE_IMPOSSIBLE) throw new Error(tx`This puzzle is not self-consistent`);
      if (r.result !== SOLVE_SOLVED)
        throw new Error(tx`Unable to find a unique solution for this puzzle`);
      soln = r.soln;
    }
    let move = 'S';
    for (let i = 0; i < w * h; i++) {
      if (curr.soln[i] !== soln[i]) move += `;${moveChar(soln[i])}${i % w},${Math.floor(i / w)}`;
    }
    return move;
  },

  textFormat(s) {
    const { w, h } = s;
    const W = w + 1;
    const rows: string[] = [];
    for (let y = 0; y <= h; y++) {
      let row = '';
      for (let x = 0; x <= w; x++) {
        const c = s.clues[y * W + x];
        row += c === NO_CLUE ? '+' : String(c);
        if (x < w) row += '-';
      }
      rows.push(row);
      if (y < h) {
        let mid = '';
        for (let x = 0; x <= w; x++) {
          mid += '|';
          if (x < w) {
            const v = s.soln[y * w + x];
            mid += v === EMPTY ? ' ' : moveChar(v);
          }
        }
        rows.push(mid);
      }
    }
    return rows.join('\n');
  },

  newUI: () => ({ cx: 0, cy: 0, cursorVisible: false }),
  changedState(ui, _old, next) {
    if (next.completed) ui.cursorVisible = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h } = state;
    let x: number;
    let y: number;
    let clockwise: boolean;
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      const t = ds.tileSize;
      const bd = boardBorder(t);
      x = Math.floor((mx - bd) / t);
      y = Math.floor((my - bd) / t);
      const hadCursor = ui.cursorVisible;
      ui.cursorVisible = false;
      if (x < 0 || y < 0 || x >= w || y >= h) return hadCursor ? '' : null;
      clockwise = b === LEFT_BUTTON;
    } else if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      x = ui.cx;
      y = ui.cy;
      clockwise = b !== CURSOR_SELECT2;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      return '';
    } else {
      return null;
    }
    // Left/Enter cycles blank → \ → / → blank; right/Space goes the other way round.
    const cur = state.soln[y * w + x];
    let v: number;
    if (clockwise) v = cur === EMPTY ? BACK : cur === BACK ? FORWARD : EMPTY;
    else v = cur === EMPTY ? FORWARD : cur === FORWARD ? BACK : EMPTY;
    return `${moveChar(v)}${x},${y}`;
  },

  executeMove(state, move) {
    if (!move) return null;
    const { w, h } = state;
    const soln = state.soln.slice();
    let usedSolve = state.usedSolve;
    for (const part of move.split(';')) {
      if (part === 'S') {
        usedSolve = true;
        continue;
      }
      const m = /^([\\/C])(\d+),(\d+)$/.exec(part);
      if (!m) return null;
      const x = parseInt(m[2], 10);
      const y = parseInt(m[3], 10);
      if (x >= w || y >= h) return null;
      soln[y * w + x] = m[1] === '\\' ? BACK : m[1] === '/' ? FORWARD : EMPTY;
    }
    return { ...makeState(w, h, state.clues, soln, state), usedSolve };
  },

  preferredTileSize: 40,
  computeSize(p, t) {
    const b = boardBorder(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds: DrawState, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, clues, soln, loopErr, clueErr } = state;
    const W = w + 1;
    const t = ds.tileSize;
    const b = boardBorder(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const px = (x: number) => b + x * t;

    dr.rect(b, b, w * t, h * t, flash ? 'shade' : 'paper');
    for (let x = 1; x < w; x++) dr.line(px(x), b, px(x), b + h * t, 'faint', 1.2);
    for (let y = 1; y < h; y++) dr.line(b, px(y), b + w * t, px(y), 'faint', 1.2);
    dr.rectOutline(b, b, w * t, h * t, 'pencil', { width: 1.6 });

    if (ui.cursorVisible) {
      const inset = t * 0.12;
      dr.cursor(px(ui.cx) + inset, px(ui.cy) + inset, t - 2 * inset, t - 2 * inset);
    }

    // Diagonals run exactly from corner to corner. A diagonal the player has just put
    // down is drawn growing out from the middle of the square, where their cursor was —
    // a pencil stroke rather than a line that was suddenly always there. An erase runs
    // the same stroke backwards, and so does an undo.
    const lw = Math.max(2.4, t * 0.085);
    const drawing = oldState ? changedAt(oldState.soln, soln) : null;
    const growing = new Set(drawing ?? []);
    const grow = drawGrow(animTime);
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        // Mid-stroke the square may be empty in the state being drawn and filled in the
        // one being left; either way it is the filled end of the move that is animated.
        const v = soln[i] === EMPTY && growing.has(i) ? oldState!.soln[i] : soln[i];
        if (v === EMPTY) continue;
        const colour = loopErr[i] ? 'error' : 'ink';
        // Landing on an empty square means the line is being rubbed out, so it shrinks
        // back into the paper instead of coming out of it.
        const g = growing.has(i) ? (soln[i] === EMPTY ? 1 - grow : grow) : 1;
        if (g <= 0) continue;
        const e =
          v === BACK
            ? growSegment(px(x), px(y), px(x + 1), px(y + 1), g)
            : growSegment(px(x + 1), px(y), px(x), px(y + 1), g);
        dr.line(e.x1, e.y1, e.x2, e.y2, colour, lw);
      }
    }

    // Clues: a small circle on the grid point with the digit inside.
    const r = t * 0.27;
    for (let y = 0; y <= h; y++) {
      for (let x = 0; x <= w; x++) {
        const c = clues[y * W + x];
        if (c === NO_CLUE) continue;
        const colour = clueErr[y * W + x] ? 'error' : 'ink';
        dr.circle(px(x), px(y), r, 'paper', colour, { width: Math.max(1.3, t * 0.04) });
        dr.text(px(x), px(y), String(c), { size: t * 0.42, colour });
      }
    }
  },

  animLength(oldState, newState) {
    return changedAt(oldState.soln, newState.soln) ? DRAW_TIME : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.usedSolve && !newState.usedSolve
      ? FLASH
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,

  /** Half of the solution of the puzzle the menu renders (seed `thumbnail:slant`). */
  thumbnailMoves: ['/0,0;\\2,0;\\4,0;\\1,1;\\3,1;/0,2;\\2,2;/4,2;/1,3;/3,3;\\0,4;/2,4;\\4,4'],
});

export default game;
