/**
 * The little the play page has to remember about the puzzle on the board for its
 * achievements: undos and restarts since the deal, whether it was lost along the way, and
 * how long it has been on screen. Fed the midend's own `onMove` effects, like the
 * analytics tracker, and independent of it — analytics can be off, achievements cannot.
 */
import type { MoveEffect } from '../framework/midend';

export interface PuzzleRun {
  effect(e: MoveEffect): void;
  /** The board has just been lost (a later win is then a comeback). */
  lost(): void;
  snapshot(): { undos: number; restarts: number; secs: number; lostBefore: boolean };
  /** Count `secs` already spent on this puzzle before (a saved game put back on a reload). */
  carry(secs: number): void;
  /**
   * Stop or restart the clock: the pause menu, an ad. Time behind either is not time spent
   * on the puzzle, which is what the results card and the quick-solve badges count.
   */
  pause(on: boolean): void;
  destroy(): void;
}

export function trackRun(): PuzzleRun {
  let undos = 0;
  let restarts = 0;
  let lostBefore = false;
  let shownMs = 0;
  let paused = false;
  /** Whether the clock should be running: the page in view and nothing on top of the play. */
  const running = () => document.visibilityState !== 'hidden' && !paused;
  let since: number | null = running() ? performance.now() : null;
  /** Bank what has run and start or stop, to match `running()`. */
  const sync = () => {
    if (since !== null) shownMs += performance.now() - since;
    since = running() ? performance.now() : null;
  };
  const onVisibility = () => sync();
  document.addEventListener('visibilitychange', onVisibility);
  const reset = () => {
    undos = restarts = shownMs = 0;
    lostBefore = false;
    since = running() ? performance.now() : null;
  };
  return {
    effect(e) {
      if (e === 'new') reset();
      else if (e === 'undo') undos++;
      else if (e === 'restart') restarts++;
    },
    lost() {
      lostBefore = true;
    },
    carry(secs) {
      if (Number.isFinite(secs) && secs > 0) shownMs += secs * 1000;
    },
    pause(on) {
      if (paused === on) return;
      paused = on;
      sync();
    },
    snapshot() {
      const ms = shownMs + (since !== null ? performance.now() - since : 0);
      return { undos, restarts, secs: Math.round(ms / 100) / 10, lostBefore };
    },
    destroy() {
      document.removeEventListener('visibilitychange', onVisibility);
    },
  };
}
