import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_UP,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  isCursorMove,
  isCursorSelect,
  stripMods,
} from '../../framework/input';
import { DIRS4, clamp, easeInOut, flashOn, inBounds, parseWxH } from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export type BoardType = 'cross' | 'octagon' | 'random';
export const BOARD_TYPES: readonly BoardType[] = ['cross', 'octagon', 'random'];

export interface PegsParams {
  w: number;
  h: number;
  type: BoardType;
}

/** Cell contents. An absent cell is part of the board's outline, not a place to play. */
export const HOLE = 0;
export const PEG = 1;
export const ABSENT = 2;

export interface PegsState {
  w: number;
  h: number;
  /** Row-major cells: HOLE, PEG or ABSENT. Absent cells never change. */
  grid: number[];
  moves: number;
  /** Move count at which a single peg was first reached, or 0. */
  completed: number;
}

export interface PegsUI {
  /** A peg is being dragged with the mouse. */
  dragging: boolean;
  /** Grid cell the drag started on. */
  sx: number;
  sy: number;
  /** Pointer position (canvas pixels) during a drag; the peg is drawn here. */
  dx: number;
  dy: number;
  /** The peg under the pointer was already picked up when the press began. */
  reselect: boolean;
  /** A picked-up peg waiting for a destination (click or Enter); -1 when none. */
  selX: number;
  selY: number;
  cx: number;
  cy: number;
  cursorVisible: boolean;
}

/** A jump from (sx, sy) to (tx, ty), removing the peg between them. */
export interface Jump {
  sx: number;
  sy: number;
  tx: number;
  ty: number;
}

const FLASH_FRAME = 0.13;
/** How long a peg is in the air. */
const ANIM = 0.26;
const MAX_SIDE = 16;
/** Standard-shape boards are only known to be solvable at this size. */
const STANDARD_SIDE = 7;

// ------------------------------------------------------------------ rules

export function isLegalJump(
  grid: ArrayLike<number>,
  w: number,
  h: number,
  sx: number,
  sy: number,
  tx: number,
  ty: number,
): boolean {
  if (!inBounds(sx, sy, w, h) || !inBounds(tx, ty, w, h)) return false;
  const dx = tx - sx;
  const dy = ty - sy;
  if (Math.max(Math.abs(dx), Math.abs(dy)) !== 2 || Math.min(Math.abs(dx), Math.abs(dy)) !== 0)
    return false;
  const mx = sx + dx / 2;
  const my = sy + dy / 2;
  return grid[sy * w + sx] === PEG && grid[my * w + mx] === PEG && grid[ty * w + tx] === HOLE;
}

export function countPegs(grid: ArrayLike<number>): number {
  let n = 0;
  for (let i = 0; i < grid.length; i++) if (grid[i] === PEG) n++;
  return n;
}

/** Every jump that can be made on the board right now. */
export function legalJumps(grid: ArrayLike<number>, w: number, h: number): Jump[] {
  const out: Jump[] = [];
  for (let sy = 0; sy < h; sy++) {
    for (let sx = 0; sx < w; sx++) {
      if (grid[sy * w + sx] !== PEG) continue;
      for (const [dx, dy] of DIRS4) {
        const tx = sx + 2 * dx;
        const ty = sy + 2 * dy;
        if (isLegalJump(grid, w, h, sx, sy, tx, ty)) out.push({ sx, sy, tx, ty });
      }
    }
  }
  return out;
}

function hasAnyJump(grid: ArrayLike<number>, w: number, h: number): boolean {
  for (let sy = 0; sy < h; sy++) {
    for (let sx = 0; sx < w; sx++) {
      if (grid[sy * w + sx] !== PEG) continue;
      for (const [dx, dy] of DIRS4)
        if (isLegalJump(grid, w, h, sx, sy, sx + 2 * dx, sy + 2 * dy)) return true;
    }
  }
  return false;
}

function encodeJump(sx: number, sy: number, tx: number, ty: number): string {
  return `${sx},${sy}-${tx},${ty}`;
}

// ------------------------------------------------------------------ boards

/** The traditional English board: a plus shape of 33 cells with the centre empty. */
export function crossBoard(w: number, h: number): number[] {
  const grid = new Array<number>(w * h);
  const hw = Math.floor(w / 2);
  const hh = Math.floor(h / 2);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const ax = Math.abs(x - hw);
      const ay = Math.abs(y - hh);
      grid[y * w + x] = ax === 0 && ay === 0 ? HOLE : ax > 1 && ay > 1 ? ABSENT : PEG;
    }
  }
  return grid;
}

/**
 * Starting holes on the 7×7 octagon from which the puzzle can be finished. With the
 * hole in the centre (or most other places) a colouring argument shows that no
 * sequence of jumps can ever leave a single peg, so one of these is opened instead.
 * They fall into three classes: a corner of the octagon, a cell two steps from the
 * centre along an axis, and a cell one step from the centre.
 */
const OCTAGON_HOLES: readonly (readonly [number, number])[][] = [
  [
    [2, 0],
    [4, 0],
    [0, 2],
    [6, 2],
    [0, 4],
    [6, 4],
    [2, 6],
    [4, 6],
  ],
  [
    [1, 3],
    [5, 3],
    [3, 1],
    [3, 5],
  ],
  [
    [2, 3],
    [4, 3],
    [3, 2],
    [3, 4],
  ],
];

/** The traditional European board: a 7×7 octagon of 37 cells with one peg missing. */
export function octagonBoard(w: number, h: number, rng: Random): number[] {
  const grid = new Array<number>(w * h);
  const hw = Math.floor(w / 2);
  const hh = Math.floor(h / 2);
  const limit = 1 + Math.floor(Math.max(w, h) / 2);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const ax = Math.abs(x - hw);
      const ay = Math.abs(y - hh);
      grid[y * w + x] = ax + ay > limit ? ABSENT : PEG;
    }
  }
  // Pick a class first so that each class is equally likely, as the original does.
  const cls = OCTAGON_HOLES[rng.upto(OCTAGON_HOLES.length)];
  const [hx, hy] = cls[rng.upto(cls.length)];
  grid[hy * w + hx] = HOLE;
  return grid;
}

/**
 * Which board a description shows: the cross exactly as dealt, the octagon's shape with its
 * one starting hole at a solvable spot, or else a random board.
 */
export function boardTypeOf(w: number, h: number, desc: string): BoardType {
  if (desc === encodeGrid(crossBoard(w, h))) return 'cross';
  // The octagon with every cell pegged, as `octagonBoard` lays it out before the hole.
  const hw = Math.floor(w / 2);
  const hh = Math.floor(h / 2);
  const limit = 1 + Math.floor(Math.max(w, h) / 2);
  let shape = '';
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) shape += Math.abs(x - hw) + Math.abs(y - hh) > limit ? 'O' : 'P';
  const holes = [...desc].flatMap((c, i) => (c === 'H' ? [i] : []));
  if (holes.length === 1 && desc.replace('H', 'P') === shape) {
    const [hole] = holes;
    const x = hole % w;
    const y = Math.floor(hole / w);
    if (OCTAGON_HOLES.some((cls) => cls.some(([hx, hy]) => hx === x && hy === y))) return 'octagon';
  }
  return 'random';
}

export interface RandomBoard {
  grid: number[];
  /** Jumps that finish the board, in playing order. */
  solution: Jump[];
}

/**
 * Grow a random board by playing peg solitaire backwards. Start from a lone peg in the
 * middle of an otherwise absent board and repeatedly "un-jump": a peg at A moves back
 * to C, leaving a new peg at B in between, where B and C were not pegs before. Cells
 * that were absent become part of the board as they are used. Moves that reuse
 * existing board cells are preferred over ones that carve out new cells (cost = the
 * number of absent cells they open up), and once half the rectangle has been visited
 * moves that open two new cells are no longer taken. Whatever this produces can be
 * solved by playing the same moves forwards; boards that fail to reach all four edges
 * of the rectangle are thrown away and regrown.
 */
export function generateRandomBoard(w: number, h: number, rng: Random): RandomBoard {
  const wh = w * h;
  for (;;) {
    const grid = new Array<number>(wh).fill(ABSENT);
    grid[Math.floor(h / 2) * w + Math.floor(w / 2)] = PEG;
    const undone: Jump[] = [];

    for (;;) {
      const maxCost = undone.length < Math.floor(wh / 2) ? 2 : 1;
      const byCost: Jump[][] = [[], [], []];
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          if (grid[y * w + x] !== PEG) continue;
          for (const [dx, dy] of DIRS4) {
            const bx = x + dx;
            const by = y + dy;
            const cx = x + 2 * dx;
            const cy = y + 2 * dy;
            if (!inBounds(cx, cy, w, h)) continue;
            const vb = grid[by * w + bx];
            const vc = grid[cy * w + cx];
            if (vb === PEG || vc === PEG) continue;
            const cost = (vb === ABSENT ? 1 : 0) + (vc === ABSENT ? 1 : 0);
            // Playing forwards this is a jump from C over B to A.
            byCost[cost].push({ sx: cx, sy: cy, tx: x, ty: y });
          }
        }
      }
      let pool: Jump[] | null = null;
      for (let c = 0; c <= maxCost; c++) {
        if (byCost[c].length) {
          pool = byCost[c];
          break;
        }
      }
      if (!pool) break;
      const j = pool[rng.upto(pool.length)];
      grid[j.ty * w + j.tx] = HOLE;
      grid[((j.sy + j.ty) / 2) * w + (j.sx + j.tx) / 2] = PEG;
      grid[j.sy * w + j.sx] = PEG;
      undone.push(j);
    }

    let edges = 0;
    for (let y = 0; y < h; y++) {
      if (grid[y * w] !== ABSENT) edges |= 1;
      if (grid[y * w + w - 1] !== ABSENT) edges |= 2;
    }
    for (let x = 0; x < w; x++) {
      if (grid[x] !== ABSENT) edges |= 4;
      if (grid[(h - 1) * w + x] !== ABSENT) edges |= 8;
    }
    if (edges === 15) return { grid, solution: undone.reverse() };
  }
}

function encodeGrid(grid: number[]): string {
  let s = '';
  for (const v of grid) s += v === PEG ? 'P' : v === HOLE ? 'H' : 'O';
  return s;
}

function decodeGrid(desc: string): number[] {
  const grid: number[] = [];
  for (const ch of desc) grid.push(ch === 'P' ? PEG : ch === 'H' ? HOLE : ABSENT);
  return grid;
}

// ------------------------------------------------------------------ helpers

function borderFor(t: number): number {
  return Math.round(t * 0.3);
}

function cellAt(ds: DrawState, mx: number, my: number): { x: number; y: number } {
  const t = ds.tileSize;
  const b = borderFor(t);
  return { x: Math.floor((mx - b) / t), y: Math.floor((my - b) / t) };
}

function typeName(t: BoardType): string {
  return t === 'cross' ? 'Cross' : t === 'octagon' ? 'Octagon' : 'Random';
}

/** Step the cursor one cell, skipping over absent cells; stays put at the edge. */
function stepCursor(state: PegsState, cx: number, cy: number, dx: number, dy: number) {
  let x = cx + dx;
  let y = cy + dy;
  while (inBounds(x, y, state.w, state.h)) {
    if (state.grid[y * state.w + x] !== ABSENT) return { x, y };
    x += dx;
    y += dy;
  }
  return { x: cx, y: cy };
}

function cursorDelta(button: number): [number, number] {
  switch (button) {
    case CURSOR_UP:
      return [0, -1];
    case CURSOR_DOWN:
      return [0, 1];
    case CURSOR_LEFT:
      return [-1, 0];
    default:
      return [1, 0];
  }
}

// ------------------------------------------------------------------ the game

const game = defineGame<PegsParams, PegsState, PegsUI>({
  id: 'pegs',
  name: 'Pegs',
  description: 'Jump pegs over each other until only one is left.',
  alsoKnownAs: 'Peg solitaire',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: [
    { name: 'Cross', params: { w: 7, h: 7, type: 'cross' } },
    { name: 'Octagon', params: { w: 7, h: 7, type: 'octagon' } },
    { name: 'Random 5×5', params: { w: 5, h: 5, type: 'random' } },
    { name: 'Random 7×7', params: { w: 7, h: 7, type: 'random' } },
    { name: 'Random 9×9', params: { w: 9, h: 9, type: 'random' } },
  ],
  defaultParams: () => ({ w: 7, h: 7, type: 'cross' }),
  encodeParams: (p, full) => `${p.w}x${p.h}${full ? p.type : ''}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    // A descriptive ID (a share link) carries only the size. The traditional boards exist
    // only at 7×7, so any other size must have been a random one: reading it as a cross
    // left New dealing a 5×5 or 9×9 "cross" the custom dialog would refuse.
    const standard = r.w === STANDARD_SIDE && r.h === STANDARD_SIDE;
    const type = (BOARD_TYPES as readonly string[]).includes(r.rest)
      ? (r.rest as BoardType)
      : standard
        ? 'cross'
        : 'random';
    return { w: r.w, h: r.h, type };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must be positive`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (!BOARD_TYPES.includes(p.type)) return tx`Unknown board type`;
    if (full) {
      if (p.w <= 3 || p.h <= 3) return tx`Width and height must both be greater than three`;
      if (p.type !== 'random' && (p.w !== STANDARD_SIDE || p.h !== STANDARD_SIDE))
        return p.type === 'cross'
          ? tx`The Cross board is only available at ${STANDARD_SIDE}×${STANDARD_SIDE}`
          : tx`The Octagon board is only available at ${STANDARD_SIDE}×${STANDARD_SIDE}`;
    }
    return null;
  },
  paramsFromDesc(p, desc) {
    // Only 7×7 is ambiguous: `decodeParams` already reads every other size as random.
    if (p.w !== STANDARD_SIDE || p.h !== STANDARD_SIDE) return null;
    return { ...p, type: boardTypeOf(p.w, p.h, desc) };
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      {
        type: 'choices',
        name: 'Board type',
        choices: BOARD_TYPES.map(typeName),
        selected: Math.max(0, BOARD_TYPES.indexOf(p.type)),
      },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "7.5" or "7x" as a size.
    const int = (i: number) => {
      const s = (items[i] as { value: string }).value.trim();
      return /^-?\d+$/.test(s) ? parseInt(s, 10) : NaN;
    };
    const w = int(0);
    const h = int(1);
    const sel = (items[2] as { selected: number }).selected;
    return { w, h, type: BOARD_TYPES[sel] ?? 'cross' };
  },

  newDesc(p, rng: Random) {
    const grid =
      p.type === 'cross'
        ? crossBoard(p.w, p.h)
        : p.type === 'octagon'
          ? octagonBoard(p.w, p.h, rng)
          : generateRandomBoard(p.w, p.h, rng).grid;
    return { desc: encodeGrid(grid) };
  },

  validateDesc(p, desc) {
    if (desc.length !== p.w * p.h) return tx`Description must be exactly ${p.w * p.h} characters`;
    if (!/^[PHO]*$/.test(desc)) return tx`Description may only contain P, H and O`;
    if (!desc.includes('P')) return tx`Description must contain at least one peg`;
    return null;
  },

  newGame(p, desc) {
    return { w: p.w, h: p.h, grid: decodeGrid(desc), moves: 0, completed: 0 };
  },

  canSolve: false,

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const v = s.grid[y * s.w + x];
        row += v === PEG ? '*' : v === HOLE ? '-' : ' ';
      }
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI(state) {
    // Start the cursor in the middle if that is part of the board, else on the first
    // cell that is.
    let cx = Math.floor(state.w / 2);
    let cy = Math.floor(state.h / 2);
    if (state.grid[cy * state.w + cx] === ABSENT) {
      const i = state.grid.findIndex((v) => v !== ABSENT);
      if (i >= 0) {
        cx = i % state.w;
        cy = Math.floor(i / state.w);
      }
    }
    return {
      dragging: false,
      sx: 0,
      sy: 0,
      dx: 0,
      dy: 0,
      reselect: false,
      selX: -1,
      selY: -1,
      cx,
      cy,
      cursorVisible: false,
    };
  },

  changedState(ui) {
    // The board changed under us (move, undo, redo): any drag or picked-up peg may no
    // longer refer to a peg, so drop it.
    ui.dragging = false;
    ui.selX = ui.selY = -1;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, grid } = state;
    if (ui.selX >= 0 && grid[ui.selY * w + ui.selX] !== PEG) ui.selX = ui.selY = -1;

    if (b === LEFT_BUTTON) {
      const { x, y } = cellAt(ds, mx, my);
      const wasVisible = ui.cursorVisible;
      const hadSel = ui.selX >= 0;
      ui.cursorVisible = false;
      if (inBounds(x, y, w, h) && grid[y * w + x] === PEG) {
        // Pick the peg up. Whether this turns out to be a drag or a click is decided
        // on release.
        ui.dragging = true;
        ui.sx = x;
        ui.sy = y;
        ui.dx = mx;
        ui.dy = my;
        ui.reselect = ui.selX === x && ui.selY === y;
        ui.selX = x;
        ui.selY = y;
        return '';
      }
      if (hadSel) {
        const sx = ui.selX;
        const sy = ui.selY;
        ui.selX = ui.selY = -1;
        if (isLegalJump(grid, w, h, sx, sy, x, y)) return encodeJump(sx, sy, x, y);
        return '';
      }
      return wasVisible ? '' : null;
    }

    if (b === LEFT_DRAG) {
      if (!ui.dragging) return null;
      ui.dx = mx;
      ui.dy = my;
      return '';
    }

    if (b === LEFT_RELEASE) {
      if (!ui.dragging) return null;
      ui.dragging = false;
      const { x, y } = cellAt(ds, mx, my);
      const { sx, sy } = ui;
      if (x === sx && y === sy) {
        // A plain click: the peg stays picked up until a destination is clicked, or
        // is put back down if it was already picked up.
        if (ui.reselect) ui.selX = ui.selY = -1;
        return '';
      }
      ui.selX = ui.selY = -1;
      if (isLegalJump(grid, w, h, sx, sy, x, y)) return encodeJump(sx, sy, x, y);
      return '';
    }

    if (isCursorMove(b)) {
      const [dx, dy] = cursorDelta(b);
      ui.cursorVisible = true;
      if (ui.selX >= 0) {
        // A picked-up peg jumps in the direction pressed, if it can. Either way it is
        // put down again.
        const sx = ui.selX;
        const sy = ui.selY;
        ui.selX = ui.selY = -1;
        ui.cx = sx;
        ui.cy = sy;
        const tx = sx + 2 * dx;
        const ty = sy + 2 * dy;
        if (isLegalJump(grid, w, h, sx, sy, tx, ty)) {
          ui.cx = tx;
          ui.cy = ty;
          return encodeJump(sx, sy, tx, ty);
        }
        return '';
      }
      const p = stepCursor(state, ui.cx, ui.cy, dx, dy);
      ui.cx = p.x;
      ui.cy = p.y;
      return '';
    }

    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const here = grid[ui.cy * w + ui.cx];
      if (ui.selX >= 0) {
        const sx = ui.selX;
        const sy = ui.selY;
        ui.selX = ui.selY = -1;
        if (isLegalJump(grid, w, h, sx, sy, ui.cx, ui.cy)) return encodeJump(sx, sy, ui.cx, ui.cy);
        if (here === PEG && (sx !== ui.cx || sy !== ui.cy)) {
          ui.selX = ui.cx;
          ui.selY = ui.cy;
        }
        return '';
      }
      if (here === PEG) {
        ui.selX = ui.cx;
        ui.selY = ui.cy;
        return '';
      }
      return null;
    }

    return null;
  },

  executeMove(state, move) {
    const m = /^(\d+),(\d+)-(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const [sx, sy, tx, ty] = m.slice(1).map((v) => parseInt(v, 10));
    const { w, h } = state;
    if (!isLegalJump(state.grid, w, h, sx, sy, tx, ty)) return null;
    const grid = state.grid.slice();
    grid[sy * w + sx] = HOLE;
    grid[((sy + ty) / 2) * w + (sx + tx) / 2] = HOLE;
    grid[ty * w + tx] = PEG;
    const moves = state.moves + 1;
    return {
      ...state,
      grid,
      moves,
      completed: state.completed || (countPegs(grid) === 1 ? moves : 0),
    };
  },

  preferredTileSize: 48,
  computeSize(p, t) {
    const b = borderFor(t);
    return { w: p.w * t + 2 * b, h: p.h * t + 2 * b };
  },

  redraw(dr: Drawing, ds, oldState, state, dir, ui, animTime, flashTime) {
    const { w, h, grid } = state;
    const t = ds.tileSize;
    const b = borderFor(t);
    const flashing = flashOn(flashTime, FLASH_FRAME);
    const onBoard = (x: number, y: number) => inBounds(x, y, w, h) && grid[y * w + x] !== ABSENT;
    const X = (x: number) => b + x * t;
    const Y = (y: number) => b + y * t;

    if (flashing) {
      for (let y = 0; y < h; y++)
        for (let x = 0; x < w; x++) if (onBoard(x, y)) dr.rect(X(x), Y(y), t, t, 'shade', null);
    }

    // Faint lines between neighbouring board cells, drawn as long runs so the sketchy
    // strokes look like ruled lines rather than a mosaic.
    for (let x = 1; x < w; x++) {
      let y0 = -1;
      for (let y = 0; y <= h; y++) {
        const on = y < h && onBoard(x - 1, y) && onBoard(x, y);
        if (on && y0 < 0) y0 = y;
        if (!on && y0 >= 0) {
          dr.line(X(x), Y(y0), X(x), Y(y), 'faint', 1.2);
          y0 = -1;
        }
      }
    }
    for (let y = 1; y < h; y++) {
      let x0 = -1;
      for (let x = 0; x <= w; x++) {
        const on = x < w && onBoard(x, y - 1) && onBoard(x, y);
        if (on && x0 < 0) x0 = x;
        if (!on && x0 >= 0) {
          dr.line(X(x0), Y(y), X(x), Y(y), 'faint', 1.2);
          x0 = -1;
        }
      }
    }
    // The board's outline in ink: every edge between a board cell and the outside.
    for (let y = 0; y <= h; y++) {
      let x0 = -1;
      for (let x = 0; x <= w; x++) {
        const on = x < w && onBoard(x, y) !== onBoard(x, y - 1);
        if (on && x0 < 0) x0 = x;
        if (!on && x0 >= 0) {
          dr.line(X(x0), Y(y), X(x), Y(y), 'ink', 2.4);
          x0 = -1;
        }
      }
    }
    for (let x = 0; x <= w; x++) {
      let y0 = -1;
      for (let y = 0; y <= h; y++) {
        const on = y < h && onBoard(x, y) !== onBoard(x - 1, y);
        if (on && y0 < 0) y0 = y;
        if (!on && y0 >= 0) {
          dr.line(X(x), Y(y0), X(x), Y(y), 'ink', 2.4);
          y0 = -1;
        }
      }
    }

    // A jump moves three squares at once — the peg leaves, the one it hops is taken, and
    // it lands two squares on — and all three used to change between two frames. `jump`
    // reads which is which straight out of the two states, so nothing is recorded to
    // animate it; `p` runs from the board before the hop to the board after it, which an
    // undo simply walks backwards.
    const jump = oldState ? readJump(oldState, state, dir) : null;
    const p = jump
      ? dir > 0
        ? clamp(animTime / ANIM, 0, 1)
        : 1 - clamp(animTime / ANIM, 0, 1)
      : 1;

    const selected =
      ui.selX >= 0 && grid[ui.selY * w + ui.selX] === PEG ? { x: ui.selX, y: ui.selY } : null;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const v = grid[i];
        if (v === ABSENT) continue;
        const cx = X(x) + t / 2;
        const cy = Y(y) + t / 2;
        const lifted = ui.dragging && ui.sx === x && ui.sy === y;
        // The three squares the jump is using draw their own peg below, in the air or
        // fading; here they are only ever the hole underneath.
        const inFlight = jump && (i === jump.from || i === jump.to || i === jump.over);
        if (v === PEG && !lifted && !inFlight) {
          const isSel = !!selected && selected.x === x && selected.y === y;
          drawPeg(dr, cx, cy, t, isSel ? 'accent' : 'ink', i);
        } else {
          drawHole(dr, cx, cy, t, flashing);
        }
      }
    }

    if (jump) {
      // The peg it hops over is taken as the traveller passes over it, not before.
      const gone = clamp((p - 0.34) / 0.36, 0, 1);
      if (gone < 1) {
        const ox = X(jump.over % w) + t / 2;
        const oy = Y(Math.floor(jump.over / w)) + t / 2;
        drawPeg(dr, ox, oy, t, dr.withAlpha('ink', 1 - gone), jump.over);
      }
      // And the peg itself, lifted off the board and dropped two squares on. The arc is
      // what makes it a hop rather than a slide, and the board is a physical one.
      const e = easeInOut(p);
      const fx = X(jump.from % w) + t / 2;
      const fy = Y(Math.floor(jump.from / w)) + t / 2;
      const tx2 = X(jump.to % w) + t / 2;
      const ty2 = Y(Math.floor(jump.to / w)) + t / 2;
      const px = fx + (tx2 - fx) * e;
      const py = fy + (ty2 - fy) * e - Math.sin(Math.PI * e) * t * 0.42;
      drawPeg(dr, px, py, t, 'ink', jump.from);
    }

    // Where the picked-up peg may land.
    if (selected) {
      for (const [dx, dy] of DIRS4) {
        const tx = selected.x + 2 * dx;
        const ty = selected.y + 2 * dy;
        if (isLegalJump(grid, w, h, selected.x, selected.y, tx, ty)) {
          dr.circle(X(tx) + t / 2, Y(ty) + t / 2, t * 0.3, null, 'accent', {
            width: 1.6,
            dash: [t * 0.12, t * 0.1],
          });
        }
      }
    }

    if (ui.cursorVisible) {
      const pad = Math.max(2, t * 0.06);
      dr.cursor(X(ui.cx) + pad, Y(ui.cy) + pad, t - 2 * pad, t - 2 * pad);
    }

    if (ui.dragging) drawPeg(dr, ui.dx, ui.dy, t, 'accent', -1, 0.4);

    const pegs = countPegs(grid);
    const status =
      pegs === 1
        ? tr('status.movesCompleted', { n: state.completed })
        : !hasAnyJump(grid, w, h)
          ? tr('games.pegs.status.stuck', { n: pegs })
          : tr('games.pegs.status.playing', { n: pegs, moves: state.moves });
    dr.statusBar(status);
  },

  animLength(oldState, newState, dir) {
    return readJump(oldState, newState, dir) ? ANIM : 0;
  },
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed ? 3 * FLASH_FRAME : 0;
  },
  status(s) {
    if (countPegs(s.grid) === 1) return 1;
    return hasAnyJump(s.grid, s.w, s.h) ? 0 : -1;
  },
  wantsStatusBar: true,
  isTimed: false,
  // Stuck with no jump left: the jump before is always one Undo back.
  flags: { oneButton: true, undoAfterLoss: true },
});

/**
 * The three squares a jump used, worked out from the boards either side of it: the peg
 * left `from`, was hopped `over`, and landed on `to`. Returns null for anything that is
 * not a single jump — a fresh deal, a Restart, a Solve — which is also what tells
 * `animLength` there is nothing to animate.
 */
function readJump(
  oldState: PegsState,
  newState: PegsState,
  dir: number,
): { from: number; to: number; over: number } | null {
  const earlier = dir > 0 ? oldState : newState;
  const later = dir > 0 ? newState : oldState;
  const { w, grid } = earlier;
  if (later.grid.length !== grid.length) return null;
  let to = -1;
  const emptied: number[] = [];
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] === later.grid[i]) continue;
    if (later.grid[i] === PEG && grid[i] === HOLE) {
      if (to >= 0) return null;
      to = i;
    } else if (later.grid[i] === HOLE && grid[i] === PEG) {
      if (emptied.length === 2) return null;
      emptied.push(i);
    } else {
      return null;
    }
  }
  if (to < 0 || emptied.length !== 2) return null;
  const tx = to % w;
  const ty = (to - tx) / w;
  const dist = (i: number) => Math.abs((i % w) - tx) + Math.abs((i - (i % w)) / w - ty);
  const from = emptied.find((i) => dist(i) === 2);
  const over = emptied.find((i) => dist(i) === 1);
  return from === undefined || over === undefined ? null : { from, to, over };
}

/** A peg: a solid disc with a little shine. `rough` is lowered for the dragged peg. */
function drawPeg(
  dr: Drawing,
  cx: number,
  cy: number,
  t: number,
  colour: string,
  seed: number,
  rough?: number,
): void {
  const r = t * 0.3;
  dr.circle(cx, cy, r, colour, colour, { width: 1.6, seed, rough });
  dr.dot(cx - r * 0.35, cy - r * 0.38, r * 0.2, 'highlight', { alpha: 0.75, seed, rough });
}

/** An empty hole: a shaded dent outlined in pencil. */
function drawHole(dr: Drawing, cx: number, cy: number, t: number, flashing: boolean): void {
  dr.circle(cx, cy, t * 0.2, flashing ? 'paper' : 'shade', 'pencil', { width: 1.4 });
}

export default game;
