/**
 * Galaxies board geometry.
 *
 * Everything lives on a "doubled" grid of (2w+1) × (2h+1) positions: even/even
 * coordinates are vertices, odd/odd are tiles (cells), the rest are edges. Dots can sit
 * on any of the three, and the mirror image of position p through dot d is simply
 * 2d − p, which keeps all the symmetry arithmetic integer.
 */
import { tx } from '../../i18n';
import { DSF } from '../../framework/dsf';

export const DIFF_NORMAL = 0;
export const DIFF_UNREASONABLE = 1;
export const DIFFICULTY_NAMES = ['Normal', 'Unreasonable'];
export const DIFFICULTY_CHARS = 'nu';

/** Anything with the doubled-grid dimensions. */
export interface Grid {
  sx: number;
  sy: number;
}

/** The fixed part of a puzzle: its size and its dots. Shared by every state. */
export interface Layout extends Grid {
  w: number;
  h: number;
  /** sx × sy. */
  n: number;
  /** 1 at doubled-grid positions holding a dot. */
  dot: Uint8Array;
  /** 1 where that dot is "black" (upper-case letter in the description). */
  black: Uint8Array;
  /** Grid indices of the dots, in row-major order. */
  dots: number[];
  /** Grid indices of all tiles, row-major. */
  tiles: number[];
  /** Grid indices of all interior edges (the outer border is fixed), row-major. */
  edgeList: number[];
}

export const isTilePos = (x: number, y: number): boolean => (x & 1) === 1 && (y & 1) === 1;
export const isEdgePos = (x: number, y: number): boolean => ((x ^ y) & 1) === 1;
export const isVertexPos = (x: number, y: number): boolean => (x & 1) === 0 && (y & 1) === 0;

export function inGrid(g: Grid, x: number, y: number): boolean {
  return x >= 0 && y >= 0 && x < g.sx && y < g.sy;
}

/** Inside the playable area: everything except the fixed outer border. */
export function inUI(g: Grid, x: number, y: number): boolean {
  return x > 0 && y > 0 && x < g.sx - 1 && y < g.sy - 1;
}

export function makeLayout(w: number, h: number, dot: Uint8Array, black: Uint8Array): Layout {
  const sx = 2 * w + 1;
  const sy = 2 * h + 1;
  const n = sx * sy;
  const dots: number[] = [];
  const tiles: number[] = [];
  const edgeList: number[] = [];
  for (let y = 0; y < sy; y++) {
    for (let x = 0; x < sx; x++) {
      const i = y * sx + x;
      if (dot[i]) dots.push(i);
      if (isTilePos(x, y)) tiles.push(i);
      else if (isEdgePos(x, y) && inUI({ sx, sy }, x, y)) edgeList.push(i);
    }
  }
  return { w, h, sx, sy, n, dot, black, dots, tiles, edgeList };
}

/** Mirror image of grid position `i` through position `d`, or -1 when off the grid. */
export function opposite(g: Grid, i: number, d: number): number {
  const x = i % g.sx;
  const y = (i - x) / g.sx;
  const dx = d % g.sx;
  const dy = (d - dx) / g.sx;
  const tx = 2 * dx - x;
  const ty = 2 * dy - y;
  if (tx < 0 || ty < 0 || tx >= g.sx || ty >= g.sy) return -1;
  return ty * g.sx + tx;
}

/** The two tiles either side of an interior edge. */
export function edgeTiles(g: Grid, e: number): [number, number] {
  const x = e % g.sx;
  return (x & 1) === 0 ? [e - 1, e + 1] : [e - g.sx, e + g.sx];
}

/** Tiles touching a position: the tile itself, the two beside an edge, or the four around a vertex. */
export function touchingTiles(g: Grid, p: number): number[] {
  const x = p % g.sx;
  const y = (p - x) / g.sx;
  const out: number[] = [];
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const tx = x + dx;
      const ty = y + dy;
      if (isTilePos(tx, ty) && inGrid(g, tx, ty)) out.push(ty * g.sx + tx);
    }
  }
  return out;
}

/** Fresh edge array: the outer border set, everything else clear. */
export function initialEdges(g: Grid): Uint8Array {
  const edges = new Uint8Array(g.sx * g.sy);
  for (let x = 0; x < g.sx; x++) {
    edges[x] = 1;
    edges[(g.sy - 1) * g.sx + x] = 1;
  }
  for (let y = 0; y < g.sy; y++) {
    edges[y * g.sx] = 1;
    edges[y * g.sx + g.sx - 1] = 1;
  }
  return edges;
}

/** Edges implied by a complete tile → dot assignment: set wherever the two sides differ. */
export function edgesFromAssoc(L: Layout, assoc: Int32Array): Uint8Array {
  const edges = initialEdges(L);
  for (const e of L.edgeList) {
    const [a, b] = edgeTiles(L, e);
    if (assoc[a] < 0 || assoc[a] !== assoc[b]) edges[e] = 1;
  }
  return edges;
}

// ------------------------------------------------------------------ descriptions

/**
 * Descriptions run over the interior of the doubled grid, row by row: each letter is the
 * number of empty positions before the next dot (`a` = 0 … `y` = 24; upper case for a
 * black dot) and `z` is 25 empty positions with no dot. Trailing space is omitted.
 */
export function parseDesc(desc: string, w: number, h: number): Layout | string {
  const sx = 2 * w + 1;
  const sy = 2 * h + 1;
  const iw = sx - 2;
  const ih = sy - 2;
  const dot = new Uint8Array(sx * sy);
  const black = new Uint8Array(sx * sy);
  let i = 0;
  for (const ch of desc) {
    if (ch === 'z') {
      i += 25;
      continue;
    }
    let isBlack: boolean;
    if (ch >= 'a' && ch <= 'y') {
      i += ch.charCodeAt(0) - 97;
      isBlack = false;
    } else if (ch >= 'A' && ch <= 'Y') {
      i += ch.charCodeAt(0) - 65;
      isBlack = true;
    } else {
      return tx`Invalid characters in game description`;
    }
    if (i >= iw * ih) return tx`Too much data to fit in grid`;
    const x = (i % iw) + 1;
    const y = Math.floor(i / iw) + 1;
    const p = y * sx + x;
    dot[p] = 1;
    if (isBlack) black[p] = 1;
    i++;
  }
  return makeLayout(w, h, dot, black);
}

export function encodeDesc(L: Layout): string {
  let out = '';
  let run = 0;
  for (let y = 1; y < L.sy - 1; y++) {
    for (let x = 1; x < L.sx - 1; x++) {
      const p = y * L.sx + x;
      if (!L.dot[p]) {
        run++;
        continue;
      }
      while (run > 24) {
        out += 'z';
        run -= 25;
      }
      out += String.fromCharCode((L.black[p] ? 65 : 97) + run);
      run = 0;
    }
  }
  return out;
}

/** Interior edges as a string of 0/1 in `edgeList` order (used for the solver hint). */
export function encodeEdgeBits(L: Layout, edges: Uint8Array): string {
  let s = '';
  for (const e of L.edgeList) s += edges[e] ? '1' : '0';
  return s;
}

export function decodeEdgeBits(L: Layout, bits: string): Uint8Array | null {
  if (bits.length !== L.edgeList.length || !/^[01]*$/.test(bits)) return null;
  const edges = initialEdges(L);
  L.edgeList.forEach((e, k) => {
    edges[e] = bits[k] === '1' ? 1 : 0;
  });
  return edges;
}

// ------------------------------------------------------------------ completion check

export interface Check {
  /** Representative cell of each cell's region (w × h, cell indices). */
  comp: Int32Array;
  /** 1 for cells inside a finished, correct region. */
  valid: Uint8Array;
  /** 1 for valid cells whose dot is black. */
  blackRegion: Uint8Array;
  /** 1 for cells of a region that holds no dot at all and so can never be right. */
  dotless: Uint8Array;
  /** Per entry of `L.dots`: 1 when the region around that dot is certainly wrong. */
  dotError: Uint8Array;
  complete: boolean;
}

/**
 * Split the grid into regions along the set edges and decide which are correct: a region
 * is valid when it is 180° symmetric, its centre of symmetry carries a dot, no other dot
 * touches any of its cells and no set edge runs through its inside.
 *
 * A dot is flagged as an error when an edge passes through it, or when it is the only
 * dot touching its region and that region is not symmetric about it.
 */
export function checkComplete(L: Layout, edges: Uint8Array): Check {
  const { w, h, sx } = L;
  const n = w * h;
  const dsf = new DSF(n);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = y * w + x;
      if (y + 1 < h && !edges[(2 * y + 2) * sx + 2 * x + 1]) dsf.merge(c, c + w);
      if (x + 1 < w && !edges[(2 * y + 1) * sx + 2 * x + 2]) dsf.merge(c, c + 1);
    }
  }
  const comp = new Int32Array(n);
  const minx = new Int32Array(n).fill(w);
  const maxx = new Int32Array(n).fill(-1);
  const miny = new Int32Array(n).fill(h);
  const maxy = new Int32Array(n).fill(-1);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const c = y * w + x;
      const r = dsf.find(c);
      comp[c] = r;
      if (x < minx[r]) minx[r] = x;
      if (x > maxx[r]) maxx[r] = x;
      if (y < miny[r]) miny[r] = y;
      if (y > maxy[r]) maxy[r] = y;
    }
  }
  // Where the centre of symmetry of each region would have to be, in doubled coordinates.
  const cx = new Int32Array(n);
  const cy = new Int32Array(n);
  const centreOk = new Uint8Array(n);
  const bad = new Uint8Array(n);
  const sym = new Uint8Array(n).fill(1);
  const overlap = new Int32Array(n);
  for (let r = 0; r < n; r++) {
    if (comp[r] !== r) continue;
    cx[r] = minx[r] + maxx[r] + 1;
    cy[r] = miny[r] + maxy[r] + 1;
    const centre = cy[r] * sx + cx[r];
    if (!L.dot[centre]) continue;
    let ok = 1;
    for (const t of touchingTiles(L, centre)) {
      const tx = t % sx;
      const ty = (t - tx) / sx;
      if (comp[((ty - 1) / 2) * w + (tx - 1) / 2] !== r) ok = 0;
    }
    centreOk[r] = ok;
  }
  // Dots: count distinct regions each one touches; a dot anywhere other than a region's
  // centre disqualifies that region.
  const split = new Uint8Array(L.dots.length);
  L.dots.forEach((d, k) => {
    const x = d % sx;
    const y = (d - x) / sx;
    const seen: number[] = [];
    for (const t of touchingTiles(L, d)) {
      const tx = t % sx;
      const ty = (t - tx) / sx;
      const r = comp[((ty - 1) / 2) * w + (tx - 1) / 2];
      if (seen.includes(r)) continue;
      seen.push(r);
      overlap[r]++;
      if (x !== cx[r] || y !== cy[r]) bad[r] = 1;
    }
    if (seen.length > 1) split[k] = 1;
  });
  // Set edges between two cells of the same region are stray lines.
  for (const e of L.edgeList) {
    if (!edges[e]) continue;
    const [a, b] = edgeTiles(L, e);
    const ax = a % sx;
    const bx = b % sx;
    const ca = ((a - ax) / sx - 1) / 2;
    const cb = ((b - bx) / sx - 1) / 2;
    const ra = comp[ca * w + (ax - 1) / 2];
    if (ra === comp[cb * w + (bx - 1) / 2]) bad[ra] = 1;
  }
  // Rotational symmetry about the region's centre.
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const r = comp[y * w + x];
      const x2 = cx[r] - 1 - x;
      const y2 = cy[r] - 1 - y;
      if (x2 < 0 || y2 < 0 || x2 >= w || y2 >= h || comp[y2 * w + x2] !== r) sym[r] = 0;
    }
  }

  const valid = new Uint8Array(n);
  const blackRegion = new Uint8Array(n);
  const dotless = new Uint8Array(n);
  let complete = true;
  for (let c = 0; c < n; c++) {
    const r = comp[c];
    if (centreOk[r] && !bad[r] && sym[r]) {
      valid[c] = 1;
      if (L.black[cy[r] * sx + cx[r]]) blackRegion[c] = 1;
    } else {
      complete = false;
    }
    if (overlap[r] === 0) dotless[c] = 1;
  }
  const dotError = new Uint8Array(L.dots.length);
  L.dots.forEach((d, k) => {
    if (split[k]) {
      dotError[k] = 1;
      return;
    }
    const x = d % sx;
    const y = (d - x) / sx;
    const t = touchingTiles(L, d)[0];
    const tx = t % sx;
    const r = comp[(((t - tx) / sx - 1) / 2) * w + (tx - 1) / 2];
    if (overlap[r] === 1 && !(cx[r] === x && cy[r] === y && sym[r])) dotError[k] = 1;
  });
  return { comp, valid, blackRegion, dotless, dotError, complete };
}

/** Plain-text picture of a position: `o` dots, `-`/`|` edges, `+` vertices, `*` assigned tiles. */
export function textFormat(L: Layout, edges: Uint8Array, assoc: Int32Array): string {
  const rows: string[] = [];
  for (let y = 0; y < L.sy; y++) {
    let row = '';
    for (let x = 0; x < L.sx; x++) {
      const i = y * L.sx + x;
      if (L.dot[i]) row += 'o';
      else if (isTilePos(x, y)) row += assoc[i] >= 0 ? '*' : ' ';
      else if (isVertexPos(x, y)) row += '+';
      else if (edges[i]) row += (x & 1) === 0 ? '|' : '-';
      else row += ' ';
    }
    rows.push(row);
  }
  return rows.join('\n');
}
