/**
 * The collection-wide achievements: how many puzzles, how many different games, how much
 * of the box unlocked, the hardest settings, habits across days. The per-game ones live
 * with their games (`Game.achievements`).
 *
 * Their text is shell text, so it is in `en.json` under `ui.achievements.meta.<id>` and
 * this file holds only ids, conditions and art.
 */
import type { AchievementTier, BadgeArt, PuzzleEndContext } from '../framework/achievements';
import type { PALETTE, PaletteToken } from '../framework/palette';
import { STARTER_GAMES } from '../ui/progress';
import { sparkle } from './art';

type C = typeof PALETTE;

/** The running totals every collection-wide condition is read from. */
export interface MetaView {
  /** Credited hand-solves, all games together. */
  solves: number;
  /** The most credited hand-solves in any one game. */
  bestInOneGame: number;
  /** Games with at least one credited hand-solve. */
  gamesSolved: number;
  /** Games unlocked (starters included; "unlock everything" does not count). */
  unlocked: number;
  totalGames: number;
  /** Games solved at their hardest preset. */
  hardest: number;
  /** Credited solves without an undo or a hint. */
  pure: number;
  /** Different days the player has opened the collection. */
  days: number;
  /** Tutorials played to the end. */
  tutorials: number;
  /** Achievements earned, and how many exist (both excluding the "earn N" ones). */
  earned: number;
  earnable: number;
  /** Credited solves since the page loaded. */
  session: number;
}

export type MetaEvent =
  | {
      kind: 'end';
      ctx: PuzzleEndContext;
      /**
       * Counts at all: a preset size, outside the tutorial, and — for a win — solved by
       * hand (see `GameAchievement.on`).
       */
      eligible: boolean;
      /** A first-time solve of this exact puzzle: it earned a credit. */
      credited: boolean;
      /** The player lost this same puzzle earlier and came back to win it. */
      lostBefore: boolean;
      /** Local hour of day, 0–23. */
      hour: number;
    }
  | { kind: 'hint' }
  | { kind: 'tutorial' }
  | { kind: 'visit' }
  | { kind: 'progress' };

export interface MetaAchievement {
  id: string;
  tier: AchievementTier;
  hidden?: boolean;
  hue?: PaletteToken;
  art: BadgeArt;
  /** Counting achievements: earned at `goal`, and the page draws a progress bar. */
  goal?: number | ((v: MetaView) => number);
  count?: (v: MetaView) => number;
  /** One-off achievements: earned by the event that makes this true. */
  test?: (v: MetaView, e: MetaEvent) => boolean;
  /** Counts other achievements, so it is checked last and left out of `earnable`. */
  hunter?: boolean;
}

// ---------------------------------------------------------------- drawing helpers

const line = (d: string, col: string, w = 6) =>
  `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const shape = (d: string, fill: string, ink: string, w = 4.5) =>
  `<path d="${d}" fill="${fill}" stroke="${ink}" stroke-width="${w}" stroke-linejoin="round"/>`;
const dot = (x: number, y: number, r: number, fill: string) =>
  `<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}"/>`;

/** A sheet of paper, slightly turned, with a few ruled lines. */
const sheet = (c: C, x = 28, y = 22, w = 44, h = 56) =>
  shape(`M${x} ${y} H${x + w - 10} L${x + w} ${y + 10} V${y + h} H${x} Z`, c.paper, c.ink) +
  line(`M${x + w - 10} ${y} V${y + 10} H${x + w}`, c.ink, 3.5);

/** Tally marks: `n` of them, a gate of five struck through. */
function tally(c: C, n: number, x: number, y: number, h = 26): string {
  let out = '';
  let cx = x;
  for (let g = 0; g < n; g += 5) {
    const k = Math.min(5, n - g);
    const start = cx;
    for (let i = 0; i < Math.min(k, 4); i++) {
      out += line(`M${cx} ${y} L${cx + 1} ${y + h}`, c.ink, 4.5);
      cx += 7;
    }
    if (k === 5) out += line(`M${start - 4} ${y + h - 4} L${cx - 3} ${y + 4}`, c.accent, 4.5);
    cx += 6;
  }
  return out;
}

const check = (c: C, x: number, y: number, s = 1, col = c.ok) =>
  line(`M${x - 12 * s} ${y} L${x - 3 * s} ${y + 9 * s} L${x + 14 * s} ${y - 12 * s}`, col, 7 * s);

const star = (c: C, cx: number, cy: number, r: number, fill: string) => {
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r * 0.45 : r;
    pts.push(`${(cx + rr * Math.cos(a)).toFixed(1)} ${(cy + rr * Math.sin(a)).toFixed(1)}`);
  }
  return shape(`M${pts.join(' L')} Z`, fill, c.ink, 4);
};

/** A small board tile in a series colour — the collection, in miniature. */
const tile = (c: C, x: number, y: number, s: number, fill: string) =>
  shape(`M${x} ${y} h${s} v${s} h${-s} Z`, fill, c.ink, 3.5);

const padlock = (c: C, open: boolean, body: string) =>
  line(open ? 'M36 46 V36 A14 14 0 0 1 64 34' : 'M36 46 V36 A14 14 0 0 1 64 36 V46', c.ink, 7) +
  shape('M28 46 H72 V78 H28 Z', body, c.ink) +
  dot(50, 60, 4.5, c.ink) +
  line('M50 62 V70', c.ink, 4);

const key = (c: C, x: number, y: number, s: number, fill: string) =>
  `<g transform="translate(${x} ${y}) scale(${s})">` +
  shape('M-10 -10 A10 10 0 1 1 -10 10 A10 10 0 1 1 -10 -10 Z', fill, c.ink) +
  dot(-10, 0, 3.5, c.ink) +
  line('M0 0 H30 M22 0 V8 M29 0 V10', c.ink, 5) +
  '</g>';

const mountain = (c: C, flag: string) =>
  shape('M16 78 L42 34 L54 52 L62 42 L84 78 Z', c.faint, c.ink) +
  shape('M42 34 L49 46 L44 44 L38 48 Z', c.paper, c.ink, 3) +
  line('M42 34 V16', c.ink, 4) +
  shape('M42 16 L58 21 L42 27 Z', flag, c.ink, 3);

const calendar = (c: C, marks: number) => {
  let out =
    shape('M22 28 H78 V80 H22 Z', c.paper, c.ink) +
    shape('M22 28 H78 V40 H22 Z', c.red, c.ink) +
    line('M34 22 V32 M66 22 V32', c.ink, 5);
  for (let i = 0; i < 9; i++) {
    const x = 32 + (i % 3) * 18;
    const y = 52 + Math.floor(i / 3) * 10;
    out +=
      i < marks
        ? line(`M${x - 4} ${y} L${x - 1} ${y + 3} L${x + 5} ${y - 4}`, c.ok, 3.5)
        : dot(x, y, 2, c.lowlight);
  }
  return out;
};

