import { gsap } from 'gsap';
import { PALETTE } from '../framework/palette';
import { ziggyEnabled, ziggySVG } from '../framework/ziggy';
import { flightActive } from './flight';
import { reducedMotion } from './motion';

/**
 * Motion helpers built on GSAP. Everything is short and springy so the interface feels
 * hand-made rather than mechanical. Respects the user's reduced-motion preference.
 */

/** Asked at the moment of moving, so the switch in Settings takes effect at once. */
const reduced = (): boolean => reducedMotion();

export { gsap };

/**
 * Whether the player has asked for less motion — for the movement this module does not do
 * itself, such as a smooth scroll, which has its own switch. The Settings switch when the
 * player has set it, the system's `prefers-reduced-motion` until then (`motion.ts`).
 */
export function prefersReducedMotion(): boolean {
  return reduced();
}

/**
 * How long a staggered entrance may take to reach its last element, however many there
 * are. At a flat 45ms a card, the collection's thirty-eight take over a second and a
 * half to finish arriving, most of it below the fold where nobody sees it — and the menu
 * feels slow for the whole of it. Spreading a fixed window instead keeps the cadence of a
 * short list and puts a ceiling on a long one.
 */
const STAGGER_WINDOW = 0.6;
const STAGGER_EACH = 0.045;

/** Stagger a list of elements in from below with a tiny random tilt. */
export function staggerIn(els: Element[], opts: { delay?: number; stagger?: number } = {}): void {
  if (!els.length) return;
  if (reduced()) {
    gsap.set(els, { opacity: 1, y: 0, rotation: 0 });
    return;
  }
  const each = opts.stagger ?? STAGGER_EACH;
  gsap.fromTo(
    els,
    { opacity: 0, y: 26, rotation: () => gsap.utils.random(-3, 3) },
    {
      opacity: 1,
      y: 0,
      rotation: 0,
      duration: 0.55,
      ease: 'back.out(1.6)',
      stagger: { amount: Math.min(els.length * each, STAGGER_WINDOW) },
      delay: opts.delay ?? 0,
      clearProps: 'rotation,transform',
    },
  );
}

/**
 * The lighter cousin of {@link staggerIn}, for cards a search query has just brought back:
 * no tilt and half the travel, because these arrive into a grid that is already there
 * rather than onto an empty page. Narrowing a query is left alone deliberately — a result
 * list that reflows the instant you type feels fast, and it is only things appearing out of
 * nowhere that want explaining.
 */
export function filterIn(els: Element[]): void {
  if (!els.length || reduced()) return;
  gsap.fromTo(
    els,
    { opacity: 0, y: 10, scale: 0.97 },
    {
      opacity: 1,
      y: 0,
      scale: 1,
      duration: 0.3,
      ease: 'back.out(1.5)',
      stagger: { amount: Math.min(els.length * 0.02, 0.22) },
      clearProps: 'transform,opacity',
    },
  );
}

/** Pop an element in (modals, badges, callouts). */
export function popIn(el: Element, from = 0.7): gsap.core.Tween {
  if (reduced()) return gsap.set(el, { opacity: 1, scale: 1 }) as unknown as gsap.core.Tween;
  return gsap.fromTo(
    el,
    { opacity: 0, scale: from, rotation: -3 },
    { opacity: 1, scale: 1, rotation: 0, duration: 0.38, ease: 'back.out(2.2)' },
  );
}

/**
 * Rise a panel into place from just below it, with the faintest tilt straightening out.
 * Used for the end-of-game card, which slides up under the finished board rather than
 * popping over it.
 */
export function riseIn(el: Element): gsap.core.Tween {
  if (reduced()) {
    return gsap.set(el, { opacity: 1, y: 0, scale: 1, rotation: 0 }) as unknown as gsap.core.Tween;
  }
  return gsap.fromTo(
    el,
    { opacity: 0, y: 28, scale: 0.96, rotation: -1.4 },
    {
      opacity: 1,
      y: 0,
      scale: 1,
      rotation: 0,
      duration: 0.42,
      ease: 'back.out(1.7)',
      clearProps: 'transform',
    },
  );
}

/** Pop an element out, then call onDone. */
export function popOut(el: Element, onDone?: () => void): void {
  if (reduced()) {
    onDone?.();
    return;
  }
  gsap.to(el, { opacity: 0, scale: 0.85, duration: 0.18, ease: 'power2.in', onComplete: onDone });
}

/** Quick horizontal shake, for mistakes. */
export function shake(el: Element, strength = 8): void {
  if (reduced()) return;
  gsap.fromTo(
    el,
    { x: -strength },
    { x: 0, duration: 0.5, ease: 'elastic.out(1, 0.25)', clearProps: 'x' },
  );
}

/** Small wiggle rotation, for "nope" feedback on locked items. */
export function wiggle(el: Element): void {
  if (reduced()) return;
  gsap
    .timeline()
    .to(el, { rotation: -4, duration: 0.07 })
    .to(el, { rotation: 4, duration: 0.09 })
    .to(el, { rotation: -2, duration: 0.08 })
    .to(el, { rotation: 0, duration: 0.1, clearProps: 'rotation' });
}

/** Pulse (scale up and back) for celebrating. */
export function pulse(el: Element, amount = 1.04): void {
  if (reduced()) return;
  gsap.fromTo(
    el,
    { scale: 1 },
    {
      scale: amount,
      duration: 0.18,
      yoyo: true,
      repeat: 1,
      ease: 'sine.inOut',
      clearProps: 'scale',
    },
  );
}

/** The status tag's hop when a move changes what it says: up a little, and settle. */
export function statusHop(el: Element): void {
  if (reduced()) return;
  gsap.killTweensOf(el);
  gsap.fromTo(
    el,
    { scale: 1.08, y: -2 },
    { scale: 1, y: 0, duration: 0.32, ease: 'back.out(3)', clearProps: 'transform' },
  );
}

/**
 * A closed, hand-drawn loop of radius about 1 around the origin, as SVG path data: a
 * circle drawn the way a pencil draws one — a little off round, never quite the same
 * twice, and carried a short way past where it started instead of meeting itself exactly.
 * It is scaled up by its group's transform, so the stroke (see `vector-effect` in
 * celebrate.css) keeps its width however big the ring gets.
 */
function sketchLoop(): string {
  const steps = 16;
  const start = gsap.utils.random(0, Math.PI * 2);
  const sweep = Math.PI * 2 + gsap.utils.random(0.25, 0.5);
  const pts: [number, number][] = [];
  for (let i = 0; i <= steps; i++) {
    const a = start + (sweep * i) / steps;
    // The radius drifts outwards over the stroke, so the overlap sits just outside the
    // start rather than on top of it — the way a quick circle actually ends.
    const r = 1 + gsap.utils.random(-0.045, 0.045) + (0.05 * i) / steps;
    pts.push([Math.cos(a) * r, Math.sin(a) * r]);
  }
  // Through the midpoints, with each point as a control: smooth, and still lumpy.
  const f = (n: number) => n.toFixed(3);
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 1; i < pts.length - 1; i++) {
    const mx = (pts[i][0] + pts[i + 1][0]) / 2;
    const my = (pts[i][1] + pts[i + 1][1]) / 2;
    d += `Q${f(pts[i][0])} ${f(pts[i][1])} ${f(mx)} ${f(my)}`;
  }
  const last = pts[pts.length - 1];
  return `${d}L${f(last[0])} ${f(last[1])}`;
}

/**
 * The moment a puzzle comes out: the sheet the board is drawn on lifts off the desk, a
 * pencilled ring or two spreads out from the square the player last touched, and a band
 * of light passes once across the paper.
 *
 * It replaces a 4% `pulse` of the whole board, which said "something happened" and not
 * much else — the same bump a Restart or a hint might have been. The lift is the sheet's
 * own shadow deepening and its tilt going a little further (both CSS variables on the
 * wrap, see play.css), so the board itself never moves: nothing is laid out again, and a
 * click in the last instant still lands on the square under it. The rings start where
 * the solving move was made — `origin`, in the canvas's own pixels, or the middle of the
 * board for a move that came from the keyboard or the Solve button — because that is
 * where the player is looking. All of it is over in about 0.8s, inside the pause the
 * end-of-game panel keeps (ENDGAME_DELAY_MS in gameView), and it draws in a throwaway
 * layer over the canvas, so the finished board underneath is untouched.
 */
export function celebrateBoard(el: HTMLElement, origin: { x: number; y: number } | null): void {
  if (reduced()) return;
  const w = el.clientWidth;
  const h = el.clientHeight;
  if (!w || !h) return;
  // A second solve before the first moment has finished — undo and redo in quick
  // succession — starts over rather than stacking two sets of rings.
  el.querySelector(':scope > .win-fx')?.remove();
  gsap.killTweensOf(el, '--sheet-lift,--sheet-tilt');
  el.style.removeProperty('--sheet-lift');
  el.style.removeProperty('--sheet-tilt');

  const ox = origin ? Math.min(Math.max(origin.x, 0), w) : w / 2;
  const oy = origin ? Math.min(Math.max(origin.y, 0), h) : h / 2;
  const layer = document.createElement('div');
  layer.className = 'win-fx';
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
  svg.setAttribute('width', String(w));
  svg.setAttribute('height', String(h));
  const shine = document.createElement('div');
  shine.className = 'win-fx-shine';
  layer.append(svg, shine);
  el.append(layer);

  const tl = gsap.timeline({
    onComplete: () => {
      layer.remove();
      el.style.removeProperty('--sheet-lift');
      el.style.removeProperty('--sheet-tilt');
    },
  });

  // Back to whatever tilt this layout gives the sheet — none at all on a phone.
  const rest = getComputedStyle(el).getPropertyValue('--sheet-tilt').trim() || '0deg';
  tl.fromTo(
    el,
    { '--sheet-lift': '0px', '--sheet-tilt': rest },
    { '--sheet-lift': '6px', '--sheet-tilt': '-0.8deg', duration: 0.22, ease: 'power2.out' },
    0,
  ).to(
    el,
    { '--sheet-lift': '0px', '--sheet-tilt': rest, duration: 0.5, ease: 'power2.inOut' },
    0.3,
  );

  // Far enough to cross most of the board from wherever it starts, not all of it: a ring
  // that has left every edge before it fades is a ring nobody saw finish.
  const reach = Math.hypot(Math.max(ox, w - ox), Math.max(oy, h - oy)) * 0.85;
  [0, 0.14].forEach((delay, i) => {
    const g = document.createElementNS(NS, 'g');
    const path = document.createElementNS(NS, 'path');
    path.setAttribute('d', sketchLoop());
    path.setAttribute('class', 'win-fx-ring');
    g.append(path);
    g.style.opacity = '0';
    svg.append(g);
    const spin = gsap.utils.random(-20, 20);
    const ring = { r: 4 };
    const draw = () =>
      g.setAttribute('transform', `translate(${ox} ${oy}) rotate(${spin}) scale(${ring.r})`);
    draw();
    tl.set(g, { opacity: i ? 0.55 : 0.9 }, delay)
      .to(
        ring,
        { r: reach * (i ? 0.8 : 1), duration: 0.62, ease: 'power2.out', onUpdate: draw },
        delay,
      )
      .to(g, { opacity: 0, duration: 0.42, ease: 'power1.in' }, delay + 0.22);
  });

  // Tall enough that, tipped over, the band still spans the board from corner to corner.
  const band = Math.max(60, Math.min(w, h) * 0.35);
  const tall = Math.hypot(w, h) * 1.2;
  gsap.set(shine, { width: band, height: tall, top: (h - tall) / 2 });
  tl.fromTo(
    shine,
    { x: -band * 1.6 },
    { x: w + band * 0.6, duration: 0.6, ease: 'power1.inOut' },
    0.1,
  );
}

/**
 * A key going down and springing back, for the on-screen keypad. Short enough that a
 * fast run of taps still shows one bounce each.
 */
export function keyPress(el: Element): void {
  if (reduced()) return;
  gsap
    .timeline()
    .to(el, { scale: 0.88, duration: 0.06, ease: 'power2.out' })
    .to(el, { scale: 1, duration: 0.22, ease: 'elastic.out(1, 0.4)', clearProps: 'scale' });
}

/**
 * Entrance for a freshly generated puzzle board. The degree of tilt straightening out is
 * what makes it read as a sheet of paper being dealt onto the table rather than a panel
 * being scaled up — the same trick the menu cards play, at a quarter of the angle, because
 * this one lands under the player's eyes every time they press New.
 *
 * A board that a card has just been opened into does nothing here: it is the sheet the
 * card turned into on the way (flight.ts), and that landing is its arrival.
 */
export function boardEnter(el: Element): void {
  if (reduced() || flightActive()) return;
  gsap.fromTo(
    el,
    { opacity: 0, scale: 0.94, y: 10, rotation: -1 },
    {
      opacity: 1,
      scale: 1,
      y: 0,
      rotation: 0,
      duration: 0.42,
      ease: 'back.out(1.8)',
      clearProps: 'transform,opacity',
    },
  );
}

/**
 * The same board coming back to its starting position, for Restart. Deliberately not
 * {@link boardEnter}: nothing has been dealt, so there is no tilt and no travel — the grid
 * simply comes back up out of nothing, the way a rubbed-out pencil drawing would.
 */
export function boardReset(el: Element): void {
  if (reduced()) return;
  gsap.fromTo(
    el,
    { opacity: 0.25, scale: 0.985 },
    { opacity: 1, scale: 1, duration: 0.26, ease: 'power2.out', clearProps: 'transform,opacity' },
  );
}

/**
 * Fade a just-painted preview up in its card.
 *
 * The menu paints one thumbnail per animation frame, so a cold grid fills in as a run of
 * pictures snapping into empty frames, a couple of dozen of them in a row. The same run
 * with each picture fading up reads as the page drawing itself — which is what it is
 * doing. Deliberately quick and without travel: the card is already where it belongs, and
 * only the picture inside it is new.
 */
export function revealThumb(canvas: HTMLCanvasElement): void {
  if (reduced()) return;
  gsap.fromTo(
    canvas,
    { opacity: 0, scale: 0.92 },
    {
      opacity: 1,
      scale: 1,
      duration: 0.34,
      ease: 'back.out(1.4)',
      // Both, so a locked card's own `filter: grayscale(1) opacity(.35)` is left to do its
      // job on a canvas carrying no inline styles of ours at all.
      clearProps: 'transform,opacity',
    },
  );
}

/** Animate a numeric counter's text content. */
export function countTo(el: HTMLElement, value: number, duration = 0.6): void {
  const from = parseInt(el.textContent || '0', 10) || 0;
  if (reduced() || from === value) {
    el.textContent = String(value);
    return;
  }
  const obj = { v: from };
  gsap.to(obj, {
    v: value,
    duration,
    ease: 'power2.out',
    onUpdate: () => (el.textContent = String(Math.round(obj.v))),
  });
}

const CONFETTI_COLOURS = [
  PALETTE.accent,
  PALETTE.blue,
  PALETTE.green,
  PALETTE.yellow,
  PALETTE.purple,
  PALETTE.pink,
];

/**
 * How many of the confetti pieces are Ziggy himself, tumbling end over end with the rest.
 *
 * Three, spread through the burst rather than clumped: few enough that spotting one is a
 * small surprise every time instead of a pattern, and they are the only pieces drawn as a
 * character, so any more would turn a shower of paper into a crowd.
 */
const CONFETTI_ZIGGIES = 3;

/**
 * Hand-drawn confetti: little sketched squares, circles and triangles burst from the centre
 * of `origin` and drift down. Elements are removed when done.
 */
export function confetti(origin: Element, count = 46): void {
  if (reduced()) return;
  const r = origin.getBoundingClientRect();
  const cx = r.left + r.width / 2;
  const cy = r.top + r.height / 2;
  const layer = document.createElement('div');
  layer.className = 'confetti-layer';
  document.body.append(layer);
  const pieces: HTMLElement[] = [];
  const ziggyEvery = ziggyEnabled() ? Math.floor(count / CONFETTI_ZIGGIES) : 0;
  for (let i = 0; i < count; i++) {
    const p = document.createElement('div');
    const shape = i % 3;
    const colour = CONFETTI_COLOURS[i % CONFETTI_COLOURS.length];
    const mascot = ziggyEvery > 0 && i % ziggyEvery === 1;
    const size = mascot ? gsap.utils.random(18, 26) : gsap.utils.random(7, 13);
    p.className = 'confetti';
    p.style.width = `${size}px`;
    p.style.height = `${size}px`;
    p.style.left = `${cx}px`;
    p.style.top = `${cy}px`;
    if (mascot) {
      p.classList.add('confetti-ziggy');
      p.innerHTML = ziggySVG({ className: 'ziggy', tilt: gsap.utils.random(-14, 14) });
    } else if (shape === 0) {
      p.style.background = colour;
      p.style.borderRadius = '30% 70% 60% 40%';
    } else if (shape === 1) {
      p.style.border = `2.5px solid ${colour}`;
      p.style.borderRadius = '50%';
    } else {
      p.style.width = '0';
      p.style.height = '0';
      p.style.borderLeft = `${size / 2}px solid transparent`;
      p.style.borderRight = `${size / 2}px solid transparent`;
      p.style.borderBottom = `${size}px solid ${colour}`;
    }
    layer.append(p);
    pieces.push(p);
  }
  const tl = gsap.timeline({ onComplete: () => layer.remove() });
  pieces.forEach((p) => {
    const angle = gsap.utils.random(-Math.PI, 0) + gsap.utils.random(-0.6, 0.6);
    const speed = gsap.utils.random(180, 420);
    const dx = Math.cos(angle) * speed;
    const dy = Math.sin(angle) * speed;
    tl.to(
      p,
      {
        x: dx,
        y: dy,
        rotation: gsap.utils.random(-260, 260),
        duration: 0.7,
        ease: 'power2.out',
      },
      0,
    ).to(
      p,
      {
        y: `+=${gsap.utils.random(260, 420)}`,
        x: `+=${gsap.utils.random(-60, 60)}`,
        rotation: `+=${gsap.utils.random(-140, 140)}`,
        opacity: 0,
        duration: gsap.utils.random(0.9, 1.4),
        ease: 'power1.in',
      },
      0.55,
    );
  });
}

/** Float a little label up from an element (e.g. "+1 credit"). */
export function floatLabel(anchor: Element | DOMRect, text: string): void {
  const r = anchor instanceof Element ? anchor.getBoundingClientRect() : anchor;
  const el = document.createElement('div');
  el.className = 'float-label';
  el.textContent = text;
  el.style.left = `${r.left + r.width / 2}px`;
  el.style.top = `${r.top}px`;
  document.body.append(el);
  // Centred over a card in a phone's side column, a long name ran off the screen's edge.
  const half = el.offsetWidth / 2;
  const vw = document.documentElement.clientWidth;
  const cx = r.left + r.width / 2;
  el.style.left = `${half * 2 + 16 > vw ? vw / 2 : Math.min(Math.max(cx, half + 8), vw - half - 8)}px`;
  // Likewise the top: a card whose button was tapped with its top scrolled away (a phone on
  // its side, or a keyboard focus that only brought the button into view) sent it upward
  // from above the window. It starts where it can be seen, with room left to rise.
  const vh = document.documentElement.clientHeight;
  el.style.top = `${Math.min(Math.max(r.top, 48), vh - el.offsetHeight - 8)}px`;
  if (reduced()) {
    setTimeout(() => el.remove(), 1200);
    return;
  }
  gsap
    .timeline({ onComplete: () => el.remove() })
    .fromTo(
      el,
      { opacity: 0, y: 10, scale: 0.7 },
      { opacity: 1, y: -10, scale: 1, duration: 0.35, ease: 'back.out(2)' },
    )
    .to(el, { y: -60, opacity: 0, duration: 0.9, ease: 'power1.in' }, 0.7);
}

/** Unlock animation for a menu card: padlock shakes, then the card brightens. */
export function unlockCard(card: HTMLElement, lock: HTMLElement | null, onDone?: () => void): void {
  if (reduced()) {
    onDone?.();
    return;
  }
  const tl = gsap.timeline({ onComplete: onDone });
  if (lock) {
    tl.to(lock, { rotation: -12, duration: 0.08 })
      .to(lock, { rotation: 12, duration: 0.1 })
      .to(lock, { rotation: -8, duration: 0.08 })
      .to(lock, { rotation: 0, duration: 0.08 })
      .to(lock, { scale: 1.5, opacity: 0, duration: 0.3, ease: 'back.in(2)' });
  }
  tl.fromTo(card, { scale: 0.97 }, { scale: 1.03, duration: 0.2, ease: 'power2.out' }).to(card, {
    scale: 1,
    duration: 0.35,
    ease: 'elastic.out(1, 0.4)',
    clearProps: 'scale',
  });
}

/** How far a card that is leaving for an off-screen shelf travels before it fades. */
const DEPART_DISTANCE = 110;

/**
 * Send a just-unlocked card to the shelf it has joined — the FLIP trick, on the real
 * element rather than a copy of it: the grid has already been rebuilt with the card in its
 * new home, so it is put back where the player last saw it and allowed to travel.
 *
 * This is what a spent credit buys, and until now the card simply stopped being where the
 * player was looking: the locked shelf redrew without it, and it turned up a screen or two
 * higher among the puzzles they already had, with nothing in between to say so.
 *
 * Which of the two journeys it makes depends on whether the destination is on screen. It
 * usually is not — reaching the locked shelf means scrolling past everything already
 * unlocked — and carrying a card a thousand pixels up the page reads as a glitch rather
 * than a move, so in that case it only sets off in the right direction and is gone.
 */
export function flyToShelf(card: HTMLElement, from: DOMRect): void {
  if (reduced()) return;
  const to = card.getBoundingClientRect();
  const dx = from.left - to.left;
  const dy = from.top - to.top;
  if (!dx && !dy) return;
  const scale = to.width ? from.width / to.width : 1;
  gsap.set(card, { position: 'relative', zIndex: 3 });
  if (to.bottom > 0 && to.top < window.innerHeight) {
    gsap.fromTo(
      card,
      { x: dx, y: dy, scale },
      {
        x: 0,
        y: 0,
        scale: 1,
        duration: 0.62,
        ease: 'power3.inOut',
        clearProps: 'transform,position,zIndex',
      },
    );
    return;
  }
  gsap.fromTo(
    card,
    { x: dx, y: dy, scale, opacity: 1 },
    {
      x: dx * 0.82,
      y: dy - Math.sign(dy) * Math.min(Math.abs(dy), DEPART_DISTANCE),
      scale: scale * 0.94,
      opacity: 0,
      duration: 0.42,
      ease: 'power2.in',
      clearProps: 'transform,opacity,position,zIndex',
    },
  );
}

/** Slide a drawer open/closed. */
export function slideDrawer(el: Element, open: boolean): void {
  gsap.to(el, {
    xPercent: open ? 0 : drawerHiddenX(),
    duration: reduced() ? 0 : 0.32,
    ease: open ? 'power3.out' : 'power2.in',
  });
}

/**
 * Where the closed help drawer parks. It is docked to the inline end of the page, so in a
 * right-to-left language it slides out to the left instead of the right.
 */
export function drawerHiddenX(): number {
  const rtl =
    typeof document !== 'undefined' && document.documentElement.getAttribute('dir') === 'rtl';
  return rtl ? -105 : 105;
}

/**
 * Which way the router is travelling. `open` is a card being opened into its puzzle,
 * `close` the way back out to the collection, and `none` a page replacing itself where it
 * stands — a language switch — which is not a journey and gets the plain fade page swaps
 * have always had.
 */
export type PageTurn = 'open' | 'close' | 'none';

/**
 * How far the collection is pushed past the viewer as one of its cards opens. The whole
 * page grows about the card that was picked, so at this scale that card is only about a
 * quarter bigger by the time it goes while the cards at the edges of the screen have left
 * the screen altogether — which is what makes it read as going *into* the card rather
 * than as a page fading out.
 */
const DIVE_SCALE = 1.28;

/**
 * Where a page zoom pivots, in the page's own pixels: the middle of the card being
 * opened, or the middle of the screen when there is no card to pivot on — a puzzle reached
 * by its own URL, or one the search field has filtered away. Never the middle of the
 * *element*, which is where a transform origin would otherwise sit: the collection is
 * several screens tall, and its middle is nowhere the player is looking.
 */
function zoomOrigin(page: Element, focus: Element | null): string {
  const p = page.getBoundingClientRect();
  const f = focus?.getBoundingClientRect();
  const usable = !!f && f.width > 0 && f.bottom > 0 && f.top < window.innerHeight;
  const cx = usable ? f!.left + f!.width / 2 : window.innerWidth / 2;
  const cy = usable ? f!.top + f!.height / 2 : window.innerHeight / 2;
  return `${cx - p.left}px ${cy - p.top}px`;
}

/**
 * Take the page being left off the screen, then call `onDone` — which is where the router
 * swaps the two over. The fallback journey: opening a card on screen, and going back to it,
 * is a flight instead (flight.ts); this is for the rest, such as a card that is not there.
 *
 * Deliberately one after the other rather than a crossfade: mounting a game generates a
 * puzzle, and a generator can hold the main thread for a frame or two. A stall while two
 * pages slide over each other is a stutter; the same stall on an empty screen is nothing
 * at all. It is also why both halves are short — the pause between them is real.
 *
 * Returns the tween, so a second navigation arriving mid-flight can kill it and land
 * straight away instead of queueing one journey behind another.
 */
export function pageOut(
  el: Element,
  turn: PageTurn,
  focus: Element | null,
  onDone: () => void,
): gsap.core.Animation | null {
  if (reduced() || turn === 'none') {
    onDone();
    return null;
  }
  const opening = turn === 'open';
  const duration = opening ? 0.24 : 0.2;
  return gsap
    .timeline({ onComplete: onDone })
    .to(
      el,
      {
        scale: opening ? DIVE_SCALE : 0.93,
        duration,
        ease: 'power1.in',
        transformOrigin: zoomOrigin(el, focus),
      },
      0,
    )
    .to(
      el,
      // Held back, and then quick. Sharing the scale's curve, the page is more than half
      // gone before it has travelled anywhere worth seeing, and the whole thing reads as
      // a dissolve with a wobble in it rather than as a journey.
      { opacity: 0, duration: duration * 0.62, ease: 'power2.in' },
      duration * 0.38,
    );
}

/**
 * Bring the page that has just been mounted in, when no flight brought it (flight.ts).
 * `turn` describes the page arriving, not the one that left: the play page is exactly one
 * screen tall, so it can come up out of the zoom by growing about its own middle. The collection cannot — it is several screens
 * of cards, and scaling something that tall about a middle far below the fold moves
 * everything the player can see — so the way back is a lift instead of a zoom.
 */
export function pageIn(el: Element, turn: PageTurn = 'none'): void {
  if (reduced()) return;
  const from = turn === 'open' ? { opacity: 0, scale: 0.95 } : { opacity: 0, y: 8 };
  gsap.fromTo(el, from, {
    opacity: 1,
    scale: 1,
    y: 0,
    duration: 0.3,
    ease: 'power2.out',
    clearProps: 'transform',
  });
}

/**
 * The on-screen keypad arriving. It is a row of the play page, so showing it takes height
 * away from the board and the board refits — which used to happen in a single frame, with
 * a rank of buttons appearing out of nothing underneath a board that had just jumped.
 * The refit is still one frame (the board is a canvas fitted to whatever is left over),
 * but the keys come up into the room it made, which is what the change actually is.
 */
export function keypadIn(el: HTMLElement): void {
  if (reduced()) return;
  gsap.killTweensOf(el);
  const keys = [...el.children];
  gsap.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.18, ease: 'power2.out' });
  if (!keys.length) return;
  gsap.fromTo(
    keys,
    { y: 16, opacity: 0, scale: 0.9 },
    {
      y: 0,
      opacity: 1,
      scale: 1,
      duration: 0.3,
      ease: 'back.out(1.8)',
      stagger: { amount: Math.min(keys.length * 0.02, 0.14) },
      clearProps: 'transform,opacity',
    },
  );
}

/** The same row leaving, with `onDone` called once it is off the page and can be hidden. */
export function keypadOut(el: HTMLElement, onDone: () => void): void {
  if (reduced()) {
    onDone();
    return;
  }
  gsap.killTweensOf(el);
  gsap.to(el, {
    opacity: 0,
    y: 12,
    duration: 0.14,
    ease: 'power2.in',
    onComplete: () => {
      gsap.set(el, { clearProps: 'transform,opacity' });
      onDone();
    },
  });
}

/**
 * The board settling into a new zoom level.
 *
 * Zooming redraws the canvas at a new tile size, which is one frame and no motion at all —
 * fine under a pinch, where the fingers supply the movement, but the +/− buttons made the
 * board jump. This is the FLIP trick on the canvas itself: it is put back exactly where
 * and how big it was, and allowed to travel to where it now is. Nothing is laid out twice
 * and the board is redrawn once, at its new size; the journey is a transform on top of it.
 *
 * The anchor needs no special handling: the caller has already adjusted the scroll so the
 * focal point is where it belongs, which is baked into the rect this measures.
 */
export function zoomTo(canvas: HTMLElement, from: DOMRect): void {
  if (reduced()) return;
  const to = canvas.getBoundingClientRect();
  if (!to.width || !from.width) return;
  const scale = from.width / to.width;
  if (Math.abs(scale - 1) < 0.005) return;
  gsap.killTweensOf(canvas);
  gsap.fromTo(
    canvas,
    { scale, x: from.left - to.left, y: from.top - to.top, transformOrigin: '0 0' },
    { scale: 1, x: 0, y: 0, duration: 0.24, ease: 'power3.out', clearProps: 'transform' },
  );
}

// ------------------------------------------------------------------- the desk

/**
 * How much closer the camera is to the desk while a puzzle is open. The collection is the
 * whole box, seen from where you sit; a puzzle is one sheet out of it, and you lean in.
 */
const DESK_NEAR = 1.14;

let desk: HTMLElement | null = null;
let deskNear = false;

/**
 * The desk every screen lies on: one fixed layer behind the app, so the collection and the
 * board share a surface and a page turn is the camera moving over it, not a page swap.
 * Built once, at boot, in front of `#app` in the document and behind it on screen.
 */
export function mountDesk(): HTMLElement {
  if (desk) return desk;
  desk = document.createElement('div');
  desk.className = 'desk';
  desk.setAttribute('aria-hidden', 'true');
  const vignette = document.createElement('div');
  vignette.className = 'desk-vignette';
  vignette.setAttribute('aria-hidden', 'true');
  document.body.prepend(desk, vignette);
  return desk;
}

/**
 * Move the camera: nearer the desk for a puzzle, back for the collection. `origin` is the
 * point to lean in towards — the card that was picked — in viewport pixels; leaning out
 * again pulls back about the same point, so the camera retraces its path. `animate` is
 * false for an arrival that is not a journey (a page load, a language switch), which
 * simply puts the camera where it goes.
 *
 * A Web Animation rather than a tween, for the same reason as the flight it goes with
 * (flight.ts): it runs on the compositor, so it keeps moving while the puzzle is being
 * generated underneath it.
 */
export function deskCamera(
  near: boolean,
  { origin, animate = true }: { origin?: { x: number; y: number }; animate?: boolean } = {},
): void {
  const el = desk;
  if (!el) return;
  const changed = near !== deskNear;
  deskNear = near;
  const scale = `scale(${near ? DESK_NEAR : 1})`;
  if (!changed && animate) return;
  // Where the camera is right now, mid-move or not, before that move is dropped.
  const now = getComputedStyle(el).transform;
  el.getAnimations().forEach((a) => a.cancel());
  if (near) {
    // In the desk's own pixels: it reaches 6vmax past every edge of the screen (desk.css).
    const edge = Math.max(window.innerWidth, window.innerHeight) * 0.06;
    const o = origin ?? { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    el.style.transformOrigin = `${o.x + edge}px ${o.y + edge}px`;
  }
  el.style.transform = scale;
  if (reduced() || !animate) return;
  // Leaning in is about as long as the card's flight, so the desk is still settling as
  // the sheet lands; leaning out is quicker, like sitting back.
  el.animate([{ transform: now && now !== 'none' ? now : 'scale(1)' }, { transform: scale }], {
    duration: near ? 700 : 520,
    easing: near ? 'cubic-bezier(.45,0,.25,1)' : 'cubic-bezier(.2,.7,.3,1)',
  });
}
