import type { Game } from '../framework/types';
import type { Midend, SaveData } from '../framework/midend';
import type { PointerHint, TutorialCtx, TutorialRect, TutorialStep } from '../framework/tutorial';
import { demonstrate, visibleSteps } from '../framework/tutorial';
import { gameName, t, tutorialStepText } from '../i18n';
import { PALETTE } from '../framework/palette';
import { gsap, popIn, popOut, shake } from './anim';
import { isShortScreen, isSideRail, isSmallScreen, isTouch } from './device';
import { mountMascot, type Mascot } from './mascot';
import { renderMarkdown } from './markdown';
import { fitAll } from './fitText';

export interface TutorialHooks {
  /** Re-fit the canvas after the tutorial loads its own puzzle. */
  layout: () => void;
  /** Called once when the tutorial ends; `completed` is false when skipped. */
  onEnd: (completed: boolean) => void;
  /** Called as each step comes up (the toolbar follows what the step is about). */
  onStep?: () => void;
}

interface PageRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

const PAD = 7;
const RADIUS = 10;

/**
 * How long a move the step did not ask for stays on the board before it is taken back:
 * long enough to see what it did (a mine going off, a tile sliding the wrong way), short
 * enough that the lesson is never left describing a board that is not there.
 */
const REWIND_DELAY = 700;

/** Where a step started: the board it describes, to come back to after a stray move. */
interface Anchor {
  pos: number;
  state: unknown;
  save: SaveData;
}

/**
 * Ziggy's column beside a floating callout: his width plus the gap the speech tail spans.
 * Kept in step with `.tut-ziggy` in `styles.css`.
 */
const NARRATOR_W = 78;
/**
 * The smallest viewport Ziggy narrates on. Below it every pixel beside the spotlight is
 * worth more as board than as mascot, so the callout goes back to speaking for itself.
 */
const NARRATOR_MIN_W = 900;
const NARRATOR_MIN_H = 600;

/**
 * Runs a game's tutorial: dims the page except for a spotlight on the relevant part of the
 * board, shows a sketched callout with the instruction, animates a pointer hint, and
 * advances either on "Next" or automatically when the player does what was asked.
 */
export class TutorialRunner {
  private index = -1;
  private overlay: HTMLElement;
  private svg: SVGSVGElement;
  private maskGroup: SVGGElement;
  private dim: SVGRectElement;
  private callout: HTMLElement;
  private stepLabel: HTMLElement;
  private text: HTMLElement;
  private nextBtn: HTMLButtonElement;
  private skipBtn: HTMLButtonElement;
  private pointerEl: HTMLElement;
  private pointerTween: gsap.core.Tween | gsap.core.Timeline | null = null;
  /** Ziggy, delivering the instructions, or null with the mascot switched off. */
  private narrator: Mascot | null;
  /** Whether he is on screen for the current layout (see {@link updateDock}). */
  private narrating = false;
  /** Which side of the highlight the current step's callout was put on, kept against ties. */
  private placedSpot: string | null = null;
  private advancing = false;
  private ended = false;
  /** The board as the current step found it; see {@link guard}. */
  private anchor: Anchor | null = null;
  /** A stray move waiting to be taken back. */
  private rewindTimer = 0;
  /** Set while the runner itself is moving the board, so it does not judge its own moves. */
  private steering = false;
  /** The line under a step's text that says a stray move was put back. */
  private nudge: HTMLElement;
  private cutouts: SVGRectElement[] = [];
  private touch = isTouch();
  private docked = false;
  private dockHeight = -1;
  private sideWidth = -1;
  private onResize = () => this.reposition();
  private onKey = (e: KeyboardEvent) => {
    // With the help drawer open over it, Escape belongs to the drawer: closing help must
    // not throw the tutorial away too.
    // So does a dialog opened over it (Share, a custom size): Escape cancels the dialog.
    if (
      e.key === 'Escape' &&
      !document.querySelector('.help-drawer.open') &&
      !document.querySelector('.dimmer')
    ) {
      e.preventDefault();
      e.stopPropagation();
      this.end(false);
    }
  };

  constructor(
    private game: Game,
    private midend: Midend,
    private canvas: HTMLCanvasElement,
    private hooks: TutorialHooks,
  ) {
    this.overlay = document.createElement('div');
    this.overlay.className = 'tut-overlay';
    this.overlay.setAttribute('role', 'dialog');
    this.overlay.setAttribute('aria-label', t('ui.tutorial.label', { name: gameName(game) }));

    const ns = 'http://www.w3.org/2000/svg';
    this.svg = document.createElementNS(ns, 'svg');
    this.svg.setAttribute('class', 'tut-mask');
    const defs = document.createElementNS(ns, 'defs');
    const mask = document.createElementNS(ns, 'mask');
    const maskId = `tut-mask-${Math.random().toString(36).slice(2, 8)}`;
    mask.setAttribute('id', maskId);
    mask.setAttribute('maskUnits', 'userSpaceOnUse');
    const full = document.createElementNS(ns, 'rect');
    full.setAttribute('x', '0');
    full.setAttribute('y', '0');
    full.setAttribute('width', '100%');
    full.setAttribute('height', '100%');
    full.setAttribute('fill', 'white');
    this.maskGroup = document.createElementNS(ns, 'g');
    mask.append(full, this.maskGroup);
    defs.append(mask);
    this.dim = document.createElementNS(ns, 'rect');
    this.dim.setAttribute('x', '0');
    this.dim.setAttribute('y', '0');
    this.dim.setAttribute('width', '100%');
    this.dim.setAttribute('height', '100%');
    this.dim.setAttribute('class', 'tut-dim');
    this.dim.setAttribute('mask', `url(#${maskId})`);
    this.svg.append(defs, this.dim);

    this.pointerEl = document.createElement('div');
    this.pointerEl.className = 'tut-pointer';
    // A mouse arrow says "click" to someone holding a phone; a finger is shown the round
    // print of a fingertip instead, centred on the spot (see `.tut-pointer.touch`).
    this.pointerEl.innerHTML = this.touch
      ? `<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="${PALETTE.paper}" fill-opacity="0.55" stroke="${PALETTE.ink}" stroke-width="2"/><circle cx="12" cy="12" r="3.5" fill="${PALETTE.ink}"/></svg><span class="tut-pointer-tag"></span>`
      : `<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><path d="M5 3 L19 12 L12 13.5 L9 20 Z" fill="${PALETTE.paper}" stroke="${PALETTE.ink}" stroke-width="2" stroke-linejoin="round"/></svg><span class="tut-pointer-tag"></span>`;
    this.pointerEl.classList.toggle('touch', this.touch);
    this.pointerEl.hidden = true;

    this.callout = document.createElement('div');
    this.callout.className = 'tut-callout sketch';
    this.stepLabel = document.createElement('div');
    this.stepLabel.className = 'tut-step';
    this.text = document.createElement('div');
    this.text.className = 'tut-text';
    // Each step's words replace the last in place; a screen reader hears them arrive.
    this.text.setAttribute('aria-live', 'polite');
    this.nudge = document.createElement('div');
    this.nudge.className = 'tut-nudge';
    this.nudge.setAttribute('role', 'status');
    this.nudge.hidden = true;
    const actions = document.createElement('div');
    actions.className = 'tut-actions';
    this.skipBtn = document.createElement('button');
    this.skipBtn.type = 'button';
    this.skipBtn.className = 'btn tut-skip';
    this.skipBtn.textContent = t('ui.tutorial.skipTutorial');
    this.nextBtn = document.createElement('button');
    this.nextBtn.type = 'button';
    this.nextBtn.className = 'btn primary tut-next';
    this.nextBtn.textContent = t('ui.tutorial.next');
    actions.append(this.skipBtn, this.nextBtn);
    this.callout.append(this.stepLabel, this.text, this.nudge, actions);
    // Ziggy stands just outside the callout's start edge and the callout becomes his speech
    // bubble. He is a child of the callout so he pops in, moves and leaves with it, and CSS
    // keeps him hidden until `narrated` says the screen has room for him.
    const zig = document.createElement('span');
    zig.className = 'tut-ziggy';
    this.narrator = mountMascot(zig, { tilt: -8 });
    if (this.narrator) this.callout.append(zig);

    this.overlay.append(this.svg, this.pointerEl, this.callout);
    this.skipBtn.addEventListener('click', () => this.end(false));
    this.nextBtn.addEventListener('click', () => this.next());
  }

  /** The steps this player sees; `desktopOnly` ones are gone on touch devices. */
  get steps(): TutorialStep[] {
    return visibleSteps(this.game.tutorial?.steps ?? [], this.touch);
  }

  get active(): boolean {
    return !this.ended && this.index >= 0;
  }

  /** Whether the step on screen points at the toolbar command `cmd` (`solve`, `hint`). */
  spotlights(cmd: string): boolean {
    const target = this.active ? this.steps[this.index]?.target : undefined;
    return !!target && target.includes(`data-cmd="${cmd}"`);
  }

  start(): void {
    if (!this.steps.length) {
      this.end(true);
      return;
    }
    document.body.append(this.overlay);
    window.addEventListener('resize', this.onResize);
    document.addEventListener('keydown', this.onKey, true);
    gsap.fromTo(this.dim, { opacity: 0 }, { opacity: 1, duration: 0.3 });
    this.goTo(0);
  }

  private ctx(): TutorialCtx {
    return {
      state: this.midend.state,
      ui: this.midend.ui,
      tileSize: this.midend.tileSize,
      midend: this.midend,
      touch: this.touch,
    };
  }

  private goTo(i: number): void {
    this.flushRewind();
    this.index = i;
    this.advancing = false;
    this.placedSpot = null;
    const step = this.steps[i];
    if (step.gameId) {
      const err = this.midend.loadGameId(step.gameId);
      if (err) console.warn(`tutorial step ${i}: bad game id (${err})`);
      this.steer(() => this.midend.newGame());
      this.hooks.layout();
    }
    this.anchor = this.midend.hasGame
      ? { pos: this.midend.moveCount(), state: this.midend.state, save: this.midend.serialize() }
      : null;
    this.nudge.hidden = true;
    this.hooks.onStep?.();
    this.stepLabel.textContent = t('ui.tutorial.step', { n: i + 1, total: this.steps.length });
    this.text.innerHTML = renderMarkdown(this.stepMarkdown(step), { touch: this.touch });
    const last = i === this.steps.length - 1;
    this.nextBtn.textContent = last
      ? t('ui.tutorial.done')
      : step.waitFor
        ? t('ui.tutorial.skipStep')
        : t('ui.tutorial.next');
    this.nextBtn.classList.toggle('primary', !step.waitFor || last);
    this.skipBtn.hidden = last;
    this.updateDock();
    if (this.docked) {
      gsap.fromTo(
        this.callout,
        { y: 30, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.3, ease: 'power3.out', clearProps: 'transform' },
      );
    } else {
      popIn(this.callout, 0.85);
    }
    this.reposition();
    // Re-measure once fonts and entrance animations have settled.
    window.setTimeout(() => this.reposition(), 450);
    // The step may already be satisfied (e.g. after a reload).
    this.checkWait();
  }

  /**
   * The step's instruction in the active language. The key is derived from the step's
   * position in the *authored* list, so it does not move when `desktopOnly` steps are
   * filtered out on a phone.
   */
  private stepMarkdown(step: TutorialStep): string {
    const authored = this.game.tutorial?.steps ?? [];
    return tutorialStepText(this.game.id, authored.indexOf(step), step, this.touch);
  }

  /** Call after every state change or layout change. */
  update(): void {
    if (!this.active) return;
    this.reposition();
    // A stray move is about to be taken back; whatever comes on top of it goes with it.
    if (this.steering || this.rewindTimer) return;
    if (!this.checkWait()) this.guard();
  }

  private satisfied(step: TutorialStep | undefined): boolean {
    if (!step?.waitFor) return false;
    try {
      return step.waitFor(this.ctx());
    } catch (e) {
      console.warn('tutorial waitFor threw', e);
      return false;
    }
  }

  /** Whether the step is done (or already moving on); starts the move on when it is. */
  private checkWait(): boolean {
    if (this.advancing) return true;
    const step = this.steps[this.index];
    if (!this.satisfied(step)) return false;
    this.nudge.hidden = true;
    this.advancing = true;
    this.hidePointer();
    if (this.narrating) this.narrator?.cheer();
    // Acknowledge success without touching the callout's text or size: inserting a
    // congratulatory line changed its height mid-pulse, which read as a layout jump
    // rather than a deliberate animation. A green border pulse plus a settled scale-pulse
    // is enough feedback before the next step's content replaces this one, with nothing
    // reflowing in between.
    gsap.to(this.callout, {
      borderColor: PALETTE.ok,
      duration: 0.18,
      yoyo: true,
      repeat: 1,
      ease: 'power1.out',
      clearProps: 'borderColor',
    });
    gsap.fromTo(
      this.callout,
      { scale: 1 },
      { scale: 1.03, duration: 0.15, yoyo: true, repeat: 1, clearProps: 'scale' },
    );
    // Only from this step: "Skip step" pressed during the pause has already moved on, and
    // a second advance from here skipped the step after it unseen (or ended the tutorial).
    const from = this.index;
    window.setTimeout(() => {
      if (!this.ended && this.index === from) this.advance();
    }, 550);
    return true;
  }

  /**
   * Keep the board on the lesson's script. Every step after this one is written for the
   * board this one leads to, so a move it did not ask for — the wrong square, a mine trodden
   * on, an Undo back past the last step's work — would leave them pointing at things that
   * are not there. Such a move is shown for a moment and then taken back, with a line in the
   * callout saying so. Two exceptions move the lesson on instead: on a step that only asks
   * to be read, the very move the next step asks for; and, anywhere, finishing the puzzle a
   * way of the player's own. The last step, and any step marked `free`, are the player's.
   */
  private guard(): void {
    const a = this.anchor;
    if (!a || this.advancing || this.rewindTimer || !this.midend.hasGame) return;
    if (this.midend.state === a.state) return;
    const step = this.steps[this.index];
    const last = this.steps.length - 1;
    if (!step || step.free || this.index === last) return;
    // Ahead of the lesson, on a step that was only to be read: the next step's own move.
    const next = this.steps[this.index + 1];
    if (!step.waitFor && next && !next.gameId && this.satisfied(next)) {
      this.goTo(this.index + 1);
      return;
    }
    // Solved some other way: on to the last step that waits for the puzzle to be finished,
    // which sees it is and moves on to the wrap-up.
    if (this.midend.status() === 1) {
      for (let j = last; j > this.index; j--) {
        if (this.steps[j].gameId) break;
        if (this.satisfied(this.steps[j])) {
          this.goTo(j);
          return;
        }
      }
    }
    this.nudge.innerHTML = renderMarkdown(
      t(step.waitFor ? 'ui.tutorial.offScript' : 'ui.tutorial.offScriptRead'),
      { touch: this.touch },
    );
    this.nudge.hidden = false;
    this.reposition();
    shake(this.callout, 6);
    if (this.narrating) this.narrator?.nope();
    this.rewindTimer = window.setTimeout(() => {
      this.rewindTimer = 0;
      this.rewind();
    }, REWIND_DELAY);
  }

  /** Put the board back where the current step found it. */
  private rewind(): void {
    const a = this.anchor;
    if (this.ended || !a || this.midend.state === a.state) return;
    this.steer(() => {
      this.midend.travelTo(a.pos);
      // The history the step started on was cut away (an Undo, then a new move): put the
      // whole saved board back instead.
      if (this.midend.state !== a.state) {
        this.midend.deserialize(a.save);
        a.state = this.midend.state;
      }
    });
    this.reposition();
  }

  /** Take back a stray move now rather than when its timer runs out. */
  private flushRewind(rewind = true): void {
    if (!this.rewindTimer) return;
    window.clearTimeout(this.rewindTimer);
    this.rewindTimer = 0;
    if (rewind) this.rewind();
  }

  /** Move the board without the guard taking it for the player's doing. */
  private steer(fn: () => void): void {
    const was = this.steering;
    this.steering = true;
    try {
      fn();
    } finally {
      this.steering = was;
    }
  }

  /**
   * Next, or "Skip step" on a step that waits for a move. Skipping a move would leave every
   * later step describing a board without it, so the runner makes the move itself where
   * the step's pointer hint says how (a click or a drag), and only when that does not do
   * the job does it put the board back and move on regardless.
   */
  private next(): void {
    if (this.ended || this.advancing) return;
    const step = this.steps[this.index];
    if (step?.waitFor && this.index < this.steps.length - 1) {
      this.flushRewind();
      if (this.demonstrate(step)) {
        this.advancing = true;
        this.nudge.hidden = true;
        this.hidePointer();
        const from = this.index;
        window.setTimeout(() => {
          if (!this.ended && this.index === from) this.advance();
        }, 450);
        return;
      }
      this.rewind();
    }
    this.advance();
  }

  /** Make the step's move for the player. True when that satisfied the step. */
  private demonstrate(step: TutorialStep): boolean {
    let ok = false;
    this.steer(() => {
      try {
        ok = demonstrate(this.midend, step, () => this.ctx());
      } catch (e) {
        console.warn('tutorial demonstration threw', e);
      }
    });
    return ok;
  }

  private advance(): void {
    if (this.ended) return;
    if (this.index >= this.steps.length - 1) {
      this.end(true);
      return;
    }
    this.goTo(this.index + 1);
  }

  // ------------------------------------------------------------ geometry

  private canvasToPage(r: TutorialRect): PageRect {
    const c = this.canvas.getBoundingClientRect();
    return { left: c.left + r.x, top: c.top + r.y, width: r.w, height: r.h };
  }

  private currentRects(): PageRect[] {
    const step = this.steps[this.index];
    if (!step) return [];
    const out: PageRect[] = [];
    if (step.target) {
      let el = document.querySelector(step.target);
      // On a phone the toolbar is two tiers, and a step pointing at Solve is pointing at
      // something behind the More button. Spotlight the way to it instead, which is what
      // the player has to press first anyway.
      if (el?.closest('.toolbar-overflow')) el = document.querySelector('.toolbar .btn.more');
      if (el) {
        const r = el.getBoundingClientRect();
        // A target that is not on screen (a keypad key with the keypad hidden, an action
        // button its `when` has taken away) is skipped rather than spotlighting nothing.
        if (r.width > 0 && r.height > 0) {
          out.push({ left: r.left, top: r.top, width: r.width, height: r.height });
        }
      }
    }
    if (step.highlight) {
      try {
        const h = step.highlight(this.ctx());
        if (h) for (const r of Array.isArray(h) ? h : [h]) out.push(this.canvasToPage(r));
      } catch (e) {
        console.warn('tutorial highlight threw', e);
      }
    }
    return out;
  }

  private reposition(): void {
    if (!this.active) return;
    const rects = this.currentRects();
    this.setCutouts(rects);
    this.placeCallout(rects);
    this.placePointer();
  }

  private setCutouts(rects: PageRect[]): void {
    const ns = 'http://www.w3.org/2000/svg';
    while (this.cutouts.length > rects.length) this.cutouts.pop()!.remove();
    while (this.cutouts.length < rects.length) {
      const r = document.createElementNS(ns, 'rect');
      r.setAttribute('fill', 'black');
      r.setAttribute('rx', String(RADIUS));
      r.setAttribute('ry', String(RADIUS));
      this.maskGroup.append(r);
      this.cutouts.push(r);
    }
    rects.forEach((pr, i) => {
      const el = this.cutouts[i];
      const target = {
        x: pr.left - PAD,
        y: pr.top - PAD,
        width: pr.width + 2 * PAD,
        height: pr.height + 2 * PAD,
      };
      const first = !el.hasAttribute('x');
      if (first) {
        for (const [k, v] of Object.entries(target)) el.setAttribute(k, String(v));
      } else {
        gsap.to(el, { attr: target, duration: 0.3, ease: 'power2.out' });
      }
    });
  }

  /**
   * On a phone the callout is docked to the bottom of the viewport as a full-width sheet
   * instead of floating next to the highlight (there is nowhere to float to). The board
   * gets `--tut-dock` worth of room taken off the bottom so the spotlight stays visible.
   */
  private updateDock(): void {
    // A phone on its side has height for neither: a bottom sheet took half of 320px and
    // crushed the rails until their buttons overlapped, and a floating box had nowhere to go
    // but over the board — on Fifteen, over the very gap it was talking about. What such a
    // screen does have is width beside a height-bound board, so the callout stands up into
    // a column at the start edge, and the page moves over for it (`--tut-side`).
    const side = isSideRail() && isShortScreen();
    const docked = side || isSmallScreen();
    this.docked = docked;
    this.callout.classList.toggle('docked', docked && !side);
    this.callout.classList.toggle('side', side);
    this.narrating =
      !!this.narrator &&
      !docked &&
      window.innerWidth >= NARRATOR_MIN_W &&
      window.innerHeight >= NARRATOR_MIN_H;
    this.callout.classList.toggle('narrated', this.narrating);
    if (docked) {
      this.callout.style.left = '';
      this.callout.style.top = '';
      this.callout.style.width = '';
    }
    const root = document.documentElement;
    const h = docked && !side ? Math.round(this.callout.offsetHeight) : 0;
    if (h !== this.dockHeight) {
      this.dockHeight = h;
      root.style.setProperty('--tut-dock', `${h}px`);
    }
    const w = side ? Math.round(this.callout.offsetWidth) : 0;
    if (w !== this.sideWidth) {
      this.sideWidth = w;
      root.style.setProperty('--tut-side', `${w}px`);
      root.classList.toggle('tut-side', side);
    }
  }

  /**
   * Skip and Next stay one line each: a long word ("Пропустить обучение") is set smaller
   * rather than breaking the button in two.
   */
  private fitButtons(): void {
    fitAll(this.callout, '.tut-actions .btn');
  }

  private placeCallout(rects: PageRect[]): void {
    this.updateDock();
    if (this.docked) {
      this.fitButtons();
      return;
    }
    const step = this.steps[this.index];
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const bw = Math.min(360, vw - 24);
    this.callout.style.width = `${bw}px`;
    this.fitButtons();
    // Everything below places the callout and Ziggy as one box, so he is never the part
    // left standing on the spotlight. He is on the start side: the left, bar in RTL.
    const zw = this.narrating ? NARRATOR_W : 0;
    const zStart = zw && getComputedStyle(this.callout).direction !== 'rtl' ? zw : 0;
    const cw = bw + zw;
    const ch = this.callout.offsetHeight || 140;
    const clamp = (l: number, t: number) => ({
      left: Math.max(12, Math.min(vw - cw - 12, l)),
      top: Math.max(12, Math.min(vh - ch - 12, t)),
    });
    let pos: { left: number; top: number };
    if (rects.length) {
      const u = union(rects);
      const gap = PAD + 18;
      const spots: Record<string, { left: number; top: number }> = {
        below: { left: u.left + u.width / 2 - cw / 2, top: u.top + u.height + gap },
        above: { left: u.left + u.width / 2 - cw / 2, top: u.top - gap - ch },
        right: { left: u.left + u.width + gap, top: u.top + u.height / 2 - ch / 2 },
        left: { left: u.left - gap - cw, top: u.top + u.height / 2 - ch / 2 },
      };
      // Last resorts, tried only when every side of the highlight lands on the board: the
      // margin beside the board itself, level with the highlight. On a desktop there is
      // usually room, and it keeps Ziggy off clues the step is talking about (Rectangles'
      // "9" at step 3 sat under him when the callout hugged the highlight).
      const cb = this.canvas.getBoundingClientRect();
      spots.besideRight = { left: cb.right + gap, top: spots.right.top };
      spots.besideLeft = { left: cb.left - gap - cw, top: spots.left.top };
      const order = [
        step.placement,
        'below',
        'above',
        'right',
        'left',
        'besideRight',
        'besideLeft',
      ].filter((k, i, arr): k is string => !!k && arr.indexOf(k) === i);
      // Prefer a placement that covers neither the highlight nor the board; covering the
      // highlight is far worse than covering some other part of the board.
      const cr = this.canvas.getBoundingClientRect();
      const board = { left: cr.left, top: cr.top, width: cr.width, height: cr.height };
      const hl = {
        left: u.left - PAD,
        top: u.top - PAD,
        width: u.width + 2 * PAD,
        height: u.height + 2 * PAD,
      };
      // The page's own buttons count too. A desktop's side column is where a callout
      // squeezed off the board ends up, and level with a highlight near the top it sat
      // right over New, Restart and Undo (Rectangles, Same Game, Slant, Solo at 1280x800),
      // which the player may well want mid-lesson. Hiding one counts as much as hiding the
      // same patch of board: weighed any heavier, a portrait tablet's callout left the clear
      // strip under the toolbar, which it only grazes, for the middle of Black Box's board.
      const controls: PageRect[] = [];
      for (const b of document.querySelectorAll<HTMLElement>(
        '.topbar a, .topbar button, .toolbar button, .toolbar select',
      )) {
        const r = b.getBoundingClientRect();
        if (r.width > 0 && r.height > 0) controls.push(r);
      }
      // The status line counts as well, which some steps send the player to read; a
      // callout pushed down to a corner of the window put Ziggy over its end. It is only
      // weighed, not slid past: it sits under the board, so clearing it the way a column
      // of buttons is cleared would rule out every spot beside the board.
      const covered = [...controls];
      const status = document.querySelector('.statusbar')?.getBoundingClientRect();
      if (status && status.width > 0 && status.height > 0) covered.push(status);
      const boxesAt = (c: { left: number; top: number }): PageRect[] => {
        // The callout and Ziggy as the two boxes they really are: he is only as tall as he
        // is, so the empty column above his head may sit over the board for free.
        const boxes = [{ left: c.left + zStart, top: c.top, width: bw, height: ch }];
        if (zw) {
          const zl = zStart ? c.left : c.left + bw;
          boxes.push({ left: zl, top: c.top + ch - NARRATOR_W, width: zw, height: NARRATOR_W });
        }
        return boxes;
      };
      const hlAt = (c: { left: number; top: number }): number =>
        boxesAt(c).reduce((a, box) => a + overlapArea(box, hl), 0);
      const scoreAt = (c: { left: number; top: number }): number => {
        let score = 0;
        for (const box of boxesAt(c)) {
          score += overlapArea(box, hl) * 1000 + overlapArea(box, board);
          for (const r of covered) score += overlapArea(box, r);
        }
        return score;
      };
      // Each side again, slid clear of the column of buttons it lands on: down past all of
      // them, or up above them. Tried only after every spot level with the highlight.
      for (const k of order.slice()) {
        const c = clamp(spots[k].left, spots[k].top);
        const boxes = boxesAt(c);
        if (!controls.some((r) => boxes.some((b) => overlapArea(b, r) > 0))) continue;
        const hit = controls.filter((r) =>
          boxes.some((b) => r.left < b.left + b.width && b.left < r.left + r.width),
        );
        const below = Math.max(...hit.map((r) => r.top + r.height)) + 12;
        const above = Math.min(...hit.map((r) => r.top)) - 12 - ch;
        // Only where it fits as it is: squeezed back onto the screen, it lands on the very
        // buttons it slid away from (Magnets' first step went up over the top bar).
        if (below + ch <= vh - 12) {
          spots[`${k}Below`] = { left: spots[k].left, top: below };
          order.push(`${k}Below`);
        }
        if (above >= 12) {
          spots[`${k}Above`] = { left: spots[k].left, top: above };
          order.push(`${k}Above`);
        }
      }
      const scored: { k: string; pos: { left: number; top: number }; score: number }[] = [];
      for (const k of order) {
        const c = clamp(spots[k].left, spots[k].top);
        const score = scoreAt(c);
        scored.push({ k, pos: c, score });
        if (score === 0) break;
      }
      // A highlight too big to stand clear of (the whole board, on a first step) is covered
      // somewhere whatever happens, and level with its middle was the worst place to do it:
      // the callout sat over a band of clues right across it (Magnets' "3" and minus sign,
      // Inertia's gems at 1024x768) while the corner below was board margin. So then the
      // sides are also tried pushed to the bottom and the top of the window, where the least
      // of the highlight is under them.
      if (scored.every((s) => hlAt(s.pos) > 0)) {
        for (const k of ['right', 'left', 'besideRight', 'besideLeft']) {
          for (const [edge, top] of [
            ['Low', vh - ch - 12],
            ['High', 12],
          ] as const) {
            const c = clamp(spots[k].left, top);
            scored.push({ k: `${k}${edge}`, pos: c, score: scoreAt(c) });
          }
        }
      }
      // Near-equal scores are a tie, not a verdict. Two sides that each clip the same strip
      // of board differ only by the sub-pixel drift of a board still easing in, and letting
      // that decide sent the callout across the screen at the re-measure half a second in
      // (Net's first step). So a tie goes to the side this step already stands on, and
      // failing that to the preferred order; only a clearly better spot moves it.
      const min = Math.min(...scored.map((s) => s.score));
      const near = (s: { score: number }) => s.score <= min + Math.max(min * 0.05, 400);
      const pick = scored.find((s) => s.k === this.placedSpot && near(s)) ?? scored.find(near)!;
      this.placedSpot = pick.k;
      pos = pick.pos;
    } else {
      const c = this.canvas.getBoundingClientRect();
      pos = clamp(c.left + c.width / 2 - cw / 2, Math.min(vh - ch - 16, c.top + c.height + 20));
    }
    this.callout.style.left = `${pos.left + zStart}px`;
    this.callout.style.top = `${pos.top}px`;
  }

  private placePointer(): void {
    const step = this.steps[this.index];
    let hint: PointerHint | null = null;
    if (step?.pointer && !this.advancing) {
      try {
        hint = step.pointer(this.ctx());
      } catch (e) {
        console.warn('tutorial pointer threw', e);
      }
    }
    if (!hint) {
      this.hidePointer();
      return;
    }
    const c = this.canvas.getBoundingClientRect();
    const x = c.left + hint.x;
    const y = c.top + hint.y;
    this.pointerEl.hidden = false;
    const tag = this.pointerEl.querySelector<HTMLElement>('.tut-pointer-tag')!;
    const drag = t(
      this.touch ? 'ui.tutorial.pointer.longPressDrag' : 'ui.tutorial.pointer.rightDrag',
    );
    const press = t(
      this.touch ? 'ui.tutorial.pointer.longPress' : 'ui.tutorial.pointer.rightClick',
    );
    const middle = t(
      this.touch ? 'ui.tutorial.pointer.twoFingerTap' : 'ui.tutorial.pointer.middleClick',
    );
    tag.textContent =
      hint.button === 'right'
        ? hint.to
          ? drag
          : press
        : hint.button === 'middle'
          ? middle
          : hint.to
            ? t('ui.tutorial.pointer.drag')
            : '';
    this.pointerTween?.kill();
    gsap.set(this.pointerEl, { left: x, top: y, x: 0, y: 0, opacity: 1 });
    // The tag rides to the right of the arrow; near the right edge of a phone — a drag
    // across the last column, a longer word than "drag" — it goes on the other side
    // rather than off the screen.
    this.pointerEl.classList.remove('tag-left', 'tag-below');
    tag.style.left = '';
    if (tag.textContent) {
      const arrow = this.pointerEl.querySelector('svg')?.getBoundingClientRect().width ?? 30;
      const dx = hint.to ? hint.to.x - hint.x : 0;
      const tagW = tag.offsetWidth;
      const vw = window.innerWidth;
      if (Math.max(x, x + dx) + arrow + tagW > vw - 4) {
        // No room on the right; the left, if the whole of the drag leaves room there.
        if (Math.min(x, x + dx) - tagW >= 4) this.pointerEl.classList.add('tag-left');
        else {
          // Neither ("lange drücken und ziehen" on a phone): under the arrow, slid along
          // to stay on screen wherever the drag carries it.
          this.pointerEl.classList.add('tag-below');
          const lo = 4 - Math.min(x, x + dx);
          const hi = vw - 4 - Math.max(x, x + dx) - tagW;
          tag.style.left = `${Math.max(lo, Math.min(0, hi))}px`;
        }
      }
    }
    if (hint.to) {
      const dx = hint.to.x - hint.x;
      const dy = hint.to.y - hint.y;
      this.pointerTween = gsap
        .timeline({ repeat: -1, repeatDelay: 0.4 })
        .fromTo(this.pointerEl, { x: 0, y: 0, opacity: 0 }, { opacity: 1, duration: 0.2 })
        .to(this.pointerEl, { x: dx, y: dy, duration: 0.9, ease: 'power1.inOut' })
        .to(this.pointerEl, { opacity: 0, duration: 0.25 });
    } else {
      this.pointerTween = gsap.to(this.pointerEl, {
        y: -7,
        duration: 0.5,
        yoyo: true,
        repeat: -1,
        ease: 'sine.inOut',
      });
    }
  }

  private hidePointer(): void {
    this.pointerTween?.kill();
    this.pointerTween = null;
    this.pointerEl.hidden = true;
  }

  private undock(): void {
    this.dockHeight = -1;
    this.sideWidth = -1;
    const root = document.documentElement;
    root.style.removeProperty('--tut-dock');
    root.style.removeProperty('--tut-side');
    root.classList.remove('tut-side');
  }

  end(completed: boolean): void {
    if (this.ended) return;
    this.flushRewind(false);
    this.ended = true;
    this.hidePointer();
    this.undock();
    window.removeEventListener('resize', this.onResize);
    document.removeEventListener('keydown', this.onKey, true);
    gsap.to(this.dim, { opacity: 0, duration: 0.25 });
    popOut(this.callout, () => {
      this.narrator?.destroy();
      this.overlay.remove();
    });
    this.hooks.onEnd(completed);
  }

  destroy(): void {
    this.flushRewind(false);
    this.undock();
    if (!this.ended) {
      this.ended = true;
      this.hidePointer();
      window.removeEventListener('resize', this.onResize);
      document.removeEventListener('keydown', this.onKey, true);
    }
    this.narrator?.destroy();
    this.overlay.remove();
  }
}

function overlapArea(a: PageRect, b: PageRect): number {
  const w = Math.min(a.left + a.width, b.left + b.width) - Math.max(a.left, b.left);
  const h = Math.min(a.top + a.height, b.top + b.height) - Math.max(a.top, b.top);
  return w > 0 && h > 0 ? w * h : 0;
}

function union(rs: PageRect[]): PageRect {
  const left = Math.min(...rs.map((r) => r.left));
  const top = Math.min(...rs.map((r) => r.top));
  const right = Math.max(...rs.map((r) => r.left + r.width));
  const bottom = Math.max(...rs.map((r) => r.top + r.height));
  return { left, top, width: right - left, height: bottom - top };
}
