/**
 * A buzz in the hand for what the board says out loud, on phones that can.
 *
 * Most portal players on a phone have the sound off — on a bus, in a queue, in bed — and
 * then a move landing, a move refused and a win all looked the same as nothing at all.
 * The board's voice (`sound.ts`) already names every one of those moments, so the buzz
 * rides on it: `playSound` hands each name here first, before any of its own reasons for
 * staying quiet, because a muted phone is exactly where a buzz is wanted. Only the board's
 * own sounds buzz, never the interface's ticks, and each one briefly.
 *
 * A switch in Settings (on by default) turns it off; it is only offered where
 * `navigator.vibrate` exists on a touch screen, which leaves out every desktop and iOS.
 * A leaf module: storage and the device check only. Nothing here throws.
 */

import { onStorageUpgrade, readItem, writeItem } from '../storage';
import { isTouch } from './device';

const KEY = 'puzzlebox:haptics';

/** The pattern each of the board's sounds buzzes with, in milliseconds on and off. */
const PATTERNS: Partial<Record<string, number | number[]>> = {
  move: 8,
  reject: [14, 50, 14],
  win: [20, 60, 20, 60, 40],
  lose: 90,
  credit: [10, 40, 30],
  unlock: [15, 40, 15],
};
/** A drag across a grid sounds once per square; it buzzes no more often than this. */
const MIN_GAP_MS = 60;

type Listener = (on: boolean) => void;
const listeners = new Set<Listener>();
let on = readItem(KEY) !== 'off';
let last = 0;

/** Whether this device can buzz at all: a touch screen with the Vibration API. */
export function canVibrate(): boolean {
  try {
    return typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function' && isTouch();
  } catch {
    return false;
  }
}

/** The Settings switch. */
export function hapticsOn(): boolean {
  return on;
}

export function setHaptics(next: boolean): void {
  if (next === on) return;
  on = next;
  writeItem(KEY, next ? 'on' : 'off');
  for (const fn of [...listeners]) {
    try {
      fn(on);
    } catch {
      /* a listener is never worth a buzz */
    }
  }
}

export function onHapticsChange(fn: Listener): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** The buzz for the board sound `name`, if it has one and buzzing is on. */
export function buzzFor(name: string): void {
  try {
    const pattern = PATTERNS[name];
    if (pattern === undefined || !on || !canVibrate()) return;
    const now = Date.now();
    if (name === 'move' && now - last < MIN_GAP_MS) return;
    last = now;
    navigator.vibrate(pattern);
  } catch {
    /* no buzz is ever worth breaking a puzzle over */
  }
}

/** The pattern for `name`, for the tests. */
export function hapticPattern(name: string): number | number[] | undefined {
  return PATTERNS[name];
}

// A choice saved on CrazyGames arrives with the platform store, a moment after boot.
onStorageUpgrade(() => {
  const next = readItem(KEY) !== 'off';
  if (next !== on) setHaptics(next);
});
