/**
 * Line-based solver for Pattern (nonograms).
 *
 * The solver only ever looks at one row or column at a time, exactly like the original
 * collection's, so it never guesses and never combines lines. Rather than enumerating
 * every placement of the runs, each line is analysed with two dynamic-programming
 * tables:
 *
 * - `F[i][j]`: the first `i` cells can be filled in agreement with what is already
 *   known, using exactly the first `j` runs (with cell `i-1` white, so a run may start
 *   at `i`);
 * - `B[i][j]`: cells `i..` can be filled using runs `j..`.
 *
 * A cell may be white if some `j` has `F[c][j] && B[c+1][j]`; it may be black if some
 * run `j` can start at some `s <= c < s+len` with `F[s][j]`, no white cell inside the
 * run, and a valid tail after it. Cells that can only be one thing are deduced. This is
 * O(length × runs) per line, so a 30×30 grid is checked in well under a millisecond.
 *
 * `solveGrid` repeats this over every row and column until nothing changes. It cannot
 * solve puzzles that need reasoning across several lines at once (the original's
 * comments give `4x4:2/1/2/1/1.1/2/1/1` as an example); the generator only ever
 * produces puzzles this solver finishes, so Solve always works on them.
 */
import { tx } from '../../i18n';
import { EMPTY, FULL, UNKNOWN, readLine, type Clues } from './clues';

/** Reusable workspace so the generator can solve thousands of lines without allocating. */
export class LineSolver {
  private readonly maxLen: number;
  private readonly stride: number;
  private readonly F: Uint8Array;
  private readonly B: Uint8Array;
  private readonly dots: Int32Array;
  private readonly canDot: Uint8Array;
  private readonly blockDiff: Int32Array;

  constructor(maxLen: number) {
    this.maxLen = maxLen;
    this.stride = (maxLen >> 1) + 2; // a line of n cells holds at most ceil(n/2) runs
    const cells = (maxLen + 1) * this.stride;
    this.F = new Uint8Array(cells);
    this.B = new Uint8Array(cells);
    this.dots = new Int32Array(maxLen + 1);
    this.canDot = new Uint8Array(maxLen);
    this.blockDiff = new Int32Array(maxLen + 2);
  }

  /**
   * Deduce whatever the clue forces in `line[0..len)`, writing results back in place.
   * Returns the number of cells filled in, or -1 when the line contradicts its clue.
   */
  solve(line: Uint8Array, len: number, clue: number[]): number {
    const n = len;
    const k = clue.length;
    if (n > this.maxLen || k >= this.stride) throw new Error(tx`line too long for solver`);
    const S = this.stride;
    const { F, B, dots, canDot, blockDiff } = this;
    F.fill(0, 0, (n + 1) * S);
    B.fill(0, 0, (n + 1) * S);

    dots[0] = 0;
    for (let i = 0; i < n; i++) dots[i + 1] = dots[i] + (line[i] === EMPTY ? 1 : 0);
    const fits = (s: number, runLen: number) => s + runLen <= n && dots[s + runLen] === dots[s];

    F[0] = 1;
    for (let i = 0; i < n; i++) {
      for (let j = 0; j <= k; j++) {
        if (!F[i * S + j]) continue;
        if (line[i] !== FULL) F[(i + 1) * S + j] = 1;
        if (j < k && fits(i, clue[j])) {
          const e = i + clue[j];
          if (e === n) F[n * S + j + 1] = 1;
          else if (line[e] !== FULL) F[(e + 1) * S + j + 1] = 1;
        }
      }
    }
    if (!F[n * S + k]) return -1;

    B[n * S + k] = 1;
    for (let i = n - 1; i >= 0; i--) {
      for (let j = 0; j <= k; j++) {
        let v = 0;
        if (line[i] !== FULL && B[(i + 1) * S + j]) v = 1;
        else if (j < k && fits(i, clue[j])) {
          const e = i + clue[j];
          if (e === n) v = j + 1 === k ? 1 : 0;
          else if (line[e] !== FULL && B[(e + 1) * S + j + 1]) v = 1;
        }
        B[i * S + j] = v;
      }
    }

    // Which cells can be white, and which can be covered by some run? A white cell
    // either follows another white cell (or the start of the line) — `F[c][j]` with a
    // matching tail — or is the separator right after a run, which the placement loop
    // below records.
    blockDiff.fill(0, 0, n + 2);
    for (let c = 0; c < n; c++) {
      let d = 0;
      if (line[c] !== FULL) {
        for (let j = 0; j <= k; j++) {
          if (F[c * S + j] && B[(c + 1) * S + j]) {
            d = 1;
            break;
          }
        }
      }
      canDot[c] = d;
    }
    for (let j = 0; j < k; j++) {
      const runLen = clue[j];
      for (let s = 0; s + runLen <= n; s++) {
        if (!F[s * S + j] || !fits(s, runLen)) continue;
        const e = s + runLen;
        const tailOk = e === n ? j + 1 === k : line[e] !== FULL && B[(e + 1) * S + j + 1] === 1;
        if (!tailOk) continue;
        blockDiff[s]++;
        blockDiff[e]--;
        if (e < n) canDot[e] = 1;
      }
    }

    let changed = 0;
    let cover = 0;
    for (let c = 0; c < n; c++) {
      cover += blockDiff[c];
      if (line[c] !== UNKNOWN) continue;
      const block = cover > 0;
      const dot = canDot[c] === 1;
      if (block && !dot) {
        line[c] = FULL;
        changed++;
      } else if (dot && !block) {
        line[c] = EMPTY;
        changed++;
      } else if (!dot && !block) {
        return -1;
      }
    }
    return changed;
  }
}

export interface GridSolution {
  /** Deduced grid; `UNKNOWN` where the line solver could not decide. */
  grid: Uint8Array;
  /** Every cell was decided. */
  solved: boolean;
  /** Some line turned out to be impossible (the clues are inconsistent). */
  contradiction: boolean;
}

/**
 * Solve a whole grid from its clues by repeatedly applying the line solver to every
 * row and column that has changed since it was last examined. `start` may hold cells
 * already known; a fresh all-unknown grid is used otherwise.
 */
export function solveGrid(
  w: number,
  h: number,
  clues: Clues,
  solver: LineSolver = new LineSolver(Math.max(w, h)),
  start?: Uint8Array,
): GridSolution {
  const grid = start ? start.slice() : new Uint8Array(w * h).fill(UNKNOWN);
  const max = Math.max(w, h);
  const buf = new Uint8Array(max);
  const dirty = new Uint8Array(w + h).fill(1);
  let pending = w + h;
  let contradiction = false;

  while (pending > 0 && !contradiction) {
    for (let i = 0; i < w + h && !contradiction; i++) {
      if (!dirty[i]) continue;
      dirty[i] = 0;
      pending--;
      const len = readLine(grid, w, h, i, buf);
      const clue = i < w ? clues.cols[i] : clues.rows[i - w];
      const changed = solver.solve(buf, len, clue);
      if (changed < 0) {
        contradiction = true;
        break;
      }
      if (changed === 0) continue;
      // Write back and mark the crossing lines for another look.
      if (i < w) {
        for (let y = 0; y < h; y++) {
          if (grid[y * w + i] !== buf[y]) {
            grid[y * w + i] = buf[y];
            if (!dirty[w + y]) {
              dirty[w + y] = 1;
              pending++;
            }
          }
        }
      } else {
        const base = (i - w) * w;
        for (let x = 0; x < w; x++) {
          if (grid[base + x] !== buf[x]) {
            grid[base + x] = buf[x];
            if (!dirty[x]) {
              dirty[x] = 1;
              pending++;
            }
          }
        }
      }
    }
  }

  let solved = !contradiction;
  if (solved) for (let i = 0; i < grid.length; i++) if (grid[i] === UNKNOWN) solved = false;
  return { grid, solved, contradiction };
}
