/**
 * Grid utilities and the automatic solver for Flood.
 *
 * Grids are flat `Uint8Array`s of colour indices, row-major, and the fill point is
 * always the top-left corner (index 0). The solver is a greedy search with a short
 * lookahead: every candidate colour is tried a few moves deep and the line of play
 * whose resulting grid looks "closest to finished" wins. Closeness is judged by a
 * cheap breadth-first survey of the grid: how many colour boundaries must be crossed
 * to reach the farthest square, how many squares are that far away, and how big the
 * controlled region already is. It is not optimal, but it is fast and rarely wasteful,
 * which is what a move limit needs.
 */

/** Index of the square that is flood-filled. */
export const FILL = 0;

/** How many moves deep the solver looks before falling back to the survey. */
const LOOKAHEAD = 3;

function neighbours(p: number, w: number, wh: number, out: Int32Array): number {
  let n = 0;
  const x = p % w;
  if (x > 0) out[n++] = p - 1;
  if (x < w - 1) out[n++] = p + 1;
  if (p >= w) out[n++] = p - w;
  if (p + w < wh) out[n++] = p + w;
  return n;
}

/**
 * Recolour the region connected to the fill point. `queue` is scratch space of at
 * least `grid.length` entries. Returns the number of squares recoloured. The caller
 * must make sure `colour` differs from the region's current colour.
 */
export function floodFill(
  grid: Uint8Array,
  w: number,
  h: number,
  colour: number,
  queue: Int32Array,
): number {
  const wh = w * h;
  const old = grid[FILL];
  const nb = new Int32Array(4);
  grid[FILL] = colour;
  queue[0] = FILL;
  let head = 1;
  let tail = 0;
  while (tail < head) {
    const p = queue[tail++];
    const n = neighbours(p, w, wh, nb);
    for (let i = 0; i < n; i++) {
      const q = nb[i];
      if (grid[q] === old) {
        grid[q] = colour;
        queue[head++] = q;
      }
    }
  }
  return head;
}

/** True when every square has the same colour. */
export function isUniform(grid: Uint8Array): boolean {
  const c = grid[FILL];
  for (let i = 1; i < grid.length; i++) if (grid[i] !== c) return false;
  return true;
}

/**
 * Mark the squares of colour `target` that would join the controlled region if it
 * were filled with that colour: every `target`-coloured component touching the region.
 */
export function joiningSquares(grid: Uint8Array, w: number, h: number, target: number): Uint8Array {
  const wh = w * h;
  const out = new Uint8Array(wh);
  if (target === grid[FILL]) return out;
  const tmp = grid.slice();
  const queue = new Int32Array(wh);
  floodFill(tmp, w, h, target, queue);
  // A second fill in an impossible colour marks the whole enlarged region.
  floodFill(tmp, w, h, 255, queue);
  for (let i = 0; i < wh; i++) if (tmp[i] === 255 && grid[i] === target) out[i] = 1;
  return out;
}

/**
 * Breadth-first distances from the fill point over the squares where `a` and `b`
 * differ — i.e. the region a move recoloured. Used to animate the fill spreading
 * outward. Squares outside the region get -1.
 */
export function waveDistances(
  a: Uint8Array,
  b: Uint8Array,
  w: number,
  h: number,
): { dist: Int32Array; max: number } {
  const wh = w * h;
  const dist = new Int32Array(wh).fill(-1);
  if (a[FILL] === b[FILL]) return { dist, max: -1 };
  const queue = new Int32Array(wh);
  const nb = new Int32Array(4);
  dist[FILL] = 0;
  queue[0] = FILL;
  let head = 1;
  let tail = 0;
  let max = 0;
  while (tail < head) {
    const p = queue[tail++];
    const n = neighbours(p, w, wh, nb);
    for (let i = 0; i < n; i++) {
      const q = nb[i];
      if (dist[q] < 0 && a[q] !== b[q]) {
        dist[q] = dist[p] + 1;
        if (dist[q] > max) max = dist[q];
        queue[head++] = q;
      }
    }
  }
  return { dist, max };
}

/** How promising a grid looks; smaller `depth`, then smaller `farthest`, then larger `control` is better. */
interface Survey {
  /** Colour boundaries crossed on the cheapest path to the farthest square. */
  depth: number;
  /** Number of squares at that distance. */
  farthest: number;
  /** Size of the controlled region. */
  control: number;
}

function isBetter(a: Survey, b: Survey): boolean {
  if (a.depth !== b.depth) return a.depth < b.depth;
  if (a.farthest !== b.farthest) return a.farthest < b.farthest;
  return a.control > b.control;
}

/** Scratch buffers so the solver does not allocate in its inner loops. */
class Scratch {
  readonly wh: number;
  readonly dist: Int32Array;
  readonly queueA: Int32Array;
  readonly queueB: Int32Array;
  readonly nb = new Int32Array(4);
  readonly grids: Uint8Array[] = [];
  constructor(
    readonly w: number,
    readonly h: number,
  ) {
    this.wh = w * h;
    this.dist = new Int32Array(this.wh);
    this.queueA = new Int32Array(this.wh);
    this.queueB = new Int32Array(this.wh);
    for (let d = 0; d < LOOKAHEAD; d++) this.grids.push(new Uint8Array(this.wh));
  }

  /**
   * Zero-one breadth-first search from the fill point: stepping to a same-coloured
   * square is free, crossing into a different colour costs one. Each layer is first
   * flooded through its own colours, then expanded across boundaries.
   */
  survey(grid: Uint8Array, out: Survey): void {
    const { w, wh, dist, nb } = this;
    dist.fill(-1);
    let cur = this.queueA;
    let next = this.queueB;
    let curLen = 1;
    cur[0] = FILL;
    dist[FILL] = 0;
    let d = 0;
    out.control = 0;
    for (;;) {
      for (let i = 0; i < curLen; i++) {
        const p = cur[i];
        const c = grid[p];
        const n = neighbours(p, w, wh, nb);
        for (let k = 0; k < n; k++) {
          const q = nb[k];
          if (dist[q] < 0 && grid[q] === c) {
            dist[q] = d;
            cur[curLen++] = q;
          }
        }
      }
      if (d === 0) out.control = curLen;
      let nextLen = 0;
      for (let i = 0; i < curLen; i++) {
        const n = neighbours(cur[i], w, wh, nb);
        for (let k = 0; k < n; k++) {
          const q = nb[k];
          if (dist[q] < 0) {
            dist[q] = d + 1;
            next[nextLen++] = q;
          }
        }
      }
      if (nextLen === 0) {
        out.depth = d;
        out.farthest = curLen;
        return;
      }
      const t = cur;
      cur = next;
      next = t;
      curLen = nextLen;
      d++;
    }
  }

  /** Bitmask of the colours bordering the controlled region. */
  adjacentColours(grid: Uint8Array): number {
    const { w, wh, dist, nb } = this;
    const queue = this.queueA;
    const own = grid[FILL];
    dist.fill(-1);
    dist[FILL] = 0;
    queue[0] = FILL;
    let head = 1;
    let tail = 0;
    let mask = 0;
    while (tail < head) {
      const p = queue[tail++];
      const n = neighbours(p, w, wh, nb);
      for (let k = 0; k < n; k++) {
        const q = nb[k];
        if (dist[q] >= 0) continue;
        dist[q] = 0;
        if (grid[q] === own) queue[head++] = q;
        else mask |= 1 << grid[q];
      }
    }
    return mask;
  }

  /**
   * Try every colour that borders the region at this level (any other colour would be
   * a wasted move); a move that finishes the grid wins outright (shallower finishes
   * rank higher), otherwise recurse or survey the result.
   */
  choose(grid: Uint8Array, colours: number, level: number, out: Survey): number {
    const { w, h, wh } = this;
    const tmp = this.grids[level];
    const result: Survey = { depth: 0, farthest: 0, control: 0 };
    let best: Survey = { depth: wh + 1, farthest: 0, control: 0 };
    let bestMove = -1;
    const adjacent = this.adjacentColours(grid);
    for (let c = 0; c < colours; c++) {
      if (!(adjacent & (1 << c))) continue;
      tmp.set(grid);
      floodFill(tmp, w, h, c, this.queueA);
      if (isUniform(tmp)) {
        out.depth = -1;
        out.farthest = level;
        out.control = wh;
        return c;
      }
      if (level < LOOKAHEAD - 1) this.choose(tmp, colours, level + 1, result);
      else this.survey(tmp, result);
      if (bestMove < 0 || isBetter(result, best)) {
        best = { ...result };
        bestMove = c;
      }
    }
    out.depth = best.depth;
    out.farthest = best.farthest;
    out.control = best.control;
    return bestMove;
  }
}

/**
 * Play the grid to completion with the automatic solver and return the sequence of
 * colours it chose. The input grid is not modified.
 */
export function solveGrid(grid: Uint8Array, w: number, h: number, colours: number): number[] {
  const scratch = new Scratch(w, h);
  const cur = grid.slice();
  const moves: number[] = [];
  const survey: Survey = { depth: 0, farthest: 0, control: 0 };
  while (!isUniform(cur) && moves.length < cur.length) {
    const c = scratch.choose(cur, colours, 0, survey);
    if (c < 0) break;
    floodFill(cur, w, h, c, scratch.queueA);
    moves.push(c);
  }
  return moves;
}
