/**
 * Tracks puzzle generation.
 *
 * A random self-avoiding walk from a square on the left edge to the bottom edge gives the
 * solution; its row and column counts become the clues. Given pieces are then chosen one
 * at a time (each must let the solver get further) until the solver of the requested
 * difficulty finishes the puzzle, after which redundant pieces are dropped again. A
 * Tricky puzzle must also defeat the Easy solver. Boards whose counts include a zero, or
 * two neighbouring ones when `singleOnes` is set, are thrown away as dull.
 */
import type { Random } from '../../framework/rng';
import {
  Board,
  D,
  L,
  Layout,
  NBITS,
  U,
  R,
  boardFromLayout,
  dx,
  dy,
  encodeDesc,
  opposite,
} from './board';
import { DIFF_EASY, solveBoard, solveProgress } from './solver';

export interface TracksParams {
  w: number;
  h: number;
  diff: number;
  /** Reject boards with a 1 count next to another 1 or at the entrance/exit. */
  singleOnes: boolean;
}

interface Path {
  /** Direction bits of the solution in every square (entrance and exit include L / D). */
  track: Uint8Array;
  rowS: number;
  colS: number;
}

/** A random self-avoiding walk from the left edge to the bottom edge. */
export function layPath(w: number, h: number, rng: Random): Path {
  const dirs = [U, D, L, R];
  for (;;) {
    const track = new Uint8Array(w * h);
    const rowS = rng.upto(h);
    let x = 0;
    let y = rowS;
    track[y * w] |= L;
    let stuck = false;
    while (y < h) {
      rng.shuffle(dirs);
      let chosen = 0;
      for (const d of dirs) {
        const nx = x + dx(d);
        const ny = y + dy(d);
        if (nx >= 0 && nx < w && ny === h) {
          chosen = d;
          break;
        }
        if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
        if (track[ny * w + nx]) continue;
        chosen = d;
        break;
      }
      if (!chosen) {
        stuck = true;
        break;
      }
      track[y * w + x] |= chosen;
      x += dx(chosen);
      y += dy(chosen);
      if (y < h) track[y * w + x] |= opposite(chosen);
    }
    if (stuck) continue;
    return { track, rowS, colS: x };
  }
}

/** Column then row counts of a solution. */
export function countsOf(track: Uint8Array, w: number, h: number): number[] {
  const numbers = new Array<number>(w + h).fill(0);
  for (let i = 0; i < w * h; i++) {
    if (track[i]) {
      numbers[i % w]++;
      numbers[w + Math.floor(i / w)]++;
    }
  }
  return numbers;
}

/** The dullness filters of the original: no empty line, and optionally no adjacent 1s. */
export function countsAcceptable(numbers: number[], singleOnes: boolean): boolean {
  if (numbers.some((v) => v === 0)) return false;
  if (singleOnes) {
    let lastOne = true; // a 1 in the entrance column is out too
    for (const v of numbers) {
      const one = v === 1;
      if (one && lastOne) return false;
      lastOne = one;
    }
    if (numbers[numbers.length - 1] === 1) return false; // and in the exit row
  }
  return true;
}

/** A square that is not a clue but has rails from two clue neighbours would show phantom track. */
function hasPhantom(b: Board): boolean {
  for (let i = 0; i < b.n; i++) if (!b.layout.clue[i] && NBITS[b.track[i]] > 1) return true;
  return false;
}

function stripped(layout: Layout, clue: Uint8Array): Board {
  return boardFromLayout({ ...layout, clue });
}

/**
 * Choose which pieces to give away. Returns 1 with `layout.clue` filled in on success,
 * -1 when the board is too easy or cannot be made solvable at this difficulty.
 */
export function addClues(layout: Layout, track: Uint8Array, diff: number, rng: Random): number {
  const { w, h, n } = layout;
  const clue = layout.clue;
  const positions: number[] = [];
  for (let i = 0; i < n; i++) if (track[i]) positions.push(i);

  let scratch = stripped(layout, clue);
  if (diff > DIFF_EASY && solveBoard(scratch, diff - 1) > 0) return -1;
  if (solveBoard(scratch, diff) > 0) return 1;
  let progress = solveProgress(scratch);
  const edgesBefore = new Uint8Array(n);

  rng.shuffle(positions);
  let solvable = false;
  for (const i of positions) {
    if (clue[i] || edgesBefore[i] === 2) continue;
    const trial = clue.slice();
    trial[i] = track[i];
    scratch = stripped(layout, trial);
    if (hasPhantom(scratch)) continue;
    if (diff > DIFF_EASY && solveBoard(scratch, diff - 1) > 0) continue;
    if (solveBoard(scratch, diff) > 0) {
      clue[i] = track[i];
      solvable = true;
      break;
    }
    const p = solveProgress(scratch);
    if (p > progress) {
      progress = p;
      clue[i] = track[i];
      for (let j = 0; j < n; j++) edgesBefore[j] = NBITS[scratch.track[j]];
    }
  }
  if (!solvable) return -1;

  const ent = layout.rowS * w;
  const ext = (h - 1) * w + layout.colS;
  rng.shuffle(positions);
  for (const i of positions) {
    if (!clue[i] || i === ent || i === ext) continue;
    const trial = clue.slice();
    trial[i] = 0;
    scratch = stripped(layout, trial);
    if (hasPhantom(scratch)) continue;
    if (solveBoard(scratch, diff) > 0) clue[i] = 0;
  }
  return 1;
}

/** Solution direction bits as one hex digit per square, for `aux`. */
export function encodeTrack(track: Uint8Array): string {
  let s = '';
  for (let i = 0; i < track.length; i++) s += track[i].toString(16).toUpperCase();
  return s;
}

export function decodeTrack(aux: string, n: number): Uint8Array | null {
  if (aux.length !== n || !/^[0-9A-F]+$/.test(aux)) return null;
  const track = new Uint8Array(n);
  for (let i = 0; i < n; i++) track[i] = parseInt(aux[i], 16);
  return track;
}

export function generate(p: TracksParams, rng: Random): { desc: string; aux: string } {
  const { w, h } = p;
  // The smallest board cannot be made Tricky; the original falls back silently too.
  const diff = w === 4 && h === 4 ? DIFF_EASY : p.diff;
  for (;;) {
    const path = layPath(w, h, rng);
    const numbers = countsOf(path.track, w, h);
    if (!countsAcceptable(numbers, p.singleOnes)) continue;
    const clue = new Uint8Array(w * h);
    clue[path.rowS * w] = path.track[path.rowS * w];
    clue[(h - 1) * w + path.colS] = path.track[(h - 1) * w + path.colS];
    const layout: Layout = { w, h, n: w * h, clue, numbers, rowS: path.rowS, colS: path.colS };
    if (addClues(layout, path.track, diff, rng) !== 1) continue;
    return { desc: encodeDesc(layout), aux: encodeTrack(path.track) };
  }
}
