/**
 * Which puzzles the player left half done, and when — for the menu's Continue button.
 *
 * The play page already keeps the board of every game under `puzzlebox:save:<slug>`
 * (gameView.ts), but a save says nothing about whether the board in it is one the player
 * was in the middle of: a fresh deal nobody touched is saved too, and so is a solved one.
 * So each save also notes here whether it left a puzzle *in progress* — a move made, and
 * not over — and when. Continue offers the most recent of those.
 *
 * In `localStorage` beside the saves, deliberately not in the tiered store: a record of a
 * board that is not there to be put back would offer a Continue that deals a new puzzle.
 */

const KEY = 'puzzlebox:inprogress';
const SAVE_PREFIX = 'puzzlebox:save:';

type Record_ = Record<string, number>;

function local(): Storage | null {
  try {
    const s = globalThis.localStorage;
    return s && typeof s.getItem === 'function' ? s : null;
  } catch {
    return null;
  }
}

function read(): Record_ {
  try {
    const raw = local()?.getItem(KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    const out: Record_ = {};
    for (const [slug, at] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof at === 'number' && Number.isFinite(at)) out[slug] = at;
    }
    return out;
  } catch {
    return {};
  }
}

function write(rec: Record_): void {
  try {
    local()?.setItem(KEY, JSON.stringify(rec));
  } catch {
    /* storage unavailable: there is simply no Continue */
  }
}

/**
 * Note the board `slug` was just saved on: `inProgress` when a move has been made on it and
 * it is not over. `at` is the wall clock, which only ever orders the entries.
 */
export function noteBoard(slug: string, inProgress: boolean, at = Date.now()): void {
  const rec = read();
  if (inProgress) {
    // The same puzzle saved again a moment later is still the same visit: keep it at the
    // top without rewriting the record on every move.
    if (rec[slug] !== undefined && at - rec[slug] < 1000) return;
    rec[slug] = at;
  } else {
    if (rec[slug] === undefined) return;
    delete rec[slug];
  }
  write(rec);
}

/**
 * The puzzle to continue: the most recently left one that is still in progress, still has
 * its save, and passes `canOpen` (in the collection, and unlocked). `null` for none.
 */
export function continueSlug(canOpen: (slug: string) => boolean): string | null {
  const rec = read();
  const store = local();
  let best: string | null = null;
  let bestAt = -Infinity;
  for (const [slug, at] of Object.entries(rec)) {
    if (at <= bestAt || !canOpen(slug)) continue;
    try {
      if (!store?.getItem(SAVE_PREFIX + slug)) continue;
    } catch {
      continue;
    }
    best = slug;
    bestAt = at;
  }
  return best;
}
