/**
 * Faces for the round HUD buttons a game declares (`GameAction.glyph`). Each is a 24×24
 * SVG drawn in `currentColor` with the same pen as the shell's own glyphs (Undo, Hint,
 * Pause), so a game's tools read as part of one set. A game with a tool nobody else has
 * draws its own face in its folder, to the same recipe: `glyph(pathData)`.
 */

/** Wrap path data (stroked, round ends) in the HUD's standard glyph `<svg>`. */
export function glyph(d: string, extra = ''): string {
  return (
    '<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">' +
    `<path d="${d}" fill="none" stroke="currentColor" stroke-width="2" ` +
    'stroke-linecap="round" stroke-linejoin="round"/>' +
    extra +
    '</svg>'
  );
}

/** A solid shape in `currentColor`, for the glyphs that need something filled in. */
export function solid(d: string): string {
  return `<path d="${d}" fill="currentColor"/>`;
}

