/**
 * The very first screen a new player sees: "pick your first puzzle", the free games as
 * big cards, and under them a row of padlocked ones saying there is more to come.
 *
 * It replaces the menu exactly once. A brand-new visitor faced with thirty-eight cards and
 * a strip of stats has to work out what the page is before they can play anything; this
 * asks one question with one click to answer it, which is also what CrazyGames asks of a
 * first session (gameplay within a click). Picking a card — or anything that shows the
 * player is not new after all, such as progress arriving from the platform's store a
 * moment after boot — marks the welcome as done, and from then on `#/` is the ordinary
 * menu.
 */
import type { Game } from '../framework/types';
import { menuGames } from '../games/registry';
import { gameDescription, gameName, t } from '../i18n';
import { readItem, writeItem } from '../storage';
import { revealThumb, staggerIn } from './anim';
import { handFontReady } from './fonts';
import { languageSwitcher } from './language';
import { brandMarkSVG } from './brand';
import { mountMascot } from './mascot';
import { bestKnownName } from './menu-search';
import { STARTER_GAMES, getProgress, onProgressChange, totalSolved } from './progress';
import { paintCachedThumbnail, renderThumbnail } from './thumbnail';

const KEY = 'puzzlebox:welcomed';
/** How many locked puzzles the teaser row shows before "+N". */
const TEASER = 6;

const LOCK_SVG =
  '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 11V8a5 5 0 0 1 10 0v3" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/><rect x="4.5" y="11" width="15" height="10" rx="3" fill="currentColor"/></svg>';

/** A player with anything to their name has been here before, whatever the flag says. */
function hasHistory(): boolean {
  const p = getProgress();
  return (
    p.unlockAll ||
    totalSolved() > 0 ||
    p.credits > 0 ||
    p.unlocked.some((slug) => !STARTER_GAMES.includes(slug))
  );
}

/** Whether `#/` should show the welcome rather than the menu. */
export function needsWelcome(): boolean {
  if (hasHistory()) return false;
  try {
    return readItem(KEY) !== '1';
  } catch {
    return false;
  }
}

export function markWelcomed(): void {
  writeItem(KEY, '1');
}

function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  cls?: string,
  text?: string,
): HTMLElementTagNameMap[K] {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

/**
 * Draw the welcome into `root`. `toMenu` is called if the player turns out not to be new
 * while it is up (their saved progress arrived late), so the app can put the menu there.
 */
export function renderWelcome(root: HTMLElement, toMenu: () => void): { destroy(): void } {
  document.title = t('ui.appName');
  const page = el('div', 'welcome-page');
  // Once shown, it is shown: a reload lands on the menu rather than asking again.
  markWelcomed();
  const free = menuGames.filter((g) => STARTER_GAMES.includes(g.id));
  const locked = menuGames.filter((g) => !STARTER_GAMES.includes(g.id));

  const head = el('header', 'welcome-head');
  const mark = el('span', 'logo-mark welcome-mark');
  mark.innerHTML = brandMarkSVG({ className: 'brand-mark' });
  const mascot = mountMascot(mark, { className: 'logo-ziggy', tilt: -12 });
  const title = el('h1', 'welcome-title', t('ui.welcome.title'));
  const sub = el('p', 'welcome-sub', t('ui.welcome.subtitle', { n: free.length }));
  head.append(languageSwitcher(), mark, title, sub);

  const pending: { game: Game; canvas: HTMLCanvasElement }[] = [];
  const thumb = (game: Game) => {
    const wrap = el('div', 'thumb');
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 1;
    wrap.append(canvas);
    if (!paintCachedThumbnail(game, canvas)) pending.push({ game, canvas });
    return wrap;
  };

  // The eight lie in the same open box as the collection's cards (desk.css), and fill it:
  // this is a fixed screen, like the menu, not a page to scroll (welcome.css).
  const tray = el('div', 'shelf welcome-shelf');
  const grid = el('div', 'card-grid welcome-grid');
  tray.append(grid);
  for (const game of free) {
    // The same card as the menu's, so it lifts off the page and turns into the puzzle's
    // sheet as it would there (`app.ts` looks for `.card[data-slug]`, see flight.ts).
    const card = el('a', 'card sketch');
    card.href = `#/${game.id}`;
    card.dataset.slug = game.id;
    card.append(thumb(game), el('h2', undefined, gameName(game)));
    const familiar = bestKnownName(game);
    if (familiar) card.append(el('p', 'card-alias', familiar));
    card.append(el('p', undefined, gameDescription(game)));
    grid.append(card);
  }

  // More to come: a few of the padlocked puzzles by name, and how to open them.
  const more = el('section', 'welcome-more');
  const moreTitle = el('h2', 'welcome-more-title', t('ui.welcome.more', { n: locked.length }));
  const how = el('p', 'welcome-how', t('ui.welcome.how'));
  const row = el('ul', 'welcome-locked');
  for (const game of locked.slice(0, TEASER)) {
    const li = el('li', 'welcome-locked-card');
    const th = thumb(game);
    const lock = el('span', 'welcome-lock');
    lock.innerHTML = LOCK_SVG;
    th.append(lock);
    li.append(th, el('span', 'welcome-locked-name', gameName(game)));
    row.append(li);
  }
  if (locked.length > TEASER) {
    const rest = el('li', 'welcome-locked-card welcome-locked-rest');
    rest.append(el('b', undefined, `+${locked.length - TEASER}`));
    row.append(rest);
  }
  const words = el('div', 'welcome-more-words');
  words.append(moreTitle, how);
  more.append(words, row);

  // A fixed screen that never scrolls, as the menu is (shelf.css `html.screen`).
  document.documentElement.classList.add('screen');
  page.append(head, tray, more);
  root.append(page);
  staggerIn([...grid.children], { stagger: 0.05 });

  let cancelled = false;
  const step = () => {
    if (cancelled) return;
    const next = pending.shift();
    if (!next) return;
    try {
      renderThumbnail(next.game, next.canvas);
      // Faded up as it lands, as the menu's are, rather than snapping into an empty frame.
      revealThumb(next.canvas);
    } catch (e) {
      console.error(`thumbnail for ${next.game.id} failed`, e);
    }
    requestAnimationFrame(step);
  };
  // A canvas keeps the face it was painted in: the previews wait for the hand lettering
  // rather than baking a fallback into every digit on the first screen (`fonts.ts`).
  void handFontReady().then(() => requestAnimationFrame(step));

  const off = onProgressChange(() => {
    if (!hasHistory()) return;
    markWelcomed();
    toMenu();
  });

  return {
    destroy() {
      cancelled = true;
      off();
      mascot?.destroy();
      page.remove();
      document.documentElement.classList.remove('screen');
    },
  };
}
