/**
 * The single source of truth for colours. These are injected as CSS custom properties
 * (`--c-<token>`) at startup so the page chrome and the canvas share one palette.
 *
 * The collection is ink on warm paper, and the tuning follows from that: paper stays warm
 * but sits brighter than the card fills printed on it, ink is nearly black so a thin
 * sketched stroke still reads at thumbnail size, and the category colours are saturated
 * enough to survive being shrunk to a 200px menu card or a portal thumbnail. They were
 * previously mixed down towards the paper, which looked calm at full size and turned to
 * grey mush at small ones.
 */
export const PALETTE = {
  paper: '#fbf6ea',
  ink: '#23222e',
  dark: '#39374a',
  pencil: '#6a6676',
  faint: '#d5cec0',
  shade: '#f0e8d7',
  accent: '#e8502e',
  red: '#e03b3b',
  blue: '#2f6fd0',
  green: '#2f9d57',
  yellow: '#f2b52a',
  orange: '#f0861e',
  purple: '#8a4fc4',
  /** Ziggy's violet. Deliberately bluer than `purple`, which games already use. */
  violet: '#4d28e6',
  teal: '#12a0a0',
  pink: '#e35f9c',
  brown: '#96693f',
  highlight: '#ffffff',
  lowlight: '#b9b2a3',
  error: '#cf2f2f',
  /** The green a finished puzzle flashes in. See `docs/ADDING-A-GAME.md` under Drawing. */
  ok: '#2f8f55',
  white: '#ffffff',
  black: '#000000',
} as const;

export type PaletteToken = keyof typeof PALETTE;

/** A stable ordered list of distinct colours for games that need N categories. */
export const SERIES: PaletteToken[] = [
  'red',
  'blue',
  'green',
  'yellow',
  'purple',
  'orange',
  'teal',
  'pink',
  'brown',
  'dark',
];

export function injectPaletteCSS(root: HTMLElement = document.documentElement): void {
  for (const [k, v] of Object.entries(PALETTE)) root.style.setProperty(`--c-${k}`, v);
}

/** Parse a CSS hex colour into [r, g, b]. */
export function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace('#', '');
  if (h.length === 3)
    h = h
      .split('')
      .map((c) => c + c)
      .join('');
  const n = parseInt(h.slice(0, 6), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

export function rgbToHex(r: number, g: number, b: number): string {
  const c = (v: number) =>
    Math.max(0, Math.min(255, Math.round(v)))
      .toString(16)
      .padStart(2, '0');
  return `#${c(r)}${c(g)}${c(b)}`;
}

/** Linear blend between two hex colours; t = 0 gives `a`, t = 1 gives `b`. */
export function mix(a: string, b: string, t: number): string {
  const [r1, g1, b1] = hexToRgb(a);
  const [r2, g2, b2] = hexToRgb(b);
  return rgbToHex(r1 + (r2 - r1) * t, g1 + (g2 - g1) * t, b1 + (b2 - b1) * t);
}
