import { t as tr, tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  RIGHT_BUTTON,
  RIGHT_DRAG,
  RIGHT_RELEASE,
  isCursorMove,
  isCursorSelect,
  keyChar,
  moveCursor,
  stripMods,
} from '../../framework/input';
import { flashOn } from '../../framework/grid';
import { ERASE_GLYPH } from '../../framework/glyphs';
import type { Drawing } from '../../framework/drawing';
import type { Random } from '../../framework/rng';
import {
  drawRectEdges,
  edgesOfRects,
  encodeEdges,
  findRegions,
  hIndex,
  inHRange,
  inVRange,
  parseDesc,
  textFormat,
  vIndex,
} from './board';
import type { Rect, Region } from './board';
import { generateRect } from './generator';
import { numbersOfGrid, searchSolutions, solveRects } from './solver';
import { tutorial } from './tutorial';
import help from './help.md?raw';
import { achievements } from './achievements';

export interface RectParams {
  w: number;
  h: number;
  /** Generate a grid this much smaller in each dimension and stretch it (0 = off). */
  expand: number;
  /** Place the numbers so the solution is unique. */
  unique: boolean;
}

export interface RectState {
  w: number;
  h: number;
  /** Clue number per cell, 0 for none. */
  grid: number[];
  /** Vertical edges: `vedge[y * w + x]` is the edge on the left of cell (x, y), x ≥ 1. */
  vedge: Uint8Array;
  /** Horizontal edges: `hedge[y * w + x]` is the edge above cell (x, y), y ≥ 1. */
  hedge: Uint8Array;
  /** Cells inside a closed rectangle holding exactly one number equal to its area. */
  correct: Uint8Array;
  /** Every closed rectangle currently on the board. */
  regions: Region[];
  completed: boolean;
  cheated: boolean;
}

/**
 * Drag bookkeeping uses doubled grid coordinates, as the original does: even values are
 * grid lines, odd values are cell centres, so a drag can start on an edge (one odd
 * coordinate) or in a cell (both odd) as well as at a corner.
 */
export interface RectUI {
  /** Doubled coordinates of the drag start, or -1 when no drag is in progress. */
  dragStartX: number;
  dragStartY: number;
  dragEndX: number;
  dragEndY: number;
  /** The pointer has left its starting point, so the release is a drag not a click. */
  dragged: boolean;
  /** Erasing (right button / Space): clear the inside without touching the outline. */
  erasing: boolean;
  /** Cell bounds of the dragged rectangle: cells [x1, x2) × [y1, y2); -1 when none. */
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  cx: number;
  cy: number;
  cursorVisible: boolean;
  /** A rectangle is being dragged out from the keyboard cursor. */
  cursorDragging: boolean;
  /**
   * The Erase tool: the left button works like the right one — a drag clears the lines
   * inside an area — except that a click on a grid line only ever removes it.
   */
  erase: boolean;
}

const MAX_SIDE = 40;
const FLASH_FRAME = 0.13;
const BORDER = 0.3;
/** Fraction of a tile around a corner or a cell centre that counts as clicking it. */
const CORNER_TOLERANCE = 0.15;
const CENTRE_TOLERANCE = 0.15;
const EDGE_WIDTH = 0.11;

export function border(t: number): number {
  return Math.round(t * BORDER);
}

/**
 * Format a float to six significant digits for the parameter string, like C's `%g`
 * but never in exponent form: `decodeParams` reads plain digits only, so "1e-9" came
 * back as 1 and swallowed the "a" (no unique solution) after it.
 */
function fmtFactor(f: number): string {
  return f.toLocaleString('en-US', { useGrouping: false, maximumSignificantDigits: 6 });
}

/**
 * Snap a position in tile units to doubled grid coordinates: a nearby corner wins,
 * then a nearby cell centre, otherwise the closer of the two edges.
 */
export function coordRound(x: number, y: number): [number, number] {
  const xs = Math.floor(x) + 0.5;
  const ys = Math.floor(y) + 0.5;
  const xv = Math.floor(x + 0.5);
  const yv = Math.floor(y + 0.5);
  let dx = Math.abs(x - xv);
  let dy = Math.abs(y - yv);
  if (Math.max(dx, dy) < CORNER_TOLERANCE) return [2 * xv, 2 * yv];
  dx = Math.abs(x - xs);
  dy = Math.abs(y - ys);
  if (Math.max(dx, dy) < CENTRE_TOLERANCE) return [1 + 2 * Math.floor(xs), 1 + 2 * Math.floor(ys)];
  if (dx > dy) return [2 * xv, 1 + 2 * Math.floor(ys)];
  return [1 + 2 * Math.floor(xs), 2 * yv];
}

function makeState(
  w: number,
  h: number,
  grid: number[],
  vedge: Uint8Array,
  hedge: Uint8Array,
  cheated: boolean,
): RectState {
  const { correct, regions } = findRegions(w, h, grid, vedge, hedge);
  let completed = true;
  for (let i = 0; i < correct.length; i++) {
    if (!correct[i]) {
      completed = false;
      break;
    }
  }
  return { w, h, grid, vedge, hedge, correct, regions, completed, cheated };
}

function clearDrag(ui: RectUI): void {
  ui.dragStartX = ui.dragStartY = ui.dragEndX = ui.dragEndY = -1;
  ui.x1 = ui.y1 = ui.x2 = ui.y2 = -1;
  ui.dragged = false;
}

const game = defineGame<RectParams, RectState, RectUI>({
  id: 'rect',
  name: 'Rectangles',
  description: 'Divide the grid into rectangles, each containing one number equal to its area.',
  alsoKnownAs: 'Shikaku',
  help,
  tutorial,
  achievements,
  presets: [7, 9, 11, 13, 15, 17, 19].map((d) => ({
    name: `${d}×${d}`,
    params: { w: d, h: d, expand: 0, unique: true },
  })),
  defaultParams: () => ({ w: 7, h: 7, expand: 0, unique: true }),
  encodeParams(p, full) {
    let s = `${p.w}x${p.h}`;
    if (full && p.expand) s += `e${fmtFactor(p.expand)}`;
    if (full && !p.unique) s += 'a';
    return s;
  },
  decodeParams(str) {
    const m = /^(\d+)(?:x(\d+))?(?:e(\d*\.?\d*))?(a)?/.exec(str);
    if (!m) throw new Error(tx`expected WxH`);
    const w = parseInt(m[1], 10);
    return {
      w,
      h: m[2] ? parseInt(m[2], 10) : w,
      expand: m[3] ? parseFloat(m[3]) || 0 : 0,
      unique: !m[4],
    };
  },
  validateParams(p) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w <= 0 || p.h <= 0) return tx`Width and height must both be greater than zero`;
    if (p.w * p.h < 2) return tx`Grid area must be greater than one`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (!Number.isFinite(p.expand)) return tx`Expansion factor must be a number`;
    if (p.expand < 0) return tx`Expansion factor may not be negative`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
      // A fraction, even when the preset of the day happens to show a whole `0`.
      { type: 'string', name: 'Expansion factor', value: fmtFactor(p.expand), keyboard: 'decimal' },
      { type: 'boolean', name: 'Ensure unique solution', value: p.unique },
    ];
  },
  customParams(items) {
    const str = (i: number) => (items[i] as { value: string }).value;
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (s: string) => (/^-?\d+$/.test(s.trim()) ? parseInt(s, 10) : NaN);
    return {
      w: int(str(0)),
      h: int(str(1)),
      // A decimal comma is what a Dutch or German phone keypad offers.
      expand: str(2).trim() === '' ? 0 : Number(str(2).trim().replace(',', '.')),
      unique: (items[3] as { value: boolean }).value,
    };
  },

  newDesc(p, rng: Random) {
    const g = generateRect(p.w, p.h, p.expand, p.unique, rng);
    return { desc: g.desc, aux: g.aux };
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const grid = parseDesc(desc, p.w, p.h) as number[];
    return makeState(p.w, p.h, grid, new Uint8Array(p.w * p.h), new Uint8Array(p.w * p.h), false);
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const { w, h } = curr;
    const bits = (w - 1) * h + (h - 1) * w;
    if (aux && aux.length === bits + 1 && aux[0] === 'S') return aux;
    const numbers = numbersOfGrid(w, h, curr.grid);
    let rects: Rect[] | null = null;
    const res = solveRects(w, h, numbers);
    if (res.outcome === 1) rects = res.placements.map((list) => list[0]);
    else if (res.outcome === 2) rects = searchSolutions(w, h, numbers, 1)[0] ?? null;
    if (!rects) throw new Error(tx`No solution exists for this puzzle`);
    const { vedge, hedge } = edgesOfRects(w, h, rects);
    return encodeEdges(w, h, vedge, hedge);
  },

  textFormat: (s) => textFormat(s.w, s.h, s.grid, s.vedge, s.hedge),

  newUI: () => ({
    dragStartX: -1,
    dragStartY: -1,
    dragEndX: -1,
    dragEndY: -1,
    dragged: false,
    erasing: false,
    x1: -1,
    y1: -1,
    x2: -1,
    y2: -1,
    cx: 0,
    cy: 0,
    cursorVisible: false,
    cursorDragging: false,
    erase: false,
  }),
  // A finished board is not left with a keyboard cursor sitting on it.
  changedState(ui, old, next) {
    // A drag (mouse or keyboard) still held when Undo, Solve or Restart changes the board
    // is dropped rather than drawn onto the new board at release; the drag's own move is
    // made after it has been cleared.
    clearDrag(ui);
    ui.cursorDragging = false;
    if (!old.completed && next.completed) ui.cursorVisible = false;
  },

  actions: [
    {
      label: 'Erase',
      key: 'E',
      hud: true,
      glyph: ERASE_GLYPH,
      pressed: (_s, ui) => ui.erase,
      title: 'Drag over an area to clear the lines inside it, or click a line to remove it (E)',
    },
  ],

  interpretMove(state, ui, ds, mx, my, button) {
    let b = stripMods(button);
    const { w, h } = state;
    const ch = keyChar(b);
    if (ch === 'e' || ch === 'E') {
      ui.erase = !ui.erase;
      return '';
    }
    // With the Erase tool the left button is an eraser, exactly as the right one is.
    const tool = ui.erase && (b === LEFT_BUTTON || b === LEFT_DRAG || b === LEFT_RELEASE);
    if (tool) b += RIGHT_BUTTON - LEFT_BUTTON;
    const t = ds.tileSize;
    const bd = border(t);
    let [xc, yc] = coordRound((mx - bd) / t, (my - bd) / t);
    let startDrag = false;
    let endDrag = false;
    let active = false;
    let erasing = false;

    if (b === LEFT_BUTTON || b === RIGHT_BUTTON) {
      // A mouse press cancels any keyboard drag in progress.
      if (ui.dragStartX >= 0 && ui.cursorDragging) clearDrag(ui);
      startDrag = true;
      ui.cursorVisible = ui.cursorDragging = false;
      active = true;
      erasing = b === RIGHT_BUTTON;
    } else if (b === LEFT_RELEASE || b === RIGHT_RELEASE) {
      if (ui.cursorVisible) {
        ui.cursorVisible = false;
        active = true;
      }
      endDrag = true;
      erasing = b === RIGHT_RELEASE;
    } else if (isCursorMove(b)) {
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      active = true;
      if (!ui.cursorDragging) return '';
      [xc, yc] = coordRound(ui.cx + 0.5, ui.cy + 0.5);
    } else if (isCursorSelect(b)) {
      // Ignore the keyboard while a mouse drag is in progress.
      if (ui.dragStartX >= 0 && !ui.cursorDragging) return null;
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      [xc, yc] = coordRound(ui.cx + 0.5, ui.cy + 0.5);
      erasing = b === CURSOR_SELECT2;
      if (ui.cursorDragging) {
        ui.cursorDragging = false;
        endDrag = true;
      } else {
        ui.cursorDragging = true;
        startDrag = true;
      }
      active = true;
    } else if (b !== LEFT_DRAG && b !== RIGHT_DRAG) {
      return null;
    }

    const inRange = xc >= 0 && xc <= 2 * w && yc >= 0 && yc <= 2 * h;

    if (startDrag && inRange) {
      ui.dragStartX = xc;
      ui.dragStartY = yc;
      ui.dragEndX = ui.dragEndY = -1;
      ui.dragged = false;
      ui.erasing = erasing;
      active = true;
    }

    if (ui.dragStartX >= 0 && (xc !== ui.dragEndX || yc !== ui.dragEndY)) {
      if (ui.dragEndX !== -1 && ui.dragEndY !== -1) ui.dragged = true;
      ui.dragEndX = xc;
      ui.dragEndY = yc;
      active = true;
      if (inRange) {
        // Round the doubled coordinates outwards to whole cells.
        ui.x1 = Math.min(ui.dragStartX, xc) >> 1;
        ui.x2 = (Math.max(ui.dragStartX, xc) + 1) >> 1;
        ui.y1 = Math.min(ui.dragStartY, yc) >> 1;
        ui.y2 = (Math.max(ui.dragStartY, yc) + 1) >> 1;
      } else {
        ui.x1 = ui.y1 = ui.x2 = ui.y2 = -1;
      }
    }

    let move: string | null = null;
    if (endDrag && ui.dragStartX >= 0) {
      if (inRange && erasing === ui.erasing) {
        if (ui.dragged) {
          if (
            ui.x1 >= 0 &&
            drawRectEdges(
              w,
              h,
              state.hedge,
              state.vedge,
              !ui.erasing,
              ui.x1,
              ui.y1,
              ui.x2,
              ui.y2,
              false,
            )
          ) {
            move = `${ui.erasing ? 'E' : 'R'}${ui.x1},${ui.y1},${ui.x2 - ui.x1},${ui.y2 - ui.y1}`;
          }
        } else if (xc & 1 && !(yc & 1) && inHRange(w, h, xc >> 1, yc >> 1)) {
          // The eraser takes a line away but never draws one.
          if (!tool || state.hedge[hIndex(w, xc >> 1, yc >> 1)]) move = `H${xc >> 1},${yc >> 1}`;
        } else if (yc & 1 && !(xc & 1) && inVRange(w, h, xc >> 1, yc >> 1)) {
          if (!tool || state.vedge[vIndex(w, xc >> 1, yc >> 1)]) move = `V${xc >> 1},${yc >> 1}`;
        }
      }
      clearDrag(ui);
      active = true;
    }

    if (move) return move;
    return active ? '' : null;
  },

  executeMove(state, move) {
    const { w, h } = state;
    if (move[0] === 'S') {
      const bits = move.slice(1);
      if (bits.length !== (w - 1) * h + (h - 1) * w || !/^[01]*$/.test(bits)) return null;
      const vedge = new Uint8Array(w * h);
      const hedge = new Uint8Array(w * h);
      let i = 0;
      for (let y = 0; y < h; y++)
        for (let x = 1; x < w; x++) vedge[vIndex(w, x, y)] = bits[i++] === '1' ? 1 : 0;
      for (let y = 1; y < h; y++)
        for (let x = 0; x < w; x++) hedge[hIndex(w, x, y)] = bits[i++] === '1' ? 1 : 0;
      return makeState(w, h, state.grid, vedge, hedge, true);
    }
    let m = /^([RE])(\d+),(\d+),(\d+),(\d+)$/.exec(move);
    if (m) {
      const x1 = parseInt(m[2], 10);
      const y1 = parseInt(m[3], 10);
      const rw = parseInt(m[4], 10);
      const rh = parseInt(m[5], 10);
      if (x1 + rw > w || y1 + rh > h) return null;
      const hedge = state.hedge.slice();
      const vedge = state.vedge.slice();
      if (!drawRectEdges(w, h, hedge, vedge, m[1] === 'R', x1, y1, x1 + rw, y1 + rh, true))
        return state;
      return makeState(w, h, state.grid, vedge, hedge, state.cheated);
    }
    m = /^([HV])(\d+),(\d+)$/.exec(move);
    if (!m) return null;
    const x = parseInt(m[2], 10);
    const y = parseInt(m[3], 10);
    if (m[1] === 'H') {
      if (!inHRange(w, h, x, y)) return null;
      const hedge = state.hedge.slice();
      hedge[hIndex(w, x, y)] ^= 1;
      return makeState(w, h, state.grid, state.vedge, hedge, state.cheated);
    }
    if (!inVRange(w, h, x, y)) return null;
    const vedge = state.vedge.slice();
    vedge[vIndex(w, x, y)] ^= 1;
    return makeState(w, h, state.grid, vedge, state.hedge, state.cheated);
  },

  preferredTileSize: 32,
  computeSize(p, t) {
    const bd = border(t);
    return { w: p.w * t + 2 * bd, h: p.h * t + 2 * bd };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, grid, vedge, hedge, regions } = state;
    const t = ds.tileSize;
    const bd = border(t);
    const flash = flashOn(flashTime, FLASH_FRAME);
    const px = (x: number) => bd + x * t;
    const py = (y: number) => bd + y * t;

    dr.rect(px(0), py(0), w * t, h * t, flash ? 'shade' : 'paper');

    // Closed rectangles: correct ones are shaded. A closed rectangle can never be right
    // if it has no number (hatched) or one number of the wrong size (number in red); one
    // holding several numbers may still be carved up, so it is left alone.
    const wrong = new Set<number>();
    for (const r of regions) {
      if (r.valid) {
        if (!flash) dr.rect(px(r.x), py(r.y), r.w * t, r.h * t, 'shade');
      } else if (r.numbers.length === 0) {
        dr.hatch(px(r.x), py(r.y), r.w * t, r.h * t, 'error', t * 0.4, Math.PI / 4, 1, {
          alpha: 0.35,
        });
      } else if (r.numbers.length === 1) {
        for (let y = r.y; y < r.y + r.h; y++)
          for (let x = r.x; x < r.x + r.w; x++) if (grid[y * w + x]) wrong.add(y * w + x);
      }
    }

    // Dotted grid.
    const dash = [Math.max(2, t * 0.09), Math.max(2, t * 0.11)];
    for (let x = 1; x < w; x++) dr.line(px(x), py(0), px(x), py(h), 'faint', 1.2, { dash });
    for (let y = 1; y < h; y++) dr.line(px(0), py(y), px(w), py(y), 'faint', 1.2, { dash });

    // Numbers.
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const n = grid[y * w + x];
        if (!n) continue;
        dr.text(px(x) + t / 2, py(y) + t / 2, String(n), {
          size: t * 0.5,
          colour: flash ? 'ok' : wrong.has(y * w + x) ? 'error' : 'ink',
          maxWidth: t * 0.85,
        });
      }
    }

    // Drawn edges, merged into runs so each stroke is one sketched line.
    const ew = Math.max(2.4, t * EDGE_WIDTH);
    for (let y = 1; y < h; y++) {
      for (let x = 0; x < w;) {
        if (!hedge[hIndex(w, x, y)]) {
          x++;
          continue;
        }
        const x0 = x;
        while (x < w && hedge[hIndex(w, x, y)]) x++;
        dr.line(px(x0), py(y), px(x), py(y), 'ink', ew);
      }
    }
    for (let x = 1; x < w; x++) {
      for (let y = 0; y < h;) {
        if (!vedge[vIndex(w, x, y)]) {
          y++;
          continue;
        }
        const y0 = y;
        while (y < h && vedge[vIndex(w, x, y)]) y++;
        dr.line(px(x), py(y0), px(x), py(y), 'ink', ew);
      }
    }

    dr.rectOutline(px(0), py(0), w * t, h * t, 'ink', { width: ew });

    // The rectangle being dragged out.
    if (ui.dragged && ui.x1 >= 0 && (ui.x1 !== ui.x2 || ui.y1 !== ui.y2)) {
      const colour = ui.erasing ? 'blue' : 'accent';
      const opts = { width: ew, alpha: 0.85 };
      if (ui.x1 === ui.x2 || ui.y1 === ui.y2) {
        dr.line(px(ui.x1), py(ui.y1), px(ui.x2), py(ui.y2), colour, ew, opts);
      } else {
        dr.rectOutline(
          px(ui.x1),
          py(ui.y1),
          (ui.x2 - ui.x1) * t,
          (ui.y2 - ui.y1) * t,
          colour,
          opts,
        );
      }
    }

    if (ui.cursorVisible) {
      const inset = t * 0.12;
      dr.cursor(px(ui.cx) + inset, py(ui.cy) + inset, t - 2 * inset, t - 2 * inset, 'accent', 2.2);
    }

    let status = '';
    if (ui.dragged && ui.x1 >= 0)
      status = tr('games.rect.status.drag', { w: ui.x2 - ui.x1, h: ui.y2 - ui.y1 });
    // Only while the board is actually finished: an edge drawn after Solve undoes it.
    if (state.completed) status += tr(state.cheated ? 'status.autoSolved' : 'status.completed');
    dr.statusBar(status);
  },

  animLength: () => 0,
  flashLength(oldState, newState) {
    return !oldState.completed && newState.completed && !oldState.cheated && !newState.cheated
      ? 3 * FLASH_FRAME
      : 0;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: true,
  isTimed: false,
  // Five rectangles of the solution to the 7×7 puzzle the menu thumbnail shows (seed
  // `thumbnail:rect`), so the preview looks half played. A unit test keeps these in step
  // with the generator.
  thumbnailMoves: ['R0,0,2,4', 'R2,0,5,1', 'R3,1,4,2', 'R6,4,1,3', 'R0,6,2,1'],
});

export default game;
