import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { MapParams } from './generator';
import type { MapState } from './index';
import { DIFF_HARD, DIFF_RECURSE } from './solver';

type C = typeof PALETTE;

/**
 * Four countries in the game's four colours, cut from the square (x, y, x+s, y+s) along
 * crooked borders.
 */
function atlas(c: C, x: number, y: number, s: number): string {
  const P = (px: number, py: number) =>
    `${(x + (px * s) / 60).toFixed(1)} ${(y + (py * s) / 60).toFixed(1)}`;
  const region = (d: string, fill: string) =>
    `<path d="${d}" fill="${fill}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>`;
  return (
    region(`M${P(0, 0)} L${P(34, 0)} L${P(30, 22)} L${P(0, 30)} Z`, c.red) +
    region(`M${P(34, 0)} L${P(60, 0)} L${P(60, 36)} L${P(42, 34)} L${P(30, 22)} Z`, c.blue) +
    region(`M${P(0, 30)} L${P(30, 22)} L${P(42, 34)} L${P(26, 60)} L${P(0, 60)} Z`, c.yellow) +
    region(`M${P(42, 34)} L${P(60, 36)} L${P(60, 60)} L${P(26, 60)} Z`, c.green) +
    `<rect x="${x}" y="${y}" width="${s}" height="${s}" fill="none" stroke="${c.ink}" stroke-width="5" stroke-linejoin="round"/>`
  );
}

/** Some region that had a colour was given another one, or cleared. */
function recoloured(history: readonly MapState[]): boolean {
  for (let k = 1; k < history.length; k++) {
    const a = history[k - 1].colouring;
    const b = history[k].colouring;
    for (let i = 0; i < a.length; i++) if (a[i] >= 0 && b[i] !== a[i]) return true;
  }
  return false;
}

export const achievements = defineAchievements<MapParams, MapState>([
  {
    id: 'no-dots',
    name: 'Freehand Atlas',
    description: 'Solve a Hard Map or harder without a single pencil dot.',
    tier: 'silver',
    hue: 'blue',
    art: (c) =>
      atlas(c, 17, 17, 56) +
      // The pencil dots nobody drew, in a red no-entry ring.
      `<circle cx="70" cy="70" r="13" fill="${c.paper}" stroke="${c.red}" stroke-width="4.5"/>` +
      `<circle cx="64.5" cy="64.5" r="3.8" fill="${c.green}"/><circle cx="75.5" cy="75.5" r="3.8" fill="${c.blue}"/>` +
      `<path d="M61 79 L79 61" stroke="${c.red}" stroke-width="4.5" stroke-linecap="round"/>`,
    test: (ctx) =>
      ctx.params.diff >= DIFF_HARD && ctx.history.every((s) => !s.pencil.some((p) => p)),
  },
  {
    id: 'steady-brush',
    name: 'Steady Brush',
    description: "Solve an Extreme Map without ever changing a region's colour.",
    tier: 'gold',
    hue: 'green',
    art: (c) =>
      atlas(c, 16, 16, 50) +
      // A brush laying down the last colour, in one go.
      `<g transform="rotate(-45 64 64)">` +
      `<path d="M58 70 H70 V90 Q64 94 58 90 Z" fill="${c.brown}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
      `<path d="M57 60 H71 V70 H57 Z" fill="${c.lowlight}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
      `<path d="M57 60 Q56 48 64 40 Q72 48 71 60 Z" fill="${c.green}" stroke="${c.ink}" stroke-width="3.5" stroke-linejoin="round"/>` +
      `</g>`,
    test: (ctx) => ctx.params.diff >= DIFF_RECURSE && !recoloured(ctx.history),
  },
]);
