/**
 * The Puzzlebox mark: one box, one grid, one piece dropping into it.
 *
 * There is exactly one definition of the logo and everything draws from it — the favicon,
 * the splash, the menu masthead, the play page's back rail and the store covers generated
 * by `scripts/covers.mjs`. Before this existed the splash drew its own box-and-cross, the
 * favicon carried a second hand-written copy of the same shape in a data URI, and the
 * masthead was a wordmark with no mark at all, so "the logo" was three different pictures
 * depending on where you looked.
 *
 * The geometry is deliberately coarse. A portal shows this at 16px in a browser tab and in
 * a 800×800 store tile, so the mark is four strokes and one filled tile: the box reads as a
 * container, the grid says the contents are puzzles, and the tilted accent piece — the only
 * saturated thing in it — is what stops it being a generic "grid" glyph at small sizes.
 */
import { PALETTE } from '../framework/palette';

/** The box, drawn as a path (not a `<rect>`) so the splash can stroke-dash it on. */
export const BRAND_BOX_PATH =
  'M22 9 H78 A13 13 0 0 1 91 22 V78 A13 13 0 0 1 78 91 H22 A13 13 0 0 1 9 78 V22 A13 13 0 0 1 22 9 Z';
export const BRAND_BAR_H = 'M26 50 H74';
export const BRAND_BAR_V = 'M50 26 V74';
/**
 * The piece: a tilted square straddling the box's top-right corner, so it reads as going
 * *into* the box rather than as a coloured cell already in it. Sized and placed to clear
 * both grid bars, and to stay inside the viewBox once rotated and stroked — the favicon
 * renders the same path with no room to overflow into.
 */
export const BRAND_PIECE =
  'M68 6 H86 A6 6 0 0 1 92 12 V30 A6 6 0 0 1 86 36 H68 A6 6 0 0 1 62 30 V12 A6 6 0 0 1 68 6 Z';

export interface BrandMarkOptions {
  /** Rendered size in px. Omit to let CSS size it. */
  size?: number;
  /** Class on the `<svg>`, so the splash can keep animating its own copy. */
  className?: string;
  /** Colours. Default to the live palette; the cover script overrides for flat art. */
  ink?: string;
  accent?: string;
  paper?: string;
  /** Include the tilted piece. The favicon keeps it; a 16px tab icon needs the colour. */
  piece?: boolean;
}

/**
 * The mark as an SVG string. Returned as markup rather than a node because every consumer
 * wants it in a different place — `innerHTML` of a splash overlay, a masthead lockup, a
 * data URI for `<link rel=icon>`, a standalone file for the covers.
 */
export function brandMarkSVG(opts: BrandMarkOptions = {}): string {
  const {
    size,
    className = 'brand-mark',
    ink = PALETTE.ink,
    accent = PALETTE.accent,
    paper = PALETTE.paper,
    piece = true,
  } = opts;
  const dim = size ? ` width="${size}" height="${size}"` : '';
  return `<svg class="${className}" viewBox="0 0 100 100"${dim} fill="none" aria-hidden="true">
  <path class="brand-box" d="${BRAND_BOX_PATH}" fill="${paper}" stroke="${ink}" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>
  <path class="brand-bar brand-bar-h" d="${BRAND_BAR_H}" stroke="${ink}" stroke-width="5" stroke-linecap="round" opacity="0.55"/>
  <path class="brand-bar brand-bar-v" d="${BRAND_BAR_V}" stroke="${ink}" stroke-width="5" stroke-linecap="round" opacity="0.55"/>
  ${piece ? `<path class="brand-piece" d="${BRAND_PIECE}" fill="${accent}" stroke="${ink}" stroke-width="5" stroke-linejoin="round" transform="rotate(-12 77 21)"/>` : ''}
</svg>`;
}

/**
 * The same mark packed into a `data:` URI for `<link rel="icon">`.
 *
 * `#` has to be percent-encoded or the URI ends at the first colour, which is the classic
 * way a hand-written SVG favicon silently becomes a blank tab.
 */
export function brandFaviconDataURI(): string {
  const svg = brandMarkSVG({ className: 'f' })
    .replace(/\n\s*/g, ' ')
    .replace(/#/g, '%23')
    .replace(/"/g, "'");
  return `data:image/svg+xml,${svg}`;
}

/**
 * Point the tab icon and the browser's UI colour at the mark, at boot.
 *
 * Done here rather than as a static data URI in `index.html` so that the logo has exactly
 * one definition: a second copy pasted into the HTML is a copy that silently goes stale the
 * first time the mark or the accent colour changes, which is precisely what had happened.
 */
export function applyBrandToDocument(doc: Document = document): void {
  let icon = doc.querySelector<HTMLLinkElement>('link[rel="icon"]');
  if (!icon) {
    icon = doc.createElement('link');
    icon.rel = 'icon';
    doc.head.append(icon);
  }
  icon.type = 'image/svg+xml';
  icon.href = brandFaviconDataURI();

  let theme = doc.querySelector<HTMLMetaElement>('meta[name="theme-color"]');
  if (!theme) {
    theme = doc.createElement('meta');
    theme.name = 'theme-color';
    doc.head.append(theme);
  }
  theme.content = PALETTE.paper;
}
