/**
 * Deductive Minesweeper solver.
 *
 * Knowledge about the grid is an `Int8Array`: `UNKNOWN` (-2) for a covered square,
 * `MINE` (-1) for a square known to hold a mine, and 0–8 for an open square with its
 * neighbour count. The solver reasons with small *sets*: a 3×3 window (top-left corner
 * `x`,`y`, 9-bit `mask` of member squares) together with the number of mines it holds.
 * Every open number contributes one set (its still-unknown neighbours), and the rules are
 *
 *  - a set with no mines, or as many mines as squares, is settled outright;
 *  - if two overlapping sets differ in mine count by exactly the size of one set's
 *    private part, that part is all mines and the other's private part all clear;
 *  - when one set is a subset of another, the difference becomes a set of its own;
 *  - when all that fails and the total mine count is known, every disjoint union of the
 *    remaining sets (up to ten of them) is tried, looking for one that pins down the
 *    squares outside it as all mines or all clear.
 *
 * When even that stalls, an optional `perturb` callback may rearrange mines in the
 * hidden grid to make progress possible; the generator uses this to build grids that are
 * solvable from the first click without guessing.
 */
import { tx } from '../../i18n';
import type { Random } from '../../framework/rng';

export const UNKNOWN = -2;
export const MINE = -1;

export interface MineSet {
  x: number;
  y: number;
  mask: number;
  mines: number;
  todo: boolean;
}

/** One square changed by a perturbation: +1 it became a mine, -1 it was cleared. */
export interface Perturbation {
  x: number;
  y: number;
  delta: 1 | -1;
}

/** Reveal the number under a square known to be safe (-1 if it holds a mine). */
export type OpenFn = (x: number, y: number) => number;
/**
 * Rearrange the hidden grid so that the set (`x`, `y`, `mask`; mask 0 means "all
 * unknown squares") becomes either all mines or all clear, updating `grid` to match.
 * Returns the changes made, or null if it declined.
 */
export type PerturbFn = (
  grid: Int8Array,
  x: number,
  y: number,
  mask: number,
) => Perturbation[] | null;

const LEFT_COL = 0o111;
const RIGHT_COL = 0o444;
const TOP_ROW = 0o007;
const BOTTOM_ROW = 0o700;

export function popcount9(mask: number): number {
  let n = 0;
  for (let m = mask & 511; m; m &= m - 1) n++;
  return n;
}

/**
 * Re-express a 3×3 mask whose window origin is offset by (dx, dy) from ours in our own
 * window; squares that fall outside our window are dropped.
 */
export function shiftMask(mask: number, dx: number, dy: number): number {
  if (dx >= 3 || dx <= -3 || dy >= 3 || dy <= -3) return 0;
  let m = mask & 511;
  for (; dx > 0; dx--) m = (m & ~RIGHT_COL) << 1;
  for (; dx < 0; dx++) m = (m & ~LEFT_COL) >> 1;
  for (; dy > 0; dy--) m = (m & ~BOTTOM_ROW) << 3;
  for (; dy < 0; dy++) m = (m & ~TOP_ROW) >> 3;
  return m & 511;
}

/** Squares of set 1 that are also in set 2, as a mask in set 1's window. */
export function maskAnd(x1: number, y1: number, m1: number, x2: number, y2: number, m2: number) {
  return m1 & shiftMask(m2, x2 - x1, y2 - y1);
}

/** Squares of set 1 that are not in set 2, as a mask in set 1's window. */
export function maskMinus(x1: number, y1: number, m1: number, x2: number, y2: number, m2: number) {
  return m1 & ~shiftMask(m2, x2 - x1, y2 - y1) & 511;
}

/** All current sets, indexed by window origin, plus a FIFO of sets awaiting attention. */
class SetStore {
  readonly all = new Set<MineSet>();
  private byOrigin = new Map<number, MineSet[]>();
  private queue: MineSet[] = [];

  constructor(private w: number) {}

  private key(x: number, y: number): number {
    return y * (this.w + 3) + x;
  }

  /** Add a set (normalising its window); duplicates are ignored. */
  add(x: number, y: number, mask: number, mines: number): void {
    while (!(mask & LEFT_COL)) {
      mask >>= 1;
      x++;
    }
    while (!(mask & TOP_ROW)) {
      mask >>= 3;
      y++;
    }
    const k = this.key(x, y);
    let bucket = this.byOrigin.get(k);
    if (!bucket) {
      bucket = [];
      this.byOrigin.set(k, bucket);
    } else if (bucket.some((s) => s.mask === mask)) {
      return;
    }
    const s: MineSet = { x, y, mask, mines, todo: false };
    bucket.push(s);
    this.all.add(s);
    this.enqueue(s);
  }

  remove(s: MineSet): void {
    this.all.delete(s);
    const k = this.key(s.x, s.y);
    const bucket = this.byOrigin.get(k)!;
    bucket.splice(bucket.indexOf(s), 1);
    if (bucket.length === 0) this.byOrigin.delete(k);
    s.todo = false; // a dead set left in the queue is skipped when dequeued
  }

  enqueue(s: MineSet): void {
    if (s.todo) return;
    s.todo = true;
    this.queue.push(s);
  }

  dequeue(): MineSet | null {
    while (this.queue.length) {
      const s = this.queue.shift()!;
      if (s.todo && this.all.has(s)) {
        s.todo = false;
        return s;
      }
    }
    return null;
  }

  /** Every stored set sharing at least one square with the given set. */
  overlapping(x: number, y: number, mask: number): MineSet[] {
    const out: MineSet[] = [];
    for (let yy = Math.max(0, y - 2); yy <= y + 2; yy++) {
      for (let xx = Math.max(0, x - 2); xx <= x + 2; xx++) {
        const bucket = this.byOrigin.get(this.key(xx, yy));
        if (!bucket) continue;
        for (const s of bucket) if (maskAnd(x, y, mask, s.x, s.y, s.mask)) out.push(s);
      }
    }
    return out;
  }
}

/** Solver limits: sets to try in the global mine-count search, and perturbations before giving up. */
const MAX_GLOBAL_SETS = 10;
const MAX_PERTURBS = 2000;

/**
 * Fill in as much of `grid` as can be deduced. `n` is the total mine count, or -1 if it
 * is not known (which disables the global deduction). Returns -1 if the solver stalled
 * with unknown squares left, 0 if it finished without help, or the number of
 * perturbations that were needed.
 */
export function solveMines(
  w: number,
  h: number,
  n: number,
  grid: Int8Array,
  open: OpenFn,
  perturb: PerturbFn | null = null,
  rng: Random | null = null,
): number {
  const store = new SetStore(w);
  const squares: number[] = [];
  for (let i = 0; i < w * h; i++) if (grid[i] !== UNKNOWN) squares.push(i);
  let nperturbs = 0;

  /** Record every square of a set as a mine or as safe (opening safe ones). */
  const settle = (x: number, y: number, mask: number, mine: boolean) => {
    for (let bit = 0, dy = 0; dy < 3; dy++) {
      for (let dx = 0; dx < 3; dx++, bit++) {
        if (!(mask & (1 << bit))) continue;
        const i = (y + dy) * w + (x + dx);
        if (grid[i] !== UNKNOWN) continue;
        if (mine) {
          grid[i] = MINE;
        } else {
          const v = open(x + dx, y + dy);
          if (v < 0) throw new Error(tx`Mines solver opened a mine: inconsistent knowledge`);
          grid[i] = v;
        }
        squares.push(i);
      }
    }
  };

  for (;;) {
    let progress = false;

    // Newly known squares: give each open number its set, and prune every set that
    // contained the square.
    while (squares.length) {
      const i = squares.shift()!;
      const x = i % w;
      const y = (i - x) / w;
      if (grid[i] >= 0) {
        let mines = grid[i];
        let mask = 0;
        for (let bit = 0, dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++, bit++) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;
            const v = grid[ny * w + nx];
            if (v === MINE) mines--;
            else if (v === UNKNOWN) mask |= 1 << bit;
          }
        }
        if (mask) store.add(x - 1, y - 1, mask, mines);
      }
      for (const s of store.overlapping(x, y, 1)) {
        const rest = maskMinus(s.x, s.y, s.mask, x, y, 1);
        const mines = s.mines - (grid[i] === MINE ? 1 : 0);
        if (rest) store.add(s.x, s.y, rest, mines);
        store.remove(s);
      }
      progress = true;
    }

    const s = store.dequeue();
    if (s) {
      if (s.mines === 0 || s.mines === popcount9(s.mask)) {
        settle(s.x, s.y, s.mask, s.mines !== 0);
        continue;
      }
      for (const t of store.overlapping(s.x, s.y, s.mask)) {
        if (t === s) continue;
        const sOnly = maskMinus(s.x, s.y, s.mask, t.x, t.y, t.mask);
        const tOnly = maskMinus(t.x, t.y, t.mask, s.x, s.y, s.mask);
        const sc = popcount9(sOnly);
        const tc = popcount9(tOnly);
        // Mine-count difference equal to one private part: that part is all mines and
        // the other private part all clear.
        if (sc === s.mines - t.mines || tc === t.mines - s.mines) {
          settle(s.x, s.y, sOnly, sc === s.mines - t.mines);
          settle(t.x, t.y, tOnly, tc === t.mines - s.mines);
          continue;
        }
        // Subset: the difference has a mine count of its own.
        if (sc === 0 && tc !== 0) store.add(t.x, t.y, tOnly, t.mines - s.mines);
        else if (tc === 0 && sc !== 0) store.add(s.x, s.y, sOnly, s.mines - t.mines);
      }
      progress = true;
    } else if (n >= 0) {
      // Local reasoning is exhausted; bring in the total mine count.
      let minesLeft = n;
      let squaresLeft = 0;
      for (let i = 0; i < w * h; i++) {
        if (grid[i] === MINE) minesLeft--;
        else if (grid[i] === UNKNOWN) squaresLeft++;
      }
      if (squaresLeft === 0) break;
      if (minesLeft === 0 || minesLeft === squaresLeft) {
        for (let i = 0; i < w * h; i++)
          if (grid[i] === UNKNOWN) settle(i % w, Math.floor(i / w), 1, minesLeft !== 0);
        continue;
      }
      if (
        store.all.size <= MAX_GLOBAL_SETS &&
        globalDeduce(store, grid, w, h, minesLeft, squaresLeft, settle)
      )
        progress = true;
    }

    if (progress) continue;

    // Stuck. Ask for the hidden grid to be rearranged, if we may.
    if (perturb && nperturbs < MAX_PERTURBS) {
      nperturbs++;
      let changes: Perturbation[] | null;
      if (store.all.size === 0) {
        changes = perturb(grid, 0, 0, 0);
      } else {
        const sets = [...store.all];
        const pick = sets[rng ? rng.upto(sets.length) : 0];
        changes = perturb(grid, pick.x, pick.y, pick.mask);
      }
      if (changes && changes.length) {
        for (const c of changes) {
          const i = c.y * w + c.x;
          // A known square that lost its mine is now an open number and needs a set.
          if (c.delta < 0 && grid[i] !== UNKNOWN) squares.push(i);
          for (const t of store.overlapping(c.x, c.y, 1)) {
            t.mines += c.delta;
            store.enqueue(t);
          }
        }
        continue;
      }
    }
    break;
  }

  for (let i = 0; i < w * h; i++) if (grid[i] === UNKNOWN) return -1;
  return nperturbs;
}

/**
 * Try every union of pairwise-disjoint sets; if the squares outside some union must be
 * all mines or all clear, settle them. Returns true if anything was deduced.
 */
function globalDeduce(
  store: SetStore,
  grid: Int8Array,
  w: number,
  h: number,
  minesLeft: number,
  squaresLeft: number,
  settle: (x: number, y: number, mask: number, mine: boolean) => void,
): boolean {
  const sets = [...store.all];
  const used: boolean[] = new Array(sets.length).fill(false);

  const outside = (x: number, y: number) =>
    sets.every((s, j) => !used[j] || !maskAnd(s.x, s.y, s.mask, x, y, 1));

  const search = (idx: number, mines: number, squares: number): boolean => {
    if (idx === sets.length) {
      if (squares <= 0 || (mines !== 0 && mines !== squares)) return false;
      for (let i = 0; i < w * h; i++) {
        if (grid[i] !== UNKNOWN) continue;
        const x = i % w;
        const y = (i - x) / w;
        if (outside(x, y)) settle(x, y, 1, mines !== 0);
      }
      return true;
    }
    const s = sets[idx];
    let disjoint = true;
    for (let j = 0; j < idx; j++) {
      if (used[j] && maskAnd(s.x, s.y, s.mask, sets[j].x, sets[j].y, sets[j].mask)) {
        disjoint = false;
        break;
      }
    }
    if (disjoint) {
      used[idx] = true;
      if (search(idx + 1, mines - s.mines, squares - popcount9(s.mask))) return true;
      used[idx] = false;
    }
    return search(idx + 1, mines, squares);
  };

  return search(0, minesLeft, squaresLeft);
}
