import { tx } from '../../i18n';
import { defineGame } from '../../framework/types';
import type { ConfigItem, DrawState } from '../../framework/types';
import {
  CURSOR_SELECT2,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  MIDDLE_BUTTON,
  MOD_CTRL,
  MOD_SHFT,
  RIGHT_BUTTON,
  isCursorMove,
  isCursorSelect,
  moveCursor,
  stripMods,
} from '../../framework/input';
import {
  clamp,
  flashOn,
  hintFlashCell,
  hintFlashing,
  markHint,
  noHint,
  parseWxH,
  takeHintFlash,
  type HintMark,
} from '../../framework/grid';
import type { Drawing } from '../../framework/drawing';
import { ERASE_GLYPH } from '../../framework/glyphs';
import type { Random } from '../../framework/rng';
import {
  EMPTY,
  FULL,
  UNKNOWN,
  cluesOf,
  encodeClues,
  gridMatchesClues,
  lineHasError,
  parseDesc,
  readLine,
  runsOf,
  sameRuns,
} from './clues';
import type { Clues } from './clues';
import { generateSoluble } from './generator';
import { LineSolver, solveGrid } from './solver';
import help from './help.md?raw';
import { achievements } from './achievements';
import { tutorial } from './tutorial';

export interface PatternParams {
  w: number;
  h: number;
}

export interface PatternState {
  w: number;
  h: number;
  clues: Clues;
  /** `EMPTY`, `FULL` or `UNKNOWN` per cell, row-major. */
  grid: Uint8Array;
  /** Every row and column currently matches its clue. */
  completed: boolean;
  /** Solve was used to reach this state. */
  cheated: boolean;
}

export interface PatternUI extends HintMark {
  cx: number;
  cy: number;
  cursorVisible: boolean;
  dragging: boolean;
  /** Drag and release codes of the button that started the current gesture. */
  dragButton: number;
  releaseButton: number;
  /** Value being painted, and the state a cell must currently have to be affected (-1: any). */
  dragValue: number;
  dragFrom: number;
  /** Cells where the drag started and where it currently is. */
  sx: number;
  sy: number;
  ex: number;
  ey: number;
  /**
   * The Erase tool: a left click or drag wipes squares back to unknown, as a middle-click
   * or middle-drag does, clearing a whole rectangle whatever is in it.
   */
  erase: boolean;
}

/** Random grids that the line solver can finish get rare quickly beyond this. */
const MAX_SIDE = 40;
/**
 * Squares a generated grid may have. Line-solvable pictures thin out steeply with size:
 * 35×35 needs about 20 random pictures, 40×40 about 220 and sometimes well over 1000, at
 * a few milliseconds each, which froze the page for five seconds and more. A shared
 * puzzle up to `MAX_SIDE` on a side still loads.
 */
const MAX_GEN_AREA = 35 * 35;
const FLASH_FRAME = 0.13;
/** Layout fractions of the tile size. */
const BORDER = 0.3;
const GUTTER = 0.3;
const PITCH = 0.8;
/** Move letters indexed by cell value (EMPTY, FULL, UNKNOWN). */
const VALUE_CHARS = ['E', 'F', 'U'];
const MOVE_RE = /^([EFU])(\d+),(\d+),(\d+),(\d+)(?:,([EFU]))?$/;

/** Number of clue positions reserved beside a line of `d` cells (same rule as the original). */
export function clueSlots(d: number): number {
  return Math.floor(d / 5) + 2;
}

interface Geometry {
  t: number;
  border: number;
  gutter: number;
  /** Spacing between clue numbers. */
  pitch: number;
  /** Top-left corner of the grid. */
  gx: number;
  gy: number;
}

export function geometry(p: { w: number; h: number }, t: number): Geometry {
  const border = Math.round(t * BORDER);
  const gutter = Math.round(t * GUTTER);
  const pitch = t * PITCH;
  return {
    t,
    border,
    gutter,
    pitch,
    gx: border + Math.round(clueSlots(p.w) * pitch) + gutter,
    gy: border + Math.round(clueSlots(p.h) * pitch) + gutter,
  };
}

/** `F3,4,5,1` paints FULL over the 5×1 rectangle at (3,4); a trailing `,U` limits it to unknown cells. */
export function paintMove(
  value: number,
  x: number,
  y: number,
  w: number,
  h: number,
  from = -1,
): string {
  return `${VALUE_CHARS[value]}${x},${y},${w},${h}${from >= 0 ? `,${VALUE_CHARS[from]}` : ''}`;
}

/** The finished grid: the generator's own answer where there is one, else solved afresh. */
function solutionOf(state: PatternState, aux: string | undefined): Uint8Array {
  const { w, h, clues } = state;
  const n = w * h;
  if (aux && aux.length === n + 1 && aux[0] === 'S' && /^[01]+$/.test(aux.slice(1))) {
    const grid = new Uint8Array(n);
    for (let i = 0; i < n; i++) grid[i] = aux[i + 1] === '1' ? FULL : EMPTY;
    if (gridMatchesClues(grid, w, h, clues)) return grid;
  }
  const r = solveGrid(w, h, clues);
  if (!r.solved) throw new Error(tx`Solving algorithm cannot complete this puzzle`);
  return r.grid;
}

function solutionMove(grid: Uint8Array): string {
  let s = 'S';
  for (let i = 0; i < grid.length; i++) s += grid[i] === FULL ? '1' : '0';
  return s;
}

/** The rectangle of the current drag as inclusive cell bounds. */
function dragRect(ui: PatternUI) {
  return {
    x1: Math.min(ui.sx, ui.ex),
    y1: Math.min(ui.sy, ui.ey),
    x2: Math.max(ui.sx, ui.ex),
    y2: Math.max(ui.sy, ui.ey),
  };
}

/** The grid as it will look if the drag in progress is released now. */
function previewGrid(state: PatternState, ui: PatternUI): Uint8Array {
  const grid = state.grid.slice();
  const { x1, y1, x2, y2 } = dragRect(ui);
  for (let y = y1; y <= y2; y++) {
    for (let x = x1; x <= x2; x++) {
      const i = y * state.w + x;
      if (ui.dragFrom < 0 || grid[i] === ui.dragFrom) grid[i] = ui.dragValue;
    }
  }
  return grid;
}

function drawClue(
  dr: Drawing,
  g: Geometry,
  isColumn: boolean,
  index: number,
  clue: number[],
  lineLength: number,
  colour: string,
): void {
  // An all-white line reads 0, as nonograms write it: a blank clue looks like a missing one.
  if (!clue.length) clue = [0];
  const n = clue.length;
  const slots = clueSlots(lineLength);
  // Numbers sit at one pitch apart, right- or bottom-aligned against the grid; a list
  // longer than the reserved space is squashed to fit.
  const pitch = n <= slots ? g.pitch : (slots * g.pitch) / n;
  const size = Math.min(g.t * 0.62, pitch * 0.78);
  const along = (isColumn ? g.gx : g.gy) + index * g.t + g.t / 2;
  const edge = (isColumn ? g.gy : g.gx) - g.gutter;
  for (let j = 0; j < n; j++) {
    const away = edge - pitch * (n - 1 - j + 0.5);
    dr.text(isColumn ? along : away, isColumn ? away : along, String(clue[j]), {
      size,
      colour,
      maxWidth: Math.min(g.t, pitch) * 0.95,
    });
  }
}

const game = defineGame<PatternParams, PatternState, PatternUI>({
  id: 'pattern',
  name: 'Pattern',
  description: 'Fill in the grid from the run lengths given for every row and column.',
  alsoKnownAs: 'Nonogram, Picross, Griddlers',
  menuTier: 1,
  help,
  tutorial,
  achievements,
  presets: [10, 15, 20, 25, 30].map((d) => ({ name: `${d}×${d}`, params: { w: d, h: d } })),
  // The smallest board the Type menu offers, rather than the original's default: a
  // newcomer's first puzzle should be one they can finish. See the other games' OPENING.
  defaultParams: () => ({ w: 10, h: 10 }),
  encodeParams: (p) => `${p.w}x${p.h}`,
  decodeParams(str) {
    const r = parseWxH(str);
    if (!r) throw new Error(tx`expected WxH`);
    return { w: r.w, h: r.h };
  },
  validateParams(p, full) {
    if (!Number.isInteger(p.w) || !Number.isInteger(p.h))
      return tx`Width and height must be whole numbers`;
    if (p.w < 1 || p.h < 1) return tx`Width and height must both be greater than zero`;
    if (p.w > MAX_SIDE || p.h > MAX_SIDE) return tx`Width and height must be at most ${MAX_SIDE}`;
    if (full && p.w * p.h > MAX_GEN_AREA)
      return tx`The grid can have at most ${MAX_GEN_AREA} squares`;
    return null;
  },
  configure(p): ConfigItem[] {
    return [
      { type: 'string', name: 'Width', value: String(p.w) },
      { type: 'string', name: 'Height', value: String(p.h) },
    ];
  },
  customParams(items) {
    // Whole numbers only: parseInt would quietly read "6.5" or "6x" as a size.
    const int = (s: string) => (/^-?\d+$/.test(s.trim()) ? parseInt(s, 10) : NaN);
    const w = int((items[0] as { value: string }).value);
    const h = int((items[1] as { value: string }).value);
    return { w, h };
  },

  newDesc(p, rng: Random) {
    const grid = generateSoluble(p.w, p.h, rng);
    return { desc: encodeClues(cluesOf(grid, p.w, p.h)), aux: solutionMove(grid) };
  },

  validateDesc(p, desc) {
    const r = parseDesc(desc, p.w, p.h);
    return typeof r === 'string' ? r : null;
  },

  newGame(p, desc) {
    const clues = parseDesc(desc, p.w, p.h) as Clues;
    return {
      w: p.w,
      h: p.h,
      clues,
      grid: new Uint8Array(p.w * p.h).fill(UNKNOWN),
      completed: false,
      cheated: false,
    };
  },

  canSolve: true,
  solve(_orig, curr, aux) {
    const n = curr.w * curr.h;
    if (aux && aux.length === n + 1 && aux[0] === 'S') return aux;
    const r = solveGrid(curr.w, curr.h, curr.clues);
    if (!r.solved) throw new Error(tx`Solving algorithm cannot complete this puzzle`);
    return solutionMove(r.grid);
  },

  /**
   * One cell. A cell that contradicts the answer is put right first; otherwise the first
   * cell that a single row or column settles from what is already on the board is filled
   * in — the same one-line reasoning the puzzle is built to be solvable by, so the hint
   * is always a deduction the player could have made themselves.
   */
  hint(_orig, curr, aux, ui) {
    const { w, h, grid, clues } = curr;
    if (curr.completed) return null;
    const solution = solutionOf(curr, aux);
    const cell = (i: number, v: number) =>
      markHint(ui, i, paintMove(v, i % w, Math.floor(i / w), 1, 1));

    for (let i = 0; i < w * h; i++) {
      if (grid[i] !== UNKNOWN && grid[i] !== solution[i]) return cell(i, solution[i]);
    }
    const solver = new LineSolver(Math.max(w, h));
    const buf = new Uint8Array(Math.max(w, h));
    for (let line = 0; line < w + h; line++) {
      const len = readLine(grid, w, h, line, buf);
      const before = buf.slice(0, len);
      const clue = line < w ? clues.cols[line] : clues.rows[line - w];
      if (solver.solve(buf, len, clue) <= 0) continue;
      for (let j = 0; j < len; j++) {
        if (before[j] !== UNKNOWN || buf[j] === UNKNOWN) continue;
        const i = line < w ? j * w + line : (line - w) * w + j;
        if (buf[j] === solution[i]) return cell(i, buf[j]);
      }
    }
    // Nothing one line can settle on its own: hand over a cell anyway.
    for (let i = 0; i < w * h; i++) if (grid[i] === UNKNOWN) return cell(i, solution[i]);
    return null;
  },

  textFormat(s) {
    const rows: string[] = [];
    for (let y = 0; y < s.h; y++) {
      let row = '';
      for (let x = 0; x < s.w; x++) {
        const v = s.grid[y * s.w + x];
        row += v === FULL ? '#' : v === EMPTY ? '.' : '?';
      }
      rows.push(row);
    }
    return rows.join('\n');
  },

  newUI: () => ({
    ...noHint(),
    cx: 0,
    cy: 0,
    cursorVisible: false,
    dragging: false,
    dragButton: 0,
    releaseButton: 0,
    dragValue: UNKNOWN,
    dragFrom: -1,
    sx: 0,
    sy: 0,
    ex: 0,
    ey: 0,
    erase: false,
  }),

  actions: [
    {
      label: 'Erase',
      key: 'E',
      hud: true,
      glyph: ERASE_GLYPH,
      pressed: (_s, ui) => ui.erase,
      title: 'Click or drag to wipe squares back to unknown (E)',
    },
  ],
  // A finished picture is not left with a keyboard cursor sitting on it, as in the other
  // grid games.
  changedState(ui, old, next) {
    if (!old.completed && next.completed) ui.cursorVisible = false;
    // A drag still held when Undo, Solve or a hint changes the board is dropped rather than
    // painted over the new board at release. (The drag's own move comes after release.)
    ui.dragging = false;
  },

  interpretMove(state, ui, ds, mx, my, button) {
    const b = stripMods(button);
    const { w, h, grid } = state;
    const g = geometry(state, ds.tileSize);
    const cx = Math.floor((mx - g.gx) / g.t);
    const cy = Math.floor((my - g.gy) / g.t);
    const inside = cx >= 0 && cx < w && cy >= 0 && cy < h;

    if (b === 'e'.charCodeAt(0) || b === 'E'.charCodeAt(0)) {
      ui.erase = !ui.erase;
      return '';
    }
    if (b === LEFT_BUTTON || b === RIGHT_BUTTON || b === MIDDLE_BUTTON) {
      if (!inside) return null;
      const cur = grid[cy * w + cx];
      ui.dragging = true;
      ui.dragButton = b + (LEFT_DRAG - LEFT_BUTTON);
      ui.releaseButton = b + (LEFT_RELEASE - LEFT_BUTTON);
      if (b === MIDDLE_BUTTON || (b === LEFT_BUTTON && ui.erase)) {
        // Clearing: a free rectangle over every cell in it.
        ui.dragValue = UNKNOWN;
        ui.dragFrom = -1;
      } else {
        // Painting: the first cell decides whether we paint or clear, and only cells in
        // the same state as that first cell follow suit along the line.
        const paint = b === LEFT_BUTTON ? FULL : EMPTY;
        ui.dragValue = cur === paint ? UNKNOWN : paint;
        ui.dragFrom = cur;
      }
      ui.sx = ui.ex = cx;
      ui.sy = ui.ey = cy;
      ui.cursorVisible = false;
      return '';
    }
    if (ui.dragging && b === ui.dragButton) {
      let x = cx;
      let y = cy;
      if (ui.dragFrom >= 0) {
        // Snap a painting drag to a straight horizontal or vertical line.
        if (Math.abs(x - ui.sx) > Math.abs(y - ui.sy)) y = ui.sy;
        else x = ui.sx;
      }
      ui.ex = clamp(x, 0, w - 1);
      ui.ey = clamp(y, 0, h - 1);
      return '';
    }
    if (ui.dragging && b === ui.releaseButton) {
      ui.dragging = false;
      const { x1, y1, x2, y2 } = dragRect(ui);
      let needed = false;
      for (let y = y1; y <= y2 && !needed; y++) {
        for (let x = x1; x <= x2; x++) {
          const v = grid[y * w + x];
          if (v !== ui.dragValue && (ui.dragFrom < 0 || v === ui.dragFrom)) {
            needed = true;
            break;
          }
        }
      }
      if (!needed) return '';
      return paintMove(ui.dragValue, x1, y1, x2 - x1 + 1, y2 - y1 + 1, ui.dragFrom);
    }

    if (isCursorMove(b)) {
      const ox = ui.cx;
      const oy = ui.cy;
      const p = moveCursor(b, ui.cx, ui.cy, w, h);
      ui.cx = p.x;
      ui.cy = p.y;
      ui.cursorVisible = true;
      const ctrl = (button & MOD_CTRL) !== 0;
      const shift = (button & MOD_SHFT) !== 0;
      if (!ctrl && !shift) return '';
      // Ctrl paints black, Shift lays dots, both clear: over the cell left and the cell entered.
      const value = ctrl ? (shift ? UNKNOWN : FULL) : EMPTY;
      if (grid[oy * w + ox] === value && grid[ui.cy * w + ui.cx] === value) return '';
      return paintMove(
        value,
        Math.min(ox, ui.cx),
        Math.min(oy, ui.cy),
        Math.abs(ox - ui.cx) + 1,
        Math.abs(oy - ui.cy) + 1,
      );
    }
    if (isCursorSelect(b)) {
      if (!ui.cursorVisible) {
        ui.cursorVisible = true;
        return '';
      }
      const cur = grid[ui.cy * w + ui.cx];
      const paint = b === CURSOR_SELECT2 ? EMPTY : FULL;
      return paintMove(cur === paint ? UNKNOWN : paint, ui.cx, ui.cy, 1, 1);
    }
    return null;
  },

  executeMove(state, move) {
    const { w, h } = state;
    if (move[0] === 'S') {
      const bits = move.slice(1);
      if (bits.length !== w * h || !/^[01]+$/.test(bits)) return null;
      const grid = new Uint8Array(w * h);
      for (let i = 0; i < grid.length; i++) grid[i] = bits[i] === '1' ? FULL : EMPTY;
      if (!gridMatchesClues(grid, w, h, state.clues)) return null;
      return { ...state, grid, completed: true, cheated: true };
    }
    const m = MOVE_RE.exec(move);
    if (!m) return null;
    const value = VALUE_CHARS.indexOf(m[1]);
    const x1 = parseInt(m[2], 10);
    const y1 = parseInt(m[3], 10);
    const rw = parseInt(m[4], 10);
    const rh = parseInt(m[5], 10);
    if (rw < 1 || rh < 1 || x1 + rw > w || y1 + rh > h) return null;
    const from = m[6] ? VALUE_CHARS.indexOf(m[6]) : -1;
    let grid: Uint8Array | null = null;
    for (let y = y1; y < y1 + rh; y++) {
      for (let x = x1; x < x1 + rw; x++) {
        const i = y * w + x;
        const v = state.grid[i];
        if (v === value || (from >= 0 && v !== from)) continue;
        if (!grid) grid = state.grid.slice();
        grid[i] = value;
      }
    }
    if (!grid) return state;
    return { ...state, grid, completed: gridMatchesClues(grid, w, h, state.clues) };
  },

  preferredTileSize: 24,
  computeSize(p, t) {
    const g = geometry(p, t);
    return { w: g.gx + p.w * t + g.border, h: g.gy + p.h * t + g.border };
  },

  redraw(dr: Drawing, ds: DrawState, _old, state, _dir, ui, _anim, flashTime) {
    const { w, h, grid, clues } = state;
    const g = geometry(state, ds.tileSize);
    const t = g.t;
    const hintCell = hintFlashCell(ui, flashTime);
    // A hint owns the flash it asked for: only a completed grid recolours its clues.
    const flash = !hintFlashing(ui) && flashOn(flashTime, FLASH_FRAME);
    const view = ui.dragging ? previewGrid(state, ui) : grid;

    dr.rect(g.gx, g.gy, w * t, h * t, flash ? 'shade' : 'paper');

    const pad = Math.max(1, t * 0.08);
    const dotR = Math.max(1.5, t * 0.09);
    const black = flash ? 'ok' : 'ink';
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = y * w + x;
        const v = view[i];
        const px = g.gx + x * t;
        const py = g.gy + y * t;
        if (v === FULL) {
          dr.rect(px + pad, py + pad, t - 2 * pad, t - 2 * pad, black, black, {
            width: Math.max(1, t * 0.06),
            seed: i,
          });
        } else if (v === EMPTY) {
          dr.dot(px + t / 2, py + t / 2, dotR, 'pencil', { seed: i });
        }
      }
    }

    for (let x = 1; x < w; x++) {
      const heavy = x % 5 === 0;
      dr.line(
        g.gx + x * t,
        g.gy,
        g.gx + x * t,
        g.gy + h * t,
        heavy ? 'pencil' : 'faint',
        heavy ? 1.6 : 1.2,
      );
    }
    for (let y = 1; y < h; y++) {
      const heavy = y % 5 === 0;
      dr.line(
        g.gx,
        g.gy + y * t,
        g.gx + w * t,
        g.gy + y * t,
        heavy ? 'pencil' : 'faint',
        heavy ? 1.6 : 1.2,
      );
    }
    dr.rectOutline(g.gx, g.gy, w * t, h * t, 'ink', { width: 2.4 });

    if (ui.dragging) {
      const { x1, y1, x2, y2 } = dragRect(ui);
      dr.rectOutline(g.gx + x1 * t, g.gy + y1 * t, (x2 - x1 + 1) * t, (y2 - y1 + 1) * t, 'accent', {
        width: 1.6,
        alpha: 0.7,
      });
    }

    // Clues: grey once the line's black runs match, red when its finished runs cannot fit.
    const buf = new Uint8Array(Math.max(w, h));
    for (let i = 0; i < w + h; i++) {
      const len = readLine(grid, w, h, i, buf);
      const clue = i < w ? clues.cols[i] : clues.rows[i - w];
      const colour = flash
        ? 'ok'
        : lineHasError(buf, len, clue)
          ? 'error'
          : sameRuns(runsOf(buf, len), clue)
            ? 'pencil'
            : 'ink';
      drawClue(dr, g, i < w, i < w ? i : i - w, clue, len, colour);
    }

    if (hintCell >= 0) {
      dr.hintBox(g.gx + (hintCell % w) * t, g.gy + Math.floor(hintCell / w) * t, t, t);
    }

    if (ui.cursorVisible) {
      const inset = t * 0.1;
      const args = [
        g.gx + ui.cx * t + inset,
        g.gy + ui.cy * t + inset,
        t - 2 * inset,
        t - 2 * inset,
      ] as const;
      dr.cursor(...args, 'paper', 4.5);
      dr.cursor(...args, 'accent', 2.2);
    }
  },

  animLength: () => 0,
  flashLength(oldState, newState, _dir, ui) {
    const hint = takeHintFlash(ui);
    return !oldState.completed && newState.completed && !newState.cheated ? 3 * FLASH_FRAME : hint;
  },
  status: (s) => (s.completed ? 1 : 0),
  wantsStatusBar: false,
  isTimed: false,
  // The first five rows of the puzzle the menu thumbnail shows (seed `thumbnail:pattern`,
  // 10×10), so the preview looks half solved. A unit test keeps these in step with the
  // generator.
  thumbnailMoves: [
    'F0,0,1,1',
    'E1,0,6,1',
    'F7,0,3,1',
    'F0,1,3,1',
    'E3,1,1,1',
    'F4,1,1,1',
    'E5,1,1,1',
    'F6,1,4,1',
    'F0,2,2,1',
    'E2,2,2,1',
    'F4,2,2,1',
    'E6,2,2,1',
    'F8,2,2,1',
    'F0,3,3,1',
    'E3,3,1,1',
    'F4,3,1,1',
    'E5,3,5,1',
    'E0,4,4,1',
    'F4,4,2,1',
    'E6,4,4,1',
  ],
});

export default game;
