import { defineAchievements } from '../../framework/achievements';
import type { PALETTE } from '../../framework/palette';
import type { LightupParams, LightupState } from './index';
import { DIFF_HARD } from './solver';

type C = typeof PALETTE;

/** The game's bulb: a yellow glass with a filament, on a screw base. */
function bulb(c: C, cx: number, cy: number, r: number): string {
  const w = r * 0.5;
  const top = cy + r * 0.72;
  const bottom = cy + r * 1.45;
  return (
    `<path d="M${cx - w} ${top} H${cx + w} V${bottom} Q${cx} ${bottom + r * 0.3} ${cx - w} ${bottom} Z" fill="${c.lowlight}" stroke="${c.ink}" stroke-width="${r * 0.2}" stroke-linejoin="round"/>` +
    `<path d="M${cx - w} ${cy + r * 1.08} H${cx + w}" stroke="${c.ink}" stroke-width="${r * 0.14}"/>` +
    `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${c.yellow}" stroke="${c.ink}" stroke-width="${r * 0.2}"/>` +
    `<path d="M${cx - r * 0.35} ${cy + r * 0.72} V${cy + r * 0.1} L${cx - r * 0.12} ${cy - r * 0.22} L${cx + r * 0.12} ${cy + r * 0.1} L${cx + r * 0.35} ${cy - r * 0.22} V${cy + r * 0.72}" fill="none" stroke="${c.ink}" stroke-width="${r * 0.12}" stroke-linejoin="round"/>` +
    `<circle cx="${cx - r * 0.42}" cy="${cy - r * 0.42}" r="${r * 0.18}" fill="${c.highlight}"/>`
  );
}

/** Short rays all round a bulb, skipping the ones that would run into its base. */
function rays(c: C, cx: number, cy: number, r1: number, r2: number, w: number): string {
  let d = '';
  for (let i = 0; i < 8; i++) {
    if (i === 2) continue; // straight down: the base is there
    const a = (i * Math.PI) / 4;
    d += `M${(cx + Math.cos(a) * r1).toFixed(1)} ${(cy + Math.sin(a) * r1).toFixed(1)} L${(cx + Math.cos(a) * r2).toFixed(1)} ${(cy + Math.sin(a) * r2).toFixed(1)} `;
  }
  return `<path d="${d}" stroke="${c.orange}" stroke-width="${w}" stroke-linecap="round"/>`;
}

export const achievements = defineAchievements<LightupParams, LightupState>([
  {
    id: 'no-crosses',
    name: 'Lights Only',
    description: 'Solve a 10×10 Light Up or larger without drawing a single cross.',
    tier: 'silver',
    hue: 'blue',
    art: (c) => {
      const cell = (x: number, y: number, fill: string) =>
        `<rect x="${17 + x * 22}" y="${17 + y * 22}" width="22" height="22" fill="${fill}"/>`;
      // A lamp in the middle of a 3×3 patch: its row and column washed in yellow, black
      // squares in three corners, and in the fourth the cross mark nobody needed.
      return (
        cell(0, 0, c.ink) +
        cell(0, 2, c.ink) +
        cell(2, 2, c.ink) +
        cell(1, 0, c.yellow) +
        cell(0, 1, c.yellow) +
        cell(1, 1, c.yellow) +
        cell(2, 1, c.yellow) +
        cell(1, 2, c.yellow) +
        cell(2, 0, c.paper) +
        `<path d="M39 17 V83 M61 17 V83 M17 39 H83 M17 61 H83" stroke="${c.ink}" stroke-width="2.5"/>` +
        `<rect x="17" y="17" width="66" height="66" fill="none" stroke="${c.ink}" stroke-width="5"/>` +
        bulb(c, 50, 47, 8) +
        `<path d="M66 22 L78 34 M78 22 L66 34" stroke="${c.pencil}" stroke-width="3.5" stroke-linecap="round"/>` +
        `<path d="M64 36 L80 20" stroke="${c.red}" stroke-width="5" stroke-linecap="round"/>`
      );
    },
    test: (ctx) =>
      ctx.params.w >= 10 && ctx.params.h >= 10 && ctx.history.every((s) => !s.imposs.includes(1)),
  },
  {
    id: 'no-takebacks',
    name: 'Bright Idea',
    description: 'Solve a Hard Light Up without ever taking a bulb away.',
    tier: 'gold',
    hue: 'yellow',
    art: (c) => rays(c, 50, 42, 22, 32, 5.5) + bulb(c, 50, 42, 17),
    test: (ctx) => {
      if (ctx.params.difficulty !== DIFF_HARD) return false;
      for (let k = 1; k < ctx.history.length; k++) {
        const a = ctx.history[k - 1].light;
        const b = ctx.history[k].light;
        for (let i = 0; i < a.length; i++) if (a[i] && !b[i]) return false;
      }
      return true;
    },
  },
]);
