import type { Tutorial, TutorialRect } from '../../framework/tutorial';
import { cellCentre, cellRect } from '../../framework/tutorial';
import { border } from './index';
import { vIndex } from './board';
import type { RectState, RectUI } from './index';

/** The 4×4 walkthrough puzzle: a 4 in the top-left corner, a 3 under it and a 9 in the
 *  middle. Its only solution is the top row, the rest of the left column and a 3×3. */
const GAME_ID = '4x4:4c3e9e';

const cell = (x: number, y: number, t: number, cells = 1, rows = 1): TutorialRect =>
  cellRect(x, y, t, border(t), cells, rows);
const centre = (x: number, y: number, t: number) => cellCentre(x, y, t, border(t));

/** Is a closed, correct rectangle of exactly this shape on the board? */
const drawn = (state: RectState, x: number, y: number, w: number, h: number) =>
  state.regions.some((r) => r.valid && r.x === x && r.y === y && r.w === w && r.h === h);

export const tutorial: Tutorial<RectState, RectUI> = {
  steps: [
    {
      gameId: GAME_ID,
      text: 'Cut this grid into rectangles so that every rectangle holds exactly one number, and that number is how many squares the rectangle covers.',
      highlight: ({ state, tileSize }) => cell(0, 0, tileSize, state.w, state.h),
    },
    {
      text: 'A rectangle may hold only one number, and the **3** sits right under the **4** — so the 4 has to take the whole top row. **Drag** from the 4 across to the right-hand end of that row.',
      highlight: ({ state, tileSize }) => cell(0, 0, tileSize, state.w, 1),
      pointer: ({ state, tileSize }) => ({
        ...centre(0, 0, tileSize),
        to: centre(state.w - 1, 0, tileSize),
      }),
      waitFor: ({ state }) => drawn(state, 0, 0, state.w, 1),
    },
    {
      text: 'Clicking a single grid line adds or removes just that one edge. **Click** the line on the right-hand side of the **3**.',
      highlight: ({ tileSize }) => cell(0, 1, tileSize, 2, 1),
      pointer: ({ tileSize }) => {
        const b = border(tileSize);
        return { x: b + tileSize, y: b + 1.5 * tileSize };
      },
      waitFor: ({ state }) => state.vedge[vIndex(state.w, 1, 1)] === 1,
    },
    {
      text: 'A 9 can only be a 3×3 block, and there is one place left for it. **Drag** across the spotlighted block, from its top-left square to the bottom-right corner: that pens the 3 in too.',
      highlight: ({ state, tileSize }) => cell(1, 1, tileSize, state.w - 1, state.h - 1),
      pointer: ({ state, tileSize }) => ({
        ...centre(1, 1, tileSize),
        to: centre(state.w - 1, state.h - 1, tileSize),
      }),
      waitFor: ({ midend }) => midend.status() === 1,
    },
    {
      text: 'Every square is in a rectangle of the right size. A **right-click and drag** rubs out the lines inside an area but leaves its outline, and **Undo** takes back a stroke.',
      target: '[data-cmd="undo"]',
    },
  ],
};
